INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-1', 'en', 'Bài 1: Giáo dục & Trường học (1) - CEFR A2', 'CEFR A2', 'A2 · Giáo dục', '25 từ vựng Tiếng Anh CEFR A2 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2001, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pronounce', 'en-a2-1', 'pronounce', '/prəˈnaʊns/', 'A2', 'phát âm; đọc; tuyên bố; phán quyết', 'v.', 'pronunciation (n.), mispronounce (v.), pronounceable (adj.)', NULL, 'Danh từ là pronunciation, chú ý ở giữa không có chữ cái o.', 'Could you teach me how to pronounce your name?', NULL, 'Bạn có thể dạy tôi cách phát âm tên của bạn không?', '{"wordId":"pronounce","ukIpa":"/prəˈnaʊns/","usIpa":"/prəˈnaʊns/","cefr":"A2","topic":"education","senses":[{"pos":"v.","en":"To make the sounds of a word when speaking.","vi":"phát âm; đọc"},{"pos":"v.","en":"To state an official decision or judgment.","vi":"tuyên bố; phán quyết"}],"examples":[{"en":"Could you teach me how to pronounce your name?","vi":"Bạn có thể dạy tôi cách phát âm tên của bạn không?","audioKind":"ex"},{"en":"Language learners often find unfamiliar sounds easier to pronounce after regular listening practice and feedback.","vi":"Người học ngôn ngữ thường thấy những âm lạ dễ phát âm chuẩn hơn sau khi luyện nghe thường xuyên và nhận phản hồi.","audioKind":"ex2"}],"collocations":[{"en":"pronounce a word","vi":"phát âm một từ"},{"en":"pronounce correctly","vi":"phát âm đúng"},{"en":"pronounce someone innocent","vi":"tuyên bố ai đó vô tội"}],"wordFamily":["pronunciation (n.)","mispronounce (v.)","pronounceable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ là pronunciation, chú ý ở giữa không có chữ cái o.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ability', 'en-a2-1', 'ability', '/əˈbɪləti/', 'A2', 'khả năng; tài năng', 'n.', 'able (adj.), unable (adj.), inability (n.)', 'Đồng nghĩa: capability, capacity · Trái nghĩa: inability', 'Bản chất biểu thị “khả năng làm gì” đi với ability to do.', 'Her ability to fix bicycles impressed all her friends.', NULL, 'Khả năng sửa xe đạp của cô ấy khiến tất cả bạn bè đều ấn tượng.', '{"wordId":"ability","ukIpa":"/əˈbɪləti/","usIpa":"/əˈbɪləti/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"the skill or power needed to do something","vi":"khả năng; tài năng"}],"examples":[{"en":"Her ability to fix bicycles impressed all her friends.","vi":"Khả năng sửa xe đạp của cô ấy khiến tất cả bạn bè đều ấn tượng.","audioKind":"ex"},{"en":"Regular reading can strengthen children''s ability to understand complex ideas and express their own views clearly.","vi":"Việc đọc sách thường xuyên có thể củng cố khả năng hiểu các ý tưởng phức tạp và thể hiện quan điểm của trẻ một cách rõ ràng.","audioKind":"ex2"}],"collocations":[{"en":"the ability to learn","vi":"khả năng học tập"},{"en":"develop an ability","vi":"phát triển năng lực"},{"en":"academic ability","vi":"năng lực học thuật"},{"en":"natural ability","vi":"thiên bẩm"}],"wordFamily":["able (adj.)","unable (adj.)","inability (n.)"],"synonyms":["capability","capacity"],"antonyms":["inability"],"tipVi":"Bản chất biểu thị “khả năng làm gì” đi với ability to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pronunciation', 'en-a2-1', 'pronunciation', '/prəˌnʌnsiˈeɪʃən/', 'A2', 'cách phát âm; ngữ âm', 'n.', 'pronounce (v.), mispronounce (v.), mispronunciation (n.)', NULL, 'Cách viết là pronunciation, lưu ý phần giữa không phải là noun.', 'I practise my pronunciation by recording short voice messages.', NULL, 'Tôi rèn luyện cách phát âm của mình bằng cách ghi âm lại các đoạn tin nhắn thoại ngắn.', '{"wordId":"pronunciation","ukIpa":"/prəˌnʌnsiˈeɪʃən/","usIpa":"/prəˌnʌnsiˈeɪʃən/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"the way a word or language is spoken","vi":"cách phát âm; ngữ âm"}],"examples":[{"en":"I practise my pronunciation by recording short voice messages.","vi":"Tôi rèn luyện cách phát âm của mình bằng cách ghi âm lại các đoạn tin nhắn thoại ngắn.","audioKind":"ex"},{"en":"Clear pronunciation helps language learners communicate effectively, even when their grammar is not always accurate.","vi":"Phát âm rõ ràng giúp người học ngôn ngữ giao tiếp hiệu quả, ngay cả khi ngữ pháp của họ không phải lúc nào cũng chính xác.","audioKind":"ex2"}],"collocations":[{"en":"clear pronunciation","vi":"phát âm rõ ràng"},{"en":"correct pronunciation","vi":"phát âm chuẩn xác"},{"en":"improve your pronunciation","vi":"cải thiện phát âm"},{"en":"pronunciation practice","vi":"luyện phát âm"}],"wordFamily":["pronounce (v.)","mispronounce (v.)","mispronunciation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết là pronunciation, lưu ý phần giữa không phải là noun.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_correctly', 'en-a2-1', 'correctly', '/kəˈrektli/', 'A2', 'đúng đắn; chính xác; theo đúng quy tắc', 'adv.', 'correct (adj.), correct (v.), correction (n.), incorrectly (adv.)', 'Đồng nghĩa: accurately, properly · Trái nghĩa: incorrectly, wrongly', 'Là phó từ bổ nghĩa cho động từ; correct là tính từ hoặc động từ chứ không đóng vai trò phó từ.', 'Check that you have entered your address correctly.', NULL, 'Hãy kiểm tra xem bạn đã nhập đúng địa chỉ của mình chưa.', '{"wordId":"correctly","ukIpa":"/kəˈrektli/","usIpa":"/kəˈrektli/","cefr":"A2","topic":"education","senses":[{"pos":"adv.","en":"in a way that is accurate or follows the rules","vi":"đúng đắn; chính xác; theo đúng quy tắc"}],"examples":[{"en":"Check that you have entered your address correctly.","vi":"Hãy kiểm tra xem bạn đã nhập đúng địa chỉ của mình chưa.","audioKind":"ex"},{"en":"Students need regular feedback to ensure that they apply newly learned scientific concepts correctly in practical situations.","vi":"Học sinh cần nhận phản hồi thường xuyên để đảm bảo các em vận dụng chính xác các khái niệm khoa học mới học vào các tình huống thực tế.","audioKind":"ex2"}],"collocations":[{"en":"answer correctly","vi":"trả lời đúng"},{"en":"correctly identify","vi":"xác định đúng"},{"en":"correctly interpret","vi":"hiểu đúng"},{"en":"if I remember correctly","vi":"nếu tôi nhớ không nhầm"}],"wordFamily":["correct (adj.)","correct (v.)","correction (n.)","incorrectly (adv.)"],"synonyms":["accurately","properly"],"antonyms":["incorrectly","wrongly"],"tipVi":"Là phó từ bổ nghĩa cho động từ; correct là tính từ hoặc động từ chứ không đóng vai trò phó từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discuss', 'en-a2-1', 'discuss', '/dɪˈskʌs/', 'A2', 'thảo luận; bàn luận; bàn bạc; bàn về; luận bàn; thảo luận chi tiết', 'v.', 'discussion (n.), discussant (n.)', 'Đồng nghĩa: talk about, consider', 'Đi trực tiếp với nội dung thảo luận: discuss sth, không thêm giới từ about.', 'Let''s discuss our holiday plans over dinner tonight.', NULL, 'Tối nay chúng ta hãy vừa ăn tối vừa bàn về kế hoạch nghỉ mát nhé.', '{"wordId":"discuss","ukIpa":"/dɪˈskʌs/","usIpa":"/dɪˈskʌs/","cefr":"A2","topic":"education","senses":[{"pos":"v.","en":"to talk about something and exchange ideas","vi":"thảo luận; bàn luận; bàn bạc"},{"pos":"v.","en":"to examine a subject in speech or writing","vi":"bàn về; luận bàn; thảo luận chi tiết"}],"examples":[{"en":"Let''s discuss our holiday plans over dinner tonight.","vi":"Tối nay chúng ta hãy vừa ăn tối vừa bàn về kế hoạch nghỉ mát nhé.","audioKind":"ex"},{"en":"Students should discuss different solutions before deciding how to reduce waste on their campus.","vi":"Học sinh nên thảo luận về các giải pháp khác nhau trước khi quyết định cách giảm rác thải trong khuôn viên trường của họ.","audioKind":"ex2"}],"collocations":[{"en":"discuss a problem","vi":"thảo luận một vấn đề"},{"en":"discuss something with someone","vi":"thảo luận điều gì với ai"},{"en":"discuss in detail","vi":"thảo luận chi tiết"}],"wordFamily":["discussion (n.)","discussant (n.)"],"synonyms":["talk about","consider"],"antonyms":[],"tipVi":"Đi trực tiếp với nội dung thảo luận: discuss sth, không thêm giới từ about.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pupil', 'en-a2-1', 'pupil', '/ˈpjuːpəl/', 'A2', 'học sinh (thường ở bậc tiểu học hoặc trung học); đồng tử (mắt)', 'n.', NULL, NULL, 'Trong tiếng Anh Anh, từ này thường chỉ học sinh phổ thông; sinh viên đại học dùng student.', 'Each pupil brought a leaf to the science lesson.', NULL, 'Mỗi học sinh đều mang một chiếc chiếc lá đến buổi học khoa học.', '{"wordId":"pupil","ukIpa":"/ˈpjuːpəl/","usIpa":"/ˈpjuːpəl/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"A child who attends school.","vi":"học sinh (thường ở bậc tiểu học hoặc trung học)"},{"pos":"n.","en":"The dark opening in the eye that lets light enter.","vi":"đồng tử (mắt)"}],"examples":[{"en":"Each pupil brought a leaf to the science lesson.","vi":"Mỗi học sinh đều mang một chiếc chiếc lá đến buổi học khoa học.","audioKind":"ex"},{"en":"Smaller classes may allow teachers to give each pupil more individual support and useful feedback.","vi":"Lớp học ít học sinh hơn có thể giúp giáo viên dành cho mỗi em sự quan tâm cá nhân nhiều hơn và những phản hồi hữu ích.","audioKind":"ex2"}],"collocations":[{"en":"primary school pupil","vi":"học sinh tiểu học"},{"en":"former pupil","vi":"cựu học sinh"},{"en":"dilated pupils","vi":"đồng tử giãn nở"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh Anh, từ này thường chỉ học sinh phổ thông; sinh viên đại học dùng student.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vocabulary', 'en-a2-1', 'vocabulary', '/voʊˈkæbjəleri/', 'A2', 'vựng từ; vốn từ vựng; thuật ngữ chuyên ngành', 'n.', NULL, 'Đồng nghĩa: lexicon', 'Từ đơn lẻ dùng word; vocabulary thường chỉ tổng lượng từ vựng hoặc tập hợp từ.', 'Reading short stories helps me build my English vocabulary.', NULL, 'Việc đọc truyện ngắn giúp tôi xây dựng vốn từ vựng tiếng Anh của mình.', '{"wordId":"vocabulary","ukIpa":"/vəˈkæbjələri/","usIpa":"/voʊˈkæbjəleri/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"The words someone knows or uses in a language.","vi":"vựng từ; vốn từ vựng"},{"pos":"n.","en":"The words used in a particular subject or activity.","vi":"thuật ngữ chuyên ngành"}],"examples":[{"en":"Reading short stories helps me build my English vocabulary.","vi":"Việc đọc truyện ngắn giúp tôi xây dựng vốn từ vựng tiếng Anh của mình.","audioKind":"ex"},{"en":"Students need a broad academic vocabulary to understand lectures and express complex ideas clearly in essays.","vi":"Học sinh cần một vốn từ vựng học thuật phong phú để hiểu các bài giảng và diễn đạt các ý tưởng phức tạp một cách rõ ràng trong bài luận.","audioKind":"ex2"}],"collocations":[{"en":"expand your vocabulary","vi":"mở rộng vốn từ vựng"},{"en":"a limited vocabulary","vi":"vốn từ vựng hạn chế"},{"en":"academic vocabulary","vi":"từ vựng học thuật"},{"en":"technical vocabulary","vi":"thuật ngữ chuyên ngành"}],"wordFamily":[],"synonyms":["lexicon"],"antonyms":[],"tipVi":"Từ đơn lẻ dùng word; vocabulary thường chỉ tổng lượng từ vựng hoặc tập hợp từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reader', 'en-a2-1', 'reader', '/ˈriːdər/', 'A2', 'người đọc (đặc biệt là sách, báo hoặc tạp chí); thiết bị hiển thị tài liệu văn bản hoặc đọc thông tin đã lưu trữ; sách giáo khoa hoặc sách chuyên khảo được thiết kế để giúp người học phát triển kỹ năng đọc', 'n.', 'read (v.), reading (n.), readable (adj.), readability (n.)', NULL, 'Từ reader vừa có thể chỉ người, vừa có thể chỉ thiết bị hoặc tài liệu học tập.', 'An eager reader, Lina always carries a book.', NULL, 'Là một người rất ham đọc sách, Lina luôn mang theo một cuốn sách bên mình.', '{"wordId":"reader","ukIpa":"/ˈriːdə/","usIpa":"/ˈriːdər/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"A person who reads, especially books, newspapers, or magazines","vi":"người đọc (đặc biệt là sách, báo hoặc tạp chí)"},{"pos":"n.","en":"A device that displays written material or reads stored information","vi":"thiết bị hiển thị tài liệu văn bản hoặc đọc thông tin đã lưu trữ"},{"pos":"n.","en":"A book designed to help learners develop reading skills","vi":"sách giáo khoa hoặc sách chuyên khảo được thiết kế để giúp người học phát triển kỹ năng đọc"}],"examples":[{"en":"An eager reader, Lina always carries a book.","vi":"Là một người rất ham đọc sách, Lina luôn mang theo một cuốn sách bên mình.","audioKind":"ex"},{"en":"Digital libraries allow readers in remote communities to access educational resources without travelling to larger towns.","vi":"Thư viện kỹ thuật số cho phép độc giả ở các cộng đồng vùng sâu vùng xa tiếp cận các nguồn tài nguyên giáo dục mà không cần phải đến các thị trấn lớn.","audioKind":"ex2"}],"collocations":[{"en":"an avid reader","vi":"một người rất ham đọc sách"},{"en":"a card reader","vi":"thiết bị đọc thẻ"},{"en":"a graded reader","vi":"sách đọc phân theo cấp độ"}],"wordFamily":["read (v.)","reading (n.)","readable (adj.)","readability (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ reader vừa có thể chỉ người, vừa có thể chỉ thiết bị hoặc tài liệu học tập.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_education', 'en-a2-1', 'education', '/ˌedʒəˈkeɪʃən/', 'A2', 'giáo dục, quá trình học tập hoặc giảng dạy kiến thức và kỹ năng', 'n.', 'educate (v.), educational (adj.), educator (n.), educated (adj.)', 'Đồng nghĩa: schooling', 'Thông thường là danh từ không đếm được; tuy nhiên có thể dùng a good education để chỉ nền giáo dục tốt.', 'Her grandparents saved money to pay for her education.', NULL, 'Ông bà của cô ấy đã tiết kiệm tiền để trang trải cho việc học hành của cô.', '{"wordId":"education","ukIpa":"/ˌedʒuˈkeɪʃən/","usIpa":"/ˌedʒəˈkeɪʃən/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"The process of learning or teaching knowledge and skills.","vi":"giáo dục, quá trình học tập hoặc giảng dạy kiến thức và kỹ năng"}],"examples":[{"en":"Her grandparents saved money to pay for her education.","vi":"Ông bà của cô ấy đã tiết kiệm tiền để trang trải cho việc học hành của cô.","audioKind":"ex"},{"en":"Access to quality education can improve employment prospects and reduce inequality across different social groups.","vi":"Việc tiếp cận giáo dục chất lượng có thể cải thiện triển vọng việc làm và giảm bớt bất bình đẳng giữa các tầng lớp xã hội khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"higher education","vi":"giáo dục bậc cao, giáo dục đại học"},{"en":"compulsory education","vi":"giáo dục bắt buộc"},{"en":"access to education","vi":"cơ hội tiếp cận giáo dục"},{"en":"education system","vi":"hệ thống giáo dục"}],"wordFamily":["educate (v.)","educational (adj.)","educator (n.)","educated (adj.)"],"synonyms":["schooling"],"antonyms":[],"tipVi":"Thông thường là danh từ không đếm được; tuy nhiên có thể dùng a good education để chỉ nền giáo dục tốt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_meaning', 'en-a2-1', 'meaning', '/ˈmiːnɪŋ/', 'A2', 'nghĩa; ý nghĩa; hàm ý; tính ý nghĩa; giá trị', 'n.', 'mean (v.), meaningful (adj.), meaningless (adj.)', 'Đồng nghĩa: sense, significance', 'Để hỏi về nghĩa của từ, hãy dùng the meaning of; tránh nhầm lẫn với từ opinion.', 'Could you explain the meaning of this unusual word?', NULL, 'Bạn có thể giải thích ý nghĩa của từ bất thường này được không?', '{"wordId":"meaning","ukIpa":"/ˈmiːnɪŋ/","usIpa":"/ˈmiːnɪŋ/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"The idea that a word, action, or message communicates.","vi":"nghĩa; ý nghĩa; hàm ý"},{"pos":"n.","en":"The importance or purpose that makes something worthwhile.","vi":"tính ý nghĩa; giá trị"}],"examples":[{"en":"Could you explain the meaning of this unusual word?","vi":"Bạn có thể giải thích ý nghĩa của từ bất thường này được không?","audioKind":"ex"},{"en":"Volunteering can give people a sense of meaning while strengthening connections within their local communities.","vi":"Hoạt động tình nguyện có thể mang lại cho con người cảm giác có ý nghĩa đồng thời củng cố mối liên kết trong cộng đồng địa phương của họ.","audioKind":"ex2"}],"collocations":[{"en":"the meaning of a word","vi":"nghĩa của một từ"},{"en":"literal meaning","vi":"nghĩa đen"},{"en":"convey meaning","vi":"truyền tải ý nghĩa"},{"en":"give meaning to life","vi":"mang lại ý nghĩa cho cuộc sống"}],"wordFamily":["mean (v.)","meaningful (adj.)","meaningless (adj.)"],"synonyms":["sense","significance"],"antonyms":[],"tipVi":"Để hỏi về nghĩa của từ, hãy dùng the meaning of; tránh nhầm lẫn với từ opinion.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subject', 'en-a2-1', 'subject', '/ˈsʌbdʒɪkt/', 'A2', 'chủ đề; đề tài; môn học; đối tượng; chịu ảnh hưởng; dễ mắc phải; tùy thuộc vào; khiến cho phải chịu đựng; bắt phải trải qua', 'n.', NULL, 'Đồng nghĩa: topic, theme', 'Khi là động từ, trọng âm rơi vào âm tiết thứ hai: /səbˈdʒekt/; cấu trúc phổ biến là subject A to B.', 'Science was my favourite subject when I was younger.', NULL, 'Khoa học là môn học yêu thích của tôi hồi còn nhỏ.', '{"wordId":"subject","ukIpa":"/ˈsʌbdʒɪkt/","usIpa":"/ˈsʌbdʒɪkt/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"Something discussed, studied, or taught.","vi":"chủ đề; đề tài; môn học; đối tượng"},{"pos":"adj.","en":"Affected by something or dependent on a condition.","vi":"chịu ảnh hưởng; dễ mắc phải; tùy thuộc vào"},{"pos":"v.","en":"To make someone experience something, especially something unpleasant.","vi":"khiến cho phải chịu đựng; bắt phải trải qua"}],"examples":[{"en":"Science was my favourite subject when I was younger.","vi":"Khoa học là môn học yêu thích của tôi hồi còn nhỏ.","audioKind":"ex"},{"en":"Schools should give creative subjects sufficient attention because they help students develop imagination and problem-solving skills.","vi":"Nhà trường nên dành sự quan tâm đầy đủ cho các môn nghệ thuật vì chúng giúp học sinh phát triển trí tưởng tượng và kỹ năng giải quyết vấn đề.","audioKind":"ex2"}],"collocations":[{"en":"school subject","vi":"môn học ở trường"},{"en":"change the subject","vi":"đổi chủ đề"},{"en":"subject to approval","vi":"tùy thuộc vào sự phê duyệt"},{"en":"subject someone to stress","vi":"khiến ai đó chịu áp lực"}],"wordFamily":[],"synonyms":["topic","theme"],"antonyms":[],"tipVi":"Khi là động từ, trọng âm rơi vào âm tiết thứ hai: /səbˈdʒekt/; cấu trúc phổ biến là subject A to B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_title', 'en-a2-1', 'title', '/ˈtaɪtəl/', 'A2', 'tựa đề; tên sách; tên tác phẩm; chức danh; chức vụ; danh xưng; danh hiệu vô địch', 'n.', 'title (v.), titled (adj.), untitled (adj.)', 'Đồng nghĩa: heading, name', 'Từ "title" là tên gọi hoặc tựa đề, còn "topic" là chủ đề được thảo luận.', 'I remember the book''s cover but not its title.', NULL, 'Tôi nhớ bìa của cuốn sách nhưng lại quên mất tựa đề của nó.', '{"wordId":"title","ukIpa":"/ˈtaɪtəl/","usIpa":"/ˈtaɪtəl/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"the name given to a book, film, or other work","vi":"tựa đề; tên sách; tên tác phẩm"},{"pos":"n.","en":"a name indicating someone''s rank, position, or professional role","vi":"chức danh; chức vụ; danh xưng"},{"pos":"n.","en":"the position of winner in a sporting competition","vi":"danh hiệu vô địch"}],"examples":[{"en":"I remember the book''s cover but not its title.","vi":"Tôi nhớ bìa của cuốn sách nhưng lại quên mất tựa đề của nó.","audioKind":"ex"},{"en":"An effective essay title should clearly indicate the main issue being discussed without revealing every detail.","vi":"Tiêu đề của một bài luận hiệu quả nên nêu rõ vấn đề chính đang được bàn luận mà không cần tiết lộ mọi chi tiết.","audioKind":"ex2"}],"collocations":[{"en":"book title","vi":"tên sách"},{"en":"job title","vi":"chức danh công việc"},{"en":"win the title","vi":"giành chức vô địch"},{"en":"defend a title","vi":"bảo vệ ngôi vô địch"}],"wordFamily":["title (v.)","titled (adj.)","untitled (adj.)"],"synonyms":["heading","name"],"antonyms":[],"tipVi":"Từ \"title\" là tên gọi hoặc tựa đề, còn \"topic\" là chủ đề được thảo luận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_essay', 'en-a2-1', 'essay', '/ˈeseɪ/', 'A2', 'bài luận; bài văn; bài viết ngắn', 'n.', 'essayist (n.)', NULL, 'Danh từ đếm được; một bài luận về chủ đề nào đó dùng an essay on.', 'I finished my history essay just before dinner.', NULL, 'Tôi vừa viết xong bài luận môn lịch sử ngay trước bữa tối.', '{"wordId":"essay","ukIpa":"/ˈeseɪ/","usIpa":"/ˈeseɪ/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"A short piece of writing exploring a particular subject.","vi":"bài luận; bài văn; bài viết ngắn"}],"examples":[{"en":"I finished my history essay just before dinner.","vi":"Tôi vừa viết xong bài luận môn lịch sử ngay trước bữa tối.","audioKind":"ex"},{"en":"Writing an essay encourages students to organise their ideas and support arguments with relevant evidence.","vi":"Viết một bài luận giúp khuyến khích học sinh sắp xếp ý tưởng và củng cố các luận điểm bằng những bằng chứng liên quan.","audioKind":"ex2"}],"collocations":[{"en":"write an essay","vi":"viết một bài luận"},{"en":"essay question","vi":"câu hỏi tự luận"},{"en":"an essay on","vi":"một bài viết về..."}],"wordFamily":["essayist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đếm được; một bài luận về chủ đề nào đó dùng an essay on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_teaching', 'en-a2-1', 'teaching', '/ˈtiːtʃɪŋ/', 'A2', 'việc dạy học; công tác giảng dạy; nghề dạy học; giáo lý; học thuyết', 'n.', 'teach (v.), teacher (n.)', 'Đồng nghĩa: instruction', 'Khi chỉ hoạt động dạy học thì teaching là danh từ không đếm được; khi chỉ giáo lý hay học thuyết, thường dùng số nhiều teachings.', 'Her love of teaching began at a small village school.', NULL, 'Niềm đam mê dạy học của cô ấy bắt đầu tại một ngôi trường làng nhỏ.', '{"wordId":"teaching","ukIpa":"/ˈtiːtʃɪŋ/","usIpa":"/ˈtiːtʃɪŋ/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"The work of helping people learn knowledge or skills.","vi":"việc dạy học; công tác giảng dạy; nghề dạy học"},{"pos":"n.","en":"Ideas or principles taught by a person or tradition.","vi":"giáo lý; học thuyết"}],"examples":[{"en":"Her love of teaching began at a small village school.","vi":"Niềm đam mê dạy học của cô ấy bắt đầu tại một ngôi trường làng nhỏ.","audioKind":"ex"},{"en":"Effective teaching should combine clear explanations with practical activities that encourage students to apply their knowledge independently.","vi":"Việc giảng dạy hiệu quả nên kết hợp các lời giải thích rõ ràng với các hoạt động thực tế nhằm khuyến khích học sinh tự mình vận dụng kiến thức.","audioKind":"ex2"}],"collocations":[{"en":"teaching methods","vi":"phương pháp giảng dạy"},{"en":"teaching materials","vi":"tài liệu giảng dạy"},{"en":"teaching experience","vi":"kinh nghiệm giảng dạy"},{"en":"a career in teaching","vi":"sự nghiệp giảng dạy"}],"wordFamily":["teach (v.)","teacher (n.)"],"synonyms":["instruction"],"antonyms":[],"tipVi":"Khi chỉ hoạt động dạy học thì teaching là danh từ không đếm được; khi chỉ giáo lý hay học thuyết, thường dùng số nhiều teachings.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_develop', 'en-a2-1', 'develop', '/dɪˈveləp/', 'A2', 'phát triển; lớn lên; làm cho mạnh mẽ, lớn mạnh hoặc tiến bộ hơn; chế tạo; xây dựng (sản phẩm, phương pháp, ý tưởng mới); bắt đầu phát triển; mắc phải (tình trạng, vấn đề, cảm giác)', 'v.', 'development (n.), developer (n.), developing (adj.), developed (adj.)', NULL, 'develop có thể dùng cả ngoại động từ và nội động từ: develop skills (phát triển kỹ năng) hoặc skills develop (kỹ năng phát triển).', 'Children develop confidence when they try new activities.', NULL, 'Trẻ em sẽ phát triển sự tự tin khi các em thử sức với các hoạt động mới.', '{"wordId":"develop","ukIpa":"/dɪˈveləp/","usIpa":"/dɪˈveləp/","cefr":"A2","topic":"education","senses":[{"pos":"v.","en":"to grow or make something stronger, larger, or more advanced","vi":"phát triển; lớn lên; làm cho mạnh mẽ, lớn mạnh hoặc tiến bộ hơn"},{"pos":"v.","en":"to create a new product, method, or idea","vi":"phát triển; chế tạo; xây dựng (sản phẩm, phương pháp, ý tưởng mới)"},{"pos":"v.","en":"to begin to have a condition, problem, or feeling","vi":"bắt đầu phát triển; mắc phải (tình trạng, vấn đề, cảm giác)"}],"examples":[{"en":"Children develop confidence when they try new activities.","vi":"Trẻ em sẽ phát triển sự tự tin khi các em thử sức với các hoạt động mới.","audioKind":"ex"},{"en":"Governments should fund research to develop affordable technologies that address water shortages in rural communities.","vi":"Chính phủ nên tài trợ cho công tác nghiên cứu nhằm phát triển các công nghệ có giá cả phải chăng để giải quyết tình trạng thiếu nước ở các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"develop skills","vi":"phát triển kỹ năng"},{"en":"develop a habit","vi":"hình thành thói quen"},{"en":"develop new technology","vi":"phát triển công nghệ mới"},{"en":"develop symptoms","vi":"phát sinh triệu chứng"}],"wordFamily":["development (n.)","developer (n.)","developing (adj.)","developed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"develop có thể dùng cả ngoại động từ và nội động từ: develop skills (phát triển kỹ năng) hoặc skills develop (kỹ năng phát triển).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_calculator', 'en-a2-1', 'calculator', '/ˈkælkjəleɪtər/', 'A2', 'máy tính (cầm tay hoặc ứng dụng tính toán)', 'n.', 'calculate (v.), calculation (n.), calculable (adj.)', NULL, 'calculator chỉ dụng cụ; calculation chỉ quá trình hoặc kết quả tính toán.', 'I used a calculator to check the shopping total.', NULL, 'Tôi đã dùng máy tính để kiểm tra tổng số tiền mua sắm.', '{"wordId":"calculator","ukIpa":"/ˈkælkjəleɪtə/","usIpa":"/ˈkælkjəleɪtər/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"A device or application used for mathematical calculations","vi":"máy tính (cầm tay hoặc ứng dụng tính toán)"}],"examples":[{"en":"I used a calculator to check the shopping total.","vi":"Tôi đã dùng máy tính để kiểm tra tổng số tiền mua sắm.","audioKind":"ex"},{"en":"Allowing students to use a calculator can help them focus on solving more complex mathematical problems.","vi":"Việc cho phép học sinh sử dụng máy tính có thể giúp các em tập trung giải quyết các bài toán phức tạp hơn.","audioKind":"ex2"}],"collocations":[{"en":"use a calculator","vi":"sử dụng máy tính"},{"en":"scientific calculator","vi":"máy tính khoa học"},{"en":"pocket calculator","vi":"máy tính bỏ túi"}],"wordFamily":["calculate (v.)","calculation (n.)","calculable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"calculator chỉ dụng cụ; calculation chỉ quá trình hoặc kết quả tính toán.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_classmate', 'en-a2-1', 'classmate', '/ˈklæsmeɪt/', 'A2', 'bạn cùng lớp; bạn học', 'n.', 'class (n.), classroom (n.)', NULL, 'classmate chỉ bạn cùng lớp, còn schoolmate chỉ bạn cùng trường.', 'My classmate lent me a pencil before the lesson.', NULL, 'Bạn cùng lớp đã cho tôi mượn một chiếc bút chì trước giờ học.', '{"wordId":"classmate","ukIpa":"/ˈklɑːsmeɪt/","usIpa":"/ˈklæsmeɪt/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"Someone who studies in the same class as you.","vi":"bạn cùng lớp; bạn học"}],"examples":[{"en":"My classmate lent me a pencil before the lesson.","vi":"Bạn cùng lớp đã cho tôi mượn một chiếc bút chì trước giờ học.","audioKind":"ex"},{"en":"Working with classmates on group projects can help students develop communication and problem-solving skills.","vi":"Làm việc cùng các bạn cùng lớp trong các dự án nhóm có thể giúp học sinh phát triển kỹ năng giao tiếp và giải quyết vấn đề.","audioKind":"ex2"}],"collocations":[{"en":"a former classmate","vi":"một người bạn học cũ"},{"en":"help a classmate","vi":"giúp đỡ bạn cùng lớp"},{"en":"a new classmate","vi":"một bạn học mới"}],"wordFamily":["class (n.)","classroom (n.)"],"synonyms":[],"antonyms":[],"tipVi":"classmate chỉ bạn cùng lớp, còn schoolmate chỉ bạn cùng trường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attend', 'en-a2-1', 'attend', '/əˈtend/', 'A2', 'tham dự; có mặt; theo học; giải quyết; chăm sóc', 'v.', 'attendance (n.), attendant (n.)', NULL, 'Tham gia sự kiện thì đi thẳng với tân ngữ; xử lý hoặc chăm sóc thì dùng attend to.', 'My sister attends a dance class every Saturday morning.', NULL, 'Em gái tôi tham gia một lớp học nhảy vào mỗi sáng thứ Bảy.', '{"wordId":"attend","ukIpa":"/əˈtend/","usIpa":"/əˈtend/","cefr":"A2","topic":"education","senses":[{"pos":"v.","en":"to go to an event or regularly visit an institution","vi":"tham dự; có mặt; theo học"},{"pos":"v.","en":"to deal with something or care for someone","vi":"giải quyết; chăm sóc"}],"examples":[{"en":"My sister attends a dance class every Saturday morning.","vi":"Em gái tôi tham gia một lớp học nhảy vào mỗi sáng thứ Bảy.","audioKind":"ex"},{"en":"Students who attend lectures regularly are more likely to understand difficult concepts and complete assignments successfully.","vi":"Những học sinh thường xuyên lên lớp sẽ dễ dàng hiểu được các khái niệm khó và hoàn thành bài tập thành công hơn.","audioKind":"ex2"}],"collocations":[{"en":"attend a meeting","vi":"tham gia cuộc họp"},{"en":"attend school","vi":"đi học"},{"en":"attend to a problem","vi":"giải quyết một vấn đề"}],"wordFamily":["attendance (n.)","attendant (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tham gia sự kiện thì đi thẳng với tân ngữ; xử lý hoặc chăm sóc thì dùng attend to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_basic', 'en-a2-1', 'basic', '/ˈbeɪsɪk/', 'A2', 'cơ bản; nền tảng; đơn giản; tối giản; không có gì phụ trội', 'adj.', 'base (n.), basically (adv.), basics (n.)', 'Đồng nghĩa: fundamental, essential · Trái nghĩa: advanced', 'Danh từ chỉ “kiến thức cơ bản/nền tảng” thường dùng dạng số nhiều the basics.', 'This course teaches basic cooking skills to complete beginners.', NULL, 'Khóa học này dạy các kỹ năng nấu ăn cơ bản cho người mới bắt đầu.', '{"wordId":"basic","ukIpa":"/ˈbeɪsɪk/","usIpa":"/ˈbeɪsɪk/","cefr":"A2","topic":"education","senses":[{"pos":"adj.","en":"Forming the main or most necessary part of something.","vi":"cơ bản; nền tảng"},{"pos":"adj.","en":"Having only necessary features, without anything extra.","vi":"đơn giản; tối giản; không có gì phụ trội"}],"examples":[{"en":"This course teaches basic cooking skills to complete beginners.","vi":"Khóa học này dạy các kỹ năng nấu ăn cơ bản cho người mới bắt đầu.","audioKind":"ex"},{"en":"Governments should ensure that all citizens have access to basic healthcare, regardless of their income.","vi":"Chính phủ nên đảm bảo mọi công dân đều được tiếp cận dịch vụ y tế cơ bản, bất kể thu nhập của họ ra sao.","audioKind":"ex2"}],"collocations":[{"en":"basic skills","vi":"kỹ năng cơ bản"},{"en":"basic needs","vi":"nhu cầu thiết yếu"},{"en":"basic knowledge","vi":"kiến thức nền tảng"},{"en":"basic principles","vi":"nguyên tắc cơ bản"}],"wordFamily":["base (n.)","basically (adv.)","basics (n.)"],"synonyms":["fundamental","essential"],"antonyms":["advanced"],"tipVi":"Danh từ chỉ “kiến thức cơ bản/nền tảng” thường dùng dạng số nhiều the basics.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_comma', 'en-a2-1', 'comma', '/ˈkɑːmə/', 'A2', 'dấu phẩy', 'n.', NULL, NULL, 'comma là dấu phẩy, dấu chấm thường được gọi là full stop (tiếng Anh-Anh) hoặc period (tiếng Anh-Mỹ).', 'I added a comma to make the sentence clearer.', NULL, 'Tôi thêm một dấu phẩy để câu văn rõ nghĩa hơn.', '{"wordId":"comma","ukIpa":"/ˈkɒmə/","usIpa":"/ˈkɑːmə/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"A punctuation mark separating parts of a sentence or list.","vi":"dấu phẩy"}],"examples":[{"en":"I added a comma to make the sentence clearer.","vi":"Tôi thêm một dấu phẩy để câu văn rõ nghĩa hơn.","audioKind":"ex"},{"en":"A misplaced comma can change the meaning of a sentence and confuse readers of academic writing.","vi":"Một dấu phẩy đặt nhầm chỗ có thể làm thay đổi ý nghĩa của cả câu và gây nhầm lẫn cho người đọc các văn bản học thuật.","audioKind":"ex2"}],"collocations":[{"en":"add a comma","vi":"thêm dấu phẩy"},{"en":"a misplaced comma","vi":"dấu phẩy đặt nhầm chỗ"},{"en":"separate items with commas","vi":"phân tách các mục bằng dấu phẩy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"comma là dấu phẩy, dấu chấm thường được gọi là full stop (tiếng Anh-Anh) hoặc period (tiếng Anh-Mỹ).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_professor', 'en-a2-1', 'professor', '/prəˈfesər/', 'A2', 'giáo sư', 'n.', 'professorship (n.), professorial (adj.)', NULL, 'Ở Anh thường chỉ chức danh cao cấp; ở Mỹ cũng dùng chung cho giảng viên đại học.', 'Our professor brought ancient coins to class today.', NULL, 'Giáo sư của chúng tôi đã mang những đồng tiền cổ đến lớp ngày hôm nay.', '{"wordId":"professor","ukIpa":"/prəˈfesə/","usIpa":"/prəˈfesər/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"A university teacher, especially one holding a senior academic position.","vi":"giáo sư"}],"examples":[{"en":"Our professor brought ancient coins to class today.","vi":"Giáo sư của chúng tôi đã mang những đồng tiền cổ đến lớp ngày hôm nay.","audioKind":"ex"},{"en":"The professor encouraged students to evaluate different sources before drawing conclusions about climate policy.","vi":"Vị giáo sư khuyến khích sinh viên đánh giá các nguồn thông tin khác nhau trước khi đưa ra kết luận về chính sách khí hậu.","audioKind":"ex2"}],"collocations":[{"en":"university professor","vi":"giáo sư đại học"},{"en":"professor of economics","vi":"giáo sư kinh tế học"},{"en":"visiting professor","vi":"giáo sư thỉnh giảng"}],"wordFamily":["professorship (n.)","professorial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Ở Anh thường chỉ chức danh cao cấp; ở Mỹ cũng dùng chung cho giảng viên đại học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_improve', 'en-a2-1', 'improve', '/ɪmˈpruːv/', 'A2', 'cải thiện; nâng cao; tiến bộ', 'v.', 'improvement (n.), improved (adj.)', 'Đồng nghĩa: enhance, better · Trái nghĩa: worsen, deteriorate', 'Có thể dùng cả ngoại động từ lẫn nội động từ: improve skills; skills improve.', 'My cooking has improved since I started practising daily.', NULL, 'Khả năng nấu ăn của tôi đã tiến bộ hơn kể từ khi tôi bắt đầu luyện tập hàng ngày.', '{"wordId":"improve","ukIpa":"/ɪmˈpruːv/","usIpa":"/ɪmˈpruːv/","cefr":"A2","topic":"education","senses":[{"pos":"v.","en":"To become better or make something better.","vi":"cải thiện; nâng cao; tiến bộ"}],"examples":[{"en":"My cooking has improved since I started practising daily.","vi":"Khả năng nấu ăn của tôi đã tiến bộ hơn kể từ khi tôi bắt đầu luyện tập hàng ngày.","audioKind":"ex"},{"en":"Investing in teacher training can improve educational outcomes, especially in schools serving disadvantaged communities.","vi":"Đầu tư vào đào tạo giáo viên có thể cải thiện kết quả giáo dục, đặc biệt là ở các trường học phục vụ các cộng đồng còn nhiều thiệt thòi.","audioKind":"ex2"}],"collocations":[{"en":"improve performance","vi":"nâng cao hiệu suất"},{"en":"improve access to","vi":"cải thiện khả năng tiếp cận"},{"en":"improve significantly","vi":"cải thiện đáng kể"},{"en":"improve living standards","vi":"nâng cao mức sống"}],"wordFamily":["improvement (n.)","improved (adj.)"],"synonyms":["enhance","better"],"antonyms":["worsen","deteriorate"],"tipVi":"Có thể dùng cả ngoại động từ lẫn nội động từ: improve skills; skills improve.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_noun', 'en-a2-1', 'noun', '/naʊn/', 'A2', 'danh từ', 'n.', NULL, NULL, 'Danh từ không chỉ chỉ vật thể, mà còn có thể chỉ các khái niệm trừu tượng như advice.', 'Our teacher asked us to circle every noun.', NULL, 'Giáo viên yêu cầu chúng tôi khoanh tròn mọi danh từ.', '{"wordId":"noun","ukIpa":"/naʊn/","usIpa":"/naʊn/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"a word naming a person, place, thing, quality, or idea","vi":"danh từ"}],"examples":[{"en":"Our teacher asked us to circle every noun.","vi":"Giáo viên yêu cầu chúng tôi khoanh tròn mọi danh từ.","audioKind":"ex"},{"en":"Understanding whether a noun is countable helps language learners choose appropriate articles and express quantities accurately in academic writing.","vi":"Việc hiểu rõ một danh từ là đếm được hay không đếm được giúp người học ngôn ngữ chọn mạo từ phù hợp và diễn tả chính xác số lượng trong văn bản học thuật.","audioKind":"ex2"}],"collocations":[{"en":"countable noun","vi":"danh từ đếm được"},{"en":"uncountable noun","vi":"danh từ không đếm được"},{"en":"proper noun","vi":"danh từ riêng"},{"en":"noun phrase","vi":"cụm danh từ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ không chỉ chỉ vật thể, mà còn có thể chỉ các khái niệm trừu tượng như advice.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_portuguese', 'en-a2-1', 'Portuguese', '/ˌpɔːrtʃəˈɡiːz/', 'A2', 'tiếng Bồ Đào Nha; thuộc về Bồ Đào Nha; bằng tiếng Bồ Đào Nha; người Bồ Đào Nha', 'n.', NULL, NULL, 'Viết hoa chữ cái đầu; nói một người Bồ Đào Nha dùng a Portuguese person.', 'My neighbour speaks Portuguese with her family at home.', NULL, 'Hàng xóm của tôi nói tiếng Bồ Đào Nha với gia đình cô ấy ở nhà.', '{"wordId":"portuguese","ukIpa":"/ˌpɔːtʃʊˈɡiːz/","usIpa":"/ˌpɔːrtʃəˈɡiːz/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"The language spoken in Portugal, Brazil, and several other countries","vi":"tiếng Bồ Đào Nha"},{"pos":"adj.","en":"Relating to Portugal, its people, or their language","vi":"thuộc về Bồ Đào Nha; bằng tiếng Bồ Đào Nha"},{"pos":"n.","en":"The people of Portugal, considered as a group","vi":"người Bồ Đào Nha"}],"examples":[{"en":"My neighbour speaks Portuguese with her family at home.","vi":"Hàng xóm của tôi nói tiếng Bồ Đào Nha với gia đình cô ấy ở nhà.","audioKind":"ex"},{"en":"Learning Portuguese can help students access a wider range of literature and international career opportunities.","vi":"Học tiếng Bồ Đào Nha có thể giúp học sinh tiếp cận với nhiều tác phẩm văn học hơn và mở ra các cơ hội nghề nghiệp quốc tế.","audioKind":"ex2"}],"collocations":[{"en":"speak Portuguese","vi":"nói tiếng Bồ Đào Nha"},{"en":"European Portuguese","vi":"tiếng Bồ Đào Nha châu Âu"},{"en":"Portuguese culture","vi":"văn hóa Bồ Đào Nha"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Viết hoa chữ cái đầu; nói một người Bồ Đào Nha dùng a Portuguese person.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_timetable', 'en-a2-1', 'timetable', '/ˈtaɪmteɪbəl/', 'A2', 'thời khóa biểu; lịch trình; bảng giờ tàu chạy; lên lịch trình; sắp xếp thời gian', 'n.', NULL, 'Đồng nghĩa: schedule', 'Tiếng Anh-Anh dùng timetable; tiếng Anh-Mỹ thường dùng schedule.', 'I checked the timetable before leaving for the station.', NULL, 'Tôi đã kiểm tra bảng giờ tàu trước khi ra ga.', '{"wordId":"timetable","ukIpa":"/ˈtaɪmteɪbəl/","usIpa":"/ˈtaɪmteɪbəl/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"A schedule showing when lessons, journeys, or other events happen.","vi":"thời khóa biểu; lịch trình; bảng giờ tàu chạy"},{"pos":"v.","en":"To arrange when an event or activity will happen.","vi":"lên lịch trình; sắp xếp thời gian"}],"examples":[{"en":"I checked the timetable before leaving for the station.","vi":"Tôi đã kiểm tra bảng giờ tàu trước khi ra ga.","audioKind":"ex"},{"en":"A flexible school timetable can help students balance academic subjects with physical activity and creative learning.","vi":"Thời khóa biểu linh hoạt ở trường học có thể giúp học sinh cân bằng giữa các môn học văn hóa, hoạt động thểchất và học tập sáng tạo.","audioKind":"ex2"}],"collocations":[{"en":"train timetable","vi":"lịch tàu chạy"},{"en":"school timetable","vi":"thời khóa biểu của trường"},{"en":"a revised timetable","vi":"lịch trình đã được điều chỉnh"}],"wordFamily":[],"synonyms":["schedule"],"antonyms":[],"tipVi":"Tiếng Anh-Anh dùng timetable; tiếng Anh-Mỹ thường dùng schedule.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_1_1', 'en-a2-1', 'Cách dùng “develop” (v.) — phát triển; lớn lên; làm cho mạnh mẽ, lớn mạnh hoặc tiến bộ hơn', 'develop skills  ·  develop a habit  ·  develop new technology', 'develop có thể dùng cả ngoại động từ và nội động từ: develop skills (phát triển kỹ năng) hoặc skills develop (kỹ năng phát triển).', 'Họ từ (Word Family): development (n.), developer (n.), developing (adj.), developed (adj.)', '[{"hanzi":"Children develop confidence when they try new activities.","pinyin":"","meaning":"Trẻ em sẽ phát triển sự tự tin khi các em thử sức với các hoạt động mới."},{"hanzi":"Governments should fund research to develop affordable technologies that address water shortages in rural communities.","pinyin":"","meaning":"Chính phủ nên tài trợ cho công tác nghiên cứu nhằm phát triển các công nghệ có giá cả phải chăng để giải quyết tình trạng thiếu nước ở các cộng đồng nông thôn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_1_2', 'en-a2-1', 'Cách dùng “teaching” (n.) — việc dạy học; công tác giảng dạy; nghề dạy học', 'teaching methods  ·  teaching materials  ·  teaching experience', 'Khi chỉ hoạt động dạy học thì teaching là danh từ không đếm được; khi chỉ giáo lý hay học thuyết, thường dùng số nhiều teachings.', 'Họ từ (Word Family): teach (v.), teacher (n.) | Đồng nghĩa: instruction', '[{"hanzi":"Her love of teaching began at a small village school.","pinyin":"","meaning":"Niềm đam mê dạy học của cô ấy bắt đầu tại một ngôi trường làng nhỏ."},{"hanzi":"Effective teaching should combine clear explanations with practical activities that encourage students to apply their knowledge independently.","pinyin":"","meaning":"Việc giảng dạy hiệu quả nên kết hợp các lời giải thích rõ ràng với các hoạt động thực tế nhằm khuyến khích học sinh tự mình vận dụng kiến thức."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_1_3', 'en-a2-1', 'Cách dùng “education” (n.) — giáo dục, quá trình học tập hoặc giảng dạy kiến thức và kỹ năng', 'higher education  ·  compulsory education  ·  access to education', 'Thông thường là danh từ không đếm được; tuy nhiên có thể dùng a good education để chỉ nền giáo dục tốt.', 'Họ từ (Word Family): educate (v.), educational (adj.), educator (n.), educated (adj.) | Đồng nghĩa: schooling', '[{"hanzi":"Her grandparents saved money to pay for her education.","pinyin":"","meaning":"Ông bà của cô ấy đã tiết kiệm tiền để trang trải cho việc học hành của cô."},{"hanzi":"Access to quality education can improve employment prospects and reduce inequality across different social groups.","pinyin":"","meaning":"Việc tiếp cận giáo dục chất lượng có thể cải thiện triển vọng việc làm và giảm bớt bất bình đẳng giữa các tầng lớp xã hội khác nhau."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_1_4', 'en-a2-1', 'Cách dùng “comma” (n.) — dấu phẩy', 'add a comma  ·  a misplaced comma  ·  separate items with commas', 'comma là dấu phẩy, dấu chấm thường được gọi là full stop (tiếng Anh-Anh) hoặc period (tiếng Anh-Mỹ).', NULL, '[{"hanzi":"I added a comma to make the sentence clearer.","pinyin":"","meaning":"Tôi thêm một dấu phẩy để câu văn rõ nghĩa hơn."},{"hanzi":"A misplaced comma can change the meaning of a sentence and confuse readers of academic writing.","pinyin":"","meaning":"Một dấu phẩy đặt nhầm chỗ có thể làm thay đổi ý nghĩa của cả câu và gây nhầm lẫn cho người đọc các văn bản học thuật."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_1_1', 'en-a2-1', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_1_1_1', 'ten_a2_1_1', 'pronounce', 'Could you teach me how to pronounce your name?', 'Could you teach me how to pronounce your name?', '/prəˈnaʊns/', 'Bạn có thể dạy tôi cách phát âm tên của bạn không?', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_1_1_2', 'ten_a2_1_1', 'ability', 'Her ability to fix bicycles impressed all her friends.', 'Her ability to fix bicycles impressed all her friends.', '/əˈbɪləti/', 'Khả năng sửa xe đạp của cô ấy khiến tất cả bạn bè đều ấn tượng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_1_1_3', 'ten_a2_1_1', 'pronunciation', 'I practise my pronunciation by recording short voice messages.', 'I practise my pronunciation by recording short voice messages.', '/prəˌnʌnsiˈeɪʃən/', 'Tôi rèn luyện cách phát âm của mình bằng cách ghi âm lại các đoạn tin nhắn thoại ngắn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_1_1_4', 'ten_a2_1_1', 'correctly', 'Check that you have entered your address correctly.', 'Check that you have entered your address correctly.', '/kəˈrektli/', 'Hãy kiểm tra xem bạn đã nhập đúng địa chỉ của mình chưa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
