INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_1_1_8', 'ten_a2_1_1', 'reader', 'An eager reader, Lina always carries a book.', 'An eager reader, Lina always carries a book.', '/ˈriːdər/', 'Là một người rất ham đọc sách, Lina luôn mang theo một cuốn sách bên mình.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_1_1_1', 'en-a2-1', 'ten_a2_1_1', 'listening', 'listening', 'Could you teach me how to pronounce your name?', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bạn có thể dạy tôi cách phát âm tên của bạn không?","Là một người rất ham đọc sách, Lina luôn mang theo một cuốn sách bên mình.","Tôi nhớ bìa của cuốn sách nhưng lại quên mất tựa đề của nó.","Bạn cùng lớp đã cho tôi mượn một chiếc bút chì trước giờ học."]'::jsonb, 0, 'Could you teach me how to pronounce your name? → Bạn có thể dạy tôi cách phát âm tên của bạn không?', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_1_1_2', 'en-a2-1', 'ten_a2_1_1', 'listening', 'listening', 'Her ability to fix bicycles impressed all her friends.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi rèn luyện cách phát âm của mình bằng cách ghi âm lại các đoạn tin nhắn thoại ngắn.","Khả năng sửa xe đạp của cô ấy khiến tất cả bạn bè đều ấn tượng.","Hàng xóm của tôi nói tiếng Bồ Đào Nha với gia đình cô ấy ở nhà.","Bạn cùng lớp đã cho tôi mượn một chiếc bút chì trước giờ học."]'::jsonb, 1, 'Her ability to fix bicycles impressed all her friends. → Khả năng sửa xe đạp của cô ấy khiến tất cả bạn bè đều ấn tượng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_1_1_3', 'en-a2-1', 'ten_a2_1_1', 'listening', 'listening', 'I practise my pronunciation by recording short voice messages.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Khả năng nấu ăn của tôi đã tiến bộ hơn kể từ khi tôi bắt đầu luyện tập hàng ngày.","Tôi rèn luyện cách phát âm của mình bằng cách ghi âm lại các đoạn tin nhắn thoại ngắn.","Niềm đam mê dạy học của cô ấy bắt đầu tại một ngôi trường làng nhỏ.","Hàng xóm của tôi nói tiếng Bồ Đào Nha với gia đình cô ấy ở nhà."]'::jsonb, 1, 'I practise my pronunciation by recording short voice messages. → Tôi rèn luyện cách phát âm của mình bằng cách ghi âm lại các đoạn tin nhắn thoại ngắn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_1_2', 'en-a2-1', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_1_2_1', 'ten_a2_1_2', 'pronounce', 'Language learners often find unfamiliar sounds easier to pronounce after regular listening practice and feedback.', 'Language learners often find unfamiliar sounds easier to pronounce after regular listening practice and feedback.', '/prəˈnaʊns/', 'Người học ngôn ngữ thường thấy những âm lạ dễ phát âm chuẩn hơn sau khi luyện nghe thường xuyên và nhận phản hồi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_1_2_2', 'ten_a2_1_2', 'ability', 'Regular reading can strengthen children''s ability to understand complex ideas and express their own views clearly.', 'Regular reading can strengthen children''s ability to understand complex ideas and express their own views clearly.', '/əˈbɪləti/', 'Việc đọc sách thường xuyên có thể củng cố khả năng hiểu các ý tưởng phức tạp và thể hiện quan điểm của trẻ một cách rõ ràng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_1_2_3', 'ten_a2_1_2', 'pronunciation', 'Clear pronunciation helps language learners communicate effectively, even when their grammar is not always accurate.', 'Clear pronunciation helps language learners communicate effectively, even when their grammar is not always accurate.', '/prəˌnʌnsiˈeɪʃən/', 'Phát âm rõ ràng giúp người học ngôn ngữ giao tiếp hiệu quả, ngay cả khi ngữ pháp của họ không phải lúc nào cũng chính xác.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_1_2_4', 'ten_a2_1_2', 'correctly', 'Students need regular feedback to ensure that they apply newly learned scientific concepts correctly in practical situations.', 'Students need regular feedback to ensure that they apply newly learned scientific concepts correctly in practical situations.', '/kəˈrektli/', 'Học sinh cần nhận phản hồi thường xuyên để đảm bảo các em vận dụng chính xác các khái niệm khoa học mới học vào các tình huống thực tế.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_1_2_5', 'ten_a2_1_2', 'discuss', 'Students should discuss different solutions before deciding how to reduce waste on their campus.', 'Students should discuss different solutions before deciding how to reduce waste on their campus.', '/dɪˈskʌs/', 'Học sinh nên thảo luận về các giải pháp khác nhau trước khi quyết định cách giảm rác thải trong khuôn viên trường của họ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_1_2_6', 'ten_a2_1_2', 'pupil', 'Smaller classes may allow teachers to give each pupil more individual support and useful feedback.', 'Smaller classes may allow teachers to give each pupil more individual support and useful feedback.', '/ˈpjuːpəl/', 'Lớp học ít học sinh hơn có thể giúp giáo viên dành cho mỗi em sự quan tâm cá nhân nhiều hơn và những phản hồi hữu ích.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
