INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_1_2', 'en-a2-1', NULL, 'comprehensive_test', 'listening', 'Her ability to fix bicycles impressed all her friends.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Khả năng nấu ăn của tôi đã tiến bộ hơn kể từ khi tôi bắt đầu luyện tập hàng ngày.","Bạn có thể giải thích ý nghĩa của từ bất thường này được không?","Khả năng sửa xe đạp của cô ấy khiến tất cả bạn bè đều ấn tượng.","Tôi đã kiểm tra bảng giờ tàu trước khi ra ga."]'::jsonb, 2, 'Her ability to fix bicycles impressed all her friends. → Khả năng sửa xe đạp của cô ấy khiến tất cả bạn bè đều ấn tượng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
