INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_1_4', 'en-a2-1', NULL, 'comprehensive_test', 'listening', 'Check that you have entered your address correctly.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy kiểm tra xem bạn đã nhập đúng địa chỉ của mình chưa.","Mỗi học sinh đều mang một chiếc chiếc lá đến buổi học khoa học.","Ông bà của cô ấy đã tiết kiệm tiền để trang trải cho việc học hành của cô.","Tôi vừa viết xong bài luận môn lịch sử ngay trước bữa tối."]'::jsonb, 0, 'Check that you have entered your address correctly. → Hãy kiểm tra xem bạn đã nhập đúng địa chỉ của mình chưa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
