INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_1_18', 'en-a2-1', NULL, 'comprehensive_test', 'reading', NULL, 'Language learners often find unfamiliar sounds easier to pronounce after regular listening practice and feedback.', 'Dựa vào câu trên, từ “pronounce” có nghĩa phù hợp nhất là gì?', '["phát âm; đọc","cờ vua; môn cờ vua","cái lỗ; hố; kẽ hở","quyết định; lựa chọn"]'::jsonb, 0, 'pronounce: phát âm; đọc; tuyên bố; phán quyết. Dịch cả câu: Người học ngôn ngữ thường thấy những âm lạ dễ phát âm chuẩn hơn sau khi luyện nghe thường xuyên và nhận phản hồi.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_1_19', 'en-a2-1', NULL, 'comprehensive_test', 'reading', NULL, 'Regular reading can strengthen children''s ability to understand complex ideas and express their own views clearly.', 'Dựa vào câu trên, từ “ability” có nghĩa phù hợp nhất là gì?', '["bị vỡ; bị gãy","vựng từ; vốn từ vựng","thẳng; không cong","khả năng; tài năng"]'::jsonb, 3, 'ability: khả năng; tài năng. Dịch cả câu: Việc đọc sách thường xuyên có thể củng cố khả năng hiểu các ý tưởng phức tạp và thể hiện quan điểm của trẻ một cách rõ ràng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_1_20', 'en-a2-1', NULL, 'comprehensive_test', 'reading', NULL, 'Clear pronunciation helps language learners communicate effectively, even when their grammar is not always accurate.', 'Dựa vào câu trên, từ “pronunciation” có nghĩa phù hợp nhất là gì?', '["cách phát âm; ngữ âm","điểm số; kết quả","từ (một thời điểm trong quá khứ) cho đến nay","khách du lịch; người tham quan"]'::jsonb, 0, 'pronunciation: cách phát âm; ngữ âm. Dịch cả câu: Phát âm rõ ràng giúp người học ngôn ngữ giao tiếp hiệu quả, ngay cả khi ngữ pháp của họ không phải lúc nào cũng chính xác.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_1_21', 'en-a2-1', NULL, 'comprehensive_test', 'reading', NULL, 'Students need regular feedback to ensure that they apply newly learned scientific concepts correctly in practical situations.', 'Dựa vào câu trên, từ “correctly” có nghĩa phù hợp nhất là gì?', '["đúng đắn; chính xác; theo đúng quy tắc","chất dẻo; nhựa","chính xác; hoàn toàn","đáng sợ; làm hoảng sợ"]'::jsonb, 0, 'correctly: đúng đắn; chính xác; theo đúng quy tắc. Dịch cả câu: Học sinh cần nhận phản hồi thường xuyên để đảm bảo các em vận dụng chính xác các khái niệm khoa học mới học vào các tình huống thực tế.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_1_22', 'en-a2-1', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “danh từ”', '["should","noun","imagine","stupid"]'::jsonb, 1, 'danh từ → noun (/naʊn/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_1_23', 'en-a2-1', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tiếng Bồ Đào Nha”', '["restroom","Portuguese","timetable","anyway"]'::jsonb, 1, 'tiếng Bồ Đào Nha → Portuguese (/ˌpɔːrtʃəˈɡiːz/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_1_24', 'en-a2-1', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thời khóa biểu; lịch trình; bảng giờ tàu chạy”', '["wooden","timetable","coach","almost"]'::jsonb, 1, 'thời khóa biểu; lịch trình; bảng giờ tàu chạy → timetable (/ˈtaɪmteɪbəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-2', 'en', 'Bài 2: Giáo dục & Trường học (2) - CEFR A2', 'CEFR A2', 'A2 · Giáo dục', '25 từ vựng Tiếng Anh CEFR A2 chủ đề giáo dục & trường học kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2002, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_degree', 'en-a2-2', 'degree', '/dɪˈɡriː/', 'A2', 'bằng cấp; văn bằng; mức độ; chừng mực; độ (đơn vị đo nhiệt độ hoặc góc)', 'n.', NULL, NULL, 'Cụm chỉ chuyên ngành dùng a degree in; nghĩa chỉ mức độ thường gặp trong to some degree.', 'My cousin earned a degree in engineering last summer.', NULL, 'Anh họ tôi đã lấy bằng kỹ sư vào mùa hè năm ngoái.', '{"wordId":"degree","ukIpa":"/dɪˈɡriː/","usIpa":"/dɪˈɡriː/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"a qualification awarded after completing a university course","vi":"bằng cấp; văn bằng"},{"pos":"n.","en":"the amount or level of something","vi":"mức độ; chừng mực"},{"pos":"n.","en":"a unit used to measure temperature or angles","vi":"độ (đơn vị đo nhiệt độ hoặc góc)"}],"examples":[{"en":"My cousin earned a degree in engineering last summer.","vi":"Anh họ tôi đã lấy bằng kỹ sư vào mùa hè năm ngoái.","audioKind":"ex"},{"en":"Although a university degree can improve employment prospects, practical experience remains highly valuable in many industries.","vi":"Mặc dù bằng đại học có thể cải thiện cơ hội việc làm, kinh nghiệm thực tế vẫn vô cùng giá trị trong nhiều ngành nghề.","audioKind":"ex2"}],"collocations":[{"en":"a degree in economics","vi":"bằng kinh tế học"},{"en":"a bachelor''s degree","vi":"bằng cử nhân"},{"en":"to some degree","vi":"ở một mức độ nào đó"},{"en":"degrees Celsius","vi":"độ C"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm chỉ chuyên ngành dùng a degree in; nghĩa chỉ mức độ thường gặp trong to some degree.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_textbook', 'en-a2-2', 'textbook', '/ˈtekstbʊk/', 'A2', 'sách giáo khoa; giáo trình; điển hình; chuẩn mực', 'n.', NULL, NULL, 'Khi dùng làm tính từ, từ này chỉ tính điển hình hoặc chuẩn mực, như trong textbook example.', 'I left my science textbook on the kitchen table.', NULL, 'Tôi để quên sách khoa học trên bàn bếp.', '{"wordId":"textbook","ukIpa":"/ˈtekstbʊk/","usIpa":"/ˈtekstbʊk/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"A book used to study a particular subject.","vi":"sách giáo khoa; giáo trình"},{"pos":"adj.","en":"Showing exactly how something usually happens or should be done.","vi":"điển hình; chuẩn mực"}],"examples":[{"en":"I left my science textbook on the kitchen table.","vi":"Tôi để quên sách khoa học trên bàn bếp.","audioKind":"ex"},{"en":"Digital textbooks can reduce school expenses, although some students find printed materials easier to study.","vi":"Sách giáo khoa kỹgital có thể giảm chi phí trường học, mặc dù một số học sinh thấy tài liệu in dễ học hơn.","audioKind":"ex2"}],"collocations":[{"en":"school textbook","vi":"sách giáo khoa trường học"},{"en":"textbook example","vi":"ví dụ điển hình"},{"en":"textbook publisher","vi":"nhà xuất bản sách giáo khoa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng làm tính từ, từ này chỉ tính điển hình hoặc chuẩn mực, như trong textbook example.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_instruction', 'en-a2-2', 'instruction', '/ɪnˈstrʌkʃən/', 'A2', 'hướng dẫn; chỉ dẫn; lệnh; chỉ thị; sự giảng dạy; sự hướng dẫn', 'n.', 'instruct (v.), instructor (n.), instructive (adj.), instructional (adj.)', NULL, 'Chỉ dẫn thao tác thường dùng ở dạng số nhiều ''instructions''; khi chỉ việc dạy học thì không đếm được.', 'The instructor gave one clear instruction: hold the rope tightly.', NULL, 'Người hướng dẫn đưa ra một chỉ dẫn rõ ràng: giữ chặt sợi dây.', '{"wordId":"instruction","ukIpa":"/ɪnˈstrʌkʃən/","usIpa":"/ɪnˈstrʌkʃən/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"Information explaining what to do or how to do something","vi":"hướng dẫn; chỉ dẫn"},{"pos":"n.","en":"An order telling someone what they must do","vi":"lệnh; chỉ thị"},{"pos":"n.","en":"The activity of teaching someone a skill or subject","vi":"sự giảng dạy; sự hướng dẫn"}],"examples":[{"en":"The instructor gave one clear instruction: hold the rope tightly.","vi":"Người hướng dẫn đưa ra một chỉ dẫn rõ ràng: giữ chặt sợi dây.","audioKind":"ex"},{"en":"Students often benefit from practical instruction that connects classroom theory with everyday problems.","vi":"Học sinh thường hưởng lợi từ việc học thực hành kết hợp lý thuyết lớp học với các vấn đề thường ngày.","audioKind":"ex2"}],"collocations":[{"en":"follow instructions","vi":"làm theo hướng dẫn"},{"en":"step-by-step instructions","vi":"hướng dẫn từng bước"},{"en":"give instructions","vi":"đưa ra chỉ dẫn"},{"en":"practical instruction","vi":"hướng dẫn thực tế"}],"wordFamily":["instruct (v.)","instructor (n.)","instructive (adj.)","instructional (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ dẫn thao tác thường dùng ở dạng số nhiều ''instructions''; khi chỉ việc dạy học thì không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mathematics', 'en-a2-2', 'mathematics', '/ˌmæθəˈmætɪks/', 'A2', 'môn toán; toán học', 'n.', 'mathematical (adj.), mathematically (adv.), mathematician (n.)', 'Đồng nghĩa: maths, math', 'Mặc dù tận cùng bằng s, tên môn học này đi với động từ số ít; tiếng Anh-Anh thường viết tắt là maths.', 'She enjoys mathematics, especially solving puzzles about shapes.', NULL, 'Cô ấy thích toán học, đặc biệt là việc giải các câu đố về hình học.', '{"wordId":"mathematics","ukIpa":"/ˌmæθəˈmætɪks/","usIpa":"/ˌmæθəˈmætɪks/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"The study of quantities, shapes, patterns, and their relationships.","vi":"môn toán; toán học"}],"examples":[{"en":"She enjoys mathematics, especially solving puzzles about shapes.","vi":"Cô ấy thích toán học, đặc biệt là việc giải các câu đố về hình học.","audioKind":"ex"},{"en":"A strong foundation in mathematics enables students to interpret data and evaluate claims in everyday life.","vi":"Nền tảng toán học vững chắc giúp học sinh diễn giải dữ liệu và đánh giá các nhận định trong đời sống hằng ngày.","audioKind":"ex2"}],"collocations":[{"en":"applied mathematics","vi":"toán học ứng dụng"},{"en":"pure mathematics","vi":"toán học thuần túy"},{"en":"mathematics teacher","vi":"giáo viên toán"}],"wordFamily":["mathematical (adj.)","mathematically (adv.)","mathematician (n.)"],"synonyms":["maths","math"],"antonyms":[],"tipVi":"Mặc dù tận cùng bằng s, tên môn học này đi với động từ số ít; tiếng Anh-Anh thường viết tắt là maths.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prize', 'en-a2-2', 'prize', '/praɪz/', 'A2', 'giải thưởng; phần thưởng; trân trọng; đánh giá cao', 'n.', 'prized (adj.)', 'Đồng nghĩa: award, reward', 'prize có thể làm động từ chỉ sự trân trọng, thường gặp trong cấu trúc be highly prized.', 'Lina won a prize for her colourful garden.', NULL, 'Lina đã giành được giải thưởng nhờ khu vườn rực rỡ sắc màu của mình.', '{"wordId":"prize","ukIpa":"/praɪz/","usIpa":"/praɪz/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"something given for winning a competition or achieving something","vi":"giải thưởng; phần thưởng"},{"pos":"v.","en":"to value something very highly","vi":"trân trọng; đánh giá cao"}],"examples":[{"en":"Lina won a prize for her colourful garden.","vi":"Lina đã giành được giải thưởng nhờ khu vườn rực rỡ sắc màu của mình.","audioKind":"ex"},{"en":"Offering a prize for innovative designs can encourage students to develop practical solutions to environmental problems.","vi":"Việc trao giải thưởng cho các thiết kế đổi mới có thể khuyến khích học sinh tìm ra các giải pháp thiết thực cho các vấn đề môi trường.","audioKind":"ex2"}],"collocations":[{"en":"win a prize","vi":"giành giải thưởng"},{"en":"first prize","vi":"giải nhất"},{"en":"prize money","vi":"tiền thưởng"},{"en":"highly prized","vi":"được đánh giá rất cao"}],"wordFamily":["prized (adj.)"],"synonyms":["award","reward"],"antonyms":[],"tipVi":"prize có thể làm động từ chỉ sự trân trọng, thường gặp trong cấu trúc be highly prized.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_programme', 'en-a2-2', 'programme', '/ˈproʊɡræm/', 'A2', 'chương trình; kế hoạch; đề án; chương trình phát sóng (trên TV hoặc radio); lập chương trình; lên lịch trình; cài đặt vận hành', 'n.', 'programming (n.), programmer (n.)', NULL, 'Tiếng Anh-Anh thường dùng programme, chương trình máy tính dùng program; tiếng Anh-Mỹ đều dùng program.', 'I joined a fitness programme at the local gym.', NULL, 'Tôi đã tham gia một chương trình thể dục tại phòng gym địa phương.', '{"wordId":"programme","ukIpa":"/ˈprəʊɡræm/","usIpa":"/ˈproʊɡræm/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"an organised set of activities with a particular purpose","vi":"chương trình; kế hoạch; đề án"},{"pos":"n.","en":"a show broadcast on television or radio","vi":"chương trình phát sóng (trên TV hoặc radio)"},{"pos":"v.","en":"to arrange activities or set a machine to operate automatically","vi":"lập chương trình; lên lịch trình; cài đặt vận hành"}],"examples":[{"en":"I joined a fitness programme at the local gym.","vi":"Tôi đã tham gia một chương trình thể dục tại phòng gym địa phương.","audioKind":"ex"},{"en":"A well-designed training programme can help unemployed adults gain the skills needed for new careers.","vi":"Một chương trình đào tạo được thiết kế kỹ lưỡng có thể giúp người lớn thất nghiệp có được các kỹ năng cần thiết cho nghề nghiệp mới.","audioKind":"ex2"}],"collocations":[{"en":"training programme","vi":"chương trình đào tạo"},{"en":"television programme","vi":"chương trình truyền hình"},{"en":"degree programme","vi":"chương trình đào tạo cấp bằng"},{"en":"launch a programme","vi":"khởi động một chương trình"}],"wordFamily":["programming (n.)","programmer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Anh thường dùng programme, chương trình máy tính dùng program; tiếng Anh-Mỹ đều dùng program.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_speaker', 'en-a2-2', 'speaker', '/ˈspiːkər/', 'A2', 'diễn giả; người phát biểu; người nói (một ngôn ngữ nào đó); loa; thiết bị phát âm thanh', 'n.', 'speak (v.), speech (n.), spoken (adj.)', NULL, 'a native speaker of English chỉ người có tiếng Anh là tiếng mẹ đẻ.', 'The speaker made everyone laugh with her opening story.', NULL, 'Diễn giả đã làm tất cả mọi người bật cười với câu chuyện mở đầu của cô ấy.', '{"wordId":"speaker","ukIpa":"/ˈspiːkə/","usIpa":"/ˈspiːkər/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"a person who gives a talk or addresses others","vi":"diễn giả; người phát biểu"},{"pos":"n.","en":"a person who speaks a particular language","vi":"người nói (một ngôn ngữ nào đó)"},{"pos":"n.","en":"a device that produces sound from electrical signals","vi":"loa; thiết bị phát âm thanh"}],"examples":[{"en":"The speaker made everyone laugh with her opening story.","vi":"Diễn giả đã làm tất cả mọi người bật cười với câu chuyện mở đầu của cô ấy.","audioKind":"ex"},{"en":"Inviting a guest speaker from the scientific community can help students understand how classroom knowledge applies to real problems.","vi":"Việc mời một diễn giả khách mời từ cộng đồng khoa học có thể giúp học sinh hiểu cách áp dụng kiến thức trên lớp vào các vấn đề thực tế.","audioKind":"ex2"}],"collocations":[{"en":"guest speaker","vi":"diễn giả khách mời"},{"en":"native speaker","vi":"người bản xứ"},{"en":"fluent speaker","vi":"người nói lưu loát"},{"en":"wireless speaker","vi":"loa không dây"}],"wordFamily":["speak (v.)","speech (n.)","spoken (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"a native speaker of English chỉ người có tiếng Anh là tiếng mẹ đẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_topic', 'en-a2-2', 'topic', '/ˈtɑːpɪk/', 'A2', 'chủ đề; đề tài', 'n.', 'topical (adj.)', 'Đồng nghĩa: subject, theme', 'topic chỉ chủ đề để thảo luận hoặc viết lách; title chỉ tiêu đề của bài viết, v.v.', 'Food is always a popular topic in our house.', NULL, 'Đồ ăn luôn là một chủ đề phổ biến trong gia đình chúng tôi.', '{"wordId":"topic","ukIpa":"/ˈtɒpɪk/","usIpa":"/ˈtɑːpɪk/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"a subject that people discuss, write about, or study","vi":"chủ đề; đề tài"}],"examples":[{"en":"Food is always a popular topic in our house.","vi":"Đồ ăn luôn là một chủ đề phổ biến trong gia đình chúng tôi.","audioKind":"ex"},{"en":"Climate change has become a central topic in school discussions about the future of our planet.","vi":"Biến đổi khí hậu đã trở thành một chủ đề trung tâm trong các cuộc thảo luận ở trường học về tương lai của hành tinh chúng ta.","audioKind":"ex2"}],"collocations":[{"en":"a topic of discussion","vi":"chủ đề thảo luận"},{"en":"a controversial topic","vi":"chủ đề gây tranh cãi"},{"en":"change the topic","vi":"chuyển chủ đề"},{"en":"research topic","vi":"chủ đề nghiên cứu"}],"wordFamily":["topical (adj.)"],"synonyms":["subject","theme"],"antonyms":[],"tipVi":"topic chỉ chủ đề để thảo luận hoặc viết lách; title chỉ tiêu đề của bài viết, v.v.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discussion', 'en-a2-2', 'discussion', '/dɪˈskʌʃən/', 'A2', 'cuộc thảo luận; sự bàn bạc; sự luận bàn; bài khảo sát chi tiết', 'n.', 'discuss (v.), discussant (n.)', 'Đồng nghĩa: conversation, deliberation', 'Danh từ có thể đi với about hoặcof; động từ discuss đi trực tiếp với chủ đề.', 'We had a lively discussion about our holiday plans.', NULL, 'Chúng tôi đã có một cuộc thảo luận sôi nổi về kế hoạch kỳ nghỉ của mình.', '{"wordId":"discussion","ukIpa":"/dɪˈskʌʃən/","usIpa":"/dɪˈskʌʃən/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"An exchange of ideas or opinions about a subject.","vi":"cuộc thảo luận; sự bàn bạc"},{"pos":"n.","en":"A detailed examination of a subject in speech or writing.","vi":"sự luận bàn; bài khảo sát chi tiết"}],"examples":[{"en":"We had a lively discussion about our holiday plans.","vi":"Chúng tôi đã có một cuộc thảo luận sôi nổi về kế hoạch kỳ nghỉ của mình.","audioKind":"ex"},{"en":"Public discussion of transport policy can help governments design services that better meet residents'' needs.","vi":"Cuộc thảo luận công khai về chính sách giao thông có thể giúp chính phủ thiết kế các dịch vụ đáp ứng tốt hơn nhu cầu của người dân.","audioKind":"ex2"}],"collocations":[{"en":"have a discussion","vi":"có một cuộc thảo luận"},{"en":"group discussion","vi":"thảo luận nhóm"},{"en":"under discussion","vi":"đang được thảo luận"},{"en":"in-depth discussion","vi":"thảo luận sâu"}],"wordFamily":["discuss (v.)","discussant (n.)"],"synonyms":["conversation","deliberation"],"antonyms":[],"tipVi":"Danh từ có thể đi với about hoặcof; động từ discuss đi trực tiếp với chủ đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_description', 'en-a2-2', 'description', '/dɪˈskrɪpʃən/', 'A2', 'sự miêu tả; sự mô tả', 'n.', 'describe (v.), descriptive (adj.)', 'Đồng nghĩa: account, portrayal', 'Diễn tả sự miêu tả về cái gì, dùng a description of, không dùng about.', 'Your description helped me find the little bakery.', NULL, 'Lời miêu tả của bạn đã giúp tôi tìm thấy tiệm bánh nhỏ đó.', '{"wordId":"description","ukIpa":"/dɪˈskrɪpʃən/","usIpa":"/dɪˈskrɪpʃən/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"an account explaining what someone or something is like","vi":"sự miêu tả; sự mô tả"}],"examples":[{"en":"Your description helped me find the little bakery.","vi":"Lời miêu tả của bạn đã giúp tôi tìm thấy tiệm bánh nhỏ đó.","audioKind":"ex"},{"en":"A clear description of research methods allows other scientists to evaluate the reliability of a study.","vi":"Mô tả rõ ràng về các phương pháp nghiên cứu cho phép các nhà khoa học khác đánh giá độ tin cậy của một nghiên cứu.","audioKind":"ex2"}],"collocations":[{"en":"a detailed description","vi":"mô tả chi tiết"},{"en":"give a description of","vi":"đưa ra mô tả về"},{"en":"a job description","vi":"bản mô tả công việc"},{"en":"an accurate description","vi":"mô tả chính xác"}],"wordFamily":["describe (v.)","descriptive (adj.)"],"synonyms":["account","portrayal"],"antonyms":[],"tipVi":"Diễn tả sự miêu tả về cái gì, dùng a description of, không dùng about.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_knowledge', 'en-a2-2', 'knowledge', '/ˈnɑːlɪdʒ/', 'A2', 'kiến thức, sự hiểu biết; sự hay biết, sự nhận thức', 'n.', 'know (v.), knowledgeable (adj.), known (adj.)', 'Trái nghĩa: ignorance', 'Thông thường là danh từ không đếm được; có thể dùng "a good knowledge of" cho một lĩnh vực nào đó.', 'My grandfather shared his knowledge of birds with me.', NULL, 'Ông tôi đã chia sẻ sự hiểu biết của ông về các loài chim với tôi.', '{"wordId":"knowledge","ukIpa":"/ˈnɒlɪdʒ/","usIpa":"/ˈnɑːlɪdʒ/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"information and understanding gained through learning or experience","vi":"kiến thức, sự hiểu biết"},{"pos":"n.","en":"awareness of a particular fact or situation","vi":"sự hay biết, sự nhận thức"}],"examples":[{"en":"My grandfather shared his knowledge of birds with me.","vi":"Ông tôi đã chia sẻ sự hiểu biết của ông về các loài chim với tôi.","audioKind":"ex"},{"en":"Schools should help students apply their knowledge to practical problems rather than simply memorise facts.","vi":"Nhà trường nên giúp học sinh vận dụng kiến thức vào các vấn đề thực tiễn thay vì chỉ học thuộc lòng các sự kiện.","audioKind":"ex2"}],"collocations":[{"en":"gain knowledge","vi":"thu thập kiến thức"},{"en":"practical knowledge","vi":"kiến thức thực tế"},{"en":"knowledge of","vi":"sự hiểu biết về"},{"en":"without someone''s knowledge","vi":"mà không sự hay biết của ai đó"}],"wordFamily":["know (v.)","knowledgeable (adj.)","known (adj.)"],"synonyms":[],"antonyms":["ignorance"],"tipVi":"Thông thường là danh từ không đếm được; có thể dùng \"a good knowledge of\" cho một lĩnh vực nào đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_workbook', 'en-a2-2', 'workbook', '/ˈwɝːkbʊk/', 'A2', 'sách bài tập; tập tin bảng tính (máy tính)', 'n.', NULL, NULL, 'workbook tập trung vào việc làm bài tập thực hành; textbook tập trung vào việc giải thích kiến thức lý thuyết.', 'I left my workbook in my school bag.', NULL, 'Tôi để quên sách bài tập trong cặp sách rồi.', '{"wordId":"workbook","ukIpa":"/ˈwɜːkbʊk/","usIpa":"/ˈwɝːkbʊk/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"A book containing exercises for learners to complete","vi":"sách bài tập"},{"pos":"n.","en":"A computer file containing one or more spreadsheets","vi":"tập tin bảng tính (máy tính)"}],"examples":[{"en":"I left my workbook in my school bag.","vi":"Tôi để quên sách bài tập trong cặp sách rồi.","audioKind":"ex"},{"en":"A well-designed workbook allows students to practise new skills independently and monitor their progress.","vi":"Một cuốn sách bài tập được thiết kế tốt cho phép học sinh tự luyện tập các kỹ năng mới và theo dõi sự tiến bộ của bản thân.","audioKind":"ex2"}],"collocations":[{"en":"complete a workbook","vi":"làm xong sách bài tập"},{"en":"workbook exercises","vi":"bài tập trong sách bài tập"},{"en":"a grammar workbook","vi":"sách bài tập ngữ pháp"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"workbook tập trung vào việc làm bài tập thực hành; textbook tập trung vào việc giải thích kiến thức lý thuyết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adjective', 'en-a2-2', 'adjective', '/ˈædʒɪktɪv/', 'A2', 'tính từ', 'n.', 'adjectival (adj.), adjectivally (adv.)', NULL, 'Tính từ thường đứng trước danh từ hoặc sau động từ liên kết, ví dụ như a cold day.', 'Our teacher asked us to find adjectives describing weather.', NULL, 'Giáo viên yêu cầu chúng tôi tìm các tính từ miêu tả thời tiết.', '{"wordId":"adjective","ukIpa":"/ˈædʒɪktɪv/","usIpa":"/ˈædʒɪktɪv/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"a word that describes a person, thing, or state","vi":"tính từ"}],"examples":[{"en":"Our teacher asked us to find adjectives describing weather.","vi":"Giáo viên yêu cầu chúng tôi tìm các tính từ miêu tả thời tiết.","audioKind":"ex"},{"en":"In academic writing, precise adjectives help readers understand complex ideas without relying on lengthy explanations.","vi":"Trong văn phong học thuật, các tính từ chính xác giúp người đọc hiểu được các khái niệm phức tạp mà không cần dựa vào những lời giải thích dài dòng.","audioKind":"ex2"}],"collocations":[{"en":"a descriptive adjective","vi":"tính từ miêu tả"},{"en":"a comparative adjective","vi":"tính từ so sánh"},{"en":"adjective order","vi":"trật tự tính từ"}],"wordFamily":["adjectival (adj.)","adjectivally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Tính từ thường đứng trước danh từ hoặc sau động từ liên kết, ví dụ như a cold day.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_playground', 'en-a2-2', 'playground', '/ˈpleɪɡraʊnd/', 'A2', 'sân chơi; sân trường', 'n.', NULL, NULL, 'Chủ yếu chỉ khu vực cho trẻ em chơi đùa, không dùng để chỉ sân vận động chuyên nghiệp.', 'The children raced to the playground after lunch.', NULL, 'Bọn trẻ chạy ùa ra sân chơi sau bữa trưa.', '{"wordId":"playground","ukIpa":"/ˈpleɪɡraʊnd/","usIpa":"/ˈpleɪɡraʊnd/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"An outdoor area where children play, often with special equipment.","vi":"sân chơi; sân trường"}],"examples":[{"en":"The children raced to the playground after lunch.","vi":"Bọn trẻ chạy ùa ra sân chơi sau bữa trưa.","audioKind":"ex"},{"en":"Every neighbourhood should provide a safe playground where children can exercise and develop social skills.","vi":"Mỗi khu139c nên cung cấp một sân chơi an toàn để trẻ em có thể rèn luyện sức khỏe và phát triển các kỹ năng xã hội.","audioKind":"ex2"}],"collocations":[{"en":"school playground","vi":"sân trường"},{"en":"playground equipment","vi":"thiết bị vui chơi"},{"en":"adventure playground","vi":"sân chơi mạo hiểm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chủ yếu chỉ khu vực cho trẻ em chơi đùa, không dùng để chỉ sân vận động chuyên nghiệp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spelling', 'en-a2-2', 'spelling', '/ˈspelɪŋ/', 'A2', 'khả năng chính tả; cách viết đúng chính tả; cách viết từ', 'n.', 'spell (v.), misspell (v.), misspelling (n.)', NULL, 'Khi chỉ kỹ năng chính tả thì thường không đếm được; khi chỉ cách viết cụ thể của một từ thì đếm được.', 'My sister checks my spelling before I send emails.', NULL, 'Chị tôi kiểm tra lỗi chính tả giúp tôi trước khi tôi gửi email.', '{"wordId":"spelling","ukIpa":"/ˈspelɪŋ/","usIpa":"/ˈspelɪŋ/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"forming words correctly using their written characters","vi":"khả năng chính tả; cách viết đúng chính tả"},{"pos":"n.","en":"the particular way a word is written","vi":"cách viết từ"}],"examples":[{"en":"My sister checks my spelling before I send emails.","vi":"Chị tôi kiểm tra lỗi chính tả giúp tôi trước khi tôi gửi email.","audioKind":"ex"},{"en":"Although digital tools can correct spelling, students still need to develop accurate writing skills.","vi":"Mặc dù các công cụ kỹ thuật số có thể sửa lỗi chính tả, học sinh vẫn cần phải phát triển kỹ năng viết chính xác.","audioKind":"ex2"}],"collocations":[{"en":"spelling mistake","vi":"lỗi chính tả"},{"en":"check your spelling","vi":"kiểm tra chính tả"},{"en":"correct spelling","vi":"cách viết đúng"}],"wordFamily":["spell (v.)","misspell (v.)","misspelling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ kỹ năng chính tả thì thường không đếm được; khi chỉ cách viết cụ thể của một từ thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quiz', 'en-a2-2', 'quiz', '/kwɪz/', 'A2', 'bài kiểm tra ngắn; trò chơi đố vui; kiểm tra; hỏi khảo sát chi tiết', 'n.', NULL, NULL, 'Dạng số nhiều là quizzes; dạng quá khứ là quizzed.', 'We played a music quiz after dinner yesterday.', NULL, 'Hôm qua sau bữa tối, chúng tôi đã chơi một trò chơi đố vui âm nhạc.', '{"wordId":"quiz","ukIpa":"/kwɪz/","usIpa":"/kwɪz/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"A short test or game involving questions.","vi":"bài kiểm tra ngắn; trò chơi đố vui"},{"pos":"v.","en":"To test someone''s knowledge or ask them detailed questions.","vi":"kiểm tra; hỏi khảo sát chi tiết"}],"examples":[{"en":"We played a music quiz after dinner yesterday.","vi":"Hôm qua sau bữa tối, chúng tôi đã chơi một trò chơi đố vui âm nhạc.","audioKind":"ex"},{"en":"A short quiz at the beginning of each lesson can help teachers identify gaps in students'' understanding.","vi":"Một bài kiểm tra ngắn ở đầu mỗi bài học có thể giúp giáo viên phát hiện những lỗ hổng trong sự hiểu biết của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"take a quiz","vi":"làm bài trắc nghiệm"},{"en":"general knowledge quiz","vi":"câu đố kiến thức chung"},{"en":"quiz someone on","vi":"đố ai đó về vấn đề gì"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là quizzes; dạng quá khứ là quizzed.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_practice', 'en-a2-2', 'practice', '/ˈpræktɪs/', 'A2', 'sự luyện tập; sự rèn luyện; thói quen; tập quán; cách làm; thực tiễn; thực tế', 'n.', 'practise (v.), practical (adj.), practitioner (n.)', NULL, 'Anh-Anh dùng practice cho danh từ và practise cho động từ; Anh-Mỹ đều dùng practice.', 'Daily practice helped me play the guitar more confidently.', NULL, 'Việc luyện tập hàng ngày giúp tôi chơi guitar tự tin hơn.', '{"wordId":"practice","ukIpa":"/ˈpræktɪs/","usIpa":"/ˈpræktɪs/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"Repeated activity done to improve a skill.","vi":"sự luyện tập; sự rèn luyện"},{"pos":"n.","en":"A usual or established way of doing something.","vi":"thói quen; tập quán; cách làm"},{"pos":"n.","en":"The actual use of an idea, method, or skill.","vi":"thực tiễn; thực tế"}],"examples":[{"en":"Daily practice helped me play the guitar more confidently.","vi":"Việc luyện tập hàng ngày giúp tôi chơi guitar tự tin hơn.","audioKind":"ex"},{"en":"Schools should give students opportunities to put scientific knowledge into practice through experiments and practical projects.","vi":"Nhà trường nên tạo cơ hội cho học sinh đưa kiến thức khoa học vào thực tiễn thông qua các thí nghiệm và dự án thực tế.","audioKind":"ex2"}],"collocations":[{"en":"regular practice","vi":"tập luyện thường xuyên"},{"en":"common practice","vi":"thói quen phổ biến"},{"en":"in practice","vi":"trong thực tế"},{"en":"put into practice","vi":"đưa vào thực tiễn"}],"wordFamily":["practise (v.)","practical (adj.)","practitioner (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Anh-Anh dùng practice cho danh từ và practise cho động từ; Anh-Mỹ đều dùng practice.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_learning', 'en-a2-2', 'learning', '/ˈlɝːnɪŋ/', 'A2', 'sự học; quá trình học tập; học thức; kiến thức uyên bác', 'n.', 'learn (v.), learner (n.), learned (adj.)', NULL, 'Thường là danh từ không đếm được; nhấn mạnh quá trình tiếp thu, trong khi knowledge nhấn mạnh lượng kiến thức đã nắm vững.', 'Learning becomes easier when I practise a little every day.', NULL, 'Việc học trở nên dễ dàng hơn khi tôi luyện tập một chút mỗi ngày.', '{"wordId":"learning","ukIpa":"/ˈlɜːnɪŋ/","usIpa":"/ˈlɝːnɪŋ/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"The process of gaining knowledge or skills through study or experience.","vi":"sự học; quá trình học tập"},{"pos":"n.","en":"Knowledge gained through extensive study.","vi":"học thức; kiến thức uyên bác"}],"examples":[{"en":"Learning becomes easier when I practise a little every day.","vi":"Việc học trở nên dễ dàng hơn khi tôi luyện tập một chút mỗi ngày.","audioKind":"ex"},{"en":"Schools can encourage independent learning by giving students opportunities to investigate questions beyond the standard curriculum.","vi":"Các trường học có thể khuyến khích việc tự học bằng cách trao cho học sinh cơ hội tìm hiểu những vấn đề nằm ngoài chương trình tiêu chuẩn.","audioKind":"ex2"}],"collocations":[{"en":"lifelong learning","vi":"học tập suốt đời"},{"en":"independent learning","vi":"tự học; học tập độc lập"},{"en":"a learning environment","vi":"môi trường học tập"},{"en":"a steep learning curve","vi":"quá trình học tập khó khăn và tốn nhiều thời gian"}],"wordFamily":["learn (v.)","learner (n.)","learned (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; nhấn mạnh quá trình tiếp thu, trong khi knowledge nhấn mạnh lượng kiến thức đã nắm vững.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_handwriting', 'en-a2-2', 'handwriting', '/ˈhændraɪtɪŋ/', 'A2', 'chữ viết tay; bút tích', 'n.', 'handwrite (v.), handwritten (adj.)', NULL, 'Thông thường đây là danh từ không đếm được; nghệ thuật viết chữ đẹp gọi là "calligraphy".', 'Your handwriting is much neater with this new pen.', NULL, 'Chữ viết tay của bạn cẩn thận và ngay ngắn hơn hẳn khi dùng cây bút mới này.', '{"wordId":"handwriting","ukIpa":"/ˈhændraɪtɪŋ/","usIpa":"/ˈhændraɪtɪŋ/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"The particular way someone forms words when writing by hand.","vi":"chữ viết tay; bút tích"}],"examples":[{"en":"Your handwriting is much neater with this new pen.","vi":"Chữ viết tay của bạn cẩn thận và ngay ngắn hơn hẳn khi dùng cây bút mới này.","audioKind":"ex"},{"en":"Although digital devices are common in classrooms, clear handwriting remains useful for examinations and personal communication.","vi":"Mặc dù các thiết bị kỹ thuật số rất phổ biến trong lớp học, chữ viết tay rõ ràng vẫn rất hữu ích cho các kỳ thi và giao tiếp cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"neat handwriting","vi":"chữ viết tay ngay ngắn"},{"en":"illegible handwriting","vi":"chữ viết tay khó đọc"},{"en":"improve your handwriting","vi":"cải thiện chữ viết tay"}],"wordFamily":["handwrite (v.)","handwritten (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thông thường đây là danh từ không đếm được; nghệ thuật viết chữ đẹp gọi là \"calligraphy\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mark', 'en-a2-2', 'mark', '/mɑrk/', 'A2', 'vết; dấu; vết bẩn hoặc ký hiệu trên bề mặt; điểm số; điểm (thể hiện chất lượng bài làm của học sinh); đánh dấu; làm dấu; chấm bài; cho điểm học sinh', 'n.', 'marker (n.), marking (n.), unmarked (adj.)', NULL, 'Khi chỉ điểm số trong kỳ thi, thường dùng dạng số nhiều marks, đặc biệt trong tiếng Anh-Anh.', 'Your wet glass left a mark on the table.', NULL, 'Cái cốc ướt của bạn đã để lại một vết trên bàn.', '{"wordId":"mark","ukIpa":"/mɑːk/","usIpa":"/mɑrk/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"a visible spot, line, or symbol on a surface","vi":"vết; dấu; vết bẩn hoặc ký hiệu trên bề mặt"},{"pos":"n.","en":"a score showing the quality of a student''s work","vi":"điểm số; điểm (thể hiện chất lượng bài làm của học sinh)"},{"pos":"v.","en":"to indicate something visibly or assess a student''s work","vi":"đánh dấu; làm dấu; chấm bài; cho điểm học sinh"}],"examples":[{"en":"Your wet glass left a mark on the table.","vi":"Cái cốc ướt của bạn đã để lại một vết trên bàn.","audioKind":"ex"},{"en":"Teachers should mark assignments consistently so that students receive fair and useful feedback.","vi":"Giáo viên nên chấm bài tập một cách nhất quán để học sinh nhận được những phản hồi công bằng và hữu ích.","audioKind":"ex2"}],"collocations":[{"en":"leave a mark","vi":"để lại dấu vết"},{"en":"get high marks","vi":"đạt điểm cao"},{"en":"mark an exam","vi":"chấm bài thi"},{"en":"full marks","vi":"điểm tuyệt đối"}],"wordFamily":["marker (n.)","marking (n.)","unmarked (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ điểm số trong kỳ thi, thường dùng dạng số nhiều marks, đặc biệt trong tiếng Anh-Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_speech', 'en-a2-2', 'speech', '/spiːtʃ/', 'A2', 'bài phát biểu; bài diễn thuyết; khả năng nói; lời nói', 'n.', 'speak (v.), speaker (n.), spoken (adj.), speechless (adj.)', NULL, 'Một bài phát biểu dùng a speech; khả năng nói thường là danh từ không đếm được.', 'Leila practised her speech in front of the mirror.', NULL, 'Leila đã đứng trước gương để luyện tập bài phát biểu của mình.', '{"wordId":"speech","ukIpa":"/spiːtʃ/","usIpa":"/spiːtʃ/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"A formal talk given to an audience.","vi":"bài phát biểu; bài diễn thuyết"},{"pos":"n.","en":"The ability or act of expressing thoughts through spoken words.","vi":"khả năng nói; lời nói"}],"examples":[{"en":"Leila practised her speech in front of the mirror.","vi":"Leila đã đứng trước gương để luyện tập bài phát biểu của mình.","audioKind":"ex"},{"en":"In his speech, the researcher explained how access to green spaces can improve children''s mental health.","vi":"Trong bài phát biểu của mình, nhà nghiên cứu đã giải thích việc tiếp cận không gian xanh có thể cải thiện sức khỏe tinh thần của trẻ em như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"give a speech","vi":"đọc diễn thuyết; phát biểu"},{"en":"freedom of speech","vi":"tự do ngôn luận"},{"en":"speech therapy","vi":"liệu pháp ngôn ngữ"},{"en":"opening speech","vi":"lời phát biểu khai mạc"}],"wordFamily":["speak (v.)","speaker (n.)","spoken (adj.)","speechless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Một bài phát biểu dùng a speech; khả năng nói thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_paragraph', 'en-a2-2', 'paragraph', '/ˈpærəɡræf/', 'A2', 'đoạn văn', 'n.', NULL, NULL, 'Là danh từ đếm được; trong văn bản, mỗi đoạn thường xoay quanh một ý chính duy nhất.', 'This paragraph is too long for a quick email.', NULL, 'Đoạn văn này quá dài đối với một bức thư điện tử ngắn gọn.', '{"wordId":"paragraph","ukIpa":"/ˈpærəɡrɑːf/","usIpa":"/ˈpærəɡræf/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"A section of writing dealing with one main idea.","vi":"đoạn văn"}],"examples":[{"en":"This paragraph is too long for a quick email.","vi":"Đoạn văn này quá dài đối với một bức thư điện tử ngắn gọn.","audioKind":"ex"},{"en":"Each paragraph in an academic essay should develop a clear argument supported by relevant evidence.","vi":"Mỗi đoạn văn trong bài luận học thuật phải phát triển một luận điểm rõ ràng được hỗ trợ bằng các bằng chứng xác thực.","audioKind":"ex2"}],"collocations":[{"en":"opening paragraph","vi":"đoạn mở đầu"},{"en":"concluding paragraph","vi":"đoạn kết luận"},{"en":"a short paragraph","vi":"một đoạn văn ngắn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được; trong văn bản, mỗi đoạn thường xoay quanh một ý chính duy nhất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_canteen', 'en-a2-2', 'canteen', '/kænˈtiːn/', 'A2', 'căn tin; nhà ăn; bình đựng nước cá nhân', 'n.', NULL, 'Đồng nghĩa: cafeteria', 'Trong tiếng Anh-Anh thường chỉ nhà ăn; tiếng Anh-Mỹ thường dùng cafeteria.', 'We usually eat lunch together in the school canteen.', NULL, 'Chúng tôi thường ăn trưa cùng nhau ở căn tin trường.', '{"wordId":"canteen","ukIpa":"/kænˈtiːn/","usIpa":"/kænˈtiːn/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"a place serving meals in a school or workplace","vi":"căn tin; nhà ăn"},{"pos":"n.","en":"a container used to carry drinking water outdoors","vi":"bình đựng nước cá nhân"}],"examples":[{"en":"We usually eat lunch together in the school canteen.","vi":"Chúng tôi thường ăn trưa cùng nhau ở căn tin trường.","audioKind":"ex"},{"en":"Providing affordable healthy meals in the workplace canteen can improve employee wellbeing and productivity.","vi":"Cung cấp các bữa ăn lành mạnh với giá cả phải chăng tại nhà ăn của cơ quan có thể cải thiện sức khỏe và năng suất làm việc của nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"school canteen","vi":"căn tin trường học"},{"en":"staff canteen","vi":"nhà ăn nhân viên"},{"en":"canteen food","vi":"đồ ăn căn tin"},{"en":"a water canteen","vi":"bình đựng nước"}],"wordFamily":[],"synonyms":["cafeteria"],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh thường chỉ nhà ăn; tiếng Anh-Mỹ thường dùng cafeteria.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_explain', 'en-a2-2', 'explain', '/ɪkˈspleɪn/', 'A2', 'giải thích; làm rõ; giải thích lý do; nêu nguyên nhân', 'v.', 'explanation (n.), explanatory (adj.), explainable (adj.)', 'Đồng nghĩa: clarify', 'Cấu trúc là explain something to someone, không dùng explain someone.', 'Could you explain how this coffee machine works?', NULL, 'Bạn có thể giải thích cách chiếc máy pha cà phê này hoạt động được không?', '{"wordId":"explain","ukIpa":"/ɪkˈspleɪn/","usIpa":"/ɪkˈspleɪn/","cefr":"A2","topic":"education","senses":[{"pos":"v.","en":"to make something clear or easy to understand","vi":"giải thích; làm rõ"},{"pos":"v.","en":"to give or be the reason why something happens","vi":"giải thích lý do; nêu nguyên nhân"}],"examples":[{"en":"Could you explain how this coffee machine works?","vi":"Bạn có thể giải thích cách chiếc máy pha cà phê này hoạt động được không?","audioKind":"ex"},{"en":"Differences in access to healthcare may partly explain why life expectancy varies considerably between regions.","vi":"Sự khác biệt trong việc tiếp cận dịch vụ y tế phần nào có thể giải thích lý do tại sao tuổi thọ lại chênh lệch đáng kể giữa các vùng miền.","audioKind":"ex2"}],"collocations":[{"en":"explain something to someone","vi":"giải thích điều gì cho ai"},{"en":"explain why","vi":"giải thích lý do tại sao"},{"en":"explain in detail","vi":"giải thích chi tiết"},{"en":"explain the difference","vi":"giải thích sự khác biệt"}],"wordFamily":["explanation (n.)","explanatory (adj.)","explainable (adj.)"],"synonyms":["clarify"],"antonyms":[],"tipVi":"Cấu trúc là explain something to someone, không dùng explain someone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_copy', 'en-a2-2', 'copy', '/ˈkɑːpi/', 'A2', 'bản sao; bản; cuốn; sao chép; chép lại; bắt chước; bản thảo; văn bản quảng cáo', 'n.', 'copier (n.), copying (n.), copywriter (n.)', 'Đồng nghĩa: duplicate, reproduce, imitate · Trái nghĩa: original', 'Dạng số nhiều là copies; từ copy mang nghĩa văn bản quảng cáo thường không đếm được.', 'Please keep a copy of the receipt at home.', NULL, 'Xin hãy giữ lại một bản sao của biên lai ở nhà.', '{"wordId":"copy","ukIpa":"/ˈkɒpi/","usIpa":"/ˈkɑːpi/","cefr":"A2","topic":"education","senses":[{"pos":"n.","en":"A reproduction, or one example of a book or document","vi":"bản sao; bản; cuốn"},{"pos":"v.","en":"To reproduce something or imitate someone''s actions","vi":"sao chép; chép lại; bắt chước"},{"pos":"n.","en":"Written material prepared for publication or advertising","vi":"bản thảo; văn bản quảng cáo"}],"examples":[{"en":"Please keep a copy of the receipt at home.","vi":"Xin hãy giữ lại một bản sao của biên lai ở nhà.","audioKind":"ex"},{"en":"Students should learn to evaluate sources rather than simply copy information from websites into their assignments.","vi":"Học sinh nên học cách đánh giá nguồn tài liệu thay vì chỉ đơn thuần sao chép thông tin từ các trang web vào bài tập của mình.","audioKind":"ex2"}],"collocations":[{"en":"a copy of","vi":"một bản của"},{"en":"a digital copy","vi":"bản sao kỹ thuật số"},{"en":"copy and paste","vi":"sao chép và dán"},{"en":"advertising copy","vi":"văn bản quảng cáo"}],"wordFamily":["copier (n.)","copying (n.)","copywriter (n.)"],"synonyms":["duplicate","reproduce","imitate"],"antonyms":["original"],"tipVi":"Dạng số nhiều là copies; từ copy mang nghĩa văn bản quảng cáo thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_2_1', 'en-a2-2', 'Cách dùng “learning” (n.) — sự học; quá trình học tập', 'lifelong learning  ·  independent learning  ·  a learning environment', 'Thường là danh từ không đếm được; nhấn mạnh quá trình tiếp thu, trong khi knowledge nhấn mạnh lượng kiến thức đã nắm vững.', 'Họ từ (Word Family): learn (v.), learner (n.), learned (adj.)', '[{"hanzi":"Learning becomes easier when I practise a little every day.","pinyin":"","meaning":"Việc học trở nên dễ dàng hơn khi tôi luyện tập một chút mỗi ngày."},{"hanzi":"Schools can encourage independent learning by giving students opportunities to investigate questions beyond the standard curriculum.","pinyin":"","meaning":"Các trường học có thể khuyến khích việc tự học bằng cách trao cho học sinh cơ hội tìm hiểu những vấn đề nằm ngoài chương trình tiêu chuẩn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_2_2', 'en-a2-2', 'Cách dùng “workbook” (n.) — sách bài tập', 'complete a workbook  ·  workbook exercises  ·  a grammar workbook', 'workbook tập trung vào việc làm bài tập thực hành; textbook tập trung vào việc giải thích kiến thức lý thuyết.', NULL, '[{"hanzi":"I left my workbook in my school bag.","pinyin":"","meaning":"Tôi để quên sách bài tập trong cặp sách rồi."},{"hanzi":"A well-designed workbook allows students to practise new skills independently and monitor their progress.","pinyin":"","meaning":"Một cuốn sách bài tập được thiết kế tốt cho phép học sinh tự luyện tập các kỹ năng mới và theo dõi sự tiến bộ của bản thân."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_2_3', 'en-a2-2', 'Cách dùng “programme” (n.) — chương trình; kế hoạch; đề án', 'training programme  ·  television programme  ·  degree programme', 'Tiếng Anh-Anh thường dùng programme, chương trình máy tính dùng program; tiếng Anh-Mỹ đều dùng program.', 'Họ từ (Word Family): programming (n.), programmer (n.)', '[{"hanzi":"I joined a fitness programme at the local gym.","pinyin":"","meaning":"Tôi đã tham gia một chương trình thể dục tại phòng gym địa phương."},{"hanzi":"A well-designed training programme can help unemployed adults gain the skills needed for new careers.","pinyin":"","meaning":"Một chương trình đào tạo được thiết kế kỹ lưỡng có thể giúp người lớn thất nghiệp có được các kỹ năng cần thiết cho nghề nghiệp mới."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_2_4', 'en-a2-2', 'Cách dùng “instruction” (n.) — hướng dẫn; chỉ dẫn', 'follow instructions  ·  step-by-step instructions  ·  give instructions', 'Chỉ dẫn thao tác thường dùng ở dạng số nhiều ''instructions''; khi chỉ việc dạy học thì không đếm được.', 'Họ từ (Word Family): instruct (v.), instructor (n.), instructive (adj.), instructional (adj.)', '[{"hanzi":"The instructor gave one clear instruction: hold the rope tightly.","pinyin":"","meaning":"Người hướng dẫn đưa ra một chỉ dẫn rõ ràng: giữ chặt sợi dây."},{"hanzi":"Students often benefit from practical instruction that connects classroom theory with everyday problems.","pinyin":"","meaning":"Học sinh thường hưởng lợi từ việc học thực hành kết hợp lý thuyết lớp học với các vấn đề thường ngày."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_2_1', 'en-a2-2', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
