INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_2_1_2', 'ten_a2_2_1', 'textbook', 'I left my science textbook on the kitchen table.', 'I left my science textbook on the kitchen table.', '/ˈtekstbʊk/', 'Tôi để quên sách khoa học trên bàn bếp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_2_1_3', 'ten_a2_2_1', 'instruction', 'The instructor gave one clear instruction: hold the rope tightly.', 'The instructor gave one clear instruction: hold the rope tightly.', '/ɪnˈstrʌkʃən/', 'Người hướng dẫn đưa ra một chỉ dẫn rõ ràng: giữ chặt sợi dây.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_2_1_4', 'ten_a2_2_1', 'mathematics', 'She enjoys mathematics, especially solving puzzles about shapes.', 'She enjoys mathematics, especially solving puzzles about shapes.', '/ˌmæθəˈmætɪks/', 'Cô ấy thích toán học, đặc biệt là việc giải các câu đố về hình học.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_2_1_5', 'ten_a2_2_1', 'prize', 'Lina won a prize for her colourful garden.', 'Lina won a prize for her colourful garden.', '/praɪz/', 'Lina đã giành được giải thưởng nhờ khu vườn rực rỡ sắc màu của mình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
