INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_2_1_7', 'ten_a2_2_1', 'speaker', 'The speaker made everyone laugh with her opening story.', 'The speaker made everyone laugh with her opening story.', '/ˈspiːkər/', 'Diễn giả đã làm tất cả mọi người bật cười với câu chuyện mở đầu của cô ấy.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_2_1_8', 'ten_a2_2_1', 'topic', 'Food is always a popular topic in our house.', 'Food is always a popular topic in our house.', '/ˈtɑːpɪk/', 'Đồ ăn luôn là một chủ đề phổ biến trong gia đình chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_2_1_1', 'en-a2-2', 'ten_a2_2_1', 'listening', 'listening', 'My cousin earned a degree in engineering last summer.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh họ tôi đã lấy bằng kỹ sư vào mùa hè năm ngoái.","Chúng tôi đã có một cuộc thảo luận sôi nổi về kế hoạch kỳ nghỉ của mình.","Diễn giả đã làm tất cả mọi người bật cười với câu chuyện mở đầu của cô ấy.","Bạn có thể giải thích cách chiếc máy pha cà phê này hoạt động được không?"]'::jsonb, 0, 'My cousin earned a degree in engineering last summer. → Anh họ tôi đã lấy bằng kỹ sư vào mùa hè năm ngoái.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_2_1_2', 'en-a2-2', 'ten_a2_2_1', 'listening', 'listening', 'I left my science textbook on the kitchen table.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi để quên sách khoa học trên bàn bếp.","Lina đã giành được giải thưởng nhờ khu vườn rực rỡ sắc màu của mình.","Ông tôi đã chia sẻ sự hiểu biết của ông về các loài chim với tôi.","Bạn có thể giải thích cách chiếc máy pha cà phê này hoạt động được không?"]'::jsonb, 0, 'I left my science textbook on the kitchen table. → Tôi để quên sách khoa học trên bàn bếp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_2_1_3', 'en-a2-2', 'ten_a2_2_1', 'listening', 'listening', 'The instructor gave one clear instruction: hold the rope tightly.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi để quên sách bài tập trong cặp sách rồi.","Việc học trở nên dễ dàng hơn khi tôi luyện tập một chút mỗi ngày.","Diễn giả đã làm tất cả mọi người bật cười với câu chuyện mở đầu của cô ấy.","Người hướng dẫn đưa ra một chỉ dẫn rõ ràng: giữ chặt sợi dây."]'::jsonb, 3, 'The instructor gave one clear instruction: hold the rope tightly. → Người hướng dẫn đưa ra một chỉ dẫn rõ ràng: giữ chặt sợi dây.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_2_2', 'en-a2-2', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_2_2_1', 'ten_a2_2_2', 'degree', 'Although a university degree can improve employment prospects, practical experience remains highly valuable in many industries.', 'Although a university degree can improve employment prospects, practical experience remains highly valuable in many industries.', '/dɪˈɡriː/', 'Mặc dù bằng đại học có thể cải thiện cơ hội việc làm, kinh nghiệm thực tế vẫn vô cùng giá trị trong nhiều ngành nghề.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_2_2_2', 'ten_a2_2_2', 'textbook', 'Digital textbooks can reduce school expenses, although some students find printed materials easier to study.', 'Digital textbooks can reduce school expenses, although some students find printed materials easier to study.', '/ˈtekstbʊk/', 'Sách giáo khoa kỹgital có thể giảm chi phí trường học, mặc dù một số học sinh thấy tài liệu in dễ học hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_2_2_3', 'ten_a2_2_2', 'instruction', 'Students often benefit from practical instruction that connects classroom theory with everyday problems.', 'Students often benefit from practical instruction that connects classroom theory with everyday problems.', '/ɪnˈstrʌkʃən/', 'Học sinh thường hưởng lợi từ việc học thực hành kết hợp lý thuyết lớp học với các vấn đề thường ngày.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_2_2_4', 'ten_a2_2_2', 'mathematics', 'A strong foundation in mathematics enables students to interpret data and evaluate claims in everyday life.', 'A strong foundation in mathematics enables students to interpret data and evaluate claims in everyday life.', '/ˌmæθəˈmætɪks/', 'Nền tảng toán học vững chắc giúp học sinh diễn giải dữ liệu và đánh giá các nhận định trong đời sống hằng ngày.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_2_2_5', 'ten_a2_2_2', 'prize', 'Offering a prize for innovative designs can encourage students to develop practical solutions to environmental problems.', 'Offering a prize for innovative designs can encourage students to develop practical solutions to environmental problems.', '/praɪz/', 'Việc trao giải thưởng cho các thiết kế đổi mới có thể khuyến khích học sinh tìm ra các giải pháp thiết thực cho các vấn đề môi trường.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_2_2_6', 'ten_a2_2_2', 'programme', 'A well-designed training programme can help unemployed adults gain the skills needed for new careers.', 'A well-designed training programme can help unemployed adults gain the skills needed for new careers.', '/ˈproʊɡræm/', 'Một chương trình đào tạo được thiết kế kỹ lưỡng có thể giúp người lớn thất nghiệp có được các kỹ năng cần thiết cho nghề nghiệp mới.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_2_2_1', 'en-a2-2', 'ten_a2_2_2', 'listening', 'listening', 'Although a university degree can improve employment prospects, practical experience remains highly valuable in many industries.', NULL, 'Trong câu vừa nghe, từ “degree” mang nghĩa nào sau đây?', '["bằng cấp; văn bằng","tuyệt vời; đáng kinh ngạc","nghiêm trọng; trầm trọng","cuối cùng; sau cùng (sau một thời gian dài chờ đợi hoặc nỗ lực)"]'::jsonb, 0, '“degree” (/dɪˈɡriː/): bằng cấp; văn bằng. Câu đầy đủ: Although a university degree can improve employment prospects, practical experience remains highly valuable in many industries.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_2_2_2', 'en-a2-2', 'ten_a2_2_2', 'listening', 'listening', 'Digital textbooks can reduce school expenses, although some students find printed materials easier to study.', NULL, 'Trong câu vừa nghe, từ “textbook” mang nghĩa nào sau đây?', '["sóng; sóng biển","từng; bao giờ (đặc biệt dùng trong câu hỏi và câu phủ định)","theo như; theo lời","sách giáo khoa; giáo trình"]'::jsonb, 3, '“textbook” (/ˈtekstbʊk/): sách giáo khoa; giáo trình. Câu đầy đủ: Digital textbooks can reduce school expenses, although some students find printed materials easier to study.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
