INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_2_4', 'en-a2-2', NULL, 'comprehensive_test', 'listening', 'She enjoys mathematics, especially solving puzzles about shapes.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Việc luyện tập hàng ngày giúp tôi chơi guitar tự tin hơn.","Chữ viết tay của bạn cẩn thận và ngay ngắn hơn hẳn khi dùng cây bút mới này.","Cô ấy thích toán học, đặc biệt là việc giải các câu đố về hình học.","Leila đã đứng trước gương để luyện tập bài phát biểu của mình."]'::jsonb, 2, 'She enjoys mathematics, especially solving puzzles about shapes. → Cô ấy thích toán học, đặc biệt là việc giải các câu đố về hình học.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
