INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_2_6', 'en-a2-2', NULL, 'comprehensive_test', 'listening', 'I joined a fitness programme at the local gym.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã tham gia một chương trình thể dục tại phòng gym địa phương.","Việc học trở nên dễ dàng hơn khi tôi luyện tập một chút mỗi ngày.","Xin hãy giữ lại một bản sao của biên lai ở nhà.","Ông tôi đã chia sẻ sự hiểu biết của ông về các loài chim với tôi."]'::jsonb, 0, 'I joined a fitness programme at the local gym. → Tôi đã tham gia một chương trình thể dục tại phòng gym địa phương.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_2_7', 'en-a2-2', NULL, 'comprehensive_test', 'listening', 'speaker', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khổng lồ; to lớn; rất nhiều (về kích thước, số lượng hoặc mức độ)","thời khóa biểu; lịch trình; bảng giờ tàu chạy","diễn giả; người phát biểu","láng giềng; người hàng xóm"]'::jsonb, 2, 'speaker (/ˈspiːkər/) → diễn giả; người phát biểu; người nói (một ngôn ngữ nào đó); loa; thiết bị phát âm thanh', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_2_8', 'en-a2-2', NULL, 'comprehensive_test', 'listening', 'Food is always a popular topic in our house.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chữ viết tay của bạn cẩn thận và ngay ngắn hơn hẳn khi dùng cây bút mới này.","Việc học trở nên dễ dàng hơn khi tôi luyện tập một chút mỗi ngày.","Đồ ăn luôn là một chủ đề phổ biến trong gia đình chúng tôi.","Chúng tôi đã có một cuộc thảo luận sôi nổi về kế hoạch kỳ nghỉ của mình."]'::jsonb, 2, 'Food is always a popular topic in our house. → Đồ ăn luôn là một chủ đề phổ biến trong gia đình chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_2_9', 'en-a2-2', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “something given for winning a competition or achieving something”?', '["mathematics","description","canteen","prize"]'::jsonb, 3, 'prize (/praɪz/) → giải thưởng; phần thưởng', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_2_10', 'en-a2-2', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “an organised set of activities with a particular purpose”?', '["workbook","playground","instruction","programme"]'::jsonb, 3, 'programme (/ˈproʊɡræm/) → chương trình; kế hoạch; đề án', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_2_11', 'en-a2-2', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a person who gives a talk or addresses others”?', '["speech","copy","speaker","adjective"]'::jsonb, 2, 'speaker (/ˈspiːkər/) → diễn giả; người phát biểu', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_2_12', 'en-a2-2', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a subject that people discuss, write about, or study”?', '["quiz","practice","workbook","topic"]'::jsonb, 3, 'topic (/ˈtɑːpɪk/) → chủ đề; đề tài', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
