INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_2_18', 'en-a2-2', NULL, 'comprehensive_test', 'reading', NULL, 'Although a university degree can improve employment prospects, practical experience remains highly valuable in many industries.', 'Dựa vào câu trên, từ “degree” có nghĩa phù hợp nhất là gì?', '["hành khách; khách đi xe, tàu, máy bay","bằng cấp; văn bằng","tạo ra; sáng tạo","một chút; một lượng nhỏ; một miếng nhỏ"]'::jsonb, 1, 'degree: bằng cấp; văn bằng; mức độ; chừng mực; độ (đơn vị đo nhiệt độ hoặc góc). Dịch cả câu: Mặc dù bằng đại học có thể cải thiện cơ hội việc làm, kinh nghiệm thực tế vẫn vô cùng giá trị trong nhiều ngành nghề.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_2_19', 'en-a2-2', NULL, 'comprehensive_test', 'reading', NULL, 'Digital textbooks can reduce school expenses, although some students find printed materials easier to study.', 'Dựa vào câu trên, từ “textbook” có nghĩa phù hợp nhất là gì?', '["sách giáo khoa; giáo trình","ước gì; mong rằng","nghiêm trọng; trầm trọng","tồi tệ; khó chịu"]'::jsonb, 0, 'textbook: sách giáo khoa; giáo trình; điển hình; chuẩn mực. Dịch cả câu: Sách giáo khoa kỹgital có thể giảm chi phí trường học, mặc dù một số học sinh thấy tài liệu in dễ học hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_2_20', 'en-a2-2', NULL, 'comprehensive_test', 'reading', NULL, 'Students often benefit from practical instruction that connects classroom theory with everyday problems.', 'Dựa vào câu trên, từ “instruction” có nghĩa phù hợp nhất là gì?', '["hướng dẫn; chỉ dẫn","giày thể thao; giày vải đế cao su","cái giỏ; cái sọt","thuộc về Ấn Độ hoặc người Ấn Độ"]'::jsonb, 0, 'instruction: hướng dẫn; chỉ dẫn; lệnh; chỉ thị; sự giảng dạy; sự hướng dẫn. Dịch cả câu: Học sinh thường hưởng lợi từ việc học thực hành kết hợp lý thuyết lớp học với các vấn đề thường ngày.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_2_21', 'en-a2-2', NULL, 'comprehensive_test', 'reading', NULL, 'A strong foundation in mathematics enables students to interpret data and evaluate claims in everyday life.', 'Dựa vào câu trên, từ “mathematics” có nghĩa phù hợp nhất là gì?', '["hầu như; suýt; gần như","môn toán; toán học","cộng sự; đối tác; người cùng chơi","việc gia nhập; việc tham gia"]'::jsonb, 1, 'mathematics: môn toán; toán học. Dịch cả câu: Nền tảng toán học vững chắc giúp học sinh diễn giải dữ liệu và đánh giá các nhận định trong đời sống hằng ngày.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_2_22', 'en-a2-2', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “căn tin; nhà ăn”', '["windsurfing","helpful","canteen","comfortable"]'::jsonb, 2, 'căn tin; nhà ăn → canteen (/kænˈtiːn/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_2_23', 'en-a2-2', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “giải thích; làm rõ”', '["explain","jam","still","mirror"]'::jsonb, 0, 'giải thích; làm rõ → explain (/ɪkˈspleɪn/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
