INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-3', 'en', 'Bài 3: Du lịch & Di chuyển (1) - CEFR A2', 'CEFR A2', 'A2 · Du lịch', '24 từ vựng Tiếng Anh CEFR A2 chủ đề du lịch & di chuyển kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2003, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_along', 'en-a2-3', 'along', '/əˈlɔːŋ/', 'A2', 'dọc theo; theo; về phía trước; cùng nhau; đi kèm', 'prep.', NULL, NULL, 'along chỉ hành động di chuyển dọc theo chiều dài; across nhấn mạnh việc băng qua từ bên này sang bên kia.', 'We walked along the river and watched the ducks.', NULL, 'Chúng tôi đi dạo dọc bờ sông và ngắm nhìn những con vịt.', '{"wordId":"along","ukIpa":"/əˈlɒŋ/","usIpa":"/əˈlɔːŋ/","cefr":"A2","topic":"travel","senses":[{"pos":"prep.","en":"following the length or direction of something","vi":"dọc theo; theo"},{"pos":"adv.","en":"forward from one place towards another","vi":"về phía trước"},{"pos":"adv.","en":"with someone when they go somewhere","vi":"cùng nhau; đi kèm"}],"examples":[{"en":"We walked along the river and watched the ducks.","vi":"Chúng tôi đi dạo dọc bờ sông và ngắm nhìn những con vịt.","audioKind":"ex"},{"en":"Planting trees along busy roads can provide shade for pedestrians and improve the appearance of urban areas.","vi":"Việc trồng cây dọc các con đường bận rộn có thể che bóng mát cho người đi bộ và cải thiện diện mạo khu đô thị.","audioKind":"ex2"}],"collocations":[{"en":"along the coast","vi":"dọc theo bờ biển"},{"en":"come along","vi":"đi cùng"},{"en":"bring someone along","vi":"dẫn ai đi cùng"},{"en":"along with","vi":"cùng với; kèm theo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"along chỉ hành động di chuyển dọc theo chiều dài; across nhấn mạnh việc băng qua từ bên này sang bên kia.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_distance', 'en-a2-3', 'distance', '/ˈdɪstəns/', 'A2', 'khoảng cách; quãng đường; sự xa cách; khoảng cách tình cảm; giữ khoảng cách; tạo khoảng cách; tách biệt', 'n.', 'distant (adj.), distantly (adv.)', NULL, 'in the distance chỉ khoảng cách ở xa; at a distance chỉ việc cách một đoạn khoảng cách.', 'The distance from our house to school is quite short.', NULL, 'Khoảng cách từ nhà chúng tôi đến trường khá ngắn.', '{"wordId":"distance","ukIpa":"/ˈdɪstəns/","usIpa":"/ˈdɪstəns/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"The amount of space between two places or things","vi":"khoảng cách; quãng đường"},{"pos":"n.","en":"A lack of emotional closeness between people","vi":"sự xa cách; khoảng cách tình cảm"},{"pos":"v.","en":"To separate yourself from someone, something, or their views","vi":"giữ khoảng cách; tạo khoảng cách; tách biệt"}],"examples":[{"en":"The distance from our house to school is quite short.","vi":"Khoảng cách từ nhà chúng tôi đến trường khá ngắn.","audioKind":"ex"},{"en":"Reducing the distance between residential areas and workplaces could lower transport emissions and improve urban quality of life.","vi":"Việc thu hẹp khoảng cách giữa các khu dân cư và nơi làm việc có thể làm giảm lượng khí thải giao thông và cải thiện chất lượng cuộc sống đô thị.","audioKind":"ex2"}],"collocations":[{"en":"walking distance","vi":"khoảng cách có thể đi bộ được"},{"en":"in the distance","vi":"ở đằng xa; trong khoảng xa"},{"en":"keep your distance","vi":"giữ khoảng cách"},{"en":"distance yourself from","vi":"giữ khoảng cách với; vạch ranh giới với"}],"wordFamily":["distant (adj.)","distantly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"in the distance chỉ khoảng cách ở xa; at a distance chỉ việc cách một đoạn khoảng cách.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vacation', 'en-a2-3', 'vacation', '/veɪˈkeɪʃən/', 'A2', 'kỳ nghỉ; thời gian nghỉ ngơi, du lịch; đi nghỉ mát; đi du lịch xa nhà', 'n.', 'vacationer (n.)', 'Đồng nghĩa: holiday', 'Chủ yếu dùng trong tiếng Anh Mỹ; tiếng Anh Anh thường dùng holiday.', 'We spent our summer vacation camping beside a lake.', NULL, 'Chúng tôi đã dành kỳ nghỉ hè để cắm trại bên bờ hồ.', '{"wordId":"vacation","ukIpa":"/vəˈkeɪʃən/","usIpa":"/veɪˈkeɪʃən/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"time away from work or study for rest or travel","vi":"kỳ nghỉ; thời gian nghỉ ngơi, du lịch"},{"pos":"v.","en":"to spend a holiday somewhere away from home","vi":"đi nghỉ mát; đi du lịch xa nhà"}],"examples":[{"en":"We spent our summer vacation camping beside a lake.","vi":"Chúng tôi đã dành kỳ nghỉ hè để cắm trại bên bờ hồ.","audioKind":"ex"},{"en":"Taking a regular vacation may improve employees'' mental health and help them return to work with greater motivation.","vi":"Việc duy trì kỳ nghỉ đều đặn có thể cải thiện sức khỏe tinh thần của nhân viên và giúp họ quay lại làm việc với động lực lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"on vacation","vi":"đang đi nghỉ mát"},{"en":"take a vacation","vi":"đi nghỉ"},{"en":"summer vacation","vi":"kỳ nghỉ hè"},{"en":"paid vacation","vi":"nghỉ phép có lương"}],"wordFamily":["vacationer (n.)"],"synonyms":["holiday"],"antonyms":[],"tipVi":"Chủ yếu dùng trong tiếng Anh Mỹ; tiếng Anh Anh thường dùng holiday.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_traveler', 'en-a2-3', 'traveler', '/ˈtrævələr/', 'A2', 'người đi du lịch; hành khách; lữ khách', 'n.', 'travel (v.), travel (n.), traveling (adj.)', NULL, 'traveler là cách viết theo kiểu Mỹ; tiếng Anh Anh thường viết là traveller.', 'A tired traveler asked me where the station was.', NULL, 'Một vị lữ khách mệt mỏi đã hỏi tôi ga tàu nằm ở đâu.', '{"wordId":"traveler","ukIpa":"/ˈtrævələ/","usIpa":"/ˈtrævələr/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"a person who travels from one place to another","vi":"người đi du lịch; hành khách; lữ khách"}],"examples":[{"en":"A tired traveler asked me where the station was.","vi":"Một vị lữ khách mệt mỏi đã hỏi tôi ga tàu nằm ở đâu.","audioKind":"ex"},{"en":"Every traveler can support local communities by choosing accommodation and services owned by residents.","vi":"Mỗi du khách đều có thể hỗ trợ cộng đồng địa phương bằng cách chọn các cơ sở lưu trú và dịch vụ do chính cư dân bản địa sở hữu.","audioKind":"ex2"}],"collocations":[{"en":"solo traveler","vi":"người đi du lịch một mình"},{"en":"business traveler","vi":"khách du lịch công tác"},{"en":"frequent traveler","vi":"người đi du lịch thường xuyên"}],"wordFamily":["travel (v.)","travel (n.)","traveling (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"traveler là cách viết theo kiểu Mỹ; tiếng Anh Anh thường viết là traveller.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lost', 'en-a2-3', 'lost', '/lɔːst/', 'A2', 'lạc đường; bị thất lạc; bối rối; lúng túng; không biết phải làm gì; đã mất; đã thua (dạng quá khứ và phân từ hai của lose)', 'adj.', 'lose (v.), loss (n.), loser (n.)', 'Đồng nghĩa: missing, bewildered · Trái nghĩa: found', 'get lost có thể mang nghĩa là lạc đường; nếu dùng riêng như một câu mệnh lệnh thì mang sắc thái thô lỗ.', 'We got lost while walking through the old town.', NULL, 'Chúng tôi đã bị lạc đường khi đang đi bộ qua khu phố cổ.', '{"wordId":"lost","ukIpa":"/lɒst/","usIpa":"/lɔːst/","cefr":"A2","topic":"travel","senses":[{"pos":"adj.","en":"Unable to find the way, or unable to be found.","vi":"lạc đường; bị thất lạc"},{"pos":"adj.","en":"Unable to understand something or decide what to do.","vi":"bối rối; lúng túng; không biết phải làm gì"},{"pos":"v.","en":"Past tense and past participle of lose.","vi":"đã mất; đã thua (dạng quá khứ và phân từ hai của lose)"}],"examples":[{"en":"We got lost while walking through the old town.","vi":"Chúng tôi đã bị lạc đường khi đang đi bộ qua khu phố cổ.","audioKind":"ex"},{"en":"Without clear guidance, new university students may feel lost when choosing courses that affect their future careers.","vi":"Nếu thiếu sự định hướng rõ ràng, tân sinh viên đại học có thể cảm thấy bối rối khi chọn các môn học ảnh hưởng đến sự nghiệp tương lai của họ.","audioKind":"ex2"}],"collocations":[{"en":"get lost","vi":"bị lạc đường"},{"en":"lost property","vi":"đồ thất lạc"},{"en":"feel lost","vi":"cảm thấy bối rối"},{"en":"lost in thought","vi":"chìm đắm trong suy nghĩ"}],"wordFamily":["lose (v.)","loss (n.)","loser (n.)"],"synonyms":["missing","bewildered"],"antonyms":["found"],"tipVi":"get lost có thể mang nghĩa là lạc đường; nếu dùng riêng như một câu mệnh lệnh thì mang sắc thái thô lỗ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tour', 'en-a2-3', 'tour', '/tʊr/', 'A2', 'chuyến tham quan; cuộc đi vòng quanh; chuyến lưu diễn; chuyến thi đấu giao hữu; đi du lịch; đi lưu diễn', 'n.', 'tourism (n.), tourist (n.), touring (adj.)', NULL, 'tour nhấn mạnh hoạt động tham quan hoặc lịch trình nhiều điểm dừng; trip mang nghĩa chung cho một chuyến đi.', 'We took a guided tour of the old castle.', NULL, 'Chúng tôi đã tham gia một chuyến tham quan có hướng dẫn viên tại lâu đài cổ.', '{"wordId":"tour","ukIpa":"/tʊə/","usIpa":"/tʊr/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A journey visiting several places, or a guided visit somewhere.","vi":"chuyến tham quan; cuộc đi vòng quanh"},{"pos":"n.","en":"A series of performances or matches held in different places.","vi":"chuyến lưu diễn; chuyến thi đấu giao hữu"},{"pos":"v.","en":"To travel around places for sightseeing, performances, or other activities.","vi":"đi du lịch; đi lưu diễn"}],"examples":[{"en":"We took a guided tour of the old castle.","vi":"Chúng tôi đã tham gia một chuyến tham quan có hướng dẫn viên tại lâu đài cổ.","audioKind":"ex"},{"en":"Organized tours can introduce visitors to local traditions while providing reliable income for community guides.","vi":"Các chuyến tham quan được tổ chức bài bản có thể giới thiệu các truyền thống địa phương cho du khách đồng thời mang lại nguồn thu nhập ổn định cho hướng dẫn viên cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"guided tour","vi":"chuyến tham quan có hướng dẫn viên"},{"en":"walking tour","vi":"chuyến đi bộ tham quan"},{"en":"concert tour","vi":"chuyến lưu diễn ca nhạc"},{"en":"go on tour","vi":"đi lưu diễn"}],"wordFamily":["tourism (n.)","tourist (n.)","touring (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"tour nhấn mạnh hoạt động tham quan hoặc lịch trình nhiều điểm dừng; trip mang nghĩa chung cho một chuyến đi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_path', 'en-a2-3', 'path', '/pæθ/', 'A2', 'đường mòn; lối đi nhỏ; đường đi; quỹ đạo; con đường; phương hướng', 'n.', NULL, NULL, 'Để chỉ phương thức đạt được mục tiêu, dùng "a path to", theo sau "to" là một danh từ.', 'We followed a narrow path down to the beach.', NULL, 'Chúng tôi đi theo một con đường mòn nhỏ dẫn xuống bãi biển.', '{"wordId":"path","ukIpa":"/pɑːθ/","usIpa":"/pæθ/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A narrow track for people to walk along.","vi":"đường mòn; lối đi nhỏ"},{"pos":"n.","en":"The route along which someone or something moves.","vi":"đường đi; quỹ đạo"},{"pos":"n.","en":"A way of achieving something or developing over time.","vi":"con đường; phương hướng"}],"examples":[{"en":"We followed a narrow path down to the beach.","vi":"Chúng tôi đi theo một con đường mòn nhỏ dẫn xuống bãi biển.","audioKind":"ex"},{"en":"Access to affordable education can provide a path out of poverty for disadvantaged communities.","vi":"Việc tiếp cận giáo dục vừa túi tiền có thể mang lại con đường thoát nghèo cho các cộng đồng có hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"follow a path","vi":"đi theo lối mòn"},{"en":"career path","vi":"con đường sự nghiệp"},{"en":"flight path","vi":"đường bay"},{"en":"a path to success","vi":"con đường dẫn đến thành công"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Để chỉ phương thức đạt được mục tiêu, dùng \"a path to\", theo sau \"to\" là một danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_northeast', 'en-a2-3', 'northeast', '/ˌnɔːrθˈiːst/', 'A2', 'phía đông bắc; miền đông bắc; thuộc phía đông bắc; ở phía đông bắc; về hướng đông bắc', 'n.', 'northeastern (adj.)', 'Trái nghĩa: southwest', 'Dùng "northeast of" để chỉ vị trí nằm ở phía đông bắc của nơi nào đó; tiếng Anh Anh cũng viết là "north-east".', 'The storm is moving northeast towards the coastal villages.', NULL, 'Cơn bão đang di chuyển về hướng đông bắc tiến vào các ngôi làng ven biển.', '{"wordId":"northeast","ukIpa":"/ˌnɔːθˈiːst/","usIpa":"/ˌnɔːrθˈiːst/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"The direction between north and east, or an area''s northeastern part.","vi":"phía đông bắc; miền đông bắc"},{"pos":"adj.","en":"Located in, facing, or coming from the northeast.","vi":"thuộc phía đông bắc; ở phía đông bắc"},{"pos":"adv.","en":"Towards or in the direction between north and east.","vi":"về hướng đông bắc"}],"examples":[{"en":"The storm is moving northeast towards the coastal villages.","vi":"Cơn bão đang di chuyển về hướng đông bắc tiến vào các ngôi làng ven biển.","audioKind":"ex"},{"en":"Investment in rail connections could improve access to employment for communities in the northeast of the country.","vi":"Việc đầu tư vào các tuyến đường sắt có thể cải thiện khả năng tiếp cận việc làm cho người dân ở vùng đông bắc của đất nước.","audioKind":"ex2"}],"collocations":[{"en":"in the northeast","vi":"ở phía đông bắc"},{"en":"head northeast","vi":"đi về hướng đông bắc"},{"en":"the northeast coast","vi":"bờ biển phía đông bắc"}],"wordFamily":["northeastern (adj.)"],"synonyms":[],"antonyms":["southwest"],"tipVi":"Dùng \"northeast of\" để chỉ vị trí nằm ở phía đông bắc của nơi nào đó; tiếng Anh Anh cũng viết là \"north-east\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_driving', 'en-a2-3', 'driving', '/ˈdraɪvɪŋ/', 'A2', 'việc lái xe; kỹ năng lái xe; có tính thúc đẩy; quyết định; mưa gió dữ dội', 'n.', 'drive (v.), driver (n.)', NULL, 'driving force có nghĩa là động lực thúc đẩy; driving cũng có thể đóng vai trò là phân từ hiện tại của drive.', 'Her careful driving made the mountain journey feel safe.', NULL, 'Cách lái xe cẩn thận của cô ấy giúp chuyến hành trình qua vùng núi trở nên an toàn.', '{"wordId":"driving","ukIpa":"/ˈdraɪvɪŋ/","usIpa":"/ˈdraɪvɪŋ/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"the activity of controlling a car or another road vehicle","vi":"việc lái xe; kỹ năng lái xe"},{"pos":"adj.","en":"strongly influencing something and making it happen","vi":"có tính thúc đẩy; quyết định"},{"pos":"adj.","en":"blown hard by strong winds","vi":"mưa gió dữ dội"}],"examples":[{"en":"Her careful driving made the mountain journey feel safe.","vi":"Cách lái xe cẩn thận của cô ấy giúp chuyến hành trình qua vùng núi trở nên an toàn.","audioKind":"ex"},{"en":"Technological innovation is a driving force behind economic growth, although its benefits are not always shared equally.","vi":"Đổi mới công nghệ là động lực thúc đẩy tăng trưởng kinh tế, mặc dù lợi ích từ đó không phải lúc nào cũng được phân chia công bằng.","audioKind":"ex2"}],"collocations":[{"en":"driving test","vi":"bài thi sát hạch lái xe"},{"en":"driving licence","vi":"giấy phép lái xe"},{"en":"driving force","vi":"động lực thúc đẩy"},{"en":"driving rain","vi":"cơn mưa tầm tã"}],"wordFamily":["drive (v.)","driver (n.)"],"synonyms":[],"antonyms":[],"tipVi":"driving force có nghĩa là động lực thúc đẩy; driving cũng có thể đóng vai trò là phân từ hiện tại của drive.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wheel', 'en-a2-3', 'wheel', '/wiːl/', 'A2', 'bánh xe; vô lăng; tay lái; đẩy (xe có bánh) di chuyển', 'n.', 'wheeled (adj.), wheelchair (n.)', NULL, 'Cụm từ at hoặc behind the wheel thường diễn tả hành động đang lái xe.', 'The front wheel of my bicycle needs replacing.', NULL, 'Bánh trước chiếc xe đạp của tôi cần phải được thay thế.', '{"wordId":"wheel","ukIpa":"/wiːl/","usIpa":"/wiːl/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A round object that turns to move a vehicle.","vi":"bánh xe"},{"pos":"n.","en":"The circular control used to steer a vehicle.","vi":"vô lăng; tay lái"},{"pos":"v.","en":"To move something along on its wheels.","vi":"đẩy (xe có bánh) di chuyển"}],"examples":[{"en":"The front wheel of my bicycle needs replacing.","vi":"Bánh trước chiếc xe đạp của tôi cần phải được thay thế.","audioKind":"ex"},{"en":"Transport planners should ensure that passengers can wheel their luggage easily through stations and onto trains.","vi":"Các nhà quy hoạch giao thông nên đảm bảo rằng hành khách có thể dễ dàng đẩy hành lý của họ qua ga và lên tàu.","audioKind":"ex2"}],"collocations":[{"en":"front wheel","vi":"bánh trước"},{"en":"steering wheel","vi":"vô lăng"},{"en":"behind the wheel","vi":"đang lái xe; nắm quyền điều khiển"},{"en":"wheel a trolley","vi":"đẩy xe đẩy hàng"}],"wordFamily":["wheeled (adj.)","wheelchair (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ at hoặc behind the wheel thường diễn tả hành động đang lái xe.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gate', 'en-a2-3', 'gate', '/ɡeɪt/', 'A2', 'cổng; cửa rào; cổng ra máy bay; cửa lên máy bay', 'n.', NULL, NULL, 'Từ "gate" thường chỉ cửa ở hàng rào hoặc tường rào; cửa phòng thường dùng "door".', 'She closed the garden gate to keep the dog inside.', NULL, 'Cô ấy đóng cửa sân vườn lại để nhốt con chó ở bên trong.', '{"wordId":"gate","ukIpa":"/ɡeɪt/","usIpa":"/ɡeɪt/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A movable barrier controlling entry through a fence or wall.","vi":"cổng; cửa rào"},{"pos":"n.","en":"An airport area where passengers board a plane.","vi":"cổng ra máy bay; cửa lên máy bay"}],"examples":[{"en":"She closed the garden gate to keep the dog inside.","vi":"Cô ấy đóng cửa sân vườn lại để nhốt con chó ở bên trong.","audioKind":"ex"},{"en":"Airports should provide clear directions so passengers can reach their departure gate without unnecessary stress.","vi":"Các sân bay nên cung cấp chỉ dẫn rõ ràng để hành khách có thể đến cửa ra máy bay của mình mà không bị căng thẳng không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"front gate","vi":"cổng trước"},{"en":"departure gate","vi":"cổng ra máy bay"},{"en":"school gate","vi":"cổng trường"},{"en":"lock the gate","vi":"khóa cổng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ \"gate\" thường chỉ cửa ở hàng rào hoặc tường rào; cửa phòng thường dùng \"door\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_platform', 'en-a2-3', 'platform', '/ˈplætfɔːrm/', 'A2', 'sân ga; thềm nhà ga; bục; bục phát biểu; nền tảng; hệ thống trực tuyến', 'n.', NULL, NULL, 'Khi ở trên sân ga, dùng giới từ "on the platform", không dùng "in".', 'We waited on the platform as the train approached.', NULL, 'Chúng tôi đứng chờ trên sân ga khi đoàn tàu đang tiến vào.', '{"wordId":"platform","ukIpa":"/ˈplætfɔːm/","usIpa":"/ˈplætfɔːrm/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"The area beside railway tracks where passengers board trains.","vi":"sân ga; thềm nhà ga"},{"pos":"n.","en":"A raised surface where people can stand or perform.","vi":"bục; bục phát biểu"},{"pos":"n.","en":"A service or system for sharing information or doing activities.","vi":"nền tảng; hệ thống trực tuyến"}],"examples":[{"en":"We waited on the platform as the train approached.","vi":"Chúng tôi đứng chờ trên sân ga khi đoàn tàu đang tiến vào.","audioKind":"ex"},{"en":"Online learning platforms allow students in remote areas to access courses that are unavailable locally.","vi":"Các nền tảng học trực tuyến giúp học sinh ở vùng sâu vùng xa tiếp cận được những khóa học mà ở địa phương không có.","audioKind":"ex2"}],"collocations":[{"en":"railway platform","vi":"sân ga tàu"},{"en":"online platform","vi":"nền tảng trực tuyến"},{"en":"a platform for debate","vi":"diễn đàn tranh luận"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi ở trên sân ga, dùng giới từ \"on the platform\", không dùng \"in\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rucksack', 'en-a2-3', 'rucksack', '/ˈrʌksæk/', 'A2', 'ba lô đeo lưng', 'n.', NULL, 'Đồng nghĩa: backpack', 'Tiếng Anh - Anh thường dùng rucksack; không giới hạn chất liệu bằng vải bạt.', 'I packed my lunch and jacket in a rucksack.', NULL, 'Tôi đã nhét bữa trưa và áo khoác vào một chiếc ba lô.', '{"wordId":"rucksack","ukIpa":"/ˈrʌksæk/","usIpa":"/ˈrʌksæk/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A bag carried on your back using shoulder straps.","vi":"ba lô đeo lưng"}],"examples":[{"en":"I packed my lunch and jacket in a rucksack.","vi":"Tôi đã nhét bữa trưa và áo khoác vào một chiếc ba lô.","audioKind":"ex"},{"en":"Travellers carrying only a rucksack can move more easily between public transport services.","vi":"Những du khách chỉ mang theo một chiếc ba lô có thể di chuyển thuận tiện hơn giữa các phương tiện giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"pack a rucksack","vi":"thu dọn ba lô"},{"en":"carry a rucksack","vi":"mang ba lô"},{"en":"hiking rucksack","vi":"ba lô đi bộ đường dài"}],"wordFamily":[],"synonyms":["backpack"],"antonyms":[],"tipVi":"Tiếng Anh - Anh thường dùng rucksack; không giới hạn chất liệu bằng vải bạt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tourist', 'en-a2-3', 'tourist', '/ˈtʊrɪst/', 'A2', 'khách du lịch; người tham quan', 'n.', 'tourism (n.), tour (n.), tour (v.)', 'Đồng nghĩa: visitor, sightseer', 'tourist thường là danh từ, trong tourist attraction đóng vai trò bổ nghĩa cho danh từ.', 'A tourist asked me how to reach the castle.', NULL, 'Một khách du lịch đã hỏi tôi đường đi đến lâu đài.', '{"wordId":"tourist","ukIpa":"/ˈtʊərɪst/","usIpa":"/ˈtʊrɪst/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"Someone who visits places for pleasure rather than work","vi":"khách du lịch; người tham quan"}],"examples":[{"en":"A tourist asked me how to reach the castle.","vi":"Một khách du lịch đã hỏi tôi đường đi đến lâu đài.","audioKind":"ex"},{"en":"Large numbers of tourists support local businesses but can also place pressure on public transport.","vi":"Đông đảo du khách hỗ trợ các doanh nghiệp địa phương nhưng đồng thời cũng có thể gây áp lực lên hệ thống giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"tourist attraction","vi":"điểm thu hút khách du lịch"},{"en":"tourist destination","vi":"điểm đến du lịch"},{"en":"tourist information","vi":"thông tin du lịch"},{"en":"overseas tourists","vi":"khách du lịch quốc tế"}],"wordFamily":["tourism (n.)","tour (n.)","tour (v.)"],"synonyms":["visitor","sightseer"],"antonyms":[],"tipVi":"tourist thường là danh từ, trong tourist attraction đóng vai trò bổ nghĩa cho danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_check-out', 'en-a2-3', 'check-out', '/ˈtʃek aʊt/', 'A2', 'thủ tục trả phòng; việc thanh toán và rời khách sạn; thời điểm trả phòng muộn nhất', 'n.', 'check out (v.)', 'Trái nghĩa: check-in', 'Danh từ cũng có thể viết liền thành checkout; dạng động từ là check out.', 'We left our bags at reception after check-out.', NULL, 'Chúng tôi đã gửi hành lý ở quầy lễ tân sau khi làm thủ tục trả phòng.', '{"wordId":"check-out","ukIpa":"/ˈtʃek aʊt/","usIpa":"/ˈtʃek aʊt/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"The process of paying and leaving a hotel","vi":"thủ tục trả phòng; việc thanh toán và rời khách sạn"},{"pos":"n.","en":"The latest time guests must leave their hotel rooms","vi":"thời điểm trả phòng muộn nhất"}],"examples":[{"en":"We left our bags at reception after check-out.","vi":"Chúng tôi đã gửi hành lý ở quầy lễ tân sau khi làm thủ tục trả phòng.","audioKind":"ex"},{"en":"Flexible check-out times can improve the travel experience for families with young children.","vi":"Thời gian trả phòng linh hoạt có thể cải thiện trải nghiệm du lịch cho các gia đình có con nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"late check-out","vi":"trả phòng muộn"},{"en":"check-out time","vi":"giờ trả phòng"},{"en":"express check-out","vi":"trả phòng nhanh"}],"wordFamily":["check out (v.)"],"synonyms":[],"antonyms":["check-in"],"tipVi":"Danh từ cũng có thể viết liền thành checkout; dạng động từ là check out.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_swiss', 'en-a2-3', 'Swiss', '/swɪs/', 'A2', 'thuộc Thụy Sĩ; thuộc người hoặc văn hóa Thụy Sĩ; người Thụy Sĩ (chỉ chung một nhóm người)', 'adj.', 'Switzerland (n.)', NULL, 'Chữ cái đầu tiên phải viết hoa; the Swiss chỉ chung người Thụy Sĩ và không thêm s ở cuối.', 'We enjoyed Swiss cheese during our picnic by the lake.', NULL, 'Chúng tôi đã thưởng thức phô mai Thụy Sĩ trong buổi dã ngoại bên hồ.', '{"wordId":"swiss","ukIpa":"/swɪs/","usIpa":"/swɪs/","cefr":"A2","topic":"travel","senses":[{"pos":"adj.","en":"Relating to Switzerland, its people, or their culture.","vi":"thuộc Thụy Sĩ; thuộc người hoặc văn hóa Thụy Sĩ"},{"pos":"n.","en":"The people of Switzerland, considered as a group.","vi":"người Thụy Sĩ (chỉ chung một nhóm người)"}],"examples":[{"en":"We enjoyed Swiss cheese during our picnic by the lake.","vi":"Chúng tôi đã thưởng thức phô mai Thụy Sĩ trong buổi dã ngoại bên hồ.","audioKind":"ex"},{"en":"Swiss railways demonstrate how reliable public transport can connect remote mountain communities and support sustainable tourism.","vi":"Hệ thống đường sắt Thụy Sĩ minh chứng cho thấy giao thông công cộng đáng tin cậy có thể kết nối các cộng đồng miền núi hẻo lánh và hỗ trợ du lịch bền vững như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"Swiss cheese","vi":"phô mai Thụy Sĩ"},{"en":"Swiss Alps","vi":"dãy Alps Thụy Sĩ"},{"en":"Swiss watches","vi":"đồng hồ Thụy Sĩ"}],"wordFamily":["Switzerland (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái đầu tiên phải viết hoa; the Swiss chỉ chung người Thụy Sĩ và không thêm s ở cuối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_motorcycle', 'en-a2-3', 'motorcycle', '/ˈmoʊtərsaɪkəl/', 'A2', 'xe máy; xe mô tô; đi xe máy; lái xe máy', 'n.', 'motorcyclist (n.), motorcycling (n.)', 'Đồng nghĩa: motorbike', 'Đi xe máy dùng động từ ride, thông thường không dùng drive.', 'He parked his motorcycle beside the garden gate.', NULL, 'Anh ấy đỗ chiếc xe máy cạnh cổng vườn.', '{"wordId":"motorcycle","ukIpa":"/ˈməʊtəsaɪkəl/","usIpa":"/ˈmoʊtərsaɪkəl/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A motor vehicle with two wheels, usually for one or two.","vi":"xe máy; xe mô tô"},{"pos":"v.","en":"To travel by motorcycle.","vi":"đi xe máy; lái xe máy"}],"examples":[{"en":"He parked his motorcycle beside the garden gate.","vi":"Anh ấy đỗ chiếc xe máy cạnh cổng vườn.","audioKind":"ex"},{"en":"Although motorcycles require less parking space than cars, riders are more exposed to injury in road accidents.","vi":"Mặc dù xe máy chiếm ít không gian đỗ xe hơn ô tô, nhưng người lái xe máy lại dễ gặp chấn thương hơn trong các vụ tai nạn giao thông.","audioKind":"ex2"}],"collocations":[{"en":"ride a motorcycle","vi":"lái xe máy"},{"en":"motorcycle helmet","vi":"mũ bảo hiểm xe máy"},{"en":"motorcycle licence","vi":"bằng lái xe máy"}],"wordFamily":["motorcyclist (n.)","motorcycling (n.)"],"synonyms":["motorbike"],"antonyms":[],"tipVi":"Đi xe máy dùng động từ ride, thông thường không dùng drive.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reception', 'en-a2-3', 'reception', '/rɪˈsepʃən/', 'A2', 'quầy lễ tân; bộ phận tiếp đón; buổi tiệc chiêu đãi; lễ tân; khả năng bắt sóng; sự đón nhận; phản ứng', 'n.', 'receptionist (n.), receive (v.), receptive (adj.)', NULL, 'Trong tiếng Anh Anh, người ta thường dùng cụm at reception để chỉ vị trí tại quầy lễ tân.', 'Please leave your room key at reception before breakfast.', NULL, 'Xin vui lòng để chìa khóa phòng của bạn tại quầy lễ tân trước bữa sáng.', '{"wordId":"reception","ukIpa":"/rɪˈsepʃən/","usIpa":"/rɪˈsepʃən/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"the area where visitors are welcomed and given information","vi":"quầy lễ tân; bộ phận tiếp đón"},{"pos":"n.","en":"a formal social event held to welcome or celebrate someone","vi":"buổi tiệc chiêu đãi; lễ tân"},{"pos":"n.","en":"how well signals are received, or how people respond","vi":"khả năng bắt sóng; sự đón nhận; phản ứng"}],"examples":[{"en":"Please leave your room key at reception before breakfast.","vi":"Xin vui lòng để chìa khóa phòng của bạn tại quầy lễ tân trước bữa sáng.","audioKind":"ex"},{"en":"The proposal received a positive reception from local residents because it addressed their concerns about road safety.","vi":"Đề xuất này nhận được phản ứng tích cực từ cư dân địa phương vì nó giải quyết được những lo ngại của họ về an toàn giao thông.","audioKind":"ex2"}],"collocations":[{"en":"reception desk","vi":"bàn tiếp tân"},{"en":"wedding reception","vi":"tiệc cưới"},{"en":"poor reception","vi":"sóng kém; bắt sóng kém"},{"en":"warm reception","vi":"sự đón tiếp nồng nhiệt"}],"wordFamily":["receptionist (n.)","receive (v.)","receptive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh Anh, người ta thường dùng cụm at reception để chỉ vị trí tại quầy lễ tân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_foreign', 'en-a2-3', 'foreign', '/ˈfɔːrən/', 'A2', 'thuộc về nước ngoài; ngoại quốc; ngoại lai; lạ; xa lạ; không quen thuộc', 'adj.', 'foreigner (n.)', 'Đồng nghĩa: overseas · Trái nghĩa: domestic', 'Cấu trúc foreign to có thể mang nghĩa xa lạ đối với ai đó, hoặc không phù hợp với điều gì.', 'My sister enjoys learning foreign languages in her spare time.', NULL, 'Chị tôi thích học ngoại ngữ vào thời gian rảnh.', '{"wordId":"foreign","ukIpa":"/ˈfɒrən/","usIpa":"/ˈfɔːrən/","cefr":"A2","topic":"travel","senses":[{"pos":"adj.","en":"From or relating to a country other than your own.","vi":"thuộc về nước ngoài; ngoại quốc"},{"pos":"adj.","en":"Present where it does not naturally belong.","vi":"ngoại lai; lạ"},{"pos":"adj.","en":"Unfamiliar to someone or inconsistent with something.","vi":"xa lạ; không quen thuộc"}],"examples":[{"en":"My sister enjoys learning foreign languages in her spare time.","vi":"Chị tôi thích học ngoại ngữ vào thời gian rảnh.","audioKind":"ex"},{"en":"Foreign investment can create jobs, but governments should ensure that local communities also benefit from economic growth.","vi":"Đầu tư nước ngoài có thể tạo ra việc làm, nhưng chính phủ nên đảm bảo rằng cộng đồng địa phương cũng được hưởng lợi từ tăng trưởng kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"foreign language","vi":"ngoại ngữ"},{"en":"foreign investment","vi":"đầu tư nước ngoài"},{"en":"foreign policy","vi":"chính sách đối ngoại"},{"en":"foreign body","vi":"dị vật"}],"wordFamily":["foreigner (n.)"],"synonyms":["overseas"],"antonyms":["domestic"],"tipVi":"Cấu trúc foreign to có thể mang nghĩa xa lạ đối với ai đó, hoặc không phù hợp với điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_motorway', 'en-a2-3', 'motorway', '/ˈmoʊtərweɪ/', 'A2', 'đường cao tốc', 'n.', NULL, 'Đồng nghĩa: freeway, expressway', 'Chủ yếu dùng trong tiếng Anh-Anh; tiếng Anh-Mỹ thường dùng freeway.', 'We left the motorway and stopped for lunch.', NULL, 'Chúng tôi đã rời khỏi đường cao tốc và dừng lại để ăn trưa.', '{"wordId":"motorway","ukIpa":"/ˈməʊtəweɪ/","usIpa":"/ˈmoʊtərweɪ/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"a wide road designed for fast travel over long distances","vi":"đường cao tốc"}],"examples":[{"en":"We left the motorway and stopped for lunch.","vi":"Chúng tôi đã rời khỏi đường cao tốc và dừng lại để ăn trưa.","audioKind":"ex"},{"en":"Building a new motorway may reduce journey times, but it can also damage nearby wildlife habitats.","vi":"Việc xây dựng một con đường cao tốc mới có thể rút ngắn thời gian di chuyển, nhưng nó cũng có thể tàn phá môi trường sống của động vật hoang dã ở gần đó.","audioKind":"ex2"}],"collocations":[{"en":"motorway junction","vi":"nút giao thông cao tốc"},{"en":"motorway services","vi":"trạm dịch vụ cao tốc"},{"en":"join the motorway","vi":"nhập vào đường cao tốc"}],"wordFamily":[],"synonyms":["freeway","expressway"],"antonyms":[],"tipVi":"Chủ yếu dùng trong tiếng Anh-Anh; tiếng Anh-Mỹ thường dùng freeway.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_european', 'en-a2-3', 'European', '/ˌjʊrəˈpiːən/', 'A2', 'thuộc châu âu; người châu âu', 'adj.', 'Europe (n.)', NULL, 'Viết hoa chữ cái đầu; dùng mạo từ a thay vì an, và không đồng nghĩa với Liên minh Châu Âu.', 'We explored several European cities during our summer holiday.', NULL, 'Chúng tôi đã khám phá vài thành phố ở châu Âu trong kỳ nghỉ hè.', '{"wordId":"european","ukIpa":"/ˌjʊərəˈpiːən/","usIpa":"/ˌjʊrəˈpiːən/","cefr":"A2","topic":"travel","senses":[{"pos":"adj.","en":"Relating to Europe or its people.","vi":"thuộc châu âu; người châu âu"},{"pos":"n.","en":"A person from Europe.","vi":"người châu âu"}],"examples":[{"en":"We explored several European cities during our summer holiday.","vi":"Chúng tôi đã khám phá vài thành phố ở châu Âu trong kỳ nghỉ hè.","audioKind":"ex"},{"en":"Many European countries have invested in railway networks to reduce dependence on short domestic flights.","vi":"Nhiều quốc gia châu Âu đã đầu tư vào hệ thống mạng lưới đường sắt nhằm giảm sự phụ thuộc vào các chuyến bay nội địa ngắn.","audioKind":"ex2"}],"collocations":[{"en":"European countries","vi":"các quốc gia châu Âu"},{"en":"European culture","vi":"văn hóa châu Âu"},{"en":"the European Union","vi":"Liên minh Châu Âu"}],"wordFamily":["Europe (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Viết hoa chữ cái đầu; dùng mạo từ a thay vì an, và không đồng nghĩa với Liên minh Châu Âu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mile', 'en-a2-3', 'mile', '/maɪl/', 'A2', 'dặm (đơn vị đo khoảng cách)', 'n.', 'mileage (n.)', NULL, 'Mile là đơn vị đo khoảng cách; là danh từ đếm được, dạng số nhiều thêm s.', 'The nearest swimming pool is only a mile away.', NULL, 'Hồ bơi gần nhất chỉ cách đó vỏn vẹn một dặm.', '{"wordId":"mile","ukIpa":"/maɪl/","usIpa":"/maɪl/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A unit of distance equal to approximately 1.61 kilometres.","vi":"dặm (đơn vị đo khoảng cách)"}],"examples":[{"en":"The nearest swimming pool is only a mile away.","vi":"Hồ bơi gần nhất chỉ cách đó vỏn vẹn một dặm.","audioKind":"ex"},{"en":"Replacing short car journeys with walking even one mile could improve public health and reduce emissions.","vi":"Việc thay thế những chuyến đi xe ô tô ngắn bằng việc đi bộ dù chỉ một dặm cũng có thể cải thiện sức khỏe cộng đồng và giảm lượng khí thải.","audioKind":"ex2"}],"collocations":[{"en":"a mile away","vi":"cách một dặm"},{"en":"square mile","vi":"dặm vuông"},{"en":"miles per hour","vi":"dặm trên giờ"}],"wordFamily":["mileage (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Mile là đơn vị đo khoảng cách; là danh từ đếm được, dạng số nhiều thêm s.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_petrol', 'en-a2-3', 'petrol', '/ˈpetrəl/', 'A2', 'xăng', 'n.', NULL, 'Đồng nghĩa: gasoline', 'Là danh từ không đếm được; tiếng Anh - Anh dùng petrol, tiếng Anh - Mỹ dùng gasoline hoặc gas.', 'We stopped for petrol before driving into the mountains.', NULL, 'Chúng tôi ghé vào đổ xăng trước khi lái xe lên núi.', '{"wordId":"petrol","ukIpa":"/ˈpetrəl/","usIpa":"/ˈpetrəl/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"a liquid fuel used in cars and other engines","vi":"xăng"}],"examples":[{"en":"We stopped for petrol before driving into the mountains.","vi":"Chúng tôi ghé vào đổ xăng trước khi lái xe lên núi.","audioKind":"ex"},{"en":"Higher petrol prices may encourage commuters to use public transport rather than drive to work.","vi":"Giá xăng cao hơn có thể khuyến khích những người đi làm xa sử dụng phương tiện công cộng thay vì lái xe đi làm.","audioKind":"ex2"}],"collocations":[{"en":"petrol station","vi":"cây xăng"},{"en":"unleaded petrol","vi":"xăng không chì"},{"en":"petrol prices","vi":"giá xăng"},{"en":"run out of petrol","vi":"hết xăng"}],"wordFamily":[],"synonyms":["gasoline"],"antonyms":[],"tipVi":"Là danh từ không đếm được; tiếng Anh - Anh dùng petrol, tiếng Anh - Mỹ dùng gasoline hoặc gas.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_guide', 'en-a2-3', 'guide', '/ɡaɪd/', 'A2', 'hướng dẫn viên; người dẫn đường; sách hướng dẫn; tài liệu chỉ dẫn; hướng dẫn; dìu dắt', 'n.', 'guidance (n.), guided (adj.), guidebook (n.)', NULL, 'Hướng dẫn dùng a guide to; hướng dẫn ai đó hoàn thành dùng guide someone through.', 'Our guide led us through the narrow market streets.', NULL, 'Hướng dẫn viên của chúng tôi dẫn chúng tôi đi qua những con phố chợ chật hẹp.', '{"wordId":"guide","ukIpa":"/ɡaɪd/","usIpa":"/ɡaɪd/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"someone who leads people and explains places they visit","vi":"hướng dẫn viên; người dẫn đường"},{"pos":"n.","en":"a book or resource giving useful information or instructions","vi":"sách hướng dẫn; tài liệu chỉ dẫn"},{"pos":"v.","en":"to show someone the way or help them decide","vi":"hướng dẫn; dìu dắt"}],"examples":[{"en":"Our guide led us through the narrow market streets.","vi":"Hướng dẫn viên của chúng tôi dẫn chúng tôi đi qua những con phố chợ chật hẹp.","audioKind":"ex"},{"en":"Teachers should guide students towards reliable sources rather than simply provide answers to every question.","vi":"Giáo viên nên hướng dẫn học sinh tìm đến các nguồn tin cậy thay vì chỉ đơn thuần cung cấp câu trả lời cho mọi câu hỏi.","audioKind":"ex2"}],"collocations":[{"en":"tour guide","vi":"hướng dẫn viên du lịch"},{"en":"a guide to","vi":"hướng dẫn về..."},{"en":"guide someone through","vi":"hướng dẫn ai đó vượt qua/hoàn thành"},{"en":"guided tour","vi":"chuyến tham quan có hướng dẫn"}],"wordFamily":["guidance (n.)","guided (adj.)","guidebook (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Hướng dẫn dùng a guide to; hướng dẫn ai đó hoàn thành dùng guide someone through.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_3_1', 'en-a2-3', 'Cách dùng “northeast” (n.) — phía đông bắc; miền đông bắc', 'in the northeast  ·  head northeast  ·  the northeast coast', 'Dùng "northeast of" để chỉ vị trí nằm ở phía đông bắc của nơi nào đó; tiếng Anh Anh cũng viết là "north-east".', 'Họ từ (Word Family): northeastern (adj.) | Trái nghĩa: southwest', '[{"hanzi":"The storm is moving northeast towards the coastal villages.","pinyin":"","meaning":"Cơn bão đang di chuyển về hướng đông bắc tiến vào các ngôi làng ven biển."},{"hanzi":"Investment in rail connections could improve access to employment for communities in the northeast of the country.","pinyin":"","meaning":"Việc đầu tư vào các tuyến đường sắt có thể cải thiện khả năng tiếp cận việc làm cho người dân ở vùng đông bắc của đất nước."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_3_2', 'en-a2-3', 'Cách dùng “tour” (n.) — chuyến tham quan; cuộc đi vòng quanh', 'guided tour  ·  walking tour  ·  concert tour', 'tour nhấn mạnh hoạt động tham quan hoặc lịch trình nhiều điểm dừng; trip mang nghĩa chung cho một chuyến đi.', 'Họ từ (Word Family): tourism (n.), tourist (n.), touring (adj.)', '[{"hanzi":"We took a guided tour of the old castle.","pinyin":"","meaning":"Chúng tôi đã tham gia một chuyến tham quan có hướng dẫn viên tại lâu đài cổ."},{"hanzi":"Organized tours can introduce visitors to local traditions while providing reliable income for community guides.","pinyin":"","meaning":"Các chuyến tham quan được tổ chức bài bản có thể giới thiệu các truyền thống địa phương cho du khách đồng thời mang lại nguồn thu nhập ổn định cho hướng dẫn viên cộng đồng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_3_3', 'en-a2-3', 'Cách dùng “driving” (n.) — việc lái xe; kỹ năng lái xe', 'driving test  ·  driving licence  ·  driving force', 'driving force có nghĩa là động lực thúc đẩy; driving cũng có thể đóng vai trò là phân từ hiện tại của drive.', 'Họ từ (Word Family): drive (v.), driver (n.)', '[{"hanzi":"Her careful driving made the mountain journey feel safe.","pinyin":"","meaning":"Cách lái xe cẩn thận của cô ấy giúp chuyến hành trình qua vùng núi trở nên an toàn."},{"hanzi":"Technological innovation is a driving force behind economic growth, although its benefits are not always shared equally.","pinyin":"","meaning":"Đổi mới công nghệ là động lực thúc đẩy tăng trưởng kinh tế, mặc dù lợi ích từ đó không phải lúc nào cũng được phân chia công bằng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_3_4', 'en-a2-3', 'Cách dùng “along” (prep.) — dọc theo; theo', 'along the coast  ·  come along  ·  bring someone along', 'along chỉ hành động di chuyển dọc theo chiều dài; across nhấn mạnh việc băng qua từ bên này sang bên kia.', NULL, '[{"hanzi":"We walked along the river and watched the ducks.","pinyin":"","meaning":"Chúng tôi đi dạo dọc bờ sông và ngắm nhìn những con vịt."},{"hanzi":"Planting trees along busy roads can provide shade for pedestrians and improve the appearance of urban areas.","pinyin":"","meaning":"Việc trồng cây dọc các con đường bận rộn có thể che bóng mát cho người đi bộ và cải thiện diện mạo khu đô thị."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_3_1', 'en-a2-3', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_3_1_1', 'ten_a2_3_1', 'along', 'We walked along the river and watched the ducks.', 'We walked along the river and watched the ducks.', '/əˈlɔːŋ/', 'Chúng tôi đi dạo dọc bờ sông và ngắm nhìn những con vịt.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_3_1_2', 'ten_a2_3_1', 'distance', 'The distance from our house to school is quite short.', 'The distance from our house to school is quite short.', '/ˈdɪstəns/', 'Khoảng cách từ nhà chúng tôi đến trường khá ngắn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_3_1_3', 'ten_a2_3_1', 'vacation', 'We spent our summer vacation camping beside a lake.', 'We spent our summer vacation camping beside a lake.', '/veɪˈkeɪʃən/', 'Chúng tôi đã dành kỳ nghỉ hè để cắm trại bên bờ hồ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_3_1_4', 'ten_a2_3_1', 'traveler', 'A tired traveler asked me where the station was.', 'A tired traveler asked me where the station was.', '/ˈtrævələr/', 'Một vị lữ khách mệt mỏi đã hỏi tôi ga tàu nằm ở đâu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_3_1_5', 'ten_a2_3_1', 'lost', 'We got lost while walking through the old town.', 'We got lost while walking through the old town.', '/lɔːst/', 'Chúng tôi đã bị lạc đường khi đang đi bộ qua khu phố cổ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_3_1_6', 'ten_a2_3_1', 'tour', 'We took a guided tour of the old castle.', 'We took a guided tour of the old castle.', '/tʊr/', 'Chúng tôi đã tham gia một chuyến tham quan có hướng dẫn viên tại lâu đài cổ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_3_1_7', 'ten_a2_3_1', 'path', 'We followed a narrow path down to the beach.', 'We followed a narrow path down to the beach.', '/pæθ/', 'Chúng tôi đi theo một con đường mòn nhỏ dẫn xuống bãi biển.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_3_1_8', 'ten_a2_3_1', 'northeast', 'The storm is moving northeast towards the coastal villages.', 'The storm is moving northeast towards the coastal villages.', '/ˌnɔːrθˈiːst/', 'Cơn bão đang di chuyển về hướng đông bắc tiến vào các ngôi làng ven biển.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_3_1_1', 'en-a2-3', 'ten_a2_3_1', 'listening', 'listening', 'We walked along the river and watched the ducks.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đi dạo dọc bờ sông và ngắm nhìn những con vịt.","Cơn bão đang di chuyển về hướng đông bắc tiến vào các ngôi làng ven biển.","Chúng tôi đứng chờ trên sân ga khi đoàn tàu đang tiến vào.","Chúng tôi đã tham gia một chuyến tham quan có hướng dẫn viên tại lâu đài cổ."]'::jsonb, 0, 'We walked along the river and watched the ducks. → Chúng tôi đi dạo dọc bờ sông và ngắm nhìn những con vịt.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_3_1_2', 'en-a2-3', 'ten_a2_3_1', 'listening', 'listening', 'The distance from our house to school is quite short.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đứng chờ trên sân ga khi đoàn tàu đang tiến vào.","Tôi đã nhét bữa trưa và áo khoác vào một chiếc ba lô.","Khoảng cách từ nhà chúng tôi đến trường khá ngắn.","Một vị lữ khách mệt mỏi đã hỏi tôi ga tàu nằm ở đâu."]'::jsonb, 2, 'The distance from our house to school is quite short. → Khoảng cách từ nhà chúng tôi đến trường khá ngắn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_3_1_3', 'en-a2-3', 'ten_a2_3_1', 'listening', 'listening', 'We spent our summer vacation camping beside a lake.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã dành kỳ nghỉ hè để cắm trại bên bờ hồ.","Chúng tôi đã bị lạc đường khi đang đi bộ qua khu phố cổ.","Cách lái xe cẩn thận của cô ấy giúp chuyến hành trình qua vùng núi trở nên an toàn.","Chị tôi thích học ngoại ngữ vào thời gian rảnh."]'::jsonb, 0, 'We spent our summer vacation camping beside a lake. → Chúng tôi đã dành kỳ nghỉ hè để cắm trại bên bờ hồ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_3_2', 'en-a2-3', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_3_2_1', 'ten_a2_3_2', 'along', 'Planting trees along busy roads can provide shade for pedestrians and improve the appearance of urban areas.', 'Planting trees along busy roads can provide shade for pedestrians and improve the appearance of urban areas.', '/əˈlɔːŋ/', 'Việc trồng cây dọc các con đường bận rộn có thể che bóng mát cho người đi bộ và cải thiện diện mạo khu đô thị.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_3_2_2', 'ten_a2_3_2', 'distance', 'Reducing the distance between residential areas and workplaces could lower transport emissions and improve urban quality of life.', 'Reducing the distance between residential areas and workplaces could lower transport emissions and improve urban quality of life.', '/ˈdɪstəns/', 'Việc thu hẹp khoảng cách giữa các khu dân cư và nơi làm việc có thể làm giảm lượng khí thải giao thông và cải thiện chất lượng cuộc sống đô thị.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_3_2_3', 'ten_a2_3_2', 'vacation', 'Taking a regular vacation may improve employees'' mental health and help them return to work with greater motivation.', 'Taking a regular vacation may improve employees'' mental health and help them return to work with greater motivation.', '/veɪˈkeɪʃən/', 'Việc duy trì kỳ nghỉ đều đặn có thể cải thiện sức khỏe tinh thần của nhân viên và giúp họ quay lại làm việc với động lực lớn hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_3_2_4', 'ten_a2_3_2', 'traveler', 'Every traveler can support local communities by choosing accommodation and services owned by residents.', 'Every traveler can support local communities by choosing accommodation and services owned by residents.', '/ˈtrævələr/', 'Mỗi du khách đều có thể hỗ trợ cộng đồng địa phương bằng cách chọn các cơ sở lưu trú và dịch vụ do chính cư dân bản địa sở hữu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_3_2_5', 'ten_a2_3_2', 'lost', 'Without clear guidance, new university students may feel lost when choosing courses that affect their future careers.', 'Without clear guidance, new university students may feel lost when choosing courses that affect their future careers.', '/lɔːst/', 'Nếu thiếu sự định hướng rõ ràng, tân sinh viên đại học có thể cảm thấy bối rối khi chọn các môn học ảnh hưởng đến sự nghiệp tương lai của họ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_3_2_6', 'ten_a2_3_2', 'tour', 'Organized tours can introduce visitors to local traditions while providing reliable income for community guides.', 'Organized tours can introduce visitors to local traditions while providing reliable income for community guides.', '/tʊr/', 'Các chuyến tham quan được tổ chức bài bản có thể giới thiệu các truyền thống địa phương cho du khách đồng thời mang lại nguồn thu nhập ổn định cho hướng dẫn viên cộng đồng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_3_2_1', 'en-a2-3', 'ten_a2_3_2', 'listening', 'listening', 'Planting trees along busy roads can provide shade for pedestrians and improve the appearance of urban areas.', NULL, 'Trong câu vừa nghe, từ “along” mang nghĩa nào sau đây?', '["ngành du lịch; du lịch","dọc theo; theo","bộ phận; khoa; ban","về phía trước; hướng về tương lai"]'::jsonb, 1, '“along” (/əˈlɔːŋ/): dọc theo; theo. Câu đầy đủ: Planting trees along busy roads can provide shade for pedestrians and improve the appearance of urban areas.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_3_2_2', 'en-a2-3', 'ten_a2_3_2', 'listening', 'listening', 'Reducing the distance between residential areas and workplaces could lower transport emissions and improve urban quality of life.', NULL, 'Trong câu vừa nghe, từ “distance” mang nghĩa nào sau đây?', '["khoảng cách; quãng đường","nhẫn; vật hình vòng tròn","ý kiến đề xuất; lời khuyên","thế vận hội Olympic"]'::jsonb, 0, '“distance” (/ˈdɪstəns/): khoảng cách; quãng đường. Câu đầy đủ: Reducing the distance between residential areas and workplaces could lower transport emissions and improve urban quality of life.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
