INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_1', 'en-a2-3', NULL, 'comprehensive_test', 'listening', 'along', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["dọc theo; theo","vị; vị giác","keo, hồ dán","ở dưới lòng đất; ngầm; hoạt động bí mật"]'::jsonb, 0, 'along (/əˈlɔːŋ/) → dọc theo; theo; về phía trước; cùng nhau; đi kèm', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_2', 'en-a2-3', NULL, 'comprehensive_test', 'listening', 'The distance from our house to school is quite short.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đóng cửa sân vườn lại để nhốt con chó ở bên trong.","Anh ấy đỗ chiếc xe máy cạnh cổng vườn.","Chúng tôi đã dành kỳ nghỉ hè để cắm trại bên bờ hồ.","Khoảng cách từ nhà chúng tôi đến trường khá ngắn."]'::jsonb, 3, 'The distance from our house to school is quite short. → Khoảng cách từ nhà chúng tôi đến trường khá ngắn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_3', 'en-a2-3', NULL, 'comprehensive_test', 'listening', 'vacation', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vui vẻ; hạnh phúc","kỳ nghỉ; thời gian nghỉ ngơi, du lịch","sự đau đớn; cơn đau","cơn đau đầu"]'::jsonb, 1, 'vacation (/veɪˈkeɪʃən/) → kỳ nghỉ; thời gian nghỉ ngơi, du lịch; đi nghỉ mát; đi du lịch xa nhà', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_4', 'en-a2-3', NULL, 'comprehensive_test', 'listening', 'A tired traveler asked me where the station was.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một vị lữ khách mệt mỏi đã hỏi tôi ga tàu nằm ở đâu.","Chúng tôi đã rời khỏi đường cao tốc và dừng lại để ăn trưa.","Chị tôi thích học ngoại ngữ vào thời gian rảnh.","Chúng tôi đi dạo dọc bờ sông và ngắm nhìn những con vịt."]'::jsonb, 0, 'A tired traveler asked me where the station was. → Một vị lữ khách mệt mỏi đã hỏi tôi ga tàu nằm ở đâu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_5', 'en-a2-3', NULL, 'comprehensive_test', 'listening', 'lost', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ngu ngốc; khờ khạo; kém suy nghĩ","lạc đường; bị thất lạc","vừa vặn; thích hợp; vừa","súng (cầm tay hoặc đại bác)"]'::jsonb, 1, 'lost (/lɔːst/) → lạc đường; bị thất lạc; bối rối; lúng túng; không biết phải làm gì; đã mất; đã thua (dạng quá khứ và phân từ hai của lose)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_6', 'en-a2-3', NULL, 'comprehensive_test', 'listening', 'We took a guided tour of the old castle.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã gửi hành lý ở quầy lễ tân sau khi làm thủ tục trả phòng.","Tôi đã nhét bữa trưa và áo khoác vào một chiếc ba lô.","Chúng tôi ghé vào đổ xăng trước khi lái xe lên núi.","Chúng tôi đã tham gia một chuyến tham quan có hướng dẫn viên tại lâu đài cổ."]'::jsonb, 3, 'We took a guided tour of the old castle. → Chúng tôi đã tham gia một chuyến tham quan có hướng dẫn viên tại lâu đài cổ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_7', 'en-a2-3', NULL, 'comprehensive_test', 'listening', 'path', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đường sắt; hệ thống đường sắt","đường mòn; lối đi nhỏ","cộng sự; đối tác; người cùng chơi","nữ vương; vương hậu"]'::jsonb, 1, 'path (/pæθ/) → đường mòn; lối đi nhỏ; đường đi; quỹ đạo; con đường; phương hướng', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_8', 'en-a2-3', NULL, 'comprehensive_test', 'listening', 'The storm is moving northeast towards the coastal villages.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cơn bão đang di chuyển về hướng đông bắc tiến vào các ngôi làng ven biển.","Hồ bơi gần nhất chỉ cách đó vỏn vẹn một dặm.","Khoảng cách từ nhà chúng tôi đến trường khá ngắn.","Một vị lữ khách mệt mỏi đã hỏi tôi ga tàu nằm ở đâu."]'::jsonb, 0, 'The storm is moving northeast towards the coastal villages. → Cơn bão đang di chuyển về hướng đông bắc tiến vào các ngôi làng ven biển.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_9', 'en-a2-3', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Unable to find the way, or unable to be found.”?', '["lost","path","traveler","mile"]'::jsonb, 0, 'lost (/lɔːst/) → lạc đường; bị thất lạc', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_10', 'en-a2-3', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A journey visiting several places, or a guided visit somewhere.”?', '["tour","motorway","guide","driving"]'::jsonb, 0, 'tour (/tʊr/) → chuyến tham quan; cuộc đi vòng quanh', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_11', 'en-a2-3', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A narrow track for people to walk along.”?', '["driving","reception","path","along"]'::jsonb, 2, 'path (/pæθ/) → đường mòn; lối đi nhỏ', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_12', 'en-a2-3', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The direction between north and east, or an area''s northeastern part.”?', '["lost","northeast","wheel","guide"]'::jsonb, 1, 'northeast (/ˌnɔːrθˈiːst/) → phía đông bắc; miền đông bắc', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
