INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_18', 'en-a2-3', NULL, 'comprehensive_test', 'reading', NULL, 'Planting trees along busy roads can provide shade for pedestrians and improve the appearance of urban areas.', 'Dựa vào câu trên, từ “along” có nghĩa phù hợp nhất là gì?', '["to; lớn tiếng; ồn ào","thẻ lên máy bay; giấy lên máy bay","tránh; ngăn chặn","dọc theo; theo"]'::jsonb, 3, 'along: dọc theo; theo; về phía trước; cùng nhau; đi kèm. Dịch cả câu: Việc trồng cây dọc các con đường bận rộn có thể che bóng mát cho người đi bộ và cải thiện diện mạo khu đô thị.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_19', 'en-a2-3', NULL, 'comprehensive_test', 'reading', NULL, 'Reducing the distance between residential areas and workplaces could lower transport emissions and improve urban quality of life.', 'Dựa vào câu trên, từ “distance” có nghĩa phù hợp nhất là gì?', '["khu phố; vùng lân cận","lâu đài","khoảng cách; quãng đường","chuột túi; con kangaroo"]'::jsonb, 2, 'distance: khoảng cách; quãng đường; sự xa cách; khoảng cách tình cảm; giữ khoảng cách; tạo khoảng cách; tách biệt. Dịch cả câu: Việc thu hẹp khoảng cách giữa các khu dân cư và nơi làm việc có thể làm giảm lượng khí thải giao thông và cải thiện chất lượng cuộc sống đô thị.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_20', 'en-a2-3', NULL, 'comprehensive_test', 'reading', NULL, 'Taking a regular vacation may improve employees'' mental health and help them return to work with greater motivation.', 'Dựa vào câu trên, từ “vacation” có nghĩa phù hợp nhất là gì?', '["cháy; đốt cháy","kỳ nghỉ; thời gian nghỉ ngơi, du lịch","thuộc về hoặc liên quan đến châu Á và người châu Á","ngựa vằn"]'::jsonb, 1, 'vacation: kỳ nghỉ; thời gian nghỉ ngơi, du lịch; đi nghỉ mát; đi du lịch xa nhà. Dịch cả câu: Việc duy trì kỳ nghỉ đều đặn có thể cải thiện sức khỏe tinh thần của nhân viên và giúp họ quay lại làm việc với động lực lớn hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_21', 'en-a2-3', NULL, 'comprehensive_test', 'reading', NULL, 'Every traveler can support local communities by choosing accommodation and services owned by residents.', 'Dựa vào câu trên, từ “traveler” có nghĩa phù hợp nhất là gì?', '["động cơ; máy","người đi du lịch; hành khách; lữ khách","bữa ăn nhẹ; đồ ăn vặt","quà; quà tặng"]'::jsonb, 1, 'traveler: người đi du lịch; hành khách; lữ khách. Dịch cả câu: Mỗi du khách đều có thể hỗ trợ cộng đồng địa phương bằng cách chọn các cơ sở lưu trú và dịch vụ do chính cư dân bản địa sở hữu.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_22', 'en-a2-3', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dặm (đơn vị đo khoảng cách)”', '["postcode","mile","item","stupid"]'::jsonb, 1, 'dặm (đơn vị đo khoảng cách) → mile (/maɪl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_23', 'en-a2-3', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “xăng”', '["tenth","petrol","photocopy","messy"]'::jsonb, 1, 'xăng → petrol (/ˈpetrəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_3_24', 'en-a2-3', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hướng dẫn viên; người dẫn đường”', '["popular","guide","push","closed"]'::jsonb, 1, 'hướng dẫn viên; người dẫn đường → guide (/ɡaɪd/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-4', 'en', 'Bài 4: Du lịch & Di chuyển (2) - CEFR A2', 'CEFR A2', 'A2 · Du lịch', '23 từ vựng Tiếng Anh CEFR A2 chủ đề du lịch & di chuyển kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2004, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scotland', 'en-a2-4', 'Scotland', '/ˈskɑːtlənd/', 'A2', 'Xốt-lân; Xéc-lân (Xơ-cốt-len)', 'n.', 'Scottish (adj.), Scot (n.), Scots (adj.)', NULL, 'Xơ-cốt-len là một quốc gia thuộc Vương quốc Anh; tính từ thường dùng là Scottish.', 'We explored old castles during our holiday in Scotland.', NULL, 'Chúng tôi đã khám phá những lâu đài cổ trong chuyến nghỉ dưỡng tại Xơ-cốt-len.', '{"wordId":"scotland","ukIpa":"/ˈskɒtlənd/","usIpa":"/ˈskɑːtlənd/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A country in the northern part of Great Britain.","vi":"Xốt-lân; Xéc-lân (Xơ-cốt-len)"}],"examples":[{"en":"We explored old castles during our holiday in Scotland.","vi":"Chúng tôi đã khám phá những lâu đài cổ trong chuyến nghỉ dưỡng tại Xơ-cốt-len.","audioKind":"ex"},{"en":"Scotland attracts visitors with its dramatic landscapes, while rural communities benefit from spending on accommodation and local services.","vi":"Xơ-cốt-len thu hút du khách bởi cảnh quan hùng vĩ, trong khi các cộng đồng nông thôn được hưởng lợi từ chi tiêu cho chỗ ở và dịch vụ địa phương.","audioKind":"ex2"}],"collocations":[{"en":"the west coast of Scotland","vi":"bờ tây Xơ-cốt-len"},{"en":"rural Scotland","vi":"vùng nông thôn Xơ-cốt-len"},{"en":"a trip to Scotland","vi":"chuyến đi đến Xơ-cốt-len"}],"wordFamily":["Scottish (adj.)","Scot (n.)","Scots (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Xơ-cốt-len là một quốc gia thuộc Vương quốc Anh; tính từ thường dùng là Scottish.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_visitor', 'en-a2-4', 'visitor', '/ˈvɪzɪtər/', 'A2', 'khách; khách tham quan; du khách', 'n.', 'visit (v.), visit (n.)', NULL, 'visitor chỉ người; visit có thể dùng làm động từ hoặc danh từ.', 'A visitor left her umbrella beside our front door.', NULL, 'Một vị khách đã để quên chiếc ô bên cạnh cửa trước nhà chúng tôi.', '{"wordId":"visitor","ukIpa":"/ˈvɪzɪtə/","usIpa":"/ˈvɪzɪtər/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"Someone who goes to see a person or place.","vi":"khách; khách tham quan; du khách"}],"examples":[{"en":"A visitor left her umbrella beside our front door.","vi":"Một vị khách đã để quên chiếc ô bên cạnh cửa trước nhà chúng tôi.","audioKind":"ex"},{"en":"The museum attracts international visitors by offering exhibitions that explore local history and culture.","vi":"Bảo tàng thu hút du khách quốc tế bằng cách cung cấp các triển lãm khám phá lịch sử và văn hóa địa phương.","audioKind":"ex2"}],"collocations":[{"en":"attract visitors","vi":"thu hút khách du lịch"},{"en":"overseas visitors","vi":"du khách quốc tế"},{"en":"visitor centre","vi":"trung tâm đón tiếp du khách"}],"wordFamily":["visit (v.)","visit (n.)"],"synonyms":[],"antonyms":[],"tipVi":"visitor chỉ người; visit có thể dùng làm động từ hoặc danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kilometer', 'en-a2-4', 'kilometer', '/kɪˈlɑːmɪtər/', 'A2', 'ki-lô-mét; cây số', 'n.', NULL, 'Đồng nghĩa: kilometre', 'Cách viết theo kiểu Mỹ; kiểu Anh là kilometre, ký hiệu km không thêm s.', 'The nearest bakery is about a kilometer from here.', NULL, 'Tiệm bánh gần nhất cách đây khoảng một cây số.', '{"wordId":"kilometer","ukIpa":"/kɪˈlɒmɪtə/","usIpa":"/kɪˈlɑːmɪtər/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"a unit of distance equal to one thousand meters","vi":"ki-lô-mét; cây số"}],"examples":[{"en":"The nearest bakery is about a kilometer from here.","vi":"Tiệm bánh gần nhất cách đây khoảng một cây số.","audioKind":"ex"},{"en":"Providing reliable public transport within a kilometer of residential areas could reduce dependence on private cars.","vi":"Việc cung cấp giao thông công cộng đáng tin cậy trong phạm vi một ki-lô-mét từ các khu dân cư có thể làm giảm sự phụ thuộc vào ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"a square kilometer","vi":"một ki-lô-mét vuông"},{"en":"kilometers per hour","vi":"ki-lô-mét trên giờ"},{"en":"a kilometer away","vi":"cách đó một ki-lô-mét"}],"wordFamily":[],"synonyms":["kilometre"],"antonyms":[],"tipVi":"Cách viết theo kiểu Mỹ; kiểu Anh là kilometre, ký hiệu km không thêm s.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_passenger', 'en-a2-4', 'passenger', '/ˈpæsɪndʒər/', 'A2', 'hành khách; khách đi xe, tàu, máy bay', 'n.', NULL, NULL, 'Chỉ người đi trên phương tiện giao thông, không bao gồm tài xế hoặc phi hành đoàn.', 'A passenger left a blue umbrella on the bus.', NULL, 'Một hành khách đã để quên chiếc ô màu xanh trên xe buýt.', '{"wordId":"passenger","ukIpa":"/ˈpæsɪndʒə/","usIpa":"/ˈpæsɪndʒər/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"Someone travelling in a vehicle without driving or operating it","vi":"hành khách; khách đi xe, tàu, máy bay"}],"examples":[{"en":"A passenger left a blue umbrella on the bus.","vi":"Một hành khách đã để quên chiếc ô màu xanh trên xe buýt.","audioKind":"ex"},{"en":"Improved rail services could increase passenger numbers and reduce reliance on private cars.","vi":"Việc cải thiện dịch vụ đường sắt có thể làm tăng lượng hành khách và giảm sự phụ thuộc vào ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"passenger train","vi":"tàu chở khách"},{"en":"passenger seat","vi":"ghế hành khách"},{"en":"passenger numbers","vi":"số lượng hành khách"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ người đi trên phương tiện giao thông, không bao gồm tài xế hoặc phi hành đoàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_direction', 'en-a2-4', 'direction', '/dəˈrekʃən/', 'A2', 'phương hướng; hướng đi; chỉ đường; hướng dẫn sử dụng; sự chỉ đạo; sự quản lý', 'n.', 'direct (v.), director (n.), directional (adj.)', NULL, 'Khi mang nghĩa là hướng dẫn đường đi hoặc chỉ dẫn cách làm, từ này thường được dùng ở số nhiều là directions.', 'The dog suddenly ran in the opposite direction.', NULL, 'Con chó đột nhiên chạy theo hướng ngược lại.', '{"wordId":"direction","ukIpa":"/dəˈrekʃən/","usIpa":"/dəˈrekʃən/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"the way something points, moves, or develops","vi":"phương hướng; hướng đi"},{"pos":"n.","en":"instructions explaining how to reach somewhere or do something","vi":"chỉ đường; hướng dẫn sử dụng"},{"pos":"n.","en":"the control or guidance of an activity or group","vi":"sự chỉ đạo; sự quản lý"}],"examples":[{"en":"The dog suddenly ran in the opposite direction.","vi":"Con chó đột nhiên chạy theo hướng ngược lại.","audioKind":"ex"},{"en":"Government investment can influence the direction of technological development by supporting research into cleaner energy sources.","vi":"Sự đầu tư của chính phủ có thể định hướng sự phát triển công nghệ bằng cách hỗ trợ nghiên cứu về các nguồn năng lượng sạch hơn.","audioKind":"ex2"}],"collocations":[{"en":"in the opposite direction","vi":"theo hướng ngược lại"},{"en":"ask for directions","vi":"hỏi đường"},{"en":"follow the directions","vi":"làm theo hướng dẫn"},{"en":"under the direction of","vi":"dưới sự chỉ đạo của"}],"wordFamily":["direct (v.)","director (n.)","directional (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa là hướng dẫn đường đi hoặc chỉ dẫn cách làm, từ này thường được dùng ở số nhiều là directions.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_helicopter', 'en-a2-4', 'helicopter', '/ˈhelɪkɑːptər/', 'A2', 'trực thăng', 'n.', NULL, 'Đồng nghĩa: chopper', 'Cụm từ đi bằng trực thăng sử dụng by helicopter, ở giữa không thêm mạo từ.', 'A helicopter landed in the field behind our house.', NULL, 'Một chiếc trực thăng đã hạ cánh xuống bãi cỏ phía sau nhà chúng tôi.', '{"wordId":"helicopter","ukIpa":"/ˈhelɪkɒptə/","usIpa":"/ˈhelɪkɑːptər/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"An aircraft with rotating blades that can rise straight upwards.","vi":"trực thăng"}],"examples":[{"en":"A helicopter landed in the field behind our house.","vi":"Một chiếc trực thăng đã hạ cánh xuống bãi cỏ phía sau nhà chúng tôi.","audioKind":"ex"},{"en":"A rescue helicopter can reach isolated communities when floods make roads unsafe for emergency vehicles.","vi":"Trực thăng cứu hộ có thể tiếp cận các cộng đồng bị cô lập khi lũ lụt khiến đường xá trở nên nguy hiểm đối với các phương tiện khẩn cấp.","audioKind":"ex2"}],"collocations":[{"en":"rescue helicopter","vi":"trực thăng cứu hộ"},{"en":"helicopter pilot","vi":"phi công trực thăng"},{"en":"by helicopter","vi":"đi bằng trực thăng"}],"wordFamily":[],"synonyms":["chopper"],"antonyms":[],"tipVi":"Cụm từ đi bằng trực thăng sử dụng by helicopter, ở giữa không thêm mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_abroad', 'en-a2-4', 'abroad', '/əˈbrɔːd/', 'A2', 'ở nước ngoài; ra nước ngoài', 'adv.', NULL, 'Đồng nghĩa: overseas', 'abroad là trạng từ: nói go abroad, không nói go to abroad.', 'My sister moved abroad and now lives near the sea.', NULL, 'Chị gái tôi đã chuyển ra nước ngoài sinh sống và hiện đang ở gần biển.', '{"wordId":"abroad","ukIpa":"/əˈbrɔːd/","usIpa":"/əˈbrɔːd/","cefr":"A2","topic":"travel","senses":[{"pos":"adv.","en":"in or to a foreign country","vi":"ở nước ngoài; ra nước ngoài"}],"examples":[{"en":"My sister moved abroad and now lives near the sea.","vi":"Chị gái tôi đã chuyển ra nước ngoài sinh sống và hiện đang ở gần biển.","audioKind":"ex"},{"en":"Studying abroad can help students develop independence and gain a better understanding of other cultures.","vi":"Đi du học có thể giúp học sinh phát triển tính độc lập và hiểu biết sâu sắc hơn về các nền văn hóa khác.","audioKind":"ex2"}],"collocations":[{"en":"study abroad","vi":"du học"},{"en":"go abroad","vi":"đi nước ngoài"},{"en":"live abroad","vi":"sống ở nước ngoài"},{"en":"travel abroad","vi":"du lịch nước ngoài"}],"wordFamily":[],"synonyms":["overseas"],"antonyms":[],"tipVi":"abroad là trạng từ: nói go abroad, không nói go to abroad.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boarding-card', 'en-a2-4', 'boarding card', '/ˈbɔːrdɪŋ kɑːrd/', 'A2', 'thẻ lên máy bay; giấy lên máy bay', 'n.', NULL, 'Đồng nghĩa: boarding pass', 'Chỉ thẻ lên máy bay chứ không phải vé máy bay; boarding pass cũng là từ rất phổ biến.', 'Keep your boarding card handy until you reach your seat.', NULL, 'Hãy giữ thẻ lên máy bay ở nơi dễ lấy cho đến khi bạn về tới chỗ ngồi.', '{"wordId":"boarding-card","ukIpa":"/ˈbɔːdɪŋ kɑːd/","usIpa":"/ˈbɔːrdɪŋ kɑːrd/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A document that allows a passenger to board a plane.","vi":"thẻ lên máy bay; giấy lên máy bay"}],"examples":[{"en":"Keep your boarding card handy until you reach your seat.","vi":"Hãy giữ thẻ lên máy bay ở nơi dễ lấy cho đến khi bạn về tới chỗ ngồi.","audioKind":"ex"},{"en":"Passengers can now download a boarding card, reducing paper consumption and waiting times at airport counters.","vi":"Hành khách giờ đây có thể tải xuống thẻ lên máy bay điện tử, qua đó giúp giảm lượng giấy tiêu thụ và thời gian chờ đợi tại quầy làm thủ tục sân bay.","audioKind":"ex2"}],"collocations":[{"en":"show your boarding card","vi":"xuất trình thẻ lên máy bay"},{"en":"print a boarding card","vi":"in thẻ lên máy bay"},{"en":"electronic boarding card","vi":"thẻ lên máy bay điện tử"}],"wordFamily":[],"synonyms":["boarding pass"],"antonyms":[],"tipVi":"Chỉ thẻ lên máy bay chứ không phải vé máy bay; boarding pass cũng là từ rất phổ biến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_restroom', 'en-a2-4', 'restroom', '/ˈrestruːm/', 'A2', 'phòng vệ sinh công cộng; nhà vệ sinh', 'n.', NULL, 'Đồng nghĩa: washroom, toilet', 'Trong tiếng Anh-Mỹ dùng để chỉ nhà vệ sinh công cộng, không phải phòng nghỉ thông thường.', 'I stopped at the restroom before boarding the bus.', NULL, 'Tôi đã ghé vào phòng vệ sinh trước khi lên xe buýt.', '{"wordId":"restroom","ukIpa":"/ˈrestruːm/","usIpa":"/ˈrestruːm/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"a room with toilets in a public place","vi":"phòng vệ sinh công cộng; nhà vệ sinh"}],"examples":[{"en":"I stopped at the restroom before boarding the bus.","vi":"Tôi đã ghé vào phòng vệ sinh trước khi lên xe buýt.","audioKind":"ex"},{"en":"Providing a clean public restroom near busy transport hubs improves comfort for commuters and tourists alike.","vi":"Việc bố trí một phòng vệ sinh công cộng sạch sẽ gần các đầu mối giao thông nhộn nhịp sẽ mang lại sự thoải mái cho cả người đi làm lẫn khách du lịch.","audioKind":"ex2"}],"collocations":[{"en":"public restroom","vi":"phòng vệ sinh công cộng"},{"en":"restroom facilities","vi":"tiện nghi vệ sinh"},{"en":"accessible restroom","vi":"phòng vệ sinh cho người khuyết tật"}],"wordFamily":[],"synonyms":["washroom","toilet"],"antonyms":[],"tipVi":"Trong tiếng Anh-Mỹ dùng để chỉ nhà vệ sinh công cộng, không phải phòng nghỉ thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_northwest', 'en-a2-4', 'northwest', '/ˌnɔːrθˈwest/', 'A2', 'phía tây bắc; vùng tây bắc; thuộc phía tây bắc; hướng tây bắc; về hướng tây bắc', 'n.', 'northwestern (adj.)', 'Trái nghĩa: southeast', 'Gió tây bắc là gió thổi từ hướng tây bắc tới; di chuyển về hướng tây bắc dùng head northwest.', 'Our cabin is in the northwest of the island.', NULL, 'Nhỏ của chúng tôi nằm ở phía tây bắc của hòn đảo.', '{"wordId":"northwest","ukIpa":"/ˌnɔːθˈwest/","usIpa":"/ˌnɔːrθˈwest/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"The direction between north and west, or an area''s northwestern part.","vi":"phía tây bắc; vùng tây bắc"},{"pos":"adj.","en":"Located in the northwest, or coming from that direction.","vi":"thuộc phía tây bắc; hướng tây bắc"},{"pos":"adv.","en":"Towards or in the direction between north and west.","vi":"về hướng tây bắc"}],"examples":[{"en":"Our cabin is in the northwest of the island.","vi":"Nhỏ của chúng tôi nằm ở phía tây bắc của hòn đảo.","audioKind":"ex"},{"en":"Investment in rail networks could improve access to employment for communities in the northwest of the country.","vi":"Việc đầu tư vào mạng lưới đường sắt có thể cải thiện khả năng tiếp cận việc làm cho các cộng đồng ở khu vực phía tây bắc của đất nước.","audioKind":"ex2"}],"collocations":[{"en":"in the northwest","vi":"ở phía tây bắc"},{"en":"head northwest","vi":"đi về hướng tây bắc"},{"en":"a northwest wind","vi":"gió tây bắc"}],"wordFamily":["northwestern (adj.)"],"synonyms":[],"antonyms":["southeast"],"tipVi":"Gió tây bắc là gió thổi từ hướng tây bắc tới; di chuyển về hướng tây bắc dùng head northwest.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_camping', 'en-a2-4', 'camping', '/ˈkæmpɪŋ/', 'A2', 'sự cắm trại; việc đi cắm trại', 'n.', 'camp (v.), camper (n.), campsite (n.)', NULL, 'Danh từ chỉ hoạt động camping là không đếm được; đi cắm trại nói go camping.', 'We are going camping by the river this weekend.', NULL, 'Cuối tuần này chúng tôi sẽ đi cắm trại bên bờ sông.', '{"wordId":"camping","ukIpa":"/ˈkæmpɪŋ/","usIpa":"/ˈkæmpɪŋ/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"staying outdoors in a tent, usually for a holiday","vi":"sự cắm trại; việc đi cắm trại"}],"examples":[{"en":"We are going camping by the river this weekend.","vi":"Cuối tuần này chúng tôi sẽ đi cắm trại bên bờ sông.","audioKind":"ex"},{"en":"Camping can encourage greater appreciation of nature, provided visitors avoid disturbing wildlife and take their rubbish home.","vi":"Cắm trại có thể thúc đẩy sự trân trọng thiên nhiên nhiều hơn, miễn là du khách tránh làm phiền động vật hoang dã và mang rác về nhà.","audioKind":"ex2"}],"collocations":[{"en":"go camping","vi":"đi cắm trại"},{"en":"camping equipment","vi":"thiết bị cắm trại"},{"en":"a camping trip","vi":"chuyến đi cắm trại"}],"wordFamily":["camp (v.)","camper (n.)","campsite (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ chỉ hoạt động camping là không đếm được; đi cắm trại nói go camping.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_truck', 'en-a2-4', 'truck', '/trʌk/', 'A2', 'xe tải; xe chở hàng; vận chuyển bằng xe tải', 'n.', 'trucking (n.), trucker (n.)', 'Đồng nghĩa: lorry', 'Từ truck thường được dùng trong tiếng Anh-Mỹ, trong khi tiếng Anh-Anh thường dùng lorry.', 'A truck delivered fresh vegetables to the market this morning.', NULL, 'Một chiếc xe tải đã giao rau tươi đến chợ vào sáng nay.', '{"wordId":"truck","ukIpa":"/trʌk/","usIpa":"/trʌk/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A large road vehicle used for carrying goods.","vi":"xe tải; xe chở hàng"},{"pos":"v.","en":"To transport goods by truck.","vi":"vận chuyển bằng xe tải"}],"examples":[{"en":"A truck delivered fresh vegetables to the market this morning.","vi":"Một chiếc xe tải đã giao rau tươi đến chợ vào sáng nay.","audioKind":"ex"},{"en":"Transporting goods by truck offers flexibility, but rail freight can reduce emissions over longer distances.","vi":"Việc vận chuyển hàng hóa bằng xe tải mang lại sự linh hoạt, nhưng vận tải đường sắt có thể giảm lượng khí thải trên những quãng đường dài hơn.","audioKind":"ex2"}],"collocations":[{"en":"delivery truck","vi":"xe tải giao hàng"},{"en":"truck driver","vi":"tài xế xe tải"},{"en":"truck goods","vi":"vận chuyển hàng hóa bằng xe tải"}],"wordFamily":["trucking (n.)","trucker (n.)"],"synonyms":["lorry"],"antonyms":[],"tipVi":"Từ truck thường được dùng trong tiếng Anh-Mỹ, trong khi tiếng Anh-Anh thường dùng lorry.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tourism', 'en-a2-4', 'tourism', '/ˈtʊrɪzəm/', 'A2', 'ngành du lịch; du lịch', 'n.', 'tourist (n.), tour (n.)', NULL, 'tourism thường không đếm được; để chỉ một du khách, dùng a tourist.', 'Tourism brings many visitors to our village each summer.', NULL, 'Du lịch mang lại nhiều du khách cho ngôi làng của chúng tôi vào mỗi mùa hè.', '{"wordId":"tourism","ukIpa":"/ˈtʊərɪzəm/","usIpa":"/ˈtʊrɪzəm/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"travel for pleasure and the businesses serving people who travel","vi":"ngành du lịch; du lịch"}],"examples":[{"en":"Tourism brings many visitors to our village each summer.","vi":"Du lịch mang lại nhiều du khách cho ngôi làng của chúng tôi vào mỗi mùa hè.","audioKind":"ex"},{"en":"Sustainable tourism can generate income for local communities while protecting the natural landscapes that attract visitors.","vi":"Du lịch bền vững có thể tạo ra thu nhập cho các cộng đồng địa phương đồng thời bảo vệ các cảnh quan tự nhiên thu hút du khách.","audioKind":"ex2"}],"collocations":[{"en":"sustainable tourism","vi":"du lịch bền vững"},{"en":"mass tourism","vi":"du lịch đại chúng"},{"en":"domestic tourism","vi":"du lịch nội địa"},{"en":"tourism industry","vi":"ngành du lịch"}],"wordFamily":["tourist (n.)","tour (n.)"],"synonyms":[],"antonyms":[],"tipVi":"tourism thường không đếm được; để chỉ một du khách, dùng a tourist.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_journey', 'en-a2-4', 'journey', '/ˈdʒɝːni/', 'A2', 'cuộc hành trình; chuyến đi; hành trình phát triển; đi du lịch; đi đường', 'n.', NULL, 'Đồng nghĩa: trip', 'journey nhấn mạnh khoảng cách di chuyển; trip thường chỉ chuyến đi có cả chiều đi và về.', 'The train journey took us through snowy mountains.', NULL, 'Chuyến đi bằng tàu hỏa đưa chúng tôi băng qua những ngọn núi phủ đầy tuyết.', '{"wordId":"journey","ukIpa":"/ˈdʒɜːni/","usIpa":"/ˈdʒɝːni/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"an occasion of travelling from one place to another","vi":"cuộc hành trình; chuyến đi"},{"pos":"n.","en":"a process of personal change or development over time","vi":"hành trình phát triển"},{"pos":"v.","en":"to travel from one place to another","vi":"đi du lịch; đi đường"}],"examples":[{"en":"The train journey took us through snowy mountains.","vi":"Chuyến đi bằng tàu hỏa đưa chúng tôi băng qua những ngọn núi phủ đầy tuyết.","audioKind":"ex"},{"en":"Improved rail services could shorten the daily journey to work and encourage commuters to leave their cars at home.","vi":"Dịch vụ đường sắt được cải thiện có thể rút ngắn thời gian di chuyển đi làm hàng ngày và khuyến khích những người đi làm để xe ở nhà.","audioKind":"ex2"}],"collocations":[{"en":"a long journey","vi":"một chuyến đi dài"},{"en":"a return journey","vi":"chuyến đi khứ hồi"},{"en":"a journey of discovery","vi":"hành trình khám phá"},{"en":"make a journey","vi":"thực hiện một chuyến đi"}],"wordFamily":[],"synonyms":["trip"],"antonyms":[],"tipVi":"journey nhấn mạnh khoảng cách di chuyển; trip thường chỉ chuyến đi có cả chiều đi và về.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tent', 'en-a2-4', 'tent', '/tent/', 'A2', 'lều', 'n.', NULL, NULL, 'Cụm từ "dựng lều" dùng động từ "pitch" hoặc "put up a tent".', 'We pitched our tent beside a quiet lake.', NULL, 'Chúng tôi dựng lều bên một hồ nước yên bình.', '{"wordId":"tent","ukIpa":"/tent/","usIpa":"/tent/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"a portable fabric shelter supported by poles and ropes","vi":"lều"}],"examples":[{"en":"We pitched our tent beside a quiet lake.","vi":"Chúng tôi dựng lều bên một hồ nước yên bình.","audioKind":"ex"},{"en":"Visitors who sleep in a tent should follow campsite rules to minimise their impact on local wildlife.","vi":"Du khách ngủ trong lều nên tuân thủ các quy định tại khu cắm trại để giảm thiểu tác động đến động vật hoang dã địa phương.","audioKind":"ex2"}],"collocations":[{"en":"pitch a tent","vi":"dựng lều"},{"en":"put up a tent","vi":"dựng lều trại"},{"en":"take down a tent","vi":"tháo dỡ lều"},{"en":"camping tent","vi":"lều cắm trại"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ \"dựng lều\" dùng động từ \"pitch\" hoặc \"put up a tent\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_speed', 'en-a2-4', 'speed', '/spiːd/', 'A2', 'tốc độ; vận tốc; di chuyển rất nhanh; phóng nhanh; lái xe quá tốc độ quy định; chạy quá tốc độ', 'n.', 'speedy (adj.), speedily (adv.), speeding (n.)', 'Đồng nghĩa: pace, velocity', 'speed up có nghĩa là tăng tốc; speed cũng có thể làm động từ chỉ hành vi lái xe quá tốc độ.', 'The train picked up speed as we left town.', NULL, 'Tàu hỏa bắt đầu tăng tốc khi chúng tôi rời khỏi thị trấn.', '{"wordId":"speed","ukIpa":"/spiːd/","usIpa":"/spiːd/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"How fast something moves, happens, or operates","vi":"tốc độ; vận tốc"},{"pos":"v.","en":"To move or travel very fast","vi":"di chuyển rất nhanh; phóng nhanh"},{"pos":"v.","en":"To drive faster than the legal limit","vi":"lái xe quá tốc độ quy định; chạy quá tốc độ"}],"examples":[{"en":"The train picked up speed as we left town.","vi":"Tàu hỏa bắt đầu tăng tốc khi chúng tôi rời khỏi thị trấn.","audioKind":"ex"},{"en":"Reducing vehicle speeds near schools can significantly improve road safety for children walking or cycling to class.","vi":"Việc giảm tốc độ xe cộ gần các trường học có thể cải thiện đáng kể an toàn giao thông cho trẻ em đi bộ hoặc đi xe đạp đến lớp.","audioKind":"ex2"}],"collocations":[{"en":"at high speed","vi":"ở tốc độ cao"},{"en":"a speed limit","vi":"giới hạn tốc độ"},{"en":"pick up speed","vi":"tăng tốc"},{"en":"speed up","vi":"tăng tốc độ"}],"wordFamily":["speedy (adj.)","speedily (adv.)","speeding (n.)"],"synonyms":["pace","velocity"],"antonyms":[],"tipVi":"speed up có nghĩa là tăng tốc; speed cũng có thể làm động từ chỉ hành vi lái xe quá tốc độ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_airline', 'en-a2-4', 'airline', '/ˈerlaɪn/', 'A2', 'hãng hàng không', 'n.', NULL, 'Đồng nghĩa: air carrier', 'airline dùng để chỉ công ty hàng không; còn chuyến bay cụ thể dùng flight.', 'The airline sent us new tickets after cancelling our flight.', NULL, 'Hãng hàng không đã gửi vé mới cho chúng tôi sau khi hủy chuyến bay.', '{"wordId":"airline","ukIpa":"/ˈeəlaɪn/","usIpa":"/ˈerlaɪn/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A company that transports passengers or goods by aircraft","vi":"hãng hàng không"}],"examples":[{"en":"The airline sent us new tickets after cancelling our flight.","vi":"Hãng hàng không đã gửi vé mới cho chúng tôi sau khi hủy chuyến bay.","audioKind":"ex"},{"en":"Airlines can lower their environmental impact by investing in more efficient aircraft and reducing unnecessary flights.","vi":"Các hãng hàng không có thể giảm thiểu tác động môi trường bằng cách đầu tư vào các dòng máy bay tiết kiệm nhiên liệu hơn và cắt giảm những chuyến bay không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"budget airline","vi":"hãng hàng không giá rẻ"},{"en":"airline ticket","vi":"vé máy bay"},{"en":"airline industry","vi":"ngành hàng không"}],"wordFamily":[],"synonyms":["air carrier"],"antonyms":[],"tipVi":"airline dùng để chỉ công ty hàng không; còn chuyến bay cụ thể dùng flight.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seaside', 'en-a2-4', 'seaside', '/ˈsiːsaɪd/', 'A2', 'vùng biển; bờ biển; thuộc vùng biển; ven biển', 'n.', 'sea (n.)', 'Đồng nghĩa: coast, seashore', 'Danh từ thường đi với mạo từ the seaside; diễn đạt ý "ở bãi biển/bờ biển" dùng giới từ at.', 'We spent the afternoon building sandcastles at the seaside.', NULL, 'Chúng tôi đã dành cả buổi chiều để xây lâu đài cát ở bãi biển.', '{"wordId":"seaside","ukIpa":"/ˈsiːsaɪd/","usIpa":"/ˈsiːsaɪd/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"The area beside the sea, especially where people spend holidays","vi":"vùng biển; bờ biển"},{"pos":"adj.","en":"Located beside the sea, especially in a holiday area","vi":"thuộc vùng biển; ven biển"}],"examples":[{"en":"We spent the afternoon building sandcastles at the seaside.","vi":"Chúng tôi đã dành cả buổi chiều để xây lâu đài cát ở bãi biển.","audioKind":"ex"},{"en":"Seaside towns often depend on summer tourism, which can create unstable employment for local residents.","vi":"Các thị trấn ven biển thường phụ thuộc vào du lịch mùa hè, điều này có thể tạo ra việc làm bấp bênh cho cư dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"at the seaside","vi":"ở bờ biển"},{"en":"seaside resort","vi":"khu nghỉ mát ven biển"},{"en":"seaside town","vi":"thị trấn ven biển"},{"en":"seaside holiday","vi":"kỳ nghỉ ở biển"}],"wordFamily":["sea (n.)"],"synonyms":["coast","seashore"],"antonyms":[],"tipVi":"Danh từ thường đi với mạo từ the seaside; diễn đạt ý \"ở bãi biển/bờ biển\" dùng giới từ at.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_across', 'en-a2-4', 'across', '/əˈkrɔːs/', 'A2', 'qua; băng qua; từ bên này sang bên kia; ở phía bên kia; khắp; trải khắp; ở phía đối diện', 'prep.', NULL, NULL, 'across nhấn mạnh việc di chuyển băng qua bề mặt; through nhấn mạnh việc đi xuyên qua từ bên trong.', 'We walked across the bridge before the rain started.', NULL, 'Chúng tôi đi bộ qua cầu trước khi trời bắt đầu mưa.', '{"wordId":"across","ukIpa":"/əˈkrɒs/","usIpa":"/əˈkrɔːs/","cefr":"A2","topic":"travel","senses":[{"pos":"prep.","en":"From one side of something to the other.","vi":"qua; băng qua; từ bên này sang bên kia"},{"pos":"prep.","en":"On the opposite side of, or throughout, an area.","vi":"ở phía bên kia; khắp; trải khắp"},{"pos":"adv.","en":"From one side to another, or on the opposite side.","vi":"từ bên này sang bên kia; ở phía đối diện"}],"examples":[{"en":"We walked across the bridge before the rain started.","vi":"Chúng tôi đi bộ qua cầu trước khi trời bắt đầu mưa.","audioKind":"ex"},{"en":"Improved internet access allows students across rural regions to benefit from a wider range of educational resources.","vi":"Việc cải thiện khả năng truy cập internet cho phép học sinh ở các vùng nông thôn tiếp cận được với nhiều nguồn tài nguyên giáo dục phong phú hơn.","audioKind":"ex2"}],"collocations":[{"en":"across the road","vi":"ở bên kia đường"},{"en":"across the country","vi":"trên khắp cả nước"},{"en":"walk across a bridge","vi":"đi bộ qua cầu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"across nhấn mạnh việc di chuyển băng qua bề mặt; through nhấn mạnh việc đi xuyên qua từ bên trong.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_malaysia', 'en-a2-4', 'Malaysia', '/məˈleɪʒə/', 'A2', 'Malaysia (một quốc gia Đông Nam Á nằm ở bán đảo Mã Lai và đảo Borneo)', 'n.', 'Malaysian (adj.), Malaysian (n.)', NULL, 'Tên quốc gia phải viết hoa chữ cái đầu và thông thường không đi kèm mạo từ the.', 'We explored a rainforest during our holiday in Malaysia.', NULL, 'Chúng tôi đã thám hiểm một khu rừng nhiệt đới trong chuyến nghỉ mát tại Malaysia.', '{"wordId":"malaysia","ukIpa":"/məˈleɪziə/","usIpa":"/məˈleɪʒə/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"a Southeast Asian country occupying parts of a peninsula and Borneo","vi":"Malaysia (một quốc gia Đông Nam Á nằm ở bán đảo Mã Lai và đảo Borneo)"}],"examples":[{"en":"We explored a rainforest during our holiday in Malaysia.","vi":"Chúng tôi đã thám hiểm một khu rừng nhiệt đới trong chuyến nghỉ mát tại Malaysia.","audioKind":"ex"},{"en":"Tourism in Malaysia creates employment opportunities, but protecting fragile coastal ecosystems remains an important priority.","vi":"Ngành du lịch ở Malaysia tạo ra cơ hội việc làm, nhưng việc bảo vệ các hệ sinh thái ven biển mỏng manh vẫn là một ưu tiên quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"visit Malaysia","vi":"ghé thăm Malaysia"},{"en":"travel to Malaysia","vi":"đi du lịch Malaysia"},{"en":"Peninsular Malaysia","vi":"Bán đảo Malaysia"}],"wordFamily":["Malaysian (adj.)","Malaysian (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên quốc gia phải viết hoa chữ cái đầu và thông thường không đi kèm mạo từ the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_southeast', 'en-a2-4', 'southeast', '/ˌsaʊθˈiːst/', 'A2', 'hướng đông nam; miền đông nam; thuộc phía đông nam; về hướng đông nam; ở phía đông nam', 'n.', 'southeastern (adj.)', 'Trái nghĩa: northwest', 'Trước danh từ thường dùng the; phó từ thì không cần: head southeast.', 'Our kitchen window faces southeast and catches the morning sun.', NULL, 'Cửa sổ nhà bếp của chúng tôi quay về hướng đông nam và đón nắng ban mai.', '{"wordId":"southeast","ukIpa":"/ˌsaʊθˈiːst/","usIpa":"/ˌsaʊθˈiːst/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"The direction between south and east, or an area''s southeastern part.","vi":"hướng đông nam; miền đông nam"},{"pos":"adj.","en":"Located in the southeast, or coming from that direction.","vi":"thuộc phía đông nam; hướng đông nam"},{"pos":"adv.","en":"Towards or in the southeast.","vi":"về hướng đông nam; ở phía đông nam"}],"examples":[{"en":"Our kitchen window faces southeast and catches the morning sun.","vi":"Cửa sổ nhà bếp của chúng tôi quay về hướng đông nam và đón nắng ban mai.","audioKind":"ex"},{"en":"Population growth in the southeast has increased demand for affordable housing and reliable public transport.","vi":"Sự gia tăng dân số ở khu vực phía đông nam đã làm tăng nhu cầu về nhà ở vừa túi tiền và phương tiện giao thông công cộng đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"in the southeast","vi":"ở phía đông nam"},{"en":"southeast of","vi":"về phía đông nam của"},{"en":"head southeast","vi":"đi về hướng đông nam"},{"en":"the southeast coast","vi":"bờ biển phía đông nam"}],"wordFamily":["southeastern (adj.)"],"synonyms":[],"antonyms":["northwest"],"tipVi":"Trước danh từ thường dùng the; phó từ thì không cần: head southeast.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_passport', 'en-a2-4', 'passport', '/ˈpæspɔːrt/', 'A2', 'hộ chiếu; phương tiện dẫn đến thành công', 'n.', NULL, NULL, 'Trong cấu trúc ẩn dụ a passport to, từ to đi kèm với danh từ.', 'I checked my bag twice to find my passport.', NULL, 'Tôi đã kiểm tra túi của mình hai lần để tìm hộ chiếu.', '{"wordId":"passport","ukIpa":"/ˈpɑːspɔːt/","usIpa":"/ˈpæspɔːrt/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"an official document identifying you when travelling between countries","vi":"hộ chiếu"},{"pos":"n.","en":"something that makes success or an opportunity possible","vi":"phương tiện dẫn đến thành công"}],"examples":[{"en":"I checked my bag twice to find my passport.","vi":"Tôi đã kiểm tra túi của mình hai lần để tìm hộ chiếu.","audioKind":"ex"},{"en":"A university degree is often viewed as a passport to better employment, although practical experience also matters.","vi":"Bằng đại học thường được xem là tấm vé thông hành dẫn đến việc làm tốt hơn, mặc dù kinh nghiệm thực tế cũng rất quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"valid passport","vi":"hộ chiếu còn hạn"},{"en":"renew a passport","vi":"gia hạn hộ chiếu"},{"en":"passport control","vi":"khu vực kiểm tra hộ chiếu"},{"en":"a passport to success","vi":"tấm vé thông hành đến thành công"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong cấu trúc ẩn dụ a passport to, từ to đi kèm với danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_luggage', 'en-a2-4', 'luggage', '/ˈlʌɡɪdʒ/', 'A2', 'hành lý', 'n.', NULL, 'Đồng nghĩa: baggage', 'Không đếm được; một kiện hành lý dùng a piece of luggage.', 'Our luggage barely fitted into the small taxi.', NULL, 'Hành lý của chúng tôi vừa vặn nhét vào chiếc taxi nhỏ.', '{"wordId":"luggage","ukIpa":"/ˈlʌɡɪdʒ/","usIpa":"/ˈlʌɡɪdʒ/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"bags and cases that hold your belongings when travelling","vi":"hành lý"}],"examples":[{"en":"Our luggage barely fitted into the small taxi.","vi":"Hành lý của chúng tôi vừa vặn nhét vào chiếc taxi nhỏ.","audioKind":"ex"},{"en":"Providing secure luggage storage at railway stations can encourage tourists to explore nearby attractions on foot.","vi":"Việc cung cấp dịch vụ giữ hành lý an toàn tại các nhà ga xe lửa có thể khuyến khích du khách đi bộ khám phá các điểm tham quan gần đó.","audioKind":"ex2"}],"collocations":[{"en":"hand luggage","vi":"hành lý xách tay"},{"en":"luggage storage","vi":"giữ hành lý"},{"en":"a piece of luggage","vi":"một kiện hành lý"},{"en":"luggage allowance","vi":"hạn mức hành lý"}],"wordFamily":[],"synonyms":["baggage"],"antonyms":[],"tipVi":"Không đếm được; một kiện hành lý dùng a piece of luggage.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_4_1', 'en-a2-4', 'Cách dùng “direction” (n.) — phương hướng; hướng đi', 'in the opposite direction  ·  ask for directions  ·  follow the directions', 'Khi mang nghĩa là hướng dẫn đường đi hoặc chỉ dẫn cách làm, từ này thường được dùng ở số nhiều là directions.', 'Họ từ (Word Family): direct (v.), director (n.), directional (adj.)', '[{"hanzi":"The dog suddenly ran in the opposite direction.","pinyin":"","meaning":"Con chó đột nhiên chạy theo hướng ngược lại."},{"hanzi":"Government investment can influence the direction of technological development by supporting research into cleaner energy sources.","pinyin":"","meaning":"Sự đầu tư của chính phủ có thể định hướng sự phát triển công nghệ bằng cách hỗ trợ nghiên cứu về các nguồn năng lượng sạch hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_4_2', 'en-a2-4', 'Cách dùng “across” (prep.) — qua; băng qua; từ bên này sang bên kia', 'across the road  ·  across the country  ·  walk across a bridge', 'across nhấn mạnh việc di chuyển băng qua bề mặt; through nhấn mạnh việc đi xuyên qua từ bên trong.', NULL, '[{"hanzi":"We walked across the bridge before the rain started.","pinyin":"","meaning":"Chúng tôi đi bộ qua cầu trước khi trời bắt đầu mưa."},{"hanzi":"Improved internet access allows students across rural regions to benefit from a wider range of educational resources.","pinyin":"","meaning":"Việc cải thiện khả năng truy cập internet cho phép học sinh ở các vùng nông thôn tiếp cận được với nhiều nguồn tài nguyên giáo dục phong phú hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_4_3', 'en-a2-4', 'Cách dùng “northwest” (n.) — phía tây bắc; vùng tây bắc', 'in the northwest  ·  head northwest  ·  a northwest wind', 'Gió tây bắc là gió thổi từ hướng tây bắc tới; di chuyển về hướng tây bắc dùng head northwest.', 'Họ từ (Word Family): northwestern (adj.) | Trái nghĩa: southeast', '[{"hanzi":"Our cabin is in the northwest of the island.","pinyin":"","meaning":"Nhỏ của chúng tôi nằm ở phía tây bắc của hòn đảo."},{"hanzi":"Investment in rail networks could improve access to employment for communities in the northwest of the country.","pinyin":"","meaning":"Việc đầu tư vào mạng lưới đường sắt có thể cải thiện khả năng tiếp cận việc làm cho các cộng đồng ở khu vực phía tây bắc của đất nước."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_4_4', 'en-a2-4', 'Cách dùng “speed” (n.) — tốc độ; vận tốc', 'at high speed  ·  a speed limit  ·  pick up speed', 'speed up có nghĩa là tăng tốc; speed cũng có thể làm động từ chỉ hành vi lái xe quá tốc độ.', 'Họ từ (Word Family): speedy (adj.), speedily (adv.), speeding (n.) | Đồng nghĩa: pace, velocity', '[{"hanzi":"The train picked up speed as we left town.","pinyin":"","meaning":"Tàu hỏa bắt đầu tăng tốc khi chúng tôi rời khỏi thị trấn."},{"hanzi":"Reducing vehicle speeds near schools can significantly improve road safety for children walking or cycling to class.","pinyin":"","meaning":"Việc giảm tốc độ xe cộ gần các trường học có thể cải thiện đáng kể an toàn giao thông cho trẻ em đi bộ hoặc đi xe đạp đến lớp."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_4_1', 'en-a2-4', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_4_1_1', 'ten_a2_4_1', 'Scotland', 'We explored old castles during our holiday in Scotland.', 'We explored old castles during our holiday in Scotland.', '/ˈskɑːtlənd/', 'Chúng tôi đã khám phá những lâu đài cổ trong chuyến nghỉ dưỡng tại Xơ-cốt-len.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_4_1_2', 'ten_a2_4_1', 'visitor', 'A visitor left her umbrella beside our front door.', 'A visitor left her umbrella beside our front door.', '/ˈvɪzɪtər/', 'Một vị khách đã để quên chiếc ô bên cạnh cửa trước nhà chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_4_1_3', 'ten_a2_4_1', 'kilometer', 'The nearest bakery is about a kilometer from here.', 'The nearest bakery is about a kilometer from here.', '/kɪˈlɑːmɪtər/', 'Tiệm bánh gần nhất cách đây khoảng một cây số.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_4_1_4', 'ten_a2_4_1', 'passenger', 'A passenger left a blue umbrella on the bus.', 'A passenger left a blue umbrella on the bus.', '/ˈpæsɪndʒər/', 'Một hành khách đã để quên chiếc ô màu xanh trên xe buýt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_4_1_5', 'ten_a2_4_1', 'direction', 'The dog suddenly ran in the opposite direction.', 'The dog suddenly ran in the opposite direction.', '/dəˈrekʃən/', 'Con chó đột nhiên chạy theo hướng ngược lại.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_4_1_6', 'ten_a2_4_1', 'helicopter', 'A helicopter landed in the field behind our house.', 'A helicopter landed in the field behind our house.', '/ˈhelɪkɑːptər/', 'Một chiếc trực thăng đã hạ cánh xuống bãi cỏ phía sau nhà chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_4_1_7', 'ten_a2_4_1', 'abroad', 'My sister moved abroad and now lives near the sea.', 'My sister moved abroad and now lives near the sea.', '/əˈbrɔːd/', 'Chị gái tôi đã chuyển ra nước ngoài sinh sống và hiện đang ở gần biển.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_4_1_8', 'ten_a2_4_1', 'boarding card', 'Keep your boarding card handy until you reach your seat.', 'Keep your boarding card handy until you reach your seat.', '/ˈbɔːrdɪŋ kɑːrd/', 'Hãy giữ thẻ lên máy bay ở nơi dễ lấy cho đến khi bạn về tới chỗ ngồi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_4_1_1', 'en-a2-4', 'ten_a2_4_1', 'listening', 'listening', 'We explored old castles during our holiday in Scotland.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cửa sổ nhà bếp của chúng tôi quay về hướng đông nam và đón nắng ban mai.","Hãy giữ thẻ lên máy bay ở nơi dễ lấy cho đến khi bạn về tới chỗ ngồi.","Cuối tuần này chúng tôi sẽ đi cắm trại bên bờ sông.","Chúng tôi đã khám phá những lâu đài cổ trong chuyến nghỉ dưỡng tại Xơ-cốt-len."]'::jsonb, 3, 'We explored old castles during our holiday in Scotland. → Chúng tôi đã khám phá những lâu đài cổ trong chuyến nghỉ dưỡng tại Xơ-cốt-len.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_4_1_2', 'en-a2-4', 'ten_a2_4_1', 'listening', 'listening', 'A visitor left her umbrella beside our front door.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Nhỏ của chúng tôi nằm ở phía tây bắc của hòn đảo.","Một vị khách đã để quên chiếc ô bên cạnh cửa trước nhà chúng tôi.","Con chó đột nhiên chạy theo hướng ngược lại.","Chúng tôi đi bộ qua cầu trước khi trời bắt đầu mưa."]'::jsonb, 1, 'A visitor left her umbrella beside our front door. → Một vị khách đã để quên chiếc ô bên cạnh cửa trước nhà chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_4_1_3', 'en-a2-4', 'ten_a2_4_1', 'listening', 'listening', 'The nearest bakery is about a kilometer from here.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tiệm bánh gần nhất cách đây khoảng một cây số.","Chúng tôi đã khám phá những lâu đài cổ trong chuyến nghỉ dưỡng tại Xơ-cốt-len.","Chị gái tôi đã chuyển ra nước ngoài sinh sống và hiện đang ở gần biển.","Tôi đã kiểm tra túi của mình hai lần để tìm hộ chiếu."]'::jsonb, 0, 'The nearest bakery is about a kilometer from here. → Tiệm bánh gần nhất cách đây khoảng một cây số.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_4_2', 'en-a2-4', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_4_2_1', 'ten_a2_4_2', 'Scotland', 'Scotland attracts visitors with its dramatic landscapes, while rural communities benefit from spending on accommodation and local services.', 'Scotland attracts visitors with its dramatic landscapes, while rural communities benefit from spending on accommodation and local services.', '/ˈskɑːtlənd/', 'Xơ-cốt-len thu hút du khách bởi cảnh quan hùng vĩ, trong khi các cộng đồng nông thôn được hưởng lợi từ chi tiêu cho chỗ ở và dịch vụ địa phương.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_4_2_2', 'ten_a2_4_2', 'visitor', 'The museum attracts international visitors by offering exhibitions that explore local history and culture.', 'The museum attracts international visitors by offering exhibitions that explore local history and culture.', '/ˈvɪzɪtər/', 'Bảo tàng thu hút du khách quốc tế bằng cách cung cấp các triển lãm khám phá lịch sử và văn hóa địa phương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_4_2_3', 'ten_a2_4_2', 'kilometer', 'Providing reliable public transport within a kilometer of residential areas could reduce dependence on private cars.', 'Providing reliable public transport within a kilometer of residential areas could reduce dependence on private cars.', '/kɪˈlɑːmɪtər/', 'Việc cung cấp giao thông công cộng đáng tin cậy trong phạm vi một ki-lô-mét từ các khu dân cư có thể làm giảm sự phụ thuộc vào ô tô cá nhân.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_4_2_4', 'ten_a2_4_2', 'passenger', 'Improved rail services could increase passenger numbers and reduce reliance on private cars.', 'Improved rail services could increase passenger numbers and reduce reliance on private cars.', '/ˈpæsɪndʒər/', 'Việc cải thiện dịch vụ đường sắt có thể làm tăng lượng hành khách và giảm sự phụ thuộc vào ô tô cá nhân.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_4_2_5', 'ten_a2_4_2', 'direction', 'Government investment can influence the direction of technological development by supporting research into cleaner energy sources.', 'Government investment can influence the direction of technological development by supporting research into cleaner energy sources.', '/dəˈrekʃən/', 'Sự đầu tư của chính phủ có thể định hướng sự phát triển công nghệ bằng cách hỗ trợ nghiên cứu về các nguồn năng lượng sạch hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_4_2_6', 'ten_a2_4_2', 'helicopter', 'A rescue helicopter can reach isolated communities when floods make roads unsafe for emergency vehicles.', 'A rescue helicopter can reach isolated communities when floods make roads unsafe for emergency vehicles.', '/ˈhelɪkɑːptər/', 'Trực thăng cứu hộ có thể tiếp cận các cộng đồng bị cô lập khi lũ lụt khiến đường xá trở nên nguy hiểm đối với các phương tiện khẩn cấp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_4_2_1', 'en-a2-4', 'ten_a2_4_2', 'listening', 'listening', 'Scotland attracts visitors with its dramatic landscapes, while rural communities benefit from spending on accommodation and local services.', NULL, 'Trong câu vừa nghe, từ “Scotland” mang nghĩa nào sau đây?', '["thiết bị, dụng cụ, trang thiết bị","da (người hoặc động vật)","Xốt-lân; Xéc-lân (Xơ-cốt-len)","thực ra; thực sự; quả thực"]'::jsonb, 2, '“Scotland” (/ˈskɑːtlənd/): Xốt-lân; Xéc-lân (Xơ-cốt-len). Câu đầy đủ: Scotland attracts visitors with its dramatic landscapes, while rural communities benefit from spending on accommodation and local services.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_4_2_2', 'en-a2-4', 'ten_a2_4_2', 'listening', 'listening', 'The museum attracts international visitors by offering exhibitions that explore local history and culture.', NULL, 'Trong câu vừa nghe, từ “visitor” mang nghĩa nào sau đây?', '["chuẩn bị; làm cho ai hoặc cái gì sẵn sàng cho một hoạt động hoặc tình huống","kỹ sư","khách; khách tham quan; du khách","điên rồ; ngớ ngẩn; bất hợp lý; kỳ quặc"]'::jsonb, 2, '“visitor” (/ˈvɪzɪtər/): khách; khách tham quan; du khách. Câu đầy đủ: The museum attracts international visitors by offering exhibitions that explore local history and culture.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
