INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_4_2', 'en-a2-4', NULL, 'comprehensive_test', 'listening', 'A visitor left her umbrella beside our front door.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một vị khách đã để quên chiếc ô bên cạnh cửa trước nhà chúng tôi.","Một chiếc trực thăng đã hạ cánh xuống bãi cỏ phía sau nhà chúng tôi.","Chúng tôi đã thám hiểm một khu rừng nhiệt đới trong chuyến nghỉ mát tại Malaysia.","Tôi đã ghé vào phòng vệ sinh trước khi lên xe buýt."]'::jsonb, 0, 'A visitor left her umbrella beside our front door. → Một vị khách đã để quên chiếc ô bên cạnh cửa trước nhà chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_4_3', 'en-a2-4', NULL, 'comprehensive_test', 'listening', 'kilometer', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bồn tắm","chạy bộ chậm và đều đặn, thường là để rèn luyện sức khỏe","ki-lô-mét; cây số","tránh; ngăn chặn"]'::jsonb, 2, 'kilometer (/kɪˈlɑːmɪtər/) → ki-lô-mét; cây số', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_4_4', 'en-a2-4', NULL, 'comprehensive_test', 'listening', 'A passenger left a blue umbrella on the bus.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã ghé vào phòng vệ sinh trước khi lên xe buýt.","Chúng tôi đã khám phá những lâu đài cổ trong chuyến nghỉ dưỡng tại Xơ-cốt-len.","Một hành khách đã để quên chiếc ô màu xanh trên xe buýt.","Hãng hàng không đã gửi vé mới cho chúng tôi sau khi hủy chuyến bay."]'::jsonb, 2, 'A passenger left a blue umbrella on the bus. → Một hành khách đã để quên chiếc ô màu xanh trên xe buýt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_4_5', 'en-a2-4', NULL, 'comprehensive_test', 'listening', 'direction', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["phương hướng; hướng đi","tác giả; nhà văn","kiếm được; kiếm tiền","kem; sữa đặc béo"]'::jsonb, 0, 'direction (/dəˈrekʃən/) → phương hướng; hướng đi; chỉ đường; hướng dẫn sử dụng; sự chỉ đạo; sự quản lý', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_4_6', 'en-a2-4', NULL, 'comprehensive_test', 'listening', 'A helicopter landed in the field behind our house.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã dành cả buổi chiều để xây lâu đài cát ở bãi biển.","Cuối tuần này chúng tôi sẽ đi cắm trại bên bờ sông.","Một chiếc trực thăng đã hạ cánh xuống bãi cỏ phía sau nhà chúng tôi.","Tôi đã ghé vào phòng vệ sinh trước khi lên xe buýt."]'::jsonb, 2, 'A helicopter landed in the field behind our house. → Một chiếc trực thăng đã hạ cánh xuống bãi cỏ phía sau nhà chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
