INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_4_8', 'en-a2-4', NULL, 'comprehensive_test', 'listening', 'Keep your boarding card handy until you reach your seat.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Du lịch mang lại nhiều du khách cho ngôi làng của chúng tôi vào mỗi mùa hè.","Nhỏ của chúng tôi nằm ở phía tây bắc của hòn đảo.","Hãy giữ thẻ lên máy bay ở nơi dễ lấy cho đến khi bạn về tới chỗ ngồi.","Chúng tôi đã khám phá những lâu đài cổ trong chuyến nghỉ dưỡng tại Xơ-cốt-len."]'::jsonb, 2, 'Keep your boarding card handy until you reach your seat. → Hãy giữ thẻ lên máy bay ở nơi dễ lấy cho đến khi bạn về tới chỗ ngồi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
