INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_4_18', 'en-a2-4', NULL, 'comprehensive_test', 'reading', NULL, 'Scotland attracts visitors with its dramatic landscapes, while rural communities benefit from spending on accommodation and local services.', 'Dựa vào câu trên, từ “Scotland” có nghĩa phù hợp nhất là gì?', '["chạy bộ (chạy chậm và đều như một hình thức tập thể dục)","cho là; nghĩ rằng; đoán rằng (khi chưa chắc chắn)","Xốt-lân; Xéc-lân (Xơ-cốt-len)","hình thức; dạng; hình dáng"]'::jsonb, 2, 'Scotland: Xốt-lân; Xéc-lân (Xơ-cốt-len). Dịch cả câu: Xơ-cốt-len thu hút du khách bởi cảnh quan hùng vĩ, trong khi các cộng đồng nông thôn được hưởng lợi từ chi tiêu cho chỗ ở và dịch vụ địa phương.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_4_19', 'en-a2-4', NULL, 'comprehensive_test', 'reading', NULL, 'The museum attracts international visitors by offering exhibitions that explore local history and culture.', 'Dựa vào câu trên, từ “visitor” có nghĩa phù hợp nhất là gì?', '["một cách buồn bã; đầy đau buồn","khách; khách tham quan; du khách","nhận được (cái gì đó do ai gửi, trao hoặc cung cấp)","cốc có quai lớn"]'::jsonb, 1, 'visitor: khách; khách tham quan; du khách. Dịch cả câu: Bảo tàng thu hút du khách quốc tế bằng cách cung cấp các triển lãm khám phá lịch sử và văn hóa địa phương.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_4_20', 'en-a2-4', NULL, 'comprehensive_test', 'reading', NULL, 'Providing reliable public transport within a kilometer of residential areas could reduce dependence on private cars.', 'Dựa vào câu trên, từ “kilometer” có nghĩa phù hợp nhất là gì?', '["tàu thủy; thuyền lớn","dịch vụ; sự phục vụ","ki-lô-mét; cây số","hòa bình; sự hòa thuận"]'::jsonb, 2, 'kilometer: ki-lô-mét; cây số. Dịch cả câu: Việc cung cấp giao thông công cộng đáng tin cậy trong phạm vi một ki-lô-mét từ các khu dân cư có thể làm giảm sự phụ thuộc vào ô tô cá nhân.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_4_21', 'en-a2-4', NULL, 'comprehensive_test', 'reading', NULL, 'Improved rail services could increase passenger numbers and reduce reliance on private cars.', 'Dựa vào câu trên, từ “passenger” có nghĩa phù hợp nhất là gì?', '["hành khách; khách đi xe, tàu, máy bay","túi áo; túi quần","việc dạy học; công tác giảng dạy; nghề dạy học","chạm; sờ"]'::jsonb, 0, 'passenger: hành khách; khách đi xe, tàu, máy bay. Dịch cả câu: Việc cải thiện dịch vụ đường sắt có thể làm tăng lượng hành khách và giảm sự phụ thuộc vào ô tô cá nhân.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_4_22', 'en-a2-4', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hướng đông nam; miền đông nam”', '["loudly","southeast","closed","platform"]'::jsonb, 1, 'hướng đông nam; miền đông nam → southeast (/ˌsaʊθˈiːst/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_4_23', 'en-a2-4', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hộ chiếu”', '["fork","rule","passport","perhaps"]'::jsonb, 2, 'hộ chiếu → passport (/ˈpæspɔːrt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_4_24', 'en-a2-4', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hành lý”', '["underground","luggage","cover","along"]'::jsonb, 1, 'hành lý → luggage (/ˈlʌɡɪdʒ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-5', 'en', 'Bài 5: Du lịch & Di chuyển (3) - CEFR A2', 'CEFR A2', 'A2 · Du lịch', '23 từ vựng Tiếng Anh CEFR A2 chủ đề du lịch & di chuyển kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2005, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_united-kingdom', 'en-a2-5', 'United Kingdom', '/juˌnaɪtɪd ˈkɪŋdəm/', 'A2', 'Vương quốc Anh; Vương quốc Liên hiệp Anh và Bắc Ireland', 'n.', NULL, 'Đồng nghĩa: UK', 'Phía trước thường có mạo từ the; bao gồm Bắc Ireland, không đồng nhất với Đại bất liệt.', 'We travelled around the United Kingdom by train last summer.', NULL, 'Chúng tôi đã đi du lịch khắp Vương quốc Anh bằng tàu hỏa vào mùa hè năm ngoái.', '{"wordId":"united-kingdom","ukIpa":"/juˌnaɪtɪd ˈkɪŋdəm/","usIpa":"/juˌnaɪtɪd ˈkɪŋdəm/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"The country comprising England, Scotland, Wales, and Northern Ireland.","vi":"Vương quốc Anh; Vương quốc Liên hiệp Anh và Bắc Ireland"}],"examples":[{"en":"We travelled around the United Kingdom by train last summer.","vi":"Chúng tôi đã đi du lịch khắp Vương quốc Anh bằng tàu hỏa vào mùa hè năm ngoái.","audioKind":"ex"},{"en":"International students in the United Kingdom contribute to university communities through their diverse experiences and perspectives.","vi":"Sinh viên quốc tế tại Vương quốc Anh đóng góp cho cộng đồng đại học thông qua những trải nghiệm và góc nhìn đa dạng của họ.","audioKind":"ex2"}],"collocations":[{"en":"the United Kingdom","vi":"Vương quốc Anh"},{"en":"across the United Kingdom","vi":"khắp Vương quốc Anh"},{"en":"the United Kingdom economy","vi":"kinh tế Vương quốc Anh"}],"wordFamily":[],"synonyms":["UK"],"antonyms":[],"tipVi":"Phía trước thường có mạo từ the; bao gồm Bắc Ireland, không đồng nhất với Đại bất liệt.","noteVi":"Đã viết hoa chữ cái đầu theo tên quốc gia chuẩn.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_transport', 'en-a2-5', 'transport', '/ˈtrænspɔːrt/', 'A2', 'giao thông vận tải; phương tiện giao thông; vận chuyển; chuyên chở', 'n.', 'transportation (n.), transporter (n.), transportable (adj.)', NULL, 'Các mục trên dùng cho âm tiết danh từ; động từ chuyển trọng âm về sau, âm /t/ đứng trước /n/.', 'We rely on public transport to get around town.', NULL, 'Chúng tôi dựa vào phương tiện giao thông công cộng để đi lại trong thị trấn.', '{"wordId":"transport","ukIpa":"/ˈtrænspɔːt/","usIpa":"/ˈtrænspɔːrt/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"Vehicles or systems used to move people and goods.","vi":"giao thông vận tải; phương tiện giao thông"},{"pos":"v.","en":"To move people or goods from one place to another.","vi":"vận chuyển; chuyên chở"}],"examples":[{"en":"We rely on public transport to get around town.","vi":"Chúng tôi dựa vào phương tiện giao thông công cộng để đi lại trong thị trấn.","audioKind":"ex"},{"en":"Better transport links between rural areas and cities can expand employment opportunities for local residents.","vi":"Các mối liên kết giao thông tốt hơn giữa các vùng nông thôn và thành phố có thể mở rộng cơ hội việc làm cho cư dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"public transport","vi":"giao thông công cộng"},{"en":"transport links","vi":"kết nối giao thông"},{"en":"transport goods","vi":"vận chuyển hàng hóa"},{"en":"transport network","vi":"mạng lưới giao thông"}],"wordFamily":["transportation (n.)","transporter (n.)","transportable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Các mục trên dùng cho âm tiết danh từ; động từ chuyển trọng âm về sau, âm /t/ đứng trước /n/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tram', 'en-a2-5', 'tram', '/træm/', 'A2', 'xe điện; tàu điện', 'n.', NULL, 'Đồng nghĩa: streetcar', 'Chỉ phương tiện xe điện, không phải đường ray; tiếng Anh-Mỹ thường dùng streetcar.', 'We caught the tram outside the library this morning.', NULL, 'Chúng tôi đã bắt xe điện bên ngoài thư viện sáng nay.', '{"wordId":"tram","ukIpa":"/træm/","usIpa":"/træm/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"An electric passenger vehicle running on tracks along city streets.","vi":"xe điện; tàu điện"}],"examples":[{"en":"We caught the tram outside the library this morning.","vi":"Chúng tôi đã bắt xe điện bên ngoài thư viện sáng nay.","audioKind":"ex"},{"en":"Investing in tram networks can reduce traffic congestion and improve access to busy city centres.","vi":"Đầu tư vào mạng lưới xe điện có thể làm giảm tắc nghẽn giao thông và giúp việc tiếp cận khu trung tâm thành phố sầm uất trở nên dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"catch a tram","vi":"bắt xe điện"},{"en":"tram stop","vi":"trạm xe điện"},{"en":"tram network","vi":"mạng lưới xe điện"}],"wordFamily":[],"synonyms":["streetcar"],"antonyms":[],"tipVi":"Chỉ phương tiện xe điện, không phải đường ray; tiếng Anh-Mỹ thường dùng streetcar.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cross', 'en-a2-5', 'cross', '/krɔːs/', 'A2', 'đi qua; băng qua; giao nhau; hình chữ thập; ký hiệu chữ thập; cây thánh giá; bực mình; cáu kỉnh', 'v.', 'crossing (n.)', NULL, 'cross là động từ; across là giới từ hoặc trạng từ.', 'We waited for the traffic to stop before crossing.', NULL, 'Chúng tôi đợi xe cộ dừng lại rồi mới qua đường.', '{"wordId":"cross","ukIpa":"/krɒs/","usIpa":"/krɔːs/","cefr":"A2","topic":"travel","senses":[{"pos":"v.","en":"to go from one side to another, or intersect","vi":"đi qua; băng qua; giao nhau"},{"pos":"n.","en":"a shape made by two intersecting lines, or a religious symbol","vi":"hình chữ thập; ký hiệu chữ thập; cây thánh giá"},{"pos":"adj.","en":"annoyed or slightly angry","vi":"bực mình; cáu kỉnh"}],"examples":[{"en":"We waited for the traffic to stop before crossing.","vi":"Chúng tôi đợi xe cộ dừng lại rồi mới qua đường.","audioKind":"ex"},{"en":"Safer pedestrian routes encourage residents to cross busy roads on foot rather than drive short distances.","vi":"Các tuyến đường dành cho người đi bộ an toàn hơn khuyến khích cư dân đi bộ băng qua các con đường đông đúc thay vì lái xe những quãng đường ngắn.","audioKind":"ex2"}],"collocations":[{"en":"cross the road","vi":"sang đường"},{"en":"cross a bridge","vi":"đi qua cầu"},{"en":"cross with someone","vi":"giận ai đó"}],"wordFamily":["crossing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"cross là động từ; across là giới từ hoặc trạng từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_adventure', 'en-a2-5', 'adventure', '/ədˈventʃər/', 'A2', 'chuyến phiêu lưu; cuộc thám hiểm; tinh thần phiêu lưu', 'n.', 'adventurous (adj.), adventurer (n.)', NULL, 'adventure là danh từ đếm được khi chỉ một trải nghiệm cụ thể, và là danh từ không đếm được khi chỉ tinh thần phiêu lưu.', 'Our camping trip turned into an adventure after dark.', NULL, 'Chuyến đi cắm trại của chúng tôi đã biến thành một cuộc phiêu lưu thực sự sau khi trời tối.', '{"wordId":"adventure","ukIpa":"/ədˈventʃə/","usIpa":"/ədˈventʃər/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"An exciting experience involving uncertainty or possible danger","vi":"chuyến phiêu lưu; cuộc thám hiểm"},{"pos":"n.","en":"Willingness to explore unfamiliar or exciting situations","vi":"tinh thần phiêu lưu"}],"examples":[{"en":"Our camping trip turned into an adventure after dark.","vi":"Chuyến đi cắm trại của chúng tôi đã biến thành một cuộc phiêu lưu thực sự sau khi trời tối.","audioKind":"ex"},{"en":"Outdoor adventure activities can help young people develop confidence and learn to cooperate with others.","vi":"Các hoạt động thám hiểm ngoài trời có thể giúp giới trẻ phát triển sự tự tin và học cách hợp tác với người khác.","audioKind":"ex2"}],"collocations":[{"en":"go on an adventure","vi":"đi phiêu lưu"},{"en":"a sense of adventure","vi":"tinh thần phiêu lưu"},{"en":"adventure tourism","vi":"du lịch mạo hiểm"}],"wordFamily":["adventurous (adj.)","adventurer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"adventure là danh từ đếm được khi chỉ một trải nghiệm cụ thể, và là danh từ không đếm được khi chỉ tinh thần phiêu lưu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suitcase', 'en-a2-5', 'suitcase', '/ˈsuːtkeɪs/', 'A2', 'vali; va-li', 'n.', NULL, NULL, 'suitcase là danh từ đếm được; từ chỉ chung hành lý là luggage không đếm được.', 'Her suitcase was too heavy to lift onto the train.', NULL, 'Chiếc vali của cô ấy quá nặng nên không thể nhấc lên tàu.', '{"wordId":"suitcase","ukIpa":"/ˈsuːtkeɪs/","usIpa":"/ˈsuːtkeɪs/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A case with a handle for carrying clothes when travelling.","vi":"vali; va-li"}],"examples":[{"en":"Her suitcase was too heavy to lift onto the train.","vi":"Chiếc vali của cô ấy quá nặng nên không thể nhấc lên tàu.","audioKind":"ex"},{"en":"Travellers can reduce transport emissions by packing a lighter suitcase and choosing public transport whenever possible.","vi":"Du khách có thể giảm lượng khí thải do di chuyển bằng cách đóng gói vali nhẹ hơn và chọn phương tiện giao thông công cộng bất cứ khi nào có thể.","audioKind":"ex2"}],"collocations":[{"en":"pack a suitcase","vi":"thu dọn vali"},{"en":"unpack a suitcase","vi":"mở vali"},{"en":"a wheeled suitcase","vi":"vali kéo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"suitcase là danh từ đếm được; từ chỉ chung hành lý là luggage không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reach', 'en-a2-5', 'reach', '/riːtʃ/', 'A2', 'đạt tới, chạm tới; đi đến, vươn tới; với tay ra để chạm vào hoặc lấy thứ gì đó; tầm với, tầm ảnh hưởng', 'v.', 'reachable (adj.), unreachable (adj.)', 'Đồng nghĩa: arrive, attain', 'Khi biểu thị ý nghĩa đến nơi chốn, dùng động từ reach trực tiếp với địa điểm, không cần dùng giới từ at.', 'We reached the station just before the rain started.', NULL, 'Chúng tôi đã đến ga ngay trước khi trời mưa.', '{"wordId":"reach","ukIpa":"/riːtʃ/","usIpa":"/riːtʃ/","cefr":"A2","topic":"travel","senses":[{"pos":"v.","en":"to arrive at a place or achieve a particular level","vi":"đạt tới, chạm tới; đi đến, vươn tới"},{"pos":"v.","en":"to stretch out your arm towards something or touch it","vi":"với tay ra để chạm vào hoặc lấy thứ gì đó"},{"pos":"n.","en":"the distance or extent over which something can act","vi":"tầm với, tầm ảnh hưởng"}],"examples":[{"en":"We reached the station just before the rain started.","vi":"Chúng tôi đã đến ga ngay trước khi trời mưa.","audioKind":"ex"},{"en":"Governments must invest in public transport if they hope to reach their targets for reducing urban emissions.","vi":"Chính phủ phải đầu tư vào giao thông công cộng nếu họ hy vọng đạt được các mục tiêu giảm lượng khí thải đô thị.","audioKind":"ex2"}],"collocations":[{"en":"reach a destination","vi":"đến một điểm đến"},{"en":"reach an agreement","vi":"đạt được thỏa thuận"},{"en":"reach for something","vi":"với tay lấy thứ gì đó"},{"en":"out of reach","vi":"ngoài tầm với"}],"wordFamily":["reachable (adj.)","unreachable (adj.)"],"synonyms":["arrive","attain"],"antonyms":[],"tipVi":"Khi biểu thị ý nghĩa đến nơi chốn, dùng động từ reach trực tiếp với địa điểm, không cần dùng giới từ at.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_southwest', 'en-a2-5', 'southwest', '/ˌsaʊθˈwest/', 'A2', 'phía tây nam; miền tây nam; thuộc phía tây nam; ở hướng tây nam; về hướng tây nam', 'n.', 'southwestern (adj.)', 'Trái nghĩa: northeast', 'Tiếng Anh-Anh cũng thường viết là south-west.', 'Our village lies southwest of the nearest town.', NULL, 'Làng của chúng tôi nằm ở phía tây nam của thị trấn gần nhất.', '{"wordId":"southwest","ukIpa":"/ˌsaʊθˈwest/","usIpa":"/ˌsaʊθˈwest/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"the direction between south and west, or an area''s southwestern part","vi":"phía tây nam; miền tây nam"},{"pos":"adj.","en":"in the southwest, or coming from that direction","vi":"thuộc phía tây nam; ở hướng tây nam"},{"pos":"adv.","en":"towards or in the direction between south and west","vi":"về hướng tây nam"}],"examples":[{"en":"Our village lies southwest of the nearest town.","vi":"Làng của chúng tôi nằm ở phía tây nam của thị trấn gần nhất.","audioKind":"ex"},{"en":"The southwest of the country attracts visitors because of its mild climate and varied coastal landscapes.","vi":"Miền tây nam của đất nước thu hút du khách nhờ khí hậu ôn hòa và cảnh quan bờ biển đa dạng.","audioKind":"ex2"}],"collocations":[{"en":"in the southwest","vi":"ở phía tây nam"},{"en":"southwest of","vi":"về phía tây nam của"},{"en":"head southwest","vi":"đi về hướng tây nam"},{"en":"southwest coast","vi":"bờ biển tây nam"}],"wordFamily":["southwestern (adj.)"],"synonyms":[],"antonyms":["northeast"],"tipVi":"Tiếng Anh-Anh cũng thường viết là south-west.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_railway', 'en-a2-5', 'railway', '/ˈreɪlweɪ/', 'A2', 'đường sắt; hệ thống đường sắt', 'n.', 'rail (n.)', 'Đồng nghĩa: railroad', 'railway thường dùng trong tiếng Anh-Anh, tiếng Anh-Mỹ thường dùng railroad.', 'Our house overlooks the railway near the old bridge.', NULL, 'Nhà chúng tôi nhìn ra tuyến đường sắt gần cây cầu cũ.', '{"wordId":"railway","ukIpa":"/ˈreɪlweɪ/","usIpa":"/ˈreɪlweɪ/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"Tracks and services used by trains to transport people or goods.","vi":"đường sắt; hệ thống đường sắt"}],"examples":[{"en":"Our house overlooks the railway near the old bridge.","vi":"Nhà chúng tôi nhìn ra tuyến đường sắt gần cây cầu cũ.","audioKind":"ex"},{"en":"Investment in railway networks can reduce road congestion while improving access to employment in neighbouring cities.","vi":"Đầu tư vào mạng lưới đường sắt có thể giảm tình trạng tắc nghẽn giao thông đồng thời tạo điều kiện thuận lợi cho việc tiếp cận việc làm ở các thành phố lân cận.","audioKind":"ex2"}],"collocations":[{"en":"a railway station","vi":"ga tàu hỏa"},{"en":"a railway line","vi":"tuyến đường sắt"},{"en":"a railway network","vi":"mạng lưới đường sắt"},{"en":"railway infrastructure","vi":"cơ sở hạ tầng đường sắt"}],"wordFamily":["rail (n.)"],"synonyms":["railroad"],"antonyms":[],"tipVi":"railway thường dùng trong tiếng Anh-Anh, tiếng Anh-Mỹ thường dùng railroad.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kilometre', 'en-a2-5', 'kilometre', '/kɪˈlɑːmətər/', 'A2', 'ki-lô-mét, cây số', 'n.', NULL, 'Đồng nghĩa: kilometer', 'Cách viết theo Anh-Anh là "kilometre", còn Anh-Mỹ là "kilometer".', 'The nearest bus stop is about a kilometre away.', NULL, 'Trạm xe buýt gần nhất cách đây khoảng một cây số.', '{"wordId":"kilometre","ukIpa":"/ˈkɪləmiːtə/","usIpa":"/kɪˈlɑːmətər/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A unit of distance equal to one thousand metres.","vi":"ki-lô-mét, cây số"}],"examples":[{"en":"The nearest bus stop is about a kilometre away.","vi":"Trạm xe buýt gần nhất cách đây khoảng một cây số.","audioKind":"ex"},{"en":"Building safe cycle lanes within a kilometre of schools could encourage more children to cycle daily.","vi":"Việc xây dựng các làn đường dành cho xe đạp an toàn trong phạm vi một ki-lô-mét quanh các trường học có thể khuyến khích nhiều trẻ em đạp xe hàng ngày hơn.","audioKind":"ex2"}],"collocations":[{"en":"a kilometre away","vi":"cách một ki-lô-mét"},{"en":"square kilometre","vi":"ki-lô-mét vuông"},{"en":"kilometres per hour","vi":"ki-lô-mét một giờ"}],"wordFamily":[],"synonyms":["kilometer"],"antonyms":[],"tipVi":"Cách viết theo Anh-Anh là \"kilometre\", còn Anh-Mỹ là \"kilometer\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flight', 'en-a2-5', 'flight', '/flaɪt/', 'A2', 'chuyến bay, hành trình đường hàng không; sự bay, khả năng bay; cầu thang (một dải bậc thang liên tục giữa các tầng)', 'n.', 'fly (v.), flying (adj.), flightless (adj.)', NULL, '"A flight of stairs" chỉ một đoạn cầu thang giữa hai tầng hoặc chiếu nghỉ.', 'Our flight leaves early, so we should pack tonight.', NULL, 'Chuyến bay của chúng tôi khởi hành sớm, vì vậy tối nay chúng ta nên chuẩn bị hành lý.', '{"wordId":"flight","ukIpa":"/flaɪt/","usIpa":"/flaɪt/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A journey through the air, especially in an aircraft.","vi":"chuyến bay, hành trình đường hàng không"},{"pos":"n.","en":"The act or ability of moving through the air.","vi":"sự bay, khả năng bay"},{"pos":"n.","en":"A continuous set of stairs between floors or landings.","vi":"cầu thang (một dải bậc thang liên tục giữa các tầng)"}],"examples":[{"en":"Our flight leaves early, so we should pack tonight.","vi":"Chuyến bay của chúng tôi khởi hành sớm, vì vậy tối nay chúng ta nên chuẩn bị hành lý.","audioKind":"ex"},{"en":"Reducing the number of short domestic flights could lower emissions where reliable rail alternatives already exist.","vi":"Việc giảm số lượng các chuyến bay nội địa ngắn có thể làm giảm lượng khí thải ở những nơi đã có các lựa chọn thay thế bằng đường sắt đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"book a flight","vi":"đặt vé máy bay"},{"en":"direct flight","vi":"chuyến bay thẳng"},{"en":"in flight","vi":"đang bay"},{"en":"a flight of stairs","vi":"một cầu thang"}],"wordFamily":["fly (v.)","flying (adj.)","flightless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"\"A flight of stairs\" chỉ một đoạn cầu thang giữa hai tầng hoặc chiếu nghỉ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lorry', 'en-a2-5', 'lorry', '/ˈlɔːri/', 'A2', 'xe tải; xe vận tải lớn', 'n.', NULL, 'Đồng nghĩa: truck', 'lorry chủ yếu dùng trong tiếng Anh-Anh, trong khi tiếng Anh-Mỹ thường dùng truck.', 'A lorry delivered fresh vegetables to the shop.', NULL, 'Một chiếc xe tải đã giao rau củ tươi cho cửa hàng.', '{"wordId":"lorry","ukIpa":"/ˈlɒri/","usIpa":"/ˈlɔːri/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A large road vehicle used for carrying goods.","vi":"xe tải; xe vận tải lớn"}],"examples":[{"en":"A lorry delivered fresh vegetables to the shop.","vi":"Một chiếc xe tải đã giao rau củ tươi cho cửa hàng.","audioKind":"ex"},{"en":"Restricting lorry deliveries during peak hours could reduce congestion and improve road safety in city centres.","vi":"Việc hạn chế xe tải giao hàng trong giờ cao điểm có thể làm giảm ùn tắc và cải thiện an toàn giao thông ở khu vực trung tâm thành phố.","audioKind":"ex2"}],"collocations":[{"en":"lorry driver","vi":"tài xế xe tải"},{"en":"delivery lorry","vi":"xe tải giao hàng"},{"en":"load a lorry","vi":"chất hàng lên xe tải"}],"wordFamily":[],"synonyms":["truck"],"antonyms":[],"tipVi":"lorry chủ yếu dùng trong tiếng Anh-Anh, trong khi tiếng Anh-Mỹ thường dùng truck.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ireland', 'en-a2-5', 'Ireland', '/ˈaɪərlənd/', 'A2', 'quốc gia Ai-len; hòn đảo Ai-len', 'n.', 'Irish (adj.)', NULL, 'Có thể chỉ quốc gia hoặc toàn bộ hòn đảo; Bắc Ai-len thuộc Vương quốc Anh chứ không thuộc quốc gia này.', 'We explored the west coast of Ireland by bicycle.', NULL, 'Chúng tôi đã khám phá bờ biển phía tây của Ai-len bằng xe đạp.', '{"wordId":"ireland","ukIpa":"/ˈaɪələnd/","usIpa":"/ˈaɪərlənd/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"a European country occupying most of the island of Ireland","vi":"quốc gia Ai-len"},{"pos":"n.","en":"an island west of Great Britain","vi":"hòn đảo Ai-len"}],"examples":[{"en":"We explored the west coast of Ireland by bicycle.","vi":"Chúng tôi đã khám phá bờ biển phía tây của Ai-len bằng xe đạp.","audioKind":"ex"},{"en":"Ireland attracts international students through its English-speaking universities and opportunities to experience a different culture.","vi":"Ai-len thu hút sinh viên quốc tế thông qua các trường đại học giảng dạy bằng tiếng Anh và cơ hội trải nghiệm một nền văn hóa khác biệt.","audioKind":"ex2"}],"collocations":[{"en":"in Ireland","vi":"ở Ai-len"},{"en":"the Republic of Ireland","vi":"Cộng hòa Ai-len"},{"en":"the island of Ireland","vi":"hòn đảo Ai-len"},{"en":"rural Ireland","vi":"vùng nông thôn Ai-len"}],"wordFamily":["Irish (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ quốc gia hoặc toàn bộ hòn đảo; Bắc Ai-len thuộc Vương quốc Anh chứ không thuộc quốc gia này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_backpack', 'en-a2-5', 'backpack', '/ˈbækpæk/', 'A2', 'ba lô đeo lưng; đi du lịch ba lô; phượt', 'n.', 'backpacker (n.), backpacking (n.)', 'Đồng nghĩa: rucksack', 'Chỉ ba lô đeo hai vai; trong tiếng Anh - Anh thường dùng rucksack.', 'I packed my lunch and jacket in my backpack.', NULL, 'Tôi đã xếp bữa trưa và áo khoác vào trong ba lô của mình.', '{"wordId":"backpack","ukIpa":"/ˈbækpæk/","usIpa":"/ˈbækpæk/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A bag carried on the back using two shoulder straps.","vi":"ba lô đeo lưng"},{"pos":"v.","en":"To travel carrying your belongings in a backpack.","vi":"đi du lịch ba lô; phượt"}],"examples":[{"en":"I packed my lunch and jacket in my backpack.","vi":"Tôi đã xếp bữa trưa và áo khoác vào trong ba lô của mình.","audioKind":"ex"},{"en":"Young adults often backpack through rural regions, supporting small businesses and learning about local traditions.","vi":"Những người trẻ tuổi thường đi du lịch ba lô qua các vùng nông thôn, hỗ trợ các doanh nghiệp nhỏ và tìm hiểu về các truyền thống địa phương.","audioKind":"ex2"}],"collocations":[{"en":"carry a backpack","vi":"đeo ba lô"},{"en":"pack a backpack","vi":"sắp xếp ba lô hành lý"},{"en":"a hiking backpack","vi":"ba lô leo núi"}],"wordFamily":["backpacker (n.)","backpacking (n.)"],"synonyms":["rucksack"],"antonyms":[],"tipVi":"Chỉ ba lô đeo hai vai; trong tiếng Anh - Anh thường dùng rucksack.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_denmark', 'en-a2-5', 'Denmark', '/ˈdenmɑːrk/', 'A2', 'Đan Mạch', 'n.', 'Danish (adj.), Dane (n.)', NULL, 'Tên quốc gia thường không đi kèm mạo từ the; người Đan Mạch gọi là Dane.', 'My cousin moved to Denmark to study architecture.', NULL, 'Anh họ của tôi đã chuyển đến Đan Mạch để học kiến trúc.', '{"wordId":"denmark","ukIpa":"/ˈdenmɑːk/","usIpa":"/ˈdenmɑːrk/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"a country in northern Europe, with Copenhagen as its capital","vi":"Đan Mạch"}],"examples":[{"en":"My cousin moved to Denmark to study architecture.","vi":"Anh họ của tôi đã chuyển đến Đan Mạch để học kiến trúc.","audioKind":"ex"},{"en":"Denmark offers useful examples of how cycling infrastructure can support healthier and more sustainable urban transport.","vi":"Đan Mạch mang đến những ví dụ hữu ích về cách cơ sở hạ tầng giao thông xe đạp có thể hỗ trợ hệ thống giao thông đô thị lành mạnh và bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"visit Denmark","vi":"thăm Đan Mạch"},{"en":"live in Denmark","vi":"sống ở Đan Mạch"},{"en":"the capital of Denmark","vi":"thủ đô của Đan Mạch"}],"wordFamily":["Danish (adj.)","Dane (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên quốc gia thường không đi kèm mạo từ the; người Đan Mạch gọi là Dane.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thai', 'en-a2-5', 'Thai', '/taɪ/', 'A2', 'thuộc về Thái Lan, người Thái hoặc tiếng Thái; tiếng Thái (ngôn ngữ chính được sử dụng ở Thái Lan); người Thái Lan', 'adj.', NULL, NULL, 'Chữ cái đầu tiên của Thai luôn được viết hoa; tên quốc gia là Thailand.', 'We shared a delicious Thai curry for dinner.', NULL, 'Chúng tôi đã cùng nhau thưởng thức món cà ri Thái ngon tuyệt cho bữa tối.', '{"wordId":"thai","ukIpa":"/taɪ/","usIpa":"/taɪ/","cefr":"A2","topic":"travel","senses":[{"pos":"adj.","en":"relating to Thailand, its people, or its language","vi":"thuộc về Thái Lan, người Thái hoặc tiếng Thái"},{"pos":"n.","en":"the main language spoken in Thailand","vi":"tiếng Thái (ngôn ngữ chính được sử dụng ở Thái Lan)"},{"pos":"n.","en":"a person from Thailand","vi":"người Thái Lan"}],"examples":[{"en":"We shared a delicious Thai curry for dinner.","vi":"Chúng tôi đã cùng nhau thưởng thức món cà ri Thái ngon tuyệt cho bữa tối.","audioKind":"ex"},{"en":"Thai cuisine attracts international visitors and provides valuable opportunities for local restaurants and cooking schools.","vi":"Ẩm thực Thái Lan thu hút du khách quốc tế và mang lại những cơ hội giá trị cho các nhà hàng cũng như trường dạy nấu ăn địa phương.","audioKind":"ex2"}],"collocations":[{"en":"Thai cuisine","vi":"ẩm thực Thái Lan"},{"en":"Thai culture","vi":"văn hóa Thái Lan"},{"en":"speak Thai","vi":"nói tiếng Thái"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái đầu tiên của Thai luôn được viết hoa; tên quốc gia là Thailand.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ship', 'en-a2-5', 'ship', '/ʃɪp/', 'A2', 'tàu thủy; thuyền lớn; vận chuyển; chuyên chở', 'n.', 'shipping (n.), shipment (n.), shipper (n.)', 'Đồng nghĩa: vessel, transport', 'ship khi là động từ không chỉ giới hạn ở đường biển, mà còn có thể chỉ vận chuyển qua đường bộ hoặc đường hàng không.', 'We watched a huge ship glide into the harbour.', NULL, 'Chúng tôi đứng nhìn một con tàu khổng lồ lướt vào cảng.', '{"wordId":"ship","ukIpa":"/ʃɪp/","usIpa":"/ʃɪp/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A large boat carrying people or goods, especially at sea.","vi":"tàu thủy; thuyền lớn"},{"pos":"v.","en":"To send goods somewhere by sea, air, or land.","vi":"vận chuyển; chuyên chở"}],"examples":[{"en":"We watched a huge ship glide into the harbour.","vi":"Chúng tôi đứng nhìn một con tàu khổng lồ lướt vào cảng.","audioKind":"ex"},{"en":"Many countries ship agricultural products overseas, making reliable transport networks essential for economic growth.","vi":"Nhiều quốc gia vận chuyển nông sản ra nước ngoài, điều này làm cho các mạng lưới giao thông đáng tin cậy trở nên thiết yếu đối với tăng trưởng kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"cargo ship","vi":"tàu chở hàng"},{"en":"cruise ship","vi":"tàu du lịch"},{"en":"ship goods","vi":"vận chuyển hàng hóa"},{"en":"on board a ship","vi":"trên tàu thủy"}],"wordFamily":["shipping (n.)","shipment (n.)","shipper (n.)"],"synonyms":["vessel","transport"],"antonyms":[],"tipVi":"ship khi là động từ không chỉ giới hạn ở đường biển, mà còn có thể chỉ vận chuyển qua đường bộ hoặc đường hàng không.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pilot', 'en-a2-5', 'pilot', '/ˈpaɪlət/', 'A2', 'phi công; thử nghiệm; thí điểm; lái (máy bay); điều khiển thử', 'n.', NULL, NULL, 'pilot làm tính từ thường chỉ tính chất thí điểm, ví dụ như pilot project.', 'The pilot landed the plane smoothly despite strong winds.', NULL, 'Phi công hạ cánh máy bay suôn sẻ dù có gió lớn.', '{"wordId":"pilot","ukIpa":"/ˈpaɪlət/","usIpa":"/ˈpaɪlət/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"a person who flies an aircraft","vi":"phi công"},{"pos":"adj.","en":"done on a small scale to test whether something works","vi":"thử nghiệm; thí điểm"},{"pos":"v.","en":"to fly an aircraft or test a new plan","vi":"lái (máy bay); điều khiển thử"}],"examples":[{"en":"The pilot landed the plane smoothly despite strong winds.","vi":"Phi công hạ cánh máy bay suôn sẻ dù có gió lớn.","audioKind":"ex"},{"en":"The council launched a pilot scheme to assess whether free bus travel would reduce traffic congestion.","vi":"Hội đồng đã triển khai một kế hoạch thí điểm để đánh giá xem việc đi xe buýt miễn phí có làm giảm ùn tắc giao thông hay không.","audioKind":"ex2"}],"collocations":[{"en":"airline pilot","vi":"phi công hàng không"},{"en":"pilot scheme","vi":"chương trình thí điểm"},{"en":"pilot study","vi":"nghiên cứu thử nghiệm"},{"en":"pilot a programme","vi":"thí điểm một chương trình"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"pilot làm tính từ thường chỉ tính chất thí điểm, ví dụ như pilot project.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_van', 'en-a2-5', 'van', '/væn/', 'A2', 'xe tải nhỏ; xe van; xe ô tô chở khách loại nhỏ', 'n.', NULL, NULL, 'Thường chỉ loại phương tiện kín chuyên chở hàng hóa; không nên nhầm lẫn với xe tải mui trần.', 'We loaded the boxes into a small white van.', NULL, 'Chúng tôi đã xếp các thùng hàng lên một chiếc xe tải nhỏ màu trắng.', '{"wordId":"van","ukIpa":"/væn/","usIpa":"/væn/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A covered vehicle used to carry goods or people.","vi":"xe tải nhỏ; xe van; xe ô tô chở khách loại nhỏ"}],"examples":[{"en":"We loaded the boxes into a small white van.","vi":"Chúng tôi đã xếp các thùng hàng lên một chiếc xe tải nhỏ màu trắng.","audioKind":"ex"},{"en":"Replacing diesel delivery vans with electric vehicles could help reduce air pollution in densely populated cities.","vi":"Việc thay thế các dòng xe giao hàng chạy bằng dầu diesel bằng xe điện có thể góp phần làm giảm ô nhiễm không khí tại các thành phố đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"delivery van","vi":"xe giao hàng"},{"en":"hire a van","vi":"thuê xe tải nhỏ"},{"en":"load a van","vi":"bốc hàng lên xe tải"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ loại phương tiện kín chuyên chở hàng hóa; không nên nhầm lẫn với xe tải mui trần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hiking', 'en-a2-5', 'hiking', '/ˈhaɪkɪŋ/', 'A2', 'đi bộ đường dài; leo núi; đi dã ngoại (đi dạo dài ở ngoài trời, đặc biệt là vùng nông thôn)', 'n.', 'hike (n.), hike (v.), hiker (n.)', NULL, 'Thường chỉ việc đi bộ đường dài ở vùng quê; cũng có thể đóng vai trò là phân từ hiện tại của động từ hike.', 'These boots keep my feet dry when I go hiking.', NULL, 'Đôi giày này giữ cho đôi chân của tôi luôn khô ráo khi tôi đi leo núi.', '{"wordId":"hiking","ukIpa":"/ˈhaɪkɪŋ/","usIpa":"/ˈhaɪkɪŋ/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"Taking long walks outdoors, especially in the countryside.","vi":"đi bộ đường dài; leo núi; đi dã ngoại (đi dạo dài ở ngoài trời, đặc biệt là vùng nông thôn)"}],"examples":[{"en":"These boots keep my feet dry when I go hiking.","vi":"Đôi giày này giữ cho đôi chân của tôi luôn khô ráo khi tôi đi leo núi.","audioKind":"ex"},{"en":"Hiking offers an affordable way to improve physical health while encouraging people to appreciate natural landscapes.","vi":"Đi bộ đường dài là một hình thức rèn luyện sức khỏe tiết kiệm, đồng thời khuyến khích mọi người trân trọng phong cảnh thiên nhiên.","audioKind":"ex2"}],"collocations":[{"en":"go hiking","vi":"đi bộ đường dài"},{"en":"hiking boots","vi":"giày leo núi"},{"en":"hiking trail","vi":"đường mòn đi bộ"},{"en":"hiking equipment","vi":"dụng cụ đi bộ đường dài"}],"wordFamily":["hike (n.)","hike (v.)","hiker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ việc đi bộ đường dài ở vùng quê; cũng có thể đóng vai trò là phân từ hiện tại của động từ hike.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sightseeing', 'en-a2-5', 'sightseeing', '/ˈsaɪtsiːɪŋ/', 'A2', 'sự tham quan; sự vãn cảnh', 'n.', 'sightsee (v.), sightseer (n.)', NULL, 'Danh từ không đếm được; dùng go sightseeing, không thêm a.', 'We spent the morning sightseeing around the old harbour.', NULL, 'Chúng tôi dành cả buổi sáng để tham quan quanh khu cảng cổ.', '{"wordId":"sightseeing","ukIpa":"/ˈsaɪtsiːɪŋ/","usIpa":"/ˈsaɪtsiːɪŋ/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"the activity of visiting interesting places as a tourist","vi":"sự tham quan; sự vãn cảnh"}],"examples":[{"en":"We spent the morning sightseeing around the old harbour.","vi":"Chúng tôi dành cả buổi sáng để tham quan quanh khu cảng cổ.","audioKind":"ex"},{"en":"Sightseeing tours can support local economies, especially when visitors choose guides and businesses from the community.","vi":"Các chuyến tham quan du lịch có thể hỗ trợ nền kinh tế địa phương, đặc biệt là khi du khách lựa chọn hướng dẫn viên và các doanh nghiệp từ cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"go sightseeing","vi":"đi tham quan"},{"en":"a sightseeing tour","vi":"chuyến tham quan du lịch"},{"en":"a sightseeing bus","vi":"xe buýt tham quan"}],"wordFamily":["sightsee (v.)","sightseer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ không đếm được; dùng go sightseeing, không thêm a.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_travelling', 'en-a2-5', 'travelling', '/ˈtrævəlɪŋ/', 'A2', 'việc đi lại; sự du lịch; lưu động; di chuyển nay đây mai đó; việc di chuyển; hành trình', 'n.', 'travel (v.), travel (n.), traveller (n.)', NULL, 'Cách viết Anh-Anh gấp đôi chữ l (travelling); người Mỹ thường viết là traveling.', 'Travelling by train gives me time to enjoy the scenery.', NULL, 'Đi du lịch bằng tàu hỏa cho tôi thời gian để thưởng ngoạn phong cảnh.', '{"wordId":"travelling","ukIpa":"/ˈtrævəlɪŋ/","usIpa":"/ˈtrævəlɪŋ/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"The activity of going from one place to another","vi":"việc đi lại; sự du lịch"},{"pos":"adj.","en":"Moving between places rather than staying in one location","vi":"lưu động; di chuyển nay đây mai đó"},{"pos":"v.","en":"Going from one place to another","vi":"việc di chuyển; hành trình"}],"examples":[{"en":"Travelling by train gives me time to enjoy the scenery.","vi":"Đi du lịch bằng tàu hỏa cho tôi thời gian để thưởng ngoạn phong cảnh.","audioKind":"ex"},{"en":"Travelling abroad can broaden students'' perspectives by exposing them to different customs and ways of life.","vi":"Đi du lịch nước ngoài có thể mở rộng tầm nhìn của học sinh bằng cách cho các em tiếp xúc với những phong tục và lối sống khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"go travelling","vi":"đi du lịch"},{"en":"travelling abroad","vi":"du lịch nước ngoài"},{"en":"travelling expenses","vi":"chi phí đi lại"},{"en":"a travelling exhibition","vi":"triển lãm lưu động"}],"wordFamily":["travel (v.)","travel (n.)","traveller (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết Anh-Anh gấp đôi chữ l (travelling); người Mỹ thường viết là traveling.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_camp', 'en-a2-5', 'camp', '/kæmp/', 'A2', 'trại; khu cắm trại; cắm trại; dựng lều; trận địa; phe phái', 'n.', 'camping (n.), camper (n.), campsite (n.)', NULL, '"go camping" nghĩa là đi cắm trại; "camp" cũng có thể chỉ một nhóm người có chung quan điểm hoặc mục đích.', 'We returned to camp before the rain started.', NULL, 'Chúng tôi đã quay trở lại trại trước khi trời đổ mưa.', '{"wordId":"camp","ukIpa":"/kæmp/","usIpa":"/kæmp/","cefr":"A2","topic":"travel","senses":[{"pos":"n.","en":"A place where people stay temporarily, often in tents.","vi":"trại; khu cắm trại"},{"pos":"v.","en":"Stay outdoors temporarily in a tent or similar shelter.","vi":"cắm trại; dựng lều"},{"pos":"n.","en":"A group sharing the same opinions or aims.","vi":"trận địa; phe phái"}],"examples":[{"en":"We returned to camp before the rain started.","vi":"Chúng tôi đã quay trở lại trại trước khi trời đổ mưa.","audioKind":"ex"},{"en":"Schools can organise outdoor camps to help students develop independence and learn practical skills beyond the classroom.","vi":"Các trường học có thể tổ chức các chuyến cắm trại ngoài trời để giúp học sinh phát triển tính tự lập và học hỏi các kỹ năng thực tế ngoài lớp học.","audioKind":"ex2"}],"collocations":[{"en":"set up camp","vi":"dựng trại"},{"en":"go camping","vi":"đi cắm trại"},{"en":"a summer camp","vi":"trại hè"},{"en":"opposing camps","vi":"các phe đối lập"}],"wordFamily":["camping (n.)","camper (n.)","campsite (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"go camping\" nghĩa là đi cắm trại; \"camp\" cũng có thể chỉ một nhóm người có chung quan điểm hoặc mục đích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_5_1', 'en-a2-5', 'Cách dùng “adventure” (n.) — chuyến phiêu lưu; cuộc thám hiểm', 'go on an adventure  ·  a sense of adventure  ·  adventure tourism', 'adventure là danh từ đếm được khi chỉ một trải nghiệm cụ thể, và là danh từ không đếm được khi chỉ tinh thần phiêu lưu.', 'Họ từ (Word Family): adventurous (adj.), adventurer (n.)', '[{"hanzi":"Our camping trip turned into an adventure after dark.","pinyin":"","meaning":"Chuyến đi cắm trại của chúng tôi đã biến thành một cuộc phiêu lưu thực sự sau khi trời tối."},{"hanzi":"Outdoor adventure activities can help young people develop confidence and learn to cooperate with others.","pinyin":"","meaning":"Các hoạt động thám hiểm ngoài trời có thể giúp giới trẻ phát triển sự tự tin và học cách hợp tác với người khác."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_5_2', 'en-a2-5', 'Cách dùng “ship” (n.) — tàu thủy; thuyền lớn', 'cargo ship  ·  cruise ship  ·  ship goods', 'ship khi là động từ không chỉ giới hạn ở đường biển, mà còn có thể chỉ vận chuyển qua đường bộ hoặc đường hàng không.', 'Họ từ (Word Family): shipping (n.), shipment (n.), shipper (n.) | Đồng nghĩa: vessel, transport', '[{"hanzi":"We watched a huge ship glide into the harbour.","pinyin":"","meaning":"Chúng tôi đứng nhìn một con tàu khổng lồ lướt vào cảng."},{"hanzi":"Many countries ship agricultural products overseas, making reliable transport networks essential for economic growth.","pinyin":"","meaning":"Nhiều quốc gia vận chuyển nông sản ra nước ngoài, điều này làm cho các mạng lưới giao thông đáng tin cậy trở nên thiết yếu đối với tăng trưởng kinh tế."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_5_3', 'en-a2-5', 'Cách dùng “hiking” (n.) — đi bộ đường dài; leo núi; đi dã ngoại (đi dạo dài ở ngoài trời, đặc biệt là vùng nông thôn)', 'go hiking  ·  hiking boots  ·  hiking trail', 'Thường chỉ việc đi bộ đường dài ở vùng quê; cũng có thể đóng vai trò là phân từ hiện tại của động từ hike.', 'Họ từ (Word Family): hike (n.), hike (v.), hiker (n.)', '[{"hanzi":"These boots keep my feet dry when I go hiking.","pinyin":"","meaning":"Đôi giày này giữ cho đôi chân của tôi luôn khô ráo khi tôi đi leo núi."},{"hanzi":"Hiking offers an affordable way to improve physical health while encouraging people to appreciate natural landscapes.","pinyin":"","meaning":"Đi bộ đường dài là một hình thức rèn luyện sức khỏe tiết kiệm, đồng thời khuyến khích mọi người trân trọng phong cảnh thiên nhiên."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_5_4', 'en-a2-5', 'Cách dùng “camp” (n.) — trại; khu cắm trại', 'set up camp  ·  go camping  ·  a summer camp', '"go camping" nghĩa là đi cắm trại; "camp" cũng có thể chỉ một nhóm người có chung quan điểm hoặc mục đích.', 'Họ từ (Word Family): camping (n.), camper (n.), campsite (n.)', '[{"hanzi":"We returned to camp before the rain started.","pinyin":"","meaning":"Chúng tôi đã quay trở lại trại trước khi trời đổ mưa."},{"hanzi":"Schools can organise outdoor camps to help students develop independence and learn practical skills beyond the classroom.","pinyin":"","meaning":"Các trường học có thể tổ chức các chuyến cắm trại ngoài trời để giúp học sinh phát triển tính tự lập và học hỏi các kỹ năng thực tế ngoài lớp học."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_5_1', 'en-a2-5', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_5_1_1', 'ten_a2_5_1', 'United Kingdom', 'We travelled around the United Kingdom by train last summer.', 'We travelled around the United Kingdom by train last summer.', '/juˌnaɪtɪd ˈkɪŋdəm/', 'Chúng tôi đã đi du lịch khắp Vương quốc Anh bằng tàu hỏa vào mùa hè năm ngoái.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_5_1_2', 'ten_a2_5_1', 'transport', 'We rely on public transport to get around town.', 'We rely on public transport to get around town.', '/ˈtrænspɔːrt/', 'Chúng tôi dựa vào phương tiện giao thông công cộng để đi lại trong thị trấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_5_1_3', 'ten_a2_5_1', 'tram', 'We caught the tram outside the library this morning.', 'We caught the tram outside the library this morning.', '/træm/', 'Chúng tôi đã bắt xe điện bên ngoài thư viện sáng nay.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_5_1_4', 'ten_a2_5_1', 'cross', 'We waited for the traffic to stop before crossing.', 'We waited for the traffic to stop before crossing.', '/krɔːs/', 'Chúng tôi đợi xe cộ dừng lại rồi mới qua đường.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
