INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_5_1_8', 'ten_a2_5_1', 'southwest', 'Our village lies southwest of the nearest town.', 'Our village lies southwest of the nearest town.', '/ˌsaʊθˈwest/', 'Làng của chúng tôi nằm ở phía tây nam của thị trấn gần nhất.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_5_1_1', 'en-a2-5', 'ten_a2_5_1', 'listening', 'listening', 'We travelled around the United Kingdom by train last summer.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã đi du lịch khắp Vương quốc Anh bằng tàu hỏa vào mùa hè năm ngoái.","Làng của chúng tôi nằm ở phía tây nam của thị trấn gần nhất.","Tôi đã xếp bữa trưa và áo khoác vào trong ba lô của mình.","Phi công hạ cánh máy bay suôn sẻ dù có gió lớn."]'::jsonb, 0, 'We travelled around the United Kingdom by train last summer. → Chúng tôi đã đi du lịch khắp Vương quốc Anh bằng tàu hỏa vào mùa hè năm ngoái.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_5_1_2', 'en-a2-5', 'ten_a2_5_1', 'listening', 'listening', 'We rely on public transport to get around town.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã đến ga ngay trước khi trời mưa.","Đôi giày này giữ cho đôi chân của tôi luôn khô ráo khi tôi đi leo núi.","Chúng tôi dựa vào phương tiện giao thông công cộng để đi lại trong thị trấn.","Phi công hạ cánh máy bay suôn sẻ dù có gió lớn."]'::jsonb, 2, 'We rely on public transport to get around town. → Chúng tôi dựa vào phương tiện giao thông công cộng để đi lại trong thị trấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_5_1_3', 'en-a2-5', 'ten_a2_5_1', 'listening', 'listening', 'We caught the tram outside the library this morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chuyến đi cắm trại của chúng tôi đã biến thành một cuộc phiêu lưu thực sự sau khi trời tối.","Chúng tôi đã bắt xe điện bên ngoài thư viện sáng nay.","Chúng tôi đã xếp các thùng hàng lên một chiếc xe tải nhỏ màu trắng.","Chúng tôi dành cả buổi sáng để tham quan quanh khu cảng cổ."]'::jsonb, 1, 'We caught the tram outside the library this morning. → Chúng tôi đã bắt xe điện bên ngoài thư viện sáng nay.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_5_2', 'en-a2-5', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_5_2_1', 'ten_a2_5_2', 'United Kingdom', 'International students in the United Kingdom contribute to university communities through their diverse experiences and perspectives.', 'International students in the United Kingdom contribute to university communities through their diverse experiences and perspectives.', '/juˌnaɪtɪd ˈkɪŋdəm/', 'Sinh viên quốc tế tại Vương quốc Anh đóng góp cho cộng đồng đại học thông qua những trải nghiệm và góc nhìn đa dạng của họ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_5_2_2', 'ten_a2_5_2', 'transport', 'Better transport links between rural areas and cities can expand employment opportunities for local residents.', 'Better transport links between rural areas and cities can expand employment opportunities for local residents.', '/ˈtrænspɔːrt/', 'Các mối liên kết giao thông tốt hơn giữa các vùng nông thôn và thành phố có thể mở rộng cơ hội việc làm cho cư dân địa phương.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_5_2_3', 'ten_a2_5_2', 'tram', 'Investing in tram networks can reduce traffic congestion and improve access to busy city centres.', 'Investing in tram networks can reduce traffic congestion and improve access to busy city centres.', '/træm/', 'Đầu tư vào mạng lưới xe điện có thể làm giảm tắc nghẽn giao thông và giúp việc tiếp cận khu trung tâm thành phố sầm uất trở nên dễ dàng hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_5_2_4', 'ten_a2_5_2', 'cross', 'Safer pedestrian routes encourage residents to cross busy roads on foot rather than drive short distances.', 'Safer pedestrian routes encourage residents to cross busy roads on foot rather than drive short distances.', '/krɔːs/', 'Các tuyến đường dành cho người đi bộ an toàn hơn khuyến khích cư dân đi bộ băng qua các con đường đông đúc thay vì lái xe những quãng đường ngắn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_5_2_5', 'ten_a2_5_2', 'adventure', 'Outdoor adventure activities can help young people develop confidence and learn to cooperate with others.', 'Outdoor adventure activities can help young people develop confidence and learn to cooperate with others.', '/ədˈventʃər/', 'Các hoạt động thám hiểm ngoài trời có thể giúp giới trẻ phát triển sự tự tin và học cách hợp tác với người khác.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_5_2_6', 'ten_a2_5_2', 'suitcase', 'Travellers can reduce transport emissions by packing a lighter suitcase and choosing public transport whenever possible.', 'Travellers can reduce transport emissions by packing a lighter suitcase and choosing public transport whenever possible.', '/ˈsuːtkeɪs/', 'Du khách có thể giảm lượng khí thải do di chuyển bằng cách đóng gói vali nhẹ hơn và chọn phương tiện giao thông công cộng bất cứ khi nào có thể.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_5_2_1', 'en-a2-5', 'ten_a2_5_2', 'listening', 'listening', 'International students in the United Kingdom contribute to university communities through their diverse experiences and perspectives.', NULL, 'Trong câu vừa nghe, từ “United Kingdom” mang nghĩa nào sau đây?', '["Vương quốc Anh; Vương quốc Liên hiệp Anh và Bắc Ireland","hình tròn; vòng tròn","về phía trước; hướng về tương lai","ở bất cứ đâu; đến bất cứ nơi nào"]'::jsonb, 0, '“United Kingdom” (/juˌnaɪtɪd ˈkɪŋdəm/): Vương quốc Anh; Vương quốc Liên hiệp Anh và Bắc Ireland. Câu đầy đủ: International students in the United Kingdom contribute to university communities through their diverse experiences and perspectives.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_5_2_2', 'en-a2-5', 'ten_a2_5_2', 'listening', 'listening', 'Better transport links between rural areas and cities can expand employment opportunities for local residents.', NULL, 'Trong câu vừa nghe, từ “transport” mang nghĩa nào sau đây?', '["hệ thống tàu điện ngầm","hướng dẫn viên; người dẫn đường","giao thông vận tải; phương tiện giao thông","bờ biển; vùng duyên hải"]'::jsonb, 2, '“transport” (/ˈtrænspɔːrt/): giao thông vận tải; phương tiện giao thông. Câu đầy đủ: Better transport links between rural areas and cities can expand employment opportunities for local residents.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
