INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_5_2', 'en-a2-5', NULL, 'comprehensive_test', 'listening', 'We rely on public transport to get around town.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã bắt xe điện bên ngoài thư viện sáng nay.","Chúng tôi đã khám phá bờ biển phía tây của Ai-len bằng xe đạp.","Làng của chúng tôi nằm ở phía tây nam của thị trấn gần nhất.","Chúng tôi dựa vào phương tiện giao thông công cộng để đi lại trong thị trấn."]'::jsonb, 3, 'We rely on public transport to get around town. → Chúng tôi dựa vào phương tiện giao thông công cộng để đi lại trong thị trấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
