INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_5_4', 'en-a2-5', NULL, 'comprehensive_test', 'listening', 'We waited for the traffic to stop before crossing.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một chiếc xe tải đã giao rau củ tươi cho cửa hàng.","Phi công hạ cánh máy bay suôn sẻ dù có gió lớn.","Chúng tôi đã quay trở lại trại trước khi trời đổ mưa.","Chúng tôi đợi xe cộ dừng lại rồi mới qua đường."]'::jsonb, 3, 'We waited for the traffic to stop before crossing. → Chúng tôi đợi xe cộ dừng lại rồi mới qua đường.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
