INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_5_6', 'en-a2-5', NULL, 'comprehensive_test', 'listening', 'Her suitcase was too heavy to lift onto the train.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc vali của cô ấy quá nặng nên không thể nhấc lên tàu.","Chúng tôi đã cùng nhau thưởng thức món cà ri Thái ngon tuyệt cho bữa tối.","Nhà chúng tôi nhìn ra tuyến đường sắt gần cây cầu cũ.","Chúng tôi đã xếp các thùng hàng lên một chiếc xe tải nhỏ màu trắng."]'::jsonb, 0, 'Her suitcase was too heavy to lift onto the train. → Chiếc vali của cô ấy quá nặng nên không thể nhấc lên tàu.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
