INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_5_18', 'en-a2-5', NULL, 'comprehensive_test', 'reading', NULL, 'International students in the United Kingdom contribute to university communities through their diverse experiences and perspectives.', 'Dựa vào câu trên, từ “United Kingdom” có nghĩa phù hợp nhất là gì?', '["Vương quốc Anh; Vương quốc Liên hiệp Anh và Bắc Ireland","cuộc thảo luận; sự bàn bạc","con lừa","nữa; không... nữa"]'::jsonb, 0, 'United Kingdom: Vương quốc Anh; Vương quốc Liên hiệp Anh và Bắc Ireland. Dịch cả câu: Sinh viên quốc tế tại Vương quốc Anh đóng góp cho cộng đồng đại học thông qua những trải nghiệm và góc nhìn đa dạng của họ.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_5_19', 'en-a2-5', NULL, 'comprehensive_test', 'reading', NULL, 'Better transport links between rural areas and cities can expand employment opportunities for local residents.', 'Dựa vào câu trên, từ “transport” có nghĩa phù hợp nhất là gì?', '["diều","anh chị em sinh đôi","giao thông vận tải; phương tiện giao thông","loại; kiểu"]'::jsonb, 2, 'transport: giao thông vận tải; phương tiện giao thông; vận chuyển; chuyên chở. Dịch cả câu: Các mối liên kết giao thông tốt hơn giữa các vùng nông thôn và thành phố có thể mở rộng cơ hội việc làm cho cư dân địa phương.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_5_20', 'en-a2-5', NULL, 'comprehensive_test', 'reading', NULL, 'Investing in tram networks can reduce traffic congestion and improve access to busy city centres.', 'Dựa vào câu trên, từ “tram” có nghĩa phù hợp nhất là gì?', '["xe điện; tàu điện","nam nhân viên bán hàng; nam nhân viên tiếp thị","có sương mù, mờ mịt","phương pháp; cách thức"]'::jsonb, 0, 'tram: xe điện; tàu điện. Dịch cả câu: Đầu tư vào mạng lưới xe điện có thể làm giảm tắc nghẽn giao thông và giúp việc tiếp cận khu trung tâm thành phố sầm uất trở nên dễ dàng hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_5_21', 'en-a2-5', NULL, 'comprehensive_test', 'reading', NULL, 'Safer pedestrian routes encourage residents to cross busy roads on foot rather than drive short distances.', 'Dựa vào câu trên, từ “cross” có nghĩa phù hợp nhất là gì?', '["đi qua; băng qua; giao nhau","tiếp tục","có sẵn; có thể mua/dùng được","tương cà chua"]'::jsonb, 0, 'cross: đi qua; băng qua; giao nhau; hình chữ thập; ký hiệu chữ thập; cây thánh giá; bực mình; cáu kỉnh. Dịch cả câu: Các tuyến đường dành cho người đi bộ an toàn hơn khuyến khích cư dân đi bộ băng qua các con đường đông đúc thay vì lái xe những quãng đường ngắn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_5_22', 'en-a2-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự tham quan; sự vãn cảnh”', '["method","sightseeing","forest","snowboarding"]'::jsonb, 1, 'sự tham quan; sự vãn cảnh → sightseeing (/ˈsaɪtsiːɪŋ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_5_23', 'en-a2-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “việc đi lại; sự du lịch”', '["adventure","scissors","against","travelling"]'::jsonb, 3, 'việc đi lại; sự du lịch → travelling (/ˈtrævəlɪŋ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_5_24', 'en-a2-5', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “trại; khu cắm trại”', '["chance","camp","borrow","oil"]'::jsonb, 1, 'trại; khu cắm trại → camp (/kæmp/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-6', 'en', 'Bài 6: Xã hội & Cộng đồng (1) - CEFR A2', 'CEFR A2', 'A2 · Xã hội', '27 từ vựng Tiếng Anh CEFR A2 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2006, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_male', 'en-a2-6', 'male', '/meɪl/', 'A2', 'thuộc nam giới; thuộc giống đực; nam giới; con đực', 'adj.', 'maleness (n.)', 'Trái nghĩa: female', 'male có thể làm tính từ hoặc danh từ; chỉ đàn ông trong đời thường thường dùng man.', 'The male duck has a shiny green head.', NULL, 'Con vịt đực có cái đầu màu xanh lục lấp lánh.', '{"wordId":"male","ukIpa":"/meɪl/","usIpa":"/meɪl/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"Relating to men or boys, or the sex that produces sperm.","vi":"thuộc nam giới; thuộc giống đực"},{"pos":"n.","en":"A male person or animal.","vi":"nam giới; con đực"}],"examples":[{"en":"The male duck has a shiny green head.","vi":"Con vịt đực có cái đầu màu xanh lục lấp lánh.","audioKind":"ex"},{"en":"Encouraging more male applicants to enter nursing could help address staff shortages and challenge gender stereotypes.","vi":"Việc khuyến khích nhiều nam ứng viên tham gia ngành điều dưỡng có thể giúp giải quyết tình trạng thiếu nhân lực và phá vỡ các định kiến giới.","audioKind":"ex2"}],"collocations":[{"en":"male students","vi":"nam sinh"},{"en":"male nurse","vi":"nam y tá"},{"en":"male and female","vi":"nam và nữ; đực và cái"}],"wordFamily":["maleness (n.)"],"synonyms":[],"antonyms":["female"],"tipVi":"male có thể làm tính từ hoặc danh từ; chỉ đàn ông trong đời thường thường dùng man.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rude', 'en-a2-6', 'rude', '/ruːd/', 'A2', 'thất lễ; thô lỗ; bất lịch sự', 'adj.', 'rudely (adv.), rudeness (n.)', 'Đồng nghĩa: impolite, disrespectful · Trái nghĩa: polite, courteous', 'Cấu trúc "rude to someone" dùng để chỉ thái độ vô lễ với ai đó, không dùng "rude with".', 'It was rude to interrupt her during dinner.', NULL, 'Thật là bất lịch sự khi cắt ngang lời cô ấy trong bữa tối.', '{"wordId":"rude","ukIpa":"/ruːd/","usIpa":"/ruːd/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"speaking or behaving without respect for others","vi":"thất lễ; thô lỗ; bất lịch sự"}],"examples":[{"en":"It was rude to interrupt her during dinner.","vi":"Thật là bất lịch sự khi cắt ngang lời cô ấy trong bữa tối.","audioKind":"ex"},{"en":"Schools should teach children how to disagree respectfully without making rude comments about others.","vi":"Nhà trường nên dạy học sinh cách thể hiện sự bất đồng một cách tôn trọng mà không đưa ra những nhận xét thô lỗ về người khác.","audioKind":"ex2"}],"collocations":[{"en":"rude to someone","vi":"thất lễ với ai đó"},{"en":"rude behaviour","vi":"hành vi thô lỗ"},{"en":"rude remark","vi":"lời nói khiếm nhã"}],"wordFamily":["rudely (adv.)","rudeness (n.)"],"synonyms":["impolite","disrespectful"],"antonyms":["polite","courteous"],"tipVi":"Cấu trúc \"rude to someone\" dùng để chỉ thái độ vô lễ với ai đó, không dùng \"rude with\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dutch', 'en-a2-6', 'Dutch', '/dʌtʃ/', 'A2', 'thuộc Hà Lan; của người Hà Lan; tiếng Hà Lan; người Hà Lan', 'adj.', NULL, NULL, 'Dutch viết hoa chữ cái đầu; the Dutch dùng để chỉ chung người Hà Lan.', 'Our Dutch neighbour taught us how to bake apple pie.', NULL, 'Người hàng xóm gốc Hà Lan của chúng tôi đã dạy chúng tôi cách nướng bánh táo.', '{"wordId":"dutch","ukIpa":"/dʌtʃ/","usIpa":"/dʌtʃ/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"Relating to the Netherlands, its people, or their language.","vi":"thuộc Hà Lan; của người Hà Lan"},{"pos":"n.","en":"The language spoken in the Netherlands and parts of Belgium.","vi":"tiếng Hà Lan"},{"pos":"n.","en":"The people of the Netherlands, considered as a group.","vi":"người Hà Lan"}],"examples":[{"en":"Our Dutch neighbour taught us how to bake apple pie.","vi":"Người hàng xóm gốc Hà Lan của chúng tôi đã dạy chúng tôi cách nướng bánh táo.","audioKind":"ex"},{"en":"Dutch cities are often studied by urban planners seeking to develop safer and more accessible cycling networks.","vi":"Các thành phố của Hà Lan thường được nghiên cứu bởi các nhà quy hoạch đô thị muốn phát triển các mạng lưới đi xe đạp an toàn và dễ tiếp cận hơn.","audioKind":"ex2"}],"collocations":[{"en":"Dutch culture","vi":"văn hóa Hà Lan"},{"en":"speak Dutch","vi":"nói tiếng Hà Lan"},{"en":"the Dutch","vi":"người Hà Lan"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dutch viết hoa chữ cái đầu; the Dutch dùng để chỉ chung người Hà Lan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_social', 'en-a2-6', 'social', '/ˈsoʊʃəl/', 'A2', 'thuộc về xã hội; mang tính giao lưu; thuộc về giao tiếp xã hội; sống bầy đàn', 'adj.', 'society (n), socially (adv), socialise (v), socialisation (n)', NULL, 'social dùng để chỉ các vấn đề thuộc xã hội hoặc giao lưu; còn sociable dùng để chỉ người cởi mở, thích giao thiệp.', 'My new job leaves little time for social activities.', NULL, 'Công việc mới khiến tôi gần như không còn thời gian cho các hoạt động xã hội.', '{"wordId":"social","ukIpa":"/ˈsəʊʃəl/","usIpa":"/ˈsoʊʃəl/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"relating to society and how people live together","vi":"thuộc về xã hội"},{"pos":"adj.","en":"relating to meeting people and spending time with them","vi":"mang tính giao lưu; thuộc về giao tiếp xã hội"},{"pos":"adj.","en":"living naturally in organised groups rather than alone","vi":"sống bầy đàn"}],"examples":[{"en":"My new job leaves little time for social activities.","vi":"Công việc mới khiến tôi gần như không còn thời gian cho các hoạt động xã hội.","audioKind":"ex"},{"en":"Affordable housing policies can reduce social inequality by helping families access safe homes near essential services.","vi":"Các chính sách nhà ở vừa túi tiền có thể làm giảm tình trạng bất bình đẳng xã hội bằng cách giúp các gia đình tiếp cận nhà ở an toàn gần các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"social inequality","vi":"bất bình đẳng xã hội"},{"en":"social skills","vi":"kỹ năng giao tiếp xã hội"},{"en":"social activities","vi":"hoạt động xã hội"},{"en":"social change","vi":"sự thay đổi xã hội"}],"wordFamily":["society (n)","socially (adv)","socialise (v)","socialisation (n)"],"synonyms":[],"antonyms":[],"tipVi":"social dùng để chỉ các vấn đề thuộc xã hội hoặc giao lưu; còn sociable dùng để chỉ người cởi mở, thích giao thiệp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grandson', 'en-a2-6', 'grandson', '/ˈɡrænsʌn/', 'A2', 'cháu trai (con của con trai hoặc con gái)', 'n.', 'granddaughter (n.), grandchild (n.), grandparent (n.)', NULL, 'Không phân biệt nội ngoại, dùng chung cho cả cháu trai nội và cháu trai ngoại.', 'Her grandson visits every Sunday and helps with cooking.', NULL, 'Cháu trai của bà đến thăm vào mỗi Chủ nhật và giúp nấu ăn.', '{"wordId":"grandson","ukIpa":"/ˈɡrænsʌn/","usIpa":"/ˈɡrænsʌn/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"the son of your son or daughter","vi":"cháu trai (con của con trai hoặc con gái)"}],"examples":[{"en":"Her grandson visits every Sunday and helps with cooking.","vi":"Cháu trai của bà đến thăm vào mỗi Chủ nhật và giúp nấu ăn.","audioKind":"ex"},{"en":"Regular contact with a grandson or granddaughter can help older adults feel more socially connected.","vi":"Việc thường xuyên liên lạc với cháu trai hoặc cháu gái có thể giúp người cao tuổi cảm thấy gắn kết hơn với xã hội.","audioKind":"ex2"}],"collocations":[{"en":"youngest grandson","vi":"cháu trai út"},{"en":"eldest grandson","vi":"cháu trai trưởng"}],"wordFamily":["granddaughter (n.)","grandchild (n.)","grandparent (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Không phân biệt nội ngoại, dùng chung cho cả cháu trai nội và cháu trai ngoại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flag', 'en-a2-6', 'flag', '/flæɡ/', 'A2', 'lá cờ; quốc kỳ; đánh dấu; nêu vấn đề; suy giảm; giảm sút năng lượng', 'n.', 'flagging (adj.)', NULL, 'Dạng quá khứ của động từ là flagged, dạng V-ing là flagging, gấp đôi chữ g.', 'A bright flag fluttered above the school gate.', NULL, 'Một lá cờ rực rỡ bay phấp phới phía trên cổng trường.', '{"wordId":"flag","ukIpa":"/flæɡ/","usIpa":"/flæɡ/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"a cloth symbol representing a country, group, or organisation","vi":"lá cờ; quốc kỳ"},{"pos":"v.","en":"to mark something as needing attention","vi":"đánh dấu; nêu vấn đề"},{"pos":"v.","en":"to become weaker or less energetic","vi":"suy giảm; giảm sút năng lượng"}],"examples":[{"en":"A bright flag fluttered above the school gate.","vi":"Một lá cờ rực rỡ bay phấp phới phía trên cổng trường.","audioKind":"ex"},{"en":"Teachers should flag potential learning difficulties early so that students can receive appropriate support.","vi":"Giáo viên nên sớm nêu lên các khó khăn học tập tiềm ẩn để học sinh nhận được sự hỗ trợ phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"raise a flag","vi":"kéo cờ lên"},{"en":"national flag","vi":"quốc kỳ"},{"en":"flag an issue","vi":"đánh dấu một vấn đề"},{"en":"flagging energy","vi":"năng lượng đang giảm dần"}],"wordFamily":["flagging (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ của động từ là flagged, dạng V-ing là flagging, gấp đôi chữ g.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_marry', 'en-a2-6', 'marry', '/ˈmæri/', 'A2', 'kết hôn với ai; lập gia đình; làm lễ kết hôn cho ai', 'v.', 'marriage (n.), married (adj.), unmarried (adj.), remarry (v.)', 'Đồng nghĩa: wed · Trái nghĩa: divorce', 'Dùng "marry someone" hoặc "get married to", không dùng "marry with".', 'My cousin plans to marry her partner next spring.', NULL, 'Anh họ của tôi dự định kết hôn với bạn đời vào mùa xuân tới.', '{"wordId":"marry","ukIpa":"/ˈmæri/","usIpa":"/ˈmæri/","cefr":"A2","topic":"society","senses":[{"pos":"v.","en":"To become someone''s husband or wife.","vi":"kết hôn với ai; lập gia đình"},{"pos":"v.","en":"To perform the ceremony that makes two people legally married.","vi":"làm lễ kết hôn cho ai"}],"examples":[{"en":"My cousin plans to marry her partner next spring.","vi":"Anh họ của tôi dự định kết hôn với bạn đời vào mùa xuân tới.","audioKind":"ex"},{"en":"Many young adults choose to marry later because they want financial stability before starting a family.","vi":"Nhiều người trẻ chọn kết hôn muộn hơn vì họ muốn có nền tảng kinh tế ổn định trước khi lập gia đình.","audioKind":"ex2"}],"collocations":[{"en":"marry someone","vi":"kết hôn với ai"},{"en":"get married","vi":"lấy nhau"},{"en":"marry young","vi":"kết hôn khi còn trẻ"}],"wordFamily":["marriage (n.)","married (adj.)","unmarried (adj.)","remarry (v.)"],"synonyms":["wed"],"antonyms":["divorce"],"tipVi":"Dùng \"marry someone\" hoặc \"get married to\", không dùng \"marry with\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mother-in-law', 'en-a2-6', 'mother-in-law', '/ˈmʌðər ɪn lɔː/', 'A2', 'mẹ chồng; mẹ vợ', 'n.', NULL, NULL, 'Chỉ mẹ của chồng hoặc vợ; dạng số nhiều là mothers-in-law.', 'My mother-in-law taught me how to grow tomatoes.', NULL, 'Mẹ chồng tôi đã dạy tôi cách trồng cà chua.', '{"wordId":"mother-in-law","ukIpa":"/ˈmʌðər ɪn lɔː/","usIpa":"/ˈmʌðər ɪn lɔː/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"the mother of your husband or wife","vi":"mẹ chồng; mẹ vợ"}],"examples":[{"en":"My mother-in-law taught me how to grow tomatoes.","vi":"Mẹ chồng tôi đã dạy tôi cách trồng cà chua.","audioKind":"ex"},{"en":"Support from a mother-in-law can reduce childcare costs and allow parents to continue their education.","vi":"Sự hỗ trợ từ mẹ chồng hoặc mẹ vợ có thể giúp giảm chi phí chăm sóc trẻ và tạo điều kiện để các bậc cha mẹ tiếp tục việc học.","audioKind":"ex2"}],"collocations":[{"en":"future mother-in-law","vi":"mẹ chồng tương lai hoặc mẹ vợ tương lai"},{"en":"supportive mother-in-law","vi":"mẹ chồng hoặc mẹ vợ chu đáo, ủng hộ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ mẹ của chồng hoặc vợ; dạng số nhiều là mothers-in-law.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_polite', 'en-a2-6', 'polite', '/pəˈlaɪt/', 'A2', 'lịch sự; nhã nhặn', 'adj.', 'politely (adv.), politeness (n.), impolite (adj.)', 'Đồng nghĩa: courteous, respectful · Trái nghĩa: rude, impolite', 'Dùng cấu trúc be polite to ai đó, không dùng polite with.', 'The polite child held the door open for us.', NULL, 'Đứa trẻ ngoan ngoãn và lịch sự đã giữ cửa giúp chúng tôi.', '{"wordId":"polite","ukIpa":"/pəˈlaɪt/","usIpa":"/pəˈlaɪt/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"Showing respect and consideration for other people.","vi":"lịch sự; nhã nhặn"}],"examples":[{"en":"The polite child held the door open for us.","vi":"Đứa trẻ ngoan ngoãn và lịch sự đã giữ cửa giúp chúng tôi.","audioKind":"ex"},{"en":"Polite communication in the workplace can reduce misunderstandings and help employees build stronger professional relationships.","vi":"Giao tiếp lịch sự ở nơi làm việc có thể giảm bớt sự hiểu lầm và giúp nhân viên xây dựng các mối quan hệ công việc bền chặt hơn.","audioKind":"ex2"}],"collocations":[{"en":"polite to someone","vi":"lịch sự với ai đó"},{"en":"polite request","vi":"yêu cầu lịch sự"},{"en":"polite conversation","vi":"cuộc trò chuyện lịch sự"},{"en":"polite refusal","vi":"lời từ chối khéo léo"}],"wordFamily":["politely (adv.)","politeness (n.)","impolite (adj.)"],"synonyms":["courteous","respectful"],"antonyms":["rude","impolite"],"tipVi":"Dùng cấu trúc be polite to ai đó, không dùng polite with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fair', 'en-a2-6', 'fair', '/fer/', 'A2', 'công bằng; hợp lý; có làn da trắng hoặc tóc sáng màu; hội chợ; triển lãm thương mại', 'adj.', 'fairly (adv.), fairness (n.), unfair (adj.)', 'Đồng nghĩa: just, equitable · Trái nghĩa: unfair', 'fair chỉ sự công bằng trong đối xử; fairly còn có thể mang nghĩa là "tương đối".', 'We took turns choosing games to keep things fair.', NULL, 'Chúng tôi luân phiên chọn trò chơi để mọi thứ được công bằng.', '{"wordId":"fair","ukIpa":"/feə/","usIpa":"/fer/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"treating people equally or reasonably","vi":"công bằng; hợp lý"},{"pos":"adj.","en":"having pale skin or light hair","vi":"có làn da trắng hoặc tóc sáng màu"},{"pos":"n.","en":"an event where people display or sell goods and services","vi":"hội chợ; triển lãm thương mại"}],"examples":[{"en":"We took turns choosing games to keep things fair.","vi":"Chúng tôi luân phiên chọn trò chơi để mọi thứ được công bằng.","audioKind":"ex"},{"en":"A fair education system should give every child access to quality teaching, regardless of family income.","vi":"Một hệ thống giáo dục công bằng nên trao cho mọi trẻ em cơ hội tiếp cận nền giáo dục chất lượng, không phân biệt thu nhập gia đình.","audioKind":"ex2"}],"collocations":[{"en":"fair treatment","vi":"đối xử công bằng"},{"en":"a fair price","vi":"một mức giá hợp lý"},{"en":"fair hair","vi":"tóc sáng màu"},{"en":"trade fair","vi":"hội chợ thương mại"}],"wordFamily":["fairly (adv.)","fairness (n.)","unfair (adj.)"],"synonyms":["just","equitable"],"antonyms":["unfair"],"tipVi":"fair chỉ sự công bằng trong đối xử; fairly còn có thể mang nghĩa là \"tương đối\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_frenchman', 'en-a2-6', 'Frenchman', '/ˈfrentʃmən/', 'A2', 'người đàn ông Pháp; nam công dân Pháp', 'n.', 'French (adj.), Frenchwoman (n.)', NULL, 'Viết hoa chữ cái đầu, số nhiều là Frenchmen; không phân biệt giới tính dùng French person.', 'A Frenchman on the train helped me lift my suitcase.', NULL, 'Một người đàn ông Pháp trên tàu đã giúp tôi nhấc chiếc vali lên.', '{"wordId":"frenchman","ukIpa":"/ˈfrentʃmən/","usIpa":"/ˈfrentʃmən/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"a man who is French","vi":"người đàn ông Pháp; nam công dân Pháp"}],"examples":[{"en":"A Frenchman on the train helped me lift my suitcase.","vi":"Một người đàn ông Pháp trên tàu đã giúp tôi nhấc chiếc vali lên.","audioKind":"ex"},{"en":"The exhibition explores how a Frenchman adapted to life abroad while maintaining connections with his home culture.","vi":"Cuộc triển lãm khám phá cách một người đàn ông Pháp thích nghi với cuộc sống ở nước ngoài trong khi vẫn duy trì kết nối với nền văn hóa quê hương.","audioKind":"ex2"}],"collocations":[{"en":"a young Frenchman","vi":"một thanh niên người Pháp"},{"en":"a native Frenchman","vi":"một người đàn ông Pháp chính gốc"}],"wordFamily":["French (adj.)","Frenchwoman (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Viết hoa chữ cái đầu, số nhiều là Frenchmen; không phân biệt giới tính dùng French person.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_competition', 'en-a2-6', 'competition', '/ˌkɑːmpəˈtɪʃən/', 'A2', 'sự cạnh tranh; sự tranh đua; cuộc thi; cuộc đua tài', 'n.', 'compete (v.), competitive (adj.), competitor (n.), competitiveness (n.)', 'Đồng nghĩa: rivalry, contest · Trái nghĩa: cooperation', 'Chỉ tính chất cạnh tranh thường không đếm được; chỉ một sự kiện thi đấu cụ thể thì đếm được.', 'Our school is holding a painting competition next Friday.', NULL, 'Trường chúng tôi sẽ tổ chức một cuộc thi vẽ tranh vào thứ Sáu tới.', '{"wordId":"competition","ukIpa":"/ˌkɒmpəˈtɪʃən/","usIpa":"/ˌkɑːmpəˈtɪʃən/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"The effort to succeed against others seeking the same goal.","vi":"sự cạnh tranh; sự tranh đua"},{"pos":"n.","en":"An organised event in which people try to win.","vi":"cuộc thi; cuộc đua tài"}],"examples":[{"en":"Our school is holding a painting competition next Friday.","vi":"Trường chúng tôi sẽ tổ chức một cuộc thi vẽ tranh vào thứ Sáu tới.","audioKind":"ex"},{"en":"Competition between businesses can lower prices, but effective regulation is needed to protect consumers from unfair practices.","vi":"Cạnh tranh giữa các doanh nghiệp có thể làm giảm giá cả, nhưng cần phải có sự quản lý hiệu quả để bảo vệ người tiêu dùng khỏi các hành vi thương mại không công bằng.","audioKind":"ex2"}],"collocations":[{"en":"fierce competition","vi":"cạnh tranh khốc liệt"},{"en":"competition for jobs","vi":"cạnh tranh tìm việc làm"},{"en":"enter a competition","vi":"tham gia một cuộc thi"},{"en":"win a competition","vi":"chiến thắng trong một cuộc thi"}],"wordFamily":["compete (v.)","competitive (adj.)","competitor (n.)","competitiveness (n.)"],"synonyms":["rivalry","contest"],"antonyms":["cooperation"],"tipVi":"Chỉ tính chất cạnh tranh thường không đếm được; chỉ một sự kiện thi đấu cụ thể thì đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_god', 'en-a2-6', 'God', '/ɡɑːd/', 'A2', 'Thượng Đế; Chúa; vị thần tối cao', 'n.', 'godly (adj.), godless (adj.), godliness (n.)', NULL, 'Khi chỉ đấng tối cao duy nhất, dùng God thường không kèm mạo từ; khi chỉ thần linh chung chung, dùng god.', 'My grandmother thanks God before each meal at home.', NULL, 'Bà tôi cảm ơn Thượng Đế trước mỗi bữa ăn ở nhà.', '{"wordId":"god","ukIpa":"/ɡɒd/","usIpa":"/ɡɑːd/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"The supreme being worshipped in religions believing in one god.","vi":"Thượng Đế; Chúa; vị thần tối cao"}],"examples":[{"en":"My grandmother thanks God before each meal at home.","vi":"Bà tôi cảm ơn Thượng Đế trước mỗi bữa ăn ở nhà.","audioKind":"ex"},{"en":"Belief in God can influence people''s values, charitable activities, and responses to difficult circumstances.","vi":"Niềm tin vào Thượng Đế có thể ảnh hưởng đến giá trị sống, các hoạt động từ thiện và cách mọi người đối phó với hoàn cảnh khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"believe in God","vi":"tin vào Chúa"},{"en":"pray to God","vi":"cầu nguyện với Chúa"},{"en":"faith in God","vi":"niềm tin vào Chúa"}],"wordFamily":["godly (adj.)","godless (adj.)","godliness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ đấng tối cao duy nhất, dùng God thường không kèm mạo từ; khi chỉ thần linh chung chung, dùng god.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_swedish', 'en-a2-6', 'Swedish', '/ˈswiːdɪʃ/', 'A2', 'thuộc về Thụy Điển, người Thụy Điển hoặc tiếng Thụy Điển; tiếng Thụy Điển', 'adj.', 'Sweden (n.), Swede (n.)', NULL, 'Luôn viết hoa chữ cái đầu; một người Thụy Điển dùng từ a Swede.', 'Our Swedish neighbour taught us to bake cinnamon buns.', NULL, 'Người hàng xóm người Thụy Điển của chúng tôi đã dạy chúng tôi cách nướng bánh mì quế.', '{"wordId":"swedish","ukIpa":"/ˈswiːdɪʃ/","usIpa":"/ˈswiːdɪʃ/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"relating to Sweden, its people, or its language","vi":"thuộc về Thụy Điển, người Thụy Điển hoặc tiếng Thụy Điển"},{"pos":"n.","en":"the main language spoken in Sweden","vi":"tiếng Thụy Điển"}],"examples":[{"en":"Our Swedish neighbour taught us to bake cinnamon buns.","vi":"Người hàng xóm người Thụy Điển của chúng tôi đã dạy chúng tôi cách nướng bánh mì quế.","audioKind":"ex"},{"en":"Swedish cities offer useful examples of how urban planning can support cycling and reduce dependence on cars.","vi":"Các thành phố ở Thụy Điển cung cấp những ví dụ hữu ích về cách quy hoạch đô thị có thể hỗ trợ việc đạp xe và giảm sự phụ thuộc vào ô tô.","audioKind":"ex2"}],"collocations":[{"en":"Swedish culture","vi":"văn hóa Thụy Điển"},{"en":"learn Swedish","vi":"học tiếng Thụy Điển"},{"en":"Swedish design","vi":"thiết kế Thụy Điển"}],"wordFamily":["Sweden (n.)","Swede (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Luôn viết hoa chữ cái đầu; một người Thụy Điển dùng từ a Swede.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_divorced', 'en-a2-6', 'divorced', '/dɪˈvɔːrst/', 'A2', 'đã ly hôn; tách rời; tách biệt', 'adj.', 'divorce (n.), divorce (v.)', 'Trái nghĩa: married', 'get divorced dùng để chỉ hành động ly hôn; sự tách biệt khỏi cái gì dùng cấu trúc divorced from.', 'My divorced uncle lives happily near his children.', NULL, 'Người chú đã ly hôn của tôi sống rất hạnh phúc gần các con của ông ấy.', '{"wordId":"divorced","ukIpa":"/dɪˈvɔːst/","usIpa":"/dɪˈvɔːrst/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"No longer married because the marriage legally ended.","vi":"đã ly hôn"},{"pos":"adj.","en":"Separated from something that should be closely connected.","vi":"tách rời; tách biệt"}],"examples":[{"en":"My divorced uncle lives happily near his children.","vi":"Người chú đã ly hôn của tôi sống rất hạnh phúc gần các con của ông ấy.","audioKind":"ex"},{"en":"Housing policies should consider the needs of divorced parents who share responsibility for raising children.","vi":"Các chính sách nhà ở nên cân nhắc nhu cầu của những bậc cha mẹ ly hôn nhưng vẫn cùng chia sẻ trách nhiệm nuôi dạy con cái.","audioKind":"ex2"}],"collocations":[{"en":"get divorced","vi":"ly hôn"},{"en":"divorced parents","vi":"cha mẹ ly hôn"},{"en":"divorced from reality","vi":"tách rời khỏi thực tế"}],"wordFamily":["divorce (n.)","divorce (v.)"],"synonyms":[],"antonyms":["married"],"tipVi":"get divorced dùng để chỉ hành động ly hôn; sự tách biệt khỏi cái gì dùng cấu trúc divorced from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_church', 'en-a2-6', 'church', '/tʃɝːtʃ/', 'A2', 'nhà thờ; buổi lễ tôn giáo tại nhà thờ; giáo hội; giáo đoàn', 'n.', NULL, NULL, 'go to church mang nghĩa đi làm lễ tôn giáo; go to the church mang nghĩa đi đến tòa nhà nhà thờ.', 'The old church has beautiful windows and a stone tower.', NULL, 'Ngôi nhà thờ cổ có những ô cửa sổ tuyệt đẹp và một ngọn tháp bằng đá.', '{"wordId":"church","ukIpa":"/tʃɜːtʃ/","usIpa":"/tʃɝːtʃ/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"a building where Christians gather to worship","vi":"nhà thờ"},{"pos":"n.","en":"Christian religious worship attended as a service","vi":"buổi lễ tôn giáo tại nhà thờ"},{"pos":"n.","en":"an organized group of Christians sharing beliefs and practices","vi":"giáo hội; giáo đoàn"}],"examples":[{"en":"The old church has beautiful windows and a stone tower.","vi":"Ngôi nhà thờ cổ có những ô cửa sổ tuyệt đẹp và một ngọn tháp bằng đá.","audioKind":"ex"},{"en":"Preserving a historic church can protect local heritage while providing opportunities for education and tourism.","vi":"Việc bảo tồn một nhà thờ lịch sử vừa có thể bảo vệ di sản địa phương vừa tạo ra cơ hội cho giáo dục và du lịch.","audioKind":"ex2"}],"collocations":[{"en":"go to church","vi":"đi lễ nhà thờ"},{"en":"attend church","vi":"tham dự lễ ở nhà thờ"},{"en":"church service","vi":"lễ nghi nhà thờ"},{"en":"historic church","vi":"nhà thờ lịch sử"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"go to church mang nghĩa đi làm lễ tôn giáo; go to the church mang nghĩa đi đến tòa nhà nhà thờ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_couple', 'en-a2-6', 'couple', '/ˈkʌpəl/', 'A2', 'cặp đôi; đôi vợ chồng; đôi tình nhân; một cặp; một vài; đôi ba; nối; kết nối; gắn liền với', 'n.', 'coupling (n.), uncouple (v.)', NULL, 'Cụm a couple of theo sau là danh từ đếm được số nhiều, dùng để chỉ hai hoặc một số ít người/vật.', 'The couple next door invited us over for dinner.', NULL, 'Cặp vợ chồng nhà bên cạnh đã mời chúng tôi sang ăn tối.', '{"wordId":"couple","ukIpa":"/ˈkʌpəl/","usIpa":"/ˈkʌpəl/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"Two people who are married or in a romantic relationship.","vi":"cặp đôi; đôi vợ chồng; đôi tình nhân"},{"pos":"n.","en":"Two things or people, or a small number of them.","vi":"một cặp; một vài; đôi ba"},{"pos":"v.","en":"To join two things or consider them together.","vi":"nối; kết nối; gắn liền với"}],"examples":[{"en":"The couple next door invited us over for dinner.","vi":"Cặp vợ chồng nhà bên cạnh đã mời chúng tôi sang ăn tối.","audioKind":"ex"},{"en":"High housing costs, coupled with limited childcare, can discourage young couples from starting a family.","vi":"Chi phí nhà ở cao kết hợp với dịch vụ chăm sóc trẻ em hạn chế có thể làm nản lòng các cặp vợ chồng trẻ khi muốn có con.","audioKind":"ex2"}],"collocations":[{"en":"a married couple","vi":"một cặp vợ chồng đã kết hôn"},{"en":"a couple of days","vi":"một vài ngày"},{"en":"coupled with","vi":"kết hợp với; đi kèm với"}],"wordFamily":["coupling (n.)","uncouple (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm a couple of theo sau là danh từ đếm được số nhiều, dùng để chỉ hai hoặc một số ít người/vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_action', 'en-a2-6', 'action', '/ˈækʃən/', 'A2', 'hành động; biện pháp; hành vi; cử chỉ; cảnh hành động; cốt truyện', 'n.', 'act (v.), active (adj.), activity (n.), inaction (n.)', 'Trái nghĩa: inaction', 'take action trong đó action là danh từ không đếm được; chỉ các cử chỉ cụ thể có thể dùng actions.', 'We need to take action before the leak worsens.', NULL, 'Chúng ta cần hành động trước khi vết rò rỉ trở nên tồi tệ hơn.', '{"wordId":"action","ukIpa":"/ˈækʃən/","usIpa":"/ˈækʃən/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"Something done to achieve a result or address a problem.","vi":"hành động; biện pháp"},{"pos":"n.","en":"A particular thing that someone does.","vi":"hành vi; cử chỉ"},{"pos":"n.","en":"Exciting events in a story, film, or real situation.","vi":"cảnh hành động; cốt truyện"}],"examples":[{"en":"We need to take action before the leak worsens.","vi":"Chúng ta cần hành động trước khi vết rò rỉ trở nên tồi tệ hơn.","audioKind":"ex"},{"en":"Governments must take urgent action to protect coastal communities from the growing risks of climate change.","vi":"Chính phủ phải hành động khẩn cấp để bảo vệ các cộng đồng ven biển trước rủi ro ngày càng tăng của biến đổi khí hậu.","audioKind":"ex2"}],"collocations":[{"en":"take action","vi":"hành động"},{"en":"urgent action","vi":"hành động khẩn cấp"},{"en":"course of action","vi":"phương án hành động"},{"en":"action film","vi":"phim hành động"}],"wordFamily":["act (v.)","active (adj.)","activity (n.)","inaction (n.)"],"synonyms":[],"antonyms":["inaction"],"tipVi":"take action trong đó action là danh từ không đếm được; chỉ các cử chỉ cụ thể có thể dùng actions.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lawyer', 'en-a2-6', 'lawyer', '/ˈlɔɪər/', 'A2', 'luật sư', 'n.', 'law (n.), lawful (adj.), unlawful (adj.)', NULL, 'lawyer là thuật ngữ chung chỉ luật sư, khác với judge (thẩm phán).', 'Our lawyer explained the contract before we signed it.', NULL, 'Luật sư của chúng tôi đã giải thích hợp đồng trước khi chúng tôi ký kết.', '{"wordId":"lawyer","ukIpa":"/ˈlɔɪə/","usIpa":"/ˈlɔɪər/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"Someone qualified to advise people about law and represent them.","vi":"luật sư"}],"examples":[{"en":"Our lawyer explained the contract before we signed it.","vi":"Luật sư của chúng tôi đã giải thích hợp đồng trước khi chúng tôi ký kết.","audioKind":"ex"},{"en":"Access to an affordable lawyer helps ensure that everyone can defend their legal rights.","vi":"Khả năng tiếp cận dịch vụ luật sư với mức phí phải chăng giúp đảm bảo mọi người đều có thể bảo vệ các quyền lợi hợp pháp của mình.","audioKind":"ex2"}],"collocations":[{"en":"hire a lawyer","vi":"thuê luật sư"},{"en":"criminal lawyer","vi":"luật sư hình sự"},{"en":"consult a lawyer","vi":"tư vấn luật sư"}],"wordFamily":["law (n.)","lawful (adj.)","unlawful (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"lawyer là thuật ngữ chung chỉ luật sư, khác với judge (thẩm phán).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_voice', 'en-a2-6', 'voice', '/vɔɪs/', 'A2', 'giọng nói; tiếng nói; quyền phát biểu; tiếng nói có trọng lượng; bày tỏ; lên tiếng', 'n.', 'voiced (adj.), voiceless (adj.)', NULL, 'voice tập trung vào giọng nói của con người; sound dùng chung cho mọi loại âm thanh.', 'Her gentle voice helped the frightened puppy settle down.', NULL, 'Giọng nói dịu dàng của cô ấy đã giúp chú chó nhỏ đang hoảng sợ bình tĩnh lại.', '{"wordId":"voice","ukIpa":"/vɔɪs/","usIpa":"/vɔɪs/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"The sound someone makes when speaking or singing.","vi":"giọng nói; tiếng nói"},{"pos":"n.","en":"The right or opportunity to express opinions and influence decisions.","vi":"quyền phát biểu; tiếng nói có trọng lượng"},{"pos":"v.","en":"To express an opinion, feeling, or concern.","vi":"bày tỏ; lên tiếng"}],"examples":[{"en":"Her gentle voice helped the frightened puppy settle down.","vi":"Giọng nói dịu dàng của cô ấy đã giúp chú chó nhỏ đang hoảng sợ bình tĩnh lại.","audioKind":"ex"},{"en":"Public consultations give local residents a voice in decisions that directly affect their communities.","vi":"Các buổi tham vấn công khai mang lại cho người dân địa phương quyền phát biểu trong các quyết định ảnh hưởng trực tiếp đến cộng đồng của họ.","audioKind":"ex2"}],"collocations":[{"en":"raise your voice","vi":"nói to lên; cất cao giọng"},{"en":"a voice in decisions","vi":"tiếng nói trong các quyết định"},{"en":"voice concerns","vi":"bày tỏ sự lo lắng"},{"en":"lose your voice","vi":"mất giọng"}],"wordFamily":["voiced (adj.)","voiceless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"voice tập trung vào giọng nói của con người; sound dùng chung cho mọi loại âm thanh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_provide', 'en-a2-6', 'provide', '/prəˈvaɪd/', 'A2', 'cung cấp; đáp ứng; nuôi nấng; chu cấp', 'v.', 'provider (n.), provision (n.)', 'Đồng nghĩa: supply, offer', 'Dùng provide sb with sth hoặc provide sth for sb.', 'The campsite provides clean towels and blankets for every guest.', NULL, 'Khu cắm trại cung cấp khăn tắm và chăn sạch cho mọi vị khách.', '{"wordId":"provide","ukIpa":"/prəˈvaɪd/","usIpa":"/prəˈvaɪd/","cefr":"A2","topic":"society","senses":[{"pos":"v.","en":"To give someone something they need or make it available.","vi":"cung cấp; đáp ứng"},{"pos":"v.","en":"To support someone financially by supplying what they need.","vi":"nuôi nấng; chu cấp"}],"examples":[{"en":"The campsite provides clean towels and blankets for every guest.","vi":"Khu cắm trại cung cấp khăn tắm và chăn sạch cho mọi vị khách.","audioKind":"ex"},{"en":"Local authorities should provide affordable public transport to ensure that all residents can access essential services.","vi":"Chính quyền địa phương nên cung cấp phương tiện giao thông công cộng giá cả phải chăng để đảm bảo tất cả người dân đều tiếp cận được các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"provide support","vi":"cung cấp hỗ trợ"},{"en":"provide access to","vi":"cung cấp quyền tiếp cận"},{"en":"provide someone with something","vi":"cung cấp cho ai cái gì"},{"en":"provide for a family","vi":"nuôi gia đình"}],"wordFamily":["provider (n.)","provision (n.)"],"synonyms":["supply","offer"],"antonyms":[],"tipVi":"Dùng provide sb with sth hoặc provide sth for sb.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_international', 'en-a2-6', 'international', '/ˌɪntərˈnæʃənəl/', 'A2', 'quốc tế; thuộc về quốc tế; trận đấu quốc tế; vận động viên khoác áo đội tuyển quốc gia', 'adj.', 'nation (n.), national (adj.), internationally (adv.), internationalisation (n.)', 'Trái nghĩa: domestic', 'international chỉ tính đa quốc gia; trái nghĩa với domestic (nội địa).', 'My sister is taking an international flight tomorrow morning.', NULL, 'Chị gái tôi sẽ đi chuyến bay quốc tế vào sáng mai.', '{"wordId":"international","ukIpa":"/ˌɪntəˈnæʃənəl/","usIpa":"/ˌɪntərˈnæʃənəl/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"Involving two or more countries.","vi":"quốc tế; thuộc về quốc tế"},{"pos":"n.","en":"A match between countries, or a player representing a country.","vi":"trận đấu quốc tế; vận động viên khoác áo đội tuyển quốc gia"}],"examples":[{"en":"My sister is taking an international flight tomorrow morning.","vi":"Chị gái tôi sẽ đi chuyến bay quốc tế vào sáng mai.","audioKind":"ex"},{"en":"International cooperation is essential for tackling environmental problems that extend beyond the borders of individual countries.","vi":"Hợp tác quốc tế là điều thiết yếu để giải quyết các vấn đề môi trường vượt ra ngoài ranh giới của từng quốc gia riêng lẻ.","audioKind":"ex2"}],"collocations":[{"en":"international trade","vi":"thương mại quốc tế"},{"en":"international cooperation","vi":"hợp tác quốc tế"},{"en":"an international flight","vi":"chuyến bay quốc tế"},{"en":"international students","vi":"sinh viên quốc tế"}],"wordFamily":["nation (n.)","national (adj.)","internationally (adv.)","internationalisation (n.)"],"synonyms":[],"antonyms":["domestic"],"tipVi":"international chỉ tính đa quốc gia; trái nghĩa với domestic (nội địa).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_event', 'en-a2-6', 'event', '/ɪˈvent/', 'A2', 'sự kiện; hoạt động; môn thi đấu', 'n.', 'eventful (adj.), uneventful (adj.)', 'Đồng nghĩa: happening, occasion', 'Cụm in the event of đi kèm danh từ đằng sau, mang nghĩa là "trong trường hợp xảy ra..." hoặc "vạn/nếu xảy ra...".', 'The outdoor concert was our town''s biggest summer event.', NULL, 'Buổi hòa nhạc ngoài trời là sự kiện mùa hè lớn nhất ở thị trấn của chúng tôi.', '{"wordId":"event","ukIpa":"/ɪˈvent/","usIpa":"/ɪˈvent/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"Something that happens, especially an important or planned occasion.","vi":"sự kiện; hoạt động"},{"pos":"n.","en":"A particular contest within a sports competition.","vi":"môn thi đấu"}],"examples":[{"en":"The outdoor concert was our town''s biggest summer event.","vi":"Buổi hòa nhạc ngoài trời là sự kiện mùa hè lớn nhất ở thị trấn của chúng tôi.","audioKind":"ex"},{"en":"Hosting a major cultural event can boost local tourism, although the financial benefits may be unevenly distributed.","vi":"Tổ chức một sự kiện văn hóa lớn có thể thúc đẩy du lịch địa phương, mặc dù lợi ích tài chính có thể không được phân bổ đồng đều.","audioKind":"ex2"}],"collocations":[{"en":"organise an event","vi":"tổ chức một sự kiện"},{"en":"major event","vi":"sự kiện lớn"},{"en":"sporting event","vi":"sự kiện thể thao"},{"en":"in the event of","vi":"trong trường hợp"}],"wordFamily":["eventful (adj.)","uneventful (adj.)"],"synonyms":["happening","occasion"],"antonyms":[],"tipVi":"Cụm in the event of đi kèm danh từ đằng sau, mang nghĩa là \"trong trường hợp xảy ra...\" hoặc \"vạn/nếu xảy ra...\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_asian', 'en-a2-6', 'Asian', '/ˈeɪʒən/', 'A2', 'thuộc về hoặc liên quan đến châu Á và người châu Á; người châu Á hoặc người gốc châu Á', 'adj.', 'Asia (n.)', NULL, 'Chữ cái đầu tiên bắt buộc phải viết hoa; Asia là danh từ chỉ châu lục, còn Asian có thể dùng làm tính từ.', 'The museum displays pottery from several different Asian countries.', NULL, 'Bảo tàng trưng bày đồ gốm từ một vài quốc gia châu Á khác nhau.', '{"wordId":"asian","ukIpa":"/ˈeɪʒən/","usIpa":"/ˈeɪʒən/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"Relating to Asia or its people.","vi":"thuộc về hoặc liên quan đến châu Á và người châu Á"},{"pos":"n.","en":"A person from Asia or with family origins there.","vi":"người châu Á hoặc người gốc châu Á"}],"examples":[{"en":"The museum displays pottery from several different Asian countries.","vi":"Bảo tàng trưng bày đồ gốm từ một vài quốc gia châu Á khác nhau.","audioKind":"ex"},{"en":"Many Asian cities are expanding public transport networks to reduce traffic congestion and improve urban air quality.","vi":"Nhiều thành phố ở châu Á đang mở rộng mạng lưới giao thông công cộng nhằm giảm thiểu tình trạng ùn tắc giao thông và cải thiện chất lượng không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"Asian countries","vi":"các quốc gia châu Á"},{"en":"Asian cultures","vi":"văn hóa châu Á"},{"en":"Asian economies","vi":"các nền kinh tế châu Á"}],"wordFamily":["Asia (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái đầu tiên bắt buộc phải viết hoa; Asia là danh từ chỉ châu lục, còn Asian có thể dùng làm tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anybody', 'en-a2-6', 'anybody', '/ˈenibɑːdi/', 'A2', 'bất kỳ ai; người nào', 'pron.', NULL, 'Đồng nghĩa: anyone · Trái nghĩa: nobody', 'anybody khi làm chủ ngữ, động từ theo sau thường chia ở ngôi thứ ba số ít.', 'Does anybody know where I left my blue umbrella?', NULL, 'Có ai biết tôi để chiếc ô màu xanh ở đâu không?', '{"wordId":"anybody","ukIpa":"/ˈenibɒdi/","usIpa":"/ˈenibɑːdi/","cefr":"A2","topic":"society","senses":[{"pos":"pron.","en":"Any person, or someone whose identity is not specified.","vi":"bất kỳ ai; người nào"}],"examples":[{"en":"Does anybody know where I left my blue umbrella?","vi":"Có ai biết tôi để chiếc ô màu xanh ở đâu không?","audioKind":"ex"},{"en":"Public libraries should be accessible to anybody who wishes to learn, regardless of their income or background.","vi":"Các thư viện công cộng nên mở cửa cho bất kỳ ai muốn học tập, không phân biệt thu nhập hay gia cảnh của họ.","audioKind":"ex2"}],"collocations":[{"en":"anybody else","vi":"bất kỳ ai khác"},{"en":"hardly anybody","vi":"hầu như không có ai"},{"en":"anybody at all","vi":"bất kỳ ai đi nữa"}],"wordFamily":[],"synonyms":["anyone"],"antonyms":["nobody"],"tipVi":"anybody khi làm chủ ngữ, động từ theo sau thường chia ở ngôi thứ ba số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fight', 'en-a2-6', 'fight', '/faɪt/', 'A2', 'đánh nhau; chiến đấu; chống lại; nỗ lực đấu tranh cho; cuộc ẩu đả; cuộc đấu tranh', 'v.', 'fighter (n.), fighting (n.)', 'Đồng nghĩa: combat, struggle', 'Dạng quá khứ và quá khứ phân từ của fight đều là fought; cấu trúc fight for diễn tả việc đấu tranh cho điều gì.', 'The two cats fought over a sunny window seat.', NULL, 'Hai con mèo đánh nhau tranh giành chỗ ngồi có nắng bên cửa sổ.', '{"wordId":"fight","ukIpa":"/faɪt/","usIpa":"/faɪt/","cefr":"A2","topic":"society","senses":[{"pos":"v.","en":"To use physical force against another person or group.","vi":"đánh nhau; chiến đấu"},{"pos":"v.","en":"To try hard to stop something or achieve a goal.","vi":"chống lại; nỗ lực đấu tranh cho"},{"pos":"n.","en":"An occasion of physical conflict or a determined effort against something.","vi":"cuộc ẩu đả; cuộc đấu tranh"}],"examples":[{"en":"The two cats fought over a sunny window seat.","vi":"Hai con mèo đánh nhau tranh giành chỗ ngồi có nắng bên cửa sổ.","audioKind":"ex"},{"en":"Governments should fight poverty by improving access to education, healthcare, and stable employment opportunities.","vi":"Chính phủ nên chống lại nghèo đói bằng cách cải thiện khả năng tiếp cận giáo dục, y tế và cơ hội việc làm ổn định.","audioKind":"ex2"}],"collocations":[{"en":"fight poverty","vi":"chống lại đói nghèo"},{"en":"fight for equality","vi":"đấu tranh vì bình đẳng"},{"en":"fight against discrimination","vi":"chống lại sự phân biệt đối xử"},{"en":"get into a fight","vi":"vướng vào một vụ ẩu đả"}],"wordFamily":["fighter (n.)","fighting (n.)"],"synonyms":["combat","struggle"],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ của fight đều là fought; cấu trúc fight for diễn tả việc đấu tranh cho điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_granddaughter', 'en-a2-6', 'granddaughter', '/ˈɡrændɔːtər/', 'A2', 'cháu gái (con của con trai hoặc con gái)', 'n.', 'grandchild (n.), grandson (n.), grandparent (n.)', NULL, 'Dùng chung cho cả cháu nội lẫn cháu ngoại, tiếng Anh không phân biệt bên nội hay bên ngoại.', 'Her granddaughter brought fresh flowers when she visited on Sunday.', NULL, 'Cháu gái của bà đã mang hoa tươi đến thăm vào ngày Chủ nhật.', '{"wordId":"granddaughter","ukIpa":"/ˈɡrændɔːtə/","usIpa":"/ˈɡrændɔːtər/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"The daughter of someone''s son or daughter","vi":"cháu gái (con của con trai hoặc con gái)"}],"examples":[{"en":"Her granddaughter brought fresh flowers when she visited on Sunday.","vi":"Cháu gái của bà đã mang hoa tươi đến thăm vào ngày Chủ nhật.","audioKind":"ex"},{"en":"Regular contact with a granddaughter or grandson can help older adults feel more connected to family life.","vi":"Thường xuyên giữ liên lạc với cháu gái hoặc cháu trai có thể giúp người cao tuổi cảm thấy gắn kết hơn với đời sống gia đình.","audioKind":"ex2"}],"collocations":[{"en":"youngest granddaughter","vi":"cháu gái út"},{"en":"granddaughter''s birthday","vi":"sinh nhật của cháu gái"}],"wordFamily":["grandchild (n.)","grandson (n.)","grandparent (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng chung cho cả cháu nội lẫn cháu ngoại, tiếng Anh không phân biệt bên nội hay bên ngoại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_6_1', 'en-a2-6', 'Cách dùng “social” (adj.) — thuộc về xã hội', 'social inequality  ·  social skills  ·  social activities', 'social dùng để chỉ các vấn đề thuộc xã hội hoặc giao lưu; còn sociable dùng để chỉ người cởi mở, thích giao thiệp.', 'Họ từ (Word Family): society (n), socially (adv), socialise (v), socialisation (n)', '[{"hanzi":"My new job leaves little time for social activities.","pinyin":"","meaning":"Công việc mới khiến tôi gần như không còn thời gian cho các hoạt động xã hội."},{"hanzi":"Affordable housing policies can reduce social inequality by helping families access safe homes near essential services.","pinyin":"","meaning":"Các chính sách nhà ở vừa túi tiền có thể làm giảm tình trạng bất bình đẳng xã hội bằng cách giúp các gia đình tiếp cận nhà ở an toàn gần các dịch vụ thiết yếu."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_6_2', 'en-a2-6', 'Cách dùng “event” (n.) — sự kiện; hoạt động', 'organise an event  ·  major event  ·  sporting event', 'Cụm in the event of đi kèm danh từ đằng sau, mang nghĩa là "trong trường hợp xảy ra..." hoặc "vạn/nếu xảy ra...".', 'Họ từ (Word Family): eventful (adj.), uneventful (adj.) | Đồng nghĩa: happening, occasion', '[{"hanzi":"The outdoor concert was our town''s biggest summer event.","pinyin":"","meaning":"Buổi hòa nhạc ngoài trời là sự kiện mùa hè lớn nhất ở thị trấn của chúng tôi."},{"hanzi":"Hosting a major cultural event can boost local tourism, although the financial benefits may be unevenly distributed.","pinyin":"","meaning":"Tổ chức một sự kiện văn hóa lớn có thể thúc đẩy du lịch địa phương, mặc dù lợi ích tài chính có thể không được phân bổ đồng đều."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_6_3', 'en-a2-6', 'Cách dùng “fight” (v.) — đánh nhau; chiến đấu', 'fight poverty  ·  fight for equality  ·  fight against discrimination', 'Dạng quá khứ và quá khứ phân từ của fight đều là fought; cấu trúc fight for diễn tả việc đấu tranh cho điều gì.', 'Họ từ (Word Family): fighter (n.), fighting (n.) | Đồng nghĩa: combat, struggle', '[{"hanzi":"The two cats fought over a sunny window seat.","pinyin":"","meaning":"Hai con mèo đánh nhau tranh giành chỗ ngồi có nắng bên cửa sổ."},{"hanzi":"Governments should fight poverty by improving access to education, healthcare, and stable employment opportunities.","pinyin":"","meaning":"Chính phủ nên chống lại nghèo đói bằng cách cải thiện khả năng tiếp cận giáo dục, y tế và cơ hội việc làm ổn định."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_6_4', 'en-a2-6', 'Cách dùng “God” (n.) — Thượng Đế; Chúa; vị thần tối cao', 'believe in God  ·  pray to God  ·  faith in God', 'Khi chỉ đấng tối cao duy nhất, dùng God thường không kèm mạo từ; khi chỉ thần linh chung chung, dùng god.', 'Họ từ (Word Family): godly (adj.), godless (adj.), godliness (n.)', '[{"hanzi":"My grandmother thanks God before each meal at home.","pinyin":"","meaning":"Bà tôi cảm ơn Thượng Đế trước mỗi bữa ăn ở nhà."},{"hanzi":"Belief in God can influence people''s values, charitable activities, and responses to difficult circumstances.","pinyin":"","meaning":"Niềm tin vào Thượng Đế có thể ảnh hưởng đến giá trị sống, các hoạt động từ thiện và cách mọi người đối phó với hoàn cảnh khó khăn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
