INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_6_1_6', 'ten_a2_6_1', 'flag', 'A bright flag fluttered above the school gate.', 'A bright flag fluttered above the school gate.', '/flæɡ/', 'Một lá cờ rực rỡ bay phấp phới phía trên cổng trường.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_6_1_7', 'ten_a2_6_1', 'marry', 'My cousin plans to marry her partner next spring.', 'My cousin plans to marry her partner next spring.', '/ˈmæri/', 'Anh họ của tôi dự định kết hôn với bạn đời vào mùa xuân tới.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_6_1_8', 'ten_a2_6_1', 'mother-in-law', 'My mother-in-law taught me how to grow tomatoes.', 'My mother-in-law taught me how to grow tomatoes.', '/ˈmʌðər ɪn lɔː/', 'Mẹ chồng tôi đã dạy tôi cách trồng cà chua.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_6_1_1', 'en-a2-6', 'ten_a2_6_1', 'listening', 'listening', 'The male duck has a shiny green head.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Con vịt đực có cái đầu màu xanh lục lấp lánh.","Mẹ chồng tôi đã dạy tôi cách trồng cà chua.","Cháu gái của bà đã mang hoa tươi đến thăm vào ngày Chủ nhật.","Chị gái tôi sẽ đi chuyến bay quốc tế vào sáng mai."]'::jsonb, 0, 'The male duck has a shiny green head. → Con vịt đực có cái đầu màu xanh lục lấp lánh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_6_1_2', 'en-a2-6', 'ten_a2_6_1', 'listening', 'listening', 'It was rude to interrupt her during dinner.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bà tôi cảm ơn Thượng Đế trước mỗi bữa ăn ở nhà.","Đứa trẻ ngoan ngoãn và lịch sự đã giữ cửa giúp chúng tôi.","Thật là bất lịch sự khi cắt ngang lời cô ấy trong bữa tối.","Buổi hòa nhạc ngoài trời là sự kiện mùa hè lớn nhất ở thị trấn của chúng tôi."]'::jsonb, 2, 'It was rude to interrupt her during dinner. → Thật là bất lịch sự khi cắt ngang lời cô ấy trong bữa tối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_6_1_3', 'en-a2-6', 'ten_a2_6_1', 'listening', 'listening', 'Our Dutch neighbour taught us how to bake apple pie.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mẹ chồng tôi đã dạy tôi cách trồng cà chua.","Người hàng xóm gốc Hà Lan của chúng tôi đã dạy chúng tôi cách nướng bánh táo.","Chúng tôi luân phiên chọn trò chơi để mọi thứ được công bằng.","Cháu gái của bà đã mang hoa tươi đến thăm vào ngày Chủ nhật."]'::jsonb, 1, 'Our Dutch neighbour taught us how to bake apple pie. → Người hàng xóm gốc Hà Lan của chúng tôi đã dạy chúng tôi cách nướng bánh táo.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_6_2', 'en-a2-6', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_6_2_1', 'ten_a2_6_2', 'male', 'Encouraging more male applicants to enter nursing could help address staff shortages and challenge gender stereotypes.', 'Encouraging more male applicants to enter nursing could help address staff shortages and challenge gender stereotypes.', '/meɪl/', 'Việc khuyến khích nhiều nam ứng viên tham gia ngành điều dưỡng có thể giúp giải quyết tình trạng thiếu nhân lực và phá vỡ các định kiến giới.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_6_2_2', 'ten_a2_6_2', 'rude', 'Schools should teach children how to disagree respectfully without making rude comments about others.', 'Schools should teach children how to disagree respectfully without making rude comments about others.', '/ruːd/', 'Nhà trường nên dạy học sinh cách thể hiện sự bất đồng một cách tôn trọng mà không đưa ra những nhận xét thô lỗ về người khác.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_6_2_3', 'ten_a2_6_2', 'Dutch', 'Dutch cities are often studied by urban planners seeking to develop safer and more accessible cycling networks.', 'Dutch cities are often studied by urban planners seeking to develop safer and more accessible cycling networks.', '/dʌtʃ/', 'Các thành phố của Hà Lan thường được nghiên cứu bởi các nhà quy hoạch đô thị muốn phát triển các mạng lưới đi xe đạp an toàn và dễ tiếp cận hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_6_2_4', 'ten_a2_6_2', 'social', 'Affordable housing policies can reduce social inequality by helping families access safe homes near essential services.', 'Affordable housing policies can reduce social inequality by helping families access safe homes near essential services.', '/ˈsoʊʃəl/', 'Các chính sách nhà ở vừa túi tiền có thể làm giảm tình trạng bất bình đẳng xã hội bằng cách giúp các gia đình tiếp cận nhà ở an toàn gần các dịch vụ thiết yếu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_6_2_5', 'ten_a2_6_2', 'grandson', 'Regular contact with a grandson or granddaughter can help older adults feel more socially connected.', 'Regular contact with a grandson or granddaughter can help older adults feel more socially connected.', '/ˈɡrænsʌn/', 'Việc thường xuyên liên lạc với cháu trai hoặc cháu gái có thể giúp người cao tuổi cảm thấy gắn kết hơn với xã hội.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_6_2_6', 'ten_a2_6_2', 'flag', 'Teachers should flag potential learning difficulties early so that students can receive appropriate support.', 'Teachers should flag potential learning difficulties early so that students can receive appropriate support.', '/flæɡ/', 'Giáo viên nên sớm nêu lên các khó khăn học tập tiềm ẩn để học sinh nhận được sự hỗ trợ phù hợp.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_6_2_1', 'en-a2-6', 'ten_a2_6_2', 'listening', 'listening', 'Encouraging more male applicants to enter nursing could help address staff shortages and challenge gender stereotypes.', NULL, 'Trong câu vừa nghe, từ “male” mang nghĩa nào sau đây?', '["dầu gội đầu","thuộc nam giới; thuộc giống đực","con kiến","gói; túi nhỏ; hộp nhỏ"]'::jsonb, 1, '“male” (/meɪl/): thuộc nam giới; thuộc giống đực. Câu đầy đủ: Encouraging more male applicants to enter nursing could help address staff shortages and challenge gender stereotypes.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_6_2_2', 'en-a2-6', 'ten_a2_6_2', 'listening', 'listening', 'Schools should teach children how to disagree respectfully without making rude comments about others.', NULL, 'Trong câu vừa nghe, từ “rude” mang nghĩa nào sau đây?', '["thất lễ; thô lỗ; bất lịch sự","diễn giả; người phát biểu","việc đỗ xe; sự đậu xe","côn trùng; sâu bọ"]'::jsonb, 0, '“rude” (/ruːd/): thất lễ; thô lỗ; bất lịch sự. Câu đầy đủ: Schools should teach children how to disagree respectfully without making rude comments about others.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
