INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_6_2', 'en-a2-6', NULL, 'comprehensive_test', 'listening', 'It was rude to interrupt her during dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cháu gái của bà đã mang hoa tươi đến thăm vào ngày Chủ nhật.","Cháu trai của bà đến thăm vào mỗi Chủ nhật và giúp nấu ăn.","Thật là bất lịch sự khi cắt ngang lời cô ấy trong bữa tối.","Một lá cờ rực rỡ bay phấp phới phía trên cổng trường."]'::jsonb, 2, 'It was rude to interrupt her during dinner. → Thật là bất lịch sự khi cắt ngang lời cô ấy trong bữa tối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_6_3', 'en-a2-6', NULL, 'comprehensive_test', 'listening', 'Dutch', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["loại; kiểu","trang sức; đồ trang trí quý giá","trang blog; nhật ký điện tử","thuộc Hà Lan; của người Hà Lan"]'::jsonb, 3, 'Dutch (/dʌtʃ/) → thuộc Hà Lan; của người Hà Lan; tiếng Hà Lan; người Hà Lan', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_6_4', 'en-a2-6', NULL, 'comprehensive_test', 'listening', 'My new job leaves little time for social activities.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Khu cắm trại cung cấp khăn tắm và chăn sạch cho mọi vị khách.","Người hàng xóm người Thụy Điển của chúng tôi đã dạy chúng tôi cách nướng bánh mì quế.","Công việc mới khiến tôi gần như không còn thời gian cho các hoạt động xã hội.","Bà tôi cảm ơn Thượng Đế trước mỗi bữa ăn ở nhà."]'::jsonb, 2, 'My new job leaves little time for social activities. → Công việc mới khiến tôi gần như không còn thời gian cho các hoạt động xã hội.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_6_5', 'en-a2-6', NULL, 'comprehensive_test', 'listening', 'grandson', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhà hát; rạp hát","xăng","cháu trai (con của con trai hoặc con gái)","hành động; biện pháp"]'::jsonb, 2, 'grandson (/ˈɡrænsʌn/) → cháu trai (con của con trai hoặc con gái)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_6_6', 'en-a2-6', NULL, 'comprehensive_test', 'listening', 'A bright flag fluttered above the school gate.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cặp vợ chồng nhà bên cạnh đã mời chúng tôi sang ăn tối.","Người hàng xóm người Thụy Điển của chúng tôi đã dạy chúng tôi cách nướng bánh mì quế.","Ngôi nhà thờ cổ có những ô cửa sổ tuyệt đẹp và một ngọn tháp bằng đá.","Một lá cờ rực rỡ bay phấp phới phía trên cổng trường."]'::jsonb, 3, 'A bright flag fluttered above the school gate. → Một lá cờ rực rỡ bay phấp phới phía trên cổng trường.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_6_7', 'en-a2-6', NULL, 'comprehensive_test', 'listening', 'marry', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đá; hòn đá","nửa đêm; mười hai giờ đêm","kết hôn với ai; lập gia đình","huấn luyện viên"]'::jsonb, 2, 'marry (/ˈmæri/) → kết hôn với ai; lập gia đình; làm lễ kết hôn cho ai', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_6_8', 'en-a2-6', NULL, 'comprehensive_test', 'listening', 'My mother-in-law taught me how to grow tomatoes.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giọng nói dịu dàng của cô ấy đã giúp chú chó nhỏ đang hoảng sợ bình tĩnh lại.","Đứa trẻ ngoan ngoãn và lịch sự đã giữ cửa giúp chúng tôi.","Mẹ chồng tôi đã dạy tôi cách trồng cà chua.","Cặp vợ chồng nhà bên cạnh đã mời chúng tôi sang ăn tối."]'::jsonb, 2, 'My mother-in-law taught me how to grow tomatoes. → Mẹ chồng tôi đã dạy tôi cách trồng cà chua.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_6_9', 'en-a2-6', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “the son of your son or daughter”?', '["granddaughter","voice","Swedish","grandson"]'::jsonb, 3, 'grandson (/ˈɡrænsʌn/) → cháu trai (con của con trai hoặc con gái)', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
