INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_6_18', 'en-a2-6', NULL, 'comprehensive_test', 'reading', NULL, 'Encouraging more male applicants to enter nursing could help address staff shortages and challenge gender stereotypes.', 'Dựa vào câu trên, từ “male” có nghĩa phù hợp nhất là gì?', '["chính xác; hoàn toàn","thuộc nam giới; thuộc giống đực","nhân viên dọn dẹp; người làm vệ sinh","công chúa; vương phi"]'::jsonb, 1, 'male: thuộc nam giới; thuộc giống đực; nam giới; con đực. Dịch cả câu: Việc khuyến khích nhiều nam ứng viên tham gia ngành điều dưỡng có thể giúp giải quyết tình trạng thiếu nhân lực và phá vỡ các định kiến giới.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_6_19', 'en-a2-6', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should teach children how to disagree respectfully without making rude comments about others.', 'Dựa vào câu trên, từ “rude” có nghĩa phù hợp nhất là gì?', '["lời chào hỏi; sự chào đón","thất lễ; thô lỗ; bất lịch sự","nam nhân viên bưu điện (người làm nghề phát thư từ và bưu phẩm)","chật chội; đông đúc"]'::jsonb, 1, 'rude: thất lễ; thô lỗ; bất lịch sự. Dịch cả câu: Nhà trường nên dạy học sinh cách thể hiện sự bất đồng một cách tôn trọng mà không đưa ra những nhận xét thô lỗ về người khác.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_6_20', 'en-a2-6', NULL, 'comprehensive_test', 'reading', NULL, 'Dutch cities are often studied by urban planners seeking to develop safer and more accessible cycling networks.', 'Dựa vào câu trên, từ “Dutch” có nghĩa phù hợp nhất là gì?', '["đuôi (động vật hoặc máy bay)","bữa ăn nhẹ; đồ ăn vặt","bữa tối; bữa ăn nhẹ trước khi đi ngủ","thuộc Hà Lan; của người Hà Lan"]'::jsonb, 3, 'Dutch: thuộc Hà Lan; của người Hà Lan; tiếng Hà Lan; người Hà Lan. Dịch cả câu: Các thành phố của Hà Lan thường được nghiên cứu bởi các nhà quy hoạch đô thị muốn phát triển các mạng lưới đi xe đạp an toàn và dễ tiếp cận hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_6_21', 'en-a2-6', NULL, 'comprehensive_test', 'reading', NULL, 'Affordable housing policies can reduce social inequality by helping families access safe homes near essential services.', 'Dựa vào câu trên, từ “social” có nghĩa phù hợp nhất là gì?', '["trực tuyến; ở trên mạng","thuộc về xã hội","dọc theo; theo","cực kỳ; vô cùng"]'::jsonb, 1, 'social: thuộc về xã hội; mang tính giao lưu; thuộc về giao tiếp xã hội; sống bầy đàn. Dịch cả câu: Các chính sách nhà ở vừa túi tiền có thể làm giảm tình trạng bất bình đẳng xã hội bằng cách giúp các gia đình tiếp cận nhà ở an toàn gần các dịch vụ thiết yếu.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
