INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_6_23', 'en-a2-6', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đánh nhau; chiến đấu”', '["countryside","meaning","fight","bee"]'::jsonb, 2, 'đánh nhau; chiến đấu → fight (/faɪt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_6_24', 'en-a2-6', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cháu gái (con của con trai hoặc con gái)”', '["gift","granddaughter","scissors","elevator"]'::jsonb, 1, 'cháu gái (con của con trai hoặc con gái) → granddaughter (/ˈɡrændɔːtər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-7', 'en', 'Bài 7: Xã hội & Cộng đồng (2) - CEFR A2', 'CEFR A2', 'A2 · Xã hội', '26 từ vựng Tiếng Anh CEFR A2 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2007, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_teenager', 'en-a2-7', 'teenager', '/ˈtiːneɪdʒər/', 'A2', 'thanh thiếu niên (từ 13 đến 19 tuổi)', 'n.', 'teenage (adj.), teen (n.)', 'Đồng nghĩa: teen, adolescent', 'Chỉ dùng để chỉ người từ 13 đến 19 tuổi, không dùng để chỉ chung tất cả những người chưa thành niên.', 'As a teenager, I cycled to school every day.', NULL, 'Hồi còn là thanh thiếu niên, tôi đạp xe đi học mỗi ngày.', '{"wordId":"teenager","ukIpa":"/ˈtiːneɪdʒə/","usIpa":"/ˈtiːneɪdʒər/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"A person aged thirteen to nineteen.","vi":"thanh thiếu niên (từ 13 đến 19 tuổi)"}],"examples":[{"en":"As a teenager, I cycled to school every day.","vi":"Hồi còn là thanh thiếu niên, tôi đạp xe đi học mỗi ngày.","audioKind":"ex"},{"en":"Schools should provide spaces where teenagers can discuss their concerns and receive support from trained staff.","vi":"Các trường học nên tạo không gian để thanh thiếu niên có thể thảo luận về những băn khoăn của mình và nhận sự hỗ trợ từ đội ngũ nhân viên được đào tạo.","audioKind":"ex2"}],"collocations":[{"en":"a young teenager","vi":"một thiếu niên trẻ tuổi"},{"en":"as a teenager","vi":"khi còn là thanh thiếu niên"},{"en":"teenagers'' needs","vi":"nhu cầu của giới trẻ"}],"wordFamily":["teenage (adj.)","teen (n.)"],"synonyms":["teen","adolescent"],"antonyms":[],"tipVi":"Chỉ dùng để chỉ người từ 13 đến 19 tuổi, không dùng để chỉ chung tất cả những người chưa thành niên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_housewife', 'en-a2-7', 'housewife', '/ˈhaʊswaɪf/', 'A2', 'nội trợ; bà nội trợ', 'n.', 'househusband (n.)', 'Đồng nghĩa: homemaker', 'Dạng số nhiều là housewives; từ homemaker mang tính trung lập về giới tính hơn.', 'As a housewife, she manages a busy household.', NULL, 'Là một người nội trợ, cô ấy chu toàn mọi công việc bận rộn trong gia đình.', '{"wordId":"housewife","ukIpa":"/ˈhaʊswaɪf/","usIpa":"/ˈhaʊswaɪf/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"A married woman managing her home rather than doing paid work.","vi":"nội trợ; bà nội trợ"}],"examples":[{"en":"As a housewife, she manages a busy household.","vi":"Là một người nội trợ, cô ấy chu toàn mọi công việc bận rộn trong gia đình.","audioKind":"ex"},{"en":"The unpaid work of a housewife contributes to family welfare but is often excluded from economic statistics.","vi":"Công việc không lương của một người nội trợ góp phần quan trọng vào phúc lợi gia đình nhưng thường bị bỏ quên trong các số liệu thống kê kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"a full-time housewife","vi":"một người nội trợ toàn thời gian"},{"en":"work as a housewife","vi":"làm nội trợ"}],"wordFamily":["househusband (n.)"],"synonyms":["homemaker"],"antonyms":[],"tipVi":"Dạng số nhiều là housewives; từ homemaker mang tính trung lập về giới tính hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_soldier', 'en-a2-7', 'soldier', '/ˈsoʊldʒɚ/', 'A2', 'lính; quân nhân', 'n.', 'soldiering (n.)', NULL, 'Thường chỉ binh sĩ lực lượng lục quân; thủy thủ và phi công có tên gọi riêng.', 'The soldier helped carry supplies across the flooded road.', NULL, 'Người lính đã giúp vận chuyển nhu yếu phẩm băng qua con đường ngập lụt.', '{"wordId":"soldier","ukIpa":"/ˈsəʊldʒə/","usIpa":"/ˈsoʊldʒɚ/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"a person who serves in an army","vi":"lính; quân nhân"}],"examples":[{"en":"The soldier helped carry supplies across the flooded road.","vi":"Người lính đã giúp vận chuyển nhu yếu phẩm băng qua con đường ngập lụt.","audioKind":"ex"},{"en":"Soldiers can support emergency services by delivering food and rescuing residents after major natural disasters.","vi":"Quân nhân có thể hỗ trợ các dịch vụ ứng phó khẩn cấp bằng cách phân phát lương thực và giải cứu người dân sau các thảm họa thiên nhiên lớn.","audioKind":"ex2"}],"collocations":[{"en":"serve as a soldier","vi":"phục vụ trong quân ngũ"},{"en":"professional soldier","vi":"quân nhân chuyên nghiệp"},{"en":"train soldiers","vi":"huấn luyện binh lính"}],"wordFamily":["soldiering (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ binh sĩ lực lượng lục quân; thủy thủ và phi công có tên gọi riêng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_african', 'en-a2-7', 'African', '/ˈæfrɪkən/', 'A2', 'thuộc về hoặc liên quan đến Châu Phi; người gốc Châu Phi; người Châu Phi', 'adj.', 'Africa (n.)', NULL, 'Chữ cái đầu tiên phải viết hoa; dùng để chỉ người đến từ Châu Phi mà không giới hạn màu da.', 'We spotted several African elephants beside a muddy waterhole.', NULL, 'Chúng tôi phát hiện thấy vài con voi Châu Phi bên một vũng nước đục ngầu.', '{"wordId":"african","ukIpa":"/ˈæfrɪkən/","usIpa":"/ˈæfrɪkən/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"relating to Africa or its people","vi":"thuộc về hoặc liên quan đến Châu Phi; người gốc Châu Phi"},{"pos":"n.","en":"a person from Africa","vi":"người Châu Phi"}],"examples":[{"en":"We spotted several African elephants beside a muddy waterhole.","vi":"Chúng tôi phát hiện thấy vài con voi Châu Phi bên một vũng nước đục ngầu.","audioKind":"ex"},{"en":"Many African countries are investing in solar energy to improve electricity access in remote rural communities.","vi":"Nhiều quốc gia Châu Phi đang đầu tư vào năng lượng mặt trời nhằm cải thiện việc tiếp cận điện năng ở các vùng nông thôn hẻo lánh.","audioKind":"ex2"}],"collocations":[{"en":"African countries","vi":"các quốc gia Châu Phi"},{"en":"African wildlife","vi":"động vật hoang dã Châu Phi"},{"en":"African languages","vi":"các ngôn ngữ Châu Phi"}],"wordFamily":["Africa (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái đầu tiên phải viết hoa; dùng để chỉ người đến từ Châu Phi mà không giới hạn màu da.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_support', 'en-a2-7', 'support', '/səˈpɔːrt/', 'A2', 'hỗ trợ; khuyến khích; chu cấp; đồng tình; đỡ; nâng; chịu lực; sự hỗ trợ; sự khuyến khích; tiền trợ cấp; vật chống đỡ', 'v.', 'supporter (n.), supportive (adj.), unsupported (adj.)', 'Đồng nghĩa: help, assist, back · Trái nghĩa: oppose', 'support là động từ (verb); danh từ (noun) thường đi với giới từ for.', 'My sister supports me whenever I try something new.', NULL, 'Chị tôi luôn ủng hộ tôi bất cứ khi nào tôi thử sức với điều gì mới.', '{"wordId":"support","ukIpa":"/səˈpɔːt/","usIpa":"/səˈpɔːrt/","cefr":"A2","topic":"society","senses":[{"pos":"v.","en":"to help, encourage, provide for, or agree with someone","vi":"hỗ trợ; khuyến khích; chu cấp; đồng tình"},{"pos":"v.","en":"to hold something up or bear its weight","vi":"đỡ; nâng; chịu lực"},{"pos":"n.","en":"help, encouragement, money, or something that holds another thing up","vi":"sự hỗ trợ; sự khuyến khích; tiền trợ cấp; vật chống đỡ"}],"examples":[{"en":"My sister supports me whenever I try something new.","vi":"Chị tôi luôn ủng hộ tôi bất cứ khi nào tôi thử sức với điều gì mới.","audioKind":"ex"},{"en":"Governments should provide financial support for small businesses that create jobs in economically disadvantaged communities.","vi":"Chính phủ nên cung cấp hỗ trợ tài chính cho các doanh nghiệp nhỏ tạo ra việc làm tại các cộng đồng có hoàn cảnh kinh tế khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"financial support","vi":"hỗ trợ tài chính"},{"en":"support a family","vi":"nuôi gia đình"},{"en":"support an argument","vi":"bổ sung lập luận"},{"en":"emotional support","vi":"hỗ trợ tinh thần"}],"wordFamily":["supporter (n.)","supportive (adj.)","unsupported (adj.)"],"synonyms":["help","assist","back"],"antonyms":["oppose"],"tipVi":"support là động từ (verb); danh từ (noun) thường đi với giới từ for.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_public', 'en-a2-7', 'public', '/ˈpʌblɪk/', 'A2', 'công cộng; chung; công khai; thuộc nhà nước; công lập; công chúng; quần chúng; người dân', 'adj.', 'publicly (adv.), publicity (n.), publicise (v.)', 'Trái nghĩa: private', 'the public chỉ công chúng; in public có nghĩa là ở nơi công cộng.', 'The public garden stays open until sunset every day.', NULL, 'Khu vườn công cộng này mở cửa cho đến tận lúc hoàng hôn mỗi ngày.', '{"wordId":"public","ukIpa":"/ˈpʌblɪk/","usIpa":"/ˈpʌblɪk/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"For everyone to use, see, or know about.","vi":"công cộng; chung; công khai"},{"pos":"adj.","en":"Provided or controlled by the government.","vi":"thuộc nhà nước; công lập"},{"pos":"n.","en":"Ordinary people in society considered as a group.","vi":"công chúng; quần chúng; người dân"}],"examples":[{"en":"The public garden stays open until sunset every day.","vi":"Khu vườn công cộng này mở cửa cho đến tận lúc hoàng hôn mỗi ngày.","audioKind":"ex"},{"en":"Investment in public transport can improve access to employment while reducing dependence on private cars.","vi":"Đầu tư vào giao thông công cộng có thể giúp người dân đi lại thuận tiện hơn đồng thời giảm sự phụ thuộc vào ô tô cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"public transport","vi":"giao thông công cộng"},{"en":"public services","vi":"dịch vụ công"},{"en":"the general public","vi":"đại đa số công chúng"},{"en":"in public","vi":"ở nơi công cộng"}],"wordFamily":["publicly (adv.)","publicity (n.)","publicise (v.)"],"synonyms":[],"antonyms":["private"],"tipVi":"the public chỉ công chúng; in public có nghĩa là ở nơi công cộng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_relationship', 'en-a2-7', 'relationship', '/rɪˈleɪʃənʃɪp/', 'A2', 'mối quan hệ; mối quan hệ tình cảm; mối liên hệ; sự liên quan', 'n.', 'relate (v.), related (adj.), relation (n.)', 'Đồng nghĩa: connection, link', 'Mối quan hệ với ai dùng với with; mối liên hệ giữa các sự vật dùng với between.', 'She has a warm relationship with her younger sister.', NULL, 'Cô ấy có một mối quan hệ rất thân thiết với cô em gái của mình.', '{"wordId":"relationship","ukIpa":"/rɪˈleɪʃənʃɪp/","usIpa":"/rɪˈleɪʃənʃɪp/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"The way people know, feel about, and treat each other.","vi":"mối quan hệ; mối quan hệ tình cảm"},{"pos":"n.","en":"A connection between things or the way they affect each other.","vi":"mối liên hệ; sự liên quan"}],"examples":[{"en":"She has a warm relationship with her younger sister.","vi":"Cô ấy có một mối quan hệ rất thân thiết với cô em gái của mình.","audioKind":"ex"},{"en":"Researchers are investigating the relationship between access to green spaces and mental health in urban communities.","vi":"Các nhà nghiên cứu đang điều tra mối liên hệ giữa việc tiếp cận không gian xanh và sức khỏe tinh thần ở các cộng đồng đô thị.","audioKind":"ex2"}],"collocations":[{"en":"build a relationship","vi":"xây dựng mối quan hệ"},{"en":"a close relationship","vi":"mối quan hệ thân thiết"},{"en":"the relationship between A and B","vi":"mối quan hệ giữa A và B"}],"wordFamily":["relate (v.)","related (adj.)","relation (n.)"],"synonyms":["connection","link"],"antonyms":[],"tipVi":"Mối quan hệ với ai dùng với with; mối liên hệ giữa các sự vật dùng với between.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_permission', 'en-a2-7', 'permission', '/pɚˈmɪʃən/', 'A2', 'sự cho phép; sự chấp thuận', 'n.', 'permit (v.), permissible (adj.), permissive (adj.)', 'Đồng nghĩa: consent, approval · Trái nghĩa: refusal', 'Thường là danh từ không đếm được; dùng give permission, không thêm mạo từ a.', 'You need permission to borrow your sister''s bicycle.', NULL, 'Bạn cần phải xin phép trước khi mượn xe đạp của chị gái.', '{"wordId":"permission","ukIpa":"/pəˈmɪʃən/","usIpa":"/pɚˈmɪʃən/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"agreement allowing someone to do something","vi":"sự cho phép; sự chấp thuận"}],"examples":[{"en":"You need permission to borrow your sister''s bicycle.","vi":"Bạn cần phải xin phép trước khi mượn xe đạp của chị gái.","audioKind":"ex"},{"en":"Researchers must obtain permission from participants before collecting personal information for a scientific study.","vi":"Các nhà nghiên cứu phải xin phép người tham gia trước khi thu thập thông tin cá nhân cho một nghiên cứu khoa học.","audioKind":"ex2"}],"collocations":[{"en":"ask for permission","vi":"xin phép"},{"en":"give permission","vi":"cấp phép"},{"en":"without permission","vi":"không có sự cho phép"},{"en":"permission to do something","vi":"sự cho phép làm điều gì đó"}],"wordFamily":["permit (v.)","permissible (adj.)","permissive (adj.)"],"synonyms":["consent","approval"],"antonyms":["refusal"],"tipVi":"Thường là danh từ không đếm được; dùng give permission, không thêm mạo từ a.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enemy', 'en-a2-7', 'enemy', '/ˈenəmi/', 'A2', 'kẻ thù; kẻ địch; mối họa; kẻ thù lớn', 'n.', NULL, 'Đồng nghĩa: foe, adversary · Trái nghĩa: friend, ally', 'enemy chỉ kẻ thù hoặc đối thủ đối địch quyết liệt; trong thi đấu thể thao thường dùng opponent.', 'In the story, the prince becomes friends with his enemy.', NULL, 'Trong câu chuyện, hoàng tử đã trở thành bạn với kẻ thù của mình.', '{"wordId":"enemy","ukIpa":"/ˈenəmi/","usIpa":"/ˈenəmi/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"A person or group that opposes or wants to harm another.","vi":"kẻ thù; kẻ địch"},{"pos":"n.","en":"Something that seriously harms or threatens something else.","vi":"mối họa; kẻ thù lớn"}],"examples":[{"en":"In the story, the prince becomes friends with his enemy.","vi":"Trong câu chuyện, hoàng tử đã trở thành bạn với kẻ thù của mình.","audioKind":"ex"},{"en":"Public distrust can become an enemy of effective environmental policy, particularly when governments fail to explain their decisions.","vi":"Sự thiếu tin tưởng từ công chúng có thể trở thành kẻ thù của chính sách môi trường hiệu quả, đặc biệt khi các chính phủ không giải thích quyết định của họ.","audioKind":"ex2"}],"collocations":[{"en":"bitter enemy","vi":"kẻ thù không đội trời chung"},{"en":"common enemy","vi":"kẻ thù chung"},{"en":"enemy forces","vi":"lực lượng địch"}],"wordFamily":[],"synonyms":["foe","adversary"],"antonyms":["friend","ally"],"tipVi":"enemy chỉ kẻ thù hoặc đối thủ đối địch quyết liệt; trong thi đấu thể thao thường dùng opponent.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_act', 'en-a2-7', 'act', '/ækt/', 'A2', 'hành động; cư xử; đóng vai; hành vi; cử chỉ; đạo luật; sắc luật', 'v.', 'action (n.), actor (n.), acting (n.), active (adj.)', NULL, 'act as có nghĩa là đóng vai trò hoặc làm nhiệm vụ gì đó; act cũng có thể chỉ một hồi trong kịch.', 'We must act quickly before the kitchen sink overflows.', NULL, 'Chúng ta phải hành động nhanh chóng trước khi bồn rửa trong bếp bị tràn nước.', '{"wordId":"act","ukIpa":"/ækt/","usIpa":"/ækt/","cefr":"A2","topic":"society","senses":[{"pos":"v.","en":"To take action, behave in a way, or perform a role.","vi":"hành động; cư xử; đóng vai"},{"pos":"n.","en":"Something that someone does.","vi":"hành vi; cử chỉ"},{"pos":"n.","en":"A law formally approved by a legislative body.","vi":"đạo luật; sắc luật"}],"examples":[{"en":"We must act quickly before the kitchen sink overflows.","vi":"Chúng ta phải hành động nhanh chóng trước khi bồn rửa trong bếp bị tràn nước.","audioKind":"ex"},{"en":"Governments need to act decisively to reduce air pollution and protect the health of urban residents.","vi":"Các chính phủ cần hành động quyết đoán để giảm ô nhiễm không khí và bảo vệ sức khỏe của cư dân đô thị.","audioKind":"ex2"}],"collocations":[{"en":"act quickly","vi":"hành động nhanh chóng"},{"en":"act as","vi":"đóng vai trò là"},{"en":"an act of kindness","vi":"một hành động tử tế"},{"en":"pass an act","vi":"thông qua một đạo luật"}],"wordFamily":["action (n.)","actor (n.)","acting (n.)","active (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"act as có nghĩa là đóng vai trò hoặc làm nhiệm vụ gì đó; act cũng có thể chỉ một hồi trong kịch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_princess', 'en-a2-7', 'princess', '/ˈprɪnses/', 'A2', 'công chúa; vương phi', 'n.', 'prince (n.)', NULL, 'Có thể dùng để chỉ con gái của vua/nữ hoàng, hoặc vợ của hoàng tử.', 'The princess waved to the crowd from her carriage.', NULL, 'Công chúa vẫy tay chào đám đông từ trên xe ngựa.', '{"wordId":"princess","ukIpa":"/ˌprɪnˈses/","usIpa":"/ˈprɪnses/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"A king''s or queen''s daughter, or a prince''s wife.","vi":"công chúa; vương phi"}],"examples":[{"en":"The princess waved to the crowd from her carriage.","vi":"Công chúa vẫy tay chào đám đông từ trên xe ngựa.","audioKind":"ex"},{"en":"Traditional stories often portray a princess as dependent, whereas modern adaptations increasingly emphasise her independence and leadership.","vi":"Các câu chuyện truyền thống thường khắc họa công chúa là người phụ thuộc, trong khi các tác phẩm chuyển thể hiện đại ngày càng nhấn mạnh sự độc lập và năng lực lãnh đạo của cô ấy.","audioKind":"ex2"}],"collocations":[{"en":"a royal princess","vi":"một vị vương nữ hoàng gia"},{"en":"a fairy-tale princess","vi":"công chúa trong truyện cổ tích"}],"wordFamily":["prince (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể dùng để chỉ con gái của vua/nữ hoàng, hoặc vợ của hoàng tử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_behavior', 'en-a2-7', 'behavior', '/bɪˈheɪvjər/', 'A2', 'hành vi; cách cư xử; thái độ; cách vận hành; cách phản ứng (của một hệ thống hoặc chất)', 'n.', 'behave (v.), behavioral (adj.)', 'Đồng nghĩa: conduct', 'Cách viết theo kiểu Mỹ; kiểu Anh là behaviour. Thường là danh từ không đếm được.', 'The puppy''s calm behavior surprised everyone at the park.', NULL, 'Cách cư xử điềm tĩnh của chú cún con khiến mọi người ở công viên ngạc nhiên.', '{"wordId":"behavior","ukIpa":"/bɪˈheɪvjə/","usIpa":"/bɪˈheɪvjər/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"the way a person or animal acts","vi":"hành vi; cách cư xử; thái độ"},{"pos":"n.","en":"the way a substance or system acts under particular conditions","vi":"cách vận hành; cách phản ứng (của một hệ thống hoặc chất)"}],"examples":[{"en":"The puppy''s calm behavior surprised everyone at the park.","vi":"Cách cư xử điềm tĩnh của chú cún con khiến mọi người ở công viên ngạc nhiên.","audioKind":"ex"},{"en":"Schools can encourage responsible behavior by giving students meaningful opportunities to participate in decisions affecting their community.","vi":"Nhà trường có thể khuyến khích hành vi có trách nhiệm bằng cách trao cho học sinh những cơ hội ý nghĩa để tham gia vào các quyết định ảnh hưởng đến cộng đồng của các em.","audioKind":"ex2"}],"collocations":[{"en":"good behavior","vi":"hành vi tốt"},{"en":"consumer behavior","vi":"hành vi người tiêu dùng"},{"en":"animal behavior","vi":"hành vi động vật"},{"en":"patterns of behavior","vi":"mô hình hành vi"}],"wordFamily":["behave (v.)","behavioral (adj.)"],"synonyms":["conduct"],"antonyms":[],"tipVi":"Cách viết theo kiểu Mỹ; kiểu Anh là behaviour. Thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_easter', 'en-a2-7', 'Easter', '/ˈiːstɚ/', 'A2', 'lễ Phục sinh', 'n.', NULL, NULL, 'Tên ngày lễ phải viết hoa chữ cái đầu; dùng at Easter để chỉ khoảng thời gian lễ Phục sinh.', 'We decorated eggs together at the kitchen table for Easter.', NULL, 'Chúng tôi cùng nhau trang trí trứng ở bàn bếp nhân dịp lễ Phục sinh.', '{"wordId":"easter","ukIpa":"/ˈiːstə/","usIpa":"/ˈiːstɚ/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"A Christian festival celebrating Jesus Christ''s return to life.","vi":"lễ Phục sinh"}],"examples":[{"en":"We decorated eggs together at the kitchen table for Easter.","vi":"Chúng tôi cùng nhau trang trí trứng ở bàn bếp nhân dịp lễ Phục sinh.","audioKind":"ex"},{"en":"During Easter, many destinations attract additional visitors through seasonal events, creating temporary employment in the tourism sector.","vi":"Vào dịp lễ Phục sinh, nhiều điểm đến thu hút lượng lớn du khách thông qua các sự kiện theo mùa, tạo ra việc làm thời vụ trong ngành du lịch.","audioKind":"ex2"}],"collocations":[{"en":"Easter Sunday","vi":"chủ nhật Phục sinh"},{"en":"Easter eggs","vi":"trứng Phục sinh"},{"en":"the Easter holidays","vi":"kỳ nghỉ Phục sinh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên ngày lễ phải viết hoa chữ cái đầu; dùng at Easter để chỉ khoảng thời gian lễ Phục sinh.","noteVi":"Đã viết hoa chữ cái đầu của tên ngày lễ.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_surname', 'en-a2-7', 'surname', '/ˈsɝːneɪm/', 'A2', 'họ; họ tên', 'n.', NULL, 'Đồng nghĩa: family name, last name', 'surname chỉ họ, given name chỉ tên; họ không nhất thiết luôn ở cuối.', 'My surname is often difficult for strangers to pronounce.', NULL, 'Họ của tôi thường khiến người lạ thấy khó phát âm.', '{"wordId":"surname","ukIpa":"/ˈsɜːneɪm/","usIpa":"/ˈsɝːneɪm/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"the name shared by members of a family","vi":"họ; họ tên"}],"examples":[{"en":"My surname is often difficult for strangers to pronounce.","vi":"Họ của tôi thường khiến người lạ thấy khó phát âm.","audioKind":"ex"},{"en":"Naming traditions vary across cultures, and a person''s surname may reflect family history or regional origins.","vi":"Truyền thống đặt tên khác nhau tùy theo nền văn hóa, và họ của một người có thể phản ánh lịch sử gia đình hoặc nguồn gốc vùng miền.","audioKind":"ex2"}],"collocations":[{"en":"family surname","vi":"họ gia đình"},{"en":"common surname","vi":"họ phổ biến"},{"en":"change your surname","vi":"đổi họ"}],"wordFamily":[],"synonyms":["family name","last name"],"antonyms":[],"tipVi":"surname chỉ họ, given name chỉ tên; họ không nhất thiết luôn ở cuối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_promise', 'en-a2-7', 'promise', '/ˈprɑːmɪs/', 'A2', 'hứa; cam kết; lời hứa; tiềm năng; triển vọng', 'v.', 'promising (adj.), unpromising (adj.)', 'Đồng nghĩa: pledge', 'Sử dụng promise to do, không dùng promise doing.', 'I promise to return your bicycle before dinner.', NULL, 'Tôi hứa sẽ trả lại chiếc xe đạp cho bạn trước bữa tối.', '{"wordId":"promise","ukIpa":"/ˈprɒmɪs/","usIpa":"/ˈprɑːmɪs/","cefr":"A2","topic":"society","senses":[{"pos":"v.","en":"to say firmly that you will do something","vi":"hứa; cam kết"},{"pos":"n.","en":"a firm statement that you will do something","vi":"lời hứa; cam kết"},{"pos":"n.","en":"signs that someone or something may succeed","vi":"tiềm năng; triển vọng"}],"examples":[{"en":"I promise to return your bicycle before dinner.","vi":"Tôi hứa sẽ trả lại chiếc xe đạp cho bạn trước bữa tối.","audioKind":"ex"},{"en":"Although renewable technologies show considerable promise, further investment is needed to make them widely affordable.","vi":"Mặc dù các công nghệ tái tạo cho thấy tiềm năng đáng kể, nhưng cần phải đầu tư thêm để chúng có giá cả phải chăng cho số đông.","audioKind":"ex2"}],"collocations":[{"en":"keep a promise","vi":"giữ lời hứa"},{"en":"break a promise","vi":"thất hứa"},{"en":"promise to do something","vi":"hứa làm điều gì đó"},{"en":"show promise","vi":"thể hiện tiềm năng"}],"wordFamily":["promising (adj.)","unpromising (adj.)"],"synonyms":["pledge"],"antonyms":[],"tipVi":"Sử dụng promise to do, không dùng promise doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_invitation', 'en-a2-7', 'invitation', '/ˌɪnvɪˈteɪʃən/', 'A2', 'lời mời; giấy mời', 'n.', 'invite (v.), inviting (adj.)', NULL, 'Khi mời tham gia sự kiện, dùng invitation to; khi mời làm việc gì, dùng cấu trúc invitation to do.', 'We received an invitation to our neighbour''s garden party.', NULL, 'Chúng tôi đã nhận được lời mời đến dự buổi tiệc ngoài vườn của người hàng xóm.', '{"wordId":"invitation","ukIpa":"/ˌɪnvɪˈteɪʃən/","usIpa":"/ˌɪnvɪˈteɪʃən/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"a request for someone to attend or join something","vi":"lời mời; giấy mời"}],"examples":[{"en":"We received an invitation to our neighbour''s garden party.","vi":"Chúng tôi đã nhận được lời mời đến dự buổi tiệc ngoài vườn của người hàng xóm.","audioKind":"ex"},{"en":"An invitation to participate in local planning can encourage residents to take greater responsibility for their neighbourhood.","vi":"Việc đưa ra lời mời tham gia vào công tác quy hoạch địa phương có thể khuyến khích cư dân nâng cao tinh thần trách nhiệm đối với cộng đồng của họ.","audioKind":"ex2"}],"collocations":[{"en":"accept an invitation","vi":"nhận lời mời"},{"en":"decline an invitation","vi":"từ chối lời mời"},{"en":"an invitation to dinner","vi":"lời mời ăn tối"},{"en":"by invitation only","vi":"chỉ dành cho khách mời"}],"wordFamily":["invite (v.)","inviting (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mời tham gia sự kiện, dùng invitation to; khi mời làm việc gì, dùng cấu trúc invitation to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_irish', 'en-a2-7', 'Irish', '/ˈaɪrɪʃ/', 'A2', 'thuộc về Ireland; thuộc về người Ireland; tiếng Ireland; người Ireland', 'adj.', 'Ireland (n.)', NULL, 'the Irish chỉ chung người Ireland; một cá nhân cụ thể dùng an Irish person.', 'An Irish musician played the fiddle at our festival.', NULL, 'Một nhạc sĩ người Ireland đã chơi đàn vĩ cầm tại lễ hội của chúng tôi.', '{"wordId":"irish","ukIpa":"/ˈaɪərɪʃ/","usIpa":"/ˈaɪrɪʃ/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"relating to Ireland, its people, or their culture","vi":"thuộc về Ireland; thuộc về người Ireland"},{"pos":"n.","en":"a Celtic language traditionally spoken in Ireland","vi":"tiếng Ireland"},{"pos":"n.","en":"the people of Ireland, referred to collectively","vi":"người Ireland"}],"examples":[{"en":"An Irish musician played the fiddle at our festival.","vi":"Một nhạc sĩ người Ireland đã chơi đàn vĩ cầm tại lễ hội của chúng tôi.","audioKind":"ex"},{"en":"Traditional Irish music can strengthen cultural identity while attracting visitors to rural communities across the country.","vi":"Âm nhạc truyền thống Ireland vừa có thể củng cố bản sắc văn hóa vừa thu hút du khách đến với các cộng đồng nông thôn trên khắp cả nước.","audioKind":"ex2"}],"collocations":[{"en":"Irish culture","vi":"văn hóa Ireland"},{"en":"Irish music","vi":"âm nhạc Ireland"},{"en":"speak Irish","vi":"nói tiếng Ireland"},{"en":"the Irish","vi":"người Ireland"}],"wordFamily":["Ireland (n.)"],"synonyms":[],"antonyms":[],"tipVi":"the Irish chỉ chung người Ireland; một cá nhân cụ thể dùng an Irish person.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_female', 'en-a2-7', 'female', '/ˈfiːmeɪl/', 'A2', 'thuộc giới nữ; cái; mái; giống cái; phụ nữ; con gái', 'adj.', NULL, 'Trái nghĩa: male', 'Chỉ phụ nữ trưởng thành thường dùng women; female dùng làm định ngữ rất tự nhiên.', 'The female lion rested beside her cubs in the shade.', NULL, 'Con sư tử cái nằm nghỉ ngơi bên cạnh bầy con của nó trong bóng râm.', '{"wordId":"female","ukIpa":"/ˈfiːmeɪl/","usIpa":"/ˈfiːmeɪl/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"Relating to women, girls, or animals that typically produce eggs.","vi":"thuộc giới nữ; cái; mái"},{"pos":"n.","en":"An animal or person of the female sex.","vi":"giống cái; phụ nữ; con gái"}],"examples":[{"en":"The female lion rested beside her cubs in the shade.","vi":"Con sư tử cái nằm nghỉ ngơi bên cạnh bầy con của nó trong bóng râm.","audioKind":"ex"},{"en":"Encouraging female students to study engineering can help reduce gender inequality in the technology sector.","vi":"Việc khuyến khích các nữ sinh học ngành kỹ thuật có thể giúp giảm thiểu tình trạng bất bình đẳng giới trong lĩnh vực công nghệ.","audioKind":"ex2"}],"collocations":[{"en":"female students","vi":"nữ sinh"},{"en":"female employees","vi":"nhân viên nữ"},{"en":"a female elephant","vi":"một con voi cái"}],"wordFamily":[],"synonyms":[],"antonyms":["male"],"tipVi":"Chỉ phụ nữ trưởng thành thường dùng women; female dùng làm định ngữ rất tự nhiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_popular', 'en-a2-7', 'popular', '/ˈpɑːpjələr/', 'A2', 'được yêu thích; phổ biến; thịnh hành; đại chúng; bình dân; phổ thông', 'adj.', 'popularity (n.), popularise (v.), unpopular (adj.)', 'Đồng nghĩa: well-liked · Trái nghĩa: unpopular', 'Để chỉ sự phổ biến đối với một nhóm đối tượng, thường dùng tính từ đi với giới từ popular with hoặc among.', 'This small café is popular with local students.', NULL, 'Quán cà phê nhỏ này rất được lòng các bạn học sinh sinh viên địa phương.', '{"wordId":"popular","ukIpa":"/ˈpɒpjələ/","usIpa":"/ˈpɑːpjələr/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"Liked or enjoyed by many people.","vi":"được yêu thích; phổ biến; thịnh hành"},{"pos":"adj.","en":"Intended for ordinary people rather than specialists.","vi":"đại chúng; bình dân; phổ thông"}],"examples":[{"en":"This small café is popular with local students.","vi":"Quán cà phê nhỏ này rất được lòng các bạn học sinh sinh viên địa phương.","audioKind":"ex"},{"en":"Popular science books can encourage public interest in research by explaining discoveries in accessible language.","vi":"Sách khoa học thường thức có thể khơi gợi sự quan tâm của công chúng đối với nghiên cứu bằng cách diễn giải các phát hiện khoa học qua ngôn ngữ dễ tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"popular with students","vi":"được học sinh yêu thích"},{"en":"increasingly popular","vi":"ngày càng phổ biến"},{"en":"popular culture","vi":"văn hóa đại chúng"},{"en":"popular science","vi":"khoa học phổ thông"}],"wordFamily":["popularity (n.)","popularise (v.)","unpopular (adj.)"],"synonyms":["well-liked"],"antonyms":["unpopular"],"tipVi":"Để chỉ sự phổ biến đối với một nhóm đối tượng, thường dùng tính từ đi với giới từ popular with hoặc among.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_behave', 'en-a2-7', 'behave', '/bɪˈheɪv/', 'A2', 'cư xử; có thái độ; cư xử đúng mực; tuân thủ quy củ; hoạt động; phản ứng', 'v.', 'behaviour (n.), behavioural (adj.), misbehave (v.)', 'Đồng nghĩa: act · Trái nghĩa: misbehave', 'behave yourself có nghĩa là giữ trật tự, cư xử đúng mực, không phải là "tự biểu diễn".', 'Our dog behaves calmly when visitors come to the house.', NULL, 'Con chó của chúng tôi cư xử rất điềm tĩnh khi có khách đến nhà.', '{"wordId":"behave","ukIpa":"/bɪˈheɪv/","usIpa":"/bɪˈheɪv/","cefr":"A2","topic":"society","senses":[{"pos":"v.","en":"to act in a particular way","vi":"cư xử; có thái độ"},{"pos":"v.","en":"to act politely and do what is expected","vi":"cư xử đúng mực; tuân thủ quy củ"},{"pos":"v.","en":"to work or react in a particular way","vi":"hoạt động; phản ứng"}],"examples":[{"en":"Our dog behaves calmly when visitors come to the house.","vi":"Con chó của chúng tôi cư xử rất điềm tĩnh khi có khách đến nhà.","audioKind":"ex"},{"en":"Children often learn how to behave in social situations by observing the adults around them.","vi":"Trẻ em thường học cách cư xử trong các tình huống xã hội bằng cách quan sát những người lớn xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"behave responsibly","vi":"cư xử có trách nhiệm"},{"en":"behave well","vi":"cư xử tốt; ngoan ngoãn"},{"en":"behave yourself","vi":"biết điều; cư xử đúng mực"},{"en":"behave like","vi":"cư xử giống như"}],"wordFamily":["behaviour (n.)","behavioural (adj.)","misbehave (v.)"],"synonyms":["act"],"antonyms":["misbehave"],"tipVi":"behave yourself có nghĩa là giữ trật tự, cư xử đúng mực, không phải là \"tự biểu diễn\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_organisation', 'en-a2-7', 'organisation', '/ˌɔːrɡənəˈzeɪʃən/', 'A2', 'tổ chức; cơ quan; đoàn thể; sự tổ chức; sự sắp xếp; tính ngăn nắp', 'n.', 'organise (v.), organiser (n.), organisational (adj.), organised (adj.)', NULL, 'Tiếng Anh-Anh thường viết là organisation, trong khi tiếng Anh-Mỹ thường viết là organization.', 'He joined a local organisation that rescues injured birds.', NULL, 'Anh ấy đã tham gia một tổ chức địa phương chuyên cứu hộ các loài chim bị thương.', '{"wordId":"organisation","ukIpa":"/ˌɔːɡənaɪˈzeɪʃən/","usIpa":"/ˌɔːrɡənəˈzeɪʃən/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"A group of people working together for a particular purpose.","vi":"tổ chức; cơ quan; đoàn thể"},{"pos":"n.","en":"The planning and arrangement of activities, people, or things.","vi":"sự tổ chức; sự sắp xếp; tính ngăn nắp"}],"examples":[{"en":"He joined a local organisation that rescues injured birds.","vi":"Anh ấy đã tham gia một tổ chức địa phương chuyên cứu hộ các loài chim bị thương.","audioKind":"ex"},{"en":"Effective organisation of healthcare services can shorten waiting times and improve access for rural communities.","vi":"Việc tổ chức hiệu quả các dịch vụ y tế có thể rút ngắn thời gian chờ đợi và cải thiện khả năng tiếp cận cho cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"charitable organisation","vi":"tổ chức từ thiện"},{"en":"international organisation","vi":"tổ chức quốc tế"},{"en":"non-governmental organisation","vi":"tổ chức phi chính phủ"},{"en":"require careful organisation","vi":"đòi hỏi sự sắp xếp chu đáo"}],"wordFamily":["organise (v.)","organiser (n.)","organisational (adj.)","organised (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Anh thường viết là organisation, trong khi tiếng Anh-Mỹ thường viết là organization.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_niece', 'en-a2-7', 'niece', '/niːs/', 'A2', 'cháu gái (con của anh chị em hoặc của vợ/chồng)', 'n.', NULL, NULL, 'Niece chỉ hậu bối nữ, nephew chỉ hậu bối nam.', 'My niece brought her new puppy to our picnic.', NULL, 'Cháu gái tôi đã mang chú cún cưng mới của con bé đến buổi dã ngoại của chúng tôi.', '{"wordId":"niece","ukIpa":"/niːs/","usIpa":"/niːs/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"A daughter of your sibling or your spouse''s sibling.","vi":"cháu gái (con của anh chị em hoặc của vợ/chồng)"}],"examples":[{"en":"My niece brought her new puppy to our picnic.","vi":"Cháu gái tôi đã mang chú cún cưng mới của con bé đến buổi dã ngoại của chúng tôi.","audioKind":"ex"},{"en":"Flexible working hours can help adults care for relatives, including a young niece or nephew.","vi":"Giờ làm việc linh hoạt có thể giúp người lớn chăm sóc người thân, bao gồm cả cháu gái hoặc cháu trai còn nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"young niece","vi":"cháu gái nhỏ tuổi"},{"en":"nieces and nephews","vi":"các cháu trai và cháu gái"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Niece chỉ hậu bối nữ, nephew chỉ hậu bối nam.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_joining', 'en-a2-7', 'joining', '/ˈdʒɔɪnɪŋ/', 'A2', 'việc gia nhập; việc tham gia; sự kết nối; sự liên kết', 'v.', 'join (v.), joint (n.)', NULL, 'Là dạng -ing của join; gia nhập tổ chức thì đi thẳng với tân ngữ, không thêm in.', 'I''m joining a swimming club near my house.', NULL, 'Tôi chuẩn bị tham gia một câu lạc bộ bơi lội gần nhà.', '{"wordId":"joining","ukIpa":"/ˈdʒɔɪnɪŋ/","usIpa":"/ˈdʒɔɪnɪŋ/","cefr":"A2","topic":"society","senses":[{"pos":"v.","en":"Becoming a member of a group or taking part.","vi":"việc gia nhập; việc tham gia"},{"pos":"v.","en":"Connecting two or more things together.","vi":"sự kết nối; sự liên kết"}],"examples":[{"en":"I''m joining a swimming club near my house.","vi":"Tôi chuẩn bị tham gia một câu lạc bộ bơi lội gần nhà.","audioKind":"ex"},{"en":"Joining local volunteer groups allows young people to gain practical experience while contributing to their communities.","vi":"Việc tham gia các nhóm tình nguyện địa phương giúp giới trẻ tích lũy kinh nghiệm thực tế đồng thời đóng góp cho cộng đồng của họ.","audioKind":"ex2"}],"collocations":[{"en":"joining a club","vi":"tham gia câu lạc bộ"},{"en":"joining forces","vi":"bắt tay hợp tác"},{"en":"joining two pieces together","vi":"nối hai mảnh lại với nhau"}],"wordFamily":["join (v.)","joint (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là dạng -ing của join; gia nhập tổ chức thì đi thẳng với tân ngữ, không thêm in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_greeting', 'en-a2-7', 'greeting', '/ˈɡriːtɪŋ/', 'A2', 'lời chào hỏi; sự chào đón; lời chúc mừng', 'n.', 'greet (v.)', 'Đồng nghĩa: salutation · Trái nghĩa: farewell', 'Biểu thị lời chúc dịp lễ thường dùng dạng số nhiều greetings, ví dụ birthday greetings.', 'She gave us a cheerful greeting at the door.', NULL, 'Cô ấy đã gửi cho chúng tôi một lời chào vui vẻ ngay tại cửa.', '{"wordId":"greeting","ukIpa":"/ˈɡriːtɪŋ/","usIpa":"/ˈɡriːtɪŋ/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"Words or actions used when meeting or welcoming someone.","vi":"lời chào hỏi; sự chào đón"},{"pos":"n.","en":"Friendly wishes expressed on a special occasion.","vi":"lời chúc mừng"}],"examples":[{"en":"She gave us a cheerful greeting at the door.","vi":"Cô ấy đã gửi cho chúng tôi một lời chào vui vẻ ngay tại cửa.","audioKind":"ex"},{"en":"Learning local greeting customs can help international students build relationships and avoid misunderstandings in their new environment.","vi":"Việc tìm hiểu các phong tục chào hỏi địa phương có thể giúp sinh viên quốc tế xây dựng mối quan hệ và tránh những hiểu lầm trong môi trường mới của họ.","audioKind":"ex2"}],"collocations":[{"en":"a warm greeting","vi":"một lời chào nồng nhiệt"},{"en":"exchange greetings","vi":"trao đổi lời chào"},{"en":"a greeting card","vi":"một tấm thiệp chúc mừng"},{"en":"birthday greetings","vi":"những lời chúc sinh nhật"}],"wordFamily":["greet (v.)"],"synonyms":["salutation"],"antonyms":["farewell"],"tipVi":"Biểu thị lời chúc dịp lễ thường dùng dạng số nhiều greetings, ví dụ birthday greetings.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prince', 'en-a2-7', 'prince', '/prɪns/', 'A2', 'hoàng tử; thân vương; quốc vương của một tiểu quốc', 'n.', 'princess (n.), princely (adj.)', NULL, 'Prince không chỉ có nghĩa là hoàng tử mà đôi khi còn chỉ thân vương hoặc người đứng đầu một công quốc.', 'The prince waved to visitors from the palace balcony.', NULL, 'Hoàng tử vẫy tay chào du khách từ ban công cung điện.', '{"wordId":"prince","ukIpa":"/prɪns/","usIpa":"/prɪns/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"A male royal family member, often a monarch''s son.","vi":"hoàng tử; thân vương"},{"pos":"n.","en":"A male ruler of a small independent state.","vi":"quốc vương của một tiểu quốc"}],"examples":[{"en":"The prince waved to visitors from the palace balcony.","vi":"Hoàng tử vẫy tay chào du khách từ ban công cung điện.","audioKind":"ex"},{"en":"In some constitutional monarchies, a prince may support charitable organisations without holding any direct political power.","vi":"Ở một số quốc gia quân chủ lập hiến, hoàng tử có thể hỗ trợ các tổ chức từ thiện mà không nắm giữ quyền lực chính trị trực tiếp nào.","audioKind":"ex2"}],"collocations":[{"en":"crown prince","vi":"thái tử"},{"en":"young prince","vi":"hoàng tử trẻ tuổi"}],"wordFamily":["princess (n.)","princely (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Prince không chỉ có nghĩa là hoàng tử mà đôi khi còn chỉ thân vương hoặc người đứng đầu một công quốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_introduce', 'en-a2-7', 'introduce', '/ˌɪntrəˈduːs/', 'A2', 'giới thiệu; ra mắt (tên tuổi của mọi người); đưa vào sử dụng; áp dụng lần đầu; giúp ai đó làm quen', 'v.', 'introduction (n.), introductory (adj.)', NULL, 'Khi giới thiệu ai với ai, dùng cấu trúc introduce A to B, tuyệt đối không dùng với with.', 'Let me introduce you to my new neighbour.', NULL, 'Để tôi giới thiệu bạn với người hàng xóm mới của tôi nhé.', '{"wordId":"introduce","ukIpa":"/ˌɪntrəˈdjuːs/","usIpa":"/ˌɪntrəˈduːs/","cefr":"A2","topic":"society","senses":[{"pos":"v.","en":"Tell people each other''s names when they first meet.","vi":"giới thiệu; ra mắt (tên tuổi của mọi người)"},{"pos":"v.","en":"Bring something into use or a place for the first time.","vi":"đưa vào sử dụng; áp dụng lần đầu"},{"pos":"v.","en":"Help someone experience or learn about something for the first time.","vi":"giới thiệu; giúp ai đó làm quen"}],"examples":[{"en":"Let me introduce you to my new neighbour.","vi":"Để tôi giới thiệu bạn với người hàng xóm mới của tôi nhé.","audioKind":"ex"},{"en":"Schools should introduce practical financial education to help students manage money responsibly in adult life.","vi":"Các trường học nên đưa chương trình giáo dục tài chính thực tế vào giảng dạy để giúp học sinh quản lý tiền bạc một cách có trách nhiệm khi trưởng thành.","audioKind":"ex2"}],"collocations":[{"en":"introduce yourself","vi":"tự giới thiệu bản thân"},{"en":"introduce someone to someone","vi":"giới thiệu ai với ai"},{"en":"introduce new measures","vi":"đưa ra các biện pháp mới"},{"en":"introduce someone to a subject","vi":"dẫn dắt ai đó làm quen với một môn học"}],"wordFamily":["introduction (n.)","introductory (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi giới thiệu ai với ai, dùng cấu trúc introduce A to B, tuyệt đối không dùng với with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_7_1', 'en-a2-7', 'Cách dùng “popular” (adj.) — được yêu thích; phổ biến; thịnh hành', 'popular with students  ·  increasingly popular  ·  popular culture', 'Để chỉ sự phổ biến đối với một nhóm đối tượng, thường dùng tính từ đi với giới từ popular with hoặc among.', 'Họ từ (Word Family): popularity (n.), popularise (v.), unpopular (adj.) | Đồng nghĩa: well-liked · Trái nghĩa: unpopular', '[{"hanzi":"This small café is popular with local students.","pinyin":"","meaning":"Quán cà phê nhỏ này rất được lòng các bạn học sinh sinh viên địa phương."},{"hanzi":"Popular science books can encourage public interest in research by explaining discoveries in accessible language.","pinyin":"","meaning":"Sách khoa học thường thức có thể khơi gợi sự quan tâm của công chúng đối với nghiên cứu bằng cách diễn giải các phát hiện khoa học qua ngôn ngữ dễ tiếp cận."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_7_2', 'en-a2-7', 'Cách dùng “prince” (n.) — hoàng tử; thân vương', 'crown prince  ·  young prince', 'Prince không chỉ có nghĩa là hoàng tử mà đôi khi còn chỉ thân vương hoặc người đứng đầu một công quốc.', 'Họ từ (Word Family): princess (n.), princely (adj.)', '[{"hanzi":"The prince waved to visitors from the palace balcony.","pinyin":"","meaning":"Hoàng tử vẫy tay chào du khách từ ban công cung điện."},{"hanzi":"In some constitutional monarchies, a prince may support charitable organisations without holding any direct political power.","pinyin":"","meaning":"Ở một số quốc gia quân chủ lập hiến, hoàng tử có thể hỗ trợ các tổ chức từ thiện mà không nắm giữ quyền lực chính trị trực tiếp nào."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_7_3', 'en-a2-7', 'Cách dùng “teenager” (n.) — thanh thiếu niên (từ 13 đến 19 tuổi)', 'a young teenager  ·  as a teenager  ·  teenagers'' needs', 'Chỉ dùng để chỉ người từ 13 đến 19 tuổi, không dùng để chỉ chung tất cả những người chưa thành niên.', 'Họ từ (Word Family): teenage (adj.), teen (n.) | Đồng nghĩa: teen, adolescent', '[{"hanzi":"As a teenager, I cycled to school every day.","pinyin":"","meaning":"Hồi còn là thanh thiếu niên, tôi đạp xe đi học mỗi ngày."},{"hanzi":"Schools should provide spaces where teenagers can discuss their concerns and receive support from trained staff.","pinyin":"","meaning":"Các trường học nên tạo không gian để thanh thiếu niên có thể thảo luận về những băn khoăn của mình và nhận sự hỗ trợ từ đội ngũ nhân viên được đào tạo."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_7_4', 'en-a2-7', 'Cách dùng “invitation” (n.) — lời mời; giấy mời', 'accept an invitation  ·  decline an invitation  ·  an invitation to dinner', 'Khi mời tham gia sự kiện, dùng invitation to; khi mời làm việc gì, dùng cấu trúc invitation to do.', 'Họ từ (Word Family): invite (v.), inviting (adj.)', '[{"hanzi":"We received an invitation to our neighbour''s garden party.","pinyin":"","meaning":"Chúng tôi đã nhận được lời mời đến dự buổi tiệc ngoài vườn của người hàng xóm."},{"hanzi":"An invitation to participate in local planning can encourage residents to take greater responsibility for their neighbourhood.","pinyin":"","meaning":"Việc đưa ra lời mời tham gia vào công tác quy hoạch địa phương có thể khuyến khích cư dân nâng cao tinh thần trách nhiệm đối với cộng đồng của họ."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_7_1', 'en-a2-7', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
