INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_7_1_8', 'ten_a2_7_1', 'permission', 'You need permission to borrow your sister''s bicycle.', 'You need permission to borrow your sister''s bicycle.', '/pɚˈmɪʃən/', 'Bạn cần phải xin phép trước khi mượn xe đạp của chị gái.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_7_1_1', 'en-a2-7', 'ten_a2_7_1', 'listening', 'listening', 'As a teenager, I cycled to school every day.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Công chúa vẫy tay chào đám đông từ trên xe ngựa.","Con chó của chúng tôi cư xử rất điềm tĩnh khi có khách đến nhà.","Một nhạc sĩ người Ireland đã chơi đàn vĩ cầm tại lễ hội của chúng tôi.","Hồi còn là thanh thiếu niên, tôi đạp xe đi học mỗi ngày."]'::jsonb, 3, 'As a teenager, I cycled to school every day. → Hồi còn là thanh thiếu niên, tôi đạp xe đi học mỗi ngày.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_7_1_2', 'en-a2-7', 'ten_a2_7_1', 'listening', 'listening', 'As a housewife, she manages a busy household.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Là một người nội trợ, cô ấy chu toàn mọi công việc bận rộn trong gia đình.","Chúng tôi phát hiện thấy vài con voi Châu Phi bên một vũng nước đục ngầu.","Trong câu chuyện, hoàng tử đã trở thành bạn với kẻ thù của mình.","Người lính đã giúp vận chuyển nhu yếu phẩm băng qua con đường ngập lụt."]'::jsonb, 0, 'As a housewife, she manages a busy household. → Là một người nội trợ, cô ấy chu toàn mọi công việc bận rộn trong gia đình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_7_1_3', 'en-a2-7', 'ten_a2_7_1', 'listening', 'listening', 'The soldier helped carry supplies across the flooded road.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Công chúa vẫy tay chào đám đông từ trên xe ngựa.","Quán cà phê nhỏ này rất được lòng các bạn học sinh sinh viên địa phương.","Người lính đã giúp vận chuyển nhu yếu phẩm băng qua con đường ngập lụt.","Chị tôi luôn ủng hộ tôi bất cứ khi nào tôi thử sức với điều gì mới."]'::jsonb, 2, 'The soldier helped carry supplies across the flooded road. → Người lính đã giúp vận chuyển nhu yếu phẩm băng qua con đường ngập lụt.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_7_2', 'en-a2-7', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_7_2_1', 'ten_a2_7_2', 'teenager', 'Schools should provide spaces where teenagers can discuss their concerns and receive support from trained staff.', 'Schools should provide spaces where teenagers can discuss their concerns and receive support from trained staff.', '/ˈtiːneɪdʒər/', 'Các trường học nên tạo không gian để thanh thiếu niên có thể thảo luận về những băn khoăn của mình và nhận sự hỗ trợ từ đội ngũ nhân viên được đào tạo.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_7_2_2', 'ten_a2_7_2', 'housewife', 'The unpaid work of a housewife contributes to family welfare but is often excluded from economic statistics.', 'The unpaid work of a housewife contributes to family welfare but is often excluded from economic statistics.', '/ˈhaʊswaɪf/', 'Công việc không lương của một người nội trợ góp phần quan trọng vào phúc lợi gia đình nhưng thường bị bỏ quên trong các số liệu thống kê kinh tế.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_7_2_3', 'ten_a2_7_2', 'soldier', 'Soldiers can support emergency services by delivering food and rescuing residents after major natural disasters.', 'Soldiers can support emergency services by delivering food and rescuing residents after major natural disasters.', '/ˈsoʊldʒɚ/', 'Quân nhân có thể hỗ trợ các dịch vụ ứng phó khẩn cấp bằng cách phân phát lương thực và giải cứu người dân sau các thảm họa thiên nhiên lớn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_7_2_4', 'ten_a2_7_2', 'African', 'Many African countries are investing in solar energy to improve electricity access in remote rural communities.', 'Many African countries are investing in solar energy to improve electricity access in remote rural communities.', '/ˈæfrɪkən/', 'Nhiều quốc gia Châu Phi đang đầu tư vào năng lượng mặt trời nhằm cải thiện việc tiếp cận điện năng ở các vùng nông thôn hẻo lánh.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_7_2_5', 'ten_a2_7_2', 'support', 'Governments should provide financial support for small businesses that create jobs in economically disadvantaged communities.', 'Governments should provide financial support for small businesses that create jobs in economically disadvantaged communities.', '/səˈpɔːrt/', 'Chính phủ nên cung cấp hỗ trợ tài chính cho các doanh nghiệp nhỏ tạo ra việc làm tại các cộng đồng có hoàn cảnh kinh tế khó khăn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_7_2_6', 'ten_a2_7_2', 'public', 'Investment in public transport can improve access to employment while reducing dependence on private cars.', 'Investment in public transport can improve access to employment while reducing dependence on private cars.', '/ˈpʌblɪk/', 'Đầu tư vào giao thông công cộng có thể giúp người dân đi lại thuận tiện hơn đồng thời giảm sự phụ thuộc vào ô tô cá nhân.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_7_2_1', 'en-a2-7', 'ten_a2_7_2', 'listening', 'listening', 'Schools should provide spaces where teenagers can discuss their concerns and receive support from trained staff.', NULL, 'Trong câu vừa nghe, từ “teenager” mang nghĩa nào sau đây?', '["thanh thiếu niên (từ 13 đến 19 tuổi)","đột ngột; bỗng nhiên","tròn; có hình tròn (hoặc hình cầu)","ở giữa; trong số"]'::jsonb, 0, '“teenager” (/ˈtiːneɪdʒər/): thanh thiếu niên (từ 13 đến 19 tuổi). Câu đầy đủ: Schools should provide spaces where teenagers can discuss their concerns and receive support from trained staff.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
