INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_7_2', 'en-a2-7', NULL, 'comprehensive_test', 'listening', 'As a housewife, she manages a busy household.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người lính đã giúp vận chuyển nhu yếu phẩm băng qua con đường ngập lụt.","Là một người nội trợ, cô ấy chu toàn mọi công việc bận rộn trong gia đình.","Khu vườn công cộng này mở cửa cho đến tận lúc hoàng hôn mỗi ngày.","Chúng tôi đã nhận được lời mời đến dự buổi tiệc ngoài vườn của người hàng xóm."]'::jsonb, 1, 'As a housewife, she manages a busy household. → Là một người nội trợ, cô ấy chu toàn mọi công việc bận rộn trong gia đình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
