INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_7_4', 'en-a2-7', NULL, 'comprehensive_test', 'listening', 'We spotted several African elephants beside a muddy waterhole.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chị tôi luôn ủng hộ tôi bất cứ khi nào tôi thử sức với điều gì mới.","Cách cư xử điềm tĩnh của chú cún con khiến mọi người ở công viên ngạc nhiên.","Cô ấy có một mối quan hệ rất thân thiết với cô em gái của mình.","Chúng tôi phát hiện thấy vài con voi Châu Phi bên một vũng nước đục ngầu."]'::jsonb, 3, 'We spotted several African elephants beside a muddy waterhole. → Chúng tôi phát hiện thấy vài con voi Châu Phi bên một vũng nước đục ngầu.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_7_5', 'en-a2-7', NULL, 'comprehensive_test', 'listening', 'support', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nam nhân viên bưu điện (người làm nghề phát thư từ và bưu phẩm)","ngón chân","phương hướng; hướng đi","hỗ trợ; khuyến khích; chu cấp; đồng tình"]'::jsonb, 3, 'support (/səˈpɔːrt/) → hỗ trợ; khuyến khích; chu cấp; đồng tình; đỡ; nâng; chịu lực; sự hỗ trợ; sự khuyến khích; tiền trợ cấp; vật chống đỡ', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_7_6', 'en-a2-7', NULL, 'comprehensive_test', 'listening', 'The public garden stays open until sunset every day.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Khu vườn công cộng này mở cửa cho đến tận lúc hoàng hôn mỗi ngày.","Con sư tử cái nằm nghỉ ngơi bên cạnh bầy con của nó trong bóng râm.","Chúng ta phải hành động nhanh chóng trước khi bồn rửa trong bếp bị tràn nước.","Công chúa vẫy tay chào đám đông từ trên xe ngựa."]'::jsonb, 0, 'The public garden stays open until sunset every day. → Khu vườn công cộng này mở cửa cho đến tận lúc hoàng hôn mỗi ngày.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
