INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_7_8', 'en-a2-7', NULL, 'comprehensive_test', 'listening', 'You need permission to borrow your sister''s bicycle.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi phát hiện thấy vài con voi Châu Phi bên một vũng nước đục ngầu.","Người lính đã giúp vận chuyển nhu yếu phẩm băng qua con đường ngập lụt.","Bạn cần phải xin phép trước khi mượn xe đạp của chị gái.","Cháu gái tôi đã mang chú cún cưng mới của con bé đến buổi dã ngoại của chúng tôi."]'::jsonb, 2, 'You need permission to borrow your sister''s bicycle. → Bạn cần phải xin phép trước khi mượn xe đạp của chị gái.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_7_9', 'en-a2-7', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to help, encourage, provide for, or agree with someone”?', '["behavior","behave","support","soldier"]'::jsonb, 2, 'support (/səˈpɔːrt/) → hỗ trợ; khuyến khích; chu cấp; đồng tình', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
