INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_7_18', 'en-a2-7', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should provide spaces where teenagers can discuss their concerns and receive support from trained staff.', 'Dựa vào câu trên, từ “teenager” có nghĩa phù hợp nhất là gì?', '["thanh thiếu niên (từ 13 đến 19 tuổi)","hoàng tử; thân vương","kỹ năng; kỹ xảo; sự khéo léo","tiếng Bồ Đào Nha"]'::jsonb, 0, 'teenager: thanh thiếu niên (từ 13 đến 19 tuổi). Dịch cả câu: Các trường học nên tạo không gian để thanh thiếu niên có thể thảo luận về những băn khoăn của mình và nhận sự hỗ trợ từ đội ngũ nhân viên được đào tạo.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_7_19', 'en-a2-7', NULL, 'comprehensive_test', 'reading', NULL, 'The unpaid work of a housewife contributes to family welfare but is often excluded from economic statistics.', 'Dựa vào câu trên, từ “housewife” có nghĩa phù hợp nhất là gì?', '["kinh nghiệm","vỗ tay; khua tay","nội trợ; bà nội trợ","chương trình; kế hoạch; đề án"]'::jsonb, 2, 'housewife: nội trợ; bà nội trợ. Dịch cả câu: Công việc không lương của một người nội trợ góp phần quan trọng vào phúc lợi gia đình nhưng thường bị bỏ quên trong các số liệu thống kê kinh tế.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_7_20', 'en-a2-7', NULL, 'comprehensive_test', 'reading', NULL, 'Soldiers can support emergency services by delivering food and rescuing residents after major natural disasters.', 'Dựa vào câu trên, từ “soldier” có nghĩa phù hợp nhất là gì?', '["trống rỗng; không có người","cửa hàng; tiệm","lính; quân nhân","nhà khoa học"]'::jsonb, 2, 'soldier: lính; quân nhân. Dịch cả câu: Quân nhân có thể hỗ trợ các dịch vụ ứng phó khẩn cấp bằng cách phân phát lương thực và giải cứu người dân sau các thảm họa thiên nhiên lớn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_7_21', 'en-a2-7', NULL, 'comprehensive_test', 'reading', NULL, 'Many African countries are investing in solar energy to improve electricity access in remote rural communities.', 'Dựa vào câu trên, từ “African” có nghĩa phù hợp nhất là gì?', '["ánh nắng; ánh mặt trời","gần nhất (về khoảng cách, thời gian hoặc sự tương đồng)","luật; pháp luật","thuộc về hoặc liên quan đến Châu Phi; người gốc Châu Phi"]'::jsonb, 3, 'African: thuộc về hoặc liên quan đến Châu Phi; người gốc Châu Phi; người Châu Phi. Dịch cả câu: Nhiều quốc gia Châu Phi đang đầu tư vào năng lượng mặt trời nhằm cải thiện việc tiếp cận điện năng ở các vùng nông thôn hẻo lánh.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
