INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_7_24', 'en-a2-7', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “giới thiệu; ra mắt (tên tuổi của mọi người)”', '["fit","introduce","wild","hope"]'::jsonb, 1, 'giới thiệu; ra mắt (tên tuổi của mọi người) → introduce (/ˌɪntrəˈduːs/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-8', 'en', 'Bài 8: Xã hội & Cộng đồng (3) - CEFR A2', 'CEFR A2', 'A2 · Xã hội', '26 từ vựng Tiếng Anh CEFR A2 chủ đề xã hội & cộng đồng kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2008, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_share', 'en-a2-8', 'share', '/ʃer/', 'A2', 'chia sẻ; dùng chung; gánh vác; phần; cổ phần; cổ phiếu', 'v.', 'sharing (n.), shareholder (n.)', NULL, 'Cấu trúc chia sẻ cái gì với ai dùng share something with someone.', 'My sister and I share a desk by the window.', NULL, 'Chị tôi và tôi dùng chung một chiếc bàn học bên cửa sổ.', '{"wordId":"share","ukIpa":"/ʃeə/","usIpa":"/ʃer/","cefr":"A2","topic":"society","senses":[{"pos":"v.","en":"To use, enjoy or take responsibility for something with others.","vi":"chia sẻ; dùng chung; gánh vác"},{"pos":"n.","en":"One part of something divided among people or groups.","vi":"phần; cổ phần"},{"pos":"n.","en":"One of the equal units of ownership in a company.","vi":"cổ phiếu"}],"examples":[{"en":"My sister and I share a desk by the window.","vi":"Chị tôi và tôi dùng chung một chiếc bàn học bên cửa sổ.","audioKind":"ex"},{"en":"When residents share responsibility for public spaces, neighbourhoods often become cleaner and more welcoming.","vi":"Khi cư dân cùng chia sẻ trách nhiệm đối với các không gian công cộng, các khu81 dân cư thường trở nên sạch sẽ và đáng sống hơn.","audioKind":"ex2"}],"collocations":[{"en":"share something with someone","vi":"chia sẻ cái gì với ai"},{"en":"share responsibility","vi":"chia sẻ trách nhiệm"},{"en":"market share","vi":"thị phần"},{"en":"buy shares","vi":"mua cổ phiếu"}],"wordFamily":["sharing (n.)","shareholder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc chia sẻ cái gì với ai dùng share something with someone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_steal', 'en-a2-8', 'steal', '/stiːl/', 'A2', 'trộm cắp; lấy cắp; lẻn đi; di chuyển nhẹ nhàng; món hời; đồ mua được với giá rẻ bất ngờ', 'v.', 'stolen (adj.)', NULL, 'Quá khứ là stole, phân từ hai là stolen; tân ngữ thường là vật.', 'Someone stole my bicycle while I was buying bread.', NULL, 'Ai đó đã lấy trộm chiếc xe đạp của tôi trong lúc tôi đi mua bánh mì.', '{"wordId":"steal","ukIpa":"/stiːl/","usIpa":"/stiːl/","cefr":"A2","topic":"society","senses":[{"pos":"v.","en":"to take something without permission and keep or use it","vi":"trộm cắp; lấy cắp"},{"pos":"v.","en":"to move quietly without attracting attention","vi":"lẻn đi; di chuyển nhẹ nhàng"},{"pos":"n.","en":"something bought for much less than its usual price","vi":"món hời; đồ mua được với giá rẻ bất ngờ"}],"examples":[{"en":"Someone stole my bicycle while I was buying bread.","vi":"Ai đó đã lấy trộm chiếc xe đạp của tôi trong lúc tôi đi mua bánh mì.","audioKind":"ex"},{"en":"Companies must protect customer information because criminals may steal personal data from insecure websites.","vi":"Các công ty phải bảo vệ thông tin của khách hàng vì tội phạm có thể đánh cắp dữ liệu cá nhân từ các trang web kém bảo mật.","audioKind":"ex2"}],"collocations":[{"en":"steal from someone","vi":"trộm cắp từ ai đó"},{"en":"steal an idea","vi":"đánh cắp ý tưởng"},{"en":"steal the show","vi":"thu hút toàn bộ sự chú ý; cướp sân khấu"}],"wordFamily":["stolen (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ là stole, phân từ hai là stolen; tân ngữ thường là vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_modern', 'en-a2-8', 'modern', '/ˈmɑːdərn/', 'A2', 'hiện đại; đương đại; tiên tiến; hợp thời trang; kiểu mới', 'adj.', 'modernise (v.), modernisation (n.), modernity (n.)', 'Đồng nghĩa: contemporary · Trái nghĩa: ancient, old-fashioned', 'modern nhấn mạnh tính hiện đại hoặc kiểu dáng mới; không nhất thiết phải vừa mới được sản xuất.', 'Our flat has a modern kitchen with large windows.', NULL, 'Căn hộ của chúng tôi có một nhà bếp kiểu mới với những ô cửa sổ lớn.', '{"wordId":"modern","ukIpa":"/ˈmɒdən/","usIpa":"/ˈmɑːdərn/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"Relating to the present or relatively recent times.","vi":"hiện đại; đương đại"},{"pos":"adj.","en":"Using the latest ideas, methods, or styles.","vi":"tiên tiến; hợp thời trang; kiểu mới"}],"examples":[{"en":"Our flat has a modern kitchen with large windows.","vi":"Căn hộ của chúng tôi có một nhà bếp kiểu mới với những ô cửa sổ lớn.","audioKind":"ex"},{"en":"Modern technology allows students in remote areas to access educational resources previously available only in cities.","vi":"Công nghệ hiện đại cho phép học sinh ở các vùng sâu vùng xa tiếp cận các nguồn lực giáo dục vốn trước đây chỉ có ở các thành phố.","audioKind":"ex2"}],"collocations":[{"en":"modern society","vi":"xã hội hiện đại"},{"en":"modern technology","vi":"công nghệ hiện đại"},{"en":"modern architecture","vi":"kiến trúc hiện đại"}],"wordFamily":["modernise (v.)","modernisation (n.)","modernity (n.)"],"synonyms":["contemporary"],"antonyms":["ancient","old-fashioned"],"tipVi":"modern nhấn mạnh tính hiện đại hoặc kiểu dáng mới; không nhất thiết phải vừa mới được sản xuất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_father-in-law', 'en-a2-8', 'father-in-law', '/ˈfɑːðər ɪn lɔː/', 'A2', 'bố vợ; bố chồng', 'n.', NULL, NULL, 'Không phải là cha dượng; cha dượng là stepfather.', 'My father-in-law helped us repair the garden fence.', NULL, 'Bố vợ tôi đã giúp chúng tôi sửa hàng rào khu vườn.', '{"wordId":"father-in-law","ukIpa":"/ˈfɑːðər ɪn lɔː/","usIpa":"/ˈfɑːðər ɪn lɔː/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"the father of your husband or wife","vi":"bố vợ; bố chồng"}],"examples":[{"en":"My father-in-law helped us repair the garden fence.","vi":"Bố vợ tôi đã giúp chúng tôi sửa hàng rào khu vườn.","audioKind":"ex"},{"en":"Living with a father-in-law may encourage families to share household expenses and provide care across generations.","vi":"Sống cùng bố chồng có thể giúp các gia đình chia sẻ chi phí sinh hoạt và chăm sóc lẫn nhau giữa các thế hệ.","audioKind":"ex2"}],"collocations":[{"en":"future father-in-law","vi":"bố vợ tương lai; bố chồng tương lai"},{"en":"elderly father-in-law","vi":"bố vợ lớn tuổi; bố chồng lớn tuổi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Không phải là cha dượng; cha dượng là stepfather.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_against', 'en-a2-8', 'against', '/əˈɡenst/', 'A2', 'chống lại; phản đối; dựa vào; tì vào; phòng ngừa', 'prep.', NULL, NULL, 'against là giới từ (prep.), đi kèm phía sau là danh từ, đại từ hoặc danh động từ.', 'Our team is playing against the neighbours this afternoon.', NULL, 'Chiều nay đội của chúng tôi sẽ thi đấu với đội hàng xóm.', '{"wordId":"against","ukIpa":"/əˈɡenst/","usIpa":"/əˈɡenst/","cefr":"A2","topic":"society","senses":[{"pos":"prep.","en":"Opposing someone or something, or competing with them.","vi":"chống lại; phản đối"},{"pos":"prep.","en":"Touching or supported by a surface.","vi":"dựa vào; tì vào"},{"pos":"prep.","en":"For protection from something harmful or unwanted.","vi":"phòng ngừa; chống lại"}],"examples":[{"en":"Our team is playing against the neighbours this afternoon.","vi":"Chiều nay đội của chúng tôi sẽ thi đấu với đội hàng xóm.","audioKind":"ex"},{"en":"Some residents are against airport expansion because they fear increased noise and damage to nearby habitats.","vi":"Một số cư dân phản đối việc mở rộng sân bay vì họ lo ngại tiếng ồn gia tăng và các khu ốc đảo sinh thái lân cận bị tàn phá.","audioKind":"ex2"}],"collocations":[{"en":"vote against","vi":"bỏ phiếu chống"},{"en":"lean against","vi":"tì lưng vào"},{"en":"protect against","vi":"bảo vệ chống lại"},{"en":"against the law","vi":"trái pháp luật"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"against là giới từ (prep.), đi kèm phía sau là danh từ, đại từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_neighbour', 'en-a2-8', 'neighbour', '/ˈneɪbɚ/', 'A2', 'láng giềng; người hàng xóm', 'n.', 'neighbourhood (n.), neighbouring (adj.), neighbourly (adj.)', NULL, 'Cách viết theo tiếng Anh-Anh là neighbour, còn tiếng Anh-Mỹ là neighbor.', 'Our neighbour watered the plants while we were away.', NULL, 'Hàng xóm của chúng tôi đã tưới cây giúp trong lúc chúng tôi đi vắng.', '{"wordId":"neighbour","ukIpa":"/ˈneɪbə/","usIpa":"/ˈneɪbɚ/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"someone living nearby, or something located next to another","vi":"láng giềng; người hàng xóm"}],"examples":[{"en":"Our neighbour watered the plants while we were away.","vi":"Hàng xóm của chúng tôi đã tưới cây giúp trong lúc chúng tôi đi vắng.","audioKind":"ex"},{"en":"Shared gardens can strengthen relationships between neighbours and create a greater sense of belonging in urban communities.","vi":"Các khu vườn chung có thể thắt chặt mối quan hệ giữa những người hàng xóm và tạo ra ý thức cộng đồng lớn hơn ở các khu đô thị.","audioKind":"ex2"}],"collocations":[{"en":"next-door neighbour","vi":"hàng xóm sát vách"},{"en":"close neighbours","vi":"hàng xóm gần gũi"},{"en":"neighbouring countries","vi":"các nước láng giềng"}],"wordFamily":["neighbourhood (n.)","neighbouring (adj.)","neighbourly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cách viết theo tiếng Anh-Anh là neighbour, còn tiếng Anh-Mỹ là neighbor.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_canadian', 'en-a2-8', 'Canadian', '/kəˈneɪdiən/', 'A2', 'thuộc về hoặc liên quan đến đất nước, người dân hoặc văn hóa Canada; người Canada', 'adj.', 'Canada (n.)', NULL, 'Các từ chỉ quốc tịch luôn viết hoa chữ cái đầu; dạng số nhiều của danh từ là Canadians.', 'Our Canadian neighbour invited us over for dinner yesterday.', NULL, 'Người hàng xóm người Canada của chúng tôi đã mời chúng tôi đến nhà ăn tối vào ngày hôm qua.', '{"wordId":"canadian","ukIpa":"/kəˈneɪdiən/","usIpa":"/kəˈneɪdiən/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"relating to Canada, its people, or its culture","vi":"thuộc về hoặc liên quan đến đất nước, người dân hoặc văn hóa Canada"},{"pos":"n.","en":"a person from Canada","vi":"người Canada"}],"examples":[{"en":"Our Canadian neighbour invited us over for dinner yesterday.","vi":"Người hàng xóm người Canada của chúng tôi đã mời chúng tôi đến nhà ăn tối vào ngày hôm qua.","audioKind":"ex"},{"en":"Canadian cities face challenges in providing affordable housing while accommodating population growth and protecting green spaces.","vi":"Các thành phố của Canada đang phải đối mặt với những thách thức trong việc cung cấp nhà ở giá rẻ đồng thời đáp ứng sự bùng nổ dân số và bảo vệ các không gian xanh.","audioKind":"ex2"}],"collocations":[{"en":"Canadian culture","vi":"văn hóa Canada"},{"en":"Canadian citizens","vi":"công dân Canada"},{"en":"Canadian dollars","vi":"đô la Canada"}],"wordFamily":["Canada (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Các từ chỉ quốc tịch luôn viết hoa chữ cái đầu; dạng số nhiều của danh từ là Canadians.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_twin', 'en-a2-8', 'twin', '/twɪn/', 'A2', 'anh chị em sinh đôi; sinh đôi, tạo thành một cặp giống nhau', 'n.', NULL, NULL, 'A twin chỉ một người trong cặp sinh đôi; twins dùng để chỉ cả hai người.', 'My twin and I share a love of swimming.', NULL, 'Tôi và người anh em sinh đôi của mình đều có chung tình yêu với môn bơi lội.', '{"wordId":"twin","ukIpa":"/twɪn/","usIpa":"/twɪn/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"One of two children born to the same mother together.","vi":"anh chị em sinh đôi"},{"pos":"adj.","en":"Forming a matching pair, or relating to twins.","vi":"sinh đôi, tạo thành một cặp giống nhau"}],"examples":[{"en":"My twin and I share a love of swimming.","vi":"Tôi và người anh em sinh đôi của mình đều có chung tình yêu với môn bơi lội.","audioKind":"ex"},{"en":"Studies involving identical twins help researchers understand how genes and environment influence human development.","vi":"Các nghiên cứu liên quan đến sinh đôi cùng trứng giúp các nhà nghiên cứu hiểu được cách gen và môi trường ảnh hưởng đến sự phát triển của con người.","audioKind":"ex2"}],"collocations":[{"en":"identical twins","vi":"sinh đôi cùng trứng"},{"en":"twin sister","vi":"chị em sinh đôi"},{"en":"twin beds","vi":"hai giường đơn giống nhau"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"A twin chỉ một người trong cặp sinh đôi; twins dùng để chỉ cả hai người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_argue', 'en-a2-8', 'argue', '/ˈɑːrɡjuː/', 'A2', 'cãi nhau; tranh cãi; lập luận; biện luận; cho rằng', 'v.', 'argument (n.), arguable (adj.), arguably (adv.), argumentative (adj.)', 'Đồng nghĩa: quarrel, contend · Trái nghĩa: agree', 'argue that thường được dùng trong các bài viết nghị luận để đưa ra một quan điểm có căn cứ.', 'The children argued about whose turn it was to play.', NULL, 'Bọn trẻ cãi nhau xem đến lượt ai chơi.', '{"wordId":"argue","ukIpa":"/ˈɑːɡjuː/","usIpa":"/ˈɑːrɡjuː/","cefr":"A2","topic":"society","senses":[{"pos":"v.","en":"To disagree with someone, often in an angry way.","vi":"cãi nhau; tranh cãi"},{"pos":"v.","en":"To give reasons supporting an opinion or position.","vi":"lập luận; biện luận; cho rằng"}],"examples":[{"en":"The children argued about whose turn it was to play.","vi":"Bọn trẻ cãi nhau xem đến lượt ai chơi.","audioKind":"ex"},{"en":"Some researchers argue that affordable public transport is essential for reducing inequality in large cities.","vi":"Một số nhà nghiên cứu lập luận rằng giao thông công cộng giá rẻ là yếu tố thiết yếu để giảm thiểu bất bình đẳng ở các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"argue with someone","vi":"cãi nhau với ai đó"},{"en":"argue about something","vi":"tranh cãi về điều gì đó"},{"en":"argue that","vi":"lập luận rằng..."},{"en":"argue for","vi":"lên tiếng ủng hộ; biện hộ cho"}],"wordFamily":["argument (n.)","arguable (adj.)","arguably (adv.)","argumentative (adj.)"],"synonyms":["quarrel","contend"],"antonyms":["agree"],"tipVi":"argue that thường được dùng trong các bài viết nghị luận để đưa ra một quan điểm có căn cứ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_behaviour', 'en-a2-8', 'behaviour', '/bɪˈheɪvjər/', 'A2', 'hành vi; thái độ; cách ứng xử; cách hoạt động; cách phản ứng', 'n.', 'behave (v.), behavioural (adj.), misbehave (v.), misbehaviour (n.)', 'Đồng nghĩa: conduct', 'Thường không đếm được; viết theo kiểu Anh là behaviour, kiểu Mỹ là behavior.', 'The puppy''s calm behaviour surprised everyone at the park.', NULL, 'Cách cư xử điềm tĩnh của chú cún đã khiến mọi người ở công viên ngạc nhiên.', '{"wordId":"behaviour","ukIpa":"/bɪˈheɪvjə/","usIpa":"/bɪˈheɪvjər/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"The way a person or animal acts.","vi":"hành vi; thái độ; cách ứng xử"},{"pos":"n.","en":"The way something functions or reacts under particular conditions.","vi":"cách hoạt động; cách phản ứng"}],"examples":[{"en":"The puppy''s calm behaviour surprised everyone at the park.","vi":"Cách cư xử điềm tĩnh của chú cún đã khiến mọi người ở công viên ngạc nhiên.","audioKind":"ex"},{"en":"Schools can encourage positive behaviour by establishing clear expectations and recognising students'' efforts to cooperate.","vi":"Nhà trường có thể khích lệ hành vi tích cực bằng cách thiết lập các kỳ vọng rõ ràng và ghi nhận nỗ lực hợp tác của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"good behaviour","vi":"hành vi tốt"},{"en":"consumer behaviour","vi":"hành vi tiêu dùng"},{"en":"animal behaviour","vi":"hành vi động vật"},{"en":"behaviour patterns","vi":"mô hình hành vi"}],"wordFamily":["behave (v.)","behavioural (adj.)","misbehave (v.)","misbehaviour (n.)"],"synonyms":["conduct"],"antonyms":[],"tipVi":"Thường không đếm được; viết theo kiểu Anh là behaviour, kiểu Mỹ là behavior.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wedding', 'en-a2-8', 'wedding', '/ˈwedɪŋ/', 'A2', 'lễ cưới; đám cưới', 'n.', 'wed (v.)', NULL, 'Wedding chỉ lễ cưới; marriage chỉ mối quan hệ hôn nhân.', 'Their wedding took place in a small garden.', NULL, 'Lễ cưới của họ diễn ra trong một khu vườn nhỏ.', '{"wordId":"wedding","ukIpa":"/ˈwedɪŋ/","usIpa":"/ˈwedɪŋ/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"A ceremony in which two people get married.","vi":"lễ cưới; đám cưới"}],"examples":[{"en":"Their wedding took place in a small garden.","vi":"Lễ cưới của họ diễn ra trong một khu vườn nhỏ.","audioKind":"ex"},{"en":"Wedding traditions often reflect cultural values, although many couples now choose simpler and less expensive celebrations.","vi":"Các truyền thống cưới hỏi thường phản ánh các giá trị văn hóa, mặc dù ngày nay nhiều cặp đôi chọn những buổi lễ đơn giản và ít tốn kém hơn.","audioKind":"ex2"}],"collocations":[{"en":"wedding ceremony","vi":"lễ cưới"},{"en":"wedding reception","vi":"tiệc cưới"},{"en":"wedding anniversary","vi":"lễ kỷ niệm ngày cưới"},{"en":"attend a wedding","vi":"tham dự đám cưới"}],"wordFamily":["wed (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Wedding chỉ lễ cưới; marriage chỉ mối quan hệ hôn nhân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crowd', 'en-a2-8', 'crowd', '/kraʊd/', 'A2', 'đám đông; quần chúng; chen chúc; tụ tập đông đúc', 'n.', 'crowded (adj.), crowding (n.), overcrowded (adj.)', NULL, 'Cụm a crowd of đi với danh từ số nhiều; crowded là tính từ mang nghĩa đông đúc.', 'A crowd gathered around the musicians in the square.', NULL, 'Một đám đông tụ tập quanh những người nghệ sĩ biểu diễn ở quảng trường.', '{"wordId":"crowd","ukIpa":"/kraʊd/","usIpa":"/kraʊd/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"A large group of people gathered in one place.","vi":"đám đông; quần chúng"},{"pos":"v.","en":"To gather closely together or fill a place with people.","vi":"chen chúc; tụ tập đông đúc"}],"examples":[{"en":"A crowd gathered around the musicians in the square.","vi":"Một đám đông tụ tập quanh những người nghệ sĩ biểu diễn ở quảng trường.","audioKind":"ex"},{"en":"Large crowds at popular attractions can damage historic sites unless visitor numbers are carefully managed.","vi":"Đám đông du khách chen chúc tại các điểm tham quan nổi tiếng có thể làm tổn hại đến các di tích lịch sử trừ khi số lượng khách tham quan được quản lý chặt chẽ.","audioKind":"ex2"}],"collocations":[{"en":"a large crowd","vi":"một đám đông lớn"},{"en":"attract a crowd","vi":"thu hút đám đông"},{"en":"crowd into","vi":"chen chúc vào"},{"en":"crowd control","vi":"kiểm soát đám đông"}],"wordFamily":["crowded (adj.)","crowding (n.)","overcrowded (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm a crowd of đi với danh từ số nhiều; crowded là tính từ mang nghĩa đông đúc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_traditional', 'en-a2-8', 'traditional', '/trəˈdɪʃənəl/', 'A2', 'truyền thống, theo tập quán lâu đời', 'adj.', 'tradition (n.), traditionally (adv.), traditionalist (n.)', 'Đồng nghĩa: conventional, customary · Trái nghĩa: non-traditional', 'traditional nhấn mạnh tính kế thừa lâu đời, không hàm ý mang nghĩa là lạc hậu.', 'We cooked a traditional meal for the family gathering.', NULL, 'Chúng tôi đã nấu một bữa ăn truyền thống cho buổi tụ họp gia đình.', '{"wordId":"traditional","ukIpa":"/trəˈdɪʃənəl/","usIpa":"/trəˈdɪʃənəl/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"Following customs or methods passed down over a long time.","vi":"truyền thống, theo tập quán lâu đời"}],"examples":[{"en":"We cooked a traditional meal for the family gathering.","vi":"Chúng tôi đã nấu một bữa ăn truyền thống cho buổi tụ họp gia đình.","audioKind":"ex"},{"en":"Traditional farming methods can preserve local knowledge, although some require adaptation to cope with climate change.","vi":"Các phương pháp canh tác truyền thống có thể bảo tồn tri thức bản địa, mặc dù một số phương pháp cần được điều chỉnh để đối phó với biến đổi khí hậu.","audioKind":"ex2"}],"collocations":[{"en":"traditional customs","vi":"phong tục truyền thống"},{"en":"traditional crafts","vi":"thủ công mỹ nghệ truyền thống"},{"en":"traditional methods","vi":"phương pháp truyền thống"}],"wordFamily":["tradition (n.)","traditionally (adv.)","traditionalist (n.)"],"synonyms":["conventional","customary"],"antonyms":["non-traditional"],"tipVi":"traditional nhấn mạnh tính kế thừa lâu đời, không hàm ý mang nghĩa là lạc hậu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thief', 'en-a2-8', 'thief', '/θiːf/', 'A2', 'kẻ trộm; kẻ cắp', 'n.', 'theft (n.), thieve (v.), thieving (n.)', NULL, 'Số nhiều là thieves; robber thường ám chỉ hành vi cướp bóc có bạo lực hoặc đe dọa.', 'The thief took my bicycle while I was shopping.', NULL, 'Kẻ trộm đã lấy mất chiếc xe đạp của tôi trong lúc tôi đi mua sắm.', '{"wordId":"thief","ukIpa":"/θiːf/","usIpa":"/θiːf/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"someone who steals another person''s belongings","vi":"kẻ trộm; kẻ cắp"}],"examples":[{"en":"The thief took my bicycle while I was shopping.","vi":"Kẻ trộm đã lấy mất chiếc xe đạp của tôi trong lúc tôi đi mua sắm.","audioKind":"ex"},{"en":"Secure bicycle parking can make it harder for a thief to steal from commuters.","vi":"Khu vực để xe đạp an toàn có thể khiến kẻ trộm khó lấy cắp đồ của người đi làm hơn.","audioKind":"ex2"}],"collocations":[{"en":"a bicycle thief","vi":"kẻ trộm xe đạp"},{"en":"catch a thief","vi":"bắt kẻ trộm"},{"en":"a petty thief","vi":"kẻ vặt; kẻ trộm cắp vặt"}],"wordFamily":["theft (n.)","thieve (v.)","thieving (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Số nhiều là thieves; robber thường ám chỉ hành vi cướp bóc có bạo lực hoặc đe dọa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_korean', 'en-a2-8', 'Korean', '/kəˈriːən/', 'A2', 'thuộc về Hàn Quốc, người Hàn Quốc hoặc tiếng Hàn; tiếng Hàn; tiếng Triều Tiên; người Hàn Quốc; người Triều Tiên', 'adj.', NULL, NULL, 'Korean có thể chỉ cả hai quốc gia trên Bán đảo Triều Tiên, nghĩa cụ thể phụ thuộc vào ngữ cảnh.', 'Our neighbour showed us how to make Korean dumplings.', NULL, 'Hàng xóm của chúng tôi đã chỉ cho chúng tôi cách làm bánh xếp Hàn Quốc.', '{"wordId":"korean","ukIpa":"/kəˈriːən/","usIpa":"/kəˈriːən/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"relating to Korea, its people, or its language","vi":"thuộc về Hàn Quốc, người Hàn Quốc hoặc tiếng Hàn"},{"pos":"n.","en":"the language spoken in North and South Korea","vi":"tiếng Hàn; tiếng Triều Tiên"},{"pos":"n.","en":"a person from North or South Korea","vi":"người Hàn Quốc; người Triều Tiên"}],"examples":[{"en":"Our neighbour showed us how to make Korean dumplings.","vi":"Hàng xóm của chúng tôi đã chỉ cho chúng tôi cách làm bánh xếp Hàn Quốc.","audioKind":"ex"},{"en":"Korean cinema has attracted international audiences, encouraging wider interest in the country''s language and cultural traditions.","vi":"Điện ảnh Hàn Quốc đã thu hút đông đảo khán giả quốc tế, khơi dậy sự quan tâm rộng rãi hơn đối với ngôn ngữ và truyền thống văn hóa của đất nước này.","audioKind":"ex2"}],"collocations":[{"en":"Korean language","vi":"tiếng Hàn"},{"en":"Korean cuisine","vi":"ẩm thực Hàn Quốc"},{"en":"learn Korean","vi":"học tiếng Hàn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Korean có thể chỉ cả hai quốc gia trên Bán đảo Triều Tiên, nghĩa cụ thể phụ thuộc vào ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indian', 'en-a2-8', 'Indian', '/ˈɪndiən/', 'A2', 'thuộc về Ấn Độ hoặc người Ấn Độ; người Ấn Độ', 'adj.', NULL, NULL, 'Viết hoa chữ cái đầu; khi chỉ người bản địa châu Mỹ (thổ dân), nên dùng cách gọi tự xưng của họ.', 'We cooked an Indian curry for dinner last night.', NULL, 'Tối qua chúng tôi đã nấu món cà ri Ấn Độ cho bữa tối.', '{"wordId":"indian","ukIpa":"/ˈɪndiən/","usIpa":"/ˈɪndiən/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"relating to India or its people","vi":"thuộc về Ấn Độ hoặc người Ấn Độ"},{"pos":"n.","en":"a person from India","vi":"người Ấn Độ"}],"examples":[{"en":"We cooked an Indian curry for dinner last night.","vi":"Tối qua chúng tôi đã nấu món cà ri Ấn Độ cho bữa tối.","audioKind":"ex"},{"en":"Indian cities face growing pressure to expand public transport as urban populations continue to increase.","vi":"Các thành phố ở Ấn Độ đang phải đối mặt với áp lực ngày càng lớn trong việc mở rộng giao thông công cộng khi dân số đô thị tiếp tục gia tăng.","audioKind":"ex2"}],"collocations":[{"en":"Indian cuisine","vi":"ẩm thực Ấn Độ"},{"en":"Indian culture","vi":"văn hóa Ấn Độ"},{"en":"the Indian Ocean","vi":"Ấn Độ Dương"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Viết hoa chữ cái đầu; khi chỉ người bản địa châu Mỹ (thổ dân), nên dùng cách gọi tự xưng của họ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_well-known', 'en-a2-8', 'well-known', '/ˌwel ˈnoʊn/', 'A2', 'nổi tiếng; được nhiều người biết đến', 'adj.', 'know (v.), known (adj.), unknown (adj.), knowledge (n.)', 'Đồng nghĩa: famous, renowned · Trái nghĩa: unknown, obscure', 'Thường có dấu gạch nối khi đứng trước danh từ; viết tách rời well known khi đứng ở vị trí vị ngữ.', 'We visited a well-known castle during our summer holiday.', NULL, 'Chúng tôi đã tham quan một lâu đài nổi tiếng trong kỳ nghỉ hè.', '{"wordId":"well-known","ukIpa":"/ˌwel ˈnəʊn/","usIpa":"/ˌwel ˈnoʊn/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"known or recognised by many people","vi":"nổi tiếng; được nhiều người biết đến"}],"examples":[{"en":"We visited a well-known castle during our summer holiday.","vi":"Chúng tôi đã tham quan một lâu đài nổi tiếng trong kỳ nghỉ hè.","audioKind":"ex"},{"en":"Well-known tourist destinations often face overcrowding, which can damage historic sites and reduce residents'' quality of life.","vi":"Các điểm đến du lịch nổi tiếng thường đối mặt với tình trạng quá tải, có thể làm tổn hại các di tích lịch sử và làm giảm chất lượng cuộc sống của người dân.","audioKind":"ex2"}],"collocations":[{"en":"well-known author","vi":"tác giả nổi tiếng"},{"en":"well-known landmark","vi":"địa danh nổi tiếng"},{"en":"well-known fact","vi":"sự thật ai cũng biết"}],"wordFamily":["know (v.)","known (adj.)","unknown (adj.)","knowledge (n.)"],"synonyms":["famous","renowned"],"antonyms":["unknown","obscure"],"tipVi":"Thường có dấu gạch nối khi đứng trước danh từ; viết tách rời well known khi đứng ở vị trí vị ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_human', 'en-a2-8', 'human', '/ˈhjuːmən/', 'A2', 'thuộc về con người; loài người; con người', 'adj.', 'humanity (n.), humanise (v.)', 'Trái nghĩa: non-human', 'human là "con người, thuộc về con người"; humane là "nhân đạo".', 'This robot can recognise a familiar human voice.', NULL, 'Con robot này có thể nhận diện được giọng nói quen thuộc của con người.', '{"wordId":"human","ukIpa":"/ˈhjuːmən/","usIpa":"/ˈhjuːmən/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"Relating to people rather than animals or machines.","vi":"thuộc về con người; loài người"},{"pos":"n.","en":"A person, as distinct from an animal or machine.","vi":"con người; loài người"}],"examples":[{"en":"This robot can recognise a familiar human voice.","vi":"Con robot này có thể nhận diện được giọng nói quen thuộc của con người.","audioKind":"ex"},{"en":"Human activity has significantly altered natural habitats, making wildlife conservation an urgent priority for governments.","vi":"Hoạt động của con người đã làm thay đổi đáng kể môi trường sống tự nhiên, khiến công tác bảo tồn động vật hoang dã trở thành một ưu tiên cấp bách đối với các chính phủ.","audioKind":"ex2"}],"collocations":[{"en":"human beings","vi":"con người"},{"en":"human rights","vi":"nền tảng nhân quyền"},{"en":"human activity","vi":"hoạt động của con người"},{"en":"human error","vi":"lỗi do con người"}],"wordFamily":["humanity (n.)","humanise (v.)"],"synonyms":[],"antonyms":["non-human"],"tipVi":"human là \"con người, thuộc về con người\"; humane là \"nhân đạo\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_peace', 'en-a2-8', 'peace', '/piːs/', 'A2', 'hòa bình; sự hòa thuận; sự bình yên; sự thanh thản', 'n.', 'peaceful (adj.), peacefully (adv.)', 'Đồng nghĩa: harmony, tranquillity · Trái nghĩa: war, conflict', 'Thường là danh từ không đếm được; peace of mind có nghĩa là sự an tâm, thảnh thơi.', 'I enjoy the peace of this garden before breakfast.', NULL, 'Tôi thích tận hưởng sự yên bình của khu vườn này trước bữa sáng.', '{"wordId":"peace","ukIpa":"/piːs/","usIpa":"/piːs/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"a situation without war, fighting, or serious disagreement","vi":"hòa bình; sự hòa thuận"},{"pos":"n.","en":"a state of quietness or freedom from worry","vi":"sự bình yên; sự thanh thản"}],"examples":[{"en":"I enjoy the peace of this garden before breakfast.","vi":"Tôi thích tận hưởng sự yên bình của khu vườn này trước bữa sáng.","audioKind":"ex"},{"en":"Lasting peace depends on cooperation between communities and fair access to essential resources.","vi":"Hòa bình bền vững phụ thuộc vào sự hợp tác giữa các cộng đồng và quyền tiếp cận công bằng đối với các nguồn tài nguyên thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"lasting peace","vi":"hòa bình bền vững"},{"en":"peace and quiet","vi":"sự yên tĩnh và thanh bình"},{"en":"peace of mind","vi":"sự bình yên trong tâm hồn"},{"en":"peace talks","vi":"đàm phán hòa bình"}],"wordFamily":["peaceful (adj.)","peacefully (adv.)"],"synonyms":["harmony","tranquillity"],"antonyms":["war","conflict"],"tipVi":"Thường là danh từ không đếm được; peace of mind có nghĩa là sự an tâm, thảnh thơi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_private', 'en-a2-8', 'private', '/ˈpraɪvət/', 'A2', 'riêng tư; cá nhân; tư nhân; tư sở; bí mật; kín đáo', 'adj.', 'privately (adv.), privacy (n.), privatise (v.), privatisation (n.)', 'Trái nghĩa: public', 'in private nghĩa là riêng tư; in public nghĩa là công khai.', 'Each guest has a private bathroom beside their bedroom.', NULL, 'Mỗi vị khách đều có một phòng tắm riêng bên cạnh phòng ngủ của họ.', '{"wordId":"private","ukIpa":"/ˈpraɪvət/","usIpa":"/ˈpraɪvət/","cefr":"A2","topic":"society","senses":[{"pos":"adj.","en":"For a particular person or group, not for everyone.","vi":"riêng tư; cá nhân"},{"pos":"adj.","en":"Owned or managed independently of the government.","vi":"tư nhân; tư sở"},{"pos":"adj.","en":"Not intended to be known or shared with others.","vi":"bí mật; kín đáo"}],"examples":[{"en":"Each guest has a private bathroom beside their bedroom.","vi":"Mỗi vị khách đều có một phòng tắm riêng bên cạnh phòng ngủ của họ.","audioKind":"ex"},{"en":"Private companies can improve public transport, but governments must ensure that fares remain affordable.","vi":"Các công ty tư nhân có thể cải thiện giao thông công cộng, nhưng chính phủ phải đảm bảo giá vé vẫn ở mức vừa túi tiền.","audioKind":"ex2"}],"collocations":[{"en":"private property","vi":"tài sản tư nhân"},{"en":"private sector","vi":"khu vực tư nhân"},{"en":"private life","vi":"đời tư"},{"en":"in private","vi":"riêng tư; kín đáo"}],"wordFamily":["privately (adv.)","privacy (n.)","privatise (v.)","privatisation (n.)"],"synonyms":[],"antonyms":["public"],"tipVi":"in private nghĩa là riêng tư; in public nghĩa là công khai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_million', 'en-a2-8', 'million', '/ˈmɪljən/', 'A2', 'một triệu', 'num.', NULL, NULL, 'Sau số từ cụ thể, million không thêm s; millions of dùng để chỉ hàng triệu.', 'The city now has more than a million residents.', NULL, 'Thành phố hiện có hơn một triệu cư dân.', '{"wordId":"million","ukIpa":"/ˈmɪljən/","usIpa":"/ˈmɪljən/","cefr":"A2","topic":"society","senses":[{"pos":"num.","en":"the number equal to a thousand thousands","vi":"một triệu"}],"examples":[{"en":"The city now has more than a million residents.","vi":"Thành phố hiện có hơn một triệu cư dân.","audioKind":"ex"},{"en":"The government plans to invest several million pounds in renewable energy projects over the next decade.","vi":"Chính phủ có kế hoạch đầu tư vài triệu bảng vào các dự án năng lượng tái tạo trong thập kỷ tới.","audioKind":"ex2"}],"collocations":[{"en":"a million people","vi":"một triệu người"},{"en":"two million pounds","vi":"hai triệu bảng"},{"en":"millions of people","vi":"hàng triệu người"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Sau số từ cụ thể, million không thêm s; millions of dùng để chỉ hàng triệu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gun', 'en-a2-8', 'gun', '/ɡʌn/', 'A2', 'súng (cầm tay hoặc đại bác); dụng cụ phun bắn có hình dạng giống khẩu súng', 'n.', 'gunfire (n.)', 'Đồng nghĩa: firearm', 'gun cũng có thể chỉ các thiết bị có hình dáng giống súng, chẳng hạn như glue gun (súng bắn keo).', 'The old gun was displayed behind glass at the museum.', NULL, 'Khẩu súng cũ được trưng bày phía sau tủ kính trong bảo tàng.', '{"wordId":"gun","ukIpa":"/ɡʌn/","usIpa":"/ɡʌn/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"a weapon that fires bullets or shells","vi":"súng (cầm tay hoặc đại bác)"},{"pos":"n.","en":"a tool shaped like a gun that releases a substance","vi":"dụng cụ phun bắn có hình dạng giống khẩu súng"}],"examples":[{"en":"The old gun was displayed behind glass at the museum.","vi":"Khẩu súng cũ được trưng bày phía sau tủ kính trong bảo tàng.","audioKind":"ex"},{"en":"Strict gun storage regulations can help prevent accidents and improve safety within local communities.","vi":"Các quy định nghiêm ngặt về việc bảo quản súng đạn có thể giúp ngăn ngừa tai nạn và nâng cao mức độ an toàn trong cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"gun control","vi":"kiểm soát súng đạn"},{"en":"a loaded gun","vi":"khẩu súng đã lên đạn"},{"en":"a glue gun","vi":"súng bắn keo"},{"en":"a spray gun","vi":"súng phun sơn"}],"wordFamily":["gunfire (n.)"],"synonyms":["firearm"],"antonyms":[],"tipVi":"gun cũng có thể chỉ các thiết bị có hình dáng giống súng, chẳng hạn như glue gun (súng bắn keo).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chance', 'en-a2-8', 'chance', '/tʃæns/', 'A2', 'cơ hội; khả năng; sự may rủi; tình cờ', 'n.', NULL, NULL, 'Cơ hội làm gì dùng chance to do; khả năng xảy ra điều gì thường dùng chance of doing.', 'Can you give me another chance to explain?', NULL, 'Bạn có thể cho tôi thêm một cơ hội để giải thích không?', '{"wordId":"chance","ukIpa":"/tʃɑːns/","usIpa":"/tʃæns/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"An opportunity to do something.","vi":"cơ hội"},{"pos":"n.","en":"The likelihood that something will happen.","vi":"khả năng"},{"pos":"n.","en":"Events happening without planning or a predictable cause.","vi":"sự may rủi; tình cờ"}],"examples":[{"en":"Can you give me another chance to explain?","vi":"Bạn có thể cho tôi thêm một cơ hội để giải thích không?","audioKind":"ex"},{"en":"Affordable training gives unemployed adults a chance to gain new skills and return to the workforce.","vi":"Các chương trình đào tạo vừa túi tiền mang đến cho những người lao động thất nghiệp cơ hội tiếp thu kỹ năng mới để tái gia nhập thị trường lao động.","audioKind":"ex2"}],"collocations":[{"en":"a chance to learn","vi":"cơ hội để học hỏi"},{"en":"a good chance of","vi":"nhiều khả năng xảy ra"},{"en":"by chance","vi":"tình cờ; ngẫu nhiên"},{"en":"take a chance","vi":"liều lĩnh thử một phen; nắm lấy cơ hội"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cơ hội làm gì dùng chance to do; khả năng xảy ra điều gì thường dùng chance of doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_officer', 'en-a2-8', 'officer', '/ˈɔːfɪsər/', 'A2', 'cảnh sát; sĩ quan cảnh sát; sĩ quan quân đội; viên chức; quan chức; nhân viên quản lý', 'n.', NULL, NULL, 'Từ officer có thể chỉ cảnh sát hoặc sĩ quan quân đội, nghĩa cụ thể phụ thuộc vào từ đi kèm.', 'A police officer helped us find the station.', NULL, 'Một cảnh sát đã giúp chúng tôi tìm nhà ga.', '{"wordId":"officer","ukIpa":"/ˈɒfɪsə/","usIpa":"/ˈɔːfɪsər/","cefr":"A2","topic":"society","senses":[{"pos":"n.","en":"A member of the police.","vi":"cảnh sát; sĩ quan cảnh sát"},{"pos":"n.","en":"A member of the armed forces with authority to command.","vi":"sĩ quan quân đội"},{"pos":"n.","en":"Someone with an official role in an organisation or government.","vi":"viên chức; quan chức; nhân viên quản lý"}],"examples":[{"en":"A police officer helped us find the station.","vi":"Một cảnh sát đã giúp chúng tôi tìm nhà ga.","audioKind":"ex"},{"en":"A local housing officer can advise residents on applying for affordable accommodation and accessing financial support.","vi":"Một nhân viên quản lý nhà ở địa phương có thể tư vấn cho cư dân về cách nộp đơn xin nhà ở xã hội và tiếp cận hỗ trợ tài chính.","audioKind":"ex2"}],"collocations":[{"en":"police officer","vi":"cảnh sát"},{"en":"army officer","vi":"sĩ quan quân đội"},{"en":"housing officer","vi":"cán bộ quản lý nhà ở"},{"en":"chief executive officer","vi":"giám đốc điều hành"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ officer có thể chỉ cảnh sát hoặc sĩ quan quân đội, nghĩa cụ thể phụ thuộc vào từ đi kèm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_belong', 'en-a2-8', 'belong', '/bɪˈlɔːŋ/', 'A2', 'thuộc về; ở đúng nơi; thuộc về nhóm nào đó; có cảm giác thuộc về', 'v.', 'belonging (n.), belongings (n.)', NULL, 'belong to chỉ sự sở hữu, không dùng ở thể bị động hoặc thì tiếp diễn.', 'This blue umbrella belongs to my younger sister.', NULL, 'Cây ô màu xanh này là của em gái tôi.', '{"wordId":"belong","ukIpa":"/bɪˈlɒŋ/","usIpa":"/bɪˈlɔːŋ/","cefr":"A2","topic":"society","senses":[{"pos":"v.","en":"To be owned by someone","vi":"thuộc về"},{"pos":"v.","en":"To have a proper place or category","vi":"ở đúng nơi; thuộc về nhóm nào đó"},{"pos":"v.","en":"To feel accepted as part of a group","vi":"có cảm giác thuộc về"}],"examples":[{"en":"This blue umbrella belongs to my younger sister.","vi":"Cây ô màu xanh này là của em gái tôi.","audioKind":"ex"},{"en":"Community centres provide welcoming spaces where newcomers can feel they belong and build lasting friendships.","vi":"Các trung tâm cộng đồng cung cấp không gian thân thiện, nơi những người mới đến có thể cảm thấy hòa nhập và xây dựng tình bạn lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"belong to someone","vi":"thuộc về ai đó"},{"en":"belong in a museum","vi":"đáng được trưng bày trong bảo tàng"},{"en":"feel you belong","vi":"cảm thấy mình thuộc về nơi này"}],"wordFamily":["belonging (n.)","belongings (n.)"],"synonyms":[],"antonyms":[],"tipVi":"belong to chỉ sự sở hữu, không dùng ở thể bị động hoặc thì tiếp diễn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_celebrate', 'en-a2-8', 'celebrate', '/ˈseləbreɪt/', 'A2', 'kỷ niệm; ăn mừng; tán dương; tôn vinh', 'v.', 'celebration (n.), celebratory (adj.), celebrated (adj.)', NULL, 'Ăn mừng việc gì đó dùng celebrate; chúc mừng ai đó dùng congratulate.', 'We cooked a special dinner to celebrate her graduation.', NULL, 'Chúng tôi đã nấu một bữa tối đặc biệt để ăn mừng lễ tốt nghiệp của cô ấy.', '{"wordId":"celebrate","ukIpa":"/ˈselɪbreɪt/","usIpa":"/ˈseləbreɪt/","cefr":"A2","topic":"society","senses":[{"pos":"v.","en":"To mark a special occasion by doing something enjoyable.","vi":"kỷ niệm; ăn mừng"},{"pos":"v.","en":"To praise someone or something publicly.","vi":"tán dương; tôn vinh"}],"examples":[{"en":"We cooked a special dinner to celebrate her graduation.","vi":"Chúng tôi đã nấu một bữa tối đặc biệt để ăn mừng lễ tốt nghiệp của cô ấy.","audioKind":"ex"},{"en":"Community festivals celebrate local traditions while giving residents opportunities to strengthen relationships with their neighbours.","vi":"Các lễ hội cộng đồng vừa tôn vinh các truyền thống địa phương vừa tạo cơ hội cho cư dân thắt chặt tình làng nghĩa xóm.","audioKind":"ex2"}],"collocations":[{"en":"celebrate a birthday","vi":"mừng sinh nhật"},{"en":"celebrate an achievement","vi":"kỷ niệm một thành tựu"},{"en":"celebrate diversity","vi":"tôn vinh sự đa dạng"}],"wordFamily":["celebration (n.)","celebratory (adj.)","celebrated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Ăn mừng việc gì đó dùng celebrate; chúc mừng ai đó dùng congratulate.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_8_1', 'en-a2-8', 'Cách dùng “well-known” (adj.) — nổi tiếng; được nhiều người biết đến', 'well-known author  ·  well-known landmark  ·  well-known fact', 'Thường có dấu gạch nối khi đứng trước danh từ; viết tách rời well known khi đứng ở vị trí vị ngữ.', 'Họ từ (Word Family): know (v.), known (adj.), unknown (adj.), knowledge (n.) | Đồng nghĩa: famous, renowned · Trái nghĩa: unknown, obscure', '[{"hanzi":"We visited a well-known castle during our summer holiday.","pinyin":"","meaning":"Chúng tôi đã tham quan một lâu đài nổi tiếng trong kỳ nghỉ hè."},{"hanzi":"Well-known tourist destinations often face overcrowding, which can damage historic sites and reduce residents'' quality of life.","pinyin":"","meaning":"Các điểm đến du lịch nổi tiếng thường đối mặt với tình trạng quá tải, có thể làm tổn hại các di tích lịch sử và làm giảm chất lượng cuộc sống của người dân."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_8_2', 'en-a2-8', 'Cách dùng “Indian” (adj.) — thuộc về Ấn Độ hoặc người Ấn Độ', 'Indian cuisine  ·  Indian culture  ·  the Indian Ocean', 'Viết hoa chữ cái đầu; khi chỉ người bản địa châu Mỹ (thổ dân), nên dùng cách gọi tự xưng của họ.', NULL, '[{"hanzi":"We cooked an Indian curry for dinner last night.","pinyin":"","meaning":"Tối qua chúng tôi đã nấu món cà ri Ấn Độ cho bữa tối."},{"hanzi":"Indian cities face growing pressure to expand public transport as urban populations continue to increase.","pinyin":"","meaning":"Các thành phố ở Ấn Độ đang phải đối mặt với áp lực ngày càng lớn trong việc mở rộng giao thông công cộng khi dân số đô thị tiếp tục gia tăng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_8_3', 'en-a2-8', 'Cách dùng “gun” (n.) — súng (cầm tay hoặc đại bác)', 'gun control  ·  a loaded gun  ·  a glue gun', 'gun cũng có thể chỉ các thiết bị có hình dáng giống súng, chẳng hạn như glue gun (súng bắn keo).', 'Họ từ (Word Family): gunfire (n.) | Đồng nghĩa: firearm', '[{"hanzi":"The old gun was displayed behind glass at the museum.","pinyin":"","meaning":"Khẩu súng cũ được trưng bày phía sau tủ kính trong bảo tàng."},{"hanzi":"Strict gun storage regulations can help prevent accidents and improve safety within local communities.","pinyin":"","meaning":"Các quy định nghiêm ngặt về việc bảo quản súng đạn có thể giúp ngăn ngừa tai nạn và nâng cao mức độ an toàn trong cộng đồng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_8_4', 'en-a2-8', 'Cách dùng “modern” (adj.) — hiện đại; đương đại', 'modern society  ·  modern technology  ·  modern architecture', 'modern nhấn mạnh tính hiện đại hoặc kiểu dáng mới; không nhất thiết phải vừa mới được sản xuất.', 'Họ từ (Word Family): modernise (v.), modernisation (n.), modernity (n.) | Đồng nghĩa: contemporary · Trái nghĩa: ancient, old-fashioned', '[{"hanzi":"Our flat has a modern kitchen with large windows.","pinyin":"","meaning":"Căn hộ của chúng tôi có một nhà bếp kiểu mới với những ô cửa sổ lớn."},{"hanzi":"Modern technology allows students in remote areas to access educational resources previously available only in cities.","pinyin":"","meaning":"Công nghệ hiện đại cho phép học sinh ở các vùng sâu vùng xa tiếp cận các nguồn lực giáo dục vốn trước đây chỉ có ở các thành phố."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_8_1', 'en-a2-8', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_8_1_1', 'ten_a2_8_1', 'share', 'My sister and I share a desk by the window.', 'My sister and I share a desk by the window.', '/ʃer/', 'Chị tôi và tôi dùng chung một chiếc bàn học bên cửa sổ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_8_1_2', 'ten_a2_8_1', 'steal', 'Someone stole my bicycle while I was buying bread.', 'Someone stole my bicycle while I was buying bread.', '/stiːl/', 'Ai đó đã lấy trộm chiếc xe đạp của tôi trong lúc tôi đi mua bánh mì.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_8_1_3', 'ten_a2_8_1', 'modern', 'Our flat has a modern kitchen with large windows.', 'Our flat has a modern kitchen with large windows.', '/ˈmɑːdərn/', 'Căn hộ của chúng tôi có một nhà bếp kiểu mới với những ô cửa sổ lớn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_8_1_4', 'ten_a2_8_1', 'father-in-law', 'My father-in-law helped us repair the garden fence.', 'My father-in-law helped us repair the garden fence.', '/ˈfɑːðər ɪn lɔː/', 'Bố vợ tôi đã giúp chúng tôi sửa hàng rào khu vườn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
