INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_8_1_7', 'ten_a2_8_1', 'Canadian', 'Our Canadian neighbour invited us over for dinner yesterday.', 'Our Canadian neighbour invited us over for dinner yesterday.', '/kəˈneɪdiən/', 'Người hàng xóm người Canada của chúng tôi đã mời chúng tôi đến nhà ăn tối vào ngày hôm qua.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_8_1_8', 'ten_a2_8_1', 'twin', 'My twin and I share a love of swimming.', 'My twin and I share a love of swimming.', '/twɪn/', 'Tôi và người anh em sinh đôi của mình đều có chung tình yêu với môn bơi lội.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_8_1_1', 'en-a2-8', 'ten_a2_8_1', 'listening', 'listening', 'My sister and I share a desk by the window.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chị tôi và tôi dùng chung một chiếc bàn học bên cửa sổ.","Lễ cưới của họ diễn ra trong một khu vườn nhỏ.","Hàng xóm của chúng tôi đã chỉ cho chúng tôi cách làm bánh xếp Hàn Quốc.","Người hàng xóm người Canada của chúng tôi đã mời chúng tôi đến nhà ăn tối vào ngày hôm qua."]'::jsonb, 0, 'My sister and I share a desk by the window. → Chị tôi và tôi dùng chung một chiếc bàn học bên cửa sổ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_8_1_2', 'en-a2-8', 'ten_a2_8_1', 'listening', 'listening', 'Someone stole my bicycle while I was buying bread.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tối qua chúng tôi đã nấu món cà ri Ấn Độ cho bữa tối.","Bố vợ tôi đã giúp chúng tôi sửa hàng rào khu vườn.","Kẻ trộm đã lấy mất chiếc xe đạp của tôi trong lúc tôi đi mua sắm.","Ai đó đã lấy trộm chiếc xe đạp của tôi trong lúc tôi đi mua bánh mì."]'::jsonb, 3, 'Someone stole my bicycle while I was buying bread. → Ai đó đã lấy trộm chiếc xe đạp của tôi trong lúc tôi đi mua bánh mì.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_8_1_3', 'en-a2-8', 'ten_a2_8_1', 'listening', 'listening', 'Our flat has a modern kitchen with large windows.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Căn hộ của chúng tôi có một nhà bếp kiểu mới với những ô cửa sổ lớn.","Chiều nay đội của chúng tôi sẽ thi đấu với đội hàng xóm.","Bạn có thể cho tôi thêm một cơ hội để giải thích không?","Ai đó đã lấy trộm chiếc xe đạp của tôi trong lúc tôi đi mua bánh mì."]'::jsonb, 0, 'Our flat has a modern kitchen with large windows. → Căn hộ của chúng tôi có một nhà bếp kiểu mới với những ô cửa sổ lớn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_8_2', 'en-a2-8', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_8_2_1', 'ten_a2_8_2', 'share', 'When residents share responsibility for public spaces, neighbourhoods often become cleaner and more welcoming.', 'When residents share responsibility for public spaces, neighbourhoods often become cleaner and more welcoming.', '/ʃer/', 'Khi cư dân cùng chia sẻ trách nhiệm đối với các không gian công cộng, các khu81 dân cư thường trở nên sạch sẽ và đáng sống hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_8_2_2', 'ten_a2_8_2', 'steal', 'Companies must protect customer information because criminals may steal personal data from insecure websites.', 'Companies must protect customer information because criminals may steal personal data from insecure websites.', '/stiːl/', 'Các công ty phải bảo vệ thông tin của khách hàng vì tội phạm có thể đánh cắp dữ liệu cá nhân từ các trang web kém bảo mật.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_8_2_3', 'ten_a2_8_2', 'modern', 'Modern technology allows students in remote areas to access educational resources previously available only in cities.', 'Modern technology allows students in remote areas to access educational resources previously available only in cities.', '/ˈmɑːdərn/', 'Công nghệ hiện đại cho phép học sinh ở các vùng sâu vùng xa tiếp cận các nguồn lực giáo dục vốn trước đây chỉ có ở các thành phố.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_8_2_4', 'ten_a2_8_2', 'father-in-law', 'Living with a father-in-law may encourage families to share household expenses and provide care across generations.', 'Living with a father-in-law may encourage families to share household expenses and provide care across generations.', '/ˈfɑːðər ɪn lɔː/', 'Sống cùng bố chồng có thể giúp các gia đình chia sẻ chi phí sinh hoạt và chăm sóc lẫn nhau giữa các thế hệ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_8_2_5', 'ten_a2_8_2', 'against', 'Some residents are against airport expansion because they fear increased noise and damage to nearby habitats.', 'Some residents are against airport expansion because they fear increased noise and damage to nearby habitats.', '/əˈɡenst/', 'Một số cư dân phản đối việc mở rộng sân bay vì họ lo ngại tiếng ồn gia tăng và các khu ốc đảo sinh thái lân cận bị tàn phá.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_8_2_6', 'ten_a2_8_2', 'neighbour', 'Shared gardens can strengthen relationships between neighbours and create a greater sense of belonging in urban communities.', 'Shared gardens can strengthen relationships between neighbours and create a greater sense of belonging in urban communities.', '/ˈneɪbɚ/', 'Các khu vườn chung có thể thắt chặt mối quan hệ giữa những người hàng xóm và tạo ra ý thức cộng đồng lớn hơn ở các khu đô thị.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_8_2_1', 'en-a2-8', 'ten_a2_8_2', 'listening', 'listening', 'When residents share responsibility for public spaces, neighbourhoods often become cleaner and more welcoming.', NULL, 'Trong câu vừa nghe, từ “share” mang nghĩa nào sau đây?', '["chứng đau răng; cơn đau răng","chia sẻ; dùng chung; gánh vác","chuyến bay, hành trình đường hàng không","có mặt; hiện tại"]'::jsonb, 1, '“share” (/ʃer/): chia sẻ; dùng chung; gánh vác. Câu đầy đủ: When residents share responsibility for public spaces, neighbourhoods often become cleaner and more welcoming.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_8_2_2', 'en-a2-8', 'ten_a2_8_2', 'listening', 'listening', 'Companies must protect customer information because criminals may steal personal data from insecure websites.', NULL, 'Trong câu vừa nghe, từ “steal” mang nghĩa nào sau đây?', '["trộm cắp; lấy cắp","sút; đá bằng chân","cái gương","người giao sữa"]'::jsonb, 0, '“steal” (/stiːl/): trộm cắp; lấy cắp. Câu đầy đủ: Companies must protect customer information because criminals may steal personal data from insecure websites.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
