INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_8_1', 'en-a2-8', NULL, 'comprehensive_test', 'listening', 'share', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chủ yếu là; phần lớn là","chia sẻ; dùng chung; gánh vác","người chiến thắng; đội chiến thắng","lời khuyên; sự hướng dẫn về việc ai đó nên làm gì trong một hoàn cảnh cụ thể"]'::jsonb, 1, 'share (/ʃer/) → chia sẻ; dùng chung; gánh vác; phần; cổ phần; cổ phiếu', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_8_2', 'en-a2-8', NULL, 'comprehensive_test', 'listening', 'Someone stole my bicycle while I was buying bread.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cây ô màu xanh này là của em gái tôi.","Chiều nay đội của chúng tôi sẽ thi đấu với đội hàng xóm.","Thành phố hiện có hơn một triệu cư dân.","Ai đó đã lấy trộm chiếc xe đạp của tôi trong lúc tôi đi mua bánh mì."]'::jsonb, 3, 'Someone stole my bicycle while I was buying bread. → Ai đó đã lấy trộm chiếc xe đạp của tôi trong lúc tôi đi mua bánh mì.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_8_3', 'en-a2-8', NULL, 'comprehensive_test', 'listening', 'modern', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["môn đánh gôn; môn thể thao đánh gôn","trang blog; nhật ký điện tử","hiện đại; đương đại","bản báo cáo; tường thuật"]'::jsonb, 2, 'modern (/ˈmɑːdərn/) → hiện đại; đương đại; tiên tiến; hợp thời trang; kiểu mới', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_8_4', 'en-a2-8', NULL, 'comprehensive_test', 'listening', 'My father-in-law helped us repair the garden fence.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã tham quan một lâu đài nổi tiếng trong kỳ nghỉ hè.","Bố vợ tôi đã giúp chúng tôi sửa hàng rào khu vườn.","Một đám đông tụ tập quanh những người nghệ sĩ biểu diễn ở quảng trường.","Người hàng xóm người Canada của chúng tôi đã mời chúng tôi đến nhà ăn tối vào ngày hôm qua."]'::jsonb, 1, 'My father-in-law helped us repair the garden fence. → Bố vợ tôi đã giúp chúng tôi sửa hàng rào khu vườn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_8_5', 'en-a2-8', NULL, 'comprehensive_test', 'listening', 'against', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["loại; kiểu; hạng","bình thường; theo quy luật","chống lại; phản đối","thuộc nam giới; thuộc giống đực"]'::jsonb, 2, 'against (/əˈɡenst/) → chống lại; phản đối; dựa vào; tì vào; phòng ngừa', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_8_6', 'en-a2-8', NULL, 'comprehensive_test', 'listening', 'Our neighbour watered the plants while we were away.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hàng xóm của chúng tôi đã tưới cây giúp trong lúc chúng tôi đi vắng.","Một cảnh sát đã giúp chúng tôi tìm nhà ga.","Kẻ trộm đã lấy mất chiếc xe đạp của tôi trong lúc tôi đi mua sắm.","Tôi và người anh em sinh đôi của mình đều có chung tình yêu với môn bơi lội."]'::jsonb, 0, 'Our neighbour watered the plants while we were away. → Hàng xóm của chúng tôi đã tưới cây giúp trong lúc chúng tôi đi vắng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_8_7', 'en-a2-8', NULL, 'comprehensive_test', 'listening', 'Canadian', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["lò vi sóng","Xốt-lân; Xéc-lân (Xơ-cốt-len)","vội vã; thúc giục","thuộc về hoặc liên quan đến đất nước, người dân hoặc văn hóa Canada"]'::jsonb, 3, 'Canadian (/kəˈneɪdiən/) → thuộc về hoặc liên quan đến đất nước, người dân hoặc văn hóa Canada; người Canada', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_8_8', 'en-a2-8', NULL, 'comprehensive_test', 'listening', 'My twin and I share a love of swimming.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã nấu một bữa ăn truyền thống cho buổi tụ họp gia đình.","Bạn có thể cho tôi thêm một cơ hội để giải thích không?","Tôi và người anh em sinh đôi của mình đều có chung tình yêu với môn bơi lội.","Chị tôi và tôi dùng chung một chiếc bàn học bên cửa sổ."]'::jsonb, 2, 'My twin and I share a love of swimming. → Tôi và người anh em sinh đôi của mình đều có chung tình yêu với môn bơi lội.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
