INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_8_18', 'en-a2-8', NULL, 'comprehensive_test', 'reading', NULL, 'When residents share responsibility for public spaces, neighbourhoods often become cleaner and more welcoming.', 'Dựa vào câu trên, từ “share” có nghĩa phù hợp nhất là gì?', '["chia sẻ; dùng chung; gánh vác","tương cà chua","máy ghi âm bằng băng từ","kiếm được; kiếm tiền"]'::jsonb, 0, 'share: chia sẻ; dùng chung; gánh vác; phần; cổ phần; cổ phiếu. Dịch cả câu: Khi cư dân cùng chia sẻ trách nhiệm đối với các không gian công cộng, các khu81 dân cư thường trở nên sạch sẽ và đáng sống hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_8_19', 'en-a2-8', NULL, 'comprehensive_test', 'reading', NULL, 'Companies must protect customer information because criminals may steal personal data from insecure websites.', 'Dựa vào câu trên, từ “steal” có nghĩa phù hợp nhất là gì?', '["dầu mỏ; dầu thô","hồ sơ; sổ sách; bản ghi chép","được chiên; được rán bằng dầu mỡ","trộm cắp; lấy cắp"]'::jsonb, 3, 'steal: trộm cắp; lấy cắp; lẻn đi; di chuyển nhẹ nhàng; món hời; đồ mua được với giá rẻ bất ngờ. Dịch cả câu: Các công ty phải bảo vệ thông tin của khách hàng vì tội phạm có thể đánh cắp dữ liệu cá nhân từ các trang web kém bảo mật.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_8_20', 'en-a2-8', NULL, 'comprehensive_test', 'reading', NULL, 'Modern technology allows students in remote areas to access educational resources previously available only in cities.', 'Dựa vào câu trên, từ “modern” có nghĩa phù hợp nhất là gì?', '["bạc (kim loại quý)","cuộc đua; cuộc thi chạy","hiện đại; đương đại","vùng quê; miền quê"]'::jsonb, 2, 'modern: hiện đại; đương đại; tiên tiến; hợp thời trang; kiểu mới. Dịch cả câu: Công nghệ hiện đại cho phép học sinh ở các vùng sâu vùng xa tiếp cận các nguồn lực giáo dục vốn trước đây chỉ có ở các thành phố.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_8_21', 'en-a2-8', NULL, 'comprehensive_test', 'reading', NULL, 'Living with a father-in-law may encourage families to share household expenses and provide care across generations.', 'Dựa vào câu trên, từ “father-in-law” có nghĩa phù hợp nhất là gì?', '["búp bê; con rối","bố vợ; bố chồng","máy tính (cầm tay hoặc ứng dụng tính toán)","quyết định; lựa chọn"]'::jsonb, 1, 'father-in-law: bố vợ; bố chồng. Dịch cả câu: Sống cùng bố chồng có thể giúp các gia đình chia sẻ chi phí sinh hoạt và chăm sóc lẫn nhau giữa các thế hệ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_8_22', 'en-a2-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cảnh sát; sĩ quan cảnh sát”', '["officer","running","wool","human"]'::jsonb, 0, 'cảnh sát; sĩ quan cảnh sát → officer (/ˈɔːfɪsər/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_8_23', 'en-a2-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc về”', '["secret","sauce","belong","oil"]'::jsonb, 2, 'thuộc về → belong (/bɪˈlɔːŋ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_8_24', 'en-a2-8', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “kỷ niệm; ăn mừng”', '["thousand","environment","celebrate","tenth"]'::jsonb, 2, 'kỷ niệm; ăn mừng → celebrate (/ˈseləbreɪt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-9', 'en', 'Bài 9: Thiên nhiên & Thời tiết (1) - CEFR A2', 'CEFR A2', 'A2 · Thiên nhiên', '26 từ vựng Tiếng Anh CEFR A2 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2009, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cloud', 'en-a2-9', 'cloud', '/klaʊd/', 'A2', 'đám mây; đám (khói, bụi); màn; làm lu mờ; làm mập mờ (suy nghĩ, phán đoán)', 'n.', 'cloudy (adj.), cloudless (adj.)', NULL, 'cloud dùng làm động từ có thể chỉ việc làm cho phán đoán không rõ ràng, chẳng hạn như cloud your judgment.', 'A dark cloud drifted slowly across the afternoon sky.', NULL, 'Một đám mây đen trôi lững lờ ngang qua bầu trời buổi chiều.', '{"wordId":"cloud","ukIpa":"/klaʊd/","usIpa":"/klaʊd/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"a visible mass of tiny water drops in the sky","vi":"đám mây"},{"pos":"n.","en":"a mass of smoke, dust, or similar material in air","vi":"đám (khói, bụi); màn"},{"pos":"v.","en":"to make thoughts or judgment less clear","vi":"làm lu mờ; làm mập mờ (suy nghĩ, phán đoán)"}],"examples":[{"en":"A dark cloud drifted slowly across the afternoon sky.","vi":"Một đám mây đen trôi lững lờ ngang qua bầu trời buổi chiều.","audioKind":"ex"},{"en":"Strong emotions can cloud public judgment when communities debate the benefits and risks of new technologies.","vi":"Cảm xúc mạnh mẽ có thể làm lu mờ phán đoán của công chúng khi cộng đồng tranh luận về lợi ích và rủi ro của các công nghệ mới.","audioKind":"ex2"}],"collocations":[{"en":"dark clouds","vi":"mây đen"},{"en":"a cloud of dust","vi":"một đám bụi"},{"en":"cloud someone''s judgment","vi":"làm lu mờ phán đoán của ai đó"}],"wordFamily":["cloudy (adj.)","cloudless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"cloud dùng làm động từ có thể chỉ việc làm cho phán đoán không rõ ràng, chẳng hạn như cloud your judgment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alive', 'en-a2-9', 'alive', '/əˈlaɪv/', 'A2', 'còn sống (thay vì đã chết); tràn đầy năng lượng; náo nhiệt; sôi động', 'adj.', 'live (v.), living (adj.), life (n.)', 'Đồng nghĩa: living · Trái nghĩa: dead', 'thường được đặt sau động từ liên kết; "cá sống" dùng là a live fish.', 'The tiny plant is still alive after our holiday.', NULL, 'Cây non vẫn còn sống sau kỳ nghỉ của chúng tôi.', '{"wordId":"alive","ukIpa":"/əˈlaɪv/","usIpa":"/əˈlaɪv/","cefr":"A2","topic":"nature","senses":[{"pos":"adj.","en":"Living rather than dead","vi":"còn sống (thay vì đã chết)"},{"pos":"adj.","en":"Full of energy, activity, or excitement","vi":"tràn đầy năng lượng; náo nhiệt; sôi động"}],"examples":[{"en":"The tiny plant is still alive after our holiday.","vi":"Cây non vẫn còn sống sau kỳ nghỉ của chúng tôi.","audioKind":"ex"},{"en":"Protecting natural habitats helps keep endangered species alive and preserves the ecological balance of entire regions.","vi":"Bảo vệ môi trường sống tự nhiên giúp duy trì sự sống cho các loài nguy cấp và giữ vững cân bằng sinh thái của toàn bộ khu vực.","audioKind":"ex2"}],"collocations":[{"en":"stay alive","vi":"sống sót"},{"en":"keep alive","vi":"giữ cho sống; duy trì"},{"en":"come alive","vi":"trở nên sôi động; náo nhiệt"},{"en":"alive with activity","vi":"tràn ngập hoạt động"}],"wordFamily":["live (v.)","living (adj.)","life (n.)"],"synonyms":["living"],"antonyms":["dead"],"tipVi":"thường được đặt sau động từ liên kết; \"cá sống\" dùng là a live fish.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forest', 'en-a2-9', 'forest', '/ˈfɔːrɪst/', 'A2', 'rừng; khu rừng lớn', 'n.', 'forestry (n.), forested (adj.), deforestation (n.), reforestation (n.)', 'Đồng nghĩa: woodland', 'forest thường chỉ vùng rừng lớn; wood có thể chỉ khu rừng nhỏ hơn.', 'We followed a narrow path deep into the forest.', NULL, 'Chúng tôi đi theo một lối mòn hẹp đi sâu vào trong rừng.', '{"wordId":"forest","ukIpa":"/ˈfɒrɪst/","usIpa":"/ˈfɔːrɪst/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"a large area of land covered mainly with trees","vi":"rừng; khu rừng lớn"}],"examples":[{"en":"We followed a narrow path deep into the forest.","vi":"Chúng tôi đi theo một lối mòn hẹp đi sâu vào trong rừng.","audioKind":"ex"},{"en":"Protecting natural forests helps preserve biodiversity and reduces the amount of carbon dioxide in the atmosphere.","vi":"Bảo vệ các khu rừng tự nhiên giúp duy trì đa dạng sinh học và làm giảm lượng khí thải carbon dioxide trong khí quyển.","audioKind":"ex2"}],"collocations":[{"en":"tropical forest","vi":"rừng nhiệt đới"},{"en":"forest conservation","vi":"bảo tồn rừng"},{"en":"forest fire","vi":"cháy rừng"},{"en":"dense forest","vi":"rừng rậm"}],"wordFamily":["forestry (n.)","forested (adj.)","deforestation (n.)","reforestation (n.)"],"synonyms":["woodland"],"antonyms":[],"tipVi":"forest thường chỉ vùng rừng lớn; wood có thể chỉ khu rừng nhỏ hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_donkey', 'en-a2-9', 'donkey', '/ˈdɑːŋki/', 'A2', 'con lừa', 'n.', NULL, 'Đồng nghĩa: ass', 'Khi chỉ động vật thì donkey là từ dùng phổ biến nhất; dùng từ này để gọi con người mang sắc thái miệt thị.', 'A grey donkey carried baskets along the narrow mountain path.', NULL, 'Một con lừa xám chở các giỏ hàng dọc theo con đường mòn nhỏ trên núi.', '{"wordId":"donkey","ukIpa":"/ˈdɒŋki/","usIpa":"/ˈdɑːŋki/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"an animal like a small horse with long ears","vi":"con lừa"}],"examples":[{"en":"A grey donkey carried baskets along the narrow mountain path.","vi":"Một con lừa xám chở các giỏ hàng dọc theo con đường mòn nhỏ trên núi.","audioKind":"ex"},{"en":"In some rural communities, donkeys remain important for transporting goods where roads are unsuitable for vehicles.","vi":"Ở một số cộng đồng nông thôn, lừa vẫn đóng vai trò quan trọng trong việc vận chuyển hàng hóa ở những nơi đường sá không phù hợp cho xe cộ.","audioKind":"ex2"}],"collocations":[{"en":"a pack donkey","vi":"lừa thồ hàng"},{"en":"ride a donkey","vi":"cưỡi lừa"},{"en":"a donkey brays","vi":"tiếng lừa kêu"}],"wordFamily":[],"synonyms":["ass"],"antonyms":[],"tipVi":"Khi chỉ động vật thì donkey là từ dùng phổ biến nhất; dùng từ này để gọi con người mang sắc thái miệt thị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wild', 'en-a2-9', 'wild', '/waɪld/', 'A2', 'hoang dã; mọc tự nhiên; cuồng nhiệt; quá khích; mất kiểm soát; vùng hoang dã; nơi hoang sơ', 'adj.', 'wildly (adv.), wildness (n.)', 'Đồng nghĩa: untamed · Trái nghĩa: tame, domesticated', 'Cụm từ chỉ "ở trong tự nhiên" là in the wild, không được bỏ mạo từ the.', 'We spotted wild deer drinking beside the forest stream.', NULL, 'Chúng tôi phát hiện những con hươu hoang dã đang uống nước bên dòng suối trong rừng.', '{"wordId":"wild","ukIpa":"/waɪld/","usIpa":"/waɪld/","cefr":"A2","topic":"nature","senses":[{"pos":"adj.","en":"living or growing naturally, without human care","vi":"hoang dã; mọc tự nhiên"},{"pos":"adj.","en":"showing strong excitement or uncontrolled behaviour","vi":"cuồng nhiệt; quá khích; mất kiểm soát"},{"pos":"n.","en":"natural places where animals and plants live freely","vi":"vùng hoang dã; nơi hoang sơ"}],"examples":[{"en":"We spotted wild deer drinking beside the forest stream.","vi":"Chúng tôi phát hiện những con hươu hoang dã đang uống nước bên dòng suối trong rừng.","audioKind":"ex"},{"en":"Protecting wild animals requires governments to preserve habitats and reduce illegal trade across national borders.","vi":"Việc bảo vệ động vật hoang dã đòi hỏi các chính phủ phải bảo tồn môi trường sống và giảm thiểu nạn buôn bán bất hợp pháp qua biên giới các quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"wild animals","vi":"động vật hoang dã"},{"en":"in the wild","vi":"trong môi trường hoang dã"},{"en":"go wild","vi":"trở nên cuồng nhiệt"},{"en":"wild flowers","vi":"hoa dại"}],"wordFamily":["wildly (adv.)","wildness (n.)"],"synonyms":["untamed"],"antonyms":["tame","domesticated"],"tipVi":"Cụm từ chỉ \"ở trong tự nhiên\" là in the wild, không được bỏ mạo từ the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_natural', 'en-a2-9', 'natural', '/ˈnætʃərəl/', 'A2', 'thuộc về tự nhiên; tự nhiên; bẩm sinh; thiên bẩm; bình thường; hợp lý', 'adj.', 'nature (n.), naturally (adv.), unnatural (adj.)', 'Trái nghĩa: artificial, unnatural', 'natural chỉ tính chất tự nhiên; nature là danh từ chỉ tự nhiên.', 'This soap is made entirely from natural ingredients.', NULL, 'Loại xà phòng này hoàn toàn được làm từ các thành phần tự nhiên.', '{"wordId":"natural","ukIpa":"/ˈnætʃərəl/","usIpa":"/ˈnætʃərəl/","cefr":"A2","topic":"nature","senses":[{"pos":"adj.","en":"existing in nature rather than made by people","vi":"thuộc về tự nhiên; tự nhiên"},{"pos":"adj.","en":"having an ability from birth rather than through training","vi":"bẩm sinh; thiên bẩm"},{"pos":"adj.","en":"normal and expected in a particular situation","vi":"bình thường; hợp lý; tự nhiên"}],"examples":[{"en":"This soap is made entirely from natural ingredients.","vi":"Loại xà phòng này hoàn toàn được làm từ các thành phần tự nhiên.","audioKind":"ex"},{"en":"Protecting natural habitats is essential for maintaining biodiversity and supporting communities that depend on local ecosystems.","vi":"Việc bảo vệ các môi trường sống tự nhiên là điều cốt lõi để duy trì đa dạng sinh học và hỗ trợ các cộng đồng phụ thuộc vào hệ sinh thái bản địa.","audioKind":"ex2"}],"collocations":[{"en":"natural resources","vi":"tài nguyên thiên nhiên"},{"en":"natural habitat","vi":"môi trường sống tự nhiên"},{"en":"natural talent","vi":"tài năng bẩm sinh"},{"en":"perfectly natural","vi":"hoàn toàn bình thường"}],"wordFamily":["nature (n.)","naturally (adv.)","unnatural (adj.)"],"synonyms":[],"antonyms":["artificial","unnatural"],"tipVi":"natural chỉ tính chất tự nhiên; nature là danh từ chỉ tự nhiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_snake', 'en-a2-9', 'snake', '/sneɪk/', 'A2', 'con rắn; uốn lượn, chuyển động theo đường quanh co', 'n.', 'snakelike (adj.)', NULL, 'Khi dùng làm động từ chỉ sự uốn lượn, thường đi kèm với through hoặc along.', 'A small snake slid quietly through the dry grass.', NULL, 'Một con rắn nhỏ lặng lẽ trườn qua bãi cỏ khô.', '{"wordId":"snake","ukIpa":"/sneɪk/","usIpa":"/sneɪk/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"a long reptile without legs","vi":"con rắn"},{"pos":"v.","en":"to move or extend along a winding path","vi":"uốn lượn, chuyển động theo đường quanh co"}],"examples":[{"en":"A small snake slid quietly through the dry grass.","vi":"Một con rắn nhỏ lặng lẽ trườn qua bãi cỏ khô.","audioKind":"ex"},{"en":"Although snakes often cause fear, they help maintain ecological balance by controlling populations of rodents and other animals.","vi":"Mặc dù rắn thường gây sợ hãi, chúng giúp duy trì cân bằng sinh thái bằng cách kiểm soát số lượng loài gặm nhấm và các động vật khác.","audioKind":"ex2"}],"collocations":[{"en":"a poisonous snake","vi":"rắn độc"},{"en":"a snake bite","vi":"vết rắn cắn"},{"en":"snake through","vi":"uốn lượn xuyên qua"}],"wordFamily":["snakelike (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng làm động từ chỉ sự uốn lượn, thường đi kèm với through hoặc along.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_goat', 'en-a2-9', 'goat', '/ɡoʊt/', 'A2', 'dê', 'n.', NULL, NULL, 'Goat là con dê, sheep là con cừu; thành ngữ "scapegoat" dùng để chỉ vật hy sinh hoặc kẻ chịu thay.', 'A curious goat poked its head through the fence.', NULL, 'Một chú dê tò mò thò đầu qua hàng rào.', '{"wordId":"goat","ukIpa":"/ɡəʊt/","usIpa":"/ɡoʊt/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"A hoofed animal, often with horns, kept for milk or meat.","vi":"dê"}],"examples":[{"en":"A curious goat poked its head through the fence.","vi":"Một chú dê tò mò thò đầu qua hàng rào.","audioKind":"ex"},{"en":"Raising goats can provide rural families with a reliable source of milk and additional income.","vi":"Nuôi dê có thể cung cấp cho các gia đình nông thôn nguồn sữa ổn định và thu nhập bổ sung.","audioKind":"ex2"}],"collocations":[{"en":"goat''s milk","vi":"sữa dê"},{"en":"goat''s cheese","vi":"phô mai dê"},{"en":"a herd of goats","vi":"một đàn dê"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Goat là con dê, sheep là con cừu; thành ngữ \"scapegoat\" dùng để chỉ vật hy sinh hoặc kẻ chịu thay.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_insect', 'en-a2-9', 'insect', '/ˈɪnsekt/', 'A2', 'côn trùng; sâu bọ', 'n.', 'insecticide (n.), insectivorous (adj.)', NULL, 'Danh từ đếm được; nhện có tám chân nên không thuộc loài côn trùng.', 'A tiny green insect landed on my sleeve.', NULL, 'Một con côn trùng màu xanh nhỏ xíu đậu lên tay áo của tôi.', '{"wordId":"insect","ukIpa":"/ˈɪnsekt/","usIpa":"/ˈɪnsekt/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"A small animal with six legs and three main body sections.","vi":"côn trùng; sâu bọ"}],"examples":[{"en":"A tiny green insect landed on my sleeve.","vi":"Một con côn trùng màu xanh nhỏ xíu đậu lên tay áo của tôi.","audioKind":"ex"},{"en":"Many insect species pollinate crops, making their protection essential for food production and healthy ecosystems.","vi":"Nhiều loài côn trùng thụ phấn cho cây trồng, khiến việc bảo vệ chúng trở nên thiết yếu đối với sản xuất lương thực và hệ sinh thái lành mạnh.","audioKind":"ex2"}],"collocations":[{"en":"insect bite","vi":"vết côn trùng cắn"},{"en":"insect repellent","vi":"thuốc xịt côn trùng"},{"en":"insect species","vi":"loài côn trùng"}],"wordFamily":["insecticide (n.)","insectivorous (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đếm được; nhện có tám chân nên không thuộc loài côn trùng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_puppy', 'en-a2-9', 'puppy', '/ˈpʌpi/', 'A2', 'chó con, con chó nhỏ', 'n.', 'puppyhood (n.)', 'Đồng nghĩa: pup', 'Dạng số nhiều là puppies; thường dùng chuyên biệt cho chó non.', 'The puppy fell asleep inside my empty shoe.', NULL, 'Chú chó con đã ngủ thiếp đi bên trong chiếc giày trống của tôi.', '{"wordId":"puppy","ukIpa":"/ˈpʌpi/","usIpa":"/ˈpʌpi/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"A young dog.","vi":"chó con, con chó nhỏ"}],"examples":[{"en":"The puppy fell asleep inside my empty shoe.","vi":"Chú chó con đã ngủ thiếp đi bên trong chiếc giày trống của tôi.","audioKind":"ex"},{"en":"Adopting a puppy requires a long-term commitment to training, exercise, and regular veterinary care.","vi":"Việc nhận nuôi một chú chó con đòi hỏi sự cam kết lâu dài đối với việc huấn luyện, cho vận dụng thể lực và chăm sóc thú y định kỳ.","audioKind":"ex2"}],"collocations":[{"en":"a litter of puppies","vi":"một bầy chó con"},{"en":"adopt a puppy","vi":"nhận nuôi chó con"},{"en":"puppy training","vi":"huấn luyện chó con"}],"wordFamily":["puppyhood (n.)"],"synonyms":["pup"],"antonyms":[],"tipVi":"Dạng số nhiều là puppies; thường dùng chuyên biệt cho chó non.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_field', 'en-a2-9', 'field', '/fiːld/', 'A2', 'đồng ruộng; cánh đồng; bãi chăn thả; lĩnh vực; ngành; sân vận động; sân chơi thể thao', 'n.', NULL, NULL, 'Khi nói về lĩnh vực nghiên cứu hoặc công việc, ta thường dùng cụm từ in the field of.', 'We watched sheep grazing in the field behind our cottage.', NULL, 'Chúng tôi ngắm nhìn bầy cừu đang gặm cỏ ở cánh đồng phía sau ngôi nhà tranh của chúng tôi.', '{"wordId":"field","ukIpa":"/fiːld/","usIpa":"/fiːld/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"an area of land used for crops or farm animals","vi":"đồng ruộng; cánh đồng; bãi chăn thả"},{"pos":"n.","en":"a particular area of study or work","vi":"lĩnh vực; ngành"},{"pos":"n.","en":"an area of ground used for playing a sport","vi":"sân vận động; sân chơi thể thao"}],"examples":[{"en":"We watched sheep grazing in the field behind our cottage.","vi":"Chúng tôi ngắm nhìn bầy cừu đang gặm cỏ ở cánh đồng phía sau ngôi nhà tranh của chúng tôi.","audioKind":"ex"},{"en":"Research in the field of renewable energy could create employment opportunities and reduce dependence on fossil fuels.","vi":"Nghiên cứu trong lĩnh vực năng lượng tái tạo có thể tạo ra nhiều cơ hội việc làm và giảm bớt sự phụ thuộc vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"a wheat field","vi":"cánh đồng lúa mì"},{"en":"in the field of","vi":"trong lĩnh vực"},{"en":"a football field","vi":"sân bóng đá"},{"en":"field research","vi":"nghiên cứu thực tế"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi nói về lĩnh vực nghiên cứu hoặc công việc, ta thường dùng cụm từ in the field of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coast', 'en-a2-9', 'coast', '/koʊst/', 'A2', 'bờ biển; vùng duyên hải; trôi theo quán tính; lướt đi; vượt qua hoặc tiến bộ mà không cần tốn nhiều sức', 'n.', 'coastal (adj.), coastline (n.)', 'Đồng nghĩa: seashore', 'on the coast chỉ vị trí trên bờ biển; off the coast chỉ vùng biển ngoài khơi.', 'We walked along the coast and collected smooth stones.', NULL, 'Chúng tôi đi dạo dọc theo bờ biển và nhặt những viên đá nhẵn.', '{"wordId":"coast","ukIpa":"/kəʊst/","usIpa":"/koʊst/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"the land along the edge of the sea","vi":"bờ biển; vùng duyên hải"},{"pos":"v.","en":"to move without using power or much effort","vi":"trôi theo quán tính; lướt đi"},{"pos":"v.","en":"to succeed or progress without trying very hard","vi":"vượt qua hoặc tiến bộ mà không cần tốn nhiều sức"}],"examples":[{"en":"We walked along the coast and collected smooth stones.","vi":"Chúng tôi đi dạo dọc theo bờ biển và nhặt những viên đá nhẵn.","audioKind":"ex"},{"en":"Communities along the coast face increasing risks from rising sea levels and severe storms.","vi":"Các cộng đồng ven biển đang phải đối mặt với những rủi ro ngày càng tăng từ mực nước biển dâng và các cơn bão dữ dội.","audioKind":"ex2"}],"collocations":[{"en":"along the coast","vi":"dọc theo bờ biển"},{"en":"off the coast","vi":"ngoài khơi bờ biển"},{"en":"coast downhill","vi":"lao dốc theo quán tính"},{"en":"coast through","vi":"vượt qua một cách nhẹ nhàng"}],"wordFamily":["coastal (adj.)","coastline (n.)"],"synonyms":["seashore"],"antonyms":[],"tipVi":"on the coast chỉ vị trí trên bờ biển; off the coast chỉ vùng biển ngoài khơi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rock', 'en-a2-9', 'rock', '/rɑːk/', 'A2', 'đá; tảng đá; nham thạch; nhạc rock; lắc lư; đung đưa; ru nhẹ', 'n.', 'rocky (adj.), rocker (n.)', NULL, 'rock khi chỉ chất liệu đá là danh từ không đếm được; khi chỉ một tảng/hòn đá cụ thể là danh từ đếm được.', 'We sat on a flat rock beside the river.', NULL, 'Chúng tôi ngồi trên một tảng đá phẳng bên bờ sông.', '{"wordId":"rock","ukIpa":"/rɒk/","usIpa":"/rɑːk/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"The hard natural material forming much of Earth''s surface.","vi":"đá; tảng đá; nham thạch"},{"pos":"n.","en":"Popular music with a strong beat, often featuring electric guitars.","vi":"nhạc rock"},{"pos":"v.","en":"Move gently backwards and forwards or from side to side.","vi":"lắc lư; đung đưa; ru nhẹ"}],"examples":[{"en":"We sat on a flat rock beside the river.","vi":"Chúng tôi ngồi trên một tảng đá phẳng bên bờ sông.","audioKind":"ex"},{"en":"Studying ancient rock layers helps scientists understand how the Earth''s climate has changed over time.","vi":"Việc nghiên cứu các lớp đá cổ đại giúp các nhà khoa học hiểu được khí hậu Trái Đất đã thay đổi như thế nào theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"solid rock","vi":"đá cứng; đá rắn"},{"en":"rock music","vi":"nhạc rock"},{"en":"rock formation","vi":"tầng đá; cấu trúc đá"},{"en":"rock a baby","vi":"ru em bé ngủ; đung đưa em bé"}],"wordFamily":["rocky (adj.)","rocker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"rock khi chỉ chất liệu đá là danh từ không đếm được; khi chỉ một tảng/hòn đá cụ thể là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_zebra', 'en-a2-9', 'zebra', '/ˈziːbrə/', 'A2', 'ngựa vằn', 'n.', NULL, NULL, 'zebra crossing là vạch sang đường cho người đi bộ theo tiếng Anh-Anh.', 'A zebra stood quietly beside the watering hole.', NULL, 'Một con ngựa vằn đứng lặng lẽ bên vũng nước.', '{"wordId":"zebra","ukIpa":"/ˈzebrə/","usIpa":"/ˈziːbrə/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"an African wild animal with black and white stripes","vi":"ngựa vằn"}],"examples":[{"en":"A zebra stood quietly beside the watering hole.","vi":"Một con ngựa vằn đứng lặng lẽ bên vũng nước.","audioKind":"ex"},{"en":"Protecting grasslands helps zebra populations survive while preserving habitats for many other wild animals.","vi":"Bảo vệ các đồng cỏ giúp duy trì quần thể ngựa vằn đồng thời bảo tồn môi trường sống cho nhiều loài động vật hoang dã khác.","audioKind":"ex2"}],"collocations":[{"en":"a herd of zebras","vi":"một đàn ngựa vằn"},{"en":"zebra stripes","vi":"sọc ngựa vằn"},{"en":"zebra crossing","vi":"vạch sang đường cho người đi bộ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"zebra crossing là vạch sang đường cho người đi bộ theo tiếng Anh-Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_land', 'en-a2-9', 'land', '/lænd/', 'A2', 'đất liền; đất đai; vùng đất; hạ cánh; đáp xuống; làm cho hạ cánh; đạt được (thứ gì đó mong muốn, đặc biệt là công việc)', 'n.', 'landing (n.), landless (adj.), landowner (n.)', NULL, 'Nghĩa đất đai thường không đếm được; land a job có nghĩa là thành công nhận được việc làm.', 'After hours at sea, we finally spotted dry land.', NULL, 'Sau nhiều giờ lênh đênh trên biển, cuối cùng chúng tôi đã nhìn thấy đất liền khô ráo.', '{"wordId":"land","ukIpa":"/lænd/","usIpa":"/lænd/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"Earth''s solid surface, or an area used for a particular purpose.","vi":"đất liền; đất đai; vùng đất"},{"pos":"v.","en":"To reach the ground, or bring an aircraft to the ground.","vi":"hạ cánh; đáp xuống; làm cho hạ cánh"},{"pos":"v.","en":"To succeed in getting something desirable, especially a job.","vi":"đạt được (thứ gì đó mong muốn, đặc biệt là công việc)"}],"examples":[{"en":"After hours at sea, we finally spotted dry land.","vi":"Sau nhiều giờ lênh đênh trên biển, cuối cùng chúng tôi đã nhìn thấy đất liền khô ráo.","audioKind":"ex"},{"en":"Protecting agricultural land from urban expansion is essential for maintaining food production near growing cities.","vi":"Bảo vệ đất nông nghiệp khỏi sự bành trướng của đô thị là điều thiết yếu để duy trì sản xuất lương thực gần các thành phố đang phát triển.","audioKind":"ex2"}],"collocations":[{"en":"agricultural land","vi":"đất nông nghiệp"},{"en":"by land","vi":"đi đường bộ"},{"en":"land safely","vi":"hạ cánh an toàn"},{"en":"land a job","vi":"trúng tuyển công việc"}],"wordFamily":["landing (n.)","landless (adj.)","landowner (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa đất đai thường không đếm được; land a job có nghĩa là thành công nhận được việc làm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sand', 'en-a2-9', 'sand', '/sænd/', 'A2', 'cát; chà nhám; mài nhẵn (bằng giấy nhám)', 'n.', 'sandy (adj.), sandpaper (n.)', NULL, 'Khi chỉ cát, từ này là danh từ không đếm được; một hạt cát dùng cụm a grain of sand.', 'The children built a castle from wet sand.', NULL, 'Bọn trẻ xây một lâu đài từ cát ẩm.', '{"wordId":"sand","ukIpa":"/sænd/","usIpa":"/sænd/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"Tiny loose grains of rock found on beaches and in deserts.","vi":"cát"},{"pos":"v.","en":"To make a surface smooth by rubbing it with sandpaper.","vi":"chà nhám; mài nhẵn (bằng giấy nhám)"}],"examples":[{"en":"The children built a castle from wet sand.","vi":"Bọn trẻ xây một lâu đài từ cát ẩm.","audioKind":"ex"},{"en":"Removing sand from riverbeds for construction can damage habitats and increase the risk of erosion.","vi":"Việc khai thác cát từ lòng sông phục vụ xây dựng có thể phá hủy các môi trường sống và làm tăng nguy cơ xói mòn.","audioKind":"ex2"}],"collocations":[{"en":"fine sand","vi":"cát mịn"},{"en":"a grain of sand","vi":"một hạt cát"},{"en":"sand dunes","vi":"cồn cát"},{"en":"sand down","vi":"chà nhám phẳng"}],"wordFamily":["sandy (adj.)","sandpaper (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ cát, từ này là danh từ không đếm được; một hạt cát dùng cụm a grain of sand.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_earth', 'en-a2-9', 'earth', '/ɝːθ/', 'A2', 'trái đất; hoàn cầu; đất; đất trồng', 'n.', 'earthy (adj.), earthly (adj.), earthen (adj.)', 'Đồng nghĩa: soil, ground', 'Chi khi chỉ hành tinh thường viết hoa Earth; cụm on earth không thêm the.', 'The children dug into the damp earth with small spades.', NULL, 'Lũ trẻ dùng những chiếc xẻng nhỏ để đào vào lớp đất ẩm.', '{"wordId":"earth","ukIpa":"/ɜːθ/","usIpa":"/ɝːθ/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"the planet where humans and other known living things exist","vi":"trái đất; hoàn cầu"},{"pos":"n.","en":"the loose material on the ground in which plants grow","vi":"đất; đất trồng"}],"examples":[{"en":"The children dug into the damp earth with small spades.","vi":"Lũ trẻ dùng những chiếc xẻng nhỏ để đào vào lớp đất ẩm.","audioKind":"ex"},{"en":"Life on earth depends on healthy ecosystems that provide clean water, food, and breathable air.","vi":"Sự sống trên trái đất phụ thuộc vào các hệ sinh thái khỏe mạnh cung cấp nguồn nước sạch, thức ăn và bầu không khí có thể thở được.","audioKind":"ex2"}],"collocations":[{"en":"on earth","vi":"trên trái đất"},{"en":"planet Earth","vi":"hành tinh Trái Đất"},{"en":"damp earth","vi":"đất ẩm"}],"wordFamily":["earthy (adj.)","earthly (adj.)","earthen (adj.)"],"synonyms":["soil","ground"],"antonyms":[],"tipVi":"Chi khi chỉ hành tinh thường viết hoa Earth; cụm on earth không thêm the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_windy', 'en-a2-9', 'windy', '/ˈwɪndi/', 'A2', 'lắm gió; lộng gió', 'adj.', 'wind (n.), windless (adj.)', 'Đồng nghĩa: blustery · Trái nghĩa: calm', 'Nghĩa về thời tiết đọc là /ˈwɪndi/; để mô tả con đường ngoằn ngoèo thường dùng winding.', 'It was too windy to eat lunch outside today.', NULL, 'Hôm nay trời nhiều gió quá nên chúng tôi không ăn trưa ngoài trời được.', '{"wordId":"windy","ukIpa":"/ˈwɪndi/","usIpa":"/ˈwɪndi/","cefr":"A2","topic":"nature","senses":[{"pos":"adj.","en":"Having a lot of wind.","vi":"lắm gió; lộng gió"}],"examples":[{"en":"It was too windy to eat lunch outside today.","vi":"Hôm nay trời nhiều gió quá nên chúng tôi không ăn trưa ngoài trời được.","audioKind":"ex"},{"en":"Windy coastal regions can generate renewable electricity, although turbines must be positioned carefully to protect wildlife.","vi":"Các vùng ven biển lộng gió có thể sản xuất điện tái tạo, mặc dù các tuabin phải được đặt cẩn thận để bảo vệ động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"windy weather","vi":"thời tiết nhiều gió"},{"en":"a windy day","vi":"một ngày gió lớn"},{"en":"windy conditions","vi":"điều kiện lộng gió"}],"wordFamily":["wind (n.)","windless (adj.)"],"synonyms":["blustery"],"antonyms":["calm"],"tipVi":"Nghĩa về thời tiết đọc là /ˈwɪndi/; để mô tả con đường ngoằn ngoèo thường dùng winding.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shark', 'en-a2-9', 'shark', '/ʃɑːrk/', 'A2', 'con cá mập; kẻ lừa đảo; kẻ bòn rút tiền bạc', 'n.', NULL, NULL, 'loan shark dùng để chỉ kẻ cho vay nặng lãi, không phải một loài cá mập.', 'We watched a shark swim slowly behind the aquarium glass.', NULL, 'Chúng tôi đứng xem một con cá mập bơi chậm rãi đằng sau lớp kính của thủy cung.', '{"wordId":"shark","ukIpa":"/ʃɑːk/","usIpa":"/ʃɑːrk/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"A fish with a cartilage skeleton and usually sharp teeth.","vi":"con cá mập"},{"pos":"n.","en":"Someone who cheats others, especially to get their money.","vi":"kẻ lừa đảo; kẻ bòn rút tiền bạc"}],"examples":[{"en":"We watched a shark swim slowly behind the aquarium glass.","vi":"Chúng tôi đứng xem một con cá mập bơi chậm rãi đằng sau lớp kính của thủy cung.","audioKind":"ex"},{"en":"Protecting shark populations helps maintain balanced marine ecosystems because many species regulate the numbers of other animals.","vi":"Bảo vệ các quần thể cá mập giúp duy trì sự cân bằng của hệ sinh thái biển vì nhiều loài kiểm soát số lượng của các loài động vật khác.","audioKind":"ex2"}],"collocations":[{"en":"shark fin","vi":"vây cá mập"},{"en":"whale shark","vi":"cá mập voi"},{"en":"shark conservation","vi":"bảo tồn cá mập"},{"en":"loan shark","vi":"kẻ cho vay nặng lãi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"loan shark dùng để chỉ kẻ cho vay nặng lãi, không phải một loài cá mập.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_snowy', 'en-a2-9', 'snowy', '/ˈsnoʊi/', 'A2', 'có tuyết rơi; nhiều tuyết; được bao phủ bởi tuyết', 'adj.', 'snow (n.), snow (v.), snowfall (n.)', NULL, 'Từ ''snowy'' có thể dùng để diễn tả thời tiết hoặc chỉ cảnh vật ngập tràn tuyết.', 'We stayed indoors and baked bread on that snowy afternoon.', NULL, 'Chúng tôi ở trong nhà và nướng bánh vào buổi chiều có tuyết rơi hôm đó.', '{"wordId":"snowy","ukIpa":"/ˈsnəʊi/","usIpa":"/ˈsnoʊi/","cefr":"A2","topic":"nature","senses":[{"pos":"adj.","en":"Having falling snow or frequent snowfall.","vi":"có tuyết rơi; nhiều tuyết"},{"pos":"adj.","en":"Covered with snow.","vi":"được bao phủ bởi tuyết"}],"examples":[{"en":"We stayed indoors and baked bread on that snowy afternoon.","vi":"Chúng tôi ở trong nhà và nướng bánh vào buổi chiều có tuyết rơi hôm đó.","audioKind":"ex"},{"en":"In snowy regions, reliable public transport requires regular road maintenance and vehicles designed for winter conditions.","vi":"Ở những vùng có tuyết, hệ thống giao thông công cộng đáng tin cậy đòi hỏi công tác bảo trì đường sá thường xuyên và các phương tiện được thiết kế riêng cho điều kiện thời tiết mùa đông.","audioKind":"ex2"}],"collocations":[{"en":"snowy weather","vi":"thời tiết có tuyết"},{"en":"snowy mountains","vi":"những ngọn núi phủ tuyết trắng"},{"en":"snowy winter","vi":"mùa đông nhiều tuyết"}],"wordFamily":["snow (n.)","snow (v.)","snowfall (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ ''snowy'' có thể dùng để diễn tả thời tiết hoặc chỉ cảnh vật ngập tràn tuyết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dead', 'en-a2-9', 'dead', '/ded/', 'A2', 'chết; khô héo (cây cối); hết pin; ngưng hoạt động; hoàn toàn; đúng chính xác', 'adj.', 'die (v.), death (n.), deadly (adj.)', 'Đồng nghĩa: lifeless · Trái nghĩa: alive, living', 'Dead là tính từ chỉ trạng thái, die là động từ, death là danh từ.', 'We removed the dead flowers from the balcony pots.', NULL, 'Chúng tôi đã dọn sạch những bông hoa đã héo úa khỏi các chậu cây trên ban công.', '{"wordId":"dead","ukIpa":"/ded/","usIpa":"/ded/","cefr":"A2","topic":"nature","senses":[{"pos":"adj.","en":"No longer alive","vi":"chết; khô héo (cây cối)"},{"pos":"adj.","en":"No longer working, often because power has run out","vi":"hết pin; ngưng hoạt động"},{"pos":"adv.","en":"Completely or exactly, used for emphasis","vi":"hoàn toàn; đúng chính xác"}],"examples":[{"en":"We removed the dead flowers from the balcony pots.","vi":"Chúng tôi đã dọn sạch những bông hoa đã héo úa khỏi các chậu cây trên ban công.","audioKind":"ex"},{"en":"Leaving dead trees in forests can support biodiversity by providing habitats for insects and small animals.","vi":"Việc để lại những cây chết trong rừng có thể hỗ trợ đa dạng sinh học bằng cách cung cấp môi trường sống cho côn trùng và động vật nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"dead leaves","vi":"lá khô"},{"en":"a dead battery","vi":"pin hết điện"},{"en":"dead silence","vi":"sự im lặng chết chóc"},{"en":"dead centre","vi":"chính giữa"}],"wordFamily":["die (v.)","death (n.)","deadly (adj.)"],"synonyms":["lifeless"],"antonyms":["alive","living"],"tipVi":"Dead là tính từ chỉ trạng thái, die là động từ, death là danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_duck', 'en-a2-9', 'duck', '/dʌk/', 'A2', 'con vịt; thịt vịt; cúi đầu (để né tránh); né tránh (câu hỏi, trách nhiệm)', 'n.', 'duckling (n.)', NULL, 'Chỉ vịt là danh từ đếm được, chỉ thịt vịt là danh từ không đếm được.', 'A duck paddled past us with several tiny ducklings.', NULL, 'Một con vịt đang bơi lội tung tăng qua chỗ chúng tôi cùng với vài chú vịt con nhỏ xíu.', '{"wordId":"duck","ukIpa":"/dʌk/","usIpa":"/dʌk/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"A waterbird with a broad bill, or its meat","vi":"con vịt; thịt vịt"},{"pos":"v.","en":"Lower your head or body quickly to avoid something","vi":"cúi đầu (để né tránh)"},{"pos":"v.","en":"Avoid a difficult question, responsibility, or situation","vi":"né tránh (câu hỏi, trách nhiệm)"}],"examples":[{"en":"A duck paddled past us with several tiny ducklings.","vi":"Một con vịt đang bơi lội tung tăng qua chỗ chúng tôi cùng với vài chú vịt con nhỏ xíu.","audioKind":"ex"},{"en":"Urban parks with healthy ponds provide valuable habitats for ducks and other wildlife throughout the year.","vi":"Các công viên đô thị có ao hồ trong lành cung cấp môi trường sống quý giá cho các loài vịt và động vật hoang dã khác quanh năm.","audioKind":"ex2"}],"collocations":[{"en":"wild duck","vi":"vịt hoang"},{"en":"roast duck","vi":"vịt quay"},{"en":"duck your head","vi":"cúi đầu nhanh"},{"en":"duck a question","vi":"né tránh câu hỏi"}],"wordFamily":["duckling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ vịt là danh từ đếm được, chỉ thịt vịt là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spider', 'en-a2-9', 'spider', '/ˈspaɪdər/', 'A2', 'con nhện', 'n.', NULL, NULL, 'Nhện có tám chân và không thuộc nhóm côn trùng sáu chân.', 'A tiny spider built a web beside our window.', NULL, 'Một con nhện nhỏ đã giăng mạng ngay bên cửa sổ nhà chúng tôi.', '{"wordId":"spider","ukIpa":"/ˈspaɪdə/","usIpa":"/ˈspaɪdər/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"a small creature with eight legs, often making webs","vi":"con nhện"}],"examples":[{"en":"A tiny spider built a web beside our window.","vi":"Một con nhện nhỏ đã giăng mạng ngay bên cửa sổ nhà chúng tôi.","audioKind":"ex"},{"en":"Although many people fear spiders, these creatures help control insect populations in gardens and agricultural environments.","vi":"Mặc dù nhiều người sợ nhện, những sinh vật này lại giúp kiểm soát quần thể côn trùng trong các khu vườn và môi trường nông nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"a spider web","vi":"mạng nhện"},{"en":"a spider bite","vi":"vết nhện cắn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Nhện có tám chân và không thuộc nhóm côn trùng sáu chân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ant', 'en-a2-9', 'ant', '/ænt/', 'A2', 'con kiến', 'n.', NULL, NULL, 'ant là danh từ đếm được; một con kiến dùng an ant.', 'An ant carried a crumb across the kitchen floor.', NULL, 'Một con kiến đang bò cõng mẩu vụn bánh mì qua sàn bếp.', '{"wordId":"ant","ukIpa":"/ænt/","usIpa":"/ænt/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"A small insect that lives in organised groups.","vi":"con kiến"}],"examples":[{"en":"An ant carried a crumb across the kitchen floor.","vi":"Một con kiến đang bò cõng mẩu vụn bánh mì qua sàn bếp.","audioKind":"ex"},{"en":"Ants contribute to healthy ecosystems by moving seeds and improving the structure of soil.","vi":"Loài kiến góp phần duy trì hệ sinh thái lành mạnh bằng cách phát tán hạt giống và cải thiện cấu trúc đất.","audioKind":"ex2"}],"collocations":[{"en":"an ant colony","vi":"đàn kiến"},{"en":"an ant nest","vi":"tổ kiến"},{"en":"worker ants","vi":"kiến thợ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"ant là danh từ đếm được; một con kiến dùng an ant.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_storm', 'en-a2-9', 'storm', '/stɔːrm/', 'A2', 'bão; cơn bão; bước đi giận dữ; xông vào; cơn bão (sự phẫn nộ/chỉ trích dữ dội)', 'n.', 'stormy (adj.)', 'Đồng nghĩa: tempest', 'storm out diễn tả sự tức giận bỏ đi, không phải phong ba bão táp di chuyển ra ngoài.', 'We stayed indoors while the storm shook the windows.', NULL, 'Chúng tôi ở trong nhà khi cơn bão làm rung chuyển cả khung cửa sổ.', '{"wordId":"storm","ukIpa":"/stɔːm/","usIpa":"/stɔːrm/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"severe weather with strong winds and rain, snow, or thunder","vi":"bão; cơn bão"},{"pos":"v.","en":"to move somewhere angrily and forcefully","vi":"bước đi giận dữ; xông vào"},{"pos":"n.","en":"a sudden wave of strong public anger or criticism","vi":"cơn bão (sự phẫn nộ/chỉ trích dữ dội)"}],"examples":[{"en":"We stayed indoors while the storm shook the windows.","vi":"Chúng tôi ở trong nhà khi cơn bão làm rung chuyển cả khung cửa sổ.","audioKind":"ex"},{"en":"Coastal communities need stronger flood defences to protect homes and essential services during severe storms.","vi":"Các cộng đồng ven biển cần hệ thống phòng chống lụt bão kiên cố hơn để bảo vệ nhà cửa và các dịch vụ thiết yếu trong những trận bão lớn.","audioKind":"ex2"}],"collocations":[{"en":"a severe storm","vi":"cơn bão lớn"},{"en":"a storm of protest","vi":"làn sóng phản đối dữ dội"},{"en":"storm out of the room","vi":"đùng đùng bỏ ra khỏi phòng"}],"wordFamily":["stormy (adj.)"],"synonyms":["tempest"],"antonyms":[],"tipVi":"storm out diễn tả sự tức giận bỏ đi, không phải phong ba bão táp di chuyển ra ngoài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_season', 'en-a2-9', 'season', '/ˈsiːzən/', 'A2', 'mùa; mùa vụ; mùa cao điểm; đợt; nêm gia vị; tẩm ướp', 'n.', 'seasonal (adj.), seasonally (adv.), seasoning (n.)', NULL, 'Khi là động từ, season chỉ việc nêm nếm gia vị, thường dùng cấu trúc season food with…', 'Autumn is my favourite season for walking in the woods.', NULL, 'Mùa thu là mùa tôi yêu thích nhất để đi dạo trong rừng.', '{"wordId":"season","ukIpa":"/ˈsiːzən/","usIpa":"/ˈsiːzən/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"One of the main yearly periods with particular weather conditions.","vi":"mùa"},{"pos":"n.","en":"A period when a particular activity or event usually happens.","vi":"mùa vụ; mùa cao điểm; đợt"},{"pos":"v.","en":"Add salt, herbs, or spices to improve food''s flavour.","vi":"nêm gia vị; tẩm ướp"}],"examples":[{"en":"Autumn is my favourite season for walking in the woods.","vi":"Mùa thu là mùa tôi yêu thích nhất để đi dạo trong rừng.","audioKind":"ex"},{"en":"A longer tourist season can create more stable employment, although it may increase pressure on local resources.","vi":"Mùa du lịch kéo dài hơn có thể tạo ra việc làm ổn định hơn, mặc dù nó có thể làm tăng áp lực lên các nguồn lực địa phương.","audioKind":"ex2"}],"collocations":[{"en":"rainy season","vi":"mùa mưa"},{"en":"peak season","vi":"mùa cao điểm"},{"en":"football season","vi":"mùa giải bóng đá"},{"en":"season with salt","vi":"nêm gia vị bằng muối"}],"wordFamily":["seasonal (adj.)","seasonally (adv.)","seasoning (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi là động từ, season chỉ việc nêm nếm gia vị, thường dùng cấu trúc season food with…","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_9_1', 'en-a2-9', 'Cách dùng “cloud” (n.) — đám mây', 'dark clouds  ·  a cloud of dust  ·  cloud someone''s judgment', 'cloud dùng làm động từ có thể chỉ việc làm cho phán đoán không rõ ràng, chẳng hạn như cloud your judgment.', 'Họ từ (Word Family): cloudy (adj.), cloudless (adj.)', '[{"hanzi":"A dark cloud drifted slowly across the afternoon sky.","pinyin":"","meaning":"Một đám mây đen trôi lững lờ ngang qua bầu trời buổi chiều."},{"hanzi":"Strong emotions can cloud public judgment when communities debate the benefits and risks of new technologies.","pinyin":"","meaning":"Cảm xúc mạnh mẽ có thể làm lu mờ phán đoán của công chúng khi cộng đồng tranh luận về lợi ích và rủi ro của các công nghệ mới."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_9_2', 'en-a2-9', 'Cách dùng “donkey” (n.) — con lừa', 'a pack donkey  ·  ride a donkey  ·  a donkey brays', 'Khi chỉ động vật thì donkey là từ dùng phổ biến nhất; dùng từ này để gọi con người mang sắc thái miệt thị.', 'Đồng nghĩa: ass', '[{"hanzi":"A grey donkey carried baskets along the narrow mountain path.","pinyin":"","meaning":"Một con lừa xám chở các giỏ hàng dọc theo con đường mòn nhỏ trên núi."},{"hanzi":"In some rural communities, donkeys remain important for transporting goods where roads are unsuitable for vehicles.","pinyin":"","meaning":"Ở một số cộng đồng nông thôn, lừa vẫn đóng vai trò quan trọng trong việc vận chuyển hàng hóa ở những nơi đường sá không phù hợp cho xe cộ."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_9_3', 'en-a2-9', 'Cách dùng “rock” (n.) — đá; tảng đá; nham thạch', 'solid rock  ·  rock music  ·  rock formation', 'rock khi chỉ chất liệu đá là danh từ không đếm được; khi chỉ một tảng/hòn đá cụ thể là danh từ đếm được.', 'Họ từ (Word Family): rocky (adj.), rocker (n.)', '[{"hanzi":"We sat on a flat rock beside the river.","pinyin":"","meaning":"Chúng tôi ngồi trên một tảng đá phẳng bên bờ sông."},{"hanzi":"Studying ancient rock layers helps scientists understand how the Earth''s climate has changed over time.","pinyin":"","meaning":"Việc nghiên cứu các lớp đá cổ đại giúp các nhà khoa học hiểu được khí hậu Trái Đất đã thay đổi như thế nào theo thời gian."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_9_4', 'en-a2-9', 'Cách dùng “goat” (n.) — dê', 'goat''s milk  ·  goat''s cheese  ·  a herd of goats', 'Goat là con dê, sheep là con cừu; thành ngữ "scapegoat" dùng để chỉ vật hy sinh hoặc kẻ chịu thay.', NULL, '[{"hanzi":"A curious goat poked its head through the fence.","pinyin":"","meaning":"Một chú dê tò mò thò đầu qua hàng rào."},{"hanzi":"Raising goats can provide rural families with a reliable source of milk and additional income.","pinyin":"","meaning":"Nuôi dê có thể cung cấp cho các gia đình nông thôn nguồn sữa ổn định và thu nhập bổ sung."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
