INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_9_1_5', 'ten_a2_9_1', 'wild', 'We spotted wild deer drinking beside the forest stream.', 'We spotted wild deer drinking beside the forest stream.', '/waɪld/', 'Chúng tôi phát hiện những con hươu hoang dã đang uống nước bên dòng suối trong rừng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_9_1_6', 'ten_a2_9_1', 'natural', 'This soap is made entirely from natural ingredients.', 'This soap is made entirely from natural ingredients.', '/ˈnætʃərəl/', 'Loại xà phòng này hoàn toàn được làm từ các thành phần tự nhiên.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_9_1_7', 'ten_a2_9_1', 'snake', 'A small snake slid quietly through the dry grass.', 'A small snake slid quietly through the dry grass.', '/sneɪk/', 'Một con rắn nhỏ lặng lẽ trườn qua bãi cỏ khô.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_9_1_8', 'ten_a2_9_1', 'goat', 'A curious goat poked its head through the fence.', 'A curious goat poked its head through the fence.', '/ɡoʊt/', 'Một chú dê tò mò thò đầu qua hàng rào.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_9_1_1', 'en-a2-9', 'ten_a2_9_1', 'listening', 'listening', 'A dark cloud drifted slowly across the afternoon sky.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một con lừa xám chở các giỏ hàng dọc theo con đường mòn nhỏ trên núi.","Mùa thu là mùa tôi yêu thích nhất để đi dạo trong rừng.","Một đám mây đen trôi lững lờ ngang qua bầu trời buổi chiều.","Cây non vẫn còn sống sau kỳ nghỉ của chúng tôi."]'::jsonb, 2, 'A dark cloud drifted slowly across the afternoon sky. → Một đám mây đen trôi lững lờ ngang qua bầu trời buổi chiều.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_9_1_2', 'en-a2-9', 'ten_a2_9_1', 'listening', 'listening', 'The tiny plant is still alive after our holiday.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Lũ trẻ dùng những chiếc xẻng nhỏ để đào vào lớp đất ẩm.","Hôm nay trời nhiều gió quá nên chúng tôi không ăn trưa ngoài trời được.","Cây non vẫn còn sống sau kỳ nghỉ của chúng tôi.","Chú chó con đã ngủ thiếp đi bên trong chiếc giày trống của tôi."]'::jsonb, 2, 'The tiny plant is still alive after our holiday. → Cây non vẫn còn sống sau kỳ nghỉ của chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_9_1_3', 'en-a2-9', 'ten_a2_9_1', 'listening', 'listening', 'We followed a narrow path deep into the forest.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đi theo một lối mòn hẹp đi sâu vào trong rừng.","Chúng tôi ngắm nhìn bầy cừu đang gặm cỏ ở cánh đồng phía sau ngôi nhà tranh của chúng tôi.","Một con côn trùng màu xanh nhỏ xíu đậu lên tay áo của tôi.","Một con lừa xám chở các giỏ hàng dọc theo con đường mòn nhỏ trên núi."]'::jsonb, 0, 'We followed a narrow path deep into the forest. → Chúng tôi đi theo một lối mòn hẹp đi sâu vào trong rừng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_9_2', 'en-a2-9', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_9_2_1', 'ten_a2_9_2', 'cloud', 'Strong emotions can cloud public judgment when communities debate the benefits and risks of new technologies.', 'Strong emotions can cloud public judgment when communities debate the benefits and risks of new technologies.', '/klaʊd/', 'Cảm xúc mạnh mẽ có thể làm lu mờ phán đoán của công chúng khi cộng đồng tranh luận về lợi ích và rủi ro của các công nghệ mới.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_9_2_2', 'ten_a2_9_2', 'alive', 'Protecting natural habitats helps keep endangered species alive and preserves the ecological balance of entire regions.', 'Protecting natural habitats helps keep endangered species alive and preserves the ecological balance of entire regions.', '/əˈlaɪv/', 'Bảo vệ môi trường sống tự nhiên giúp duy trì sự sống cho các loài nguy cấp và giữ vững cân bằng sinh thái của toàn bộ khu vực.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_9_2_3', 'ten_a2_9_2', 'forest', 'Protecting natural forests helps preserve biodiversity and reduces the amount of carbon dioxide in the atmosphere.', 'Protecting natural forests helps preserve biodiversity and reduces the amount of carbon dioxide in the atmosphere.', '/ˈfɔːrɪst/', 'Bảo vệ các khu rừng tự nhiên giúp duy trì đa dạng sinh học và làm giảm lượng khí thải carbon dioxide trong khí quyển.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_9_2_4', 'ten_a2_9_2', 'donkey', 'In some rural communities, donkeys remain important for transporting goods where roads are unsuitable for vehicles.', 'In some rural communities, donkeys remain important for transporting goods where roads are unsuitable for vehicles.', '/ˈdɑːŋki/', 'Ở một số cộng đồng nông thôn, lừa vẫn đóng vai trò quan trọng trong việc vận chuyển hàng hóa ở những nơi đường sá không phù hợp cho xe cộ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_9_2_5', 'ten_a2_9_2', 'wild', 'Protecting wild animals requires governments to preserve habitats and reduce illegal trade across national borders.', 'Protecting wild animals requires governments to preserve habitats and reduce illegal trade across national borders.', '/waɪld/', 'Việc bảo vệ động vật hoang dã đòi hỏi các chính phủ phải bảo tồn môi trường sống và giảm thiểu nạn buôn bán bất hợp pháp qua biên giới các quốc gia.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_9_2_6', 'ten_a2_9_2', 'natural', 'Protecting natural habitats is essential for maintaining biodiversity and supporting communities that depend on local ecosystems.', 'Protecting natural habitats is essential for maintaining biodiversity and supporting communities that depend on local ecosystems.', '/ˈnætʃərəl/', 'Việc bảo vệ các môi trường sống tự nhiên là điều cốt lõi để duy trì đa dạng sinh học và hỗ trợ các cộng đồng phụ thuộc vào hệ sinh thái bản địa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_9_2_1', 'en-a2-9', 'ten_a2_9_2', 'listening', 'listening', 'Strong emotions can cloud public judgment when communities debate the benefits and risks of new technologies.', NULL, 'Trong câu vừa nghe, từ “cloud” mang nghĩa nào sau đây?', '["bỏ lỡ; trễ","thẻ lên máy bay; giấy lên máy bay","có lẽ; chắc là","đám mây"]'::jsonb, 3, '“cloud” (/klaʊd/): đám mây. Câu đầy đủ: Strong emotions can cloud public judgment when communities debate the benefits and risks of new technologies.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_9_2_2', 'en-a2-9', 'ten_a2_9_2', 'listening', 'listening', 'Protecting natural habitats helps keep endangered species alive and preserves the ecological balance of entire regions.', NULL, 'Trong câu vừa nghe, từ “alive” mang nghĩa nào sau đây?', '["như thế; loại này","hạnh phúc; niềm vui","còn sống (thay vì đã chết)","thuộc nam giới; thuộc giống đực"]'::jsonb, 2, '“alive” (/əˈlaɪv/): còn sống (thay vì đã chết). Câu đầy đủ: Protecting natural habitats helps keep endangered species alive and preserves the ecological balance of entire regions.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
