INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_2', 'en-a2-9', NULL, 'comprehensive_test', 'listening', 'The tiny plant is still alive after our holiday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sau nhiều giờ lênh đênh trên biển, cuối cùng chúng tôi đã nhìn thấy đất liền khô ráo.","Mùa thu là mùa tôi yêu thích nhất để đi dạo trong rừng.","Chúng tôi đi dạo dọc theo bờ biển và nhặt những viên đá nhẵn.","Cây non vẫn còn sống sau kỳ nghỉ của chúng tôi."]'::jsonb, 3, 'The tiny plant is still alive after our holiday. → Cây non vẫn còn sống sau kỳ nghỉ của chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
