INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_4', 'en-a2-9', NULL, 'comprehensive_test', 'listening', 'A grey donkey carried baskets along the narrow mountain path.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một con nhện nhỏ đã giăng mạng ngay bên cửa sổ nhà chúng tôi.","Loại xà phòng này hoàn toàn được làm từ các thành phần tự nhiên.","Một con ngựa vằn đứng lặng lẽ bên vũng nước.","Một con lừa xám chở các giỏ hàng dọc theo con đường mòn nhỏ trên núi."]'::jsonb, 3, 'A grey donkey carried baskets along the narrow mountain path. → Một con lừa xám chở các giỏ hàng dọc theo con đường mòn nhỏ trên núi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_5', 'en-a2-9', NULL, 'comprehensive_test', 'listening', 'wild', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["hoang dã; mọc tự nhiên","quả nho; chùm nho","ngón chân","đồng bảng Anh (đơn vị tiền tệ chính của Vương quốc Anh)"]'::jsonb, 0, 'wild (/waɪld/) → hoang dã; mọc tự nhiên; cuồng nhiệt; quá khích; mất kiểm soát; vùng hoang dã; nơi hoang sơ', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_6', 'en-a2-9', NULL, 'comprehensive_test', 'listening', 'This soap is made entirely from natural ingredients.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một con kiến đang bò cõng mẩu vụn bánh mì qua sàn bếp.","Một con côn trùng màu xanh nhỏ xíu đậu lên tay áo của tôi.","Loại xà phòng này hoàn toàn được làm từ các thành phần tự nhiên.","Chúng tôi ngồi trên một tảng đá phẳng bên bờ sông."]'::jsonb, 2, 'This soap is made entirely from natural ingredients. → Loại xà phòng này hoàn toàn được làm từ các thành phần tự nhiên.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_7', 'en-a2-9', NULL, 'comprehensive_test', 'listening', 'snake', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["con rắn","thích hơn; ưu tiên hơn","xúc xích","tuyệt vời; xuất sắc"]'::jsonb, 0, 'snake (/sneɪk/) → con rắn; uốn lượn, chuyển động theo đường quanh co', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_8', 'en-a2-9', NULL, 'comprehensive_test', 'listening', 'A curious goat poked its head through the fence.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sau nhiều giờ lênh đênh trên biển, cuối cùng chúng tôi đã nhìn thấy đất liền khô ráo.","Một chú dê tò mò thò đầu qua hàng rào.","Một con vịt đang bơi lội tung tăng qua chỗ chúng tôi cùng với vài chú vịt con nhỏ xíu.","Cây non vẫn còn sống sau kỳ nghỉ của chúng tôi."]'::jsonb, 1, 'A curious goat poked its head through the fence. → Một chú dê tò mò thò đầu qua hàng rào.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_9', 'en-a2-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “living or growing naturally, without human care”?', '["wild","forest","storm","season"]'::jsonb, 0, 'wild (/waɪld/) → hoang dã; mọc tự nhiên', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_10', 'en-a2-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “existing in nature rather than made by people”?', '["coast","wild","shark","natural"]'::jsonb, 3, 'natural (/ˈnætʃərəl/) → thuộc về tự nhiên; tự nhiên', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_11', 'en-a2-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a long reptile without legs”?', '["snake","alive","goat","puppy"]'::jsonb, 0, 'snake (/sneɪk/) → con rắn', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_12', 'en-a2-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A hoofed animal, often with horns, kept for milk or meat.”?', '["windy","goat","sand","forest"]'::jsonb, 1, 'goat (/ɡoʊt/) → dê', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_13', 'en-a2-9', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A small animal with six legs and three main body sections.”?', '["natural","rock","coast","insect"]'::jsonb, 3, 'insect (/ˈɪnsekt/) → côn trùng; sâu bọ', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
