INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_18', 'en-a2-9', NULL, 'comprehensive_test', 'reading', NULL, 'Strong emotions can cloud public judgment when communities debate the benefits and risks of new technologies.', 'Dựa vào câu trên, từ “cloud” có nghĩa phù hợp nhất là gì?', '["tủ lạnh; tủ cấp đông","đám mây","một cách buồn bã; đầy đau buồn","đã; từ trước; đã từ lâu"]'::jsonb, 1, 'cloud: đám mây; đám (khói, bụi); màn; làm lu mờ; làm mập mờ (suy nghĩ, phán đoán). Dịch cả câu: Cảm xúc mạnh mẽ có thể làm lu mờ phán đoán của công chúng khi cộng đồng tranh luận về lợi ích và rủi ro của các công nghệ mới.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_19', 'en-a2-9', NULL, 'comprehensive_test', 'reading', NULL, 'Protecting natural habitats helps keep endangered species alive and preserves the ecological balance of entire regions.', 'Dựa vào câu trên, từ “alive” có nghĩa phù hợp nhất là gì?', '["bánh mì kẹp thịt; chả thịt băm","thuộc về nước ngoài; ngoại quốc","còn sống (thay vì đã chết)","cho phép; chuẩn y"]'::jsonb, 2, 'alive: còn sống (thay vì đã chết); tràn đầy năng lượng; náo nhiệt; sôi động. Dịch cả câu: Bảo vệ môi trường sống tự nhiên giúp duy trì sự sống cho các loài nguy cấp và giữ vững cân bằng sinh thái của toàn bộ khu vực.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_20', 'en-a2-9', NULL, 'comprehensive_test', 'reading', NULL, 'Protecting natural forests helps preserve biodiversity and reduces the amount of carbon dioxide in the atmosphere.', 'Dựa vào câu trên, từ “forest” có nghĩa phù hợp nhất là gì?', '["rừng; khu rừng lớn","trực tuyến; ở trên mạng","thất lễ; thô lỗ; bất lịch sự","không may là; đáng tiếc là"]'::jsonb, 0, 'forest: rừng; khu rừng lớn. Dịch cả câu: Bảo vệ các khu rừng tự nhiên giúp duy trì đa dạng sinh học và làm giảm lượng khí thải carbon dioxide trong khí quyển.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_21', 'en-a2-9', NULL, 'comprehensive_test', 'reading', NULL, 'In some rural communities, donkeys remain important for transporting goods where roads are unsuitable for vehicles.', 'Dựa vào câu trên, từ “donkey” có nghĩa phù hợp nhất là gì?', '["mỗi (trong hai); bất kỳ (trong hai)","lít (đơn vị đo thể tích bằng một nghìn mi-li-lít)","tổ chức; cơ quan; đoàn thể","con lừa"]'::jsonb, 3, 'donkey: con lừa. Dịch cả câu: Ở một số cộng đồng nông thôn, lừa vẫn đóng vai trò quan trọng trong việc vận chuyển hàng hóa ở những nơi đường sá không phù hợp cho xe cộ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_22', 'en-a2-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “con kiến”', '["ant","method","beside","lower"]'::jsonb, 0, 'con kiến → ant (/ænt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_9_23', 'en-a2-9', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bão; cơn bão”', '["cost","princess","storm","hide"]'::jsonb, 2, 'bão; cơn bão → storm (/stɔːrm/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
