INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-10', 'en', 'Bài 10: Thiên nhiên & Thời tiết (2) - CEFR A2', 'CEFR A2', 'A2 · Thiên nhiên', '25 từ vựng Tiếng Anh CEFR A2 chủ đề thiên nhiên & thời tiết kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2010, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rose', 'en-a2-10', 'rose', '/roʊz/', 'A2', 'hoa hồng; đã tăng lên; đã dâng lên (dạng quá khứ của rise)', 'n.', 'rosy (adj.), rise (v.), risen (v.)', NULL, 'rose cũng có thể là dạng quá khứ của rise; phân từ hai là risen.', 'She placed a single rose in a glass vase.', NULL, 'Cô ấy đặt một bông hoa hồng đơn lẻ vào một chiếc bình thủy tinh.', '{"wordId":"rose","ukIpa":"/rəʊz/","usIpa":"/roʊz/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"a flower with layered petals, often growing on thorny stems","vi":"hoa hồng"},{"pos":"v.","en":"past tense of rise: moved upwards or increased","vi":"đã tăng lên; đã dâng lên (dạng quá khứ của rise)"}],"examples":[{"en":"She placed a single rose in a glass vase.","vi":"Cô ấy đặt một bông hoa hồng đơn lẻ vào một chiếc bình thủy tinh.","audioKind":"ex"},{"en":"Demand for public transport rose sharply after the city introduced cheaper fares and more frequent services.","vi":"Nhu cầu về phương tiện giao thông công cộng đã tăng mạnh sau khi thành phố áp dụng giá vé rẻ hơn và tăng tần suất chuyến.","audioKind":"ex2"}],"collocations":[{"en":"a bunch of roses","vi":"một bó hoa hồng"},{"en":"rose petals","vi":"cánh hoa hồng"},{"en":"rose sharply","vi":"tăng mạnh"}],"wordFamily":["rosy (adj.)","rise (v.)","risen (v.)"],"synonyms":[],"antonyms":[],"tipVi":"rose cũng có thể là dạng quá khứ của rise; phân từ hai là risen.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_island', 'en-a2-10', 'island', '/ˈaɪlənd/', 'A2', 'hòn đảo', 'n.', 'islander (n.)', NULL, 'Chữ s trong island là âm câm; cấu trúc chỉ vị trí trên đảo là on an island.', 'We took a small boat to the island yesterday.', NULL, 'Hôm qua chúng tôi đi thuyền nhỏ ra đảo.', '{"wordId":"island","ukIpa":"/ˈaɪlənd/","usIpa":"/ˈaɪlənd/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"An area of land completely surrounded by water.","vi":"hòn đảo"}],"examples":[{"en":"We took a small boat to the island yesterday.","vi":"Hôm qua chúng tôi đi thuyền nhỏ ra đảo.","audioKind":"ex"},{"en":"Small island communities often depend on tourism, but increasing visitor numbers can threaten fragile coastal environments.","vi":"Các cộng đồng trên đảo nhỏ thường phụ thuộc vào du lịch, nhưng lượng du khách ngày càng tăng có thể đe dọa hệ sinh thái ven biển mỏng manh.","audioKind":"ex2"}],"collocations":[{"en":"remote island","vi":"hòn đảo xa xôi"},{"en":"tropical island","vi":"hòn đảo nhiệt đới"},{"en":"island nation","vi":"quốc gia hải đảo"},{"en":"uninhabited island","vi":"hòn đảo hoang vắng"}],"wordFamily":["islander (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ s trong island là âm câm; cấu trúc chỉ vị trí trên đảo là on an island.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kangaroo', 'en-a2-10', 'kangaroo', '/ˌkæŋɡəˈruː/', 'A2', 'chuột túi; con kangaroo', 'n.', NULL, NULL, 'Dạng số nhiều thêm -s thành kangaroos; chiếc túi nuôi con được gọi là pouch.', 'A young kangaroo peeked out of its mother''s pouch.', NULL, 'Một chú kangaroo con thò đầu ra khỏi chiếc túi trước bụng mẹ.', '{"wordId":"kangaroo","ukIpa":"/ˌkæŋɡəˈruː/","usIpa":"/ˌkæŋɡəˈruː/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"An Australian mammal with powerful hind legs; females carry pouch young.","vi":"chuột túi; con kangaroo"}],"examples":[{"en":"A young kangaroo peeked out of its mother''s pouch.","vi":"Một chú kangaroo con thò đầu ra khỏi chiếc túi trước bụng mẹ.","audioKind":"ex"},{"en":"Habitat loss can force kangaroo populations closer to roads, increasing the risk of collisions with vehicles.","vi":"Sự mất mát môi trường sống có thể buộc các đàn kangaroo tiến lại gần đường hơn, làm tăng nguy cơ va chạm với xe cộ.","audioKind":"ex2"}],"collocations":[{"en":"a kangaroo''s pouch","vi":"túi của kangaroo"},{"en":"red kangaroo","vi":"chuột túi đỏ"},{"en":"kangaroo population","vi":"quần thể kangaroo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều thêm -s thành kangaroos; chiếc túi nuôi con được gọi là pouch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_countryside', 'en-a2-10', 'countryside', '/ˈkʌntrisaɪd/', 'A2', 'vùng quê; miền quê', 'n.', NULL, 'Đồng nghĩa: rural areas', 'Thường là danh từ không đếm được, hay dùng the countryside, không dùng a countryside.', 'We spent the weekend cycling through the quiet countryside.', NULL, 'Chúng tôi đã dành cả cuối tuần để đạp xe qua vùng nông thôn yên bình.', '{"wordId":"countryside","ukIpa":"/ˈkʌntrisaɪd/","usIpa":"/ˈkʌntrisaɪd/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"land outside towns and cities, including fields, woods, and farms","vi":"vùng quê; miền quê"}],"examples":[{"en":"We spent the weekend cycling through the quiet countryside.","vi":"Chúng tôi đã dành cả cuối tuần để đạp xe qua vùng nông thôn yên bình.","audioKind":"ex"},{"en":"Reliable public transport in the countryside can improve access to employment and reduce rural residents'' dependence on cars.","vi":"Giao thông công cộng đáng tin cậy ở vùng nông thôn có thể cải thiện khả năng tiếp cận việc làm và giảm sự phụ thuộc của cư dân nông thôn vào ô tô.","audioKind":"ex2"}],"collocations":[{"en":"in the countryside","vi":"ở vùng quê"},{"en":"surrounding countryside","vi":"vùng nông thôn xung quanh"},{"en":"unspoilt countryside","vi":"vùng nông thôn hoang sơ"},{"en":"protect the countryside","vi":"bảo vệ vùng nông thôn"}],"wordFamily":[],"synonyms":["rural areas"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được, hay dùng the countryside, không dùng a countryside.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_leaves', 'en-a2-10', 'leaves', '/liːvz/', 'A2', 'những chiếc lá (dạng số nhiều của leaf); rời đi; để lại', 'n.', 'leaf (n.), leafy (adj.), leafless (adj.), leave (v.)', NULL, 'Vừa là dạng số nhiều của leaf, vừa là dạng chia động từ ngôi thứ ba số ít của leave.', 'Golden leaves covered the path outside our house.', NULL, 'Những chiếc lá vàng phủ kín lối đi bên ngoài ngôi nhà của chúng tôi.', '{"wordId":"leaves","ukIpa":"/liːvz/","usIpa":"/liːvz/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"The usually flat, green parts of plants.","vi":"những chiếc lá (dạng số nhiều của leaf)"},{"pos":"v.","en":"Goes away from somewhere, or lets something remain.","vi":"rời đi; để lại"}],"examples":[{"en":"Golden leaves covered the path outside our house.","vi":"Những chiếc lá vàng phủ kín lối đi bên ngoài ngôi nhà của chúng tôi.","audioKind":"ex"},{"en":"Fallen leaves provide habitats for small organisms and return valuable nutrients to the soil as they decompose.","vi":"Lá rụng cung cấp môi trường sống cho các sinh vật nhỏ và trả lại các chất dinh dưỡng quý giá cho đất khi chúng phân hủy.","audioKind":"ex2"}],"collocations":[{"en":"fallen leaves","vi":"lá rụng"},{"en":"green leaves","vi":"lá xanh"},{"en":"autumn leaves","vi":"lá mùa thu"},{"en":"rake leaves","vi":"cào lá rụng"}],"wordFamily":["leaf (n.)","leafy (adj.)","leafless (adj.)","leave (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Vừa là dạng số nhiều của leaf, vừa là dạng chia động từ ngôi thứ ba số ít của leave.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beauty', 'en-a2-10', 'beauty', '/ˈbjuːti/', 'A2', 'vẻ đẹp; nét đẹp; điểm hay; nét hấp dẫn', 'n.', 'beautiful (adj.), beautifully (adv.), beautify (v.), beautification (n.)', 'Đồng nghĩa: loveliness · Trái nghĩa: ugliness', 'Biểu thị "beauty" thường không đếm được; cụm "the beauty of" còn mang nghĩa là điểm hay hoặc điều thú vị.', 'We stopped to admire the beauty of the lake.', NULL, 'Chúng tôi dừng chân để chiêm ngưỡng vẻ đẹp của hồ nước.', '{"wordId":"beauty","ukIpa":"/ˈbjuːti/","usIpa":"/ˈbjuːti/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"The quality of being pleasing to see, hear, or experience.","vi":"vẻ đẹp; nét đẹp"},{"pos":"n.","en":"A particularly useful or attractive feature of something.","vi":"điểm hay; nét hấp dẫn"}],"examples":[{"en":"We stopped to admire the beauty of the lake.","vi":"Chúng tôi dừng chân để chiêm ngưỡng vẻ đẹp của hồ nước.","audioKind":"ex"},{"en":"Protecting the natural beauty of coastal areas can support tourism while preserving valuable habitats for wildlife.","vi":"Việc bảo vệ vẻ đẹp tự nhiên của các vùng ven biển có thể thúc đẩy du lịch đồng thời bảo tồn các môi trường sống quý giá cho động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"natural beauty","vi":"vẻ đẹp tự nhiên"},{"en":"outstanding beauty","vi":"vẻ đẹp tuyệt mỹ"},{"en":"the beauty of something","vi":"điểm hay của điều gì"}],"wordFamily":["beautiful (adj.)","beautifully (adv.)","beautify (v.)","beautification (n.)"],"synonyms":["loveliness"],"antonyms":["ugliness"],"tipVi":"Biểu thị \"beauty\" thường không đếm được; cụm \"the beauty of\" còn mang nghĩa là điểm hay hoặc điều thú vị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sunshine', 'en-a2-10', 'sunshine', '/ˈsʌnʃaɪn/', 'A2', 'ánh nắng; ánh mặt trời; niềm vui; người hoặc vật mang lại niềm vui', 'n.', 'sun (n.), sunny (adj.)', 'Đồng nghĩa: sunlight', 'sunshine thường không đếm được; để chỉ ngày nắng có thể dùng a sunny day.', 'We ate our breakfast outside in the warm sunshine.', NULL, 'Chúng tôi ăn sáng ngoài trời dưới ánh nắng ấm áp.', '{"wordId":"sunshine","ukIpa":"/ˈsʌnʃaɪn/","usIpa":"/ˈsʌnʃaɪn/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"light and warmth coming from the sun","vi":"ánh nắng; ánh mặt trời"},{"pos":"n.","en":"happiness, or someone or something that brings happiness","vi":"niềm vui; người hoặc vật mang lại niềm vui"}],"examples":[{"en":"We ate our breakfast outside in the warm sunshine.","vi":"Chúng tôi ăn sáng ngoài trời dưới ánh nắng ấm áp.","audioKind":"ex"},{"en":"Access to parks and sunshine can improve residents'' wellbeing, especially in densely populated urban areas.","vi":"Việc tiếp cận với công viên và ánh nắng mặt trời có thể cải thiện sức khỏe của cư dân, đặc biệt là ở những khu vực đô thị đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"bright sunshine","vi":"ánh nắng rực rỡ"},{"en":"in the sunshine","vi":"dưới ánh nắng"},{"en":"hours of sunshine","vi":"số giờ có nắng"},{"en":"a ray of sunshine","vi":"một tia nắng ấm áp (người/vật mang lại niềm vui)"}],"wordFamily":["sun (n.)","sunny (adj.)"],"synonyms":["sunlight"],"antonyms":[],"tipVi":"sunshine thường không đếm được; để chỉ ngày nắng có thể dùng a sunny day.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bee', 'en-a2-10', 'bee', '/biː/', 'A2', 'con ong', 'n.', 'beekeeper (n.), beekeeping (n.)', NULL, 'Từ bee phát âm giống hệt từ be; để chỉ một nhóm ong lớn, dùng cụm a swarm of bees.', 'A bee landed gently on the yellow flower.', NULL, 'Một con ong nhẹ nhàng đậu lên bông hoa màu vàng.', '{"wordId":"bee","ukIpa":"/biː/","usIpa":"/biː/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"a flying insect that collects pollen; some kinds make honey","vi":"con ong"}],"examples":[{"en":"A bee landed gently on the yellow flower.","vi":"Một con ong nhẹ nhàng đậu lên bông hoa màu vàng.","audioKind":"ex"},{"en":"Protecting bees is essential for agriculture because these insects pollinate many crops that humans depend on.","vi":"Việc bảo vệ loài ong có ý nghĩa sống còn đối với nông nghiệp vì chúng thụ phấn cho rất nhiều loại cây trồng mà con người phụ thuộc vào.","audioKind":"ex2"}],"collocations":[{"en":"honey bee","vi":"ong mật"},{"en":"a swarm of bees","vi":"một đàn ong"},{"en":"bee sting","vi":"vết ong đốt"},{"en":"bee colony","vi":"đàn ong; bầy ong"}],"wordFamily":["beekeeper (n.)","beekeeping (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ bee phát âm giống hệt từ be; để chỉ một nhóm ong lớn, dùng cụm a swarm of bees.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nature', 'en-a2-10', 'nature', '/ˈneɪtʃər/', 'A2', 'tự nhiên; thiên nhiên; bản chất; tính chất; bản tính; tính cách', 'n.', 'natural (adj.), naturally (adv.), naturalist (n.)', NULL, 'Khi chỉ thiên nhiên nói chung thường không dùng mạo từ the; nói về bản chất của cái gì dùng the nature of.', 'Camping helps us enjoy nature away from busy streets.', NULL, 'Cắm trại giúp chúng ta hòa mình vào thiên nhiên, tránh xa những con đường bận rộn.', '{"wordId":"nature","ukIpa":"/ˈneɪtʃə/","usIpa":"/ˈneɪtʃər/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"The physical world, including plants, animals, and landscapes.","vi":"tự nhiên; thiên nhiên"},{"pos":"n.","en":"The basic qualities that make something what it is.","vi":"bản chất; tính chất"},{"pos":"n.","en":"The qualities that shape how a person usually behaves.","vi":"bản tính; tính cách"}],"examples":[{"en":"Camping helps us enjoy nature away from busy streets.","vi":"Cắm trại giúp chúng ta hòa mình vào thiên nhiên, tránh xa những con đường bận rộn.","audioKind":"ex"},{"en":"Understanding the nature of urban poverty is essential for developing policies that address its underlying causes.","vi":"Hiểu được bản chất của đói nghèo đô thị là điều cốt yếu để hoạch định các chính sách giải quyết nguyên nhân gốc rễ của nó.","audioKind":"ex2"}],"collocations":[{"en":"protect nature","vi":"bảo vệ thiên nhiên"},{"en":"the nature of","vi":"bản chất của"},{"en":"human nature","vi":"bản tính con người"},{"en":"by nature","vi":"về bản chất"}],"wordFamily":["natural (adj.)","naturally (adv.)","naturalist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ thiên nhiên nói chung thường không dùng mạo từ the; nói về bản chất của cái gì dùng the nature of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sunset', 'en-a2-10', 'sunset', '/ˈsʌnset/', 'A2', 'hoàng hôn; thời điểm mặt trời lặn; cảnh hoàng hôn; chiều tà', 'n.', NULL, 'Đồng nghĩa: sundown · Trái nghĩa: sunrise', 'Chỉ thời điểm hoàng hôn dùng at sunset, thường không thêm mạo từ.', 'We reached the beach just before sunset yesterday.', NULL, 'Chúng tôi đã ra đến bãi biển ngay trước khi hoàng hôn buông xuống ngày hôm qua.', '{"wordId":"sunset","ukIpa":"/ˈsʌnset/","usIpa":"/ˈsʌnset/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"the time when the sun disappears below the horizon","vi":"hoàng hôn; thời điểm mặt trời lặn"},{"pos":"n.","en":"the colourful sky seen as the sun goes down","vi":"cảnh hoàng hôn; chiều tà"}],"examples":[{"en":"We reached the beach just before sunset yesterday.","vi":"Chúng tôi đã ra đến bãi biển ngay trước khi hoàng hôn buông xuống ngày hôm qua.","audioKind":"ex"},{"en":"Coastal destinations often attract tourists with spectacular sunset views, creating valuable opportunities for local businesses.","vi":"Các điểm đến ven biển thường thu hút du khách bằng cảnh hoàng hôn ngoạn mục, tạo ra cơ hội quý giá cho các doanh nghiệp địa phương.","audioKind":"ex2"}],"collocations":[{"en":"at sunset","vi":"vào lúc hoàng hôn"},{"en":"watch the sunset","vi":"ngắm hoàng hôn"},{"en":"a spectacular sunset","vi":"cảnh hoàng hôn ngoạn mục"}],"wordFamily":[],"synonyms":["sundown"],"antonyms":["sunrise"],"tipVi":"Chỉ thời điểm hoàng hôn dùng at sunset, thường không thêm mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_parrot', 'en-a2-10', 'parrot', '/ˈpærət/', 'A2', 'con vẹt; lặp lại máy móc; bắt chước như vẹt', 'n.', NULL, NULL, 'Khi dùng như động từ, từ này thường mang hàm ý chê bai, nhấn mạnh việc lặp lại mà không hiểu hoặc không suy nghĩ.', 'The green parrot cracked a seed with its beak.', NULL, 'Con vẹt màu xanh lá cây đã dùng cái mỏ của mình để cắn vỡ một hạt giống.', '{"wordId":"parrot","ukIpa":"/ˈpærət/","usIpa":"/ˈpærət/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"a tropical bird with a curved beak, sometimes copying speech","vi":"con vẹt"},{"pos":"v.","en":"to repeat someone''s words without understanding or considering them","vi":"lặp lại máy móc; bắt chước như vẹt"}],"examples":[{"en":"The green parrot cracked a seed with its beak.","vi":"Con vẹt màu xanh lá cây đã dùng cái mỏ của mình để cắn vỡ một hạt giống.","audioKind":"ex"},{"en":"Students who merely parrot their teachers'' explanations may struggle to apply knowledge to unfamiliar situations.","vi":"Những học sinh chỉ biết lặp lại một cách máy móc những lời giải thích của giáo viên có thể sẽ gặp khó khăn trong việc vận dụng kiến thức vào những tình huống xa lạ.","audioKind":"ex2"}],"collocations":[{"en":"pet parrot","vi":"vẹt cảnh"},{"en":"parrot someone''s words","vi":"lặp lại lời ai đó một cách máy móc"},{"en":"parrot fashion","vi":"bắt chước như vẹt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng như động từ, từ này thường mang hàm ý chê bai, nhấn mạnh việc lặp lại mà không hiểu hoặc không suy nghĩ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_frog', 'en-a2-10', 'frog', '/frɑːɡ/', 'A2', 'con ếch', 'n.', NULL, NULL, 'Danh từ đếm được, số nhiều là frogs; toad dùng để chỉ con cóc.', 'A green frog jumped from the stone into our pond.', NULL, 'Một con ếch xanh đã nhảy từ trên hòn đá xuống ao nhà chúng tôi.', '{"wordId":"frog","ukIpa":"/frɒɡ/","usIpa":"/frɑːɡ/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"A small amphibian with long back legs for jumping.","vi":"con ếch"}],"examples":[{"en":"A green frog jumped from the stone into our pond.","vi":"Một con ếch xanh đã nhảy từ trên hòn đá xuống ao nhà chúng tôi.","audioKind":"ex"},{"en":"Declining frog populations can indicate environmental damage because these animals are sensitive to changes in water quality.","vi":"Sự sụt giảm số lượng quần thể ếch có thể cho thấy môi trường đang bị tàn phá vì loài động vật này rất nhạy cảm với những biến động về chất lượng nước.","audioKind":"ex2"}],"collocations":[{"en":"tree frog","vi":"ếch cây"},{"en":"frog population","vi":"quần thể ếch"},{"en":"frog spawn","vi":"trứng ếch"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đếm được, số nhiều là frogs; toad dùng để chỉ con cóc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_butterfly', 'en-a2-10', 'butterfly', '/ˈbʌtərflaɪ/', 'A2', 'con bướm; kiểu bơi bướm', 'n.', NULL, NULL, 'Dạng số nhiều của từ này là butterflies; nghĩa bơi bướm thường là danh từ không đếm được.', 'A yellow butterfly landed gently on my sleeve.', NULL, 'Một con bướm vàng nhẹ nhàng đậu lên tay áo tôi.', '{"wordId":"butterfly","ukIpa":"/ˈbʌtəflaɪ/","usIpa":"/ˈbʌtərflaɪ/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"An insect with broad, often colourful wings and a thin body.","vi":"con bướm"},{"pos":"n.","en":"A swimming stroke with both arms moving forward together above water.","vi":"kiểu bơi bướm"}],"examples":[{"en":"A yellow butterfly landed gently on my sleeve.","vi":"Một con bướm vàng nhẹ nhàng đậu lên tay áo tôi.","audioKind":"ex"},{"en":"Planting native flowers in urban gardens can support butterfly populations and contribute to greater local biodiversity.","vi":"Việc trồng các loài hoa bản địa trong các khu vườn đô thị có thể hỗ trợ quần thể bướm và góp phần nâng cao đa dạng sinh học địa phương.","audioKind":"ex2"}],"collocations":[{"en":"butterfly wings","vi":"cánh bướm"},{"en":"butterfly species","vi":"các loài bướm"},{"en":"swim butterfly","vi":"bơi bướm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều của từ này là butterflies; nghĩa bơi bướm thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_foggy', 'en-a2-10', 'foggy', '/ˈfɑːɡi/', 'A2', 'có sương mù, mờ mịt; mơ hồ, không rõ ràng, khó nhớ', 'adj.', 'fog (n.)', 'Đồng nghĩa: misty, hazy · Trái nghĩa: clear', 'Từ foggy vừa có thể dùng để tả thời tiết, vừa có thể dùng để chỉ trí nhớ mơ hồ.', 'The road was so foggy that we drove slowly.', NULL, 'Đường có sương mù dày đặc đến mức chúng tôi phải lái xe rất chậm.', '{"wordId":"foggy","ukIpa":"/ˈfɒɡi/","usIpa":"/ˈfɑːɡi/","cefr":"A2","topic":"nature","senses":[{"pos":"adj.","en":"filled with fog, making things difficult to see","vi":"có sương mù, mờ mịt"},{"pos":"adj.","en":"unclear or difficult to remember or understand","vi":"mơ hồ, không rõ ràng, khó nhớ"}],"examples":[{"en":"The road was so foggy that we drove slowly.","vi":"Đường có sương mù dày đặc đến mức chúng tôi phải lái xe rất chậm.","audioKind":"ex"},{"en":"Foggy conditions can disrupt air travel, causing delays that affect both passengers and airport operations.","vi":"Điều kiện thời tiết sương mù có thể làm gián đoạn giao thông hàng không, gây ra sự chậm trễ ảnh hưởng đến cả hành khách lẫn hoạt động của sân bay.","audioKind":"ex2"}],"collocations":[{"en":"foggy weather","vi":"thời tiết sương mù"},{"en":"a foggy morning","vi":"buổi sáng sương mù"},{"en":"foggy conditions","vi":"điều kiện sương mù"}],"wordFamily":["fog (n.)"],"synonyms":["misty","hazy"],"antonyms":["clear"],"tipVi":"Từ foggy vừa có thể dùng để tả thời tiết, vừa có thể dùng để chỉ trí nhớ mơ hồ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crocodile', 'en-a2-10', 'crocodile', '/ˈkrɑːkədaɪl/', 'A2', 'cá sấu', 'n.', NULL, NULL, 'Alligator chỉ cá sấu Mỹ, khác với crocodile không phải cùng một loài.', 'We watched a crocodile slide into the river.', NULL, 'Chúng tôi đứng nhìn một con cá sấu trườn xuống sông.', '{"wordId":"crocodile","ukIpa":"/ˈkrɒkədaɪl/","usIpa":"/ˈkrɑːkədaɪl/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"a large reptile with tough skin, long jaws and tail","vi":"cá sấu"}],"examples":[{"en":"We watched a crocodile slide into the river.","vi":"Chúng tôi đứng nhìn một con cá sấu trườn xuống sông.","audioKind":"ex"},{"en":"Wetland conservation protects crocodile habitats while also supporting the fish and birds that depend on these ecosystems.","vi":"Công tác bảo tồn đất ngập nước giúp bảo vệ môi trường sống của cá sấu, đồng thời hỗ trợ các loài cá và chim phụ thuộc vào hệ sinh thái này.","audioKind":"ex2"}],"collocations":[{"en":"crocodile habitat","vi":"môi trường sống của cá sấu"},{"en":"crocodile eggs","vi":"trứng cá sấu"},{"en":"crocodile tears","vi":"nước mắt cá sấu (sự giả dối)"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Alligator chỉ cá sấu Mỹ, khác với crocodile không phải cùng một loài.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ground', 'en-a2-10', 'ground', '/ɡraʊnd/', 'A2', 'mặt đất, đất; căn cứ, lý do; bắt phải ở dưới mặt đất, làm cho máy bay đình cánh', 'n.', 'grounding (n.), grounded (adj.), groundless (adj.)', NULL, 'Để chỉ lý do thường dùng dạng số nhiều "grounds"; "ground" cũng là dạng quá khứ của "grind".', 'We spread a blanket on the ground beneath a tree.', NULL, 'Chúng tôi trải một tấm thảm xuống mặt đất dưới gốc cây.', '{"wordId":"ground","ukIpa":"/ɡraʊnd/","usIpa":"/ɡraʊnd/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"The solid surface of the earth.","vi":"mặt đất, đất"},{"pos":"n.","en":"Reasons or evidence supporting a belief, decision, or action.","vi":"căn cứ, lý do"},{"pos":"v.","en":"To prevent an aircraft from flying.","vi":"bắt phải ở dưới mặt đất, làm cho máy bay đình cánh"}],"examples":[{"en":"We spread a blanket on the ground beneath a tree.","vi":"Chúng tôi trải một tấm thảm xuống mặt đất dưới gốc cây.","audioKind":"ex"},{"en":"Planting trees helps the ground retain moisture and reduces the risk of soil erosion.","vi":"Việc trồng cây giúp giữ ẩm cho đất và làm giảm nguy cơ xói mòn đất.","audioKind":"ex2"}],"collocations":[{"en":"on the ground","vi":"trên mặt đất"},{"en":"grounds for complaint","vi":"lý do khiếu nại"},{"en":"common ground","vi":"điểm chung"},{"en":"ground a plane","vi":"đình chỉ bay của máy bay"}],"wordFamily":["grounding (n.)","grounded (adj.)","groundless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Để chỉ lý do thường dùng dạng số nhiều \"grounds\"; \"ground\" cũng là dạng quá khứ của \"grind\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wave', 'en-a2-10', 'wave', '/weɪv/', 'A2', 'sóng; sóng biển; vẫy (tay); ra hiệu; làn sóng; sự dâng trào đột ngột', 'n.', 'wavy (adj.)', NULL, 'Ra hiệu vẫy tay với ai đó dùng wave at hoặc wave to someone.', 'A huge wave washed over our little sandcastle.', NULL, 'Một con sóng lớn đã tràn qua lâu đài cát nhỏ của chúng tôi.', '{"wordId":"wave","ukIpa":"/weɪv/","usIpa":"/weɪv/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"A moving ridge of water or a travelling energy disturbance.","vi":"sóng; sóng biển"},{"pos":"v.","en":"To move a hand or object repeatedly as a signal.","vi":"vẫy (tay); ra hiệu"},{"pos":"n.","en":"A sudden increase or spread of something.","vi":"làn sóng; sự dâng trào đột ngột"}],"examples":[{"en":"A huge wave washed over our little sandcastle.","vi":"Một con sóng lớn đã tràn qua lâu đài cát nhỏ của chúng tôi.","audioKind":"ex"},{"en":"Coastal wetlands can absorb wave energy, helping to protect nearby settlements from erosion and storm damage.","vi":"Các vùng đất ngập nước ven biển có thể hấp thụ năng lượng sóng, giúp bảo vệ các khu dân cư lân cận khỏi tình trạng xói mòn và thiệt hại do bão.","audioKind":"ex2"}],"collocations":[{"en":"wave goodbye","vi":"vẫy tay tạm biệt"},{"en":"wave at someone","vi":"vẫy tay với ai đó"},{"en":"sound waves","vi":"sóng âm"},{"en":"a wave of protests","vi":"một làn sóng biểu tình"}],"wordFamily":["wavy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Ra hiệu vẫy tay với ai đó dùng wave at hoặc wave to someone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stone', 'en-a2-10', 'stone', '/stoʊn/', 'A2', 'đá; hòn đá; sỏi (trong cơ thể như sỏi thận); hạt (của một số loại quả)', 'n.', 'stony (adj.), stonemason (n.)', NULL, 'Chất liệu đá là danh từ không đếm được stone; một hòn đá cụ thể dùng a stone.', 'She picked up a smooth stone beside the lake.', NULL, 'Cô ấy nhặt một hòn đá nhẵn nhụi bên hồ.', '{"wordId":"stone","ukIpa":"/stəʊn/","usIpa":"/stoʊn/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"Hard natural material from the ground, or a piece of it.","vi":"đá; hòn đá"},{"pos":"n.","en":"A hard mass that forms inside an organ.","vi":"sỏi (trong cơ thể như sỏi thận)"},{"pos":"n.","en":"The hard central part of some fruits containing the seed.","vi":"hạt (của một số loại quả)"}],"examples":[{"en":"She picked up a smooth stone beside the lake.","vi":"Cô ấy nhặt một hòn đá nhẵn nhụi bên hồ.","audioKind":"ex"},{"en":"Buildings constructed from local stone can preserve regional character and reduce the environmental costs of transporting materials.","vi":"Các công trình xây dựng bằng đá địa phương có thể bảo tồn nét đặc trưng vùng miền và giảm chi phí vận chuyển vật liệu gây hại cho môi trường.","audioKind":"ex2"}],"collocations":[{"en":"made of stone","vi":"làm bằng đá"},{"en":"precious stone","vi":"đá quý"},{"en":"kidney stone","vi":"sỏi thận"},{"en":"a stone wall","vi":"một bức tường đá"}],"wordFamily":["stony (adj.)","stonemason (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chất liệu đá là danh từ không đếm được stone; một hòn đá cụ thể dùng a stone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wind', 'en-a2-10', 'wind', '/wɪnd/, /waɪnd/', 'A2', 'gió; quấn; cuộn; quấn quanh; uốn lượn; ngoằn ngoèo', 'n.', 'windy (adj.), winding (adj.)', NULL, 'Danh từ wind đọc là /wɪnd/; động từ mang nghĩa quấn đọc là /waɪnd/, có dạng quá khứ là wound.', 'A sudden gust of wind blew my hat away.', NULL, 'Một cơn gió bất chợt thổi bay chiếc mũ của tôi.', '{"wordId":"wind","ukIpa":"/wɪnd/, /waɪnd/","usIpa":"/wɪnd/, /waɪnd/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"Air moving naturally outdoors.","vi":"gió"},{"pos":"v.","en":"To wrap something around an object or itself.","vi":"quấn; cuộn; quấn quanh"},{"pos":"v.","en":"To follow a route with many bends and turns.","vi":"uốn lượn; ngoằn ngoèo"}],"examples":[{"en":"A sudden gust of wind blew my hat away.","vi":"Một cơn gió bất chợt thổi bay chiếc mũ của tôi.","audioKind":"ex"},{"en":"Investing in wind power can help countries reduce their dependence on fossil fuels and lower carbon emissions.","vi":"Đầu tư vào năng lượng gió có thể giúp các quốc gia giảm sự phụ thuộc vào nhiên liệu hóa thạch và cắt giảm lượng khí thải carbon.","audioKind":"ex2"}],"collocations":[{"en":"a gust of wind","vi":"một cơn gió"},{"en":"wind power","vi":"năng lượng gió"},{"en":"wind a clock","vi":"lên dây cót đồng hồ"},{"en":"wind through","vi":"uốn lượn xuyên qua"}],"wordFamily":["windy (adj.)","winding (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ wind đọc là /wɪnd/; động từ mang nghĩa quấn đọc là /waɪnd/, có dạng quá khứ là wound.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wood', 'en-a2-10', 'wood', '/wʊd/', 'A2', 'gỗ; vật liệu gỗ; rừng; khu rừng', 'n.', 'wooden (adj.), wooded (adj.), woodland (n.), woody (adj.)', 'Đồng nghĩa: timber', 'Nghĩa vật liệu gỗ không đếm được; nghĩa khu rừng có thể dùng a wood hoặc the woods.', 'This little chair is made entirely of solid wood.', NULL, 'Chiếc ghế nhỏ này được làm hoàn toàn bằng gỗ thịt.', '{"wordId":"wood","ukIpa":"/wʊd/","usIpa":"/wʊd/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"the hard material forming tree trunks and branches","vi":"gỗ; vật liệu gỗ"},{"pos":"n.","en":"an area of land covered with trees","vi":"rừng; khu rừng"}],"examples":[{"en":"This little chair is made entirely of solid wood.","vi":"Chiếc ghế nhỏ này được làm hoàn toàn bằng gỗ thịt.","audioKind":"ex"},{"en":"Using wood from responsibly managed forests can reduce the environmental impact of constructing new homes.","vi":"Sử dụng gỗ từ các khu rừng được quản lý có trách nhiệm có thể làm giảm tác động môi trường của việc xây dựng nhà mới.","audioKind":"ex2"}],"collocations":[{"en":"solid wood","vi":"gỗ thịt"},{"en":"wood carving","vi":"chạm khắc gỗ"},{"en":"a piece of wood","vi":"một khúc gỗ"},{"en":"walk in the woods","vi":"đi dạo trong rừng"}],"wordFamily":["wooden (adj.)","wooded (adj.)","woodland (n.)","woody (adj.)"],"synonyms":["timber"],"antonyms":[],"tipVi":"Nghĩa vật liệu gỗ không đếm được; nghĩa khu rừng có thể dùng a wood hoặc the woods.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fishing', 'en-a2-10', 'fishing', '/ˈfɪʃɪŋ/', 'A2', 'việc câu cá; hoạt động đánh bắt cá', 'n.', 'fish (n.), fish (v.), fisher (n.), fishery (n.)', NULL, 'Nói "đi câu cá" dùng go fishing, không dùng go to fishing.', 'We went fishing by the lake before breakfast.', NULL, 'Chúng tôi đã đi câu cá ở bên hồ trước bữa sáng.', '{"wordId":"fishing","ukIpa":"/ˈfɪʃɪŋ/","usIpa":"/ˈfɪʃɪŋ/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"the activity of catching fish for pleasure or food","vi":"việc câu cá; hoạt động đánh bắt cá"}],"examples":[{"en":"We went fishing by the lake before breakfast.","vi":"Chúng tôi đã đi câu cá ở bên hồ trước bữa sáng.","audioKind":"ex"},{"en":"Strict limits on commercial fishing can help marine ecosystems recover and support coastal communities in the long term.","vi":"Các quy định hạn chế nghiêm ngặt về đánh bắt thương mại có thể giúp các hệ sinh thái biển phục hồi và hỗ trợ bền vững cho các cộng đồng ven biển.","audioKind":"ex2"}],"collocations":[{"en":"go fishing","vi":"đi câu cá"},{"en":"fishing rod","vi":"cần câu"},{"en":"commercial fishing","vi":"đánh bắt cá thương mại"},{"en":"fishing village","vi":"làng chài"}],"wordFamily":["fish (n.)","fish (v.)","fisher (n.)","fishery (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nói \"đi câu cá\" dùng go fishing, không dùng go to fishing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lake', 'en-a2-10', 'lake', '/leɪk/', 'A2', 'hồ', 'n.', 'lakeside (n.)', NULL, 'on the lake nghĩa là ở trên mặt hồ; in the lake nghĩa là ở trong làn nước hồ.', 'We rented a small boat and crossed the lake.', NULL, 'Chúng tôi thuê một chiếc thuyền nhỏ và chèo sang bên kia hồ.', '{"wordId":"lake","ukIpa":"/leɪk/","usIpa":"/leɪk/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"A large area of water surrounded by land.","vi":"hồ"}],"examples":[{"en":"We rented a small boat and crossed the lake.","vi":"Chúng tôi thuê một chiếc thuyền nhỏ và chèo sang bên kia hồ.","audioKind":"ex"},{"en":"Agricultural pollution can damage lake ecosystems and threaten the communities that rely on them for drinking water.","vi":"Ô nhiễm nông nghiệp có thể tàn phá các hệ sinh thái hồ và đe dọa các cộng đồng dân cư phụ thuộc vào nguồn nước sinh hoạt từ đó.","audioKind":"ex2"}],"collocations":[{"en":"freshwater lake","vi":"hồ nước ngọt"},{"en":"saltwater lake","vi":"hồ nước mặn"},{"en":"the shore of a lake","vi":"bờ hồ"}],"wordFamily":["lakeside (n.)"],"synonyms":[],"antonyms":[],"tipVi":"on the lake nghĩa là ở trên mặt hồ; in the lake nghĩa là ở trong làn nước hồ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_panda', 'en-a2-10', 'panda', '/ˈpændə/', 'A2', 'gấu trúc', 'n.', NULL, NULL, '"panda" thường chỉ gấu trúc lớn; "red panda" chỉ gấu trúc đỏ.', 'The panda sat quietly, chewing a fresh bamboo shoot.', NULL, 'Con gấu trúc ngồi lặng lẽ, nhai một măng trúc tươi.', '{"wordId":"panda","ukIpa":"/ˈpændə/","usIpa":"/ˈpændə/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"a large black and white bear native to China","vi":"gấu trúc"}],"examples":[{"en":"The panda sat quietly, chewing a fresh bamboo shoot.","vi":"Con gấu trúc ngồi lặng lẽ, nhai một măng trúc tươi.","audioKind":"ex"},{"en":"Protecting panda habitats also benefits other species that depend on the same mountain forests for survival.","vi":"Việc bảo vệ môi trường sống của gấu trúc cũng mang lại lợi ích cho các loài động vật khác phụ thuộc vào cùng những cánh rừng trên núi để sinh tồn.","audioKind":"ex2"}],"collocations":[{"en":"giant panda","vi":"gấu trúc lớn"},{"en":"panda cub","vi":"gấu trúc con"},{"en":"panda habitat","vi":"môi trường sống của gấu trúc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"panda\" thường chỉ gấu trúc lớn; \"red panda\" chỉ gấu trúc đỏ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_goldfish', 'en-a2-10', 'goldfish', '/ˈɡoʊldfɪʃ/', 'A2', 'cá vàng', 'n.', NULL, NULL, 'goldfish có hình thức số ít và số nhiều giống nhau: one goldfish, two goldfish.', 'Our goldfish swims between the plants in its large tank.', NULL, 'Con cá vàng của chúng tôi bơi lội giữa những khóm cây trong bể cá lớn của nó.', '{"wordId":"goldfish","ukIpa":"/ˈɡəʊldfɪʃ/","usIpa":"/ˈɡoʊldfɪʃ/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"A small ornamental fish, often orange, kept in ponds or tanks.","vi":"cá vàng"}],"examples":[{"en":"Our goldfish swims between the plants in its large tank.","vi":"Con cá vàng của chúng tôi bơi lội giữa những khóm cây trong bể cá lớn của nó.","audioKind":"ex"},{"en":"Keeping goldfish in suitably sized tanks can teach children responsibility and the importance of animal welfare.","vi":"Nuôi cá vàng trong những bể có kích thước phù hợp có thể dạy cho trẻ em tính trách nhiệm và tầm quan trọng của việc phúc lợi động vật.","audioKind":"ex2"}],"collocations":[{"en":"keep goldfish","vi":"nuôi cá vàng"},{"en":"feed the goldfish","vi":"cho cá vàng ăn"},{"en":"goldfish pond","vi":"hồ cá vàng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"goldfish có hình thức số ít và số nhiều giống nhau: one goldfish, two goldfish.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tail', 'en-a2-10', 'tail', '/teɪl/', 'A2', 'đuôi (động vật hoặc máy bay); theo đuôi; bám theo', 'n.', 'tailless (adj.)', NULL, 'tail chỉ cái đuôi; tale chỉ câu chuyện, hai từ này phát âm giống nhau.', 'The dog wagged its tail when I came home.', NULL, 'Con chó vẫy đuôi khi tôi bước về nhà.', '{"wordId":"tail","ukIpa":"/teɪl/","usIpa":"/teɪl/","cefr":"A2","topic":"nature","senses":[{"pos":"n.","en":"the rear part of an animal or an aircraft","vi":"đuôi (động vật hoặc máy bay)"},{"pos":"v.","en":"to follow someone closely and watch where they go","vi":"theo đuôi; bám theo"}],"examples":[{"en":"The dog wagged its tail when I came home.","vi":"Con chó vẫy đuôi khi tôi bước về nhà.","audioKind":"ex"},{"en":"Some animals use their tails for balance, which helps them move safely through complex forest habitats.","vi":"Một số loài động vật dùng đuôi để giữ thăng bằng, giúp chúng di chuyển an toàn qua các sinh cảnh rừng phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"wag its tail","vi":"vẫy đuôi"},{"en":"a bushy tail","vi":"cái đuôi xù"},{"en":"the tail end","vi":"phần cuối"}],"wordFamily":["tailless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"tail chỉ cái đuôi; tale chỉ câu chuyện, hai từ này phát âm giống nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_10_1', 'en-a2-10', 'Cách dùng “parrot” (n.) — con vẹt', 'pet parrot  ·  parrot someone''s words  ·  parrot fashion', 'Khi dùng như động từ, từ này thường mang hàm ý chê bai, nhấn mạnh việc lặp lại mà không hiểu hoặc không suy nghĩ.', NULL, '[{"hanzi":"The green parrot cracked a seed with its beak.","pinyin":"","meaning":"Con vẹt màu xanh lá cây đã dùng cái mỏ của mình để cắn vỡ một hạt giống."},{"hanzi":"Students who merely parrot their teachers'' explanations may struggle to apply knowledge to unfamiliar situations.","pinyin":"","meaning":"Những học sinh chỉ biết lặp lại một cách máy móc những lời giải thích của giáo viên có thể sẽ gặp khó khăn trong việc vận dụng kiến thức vào những tình huống xa lạ."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_10_2', 'en-a2-10', 'Cách dùng “nature” (n.) — tự nhiên; thiên nhiên', 'protect nature  ·  the nature of  ·  human nature', 'Khi chỉ thiên nhiên nói chung thường không dùng mạo từ the; nói về bản chất của cái gì dùng the nature of.', 'Họ từ (Word Family): natural (adj.), naturally (adv.), naturalist (n.)', '[{"hanzi":"Camping helps us enjoy nature away from busy streets.","pinyin":"","meaning":"Cắm trại giúp chúng ta hòa mình vào thiên nhiên, tránh xa những con đường bận rộn."},{"hanzi":"Understanding the nature of urban poverty is essential for developing policies that address its underlying causes.","pinyin":"","meaning":"Hiểu được bản chất của đói nghèo đô thị là điều cốt yếu để hoạch định các chính sách giải quyết nguyên nhân gốc rễ của nó."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_10_3', 'en-a2-10', 'Cách dùng “beauty” (n.) — vẻ đẹp; nét đẹp', 'natural beauty  ·  outstanding beauty  ·  the beauty of something', 'Biểu thị "beauty" thường không đếm được; cụm "the beauty of" còn mang nghĩa là điểm hay hoặc điều thú vị.', 'Họ từ (Word Family): beautiful (adj.), beautifully (adv.), beautify (v.), beautification (n.) | Đồng nghĩa: loveliness · Trái nghĩa: ugliness', '[{"hanzi":"We stopped to admire the beauty of the lake.","pinyin":"","meaning":"Chúng tôi dừng chân để chiêm ngưỡng vẻ đẹp của hồ nước."},{"hanzi":"Protecting the natural beauty of coastal areas can support tourism while preserving valuable habitats for wildlife.","pinyin":"","meaning":"Việc bảo vệ vẻ đẹp tự nhiên của các vùng ven biển có thể thúc đẩy du lịch đồng thời bảo tồn các môi trường sống quý giá cho động vật hoang dã."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_10_4', 'en-a2-10', 'Cách dùng “wind” (n.) — gió', 'a gust of wind  ·  wind power  ·  wind a clock', 'Danh từ wind đọc là /wɪnd/; động từ mang nghĩa quấn đọc là /waɪnd/, có dạng quá khứ là wound.', 'Họ từ (Word Family): windy (adj.), winding (adj.)', '[{"hanzi":"A sudden gust of wind blew my hat away.","pinyin":"","meaning":"Một cơn gió bất chợt thổi bay chiếc mũ của tôi."},{"hanzi":"Investing in wind power can help countries reduce their dependence on fossil fuels and lower carbon emissions.","pinyin":"","meaning":"Đầu tư vào năng lượng gió có thể giúp các quốc gia giảm sự phụ thuộc vào nhiên liệu hóa thạch và cắt giảm lượng khí thải carbon."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_10_1', 'en-a2-10', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
