INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_10_1_2', 'ten_a2_10_1', 'island', 'We took a small boat to the island yesterday.', 'We took a small boat to the island yesterday.', '/ˈaɪlənd/', 'Hôm qua chúng tôi đi thuyền nhỏ ra đảo.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_10_1_3', 'ten_a2_10_1', 'kangaroo', 'A young kangaroo peeked out of its mother''s pouch.', 'A young kangaroo peeked out of its mother''s pouch.', '/ˌkæŋɡəˈruː/', 'Một chú kangaroo con thò đầu ra khỏi chiếc túi trước bụng mẹ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_10_1_4', 'ten_a2_10_1', 'countryside', 'We spent the weekend cycling through the quiet countryside.', 'We spent the weekend cycling through the quiet countryside.', '/ˈkʌntrisaɪd/', 'Chúng tôi đã dành cả cuối tuần để đạp xe qua vùng nông thôn yên bình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_10_1_5', 'ten_a2_10_1', 'leaves', 'Golden leaves covered the path outside our house.', 'Golden leaves covered the path outside our house.', '/liːvz/', 'Những chiếc lá vàng phủ kín lối đi bên ngoài ngôi nhà của chúng tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_10_1_6', 'ten_a2_10_1', 'beauty', 'We stopped to admire the beauty of the lake.', 'We stopped to admire the beauty of the lake.', '/ˈbjuːti/', 'Chúng tôi dừng chân để chiêm ngưỡng vẻ đẹp của hồ nước.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_10_1_7', 'ten_a2_10_1', 'sunshine', 'We ate our breakfast outside in the warm sunshine.', 'We ate our breakfast outside in the warm sunshine.', '/ˈsʌnʃaɪn/', 'Chúng tôi ăn sáng ngoài trời dưới ánh nắng ấm áp.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_10_1_8', 'ten_a2_10_1', 'bee', 'A bee landed gently on the yellow flower.', 'A bee landed gently on the yellow flower.', '/biː/', 'Một con ong nhẹ nhàng đậu lên bông hoa màu vàng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_10_1_1', 'en-a2-10', 'ten_a2_10_1', 'listening', 'listening', 'She placed a single rose in a glass vase.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Con gấu trúc ngồi lặng lẽ, nhai một măng trúc tươi.","Những chiếc lá vàng phủ kín lối đi bên ngoài ngôi nhà của chúng tôi.","Cô ấy đặt một bông hoa hồng đơn lẻ vào một chiếc bình thủy tinh.","Chúng tôi đã đi câu cá ở bên hồ trước bữa sáng."]'::jsonb, 2, 'She placed a single rose in a glass vase. → Cô ấy đặt một bông hoa hồng đơn lẻ vào một chiếc bình thủy tinh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_10_1_2', 'en-a2-10', 'ten_a2_10_1', 'listening', 'listening', 'We took a small boat to the island yesterday.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hôm qua chúng tôi đi thuyền nhỏ ra đảo.","Một con bướm vàng nhẹ nhàng đậu lên tay áo tôi.","Chúng tôi đã ra đến bãi biển ngay trước khi hoàng hôn buông xuống ngày hôm qua.","Con chó vẫy đuôi khi tôi bước về nhà."]'::jsonb, 0, 'We took a small boat to the island yesterday. → Hôm qua chúng tôi đi thuyền nhỏ ra đảo.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_10_1_3', 'en-a2-10', 'ten_a2_10_1', 'listening', 'listening', 'A young kangaroo peeked out of its mother''s pouch.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một chú kangaroo con thò đầu ra khỏi chiếc túi trước bụng mẹ.","Đường có sương mù dày đặc đến mức chúng tôi phải lái xe rất chậm.","Chúng tôi trải một tấm thảm xuống mặt đất dưới gốc cây.","Chúng tôi ăn sáng ngoài trời dưới ánh nắng ấm áp."]'::jsonb, 0, 'A young kangaroo peeked out of its mother''s pouch. → Một chú kangaroo con thò đầu ra khỏi chiếc túi trước bụng mẹ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_10_2', 'en-a2-10', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_10_2_1', 'ten_a2_10_2', 'rose', 'Demand for public transport rose sharply after the city introduced cheaper fares and more frequent services.', 'Demand for public transport rose sharply after the city introduced cheaper fares and more frequent services.', '/roʊz/', 'Nhu cầu về phương tiện giao thông công cộng đã tăng mạnh sau khi thành phố áp dụng giá vé rẻ hơn và tăng tần suất chuyến.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_10_2_2', 'ten_a2_10_2', 'island', 'Small island communities often depend on tourism, but increasing visitor numbers can threaten fragile coastal environments.', 'Small island communities often depend on tourism, but increasing visitor numbers can threaten fragile coastal environments.', '/ˈaɪlənd/', 'Các cộng đồng trên đảo nhỏ thường phụ thuộc vào du lịch, nhưng lượng du khách ngày càng tăng có thể đe dọa hệ sinh thái ven biển mỏng manh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_10_2_3', 'ten_a2_10_2', 'kangaroo', 'Habitat loss can force kangaroo populations closer to roads, increasing the risk of collisions with vehicles.', 'Habitat loss can force kangaroo populations closer to roads, increasing the risk of collisions with vehicles.', '/ˌkæŋɡəˈruː/', 'Sự mất mát môi trường sống có thể buộc các đàn kangaroo tiến lại gần đường hơn, làm tăng nguy cơ va chạm với xe cộ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_10_2_4', 'ten_a2_10_2', 'countryside', 'Reliable public transport in the countryside can improve access to employment and reduce rural residents'' dependence on cars.', 'Reliable public transport in the countryside can improve access to employment and reduce rural residents'' dependence on cars.', '/ˈkʌntrisaɪd/', 'Giao thông công cộng đáng tin cậy ở vùng nông thôn có thể cải thiện khả năng tiếp cận việc làm và giảm sự phụ thuộc của cư dân nông thôn vào ô tô.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_10_2_5', 'ten_a2_10_2', 'leaves', 'Fallen leaves provide habitats for small organisms and return valuable nutrients to the soil as they decompose.', 'Fallen leaves provide habitats for small organisms and return valuable nutrients to the soil as they decompose.', '/liːvz/', 'Lá rụng cung cấp môi trường sống cho các sinh vật nhỏ và trả lại các chất dinh dưỡng quý giá cho đất khi chúng phân hủy.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_10_2_6', 'ten_a2_10_2', 'beauty', 'Protecting the natural beauty of coastal areas can support tourism while preserving valuable habitats for wildlife.', 'Protecting the natural beauty of coastal areas can support tourism while preserving valuable habitats for wildlife.', '/ˈbjuːti/', 'Việc bảo vệ vẻ đẹp tự nhiên của các vùng ven biển có thể thúc đẩy du lịch đồng thời bảo tồn các môi trường sống quý giá cho động vật hoang dã.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
