INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_10_2', 'en-a2-10', NULL, 'comprehensive_test', 'listening', 'We took a small boat to the island yesterday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hôm qua chúng tôi đi thuyền nhỏ ra đảo.","Một con sóng lớn đã tràn qua lâu đài cát nhỏ của chúng tôi.","Chiếc ghế nhỏ này được làm hoàn toàn bằng gỗ thịt.","Cô ấy nhặt một hòn đá nhẵn nhụi bên hồ."]'::jsonb, 0, 'We took a small boat to the island yesterday. → Hôm qua chúng tôi đi thuyền nhỏ ra đảo.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
