INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_10_4', 'en-a2-10', NULL, 'comprehensive_test', 'listening', 'We spent the weekend cycling through the quiet countryside.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một chú kangaroo con thò đầu ra khỏi chiếc túi trước bụng mẹ.","Cắm trại giúp chúng ta hòa mình vào thiên nhiên, tránh xa những con đường bận rộn.","Một con ếch xanh đã nhảy từ trên hòn đá xuống ao nhà chúng tôi.","Chúng tôi đã dành cả cuối tuần để đạp xe qua vùng nông thôn yên bình."]'::jsonb, 3, 'We spent the weekend cycling through the quiet countryside. → Chúng tôi đã dành cả cuối tuần để đạp xe qua vùng nông thôn yên bình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_10_5', 'en-a2-10', NULL, 'comprehensive_test', 'listening', 'leaves', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chủ đề; đề tài; môn học; đối tượng","những chiếc lá (dạng số nhiều của leaf)","lộn xộn; bừa bãi; bẩn thỉu","hy vọng; mong ước"]'::jsonb, 1, 'leaves (/liːvz/) → những chiếc lá (dạng số nhiều của leaf); rời đi; để lại', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_10_6', 'en-a2-10', NULL, 'comprehensive_test', 'listening', 'We stopped to admire the beauty of the lake.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi dừng chân để chiêm ngưỡng vẻ đẹp của hồ nước.","Một con ong nhẹ nhàng đậu lên bông hoa màu vàng.","Cô ấy nhặt một hòn đá nhẵn nhụi bên hồ.","Một chú kangaroo con thò đầu ra khỏi chiếc túi trước bụng mẹ."]'::jsonb, 0, 'We stopped to admire the beauty of the lake. → Chúng tôi dừng chân để chiêm ngưỡng vẻ đẹp của hồ nước.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_10_7', 'en-a2-10', NULL, 'comprehensive_test', 'listening', 'sunshine', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ánh nắng; ánh mặt trời","thất lễ; thô lỗ; bất lịch sự","đóng; khép; ngừng hoạt động","bài luận; bài văn; bài viết ngắn"]'::jsonb, 0, 'sunshine (/ˈsʌnʃaɪn/) → ánh nắng; ánh mặt trời; niềm vui; người hoặc vật mang lại niềm vui', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_10_8', 'en-a2-10', NULL, 'comprehensive_test', 'listening', 'A bee landed gently on the yellow flower.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã ra đến bãi biển ngay trước khi hoàng hôn buông xuống ngày hôm qua.","Một con ong nhẹ nhàng đậu lên bông hoa màu vàng.","Chúng tôi dừng chân để chiêm ngưỡng vẻ đẹp của hồ nước.","Một con sóng lớn đã tràn qua lâu đài cát nhỏ của chúng tôi."]'::jsonb, 1, 'A bee landed gently on the yellow flower. → Một con ong nhẹ nhàng đậu lên bông hoa màu vàng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_10_9', 'en-a2-10', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The usually flat, green parts of plants.”?', '["tail","lake","leaves","nature"]'::jsonb, 2, 'leaves (/liːvz/) → những chiếc lá (dạng số nhiều của leaf)', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
