INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_10_18', 'en-a2-10', NULL, 'comprehensive_test', 'reading', NULL, 'Demand for public transport rose sharply after the city introduced cheaper fares and more frequent services.', 'Dựa vào câu trên, từ “rose” có nghĩa phù hợp nhất là gì?', '["vật lý học","bình hoa; lọ hoa","ngón chân","hoa hồng"]'::jsonb, 3, 'rose: hoa hồng; đã tăng lên; đã dâng lên (dạng quá khứ của rise). Dịch cả câu: Nhu cầu về phương tiện giao thông công cộng đã tăng mạnh sau khi thành phố áp dụng giá vé rẻ hơn và tăng tần suất chuyến.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_10_19', 'en-a2-10', NULL, 'comprehensive_test', 'reading', NULL, 'Small island communities often depend on tourism, but increasing visitor numbers can threaten fragile coastal environments.', 'Dựa vào câu trên, từ “island” có nghĩa phù hợp nhất là gì?', '["sức khỏe; thể trạng","hòn đảo","mật khẩu; mật mã","thay vào đó; thay thế"]'::jsonb, 1, 'island: hòn đảo. Dịch cả câu: Các cộng đồng trên đảo nhỏ thường phụ thuộc vào du lịch, nhưng lượng du khách ngày càng tăng có thể đe dọa hệ sinh thái ven biển mỏng manh.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_10_20', 'en-a2-10', NULL, 'comprehensive_test', 'reading', NULL, 'Habitat loss can force kangaroo populations closer to roads, increasing the risk of collisions with vehicles.', 'Dựa vào câu trên, từ “kangaroo” có nghĩa phù hợp nhất là gì?', '["chuột túi; con kangaroo","hướng dẫn viên; người dẫn đường","phép thuật; trò ảo thuật","chúng tôi (chính mình); chúng ta (chính mình)"]'::jsonb, 0, 'kangaroo: chuột túi; con kangaroo. Dịch cả câu: Sự mất mát môi trường sống có thể buộc các đàn kangaroo tiến lại gần đường hơn, làm tăng nguy cơ va chạm với xe cộ.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_10_21', 'en-a2-10', NULL, 'comprehensive_test', 'reading', NULL, 'Reliable public transport in the countryside can improve access to employment and reduce rural residents'' dependence on cars.', 'Dựa vào câu trên, từ “countryside” có nghĩa phù hợp nhất là gì?', '["trại; khu cắm trại","bằng cấp; văn bằng","nguyên nhân, căn nguyên","vùng quê; miền quê"]'::jsonb, 3, 'countryside: vùng quê; miền quê. Dịch cả câu: Giao thông công cộng đáng tin cậy ở vùng nông thôn có thể cải thiện khả năng tiếp cận việc làm và giảm sự phụ thuộc của cư dân nông thôn vào ô tô.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
