INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_10_24', 'en-a2-10', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đuôi (động vật hoặc máy bay)”', '["tail","brain","recording","voice"]'::jsonb, 0, 'đuôi (động vật hoặc máy bay) → tail (/teɪl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-11', 'en', 'Bài 11: Môi trường & Sinh thái - CEFR A2', 'CEFR A2', 'A2 · Môi trường', '12 từ vựng Tiếng Anh CEFR A2 chủ đề môi trường & sinh thái kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2011, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plastic', 'en-a2-11', 'plastic', '/ˈplæstɪk/', 'A2', 'chất dẻo; nhựa; bằng nhựa; dẻo; dễ uốn nắn', 'n.', 'plasticity (n.)', NULL, 'Khi chỉ vật liệu nhựa thì thường không đếm được; a plastic chỉ một loại nhựa cụ thể.', 'This lunch box is made of strong recycled plastic.', NULL, 'Hộp đựng cơm này được làm từ nhựa tái chế chắc chắn.', '{"wordId":"plastic","ukIpa":"/ˈplæstɪk/","usIpa":"/ˈplæstɪk/","cefr":"A2","topic":"environment","senses":[{"pos":"n.","en":"a lightweight manufactured material that can form many different shapes","vi":"chất dẻo; nhựa"},{"pos":"adj.","en":"made of plastic","vi":"bằng nhựa"},{"pos":"adj.","en":"able to be shaped or changed easily","vi":"dẻo; dễ uốn nắn"}],"examples":[{"en":"This lunch box is made of strong recycled plastic.","vi":"Hộp đựng cơm này được làm từ nhựa tái chế chắc chắn.","audioKind":"ex"},{"en":"Reducing single-use plastic packaging could protect marine ecosystems and lower the costs of managing household waste.","vi":"Việc giảm thiểu bao bì nhựa dùng một lần có thể bảo vệ các hệ sinh thái biển và hạ thấp chi phí xử lý rác thải sinh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"single-use plastic","vi":"nhựa dùng một lần"},{"en":"plastic waste","vi":"rác thải nhựa"},{"en":"plastic packaging","vi":"bao bì nhựa"},{"en":"recycled plastic","vi":"nhựa tái chế"}],"wordFamily":["plasticity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ vật liệu nhựa thì thường không đếm được; a plastic chỉ một loại nhựa cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_protect', 'en-a2-11', 'protect', '/prəˈtekt/', 'A2', 'bảo vệ, che chở khỏi nguy hiểm hoặc tổn hại', 'v.', 'protection (n.), protective (adj.), protector (n.), unprotected (adj.)', 'Đồng nghĩa: safeguard, shield, defend · Trái nghĩa: endanger', 'Thường đi với cấu trúc protect sb/sth from hoặc against để chỉ việc che chở khỏi sự tổn thương.', 'Wear thick gloves to protect your hands from thorns.', NULL, 'Hãy đeo găng tay dày để bảo vệ đôi tay khỏi bị gai đâm.', '{"wordId":"protect","ukIpa":"/prəˈtekt/","usIpa":"/prəˈtekt/","cefr":"A2","topic":"environment","senses":[{"pos":"v.","en":"To keep someone or something safe from harm or damage","vi":"bảo vệ, che chở khỏi nguy hiểm hoặc tổn hại"}],"examples":[{"en":"Wear thick gloves to protect your hands from thorns.","vi":"Hãy đeo găng tay dày để bảo vệ đôi tay khỏi bị gai đâm.","audioKind":"ex"},{"en":"Governments should protect endangered species by preserving natural habitats and restricting activities that threaten their survival.","vi":"Chính phủ nên bảo vệ các loài có nguy cơ tuyệt chủng bằng cách gìn giữ môi trường sống tự nhiên và hạn chế các hoạt động đe dọa sự sinh tồn của chúng.","audioKind":"ex2"}],"collocations":[{"en":"protect the environment","vi":"bảo vệ môi trường"},{"en":"protect against disease","vi":"phòng ngừa dịch bệnh"},{"en":"protect from harm","vi":"bảo vệ khỏi tổn hại"},{"en":"protect privacy","vi":"bảo vệ quyền riêng tư"}],"wordFamily":["protection (n.)","protective (adj.)","protector (n.)","unprotected (adj.)"],"synonyms":["safeguard","shield","defend"],"antonyms":["endanger"],"tipVi":"Thường đi với cấu trúc protect sb/sth from hoặc against để chỉ việc che chở khỏi sự tổn thương.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_energy', 'en-a2-11', 'energy', '/ˈenɚdʒi/', 'A2', 'năng lượng; sinh lực; nguồn điện', 'n.', 'energetic (adj.), energetically (adv.), energise (v.)', 'Đồng nghĩa: vitality, vigour', 'Khi chỉ sức lực hoặc năng lượng nói chung, từ này thường không đếm được, không dùng an energy.', 'After a short nap, I had energy to cook.', NULL, 'Sau một giấc ngủ ngắn, tôi đã có năng lượng để nấu ăn.', '{"wordId":"energy","ukIpa":"/ˈenədʒi/","usIpa":"/ˈenɚdʒi/","cefr":"A2","topic":"environment","senses":[{"pos":"n.","en":"The strength and enthusiasm needed for physical or mental activity","vi":"năng lượng; sinh lực"},{"pos":"n.","en":"Power used to produce heat, movement, light, or electricity","vi":"năng lượng; nguồn điện"}],"examples":[{"en":"After a short nap, I had energy to cook.","vi":"Sau một giấc ngủ ngắn, tôi đã có năng lượng để nấu ăn.","audioKind":"ex"},{"en":"Investing in renewable energy can reduce dependence on fossil fuels while creating new employment opportunities.","vi":"Đầu tư vào năng lượng tái tạo có thể làm giảm sự phụ thuộc vào nhiên liệu hóa thạch đồng thời tạo ra các cơ hội việc làm mới.","audioKind":"ex2"}],"collocations":[{"en":"full of energy","vi":"tràn đầy năng lượng"},{"en":"renewable energy","vi":"năng lượng tái tạo"},{"en":"energy consumption","vi":"mức tiêu thụ năng lượng"},{"en":"save energy","vi":"tiết kiệm năng lượng"}],"wordFamily":["energetic (adj.)","energetically (adv.)","energise (v.)"],"synonyms":["vitality","vigour"],"antonyms":[],"tipVi":"Khi chỉ sức lực hoặc năng lượng nói chung, từ này thường không đếm được, không dùng an energy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_waste', 'en-a2-11', 'waste', '/weɪst/', 'A2', 'lãng phí; chất thải; rác thải; sự lãng phí', 'v.', 'wasteful (adj.), wastefully (adv.), wastage (n.)', 'Đồng nghĩa: squander, rubbish · Trái nghĩa: conserve', 'Dùng cấu trúc waste time doing sth, thường không dùng to do.', 'Don''t waste water by leaving the tap running.', NULL, 'Đừng để vòi nước chảy liên tục gây lãng phí nước.', '{"wordId":"waste","ukIpa":"/weɪst/","usIpa":"/weɪst/","cefr":"A2","topic":"environment","senses":[{"pos":"v.","en":"Use more of something than necessary or without useful results.","vi":"lãng phí"},{"pos":"n.","en":"Unwanted material left after something has been used or made.","vi":"chất thải; rác thải"},{"pos":"n.","en":"An unnecessary or unproductive use of time, money, or resources.","vi":"sự lãng phí"}],"examples":[{"en":"Don''t waste water by leaving the tap running.","vi":"Đừng để vòi nước chảy liên tục gây lãng phí nước.","audioKind":"ex"},{"en":"Reducing household waste requires both convenient recycling facilities and greater public awareness of responsible consumption.","vi":"Việc giảm thiểu rác thải sinh hoạt đòi hỏi cả cơ sở tái chế thuận tiện lẫn ý thức tiêu dùng có trách nhiệm cao hơn từ phía cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"waste time","vi":"lãng phí thời gian"},{"en":"a waste of money","vi":"lãng phí tiền bạc"},{"en":"household waste","vi":"rác thải sinh hoạt"},{"en":"food waste","vi":"lãng phí thực phẩm"}],"wordFamily":["wasteful (adj.)","wastefully (adv.)","wastage (n.)"],"synonyms":["squander","rubbish"],"antonyms":["conserve"],"tipVi":"Dùng cấu trúc waste time doing sth, thường không dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rubbish', 'en-a2-11', 'rubbish', '/ˈrʌbɪʃ/', 'A2', 'rác thải; phế liệu; lời nhảm nhí; điều vô nghĩa', 'n.', NULL, 'Đồng nghĩa: garbage, trash', 'Thường là danh từ không đếm được; đây là từ thông dụng trong tiếng Anh-Anh, trong khi tiếng Anh-Mỹ thường dùng garbage hoặc trash.', 'Please put your rubbish in the bin outside.', NULL, 'Làm ơn vứt rác của bạn vào thùng rác ở bên ngoài.', '{"wordId":"rubbish","ukIpa":"/ˈrʌbɪʃ/","usIpa":"/ˈrʌbɪʃ/","cefr":"A2","topic":"environment","senses":[{"pos":"n.","en":"Things people throw away because they no longer need them.","vi":"rác thải; phế liệu"},{"pos":"n.","en":"Ideas or statements that are silly or untrue.","vi":"lời nhảm nhí; điều vô nghĩa"}],"examples":[{"en":"Please put your rubbish in the bin outside.","vi":"Làm ơn vứt rác của bạn vào thùng rác ở bên ngoài.","audioKind":"ex"},{"en":"Reducing household rubbish requires both convenient recycling facilities and greater public awareness of unnecessary packaging.","vi":"Việc giảm thiểu rác thải sinh hoạt đòi hỏi cả cơ sở tái chế thuận tiện lẫn ý thức chung cao hơn của cộng đồng về vấn đề bao bì không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"household rubbish","vi":"rác thải sinh hoạt"},{"en":"rubbish bin","vi":"thùng rác"},{"en":"collect rubbish","vi":"thu gom rác"},{"en":"talk rubbish","vi":"nói nhảm; nói điều vô nghĩa"}],"wordFamily":[],"synonyms":["garbage","trash"],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; đây là từ thông dụng trong tiếng Anh-Anh, trong khi tiếng Anh-Mỹ thường dùng garbage hoặc trash.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_destroy', 'en-a2-11', 'destroy', '/dɪˈstrɔɪ/', 'A2', 'phá hủy; tàn phá; phá hoại hoàn toàn', 'v.', 'destruction (n.), destructive (adj.), destroyer (n.)', 'Đồng nghĩa: ruin, wreck · Trái nghĩa: create, preserve', 'destroy có mức độ nghiêm trọng hơn damage, thường dùng để chỉ việc hủy hoại hoàn toàn không thể phục hồi.', 'A sudden storm destroyed the old shed behind our house.', NULL, 'Một cơn bão bất chợt đã tàn phá cái nhà kho cũ phía sau nhà chúng tôi.', '{"wordId":"destroy","ukIpa":"/dɪˈstrɔɪ/","usIpa":"/dɪˈstrɔɪ/","cefr":"A2","topic":"environment","senses":[{"pos":"v.","en":"To damage something so badly that it cannot be used.","vi":"phá hủy; tàn phá"},{"pos":"v.","en":"To completely end something valuable, such as trust or hope.","vi":"phá hoại hoàn toàn"}],"examples":[{"en":"A sudden storm destroyed the old shed behind our house.","vi":"Một cơn bão bất chợt đã tàn phá cái nhà kho cũ phía sau nhà chúng tôi.","audioKind":"ex"},{"en":"Uncontrolled urban expansion can destroy natural habitats and threaten the survival of species that depend on them.","vi":"Sự bành trướng đô thị không được kiểm soát có thể phá hủy các sinh cảnh tự nhiên và đe dọa sự sống còn của các loài phụ thuộc vào chúng.","audioKind":"ex2"}],"collocations":[{"en":"destroy habitats","vi":"phá hủy môi trường sống"},{"en":"destroy evidence","vi":"tiêu hủy chứng cứ"},{"en":"destroy confidence","vi":"làm mất niềm tin"},{"en":"completely destroy","vi":"phá hủy hoàn toàn"}],"wordFamily":["destruction (n.)","destructive (adj.)","destroyer (n.)"],"synonyms":["ruin","wreck"],"antonyms":["create","preserve"],"tipVi":"destroy có mức độ nghiêm trọng hơn damage, thường dùng để chỉ việc hủy hoại hoàn toàn không thể phục hồi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ocean', 'en-a2-11', 'ocean', '/ˈoʊʃən/', 'A2', 'đại dương; biển lớn', 'n.', 'oceanic (adj.), oceanography (n.), oceanographer (n.)', 'Đồng nghĩa: sea', 'ocean thường có diện tích lớn hơn sea; tên riêng của các đại dương thường đi với mạo từ the.', 'We watched the sun rise over the ocean.', NULL, 'Chúng tôi ngắm nhìn mặt trời mọc trên biển.', '{"wordId":"ocean","ukIpa":"/ˈəʊʃən/","usIpa":"/ˈoʊʃən/","cefr":"A2","topic":"environment","senses":[{"pos":"n.","en":"The vast salt water covering much of Earth''s surface.","vi":"đại dương; biển lớn"}],"examples":[{"en":"We watched the sun rise over the ocean.","vi":"Chúng tôi ngắm nhìn mặt trời mọc trên biển.","audioKind":"ex"},{"en":"Plastic waste entering the ocean threatens marine wildlife and can eventually affect human health through food chains.","vi":"Rác thải nhựa trôi nổi vào đại dương đe dọa động vật hoang dã biển và cuối cùng có thể ảnh hưởng đến sức khỏe con người thông qua chuỗi thức ăn.","audioKind":"ex2"}],"collocations":[{"en":"ocean currents","vi":"dòng hải lưu"},{"en":"the ocean floor","vi":"đáy đại dương"},{"en":"ocean pollution","vi":"ô nhiễm đại dương"}],"wordFamily":["oceanic (adj.)","oceanography (n.)","oceanographer (n.)"],"synonyms":["sea"],"antonyms":[],"tipVi":"ocean thường có diện tích lớn hơn sea; tên riêng của các đại dương thường đi với mạo từ the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_garbage', 'en-a2-11', 'garbage', '/ˈɡɑːrbɪdʒ/', 'A2', 'rác thải; vật bỏ đi; nói nhảm; thứ vô giá trị', 'n.', NULL, 'Đồng nghĩa: rubbish, trash', 'Là danh từ không đếm được; thường dùng trong tiếng Anh-Mỹ, trong khi tiếng Anh-Anh hay dùng rubbish.', 'Please take the garbage out before it starts smelling.', NULL, 'Làm ơn mang rác đi đổ trước khi nó bắt đầu bốc mùi.', '{"wordId":"garbage","ukIpa":"/ˈɡɑːbɪdʒ/","usIpa":"/ˈɡɑːrbɪdʒ/","cefr":"A2","topic":"environment","senses":[{"pos":"n.","en":"waste material that people throw away","vi":"rác thải; vật bỏ đi"},{"pos":"n.","en":"something considered untrue, useless, or very poor in quality","vi":"nói nhảm; thứ vô giá trị"}],"examples":[{"en":"Please take the garbage out before it starts smelling.","vi":"Làm ơn mang rác đi đổ trước khi nó bắt đầu bốc mùi.","audioKind":"ex"},{"en":"Cities can reduce the amount of garbage sent to landfill by improving recycling facilities and public awareness.","vi":"Các thành phố có thể giảm lượng rác thải đưa tới bãi chôn lấp bằng cách cải thiện các cơ sở tái chế và nâng cao nhận thức cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"take out the garbage","vi":"mang rác đi đổ"},{"en":"garbage collection","vi":"thu gom rác"},{"en":"a garbage bag","vi":"túi đựng rác"},{"en":"a garbage can","vi":"thùng đựng rác"}],"wordFamily":[],"synonyms":["rubbish","trash"],"antonyms":[],"tipVi":"Là danh từ không đếm được; thường dùng trong tiếng Anh-Mỹ, trong khi tiếng Anh-Anh hay dùng rubbish.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_noise', 'en-a2-11', 'noise', '/nɔɪz/', 'A2', 'tiếng ồn; tiếng động', 'n.', 'noisy (adj.), noisily (adv.), noiseless (adj.)', 'Đồng nghĩa: sound · Trái nghĩa: silence', 'Khi chỉ chung chung thì noise không đếm được; chỉ một tiếng động cụ thể thì dùng a noise.', 'The noise outside woke me before my alarm rang.', NULL, 'Tiếng ồn bên ngoài đã đánh thức tôi dậy trước khi đồng hồ báo thức kêu.', '{"wordId":"noise","ukIpa":"/nɔɪz/","usIpa":"/nɔɪz/","cefr":"A2","topic":"environment","senses":[{"pos":"n.","en":"a sound, especially one that is loud or unwanted","vi":"tiếng ồn; tiếng động"}],"examples":[{"en":"The noise outside woke me before my alarm rang.","vi":"Tiếng ồn bên ngoài đã đánh thức tôi dậy trước khi đồng hồ báo thức kêu.","audioKind":"ex"},{"en":"Prolonged exposure to traffic noise can affect sleep quality and reduce the wellbeing of urban residents.","vi":"Việc tiếp xúc lâu dài với tiếng ồn do giao thông có thể ảnh hưởng đến chất lượng giấc ngủ và làm giảm sức khỏe tinh thần của cư dân đô thị.","audioKind":"ex2"}],"collocations":[{"en":"noise pollution","vi":"ô nhiễm tiếng ồn"},{"en":"background noise","vi":"tiếng ồn nền"},{"en":"make a noise","vi":"làm ồn; phát ra tiếng động"},{"en":"traffic noise","vi":"tiếng ồn giao thông"}],"wordFamily":["noisy (adj.)","noisily (adv.)","noiseless (adj.)"],"synonyms":["sound"],"antonyms":["silence"],"tipVi":"Khi chỉ chung chung thì noise không đếm được; chỉ một tiếng động cụ thể thì dùng a noise.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oil', 'en-a2-11', 'oil', '/ɔɪl/', 'A2', 'dầu mỏ; dầu thô; dầu; dầu ăn; dầu bôi trơn; tra dầu; bôi trơn', 'n.', 'oily (adj.), oiliness (n.)', NULL, 'Thường là danh từ không đếm được; có thể dùng oils khi chỉ các loại dầu khác nhau.', 'The truck carried oil from the well to the refinery.', NULL, 'Xe tải chở dầu thô từ mỏ dầu đến nhà máy lọc dầu.', '{"wordId":"oil","ukIpa":"/ɔɪl/","usIpa":"/ɔɪl/","cefr":"A2","topic":"environment","senses":[{"pos":"n.","en":"A thick underground liquid used to produce fuel and chemicals.","vi":"dầu mỏ; dầu thô"},{"pos":"n.","en":"A slippery liquid used for cooking, lubrication or other purposes.","vi":"dầu; dầu ăn; dầu bôi trơn"},{"pos":"v.","en":"To apply oil so that something moves smoothly.","vi":"tra dầu; bôi trơn"}],"examples":[{"en":"The truck carried oil from the well to the refinery.","vi":"Xe tải chở dầu thô từ mỏ dầu đến nhà máy lọc dầu.","audioKind":"ex"},{"en":"Reducing dependence on oil requires sustained investment in renewable energy and more efficient public transport.","vi":"Việc giảm sự phụ thuộc vào dầu mỏ đòi hỏi phải đầu tư liên tục vào năng lượng tái tạo và hệ thống giao thông công cộng hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"crude oil","vi":"dầu thô"},{"en":"oil prices","vi":"giá dầu"},{"en":"cooking oil","vi":"dầu ăn"},{"en":"oil a hinge","vi":"tra dầu vào bản lề"}],"wordFamily":["oily (adj.)","oiliness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; có thể dùng oils khi chỉ các loại dầu khác nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_environment', 'en-a2-11', 'environment', '/ɪnˈvaɪrənmənt/', 'A2', 'môi trường tự nhiên; môi trường sống; môi trường làm việc', 'n.', 'environmental (adj.), environmentally (adv.), environmentalist (n.)', 'Đồng nghĩa: surroundings', 'Khi chỉ chung môi trường tự nhiên thường dùng the environment.', 'We cycle to school to help protect the environment.', NULL, 'Chúng tôi đạp xe đến trường để góp phần bảo vệ môi trường.', '{"wordId":"environment","ukIpa":"/ɪnˈvaɪrənmənt/","usIpa":"/ɪnˈvaɪrənmənt/","cefr":"A2","topic":"environment","senses":[{"pos":"n.","en":"The natural world, including land, water, air, and living things.","vi":"môi trường tự nhiên"},{"pos":"n.","en":"The conditions and surroundings in which someone lives or works.","vi":"môi trường sống; môi trường làm việc"}],"examples":[{"en":"We cycle to school to help protect the environment.","vi":"Chúng tôi đạp xe đến trường để góp phần bảo vệ môi trường.","audioKind":"ex"},{"en":"A supportive learning environment can improve students'' confidence and encourage them to participate more actively.","vi":"Một môi trường học tập mang tính hỗ trợ có thể nâng cao sự tự tin của học sinh và khuyến khích các em tham gia tích cực hơn.","audioKind":"ex2"}],"collocations":[{"en":"protect the environment","vi":"bảo vệ môi trường"},{"en":"natural environment","vi":"môi trường tự nhiên"},{"en":"working environment","vi":"môi trường làm việc"},{"en":"learning environment","vi":"môi trường học tập"}],"wordFamily":["environmental (adj.)","environmentally (adv.)","environmentalist (n.)"],"synonyms":["surroundings"],"antonyms":[],"tipVi":"Khi chỉ chung môi trường tự nhiên thường dùng the environment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kill', 'en-a2-11', 'kill', '/kɪl/', 'A2', 'giết, làm chết; chấm dứt, hủy hoại, bóp nghẹt', 'v.', 'killer (n.), killing (n.)', 'Trái nghĩa: revive', 'kill nhấn mạnh việc gây ra cái chết cho đối tượng khác; die biểu thị sự tự chết đi và không đi kèm tân ngữ.', 'This soap helps kill germs on your hands.', NULL, 'Loại xà phòng này giúp tiêu diệt vi khuẩn trên tay bạn.', '{"wordId":"kill","ukIpa":"/kɪl/","usIpa":"/kɪl/","cefr":"A2","topic":"environment","senses":[{"pos":"v.","en":"To cause a person, animal, or other organism to die","vi":"giết, làm chết"},{"pos":"v.","en":"To cause something to stop or fail","vi":"chấm dứt, hủy hoại, bóp nghẹt"}],"examples":[{"en":"This soap helps kill germs on your hands.","vi":"Loại xà phòng này giúp tiêu diệt vi khuẩn trên tay bạn.","audioKind":"ex"},{"en":"Excessive use of pesticides can kill beneficial insects and disrupt the natural balance of agricultural ecosystems.","vi":"Việc lạm dụng thuốc trừ sâu có thể tiêu diệt các loài côn trùng có ích và phá vỡ sự cân bằng tự nhiên của các hệ sinh thái nông nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"kill germs","vi":"tiêu diệt vi khuẩn"},{"en":"kill time","vi":"giết thời gian"},{"en":"kill off","vi":"làm chết hẳn; tiêu diệt hoàn toàn"},{"en":"kill enthusiasm","vi":"đánh gục sự nhiệt tình"}],"wordFamily":["killer (n.)","killing (n.)"],"synonyms":[],"antonyms":["revive"],"tipVi":"kill nhấn mạnh việc gây ra cái chết cho đối tượng khác; die biểu thị sự tự chết đi và không đi kèm tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_11_1', 'en-a2-11', 'Cách dùng “rubbish” (n.) — rác thải; phế liệu', 'household rubbish  ·  rubbish bin  ·  collect rubbish', 'Thường là danh từ không đếm được; đây là từ thông dụng trong tiếng Anh-Anh, trong khi tiếng Anh-Mỹ thường dùng garbage hoặc trash.', 'Đồng nghĩa: garbage, trash', '[{"hanzi":"Please put your rubbish in the bin outside.","pinyin":"","meaning":"Làm ơn vứt rác của bạn vào thùng rác ở bên ngoài."},{"hanzi":"Reducing household rubbish requires both convenient recycling facilities and greater public awareness of unnecessary packaging.","pinyin":"","meaning":"Việc giảm thiểu rác thải sinh hoạt đòi hỏi cả cơ sở tái chế thuận tiện lẫn ý thức chung cao hơn của cộng đồng về vấn đề bao bì không cần thiết."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_11_2', 'en-a2-11', 'Cách dùng “kill” (v.) — giết, làm chết', 'kill germs  ·  kill time  ·  kill off', 'kill nhấn mạnh việc gây ra cái chết cho đối tượng khác; die biểu thị sự tự chết đi và không đi kèm tân ngữ.', 'Họ từ (Word Family): killer (n.), killing (n.) | Trái nghĩa: revive', '[{"hanzi":"This soap helps kill germs on your hands.","pinyin":"","meaning":"Loại xà phòng này giúp tiêu diệt vi khuẩn trên tay bạn."},{"hanzi":"Excessive use of pesticides can kill beneficial insects and disrupt the natural balance of agricultural ecosystems.","pinyin":"","meaning":"Việc lạm dụng thuốc trừ sâu có thể tiêu diệt các loài côn trùng có ích và phá vỡ sự cân bằng tự nhiên của các hệ sinh thái nông nghiệp."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_11_3', 'en-a2-11', 'Cách dùng “destroy” (v.) — phá hủy; tàn phá', 'destroy habitats  ·  destroy evidence  ·  destroy confidence', 'destroy có mức độ nghiêm trọng hơn damage, thường dùng để chỉ việc hủy hoại hoàn toàn không thể phục hồi.', 'Họ từ (Word Family): destruction (n.), destructive (adj.), destroyer (n.) | Đồng nghĩa: ruin, wreck · Trái nghĩa: create, preserve', '[{"hanzi":"A sudden storm destroyed the old shed behind our house.","pinyin":"","meaning":"Một cơn bão bất chợt đã tàn phá cái nhà kho cũ phía sau nhà chúng tôi."},{"hanzi":"Uncontrolled urban expansion can destroy natural habitats and threaten the survival of species that depend on them.","pinyin":"","meaning":"Sự bành trướng đô thị không được kiểm soát có thể phá hủy các sinh cảnh tự nhiên và đe dọa sự sống còn của các loài phụ thuộc vào chúng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_11_4', 'en-a2-11', 'Cách dùng “garbage” (n.) — rác thải; vật bỏ đi', 'take out the garbage  ·  garbage collection  ·  a garbage bag', 'Là danh từ không đếm được; thường dùng trong tiếng Anh-Mỹ, trong khi tiếng Anh-Anh hay dùng rubbish.', 'Đồng nghĩa: rubbish, trash', '[{"hanzi":"Please take the garbage out before it starts smelling.","pinyin":"","meaning":"Làm ơn mang rác đi đổ trước khi nó bắt đầu bốc mùi."},{"hanzi":"Cities can reduce the amount of garbage sent to landfill by improving recycling facilities and public awareness.","pinyin":"","meaning":"Các thành phố có thể giảm lượng rác thải đưa tới bãi chôn lấp bằng cách cải thiện các cơ sở tái chế và nâng cao nhận thức cộng đồng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_11_1', 'en-a2-11', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_11_1_1', 'ten_a2_11_1', 'plastic', 'This lunch box is made of strong recycled plastic.', 'This lunch box is made of strong recycled plastic.', '/ˈplæstɪk/', 'Hộp đựng cơm này được làm từ nhựa tái chế chắc chắn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
