INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_11_1_8', 'ten_a2_11_1', 'garbage', 'Please take the garbage out before it starts smelling.', 'Please take the garbage out before it starts smelling.', '/ˈɡɑːrbɪdʒ/', 'Làm ơn mang rác đi đổ trước khi nó bắt đầu bốc mùi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_11_1_1', 'en-a2-11', 'ten_a2_11_1', 'listening', 'listening', 'This lunch box is made of strong recycled plastic.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đạp xe đến trường để góp phần bảo vệ môi trường.","Sau một giấc ngủ ngắn, tôi đã có năng lượng để nấu ăn.","Hộp đựng cơm này được làm từ nhựa tái chế chắc chắn.","Chúng tôi ngắm nhìn mặt trời mọc trên biển."]'::jsonb, 2, 'This lunch box is made of strong recycled plastic. → Hộp đựng cơm này được làm từ nhựa tái chế chắc chắn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_11_1_2', 'en-a2-11', 'ten_a2_11_1', 'listening', 'listening', 'Wear thick gloves to protect your hands from thorns.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một cơn bão bất chợt đã tàn phá cái nhà kho cũ phía sau nhà chúng tôi.","Hãy đeo găng tay dày để bảo vệ đôi tay khỏi bị gai đâm.","Hộp đựng cơm này được làm từ nhựa tái chế chắc chắn.","Đừng để vòi nước chảy liên tục gây lãng phí nước."]'::jsonb, 1, 'Wear thick gloves to protect your hands from thorns. → Hãy đeo găng tay dày để bảo vệ đôi tay khỏi bị gai đâm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_11_1_3', 'en-a2-11', 'ten_a2_11_1', 'listening', 'listening', 'After a short nap, I had energy to cook.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đạp xe đến trường để góp phần bảo vệ môi trường.","Xe tải chở dầu thô từ mỏ dầu đến nhà máy lọc dầu.","Hộp đựng cơm này được làm từ nhựa tái chế chắc chắn.","Sau một giấc ngủ ngắn, tôi đã có năng lượng để nấu ăn."]'::jsonb, 3, 'After a short nap, I had energy to cook. → Sau một giấc ngủ ngắn, tôi đã có năng lượng để nấu ăn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_11_2', 'en-a2-11', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_11_2_1', 'ten_a2_11_2', 'plastic', 'Reducing single-use plastic packaging could protect marine ecosystems and lower the costs of managing household waste.', 'Reducing single-use plastic packaging could protect marine ecosystems and lower the costs of managing household waste.', '/ˈplæstɪk/', 'Việc giảm thiểu bao bì nhựa dùng một lần có thể bảo vệ các hệ sinh thái biển và hạ thấp chi phí xử lý rác thải sinh hoạt.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_11_2_2', 'ten_a2_11_2', 'protect', 'Governments should protect endangered species by preserving natural habitats and restricting activities that threaten their survival.', 'Governments should protect endangered species by preserving natural habitats and restricting activities that threaten their survival.', '/prəˈtekt/', 'Chính phủ nên bảo vệ các loài có nguy cơ tuyệt chủng bằng cách gìn giữ môi trường sống tự nhiên và hạn chế các hoạt động đe dọa sự sinh tồn của chúng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_11_2_3', 'ten_a2_11_2', 'energy', 'Investing in renewable energy can reduce dependence on fossil fuels while creating new employment opportunities.', 'Investing in renewable energy can reduce dependence on fossil fuels while creating new employment opportunities.', '/ˈenɚdʒi/', 'Đầu tư vào năng lượng tái tạo có thể làm giảm sự phụ thuộc vào nhiên liệu hóa thạch đồng thời tạo ra các cơ hội việc làm mới.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_11_2_4', 'ten_a2_11_2', 'waste', 'Reducing household waste requires both convenient recycling facilities and greater public awareness of responsible consumption.', 'Reducing household waste requires both convenient recycling facilities and greater public awareness of responsible consumption.', '/weɪst/', 'Việc giảm thiểu rác thải sinh hoạt đòi hỏi cả cơ sở tái chế thuận tiện lẫn ý thức tiêu dùng có trách nhiệm cao hơn từ phía cộng đồng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_11_2_5', 'ten_a2_11_2', 'rubbish', 'Reducing household rubbish requires both convenient recycling facilities and greater public awareness of unnecessary packaging.', 'Reducing household rubbish requires both convenient recycling facilities and greater public awareness of unnecessary packaging.', '/ˈrʌbɪʃ/', 'Việc giảm thiểu rác thải sinh hoạt đòi hỏi cả cơ sở tái chế thuận tiện lẫn ý thức chung cao hơn của cộng đồng về vấn đề bao bì không cần thiết.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_11_2_6', 'ten_a2_11_2', 'destroy', 'Uncontrolled urban expansion can destroy natural habitats and threaten the survival of species that depend on them.', 'Uncontrolled urban expansion can destroy natural habitats and threaten the survival of species that depend on them.', '/dɪˈstrɔɪ/', 'Sự bành trướng đô thị không được kiểm soát có thể phá hủy các sinh cảnh tự nhiên và đe dọa sự sống còn của các loài phụ thuộc vào chúng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_11_2_1', 'en-a2-11', 'ten_a2_11_2', 'listening', 'listening', 'Reducing single-use plastic packaging could protect marine ecosystems and lower the costs of managing household waste.', NULL, 'Trong câu vừa nghe, từ “plastic” mang nghĩa nào sau đây?', '["vừa vặn; thích hợp; vừa","hàng tuần, diễn ra mỗi tuần","điện thoại thông minh","chất dẻo; nhựa"]'::jsonb, 3, '“plastic” (/ˈplæstɪk/): chất dẻo; nhựa. Câu đầy đủ: Reducing single-use plastic packaging could protect marine ecosystems and lower the costs of managing household waste.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_11_2_2', 'en-a2-11', 'ten_a2_11_2', 'listening', 'listening', 'Governments should protect endangered species by preserving natural habitats and restricting activities that threaten their survival.', NULL, 'Trong câu vừa nghe, từ “protect” mang nghĩa nào sau đây?', '["bảo vệ, che chở khỏi nguy hiểm hoặc tổn hại","danh từ","bóng bàn","đồng xu một xu (Anh); đồng xu một phần trăm bảng Anh"]'::jsonb, 0, '“protect” (/prəˈtekt/): bảo vệ, che chở khỏi nguy hiểm hoặc tổn hại. Câu đầy đủ: Governments should protect endangered species by preserving natural habitats and restricting activities that threaten their survival.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
