INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_11_2', 'en-a2-11', NULL, 'comprehensive_test', 'listening', 'Wear thick gloves to protect your hands from thorns.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sau một giấc ngủ ngắn, tôi đã có năng lượng để nấu ăn.","Tiếng ồn bên ngoài đã đánh thức tôi dậy trước khi đồng hồ báo thức kêu.","Chúng tôi đạp xe đến trường để góp phần bảo vệ môi trường.","Hãy đeo găng tay dày để bảo vệ đôi tay khỏi bị gai đâm."]'::jsonb, 3, 'Wear thick gloves to protect your hands from thorns. → Hãy đeo găng tay dày để bảo vệ đôi tay khỏi bị gai đâm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_11_3', 'en-a2-11', NULL, 'comprehensive_test', 'listening', 'energy', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quần áo; trang phục","năng lượng; sinh lực","ý kiến; quan điểm; đánh giá","thứ mười"]'::jsonb, 1, 'energy (/ˈenɚdʒi/) → năng lượng; sinh lực; nguồn điện', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_11_4', 'en-a2-11', NULL, 'comprehensive_test', 'listening', 'Don''t waste water by leaving the tap running.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Làm ơn mang rác đi đổ trước khi nó bắt đầu bốc mùi.","Xe tải chở dầu thô từ mỏ dầu đến nhà máy lọc dầu.","Chúng tôi đạp xe đến trường để góp phần bảo vệ môi trường.","Đừng để vòi nước chảy liên tục gây lãng phí nước."]'::jsonb, 3, 'Don''t waste water by leaving the tap running. → Đừng để vòi nước chảy liên tục gây lãng phí nước.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
