INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_11_6', 'en-a2-11', NULL, 'comprehensive_test', 'listening', 'A sudden storm destroyed the old shed behind our house.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi ngắm nhìn mặt trời mọc trên biển.","Làm ơn mang rác đi đổ trước khi nó bắt đầu bốc mùi.","Loại xà phòng này giúp tiêu diệt vi khuẩn trên tay bạn.","Một cơn bão bất chợt đã tàn phá cái nhà kho cũ phía sau nhà chúng tôi."]'::jsonb, 3, 'A sudden storm destroyed the old shed behind our house. → Một cơn bão bất chợt đã tàn phá cái nhà kho cũ phía sau nhà chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
