INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_11_8', 'en-a2-11', NULL, 'comprehensive_test', 'listening', 'Please take the garbage out before it starts smelling.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hộp đựng cơm này được làm từ nhựa tái chế chắc chắn.","Một cơn bão bất chợt đã tàn phá cái nhà kho cũ phía sau nhà chúng tôi.","Làm ơn mang rác đi đổ trước khi nó bắt đầu bốc mùi.","Làm ơn vứt rác của bạn vào thùng rác ở bên ngoài."]'::jsonb, 2, 'Please take the garbage out before it starts smelling. → Làm ơn mang rác đi đổ trước khi nó bắt đầu bốc mùi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
