INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_11_18', 'en-a2-11', NULL, 'comprehensive_test', 'reading', NULL, 'Reducing single-use plastic packaging could protect marine ecosystems and lower the costs of managing household waste.', 'Dựa vào câu trên, từ “plastic” có nghĩa phù hợp nhất là gì?', '["thư tín; bưu kiện; hệ thống bưu chính","chất dẻo; nhựa","bằng cấp; văn bằng","mượn; vay"]'::jsonb, 1, 'plastic: chất dẻo; nhựa; bằng nhựa; dẻo; dễ uốn nắn. Dịch cả câu: Việc giảm thiểu bao bì nhựa dùng một lần có thể bảo vệ các hệ sinh thái biển và hạ thấp chi phí xử lý rác thải sinh hoạt.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_11_19', 'en-a2-11', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should protect endangered species by preserving natural habitats and restricting activities that threaten their survival.', 'Dựa vào câu trên, từ “protect” có nghĩa phù hợp nhất là gì?', '["kỷ niệm; ăn mừng","mỗi (trong hai); bất kỳ (trong hai)","bảo vệ, che chở khỏi nguy hiểm hoặc tổn hại","mã bưu chính (tại Mỹ)"]'::jsonb, 2, 'protect: bảo vệ, che chở khỏi nguy hiểm hoặc tổn hại. Dịch cả câu: Chính phủ nên bảo vệ các loài có nguy cơ tuyệt chủng bằng cách gìn giữ môi trường sống tự nhiên và hạn chế các hoạt động đe dọa sự sinh tồn của chúng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_11_20', 'en-a2-11', NULL, 'comprehensive_test', 'reading', NULL, 'Investing in renewable energy can reduce dependence on fossil fuels while creating new employment opportunities.', 'Dựa vào câu trên, từ “energy” có nghĩa phù hợp nhất là gì?', '["dạ dày; bụng","da (người hoặc động vật)","Malaysia (một quốc gia Đông Nam Á nằm ở bán đảo Mã Lai và đảo Borneo)","năng lượng; sinh lực"]'::jsonb, 3, 'energy: năng lượng; sinh lực; nguồn điện. Dịch cả câu: Đầu tư vào năng lượng tái tạo có thể làm giảm sự phụ thuộc vào nhiên liệu hóa thạch đồng thời tạo ra các cơ hội việc làm mới.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_11_21', 'en-a2-11', NULL, 'comprehensive_test', 'reading', NULL, 'Reducing household waste requires both convenient recycling facilities and greater public awareness of responsible consumption.', 'Dựa vào câu trên, từ “waste” có nghĩa phù hợp nhất là gì?', '["chủ đề; đề tài","môn judo; võ judo","lãng phí","gam"]'::jsonb, 2, 'waste: lãng phí; chất thải; rác thải; sự lãng phí. Dịch cả câu: Việc giảm thiểu rác thải sinh hoạt đòi hỏi cả cơ sở tái chế thuận tiện lẫn ý thức tiêu dùng có trách nhiệm cao hơn từ phía cộng đồng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_11_22', 'en-a2-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dầu mỏ; dầu thô”', '["forest","pub","oil","doll"]'::jsonb, 2, 'dầu mỏ; dầu thô → oil (/ɔɪl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_11_23', 'en-a2-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “môi trường tự nhiên”', '["environment","worse","recently","against"]'::jsonb, 0, 'môi trường tự nhiên → environment (/ɪnˈvaɪrənmənt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_11_24', 'en-a2-11', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “giết, làm chết”', '["kill","mix","pan","whose"]'::jsonb, 0, 'giết, làm chết → kill (/kɪl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-12', 'en', 'Bài 12: Sức khỏe & Cơ thể (1) - CEFR A2', 'CEFR A2', 'A2 · Sức khỏe', '25 từ vựng Tiếng Anh CEFR A2 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2012, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diet', 'en-a2-12', 'diet', '/ˈdaɪət/', 'A2', 'chế độ ăn uống; khẩu phần ăn; chế độ ăn kiêng; ăn kiêng', 'n.', 'dietary (adj.), dieter (n.)', NULL, 'diet không nhất thiết chỉ việc ăn kiêng, mà còn chỉ chế độ ăn uống hàng ngày.', 'My usual diet includes plenty of rice and vegetables.', NULL, 'Chế độ ăn thông thường của tôi bao gồm nhiều cơm và rau xanh.', '{"wordId":"diet","ukIpa":"/ˈdaɪət/","usIpa":"/ˈdaɪət/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"The food and drink someone regularly consumes.","vi":"chế độ ăn uống; khẩu phần ăn"},{"pos":"n.","en":"A planned way of eating for health or weight control.","vi":"chế độ ăn kiêng"},{"pos":"v.","en":"To control what you eat, usually to lose weight.","vi":"ăn kiêng"}],"examples":[{"en":"My usual diet includes plenty of rice and vegetables.","vi":"Chế độ ăn thông thường của tôi bao gồm nhiều cơm và rau xanh.","audioKind":"ex"},{"en":"A balanced diet can improve concentration and help students maintain their energy throughout the school day.","vi":"Một chế độ ăn uống cân bằng có thể cải thiện khả năng tập trung và giúp học sinh duy trì năng lượng suốt ngày học ở trường.","audioKind":"ex2"}],"collocations":[{"en":"a balanced diet","vi":"chế độ ăn uống cân bằng"},{"en":"a diet rich in fibre","vi":"chế độ ăn giàu chất xơ"},{"en":"go on a diet","vi":"bắt đầu ăn kiêng"}],"wordFamily":["dietary (adj.)","dieter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"diet không nhất thiết chỉ việc ăn kiêng, mà còn chỉ chế độ ăn uống hàng ngày.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_broccoli', 'en-a2-12', 'broccoli', '/ˈbrɑːkəli/', 'A2', 'cải bông xanh, súp lơ xanh', 'n.', NULL, NULL, 'Thường là danh từ không đếm được; các nhánh nhỏ của súp lơ có thể gọi là broccoli florets.', 'We steamed the broccoli until it turned bright green.', NULL, 'Chúng tôi đem hấp súp lơ xanh cho đến khi chuyển sang màu xanh ngắt.', '{"wordId":"broccoli","ukIpa":"/ˈbrɒkəli/","usIpa":"/ˈbrɑːkəli/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"A green vegetable with thick stems and tightly clustered flower buds.","vi":"cải bông xanh, súp lơ xanh"}],"examples":[{"en":"We steamed the broccoli until it turned bright green.","vi":"Chúng tôi đem hấp súp lơ xanh cho đến khi chuyển sang màu xanh ngắt.","audioKind":"ex"},{"en":"Schools can encourage healthier eating by serving vegetables such as broccoli alongside familiar dishes.","vi":"Nhà trường có thể khuyến khích thói quen ăn uống lành mạnh hơn bằng cách phục vụ các loại rau củ như súp lơ xanh bên cạnh các món quen thuộc.","audioKind":"ex2"}],"collocations":[{"en":"broccoli florets","vi":"nhánh súp lơ xanh"},{"en":"steamed broccoli","vi":"súp lơ xanh hấp"},{"en":"a head of broccoli","vi":"một cây súp lơ xanh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; các nhánh nhỏ của súp lơ có thể gọi là broccoli florets.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ankle', 'en-a2-12', 'ankle', '/ˈæŋkəl/', 'A2', 'khớp mắt cá chân', 'n.', NULL, NULL, 'ankle chỉ phần khớp nối giữa chân và bàn chân, không phải gót chân heel.', 'She twisted her ankle while walking down the steps.', NULL, 'Cô ấy bị trật mắt cá chân khi đang đi xuống bậc thềm.', '{"wordId":"ankle","ukIpa":"/ˈæŋkəl/","usIpa":"/ˈæŋkəl/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"the joint connecting your foot to your leg","vi":"khớp mắt cá chân"}],"examples":[{"en":"She twisted her ankle while walking down the steps.","vi":"Cô ấy bị trật mắt cá chân khi đang đi xuống bậc thềm.","audioKind":"ex"},{"en":"Appropriate footwear can reduce the risk of ankle injuries during physical exercise and outdoor activities.","vi":"Giày dép phù hợp có thể giảm nguy cơ chấn thương mắt cá chân trong các hoạt động thể thao và hoạt động ngoài trời.","audioKind":"ex2"}],"collocations":[{"en":"sprain an ankle","vi":"trật mắt cá chân"},{"en":"a swollen ankle","vi":"mắt cá chân sưng tấy"},{"en":"ankle support","vi":"băng bảo vệ mắt cá chân"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"ankle chỉ phần khớp nối giữa chân và bàn chân, không phải gót chân heel.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_snack', 'en-a2-12', 'snack', '/snæk/', 'A2', 'bữa ăn nhẹ; đồ ăn vặt; ăn nhẹ; ăn vặt', 'n.', NULL, NULL, 'Động từ thường dùng snack on sth, chỉ việc ăn món gì đó làm đồ ăn vặt.', 'I packed an apple and some nuts for a snack.', NULL, 'Tôi mang theo một quả táo và ít hạt để ăn nhẹ.', '{"wordId":"snack","ukIpa":"/snæk/","usIpa":"/snæk/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"A small amount of food eaten between main meals.","vi":"bữa ăn nhẹ; đồ ăn vặt"},{"pos":"v.","en":"To eat small amounts of food between main meals.","vi":"ăn nhẹ; ăn vặt"}],"examples":[{"en":"I packed an apple and some nuts for a snack.","vi":"Tôi mang theo một quả táo và ít hạt để ăn nhẹ.","audioKind":"ex"},{"en":"Schools can encourage healthier eating habits by offering nutritious snacks instead of foods high in sugar.","vi":"Các trường học có thể khuyến khích thói quen ăn uống lành mạnh hơn bằng cách cung cấp các món ăn nhẹ giàu dinh dưỡng thay cho thực phẩm chứa nhiều đường.","audioKind":"ex2"}],"collocations":[{"en":"a healthy snack","vi":"đồ ăn nhẹ lành mạnh"},{"en":"a light snack","vi":"bữa ăn nhẹ"},{"en":"snack on nuts","vi":"ăn hạt làm đồ ăn vặt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ thường dùng snack on sth, chỉ việc ăn món gì đó làm đồ ăn vặt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_weak', 'en-a2-12', 'weak', '/wiːk/', 'A2', 'yếu ớt; suy nhược; yếu kém; thiếu sức thuyết phục; loãng; nhạt; yếu', 'adj.', 'weakness (n.), weaken (v.), weakly (adv.)', 'Đồng nghĩa: feeble · Trái nghĩa: strong', 'Từ weak phát âm đồng âm với week; từ weakness có thể chỉ điểm yếu hoặc sự suy yếu.', 'I felt too weak to carry the shopping upstairs.', NULL, 'Tôi cảm thấy quá yếu để có thể xách đồ mua sắm lên lầu.', '{"wordId":"weak","ukIpa":"/wiːk/","usIpa":"/wiːk/","cefr":"A2","topic":"health","senses":[{"pos":"adj.","en":"lacking physical strength or energy","vi":"yếu ớt; suy nhược"},{"pos":"adj.","en":"not effective, convincing, or well supported","vi":"yếu kém; thiếu sức thuyết phục"},{"pos":"adj.","en":"having little intensity, flavour, or power","vi":"loãng; nhạt; yếu"}],"examples":[{"en":"I felt too weak to carry the shopping upstairs.","vi":"Tôi cảm thấy quá yếu để có thể xách đồ mua sắm lên lầu.","audioKind":"ex"},{"en":"Policies based on weak evidence may fail to address the underlying causes of unemployment.","vi":"Các chính sách dựa trên bằng chứng yếu kém có thể không giải quyết được nguyên nhân gốc rễ của tình trạng thất nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"feel weak","vi":"cảm thấy mệt yếu"},{"en":"weak evidence","vi":"bằng chứng yếu"},{"en":"weak signal","vi":"tín hiệu yếu"},{"en":"weak tea","vi":"nước trà nhạt"}],"wordFamily":["weakness (n.)","weaken (v.)","weakly (adv.)"],"synonyms":["feeble"],"antonyms":["strong"],"tipVi":"Từ weak phát âm đồng âm với week; từ weakness có thể chỉ điểm yếu hoặc sự suy yếu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cigarette', 'en-a2-12', 'cigarette', '/ˈsɪɡəret/', 'A2', 'thuốc lá điếu', 'n.', NULL, NULL, 'Danh từ đếm được; một bao thuốc lá có thể nói là a packet of cigarettes.', 'He refused a cigarette and went for a walk instead.', NULL, 'Anh ấy từ chối điếu thuốc lá và đi dạo thay vào đó.', '{"wordId":"cigarette","ukIpa":"/ˌsɪɡəˈret/","usIpa":"/ˈsɪɡəret/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"A thin paper tube filled with tobacco for smoking.","vi":"thuốc lá điếu"}],"examples":[{"en":"He refused a cigarette and went for a walk instead.","vi":"Anh ấy từ chối điếu thuốc lá và đi dạo thay vào đó.","audioKind":"ex"},{"en":"Higher cigarette taxes may discourage smoking, but accessible support services are also essential for people trying to quit.","vi":"Tăng thuế thuốc lá có thể giúp hạn chế việc hút thuốc, nhưng các dịch vụ hỗ trợ dễ tiếp cận cũng vô cùng thiết yếu cho những người đang cố gắng cai thuốc.","audioKind":"ex2"}],"collocations":[{"en":"cigarette smoke","vi":"khói thuốc lá"},{"en":"a packet of cigarettes","vi":"một bao thuốc lá"},{"en":"cigarette taxes","vi":"thuế thuốc lá"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ đếm được; một bao thuốc lá có thể nói là a packet of cigarettes.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nurse', 'en-a2-12', 'nurse', '/nɝːs/', 'A2', 'y tá; điều dưỡng viên; chăm sóc; điều dưỡng; săn sóc (người bệnh)', 'n.', 'nursing (n.)', NULL, 'Khi dùng làm động từ, có thể kết hợp trực tiếp với tân ngữ chỉ người: nurse a patient.', 'The nurse gently wrapped a bandage around my wrist.', NULL, 'Y tá nhẹ nhàng quấn một lớp băng quanh cổ tay tôi.', '{"wordId":"nurse","ukIpa":"/nɜːs/","usIpa":"/nɝːs/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"A trained person who cares for ill or injured people.","vi":"y tá; điều dưỡng viên"},{"pos":"v.","en":"To care for someone who is ill or injured.","vi":"chăm sóc; điều dưỡng; săn sóc (người bệnh)"}],"examples":[{"en":"The nurse gently wrapped a bandage around my wrist.","vi":"Y tá nhẹ nhàng quấn một lớp băng quanh cổ tay tôi.","audioKind":"ex"},{"en":"Employing more community nurses could improve access to healthcare for older people living in rural areas.","vi":"Việc thuê thêm các y tá cộng đồng có thể cải thiện khả năng tiếp cận dịch vụ chăm sóc sức khỏe cho người cao tuổi sống ở vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"registered nurse","vi":"y tá đã đăng ký hành nghề"},{"en":"community nurse","vi":"y tá cộng đồng"},{"en":"nurse someone back to health","vi":"chăm sóc ai đó cho đến khi bình phục"}],"wordFamily":["nursing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng làm động từ, có thể kết hợp trực tiếp với tân ngữ chỉ người: nurse a patient.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_active', 'en-a2-12', 'active', '/ˈæk.tɪv/', 'A2', 'năng động; tích cực tham gia; đang hoạt động; có hiệu lực; chủ động', 'adj.', 'activity (n.), actively (adv.), inactive (adj.), activate (v.)', 'Đồng nghĩa: energetic, lively · Trái nghĩa: inactive, passive', 'active chỉ sự tích cực hoạt động hoặc tham gia; không đồng nghĩa với từ chỉ sự lạc quan positive.', 'My grandfather stays active by swimming every morning.', NULL, 'Ông tôi duy trì sự năng động bằng cách bơi lội mỗi sáng.', '{"wordId":"active","ukIpa":"/ˈæk.tɪv/","usIpa":"/ˈæk.tɪv/","cefr":"A2","topic":"health","senses":[{"pos":"adj.","en":"regularly moving, doing things, or taking part","vi":"năng động; tích cực tham gia"},{"pos":"adj.","en":"currently working or producing an effect","vi":"đang hoạt động; có hiệu lực"},{"pos":"adj.","en":"describing a verb whose subject performs the action","vi":"chủ động"}],"examples":[{"en":"My grandfather stays active by swimming every morning.","vi":"Ông tôi duy trì sự năng động bằng cách bơi lội mỗi sáng.","audioKind":"ex"},{"en":"Schools should encourage an active lifestyle to improve students'' physical health and overall wellbeing.","vi":"Các trường học nên khuyến khích lối sống năng động để cải thiện sức khỏe thể chất và tinh thần nói chung của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"stay active","vi":"dữ năng động"},{"en":"an active lifestyle","vi":"lối sống năng động"},{"en":"play an active role","vi":"đóng vai trò tích cực"},{"en":"active ingredient","vi":"thành phần hoạt tính"}],"wordFamily":["activity (n.)","actively (adv.)","inactive (adj.)","activate (v.)"],"synonyms":["energetic","lively"],"antonyms":["inactive","passive"],"tipVi":"active chỉ sự tích cực hoạt động hoặc tham gia; không đồng nghĩa với từ chỉ sự lạc quan positive.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eating', 'en-a2-12', 'eating', '/ˈiːtɪŋ/', 'A2', 'việc ăn uống; chế độ ăn; đang ăn; việc đưa thức ăn vào miệng', 'n.', 'eat (v.), eater (n.), edible (adj.)', NULL, 'eating có thể dùng làm danh động từ; cụm eat out có nghĩa là đi ăn hàng.', 'Healthy eating starts with small changes to your meals.', NULL, 'Ăn uống lành mạnh bắt đầu từ những thay đổi nhỏ trong bữa ăn hàng ngày.', '{"wordId":"eating","ukIpa":"/ˈiːtɪŋ/","usIpa":"/ˈiːtɪŋ/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"the activity of taking food into your body","vi":"việc ăn uống; chế độ ăn"},{"pos":"v.","en":"taking food into your mouth and swallowing it","vi":"đang ăn; việc đưa thức ăn vào miệng"}],"examples":[{"en":"Healthy eating starts with small changes to your meals.","vi":"Ăn uống lành mạnh bắt đầu từ những thay đổi nhỏ trong bữa ăn hàng ngày.","audioKind":"ex"},{"en":"Schools can encourage healthy eating by providing balanced lunches and teaching children how to prepare simple meals.","vi":"Các trường học có thể khuyến khích thói quen ăn uống lành mạnh bằng cách cung cấp bữa trưa cân bằng dinh dưỡng và dạy trẻ cách chuẩn bị những bữa ăn đơn giản.","audioKind":"ex2"}],"collocations":[{"en":"healthy eating","vi":"ăn uống lành mạnh"},{"en":"eating habits","vi":"thói quen ăn uống"},{"en":"eating out","vi":"ăn hàng; ăn ngoài"}],"wordFamily":["eat (v.)","eater (n.)","edible (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"eating có thể dùng làm danh động từ; cụm eat out có nghĩa là đi ăn hàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_asleep', 'en-a2-12', 'asleep', '/əˈsliːp/', 'A2', 'đang ngủ; ngủ say', 'adj.', 'sleep (v.), sleep (n.), sleepy (adj.), sleepless (adj.)', 'Đồng nghĩa: sleeping · Trái nghĩa: awake', 'asleep thường làm vị ngữ; cụm "em bé đang ngủ" dùng a sleeping baby.', 'The baby was asleep before we reached home.', NULL, 'Em bé đã ngủ thiếp đi trước khi chúng tôi về đến nhà.', '{"wordId":"asleep","ukIpa":"/əˈsliːp/","usIpa":"/əˈsliːp/","cefr":"A2","topic":"health","senses":[{"pos":"adj.","en":"Sleeping rather than awake.","vi":"đang ngủ; ngủ say"}],"examples":[{"en":"The baby was asleep before we reached home.","vi":"Em bé đã ngủ thiếp đi trước khi chúng tôi về đến nhà.","audioKind":"ex"},{"en":"People who use electronic devices late at night may find it harder to fall asleep.","vi":"Những người sử dụng thiết bị điện tử vào đêm muộn có thể thấy khó đi vào giấc ngủ hơn.","audioKind":"ex2"}],"collocations":[{"en":"fall asleep","vi":"chìm vào giấc ngủ"},{"en":"fast asleep","vi":"ngủ say như chết"},{"en":"stay asleep","vi":"duy trì giấc ngủ"}],"wordFamily":["sleep (v.)","sleep (n.)","sleepy (adj.)","sleepless (adj.)"],"synonyms":["sleeping"],"antonyms":["awake"],"tipVi":"asleep thường làm vị ngữ; cụm \"em bé đang ngủ\" dùng a sleeping baby.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pain', 'en-a2-12', 'pain', '/peɪn/', 'A2', 'sự đau đớn; cơn đau; nỗi đau buồn; sự đau khổ tinh thần; làm đau đớn; gây đau khổ', 'n.', 'painful (adj.), painless (adj.), painfully (adv.)', 'Đồng nghĩa: ache, suffering', 'Nghĩa chỉ sự đau đớn chung thường không đếm được; có thể dùng a pain khi chỉ một cơn đau cụ thể.', 'I felt a sharp pain in my left ankle.', NULL, 'Tôi cảm thấy một cơn đau nhói ở mắt cá chân trái.', '{"wordId":"pain","ukIpa":"/peɪn/","usIpa":"/peɪn/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"an unpleasant physical feeling caused by injury or illness","vi":"sự đau đớn; cơn đau"},{"pos":"n.","en":"strong emotional suffering caused by loss or distress","vi":"nỗi đau buồn; sự đau khổ tinh thần"},{"pos":"v.","en":"to cause someone emotional suffering","vi":"làm đau đớn; gây đau khổ"}],"examples":[{"en":"I felt a sharp pain in my left ankle.","vi":"Tôi cảm thấy một cơn đau nhói ở mắt cá chân trái.","audioKind":"ex"},{"en":"Regular exercise may reduce back pain among office workers who remain seated for long periods.","vi":"Tập thể dục đều đặn có thể làm giảm cơn đau lưng cho những nhân viên văn phòng phải ngồi làm việc trong thời gian dài.","audioKind":"ex2"}],"collocations":[{"en":"sharp pain","vi":"cơn đau nhói"},{"en":"chronic pain","vi":"cơn đau mãn tính"},{"en":"relieve pain","vi":"giảm đau"},{"en":"emotional pain","vi":"nỗi đau tinh thần"}],"wordFamily":["painful (adj.)","painless (adj.)","painfully (adv.)"],"synonyms":["ache","suffering"],"antonyms":[],"tipVi":"Nghĩa chỉ sự đau đớn chung thường không đếm được; có thể dùng a pain khi chỉ một cơn đau cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disease', 'en-a2-12', 'disease', '/dɪˈziːz/', 'A2', 'bệnh tật', 'n.', 'diseased (adj.)', 'Đồng nghĩa: illness · Trái nghĩa: health', 'Trọng âm rơi vào âm tiết thứ hai; khi chỉ bệnh nói chung có thể dùng không cần mạo từ.', 'The vet checked our rabbit for signs of disease.', NULL, 'Bác sĩ thú y đã kiểm tra chú thỏ của chúng tôi để tìm dấu hiệu bệnh tật.', '{"wordId":"disease","ukIpa":"/dɪˈziːz/","usIpa":"/dɪˈziːz/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"An illness affecting humans, animals or plants","vi":"bệnh tật"}],"examples":[{"en":"The vet checked our rabbit for signs of disease.","vi":"Bác sĩ thú y đã kiểm tra chú thỏ của chúng tôi để tìm dấu hiệu bệnh tật.","audioKind":"ex"},{"en":"Access to clean drinking water can significantly reduce the spread of infectious diseases in vulnerable communities.","vi":"Việc tiếp cận nguồn nước uống sạch có thể làm giảm đáng kể sự lây lan của các bệnh truyền nhiễm ở các cộng đồng dễ bị tổn thương.","audioKind":"ex2"}],"collocations":[{"en":"heart disease","vi":"bệnh tim"},{"en":"infectious diseases","vi":"bệnh truyền nhiễm"},{"en":"prevent disease","vi":"phòng ngừa bệnh tật"},{"en":"the spread of disease","vi":"sự lây lan của bệnh dịch"}],"wordFamily":["diseased (adj.)"],"synonyms":["illness"],"antonyms":["health"],"tipVi":"Trọng âm rơi vào âm tiết thứ hai; khi chỉ bệnh nói chung có thể dùng không cần mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_death', 'en-a2-12', 'death', '/deθ/', 'A2', 'cái chết; sự qua đời', 'n.', 'die (v.), dead (adj.), deadly (adj.)', 'Trái nghĩa: life', 'die là động từ, dead là tính từ, death là danh từ.', 'The old dog''s death left the family deeply sad.', NULL, 'Sự ra đi của chú chó già khiến gia đình vô cùng đau buồn.', '{"wordId":"death","ukIpa":"/deθ/","usIpa":"/deθ/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"the end of a person''s or animal''s life","vi":"cái chết; sự qua đời"}],"examples":[{"en":"The old dog''s death left the family deeply sad.","vi":"Sự ra đi của chú chó già khiến gia đình vô cùng đau buồn.","audioKind":"ex"},{"en":"Improved access to clean drinking water has reduced deaths from preventable diseases in many communities.","vi":"Việc tiếp cận nguồn nước uống sạch tốt hơn đã làm giảm số ca tử vong do các căn bệnh có thể phòng ngừa ở nhiều cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"cause of death","vi":"nguyên nhân cái chết"},{"en":"premature death","vi":"cái chết yểu"},{"en":"prevent deaths","vi":"ngăn chặn tử vong"},{"en":"death rate","vi":"tỷ lệ tử vong"}],"wordFamily":["die (v.)","dead (adj.)","deadly (adj.)"],"synonyms":[],"antonyms":["life"],"tipVi":"die là động từ, dead là tính từ, death là danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fat', 'en-a2-12', 'fat', '/fæt/', 'A2', 'chất béo; mỡ; béo; mập; nhiều mỡ', 'n.', 'fatty (adj.), fatten (v.)', NULL, 'Dùng từ fat để miêu tả người có thể gây khó chịu hoặc khiếm nhã; khi nói về sức khỏe, nên dùng từ overweight thì lịch sự hơn.', 'Let the soup cool, then remove the fat.', NULL, 'Hãy để súp nguội bớt, sau đó hớt bỏ lớp mỡ đi.', '{"wordId":"fat","ukIpa":"/fæt/","usIpa":"/fæt/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"a substance stored in bodies or used in cooking","vi":"chất béo; mỡ"},{"pos":"adj.","en":"having a large amount of body fat","vi":"béo; mập; nhiều mỡ"}],"examples":[{"en":"Let the soup cool, then remove the fat.","vi":"Hãy để súp nguội bớt, sau đó hớt bỏ lớp mỡ đi.","audioKind":"ex"},{"en":"Although the body needs some fat, excessive consumption can increase the risk of certain health problems.","vi":"Mặc dù cơ thể cần một lượng chất béo nhất định, việc tiêu thụ quá mức có thể làm tăng nguy cơ mắc một số vấn đề sức khỏe.","audioKind":"ex2"}],"collocations":[{"en":"body fat","vi":"lượng mỡ trong cơ thể"},{"en":"saturated fat","vi":"chất béo bão hòa"},{"en":"low in fat","vi":"ít chất béo"}],"wordFamily":["fatty (adj.)","fatten (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng từ fat để miêu tả người có thể gây khó chịu hoặc khiếm nhã; khi nói về sức khỏe, nên dùng từ overweight thì lịch sự hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_smoke', 'en-a2-12', 'smoke', '/smoʊk/', 'A2', 'khói; làn khói; hút thuốc lá; bốc khói', 'n.', 'smoker (n.), smoky (adj.), smoking (n.)', NULL, 'smoke với nghĩa "khói" thường không đếm được; smoky có nghĩa là ngập khói.', 'Dark smoke rose from the toast in the kitchen.', NULL, 'Khói đen bốc lên từ lát bánh mì nướng trong bếp.', '{"wordId":"smoke","ukIpa":"/sməʊk/","usIpa":"/smoʊk/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"a mixture of gases and particles produced when something burns","vi":"khói; làn khói"},{"pos":"v.","en":"to breathe in smoke from burning tobacco","vi":"hút thuốc lá"},{"pos":"v.","en":"to produce smoke","vi":"bốc khói"}],"examples":[{"en":"Dark smoke rose from the toast in the kitchen.","vi":"Khói đen bốc lên từ lát bánh mì nướng trong bếp.","audioKind":"ex"},{"en":"Smoke from forest fires can reduce air quality in cities hundreds of kilometres away.","vi":"Khói từ các vụ cháy rừng có thể làm giảm chất lượng không khí ở những thành phố cách đó hàng trăm km.","audioKind":"ex2"}],"collocations":[{"en":"thick smoke","vi":"khói dày đặc"},{"en":"smoke alarm","vi":"thiết bị báo khói"},{"en":"smoke cigarettes","vi":"hút thuốc lá"},{"en":"give off smoke","vi":"tỏa ra khói"}],"wordFamily":["smoker (n.)","smoky (adj.)","smoking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"smoke với nghĩa \"khói\" thường không đếm được; smoky có nghĩa là ngập khói.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_non-smoking', 'en-a2-12', 'non-smoking', '/ˌnɑːn ˈsmoʊkɪŋ/', 'A2', 'không hút thuốc; cấm hút thuốc; không hút thuốc lá (chỉ người)', 'adj.', 'smoke (v.), smoker (n.), non-smoker (n.), smoking (n.)', 'Đồng nghĩa: smoke-free', 'Có thể dùng để chỉ địa điểm cấm hút thuốc hoặc người không hút thuốc.', 'We asked for a non-smoking room at reception.', NULL, 'Chúng tôi đã yêu cầu một phòng không hút thuốc ở quầy lễ tân.', '{"wordId":"non-smoking","ukIpa":"/ˌnɒn ˈsməʊkɪŋ/","usIpa":"/ˌnɑːn ˈsmoʊkɪŋ/","cefr":"A2","topic":"health","senses":[{"pos":"adj.","en":"describing a place where smoking is not allowed","vi":"không hút thuốc; cấm hút thuốc"},{"pos":"adj.","en":"describing someone who does not smoke","vi":"không hút thuốc lá (chỉ người)"}],"examples":[{"en":"We asked for a non-smoking room at reception.","vi":"Chúng tôi đã yêu cầu một phòng không hút thuốc ở quầy lễ tân.","audioKind":"ex"},{"en":"Non-smoking areas in public buildings help protect visitors and employees from exposure to tobacco smoke.","vi":"Khu vực cấm hút thuốc trong các tòa nhà công cộng giúp bảo vệ khách tham quan và nhân viên khỏi việc phơi nhiễm khói thuốc lá.","audioKind":"ex2"}],"collocations":[{"en":"non-smoking room","vi":"phòng không hút thuốc"},{"en":"non-smoking area","vi":"khu vực cấm hút thuốc"},{"en":"non-smoking household","vi":"gia đình không ai hút thuốc"}],"wordFamily":["smoke (v.)","smoker (n.)","non-smoker (n.)","smoking (n.)"],"synonyms":["smoke-free"],"antonyms":[],"tipVi":"Có thể dùng để chỉ địa điểm cấm hút thuốc hoặc người không hút thuốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sleepy', 'en-a2-12', 'sleepy', '/ˈsliːpi/', 'A2', 'buồn ngủ; mệt mỏi; yên bình; vắng vẻ', 'adj.', 'sleep (n.), sleep (v.), sleepiness (n.), sleepily (adv.)', 'Đồng nghĩa: drowsy · Trái nghĩa: alert, wide awake', 'sleepy nghĩa là buồn ngủ; asleep nghĩa là đã chìm vào giấc ngủ.', 'I felt sleepy after lunch and took a short nap.', NULL, 'Tôi thấy buồn ngủ sau bữa trưa và đã chợp mắt một lát.', '{"wordId":"sleepy","ukIpa":"/ˈsliːpi/","usIpa":"/ˈsliːpi/","cefr":"A2","topic":"health","senses":[{"pos":"adj.","en":"feeling tired and ready to sleep","vi":"buồn ngủ; mệt mỏi"},{"pos":"adj.","en":"quiet and having very little activity","vi":"yên bình; vắng vẻ"}],"examples":[{"en":"I felt sleepy after lunch and took a short nap.","vi":"Tôi thấy buồn ngủ sau bữa trưa và đã chợp mắt một lát.","audioKind":"ex"},{"en":"Students who feel sleepy during lessons may struggle to concentrate and retain new information effectively.","vi":"Học sinh cảm thấy buồn ngủ trong giờ học có thể gặp khó khăn trong việc tập trung và tiếp thu kiến thức mới hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"feel sleepy","vi":"cảm thấy buồn ngủ"},{"en":"sleepy village","vi":"làng quê yên bình"},{"en":"sleepy eyes","vi":"đôi mắt ngái ngủ"}],"wordFamily":["sleep (n.)","sleep (v.)","sleepiness (n.)","sleepily (adv.)"],"synonyms":["drowsy"],"antonyms":["alert","wide awake"],"tipVi":"sleepy nghĩa là buồn ngủ; asleep nghĩa là đã chìm vào giấc ngủ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sick', 'en-a2-12', 'sick', '/sɪk/', 'A2', 'ốm; không khỏe; buồn nôn; muốn nôn; chán ngấy; ngán ngẩm', 'adj.', 'sickness (n.), sickly (adj.), sicken (v.)', 'Đồng nghĩa: ill, unwell · Trái nghĩa: healthy, well', 'Trong tiếng Anh-Anh, be sick thường có nghĩa là nôn mửa, còn feel sick thường chỉ cảm giác buồn nôn.', 'He stayed in bed because he felt sick this morning.', NULL, 'Anh ấy ở lại giường vì sáng nay cảm thấy không khỏe.', '{"wordId":"sick","ukIpa":"/sɪk/","usIpa":"/sɪk/","cefr":"A2","topic":"health","senses":[{"pos":"adj.","en":"Suffering from an illness or feeling unwell.","vi":"ốm; không khỏe"},{"pos":"adj.","en":"Feeling that you might vomit.","vi":"buồn nôn; muốn nôn"},{"pos":"adj.","en":"Very annoyed or tired of someone or something.","vi":"chán ngấy; ngán ngẩm"}],"examples":[{"en":"He stayed in bed because he felt sick this morning.","vi":"Anh ấy ở lại giường vì sáng nay cảm thấy không khỏe.","audioKind":"ex"},{"en":"Paid sick leave allows employees to recover at home and reduces the spread of infections in workplaces.","vi":"Chế độ nghỉ phép có lương giúp nhân viên hồi phục tại nhà và hạn chế sự lây lan của bệnh tật nơi công sở.","audioKind":"ex2"}],"collocations":[{"en":"sick leave","vi":"nghỉ ốm"},{"en":"feel sick","vi":"cảm thấy khó chịu; buồn nôn"},{"en":"be sick of","vi":"chán ngấy với cái gì"},{"en":"call in sick","vi":"gọi điện xin nghỉ ốm"}],"wordFamily":["sickness (n.)","sickly (adj.)","sicken (v.)"],"synonyms":["ill","unwell"],"antonyms":["healthy","well"],"tipVi":"Trong tiếng Anh-Anh, be sick thường có nghĩa là nôn mửa, còn feel sick thường chỉ cảm giác buồn nôn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_toothache', 'en-a2-12', 'toothache', '/ˈtuːθeɪk/', 'A2', 'chứng đau răng; cơn đau răng', 'n.', 'tooth (n.)', NULL, 'Người Anh thường nói have toothache, trong khi người Mỹ thường nói have a toothache.', 'My toothache kept me awake for most of the night.', NULL, 'Cơn đau răng khiến tôi thức trắng gần như cả đêm.', '{"wordId":"toothache","ukIpa":"/ˈtuːθeɪk/","usIpa":"/ˈtuːθeɪk/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"pain in a tooth or the surrounding area","vi":"chứng đau răng; cơn đau răng"}],"examples":[{"en":"My toothache kept me awake for most of the night.","vi":"Cơn đau răng khiến tôi thức trắng gần như cả đêm.","audioKind":"ex"},{"en":"Affordable dental services allow people with toothache to seek treatment before more serious problems develop.","vi":"Các dịch vụ nha khoa giá cả phải chăng giúp những người bị đau răng có thể tìm kiếm sự điều trị trước khi các vấn đề nghiêm trọng hơn phát sinh.","audioKind":"ex2"}],"collocations":[{"en":"have toothache","vi":"bị đau răng"},{"en":"severe toothache","vi":"đau răng dữ dội"},{"en":"relieve toothache","vi":"giảm đau răng"}],"wordFamily":["tooth (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Người Anh thường nói have toothache, trong khi người Mỹ thường nói have a toothache.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_yogurt', 'en-a2-12', 'yogurt', '/ˈjoʊɡərt/', 'A2', 'sữa chua', 'n.', NULL, NULL, 'Tiếng Anh Anh cũng thường viết là yoghurt; thường là danh từ không đếm được, nhưng khi chỉ một phần ăn có thể dùng a yogurt.', 'I mix fresh berries into my yogurt every morning.', NULL, 'Tôi trộn quả mọng tươi vào sữa chua mỗi sáng.', '{"wordId":"yogurt","ukIpa":"/ˈjɒɡət/","usIpa":"/ˈjoʊɡərt/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"A thick, slightly sour food made by fermenting milk.","vi":"sữa chua"}],"examples":[{"en":"I mix fresh berries into my yogurt every morning.","vi":"Tôi trộn quả mọng tươi vào sữa chua mỗi sáng.","audioKind":"ex"},{"en":"Plain yogurt can contribute to a balanced diet by providing protein and calcium without added sugar.","vi":"Sữa chua nguyên chất có thể góp phần tạo nên chế độ ăn cân bằng nhờ cung cấp protein và canxi mà không chứa thêm đường.","audioKind":"ex2"}],"collocations":[{"en":"plain yogurt","vi":"sữa chua nguyên chất"},{"en":"low-fat yogurt","vi":"sữa chua ít béo"},{"en":"a pot of yogurt","vi":"một hũ sữa chua"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh Anh cũng thường viết là yoghurt; thường là danh từ không đếm được, nhưng khi chỉ một phần ăn có thể dùng a yogurt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lip', 'en-a2-12', 'lip', '/lɪp/', 'A2', 'môi; bờ môi; mép; vành (của vật chứa hoặc miệng hố)', 'n.', 'lipstick (n.), lip-read (v.)', NULL, 'Cả hai môi trên và dưới gọi chung là lips; lip cũng có thể chỉ mép của đồ vật.', 'My lips felt dry after walking in the wind.', NULL, 'Môi tôi có cảm giác bị khô sau khi đi bộ trong gió.', '{"wordId":"lip","ukIpa":"/lɪp/","usIpa":"/lɪp/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"Either fleshy edge of the opening of the mouth.","vi":"môi; bờ môi"},{"pos":"n.","en":"The projecting edge of a container, opening, or hollow.","vi":"mép; vành (của vật chứa hoặc miệng hố)"}],"examples":[{"en":"My lips felt dry after walking in the wind.","vi":"Môi tôi có cảm giác bị khô sau khi đi bộ trong gió.","audioKind":"ex"},{"en":"Clear face coverings can improve communication for people who rely on watching lips to understand speech.","vi":"Các loại khẩu trang trong suốt có thể cải thiện giao tiếp cho những người phụ thuộc vào việc quan sát khẩu hình miệng để hiểu lời nói.","audioKind":"ex2"}],"collocations":[{"en":"upper lip","vi":"môi trên"},{"en":"dry lips","vi":"môi khô"},{"en":"bite your lip","vi":"cắn môi"},{"en":"the lip of a cup","vi":"vành cốc"}],"wordFamily":["lipstick (n.)","lip-read (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Cả hai môi trên và dưới gọi chung là lips; lip cũng có thể chỉ mép của đồ vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hurt', 'en-a2-12', 'hurt', '/hɝːt/', 'A2', 'đau đớn; làm tổn thương thể xác; làm tổn thương tình cảm; gây thiệt hại; bị thương; đau khổ, tổn thương về tinh thần', 'v.', 'hurtful (adj.)', NULL, 'Thể quá khứ và phân từ hai đều là hurt; bộ phận bị đau có thể làm chủ ngữ trong câu.', 'My ankle still hurts when I climb the stairs.', NULL, 'Mắt cá chân của tôi vẫn còn đau khi tôi leo cầu thang.', '{"wordId":"hurt","ukIpa":"/hɜːt/","usIpa":"/hɝːt/","cefr":"A2","topic":"health","senses":[{"pos":"v.","en":"To feel pain or cause physical injury.","vi":"đau đớn; làm tổn thương thể xác"},{"pos":"v.","en":"To cause emotional pain or damage something.","vi":"làm tổn thương tình cảm; gây thiệt hại"},{"pos":"adj.","en":"Physically injured or emotionally upset.","vi":"bị thương; đau khổ, tổn thương về tinh thần"}],"examples":[{"en":"My ankle still hurts when I climb the stairs.","vi":"Mắt cá chân của tôi vẫn còn đau khi tôi leo cầu thang.","audioKind":"ex"},{"en":"Cuts to public transport funding may hurt rural communities that depend on buses for essential journeys.","vi":"Việc cắt giảm kinh phí giao thông công cộng có thể gây tổn hại cho các cộng đồng nông thôn vốn phụ thuộc vào xe buýt để di chuyển cho các nhu cầu thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"hurt your back","vi":"làm tổn thương lưng của bạn"},{"en":"hurt someone''s feelings","vi":"làm tổn thương cảm xúc của ai đó"},{"en":"get hurt","vi":"bị thương"}],"wordFamily":["hurtful (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thể quá khứ và phân từ hai đều là hurt; bộ phận bị đau có thể làm chủ ngữ trong câu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_health', 'en-a2-12', 'health', '/helθ/', 'A2', 'sức khỏe; thể trạng; tình trạng hoạt động; sự hưng thịnh', 'n.', 'healthy (adj.), unhealthy (adj.), healthily (adv.)', 'Đồng nghĩa: well-being', 'Thường không đếm được; diễn tả việc có sức khỏe tốt dùng in good health.', 'Walking to work has really improved my health.', NULL, 'Đi bộ đi làm thực sự đã cải thiện sức khỏe của tôi.', '{"wordId":"health","ukIpa":"/helθ/","usIpa":"/helθ/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"The condition of someone''s body and mind.","vi":"sức khỏe; thể trạng"},{"pos":"n.","en":"How well an organisation, economy, or system is functioning.","vi":"tình trạng hoạt động; sự hưng thịnh"}],"examples":[{"en":"Walking to work has really improved my health.","vi":"Đi bộ đi làm thực sự đã cải thiện sức khỏe của tôi.","audioKind":"ex"},{"en":"Governments can improve public health by providing safe drinking water and affordable access to medical services.","vi":"Chính phủ có thể cải thiện sức khỏe cộng đồng bằng cách cung cấp nước uống an toàn và dịch vụ y tế với chi phí phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"mental health","vi":"sức khỏe tinh thần"},{"en":"public health","vi":"sức khỏe cộng đồng"},{"en":"in good health","vi":"có sức khỏe tốt"},{"en":"economic health","vi":"tình hình kinh tế"}],"wordFamily":["healthy (adj.)","unhealthy (adj.)","healthily (adv.)"],"synonyms":["well-being"],"antonyms":[],"tipVi":"Thường không đếm được; diễn tả việc có sức khỏe tốt dùng in good health.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brain', 'en-a2-12', 'brain', '/breɪn/', 'A2', 'bộ não; não; trí tuệ; đầu óc', 'n.', 'brainy (adj.), brainless (adj.)', NULL, 'Khi diễn tả về trí tuệ, người ta thường dùng dạng số nhiều "brains"; còn khi chỉ cơ quan sinh học thì dùng "brain".', 'A helmet helps protect your brain if you fall.', NULL, 'Đội mũ bảo hiểm giúp bảo vệ bộ não của bạn nếu bạn bị ngã.', '{"wordId":"brain","ukIpa":"/breɪn/","usIpa":"/breɪn/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"The organ inside your head controlling thought and bodily activity.","vi":"bộ não; não"},{"pos":"n.","en":"The ability to think clearly and understand things.","vi":"trí tuệ; đầu óc"}],"examples":[{"en":"A helmet helps protect your brain if you fall.","vi":"Đội mũ bảo hiểm giúp bảo vệ bộ não của bạn nếu bạn bị ngã.","audioKind":"ex"},{"en":"Adequate sleep supports healthy brain function and helps learners remember information more effectively.","vi":"Giấc ngủ đầy đủ hỗ trợ hoạt động của não bộ khỏe mạnh và giúp người học ghi nhớ thông tin hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"brain function","vi":"chức năng não bộ"},{"en":"brain damage","vi":"tổn thương não"},{"en":"use your brain","vi":"vận dụng trí óc"}],"wordFamily":["brainy (adj.)","brainless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi diễn tả về trí tuệ, người ta thường dùng dạng số nhiều \"brains\"; còn khi chỉ cơ quan sinh học thì dùng \"brain\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_illness', 'en-a2-12', 'illness', '/ˈɪlnəs/', 'A2', 'căn bệnh; tình trạng ốm đau', 'n.', 'ill (adj.)', 'Đồng nghĩa: sickness · Trái nghĩa: health', 'Từ illness dùng như danh từ không đếm được khi chỉ tình trạng ốm chung chung; dùng như danh từ đếm được khi chỉ một bệnh cụ thể.', 'She missed our picnic because of a sudden illness.', NULL, 'Cô ấy đã lỡ buổi dã ngoại của chúng tôi vì đột ngột đổ bệnh.', '{"wordId":"illness","ukIpa":"/ˈɪlnəs/","usIpa":"/ˈɪlnəs/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"a disease, or the state of being unwell","vi":"căn bệnh; tình trạng ốm đau"}],"examples":[{"en":"She missed our picnic because of a sudden illness.","vi":"Cô ấy đã lỡ buổi dã ngoại của chúng tôi vì đột ngột đổ bệnh.","audioKind":"ex"},{"en":"Early access to medical care can prevent minor illnesses from developing into serious health problems.","vi":"Việc tiếp cận sớm với dịch vụ y tế có thể ngăn chặn các căn bệnh nhẹ chuyển biến thành vấn đề sức khỏe nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"serious illness","vi":"bệnh nặng"},{"en":"mental illness","vi":"bệnh tâm thần"},{"en":"recover from an illness","vi":"hồi phục sau khi ốm"},{"en":"due to illness","vi":"do ốm đau"}],"wordFamily":["ill (adj.)"],"synonyms":["sickness"],"antonyms":["health"],"tipVi":"Từ illness dùng như danh từ không đếm được khi chỉ tình trạng ốm chung chung; dùng như danh từ đếm được khi chỉ một bệnh cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_12_1', 'en-a2-12', 'Cách dùng “illness” (n.) — căn bệnh; tình trạng ốm đau', 'serious illness  ·  mental illness  ·  recover from an illness', 'Từ illness dùng như danh từ không đếm được khi chỉ tình trạng ốm chung chung; dùng như danh từ đếm được khi chỉ một bệnh cụ thể.', 'Họ từ (Word Family): ill (adj.) | Đồng nghĩa: sickness · Trái nghĩa: health', '[{"hanzi":"She missed our picnic because of a sudden illness.","pinyin":"","meaning":"Cô ấy đã lỡ buổi dã ngoại của chúng tôi vì đột ngột đổ bệnh."},{"hanzi":"Early access to medical care can prevent minor illnesses from developing into serious health problems.","pinyin":"","meaning":"Việc tiếp cận sớm với dịch vụ y tế có thể ngăn chặn các căn bệnh nhẹ chuyển biến thành vấn đề sức khỏe nghiêm trọng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_12_2', 'en-a2-12', 'Cách dùng “fat” (n.) — chất béo; mỡ', 'body fat  ·  saturated fat  ·  low in fat', 'Dùng từ fat để miêu tả người có thể gây khó chịu hoặc khiếm nhã; khi nói về sức khỏe, nên dùng từ overweight thì lịch sự hơn.', 'Họ từ (Word Family): fatty (adj.), fatten (v.)', '[{"hanzi":"Let the soup cool, then remove the fat.","pinyin":"","meaning":"Hãy để súp nguội bớt, sau đó hớt bỏ lớp mỡ đi."},{"hanzi":"Although the body needs some fat, excessive consumption can increase the risk of certain health problems.","pinyin":"","meaning":"Mặc dù cơ thể cần một lượng chất béo nhất định, việc tiêu thụ quá mức có thể làm tăng nguy cơ mắc một số vấn đề sức khỏe."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_12_3', 'en-a2-12', 'Cách dùng “yogurt” (n.) — sữa chua', 'plain yogurt  ·  low-fat yogurt  ·  a pot of yogurt', 'Tiếng Anh Anh cũng thường viết là yoghurt; thường là danh từ không đếm được, nhưng khi chỉ một phần ăn có thể dùng a yogurt.', NULL, '[{"hanzi":"I mix fresh berries into my yogurt every morning.","pinyin":"","meaning":"Tôi trộn quả mọng tươi vào sữa chua mỗi sáng."},{"hanzi":"Plain yogurt can contribute to a balanced diet by providing protein and calcium without added sugar.","pinyin":"","meaning":"Sữa chua nguyên chất có thể góp phần tạo nên chế độ ăn cân bằng nhờ cung cấp protein và canxi mà không chứa thêm đường."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_12_4', 'en-a2-12', 'Cách dùng “brain” (n.) — bộ não; não', 'brain function  ·  brain damage  ·  use your brain', 'Khi diễn tả về trí tuệ, người ta thường dùng dạng số nhiều "brains"; còn khi chỉ cơ quan sinh học thì dùng "brain".', 'Họ từ (Word Family): brainy (adj.), brainless (adj.)', '[{"hanzi":"A helmet helps protect your brain if you fall.","pinyin":"","meaning":"Đội mũ bảo hiểm giúp bảo vệ bộ não của bạn nếu bạn bị ngã."},{"hanzi":"Adequate sleep supports healthy brain function and helps learners remember information more effectively.","pinyin":"","meaning":"Giấc ngủ đầy đủ hỗ trợ hoạt động của não bộ khỏe mạnh và giúp người học ghi nhớ thông tin hiệu quả hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_12_1', 'en-a2-12', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
