INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_12_1_2', 'ten_a2_12_1', 'broccoli', 'We steamed the broccoli until it turned bright green.', 'We steamed the broccoli until it turned bright green.', '/ˈbrɑːkəli/', 'Chúng tôi đem hấp súp lơ xanh cho đến khi chuyển sang màu xanh ngắt.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_12_1_3', 'ten_a2_12_1', 'ankle', 'She twisted her ankle while walking down the steps.', 'She twisted her ankle while walking down the steps.', '/ˈæŋkəl/', 'Cô ấy bị trật mắt cá chân khi đang đi xuống bậc thềm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_12_1_4', 'ten_a2_12_1', 'snack', 'I packed an apple and some nuts for a snack.', 'I packed an apple and some nuts for a snack.', '/snæk/', 'Tôi mang theo một quả táo và ít hạt để ăn nhẹ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_12_1_5', 'ten_a2_12_1', 'weak', 'I felt too weak to carry the shopping upstairs.', 'I felt too weak to carry the shopping upstairs.', '/wiːk/', 'Tôi cảm thấy quá yếu để có thể xách đồ mua sắm lên lầu.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_12_1_6', 'ten_a2_12_1', 'cigarette', 'He refused a cigarette and went for a walk instead.', 'He refused a cigarette and went for a walk instead.', '/ˈsɪɡəret/', 'Anh ấy từ chối điếu thuốc lá và đi dạo thay vào đó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_12_1_7', 'ten_a2_12_1', 'nurse', 'The nurse gently wrapped a bandage around my wrist.', 'The nurse gently wrapped a bandage around my wrist.', '/nɝːs/', 'Y tá nhẹ nhàng quấn một lớp băng quanh cổ tay tôi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_12_1_8', 'ten_a2_12_1', 'active', 'My grandfather stays active by swimming every morning.', 'My grandfather stays active by swimming every morning.', '/ˈæk.tɪv/', 'Ông tôi duy trì sự năng động bằng cách bơi lội mỗi sáng.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_12_1_1', 'en-a2-12', 'ten_a2_12_1', 'listening', 'listening', 'My usual diet includes plenty of rice and vegetables.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chế độ ăn thông thường của tôi bao gồm nhiều cơm và rau xanh.","Anh ấy từ chối điếu thuốc lá và đi dạo thay vào đó.","Môi tôi có cảm giác bị khô sau khi đi bộ trong gió.","Ăn uống lành mạnh bắt đầu từ những thay đổi nhỏ trong bữa ăn hàng ngày."]'::jsonb, 0, 'My usual diet includes plenty of rice and vegetables. → Chế độ ăn thông thường của tôi bao gồm nhiều cơm và rau xanh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_12_1_2', 'en-a2-12', 'ten_a2_12_1', 'listening', 'listening', 'We steamed the broccoli until it turned bright green.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Em bé đã ngủ thiếp đi trước khi chúng tôi về đến nhà.","Chúng tôi đem hấp súp lơ xanh cho đến khi chuyển sang màu xanh ngắt.","Sự ra đi của chú chó già khiến gia đình vô cùng đau buồn.","Đội mũ bảo hiểm giúp bảo vệ bộ não của bạn nếu bạn bị ngã."]'::jsonb, 1, 'We steamed the broccoli until it turned bright green. → Chúng tôi đem hấp súp lơ xanh cho đến khi chuyển sang màu xanh ngắt.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_12_1_3', 'en-a2-12', 'ten_a2_12_1', 'listening', 'listening', 'She twisted her ankle while walking down the steps.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Môi tôi có cảm giác bị khô sau khi đi bộ trong gió.","Cô ấy bị trật mắt cá chân khi đang đi xuống bậc thềm.","Đội mũ bảo hiểm giúp bảo vệ bộ não của bạn nếu bạn bị ngã.","Ông tôi duy trì sự năng động bằng cách bơi lội mỗi sáng."]'::jsonb, 1, 'She twisted her ankle while walking down the steps. → Cô ấy bị trật mắt cá chân khi đang đi xuống bậc thềm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_12_2', 'en-a2-12', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_12_2_1', 'ten_a2_12_2', 'diet', 'A balanced diet can improve concentration and help students maintain their energy throughout the school day.', 'A balanced diet can improve concentration and help students maintain their energy throughout the school day.', '/ˈdaɪət/', 'Một chế độ ăn uống cân bằng có thể cải thiện khả năng tập trung và giúp học sinh duy trì năng lượng suốt ngày học ở trường.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_12_2_2', 'ten_a2_12_2', 'broccoli', 'Schools can encourage healthier eating by serving vegetables such as broccoli alongside familiar dishes.', 'Schools can encourage healthier eating by serving vegetables such as broccoli alongside familiar dishes.', '/ˈbrɑːkəli/', 'Nhà trường có thể khuyến khích thói quen ăn uống lành mạnh hơn bằng cách phục vụ các loại rau củ như súp lơ xanh bên cạnh các món quen thuộc.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_12_2_3', 'ten_a2_12_2', 'ankle', 'Appropriate footwear can reduce the risk of ankle injuries during physical exercise and outdoor activities.', 'Appropriate footwear can reduce the risk of ankle injuries during physical exercise and outdoor activities.', '/ˈæŋkəl/', 'Giày dép phù hợp có thể giảm nguy cơ chấn thương mắt cá chân trong các hoạt động thể thao và hoạt động ngoài trời.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_12_2_4', 'ten_a2_12_2', 'snack', 'Schools can encourage healthier eating habits by offering nutritious snacks instead of foods high in sugar.', 'Schools can encourage healthier eating habits by offering nutritious snacks instead of foods high in sugar.', '/snæk/', 'Các trường học có thể khuyến khích thói quen ăn uống lành mạnh hơn bằng cách cung cấp các món ăn nhẹ giàu dinh dưỡng thay cho thực phẩm chứa nhiều đường.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_12_2_5', 'ten_a2_12_2', 'weak', 'Policies based on weak evidence may fail to address the underlying causes of unemployment.', 'Policies based on weak evidence may fail to address the underlying causes of unemployment.', '/wiːk/', 'Các chính sách dựa trên bằng chứng yếu kém có thể không giải quyết được nguyên nhân gốc rễ của tình trạng thất nghiệp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_12_2_6', 'ten_a2_12_2', 'cigarette', 'Higher cigarette taxes may discourage smoking, but accessible support services are also essential for people trying to quit.', 'Higher cigarette taxes may discourage smoking, but accessible support services are also essential for people trying to quit.', '/ˈsɪɡəret/', 'Tăng thuế thuốc lá có thể giúp hạn chế việc hút thuốc, nhưng các dịch vụ hỗ trợ dễ tiếp cận cũng vô cùng thiết yếu cho những người đang cố gắng cai thuốc.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_12_2_1', 'en-a2-12', 'ten_a2_12_2', 'listening', 'listening', 'A balanced diet can improve concentration and help students maintain their energy throughout the school day.', NULL, 'Trong câu vừa nghe, từ “diet” mang nghĩa nào sau đây?', '["con rắn","trừ ra; ngoại trừ","chế độ ăn uống; khẩu phần ăn","chất khí; thể khí"]'::jsonb, 2, '“diet” (/ˈdaɪət/): chế độ ăn uống; khẩu phần ăn. Câu đầy đủ: A balanced diet can improve concentration and help students maintain their energy throughout the school day.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_12_2_2', 'en-a2-12', 'ten_a2_12_2', 'listening', 'listening', 'Schools can encourage healthier eating by serving vegetables such as broccoli alongside familiar dishes.', NULL, 'Trong câu vừa nghe, từ “broccoli” mang nghĩa nào sau đây?', '["quả lê","hồ sơ; sổ sách; bản ghi chép","cải bông xanh, súp lơ xanh","tính từ"]'::jsonb, 2, '“broccoli” (/ˈbrɑːkəli/): cải bông xanh, súp lơ xanh. Câu đầy đủ: Schools can encourage healthier eating by serving vegetables such as broccoli alongside familiar dishes.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
