INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_12_2', 'en-a2-12', NULL, 'comprehensive_test', 'listening', 'We steamed the broccoli until it turned bright green.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đã lỡ buổi dã ngoại của chúng tôi vì đột ngột đổ bệnh.","Khói đen bốc lên từ lát bánh mì nướng trong bếp.","Chúng tôi đem hấp súp lơ xanh cho đến khi chuyển sang màu xanh ngắt.","Hãy để súp nguội bớt, sau đó hớt bỏ lớp mỡ đi."]'::jsonb, 2, 'We steamed the broccoli until it turned bright green. → Chúng tôi đem hấp súp lơ xanh cho đến khi chuyển sang màu xanh ngắt.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
