INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_12_6', 'en-a2-12', NULL, 'comprehensive_test', 'listening', 'He refused a cigarette and went for a walk instead.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Sự ra đi của chú chó già khiến gia đình vô cùng đau buồn.","Anh ấy từ chối điếu thuốc lá và đi dạo thay vào đó.","Cô ấy bị trật mắt cá chân khi đang đi xuống bậc thềm.","Tôi cảm thấy quá yếu để có thể xách đồ mua sắm lên lầu."]'::jsonb, 1, 'He refused a cigarette and went for a walk instead. → Anh ấy từ chối điếu thuốc lá và đi dạo thay vào đó.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
