INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_12_18', 'en-a2-12', NULL, 'comprehensive_test', 'reading', NULL, 'A balanced diet can improve concentration and help students maintain their energy throughout the school day.', 'Dựa vào câu trên, từ “diet” có nghĩa phù hợp nhất là gì?', '["chế độ ăn uống; khẩu phần ăn","tiền lương; lương tháng/lương năm","đám đông; quần chúng","gần đây; mới đây"]'::jsonb, 0, 'diet: chế độ ăn uống; khẩu phần ăn; chế độ ăn kiêng; ăn kiêng. Dịch cả câu: Một chế độ ăn uống cân bằng có thể cải thiện khả năng tập trung và giúp học sinh duy trì năng lượng suốt ngày học ở trường.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_12_19', 'en-a2-12', NULL, 'comprehensive_test', 'reading', NULL, 'Schools can encourage healthier eating by serving vegetables such as broccoli alongside familiar dishes.', 'Dựa vào câu trên, từ “broccoli” có nghĩa phù hợp nhất là gì?', '["thợ làm tóc; thợ cắt tóc","ví tiền; bóp tiền","tác giả; nhà văn","cải bông xanh, súp lơ xanh"]'::jsonb, 3, 'broccoli: cải bông xanh, súp lơ xanh. Dịch cả câu: Nhà trường có thể khuyến khích thói quen ăn uống lành mạnh hơn bằng cách phục vụ các loại rau củ như súp lơ xanh bên cạnh các món quen thuộc.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_12_20', 'en-a2-12', NULL, 'comprehensive_test', 'reading', NULL, 'Appropriate footwear can reduce the risk of ankle injuries during physical exercise and outdoor activities.', 'Dựa vào câu trên, từ “ankle” có nghĩa phù hợp nhất là gì?', '["khớp mắt cá chân","chắc chắn; quả quyết","phòng trưng bày nghệ thuật; bảo tàng nghệ thuật","sự kiểm soát; quyền quản lý"]'::jsonb, 0, 'ankle: khớp mắt cá chân. Dịch cả câu: Giày dép phù hợp có thể giảm nguy cơ chấn thương mắt cá chân trong các hoạt động thể thao và hoạt động ngoài trời.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_12_21', 'en-a2-12', NULL, 'comprehensive_test', 'reading', NULL, 'Schools can encourage healthier eating habits by offering nutritious snacks instead of foods high in sugar.', 'Dựa vào câu trên, từ “snack” có nghĩa phù hợp nhất là gì?', '["thưa ông; thưa ngài; thầy (cách gọi lịch sự đối với nam giới hoặc thầy giáo)","buộc; cột; thắt","được chiên; được rán bằng dầu mỡ","bữa ăn nhẹ; đồ ăn vặt"]'::jsonb, 3, 'snack: bữa ăn nhẹ; đồ ăn vặt; ăn nhẹ; ăn vặt. Dịch cả câu: Các trường học có thể khuyến khích thói quen ăn uống lành mạnh hơn bằng cách cung cấp các món ăn nhẹ giàu dinh dưỡng thay cho thực phẩm chứa nhiều đường.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_12_22', 'en-a2-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sức khỏe; thể trạng”', '["modern","button","health","pot"]'::jsonb, 2, 'sức khỏe; thể trạng → health (/helθ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
