INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_12_24', 'en-a2-12', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “căn bệnh; tình trạng ốm đau”', '["discover","illness","screen","jog"]'::jsonb, 1, 'căn bệnh; tình trạng ốm đau → illness (/ˈɪlnəs/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-13', 'en', 'Bài 13: Sức khỏe & Cơ thể (2) - CEFR A2', 'CEFR A2', 'A2 · Sức khỏe', '25 từ vựng Tiếng Anh CEFR A2 chủ đề sức khỏe & cơ thể kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2013, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_headache', 'en-a2-13', 'headache', '/ˈhedeɪk/', 'A2', 'cơn đau đầu; vấn đề đau đầu; nỗi nhức đầu', 'n.', NULL, NULL, 'Để chỉ một cơn đau đầu, dùng a headache; thông thường dùng cấu trúc have a headache.', 'I have a headache, so I need some quiet.', NULL, 'Tôi bị đau đầu nên cần một khoảng không gian yên tĩnh.', '{"wordId":"headache","ukIpa":"/ˈhedeɪk/","usIpa":"/ˈhedeɪk/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"Pain felt in the head.","vi":"cơn đau đầu"},{"pos":"n.","en":"A problem that causes worry or is difficult to manage.","vi":"vấn đề đau đầu; nỗi nhức đầu"}],"examples":[{"en":"I have a headache, so I need some quiet.","vi":"Tôi bị đau đầu nên cần một khoảng không gian yên tĩnh.","audioKind":"ex"},{"en":"Ageing transport infrastructure has become a major headache for local authorities facing increasingly limited budgets.","vi":"Hệ thống giao thông xuống cấp đã trở thành một bài toán đau đầu lớn đối với các cơ quan chính quyền địa phương đang phải đối mặt với nguồn ngân sách ngày càng hạn hẹp.","audioKind":"ex2"}],"collocations":[{"en":"have a headache","vi":"bị đau đầu"},{"en":"a severe headache","vi":"cơn đau đầu dữ dội"},{"en":"a major headache","vi":"một vấn đề nhức đầu lớn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Để chỉ một cơn đau đầu, dùng a headache; thông thường dùng cấu trúc have a headache.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pill', 'en-a2-13', 'pill', '/pɪl/', 'A2', 'viên thuốc; thuốc viên; thuốc tránh thai uống', 'n.', NULL, 'Đồng nghĩa: tablet', 'take a pill chỉ việc uống thuốc; the pill thường chỉ riêng thuốc tránh thai uống.', 'He swallowed the pill with a glass of water.', NULL, 'Anh ấy uống viên thuốc với một cốc nước.', '{"wordId":"pill","ukIpa":"/pɪl/","usIpa":"/pɪl/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"a small solid piece of medicine that you swallow","vi":"viên thuốc; thuốc viên"},{"pos":"n.","en":"an oral medicine used to prevent pregnancy","vi":"thuốc tránh thai uống"}],"examples":[{"en":"He swallowed the pill with a glass of water.","vi":"Anh ấy uống viên thuốc với một cốc nước.","audioKind":"ex"},{"en":"Although a pill may relieve symptoms, lasting improvements in health often require changes to daily habits.","vi":"Mặc dù thuốc có thể làm giảm triệu chứng, nhưng việc cải thiện sức khỏe lâu dài thường đòi hỏi phải thay đổi thói quen hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"take a pill","vi":"uống thuốc"},{"en":"swallow a pill","vi":"nuốt viên thuốc"},{"en":"vitamin pill","vi":"viên vitamin"},{"en":"the pill","vi":"thuốc tránh thai"}],"wordFamily":[],"synonyms":["tablet"],"antonyms":[],"tipVi":"take a pill chỉ việc uống thuốc; the pill thường chỉ riêng thuốc tránh thai uống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_awake', 'en-a2-13', 'awake', '/əˈweɪk/', 'A2', 'thức; tỉnh táo; thức dậy; đánh thức', 'adj.', 'awaken (v.), awakening (n.)', 'Trái nghĩa: asleep', 'Tính từ thường đóng vai trò vị ngữ; động từ biến đổi thành awoke và awoken.', 'I was still awake when the rain finally stopped.', NULL, 'Tôi vẫn còn thức khi cơn mưa cuối cùng cũng ngớt.', '{"wordId":"awake","ukIpa":"/əˈweɪk/","usIpa":"/əˈweɪk/","cefr":"A2","topic":"health","senses":[{"pos":"adj.","en":"not sleeping","vi":"thức; tỉnh táo"},{"pos":"v.","en":"to stop sleeping or cause someone to stop sleeping","vi":"thức dậy; đánh thức"}],"examples":[{"en":"I was still awake when the rain finally stopped.","vi":"Tôi vẫn còn thức khi cơn mưa cuối cùng cũng ngớt.","audioKind":"ex"},{"en":"Students who stay awake late at night may struggle to concentrate during lessons the following morning.","vi":"Những học sinh thức khuya có thể gặp khó khăn trong việc tập trung vào bài giảng vào sáng hôm sau.","audioKind":"ex2"}],"collocations":[{"en":"wide awake","vi":"tỉnh như sáo; hoàn toàn tỉnh táo"},{"en":"stay awake","vi":"thức khuya; giữ cho tỉnh táo"},{"en":"lie awake","vi":"nằm trằn trọc không ngủ được"}],"wordFamily":["awaken (v.)","awakening (n.)"],"synonyms":[],"antonyms":["asleep"],"tipVi":"Tính từ thường đóng vai trò vị ngữ; động từ biến đổi thành awoke và awoken.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shoulder', 'en-a2-13', 'shoulder', '/ˈʃoʊldər/', 'A2', 'vai; bả vai; đảm nhận; gánh vác', 'n.', NULL, NULL, 'Khi làm động từ, từ này thường đi với responsibility hoặc burden để chỉ việc gánh vác.', 'She rested her head on her father''s shoulder.', NULL, 'Cô ấy tựa đầu vào vai bố.', '{"wordId":"shoulder","ukIpa":"/ˈʃəʊldə/","usIpa":"/ˈʃoʊldər/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"the body part where an arm joins the upper body","vi":"vai; bả vai"},{"pos":"v.","en":"to accept responsibility for something difficult","vi":"đảm nhận; gánh vác"}],"examples":[{"en":"She rested her head on her father''s shoulder.","vi":"Cô ấy tựa đầu vào vai bố.","audioKind":"ex"},{"en":"Governments and businesses must shoulder greater responsibility for reducing the environmental impact of industrial production.","vi":"Chính phủ và doanh nghiệp phải gánh vác trách nhiệm lớn hơn trong việc giảm thiểu tác động môi trường từ sản xuất công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"shoulder responsibility","vi":"gánh vác trách nhiệm"},{"en":"shoulder the burden","vi":"gánh nặng trên vai"},{"en":"shoulder to shoulder","vi":"sát vai bên nhau"},{"en":"look over your shoulder","vi":"liếc nhìn qua vai"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi làm động từ, từ này thường đi với responsibility hoặc burden để chỉ việc gánh vác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_weight', 'en-a2-13', 'weight', '/weɪt/', 'A2', 'trọng lượng; cân nặng; quả tạ; quả cân; tầm quan trọng; sức ảnh hưởng', 'n.', 'weigh (v.), weightless (adj.), weighty (adj.)', 'Đồng nghĩa: heaviness, importance', 'weight là danh từ; weigh là động từ: How much does it weigh?', 'The weight of this suitcase makes it hard to lift.', NULL, 'Trọng lượng của chiếc vali này khiến việc nhấc nó lên trở nên khó khăn.', '{"wordId":"weight","ukIpa":"/weɪt/","usIpa":"/weɪt/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"How heavy someone or something is.","vi":"trọng lượng; cân nặng"},{"pos":"n.","en":"A heavy object used for exercise or measuring weight.","vi":"quả tạ; quả cân"},{"pos":"n.","en":"The importance or influence given to something.","vi":"tầm quan trọng; sức ảnh hưởng"}],"examples":[{"en":"The weight of this suitcase makes it hard to lift.","vi":"Trọng lượng của chiếc vali này khiến việc nhấc nó lên trở nên khó khăn.","audioKind":"ex"},{"en":"Policymakers should give greater weight to scientific evidence when designing strategies to improve public health.","vi":"Các nhà hoạch định chính sách nên coi trọng hơn các bằng chứng khoa học khi thiết kế các chiến lược nhằm cải thiện sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"lose weight","vi":"giảm cân"},{"en":"gain weight","vi":"tăng cân"},{"en":"lift weights","vi":"tập tạ"},{"en":"give weight to","vi":"coi trọng; đánh giá cao"}],"wordFamily":["weigh (v.)","weightless (adj.)","weighty (adj.)"],"synonyms":["heaviness","importance"],"antonyms":[],"tipVi":"weight là danh từ; weigh là động từ: How much does it weigh?","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_patient', 'en-a2-13', 'patient', '/ˈpeɪʃənt/', 'A2', 'bệnh nhân; người bệnh; kiên nhẫn; nhẫn nại', 'n.', 'patience (n.), patiently (adv.), impatient (adj.), impatience (n.)', NULL, 'Khi là danh từ nghĩa là “bệnh nhân”; khi là tính từ thường đi với giới từ with.', 'The nurse brought the patient a glass of water.', NULL, 'Cô y tá mang lại cho bệnh nhân một cốc nước.', '{"wordId":"patient","ukIpa":"/ˈpeɪʃənt/","usIpa":"/ˈpeɪʃənt/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"Someone receiving medical care.","vi":"bệnh nhân; người bệnh"},{"pos":"adj.","en":"Able to wait or handle difficulties without becoming annoyed.","vi":"kiên nhẫn; nhẫn nại"}],"examples":[{"en":"The nurse brought the patient a glass of water.","vi":"Cô y tá mang lại cho bệnh nhân một cốc nước.","audioKind":"ex"},{"en":"Allowing patients to discuss treatment options can improve trust and lead to better health outcomes.","vi":"Việc cho phép bệnh nhân thảo luận về các lựa chọn điều trị có thể cải thiện lòng tin và mang lại kết quả sức khỏe tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"treat a patient","vi":"điều trị cho bệnh nhân"},{"en":"patient care","vi":"chăm sóc bệnh nhân"},{"en":"be patient with","vi":"kiên nhẫn với ai đó"}],"wordFamily":["patience (n.)","patiently (adv.)","impatient (adj.)","impatience (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi là danh từ nghĩa là “bệnh nhân”; khi là tính từ thường đi với giới từ with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drugstore', 'en-a2-13', 'drugstore', '/ˈdrʌɡstɔːr/', 'A2', 'cửa hàng thuốc; hiệu thuốc (bán cả các sản phẩm sinh hoạt hằng ngày)', 'n.', NULL, 'Đồng nghĩa: pharmacy', 'Chủ yếu được dùng trong tiếng Mỹ; tiếng Anh-Anh thường dùng chemist’s hoặc pharmacy.', 'I bought some toothpaste at the drugstore near the station.', NULL, 'Tôi đã mua một ít kem đánh răng ở hiệu thuốc gần ga tàu.', '{"wordId":"drugstore","ukIpa":"/ˈdrʌɡstɔː/","usIpa":"/ˈdrʌɡstɔːr/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"an American shop selling medicines and various everyday products","vi":"cửa hàng thuốc; hiệu thuốc (bán cả các sản phẩm sinh hoạt hằng ngày)"}],"examples":[{"en":"I bought some toothpaste at the drugstore near the station.","vi":"Tôi đã mua một ít kem đánh răng ở hiệu thuốc gần ga tàu.","audioKind":"ex"},{"en":"In some communities, the local drugstore provides essential health advice as well as affordable medicines.","vi":"Ở một số cộng đồng, hiệu thuốc địa phương không chỉ cung cấp thuốc giá cả phải chăng mà còn đưa ra những lời khuyên y tế thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"local drugstore","vi":"hiệu thuốc địa phương"},{"en":"drugstore chain","vi":"chuỗi hiệu thuốc"},{"en":"drugstore counter","vi":"quầy thuốc"}],"wordFamily":[],"synonyms":["pharmacy"],"antonyms":[],"tipVi":"Chủ yếu được dùng trong tiếng Mỹ; tiếng Anh-Anh thường dùng chemist’s hoặc pharmacy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_smoking', 'en-a2-13', 'smoking', '/ˈsmoʊkɪŋ/', 'A2', 'việc hút thuốc', 'n.', 'smoke (v.), smoker (n.), smoky (adj.)', NULL, 'Khi chỉ hoạt động hút thuốc, từ này là danh từ không đếm được; cụm từ cai thuốc là give up smoking.', 'My uncle gave up smoking and now enjoys long walks.', NULL, 'Chú tôi đã bỏ hút thuốc và giờ rất thích đi dạo đường dài.', '{"wordId":"smoking","ukIpa":"/ˈsməʊkɪŋ/","usIpa":"/ˈsmoʊkɪŋ/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"The activity or habit of breathing in smoke from tobacco.","vi":"việc hút thuốc"}],"examples":[{"en":"My uncle gave up smoking and now enjoys long walks.","vi":"Chú tôi đã bỏ hút thuốc và giờ rất thích đi dạo đường dài.","audioKind":"ex"},{"en":"Banning smoking in public buildings can protect workers and visitors from the harmful effects of tobacco smoke.","vi":"Việc cấm hút thuốc trong các tòa nhà công cộng giúp bảo vệ nhân viên và khách tham quan khỏi tác hại của khói thuốc lá.","audioKind":"ex2"}],"collocations":[{"en":"give up smoking","vi":"cai thuốc lá"},{"en":"passive smoking","vi":"hút thuốc thụ động"},{"en":"smoking ban","vi":"lệnh cấm hút thuốc"}],"wordFamily":["smoke (v.)","smoker (n.)","smoky (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ hoạt động hút thuốc, từ này là danh từ không đếm được; cụm từ cai thuốc là give up smoking.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_neck', 'en-a2-13', 'neck', '/nek/', 'A2', 'cổ (phần cơ thể nối đầu với vai); cổ (phần thon hẹp của một vật như chai lọ)', 'n.', NULL, NULL, 'neck chỉ cổ; throat chỉ họng, không được nhầm lẫn giữa hai từ này.', 'He wrapped a warm scarf around his neck.', NULL, 'Anh ấy quấn một chiếc khăn quàng cổ ấm áp quanh cổ mình.', '{"wordId":"neck","ukIpa":"/nek/","usIpa":"/nek/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"the body part connecting the head to the shoulders","vi":"cổ (phần cơ thể nối đầu với vai)"},{"pos":"n.","en":"a narrow part of an object, such as a bottle","vi":"cổ (phần thon hẹp của một vật như chai lọ)"}],"examples":[{"en":"He wrapped a warm scarf around his neck.","vi":"Anh ấy quấn một chiếc khăn quàng cổ ấm áp quanh cổ mình.","audioKind":"ex"},{"en":"Office workers may experience neck pain if their computer screens are positioned at an unsuitable height.","vi":"Nhân viên văn phòng có thể bị đau cổ nếu màn hình máy tính của họ đặt ở độ cao không phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"neck pain","vi":"đau cổ"},{"en":"a stiff neck","vi":"cứng cổ"},{"en":"the neck of a bottle","vi":"cổ chai"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"neck chỉ cổ; throat chỉ họng, không được nhầm lẫn giữa hai từ này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blood', 'en-a2-13', 'blood', '/blʌd/', 'A2', 'máu; chất lỏng đỏ; dòng máu; huyết thống; gia thế', 'n.', 'bloody (adj.), bloodless (adj.)', NULL, 'Blood thường là danh từ không đếm được; một lần xét nghiệm máu dùng a blood test.', 'The nurse took some blood from my arm.', NULL, 'Y tá đã lấy một ít máu từ cánh tay của tôi.', '{"wordId":"blood","ukIpa":"/blʌd/","usIpa":"/blʌd/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"the red liquid that carries oxygen around your body","vi":"máu; chất lỏng đỏ"},{"pos":"n.","en":"family relationships or origins","vi":"dòng máu; huyết thống; gia thế"}],"examples":[{"en":"The nurse took some blood from my arm.","vi":"Y tá đã lấy một ít máu từ cánh tay của tôi.","audioKind":"ex"},{"en":"Regular physical activity can lower blood pressure and reduce the risk of heart disease.","vi":"Hoạt động thể chất thường xuyên có thể làm giảm huyết áp và hạn chế nguy cơ mắc bệnh tim.","audioKind":"ex2"}],"collocations":[{"en":"blood pressure","vi":"huyết áp"},{"en":"blood test","vi":"xét nghiệm máu"},{"en":"donate blood","vi":"hiến máu"},{"en":"blood vessel","vi":"mạch máu"}],"wordFamily":["bloody (adj.)","bloodless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Blood thường là danh từ không đếm được; một lần xét nghiệm máu dùng a blood test.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stomach', 'en-a2-13', 'stomach', '/ˈstʌmək/', 'A2', 'dạ dày; bụng; chịu đựng; dung thứ', 'n.', NULL, NULL, 'Khi mang nghĩa "chịu đựng", từ này thường xuất hiện trong cấu trúc can''t stomach.', 'My stomach started rumbling while I was cooking dinner.', NULL, 'Bụng tôi bắt đầu kêuọp ẹp trong lúc tôi đang nấu bữa tối.', '{"wordId":"stomach","ukIpa":"/ˈstʌmək/","usIpa":"/ˈstʌmək/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"The organ that digests food, or the surrounding body area","vi":"dạ dày; bụng"},{"pos":"v.","en":"To accept something unpleasant without feeling upset or disgusted","vi":"chịu đựng; dung thứ"}],"examples":[{"en":"My stomach started rumbling while I was cooking dinner.","vi":"Bụng tôi bắt đầu kêuọp ẹp trong lúc tôi đang nấu bữa tối.","audioKind":"ex"},{"en":"Eating regular meals may help prevent stomach discomfort and support healthy eating habits among students.","vi":"Việc ăn uống điều độ có thể giúp phòng ngừa khó tiêu và hỗ trợ thói quen ăn uống lành mạnh ở học sinh.","audioKind":"ex2"}],"collocations":[{"en":"an empty stomach","vi":"bụng đói"},{"en":"stomach ache","vi":"chứng đau dạ dày; đau bụng"},{"en":"stomach pain","vi":"đau dạ dày"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa \"chịu đựng\", từ này thường xuất hiện trong cấu trúc can''t stomach.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skin', 'en-a2-13', 'skin', '/skɪn/', 'A2', 'da (người hoặc động vật); vỏ (của một số loại quả và rau củ); lột da; gọt vỏ', 'n.', 'skincare (n.), skinless (adj.)', NULL, 'Da người nói chung là danh từ không đếm được; tấm da thú là danh từ đếm được.', 'My skin feels dry after swimming in the pool.', NULL, 'Da tôi cảm thấy khô sau khi bơi lội trong hồ bơi.', '{"wordId":"skin","ukIpa":"/skɪn/","usIpa":"/skɪn/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"The natural outer covering of a person''s or animal''s body.","vi":"da (người hoặc động vật)"},{"pos":"n.","en":"The thin outer layer of certain fruits and vegetables.","vi":"vỏ (của một số loại quả và rau củ)"},{"pos":"v.","en":"Remove the skin from an animal, fruit or vegetable.","vi":"lột da; gọt vỏ"}],"examples":[{"en":"My skin feels dry after swimming in the pool.","vi":"Da tôi cảm thấy khô sau khi bơi lội trong hồ bơi.","audioKind":"ex"},{"en":"Protecting skin from excessive sunlight can reduce the risk of serious health problems later in life.","vi":"Bảo vệ da khỏi ánh nắng mặt trời quá mức có thể làm giảm nguy cơ mắc các vấn đề sức khỏe nghiêm trọng về sau trong cuộc đời.","audioKind":"ex2"}],"collocations":[{"en":"dry skin","vi":"da khô"},{"en":"sensitive skin","vi":"da nhạy cảm"},{"en":"skin care","vi":"chăm sóc da"},{"en":"potato skins","vi":"vỏ khoai tây"}],"wordFamily":["skincare (n.)","skinless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Da người nói chung là danh từ không đếm được; tấm da thú là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_painful', 'en-a2-13', 'painful', '/ˈpeɪnfəl/', 'A2', 'đau đớn; gây đau; đau khổ; buồn bã; khó xử', 'adj.', 'pain (n.), painfully (adv.), painless (adj.), painlessly (adv.)', 'Đồng nghĩa: sore, distressing · Trái nghĩa: painless', 'painful có thể chỉ nỗi đau thể xác lẫn sự tổn thương tinh thần hoặc tình huống khó xử.', 'My ankle is still painful when I climb stairs.', NULL, 'Cổ chân của tôi vẫn còn đau khi tôi leo cầu thang.', '{"wordId":"painful","ukIpa":"/ˈpeɪnfəl/","usIpa":"/ˈpeɪnfəl/","cefr":"A2","topic":"health","senses":[{"pos":"adj.","en":"causing physical pain or hurting","vi":"đau đớn; gây đau"},{"pos":"adj.","en":"causing sadness, distress, or embarrassment","vi":"đau khổ; buồn bã; khó xử"}],"examples":[{"en":"My ankle is still painful when I climb stairs.","vi":"Cổ chân của tôi vẫn còn đau khi tôi leo cầu thang.","audioKind":"ex"},{"en":"For many workers, losing a secure job is a painful experience that affects both confidence and financial stability.","vi":"Đối với nhiều người lao động, việc mất đi một công việc ổn định là một trải nghiệm đau đớn làm ảnh hưởng đến cả sự tự tin lẫn sự ổn định tài chính.","audioKind":"ex2"}],"collocations":[{"en":"a painful injury","vi":"vết thương đau đớn"},{"en":"a painful experience","vi":"trải nghiệm đau đớn"},{"en":"painful memories","vi":"ký ức đau buồn"},{"en":"painful to touch","vi":"đau khi chạm vào"}],"wordFamily":["pain (n.)","painfully (adv.)","painless (adj.)","painlessly (adv.)"],"synonyms":["sore","distressing"],"antonyms":["painless"],"tipVi":"painful có thể chỉ nỗi đau thể xác lẫn sự tổn thương tinh thần hoặc tình huống khó xử.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_knee', 'en-a2-13', 'knee', '/niː/', 'A2', 'đầu gối; khớp gối', 'n.', 'kneel (v.)', NULL, 'Phụ âm k ở đầu từ không phát âm; dạng số nhiều knees được phát âm là /niːz/.', 'She bent her knee gently before starting the exercise.', NULL, 'Cô ấy nhẹ nhàng gập đầu gối trước khi bắt đầu bài tập.', '{"wordId":"knee","ukIpa":"/niː/","usIpa":"/niː/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"The joint where your leg bends in the middle.","vi":"đầu gối; khớp gối"}],"examples":[{"en":"She bent her knee gently before starting the exercise.","vi":"Cô ấy nhẹ nhàng gập đầu gối trước khi bắt đầu bài tập.","audioKind":"ex"},{"en":"Regular low-impact exercise can strengthen the muscles around the knee and help maintain mobility in older adults.","vi":"Việc tập luyện các bàiSDL cường độ thấp thường xuyên có thể tăng cường sức mạnh cho các cơ xung quanh khớp gối và giúp người cao tuổi duy trì khả năng vận động.","audioKind":"ex2"}],"collocations":[{"en":"knee joint","vi":"khớp gối"},{"en":"knee injury","vi":"chấn thương đầu gối"},{"en":"bend your knees","vi":"gập đầu gối"},{"en":"on your knees","vi":"quỳ gối"}],"wordFamily":["kneel (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Phụ âm k ở đầu từ không phát âm; dạng số nhiều knees được phát âm là /niːz/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_toe', 'en-a2-13', 'toe', '/toʊ/', 'A2', 'ngón chân; mũi giày; mũi tất', 'n.', 'toenail (n.)', NULL, 'Ngón tay là finger, còn ngón chân là toe; ngón chân cái gọi là big toe.', 'There is a little sand stuck between my toes.', NULL, 'Có một ít cát bị kẹt giữa các kẽ ngón chân của tôi.', '{"wordId":"toe","ukIpa":"/təʊ/","usIpa":"/toʊ/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"One of the five separate parts at the foot''s end","vi":"ngón chân"},{"pos":"n.","en":"The part of a shoe or sock covering the toes","vi":"mũi giày; mũi tất"}],"examples":[{"en":"There is a little sand stuck between my toes.","vi":"Có một ít cát bị kẹt giữa các kẽ ngón chân của tôi.","audioKind":"ex"},{"en":"Wearing shoes that restrict toe movement may affect balance and contribute to foot problems over time.","vi":"Việc đi những đôi giày hạn chế chuyển động của ngón chân có thể ảnh hưởng đến khả năng giữ thăng bằng và gây ra các vấn đề về chân theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"big toe","vi":"ngón chân cái"},{"en":"little toe","vi":"ngón chân út"},{"en":"stub your toe","vi":"va ngón chân vào vật cứng"},{"en":"from head to toe","vi":"từ đầu đến chân"}],"wordFamily":["toenail (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Ngón tay là finger, còn ngón chân là toe; ngón chân cái gọi là big toe.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_appointment', 'en-a2-13', 'appointment', '/əˈpɔɪntmənt/', 'A2', 'cuộc hẹn; sự hẹn gặp; sự bổ nhiệm; sự tuyển dụng', 'n.', 'appoint (v.), appointee (n.)', NULL, 'Hẹn gặp ai đó dùng appointment with; việc bổ nhiệm ai đó dùng appointment of.', 'I have a dental appointment early tomorrow morning.', NULL, 'Tôi có lịch hẹn khám nha khoa vào sáng sớm mai.', '{"wordId":"appointment","ukIpa":"/əˈpɔɪntmənt/","usIpa":"/əˈpɔɪntmənt/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"An arrangement to meet someone at a particular time.","vi":"cuộc hẹn; sự hẹn gặp"},{"pos":"n.","en":"The act of choosing someone for a job or position.","vi":"sự bổ nhiệm; sự tuyển dụng"}],"examples":[{"en":"I have a dental appointment early tomorrow morning.","vi":"Tôi có lịch hẹn khám nha khoa vào sáng sớm mai.","audioKind":"ex"},{"en":"Flexible working hours allow employees to attend medical appointments without taking an entire day off.","vi":"Giờ làm việc linh hoạt cho phép nhân viên tham gia các cuộc hẹn y tế mà không cần phải xin nghỉ nguyên cả ngày.","audioKind":"ex2"}],"collocations":[{"en":"make an appointment","vi":"đặt lịch hẹn"},{"en":"cancel an appointment","vi":"hủy lịch hẹn"},{"en":"by appointment only","vi":"chỉ nhận theo lịch hẹn"},{"en":"appointment of a director","vi":"việc bổ nhiệm giám đốc"}],"wordFamily":["appoint (v.)","appointee (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Hẹn gặp ai đó dùng appointment with; việc bổ nhiệm ai đó dùng appointment of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dentist', 'en-a2-13', 'dentist', '/ˈdentɪst/', 'A2', 'bác sĩ nha khoa; nha sĩ', 'n.', 'dental (adj.), dentistry (n.)', NULL, 'dentist chỉ nha sĩ; the dentist''s có thể chỉ phòng khám nha khoa.', 'The dentist checked my teeth and recommended a softer toothbrush.', NULL, 'Nha sĩ đã kiểm tra răng của tôi và giới thiệu một chiếc bàn chải đánh răng mềm hơn.', '{"wordId":"dentist","ukIpa":"/ˈdentɪst/","usIpa":"/ˈdentɪst/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"a professional who examines and treats teeth and gums","vi":"bác sĩ nha khoa; nha sĩ"}],"examples":[{"en":"The dentist checked my teeth and recommended a softer toothbrush.","vi":"Nha sĩ đã kiểm tra răng của tôi và giới thiệu một chiếc bàn chải đánh răng mềm hơn.","audioKind":"ex"},{"en":"Regular visits to a dentist can prevent minor dental problems from developing into serious health conditions.","vi":"Việc đi khám nha sĩ thường xuyên có thể ngăn chặn các vấn đề nha khoa nhỏ phát triển thành các tình trạng sức khỏe nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"see a dentist","vi":"đi khám nha sĩ"},{"en":"a dentist''s appointment","vi":"lịch hẹn nha khoa"},{"en":"a qualified dentist","vi":"nha sĩ có chứng chỉ hành nghề"}],"wordFamily":["dental (adj.)","dentistry (n.)"],"synonyms":[],"antonyms":[],"tipVi":"dentist chỉ nha sĩ; the dentist''s có thể chỉ phòng khám nha khoa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ill', 'en-a2-13', 'ill', '/ɪl/', 'A2', 'ốm; đau; không khỏe; một cách tệ hại; không thiện cảm', 'adj.', 'illness (n.)', 'Đồng nghĩa: unwell, sick · Trái nghĩa: well, healthy', 'Khi mang nghĩa bị ốm, từ này thường đóng vai trò là vị ngữ: be ill.', 'I felt ill after the long bus journey.', NULL, 'Tôi cảm thấy không khỏe sau chuyến đi xe buýt dài.', '{"wordId":"ill","ukIpa":"/ɪl/","usIpa":"/ɪl/","cefr":"A2","topic":"health","senses":[{"pos":"adj.","en":"Suffering from a disease or feeling unwell.","vi":"ốm; đau; không khỏe"},{"pos":"adv.","en":"In a bad or unkind way.","vi":"một cách tệ hại; không thiện cảm"}],"examples":[{"en":"I felt ill after the long bus journey.","vi":"Tôi cảm thấy không khỏe sau chuyến đi xe buýt dài.","audioKind":"ex"},{"en":"Employees who are ill should be encouraged to rest rather than return to work immediately.","vi":"Nên khuyến khích những nhân viên bị ốm nghỉ ngơi thay vì quay lại làm việc ngay lập tức.","audioKind":"ex2"}],"collocations":[{"en":"seriously ill","vi":"bệnh nặng"},{"en":"fall ill","vi":"ngã bệnh"},{"en":"speak ill of","vi":"nói xấu..."}],"wordFamily":["illness (n.)"],"synonyms":["unwell","sick"],"antonyms":["well","healthy"],"tipVi":"Khi mang nghĩa bị ốm, từ này thường đóng vai trò là vị ngữ: be ill.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_birth', 'en-a2-13', 'birth', '/bɝːθ/', 'A2', 'sự sinh đẻ; sự ra đời; ca sinh; sự khởi đầu', 'n.', 'born (adj.), childbirth (n.)', 'Trái nghĩa: death', 'give birth to có nghĩa là sinh ra; còn be born dùng để chỉ việc được sinh ra.', 'The whole family celebrated the birth of our daughter.', NULL, 'Cả gia đình đã ăn mừng sự ra đời của con gái chúng tôi.', '{"wordId":"birth","ukIpa":"/bɜːθ/","usIpa":"/bɝːθ/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"The event or process of a baby being born.","vi":"sự sinh đẻ; sự ra đời; ca sinh"},{"pos":"n.","en":"The beginning of something new.","vi":"sự ra đời; sự khởi đầu"}],"examples":[{"en":"The whole family celebrated the birth of our daughter.","vi":"Cả gia đình đã ăn mừng sự ra đời của con gái chúng tôi.","audioKind":"ex"},{"en":"Access to skilled medical care during birth significantly improves health outcomes for both mothers and newborn babies.","vi":"Việc tiếp cận dịch vụ chăm sóc y tế có chuyên môn trong quá trình sinh nở giúp cải thiện đáng kể kết quả sức khỏe cho cả sản phụ và trẻ sơ sinh.","audioKind":"ex2"}],"collocations":[{"en":"give birth to","vi":"sinh ra; tạo ra"},{"en":"date of birth","vi":"ngày sinh"},{"en":"birth rate","vi":"tỷ lệ sinh"},{"en":"the birth of a movement","vi":"sự ra đời của một phong trào"}],"wordFamily":["born (adj.)","childbirth (n.)"],"synonyms":[],"antonyms":["death"],"tipVi":"give birth to có nghĩa là sinh ra; còn be born dùng để chỉ việc được sinh ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_medicine', 'en-a2-13', 'medicine', '/ˈmedɪsən/', 'A2', 'thuốc; dược phẩm; y học; ngành y', 'n.', 'medical (adj.), medically (adv.), medicinal (adj.)', NULL, 'Dùng take medicine để chỉ việc uống thuốc; khi mang nghĩa là ngành y học thì từ này không đếm được.', 'The pharmacist explained how often to take the medicine.', NULL, 'Dược sĩ đã giải thích tần suất uống loại thuốc này.', '{"wordId":"medicine","ukIpa":"/ˈmedɪsən/","usIpa":"/ˈmedɪsən/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"A substance used to treat or prevent illness.","vi":"thuốc; dược phẩm"},{"pos":"n.","en":"The study and practice of treating and preventing illness.","vi":"y học; ngành y"}],"examples":[{"en":"The pharmacist explained how often to take the medicine.","vi":"Dược sĩ đã giải thích tần suất uống loại thuốc này.","audioKind":"ex"},{"en":"Advances in medicine have increased life expectancy, but access to effective treatment remains unequal across regions.","vi":"Những tiến bộ trong y học đã làm tăng tuổi thọ, nhưng cơ hội tiếp cận các phương pháp điều trị hiệu quả vẫn chưa đồng đều giữa các khu vực.","audioKind":"ex2"}],"collocations":[{"en":"take medicine","vi":"uống thuốc"},{"en":"study medicine","vi":"học ngành y"},{"en":"preventive medicine","vi":"y học dự phòng"},{"en":"prescribe medicine","vi":"kê đơn thuốc"}],"wordFamily":["medical (adj.)","medically (adv.)","medicinal (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng take medicine để chỉ việc uống thuốc; khi mang nghĩa là ngành y học thì từ này không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_care', 'en-a2-13', 'care', '/ker/', 'A2', 'sự chăm sóc; sự chiếu cố; quan tâm; để ý; sự cẩn thận; sự thận trọng', 'n.', 'careful (adj.), careless (adj.), caring (adj.), carefully (adv.)', 'Đồng nghĩa: concern, attention · Trái nghĩa: neglect', 'care about chỉ ý nghĩa quan tâm, để ý; care for có thể mang nghĩa chăm sóc hoặc thích.', 'My grandmother receives excellent care at the local clinic.', NULL, 'Bà tôi nhận được sự chăm sóc rất chu đáo tại phòng khám địa phương.', '{"wordId":"care","ukIpa":"/keə/","usIpa":"/ker/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"Support and attention given to someone who needs help","vi":"sự chăm sóc; sự chiếu cố"},{"pos":"v.","en":"To feel concern or consider something important","vi":"quan tâm; để ý"},{"pos":"n.","en":"Attention given to avoiding mistakes or damage","vi":"sự cẩn thận; sự thận trọng"}],"examples":[{"en":"My grandmother receives excellent care at the local clinic.","vi":"Bà tôi nhận được sự chăm sóc rất chu đáo tại phòng khám địa phương.","audioKind":"ex"},{"en":"Affordable childcare enables more parents to remain employed while ensuring that young children receive appropriate care.","vi":"Dịch vụ chăm sóc trẻ giá cả phải chăng giúp nhiều bậc cha mẹ tiếp tục đi làm, đồng thời bảo đảm các em nhỏ nhận được sự quan tâm thích đáng.","audioKind":"ex2"}],"collocations":[{"en":"medical care","vi":"chăm sóc y tế"},{"en":"take care of","vi":"chăm sóc; trông nom"},{"en":"care about","vi":"quan tâm đến"},{"en":"with care","vi":"một cách cẩn thận"}],"wordFamily":["careful (adj.)","careless (adj.)","caring (adj.)","carefully (adv.)"],"synonyms":["concern","attention"],"antonyms":["neglect"],"tipVi":"care about chỉ ý nghĩa quan tâm, để ý; care for có thể mang nghĩa chăm sóc hoặc thích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heart', 'en-a2-13', 'heart', '/hɑːrt/', 'A2', 'tim; trái tim; tâm can; tấm lòng; tình cảm; trọng tâm; cốt lõi; trung tâm', 'n.', 'heartless (adj.), hearty (adj.), heartfelt (adj.)', NULL, 'Cụm từ "by heart" có nghĩa là ghi nhớ kỹ; "lose heart" có nghĩa là nản lòng.', 'My heart beats faster when I run uphill.', NULL, 'Nhịp tim của tôi đập nhanh hơn khi tôi chạy lên dốc.', '{"wordId":"heart","ukIpa":"/hɑːt/","usIpa":"/hɑːrt/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"The organ that pumps blood around the body.","vi":"tim; trái tim"},{"pos":"n.","en":"The part of someone associated with feelings and love.","vi":"tâm can; tấm lòng; tình cảm"},{"pos":"n.","en":"The central or most important part of something.","vi":"trọng tâm; cốt lõi; trung tâm"}],"examples":[{"en":"My heart beats faster when I run uphill.","vi":"Nhịp tim của tôi đập nhanh hơn khi tôi chạy lên dốc.","audioKind":"ex"},{"en":"Regular physical activity strengthens the heart and can reduce the risk of serious illness.","vi":"Hoạt động thể chất đều đặn giúp tăng cường sức khỏe tim mạch và có thể làm giảm nguy cơ mắc các bệnh hiểm nghèo.","audioKind":"ex2"}],"collocations":[{"en":"heart disease","vi":"bệnh tim"},{"en":"at the heart of","vi":"ở cốt lõi của"},{"en":"learn by heart","vi":"học thuộc lòng"},{"en":"lose heart","vi":"nản lòng; nhụt chí"}],"wordFamily":["heartless (adj.)","hearty (adj.)","heartfelt (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ \"by heart\" có nghĩa là ghi nhớ kỹ; \"lose heart\" có nghĩa là nản lòng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_flu', 'en-a2-13', 'flu', '/fluː/', 'A2', 'bệnh cúm; cảm cúm', 'n.', NULL, 'Đồng nghĩa: influenza', 'flu thường không đếm được; tiếng Anh-Anh thường dùng have flu, trong khi tiếng Anh-Mỹ thường thêm the.', 'She stayed in bed all weekend with the flu.', NULL, 'Cô ấy phải nằm liệt giường suốt cả cuối tuần vì bị cúm.', '{"wordId":"flu","ukIpa":"/fluː/","usIpa":"/fluː/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"an infectious illness causing fever, aches, and tiredness","vi":"bệnh cúm; cảm cúm"}],"examples":[{"en":"She stayed in bed all weekend with the flu.","vi":"Cô ấy phải nằm liệt giường suốt cả cuối tuần vì bị cúm.","audioKind":"ex"},{"en":"Annual flu vaccinations can help protect vulnerable people and reduce pressure on hospitals during winter.","vi":"Việc tiêm phòng cúm hàng năm có thể giúp bảo vệ các nhóm đối tượng dễ bị tổn thương và giảm bớt áp lực cho các bệnh viện trong mùa đông.","audioKind":"ex2"}],"collocations":[{"en":"have the flu","vi":"mắc bệnh cúm"},{"en":"flu symptoms","vi":"triệu chứng cúm"},{"en":"a flu vaccine","vi":"vắc-xin cúm"},{"en":"a flu outbreak","vi":"đợt bùng phát dịch cúm"}],"wordFamily":[],"synonyms":["influenza"],"antonyms":[],"tipVi":"flu thường không đếm được; tiếng Anh-Anh thường dùng have flu, trong khi tiếng Anh-Mỹ thường thêm the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_soap', 'en-a2-13', 'soap', '/soʊp/', 'A2', 'xà phòng; phim truyền hình nhiều tập; phim dài tập; xoa xà phòng; rửa bằng xà phòng', 'n.', 'soapy (adj.)', NULL, 'Chỉ chất tẩy rửa thường là danh từ không đếm được; một cục xà phòng dùng a bar of soap.', 'Please wash your hands with soap before lunch.', NULL, 'Hãy nhớ rửa tay bằng xà phòng trước bữa trưa.', '{"wordId":"soap","ukIpa":"/səʊp/","usIpa":"/soʊp/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"A substance used with water to clean skin or objects.","vi":"xà phòng"},{"pos":"n.","en":"A continuing television or radio drama about everyday relationships.","vi":"phim truyền hình nhiều tập; phim dài tập"},{"pos":"v.","en":"To rub or wash something with soap.","vi":"xoa xà phòng; rửa bằng xà phòng"}],"examples":[{"en":"Please wash your hands with soap before lunch.","vi":"Hãy nhớ rửa tay bằng xà phòng trước bữa trưa.","audioKind":"ex"},{"en":"Providing clean water and soap in schools can help prevent infections and improve children''s overall health.","vi":"Việc cung cấp nước sạch và xà phòng tại các trường học có thể giúp ngăn ngừa lây nhiễm và cải thiện sức khỏe toàn diện cho trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"a bar of soap","vi":"một bánh xà phòng"},{"en":"liquid soap","vi":"xà phòng nước; nước rửa tay"},{"en":"soap and water","vi":"xà phòng và nước"},{"en":"soap opera","vi":"phim truyền hình nhiều tập"}],"wordFamily":["soapy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ chất tẩy rửa thường là danh từ không đếm được; một cục xà phòng dùng a bar of soap.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bone', 'en-a2-13', 'bone', '/boʊn/', 'A2', 'xương; lóc xương; rút xương', 'n.', 'bony (adj.), boneless (adj.)', NULL, 'bone đóng vai trò động từ chỉ hành động rút xương; boneless chỉ đồ không có xương.', 'He broke a bone in his wrist while skating.', NULL, 'Anh ấy bị gãy một chiếc xương ở cổ tay khi đang trượt patin.', '{"wordId":"bone","ukIpa":"/bəʊn/","usIpa":"/boʊn/","cefr":"A2","topic":"health","senses":[{"pos":"n.","en":"One of the hard parts forming a body''s supporting frame.","vi":"xương"},{"pos":"v.","en":"To remove the bones from meat or fish.","vi":"lóc xương; rút xương"}],"examples":[{"en":"He broke a bone in his wrist while skating.","vi":"Anh ấy bị gãy một chiếc xương ở cổ tay khi đang trượt patin.","audioKind":"ex"},{"en":"Regular weight-bearing exercise helps maintain bone strength and can reduce the risk of fractures in older adults.","vi":"Tập thể dục chịu lực thường xuyên giúp duy trì độ chắc khỏe của xương và có thể giảm nguy cơ gãy xương ở người lớn tuổi.","audioKind":"ex2"}],"collocations":[{"en":"break a bone","vi":"gãy xương"},{"en":"bone strength","vi":"độ chắc của xương"},{"en":"bone marrow","vi":"tủy xương"},{"en":"bone density","vi":"mật độ xương"}],"wordFamily":["bony (adj.)","boneless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"bone đóng vai trò động từ chỉ hành động rút xương; boneless chỉ đồ không có xương.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_13_1', 'en-a2-13', 'Cách dùng “flu” (n.) — bệnh cúm; cảm cúm', 'have the flu  ·  flu symptoms  ·  a flu vaccine', 'flu thường không đếm được; tiếng Anh-Anh thường dùng have flu, trong khi tiếng Anh-Mỹ thường thêm the.', 'Đồng nghĩa: influenza', '[{"hanzi":"She stayed in bed all weekend with the flu.","pinyin":"","meaning":"Cô ấy phải nằm liệt giường suốt cả cuối tuần vì bị cúm."},{"hanzi":"Annual flu vaccinations can help protect vulnerable people and reduce pressure on hospitals during winter.","pinyin":"","meaning":"Việc tiêm phòng cúm hàng năm có thể giúp bảo vệ các nhóm đối tượng dễ bị tổn thương và giảm bớt áp lực cho các bệnh viện trong mùa đông."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_13_2', 'en-a2-13', 'Cách dùng “smoking” (n.) — việc hút thuốc', 'give up smoking  ·  passive smoking  ·  smoking ban', 'Khi chỉ hoạt động hút thuốc, từ này là danh từ không đếm được; cụm từ cai thuốc là give up smoking.', 'Họ từ (Word Family): smoke (v.), smoker (n.), smoky (adj.)', '[{"hanzi":"My uncle gave up smoking and now enjoys long walks.","pinyin":"","meaning":"Chú tôi đã bỏ hút thuốc và giờ rất thích đi dạo đường dài."},{"hanzi":"Banning smoking in public buildings can protect workers and visitors from the harmful effects of tobacco smoke.","pinyin":"","meaning":"Việc cấm hút thuốc trong các tòa nhà công cộng giúp bảo vệ nhân viên và khách tham quan khỏi tác hại của khói thuốc lá."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_13_3', 'en-a2-13', 'Cách dùng “medicine” (n.) — thuốc; dược phẩm', 'take medicine  ·  study medicine  ·  preventive medicine', 'Dùng take medicine để chỉ việc uống thuốc; khi mang nghĩa là ngành y học thì từ này không đếm được.', 'Họ từ (Word Family): medical (adj.), medically (adv.), medicinal (adj.)', '[{"hanzi":"The pharmacist explained how often to take the medicine.","pinyin":"","meaning":"Dược sĩ đã giải thích tần suất uống loại thuốc này."},{"hanzi":"Advances in medicine have increased life expectancy, but access to effective treatment remains unequal across regions.","pinyin":"","meaning":"Những tiến bộ trong y học đã làm tăng tuổi thọ, nhưng cơ hội tiếp cận các phương pháp điều trị hiệu quả vẫn chưa đồng đều giữa các khu vực."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_13_4', 'en-a2-13', 'Cách dùng “soap” (n.) — xà phòng', 'a bar of soap  ·  liquid soap  ·  soap and water', 'Chỉ chất tẩy rửa thường là danh từ không đếm được; một cục xà phòng dùng a bar of soap.', 'Họ từ (Word Family): soapy (adj.)', '[{"hanzi":"Please wash your hands with soap before lunch.","pinyin":"","meaning":"Hãy nhớ rửa tay bằng xà phòng trước bữa trưa."},{"hanzi":"Providing clean water and soap in schools can help prevent infections and improve children''s overall health.","pinyin":"","meaning":"Việc cung cấp nước sạch và xà phòng tại các trường học có thể giúp ngăn ngừa lây nhiễm và cải thiện sức khỏe toàn diện cho trẻ em."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_13_1', 'en-a2-13', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
