INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_13_1_2', 'ten_a2_13_1', 'pill', 'He swallowed the pill with a glass of water.', 'He swallowed the pill with a glass of water.', '/pɪl/', 'Anh ấy uống viên thuốc với một cốc nước.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_13_1_3', 'ten_a2_13_1', 'awake', 'I was still awake when the rain finally stopped.', 'I was still awake when the rain finally stopped.', '/əˈweɪk/', 'Tôi vẫn còn thức khi cơn mưa cuối cùng cũng ngớt.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_13_1_4', 'ten_a2_13_1', 'shoulder', 'She rested her head on her father''s shoulder.', 'She rested her head on her father''s shoulder.', '/ˈʃoʊldər/', 'Cô ấy tựa đầu vào vai bố.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_13_1_5', 'ten_a2_13_1', 'weight', 'The weight of this suitcase makes it hard to lift.', 'The weight of this suitcase makes it hard to lift.', '/weɪt/', 'Trọng lượng của chiếc vali này khiến việc nhấc nó lên trở nên khó khăn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_13_1_6', 'ten_a2_13_1', 'patient', 'The nurse brought the patient a glass of water.', 'The nurse brought the patient a glass of water.', '/ˈpeɪʃənt/', 'Cô y tá mang lại cho bệnh nhân một cốc nước.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_13_1_7', 'ten_a2_13_1', 'drugstore', 'I bought some toothpaste at the drugstore near the station.', 'I bought some toothpaste at the drugstore near the station.', '/ˈdrʌɡstɔːr/', 'Tôi đã mua một ít kem đánh răng ở hiệu thuốc gần ga tàu.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_13_1_8', 'ten_a2_13_1', 'smoking', 'My uncle gave up smoking and now enjoys long walks.', 'My uncle gave up smoking and now enjoys long walks.', '/ˈsmoʊkɪŋ/', 'Chú tôi đã bỏ hút thuốc và giờ rất thích đi dạo đường dài.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_13_1_1', 'en-a2-13', 'ten_a2_13_1', 'listening', 'listening', 'I have a headache, so I need some quiet.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cả gia đình đã ăn mừng sự ra đời của con gái chúng tôi.","Tôi bị đau đầu nên cần một khoảng không gian yên tĩnh.","Dược sĩ đã giải thích tần suất uống loại thuốc này.","Anh ấy uống viên thuốc với một cốc nước."]'::jsonb, 1, 'I have a headache, so I need some quiet. → Tôi bị đau đầu nên cần một khoảng không gian yên tĩnh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_13_1_2', 'en-a2-13', 'ten_a2_13_1', 'listening', 'listening', 'He swallowed the pill with a glass of water.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy uống viên thuốc với một cốc nước.","Hãy nhớ rửa tay bằng xà phòng trước bữa trưa.","Tôi vẫn còn thức khi cơn mưa cuối cùng cũng ngớt.","Trọng lượng của chiếc vali này khiến việc nhấc nó lên trở nên khó khăn."]'::jsonb, 0, 'He swallowed the pill with a glass of water. → Anh ấy uống viên thuốc với một cốc nước.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_13_1_3', 'en-a2-13', 'ten_a2_13_1', 'listening', 'listening', 'I was still awake when the rain finally stopped.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Anh ấy quấn một chiếc khăn quàng cổ ấm áp quanh cổ mình.","Tôi bị đau đầu nên cần một khoảng không gian yên tĩnh.","Tôi vẫn còn thức khi cơn mưa cuối cùng cũng ngớt.","Bụng tôi bắt đầu kêuọp ẹp trong lúc tôi đang nấu bữa tối."]'::jsonb, 2, 'I was still awake when the rain finally stopped. → Tôi vẫn còn thức khi cơn mưa cuối cùng cũng ngớt.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_13_2', 'en-a2-13', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_13_2_1', 'ten_a2_13_2', 'headache', 'Ageing transport infrastructure has become a major headache for local authorities facing increasingly limited budgets.', 'Ageing transport infrastructure has become a major headache for local authorities facing increasingly limited budgets.', '/ˈhedeɪk/', 'Hệ thống giao thông xuống cấp đã trở thành một bài toán đau đầu lớn đối với các cơ quan chính quyền địa phương đang phải đối mặt với nguồn ngân sách ngày càng hạn hẹp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_13_2_2', 'ten_a2_13_2', 'pill', 'Although a pill may relieve symptoms, lasting improvements in health often require changes to daily habits.', 'Although a pill may relieve symptoms, lasting improvements in health often require changes to daily habits.', '/pɪl/', 'Mặc dù thuốc có thể làm giảm triệu chứng, nhưng việc cải thiện sức khỏe lâu dài thường đòi hỏi phải thay đổi thói quen hàng ngày.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_13_2_3', 'ten_a2_13_2', 'awake', 'Students who stay awake late at night may struggle to concentrate during lessons the following morning.', 'Students who stay awake late at night may struggle to concentrate during lessons the following morning.', '/əˈweɪk/', 'Những học sinh thức khuya có thể gặp khó khăn trong việc tập trung vào bài giảng vào sáng hôm sau.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_13_2_4', 'ten_a2_13_2', 'shoulder', 'Governments and businesses must shoulder greater responsibility for reducing the environmental impact of industrial production.', 'Governments and businesses must shoulder greater responsibility for reducing the environmental impact of industrial production.', '/ˈʃoʊldər/', 'Chính phủ và doanh nghiệp phải gánh vác trách nhiệm lớn hơn trong việc giảm thiểu tác động môi trường từ sản xuất công nghiệp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_13_2_5', 'ten_a2_13_2', 'weight', 'Policymakers should give greater weight to scientific evidence when designing strategies to improve public health.', 'Policymakers should give greater weight to scientific evidence when designing strategies to improve public health.', '/weɪt/', 'Các nhà hoạch định chính sách nên coi trọng hơn các bằng chứng khoa học khi thiết kế các chiến lược nhằm cải thiện sức khỏe cộng đồng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_13_2_6', 'ten_a2_13_2', 'patient', 'Allowing patients to discuss treatment options can improve trust and lead to better health outcomes.', 'Allowing patients to discuss treatment options can improve trust and lead to better health outcomes.', '/ˈpeɪʃənt/', 'Việc cho phép bệnh nhân thảo luận về các lựa chọn điều trị có thể cải thiện lòng tin và mang lại kết quả sức khỏe tốt hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_13_2_1', 'en-a2-13', 'ten_a2_13_2', 'listening', 'listening', 'Ageing transport infrastructure has become a major headache for local authorities facing increasingly limited budgets.', NULL, 'Trong câu vừa nghe, từ “headache” mang nghĩa nào sau đây?', '["năng động; tích cực tham gia","cơn đau đầu","vị; vị giác","hoàn toàn; triệt để"]'::jsonb, 1, '“headache” (/ˈhedeɪk/): cơn đau đầu. Câu đầy đủ: Ageing transport infrastructure has become a major headache for local authorities facing increasingly limited budgets.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
