INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_13_6', 'en-a2-13', NULL, 'comprehensive_test', 'listening', 'The nurse brought the patient a glass of water.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô y tá mang lại cho bệnh nhân một cốc nước.","Anh ấy bị gãy một chiếc xương ở cổ tay khi đang trượt patin.","Chú tôi đã bỏ hút thuốc và giờ rất thích đi dạo đường dài.","Cả gia đình đã ăn mừng sự ra đời của con gái chúng tôi."]'::jsonb, 0, 'The nurse brought the patient a glass of water. → Cô y tá mang lại cho bệnh nhân một cốc nước.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_13_7', 'en-a2-13', NULL, 'comprehensive_test', 'listening', 'drugstore', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cửa hàng thuốc; hiệu thuốc (bán cả các sản phẩm sinh hoạt hằng ngày)","quan điểm; ý chính","đi bộ đường dài; leo núi; đi dã ngoại (đi dạo dài ở ngoài trời, đặc biệt là vùng nông thôn)","nữa; không... nữa"]'::jsonb, 0, 'drugstore (/ˈdrʌɡstɔːr/) → cửa hàng thuốc; hiệu thuốc (bán cả các sản phẩm sinh hoạt hằng ngày)', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_13_8', 'en-a2-13', NULL, 'comprehensive_test', 'listening', 'My uncle gave up smoking and now enjoys long walks.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chú tôi đã bỏ hút thuốc và giờ rất thích đi dạo đường dài.","Cô ấy tựa đầu vào vai bố.","Anh ấy uống viên thuốc với một cốc nước.","Anh ấy bị gãy một chiếc xương ở cổ tay khi đang trượt patin."]'::jsonb, 0, 'My uncle gave up smoking and now enjoys long walks. → Chú tôi đã bỏ hút thuốc và giờ rất thích đi dạo đường dài.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_13_9', 'en-a2-13', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “How heavy someone or something is.”?', '["skin","headache","weight","neck"]'::jsonb, 2, 'weight (/weɪt/) → trọng lượng; cân nặng', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
