INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_13_18', 'en-a2-13', NULL, 'comprehensive_test', 'reading', NULL, 'Ageing transport infrastructure has become a major headache for local authorities facing increasingly limited budgets.', 'Dựa vào câu trên, từ “headache” có nghĩa phù hợp nhất là gì?', '["cho đến khi; đến tận","bí mật; giữ kín","cơn đau đầu","bàn phím (máy tính)"]'::jsonb, 2, 'headache: cơn đau đầu; vấn đề đau đầu; nỗi nhức đầu. Dịch cả câu: Hệ thống giao thông xuống cấp đã trở thành một bài toán đau đầu lớn đối với các cơ quan chính quyền địa phương đang phải đối mặt với nguồn ngân sách ngày càng hạn hẹp.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_13_19', 'en-a2-13', NULL, 'comprehensive_test', 'reading', NULL, 'Although a pill may relieve symptoms, lasting improvements in health often require changes to daily habits.', 'Dựa vào câu trên, từ “pill” có nghĩa phù hợp nhất là gì?', '["viên thuốc; thuốc viên","vai; bả vai","bãi đỗ xe ngoài trời","sân; khu đất quanh nhà (thường có rào chắn)"]'::jsonb, 0, 'pill: viên thuốc; thuốc viên; thuốc tránh thai uống. Dịch cả câu: Mặc dù thuốc có thể làm giảm triệu chứng, nhưng việc cải thiện sức khỏe lâu dài thường đòi hỏi phải thay đổi thói quen hàng ngày.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_13_20', 'en-a2-13', NULL, 'comprehensive_test', 'reading', NULL, 'Students who stay awake late at night may struggle to concentrate during lessons the following morning.', 'Dựa vào câu trên, từ “awake” có nghĩa phù hợp nhất là gì?', '["quyết định; sự lựa chọn","bánh quy giòn (cách dùng Anh-Anh)","thức; tỉnh táo","phòng vệ sinh công cộng; nhà vệ sinh"]'::jsonb, 2, 'awake: thức; tỉnh táo; thức dậy; đánh thức. Dịch cả câu: Những học sinh thức khuya có thể gặp khó khăn trong việc tập trung vào bài giảng vào sáng hôm sau.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_13_21', 'en-a2-13', NULL, 'comprehensive_test', 'reading', NULL, 'Governments and businesses must shoulder greater responsibility for reducing the environmental impact of industrial production.', 'Dựa vào câu trên, từ “shoulder” có nghĩa phù hợp nhất là gì?', '["sự tham quan; sự vãn cảnh","sự ngạc nhiên; điều bất ngờ","vai; bả vai","lời chào hỏi; sự chào đón"]'::jsonb, 2, 'shoulder: vai; bả vai; đảm nhận; gánh vác. Dịch cả câu: Chính phủ và doanh nghiệp phải gánh vác trách nhiệm lớn hơn trong việc giảm thiểu tác động môi trường từ sản xuất công nghiệp.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
