INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-14', 'en', 'Bài 14: Nghệ thuật & Sáng tạo - CEFR A2', 'CEFR A2', 'A2 · Nghệ thuật', '27 từ vựng Tiếng Anh CEFR A2 chủ đề nghệ thuật & sáng tạo kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2014, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_album', 'en-a2-14', 'album', '/ˈælbəm/', 'A2', 'album nhạc; đĩa nhạc; album ảnh; sách sưu tầm tem', 'n.', NULL, NULL, 'Album nhạc dùng album; đĩa đơn dùng single.', 'Her new album kept us singing all afternoon.', NULL, 'Album mới của cô ấy làm chúng tôi hát theo suốt cả buổi chiều.', '{"wordId":"album","ukIpa":"/ˈælbəm/","usIpa":"/ˈælbəm/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"A collection of recorded music released as one product.","vi":"album nhạc; đĩa nhạc"},{"pos":"n.","en":"A book for keeping photographs, stamps or similar collections.","vi":"album ảnh; sách sưu tầm tem"}],"examples":[{"en":"Her new album kept us singing all afternoon.","vi":"Album mới của cô ấy làm chúng tôi hát theo suốt cả buổi chiều.","audioKind":"ex"},{"en":"Digital platforms allow independent musicians to release an album without relying on a traditional record company.","vi":"Các nền tảng kỹ thuật số cho phép các nghệ sĩ độc lập phát hành album mà không cần phụ thuộc vào một công ty thu âm truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"release an album","vi":"phát hành album"},{"en":"debut album","vi":"album đầu tay"},{"en":"photo album","vi":"album ảnh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Album nhạc dùng album; đĩa đơn dùng single.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_design', 'en-a2-14', 'design', '/dɪˈzaɪn/', 'A2', 'thiết kế; phác thảo; bản thiết kế; kiểu dáng; họa tiết trang trí', 'v.', 'designer (n.), redesign (v.)', NULL, 'be designed to do diễn tả ý nghĩa "được thiết kế để làm gì đó / nhằm mục đích làm gì".', 'My cousin designed a wooden desk for her bedroom.', NULL, 'Anh họ của tôi đã thiết kế một chiếc bàn gỗ cho phòng ngủ của cô ấy.', '{"wordId":"design","ukIpa":"/dɪˈzaɪn/","usIpa":"/dɪˈzaɪn/","cefr":"A2","topic":"arts","senses":[{"pos":"v.","en":"plan how something will look or work before making it","vi":"thiết kế; phác thảo"},{"pos":"n.","en":"the planning of something''s appearance or function, or its plan","vi":"bản thiết kế; kiểu dáng"},{"pos":"n.","en":"a decorative pattern on an object or surface","vi":"họa tiết trang trí"}],"examples":[{"en":"My cousin designed a wooden desk for her bedroom.","vi":"Anh họ của tôi đã thiết kế một chiếc bàn gỗ cho phòng ngủ của cô ấy.","audioKind":"ex"},{"en":"Cities should design public spaces that encourage social interaction while remaining accessible to people with disabilities.","vi":"Các thành phố nên thiết kế các không gian công cộng vừa khuyến khích sự tương tác xã hội vừa thuận tiện cho người khuyết tật sử dụng.","audioKind":"ex2"}],"collocations":[{"en":"design a building","vi":"thiết kế một tòa nhà"},{"en":"be designed to do something","vi":"được thiết kế để làm gì"},{"en":"graphic design","vi":"thiết kế đồ họa"},{"en":"interior design","vi":"thiết kế nội thất"}],"wordFamily":["designer (n.)","redesign (v.)"],"synonyms":[],"antonyms":[],"tipVi":"be designed to do diễn tả ý nghĩa \"được thiết kế để làm gì đó / nhằm mục đích làm gì\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_violin', 'en-a2-14', 'violin', '/ˌvaɪəˈlɪn/', 'A2', 'đàn vĩ cầm; đàn violon', 'n.', 'violinist (n.)', NULL, 'Người chơi đàn vĩ cầm là "violinist"; hành động chơi đàn dùng "play the violin".', 'My sister practises the violin after dinner every evening.', NULL, 'Chị gái tôi tập chơi đàn vĩ cầm sau bữa tối mỗi tối.', '{"wordId":"violin","ukIpa":"/ˌvaɪəˈlɪn/","usIpa":"/ˌvaɪəˈlɪn/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"A four-stringed instrument held under the chin and usually bowed.","vi":"đàn vĩ cầm; đàn violon"}],"examples":[{"en":"My sister practises the violin after dinner every evening.","vi":"Chị gái tôi tập chơi đàn vĩ cầm sau bữa tối mỗi tối.","audioKind":"ex"},{"en":"Learning the violin can help children develop concentration, although regular lessons may be expensive for some families.","vi":"Việc học đàn vĩ cầm có thể giúp trẻ em phát triển khả năng tập trung, mặc dù các buổi học đều đặn có thể tốn kém đối với một số gia đình.","audioKind":"ex2"}],"collocations":[{"en":"play the violin","vi":"chơi đàn vĩ cầm"},{"en":"violin lessons","vi":"các buổi học đàn vĩ cầm"},{"en":"a violin concerto","vi":"bản hòa tấu vĩ cầm"}],"wordFamily":["violinist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Người chơi đàn vĩ cầm là \"violinist\"; hành động chơi đàn dùng \"play the violin\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_designer', 'en-a2-14', 'designer', '/dɪˈzaɪnər/', 'A2', 'người thiết kế; nhà thiết kế; hàng hiệu thiết kế', 'n.', 'design (v.), design (n.)', NULL, 'Là tính từ, từ này thường đứng trước các danh từ như quần áo để nhấn mạnh thương hiệu thiết kế.', 'The designer showed us a model of our kitchen.', NULL, 'Nhà thiết kế đã cho chúng tôi xem mô hình phòng bếp của mình.', '{"wordId":"designer","ukIpa":"/dɪˈzaɪnə/","usIpa":"/dɪˈzaɪnər/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"Someone who plans how something will look or work.","vi":"người thiết kế; nhà thiết kế"},{"pos":"adj.","en":"Made by a famous fashion designer, usually expensive.","vi":"hàng hiệu thiết kế"}],"examples":[{"en":"The designer showed us a model of our kitchen.","vi":"Nhà thiết kế đã cho chúng tôi xem mô hình phòng bếp của mình.","audioKind":"ex"},{"en":"A skilled designer can make public spaces more accessible to people with limited mobility.","vi":"Một nhà thiết kế tay nghề cao có thể giúp không gian công cộng trở nên thuận tiện hơn cho những người bị hạn chế về khả năng di chuyển.","audioKind":"ex2"}],"collocations":[{"en":"fashion designer","vi":"thời trang thiết kế"},{"en":"graphic designer","vi":"nhà thiết kế đồ họa"},{"en":"interior designer","vi":"nhà thiết kế nội thất"},{"en":"designer clothes","vi":"quần áo hàng hiệu"}],"wordFamily":["design (v.)","design (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là tính từ, từ này thường đứng trước các danh từ như quần áo để nhấn mạnh thương hiệu thiết kế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_style', 'en-a2-14', 'style', '/staɪl/', 'A2', 'phong cách, cách thức đặc trưng để làm điều gì đó hoặc bộc lộ ý tưởng; kiểu dáng, mẫu thiết kế hoặc vẻ ngoài hợp thời trang; tạo kiểu, thiết kế kiểu dáng cho thứ gì đó để đạt được vẻ ngoài như ý', 'n.', 'stylish (adj.), stylist (n.), stylistic (adj.), stylishly (adv.)', 'Đồng nghĩa: manner', 'Từ style có thể chỉ phong cách cá nhân, không nhất thiết phải biểu thị xu hướng thời trang thịnh hành.', 'Her colourful paintings have a cheerful, playful style.', NULL, 'Những bức tranh đầy màu sắc của cô ấy mang phong cách vui tươi và nhí nhảnh.', '{"wordId":"style","ukIpa":"/staɪl/","usIpa":"/staɪl/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"A distinctive way of doing something or expressing ideas.","vi":"phong cách, cách thức đặc trưng để làm điều gì đó hoặc bộc lộ ý tưởng"},{"pos":"n.","en":"The design of something or a fashionable appearance.","vi":"kiểu dáng, mẫu thiết kế hoặc vẻ ngoài hợp thời trang"},{"pos":"v.","en":"To arrange or design something to achieve a particular look.","vi":"tạo kiểu, thiết kế kiểu dáng cho thứ gì đó để đạt được vẻ ngoài như ý"}],"examples":[{"en":"Her colourful paintings have a cheerful, playful style.","vi":"Những bức tranh đầy màu sắc của cô ấy mang phong cách vui tươi và nhí nhảnh.","audioKind":"ex"},{"en":"Modern architects often adapt traditional building styles to preserve local identity while meeting contemporary housing needs.","vi":"Các kiến trúc sư hiện đại thường cải biên phong cách kiến trúc truyền thống nhằm bảo tồn bản sắc địa phương trong khi vẫn đáp ứng nhu cầu nhà ở đương đại.","audioKind":"ex2"}],"collocations":[{"en":"writing style","vi":"phong cách viết"},{"en":"architectural style","vi":"phong cách kiến trúc"},{"en":"in style","vi":"hợp thời trang, phong cách"},{"en":"style your hair","vi":"tạo kiểu tóc"}],"wordFamily":["stylish (adj.)","stylist (n.)","stylistic (adj.)","stylishly (adv.)"],"synonyms":["manner"],"antonyms":[],"tipVi":"Từ style có thể chỉ phong cách cá nhân, không nhất thiết phải biểu thị xu hướng thời trang thịnh hành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_musician', 'en-a2-14', 'musician', '/mjuˈzɪʃən/', 'A2', 'nhạc công; nghệ sĩ âm nhạc; nhạc sĩ', 'n.', 'music (n.), musical (adj.), musically (adv.), musicianship (n.)', NULL, 'musician chỉ chung người làm âm nhạc; từ composer dùng cụ thể hơn cho nhà soạn nhạc.', 'A musician played the violin outside the station.', NULL, 'Một nhạc công đang chơi đàn vĩ cầm ở bên ngoài nhà ga.', '{"wordId":"musician","ukIpa":"/mjuˈzɪʃən/","usIpa":"/mjuˈzɪʃən/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"someone who plays music, especially professionally","vi":"nhạc công; nghệ sĩ âm nhạc; nhạc sĩ"}],"examples":[{"en":"A musician played the violin outside the station.","vi":"Một nhạc công đang chơi đàn vĩ cầm ở bên ngoài nhà ga.","audioKind":"ex"},{"en":"Local musicians can strengthen community identity by performing traditional songs at public festivals and cultural events.","vi":"Các nhạc công địa phương có thể củng cố bản sắc cộng đồng bằng cách trình bày các bài hát truyền thống trong các lễ hội công cộng và sự kiện văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"professional musician","vi":"nhạc sĩ chuyên nghiệp"},{"en":"talented musician","vi":"nhạc sĩ tài năng"},{"en":"street musician","vi":"nhạc công đường phố"}],"wordFamily":["music (n.)","musical (adj.)","musically (adv.)","musicianship (n.)"],"synonyms":[],"antonyms":[],"tipVi":"musician chỉ chung người làm âm nhạc; từ composer dùng cụ thể hơn cho nhà soạn nhạc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_painter', 'en-a2-14', 'painter', '/ˈpeɪntər/', 'A2', 'họa sĩ; thợ sơn', 'n.', 'paint (v.), paint (n.), painting (n.)', NULL, 'Từ này vừa có thể chỉ họa sĩ nghệ thuật, vừa chỉ thợ sơn tường nhà.', 'The painter mixed blue and green on her palette.', NULL, 'Nữ họa sĩ pha màu xanh dương và xanh lá trên bảng màu của cô ấy.', '{"wordId":"painter","ukIpa":"/ˈpeɪntə/","usIpa":"/ˈpeɪntər/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"Someone who creates pictures using paint.","vi":"họa sĩ"},{"pos":"n.","en":"Someone whose job is painting buildings or other surfaces.","vi":"thợ sơn"}],"examples":[{"en":"The painter mixed blue and green on her palette.","vi":"Nữ họa sĩ pha màu xanh dương và xanh lá trên bảng màu của cô ấy.","audioKind":"ex"},{"en":"Local painters can preserve cultural traditions while introducing younger audiences to new artistic styles.","vi":"Các họa sĩ địa phương có thể bảo tồn các truyền thống văn hóa đồng thời giới thiệu các phong cách nghệ thuật mới cho khán giả trẻ tuổi.","audioKind":"ex2"}],"collocations":[{"en":"a landscape painter","vi":"họa sĩ vẽ tranh phong cảnh"},{"en":"a portrait painter","vi":"họa sĩ vẽ chân dung"},{"en":"a house painter","vi":"thợ sơn nhà"}],"wordFamily":["paint (v.)","paint (n.)","painting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ này vừa có thể chỉ họa sĩ nghệ thuật, vừa chỉ thợ sơn tường nhà.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_comedy', 'en-a2-14', 'comedy', '/ˈkɑːmədi/', 'A2', 'hài kịch; phim hài; tính hài hước; sự buồn cười', 'n.', 'comedian (n.), comic (adj.), comedic (adj.)', 'Trái nghĩa: tragedy', 'Chỉ thể loại hài kịch thường là không đếm được; một vở kịch/phim hài dùng a comedy.', 'We watched a comedy and laughed all evening.', NULL, 'Chúng tôi xem một bộ phim hài và cười suốt cả buổi tối.', '{"wordId":"comedy","ukIpa":"/ˈkɒmədi/","usIpa":"/ˈkɑːmədi/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"Entertainment intended to make people laugh.","vi":"hài kịch; phim hài"},{"pos":"n.","en":"The humorous quality of a situation or event.","vi":"tính hài hước; sự buồn cười"}],"examples":[{"en":"We watched a comedy and laughed all evening.","vi":"Chúng tôi xem một bộ phim hài và cười suốt cả buổi tối.","audioKind":"ex"},{"en":"Comedy can encourage audiences to question social attitudes by presenting familiar problems in unexpected and amusing ways.","vi":"Hài kịch có thể khuyến khích khán giả đặt câu hỏi về các quan niệm xã hội bằng cách trình bày những vấn đề quen thuộc theo những cách bất ngờ và thú vị.","audioKind":"ex2"}],"collocations":[{"en":"romantic comedy","vi":"phim hài lãng mạn"},{"en":"stand-up comedy","vi":"hài độc thoại"},{"en":"a comedy series","vi":"loạt phim hài"}],"wordFamily":["comedian (n.)","comic (adj.)","comedic (adj.)"],"synonyms":[],"antonyms":["tragedy"],"tipVi":"Chỉ thể loại hài kịch thường là không đếm được; một vở kịch/phim hài dùng a comedy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_circus', 'en-a2-14', 'circus', '/ˈsɝːkəs/', 'A2', 'gánh xiếc; buổi biểu diễn xiếc', 'n.', NULL, NULL, 'Có thể chỉ gánh xiếc hoặc buổi biểu diễn; số nhiều là circuses.', 'We watched the circus performers juggle brightly coloured balls.', NULL, 'Chúng tôi ngắm nhìn các nghệ sĩ biểu diễn xiếc tung hứng những quả bóng màu sắc rực rỡ.', '{"wordId":"circus","ukIpa":"/ˈsɜːkəs/","usIpa":"/ˈsɝːkəs/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"A group or show featuring acrobats, clowns, and other performers.","vi":"gánh xiếc; buổi biểu diễn xiếc"}],"examples":[{"en":"We watched the circus performers juggle brightly coloured balls.","vi":"Chúng tôi ngắm nhìn các nghệ sĩ biểu diễn xiếc tung hứng những quả bóng màu sắc rực rỡ.","audioKind":"ex"},{"en":"Modern circus performances can preserve traditional entertainment skills while creating opportunities for artists from diverse backgrounds.","vi":"Các màn trình diễn xiếc hiện đại vừa có thể gìn giữ các kỹ năng giải trí truyền thống vừa tạo ra cơ hội cho các nghệ sĩ đến từ nhiều hoàn cảnh khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"circus performer","vi":"nghệ sĩ xiếc"},{"en":"circus tent","vi":"lều xiếc"},{"en":"circus act","vi":"tiết mục xiếc"},{"en":"travelling circus","vi":"gánh xiếc lưu động"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ gánh xiếc hoặc buổi biểu diễn; số nhiều là circuses.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pop', 'en-a2-14', 'pop', '/pɑːp/', 'A2', 'nhạc pop; nhạc trẻ thịnh hành; làm nổ; phát ra tiếng bục; ghé qua; thò ra; nhét nhanh', 'n.', NULL, NULL, 'Khi dùng với nghĩa đi nhanh hoặc đặt nhanh, từ này mang sắc thái thân mật.', 'My sister listens to pop while she cooks dinner.', NULL, 'Chị tôi nghe nhạc pop trong lúc nấu bữa tối.', '{"wordId":"pop","ukIpa":"/pɒp/","usIpa":"/pɑːp/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"popular music with catchy tunes and usually simple structures","vi":"nhạc pop; nhạc trẻ thịnh hành"},{"pos":"v.","en":"to burst or make a short, sharp sound","vi":"làm nổ; phát ra tiếng bục"},{"pos":"v.","en":"to go somewhere briefly or put something somewhere quickly","vi":"ghé qua; thò ra; nhét nhanh"}],"examples":[{"en":"My sister listens to pop while she cooks dinner.","vi":"Chị tôi nghe nhạc pop trong lúc nấu bữa tối.","audioKind":"ex"},{"en":"Pop can introduce young listeners to other cultures, especially when artists combine different musical traditions.","vi":"Nhạc pop có thể giới thiệu cho thính giả trẻ những nền văn hóa khác, đặc biệt là khi các nghệ sĩ kết hợp các truyền thống âm nhạc khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"pop music","vi":"nhạc pop"},{"en":"pop a balloon","vi":"làm nổ bóng bay"},{"en":"pop into a shop","vi":"ghé vào cửa hàng"},{"en":"pop up","vi":"bất ngờ xuất hiện"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi dùng với nghĩa đi nhanh hoặc đặt nhanh, từ này mang sắc thái thân mật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gallery', 'en-a2-14', 'gallery', '/ˈɡæləri/', 'A2', 'phòng trưng bày nghệ thuật; bảo tàng nghệ thuật; tầng lửng; hàng ghế trên cao trong hội trường hoặc nhà hát; bộ sưu tập hình ảnh; kho ảnh trực tuyến', 'n.', NULL, NULL, 'gallery chủ yếu trưng bày các tác phẩm nghệ thuật; trong khi museum bao trùm phạm vi hiện vật rộng lớn hơn.', 'We spent a rainy afternoon exploring the local gallery.', NULL, 'Chúng tôi đã dành một buổi chiều mưa để khám phá phòng tranh nghệ thuật địa phương.', '{"wordId":"gallery","ukIpa":"/ˈɡæləri/","usIpa":"/ˈɡæləri/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"A room or building where artworks are displayed or sold.","vi":"phòng trưng bày nghệ thuật; bảo tàng nghệ thuật"},{"pos":"n.","en":"A raised seating area overlooking a hall or theatre.","vi":"tầng lửng; hàng ghế trên cao trong hội trường hoặc nhà hát"},{"pos":"n.","en":"A collection of images available to view, especially online.","vi":"bộ sưu tập hình ảnh; kho ảnh trực tuyến"}],"examples":[{"en":"We spent a rainy afternoon exploring the local gallery.","vi":"Chúng tôi đã dành một buổi chiều mưa để khám phá phòng tranh nghệ thuật địa phương.","audioKind":"ex"},{"en":"Free entry to a public gallery can make visual art accessible to people from different economic backgrounds.","vi":"Việc mở cửa miễn phí cho công chúng vào tham quan các phòng tranh nghệ thuật công cộng giúp cho nghệ thuật thị giác tiếp cận được với những người có hoàn cảnh kinh tế khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"art gallery","vi":"phòng trưng bày nghệ thuật"},{"en":"public gallery","vi":"phòng trưng bày công cộng; khu vực ghế cấp cao"},{"en":"photo gallery","vi":"bộ sưu tập ảnh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"gallery chủ yếu trưng bày các tác phẩm nghệ thuật; trong khi museum bao trùm phạm vi hiện vật rộng lớn hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ending', 'en-a2-14', 'ending', '/ˈendɪŋ/', 'A2', 'phần kết; đoạn kết; cái kết; phần đuôi từ; vĩ tố (ngữ pháp)', 'n.', 'end (n.), end (v.), endless (adj.)', 'Đồng nghĩa: conclusion · Trái nghĩa: beginning', 'Cái kết của một câu chuyện dùng ending; còn cụm at the end dùng để chỉ ở phần cuối.', 'The film had a surprisingly cheerful ending for everyone.', NULL, 'Bộ phim có một cái kết vô cùng vui tươi làm hài lòng tất cả mọi người.', '{"wordId":"ending","ukIpa":"/ˈendɪŋ/","usIpa":"/ˈendɪŋ/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"the final part of a story, event, or activity","vi":"phần kết; đoạn kết; cái kết"},{"pos":"n.","en":"a final word part that often shows grammatical information","vi":"phần đuôi từ; vĩ tố (ngữ pháp)"}],"examples":[{"en":"The film had a surprisingly cheerful ending for everyone.","vi":"Bộ phim có một cái kết vô cùng vui tươi làm hài lòng tất cả mọi người.","audioKind":"ex"},{"en":"An ambiguous ending can encourage readers to question their assumptions and consider alternative interpretations of a novel.","vi":"Một cái kết mơ hồ có thể khuyến khích người đọc chất vấn các giả định của chính họ và cân nhắc những cách hiểu khác nhau về một cuốn tiểu thuyết.","audioKind":"ex2"}],"collocations":[{"en":"a happy ending","vi":"một cái kết có hậu"},{"en":"a surprise ending","vi":"một cái kết bất ngờ"},{"en":"a verb ending","vi":"vĩ tố động từ"}],"wordFamily":["end (n.)","end (v.)","endless (adj.)"],"synonyms":["conclusion"],"antonyms":["beginning"],"tipVi":"Cái kết của một câu chuyện dùng ending; còn cụm at the end dùng để chỉ ở phần cuối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drama', 'en-a2-14', 'drama', '/ˈdrɑːmə/', 'A2', 'kịch; nghệ thuật kịch; sự việc kịch tính; tình huống đầy cảm xúc', 'n.', 'dramatic (adj.), dramatically (adv.), dramatist (n.), dramatise (v.)', NULL, 'Nghệ thuật kịch dùng danh từ không đếm được drama; một vở kịch dùng a drama.', 'Our drama group rehearses in the hall every Thursday.', NULL, 'Nhóm kịch của chúng tôi tập luyện tại hội trường vào mỗi thứ Năm.', '{"wordId":"drama","ukIpa":"/ˈdrɑːmə/","usIpa":"/ˈdrɑːmə/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"Plays and the art of writing or performing them.","vi":"kịch; nghệ thuật kịch"},{"pos":"n.","en":"An exciting or emotional event or situation.","vi":"sự việc kịch tính; tình huống đầy cảm xúc"}],"examples":[{"en":"Our drama group rehearses in the hall every Thursday.","vi":"Nhóm kịch của chúng tôi tập luyện tại hội trường vào mỗi thứ Năm.","audioKind":"ex"},{"en":"Teaching drama in schools can develop students'' confidence and encourage them to consider different perspectives.","vi":"Việc giảng dạy môn kịch ở trường học có thể phát triển sự tự tin của học sinh và khuyến khích các em nhìn nhận vấn đề từ nhiều góc độ khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"drama club","vi":"câu lạc bộ kịch"},{"en":"television drama","vi":"phim truyền hình"},{"en":"study drama","vi":"học về kịch"},{"en":"historical drama","vi":"phim dã sử; kịch lịch sử"}],"wordFamily":["dramatic (adj.)","dramatically (adv.)","dramatist (n.)","dramatise (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghệ thuật kịch dùng danh từ không đếm được drama; một vở kịch dùng a drama.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jazz', 'en-a2-14', 'jazz', '/dʒæz/', 'A2', 'nhạc jazz; nhạc gia-d', 'n.', NULL, NULL, 'Khi chỉ thể loại âm nhạc thì thường không đếm được, không đi kèm mạo từ a.', 'We listened to jazz while cooking dinner together.', NULL, 'Chúng tôi vừa nghe nhạc jazz vừa cùng nhau nấu bữa tối.', '{"wordId":"jazz","ukIpa":"/dʒæz/","usIpa":"/dʒæz/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"Music with strong rhythms and often freely invented melodies.","vi":"nhạc jazz; nhạc gia-d"}],"examples":[{"en":"We listened to jazz while cooking dinner together.","vi":"Chúng tôi vừa nghe nhạc jazz vừa cùng nhau nấu bữa tối.","audioKind":"ex"},{"en":"Community jazz festivals can attract visitors while giving local musicians valuable opportunities to perform.","vi":"Các lễ hội nhạc jazz cộng đồng vừa có thể thu hút du khách vừa mang lại cho các nghệ sĩ địa phương những cơ hội biểu diễn quý giá.","audioKind":"ex2"}],"collocations":[{"en":"jazz band","vi":"ban nhạc jazz"},{"en":"jazz festival","vi":"lễ hội nhạc jazz"},{"en":"jazz musician","vi":"nhạc sĩ jazz"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ thể loại âm nhạc thì thường không đếm được, không đi kèm mạo từ a.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_actress', 'en-a2-14', 'actress', '/ˈæktrəs/', 'A2', 'nữ diễn viên', 'n.', 'actor (n.), acting (n.), act (v.)', NULL, 'Từ actor có thể dùng chung cho cả nam lẫn nữ, trong khi actress chỉ đích danh nữ diễn viên.', 'The actress waved to the crowd outside the theatre.', NULL, 'Nữ diễn viên vẫy tay chào đám đông bên ngoài nhà hát.', '{"wordId":"actress","ukIpa":"/ˈæktrəs/","usIpa":"/ˈæktrəs/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"a woman who performs characters in plays or films","vi":"nữ diễn viên"}],"examples":[{"en":"The actress waved to the crowd outside the theatre.","vi":"Nữ diễn viên vẫy tay chào đám đông bên ngoài nhà hát.","audioKind":"ex"},{"en":"A successful actress can encourage young people to explore careers in the performing arts.","vi":"Một nữ diễn viên thành công có thể truyền cảm hứng cho giới trẻ theo đuổi sự nghiệp trong lĩnh vực nghệ thuật biểu diễn.","audioKind":"ex2"}],"collocations":[{"en":"leading actress","vi":"nữ diễn viên chính"},{"en":"supporting actress","vi":"nữ diễn viên phụ"},{"en":"award-winning actress","vi":"nữ diễn viên giành giải thưởng"}],"wordFamily":["actor (n.)","acting (n.)","act (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ actor có thể dùng chung cho cả nam lẫn nữ, trong khi actress chỉ đích danh nữ diễn viên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_create', 'en-a2-14', 'create', '/kriˈeɪt/', 'A2', 'tạo ra; sáng tạo; gây ra; tạo nên', 'v.', 'creation (n.), creative (adj.), creativity (n.), creator (n.)', 'Đồng nghĩa: make, produce, generate · Trái nghĩa: destroy', 'create nhấn mạnh tạo ra sự vật mới, hoặc có thể đi với problem để chỉ việc gây ra rắc rối.', 'We created a colourful bird from folded paper.', NULL, 'Chúng tôi đã làm một con chim đầy màu sắc từ giấy gấp.', '{"wordId":"create","ukIpa":"/kriˈeɪt/","usIpa":"/kriˈeɪt/","cefr":"A2","topic":"arts","senses":[{"pos":"v.","en":"to make something new or bring something into existence","vi":"tạo ra; sáng tạo"},{"pos":"v.","en":"to cause a situation, feeling, or problem to develop","vi":"gây ra; tạo nên"}],"examples":[{"en":"We created a colourful bird from folded paper.","vi":"Chúng tôi đã làm một con chim đầy màu sắc từ giấy gấp.","audioKind":"ex"},{"en":"Investment in renewable energy can create jobs while reducing dependence on imported fossil fuels.","vi":"Đầu tư vào năng lượng tái tạo có thể tạo ra việc làm đồng thời giảm sự phụ thuộc vào nhiên liệu hóa thạch nhập khẩu.","audioKind":"ex2"}],"collocations":[{"en":"create opportunities","vi":"tạo cơ hội"},{"en":"create jobs","vi":"tạo việc làm"},{"en":"create a problem","vi":"gây ra vấn đề"},{"en":"create a work of art","vi":"tác phẩm nghệ thuật"}],"wordFamily":["creation (n.)","creative (adj.)","creativity (n.)","creator (n.)"],"synonyms":["make","produce","generate"],"antonyms":["destroy"],"tipVi":"create nhấn mạnh tạo ra sự vật mới, hoặc có thể đi với problem để chỉ việc gây ra rắc rối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_concert', 'en-a2-14', 'concert', '/ˈkɑːnsərt/', 'A2', 'buổi hòa nhạc; buổi biểu diễn âm nhạc', 'n.', NULL, NULL, 'Đi nghe hòa nhạc dùng go to a concert.', 'We enjoyed an outdoor concert in the park yesterday.', NULL, 'Chúng tôi đã thưởng thức một buổi hòa nhạc ngoài trời tại công viên vào ngày hôm qua.', '{"wordId":"concert","ukIpa":"/ˈkɒnsət/","usIpa":"/ˈkɑːnsərt/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"a live musical performance given before an audience","vi":"buổi hòa nhạc; buổi biểu diễn âm nhạc"}],"examples":[{"en":"We enjoyed an outdoor concert in the park yesterday.","vi":"Chúng tôi đã thưởng thức một buổi hòa nhạc ngoài trời tại công viên vào ngày hôm qua.","audioKind":"ex"},{"en":"Free public concerts can make cultural activities more accessible and encourage residents to use shared urban spaces.","vi":"Các buổi hòa nhạc công cộng miễn phí có thể giúp mọi người tiếp cận nhiều hơn với các hoạt động văn hóa và khuyến khích cư dân sử dụng không gian chung của đô thị.","audioKind":"ex2"}],"collocations":[{"en":"attend a concert","vi":"tham dự buổi hòa nhạc"},{"en":"give a concert","vi":"tổ chức buổi hòa nhạc"},{"en":"concert hall","vi":"phòng hòa nhạc"},{"en":"live concert","vi":"buổi hòa nhạc trực tiếp"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đi nghe hòa nhạc dùng go to a concert.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dancer', 'en-a2-14', 'dancer', '/ˈdænsər/', 'A2', 'vũ công; diễn viên múa', 'n.', 'dance (v.), dance (n.), dancing (n.)', NULL, 'dancer không phân biệt giới tính, và cũng không nhất thiết chỉ áp dụng cho vũ công chuyên nghiệp.', 'The dancer spun gracefully across the small stage.', NULL, 'Nữ vũ công uyển chuyển xoay tròn trên sân khấu nhỏ.', '{"wordId":"dancer","ukIpa":"/ˈdɑːnsə/","usIpa":"/ˈdænsər/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"someone who dances, especially as a job","vi":"vũ công; diễn viên múa"}],"examples":[{"en":"The dancer spun gracefully across the small stage.","vi":"Nữ vũ công uyển chuyển xoay tròn trên sân khấu nhỏ.","audioKind":"ex"},{"en":"Professional dancers require regular physical training and adequate rest to maintain performance quality and prevent injuries.","vi":"Các vũ công chuyên nghiệp đòi hỏi phải luyện tập thể chất đều đặn và nghỉ ngơi đầy đủ để duy trì phong độ biểu diễn cũng như phòng ngừa chấn thương.","audioKind":"ex2"}],"collocations":[{"en":"professional dancer","vi":"vũ công chuyên nghiệp"},{"en":"ballet dancer","vi":"vũ công múa ba lê"},{"en":"talented dancer","vi":"vũ công tài năng"}],"wordFamily":["dance (v.)","dance (n.)","dancing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"dancer không phân biệt giới tính, và cũng không nhất thiết chỉ áp dụng cho vũ công chuyên nghiệp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_magic', 'en-a2-14', 'magic', '/ˈmædʒɪk/', 'A2', 'phép thuật; trò ảo thuật; sự kỳ diệu; nét quyến rũ; có phép thuật; dùng để biểu diễn ảo thuật', 'n.', 'magical (adj.), magically (adv.), magician (n.)', 'Đồng nghĩa: sorcery', 'magic thường chỉ phép thuật hoặc ảo thuật; magical cũng có thể dùng để miêu tả trải nghiệm tuyệt vời.', 'The children laughed when he performed a magic trick.', NULL, 'Bọn trẻ đã cười lớn khi anh ấy biểu diễn một màn ảo thuật.', '{"wordId":"magic","ukIpa":"/ˈmædʒɪk/","usIpa":"/ˈmædʒɪk/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"An imaginary supernatural power, or tricks that seem to use it.","vi":"phép thuật; trò ảo thuật"},{"pos":"n.","en":"A special quality that makes something exciting or wonderful.","vi":"sự kỳ diệu; nét quyến rũ"},{"pos":"adj.","en":"Having supernatural powers or used in performing tricks.","vi":"có phép thuật; dùng để biểu diễn ảo thuật"}],"examples":[{"en":"The children laughed when he performed a magic trick.","vi":"Bọn trẻ đã cười lớn khi anh ấy biểu diễn một màn ảo thuật.","audioKind":"ex"},{"en":"Although technology can improve education, it is not a magic solution to every problem schools face.","vi":"Mặc dù công nghệ có thể cải thiện giáo dục, nhưng nó không phải là giải pháp kỳ diệu cho mọi vấn đề mà các trường học phải đối mặt.","audioKind":"ex2"}],"collocations":[{"en":"magic trick","vi":"trò ảo thuật"},{"en":"magic wand","vi":"cây đũa thần"},{"en":"magic solution","vi":"giải pháp kỳ diệu"}],"wordFamily":["magical (adj.)","magically (adv.)","magician (n.)"],"synonyms":["sorcery"],"antonyms":[],"tipVi":"magic thường chỉ phép thuật hoặc ảo thuật; magical cũng có thể dùng để miêu tả trải nghiệm tuyệt vời.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clap', 'en-a2-14', 'clap', '/klæp/', 'A2', 'vỗ tay; khua tay; tiếng vỗ tay; tiếng động lớn bất chợt', 'v.', 'clapping (n.)', 'Đồng nghĩa: applaud', 'Quá khứ là clapped; phân từ hiện tại là clapping, nhân đôi chữ p.', 'Everyone clapped when the children finished their song.', NULL, 'Mọi người đều vỗ tay khi lũ trẻ hát xong bài hát của chúng.', '{"wordId":"clap","ukIpa":"/klæp/","usIpa":"/klæp/","cefr":"A2","topic":"arts","senses":[{"pos":"v.","en":"To strike your hands together, often to show approval.","vi":"vỗ tay; khua tay"},{"pos":"n.","en":"A sudden loud sound, especially from hands striking together.","vi":"tiếng vỗ tay; tiếng động lớn bất chợt"}],"examples":[{"en":"Everyone clapped when the children finished their song.","vi":"Mọi người đều vỗ tay khi lũ trẻ hát xong bài hát của chúng.","audioKind":"ex"},{"en":"Audiences often clap after live performances to express appreciation for the skill and effort of the artists.","vi":"Khán giả thường vỗ tay sau các buổi biểu diễn trực tiếp để bày tỏ sự tán thưởng đối với tài năng và nỗ lực của các nghệ sĩ.","audioKind":"ex2"}],"collocations":[{"en":"clap your hands","vi":"vỗ tay của bạn"},{"en":"clap along","vi":"vỗ tay theo nhịp"},{"en":"a clap of thunder","vi":"một tiếng sấm nổ vang"}],"wordFamily":["clapping (n.)"],"synonyms":["applaud"],"antonyms":[],"tipVi":"Quá khứ là clapped; phân từ hiện tại là clapping, nhân đôi chữ p.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_theatre', 'en-a2-14', 'theatre', '/ˈθiːətər/', 'A2', 'nhà hát; rạp hát; nghệ thuật sân khấu; kịch nghệ; phòng phẫu thuật', 'n.', 'theatrical (adj.), theatrically (adv.)', NULL, 'Kiểu Anh viết là theatre, kiểu Mỹ thường là theater; rạp chiếu phim tiếng Anh-Anh là cinema.', 'We arrived at the theatre just before the play started.', NULL, 'Chúng tôi đến nhà hát ngay trước khi vở kịch bắt đầu.', '{"wordId":"theatre","ukIpa":"/ˈθɪətə/","usIpa":"/ˈθiːətər/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"A building where people watch plays and other live performances.","vi":"nhà hát; rạp hát"},{"pos":"n.","en":"The activity or art of writing, producing, and performing plays.","vi":"nghệ thuật sân khấu; kịch nghệ"},{"pos":"n.","en":"A specially equipped room in a hospital where operations happen.","vi":"phòng phẫu thuật"}],"examples":[{"en":"We arrived at the theatre just before the play started.","vi":"Chúng tôi đến nhà hát ngay trước khi vở kịch bắt đầu.","audioKind":"ex"},{"en":"Public funding for theatre can make live performances accessible to audiences who cannot afford expensive tickets.","vi":"Sự tài trợ công cho nghệ thuật sân khấu có thể giúp những khán giả không đủ khả năng mua vé đắt tiền tiếp cận được các buổi biểu diễn trực tiếp.","audioKind":"ex2"}],"collocations":[{"en":"go to the theatre","vi":"đi xem kịch ở nhà hát"},{"en":"a theatre company","vi":"đoàn kịch"},{"en":"musical theatre","vi":"kịch ca nhạc"},{"en":"an operating theatre","vi":"phòng mổ"}],"wordFamily":["theatrical (adj.)","theatrically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Kiểu Anh viết là theatre, kiểu Mỹ thường là theater; rạp chiếu phim tiếng Anh-Anh là cinema.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fashion', 'en-a2-14', 'fashion', '/ˈfæʃən/', 'A2', 'thời trang; mốt; cách thức; phương thức; làm; tạo hình', 'n.', 'fashionable (adj.), fashionably (adv.), unfashionable (adj.)', 'Đồng nghĩa: style, vogue', 'Khi diễn tả cách thức, cụm in a... fashion thường được dùng với văn phong trang trọng hơn.', 'My sister follows fashion but rarely buys expensive clothes.', NULL, 'Chị gái tôi rất chuộng thời trang nhưng hiếm khi mua quần áo đắt tiền.', '{"wordId":"fashion","ukIpa":"/ˈfæʃən/","usIpa":"/ˈfæʃən/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"A style of clothing or behaviour popular at a particular time","vi":"thời trang; mốt"},{"pos":"n.","en":"A particular way of doing something","vi":"cách thức; phương thức"},{"pos":"v.","en":"Make or shape something, often using simple materials","vi":"làm; tạo hình"}],"examples":[{"en":"My sister follows fashion but rarely buys expensive clothes.","vi":"Chị gái tôi rất chuộng thời trang nhưng hiếm khi mua quần áo đắt tiền.","audioKind":"ex"},{"en":"The fashion industry can reduce its environmental impact by producing durable clothing and using recycled materials.","vi":"Ngành thời trang có thể giảm thiểu tác động đến môi trường bằng cách sản xuất trang phục bền và sử dụng vật liệu tái chế.","audioKind":"ex2"}],"collocations":[{"en":"in fashion","vi":"đang hợp thời trang"},{"en":"out of fashion","vi":"lỗi mốt"},{"en":"fashion industry","vi":"ngành thời trang"},{"en":"in a similar fashion","vi":"theo cách tương tự"}],"wordFamily":["fashionable (adj.)","fashionably (adv.)","unfashionable (adj.)"],"synonyms":["style","vogue"],"antonyms":[],"tipVi":"Khi diễn tả cách thức, cụm in a... fashion thường được dùng với văn phong trang trọng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_festival', 'en-a2-14', 'festival', '/ˈfestɪvəl/', 'A2', 'lễ hội; ngày hội (dịp đặc biệt mọi người kỷ niệm truyền thống hoặc sự kiện); lễ hội nghệ thuật; chuỗi sự kiện biểu diễn văn hóa', 'n.', 'festive (adj.), festivity (n.)', NULL, 'festival nhấn mạnh vào hoạt động kỷ niệm hoặc chuỗi sự kiện, không nhất thiết là holiday (ngày nghỉ lễ).', 'Our town holds a lantern festival every autumn.', NULL, 'Thị trấn của chúng tôi tổ chức lễ hội đèn lồng vào mỗi mùa thu.', '{"wordId":"festival","ukIpa":"/ˈfestɪvəl/","usIpa":"/ˈfestɪvəl/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"A special occasion when people celebrate a tradition or event","vi":"lễ hội; ngày hội (dịp đặc biệt mọi người kỷ niệm truyền thống hoặc sự kiện)"},{"pos":"n.","en":"An organised series of performances or other cultural events","vi":"lễ hội nghệ thuật; chuỗi sự kiện biểu diễn văn hóa"}],"examples":[{"en":"Our town holds a lantern festival every autumn.","vi":"Thị trấn của chúng tôi tổ chức lễ hội đèn lồng vào mỗi mùa thu.","audioKind":"ex"},{"en":"An annual arts festival can attract visitors while providing local performers with valuable opportunities to reach wider audiences.","vi":"Lễ hội nghệ thuật thường niên có thể thu hút khách du lịch đồng thời mang lại cho các nghệ sĩ biểu diễn địa phương cơ hội quý giá để tiếp cận lượng khán giả rộng lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"celebrate a festival","vi":"kỷ niệm lễ hội"},{"en":"music festival","vi":"lễ hội âm nhạc"},{"en":"film festival","vi":"lễ hội phim"},{"en":"hold a festival","vi":"tổ chức lễ hội"}],"wordFamily":["festive (adj.)","festivity (n.)"],"synonyms":[],"antonyms":[],"tipVi":"festival nhấn mạnh vào hoạt động kỷ niệm hoặc chuỗi sự kiện, không nhất thiết là holiday (ngày nghỉ lễ).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drawing', 'en-a2-14', 'drawing', '/ˈdrɔːɪŋ/', 'A2', 'bức vẽ; bức phác họa; thuật vẽ; kỹ năng vẽ', 'n.', 'draw (v.)', 'Đồng nghĩa: sketch', 'Chỉ một bức tranh là danh từ đếm được; chỉ hoạt động vẽ tranh thường là không đếm được.', 'He showed me a drawing of his cat.', NULL, 'Anh ấy cho tôi xem một bức vẽ con mèo của mình.', '{"wordId":"drawing","ukIpa":"/ˈdrɔːɪŋ/","usIpa":"/ˈdrɔːɪŋ/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"A picture made with a pencil, pen, or similar tool.","vi":"bức vẽ; bức phác họa"},{"pos":"n.","en":"The activity or skill of making pictures with lines.","vi":"thuật vẽ; kỹ năng vẽ"}],"examples":[{"en":"He showed me a drawing of his cat.","vi":"Anh ấy cho tôi xem một bức vẽ con mèo của mình.","audioKind":"ex"},{"en":"Drawing can help children express emotions that they may find difficult to communicate through spoken language.","vi":"Việc vẽ tranh có thể giúp trẻ em thể hiện những cảm xúc mà các em có thể thấy khó truyền đạt bằng ngôn ngữ nói.","audioKind":"ex2"}],"collocations":[{"en":"pencil drawing","vi":"bức vẽ bằng bút chì"},{"en":"drawing skills","vi":"kỹ năng vẽ"},{"en":"drawing class","vi":"lớp học vẽ"}],"wordFamily":["draw (v.)"],"synonyms":["sketch"],"antonyms":[],"tipVi":"Chỉ một bức tranh là danh từ đếm được; chỉ hoạt động vẽ tranh thường là không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_author', 'en-a2-14', 'author', '/ˈɔːθər/', 'A2', 'tác giả; nhà văn; viết; sáng tác', 'n.', 'authorship (n.), coauthor (n.)', 'Đồng nghĩa: writer', 'Cụm "tác giả của..." dùng the author of; từ này cũng có thể làm động từ.', 'The author answered questions about her new adventure novel.', NULL, 'Tác giả đã trả lời các câu hỏi về cuốn tiểu thuyết phiêu lưu mới của cô ấy.', '{"wordId":"author","ukIpa":"/ˈɔːθə/","usIpa":"/ˈɔːθər/","cefr":"A2","topic":"arts","senses":[{"pos":"n.","en":"A person who writes books, articles, or other written works.","vi":"tác giả; nhà văn"},{"pos":"v.","en":"To write a book, report, or other written work.","vi":"viết; sáng tác"}],"examples":[{"en":"The author answered questions about her new adventure novel.","vi":"Tác giả đã trả lời các câu hỏi về cuốn tiểu thuyết phiêu lưu mới của cô ấy.","audioKind":"ex"},{"en":"An author can challenge social attitudes by presenting familiar problems through the experiences of unfamiliar characters.","vi":"Một nhà văn có thể thách thức các quan điểm xã hội bằng cách đặt những vấn đề quen thuộc vào góc nhìn qua trải nghiệm của những nhân vật xa lạ.","audioKind":"ex2"}],"collocations":[{"en":"the author of a novel","vi":"tác giả của một cuốn tiểu thuyết"},{"en":"a bestselling author","vi":"tác giả có sách bán chạy nhất"},{"en":"author a report","vi":"viết một bản báo cáo"}],"wordFamily":["authorship (n.)","coauthor (n.)"],"synonyms":["writer"],"antonyms":[],"tipVi":"Cụm \"tác giả của...\" dùng the author of; từ này cũng có thể làm động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_colourful', 'en-a2-14', 'colourful', '/ˈkʌlərfəl/', 'A2', 'sặc sỡ; rực rỡ; nhiều màu sắc; sinh động; thú vị; phong phú', 'adj.', 'colour (n.), colourfully (adv.), colourless (adj.)', 'Đồng nghĩa: vibrant, vivid · Trái nghĩa: colourless, dull', 'colourful là cách viết theo tiếng Anh-Anh, còn colorful là tiếng Anh-Mỹ.', 'Colourful balloons floated above the tables at the party.', NULL, 'Những quả bóng bay rực rỡ sắc màu bay lơ lửng phía trên các bàn tiệc.', '{"wordId":"colourful","ukIpa":"/ˈkʌləfəl/","usIpa":"/ˈkʌlərfəl/","cefr":"A2","topic":"arts","senses":[{"pos":"adj.","en":"Having many bright colours","vi":"sặc sỡ; rực rỡ; nhiều màu sắc"},{"pos":"adj.","en":"Full of interesting, unusual or exciting details","vi":"sinh động; thú vị; phong phú"}],"examples":[{"en":"Colourful balloons floated above the tables at the party.","vi":"Những quả bóng bay rực rỡ sắc màu bay lơ lửng phía trên các bàn tiệc.","audioKind":"ex"},{"en":"Colourful public murals can transform neglected urban spaces and encourage residents to take pride in their neighbourhoods.","vi":"Những bức bích họa rực rỡ sắc màu nơi công cộng có thể biến đổi các không gian đô thị bị lãng quên và khuyến khích cư dân thêm tự hào về khu0 phố của mình.","audioKind":"ex2"}],"collocations":[{"en":"colourful flowers","vi":"những bông hoa sặc sỡ"},{"en":"a colourful display","vi":"màn trưng bày rực rỡ"},{"en":"a colourful character","vi":"một nhân vật thú vị"},{"en":"a colourful history","vi":"một lịch sử phong phú"}],"wordFamily":["colour (n.)","colourfully (adv.)","colourless (adj.)"],"synonyms":["vibrant","vivid"],"antonyms":["colourless","dull"],"tipVi":"colourful là cách viết theo tiếng Anh-Anh, còn colorful là tiếng Anh-Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_musical', 'en-a2-14', 'musical', '/ˈmjuːzɪkəl/', 'A2', 'thuộc về âm nhạc; có khiếu âm nhạc; vở kịch ca múa nhạc; phim ca nhạc; du dương; êm ái', 'adj.', 'music (n.), musician (n.), musically (adv.), musicality (n.)', NULL, 'Dùng làm tính từ nghĩa là "thuộc về âm nhạc"; dùng làm danh từ đếm được chỉ nhạc kịch.', 'He keeps his musical instruments beside the sofa.', NULL, 'Anh ấy để các nhạc cụ của mình ngay bên cạnh chiếc ghế sofa.', '{"wordId":"musical","ukIpa":"/ˈmjuːzɪkəl/","usIpa":"/ˈmjuːzɪkəl/","cefr":"A2","topic":"arts","senses":[{"pos":"adj.","en":"Relating to music, or showing skill and interest in it.","vi":"thuộc về âm nhạc; có khiếu âm nhạc"},{"pos":"n.","en":"A play or film whose story includes songs and dancing.","vi":"vở kịch ca múa nhạc; phim ca nhạc"},{"pos":"adj.","en":"Having a pleasant sound resembling music.","vi":"du dương; êm ái"}],"examples":[{"en":"He keeps his musical instruments beside the sofa.","vi":"Anh ấy để các nhạc cụ của mình ngay bên cạnh chiếc ghế sofa.","audioKind":"ex"},{"en":"Schools that offer musical training give children valuable opportunities to develop creativity and practise teamwork.","vi":"Các trường học cung cấp đào tạo âm nhạc mang lại cho trẻ em những cơ hội quý giá để phát triển sự sáng tạo và rèn luyện kỹ năng làm việc nhóm.","audioKind":"ex2"}],"collocations":[{"en":"musical instrument","vi":"nhạc cụ"},{"en":"musical talent","vi":"năng khiếu âm nhạc"},{"en":"musical performance","vi":"biểu diễn âm nhạc"},{"en":"a stage musical","vi":"vở nhạc kịch sân khấu"}],"wordFamily":["music (n.)","musician (n.)","musically (adv.)","musicality (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng làm tính từ nghĩa là \"thuộc về âm nhạc\"; dùng làm danh từ đếm được chỉ nhạc kịch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_14_1', 'en-a2-14', 'Cách dùng “gallery” (n.) — phòng trưng bày nghệ thuật; bảo tàng nghệ thuật', 'art gallery  ·  public gallery  ·  photo gallery', 'gallery chủ yếu trưng bày các tác phẩm nghệ thuật; trong khi museum bao trùm phạm vi hiện vật rộng lớn hơn.', NULL, '[{"hanzi":"We spent a rainy afternoon exploring the local gallery.","pinyin":"","meaning":"Chúng tôi đã dành một buổi chiều mưa để khám phá phòng tranh nghệ thuật địa phương."},{"hanzi":"Free entry to a public gallery can make visual art accessible to people from different economic backgrounds.","pinyin":"","meaning":"Việc mở cửa miễn phí cho công chúng vào tham quan các phòng tranh nghệ thuật công cộng giúp cho nghệ thuật thị giác tiếp cận được với những người có hoàn cảnh kinh tế khác nhau."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_14_2', 'en-a2-14', 'Cách dùng “festival” (n.) — lễ hội; ngày hội (dịp đặc biệt mọi người kỷ niệm truyền thống hoặc sự kiện)', 'celebrate a festival  ·  music festival  ·  film festival', 'festival nhấn mạnh vào hoạt động kỷ niệm hoặc chuỗi sự kiện, không nhất thiết là holiday (ngày nghỉ lễ).', 'Họ từ (Word Family): festive (adj.), festivity (n.)', '[{"hanzi":"Our town holds a lantern festival every autumn.","pinyin":"","meaning":"Thị trấn của chúng tôi tổ chức lễ hội đèn lồng vào mỗi mùa thu."},{"hanzi":"An annual arts festival can attract visitors while providing local performers with valuable opportunities to reach wider audiences.","pinyin":"","meaning":"Lễ hội nghệ thuật thường niên có thể thu hút khách du lịch đồng thời mang lại cho các nghệ sĩ biểu diễn địa phương cơ hội quý giá để tiếp cận lượng khán giả rộng lớn hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_14_3', 'en-a2-14', 'Cách dùng “style” (n.) — phong cách, cách thức đặc trưng để làm điều gì đó hoặc bộc lộ ý tưởng', 'writing style  ·  architectural style  ·  in style', 'Từ style có thể chỉ phong cách cá nhân, không nhất thiết phải biểu thị xu hướng thời trang thịnh hành.', 'Họ từ (Word Family): stylish (adj.), stylist (n.), stylistic (adj.), stylishly (adv.) | Đồng nghĩa: manner', '[{"hanzi":"Her colourful paintings have a cheerful, playful style.","pinyin":"","meaning":"Những bức tranh đầy màu sắc của cô ấy mang phong cách vui tươi và nhí nhảnh."},{"hanzi":"Modern architects often adapt traditional building styles to preserve local identity while meeting contemporary housing needs.","pinyin":"","meaning":"Các kiến trúc sư hiện đại thường cải biên phong cách kiến trúc truyền thống nhằm bảo tồn bản sắc địa phương trong khi vẫn đáp ứng nhu cầu nhà ở đương đại."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_14_4', 'en-a2-14', 'Cách dùng “magic” (n.) — phép thuật; trò ảo thuật', 'magic trick  ·  magic wand  ·  magic solution', 'magic thường chỉ phép thuật hoặc ảo thuật; magical cũng có thể dùng để miêu tả trải nghiệm tuyệt vời.', 'Họ từ (Word Family): magical (adj.), magically (adv.), magician (n.) | Đồng nghĩa: sorcery', '[{"hanzi":"The children laughed when he performed a magic trick.","pinyin":"","meaning":"Bọn trẻ đã cười lớn khi anh ấy biểu diễn một màn ảo thuật."},{"hanzi":"Although technology can improve education, it is not a magic solution to every problem schools face.","pinyin":"","meaning":"Mặc dù công nghệ có thể cải thiện giáo dục, nhưng nó không phải là giải pháp kỳ diệu cho mọi vấn đề mà các trường học phải đối mặt."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_14_1', 'en-a2-14', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
