INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_14_1_8', 'ten_a2_14_1', 'comedy', 'We watched a comedy and laughed all evening.', 'We watched a comedy and laughed all evening.', '/ˈkɑːmədi/', 'Chúng tôi xem một bộ phim hài và cười suốt cả buổi tối.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_14_1_1', 'en-a2-14', 'ten_a2_14_1', 'listening', 'listening', 'Her new album kept us singing all afternoon.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những bức tranh đầy màu sắc của cô ấy mang phong cách vui tươi và nhí nhảnh.","Album mới của cô ấy làm chúng tôi hát theo suốt cả buổi chiều.","Những quả bóng bay rực rỡ sắc màu bay lơ lửng phía trên các bàn tiệc.","Chúng tôi ngắm nhìn các nghệ sĩ biểu diễn xiếc tung hứng những quả bóng màu sắc rực rỡ."]'::jsonb, 1, 'Her new album kept us singing all afternoon. → Album mới của cô ấy làm chúng tôi hát theo suốt cả buổi chiều.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_14_1_2', 'en-a2-14', 'ten_a2_14_1', 'listening', 'listening', 'My cousin designed a wooden desk for her bedroom.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi xem một bộ phim hài và cười suốt cả buổi tối.","Anh họ của tôi đã thiết kế một chiếc bàn gỗ cho phòng ngủ của cô ấy.","Chị gái tôi tập chơi đàn vĩ cầm sau bữa tối mỗi tối.","Chúng tôi đã thưởng thức một buổi hòa nhạc ngoài trời tại công viên vào ngày hôm qua."]'::jsonb, 1, 'My cousin designed a wooden desk for her bedroom. → Anh họ của tôi đã thiết kế một chiếc bàn gỗ cho phòng ngủ của cô ấy.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_14_1_3', 'en-a2-14', 'ten_a2_14_1', 'listening', 'listening', 'My sister practises the violin after dinner every evening.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tác giả đã trả lời các câu hỏi về cuốn tiểu thuyết phiêu lưu mới của cô ấy.","Chúng tôi vừa nghe nhạc jazz vừa cùng nhau nấu bữa tối.","Chúng tôi đến nhà hát ngay trước khi vở kịch bắt đầu.","Chị gái tôi tập chơi đàn vĩ cầm sau bữa tối mỗi tối."]'::jsonb, 3, 'My sister practises the violin after dinner every evening. → Chị gái tôi tập chơi đàn vĩ cầm sau bữa tối mỗi tối.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_14_2', 'en-a2-14', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_14_2_1', 'ten_a2_14_2', 'album', 'Digital platforms allow independent musicians to release an album without relying on a traditional record company.', 'Digital platforms allow independent musicians to release an album without relying on a traditional record company.', '/ˈælbəm/', 'Các nền tảng kỹ thuật số cho phép các nghệ sĩ độc lập phát hành album mà không cần phụ thuộc vào một công ty thu âm truyền thống.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_14_2_2', 'ten_a2_14_2', 'design', 'Cities should design public spaces that encourage social interaction while remaining accessible to people with disabilities.', 'Cities should design public spaces that encourage social interaction while remaining accessible to people with disabilities.', '/dɪˈzaɪn/', 'Các thành phố nên thiết kế các không gian công cộng vừa khuyến khích sự tương tác xã hội vừa thuận tiện cho người khuyết tật sử dụng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_14_2_3', 'ten_a2_14_2', 'violin', 'Learning the violin can help children develop concentration, although regular lessons may be expensive for some families.', 'Learning the violin can help children develop concentration, although regular lessons may be expensive for some families.', '/ˌvaɪəˈlɪn/', 'Việc học đàn vĩ cầm có thể giúp trẻ em phát triển khả năng tập trung, mặc dù các buổi học đều đặn có thể tốn kém đối với một số gia đình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_14_2_4', 'ten_a2_14_2', 'designer', 'A skilled designer can make public spaces more accessible to people with limited mobility.', 'A skilled designer can make public spaces more accessible to people with limited mobility.', '/dɪˈzaɪnər/', 'Một nhà thiết kế tay nghề cao có thể giúp không gian công cộng trở nên thuận tiện hơn cho những người bị hạn chế về khả năng di chuyển.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_14_2_5', 'ten_a2_14_2', 'style', 'Modern architects often adapt traditional building styles to preserve local identity while meeting contemporary housing needs.', 'Modern architects often adapt traditional building styles to preserve local identity while meeting contemporary housing needs.', '/staɪl/', 'Các kiến trúc sư hiện đại thường cải biên phong cách kiến trúc truyền thống nhằm bảo tồn bản sắc địa phương trong khi vẫn đáp ứng nhu cầu nhà ở đương đại.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_14_2_6', 'ten_a2_14_2', 'musician', 'Local musicians can strengthen community identity by performing traditional songs at public festivals and cultural events.', 'Local musicians can strengthen community identity by performing traditional songs at public festivals and cultural events.', '/mjuˈzɪʃən/', 'Các nhạc công địa phương có thể củng cố bản sắc cộng đồng bằng cách trình bày các bài hát truyền thống trong các lễ hội công cộng và sự kiện văn hóa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_14_2_1', 'en-a2-14', 'ten_a2_14_2', 'listening', 'listening', 'Digital platforms allow independent musicians to release an album without relying on a traditional record company.', NULL, 'Trong câu vừa nghe, từ “album” mang nghĩa nào sau đây?', '["cần thiết; thiết yếu","cộng sự; đối tác; người cùng chơi","album nhạc; đĩa nhạc","tình hình; hoàn cảnh; tình thế"]'::jsonb, 2, '“album” (/ˈælbəm/): album nhạc; đĩa nhạc. Câu đầy đủ: Digital platforms allow independent musicians to release an album without relying on a traditional record company.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_14_2_2', 'en-a2-14', 'ten_a2_14_2', 'listening', 'listening', 'Cities should design public spaces that encourage social interaction while remaining accessible to people with disabilities.', NULL, 'Trong câu vừa nghe, từ “design” mang nghĩa nào sau đây?', '["lễ hội; ngày hội (dịp đặc biệt mọi người kỷ niệm truyền thống hoặc sự kiện)","sếp; thủ trưởng; ông chủ","thiết kế; phác thảo","thế kỷ; một trăm năm"]'::jsonb, 2, '“design” (/dɪˈzaɪn/): thiết kế; phác thảo. Câu đầy đủ: Cities should design public spaces that encourage social interaction while remaining accessible to people with disabilities.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
