INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_2', 'en-a2-14', NULL, 'comprehensive_test', 'listening', 'My cousin designed a wooden desk for her bedroom.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những bức tranh đầy màu sắc của cô ấy mang phong cách vui tươi và nhí nhảnh.","Album mới của cô ấy làm chúng tôi hát theo suốt cả buổi chiều.","Anh họ của tôi đã thiết kế một chiếc bàn gỗ cho phòng ngủ của cô ấy.","Chúng tôi vừa nghe nhạc jazz vừa cùng nhau nấu bữa tối."]'::jsonb, 2, 'My cousin designed a wooden desk for her bedroom. → Anh họ của tôi đã thiết kế một chiếc bàn gỗ cho phòng ngủ của cô ấy.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
