INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_4', 'en-a2-14', NULL, 'comprehensive_test', 'listening', 'The designer showed us a model of our kitchen.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh ấy để các nhạc cụ của mình ngay bên cạnh chiếc ghế sofa.","Chúng tôi xem một bộ phim hài và cười suốt cả buổi tối.","Nhà thiết kế đã cho chúng tôi xem mô hình phòng bếp của mình.","Chúng tôi đã làm một con chim đầy màu sắc từ giấy gấp."]'::jsonb, 2, 'The designer showed us a model of our kitchen. → Nhà thiết kế đã cho chúng tôi xem mô hình phòng bếp của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_5', 'en-a2-14', NULL, 'comprehensive_test', 'listening', 'style', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trang chủ (của một trang web)","khắp mọi nơi; đâu đâu cũng có","củ tỏi; tép tỏi","phong cách, cách thức đặc trưng để làm điều gì đó hoặc bộc lộ ý tưởng"]'::jsonb, 3, 'style (/staɪl/) → phong cách, cách thức đặc trưng để làm điều gì đó hoặc bộc lộ ý tưởng; kiểu dáng, mẫu thiết kế hoặc vẻ ngoài hợp thời trang; tạo kiểu, thiết kế kiểu dáng cho thứ gì đó để đạt được vẻ ngoài như ý', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_6', 'en-a2-14', NULL, 'comprehensive_test', 'listening', 'A musician played the violin outside the station.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Album mới của cô ấy làm chúng tôi hát theo suốt cả buổi chiều.","Chúng tôi đến nhà hát ngay trước khi vở kịch bắt đầu.","Chị gái tôi tập chơi đàn vĩ cầm sau bữa tối mỗi tối.","Một nhạc công đang chơi đàn vĩ cầm ở bên ngoài nhà ga."]'::jsonb, 3, 'A musician played the violin outside the station. → Một nhạc công đang chơi đàn vĩ cầm ở bên ngoài nhà ga.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_7', 'en-a2-14', NULL, 'comprehensive_test', 'listening', 'painter', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quán rượu; quán pub","sự sợ hãi; nỗi sợ","trực tuyến; ở trên mạng","họa sĩ"]'::jsonb, 3, 'painter (/ˈpeɪntər/) → họa sĩ; thợ sơn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_8', 'en-a2-14', NULL, 'comprehensive_test', 'listening', 'We watched a comedy and laughed all evening.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Thị trấn của chúng tôi tổ chức lễ hội đèn lồng vào mỗi mùa thu.","Bọn trẻ đã cười lớn khi anh ấy biểu diễn một màn ảo thuật.","Chúng tôi xem một bộ phim hài và cười suốt cả buổi tối.","Nữ họa sĩ pha màu xanh dương và xanh lá trên bảng màu của cô ấy."]'::jsonb, 2, 'We watched a comedy and laughed all evening. → Chúng tôi xem một bộ phim hài và cười suốt cả buổi tối.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_9', 'en-a2-14', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A distinctive way of doing something or expressing ideas.”?', '["musician","style","fashion","clap"]'::jsonb, 1, 'style (/staɪl/) → phong cách, cách thức đặc trưng để làm điều gì đó hoặc bộc lộ ý tưởng', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_10', 'en-a2-14', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “someone who plays music, especially professionally”?', '["album","colourful","musician","festival"]'::jsonb, 2, 'musician (/mjuˈzɪʃən/) → nhạc công; nghệ sĩ âm nhạc; nhạc sĩ', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_11', 'en-a2-14', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Someone who creates pictures using paint.”?', '["gallery","painter","author","create"]'::jsonb, 1, 'painter (/ˈpeɪntər/) → họa sĩ', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_12', 'en-a2-14', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Entertainment intended to make people laugh.”?', '["ending","comedy","festival","drama"]'::jsonb, 1, 'comedy (/ˈkɑːmədi/) → hài kịch; phim hài', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
