INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_18', 'en-a2-14', NULL, 'comprehensive_test', 'reading', NULL, 'Digital platforms allow independent musicians to release an album without relying on a traditional record company.', 'Dựa vào câu trên, từ “album” có nghĩa phù hợp nhất là gì?', '["nút; nút bấm","dùng với I hoặc we để đề nghị hoặc gợi ý điều gì đó","album nhạc; đĩa nhạc","tăng; làm tăng"]'::jsonb, 2, 'album: album nhạc; đĩa nhạc; album ảnh; sách sưu tầm tem. Dịch cả câu: Các nền tảng kỹ thuật số cho phép các nghệ sĩ độc lập phát hành album mà không cần phụ thuộc vào một công ty thu âm truyền thống.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_19', 'en-a2-14', NULL, 'comprehensive_test', 'reading', NULL, 'Cities should design public spaces that encourage social interaction while remaining accessible to people with disabilities.', 'Dựa vào câu trên, từ “design” có nghĩa phù hợp nhất là gì?', '["phát hiện; tìm ra","sữa chua","thiết kế; phác thảo","tự nhiên; thiên nhiên"]'::jsonb, 2, 'design: thiết kế; phác thảo; bản thiết kế; kiểu dáng; họa tiết trang trí. Dịch cả câu: Các thành phố nên thiết kế các không gian công cộng vừa khuyến khích sự tương tác xã hội vừa thuận tiện cho người khuyết tật sử dụng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_20', 'en-a2-14', NULL, 'comprehensive_test', 'reading', NULL, 'Learning the violin can help children develop concentration, although regular lessons may be expensive for some families.', 'Dựa vào câu trên, từ “violin” có nghĩa phù hợp nhất là gì?', '["móng tay; móng chân","được chiên; được rán bằng dầu mỡ","nhiệt độ; khí hậu; thân nhiệt","đàn vĩ cầm; đàn violon"]'::jsonb, 3, 'violin: đàn vĩ cầm; đàn violon. Dịch cả câu: Việc học đàn vĩ cầm có thể giúp trẻ em phát triển khả năng tập trung, mặc dù các buổi học đều đặn có thể tốn kém đối với một số gia đình.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_21', 'en-a2-14', NULL, 'comprehensive_test', 'reading', NULL, 'A skilled designer can make public spaces more accessible to people with limited mobility.', 'Dựa vào câu trên, từ “designer” có nghĩa phù hợp nhất là gì?', '["quả dưa (dưa gang, dưa lưới...)","cứu; cứu sống; bảo vệ","người thiết kế; nhà thiết kế","việc lái xe; kỹ năng lái xe"]'::jsonb, 2, 'designer: người thiết kế; nhà thiết kế; hàng hiệu thiết kế. Dịch cả câu: Một nhà thiết kế tay nghề cao có thể giúp không gian công cộng trở nên thuận tiện hơn cho những người bị hạn chế về khả năng di chuyển.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_22', 'en-a2-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tác giả; nhà văn”', '["rose","author","fix","modern"]'::jsonb, 1, 'tác giả; nhà văn → author (/ˈɔːθər/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_23', 'en-a2-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sặc sỡ; rực rỡ; nhiều màu sắc”', '["unhappy","cross","trainer","colourful"]'::jsonb, 3, 'sặc sỡ; rực rỡ; nhiều màu sắc → colourful (/ˈkʌlərfəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_14_24', 'en-a2-14', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc về âm nhạc; có khiếu âm nhạc”', '["fresh","musical","difference","jogging"]'::jsonb, 1, 'thuộc về âm nhạc; có khiếu âm nhạc → musical (/ˈmjuːzɪkəl/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-15', 'en', 'Bài 15: Tư duy & Nhận thức (1) - CEFR A2', 'CEFR A2', 'A2 · Tư duy', '22 từ vựng Tiếng Anh CEFR A2 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2015, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_result', 'en-a2-15', 'result', '/rɪˈzʌlt/', 'A2', 'kết quả; hậu quả; kết quả thi; thành tích; dẫn đến; do', 'n.', 'resulting (adj.)', 'Đồng nghĩa: outcome, consequence', 'result in đi kèm kết quả phía sau; result from đi kèm nguyên nhân phía sau.', 'The shiny floor was the result of hours of cleaning.', NULL, 'Sàn nhà sáng bóng là thành quả của hàng giờ dọn dẹp.', '{"wordId":"result","ukIpa":"/rɪˈzʌlt/","usIpa":"/rɪˈzʌlt/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"something that happens because of an action or event","vi":"kết quả; hậu quả"},{"pos":"n.","en":"the final score or outcome of a test or competition","vi":"kết quả thi; thành tích"},{"pos":"v.","en":"to happen because of something or cause something to happen","vi":"dẫn đến; do"}],"examples":[{"en":"The shiny floor was the result of hours of cleaning.","vi":"Sàn nhà sáng bóng là thành quả của hàng giờ dọn dẹp.","audioKind":"ex"},{"en":"Investing in reliable public transport can result in lower emissions and shorter commuting times for urban residents.","vi":"Đầu tư vào hệ thống giao thông công cộng đáng tin cậy có thể giúp giảm lượng khí thải và rút ngắn thời gian di chuyển cho cư dân đô thị.","audioKind":"ex2"}],"collocations":[{"en":"as a result","vi":"kết quả là"},{"en":"result in","vi":"dẫn đến"},{"en":"result from","vi":"bắt nguồn từ"},{"en":"exam results","vi":"kết quả thi đấu"}],"wordFamily":["resulting (adj.)"],"synonyms":["outcome","consequence"],"antonyms":[],"tipVi":"result in đi kèm kết quả phía sau; result from đi kèm nguyên nhân phía sau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_definitely', 'en-a2-15', 'definitely', '/ˈdefɪnətli/', 'A2', 'chắc chắn; dứt khoát; rạch ròi', 'adv.', 'definite (adj.), definiteness (n.)', 'Đồng nghĩa: certainly, undoubtedly · Trái nghĩa: possibly', 'Được đánh vần là definitely; đừng nhầm lẫn với defiantly.', 'I will definitely bring an umbrella after yesterday''s rain.', NULL, 'Tôi chắc chắn sẽ mang theo ô sau trận mưa ngày hôm qua.', '{"wordId":"definitely","ukIpa":"/ˈdefɪnətli/","usIpa":"/ˈdefɪnətli/","cefr":"A2","topic":"thinking","senses":[{"pos":"adv.","en":"certainly, with no doubt about something","vi":"chắc chắn; dứt khoát; rạch ròi"}],"examples":[{"en":"I will definitely bring an umbrella after yesterday''s rain.","vi":"Tôi chắc chắn sẽ mang theo ô sau trận mưa ngày hôm qua.","audioKind":"ex"},{"en":"Improved insulation will definitely reduce heat loss, although total energy savings depend on household behaviour.","vi":"Cải thiện khả năng cách nhiệt chắc chắn sẽ làm giảm thất thoát nhiệt, mặc dù mức tiết kiệm năng lượng tổng thể còn phụ thuộc vào hành vi của các hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"definitely worth","vi":"hoàn toàn đáng"},{"en":"definitely agree","vi":"hoàn toàn đồng ý"},{"en":"definitely not","vi":"chắc chắn là không"}],"wordFamily":["definite (adj.)","definiteness (n.)"],"synonyms":["certainly","undoubtedly"],"antonyms":["possibly"],"tipVi":"Được đánh vần là definitely; đừng nhầm lẫn với defiantly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_difference', 'en-a2-15', 'difference', '/ˈdɪfrəns/', 'A2', 'sự khác biệt; điểm khác nhau; sự bất đồng; mối bất hòa; số dư; khoảng chênh lệch', 'n.', 'different (adj.), differ (v.), differently (adv.), differentiate (v.)', 'Đồng nghĩa: distinction, dissimilarity · Trái nghĩa: similarity', 'Khi so sánh giữa hai đối tượng, hãy dùng the difference between A and B.', 'The main difference between these jackets is their weight.', NULL, 'Điểm khác biệt chính giữa những chiếc áo khoác này là trọng lượng của chúng.', '{"wordId":"difference","ukIpa":"/ˈdɪfrəns/","usIpa":"/ˈdɪfrəns/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"A way in which people or things are not alike","vi":"sự khác biệt; điểm khác nhau"},{"pos":"n.","en":"A disagreement between people or groups","vi":"sự bất đồng; mối bất hòa"},{"pos":"n.","en":"The amount by which one quantity exceeds another","vi":"số dư; khoảng chênh lệch"}],"examples":[{"en":"The main difference between these jackets is their weight.","vi":"Điểm khác biệt chính giữa những chiếc áo khoác này là trọng lượng của chúng.","audioKind":"ex"},{"en":"Understanding cultural differences can help international students adapt more successfully to life in a new country.","vi":"Việc thấu hiểu các khác biệt về văn hóa có thể giúp du học sinh thích nghi thành công hơn với cuộc sống ở một đất nước mới.","audioKind":"ex2"}],"collocations":[{"en":"the difference between","vi":"sự khác biệt giữa"},{"en":"make a difference","vi":"tạo ra sự khác biệt"},{"en":"a significant difference","vi":"sự khác biệt đáng kể"},{"en":"settle differences","vi":"giải quyết bất đồng"}],"wordFamily":["different (adj.)","differ (v.)","differently (adv.)","differentiate (v.)"],"synonyms":["distinction","dissimilarity"],"antonyms":["similarity"],"tipVi":"Khi so sánh giữa hai đối tượng, hãy dùng the difference between A and B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_however', 'en-a2-15', 'however', '/haʊˈevər/', 'A2', 'tuy nhiên; song; dù... đến đâu; dù theo bất kỳ cách nào', 'adv.', NULL, 'Đồng nghĩa: nevertheless, nonetheless', 'Khi dùng với nghĩa chuyển ý, đây không phải là liên từ đẳng lập; tuyệt đối không nối hai câu đơn chỉ bằng dấu phẩy.', 'The jacket looked warm; however, it felt surprisingly thin.', NULL, 'Chiếc áo khoác trông có vẻ ấm áp; tuy nhiên, nó lại mỏng một cách đáng ngạc nhiên.', '{"wordId":"however","ukIpa":"/haʊˈevə/","usIpa":"/haʊˈevər/","cefr":"A2","topic":"thinking","senses":[{"pos":"adv.","en":"Used to introduce a contrasting statement.","vi":"tuy nhiên; song"},{"pos":"adv.","en":"No matter how much or to what degree.","vi":"dù... đến đâu"},{"pos":"conj.","en":"In any way that someone chooses.","vi":"dù theo bất kỳ cách nào"}],"examples":[{"en":"The jacket looked warm; however, it felt surprisingly thin.","vi":"Chiếc áo khoác trông có vẻ ấm áp; tuy nhiên, nó lại mỏng một cách đáng ngạc nhiên.","audioKind":"ex"},{"en":"Online courses offer greater flexibility; however, some learners benefit more from direct interaction with teachers.","vi":"Các khóa học trực tuyến mang lại sự linh hoạt lớn hơn; tuy nhiên, một số người học lại thu được nhiều lợi ích hơn từ việc tương tác trực tiếp với giáo viên.","audioKind":"ex2"}],"collocations":[{"en":"however difficult","vi":"dù khó khăn đến đâu"},{"en":"however much","vi":"dù bao nhiêu"},{"en":"however hard you try","vi":"dù bạn có cố gắng đến đâu"}],"wordFamily":[],"synonyms":["nevertheless","nonetheless"],"antonyms":[],"tipVi":"Khi dùng với nghĩa chuyển ý, đây không phải là liên từ đẳng lập; tuyệt đối không nối hai câu đơn chỉ bằng dấu phẩy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stupid', 'en-a2-15', 'stupid', '/ˈstuːpɪd/', 'A2', 'ngu ngốc; khờ khạo; kém suy nghĩ', 'adj.', 'stupidity (n.), stupidly (adv.)', 'Đồng nghĩa: foolish, silly · Trái nghĩa: sensible, intelligent', 'Trực tiếp gọi ai đó là stupid mang tính xúc phạm, nên tránh khi nhận xét về con người.', 'It was stupid to leave my umbrella at home.', NULL, 'Để quên ô ở nhà thật là ngốc.', '{"wordId":"stupid","ukIpa":"/ˈstjuːpɪd/","usIpa":"/ˈstuːpɪd/","cefr":"A2","topic":"thinking","senses":[{"pos":"adj.","en":"Showing poor judgment or a lack of sensible thought.","vi":"ngu ngốc; khờ khạo; kém suy nghĩ"}],"examples":[{"en":"It was stupid to leave my umbrella at home.","vi":"Để quên ô ở nhà thật là ngốc.","audioKind":"ex"},{"en":"Calling students stupid can damage their confidence and discourage them from asking questions in class.","vi":"Việc gọi học sinh là ngốc nghếch có thể làm tổn thương sự tự tin của các em và khiến các em ngại đặt câu hỏi trong lớp.","audioKind":"ex2"}],"collocations":[{"en":"a stupid mistake","vi":"một sai lầm ngốc nghếch"},{"en":"a stupid idea","vi":"một ý tưởng ngốc nghếch"},{"en":"feel stupid","vi":"cảm thấy mình thật ngốc"}],"wordFamily":["stupidity (n.)","stupidly (adv.)"],"synonyms":["foolish","silly"],"antonyms":["sensible","intelligent"],"tipVi":"Trực tiếp gọi ai đó là stupid mang tính xúc phạm, nên tránh khi nhận xét về con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_interest', 'en-a2-15', 'interest', '/ˈɪntrəst/', 'A2', 'sự quan tâm; niềm thích thú; lãi suất; tiền lãi; làm quan tâm; gây chú ý', 'n.', 'interested (adj.), interesting (adj.), interestingly (adv.)', NULL, 'Sự quan tâm dùng interest in; sở thích cụ thể có thể dùng số nhiều interests.', 'My interest in cooking began in my grandmother''s kitchen.', NULL, 'Niềm yêu thích nấu nướng của tôi bắt đầu từ căn bếp của bà tôi.', '{"wordId":"interest","ukIpa":"/ˈɪntrəst/","usIpa":"/ˈɪntrəst/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"a desire to learn about or become involved in something","vi":"sự quan tâm; niềm thích thú"},{"pos":"n.","en":"money paid for borrowing money or earned on savings","vi":"lãi suất; tiền lãi"},{"pos":"v.","en":"to make someone want to know or learn more","vi":"làm quan tâm; gây chú ý"}],"examples":[{"en":"My interest in cooking began in my grandmother''s kitchen.","vi":"Niềm yêu thích nấu nướng của tôi bắt đầu từ căn bếp của bà tôi.","audioKind":"ex"},{"en":"Schools can stimulate interest in science by giving students opportunities to conduct experiments and explore practical problems.","vi":"Nhà trường có thể khơi 1 gợi sự quan tâm đến khoa học bằng cách cho học sinh cơ hội tiến hành thí nghiệm và khám phá các vấn đề thực tế.","audioKind":"ex2"}],"collocations":[{"en":"take an interest in","vi":"tỏ ra quan tâm đến"},{"en":"stimulate interest","vi":"kích thích sự quan tâm"},{"en":"interest rate","vi":"lãi suất"},{"en":"pay interest","vi":"trả tiền lãi"}],"wordFamily":["interested (adj.)","interesting (adj.)","interestingly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Sự quan tâm dùng interest in; sở thích cụ thể có thể dùng số nhiều interests.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mean', 'en-a2-15', 'mean', '/miːn/', 'A2', 'có nghĩa là; ngụ ý; định; keo kiệt; độc ác; bủn xỉn; số trung bình', 'v.', 'meaning (n.), meaningful (adj.), meaningless (adj.), meanness (n.)', NULL, 'mean to do có nghĩa là "định làm"; mean doing có nghĩa là "có nghĩa là làm".', 'I didn''t mean to leave you waiting outside.', NULL, 'Tôi không cố ý để bạn phải đợi bên ngoài đâu.', '{"wordId":"mean","ukIpa":"/miːn/","usIpa":"/miːn/","cefr":"A2","topic":"thinking","senses":[{"pos":"v.","en":"to express, involve, or intend something","vi":"có nghĩa là; ngụ ý; định"},{"pos":"adj.","en":"unkind or unwilling to share or spend money","vi":"keo kiệt; độc ác; bủn xỉn"},{"pos":"n.","en":"the total of several values divided by how many exist","vi":"số trung bình"}],"examples":[{"en":"I didn''t mean to leave you waiting outside.","vi":"Tôi không cố ý để bạn phải đợi bên ngoài đâu.","audioKind":"ex"},{"en":"Higher energy prices may mean that low-income households have less money available for other essential needs.","vi":"Giá năng lượng tăng cao có thể có nghĩa là các hộ gia đình thu nhập thấp có ít tiền hơn dành cho các nhu cầu thiết yếu khác.","audioKind":"ex2"}],"collocations":[{"en":"mean to do something","vi":"định làm gì đó"},{"en":"mean doing something","vi":"có nghĩa là làm gì đó"},{"en":"mean value","vi":"giá trị trung bình"},{"en":"be mean to someone","vi":"đối xử tệ với ai đó"}],"wordFamily":["meaning (n.)","meaningful (adj.)","meaningless (adj.)","meanness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"mean to do có nghĩa là \"định làm\"; mean doing có nghĩa là \"có nghĩa là làm\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dream', 'en-a2-15', 'dream', '/driːm/', 'A2', 'giấc mơ; giấc mộng; ước mơ; hoài bão; mơ; mơ mộng', 'n.', 'dreamer (n.), dreamy (adj.), dreamless (adj.)', NULL, 'dream of/about theo sau bởi danh từ hoặc danh từ chỉ hành động; dạng quá khứ có thể dùng dreamt hoặc dreamed.', 'Last night, I had a dream about flying over mountains.', NULL, 'Tối qua, tôi mơ thấy mình đang bay lượn trên những ngọn núi.', '{"wordId":"dream","ukIpa":"/driːm/","usIpa":"/driːm/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"images, feelings, and events experienced while sleeping","vi":"giấc mơ; giấc mộng"},{"pos":"n.","en":"something you strongly hope to achieve or experience","vi":"ước mơ; hoài bão"},{"pos":"v.","en":"to experience dreams while sleeping or imagine something you want","vi":"mơ; mơ mộng"}],"examples":[{"en":"Last night, I had a dream about flying over mountains.","vi":"Tối qua, tôi mơ thấy mình đang bay lượn trên những ngọn núi.","audioKind":"ex"},{"en":"Access to affordable education allows more young people to pursue their dream of entering a skilled profession.","vi":"Khả năng tiếp cận giáo dục với chi phí hợp lý cho phép nhiều người trẻ tuổi theo đuổi ước mơ bước chân vào một ngành nghề chuyên môn.","audioKind":"ex2"}],"collocations":[{"en":"have a dream","vi":"mơ một giấc mơ"},{"en":"pursue a dream","vi":"theo đuổi ước mơ"},{"en":"dream of becoming","vi":"mơ ước trở thành"},{"en":"a dream come true","vi":"giấc mơ trở thành sự thật"}],"wordFamily":["dreamer (n.)","dreamy (adj.)","dreamless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"dream of/about theo sau bởi danh từ hoặc danh từ chỉ hành động; dạng quá khứ có thể dùng dreamt hoặc dreamed.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_choice', 'en-a2-15', 'choice', '/tʃɔɪs/', 'A2', 'sự lựa chọn; quyền lựa chọn; sự lựa chọn có sẵn; phạm vi tùy chọn; chất lượng cao; thượng hạng', 'n.', 'choose (v.), choosy (adj.)', 'Đồng nghĩa: option, selection', 'choice là danh từ, choose là động từ; chọn làm việc gì dùng choose to do.', 'You have a choice between soup and salad.', NULL, 'Bạn có thể chọn giữa súp và xà lách.', '{"wordId":"choice","ukIpa":"/tʃɔɪs/","usIpa":"/tʃɔɪs/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"the act or freedom of choosing between different possibilities","vi":"sự lựa chọn; quyền lựa chọn"},{"pos":"n.","en":"something you can choose, or the range of available options","vi":"sự lựa chọn có sẵn; phạm vi tùy chọn"},{"pos":"adj.","en":"of especially good quality","vi":"chất lượng cao; thượng hạng"}],"examples":[{"en":"You have a choice between soup and salad.","vi":"Bạn có thể chọn giữa súp và xà lách.","audioKind":"ex"},{"en":"Reliable public transport gives commuters a wider choice and reduces their dependence on private cars.","vi":"Hệ thống giao thông công cộng đáng tin cậy mang lại cho người đi làm nhiều lựa chọn hơn và giảm sự phụ thuộc của họ vào xe hơi cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"make a choice","vi":"đưa ra lựa chọn"},{"en":"have no choice","vi":"không còn sự lựa chọn nào khác"},{"en":"a wide choice of","vi":"nhiều sự lựa chọn đa dạng"},{"en":"freedom of choice","vi":"quyền tự do lựa chọn"}],"wordFamily":["choose (v.)","choosy (adj.)"],"synonyms":["option","selection"],"antonyms":[],"tipVi":"choice là danh từ, choose là động từ; chọn làm việc gì dùng choose to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_point', 'en-a2-15', 'point', '/pɔɪnt/', 'A2', 'quan điểm; ý chính; điểm nhọn; đầu nhọn; chỉ; trỏ', 'n.', 'pointed (adj.), pointless (adj.), pointer (n.)', NULL, 'make a point là đưa ra quan điểm; point at là chỉ tay về phía cái gì.', 'You made a good point about sharing the kitchen.', NULL, 'Bạn đã đưa ra một ý kiến rất hay về việc chia sẻ không gian bếp chung.', '{"wordId":"point","ukIpa":"/pɔɪnt/","usIpa":"/pɔɪnt/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"an idea or detail expressed in speech or writing","vi":"quan điểm; ý chính"},{"pos":"n.","en":"the sharp, narrow end of something","vi":"điểm nhọn; đầu nhọn"},{"pos":"v.","en":"show a direction or object with a finger or tool","vi":"chỉ; trỏ"}],"examples":[{"en":"You made a good point about sharing the kitchen.","vi":"Bạn đã đưa ra một ý kiến rất hay về việc chia sẻ không gian bếp chung.","audioKind":"ex"},{"en":"The main point of this argument is that education should remain accessible to everyone.","vi":"Luận điểm chính của bài tranh luận này là giáo dục nên tiếp cận được với tất cả mọi người.","audioKind":"ex2"}],"collocations":[{"en":"make a point","vi":"nêu quan điểm"},{"en":"main point","vi":"ý chính"},{"en":"point of view","vi":"quan điểm; góc nhìn"},{"en":"point at something","vi":"chỉ tay vào cái gì"}],"wordFamily":["pointed (adj.)","pointless (adj.)","pointer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"make a point là đưa ra quan điểm; point at là chỉ tay về phía cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seem', 'en-a2-15', 'seem', '/siːm/', 'A2', 'dường như; có vẻ như', 'v.', 'seeming (adj.), seemingly (adv.)', 'Đồng nghĩa: appear', 'Thường dùng seem cộng với tính từ hoặc seem to do, không mang nghĩa giả vờ.', 'You seem tired after your long walk home.', NULL, 'Bạn có vẻ mệt mỏi sau quãng đường đi bộ dài về nhà.', '{"wordId":"seem","ukIpa":"/siːm/","usIpa":"/siːm/","cefr":"A2","topic":"thinking","senses":[{"pos":"v.","en":"To appear to be a certain way.","vi":"dường như; có vẻ như"}],"examples":[{"en":"You seem tired after your long walk home.","vi":"Bạn có vẻ mệt mỏi sau quãng đường đi bộ dài về nhà.","audioKind":"ex"},{"en":"Although online courses seem convenient, some learners benefit more from direct interaction with teachers and classmates.","vi":"Mặc dù các khóa học trực tuyến có vẻ tiện lợi, một số người học vẫn thu được lợi ích nhiều hơn từ sự tương tác trực tiếp với giáo viên và bạn cùng lớp.","audioKind":"ex2"}],"collocations":[{"en":"seem likely","vi":"dường như có khả năng"},{"en":"seem to be","vi":"dường như là"},{"en":"it seems that","vi":"có vẻ như là"}],"wordFamily":["seeming (adj.)","seemingly (adv.)"],"synonyms":["appear"],"antonyms":[],"tipVi":"Thường dùng seem cộng với tính từ hoặc seem to do, không mang nghĩa giả vờ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_guess', 'en-a2-15', 'guess', '/ɡes/', 'A2', 'đoán; phỏng đoán; sự phỏng đoán; ý kiến phỏng đoán; nghĩ rằng; đoán chừng', 'v.', 'guesswork (n.)', 'Đồng nghĩa: estimate, suppose', 'Cụm I guess thường dùng trong văn nói mang tính phỏng đoán, phỏng chừng và không chắc chắn hoàn toàn.', 'Can you guess what is inside this little box?', NULL, 'Bạn có đoán được bên trong chiếc hộp nhỏ này có gì không?', '{"wordId":"guess","ukIpa":"/ɡes/","usIpa":"/ɡes/","cefr":"A2","topic":"thinking","senses":[{"pos":"v.","en":"To give an answer without having enough information to be certain.","vi":"đoán; phỏng đoán"},{"pos":"n.","en":"An answer or opinion given without being certain.","vi":"sự phỏng đoán; ý kiến phỏng đoán"},{"pos":"v.","en":"To think something is probably true, without being completely sure.","vi":"nghĩ rằng; đoán chừng"}],"examples":[{"en":"Can you guess what is inside this little box?","vi":"Bạn có đoán được bên trong chiếc hộp nhỏ này có gì không?","audioKind":"ex"},{"en":"Without reliable data, researchers can only guess how changes in transport costs will affect household spending.","vi":"Khi thiếu dữ liệu đáng tin cậy, các nhà nghiên cứu chỉ có thể phỏng đoán sự thay đổi chi phí vận chuyển sẽ ảnh hưởng như thế nào đến chi tiêu của các hộ gia đình.","audioKind":"ex2"}],"collocations":[{"en":"make a guess","vi":"đưa ra phỏng đoán"},{"en":"an educated guess","vi":"phỏng đoán có cơ sở"},{"en":"guess correctly","vi":"đoán đúng"}],"wordFamily":["guesswork (n.)"],"synonyms":["estimate","suppose"],"antonyms":[],"tipVi":"Cụm I guess thường dùng trong văn nói mang tính phỏng đoán, phỏng chừng và không chắc chắn hoàn toàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_false', 'en-a2-15', 'FALSE', '/fɔːls/', 'A2', 'sai; không có thật; giả; nhân tạo; giả tạo; không chân thành', 'adj.', 'falsely (adv.), falsehood (n.), falsify (v.)', 'Đồng nghĩa: untrue, incorrect · Trái nghĩa: true, genuine', 'false mang nghĩa không đúng sự thật; fake nhấn mạnh việc làm giả, nhái tinh vi. Từ này thường được viết ở dạng chữ thường.', 'That rumour about our neighbour is completely FALSE.', NULL, 'Tin đồn về người hàng xóm của chúng ta hoàn toàn không đúng sự thật.', '{"wordId":"false","ukIpa":"/fɔːls/","usIpa":"/fɔːls/","cefr":"A2","topic":"thinking","senses":[{"pos":"adj.","en":"not true or based on facts","vi":"sai; không có thật"},{"pos":"adj.","en":"made to resemble something real or natural","vi":"giả; nhân tạo"},{"pos":"adj.","en":"intended to hide someone''s real feelings or intentions","vi":"giả tạo; không chân thành"}],"examples":[{"en":"That rumour about our neighbour is completely FALSE.","vi":"Tin đồn về người hàng xóm của chúng ta hoàn toàn không đúng sự thật.","audioKind":"ex"},{"en":"Claims that all online information is reliable are FALSE, so students should learn to evaluate sources critically.","vi":"Những khẳng định cho rằng tất cả thông tin trực tuyến đều đáng tin cậy là sai sự thật, vì vậy học sinh nên học cách đánh giá các nguồn thông tin một cách phản biện.","audioKind":"ex2"}],"collocations":[{"en":"false information","vi":"thông tin sai lệch"},{"en":"false impression","vi":"ấn tượng sai lầm"},{"en":"false alarm","vi":"báo động giả"},{"en":"false teeth","vi":"răng giả"}],"wordFamily":["falsely (adv.)","falsehood (n.)","falsify (v.)"],"synonyms":["untrue","incorrect"],"antonyms":["true","genuine"],"tipVi":"false mang nghĩa không đúng sự thật; fake nhấn mạnh việc làm giả, nhái tinh vi. Từ này thường được viết ở dạng chữ thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_memory', 'en-a2-15', 'memory', '/ˈmeməri/', 'A2', 'trí nhớ; khả năng ghi nhớ; hồi ức; ký ức; bộ nhớ máy tính; dung lượng lưu trữ', 'n.', 'memorise (v.), memorable (adj.)', 'Đồng nghĩa: recollection, recall', 'Trí nhớ thường không đếm được; từng khoảng thời gian ký ức dùng memories.', 'My grandmother has an excellent memory for faces.', NULL, 'Bà tôi có trí nhớ cực kỳ tốt với khuôn mặt mọi người.', '{"wordId":"memory","ukIpa":"/ˈmeməri/","usIpa":"/ˈmeməri/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"the ability to store and recall information or experiences","vi":"trí nhớ; khả năng ghi nhớ"},{"pos":"n.","en":"something from the past that you remember","vi":"hồi ức; ký ức"},{"pos":"n.","en":"the part of a computer that stores information","vi":"bộ nhớ máy tính; dung lượng lưu trữ"}],"examples":[{"en":"My grandmother has an excellent memory for faces.","vi":"Bà tôi có trí nhớ cực kỳ tốt với khuôn mặt mọi người.","audioKind":"ex"},{"en":"Regular physical exercise may improve memory and help older adults maintain their independence for longer.","vi":"Việc tập thể dục đều đặn có thể cải thiện trí nhớ và giúp người cao tuổi duy trì sự độc lập lâu hơn.","audioKind":"ex2"}],"collocations":[{"en":"short-term memory","vi":"trí nhớ ngắn hạn"},{"en":"childhood memories","vi":"ký ức tuổi thơ"},{"en":"from memory","vi":"từ trí nhớ; nhớ mang phong phanh"},{"en":"computer memory","vi":"bộ nhớ máy tính"}],"wordFamily":["memorise (v.)","memorable (adj.)"],"synonyms":["recollection","recall"],"antonyms":[],"tipVi":"Trí nhớ thường không đếm được; từng khoảng thời gian ký ức dùng memories.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_decision', 'en-a2-15', 'decision', '/dɪˈsɪʒən/', 'A2', 'quyết định; sự lựa chọn', 'n.', 'decide (v.), decisive (adj.), decisively (adv.), indecision (n.)', 'Đồng nghĩa: choice · Trái nghĩa: indecision', 'Dùng make a decision để chỉ hành động ra quyết định, không dùng động từ do.', 'Moving closer to work was a good decision.', NULL, 'Chuyển đến nơi ở gần chỗ làm hơn là một quyết định sáng suốt.', '{"wordId":"decision","ukIpa":"/dɪˈsɪʒən/","usIpa":"/dɪˈsɪʒən/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"a choice made after considering different possibilities","vi":"quyết định; sự lựa chọn"}],"examples":[{"en":"Moving closer to work was a good decision.","vi":"Chuyển đến nơi ở gần chỗ làm hơn là một quyết định sáng suốt.","audioKind":"ex"},{"en":"Governments should base every major transport decision on reliable evidence and consultation with the communities affected.","vi":"Chính phủ nên dựa trên các bằng chứng đáng tin cậy và sự tham vấn với các cộng đồng chịu ảnh hưởng đối với mọi quyết định giao thông quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"make a decision","vi":"đưa ra quyết định"},{"en":"reach a decision","vi":"đạt ến quyết định"},{"en":"informed decision","vi":"quyết định có cân nhắc"},{"en":"final decision","vi":"quyết định cuối cùng"}],"wordFamily":["decide (v.)","decisive (adj.)","decisively (adv.)","indecision (n.)"],"synonyms":["choice"],"antonyms":["indecision"],"tipVi":"Dùng make a decision để chỉ hành động ra quyết định, không dùng động từ do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prefer', 'en-a2-15', 'prefer', '/prɪˈfɝː/', 'A2', 'thích hơn; ưu tiên hơn', 'v.', 'preference (n.), preferable (adj.), preferably (adv.)', 'Đồng nghĩa: favour', 'Dùng cấu trúc prefer A to B; thì quá khứ preferred gấp đôi chữ r.', 'I prefer fresh fruit to cake after dinner.', NULL, 'Sau bữa tối, tôi thích ăn trái cây tươi hơn bánh ngọt.', '{"wordId":"prefer","ukIpa":"/prɪˈfɜː/","usIpa":"/prɪˈfɝː/","cefr":"A2","topic":"thinking","senses":[{"pos":"v.","en":"To like or choose something more than another option.","vi":"thích hơn; ưu tiên hơn"}],"examples":[{"en":"I prefer fresh fruit to cake after dinner.","vi":"Sau bữa tối, tôi thích ăn trái cây tươi hơn bánh ngọt.","audioKind":"ex"},{"en":"Some employees prefer working from home because it offers greater flexibility and eliminates daily commuting.","vi":"Một số nhân viên thích làm việc tại nhà hơn vì nó mang lại sự linh hoạt cao hơn và loại bỏ thời gian di chuyển đi làm mỗi ngày.","audioKind":"ex2"}],"collocations":[{"en":"prefer A to B","vi":"thích cái này hơn cái kia"},{"en":"prefer to do","vi":"thích làm gì hơn"},{"en":"would prefer","vi":"thích hơn; muốn hơn"}],"wordFamily":["preference (n.)","preferable (adj.)","preferably (adv.)"],"synonyms":["favour"],"antonyms":[],"tipVi":"Dùng cấu trúc prefer A to B; thì quá khứ preferred gấp đôi chữ r.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_view', 'en-a2-15', 'view', '/vjuː/', 'A2', 'quan điểm; ý kiến; cái nhìn; cảnh quan; tầm nhìn; xem xét; nhìn nhận; quan sát', 'n.', 'viewer (n.), viewing (n.)', 'Đồng nghĩa: opinion, perspective', 'Ý kiến dùng view on; coi việc gì như thế nào dùng view…as….', 'My view is that we should leave earlier.', NULL, 'Quan điểm của tôi là chúng ta nên khởi hành sớm hơn.', '{"wordId":"view","ukIpa":"/vjuː/","usIpa":"/vjuː/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"An opinion or belief about something.","vi":"quan điểm; ý kiến; cái nhìn"},{"pos":"n.","en":"What you can see from a particular place.","vi":"cảnh quan; tầm nhìn"},{"pos":"v.","en":"To consider something in a particular way, or look at it.","vi":"xem xét; nhìn nhận; quan sát"}],"examples":[{"en":"My view is that we should leave earlier.","vi":"Quan điểm của tôi là chúng ta nên khởi hành sớm hơn.","audioKind":"ex"},{"en":"Many residents view investment in public transport as an effective way to reduce urban pollution.","vi":"Nhiều cư dân coi việc đầu tư vào giao thông công cộng là cách hiệu quả để giảm ô nhiễm đô thị.","audioKind":"ex2"}],"collocations":[{"en":"express a view","vi":"bày tỏ quan điểm"},{"en":"in my view","vi":"theo quan điểm của tôi"},{"en":"a sea view","vi":"cảnh biển"},{"en":"view something as","vi":"coi cái gì là"}],"wordFamily":["viewer (n.)","viewing (n.)"],"synonyms":["opinion","perspective"],"antonyms":[],"tipVi":"Ý kiến dùng view on; coi việc gì như thế nào dùng view…as….","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_imagine', 'en-a2-15', 'imagine', '/ɪˈmædʒɪn/', 'A2', 'tưởng tượng; hình dung; nghĩ rằng; cho là', 'v.', 'imagination (n.), imaginative (adj.), imaginary (adj.)', 'Đồng nghĩa: picture, envisage', 'Sau imagine đi với danh động từ (động từ thêm -ing), không đi với to do.', 'Imagine living in a little house beside the sea.', NULL, 'Hãy tưởng tượng cảnh sống trong một ngôi nhà nhỏ bên bờ biển.', '{"wordId":"imagine","ukIpa":"/ɪˈmædʒɪn/","usIpa":"/ɪˈmædʒɪn/","cefr":"A2","topic":"thinking","senses":[{"pos":"v.","en":"Form a picture or idea of something in your mind.","vi":"tưởng tượng; hình dung"},{"pos":"v.","en":"Think something is probably true without being certain.","vi":"nghĩ rằng; cho là"}],"examples":[{"en":"Imagine living in a little house beside the sea.","vi":"Hãy tưởng tượng cảnh sống trong một ngôi nhà nhỏ bên bờ biển.","audioKind":"ex"},{"en":"Urban planners must imagine how future residents will use shared spaces before designing new neighbourhoods.","vi":"Các nhà quy hoạch đô thị phải hình dung cách cư dân tương lai sử dụng các không gian chung trước khi thiết kế các khu dân cư mới.","audioKind":"ex2"}],"collocations":[{"en":"imagine doing something","vi":"tưởng tượng làm điều gì đó"},{"en":"hard to imagine","vi":"khó mà tưởng tượng"},{"en":"imagine the future","vi":"hình dung tương lai"}],"wordFamily":["imagination (n.)","imaginative (adj.)","imaginary (adj.)"],"synonyms":["picture","envisage"],"antonyms":[],"tipVi":"Sau imagine đi với danh động từ (động từ thêm -ing), không đi với to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suggestion', 'en-a2-15', 'suggestion', '/səˈdʒestʃən/', 'A2', 'ý kiến đề xuất; lời khuyên; dấu hiệu nhỏ; sự gợi ý nhẹ', 'n.', 'suggest (v.), suggestive (adj.)', 'Đồng nghĩa: proposal, recommendation', 'suggestion là danh từ đếm được; trong khi advice thường không đếm được.', 'Your suggestion to bring a picnic was really helpful.', NULL, 'Gợi ý mang theo đồ dã ngoại của bạn thực sự rất hữu ích.', '{"wordId":"suggestion","ukIpa":"/səˈdʒestʃən/","usIpa":"/səˈdʒestʃən/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"an idea offered for someone to consider","vi":"ý kiến đề xuất; lời khuyên"},{"pos":"n.","en":"a slight sign that something exists or may be true","vi":"dấu hiệu nhỏ; sự gợi ý nhẹ"}],"examples":[{"en":"Your suggestion to bring a picnic was really helpful.","vi":"Gợi ý mang theo đồ dã ngoại của bạn thực sự rất hữu ích.","audioKind":"ex"},{"en":"The suggestion to expand cycle lanes received strong support from residents concerned about road safety.","vi":"Đề xuất mở rộng các làn đường dành cho xe đạp đã nhận được sự ủng hộ mạnh mẽ từ cư dân quan tâm đến an toàn giao thông.","audioKind":"ex2"}],"collocations":[{"en":"make a suggestion","vi":"đưa ra gợi ý"},{"en":"a useful suggestion","vi":"một gợi ý hữu ích"},{"en":"a suggestion of","vi":"một chút; thoáng qua"}],"wordFamily":["suggest (v.)","suggestive (adj.)"],"synonyms":["proposal","recommendation"],"antonyms":[],"tipVi":"suggestion là danh từ đếm được; trong khi advice thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clever', 'en-a2-15', 'clever', '/ˈklevər/', 'A2', 'thông minh; lanh lợi; khéo léo; tinh xảo', 'adj.', 'cleverly (adv.), cleverness (n.)', 'Đồng nghĩa: smart, intelligent · Trái nghĩa: stupid', 'Các dạng so sánh là cleverer và cleverest.', 'That clever child fixed the puzzle before lunch.', NULL, 'Đứa trẻ thông minh đó đã giải xong câu đố trước giờ ăn trưa.', '{"wordId":"clever","ukIpa":"/ˈklevə/","usIpa":"/ˈklevər/","cefr":"A2","topic":"thinking","senses":[{"pos":"adj.","en":"Quick to learn, understand, or find solutions.","vi":"thông minh; lanh lợi"},{"pos":"adj.","en":"Showing skill or an original way of solving a problem.","vi":"khéo léo; tinh xảo"}],"examples":[{"en":"That clever child fixed the puzzle before lunch.","vi":"Đứa trẻ thông minh đó đã giải xong câu đố trước giờ ăn trưa.","audioKind":"ex"},{"en":"Clever design can make small urban apartments feel spacious without increasing their environmental impact.","vi":"Thiết kế khéo léo có thể làm cho các căn hộ đô thị nhỏ trở nên rộng rãi mà không làm gia tăng tác động môi trường.","audioKind":"ex2"}],"collocations":[{"en":"clever idea","vi":"ý tưởng thông minh/khéo léo"},{"en":"clever at","vi":"giỏi về cái gì"},{"en":"clever solution","vi":"giải pháp khéo léo"}],"wordFamily":["cleverly (adv.)","cleverness (n.)"],"synonyms":["smart","intelligent"],"antonyms":["stupid"],"tipVi":"Các dạng so sánh là cleverer và cleverest.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_impossible', 'en-a2-15', 'impossible', '/ɪmˈpɑːsəbəl/', 'A2', 'bất khả thi; không thể xảy ra; cực kỳ khó giải quyết; khó chiều', 'adj.', 'possible (adj.), impossibility (n.), impossibly (adv.)', 'Đồng nghĩa: unachievable, unfeasible · Trái nghĩa: possible', 'Thường dùng cấu trúc it is impossible to do để chỉ việc không thể làm gì.', 'It is impossible to fit this sofa through the doorway.', NULL, 'Hoàn toàn không thể đưa chiếc ghế sofa này lọt qua khung cửa.', '{"wordId":"impossible","ukIpa":"/ɪmˈpɒsəbəl/","usIpa":"/ɪmˈpɑːsəbəl/","cefr":"A2","topic":"thinking","senses":[{"pos":"adj.","en":"unable to happen, exist, or be done","vi":"bất khả thi; không thể xảy ra"},{"pos":"adj.","en":"extremely difficult to deal with or satisfy","vi":"cực kỳ khó giải quyết; khó chiều"}],"examples":[{"en":"It is impossible to fit this sofa through the doorway.","vi":"Hoàn toàn không thể đưa chiếc ghế sofa này lọt qua khung cửa.","audioKind":"ex"},{"en":"Without reliable public transport, it is almost impossible for some rural residents to access essential services.","vi":"Nếu không có hệ thống giao thông công cộng đáng tin cậy, một số cư dân nông thôn hầu như không thể tiếp cận các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"almost impossible","vi":"gần như bất khả thi"},{"en":"impossible task","vi":"nhiệm vụ bất khả thi"},{"en":"make it impossible to","vi":"làm cho việc gì trở nên bất khả thi"}],"wordFamily":["possible (adj.)","impossibility (n.)","impossibly (adv.)"],"synonyms":["unachievable","unfeasible"],"antonyms":["possible"],"tipVi":"Thường dùng cấu trúc it is impossible to do để chỉ việc không thể làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_probably', 'en-a2-15', 'probably', '/ˈprɑːbəbli/', 'A2', 'có lẽ; chắc là', 'adv.', 'probable (adj.), probability (n.), improbable (adj.)', 'Đồng nghĩa: likely', 'Thường đặt trước động từ chỉ hành động, sau động từ ''be'' hoặc sau trợ động từ đầu tiên.', 'The bakery will probably close before we get there.', NULL, 'Tiệm bánh có lẽ sẽ đóng cửa trước khi chúng ta đến đó.', '{"wordId":"probably","ukIpa":"/ˈprɒbəbli/","usIpa":"/ˈprɑːbəbli/","cefr":"A2","topic":"thinking","senses":[{"pos":"adv.","en":"Used when something is likely but not certain.","vi":"có lẽ; chắc là"}],"examples":[{"en":"The bakery will probably close before we get there.","vi":"Tiệm bánh có lẽ sẽ đóng cửa trước khi chúng ta đến đó.","audioKind":"ex"},{"en":"Cities that invest in reliable public transport will probably experience less traffic congestion over time.","vi":"Những thành phố đầu tư vào hệ thống giao thông công cộng đáng tin cậy có lẽ sẽ ít gặp tình trạng tắc nghẽn giao thông hơn theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"will probably","vi":"có lẽ sẽ"},{"en":"probably not","vi":"chắc là không"},{"en":"probably because","vi":"có lẽ bởi vì"}],"wordFamily":["probable (adj.)","probability (n.)","improbable (adj.)"],"synonyms":["likely"],"antonyms":[],"tipVi":"Thường đặt trước động từ chỉ hành động, sau động từ ''be'' hoặc sau trợ động từ đầu tiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_15_1', 'en-a2-15', 'Cách dùng “FALSE” (adj.) — sai; không có thật', 'false information  ·  false impression  ·  false alarm', 'false mang nghĩa không đúng sự thật; fake nhấn mạnh việc làm giả, nhái tinh vi. Từ này thường được viết ở dạng chữ thường.', 'Họ từ (Word Family): falsely (adv.), falsehood (n.), falsify (v.) | Đồng nghĩa: untrue, incorrect · Trái nghĩa: true, genuine', '[{"hanzi":"That rumour about our neighbour is completely FALSE.","pinyin":"","meaning":"Tin đồn về người hàng xóm của chúng ta hoàn toàn không đúng sự thật."},{"hanzi":"Claims that all online information is reliable are FALSE, so students should learn to evaluate sources critically.","pinyin":"","meaning":"Những khẳng định cho rằng tất cả thông tin trực tuyến đều đáng tin cậy là sai sự thật, vì vậy học sinh nên học cách đánh giá các nguồn thông tin một cách phản biện."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_15_2', 'en-a2-15', 'Cách dùng “however” (adv.) — tuy nhiên; song', 'however difficult  ·  however much  ·  however hard you try', 'Khi dùng với nghĩa chuyển ý, đây không phải là liên từ đẳng lập; tuyệt đối không nối hai câu đơn chỉ bằng dấu phẩy.', 'Đồng nghĩa: nevertheless, nonetheless', '[{"hanzi":"The jacket looked warm; however, it felt surprisingly thin.","pinyin":"","meaning":"Chiếc áo khoác trông có vẻ ấm áp; tuy nhiên, nó lại mỏng một cách đáng ngạc nhiên."},{"hanzi":"Online courses offer greater flexibility; however, some learners benefit more from direct interaction with teachers.","pinyin":"","meaning":"Các khóa học trực tuyến mang lại sự linh hoạt lớn hơn; tuy nhiên, một số người học lại thu được nhiều lợi ích hơn từ việc tương tác trực tiếp với giáo viên."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_15_3', 'en-a2-15', 'Cách dùng “dream” (n.) — giấc mơ; giấc mộng', 'have a dream  ·  pursue a dream  ·  dream of becoming', 'dream of/about theo sau bởi danh từ hoặc danh từ chỉ hành động; dạng quá khứ có thể dùng dreamt hoặc dreamed.', 'Họ từ (Word Family): dreamer (n.), dreamy (adj.), dreamless (adj.)', '[{"hanzi":"Last night, I had a dream about flying over mountains.","pinyin":"","meaning":"Tối qua, tôi mơ thấy mình đang bay lượn trên những ngọn núi."},{"hanzi":"Access to affordable education allows more young people to pursue their dream of entering a skilled profession.","pinyin":"","meaning":"Khả năng tiếp cận giáo dục với chi phí hợp lý cho phép nhiều người trẻ tuổi theo đuổi ước mơ bước chân vào một ngành nghề chuyên môn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_15_4', 'en-a2-15', 'Cách dùng “guess” (v.) — đoán; phỏng đoán', 'make a guess  ·  an educated guess  ·  guess correctly', 'Cụm I guess thường dùng trong văn nói mang tính phỏng đoán, phỏng chừng và không chắc chắn hoàn toàn.', 'Họ từ (Word Family): guesswork (n.) | Đồng nghĩa: estimate, suppose', '[{"hanzi":"Can you guess what is inside this little box?","pinyin":"","meaning":"Bạn có đoán được bên trong chiếc hộp nhỏ này có gì không?"},{"hanzi":"Without reliable data, researchers can only guess how changes in transport costs will affect household spending.","pinyin":"","meaning":"Khi thiếu dữ liệu đáng tin cậy, các nhà nghiên cứu chỉ có thể phỏng đoán sự thay đổi chi phí vận chuyển sẽ ảnh hưởng như thế nào đến chi tiêu của các hộ gia đình."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_15_1', 'en-a2-15', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_15_1_1', 'ten_a2_15_1', 'result', 'The shiny floor was the result of hours of cleaning.', 'The shiny floor was the result of hours of cleaning.', '/rɪˈzʌlt/', 'Sàn nhà sáng bóng là thành quả của hàng giờ dọn dẹp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_15_1_2', 'ten_a2_15_1', 'definitely', 'I will definitely bring an umbrella after yesterday''s rain.', 'I will definitely bring an umbrella after yesterday''s rain.', '/ˈdefɪnətli/', 'Tôi chắc chắn sẽ mang theo ô sau trận mưa ngày hôm qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_15_1_3', 'ten_a2_15_1', 'difference', 'The main difference between these jackets is their weight.', 'The main difference between these jackets is their weight.', '/ˈdɪfrəns/', 'Điểm khác biệt chính giữa những chiếc áo khoác này là trọng lượng của chúng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_15_1_4', 'ten_a2_15_1', 'however', 'The jacket looked warm; however, it felt surprisingly thin.', 'The jacket looked warm; however, it felt surprisingly thin.', '/haʊˈevər/', 'Chiếc áo khoác trông có vẻ ấm áp; tuy nhiên, nó lại mỏng một cách đáng ngạc nhiên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_15_1_5', 'ten_a2_15_1', 'stupid', 'It was stupid to leave my umbrella at home.', 'It was stupid to leave my umbrella at home.', '/ˈstuːpɪd/', 'Để quên ô ở nhà thật là ngốc.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_15_1_6', 'ten_a2_15_1', 'interest', 'My interest in cooking began in my grandmother''s kitchen.', 'My interest in cooking began in my grandmother''s kitchen.', '/ˈɪntrəst/', 'Niềm yêu thích nấu nướng của tôi bắt đầu từ căn bếp của bà tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_15_1_7', 'ten_a2_15_1', 'mean', 'I didn''t mean to leave you waiting outside.', 'I didn''t mean to leave you waiting outside.', '/miːn/', 'Tôi không cố ý để bạn phải đợi bên ngoài đâu.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_15_1_8', 'ten_a2_15_1', 'dream', 'Last night, I had a dream about flying over mountains.', 'Last night, I had a dream about flying over mountains.', '/driːm/', 'Tối qua, tôi mơ thấy mình đang bay lượn trên những ngọn núi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_15_1_1', 'en-a2-15', 'ten_a2_15_1', 'listening', 'listening', 'The shiny floor was the result of hours of cleaning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bạn đã đưa ra một ý kiến rất hay về việc chia sẻ không gian bếp chung.","Sàn nhà sáng bóng là thành quả của hàng giờ dọn dẹp.","Bạn có thể chọn giữa súp và xà lách.","Chiếc áo khoác trông có vẻ ấm áp; tuy nhiên, nó lại mỏng một cách đáng ngạc nhiên."]'::jsonb, 1, 'The shiny floor was the result of hours of cleaning. → Sàn nhà sáng bóng là thành quả của hàng giờ dọn dẹp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_15_1_2', 'en-a2-15', 'ten_a2_15_1', 'listening', 'listening', 'I will definitely bring an umbrella after yesterday''s rain.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc áo khoác trông có vẻ ấm áp; tuy nhiên, nó lại mỏng một cách đáng ngạc nhiên.","Tôi chắc chắn sẽ mang theo ô sau trận mưa ngày hôm qua.","Hoàn toàn không thể đưa chiếc ghế sofa này lọt qua khung cửa.","Gợi ý mang theo đồ dã ngoại của bạn thực sự rất hữu ích."]'::jsonb, 1, 'I will definitely bring an umbrella after yesterday''s rain. → Tôi chắc chắn sẽ mang theo ô sau trận mưa ngày hôm qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_15_1_3', 'en-a2-15', 'ten_a2_15_1', 'listening', 'listening', 'The main difference between these jackets is their weight.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Gợi ý mang theo đồ dã ngoại của bạn thực sự rất hữu ích.","Tối qua, tôi mơ thấy mình đang bay lượn trên những ngọn núi.","Điểm khác biệt chính giữa những chiếc áo khoác này là trọng lượng của chúng.","Tiệm bánh có lẽ sẽ đóng cửa trước khi chúng ta đến đó."]'::jsonb, 2, 'The main difference between these jackets is their weight. → Điểm khác biệt chính giữa những chiếc áo khoác này là trọng lượng của chúng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_15_2', 'en-a2-15', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_15_2_1', 'ten_a2_15_2', 'result', 'Investing in reliable public transport can result in lower emissions and shorter commuting times for urban residents.', 'Investing in reliable public transport can result in lower emissions and shorter commuting times for urban residents.', '/rɪˈzʌlt/', 'Đầu tư vào hệ thống giao thông công cộng đáng tin cậy có thể giúp giảm lượng khí thải và rút ngắn thời gian di chuyển cho cư dân đô thị.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_15_2_2', 'ten_a2_15_2', 'definitely', 'Improved insulation will definitely reduce heat loss, although total energy savings depend on household behaviour.', 'Improved insulation will definitely reduce heat loss, although total energy savings depend on household behaviour.', '/ˈdefɪnətli/', 'Cải thiện khả năng cách nhiệt chắc chắn sẽ làm giảm thất thoát nhiệt, mặc dù mức tiết kiệm năng lượng tổng thể còn phụ thuộc vào hành vi của các hộ gia đình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_15_2_3', 'ten_a2_15_2', 'difference', 'Understanding cultural differences can help international students adapt more successfully to life in a new country.', 'Understanding cultural differences can help international students adapt more successfully to life in a new country.', '/ˈdɪfrəns/', 'Việc thấu hiểu các khác biệt về văn hóa có thể giúp du học sinh thích nghi thành công hơn với cuộc sống ở một đất nước mới.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_15_2_4', 'ten_a2_15_2', 'however', 'Online courses offer greater flexibility; however, some learners benefit more from direct interaction with teachers.', 'Online courses offer greater flexibility; however, some learners benefit more from direct interaction with teachers.', '/haʊˈevər/', 'Các khóa học trực tuyến mang lại sự linh hoạt lớn hơn; tuy nhiên, một số người học lại thu được nhiều lợi ích hơn từ việc tương tác trực tiếp với giáo viên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_15_2_5', 'ten_a2_15_2', 'stupid', 'Calling students stupid can damage their confidence and discourage them from asking questions in class.', 'Calling students stupid can damage their confidence and discourage them from asking questions in class.', '/ˈstuːpɪd/', 'Việc gọi học sinh là ngốc nghếch có thể làm tổn thương sự tự tin của các em và khiến các em ngại đặt câu hỏi trong lớp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_15_2_6', 'ten_a2_15_2', 'interest', 'Schools can stimulate interest in science by giving students opportunities to conduct experiments and explore practical problems.', 'Schools can stimulate interest in science by giving students opportunities to conduct experiments and explore practical problems.', '/ˈɪntrəst/', 'Nhà trường có thể khơi 1 gợi sự quan tâm đến khoa học bằng cách cho học sinh cơ hội tiến hành thí nghiệm và khám phá các vấn đề thực tế.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_15_2_1', 'en-a2-15', 'ten_a2_15_2', 'listening', 'listening', 'Investing in reliable public transport can result in lower emissions and shorter commuting times for urban residents.', NULL, 'Trong câu vừa nghe, từ “result” mang nghĩa nào sau đây?', '["kết quả; hậu quả","giày bốt; ủng","nhà máy; xưởng","bán thời gian; làm thêm"]'::jsonb, 0, '“result” (/rɪˈzʌlt/): kết quả; hậu quả. Câu đầy đủ: Investing in reliable public transport can result in lower emissions and shorter commuting times for urban residents.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_15_2_2', 'en-a2-15', 'ten_a2_15_2', 'listening', 'listening', 'Improved insulation will definitely reduce heat loss, although total energy savings depend on household behaviour.', NULL, 'Trong câu vừa nghe, từ “definitely” mang nghĩa nào sau đây?', '["lịch; bảng lịch; lịch trình","nên; phải","Xốt-lân; Xéc-lân (Xơ-cốt-len)","chắc chắn; dứt khoát; rạch ròi"]'::jsonb, 3, '“definitely” (/ˈdefɪnətli/): chắc chắn; dứt khoát; rạch ròi. Câu đầy đủ: Improved insulation will definitely reduce heat loss, although total energy savings depend on household behaviour.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
