INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_15_2', 'en-a2-15', NULL, 'comprehensive_test', 'listening', 'I will definitely bring an umbrella after yesterday''s rain.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi chắc chắn sẽ mang theo ô sau trận mưa ngày hôm qua.","Chuyển đến nơi ở gần chỗ làm hơn là một quyết định sáng suốt.","Bạn có vẻ mệt mỏi sau quãng đường đi bộ dài về nhà.","Sau bữa tối, tôi thích ăn trái cây tươi hơn bánh ngọt."]'::jsonb, 0, 'I will definitely bring an umbrella after yesterday''s rain. → Tôi chắc chắn sẽ mang theo ô sau trận mưa ngày hôm qua.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
