INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_15_4', 'en-a2-15', NULL, 'comprehensive_test', 'listening', 'The jacket looked warm; however, it felt surprisingly thin.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bạn có thể chọn giữa súp và xà lách.","Chuyển đến nơi ở gần chỗ làm hơn là một quyết định sáng suốt.","Đứa trẻ thông minh đó đã giải xong câu đố trước giờ ăn trưa.","Chiếc áo khoác trông có vẻ ấm áp; tuy nhiên, nó lại mỏng một cách đáng ngạc nhiên."]'::jsonb, 3, 'The jacket looked warm; however, it felt surprisingly thin. → Chiếc áo khoác trông có vẻ ấm áp; tuy nhiên, nó lại mỏng một cách đáng ngạc nhiên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_15_5', 'en-a2-15', NULL, 'comprehensive_test', 'listening', 'stupid', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cho phép; chuẩn y","ngu ngốc; khờ khạo; kém suy nghĩ","củ tỏi; tép tỏi","hành vi; thái độ; cách ứng xử"]'::jsonb, 1, 'stupid (/ˈstuːpɪd/) → ngu ngốc; khờ khạo; kém suy nghĩ', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_15_6', 'en-a2-15', NULL, 'comprehensive_test', 'listening', 'My interest in cooking began in my grandmother''s kitchen.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Niềm yêu thích nấu nướng của tôi bắt đầu từ căn bếp của bà tôi.","Bà tôi có trí nhớ cực kỳ tốt với khuôn mặt mọi người.","Tin đồn về người hàng xóm của chúng ta hoàn toàn không đúng sự thật.","Hãy tưởng tượng cảnh sống trong một ngôi nhà nhỏ bên bờ biển."]'::jsonb, 0, 'My interest in cooking began in my grandmother''s kitchen. → Niềm yêu thích nấu nướng của tôi bắt đầu từ căn bếp của bà tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_15_7', 'en-a2-15', NULL, 'comprehensive_test', 'listening', 'mean', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["dấu phẩy","lục quân; quân đội","có nghĩa là; ngụ ý; định","cuộc thảo luận; sự bàn bạc"]'::jsonb, 2, 'mean (/miːn/) → có nghĩa là; ngụ ý; định; keo kiệt; độc ác; bủn xỉn; số trung bình', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_15_8', 'en-a2-15', NULL, 'comprehensive_test', 'listening', 'Last night, I had a dream about flying over mountains.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tối qua, tôi mơ thấy mình đang bay lượn trên những ngọn núi.","Điểm khác biệt chính giữa những chiếc áo khoác này là trọng lượng của chúng.","Hoàn toàn không thể đưa chiếc ghế sofa này lọt qua khung cửa.","Chuyển đến nơi ở gần chỗ làm hơn là một quyết định sáng suốt."]'::jsonb, 0, 'Last night, I had a dream about flying over mountains. → Tối qua, tôi mơ thấy mình đang bay lượn trên những ngọn núi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_15_9', 'en-a2-15', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Showing poor judgment or a lack of sensible thought.”?', '["suggestion","result","imagine","stupid"]'::jsonb, 3, 'stupid (/ˈstuːpɪd/) → ngu ngốc; khờ khạo; kém suy nghĩ', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
