INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_15_18', 'en-a2-15', NULL, 'comprehensive_test', 'reading', NULL, 'Investing in reliable public transport can result in lower emissions and shorter commuting times for urban residents.', 'Dựa vào câu trên, từ “result” có nghĩa phù hợp nhất là gì?', '["kết quả; hậu quả","hình vuông","môn judo; võ judo","người đàn ông Pháp; nam công dân Pháp"]'::jsonb, 0, 'result: kết quả; hậu quả; kết quả thi; thành tích; dẫn đến; do. Dịch cả câu: Đầu tư vào hệ thống giao thông công cộng đáng tin cậy có thể giúp giảm lượng khí thải và rút ngắn thời gian di chuyển cho cư dân đô thị.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_15_19', 'en-a2-15', NULL, 'comprehensive_test', 'reading', NULL, 'Improved insulation will definitely reduce heat loss, although total energy savings depend on household behaviour.', 'Dựa vào câu trên, từ “definitely” có nghĩa phù hợp nhất là gì?', '["chắc chắn; dứt khoát; rạch ròi","việc gia nhập; việc tham gia","ngày làm việc trong tuần; từ thứ Hai đến thứ Sáu","lời khuyên; sự hướng dẫn về việc ai đó nên làm gì trong một hoàn cảnh cụ thể"]'::jsonb, 0, 'definitely: chắc chắn; dứt khoát; rạch ròi. Dịch cả câu: Cải thiện khả năng cách nhiệt chắc chắn sẽ làm giảm thất thoát nhiệt, mặc dù mức tiết kiệm năng lượng tổng thể còn phụ thuộc vào hành vi của các hộ gia đình.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_15_20', 'en-a2-15', NULL, 'comprehensive_test', 'reading', NULL, 'Understanding cultural differences can help international students adapt more successfully to life in a new country.', 'Dựa vào câu trên, từ “difference” có nghĩa phù hợp nhất là gì?', '["đám mây","sự khác biệt; điểm khác nhau","môi; bờ môi","tuy nhiên; song"]'::jsonb, 1, 'difference: sự khác biệt; điểm khác nhau; sự bất đồng; mối bất hòa; số dư; khoảng chênh lệch. Dịch cả câu: Việc thấu hiểu các khác biệt về văn hóa có thể giúp du học sinh thích nghi thành công hơn với cuộc sống ở một đất nước mới.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_15_21', 'en-a2-15', NULL, 'comprehensive_test', 'reading', NULL, 'Online courses offer greater flexibility; however, some learners benefit more from direct interaction with teachers.', 'Dựa vào câu trên, từ “however” có nghĩa phù hợp nhất là gì?', '["tuy nhiên; song","ngựa vằn","vui mừng; hài lòng; phấn khởi","con rắn"]'::jsonb, 0, 'however: tuy nhiên; song; dù... đến đâu; dù theo bất kỳ cách nào. Dịch cả câu: Các khóa học trực tuyến mang lại sự linh hoạt lớn hơn; tuy nhiên, một số người học lại thu được nhiều lợi ích hơn từ việc tương tác trực tiếp với giáo viên.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
