INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-16', 'en', 'Bài 16: Tư duy & Nhận thức (2) - CEFR A2', 'CEFR A2', 'A2 · Tư duy', '22 từ vựng Tiếng Anh CEFR A2 chủ đề tư duy & nhận thức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2016, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_similar', 'en-a2-16', 'similar', '/ˈsɪmələr/', 'A2', 'tương tự; giống nhau', 'adj.', 'similarity (n.), similarly (adv.), dissimilar (adj.)', 'Đồng nghĩa: alike, comparable · Trái nghĩa: different, dissimilar', 'Dùng similar to, không dùng similar with; tương tự không có nghĩa là giống hệt.', 'Your jacket looks similar to mine, but slightly darker.', NULL, 'Áo khoác của bạn trông tương tự như của tôi, nhưng tối màu hơn một chút.', '{"wordId":"similar","ukIpa":"/ˈsɪmələ/","usIpa":"/ˈsɪmələr/","cefr":"A2","topic":"thinking","senses":[{"pos":"adj.","en":"Almost the same, but not exactly alike.","vi":"tương tự; giống nhau"}],"examples":[{"en":"Your jacket looks similar to mine, but slightly darker.","vi":"Áo khoác của bạn trông tương tự như của tôi, nhưng tối màu hơn một chút.","audioKind":"ex"},{"en":"Cities with similar population sizes may require different transport policies because of their geographical features.","vi":"Các thành phố có quy mô dân số tương tự có thể cần các chính sách giao thông khác nhau do đặc điểm địa lý của chúng.","audioKind":"ex2"}],"collocations":[{"en":"similar to","vi":"tương tự với"},{"en":"similar characteristics","vi":"các đặc điểm tương tự"},{"en":"broadly similar","vi":"tương tự về cơ bản"}],"wordFamily":["similarity (n.)","similarly (adv.)","dissimilar (adj.)"],"synonyms":["alike","comparable"],"antonyms":["different","dissimilar"],"tipVi":"Dùng similar to, không dùng similar with; tương tự không có nghĩa là giống hệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thought', 'en-a2-16', 'thought', '/θɔːt/', 'A2', 'ý nghĩ; suy nghĩ; ý kiến; sự suy ngẫm; sự cân nhắc; thì quá khứ và phân từ quá khứ của think', 'n.', 'think (v.), thinker (n.), thoughtful (adj.), thoughtless (adj.)', 'Đồng nghĩa: idea, reflection', 'Khi chỉ ý nghĩ cụ thể thì đếm được; khi chỉ quá trình suy nghĩ thì thường không đếm được.', 'A sudden thought made me check my coat pocket.', NULL, 'Một suy nghĩ chợt xuất hiện khiến tôi phải kiểm tra túi áo khoác.', '{"wordId":"thought","ukIpa":"/θɔːt/","usIpa":"/θɔːt/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"an idea or opinion formed in the mind","vi":"ý nghĩ; suy nghĩ; ý kiến"},{"pos":"n.","en":"the process of thinking carefully about something","vi":"sự suy ngẫm; sự cân nhắc"},{"pos":"v.","en":"past tense and past participle of think","vi":"thì quá khứ và phân từ quá khứ của think"}],"examples":[{"en":"A sudden thought made me check my coat pocket.","vi":"Một suy nghĩ chợt xuất hiện khiến tôi phải kiểm tra túi áo khoác.","audioKind":"ex"},{"en":"Urban planning requires careful thought about how public spaces can serve people of different ages.","vi":"Quy hoạch đô thị đòi hỏi phải suy ngẫm kỹ lưỡng về cách các không gian công cộng có thể phục vụ người dân ở mọi lứa tuổi.","audioKind":"ex2"}],"collocations":[{"en":"give something some thought","vi":"suy nghĩ kỹ về điều gì; cân nhắc điều gì"},{"en":"deep in thought","vi":"chìm đắm trong suy tư; trầm ngâm"},{"en":"a sudden thought","vi":"một ý nghĩ chợt nảy ra"},{"en":"food for thought","vi":"điều đáng suy ngẫm; vấn đề gợi mở"}],"wordFamily":["think (v.)","thinker (n.)","thoughtful (adj.)","thoughtless (adj.)"],"synonyms":["idea","reflection"],"antonyms":[],"tipVi":"Khi chỉ ý nghĩ cụ thể thì đếm được; khi chỉ quá trình suy nghĩ thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_opinion', 'en-a2-16', 'opinion', '/əˈpɪnjən/', 'A2', 'ý kiến; quan điểm; đánh giá', 'n.', 'opinionated (adj.)', 'Đồng nghĩa: view, belief', 'Để diễn đạt “theo tôi” hãy dùng in my opinion, không dùng according to me.', 'What is your opinion of our new kitchen?', NULL, 'Bạn nghĩ thế nào về căn bếp mới của chúng tôi?', '{"wordId":"opinion","ukIpa":"/əˈpɪnjən/","usIpa":"/əˈpɪnjən/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"a belief or judgement about someone or something","vi":"ý kiến; quan điểm; đánh giá"}],"examples":[{"en":"What is your opinion of our new kitchen?","vi":"Bạn nghĩ thế nào về căn bếp mới của chúng tôi?","audioKind":"ex"},{"en":"In my opinion, public transport should be affordable enough to encourage people to leave their cars at home.","vi":"Theo quan điểm của tôi, phương tiện giao thông công cộng nên có giá cả phải chăng để khuyến khích mọi người để xe ở nhà.","audioKind":"ex2"}],"collocations":[{"en":"in my opinion","vi":"theo tôi; theo quan điểm của tôi"},{"en":"public opinion","vi":"dư luận công chúng"},{"en":"express an opinion","vi":"bày tỏ quan điểm"},{"en":"a difference of opinion","vi":"sự bất đồng quan điểm"}],"wordFamily":["opinionated (adj.)"],"synonyms":["view","belief"],"antonyms":[],"tipVi":"Để diễn đạt “theo tôi” hãy dùng in my opinion, không dùng according to me.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exact', 'en-a2-16', 'exact', '/ɪɡˈzækt/', 'A2', 'chính xác; đúng từng chi tiết; bắt buộc phải có; đòi hỏi', 'adj.', 'exactly (adv.), exactness (n.), inexact (adj.)', 'Đồng nghĩa: precise, accurate · Trái nghĩa: inexact, approximate', 'exact nhấn mạnh sự chuẩn xác hoàn toàn; dạng trạng từ (adv.) của nó là exactly.', 'Can you tell me the exact time we should arrive?', NULL, 'Bạn có thể cho tôi biết chính xác thời gian chúng ta nên đến không?', '{"wordId":"exact","ukIpa":"/ɪɡˈzækt/","usIpa":"/ɪɡˈzækt/","cefr":"A2","topic":"thinking","senses":[{"pos":"adj.","en":"Correct in every detail, without any difference or error.","vi":"chính xác; đúng từng chi tiết"},{"pos":"v.","en":"Demand and obtain something, often through authority or force.","vi":"bắt buộc phải có; đòi hỏi"}],"examples":[{"en":"Can you tell me the exact time we should arrive?","vi":"Bạn có thể cho tôi biết chính xác thời gian chúng ta nên đến không?","audioKind":"ex"},{"en":"Researchers need exact measurements to determine whether changes in air quality are linked to new transport policies.","vi":"Các nhà nghiên cứu cần số đo chính xác để xác định liệu sự thay đổi về chất lượng không khí có liên quan đến các chính sách giao thông mới hay không.","audioKind":"ex2"}],"collocations":[{"en":"exact location","vi":"vị trí chính xác"},{"en":"exact amount","vi":"số lượng chính xác"},{"en":"exact copy","vi":"bản sao y bản chính"},{"en":"exact a heavy toll","vi":"gây ra hậu quả nặng nề"}],"wordFamily":["exactly (adv.)","exactness (n.)","inexact (adj.)"],"synonyms":["precise","accurate"],"antonyms":["inexact","approximate"],"tipVi":"exact nhấn mạnh sự chuẩn xác hoàn toàn; dạng trạng từ (adv.) của nó là exactly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_compare', 'en-a2-16', 'compare', '/kəmˈper/', 'A2', 'so sánh; đối chiếu; ví với; sánh kịp; bì được', 'v.', 'comparison (n.), comparable (adj.), comparative (adj.), comparatively (adv.)', 'Đồng nghĩa: liken', 'Cấu trúc so sánh có thể đi với with hoặc to; khi dùng để ẩn dụ, ví von thì thường dùng với to.', 'We compared several backpacks before choosing the lightest one.', NULL, 'Chúng tôi đã so sánh vài chiếc ba lô trước khi chọn ra chiếc nhẹ nhất.', '{"wordId":"compare","ukIpa":"/kəmˈpeə/","usIpa":"/kəmˈper/","cefr":"A2","topic":"thinking","senses":[{"pos":"v.","en":"To examine things to find similarities and differences.","vi":"so sánh; đối chiếu"},{"pos":"v.","en":"To describe something as similar to another thing.","vi":"ví với"},{"pos":"v.","en":"To be as good as, or similar to, something else.","vi":"sánh kịp; bì được"}],"examples":[{"en":"We compared several backpacks before choosing the lightest one.","vi":"Chúng tôi đã so sánh vài chiếc ba lô trước khi chọn ra chiếc nhẹ nhất.","audioKind":"ex"},{"en":"Researchers should compare the long-term costs of renewable energy with those of traditional power sources.","vi":"Các nhà nghiên cứu nên so sánh chi phí dài hạn của năng lượng tái tạo với các nguồn năng lượng truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"compare prices","vi":"so sánh giá cả"},{"en":"compare A with B","vi":"so sánh A với B"},{"en":"compare A to B","vi":"ví A với B"},{"en":"compare favourably with","vi":"không thua kém gì"}],"wordFamily":["comparison (n.)","comparable (adj.)","comparative (adj.)","comparatively (adv.)"],"synonyms":["liken"],"antonyms":[],"tipVi":"Cấu trúc so sánh có thể đi với with hoặc to; khi dùng để ẩn dụ, ví von thì thường dùng với to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_perhaps', 'en-a2-16', 'perhaps', '/pərˈhæps/', 'A2', 'có lẽ; có thể; có khi; có lẽ nào (dùng để đưa ra gợi ý hoặc thỉnh cầu một cách tế nhị)', 'adv.', NULL, 'Đồng nghĩa: maybe, possibly', 'perhaps mang tính trang trọng hơn một chút so với maybe, có thể đặt ở đầu câu để lời đề nghị trở nên lịch sự, uyển chuyển hơn.', 'Perhaps we should take an umbrella; those clouds look dark.', NULL, 'Có lẽ chúng ta nên mang theo ô; những đám mây kia trông có vẻ âm u quá.', '{"wordId":"perhaps","ukIpa":"/pəˈhæps/","usIpa":"/pərˈhæps/","cefr":"A2","topic":"thinking","senses":[{"pos":"adv.","en":"Used when something is possible but not certain.","vi":"có lẽ; có thể"},{"pos":"adv.","en":"Used to make a suggestion or request sound less direct.","vi":"có khi; có lẽ nào (dùng để đưa ra gợi ý hoặc thỉnh cầu một cách tế nhị)"}],"examples":[{"en":"Perhaps we should take an umbrella; those clouds look dark.","vi":"Có lẽ chúng ta nên mang theo ô; những đám mây kia trông có vẻ âm u quá.","audioKind":"ex"},{"en":"Perhaps governments could encourage healthier diets by making fresh produce more affordable for low-income households.","vi":"Chính phủ có lẽ có thể khuyến khích chế độ ăn uống lành mạnh hơn bằng cách giúp các hộ gia đình có thu nhập thấp dễ dàng mua được nông sản tươi hơn.","audioKind":"ex2"}],"collocations":[{"en":"perhaps not","vi":"có lẽ là không"},{"en":"perhaps the best","vi":"có lẽ là tốt nhất"},{"en":"perhaps we could","vi":"có lẽ chúng ta có thể"}],"wordFamily":[],"synonyms":["maybe","possibly"],"antonyms":[],"tipVi":"perhaps mang tính trang trọng hơn một chút so với maybe, có thể đặt ở đầu câu để lời đề nghị trở nên lịch sự, uyển chuyển hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_method', 'en-a2-16', 'method', '/ˈmeθəd/', 'A2', 'phương pháp; cách thức; hệ thống; quy củ', 'n.', 'methodical (adj.), methodically (adv.), methodology (n.)', 'Đồng nghĩa: technique, approach', 'Thường dùng cấu trúc a method of/for doing sth để chỉ phương pháp làm việc gì đó.', 'This method keeps my herbs fresh for several days.', NULL, 'Phương pháp này giúp các loại rau thơm của tôi tươi được trong vài ngày.', '{"wordId":"method","ukIpa":"/ˈmeθəd/","usIpa":"/ˈmeθəd/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"A particular way of doing something.","vi":"phương pháp; cách thức"},{"pos":"n.","en":"An organized and systematic approach to an activity.","vi":"hệ thống; quy củ"}],"examples":[{"en":"This method keeps my herbs fresh for several days.","vi":"Phương pháp này giúp các loại rau thơm của tôi tươi được trong vài ngày.","audioKind":"ex"},{"en":"Teachers should adapt their teaching methods to meet the varied needs of students in mixed-ability classrooms.","vi":"Giáo viên nên điều chỉnh phương pháp giảng dạy để đáp ứng nhu cầu đa dạng của học sinh trong các lớp học có trình độ khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"teaching method","vi":"phương pháp giảng dạy"},{"en":"research method","vi":"phương pháp nghiên cứu"},{"en":"method of payment","vi":"phương thức thanh toán"},{"en":"effective method","vi":"phương pháp hiệu quả"}],"wordFamily":["methodical (adj.)","methodically (adv.)","methodology (n.)"],"synonyms":["technique","approach"],"antonyms":[],"tipVi":"Thường dùng cấu trúc a method of/for doing sth để chỉ phương pháp làm việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_according', 'en-a2-16', 'according', '/əˈkɔːr.dɪŋ/', 'A2', 'theo như; theo lời; tùy theo; theo', 'phr.', 'accord (v.), accordance (n.)', NULL, 'Thường đi trong cụm according to, không đứng độc lập như một tính từ.', 'According to the forecast, rain will arrive this evening.', NULL, 'Theo dự báo, trời sẽ đổ mưa vào tối nay.', '{"wordId":"according","ukIpa":"/əˈkɔː.dɪŋ/","usIpa":"/əˈkɔːr.dɪŋ/","cefr":"A2","topic":"thinking","senses":[{"pos":"phr.","en":"As stated or reported by someone or something","vi":"theo như; theo lời"},{"pos":"phr.","en":"In a way determined by a rule or particular factor","vi":"tùy theo; theo"}],"examples":[{"en":"According to the forecast, rain will arrive this evening.","vi":"Theo dự báo, trời sẽ đổ mưa vào tối nay.","audioKind":"ex"},{"en":"Public funding should be distributed according to local needs rather than the political influence of individual regions.","vi":"Quỹ công nên được phân bổ theo nhu cầu của địa phương thay vì ảnh hưởng chính trị của từng khu vực riêng lẻ.","audioKind":"ex2"}],"collocations":[{"en":"according to research","vi":"theo nghiên cứu"},{"en":"according to plan","vi":"theo đúng kế hoạch"},{"en":"according to need","vi":"tùy theo nhu cầu"}],"wordFamily":["accord (v.)","accordance (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường đi trong cụm according to, không đứng độc lập như một tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cause', 'en-a2-16', 'cause', '/kɔːz/', 'A2', 'nguyên nhân, căn nguyên; gây ra, làm cho (điều gì đó bất lợi xảy ra); sự nghiệp, mục đích cao đẹp', 'n.', 'causal (adj.), causation (n.)', NULL, 'Danh từ thường đi với giới từ "of"; động từ có cấu trúc "cause sb to do sth".', 'The plumber found the cause of the leak.', NULL, 'Thợ sửa ống nước đã tìm ra nguyên nhân gây rò rỉ.', '{"wordId":"cause","ukIpa":"/kɔːz/","usIpa":"/kɔːz/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"something that makes an event or situation happen","vi":"nguyên nhân, căn nguyên"},{"pos":"v.","en":"make something happen, especially something unpleasant","vi":"gây ra, làm cho (điều gì đó bất lợi xảy ra)"},{"pos":"n.","en":"an aim or principle that people support and work towards","vi":"sự nghiệp, mục đích cao đẹp"}],"examples":[{"en":"The plumber found the cause of the leak.","vi":"Thợ sửa ống nước đã tìm ra nguyên nhân gây rò rỉ.","audioKind":"ex"},{"en":"Heavy traffic is a major cause of air pollution in many rapidly growing urban areas.","vi":"Tình trạng giao thông ùn tắc là nguyên nhân chính gây ô nhiễm không khí ở nhiều khu vực đô thị đang phát triển nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"cause of","vi":"nguyên nhân của"},{"en":"cause damage","vi":"gây thiệt hại"},{"en":"root cause","vi":"nguyên nhân gốc rễ"},{"en":"a good cause","vi":"một nghĩa cử cao đẹp, một sự nghiệp chính nghĩa"}],"wordFamily":["causal (adj.)","causation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ thường đi với giới từ \"of\"; động từ có cấu trúc \"cause sb to do sth\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attention', 'en-a2-16', 'attention', '/əˈtenʃən/', 'A2', 'sự chú ý; sự tập trung; sự quan tâm; sự chăm sóc; sự xử lý', 'n.', 'attentive (adj.), attentively (adv.), inattentive (adj.)', 'Trái nghĩa: inattention', 'Sau pay attention to là một danh từ hoặc danh động từ, trong đó to đóng vai trò là giới từ.', 'Please pay attention while I explain the game.', NULL, 'Xin hãy chú ý lắng nghe trong lúc tôi giải thích trò chơi.', '{"wordId":"attention","ukIpa":"/əˈtenʃən/","usIpa":"/əˈtenʃən/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"The act of focusing your mind on someone or something.","vi":"sự chú ý; sự tập trung"},{"pos":"n.","en":"Care or action given to someone or something that needs it.","vi":"sự quan tâm; sự chăm sóc; sự xử lý"}],"examples":[{"en":"Please pay attention while I explain the game.","vi":"Xin hãy chú ý lắng nghe trong lúc tôi giải thích trò chơi.","audioKind":"ex"},{"en":"Schools should give greater attention to students'' emotional wellbeing alongside their academic progress.","vi":"Các nhà trường nên dành sự quan tâm lớn hơn đến sức khỏe tinh thần của học sinh bên cạnh tiến độ học tập của các em.","audioKind":"ex2"}],"collocations":[{"en":"pay attention to","vi":"chú ý đến"},{"en":"attract attention","vi":"thu hút sự chú ý"},{"en":"medical attention","vi":"chăm sóc y tế"},{"en":"attention span","vi":"thời gian tập trung"}],"wordFamily":["attentive (adj.)","attentively (adv.)","inattentive (adj.)"],"synonyms":[],"antonyms":["inattention"],"tipVi":"Sau pay attention to là một danh từ hoặc danh động từ, trong đó to đóng vai trò là giới từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_decide', 'en-a2-16', 'decide', '/dɪˈsaɪd/', 'A2', 'quyết định; lựa chọn; định đoạt kết quả', 'v.', 'decision (n.), decisive (adj.), decisively (adv.), indecisive (adj.)', NULL, 'Đi với cấu trúc decide to do, không dùng decide doing.', 'We decided to walk home after the film.', NULL, 'Chúng tôi đã quyết định đi bộ về nhà sau khi xem phim.', '{"wordId":"decide","ukIpa":"/dɪˈsaɪd/","usIpa":"/dɪˈsaɪd/","cefr":"A2","topic":"thinking","senses":[{"pos":"v.","en":"To choose what to do after considering the possibilities.","vi":"quyết định; lựa chọn"},{"pos":"v.","en":"To determine the result of something.","vi":"định đoạt kết quả"}],"examples":[{"en":"We decided to walk home after the film.","vi":"Chúng tôi đã quyết định đi bộ về nhà sau khi xem phim.","audioKind":"ex"},{"en":"Governments must decide how to distribute limited resources between healthcare, education and public transport.","vi":"Chính phủ phải quyết định cách phân bổ các nguồn lực hạn chế giữa y tế, giáo dục và giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"decide to do something","vi":"quyết định làm điều gì đó"},{"en":"decide on","vi":"chọn lựa; quyết định chọn"},{"en":"decide against","vi":"quyết định không chọn; phản đối"},{"en":"decide the outcome","vi":"định đoạt kết quả"}],"wordFamily":["decision (n.)","decisive (adj.)","decisively (adv.)","indecisive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Đi với cấu trúc decide to do, không dùng decide doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mind', 'en-a2-16', 'mind', '/maɪnd/', 'A2', 'tâm trí; đầu óc; trí tuệ; bận lòng; phiền lòng; phản đối; lưu ý; cẩn thận; trông nom', 'n.', 'mindful (adj.), mindless (adj.), mindfulness (n.)', NULL, 'Diễn đạt việc phiền làm gì dùng mind doing, không dùng mind to do.', 'Would you mind closing the window before you leave?', NULL, 'Bạn có phiền đóng cửa sổ lại trước khi rời đi không?', '{"wordId":"mind","ukIpa":"/maɪnd/","usIpa":"/maɪnd/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"The part of you that thinks, feels, and remembers.","vi":"tâm trí; đầu óc; trí tuệ"},{"pos":"v.","en":"To feel annoyed or uncomfortable about something.","vi":"bận lòng; phiền lòng; phản đối"},{"pos":"v.","en":"To pay attention to something or take care of someone.","vi":"lưu ý; cẩn thận; trông nom"}],"examples":[{"en":"Would you mind closing the window before you leave?","vi":"Bạn có phiền đóng cửa sổ lại trước khi rời đi không?","audioKind":"ex"},{"en":"Regular physical activity can benefit both the body and the mind by reducing stress and improving concentration.","vi":"Hoạt động thể chất thường xuyên có thể mang lại lợi ích cho cả thể chất lẫn tinh thần bằng cách giảm căng thẳng và cải thiện sự tập trung.","audioKind":"ex2"}],"collocations":[{"en":"change your mind","vi":"thay đổi ý định"},{"en":"keep in mind","vi":"ghi nhớ; khắc ghi"},{"en":"mind doing something","vi":"phiền làm điều gì đó"},{"en":"peace of mind","vi":"sự yên bình trong tâm hồn"}],"wordFamily":["mindful (adj.)","mindless (adj.)","mindfulness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Diễn đạt việc phiền làm gì dùng mind doing, không dùng mind to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_goal', 'en-a2-16', 'goal', '/ɡoʊl/', 'A2', 'mục tiêu; đích đến; bàn thắng; điểm số; khung thành; cầu môn', 'n.', NULL, 'Đồng nghĩa: aim, objective, target', 'Mục tiêu dùng set hoặc achieve; ghi bàn dùng score a goal.', 'My goal is to swim across the pool unaided.', NULL, 'Mục tiêu của tôi là bơi qua bể bơi mà không cần sự trợ giúp.', '{"wordId":"goal","ukIpa":"/ɡəʊl/","usIpa":"/ɡoʊl/","cefr":"A2","topic":"thinking","senses":[{"pos":"n.","en":"Something you want to accomplish through effort.","vi":"mục tiêu; đích đến"},{"pos":"n.","en":"A score made by sending a ball into a goal.","vi":"bàn thắng; điểm số"},{"pos":"n.","en":"A frame or area players aim to send a ball into.","vi":"khung thành; cầu môn"}],"examples":[{"en":"My goal is to swim across the pool unaided.","vi":"Mục tiêu của tôi là bơi qua bể bơi mà không cần sự trợ giúp.","audioKind":"ex"},{"en":"Setting realistic goals can help university students manage their time and maintain motivation during demanding courses.","vi":"Việc đặt ra các mục tiêu thực tế có thể giúp sinh viên đại học quản lý thời gian và duy trì động lực trong các khóa học đòi hỏi cao.","audioKind":"ex2"}],"collocations":[{"en":"set a goal","vi":"đặt ra mục tiêu"},{"en":"achieve a goal","vi":"đạt được mục tiêu"},{"en":"a long-term goal","vi":"mục tiêu dài hạn"},{"en":"score a goal","vi":"ghi bàn"}],"wordFamily":[],"synonyms":["aim","objective","target"],"antonyms":[],"tipVi":"Mục tiêu dùng set hoặc achieve; ghi bàn dùng score a goal.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_although', 'en-a2-16', 'although', '/ɔːlˈðoʊ/', 'A2', 'mặc dù; dù', 'conj.', NULL, 'Đồng nghĩa: though, even though', 'Dùng để dẫn dắt mệnh đề nhượng bộ; trong cùng một câu thường không dùng thêm "but" để nối mệnh đề chính.', 'Although it was raining, we still walked home.', NULL, 'Mặc dù trời đang mưa, chúng tôi vẫn đi bộ về nhà.', '{"wordId":"although","ukIpa":"/ɔːlˈðəʊ/","usIpa":"/ɔːlˈðoʊ/","cefr":"A2","topic":"thinking","senses":[{"pos":"conj.","en":"despite the fact that","vi":"mặc dù; dù"}],"examples":[{"en":"Although it was raining, we still walked home.","vi":"Mặc dù trời đang mưa, chúng tôi vẫn đi bộ về nhà.","audioKind":"ex"},{"en":"Although renewable energy requires substantial initial investment, it can lower electricity costs in the long term.","vi":"Mặc dù năng lượng tái tạo đòi hỏi khoản đầu tư ban đầu đáng kể, nhưng về lâu dài nó có thể làm giảm chi phí điện năng.","audioKind":"ex2"}],"collocations":[{"en":"although it is true that","vi":"mặc dù đúng là"},{"en":"although not always","vi":"dù không phải lúc nào cũng"}],"wordFamily":[],"synonyms":["though","even though"],"antonyms":[],"tipVi":"Dùng để dẫn dắt mệnh đề nhượng bộ; trong cùng một câu thường không dùng thêm \"but\" để nối mệnh đề chính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suppose', 'en-a2-16', 'suppose', '/səˈpoʊz/', 'A2', 'cho là; nghĩ rằng; đoán rằng (khi chưa chắc chắn); giả sử; giả định (một tình huống để xem xét hậu quả của nó)', 'v.', 'supposition (n.), supposed (adj.), supposedly (adv.)', 'Đồng nghĩa: assume, presume', 'Cấu trúc be supposed to diễn tả nghĩa nên làm hoặc có lịch trình, sự sắp xếp để làm gì.', 'I suppose we can eat outside if it stays warm.', NULL, 'Tôi nghĩ chúng ta có thể ăn ngoài nếu trời vẫn ấm áp như thế này.', '{"wordId":"suppose","ukIpa":"/səˈpəʊz/","usIpa":"/səˈpoʊz/","cefr":"A2","topic":"thinking","senses":[{"pos":"v.","en":"To think something is probably true without being certain.","vi":"cho là; nghĩ rằng; đoán rằng (khi chưa chắc chắn)"},{"pos":"v.","en":"To imagine a situation in order to consider its consequences.","vi":"giả sử; giả định (một tình huống để xem xét hậu quả của nó)"}],"examples":[{"en":"I suppose we can eat outside if it stays warm.","vi":"Tôi nghĩ chúng ta có thể ăn ngoài nếu trời vẫn ấm áp như thế này.","audioKind":"ex"},{"en":"Suppose every household used less electricity; the combined reduction in demand could significantly benefit the environment.","vi":"Giả sử mọi hộ gia đình đều tiêu thụ ít điện năng hơn; sự sụt giảm tổng nhu cầu đó có thể mang lại lợi ích đáng kể cho môi trường.","audioKind":"ex2"}],"collocations":[{"en":"I suppose so","vi":"tôi nghĩ vậy"},{"en":"suppose that","vi":"giả sử rằng"},{"en":"be supposed to do","vi":"được cho là phải làm gì; theo kế hoạch sẽ làm gì"}],"wordFamily":["supposition (n.)","supposed (adj.)","supposedly (adv.)"],"synonyms":["assume","presume"],"antonyms":[],"tipVi":"Cấu trúc be supposed to diễn tả nghĩa nên làm hoặc có lịch trình, sự sắp xếp để làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_certain', 'en-a2-16', 'certain', '/ˈsɝːtən/', 'A2', 'chắc chắn; quả quyết; chắc chắn sẽ xảy ra; một số; nào đó', 'adj.', 'certainty (n.), certainly (adv.), uncertain (adj.), uncertainty (n.)', 'Đồng nghĩa: sure · Trái nghĩa: uncertain', 'Khi dùng chủ ngữ chỉ người, certain of diễn tả sự chắc chắn; certain to diễn tả điều tất yếu sẽ xảy ra.', 'I''m certain I left my keys on the kitchen table.', NULL, 'Tôi chắc chắn rằng mình đã để chìa khóa trên bàn bếp.', '{"wordId":"certain","ukIpa":"/ˈsɜːtən/","usIpa":"/ˈsɝːtən/","cefr":"A2","topic":"thinking","senses":[{"pos":"adj.","en":"having no doubt about something","vi":"chắc chắn; quả quyết"},{"pos":"adj.","en":"definitely going to happen","vi":"chắc chắn sẽ xảy ra"},{"pos":"adj.","en":"particular but not named or fully described","vi":"một số; nào đó"}],"examples":[{"en":"I''m certain I left my keys on the kitchen table.","vi":"Tôi chắc chắn rằng mình đã để chìa khóa trên bàn bếp.","audioKind":"ex"},{"en":"Certain types of public transport are more suitable for densely populated cities than rural areas.","vi":"Một số loại phương tiện giao thông công cộng phù hợp với các thành phố đông dân cư hơn là các vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"certain of","vi":"chắc chắn về"},{"en":"certain to happen","vi":"chắc chắn sẽ xảy ra"},{"en":"make certain","vi":"đảm bảo cho chắc"},{"en":"certain types of","vi":"một số loại"}],"wordFamily":["certainty (n.)","certainly (adv.)","uncertain (adj.)","uncertainty (n.)"],"synonyms":["sure"],"antonyms":["uncertain"],"tipVi":"Khi dùng chủ ngữ chỉ người, certain of diễn tả sự chắc chắn; certain to diễn tả điều tất yếu sẽ xảy ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_solve', 'en-a2-16', 'solve', '/sɑːlv/', 'A2', 'giải quyết; giải đáp', 'v.', 'solution (n.), solvable (adj.), unsolved (adj.)', 'Đồng nghĩa: resolve', 'solve đi trực tiếp với vấn đề; "làm tan/hòa tan" dùng dissolve.', 'We solved the puzzle together after dinner last night.', NULL, 'Chúng tôi đã cùng nhau giải câu đố sau bữa tối tối qua.', '{"wordId":"solve","ukIpa":"/sɒlv/","usIpa":"/sɑːlv/","cefr":"A2","topic":"thinking","senses":[{"pos":"v.","en":"Find an answer to a problem or mystery","vi":"giải quyết; giải đáp"}],"examples":[{"en":"We solved the puzzle together after dinner last night.","vi":"Chúng tôi đã cùng nhau giải câu đố sau bữa tối tối qua.","audioKind":"ex"},{"en":"Improving public transport could help solve traffic problems in rapidly growing urban areas.","vi":"Cải thiện giao thông công cộng có thể giúp giải quyết các vấn đề giao thông ở các khu đô thị đang phát triển nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"solve a problem","vi":"giải quyết vấn đề"},{"en":"solve a puzzle","vi":"giải câu đố"},{"en":"solve an equation","vi":"giải phương trình"}],"wordFamily":["solution (n.)","solvable (adj.)","unsolved (adj.)"],"synonyms":["resolve"],"antonyms":[],"tipVi":"solve đi trực tiếp với vấn đề; \"làm tan/hòa tan\" dùng dissolve.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disagree', 'en-a2-16', 'disagree', '/ˌdɪsəˈɡriː/', 'A2', 'bất đồng ý kiến; không đồng tình; không khớp; khác nhau', 'v.', 'agree (v.), disagreement (n.), agreement (n.)', 'Đồng nghĩa: differ · Trái nghĩa: agree', 'Không đồng tình với ai dùng disagree with; khi nói về chủ đề tranh luận, dùng on hoặc about.', 'We disagree about which colour to paint the kitchen.', NULL, 'Chúng tôi bất đồng về việc nên sơn phòng bếp màu gì.', '{"wordId":"disagree","ukIpa":"/ˌdɪsəˈɡriː/","usIpa":"/ˌdɪsəˈɡriː/","cefr":"A2","topic":"thinking","senses":[{"pos":"v.","en":"To have a different opinion from someone else.","vi":"bất đồng ý kiến; không đồng tình"},{"pos":"v.","en":"To give different information or results.","vi":"không khớp; khác nhau"}],"examples":[{"en":"We disagree about which colour to paint the kitchen.","vi":"Chúng tôi bất đồng về việc nên sơn phòng bếp màu gì.","audioKind":"ex"},{"en":"Experts disagree on whether free public transport is the most effective way to reduce urban traffic.","vi":"Các chuyên gia vẫn còn ý kiến trái chiều về việc liệu giao thông công cộng miễn phí có phải là giải pháp hiệu quả nhất để giảm tải ùn tắc giao thông đô thị hay không.","audioKind":"ex2"}],"collocations":[{"en":"disagree with someone","vi":"bất đồng với ai đó"},{"en":"disagree about something","vi":"bất đồng về điều gì"},{"en":"strongly disagree","vi":"kịch liệt phản đối"}],"wordFamily":["agree (v.)","disagreement (n.)","agreement (n.)"],"synonyms":["differ"],"antonyms":["agree"],"tipVi":"Không đồng tình với ai dùng disagree with; khi nói về chủ đề tranh luận, dùng on hoặc about.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_according-to', 'en-a2-16', 'according to', '/əˈkɔːrdɪŋ tə/', 'A2', 'theo như; dựa theo; tuân theo; chiếu theo', 'prep.', NULL, NULL, 'Dùng according to khi trích dẫn quan điểm của người khác; khi nêu ý kiến cá nhân dùng in my opinion.', 'According to the forecast, rain will arrive this afternoon.', NULL, 'Theo dự báo thời tiết, chiều nay trời sẽ đổ mưa.', '{"wordId":"according-to","ukIpa":"/əˈkɔːdɪŋ tə/","usIpa":"/əˈkɔːrdɪŋ tə/","cefr":"A2","topic":"thinking","senses":[{"pos":"prep.","en":"as stated or reported by someone or something","vi":"theo như; dựa theo"},{"pos":"prep.","en":"following a rule, plan, or particular standard","vi":"tuân theo; chiếu theo"}],"examples":[{"en":"According to the forecast, rain will arrive this afternoon.","vi":"Theo dự báo thời tiết, chiều nay trời sẽ đổ mưa.","audioKind":"ex"},{"en":"According to recent research, regular physical activity can improve concentration and reduce stress among university students.","vi":"Theo các nghiên cứu gần đây, việc duy trì vận động thể chất đều đặn có thể cải thiện sự tập trung và giảm bớt căng thẳng cho sinh viên đại học.","audioKind":"ex2"}],"collocations":[{"en":"according to research","vi":"theo nghiên cứu"},{"en":"according to plan","vi":"theo đúng kế hoạch"},{"en":"according to the rules","vi":"tuân thủ quy định"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dùng according to khi trích dẫn quan điểm của người khác; khi nêu ý kiến cá nhân dùng in my opinion.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_possibly', 'en-a2-16', 'possibly', '/ˈpɑːsəbli/', 'A2', 'có thể; có lẽ; đến mức có thể; dẫu có thể (nhấn mạnh khả năng hoặc sự khó khăn)', 'adv.', 'possible (adj.), possibility (n.), impossible (adj.)', 'Đồng nghĩa: perhaps, maybe · Trái nghĩa: definitely', 'Cụm can''t possibly mang nghĩa "hoàn toàn không thể", với sắc thái nhấn mạnh rất mạnh.', 'We could possibly have a picnic if the rain stops.', NULL, 'Chúng ta có lẽ sẽ đi dã ngoại nếu trời tạnh mưa.', '{"wordId":"possibly","ukIpa":"/ˈpɒsəbli/","usIpa":"/ˈpɑːsəbli/","cefr":"A2","topic":"thinking","senses":[{"pos":"adv.","en":"Used when something may happen or may be true.","vi":"có thể; có lẽ"},{"pos":"adv.","en":"Used with can or could to emphasise possibility or difficulty.","vi":"đến mức có thể; dẫu có thể (nhấn mạnh khả năng hoặc sự khó khăn)"}],"examples":[{"en":"We could possibly have a picnic if the rain stops.","vi":"Chúng ta có lẽ sẽ đi dã ngoại nếu trời tạnh mưa.","audioKind":"ex"},{"en":"Expanding urban green spaces could possibly reduce summer temperatures while improving residents'' physical and mental health.","vi":"Việc mở rộng không gian xanh đô thị có thể giúp giảm nhiệt độ mùa hè đồng thời cải thiện sức khỏe thể chất và tinh thần cho cư dân.","audioKind":"ex2"}],"collocations":[{"en":"could possibly","vi":"có lẽ có thể"},{"en":"quite possibly","vi":"rất có khả năng"},{"en":"can''t possibly","vi":"hoàn toàn không thể"}],"wordFamily":["possible (adj.)","possibility (n.)","impossible (adj.)"],"synonyms":["perhaps","maybe"],"antonyms":["definitely"],"tipVi":"Cụm can''t possibly mang nghĩa \"hoàn toàn không thể\", với sắc thái nhấn mạnh rất mạnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suggest', 'en-a2-16', 'suggest', '/səɡˈdʒest/', 'A2', 'đề xuất; gợi ý; cho thấy; ngụ ý', 'v.', 'suggestion (n.), suggestive (adj.)', 'Đồng nghĩa: propose, recommend', 'Dùng suggest doing hoặc suggest that mệnh đề, không dùng suggest to do.', 'I suggest taking an umbrella because those clouds look dark.', NULL, 'Tôi khuyên bạn nên mang theo ô vì mấy đám mây kia trông có vẻ đen kịt.', '{"wordId":"suggest","ukIpa":"/səˈdʒest/","usIpa":"/səɡˈdʒest/","cefr":"A2","topic":"thinking","senses":[{"pos":"v.","en":"To offer an idea or possible action for consideration.","vi":"đề xuất; gợi ý"},{"pos":"v.","en":"To indicate that something may be true.","vi":"cho thấy; ngụ ý"}],"examples":[{"en":"I suggest taking an umbrella because those clouds look dark.","vi":"Tôi khuyên bạn nên mang theo ô vì mấy đám mây kia trông có vẻ đen kịt.","audioKind":"ex"},{"en":"Recent studies suggest that access to green spaces can improve mental health among urban residents.","vi":"Các nghiên cứu gần đây cho thấy việc tiếp cận không gian xanh có thể cải thiện sức khỏe tinh thần của cư dân đô thị.","audioKind":"ex2"}],"collocations":[{"en":"suggest a solution","vi":"đưa ra giải pháp"},{"en":"suggest doing something","vi":"đề nghị làm điều gì đó"},{"en":"strongly suggest","vi":"gợi ý mạnh mẽ"},{"en":"evidence suggests that","vi":"bằng chứng cho thấy"}],"wordFamily":["suggestion (n.)","suggestive (adj.)"],"synonyms":["propose","recommend"],"antonyms":[],"tipVi":"Dùng suggest doing hoặc suggest that mệnh đề, không dùng suggest to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_expect', 'en-a2-16', 'expect', '/ɪkˈspekt/', 'A2', 'dự đoán; trông đợi; đòi hỏi; mong đợi; chờ đợi; mong ngóng', 'v.', 'expectation (n.), expected (adj.), unexpected (adj.), expectancy (n.)', 'Đồng nghĩa: anticipate', 'expect nghiêng về việc tin rằng điều gì đó sẽ xảy ra, hope nghiêng về việc hy vọng điều gì đó xảy ra.', 'We expect rain, so take an umbrella with you.', NULL, 'Chúng tôi dự đoán trời sẽ mưa, vì vậy hãy mang theo ô nhé.', '{"wordId":"expect","ukIpa":"/ɪkˈspekt/","usIpa":"/ɪkˈspekt/","cefr":"A2","topic":"thinking","senses":[{"pos":"v.","en":"to believe that something will probably happen","vi":"dự đoán; trông đợi"},{"pos":"v.","en":"to regard something as necessary or reasonably required","vi":"đòi hỏi; mong đợi"},{"pos":"v.","en":"to believe someone or something will arrive soon","vi":"chờ đợi; mong ngóng"}],"examples":[{"en":"We expect rain, so take an umbrella with you.","vi":"Chúng tôi dự đoán trời sẽ mưa, vì vậy hãy mang theo ô nhé.","audioKind":"ex"},{"en":"Employers increasingly expect graduates to demonstrate practical skills as well as a strong understanding of their subject.","vi":"Các nhà tuyển dụng ngày càng mong đợi sinh viên tốt nghiệp thể hiện được các kỹ năng thực tế cũng như hiểu biết sâu sắc về chuyên ngành của họ.","audioKind":"ex2"}],"collocations":[{"en":"expect to do something","vi":"dự định làm gì"},{"en":"expect someone to do something","vi":"mong ai đó làm gì"},{"en":"fully expect","vi":"hoàn toàn mong đợi"},{"en":"as expected","vi":"như mong đợi"}],"wordFamily":["expectation (n.)","expected (adj.)","unexpected (adj.)","expectancy (n.)"],"synonyms":["anticipate"],"antonyms":[],"tipVi":"expect nghiêng về việc tin rằng điều gì đó sẽ xảy ra, hope nghiêng về việc hy vọng điều gì đó xảy ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_16_1', 'en-a2-16', 'Cách dùng “perhaps” (adv.) — có lẽ; có thể', 'perhaps not  ·  perhaps the best  ·  perhaps we could', 'perhaps mang tính trang trọng hơn một chút so với maybe, có thể đặt ở đầu câu để lời đề nghị trở nên lịch sự, uyển chuyển hơn.', 'Đồng nghĩa: maybe, possibly', '[{"hanzi":"Perhaps we should take an umbrella; those clouds look dark.","pinyin":"","meaning":"Có lẽ chúng ta nên mang theo ô; những đám mây kia trông có vẻ âm u quá."},{"hanzi":"Perhaps governments could encourage healthier diets by making fresh produce more affordable for low-income households.","pinyin":"","meaning":"Chính phủ có lẽ có thể khuyến khích chế độ ăn uống lành mạnh hơn bằng cách giúp các hộ gia đình có thu nhập thấp dễ dàng mua được nông sản tươi hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_16_2', 'en-a2-16', 'Cách dùng “although” (conj.) — mặc dù; dù', 'although it is true that  ·  although not always', 'Dùng để dẫn dắt mệnh đề nhượng bộ; trong cùng một câu thường không dùng thêm "but" để nối mệnh đề chính.', 'Đồng nghĩa: though, even though', '[{"hanzi":"Although it was raining, we still walked home.","pinyin":"","meaning":"Mặc dù trời đang mưa, chúng tôi vẫn đi bộ về nhà."},{"hanzi":"Although renewable energy requires substantial initial investment, it can lower electricity costs in the long term.","pinyin":"","meaning":"Mặc dù năng lượng tái tạo đòi hỏi khoản đầu tư ban đầu đáng kể, nhưng về lâu dài nó có thể làm giảm chi phí điện năng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_16_3', 'en-a2-16', 'Cách dùng “certain” (adj.) — chắc chắn; quả quyết', 'certain of  ·  certain to happen  ·  make certain', 'Khi dùng chủ ngữ chỉ người, certain of diễn tả sự chắc chắn; certain to diễn tả điều tất yếu sẽ xảy ra.', 'Họ từ (Word Family): certainty (n.), certainly (adv.), uncertain (adj.), uncertainty (n.) | Đồng nghĩa: sure · Trái nghĩa: uncertain', '[{"hanzi":"I''m certain I left my keys on the kitchen table.","pinyin":"","meaning":"Tôi chắc chắn rằng mình đã để chìa khóa trên bàn bếp."},{"hanzi":"Certain types of public transport are more suitable for densely populated cities than rural areas.","pinyin":"","meaning":"Một số loại phương tiện giao thông công cộng phù hợp với các thành phố đông dân cư hơn là các vùng nông thôn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_16_4', 'en-a2-16', 'Cách dùng “expect” (v.) — dự đoán; trông đợi', 'expect to do something  ·  expect someone to do something  ·  fully expect', 'expect nghiêng về việc tin rằng điều gì đó sẽ xảy ra, hope nghiêng về việc hy vọng điều gì đó xảy ra.', 'Họ từ (Word Family): expectation (n.), expected (adj.), unexpected (adj.), expectancy (n.) | Đồng nghĩa: anticipate', '[{"hanzi":"We expect rain, so take an umbrella with you.","pinyin":"","meaning":"Chúng tôi dự đoán trời sẽ mưa, vì vậy hãy mang theo ô nhé."},{"hanzi":"Employers increasingly expect graduates to demonstrate practical skills as well as a strong understanding of their subject.","pinyin":"","meaning":"Các nhà tuyển dụng ngày càng mong đợi sinh viên tốt nghiệp thể hiện được các kỹ năng thực tế cũng như hiểu biết sâu sắc về chuyên ngành của họ."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_16_1', 'en-a2-16', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
