INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_16_1_2', 'ten_a2_16_1', 'thought', 'A sudden thought made me check my coat pocket.', 'A sudden thought made me check my coat pocket.', '/θɔːt/', 'Một suy nghĩ chợt xuất hiện khiến tôi phải kiểm tra túi áo khoác.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
