INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_16_1_4', 'ten_a2_16_1', 'exact', 'Can you tell me the exact time we should arrive?', 'Can you tell me the exact time we should arrive?', '/ɪɡˈzækt/', 'Bạn có thể cho tôi biết chính xác thời gian chúng ta nên đến không?', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_16_1_5', 'ten_a2_16_1', 'compare', 'We compared several backpacks before choosing the lightest one.', 'We compared several backpacks before choosing the lightest one.', '/kəmˈper/', 'Chúng tôi đã so sánh vài chiếc ba lô trước khi chọn ra chiếc nhẹ nhất.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_16_1_6', 'ten_a2_16_1', 'perhaps', 'Perhaps we should take an umbrella; those clouds look dark.', 'Perhaps we should take an umbrella; those clouds look dark.', '/pərˈhæps/', 'Có lẽ chúng ta nên mang theo ô; những đám mây kia trông có vẻ âm u quá.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_16_1_7', 'ten_a2_16_1', 'method', 'This method keeps my herbs fresh for several days.', 'This method keeps my herbs fresh for several days.', '/ˈmeθəd/', 'Phương pháp này giúp các loại rau thơm của tôi tươi được trong vài ngày.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_16_1_8', 'ten_a2_16_1', 'according', 'According to the forecast, rain will arrive this evening.', 'According to the forecast, rain will arrive this evening.', '/əˈkɔːr.dɪŋ/', 'Theo dự báo, trời sẽ đổ mưa vào tối nay.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_16_1_1', 'en-a2-16', 'ten_a2_16_1', 'listening', 'listening', 'Your jacket looks similar to mine, but slightly darker.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một suy nghĩ chợt xuất hiện khiến tôi phải kiểm tra túi áo khoác.","Áo khoác của bạn trông tương tự như của tôi, nhưng tối màu hơn một chút.","Tôi khuyên bạn nên mang theo ô vì mấy đám mây kia trông có vẻ đen kịt.","Theo dự báo thời tiết, chiều nay trời sẽ đổ mưa."]'::jsonb, 1, 'Your jacket looks similar to mine, but slightly darker. → Áo khoác của bạn trông tương tự như của tôi, nhưng tối màu hơn một chút.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_16_1_2', 'en-a2-16', 'ten_a2_16_1', 'listening', 'listening', 'A sudden thought made me check my coat pocket.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một suy nghĩ chợt xuất hiện khiến tôi phải kiểm tra túi áo khoác.","Tôi khuyên bạn nên mang theo ô vì mấy đám mây kia trông có vẻ đen kịt.","Chúng tôi dự đoán trời sẽ mưa, vì vậy hãy mang theo ô nhé.","Bạn có thể cho tôi biết chính xác thời gian chúng ta nên đến không?"]'::jsonb, 0, 'A sudden thought made me check my coat pocket. → Một suy nghĩ chợt xuất hiện khiến tôi phải kiểm tra túi áo khoác.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_16_1_3', 'en-a2-16', 'ten_a2_16_1', 'listening', 'listening', 'What is your opinion of our new kitchen?', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi nghĩ chúng ta có thể ăn ngoài nếu trời vẫn ấm áp như thế này.","Chúng tôi đã quyết định đi bộ về nhà sau khi xem phim.","Chúng tôi đã cùng nhau giải câu đố sau bữa tối tối qua.","Bạn nghĩ thế nào về căn bếp mới của chúng tôi?"]'::jsonb, 3, 'What is your opinion of our new kitchen? → Bạn nghĩ thế nào về căn bếp mới của chúng tôi?', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_16_2', 'en-a2-16', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_16_2_1', 'ten_a2_16_2', 'similar', 'Cities with similar population sizes may require different transport policies because of their geographical features.', 'Cities with similar population sizes may require different transport policies because of their geographical features.', '/ˈsɪmələr/', 'Các thành phố có quy mô dân số tương tự có thể cần các chính sách giao thông khác nhau do đặc điểm địa lý của chúng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_16_2_2', 'ten_a2_16_2', 'thought', 'Urban planning requires careful thought about how public spaces can serve people of different ages.', 'Urban planning requires careful thought about how public spaces can serve people of different ages.', '/θɔːt/', 'Quy hoạch đô thị đòi hỏi phải suy ngẫm kỹ lưỡng về cách các không gian công cộng có thể phục vụ người dân ở mọi lứa tuổi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_16_2_3', 'ten_a2_16_2', 'opinion', 'In my opinion, public transport should be affordable enough to encourage people to leave their cars at home.', 'In my opinion, public transport should be affordable enough to encourage people to leave their cars at home.', '/əˈpɪnjən/', 'Theo quan điểm của tôi, phương tiện giao thông công cộng nên có giá cả phải chăng để khuyến khích mọi người để xe ở nhà.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_16_2_4', 'ten_a2_16_2', 'exact', 'Researchers need exact measurements to determine whether changes in air quality are linked to new transport policies.', 'Researchers need exact measurements to determine whether changes in air quality are linked to new transport policies.', '/ɪɡˈzækt/', 'Các nhà nghiên cứu cần số đo chính xác để xác định liệu sự thay đổi về chất lượng không khí có liên quan đến các chính sách giao thông mới hay không.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_16_2_5', 'ten_a2_16_2', 'compare', 'Researchers should compare the long-term costs of renewable energy with those of traditional power sources.', 'Researchers should compare the long-term costs of renewable energy with those of traditional power sources.', '/kəmˈper/', 'Các nhà nghiên cứu nên so sánh chi phí dài hạn của năng lượng tái tạo với các nguồn năng lượng truyền thống.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_16_2_6', 'ten_a2_16_2', 'perhaps', 'Perhaps governments could encourage healthier diets by making fresh produce more affordable for low-income households.', 'Perhaps governments could encourage healthier diets by making fresh produce more affordable for low-income households.', '/pərˈhæps/', 'Chính phủ có lẽ có thể khuyến khích chế độ ăn uống lành mạnh hơn bằng cách giúp các hộ gia đình có thu nhập thấp dễ dàng mua được nông sản tươi hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_16_2_1', 'en-a2-16', 'ten_a2_16_2', 'listening', 'listening', 'Cities with similar population sizes may require different transport policies because of their geographical features.', NULL, 'Trong câu vừa nghe, từ “similar” mang nghĩa nào sau đây?', '["thuộc châu âu; người châu âu","tương tự; giống nhau","vừa vặn; thích hợp; vừa","cát"]'::jsonb, 1, '“similar” (/ˈsɪmələr/): tương tự; giống nhau. Câu đầy đủ: Cities with similar population sizes may require different transport policies because of their geographical features.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_16_2_2', 'en-a2-16', 'ten_a2_16_2', 'listening', 'listening', 'Urban planning requires careful thought about how public spaces can serve people of different ages.', NULL, 'Trong câu vừa nghe, từ “thought” mang nghĩa nào sau đây?', '["nổi tiếng; được nhiều người biết đến","môn lướt sóng","chắc chắn; dứt khoát; rạch ròi","ý nghĩ; suy nghĩ; ý kiến"]'::jsonb, 3, '“thought” (/θɔːt/): ý nghĩ; suy nghĩ; ý kiến. Câu đầy đủ: Urban planning requires careful thought about how public spaces can serve people of different ages.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
