INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_3', 'en-a2-16', NULL, 'comprehensive_test', 'listening', 'opinion', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["gây ngạc nhiên; bất ngờ","tiếng ồn; tiếng động","vùng quê; miền quê","ý kiến; quan điểm; đánh giá"]'::jsonb, 3, 'opinion (/əˈpɪnjən/) → ý kiến; quan điểm; đánh giá', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_4', 'en-a2-16', NULL, 'comprehensive_test', 'listening', 'Can you tell me the exact time we should arrive?', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Một suy nghĩ chợt xuất hiện khiến tôi phải kiểm tra túi áo khoác.","Bạn nghĩ thế nào về căn bếp mới của chúng tôi?","Bạn có thể cho tôi biết chính xác thời gian chúng ta nên đến không?","Có lẽ chúng ta nên mang theo ô; những đám mây kia trông có vẻ âm u quá."]'::jsonb, 2, 'Can you tell me the exact time we should arrive? → Bạn có thể cho tôi biết chính xác thời gian chúng ta nên đến không?', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_5', 'en-a2-16', NULL, 'comprehensive_test', 'listening', 'compare', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vẻ đẹp; nét đẹp","so sánh; đối chiếu","phát âm; đọc","quả dứa; quả thơm"]'::jsonb, 1, 'compare (/kəmˈper/) → so sánh; đối chiếu; ví với; sánh kịp; bì được', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_6', 'en-a2-16', NULL, 'comprehensive_test', 'listening', 'Perhaps we should take an umbrella; those clouds look dark.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bạn có phiền đóng cửa sổ lại trước khi rời đi không?","Theo dự báo thời tiết, chiều nay trời sẽ đổ mưa.","Có lẽ chúng ta nên mang theo ô; những đám mây kia trông có vẻ âm u quá.","Tôi nghĩ chúng ta có thể ăn ngoài nếu trời vẫn ấm áp như thế này."]'::jsonb, 2, 'Perhaps we should take an umbrella; those clouds look dark. → Có lẽ chúng ta nên mang theo ô; những đám mây kia trông có vẻ âm u quá.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_7', 'en-a2-16', NULL, 'comprehensive_test', 'listening', 'method', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["không hút thuốc; cấm hút thuốc","mùa","cái phong bì; phong thư","phương pháp; cách thức"]'::jsonb, 3, 'method (/ˈmeθəd/) → phương pháp; cách thức; hệ thống; quy củ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_8', 'en-a2-16', NULL, 'comprehensive_test', 'listening', 'According to the forecast, rain will arrive this evening.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Theo dự báo, trời sẽ đổ mưa vào tối nay.","Tôi nghĩ chúng ta có thể ăn ngoài nếu trời vẫn ấm áp như thế này.","Chúng tôi bất đồng về việc nên sơn phòng bếp màu gì.","Theo dự báo thời tiết, chiều nay trời sẽ đổ mưa."]'::jsonb, 0, 'According to the forecast, rain will arrive this evening. → Theo dự báo, trời sẽ đổ mưa vào tối nay.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_9', 'en-a2-16', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To examine things to find similarities and differences.”?', '["similar","suppose","cause","compare"]'::jsonb, 3, 'compare (/kəmˈper/) → so sánh; đối chiếu', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_10', 'en-a2-16', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Used when something is possible but not certain.”?', '["thought","possibly","perhaps","compare"]'::jsonb, 2, 'perhaps (/pərˈhæps/) → có lẽ; có thể', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_11', 'en-a2-16', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A particular way of doing something.”?', '["method","cause","decide","possibly"]'::jsonb, 0, 'method (/ˈmeθəd/) → phương pháp; cách thức', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_12', 'en-a2-16', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “As stated or reported by someone or something”?', '["solve","according to","suppose","according"]'::jsonb, 3, 'according (/əˈkɔːr.dɪŋ/) → theo như; theo lời', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
