INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_18', 'en-a2-16', NULL, 'comprehensive_test', 'reading', NULL, 'Cities with similar population sizes may require different transport policies because of their geographical features.', 'Dựa vào câu trên, từ “similar” có nghĩa phù hợp nhất là gì?', '["thợ xây dựng; nhà thầu xây dựng","vấn đề; việc","tương tự; giống nhau","mục tiêu; đích đến"]'::jsonb, 2, 'similar: tương tự; giống nhau. Dịch cả câu: Các thành phố có quy mô dân số tương tự có thể cần các chính sách giao thông khác nhau do đặc điểm địa lý của chúng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_19', 'en-a2-16', NULL, 'comprehensive_test', 'reading', NULL, 'Urban planning requires careful thought about how public spaces can serve people of different ages.', 'Dựa vào câu trên, từ “thought” có nghĩa phù hợp nhất là gì?', '["sặc sỡ; rực rỡ; nhiều màu sắc","có màu vàng nhạt; tóc vàng","ý nghĩ; suy nghĩ; ý kiến","đại dương; biển lớn"]'::jsonb, 2, 'thought: ý nghĩ; suy nghĩ; ý kiến; sự suy ngẫm; sự cân nhắc; thì quá khứ và phân từ quá khứ của think. Dịch cả câu: Quy hoạch đô thị đòi hỏi phải suy ngẫm kỹ lưỡng về cách các không gian công cộng có thể phục vụ người dân ở mọi lứa tuổi.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_20', 'en-a2-16', NULL, 'comprehensive_test', 'reading', NULL, 'In my opinion, public transport should be affordable enough to encourage people to leave their cars at home.', 'Dựa vào câu trên, từ “opinion” có nghĩa phù hợp nhất là gì?', '["cứu; cứu sống; bảo vệ","vai; bả vai","ý kiến; quan điểm; đánh giá","nhảy; bật cao"]'::jsonb, 2, 'opinion: ý kiến; quan điểm; đánh giá. Dịch cả câu: Theo quan điểm của tôi, phương tiện giao thông công cộng nên có giá cả phải chăng để khuyến khích mọi người để xe ở nhà.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_21', 'en-a2-16', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers need exact measurements to determine whether changes in air quality are linked to new transport policies.', 'Dựa vào câu trên, từ “exact” có nghĩa phù hợp nhất là gì?', '["giấc mơ; giấc mộng","chính xác; đúng từng chi tiết","xoay sở thành công; làm được","bản báo cáo; tường thuật"]'::jsonb, 1, 'exact: chính xác; đúng từng chi tiết; bắt buộc phải có; đòi hỏi. Dịch cả câu: Các nhà nghiên cứu cần số đo chính xác để xác định liệu sự thay đổi về chất lượng không khí có liên quan đến các chính sách giao thông mới hay không.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_22', 'en-a2-16', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “có thể; có lẽ”', '["possibly","drama","unusual","couple"]'::jsonb, 0, 'có thể; có lẽ → possibly (/ˈpɑːsəbli/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_16_23', 'en-a2-16', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đề xuất; gợi ý”', '["pill","convenient","snowboarding","suggest"]'::jsonb, 3, 'đề xuất; gợi ý → suggest (/səɡˈdʒest/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
