INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-17', 'en', 'Bài 17: Cảm xúc & Tính cách - CEFR A2', 'CEFR A2', 'A2 · Cảm xúc', '27 từ vựng Tiếng Anh CEFR A2 chủ đề cảm xúc & tính cách kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2017, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_proud', 'en-a2-17', 'proud', '/praʊd/', 'A2', 'tự hào; hãnh diện; kiêu ngạo; tự phụ', 'adj.', 'pride (n.), proudly (adv.)', 'Đồng nghĩa: pleased, arrogant · Trái nghĩa: ashamed, humble', 'be proud of đi kèm danh từ hoặc danh động từ, biểu thị sự tự hào về điều gì.', 'He felt proud of the cake he baked himself.', NULL, 'Cậu ấy cảm thấy rất tự hào về chiếc bánh do chính tay mình nướng.', '{"wordId":"proud","ukIpa":"/praʊd/","usIpa":"/praʊd/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling pleased about achievements or people you care about.","vi":"tự hào; hãnh diện"},{"pos":"adj.","en":"Believing you are better or more important than others.","vi":"kiêu ngạo; tự phụ"}],"examples":[{"en":"He felt proud of the cake he baked himself.","vi":"Cậu ấy cảm thấy rất tự hào về chiếc bánh do chính tay mình nướng.","audioKind":"ex"},{"en":"Residents are often proud of their cultural heritage and support efforts to preserve historic buildings.","vi":"Cư dân thường tự hào về di sản văn hóa của họ và ủng hộ các nỗ lực bảo tồn các tòa nhà lịch sử.","audioKind":"ex2"}],"collocations":[{"en":"proud of","vi":"tự hào về"},{"en":"proud to be","vi":"vinh dự là; tự hào khi là"},{"en":"make someone proud","vi":"làm cho ai đó tự hào"},{"en":"too proud to ask","vi":"quá tự ái không dám hỏi"}],"wordFamily":["pride (n.)","proudly (adv.)"],"synonyms":["pleased","arrogant"],"antonyms":["ashamed","humble"],"tipVi":"be proud of đi kèm danh từ hoặc danh động từ, biểu thị sự tự hào về điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scary', 'en-a2-17', 'scary', '/ˈskeri/', 'A2', 'đáng sợ; làm hoảng sợ', 'adj.', 'scare (v.), scare (n.), scared (adj.)', 'Đồng nghĩa: frightening · Trái nghĩa: reassuring', '"scary" dùng để chỉ sự vật gây sợ hãi; "scared" dùng để tả cảm giác sợ hãi của con người.', 'That scary noise was just a branch against the window.', NULL, 'Âm thanh đáng sợ đó chỉ là tiếng cành cây cọ vào cửa sổ.', '{"wordId":"scary","ukIpa":"/ˈskeəri/","usIpa":"/ˈskeri/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"Making someone feel afraid or nervous.","vi":"đáng sợ; làm hoảng sợ"}],"examples":[{"en":"That scary noise was just a branch against the window.","vi":"Âm thanh đáng sợ đó chỉ là tiếng cành cây cọ vào cửa sổ.","audioKind":"ex"},{"en":"Starting school can be scary for young children, so teachers should create a welcoming environment.","vi":"Việc bắt đầu đi học có thể đáng sợ đối với trẻ nhỏ, vì vậy giáo viên nên tạo ra một môi trường thân thiện.","audioKind":"ex2"}],"collocations":[{"en":"scary movie","vi":"phim kinh dị"},{"en":"scary experience","vi":"trải nghiệm đáng sợ"},{"en":"look scary","vi":"trông đáng sợ"}],"wordFamily":["scare (v.)","scare (n.)","scared (adj.)"],"synonyms":["frightening"],"antonyms":["reassuring"],"tipVi":"\"scary\" dùng để chỉ sự vật gây sợ hãi; \"scared\" dùng để tả cảm giác sợ hãi của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lonely', 'en-a2-17', 'lonely', '/ˈloʊnli/', 'A2', 'cô đơn, buồn bã vì thiếu sự đồng hành hoặc các mối quan hệ gần gũi; hẻo lánh, xa xôi hoặc ít người lui tới', 'adj.', 'loneliness (n.), lone (adj.)', 'Đồng nghĩa: lonesome, isolated', 'Từ alone nhấn mạnh việc ở một mình về mặt thể chất; lonely nhấn mạnh cảm giác cô đơn trong tâm hồn.', 'I felt lonely until my neighbour invited me for tea.', NULL, 'Tôi từng cảm thấy cô đơn cho đến khi người hàng xóm mời tôi sang uống trà.', '{"wordId":"lonely","ukIpa":"/ˈləʊnli/","usIpa":"/ˈloʊnli/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"Unhappy because you lack companionship or close connections.","vi":"cô đơn, buồn bã vì thiếu sự đồng hành hoặc các mối quan hệ gần gũi"},{"pos":"adj.","en":"Far from people or rarely visited.","vi":"hẻo lánh, xa xôi hoặc ít người lui tới"}],"examples":[{"en":"I felt lonely until my neighbour invited me for tea.","vi":"Tôi từng cảm thấy cô đơn cho đến khi người hàng xóm mời tôi sang uống trà.","audioKind":"ex"},{"en":"Older adults may feel lonely after retirement, so community centres should provide regular opportunities for social interaction.","vi":"Người cao tuổi có thể cảm thấy cô đơn sau khi nghỉ hưu, vì vậy các trung tâm cộng đồng nên thường xuyên tạo cơ hội cho họ giao lưu xã hội.","audioKind":"ex2"}],"collocations":[{"en":"feel lonely","vi":"cảm thấy cô đơn"},{"en":"a lonely life","vi":"một cuộc sống cô đơn"},{"en":"a lonely road","vi":"một con đường hẻo lánh"}],"wordFamily":["loneliness (n.)","lone (adj.)"],"synonyms":["lonesome","isolated"],"antonyms":[],"tipVi":"Từ alone nhấn mạnh việc ở một mình về mặt thể chất; lonely nhấn mạnh cảm giác cô đơn trong tâm hồn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crazy', 'en-a2-17', 'crazy', '/ˈkreɪzi/', 'A2', 'điên rồ; ngớ ngẩn; bất hợp lý; kỳ quặc; phát cuồng; say mê; cuồng nhiệt; bực điên người; phát điên; cáu tiết', 'adj.', 'crazily (adv.), craziness (n.)', 'Đồng nghĩa: absurd, ridiculous · Trái nghĩa: sensible', 'Từ này mang văn phong thân mật, khẩu ngữ; cấu trúc crazy about diễn tả sự say mê, không dùng để chỉ các vấn đề y tế tâm thần.', 'It seems crazy to wear sandals in this snow.', NULL, 'Thật là điên rồ khi đi giày xăng-đan trong thời tiết có tuyết thế này.', '{"wordId":"crazy","ukIpa":"/ˈkreɪzi/","usIpa":"/ˈkreɪzi/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"very unreasonable, foolish, or strange","vi":"điên rồ; ngớ ngẩn; bất hợp lý; kỳ quặc"},{"pos":"adj.","en":"extremely enthusiastic about someone or something","vi":"phát cuồng; say mê; cuồng nhiệt"},{"pos":"adj.","en":"extremely annoyed or upset","vi":"bực điên người; phát điên; cáu tiết"}],"examples":[{"en":"It seems crazy to wear sandals in this snow.","vi":"Thật là điên rồ khi đi giày xăng-đan trong thời tiết có tuyết thế này.","audioKind":"ex"},{"en":"Although some people consider car-free cities a crazy idea, such policies could significantly improve urban air quality.","vi":"Mặc dù một số người coi các thành phố không có ô tô là một ý tưởng điên rồ, nhưng những chính sách như vậy có thể cải thiện đáng kể chất lượng không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"crazy about","vi":"phát cuồng vì..."},{"en":"drive someone crazy","vi":"làm ai đó phát điên"},{"en":"a crazy idea","vi":"một ý tưởng điên rồ"}],"wordFamily":["crazily (adv.)","craziness (n.)"],"synonyms":["absurd","ridiculous"],"antonyms":["sensible"],"tipVi":"Từ này mang văn phong thân mật, khẩu ngữ; cấu trúc crazy about diễn tả sự say mê, không dùng để chỉ các vấn đề y tế tâm thần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scared', 'en-a2-17', 'scared', '/skerd/', 'A2', 'sợ hãi; khiếp sợ; lo lắng', 'adj.', 'scare (v.), scary (adj.)', 'Đồng nghĩa: afraid, frightened · Trái nghĩa: unafraid', 'Tính từ scared dùng để diễn tả cảm giác sợ hãi của bản chất người, trong khi scary dùng để chỉ tính chất gây ra sợ hãi.', 'The puppy looked scared when it heard the thunder.', NULL, 'Chú cún con có vẻ rất sợ hãi khi nghe thấy tiếng sấm.', '{"wordId":"scared","ukIpa":"/skeəd/","usIpa":"/skerd/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling afraid of something or worried that something bad might happen.","vi":"sợ hãi; khiếp sợ; lo lắng"}],"examples":[{"en":"The puppy looked scared when it heard the thunder.","vi":"Chú cún con có vẻ rất sợ hãi khi nghe thấy tiếng sấm.","audioKind":"ex"},{"en":"Students who are scared of making mistakes may avoid speaking during foreign language lessons.","vi":"Những học sinh sợ mắc lỗi có thể sẽ tránh phát biểu trong các giờ học ngoại ngữ.","audioKind":"ex2"}],"collocations":[{"en":"scared of","vi":"sợ hãi cái gì"},{"en":"scared to ask","vi":"ngại không dám hỏi"},{"en":"scared stiff","vi":"sợ cứng cả người"}],"wordFamily":["scare (v.)","scary (adj.)"],"synonyms":["afraid","frightened"],"antonyms":["unafraid"],"tipVi":"Tính từ scared dùng để diễn tả cảm giác sợ hãi của bản chất người, trong khi scary dùng để chỉ tính chất gây ra sợ hãi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_surprised', 'en-a2-17', 'surprised', '/sərˈpraɪzd/', 'A2', 'ngạc nhiên; bất ngờ', 'adj.', 'surprise (n.), surprise (v.), surprising (adj.), surprisingly (adv.)', 'Đồng nghĩa: astonished, amazed · Trái nghĩa: unsurprised', 'surprised dùng để miêu tả cảm xúc của con người; surprising dùng để chỉ sự vật, sự việc gây ngạc nhiên.', 'I was surprised to find flowers outside my door.', NULL, 'Tôi rất ngạc nhiên khi thấy những bông hoa ở trước cửa nhà mình.', '{"wordId":"surprised","ukIpa":"/səˈpraɪzd/","usIpa":"/sərˈpraɪzd/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling that something unexpected has happened.","vi":"ngạc nhiên; bất ngờ"}],"examples":[{"en":"I was surprised to find flowers outside my door.","vi":"Tôi rất ngạc nhiên khi thấy những bông hoa ở trước cửa nhà mình.","audioKind":"ex"},{"en":"Researchers were surprised by how strongly access to green spaces influenced residents'' reported levels of wellbeing.","vi":"Các nhà nghiên cứu đã rất ngạc nhiên trước mức độ ảnh hưởng mạnh mẽ của việc tiếp cận không gian xanh đối với mức độ hạnh phúc tự báo cáo của người dân.","audioKind":"ex2"}],"collocations":[{"en":"surprised at the result","vi":"ngạc nhiên về kết quả"},{"en":"pleasantly surprised","vi":"bất ngờ thú vị"},{"en":"surprised to hear","vi":"ngạc nhiên khi nghe thấy"}],"wordFamily":["surprise (n.)","surprise (v.)","surprising (adj.)","surprisingly (adv.)"],"synonyms":["astonished","amazed"],"antonyms":["unsurprised"],"tipVi":"surprised dùng để miêu tả cảm xúc của con người; surprising dùng để chỉ sự vật, sự việc gây ngạc nhiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fantastic', 'en-a2-17', 'fantastic', '/fænˈtæstɪk/', 'A2', 'cực kỳ tốt; tuyệt vời; kỳ ảo; mang tính tưởng tượng; cực kỳ lớn; khổng lồ', 'adj.', 'fantastically (adv.), fantasy (n.)', 'Đồng nghĩa: excellent, wonderful · Trái nghĩa: terrible', 'Từ "fantastic" mang nghĩa "cực kỳ tốt" thường dùng trong văn nói hàng ngày; trong văn viết trang trọng, có thể dùng "excellent".', 'We had a fantastic view of the mountains from our balcony.', NULL, 'Từ ban công, chúng tôi có thể ngắm nhìn trọn vẹn khung cảnh núi non tuyệt đẹp.', '{"wordId":"fantastic","ukIpa":"/fænˈtæstɪk/","usIpa":"/fænˈtæstɪk/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"extremely good or enjoyable","vi":"cực kỳ tốt; tuyệt vời"},{"pos":"adj.","en":"strange and imaginative, rather than realistic","vi":"kỳ ảo; mang tính tưởng tượng"},{"pos":"adj.","en":"extremely large in amount or degree","vi":"cực kỳ lớn; khổng lồ"}],"examples":[{"en":"We had a fantastic view of the mountains from our balcony.","vi":"Từ ban công, chúng tôi có thể ngắm nhìn trọn vẹn khung cảnh núi non tuyệt đẹp.","audioKind":"ex"},{"en":"Community sports programmes offer young people a fantastic opportunity to develop teamwork skills and build confidence.","vi":"Các chương trình thể thao cộng đồng mang lại cho giới trẻ cơ hội tuyệt vời để phát triển kỹ năng làm việc nhóm và xây dựng lòng tự tin.","audioKind":"ex2"}],"collocations":[{"en":"fantastic opportunity","vi":"cơ hội tuyệt vời"},{"en":"fantastic view","vi":"cảnh quan tuyệt đẹp"},{"en":"fantastic achievement","vi":"thành tựu xuất sắc"},{"en":"fantastic creatures","vi":"sinh vật kỳ ảo"}],"wordFamily":["fantastically (adv.)","fantasy (n.)"],"synonyms":["excellent","wonderful"],"antonyms":["terrible"],"tipVi":"Từ \"fantastic\" mang nghĩa \"cực kỳ tốt\" thường dùng trong văn nói hàng ngày; trong văn viết trang trọng, có thể dùng \"excellent\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glad', 'en-a2-17', 'glad', '/ɡlæd/', 'A2', 'vui mừng; hài lòng; phấn khởi; sẵn lòng; vui lòng làm gì', 'adj.', 'gladly (adv.), gladness (n.)', 'Đồng nghĩa: pleased, happy, delighted · Trái nghĩa: sad, unhappy', 'Thường làm vị ngữ; dùng be glad to do hoặc be glad that với mệnh đề.', 'I''m glad you came to dinner with us tonight.', NULL, 'Tôi rất vui vì bạn đã đến ăn tối cùng chúng tôi tối nay.', '{"wordId":"glad","ukIpa":"/ɡlæd/","usIpa":"/ɡlæd/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling happy or pleased about something.","vi":"vui mừng; hài lòng; phấn khởi"},{"pos":"adj.","en":"Willing and pleased to do something.","vi":"sẵn lòng; vui lòng làm gì"}],"examples":[{"en":"I''m glad you came to dinner with us tonight.","vi":"Tôi rất vui vì bạn đã đến ăn tối cùng chúng tôi tối nay.","audioKind":"ex"},{"en":"Many residents were glad that the council had decided to preserve the local park.","vi":"Nhiều cư dân rất vui mừng khi hội đồng quyết định bảo tồn công viên địa phương.","audioKind":"ex2"}],"collocations":[{"en":"glad to hear","vi":"rất vui khi nghe"},{"en":"glad to help","vi":"rất sẵn lòng giúp đỡ"},{"en":"glad about","vi":"vui vì điều gì"},{"en":"glad that","vi":"vui mừng rằng"}],"wordFamily":["gladly (adv.)","gladness (n.)"],"synonyms":["pleased","happy","delighted"],"antonyms":["sad","unhappy"],"tipVi":"Thường làm vị ngữ; dùng be glad to do hoặc be glad that với mệnh đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hope', 'en-a2-17', 'hope', '/hoʊp/', 'A2', 'hy vọng; mong ước; niềm hy vọng; niềm tin', 'v.', 'hopeful (adj.), hopeless (adj.), hopefully (adv.), hopelessness (n.)', 'Trái nghĩa: despair', 'Ta dùng hope to do, không dùng cấu trúc hope sb to do.', 'I hope the rain stops before our picnic.', NULL, 'Tôi hy vọng trời sẽ tạnh mưa trước buổi dã ngoại của chúng ta.', '{"wordId":"hope","ukIpa":"/həʊp/","usIpa":"/hoʊp/","cefr":"A2","topic":"emotion","senses":[{"pos":"v.","en":"to want something to happen and believe it may happen","vi":"hy vọng; mong ước"},{"pos":"n.","en":"a feeling that something wanted may happen","vi":"niềm hy vọng; niềm tin"}],"examples":[{"en":"I hope the rain stops before our picnic.","vi":"Tôi hy vọng trời sẽ tạnh mưa trước buổi dã ngoại của chúng ta.","audioKind":"ex"},{"en":"Many graduates hope to find meaningful employment that allows them to contribute positively to society.","vi":"Nhiều sinh viên mới tốt nghiệp hy vọng tìm được công việc ý nghĩa giúp họ đóng góp tích cực cho xã hội.","audioKind":"ex2"}],"collocations":[{"en":"hope to do something","vi":"hy vọng làm điều gì đó"},{"en":"hope for the best","vi":"hy vọng điều tốt đẹp nhất"},{"en":"give up hope","vi":"từ bỏ hy vọng"},{"en":"in the hope of","vi":"với hy vọng rằng"}],"wordFamily":["hopeful (adj.)","hopeless (adj.)","hopefully (adv.)","hopelessness (n.)"],"synonyms":[],"antonyms":["despair"],"tipVi":"Ta dùng hope to do, không dùng cấu trúc hope sb to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_surprising', 'en-a2-17', 'surprising', '/sɚˈpraɪzɪŋ/', 'A2', 'gây ngạc nhiên; bất ngờ', 'adj.', 'surprise (n.), surprise (v.), surprised (adj.), surprisingly (adv.)', 'Đồng nghĩa: unexpected, astonishing · Trái nghĩa: unsurprising, predictable', 'Dùng ''surprising'' để mô tả sự việc/vật gây ngạc nhiên, và dùng ''surprised'' để miêu tả cảm nhận của con người.', 'The tiny bakery offers a surprising variety of fresh bread.', NULL, 'Tiệm bánh nhỏ xíu này cung cấp vô số loại bánh mì tươi ngon đến ngạc nhiên.', '{"wordId":"surprising","ukIpa":"/səˈpraɪzɪŋ/","usIpa":"/sɚˈpraɪzɪŋ/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"unexpected and causing a feeling of surprise","vi":"gây ngạc nhiên; bất ngờ"}],"examples":[{"en":"The tiny bakery offers a surprising variety of fresh bread.","vi":"Tiệm bánh nhỏ xíu này cung cấp vô số loại bánh mì tươi ngon đến ngạc nhiên.","audioKind":"ex"},{"en":"The survey revealed a surprising decline in car ownership among young adults living in major cities.","vi":"Cuộc khảo sát cho thấy tỷ lệ sở hữu ô tô giảm xuống một cách bất ngờ trong nhóm người trưởng thành trẻ tuổi sống tại các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"surprising results","vi":"kết quả đáng kinh ngạc"},{"en":"a surprising number of","vi":"số lượng lớn đáng kinh ngạc"},{"en":"hardly surprising","vi":"không có gì đáng ngạc nhiên"}],"wordFamily":["surprise (n.)","surprise (v.)","surprised (adj.)","surprisingly (adv.)"],"synonyms":["unexpected","astonishing"],"antonyms":["unsurprising","predictable"],"tipVi":"Dùng ''surprising'' để mô tả sự việc/vật gây ngạc nhiên, và dùng ''surprised'' để miêu tả cảm nhận của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_happiness', 'en-a2-17', 'happiness', '/ˈhæpinəs/', 'A2', 'hạnh phúc; niềm vui', 'n.', 'happy (adj.), happily (adv.), unhappy (adj.), unhappiness (n.)', 'Đồng nghĩa: joy, contentment · Trái nghĩa: unhappiness, sadness', 'Thường là danh từ không đếm được: khi diễn tả sự hạnh phúc, dùng happiness và không thêm mạo từ a.', 'Her face shone with happiness when the puppy arrived.', NULL, 'Khuôn mặt cô ấy rạng rỡ niềm vui khi chú chó con xuất hiện.', '{"wordId":"happiness","ukIpa":"/ˈhæpinəs/","usIpa":"/ˈhæpinəs/","cefr":"A2","topic":"emotion","senses":[{"pos":"n.","en":"The feeling of being pleased or satisfied with life.","vi":"hạnh phúc; niềm vui"}],"examples":[{"en":"Her face shone with happiness when the puppy arrived.","vi":"Khuôn mặt cô ấy rạng rỡ niềm vui khi chú chó con xuất hiện.","audioKind":"ex"},{"en":"Strong social connections often contribute more to lasting happiness than the purchase of expensive possessions.","vi":"Các mối quan hệ xã hội bền chặt thường mang lại hạnh phúc lâu dài nhiều hơn so với việc mua sắm những món đồ đắt tiền.","audioKind":"ex2"}],"collocations":[{"en":"lasting happiness","vi":"hạnh phúc lâu dài"},{"en":"personal happiness","vi":"hạnh phúc cá nhân"},{"en":"bring happiness","vi":"mang lại hạnh phúc"},{"en":"a sense of happiness","vi":"cảm giác hạnh phúc"}],"wordFamily":["happy (adj.)","happily (adv.)","unhappy (adj.)","unhappiness (n.)"],"synonyms":["joy","contentment"],"antonyms":["unhappiness","sadness"],"tipVi":"Thường là danh từ không đếm được: khi diễn tả sự hạnh phúc, dùng happiness và không thêm mạo từ a.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amazing', 'en-a2-17', 'amazing', '/əˈmeɪzɪŋ/', 'A2', 'tuyệt vời; đáng kinh ngạc', 'adj.', 'amaze (v.), amazed (adj.), amazement (n.), amazingly (adv.)', 'Đồng nghĩa: astonishing, incredible · Trái nghĩa: ordinary', 'amazing dùng để miêu tả sự vật, hiện tượng gây ngạc nhiên; trong khi amazed dùng để diễn tả cảm xúc của con người.', 'The view from the mountain was absolutely amazing.', NULL, 'Cảnh quan nhìn từ ngọn núi thực sự vô cùng tuyệt vời.', '{"wordId":"amazing","ukIpa":"/əˈmeɪzɪŋ/","usIpa":"/əˈmeɪzɪŋ/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"Causing great surprise or admiration.","vi":"tuyệt vời; đáng kinh ngạc"}],"examples":[{"en":"The view from the mountain was absolutely amazing.","vi":"Cảnh quan nhìn từ ngọn núi thực sự vô cùng tuyệt vời.","audioKind":"ex"},{"en":"Recent medical research has produced amazing results, offering new hope to patients with previously untreatable conditions.","vi":"Các nghiên cứu y học gần đây đã mang lại những kết quả đáng kinh ngạc, thắp lên hy vọng mới cho những bệnh nhân mắc các chứng bệnh trước đây không thể chữa trị.","audioKind":"ex2"}],"collocations":[{"en":"absolutely amazing","vi":"vô cùng tuyệt vời"},{"en":"amazing results","vi":"kết quả đáng kinh ngạc"},{"en":"an amazing experience","vi":"một trải nghiệm kỳ diệu"}],"wordFamily":["amaze (v.)","amazed (adj.)","amazement (n.)","amazingly (adv.)"],"synonyms":["astonishing","incredible"],"antonyms":["ordinary"],"tipVi":"amazing dùng để miêu tả sự vật, hiện tượng gây ngạc nhiên; trong khi amazed dùng để diễn tả cảm xúc của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_surprise', 'en-a2-17', 'surprise', '/sɚˈpraɪz/', 'A2', 'sự ngạc nhiên; điều bất ngờ; làm ngạc nhiên; làm bất ngờ', 'n.', 'surprised (adj.), surprising (adj.), surprisingly (adv.)', 'Đồng nghĩa: astonishment, amaze', 'Cảm giác người thấy ngạc nhiên dùng surprised; sự việc gây ngạc nhiên dùng surprising.', 'Finding a birthday cake in the kitchen was a lovely surprise.', NULL, 'Tìm thấy một chiếc bánh sinh nhật trong phòng bếp quả là một điều bất ngờ tuyệt vời.', '{"wordId":"surprise","ukIpa":"/səˈpraɪz/","usIpa":"/sɚˈpraɪz/","cefr":"A2","topic":"emotion","senses":[{"pos":"n.","en":"An unexpected event, or the feeling it causes.","vi":"sự ngạc nhiên; điều bất ngờ"},{"pos":"v.","en":"To make someone feel amazed by something unexpected.","vi":"làm ngạc nhiên; làm bất ngờ"}],"examples":[{"en":"Finding a birthday cake in the kitchen was a lovely surprise.","vi":"Tìm thấy một chiếc bánh sinh nhật trong phòng bếp quả là một điều bất ngờ tuyệt vời.","audioKind":"ex"},{"en":"The survey results may surprise policymakers who assume that young people prefer online learning.","vi":"Kết quả khảo sát có thể khiến các nhà hoạch định chính sách—những người cho rằng giới trẻ ưu tiên việc học trực tuyến—cảm thấy bất ngờ.","audioKind":"ex2"}],"collocations":[{"en":"a pleasant surprise","vi":"một bất ngờ thú vị"},{"en":"to someone''s surprise","vi":"làm ai đó ngạc nhiên"},{"en":"take someone by surprise","vi":"làm ai đó bất ngờ; làm ai đó trở tay không kịp"},{"en":"a surprise visit","vi":"chuyến thăm bất ngờ"}],"wordFamily":["surprised (adj.)","surprising (adj.)","surprisingly (adv.)"],"synonyms":["astonishment","amaze"],"antonyms":[],"tipVi":"Cảm giác người thấy ngạc nhiên dùng surprised; sự việc gây ngạc nhiên dùng surprising.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wish', 'en-a2-17', 'wish', '/wɪʃ/', 'A2', 'ước gì; mong rằng; mong ước; điều ước; chúc; gửi lời chúc', 'v.', 'wishful (adj.), wishfully (adv.)', 'Đồng nghĩa: desire, hope', 'Sau wish dùng thì quá khứ đơn để diễn tả sự tiếc nuối ở hiện tại; quá khứ hoàn thành để diễn tả sự tiếc nuối trong quá khứ.', 'I wish our flat had a bigger kitchen.', NULL, 'Ước gì căn hộ của chúng tôi có nhà bếp lớn hơn.', '{"wordId":"wish","ukIpa":"/wɪʃ/","usIpa":"/wɪʃ/","cefr":"A2","topic":"emotion","senses":[{"pos":"v.","en":"To want something, especially something unlikely or not currently true.","vi":"ước gì; mong rằng"},{"pos":"n.","en":"A strong desire for something to happen or be true.","vi":"mong ước; điều ước"},{"pos":"v.","en":"To express hope for someone''s happiness or success.","vi":"chúc; gửi lời chúc"}],"examples":[{"en":"I wish our flat had a bigger kitchen.","vi":"Ước gì căn hộ của chúng tôi có nhà bếp lớn hơn.","audioKind":"ex"},{"en":"Many residents wish their neighbourhoods had more green spaces where children could play safely and families could relax.","vi":"Nhiều cư dân mong muốn khu5 vực của họ có nhiều không gian xanh hơn để trẻ em có thể vui chơi an toàn và các gia đình có thể thư giãn.","audioKind":"ex2"}],"collocations":[{"en":"make a wish","vi":"ước một điều ước"},{"en":"wish someone luck","vi":"chúc ai đó may mắn"},{"en":"best wishes","vi":"những lời chúc tốt đẹp nhất"},{"en":"wish to do something","vi":"muốn làm điều gì đó"}],"wordFamily":["wishful (adj.)","wishfully (adv.)"],"synonyms":["desire","hope"],"antonyms":[],"tipVi":"Sau wish dùng thì quá khứ đơn để diễn tả sự tiếc nuối ở hiện tại; quá khứ hoàn thành để diễn tả sự tiếc nuối trong quá khứ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_worried', 'en-a2-17', 'worried', '/ˈwɜrid/', 'A2', 'lo lắng; bận tâm', 'adj.', 'worry (v.), worry (n.), worrying (adj.)', 'Đồng nghĩa: anxious, concerned, uneasy · Trái nghĩa: unworried, relaxed', 'Tính từ "worried" dùng để miêu tả cảm xúc của con người, trong khi "worrying" dùng để chỉ sự vật, sự việc gây ra sự lo lắng.', 'She looked worried when her cat failed to return.', NULL, 'Trông cô ấy rất lo lắng khi con mèo mãi không về.', '{"wordId":"worried","ukIpa":"/ˈwʌrid/","usIpa":"/ˈwɜrid/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"feeling anxious about problems or something that might happen","vi":"lo lắng; bận tâm"}],"examples":[{"en":"She looked worried when her cat failed to return.","vi":"Trông cô ấy rất lo lắng khi con mèo mãi không về.","audioKind":"ex"},{"en":"Many parents are worried about the effects of excessive screen time on their children''s sleep.","vi":"Nhiều bậc phụ huynh cảm thấy lo lắng về tác động của thời gian sử dụng màn hình quá mức đối với giấc ngủ của con cái họ.","audioKind":"ex2"}],"collocations":[{"en":"worried about","vi":"lo lắng về"},{"en":"deeply worried","vi":"vô cùng lo lắng"},{"en":"a worried expression","vi":"vẻ mặt lo âu"}],"wordFamily":["worry (v.)","worry (n.)","worrying (adj.)"],"synonyms":["anxious","concerned","uneasy"],"antonyms":["unworried","relaxed"],"tipVi":"Tính từ \"worried\" dùng để miêu tả cảm xúc của con người, trong khi \"worrying\" dùng để chỉ sự vật, sự việc gây ra sự lo lắng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fortunately', 'en-a2-17', 'fortunately', '/ˈfɔːrtʃənətli/', 'A2', 'may mắn thay, thật may (đặc biệt khi điều tồi tệ suýt xảy ra)', 'adv.', 'fortunate (adj.), fortune (n.), unfortunate (adj.), unfortunately (adv.)', 'Đồng nghĩa: luckily · Trái nghĩa: unfortunately, unluckily', 'Thường đứng đầu câu, theo sau là dấu phẩy để đánh giá toàn bộ sự việc là đáng mừng.', 'Fortunately, I found my keys before the bus arrived.', NULL, 'May mắn là tôi đã tìm thấy chìa khóa trước khi xe buýt đến.', '{"wordId":"fortunately","ukIpa":"/ˈfɔːtʃənətli/","usIpa":"/ˈfɔːrtʃənətli/","cefr":"A2","topic":"emotion","senses":[{"pos":"adv.","en":"Luckily, especially when something bad could have happened.","vi":"may mắn thay, thật may (đặc biệt khi điều tồi tệ suýt xảy ra)"}],"examples":[{"en":"Fortunately, I found my keys before the bus arrived.","vi":"May mắn là tôi đã tìm thấy chìa khóa trước khi xe buýt đến.","audioKind":"ex"},{"en":"Fortunately, improvements in water treatment have helped many communities reduce the spread of preventable diseases.","vi":"Thật may mắn, những cải tiến trong công nghệ xử lý nước đã giúp nhiều cộng đồng giảm thiểu sự lây lan của các bệnh có thể phòng ngừa.","audioKind":"ex2"}],"collocations":[{"en":"fortunately for us","vi":"may mắn cho chúng tôi"},{"en":"fortunately enough","vi":"rất may mắn là"},{"en":"fortunately, nobody was hurt","vi":"may mắn thay, không có ai bị thương"}],"wordFamily":["fortunate (adj.)","fortune (n.)","unfortunate (adj.)","unfortunately (adv.)"],"synonyms":["luckily"],"antonyms":["unfortunately","unluckily"],"tipVi":"Thường đứng đầu câu, theo sau là dấu phẩy để đánh giá toàn bộ sự việc là đáng mừng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_frightened', 'en-a2-17', 'frightened', '/ˈfraɪtənd/', 'A2', 'sợ hãi; khiếp sợ; hoảng sợ', 'adj.', 'fright (n.), frighten (v.), frightening (adj.)', 'Đồng nghĩa: afraid, scared · Trái nghĩa: unafraid', '‘frightened’ dùng để miêu tả cảm giác sợ hãi của ai đó; ‘frightening’ dùng để miêu tả sự vật gây sợ hãi.', 'The frightened kitten hid behind the sofa during the storm.', NULL, 'Chú mèo con sợ hãi trốn đằng sau chiếc ghế sofa trong trận bão.', '{"wordId":"frightened","ukIpa":"/ˈfraɪtənd/","usIpa":"/ˈfraɪtənd/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling afraid because of danger or something unexpected.","vi":"sợ hãi; khiếp sợ; hoảng sợ"}],"examples":[{"en":"The frightened kitten hid behind the sofa during the storm.","vi":"Chú mèo con sợ hãi trốn đằng sau chiếc ghế sofa trong trận bão.","audioKind":"ex"},{"en":"Children who feel frightened in unfamiliar environments may benefit from patient support and predictable routines.","vi":"Những đứa trẻ cảm thấy sợ hãi trong môi trường xa lạ có thể cần đến sự hỗ trợ kiên nhẫn và sinh hoạt có thể dự đoán trước.","audioKind":"ex2"}],"collocations":[{"en":"frightened of","vi":"sợ cái gì"},{"en":"frightened to death","vi":"sợ chết khiếp"},{"en":"a frightened child","vi":"một đứa trẻ hoảng sợ"}],"wordFamily":["fright (n.)","frighten (v.)","frightening (adj.)"],"synonyms":["afraid","scared"],"antonyms":["unafraid"],"tipVi":"‘frightened’ dùng để miêu tả cảm giác sợ hãi của ai đó; ‘frightening’ dùng để miêu tả sự vật gây sợ hãi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fear', 'en-a2-17', 'fear', '/fɪr/', 'A2', 'sự sợ hãi; nỗi sợ; sợ; lo lắng', 'n.', 'fearful (adj.), fearless (adj.), fearfully (adv.), fearlessly (adv.)', 'Đồng nghĩa: fright, dread', 'fear sth nghĩa là sợ điều gì; fear for sb nghĩa là lo lắng cho ai đó.', 'She held my hand because of her fear of heights.', NULL, 'Cô ấy nắm tay tôi vì chứng sợ độ cao của mình.', '{"wordId":"fear","ukIpa":"/fɪə/","usIpa":"/fɪr/","cefr":"A2","topic":"emotion","senses":[{"pos":"n.","en":"An unpleasant feeling about danger or something bad happening.","vi":"sự sợ hãi; nỗi sợ"},{"pos":"v.","en":"To feel afraid or worried about someone or something.","vi":"sợ; lo lắng"}],"examples":[{"en":"She held my hand because of her fear of heights.","vi":"Cô ấy nắm tay tôi vì chứng sợ độ cao của mình.","audioKind":"ex"},{"en":"Fear of failure may prevent students from asking questions, especially in highly competitive learning environments.","vi":"Nỗi sợ thất bại có thể khiến học sinh ngần ngại không dám đặt câu hỏi, nhất là trong môi trường học tập có tính cạnh tranh cao.","audioKind":"ex2"}],"collocations":[{"en":"fear of heights","vi":"chứng sợ độ cao"},{"en":"overcome a fear","vi":"vượt qua nỗi sợ"},{"en":"fear for someone''s safety","vi":"lo lắng cho sự an toàn của ai đó"},{"en":"for fear of","vi":"vì sợ rằng; e rằng"}],"wordFamily":["fearful (adj.)","fearless (adj.)","fearfully (adv.)","fearlessly (adv.)"],"synonyms":["fright","dread"],"antonyms":[],"tipVi":"fear sth nghĩa là sợ điều gì; fear for sb nghĩa là lo lắng cho ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_happily', 'en-a2-17', 'happily', '/ˈhæpɪli/', 'A2', 'vui vẻ; hạnh phúc; vui lòng; sẵn lòng; may mắn thay', 'adv.', 'happy (adj.), happiness (n.), unhappy (adj.), unhappily (adv.)', 'Đồng nghĩa: cheerfully, gladly · Trái nghĩa: unhappily', 'Khi đứng ở đầu câu, từ "Happily" có thể mang nghĩa là "may mắn thay", chứ không chỉ biểu thị cảm giác vui vẻ.', 'The children chatted happily while making sandwiches together.', NULL, 'Lũ trẻ vừa rôm rả trò chuyện vui vẻ vừa cùng nhau làm bánh mì kẹp.', '{"wordId":"happily","ukIpa":"/ˈhæpɪli/","usIpa":"/ˈhæpɪli/","cefr":"A2","topic":"emotion","senses":[{"pos":"adv.","en":"In a way that shows pleasure or enjoyment.","vi":"vui vẻ; hạnh phúc"},{"pos":"adv.","en":"Willingly and without objection.","vi":"vui lòng; sẵn lòng"},{"pos":"adv.","en":"With a fortunate or pleasing result.","vi":"may mắn thay"}],"examples":[{"en":"The children chatted happily while making sandwiches together.","vi":"Lũ trẻ vừa rôm rả trò chuyện vui vẻ vừa cùng nhau làm bánh mì kẹp.","audioKind":"ex"},{"en":"Many residents would happily use public transport if services were more reliable and affordable.","vi":"Nhiều cư dân sẽ sẵn sàng sử dụng giao thông công cộng nếu các dịch vụ đáng tin cậy hơn và có giá cả phải chăng hơn.","audioKind":"ex2"}],"collocations":[{"en":"smile happily","vi":"mỉm cười hạnh phúc"},{"en":"happily married","vi":"có cuộc hôn nhân hạnh phúc"},{"en":"happily agree","vi":"vui vẻ đồng ý"}],"wordFamily":["happy (adj.)","happiness (n.)","unhappy (adj.)","unhappily (adv.)"],"synonyms":["cheerfully","gladly"],"antonyms":["unhappily"],"tipVi":"Khi đứng ở đầu câu, từ \"Happily\" có thể mang nghĩa là \"may mắn thay\", chứ không chỉ biểu thị cảm giác vui vẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unhappy', 'en-a2-17', 'unhappy', '/ʌnˈhæpi/', 'A2', 'buồn bã; bất hạnh; không hài lòng; khó chịu', 'adj.', 'happy (adj.), happiness (n.), unhappiness (n.), unhappily (adv.)', 'Đồng nghĩa: sad, miserable, dissatisfied · Trái nghĩa: happy, content', 'unhappy with thường biểu thị "không hài lòng với...".', 'He looked unhappy when the picnic was cancelled.', NULL, 'Anh ấy trông có vẻ không vui khi buổi dã ngoại bị hủy bỏ.', '{"wordId":"unhappy","ukIpa":"/ʌnˈhæpi/","usIpa":"/ʌnˈhæpi/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"Feeling sad or lacking happiness","vi":"buồn bã; bất hạnh"},{"pos":"adj.","en":"Not satisfied with someone or something","vi":"không hài lòng; khó chịu"}],"examples":[{"en":"He looked unhappy when the picnic was cancelled.","vi":"Anh ấy trông có vẻ không vui khi buổi dã ngoại bị hủy bỏ.","audioKind":"ex"},{"en":"Residents are unhappy with the proposed road expansion because it would remove valuable green space.","vi":"Cư dân không hài lòng với đề xuất mở rộng con đường vì nó sẽ lấy đi không gian xanh quý giá.","audioKind":"ex2"}],"collocations":[{"en":"feel unhappy","vi":"cảm thấy không vui"},{"en":"unhappy with the service","vi":"không hài lòng với dịch vụ"},{"en":"an unhappy childhood","vi":"một tuổi thơ bất hạnh"}],"wordFamily":["happy (adj.)","happiness (n.)","unhappiness (n.)","unhappily (adv.)"],"synonyms":["sad","miserable","dissatisfied"],"antonyms":["happy","content"],"tipVi":"unhappy with thường biểu thị \"không hài lòng với...\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sadly', 'en-a2-17', 'sadly', '/ˈsædli/', 'A2', 'một cách buồn bã; đầy đau buồn; đáng tiếc là; không may là', 'adv.', 'sad (adj.), sadness (n.), sadden (v.)', 'Đồng nghĩa: sorrowfully, unfortunately · Trái nghĩa: happily', 'Đầu câu Sadly thường mang nghĩa "đáng tiếc là", bổ nghĩa cho cả câu.', 'He waved sadly as his best friend''s train departed.', NULL, 'Anh ấy buồn bã vẫy tay chào khi chuyến tàu của người bạn thân nhất lăn bánh rời đi.', '{"wordId":"sadly","ukIpa":"/ˈsædli/","usIpa":"/ˈsædli/","cefr":"A2","topic":"emotion","senses":[{"pos":"adv.","en":"in a way that expresses unhappiness","vi":"một cách buồn bã; đầy đau buồn"},{"pos":"adv.","en":"used to express regret about an unfortunate situation","vi":"đáng tiếc là; không may là"}],"examples":[{"en":"He waved sadly as his best friend''s train departed.","vi":"Anh ấy buồn bã vẫy tay chào khi chuyến tàu của người bạn thân nhất lăn bánh rời đi.","audioKind":"ex"},{"en":"Sadly, many historic buildings have been demolished to make room for roads and commercial developments.","vi":"Đáng tiếc là, nhiều tòa nhà lịch sử đã bị phá bỏ để nhường chỗ cho đường sá và các dự án phát triển thương mại.","audioKind":"ex2"}],"collocations":[{"en":"smile sadly","vi":"mỉm cười buồn bã"},{"en":"sadly lacking","vi":"thiếu thốn trầm trọng"},{"en":"sadly missed","vi":"vô cùng thương nhớ"}],"wordFamily":["sad (adj.)","sadness (n.)","sadden (v.)"],"synonyms":["sorrowfully","unfortunately"],"antonyms":["happily"],"tipVi":"Đầu câu Sadly thường mang nghĩa \"đáng tiếc là\", bổ nghĩa cho cả câu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pleased', 'en-a2-17', 'pleased', '/pliːzd/', 'A2', 'hài lòng; vui mừng', 'adj.', 'please (v.), pleasing (adj.), pleasure (n.), displeased (adj.)', 'Đồng nghĩa: glad, happy, satisfied · Trái nghĩa: displeased, dissatisfied', 'Hài lòng với kết quả dùng pleased with; nghe tin vui dùng pleased to hear.', 'I''m really pleased with how the cake turned out.', NULL, 'Tôi thực sự hài lòng với thành quả của chiếc bánh này.', '{"wordId":"pleased","ukIpa":"/pliːzd/","usIpa":"/pliːzd/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"feeling happy or satisfied about something","vi":"hài lòng; vui mừng"}],"examples":[{"en":"I''m really pleased with how the cake turned out.","vi":"Tôi thực sự hài lòng với thành quả của chiếc bánh này.","audioKind":"ex"},{"en":"Residents were pleased that the council had created more green spaces for children to play safely.","vi":"Người dân rất vui mừng khi hội đồng thành phố đã tạo ra nhiều không gian xanh hơn để trẻ em vui chơi an toàn.","audioKind":"ex2"}],"collocations":[{"en":"pleased with","vi":"hài lòng với"},{"en":"pleased to hear","vi":"vui mừng khi nghe tin"},{"en":"pleased to meet you","vi":"rất vui được gặp bạn"}],"wordFamily":["please (v.)","pleasing (adj.)","pleasure (n.)","displeased (adj.)"],"synonyms":["glad","happy","satisfied"],"antonyms":["displeased","dissatisfied"],"tipVi":"Hài lòng với kết quả dùng pleased with; nghe tin vui dùng pleased to hear.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_horrible', 'en-a2-17', 'horrible', '/ˈhɔːrəbl/', 'A2', 'tồi tệ; khó chịu; kinh khủng; đáng sợ', 'adj.', 'horribly (adv.), horror (n.), horrify (v.), horrific (adj.)', 'Đồng nghĩa: awful, terrible, dreadful · Trái nghĩa: lovely, pleasant', 'horrible thường chỉ sự tồi tệ; horrific thường chỉ sự khủng khiếp, thảm khốc.', 'A horrible smell came from the forgotten lunch box.', NULL, 'Một mùi khó chịu bốc lên từ chiếc hộp đựng bữa trưa bị bỏ quên.', '{"wordId":"horrible","ukIpa":"/ˈhɒrəbl/","usIpa":"/ˈhɔːrəbl/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"very unpleasant or bad","vi":"tồi tệ; khó chịu"},{"pos":"adj.","en":"causing strong fear or shock","vi":"kinh khủng; đáng sợ"}],"examples":[{"en":"A horrible smell came from the forgotten lunch box.","vi":"Một mùi khó chịu bốc lên từ chiếc hộp đựng bữa trưa bị bỏ quên.","audioKind":"ex"},{"en":"Residents described the horrible conditions in overcrowded housing and called for stricter enforcement of safety standards.","vi":"Cư dân đã mô tả những điều kiện tồi tệ trong các khu nhà ở quá đông đúc và kêu gọi thực thi nghiêm ngặt hơn các tiêu chuẩn an toàn.","audioKind":"ex2"}],"collocations":[{"en":"a horrible smell","vi":"mùi khó chịu"},{"en":"a horrible experience","vi":"trải nghiệm tồi tệ"},{"en":"horrible weather","vi":"thời tiết tồi tệ"}],"wordFamily":["horribly (adv.)","horror (n.)","horrify (v.)","horrific (adj.)"],"synonyms":["awful","terrible","dreadful"],"antonyms":["lovely","pleasant"],"tipVi":"horrible thường chỉ sự tồi tệ; horrific thường chỉ sự khủng khiếp, thảm khốc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_congratulations', 'en-a2-17', 'congratulations', '/kənˌɡrætʃəˈleɪʃənz/', 'A2', 'lời chúc mừng; sự chúc mừng; chúc mừng! (dùng để bày tỏ niềm vui về thành công hoặc tin vui của ai đó)', 'n.', 'congratulate (v.), congratulation (n.), congratulatory (adj.)', NULL, 'Từ congratulations thường dùng ở số nhiều; congratulations on đi theo sau bởi danh từ hoặc danh động từ.', 'Congratulations on passing your driving test this morning!', NULL, 'Chúc mừng bạn đã vượt qua bài thi lái xe sáng nay!', '{"wordId":"congratulations","ukIpa":"/kənˌɡrætʃəˈleɪʃənz/","usIpa":"/kənˌɡrætʃəˈleɪʃənz/","cefr":"A2","topic":"emotion","senses":[{"pos":"n.","en":"words expressing pleasure at someone''s success or good fortune","vi":"lời chúc mừng; sự chúc mừng"},{"pos":"int.","en":"said to show happiness about someone''s achievement or good news","vi":"chúc mừng! (dùng để bày tỏ niềm vui về thành công hoặc tin vui của ai đó)"}],"examples":[{"en":"Congratulations on passing your driving test this morning!","vi":"Chúc mừng bạn đã vượt qua bài thi lái xe sáng nay!","audioKind":"ex"},{"en":"The research team received congratulations from colleagues after winning an international award for environmental innovation.","vi":"Nhóm nghiên cứu đã nhận được những lời chúc mừng từ các đồng nghiệp sau khi giành giải thưởng quốc tế về đổi mới sáng tạo môi trường.","audioKind":"ex2"}],"collocations":[{"en":"congratulations on your success","vi":"chúc mừng thành công của bạn"},{"en":"offer congratulations","vi":"gửi lời chúc mừng"},{"en":"warm congratulations","vi":"nhiệt liệt chúc mừng"}],"wordFamily":["congratulate (v.)","congratulation (n.)","congratulatory (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ congratulations thường dùng ở số nhiều; congratulations on đi theo sau bởi danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shy', 'en-a2-17', 'shy', '/ʃaɪ/', 'A2', 'rụt rè; bẽn lẽn; e thẹn; lùi bước; chùng bước; né tránh', 'adj.', 'shyly (adv.), shyness (n.)', 'Đồng nghĩa: bashful, timid · Trái nghĩa: outgoing, confident', 'shy away from hậu tố danh từ hoặc danh động từ, biểu thị việc né tránh.', 'Lina felt shy when she joined the new club.', NULL, 'Lina cảm thấy rụt rè khi gia nhập câu lạc bộ mới.', '{"wordId":"shy","ukIpa":"/ʃaɪ/","usIpa":"/ʃaɪ/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"nervous or uncomfortable when meeting or speaking to people","vi":"rụt rè; bẽn lẽn; e thẹn"},{"pos":"v.","en":"to move away suddenly in fear, especially of a horse","vi":"lùi bước; chùng bước; né tránh"}],"examples":[{"en":"Lina felt shy when she joined the new club.","vi":"Lina cảm thấy rụt rè khi gia nhập câu lạc bộ mới.","audioKind":"ex"},{"en":"Small group discussions can help shy students gain confidence before speaking in front of the whole class.","vi":"Các cuộc thảo luận nhóm nhỏ có thể giúp học sinh rụt rè lấy lại sự tự tin trước khi phát biểu trước cả lớp.","audioKind":"ex2"}],"collocations":[{"en":"feel shy","vi":"cảm thấy rụt rè"},{"en":"painfully shy","vi":"cực kỳ rụt rè"},{"en":"shy away from","vi":"né tránh"}],"wordFamily":["shyly (adv.)","shyness (n.)"],"synonyms":["bashful","timid"],"antonyms":["outgoing","confident"],"tipVi":"shy away from hậu tố danh từ hoặc danh động từ, biểu thị việc né tránh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nervous', 'en-a2-17', 'nervous', '/ˈnɝːvəs/', 'A2', 'lo lắng; hồi hộp; bồn chồn; thuộc về thần kinh; hệ thần kinh', 'adj.', 'nerve (n.), nervously (adv.), nervousness (n.)', 'Đồng nghĩa: anxious, uneasy · Trái nghĩa: calm, relaxed', 'nervous about đi với danh từ hoặc danh động từ, biểu thị sự lo lắng về một việc gì đó.', 'I felt nervous before my first swimming lesson yesterday.', NULL, 'Tôi cảm thấy lo lắng trước buổi học bơi đầu tiên vào ngày hôm qua.', '{"wordId":"nervous","ukIpa":"/ˈnɜːvəs/","usIpa":"/ˈnɝːvəs/","cefr":"A2","topic":"emotion","senses":[{"pos":"adj.","en":"worried or uneasy about what might happen","vi":"lo lắng; hồi hộp; bồn chồn"},{"pos":"adj.","en":"relating to the nerves in the body","vi":"thuộc về thần kinh; hệ thần kinh"}],"examples":[{"en":"I felt nervous before my first swimming lesson yesterday.","vi":"Tôi cảm thấy lo lắng trước buổi học bơi đầu tiên vào ngày hôm qua.","audioKind":"ex"},{"en":"Students who feel nervous about examinations may benefit from regular practice and supportive feedback from teachers.","vi":"Những học sinh cảm thấy lo lắng về các kỳ thi có thể nhận được lợi ích từ việc luyện tập thường xuyên và những phản hồi khích lệ từ giáo viên.","audioKind":"ex2"}],"collocations":[{"en":"nervous about","vi":"lo lắng về"},{"en":"feel nervous","vi":"cảm thấy lo lắng"},{"en":"nervous system","vi":"hệ thần kinh"},{"en":"nervous laugh","vi":"nụ cười lo lắng"}],"wordFamily":["nerve (n.)","nervously (adv.)","nervousness (n.)"],"synonyms":["anxious","uneasy"],"antonyms":["calm","relaxed"],"tipVi":"nervous about đi với danh từ hoặc danh động từ, biểu thị sự lo lắng về một việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_worry', 'en-a2-17', 'worry', '/ˈwɜːri/', 'A2', 'lo lắng; làm cho lo lắng; nỗi lo âu; điều lo lắng', 'v.', 'worried (adj.), worrying (adj.)', 'Đồng nghĩa: concern', 'worry about thể hiện sự lo lắng về việc gì đó; worried dùng để miêu tả trạng thái của con người.', 'I worry about my cat when she stays outside.', NULL, 'Tôi thường lo lắng cho con mèo của mình khi nó ở ngoài trời.', '{"wordId":"worry","ukIpa":"/ˈwʌri/","usIpa":"/ˈwɜːri/","cefr":"A2","topic":"emotion","senses":[{"pos":"v.","en":"To feel anxious, or make someone feel anxious.","vi":"lo lắng; làm cho lo lắng"},{"pos":"n.","en":"An anxious feeling or something that causes it.","vi":"nỗi lo âu; điều lo lắng"}],"examples":[{"en":"I worry about my cat when she stays outside.","vi":"Tôi thường lo lắng cho con mèo của mình khi nó ở ngoài trời.","audioKind":"ex"},{"en":"Many parents worry that excessive screen time may affect their children''s sleep and concentration.","vi":"Nhiều bậc phụ huynh lo lắng rằng thời gian sử dụng màn hình quá nhiều có thể ảnh hưởng đến giấc ngủ và sự tập trung của con cái họ.","audioKind":"ex2"}],"collocations":[{"en":"worry about","vi":"lo lắng về"},{"en":"a major worry","vi":"một mối lo lớn"},{"en":"cause worry","vi":"gây lo lắng"},{"en":"financial worries","vi":"những lo âu về tài chính"}],"wordFamily":["worried (adj.)","worrying (adj.)"],"synonyms":["concern"],"antonyms":[],"tipVi":"worry about thể hiện sự lo lắng về việc gì đó; worried dùng để miêu tả trạng thái của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_17_1', 'en-a2-17', 'Cách dùng “fantastic” (adj.) — cực kỳ tốt; tuyệt vời', 'fantastic opportunity  ·  fantastic view  ·  fantastic achievement', 'Từ "fantastic" mang nghĩa "cực kỳ tốt" thường dùng trong văn nói hàng ngày; trong văn viết trang trọng, có thể dùng "excellent".', 'Họ từ (Word Family): fantastically (adv.), fantasy (n.) | Đồng nghĩa: excellent, wonderful · Trái nghĩa: terrible', '[{"hanzi":"We had a fantastic view of the mountains from our balcony.","pinyin":"","meaning":"Từ ban công, chúng tôi có thể ngắm nhìn trọn vẹn khung cảnh núi non tuyệt đẹp."},{"hanzi":"Community sports programmes offer young people a fantastic opportunity to develop teamwork skills and build confidence.","pinyin":"","meaning":"Các chương trình thể thao cộng đồng mang lại cho giới trẻ cơ hội tuyệt vời để phát triển kỹ năng làm việc nhóm và xây dựng lòng tự tin."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_17_2', 'en-a2-17', 'Cách dùng “crazy” (adj.) — điên rồ; ngớ ngẩn; bất hợp lý; kỳ quặc', 'crazy about  ·  drive someone crazy  ·  a crazy idea', 'Từ này mang văn phong thân mật, khẩu ngữ; cấu trúc crazy about diễn tả sự say mê, không dùng để chỉ các vấn đề y tế tâm thần.', 'Họ từ (Word Family): crazily (adv.), craziness (n.) | Đồng nghĩa: absurd, ridiculous · Trái nghĩa: sensible', '[{"hanzi":"It seems crazy to wear sandals in this snow.","pinyin":"","meaning":"Thật là điên rồ khi đi giày xăng-đan trong thời tiết có tuyết thế này."},{"hanzi":"Although some people consider car-free cities a crazy idea, such policies could significantly improve urban air quality.","pinyin":"","meaning":"Mặc dù một số người coi các thành phố không có ô tô là một ý tưởng điên rồ, nhưng những chính sách như vậy có thể cải thiện đáng kể chất lượng không khí đô thị."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_17_3', 'en-a2-17', 'Cách dùng “worried” (adj.) — lo lắng; bận tâm', 'worried about  ·  deeply worried  ·  a worried expression', 'Tính từ "worried" dùng để miêu tả cảm xúc của con người, trong khi "worrying" dùng để chỉ sự vật, sự việc gây ra sự lo lắng.', 'Họ từ (Word Family): worry (v.), worry (n.), worrying (adj.) | Đồng nghĩa: anxious, concerned, uneasy · Trái nghĩa: unworried, relaxed', '[{"hanzi":"She looked worried when her cat failed to return.","pinyin":"","meaning":"Trông cô ấy rất lo lắng khi con mèo mãi không về."},{"hanzi":"Many parents are worried about the effects of excessive screen time on their children''s sleep.","pinyin":"","meaning":"Nhiều bậc phụ huynh cảm thấy lo lắng về tác động của thời gian sử dụng màn hình quá mức đối với giấc ngủ của con cái họ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_17_4', 'en-a2-17', 'Cách dùng “wish” (v.) — ước gì; mong rằng', 'make a wish  ·  wish someone luck  ·  best wishes', 'Sau wish dùng thì quá khứ đơn để diễn tả sự tiếc nuối ở hiện tại; quá khứ hoàn thành để diễn tả sự tiếc nuối trong quá khứ.', 'Họ từ (Word Family): wishful (adj.), wishfully (adv.) | Đồng nghĩa: desire, hope', '[{"hanzi":"I wish our flat had a bigger kitchen.","pinyin":"","meaning":"Ước gì căn hộ của chúng tôi có nhà bếp lớn hơn."},{"hanzi":"Many residents wish their neighbourhoods had more green spaces where children could play safely and families could relax.","pinyin":"","meaning":"Nhiều cư dân mong muốn khu5 vực của họ có nhiều không gian xanh hơn để trẻ em có thể vui chơi an toàn và các gia đình có thể thư giãn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_17_1', 'en-a2-17', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_17_1_1', 'ten_a2_17_1', 'proud', 'He felt proud of the cake he baked himself.', 'He felt proud of the cake he baked himself.', '/praʊd/', 'Cậu ấy cảm thấy rất tự hào về chiếc bánh do chính tay mình nướng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_17_1_2', 'ten_a2_17_1', 'scary', 'That scary noise was just a branch against the window.', 'That scary noise was just a branch against the window.', '/ˈskeri/', 'Âm thanh đáng sợ đó chỉ là tiếng cành cây cọ vào cửa sổ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_17_1_3', 'ten_a2_17_1', 'lonely', 'I felt lonely until my neighbour invited me for tea.', 'I felt lonely until my neighbour invited me for tea.', '/ˈloʊnli/', 'Tôi từng cảm thấy cô đơn cho đến khi người hàng xóm mời tôi sang uống trà.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_17_1_4', 'ten_a2_17_1', 'crazy', 'It seems crazy to wear sandals in this snow.', 'It seems crazy to wear sandals in this snow.', '/ˈkreɪzi/', 'Thật là điên rồ khi đi giày xăng-đan trong thời tiết có tuyết thế này.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_17_1_5', 'ten_a2_17_1', 'scared', 'The puppy looked scared when it heard the thunder.', 'The puppy looked scared when it heard the thunder.', '/skerd/', 'Chú cún con có vẻ rất sợ hãi khi nghe thấy tiếng sấm.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_17_1_6', 'ten_a2_17_1', 'surprised', 'I was surprised to find flowers outside my door.', 'I was surprised to find flowers outside my door.', '/sərˈpraɪzd/', 'Tôi rất ngạc nhiên khi thấy những bông hoa ở trước cửa nhà mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_17_1_7', 'ten_a2_17_1', 'fantastic', 'We had a fantastic view of the mountains from our balcony.', 'We had a fantastic view of the mountains from our balcony.', '/fænˈtæstɪk/', 'Từ ban công, chúng tôi có thể ngắm nhìn trọn vẹn khung cảnh núi non tuyệt đẹp.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_17_1_8', 'ten_a2_17_1', 'glad', 'I''m glad you came to dinner with us tonight.', 'I''m glad you came to dinner with us tonight.', '/ɡlæd/', 'Tôi rất vui vì bạn đã đến ăn tối cùng chúng tôi tối nay.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_17_1_1', 'en-a2-17', 'ten_a2_17_1', 'listening', 'listening', 'He felt proud of the cake he baked himself.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cậu ấy cảm thấy rất tự hào về chiếc bánh do chính tay mình nướng.","Tôi cảm thấy lo lắng trước buổi học bơi đầu tiên vào ngày hôm qua.","Anh ấy buồn bã vẫy tay chào khi chuyến tàu của người bạn thân nhất lăn bánh rời đi.","Trông cô ấy rất lo lắng khi con mèo mãi không về."]'::jsonb, 0, 'He felt proud of the cake he baked himself. → Cậu ấy cảm thấy rất tự hào về chiếc bánh do chính tay mình nướng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_17_1_2', 'en-a2-17', 'ten_a2_17_1', 'listening', 'listening', 'That scary noise was just a branch against the window.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy nắm tay tôi vì chứng sợ độ cao của mình.","Âm thanh đáng sợ đó chỉ là tiếng cành cây cọ vào cửa sổ.","Tôi rất ngạc nhiên khi thấy những bông hoa ở trước cửa nhà mình.","Anh ấy trông có vẻ không vui khi buổi dã ngoại bị hủy bỏ."]'::jsonb, 1, 'That scary noise was just a branch against the window. → Âm thanh đáng sợ đó chỉ là tiếng cành cây cọ vào cửa sổ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_17_1_3', 'en-a2-17', 'ten_a2_17_1', 'listening', 'listening', 'I felt lonely until my neighbour invited me for tea.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chú cún con có vẻ rất sợ hãi khi nghe thấy tiếng sấm.","Tôi hy vọng trời sẽ tạnh mưa trước buổi dã ngoại của chúng ta.","Âm thanh đáng sợ đó chỉ là tiếng cành cây cọ vào cửa sổ.","Tôi từng cảm thấy cô đơn cho đến khi người hàng xóm mời tôi sang uống trà."]'::jsonb, 3, 'I felt lonely until my neighbour invited me for tea. → Tôi từng cảm thấy cô đơn cho đến khi người hàng xóm mời tôi sang uống trà.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_17_2', 'en-a2-17', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_17_2_1', 'ten_a2_17_2', 'proud', 'Residents are often proud of their cultural heritage and support efforts to preserve historic buildings.', 'Residents are often proud of their cultural heritage and support efforts to preserve historic buildings.', '/praʊd/', 'Cư dân thường tự hào về di sản văn hóa của họ và ủng hộ các nỗ lực bảo tồn các tòa nhà lịch sử.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_17_2_2', 'ten_a2_17_2', 'scary', 'Starting school can be scary for young children, so teachers should create a welcoming environment.', 'Starting school can be scary for young children, so teachers should create a welcoming environment.', '/ˈskeri/', 'Việc bắt đầu đi học có thể đáng sợ đối với trẻ nhỏ, vì vậy giáo viên nên tạo ra một môi trường thân thiện.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_17_2_3', 'ten_a2_17_2', 'lonely', 'Older adults may feel lonely after retirement, so community centres should provide regular opportunities for social interaction.', 'Older adults may feel lonely after retirement, so community centres should provide regular opportunities for social interaction.', '/ˈloʊnli/', 'Người cao tuổi có thể cảm thấy cô đơn sau khi nghỉ hưu, vì vậy các trung tâm cộng đồng nên thường xuyên tạo cơ hội cho họ giao lưu xã hội.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_17_2_4', 'ten_a2_17_2', 'crazy', 'Although some people consider car-free cities a crazy idea, such policies could significantly improve urban air quality.', 'Although some people consider car-free cities a crazy idea, such policies could significantly improve urban air quality.', '/ˈkreɪzi/', 'Mặc dù một số người coi các thành phố không có ô tô là một ý tưởng điên rồ, nhưng những chính sách như vậy có thể cải thiện đáng kể chất lượng không khí đô thị.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_17_2_5', 'ten_a2_17_2', 'scared', 'Students who are scared of making mistakes may avoid speaking during foreign language lessons.', 'Students who are scared of making mistakes may avoid speaking during foreign language lessons.', '/skerd/', 'Những học sinh sợ mắc lỗi có thể sẽ tránh phát biểu trong các giờ học ngoại ngữ.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_17_2_6', 'ten_a2_17_2', 'surprised', 'Researchers were surprised by how strongly access to green spaces influenced residents'' reported levels of wellbeing.', 'Researchers were surprised by how strongly access to green spaces influenced residents'' reported levels of wellbeing.', '/sərˈpraɪzd/', 'Các nhà nghiên cứu đã rất ngạc nhiên trước mức độ ảnh hưởng mạnh mẽ của việc tiếp cận không gian xanh đối với mức độ hạnh phúc tự báo cáo của người dân.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_17_2_1', 'en-a2-17', 'ten_a2_17_2', 'listening', 'listening', 'Residents are often proud of their cultural heritage and support efforts to preserve historic buildings.', NULL, 'Trong câu vừa nghe, từ “proud” mang nghĩa nào sau đây?', '["tự hào; hãnh diện","bóng bay","chúng tôi (chính mình); chúng ta (chính mình)","những chiếc lá (dạng số nhiều của leaf)"]'::jsonb, 0, '“proud” (/praʊd/): tự hào; hãnh diện. Câu đầy đủ: Residents are often proud of their cultural heritage and support efforts to preserve historic buildings.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_17_2_2', 'en-a2-17', 'ten_a2_17_2', 'listening', 'listening', 'Starting school can be scary for young children, so teachers should create a welcoming environment.', NULL, 'Trong câu vừa nghe, từ “scary” mang nghĩa nào sau đây?', '["môn bóng chày","cửa hàng; tiệm","đau đớn; làm tổn thương thể xác","đáng sợ; làm hoảng sợ"]'::jsonb, 3, '“scary” (/ˈskeri/): đáng sợ; làm hoảng sợ. Câu đầy đủ: Starting school can be scary for young children, so teachers should create a welcoming environment.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
