INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_2', 'en-a2-17', NULL, 'comprehensive_test', 'listening', 'That scary noise was just a branch against the window.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Trông cô ấy rất lo lắng khi con mèo mãi không về.","Tôi hy vọng trời sẽ tạnh mưa trước buổi dã ngoại của chúng ta.","Âm thanh đáng sợ đó chỉ là tiếng cành cây cọ vào cửa sổ.","Tôi từng cảm thấy cô đơn cho đến khi người hàng xóm mời tôi sang uống trà."]'::jsonb, 2, 'That scary noise was just a branch against the window. → Âm thanh đáng sợ đó chỉ là tiếng cành cây cọ vào cửa sổ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_3', 'en-a2-17', NULL, 'comprehensive_test', 'listening', 'lonely', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["áo mưa","cô đơn, buồn bã vì thiếu sự đồng hành hoặc các mối quan hệ gần gũi","theo như; theo lời","mặt trăng"]'::jsonb, 1, 'lonely (/ˈloʊnli/) → cô đơn, buồn bã vì thiếu sự đồng hành hoặc các mối quan hệ gần gũi; hẻo lánh, xa xôi hoặc ít người lui tới', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_4', 'en-a2-17', NULL, 'comprehensive_test', 'listening', 'It seems crazy to wear sandals in this snow.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Lũ trẻ vừa rôm rả trò chuyện vui vẻ vừa cùng nhau làm bánh mì kẹp.","Từ ban công, chúng tôi có thể ngắm nhìn trọn vẹn khung cảnh núi non tuyệt đẹp.","Thật là điên rồ khi đi giày xăng-đan trong thời tiết có tuyết thế này.","Tôi từng cảm thấy cô đơn cho đến khi người hàng xóm mời tôi sang uống trà."]'::jsonb, 2, 'It seems crazy to wear sandals in this snow. → Thật là điên rồ khi đi giày xăng-đan trong thời tiết có tuyết thế này.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_5', 'en-a2-17', NULL, 'comprehensive_test', 'listening', 'scared', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đi qua; vượt qua","thiết kế; phác thảo","thu thập; sưu tầm","sợ hãi; khiếp sợ; lo lắng"]'::jsonb, 3, 'scared (/skerd/) → sợ hãi; khiếp sợ; lo lắng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_6', 'en-a2-17', NULL, 'comprehensive_test', 'listening', 'I was surprised to find flowers outside my door.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúc mừng bạn đã vượt qua bài thi lái xe sáng nay!","Tôi từng cảm thấy cô đơn cho đến khi người hàng xóm mời tôi sang uống trà.","Tôi rất ngạc nhiên khi thấy những bông hoa ở trước cửa nhà mình.","Khuôn mặt cô ấy rạng rỡ niềm vui khi chú chó con xuất hiện."]'::jsonb, 2, 'I was surprised to find flowers outside my door. → Tôi rất ngạc nhiên khi thấy những bông hoa ở trước cửa nhà mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_7', 'en-a2-17', NULL, 'comprehensive_test', 'listening', 'fantastic', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự cắt tóc; kiểu tóc","bánh nướng; bánh pa-tê-sô","bãi đậu xe; bãi đỗ xe","cực kỳ tốt; tuyệt vời"]'::jsonb, 3, 'fantastic (/fænˈtæstɪk/) → cực kỳ tốt; tuyệt vời; kỳ ảo; mang tính tưởng tượng; cực kỳ lớn; khổng lồ', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_8', 'en-a2-17', NULL, 'comprehensive_test', 'listening', 'I''m glad you came to dinner with us tonight.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cảnh quan nhìn từ ngọn núi thực sự vô cùng tuyệt vời.","Tôi rất vui vì bạn đã đến ăn tối cùng chúng tôi tối nay.","Tôi hy vọng trời sẽ tạnh mưa trước buổi dã ngoại của chúng ta.","May mắn là tôi đã tìm thấy chìa khóa trước khi xe buýt đến."]'::jsonb, 1, 'I''m glad you came to dinner with us tonight. → Tôi rất vui vì bạn đã đến ăn tối cùng chúng tôi tối nay.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_9', 'en-a2-17', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Feeling afraid of something or worried that something bad might happen.”?', '["horrible","scared","worry","sadly"]'::jsonb, 1, 'scared (/skerd/) → sợ hãi; khiếp sợ; lo lắng', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_10', 'en-a2-17', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Feeling that something unexpected has happened.”?', '["glad","nervous","wish","surprised"]'::jsonb, 3, 'surprised (/sərˈpraɪzd/) → ngạc nhiên; bất ngờ', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_11', 'en-a2-17', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “extremely good or enjoyable”?', '["fear","fantastic","unhappy","crazy"]'::jsonb, 1, 'fantastic (/fænˈtæstɪk/) → cực kỳ tốt; tuyệt vời', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_12', 'en-a2-17', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Feeling happy or pleased about something.”?', '["surprised","horrible","glad","sadly"]'::jsonb, 2, 'glad (/ɡlæd/) → vui mừng; hài lòng; phấn khởi', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
