INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_18', 'en-a2-17', NULL, 'comprehensive_test', 'reading', NULL, 'Residents are often proud of their cultural heritage and support efforts to preserve historic buildings.', 'Dựa vào câu trên, từ “proud” có nghĩa phù hợp nhất là gì?', '["ý kiến đề xuất; lời khuyên","chế độ ăn uống; khẩu phần ăn","tự hào; hãnh diện","tương cà chua"]'::jsonb, 2, 'proud: tự hào; hãnh diện; kiêu ngạo; tự phụ. Dịch cả câu: Cư dân thường tự hào về di sản văn hóa của họ và ủng hộ các nỗ lực bảo tồn các tòa nhà lịch sử.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_19', 'en-a2-17', NULL, 'comprehensive_test', 'reading', NULL, 'Starting school can be scary for young children, so teachers should create a welcoming environment.', 'Dựa vào câu trên, từ “scary” có nghĩa phù hợp nhất là gì?', '["đáng sợ; làm hoảng sợ","ứng dụng; chương trình máy tính","động cơ; máy","chủ sở hữu; người chủ"]'::jsonb, 0, 'scary: đáng sợ; làm hoảng sợ. Dịch cả câu: Việc bắt đầu đi học có thể đáng sợ đối với trẻ nhỏ, vì vậy giáo viên nên tạo ra một môi trường thân thiện.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_20', 'en-a2-17', NULL, 'comprehensive_test', 'reading', NULL, 'Older adults may feel lonely after retirement, so community centres should provide regular opportunities for social interaction.', 'Dựa vào câu trên, từ “lonely” có nghĩa phù hợp nhất là gì?', '["thứ bảy","cô đơn, buồn bã vì thiếu sự đồng hành hoặc các mối quan hệ gần gũi","huấn luyện viên; chuyên gia đào tạo","bệnh cúm; cảm cúm"]'::jsonb, 1, 'lonely: cô đơn, buồn bã vì thiếu sự đồng hành hoặc các mối quan hệ gần gũi; hẻo lánh, xa xôi hoặc ít người lui tới. Dịch cả câu: Người cao tuổi có thể cảm thấy cô đơn sau khi nghỉ hưu, vì vậy các trung tâm cộng đồng nên thường xuyên tạo cơ hội cho họ giao lưu xã hội.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_21', 'en-a2-17', NULL, 'comprehensive_test', 'reading', NULL, 'Although some people consider car-free cities a crazy idea, such policies could significantly improve urban air quality.', 'Dựa vào câu trên, từ “crazy” có nghĩa phù hợp nhất là gì?', '["vấn đề; việc","cứu; cứu sống; bảo vệ","đáy; phần thấp nhất","điên rồ; ngớ ngẩn; bất hợp lý; kỳ quặc"]'::jsonb, 3, 'crazy: điên rồ; ngớ ngẩn; bất hợp lý; kỳ quặc; phát cuồng; say mê; cuồng nhiệt; bực điên người; phát điên; cáu tiết. Dịch cả câu: Mặc dù một số người coi các thành phố không có ô tô là một ý tưởng điên rồ, nhưng những chính sách như vậy có thể cải thiện đáng kể chất lượng không khí đô thị.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_22', 'en-a2-17', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “rụt rè; bẽn lẽn; e thẹn”', '["sleepy","brush","advertisement","shy"]'::jsonb, 3, 'rụt rè; bẽn lẽn; e thẹn → shy (/ʃaɪ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_23', 'en-a2-17', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lo lắng; hồi hộp; bồn chồn”', '["sort","nervous","uniform","balloon"]'::jsonb, 1, 'lo lắng; hồi hộp; bồn chồn → nervous (/ˈnɝːvəs/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_17_24', 'en-a2-17', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lo lắng; làm cho lo lắng”', '["drugstore","bee","garbage","worry"]'::jsonb, 3, 'lo lắng; làm cho lo lắng → worry (/ˈwɜːri/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-18', 'en', 'Bài 18: Công việc & Nghề nghiệp (1) - CEFR A2', 'CEFR A2', 'A2 · Công việc', '24 từ vựng Tiếng Anh CEFR A2 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2018, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_succeed', 'en-a2-18', 'succeed', '/səkˈsiːd/', 'A2', 'thành công; đạt được mục tiêu; kế nhiệm; thay thế vị trí của ai đó', 'v.', 'success (n.), successful (adj.), successfully (adv.), successor (n.)', 'Trái nghĩa: fail', 'Để diễn tả việc thành công làm điều gì đó, dùng succeed in doing, thay vì dùng to do.', 'After several attempts, I succeeded in fixing the lamp.', NULL, 'Sau vài lần thử, tôi cuối cùng đã sửa được chiếc đèn.', '{"wordId":"succeed","ukIpa":"/səkˈsiːd/","usIpa":"/səkˈsiːd/","cefr":"A2","topic":"work","senses":[{"pos":"v.","en":"To achieve what you are trying to do.","vi":"thành công; đạt được mục tiêu"},{"pos":"v.","en":"To take someone''s position after they leave it.","vi":"kế nhiệm; thay thế vị trí của ai đó"}],"examples":[{"en":"After several attempts, I succeeded in fixing the lamp.","vi":"Sau vài lần thử, tôi cuối cùng đã sửa được chiếc đèn.","audioKind":"ex"},{"en":"Students are more likely to succeed when schools provide consistent feedback and practical support.","vi":"Học sinh có nhiều khả năng thành công hơn khi nhà trường cung cấp phản hồi liên tục và hỗ trợ thiết thực.","audioKind":"ex2"}],"collocations":[{"en":"succeed in doing something","vi":"thành công trong việc làm gì đó"},{"en":"succeed as a manager","vi":"thành công với tư cách là quản lý"},{"en":"succeed someone as chair","vi":"kế nhiệm ai đó làm chủ tịch"}],"wordFamily":["success (n.)","successful (adj.)","successfully (adv.)","successor (n.)"],"synonyms":[],"antonyms":["fail"],"tipVi":"Để diễn tả việc thành công làm điều gì đó, dùng succeed in doing, thay vì dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boss', 'en-a2-18', 'boss', '/bɔːs/', 'A2', 'sếp; thủ trưởng; ông chủ; sai bảo; ra lệnh', 'n.', 'bossy (adj.), bossiness (n.)', 'Đồng nghĩa: manager, supervisor', 'Từ "boss" mang tính khẩu ngữ; khi dùng làm động từ, cụm thông dụng nhất là "boss someone around".', 'My boss let me leave early for my appointment.', NULL, 'Sếp của tôi đã cho phép tôi về sớm để đi hẹn gặp.', '{"wordId":"boss","ukIpa":"/bɒs/","usIpa":"/bɔːs/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A person who manages workers or runs a business.","vi":"sếp; thủ trưởng; ông chủ"},{"pos":"v.","en":"To order people around in an annoying or controlling way.","vi":"sai bảo; ra lệnh"}],"examples":[{"en":"My boss let me leave early for my appointment.","vi":"Sếp của tôi đã cho phép tôi về sớm để đi hẹn gặp.","audioKind":"ex"},{"en":"A supportive boss can improve employee satisfaction by offering constructive feedback and recognising individual contributions.","vi":"Một người sếp tâm lý có thể nâng cao sự hài lòng của nhân viên bằng cách đưa ra những góp ý mang tính xây dựng và ghi nhận sự đóng góp của cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"talk to your boss","vi":"nói chuyện với sếp"},{"en":"a supportive boss","vi":"một người sếp tâm lý"},{"en":"be your own boss","vi":"tự làm chủ chính mình"},{"en":"boss someone around","vi":"sai khiến ai đó"}],"wordFamily":["bossy (adj.)","bossiness (n.)"],"synonyms":["manager","supervisor"],"antonyms":[],"tipVi":"Từ \"boss\" mang tính khẩu ngữ; khi dùng làm động từ, cụm thông dụng nhất là \"boss someone around\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_training', 'en-a2-18', 'training', '/ˈtreɪnɪŋ/', 'A2', 'sự đào tạo; quá trình huấn luyện; thể lực; rèn luyện thể thao', 'n.', 'train (v.), trainer (n.), trainee (n.)', NULL, 'Thường là danh từ không đếm được; một buổi đào tạo có thể nói là a training session.', 'My first day of training involved helping customers.', NULL, 'Ngày đào tạo đầu tiên của tôi bao gồm việc hỗ trợ khách hàng.', '{"wordId":"training","ukIpa":"/ˈtreɪnɪŋ/","usIpa":"/ˈtreɪnɪŋ/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"Learning and practice that develop skills for a particular activity.","vi":"sự đào tạo; quá trình huấn luyện"},{"pos":"n.","en":"Physical exercise and practice to prepare for sport.","vi":"thể lực; rèn luyện thể thao"}],"examples":[{"en":"My first day of training involved helping customers.","vi":"Ngày đào tạo đầu tiên của tôi bao gồm việc hỗ trợ khách hàng.","audioKind":"ex"},{"en":"Regular professional training helps employees adapt to technological changes and improves their long-term career prospects.","vi":"Việc đào tạo chuyên môn thường xuyên giúp nhân viên thích ứng với những thay đổi về công nghệ và cải thiện triển vọng nghề nghiệp lâu dài của họ.","audioKind":"ex2"}],"collocations":[{"en":"vocational training","vi":"đào tạo nghề"},{"en":"on-the-job training","vi":"đào tạo tại nơi làm việc"},{"en":"training course","vi":"khóa học đào tạo"},{"en":"strength training","vi":"tập luyện sức mạnh"}],"wordFamily":["train (v.)","trainer (n.)","trainee (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; một buổi đào tạo có thể nói là a training session.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_organize', 'en-a2-18', 'organize', '/ˈɔːrɡənaɪz/', 'A2', 'tổ chức; chuẩn bị; sắp xếp; phân loại', 'v.', 'organization (n.), organizer (n.), organized (adj.), organizational (adj.)', 'Đồng nghĩa: arrange, coordinate', 'Người Anh thường viết là organise; organize là cách viết chuẩn quốc tế.', 'Our neighbours organized a picnic by the river.', NULL, 'Hàng xóm của chúng tôi đã tổ chức một buổi dã ngoại bên bờ sông.', '{"wordId":"organize","ukIpa":"/ˈɔːɡənaɪz/","usIpa":"/ˈɔːrɡənaɪz/","cefr":"A2","topic":"work","senses":[{"pos":"v.","en":"To plan and arrange an event or activity","vi":"tổ chức; chuẩn bị"},{"pos":"v.","en":"To arrange things in a clear, useful order","vi":"sắp xếp; phân loại"}],"examples":[{"en":"Our neighbours organized a picnic by the river.","vi":"Hàng xóm của chúng tôi đã tổ chức một buổi dã ngoại bên bờ sông.","audioKind":"ex"},{"en":"Schools should organize practical workshops that help students develop communication skills and prepare for employment.","vi":"Các trường học nên tổ chức các buổi hội thảo thực tế giúp học sinh phát triển kỹ năng giao tiếp và chuẩn bị cho việc làm.","audioKind":"ex2"}],"collocations":[{"en":"organize an event","vi":"tổ chức sự kiện"},{"en":"organize a meeting","vi":"tổ chức cuộc họp"},{"en":"organize your time","vi":"sắp xếp thời gian của bạn"},{"en":"organize files","vi":"sắp xếp tài liệu"}],"wordFamily":["organization (n.)","organizer (n.)","organized (adj.)","organizational (adj.)"],"synonyms":["arrange","coordinate"],"antonyms":[],"tipVi":"Người Anh thường viết là organise; organize là cách viết chuẩn quốc tế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_organise', 'en-a2-18', 'organise', '/ˈɔːrɡənaɪz/', 'A2', 'tổ chức; chuẩn bị sự kiện hoặc hoạt động; sắp xếp; phân loại đồ đạc ngăn nắp, khoa học', 'v.', 'organisation (n.), organiser (n.), organised (adj.), organisational (adj.)', 'Đồng nghĩa: arrange, coordinate', 'organise thường dùng trong tiếng Anh Anh; tiếng Mỹ thường viết là organize.', 'We organise a picnic for our neighbours every summer.', NULL, 'Chúng tôi tổ chức một buổi dã ngoại cho hàng xóm vào mỗi mùa hè.', '{"wordId":"organise","ukIpa":"/ˈɔːɡənaɪz/","usIpa":"/ˈɔːrɡənaɪz/","cefr":"A2","topic":"work","senses":[{"pos":"v.","en":"plan and arrange an event or activity","vi":"tổ chức; chuẩn bị sự kiện hoặc hoạt động"},{"pos":"v.","en":"put things into a clear and useful order","vi":"sắp xếp; phân loại đồ đạc ngăn nắp, khoa học"}],"examples":[{"en":"We organise a picnic for our neighbours every summer.","vi":"Chúng tôi tổ chức một buổi dã ngoại cho hàng xóm vào mỗi mùa hè.","audioKind":"ex"},{"en":"Local councils can organise community workshops to teach residents practical ways to reduce household waste.","vi":"Hội đồng địa phương có thể tổ chức các buổi workshop cộng đồng để hướng dẫn cư dân những cách thiết thực nhằm giảm thiểu rác thải sinh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"organise an event","vi":"tổ chức một sự kiện"},{"en":"organise a meeting","vi":"tổ chức một cuộc họp"},{"en":"organise your time","vi":"sắp xếp thời gian của bạn"},{"en":"organise files","vi":"sắp xếp tài liệu"}],"wordFamily":["organisation (n.)","organiser (n.)","organised (adj.)","organisational (adj.)"],"synonyms":["arrange","coordinate"],"antonyms":[],"tipVi":"organise thường dùng trong tiếng Anh Anh; tiếng Mỹ thường viết là organize.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_manager', 'en-a2-18', 'manager', '/ˈmænɪdʒɚ/', 'A2', 'quản lý; giám đốc; người điều hành', 'n.', 'manage (v.), management (n.), managerial (adj.)', NULL, 'manager chỉ người quản lý; management có thể chỉ công việc quản lý hoặc ban quản lý.', 'The manager helped a new employee arrange the shelves.', NULL, 'Người quản lý đã giúp một nhân viên mới sắp xếp các kệ hàng.', '{"wordId":"manager","ukIpa":"/ˈmænɪdʒə/","usIpa":"/ˈmænɪdʒɚ/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A person responsible for running a business, team, or department.","vi":"quản lý; giám đốc; người điều hành"}],"examples":[{"en":"The manager helped a new employee arrange the shelves.","vi":"Người quản lý đã giúp một nhân viên mới sắp xếp các kệ hàng.","audioKind":"ex"},{"en":"An effective manager encourages open communication and ensures that employees have sufficient resources to complete their tasks.","vi":"Một nhà quản lý hiệu quả sẽ khuyến khích giao tiếp cởi mở và đảm bảo nhân viên có đủ nguồn lực để hoàn thành nhiệm vụ của họ.","audioKind":"ex2"}],"collocations":[{"en":"project manager","vi":"quản lý dự án"},{"en":"store manager","vi":"quản lý cửa hàng"},{"en":"senior manager","vi":"quản lý cấp cao"},{"en":"line manager","vi":"quản lý trực tiếp"}],"wordFamily":["manage (v.)","management (n.)","managerial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"manager chỉ người quản lý; management có thể chỉ công việc quản lý hoặc ban quản lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_photocopier', 'en-a2-18', 'photocopier', '/ˈfoʊtoʊkɑːpiər/', 'A2', 'máy phô tô; máy photocopy', 'n.', 'photocopy (n.), photocopy (v.), photocopying (n.)', 'Đồng nghĩa: copier', 'Photocopier là máy móc thiết bị; còn photocopy là bản sao hoặc hành động phô tô.', 'The office photocopier has run out of paper again.', NULL, 'Máy photocopy của văn phòng lại hết giấy rồi.', '{"wordId":"photocopier","ukIpa":"/ˈfəʊtəʊkɒpiə/","usIpa":"/ˈfoʊtoʊkɑːpiər/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A machine that makes paper copies of documents or pictures.","vi":"máy phô tô; máy photocopy"}],"examples":[{"en":"The office photocopier has run out of paper again.","vi":"Máy photocopy của văn phòng lại hết giấy rồi.","audioKind":"ex"},{"en":"Providing a shared photocopier allows small businesses to reduce equipment costs while meeting their daily printing needs.","vi":"Việc trang bị một máy photocopy chung giúp các doanh nghiệp nhỏ giảm chi phí thiết bị mà vẫn đáp ứng được nhu cầu in ấn hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"use a photocopier","vi":"sử dụng máy photocopy"},{"en":"office photocopier","vi":"máy photocopy văn phòng"},{"en":"colour photocopier","vi":"máy photocopy màu"}],"wordFamily":["photocopy (n.)","photocopy (v.)","photocopying (n.)"],"synonyms":["copier"],"antonyms":[],"tipVi":"Photocopier là máy móc thiết bị; còn photocopy là bản sao hoặc hành động phô tô.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_part-time', 'en-a2-18', 'part-time', '/ˌpɑːrt ˈtaɪm/', 'A2', 'bán thời gian; làm thêm; theo hình thức bán thời gian', 'adj.', NULL, 'Trái nghĩa: full-time', 'Có thể dùng làm tính từ hoặc trạng thái phó từ: a part-time job hoặc work part-time.', 'My sister has a part-time job at a bakery.', NULL, 'Chị gái tôi làm việc bán thời gian tại một cửa hàng bánh mì.', '{"wordId":"part-time","ukIpa":"/ˌpɑːt ˈtaɪm/","usIpa":"/ˌpɑːrt ˈtaɪm/","cefr":"A2","topic":"work","senses":[{"pos":"adj.","en":"Involving fewer hours than a full working or studying week.","vi":"bán thời gian; làm thêm"},{"pos":"adv.","en":"For fewer hours than a full working or studying week.","vi":"theo hình thức bán thời gian"}],"examples":[{"en":"My sister has a part-time job at a bakery.","vi":"Chị gái tôi làm việc bán thời gian tại một cửa hàng bánh mì.","audioKind":"ex"},{"en":"Part-time employment allows university students to gain practical experience while continuing to focus on their studies.","vi":"Việc làm bán thời gian giúp sinh viên đại học tích lũy kinh nghiệm thực tế trong khi vẫn tiếp tục tập trung vào việc học.","audioKind":"ex2"}],"collocations":[{"en":"a part-time job","vi":"một công việc bán thời gian"},{"en":"work part-time","vi":"làm việc bán thời gian"},{"en":"a part-time course","vi":"một khóa học bán thời gian"}],"wordFamily":[],"synonyms":[],"antonyms":["full-time"],"tipVi":"Có thể dùng làm tính từ hoặc trạng thái phó từ: a part-time job hoặc work part-time.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hardworking', 'en-a2-18', 'hardworking', '/ˌhɑːrdˈwɜːrkɪŋ/', 'A2', 'chăm chỉ; siêng năng', 'adj.', NULL, 'Đồng nghĩa: diligent, industrious · Trái nghĩa: lazy', 'Là tính từ; cụm từ "làm việc chăm chỉ" dùng động từ work hard.', 'Our hardworking neighbour grows vegetables for the whole street.', NULL, 'Người hàng xóm chăm chỉ của chúng tôi trồng rau cho cả con phố.', '{"wordId":"hardworking","ukIpa":"/ˌhɑːdˈwɜːkɪŋ/","usIpa":"/ˌhɑːrdˈwɜːrkɪŋ/","cefr":"A2","topic":"work","senses":[{"pos":"adj.","en":"putting considerable effort and care into work","vi":"chăm chỉ; siêng năng"}],"examples":[{"en":"Our hardworking neighbour grows vegetables for the whole street.","vi":"Người hàng xóm chăm chỉ của chúng tôi trồng rau cho cả con phố.","audioKind":"ex"},{"en":"Even hardworking students may struggle academically without access to suitable learning resources and support.","vi":"Ngay cả những học sinh chăm chỉ cũng có thể gặp khó khăn trong học tập nếu thiếu các nguồn lực và sự hỗ trợ học tập phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"hardworking student","vi":"học sinh chăm chỉ"},{"en":"hardworking staff","vi":"nhân viên siêng năng"},{"en":"hardworking family","vi":"gia đình chăm chỉ"}],"wordFamily":[],"synonyms":["diligent","industrious"],"antonyms":["lazy"],"tipVi":"Là tính từ; cụm từ \"làm việc chăm chỉ\" dùng động từ work hard.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_director', 'en-a2-18', 'director', '/dəˈrektər/', 'A2', 'giám đốc; thành viên hội đồng quản trị; người quản lý; đạo diễn', 'n.', 'direct (v.), direction (n.), directorial (adj.)', NULL, 'Có thể dùng để chỉ giám đốc hoặc thành viên hội đồng quản trị của tổ chức, cũng như đạo diễn phim hoặc kịch.', 'Our director welcomed the new staff at breakfast.', NULL, 'Giám đốc của chúng tôi đã chào đón các nhân viên mới trong bữa sáng.', '{"wordId":"director","ukIpa":"/dəˈrektə/","usIpa":"/dəˈrektər/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"Someone who manages an organisation, department, or company.","vi":"giám đốc; thành viên hội đồng quản trị; người quản lý"},{"pos":"n.","en":"Someone who guides actors and controls a film or play.","vi":"đạo diễn"}],"examples":[{"en":"Our director welcomed the new staff at breakfast.","vi":"Giám đốc của chúng tôi đã chào đón các nhân viên mới trong bữa sáng.","audioKind":"ex"},{"en":"A museum director must balance the need to attract visitors with the responsibility to preserve valuable collections.","vi":"Giám đốc bảo tàng phải cân bằng giữa nhu cầu thu hút khách tham quan và trách nhiệm bảo tồn các bộ sưu tập có giá trị.","audioKind":"ex2"}],"collocations":[{"en":"managing director","vi":"giám đốc điều hành"},{"en":"board of directors","vi":"hội đồng quản trị"},{"en":"film director","vi":"đạo diễn phim"},{"en":"director of operations","vi":"giám đốc vận hành"}],"wordFamily":["direct (v.)","direction (n.)","directorial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể dùng để chỉ giám đốc hoặc thành viên hội đồng quản trị của tổ chức, cũng như đạo diễn phim hoặc kịch.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_career', 'en-a2-18', 'career', '/kəˈrɪr/', 'A2', 'sự nghiệp, quá trình làm việc của một người thường trong một ngành nghề cụ thể; lao nhanh theo cách có vẻ mất kiểm soát, lao vun vút', 'n.', 'careerist (n.)', NULL, 'Từ career nhấn mạnh quá trình phát triển nghề nghiệp lâu dài, trong khi job chỉ công việc cụ thể trước mắt.', 'My sister hopes to build a career in nursing.', NULL, 'Chị tôi hy vọng sẽ gây dựng sự nghiệp trong ngành điều dưỡng.', '{"wordId":"career","ukIpa":"/kəˈrɪə/","usIpa":"/kəˈrɪr/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"a person''s working life, often within a particular profession","vi":"sự nghiệp, quá trình làm việc của một người thường trong một ngành nghề cụ thể"},{"pos":"v.","en":"to move very fast in a way that seems uncontrolled","vi":"lao nhanh theo cách có vẻ mất kiểm soát, lao vun vút"}],"examples":[{"en":"My sister hopes to build a career in nursing.","vi":"Chị tôi hy vọng sẽ gây dựng sự nghiệp trong ngành điều dưỡng.","audioKind":"ex"},{"en":"Access to affordable training enables adults to change career and adapt to a rapidly evolving labour market.","vi":"Việc tiếp cận các khóa đào tạo vừa túi tiền giúp người trưởng thành có thể chuyển đổi nghề nghiệp và thích ứng với thị trường lao động đang phát triển nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"career prospects","vi":"triển vọng nghề nghiệp"},{"en":"career development","vi":"phát triển sự nghiệp"},{"en":"pursue a career","vi":"theo đuổi một sự nghiệp"},{"en":"a career in teaching","vi":"sự nghiệp giảng dạy"}],"wordFamily":["careerist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ career nhấn mạnh quá trình phát triển nghề nghiệp lâu dài, trong khi job chỉ công việc cụ thể trước mắt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_assistant', 'en-a2-18', 'assistant', '/əˈsɪstənt/', 'A2', 'trợ lý; phụ tá; phó; phụ trách trợ giúp', 'n.', 'assist (v.), assistance (n.)', 'Đồng nghĩa: helper, aide', 'assistant chỉ người, trong khi assistance chỉ sự trợ giúp và thường là danh từ không đếm được.', 'The assistant brought fresh towels into the treatment room.', NULL, 'Người trợ lý đã mang khăn sạch vào phòng điều trị.', '{"wordId":"assistant","ukIpa":"/əˈsɪstənt/","usIpa":"/əˈsɪstənt/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A person who helps someone with their work.","vi":"trợ lý; phụ tá"},{"pos":"adj.","en":"Having a supporting role below the main person in charge.","vi":"phó; phụ trách trợ giúp"}],"examples":[{"en":"The assistant brought fresh towels into the treatment room.","vi":"Người trợ lý đã mang khăn sạch vào phòng điều trị.","audioKind":"ex"},{"en":"Teaching assistants can provide additional support for children who need more individual attention in large classes.","vi":"Trợ giảng có thể cung cấp thêm sự hỗ trợ cho những trẻ em cần được quan tâm cá nhân nhiều hơn trong các lớp học đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"teaching assistant","vi":"trợ giảng"},{"en":"personal assistant","vi":"trợ lý cá nhân"},{"en":"shop assistant","vi":"nhân viên bán hàng"},{"en":"assistant manager","vi":"trợ lý quản lý"}],"wordFamily":["assist (v.)","assistance (n.)"],"synonyms":["helper","aide"],"antonyms":[],"tipVi":"assistant chỉ người, trong khi assistance chỉ sự trợ giúp và thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_firefighter', 'en-a2-18', 'firefighter', '/ˈfaɪərfaɪtər/', 'A2', 'lính cứu hỏa; chiến sĩ phòng cháy chữa cháy', 'n.', 'firefighting (n.)', NULL, 'firefighter là từ trung tính về giới tính và được sử dụng rộng rãi hơn fireman.', 'The firefighter showed us how to use the hose.', NULL, 'Người lính cứu hỏa đã chỉ cho chúng tôi cách sử dụng vòi phun nước.', '{"wordId":"firefighter","ukIpa":"/ˈfaɪəfaɪtə/","usIpa":"/ˈfaɪərfaɪtər/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A person trained to put out fires and rescue people","vi":"lính cứu hỏa; chiến sĩ phòng cháy chữa cháy"}],"examples":[{"en":"The firefighter showed us how to use the hose.","vi":"Người lính cứu hỏa đã chỉ cho chúng tôi cách sử dụng vòi phun nước.","audioKind":"ex"},{"en":"Every firefighter requires regular training to respond safely and effectively to emergencies in increasingly complex urban environments.","vi":"Mỗi chiến sĩ phòng cháy chữa cháy đều cần được đào tạo thường xuyên để ứng phó an toàn và hiệu quả với các tình huống khẩn cấp trong môi trường đô thị ngày càng phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"a trained firefighter","vi":"lính cứu hỏa được đào tạo bài bản"},{"en":"a volunteer firefighter","vi":"lính cứu hỏa tình nguyện"},{"en":"firefighter training","vi":"đào tạo nghiệp vụ phòng cháy chữa cháy"}],"wordFamily":["firefighting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"firefighter là từ trung tính về giới tính và được sử dụng rộng rãi hơn fireman.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_successful', 'en-a2-18', 'successful', '/səkˈsesfəl/', 'A2', 'thành công; có kết quả tốt; thành đạt; có sự nghiệp rực rỡ', 'adj.', 'success (n.), succeed (v.), successfully (adv.), unsuccessful (adj.)', 'Đồng nghĩa: effective · Trái nghĩa: unsuccessful', 'Cấu trúc thông dụng là be successful in doing; dạng động từ của từ này là succeed.', 'Our first attempt at baking bread was surprisingly successful.', NULL, 'Lần đầu tiên chúng tôi thử nướng bánh mì lại thành công một cách bất ngờ.', '{"wordId":"successful","ukIpa":"/səkˈsesfəl/","usIpa":"/səkˈsesfəl/","cefr":"A2","topic":"work","senses":[{"pos":"adj.","en":"Achieving the result that was wanted or intended.","vi":"thành công; có kết quả tốt"},{"pos":"adj.","en":"Having achieved wealth, respect, or a good position.","vi":"thành đạt; có sự nghiệp rực rỡ"}],"examples":[{"en":"Our first attempt at baking bread was surprisingly successful.","vi":"Lần đầu tiên chúng tôi thử nướng bánh mì lại thành công một cách bất ngờ.","audioKind":"ex"},{"en":"Successful recycling programmes depend on convenient collection facilities and clear guidance for households and businesses.","vi":"Các chương trình tái chế thành công phụ thuộc vào các cơ sở thu gom thuận tiện và hướng dẫn rõ ràng cho các hộ gia đình cũng như doanh nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"successful career","vi":"sự nghiệp thành công"},{"en":"successful outcome","vi":"kết quả mỹ mãn"},{"en":"highly successful","vi":"vô cùng thành công"},{"en":"successful in doing something","vi":"thành công trong việc làm gì đó"}],"wordFamily":["success (n.)","succeed (v.)","successfully (adv.)","unsuccessful (adj.)"],"synonyms":["effective"],"antonyms":["unsuccessful"],"tipVi":"Cấu trúc thông dụng là be successful in doing; dạng động từ của từ này là succeed.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skill', 'en-a2-18', 'skill', '/skɪl/', 'A2', 'kỹ năng; kỹ xảo; sự khéo léo', 'n.', 'skilled (adj.), skilful (adj.), skilfully (adv.), unskilled (adj.)', 'Đồng nghĩa: ability, expertise', 'Kỹ năng cụ thể là danh từ đếm được; khi chỉ năng lực hoặc mức độ thành thạo chung thì thường là danh từ không đếm được.', 'Baking good bread takes patience and a little skill.', NULL, 'Làm ra những mẻ bánh mì ngon đòi hỏi sự kiên nhẫn và một chút kỹ năng.', '{"wordId":"skill","ukIpa":"/skɪl/","usIpa":"/skɪl/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"an ability to do something well, developed through practice","vi":"kỹ năng; kỹ xảo; sự khéo léo"}],"examples":[{"en":"Baking good bread takes patience and a little skill.","vi":"Làm ra những mẻ bánh mì ngon đòi hỏi sự kiên nhẫn và một chút kỹ năng.","audioKind":"ex"},{"en":"Schools should teach practical skills that help young people manage money and communicate effectively.","vi":"Các nhà trường nên giảng dạy những kỹ năng thực tế giúp người trẻ tuổi quản lý tài chính và giao tiếp hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"communication skills","vi":"kỹ năng giao tiếp"},{"en":"practical skills","vi":"kỹ năng thực tế"},{"en":"develop a skill","vi":"phát triển một kỹ năng"},{"en":"skill in doing something","vi":"kỹ năng làm việc gì đó"}],"wordFamily":["skilled (adj.)","skilful (adj.)","skilfully (adv.)","unskilled (adj.)"],"synonyms":["ability","expertise"],"antonyms":[],"tipVi":"Kỹ năng cụ thể là danh từ đếm được; khi chỉ năng lực hoặc mức độ thành thạo chung thì thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_partner', 'en-a2-18', 'partner', '/ˈpɑːrtnər/', 'A2', 'cộng sự; đối tác; người cùng chơi; bạn đời; người yêu; vợ/chồng; hợp tác; kết hợp làm ăn', 'n.', 'partnership (n.)', NULL, 'partner không phân biệt giới tính; khi làm động từ thường dùng partner with.', 'My dance partner waited patiently while I practised.', NULL, 'Bạn nhảy của tôi đã kiên nhẫn đợi trong lúc tôi tập luyện.', '{"wordId":"partner","ukIpa":"/ˈpɑːtnə/","usIpa":"/ˈpɑːrtnər/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"Someone you work, play, or share a business with.","vi":"cộng sự; đối tác; người cùng chơi"},{"pos":"n.","en":"Someone you share a romantic relationship or married life with.","vi":"bạn đời; người yêu; vợ/chồng"},{"pos":"v.","en":"Work or take part in an activity with someone.","vi":"hợp tác; kết hợp làm ăn"}],"examples":[{"en":"My dance partner waited patiently while I practised.","vi":"Bạn nhảy của tôi đã kiên nhẫn đợi trong lúc tôi tập luyện.","audioKind":"ex"},{"en":"Universities can partner with local businesses to offer students practical experience before they enter the workforce.","vi":"Các trường đại học có thể hợp tác với các doanh nghiệp địa phương để mang lại cho sinh viên kinh nghiệm thực tế trước khi họ bước chân vào thị trường lao động.","audioKind":"ex2"}],"collocations":[{"en":"business partner","vi":"đối tác kinh doanh; người hùn vốn"},{"en":"dance partner","vi":"bạn nhảy"},{"en":"life partner","vi":"bạn đời; người bạn trăm năm"},{"en":"partner with","vi":"hợp tác với"}],"wordFamily":["partnership (n.)"],"synonyms":[],"antonyms":[],"tipVi":"partner không phân biệt giới tính; khi làm động từ thường dùng partner with.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_receptionist', 'en-a2-18', 'receptionist', '/rɪˈsepʃənɪst/', 'A2', 'nhân viên lễ tân', 'n.', 'reception (n.), receive (v.)', NULL, 'reception là khu vực tiếp đón; receptionist là nhân viên lễ tân.', 'The receptionist smiled and handed us our room keys.', NULL, 'Nhân viên lễ tân mỉm cười và trao chìa khóa phòng cho chúng tôi.', '{"wordId":"receptionist","ukIpa":"/rɪˈsepʃənɪst/","usIpa":"/rɪˈsepʃənɪst/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"Someone who welcomes visitors and handles enquiries at a reception desk.","vi":"nhân viên lễ tân"}],"examples":[{"en":"The receptionist smiled and handed us our room keys.","vi":"Nhân viên lễ tân mỉm cười và trao chìa khóa phòng cho chúng tôi.","audioKind":"ex"},{"en":"A skilled receptionist can improve patients'' experiences by managing appointments efficiently and responding calmly to enquiries.","vi":"Một nhân viên lễ tân lành nghề có thể cải thiện trải nghiệm của bệnh nhân bằng cách sắp xếp lịch hẹn hiệu quả và điềm tĩnh giải đáp các thắc mắc.","audioKind":"ex2"}],"collocations":[{"en":"hotel receptionist","vi":"lễ tân khách sạn"},{"en":"work as a receptionist","vi":"làm việc với tư cách nhân viên lễ tân"},{"en":"ask the receptionist","vi":"hỏi nhân viên lễ tân"}],"wordFamily":["reception (n.)","receive (v.)"],"synonyms":[],"antonyms":[],"tipVi":"reception là khu vực tiếp đón; receptionist là nhân viên lễ tân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_salesman', 'en-a2-18', 'salesman', '/ˈseɪlzmən/', 'A2', 'nam nhân viên bán hàng; nam nhân viên tiếp thị', 'n.', 'sales (n.), salesperson (n.), saleswoman (n.)', 'Đồng nghĩa: salesperson, sales representative', 'salesman chỉ rõ là nam giới; khi không muốn phân biệt giới tính, hãy dùng salesperson.', 'The salesman showed us how to fold the bicycle.', NULL, 'Nhân viên bán hàng đã hướng dẫn chúng tôi cách gập chiếc xe đạp lại.', '{"wordId":"salesman","ukIpa":"/ˈseɪlzmən/","usIpa":"/ˈseɪlzmən/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A man whose job is to sell goods or services.","vi":"nam nhân viên bán hàng; nam nhân viên tiếp thị"}],"examples":[{"en":"The salesman showed us how to fold the bicycle.","vi":"Nhân viên bán hàng đã hướng dẫn chúng tôi cách gập chiếc xe đạp lại.","audioKind":"ex"},{"en":"A skilled salesman should explain product limitations honestly rather than pressure customers into making unnecessary purchases.","vi":"Một nhân viên bán hàng giỏi nên giải thích thành thật những hạn chế của sản phẩm thay vì ép buộc khách hàng mua những thứ không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"a car salesman","vi":"người bán ô tô"},{"en":"a travelling salesman","vi":"nhân viên tiếp thị lưu động"},{"en":"an experienced salesman","vi":"nhân viên bán hàng giàu kinh nghiệm"}],"wordFamily":["sales (n.)","salesperson (n.)","saleswoman (n.)"],"synonyms":["salesperson","sales representative"],"antonyms":[],"tipVi":"salesman chỉ rõ là nam giới; khi không muốn phân biệt giới tính, hãy dùng salesperson.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_businessman', 'en-a2-18', 'businessman', '/ˈbɪznəsmæn/', 'A2', 'doanh nhân; nhà kinh doanh nam', 'n.', 'business (n.), businesswoman (n.), businessperson (n.)', NULL, 'Dạng số nhiều là businessmen; nếu không phân biệt giới tính có thể dùng businessperson.', 'A local businessman opened a bakery near our school.', NULL, 'Một doanh nhân địa phương vừa mở một tiệm bánh gần trường chúng tôi.', '{"wordId":"businessman","ukIpa":"/ˈbɪznəsmæn/","usIpa":"/ˈbɪznəsmæn/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A man who works in business, especially managing a company.","vi":"doanh nhân; nhà kinh doanh nam"}],"examples":[{"en":"A local businessman opened a bakery near our school.","vi":"Một doanh nhân địa phương vừa mở một tiệm bánh gần trường chúng tôi.","audioKind":"ex"},{"en":"A successful businessman can support local development by investing in training and creating stable employment opportunities.","vi":"Một doanh nhân thành đạt có thể hỗ trợ phát triển cộng đồng bằng cách đầu tư vào đào tạo và tạo ra cơ hội việc làm ổn định.","audioKind":"ex2"}],"collocations":[{"en":"successful businessman","vi":"doanh nhân thành đạt"},{"en":"local businessman","vi":"doanh nhân địa phương"},{"en":"wealthy businessman","vi":"đại gia thương gia"}],"wordFamily":["business (n.)","businesswoman (n.)","businessperson (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là businessmen; nếu không phân biệt giới tính có thể dùng businessperson.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_day-off', 'en-a2-18', 'day off', '/ˌdeɪ ˈɔːf/', 'A2', 'ngày nghỉ; ngày không phải làm việc', 'n.', NULL, NULL, 'Dạng số nhiều là days off; xin nghỉ một ngày nói take a day off.', 'On my day off, I cycled to the lake.', NULL, 'Vào ngày nghỉ của mình, tôi đã đạp xe ra hồ.', '{"wordId":"day-off","ukIpa":"/ˌdeɪ ˈɒf/","usIpa":"/ˌdeɪ ˈɔːf/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A day when you do not have to work.","vi":"ngày nghỉ; ngày không phải làm việc"}],"examples":[{"en":"On my day off, I cycled to the lake.","vi":"Vào ngày nghỉ của mình, tôi đã đạp xe ra hồ.","audioKind":"ex"},{"en":"Taking a regular day off allows employees to recover and may improve their performance at work.","vi":"Việc có những ngày nghỉ định kỳ giúp nhân viên hồi phục sức lực và có thể cải thiện hiệu suất làm việc của họ.","audioKind":"ex2"}],"collocations":[{"en":"take a day off","vi":"xin nghỉ một ngày"},{"en":"have a day off","vi":"có một ngày nghỉ"},{"en":"a day off work","vi":"một ngày nghỉ làm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là days off; xin nghỉ một ngày nói take a day off.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_manage', 'en-a2-18', 'manage', '/ˈmænɪdʒ/', 'A2', 'xoay sở thành công; làm được; quản lý; điều hành; đương đầu; xoay xở qua ngày', 'v.', 'manager (n.), management (n.), manageable (adj.), unmanageable (adj.)', NULL, 'manage to do diễn tả việc hoàn thành thành công, không chỉ dừng lại ở mức cố gắng.', 'I managed to carry all the bags upstairs.', NULL, 'Tôi đã xoay sở mang tất cả các túi đồ lên lầu.', '{"wordId":"manage","ukIpa":"/ˈmænɪdʒ/","usIpa":"/ˈmænɪdʒ/","cefr":"A2","topic":"work","senses":[{"pos":"v.","en":"To succeed in doing something, especially something difficult.","vi":"xoay sở thành công; làm được"},{"pos":"v.","en":"To direct or control a business, team, or activity.","vi":"quản lý; điều hành"},{"pos":"v.","en":"To cope with a situation despite difficulties or limited resources.","vi":"đương đầu; xoay xở qua ngày"}],"examples":[{"en":"I managed to carry all the bags upstairs.","vi":"Tôi đã xoay sở mang tất cả các túi đồ lên lầu.","audioKind":"ex"},{"en":"Many students manage to balance academic demands with paid employment by planning their weekly schedules carefully.","vi":"Nhiều sinh viên khéo léo sắp xếp thời gian biểu hàng tuần để có thể vừa học tập vừa làm việc kiếm tiền.","audioKind":"ex2"}],"collocations":[{"en":"manage to do something","vi":"xoay xở làm việc gì"},{"en":"manage a team","vi":"quản lý một đội ngũ"},{"en":"manage your time","vi":"quản lý thời gian của bạn"},{"en":"manage without help","vi":"tự xoay xở không cần giúp"}],"wordFamily":["manager (n.)","management (n.)","manageable (adj.)","unmanageable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"manage to do diễn tả việc hoàn thành thành công, không chỉ dừng lại ở mức cố gắng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_barber', 'en-a2-18', 'barber', '/ˈbɑːrbɚ/', 'A2', 'thợ hớt tóc nam; thợ cắt tóc', 'n.', 'barbering (n.)', 'Đồng nghĩa: hairdresser', 'barber chuyên cắt tóc và cạo râu cho nam giới; barber''s có thể chỉ tiệm cắt tóc.', 'The barber trimmed my hair before the wedding.', NULL, 'Thợ cắt tóc đã tỉa lại mái tóc cho tôi trước lễ cưới.', '{"wordId":"barber","ukIpa":"/ˈbɑːbə/","usIpa":"/ˈbɑːrbɚ/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"Someone who cuts men''s hair and trims or shaves beards.","vi":"thợ hớt tóc nam; thợ cắt tóc"}],"examples":[{"en":"The barber trimmed my hair before the wedding.","vi":"Thợ cắt tóc đã tỉa lại mái tóc cho tôi trước lễ cưới.","audioKind":"ex"},{"en":"Local businesses, such as a neighbourhood barber, provide essential services and create opportunities for informal social interaction.","vi":"Các cơ sở kinh doanh địa phương, chẳng hạn như tiệm hớt tóc trong khu phố, cung cấp các dịch vụ thiết yếu và tạo cơ hội giao lưu xã hội không chính thức.","audioKind":"ex2"}],"collocations":[{"en":"go to the barber''s","vi":"đi tiệm cắt tóc"},{"en":"a barber shop","vi":"tiệm hớt tóc nam"},{"en":"a barber''s chair","vi":"ghế cắt tóc"}],"wordFamily":["barbering (n.)"],"synonyms":["hairdresser"],"antonyms":[],"tipVi":"barber chuyên cắt tóc và cạo râu cho nam giới; barber''s có thể chỉ tiệm cắt tóc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_salary', 'en-a2-18', 'salary', '/ˈsæləri/', 'A2', 'tiền lương; lương tháng/lương năm', 'n.', 'salaried (adj.)', 'Đồng nghĩa: pay', 'salary chỉ tiền lương cố định; wages thường chỉ tiền công tính theo giờ hoặc theo tuần.', 'Her new job offers a higher salary and shorter hours.', NULL, 'Công việc mới của cô ấy có mức lương cao hơn và thời gian làm việc ngắn hơn.', '{"wordId":"salary","ukIpa":"/ˈsæləri/","usIpa":"/ˈsæləri/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A fixed regular payment for work, often expressed yearly","vi":"tiền lương; lương tháng/lương năm"}],"examples":[{"en":"Her new job offers a higher salary and shorter hours.","vi":"Công việc mới của cô ấy có mức lương cao hơn và thời gian làm việc ngắn hơn.","audioKind":"ex"},{"en":"Although salary influences career choices, many graduates also value job security and opportunities for professional development.","vi":"Mặc dù tiền lương ảnh hưởng đến lựa chọn nghề nghiệp, nhiều sinh viên mới ra trường cũng coi trọng sự ổn định công việc và cơ hội phát triển chuyên môn.","audioKind":"ex2"}],"collocations":[{"en":"annual salary","vi":"lương năm"},{"en":"starting salary","vi":"lương khởi điểm"},{"en":"salary increase","vi":"tăng lương"},{"en":"competitive salary","vi":"mức lương cạnh tranh"}],"wordFamily":["salaried (adj.)"],"synonyms":["pay"],"antonyms":[],"tipVi":"salary chỉ tiền lương cố định; wages thường chỉ tiền công tính theo giờ hoặc theo tuần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_document', 'en-a2-18', 'document', '/ˈdɑːkjumənt/', 'A2', 'tài liệu; văn bản; hồ sơ điện tử; ghi chép; lập tài liệu; tài liệu hóa', 'n.', 'documentation (n.), documentary (adj.)', 'Đồng nghĩa: record', 'Từ này có thể là danh từ hoặc động từ.', 'Please save the document before you close your laptop.', NULL, 'Vui lòng lưu tài liệu trước khi bạn đóng máy tính xách tay.', '{"wordId":"document","ukIpa":"/ˈdɒkjumənt/","usIpa":"/ˈdɑːkjumənt/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"a paper or digital record containing information","vi":"tài liệu; văn bản; hồ sơ điện tử"},{"pos":"v.","en":"record information about something in writing, photographs, or other forms","vi":"ghi chép; lập tài liệu; tài liệu hóa"}],"examples":[{"en":"Please save the document before you close your laptop.","vi":"Vui lòng lưu tài liệu trước khi bạn đóng máy tính xách tay.","audioKind":"ex"},{"en":"Researchers should document changes in local wildlife to assess the environmental impact of urban development.","vi":"Các nhà nghiên cứu nên ghi chép lại những thay đổi của động vật hoang dã địa phương để đánh giá tác động sinh thái của việc phát triển đô thị.","audioKind":"ex2"}],"collocations":[{"en":"official document","vi":"tài liệu chính thức"},{"en":"travel documents","vi":"giấy tờ tùy thân"},{"en":"save a document","vi":"lưu tài liệu"},{"en":"document changes","vi":"ghi chép sự thay đổi"}],"wordFamily":["documentation (n.)","documentary (adj.)"],"synonyms":["record"],"antonyms":[],"tipVi":"Từ này có thể là danh từ hoặc động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_18_1', 'en-a2-18', 'Cách dùng “skill” (n.) — kỹ năng; kỹ xảo; sự khéo léo', 'communication skills  ·  practical skills  ·  develop a skill', 'Kỹ năng cụ thể là danh từ đếm được; khi chỉ năng lực hoặc mức độ thành thạo chung thì thường là danh từ không đếm được.', 'Họ từ (Word Family): skilled (adj.), skilful (adj.), skilfully (adv.), unskilled (adj.) | Đồng nghĩa: ability, expertise', '[{"hanzi":"Baking good bread takes patience and a little skill.","pinyin":"","meaning":"Làm ra những mẻ bánh mì ngon đòi hỏi sự kiên nhẫn và một chút kỹ năng."},{"hanzi":"Schools should teach practical skills that help young people manage money and communicate effectively.","pinyin":"","meaning":"Các nhà trường nên giảng dạy những kỹ năng thực tế giúp người trẻ tuổi quản lý tài chính và giao tiếp hiệu quả."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_18_2', 'en-a2-18', 'Cách dùng “director” (n.) — giám đốc; thành viên hội đồng quản trị; người quản lý', 'managing director  ·  board of directors  ·  film director', 'Có thể dùng để chỉ giám đốc hoặc thành viên hội đồng quản trị của tổ chức, cũng như đạo diễn phim hoặc kịch.', 'Họ từ (Word Family): direct (v.), direction (n.), directorial (adj.)', '[{"hanzi":"Our director welcomed the new staff at breakfast.","pinyin":"","meaning":"Giám đốc của chúng tôi đã chào đón các nhân viên mới trong bữa sáng."},{"hanzi":"A museum director must balance the need to attract visitors with the responsibility to preserve valuable collections.","pinyin":"","meaning":"Giám đốc bảo tàng phải cân bằng giữa nhu cầu thu hút khách tham quan và trách nhiệm bảo tồn các bộ sưu tập có giá trị."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_18_3', 'en-a2-18', 'Cách dùng “career” (n.) — sự nghiệp, quá trình làm việc của một người thường trong một ngành nghề cụ thể', 'career prospects  ·  career development  ·  pursue a career', 'Từ career nhấn mạnh quá trình phát triển nghề nghiệp lâu dài, trong khi job chỉ công việc cụ thể trước mắt.', 'Họ từ (Word Family): careerist (n.)', '[{"hanzi":"My sister hopes to build a career in nursing.","pinyin":"","meaning":"Chị tôi hy vọng sẽ gây dựng sự nghiệp trong ngành điều dưỡng."},{"hanzi":"Access to affordable training enables adults to change career and adapt to a rapidly evolving labour market.","pinyin":"","meaning":"Việc tiếp cận các khóa đào tạo vừa túi tiền giúp người trưởng thành có thể chuyển đổi nghề nghiệp và thích ứng với thị trường lao động đang phát triển nhanh chóng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_18_4', 'en-a2-18', 'Cách dùng “boss” (n.) — sếp; thủ trưởng; ông chủ', 'talk to your boss  ·  a supportive boss  ·  be your own boss', 'Từ "boss" mang tính khẩu ngữ; khi dùng làm động từ, cụm thông dụng nhất là "boss someone around".', 'Họ từ (Word Family): bossy (adj.), bossiness (n.) | Đồng nghĩa: manager, supervisor', '[{"hanzi":"My boss let me leave early for my appointment.","pinyin":"","meaning":"Sếp của tôi đã cho phép tôi về sớm để đi hẹn gặp."},{"hanzi":"A supportive boss can improve employee satisfaction by offering constructive feedback and recognising individual contributions.","pinyin":"","meaning":"Một người sếp tâm lý có thể nâng cao sự hài lòng của nhân viên bằng cách đưa ra những góp ý mang tính xây dựng và ghi nhận sự đóng góp của cá nhân."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_18_1', 'en-a2-18', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_18_1_1', 'ten_a2_18_1', 'succeed', 'After several attempts, I succeeded in fixing the lamp.', 'After several attempts, I succeeded in fixing the lamp.', '/səkˈsiːd/', 'Sau vài lần thử, tôi cuối cùng đã sửa được chiếc đèn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_18_1_2', 'ten_a2_18_1', 'boss', 'My boss let me leave early for my appointment.', 'My boss let me leave early for my appointment.', '/bɔːs/', 'Sếp của tôi đã cho phép tôi về sớm để đi hẹn gặp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_18_1_3', 'ten_a2_18_1', 'training', 'My first day of training involved helping customers.', 'My first day of training involved helping customers.', '/ˈtreɪnɪŋ/', 'Ngày đào tạo đầu tiên của tôi bao gồm việc hỗ trợ khách hàng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_18_1_4', 'ten_a2_18_1', 'organize', 'Our neighbours organized a picnic by the river.', 'Our neighbours organized a picnic by the river.', '/ˈɔːrɡənaɪz/', 'Hàng xóm của chúng tôi đã tổ chức một buổi dã ngoại bên bờ sông.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_18_1_5', 'ten_a2_18_1', 'organise', 'We organise a picnic for our neighbours every summer.', 'We organise a picnic for our neighbours every summer.', '/ˈɔːrɡənaɪz/', 'Chúng tôi tổ chức một buổi dã ngoại cho hàng xóm vào mỗi mùa hè.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_18_1_6', 'ten_a2_18_1', 'manager', 'The manager helped a new employee arrange the shelves.', 'The manager helped a new employee arrange the shelves.', '/ˈmænɪdʒɚ/', 'Người quản lý đã giúp một nhân viên mới sắp xếp các kệ hàng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_18_1_7', 'ten_a2_18_1', 'photocopier', 'The office photocopier has run out of paper again.', 'The office photocopier has run out of paper again.', '/ˈfoʊtoʊkɑːpiər/', 'Máy photocopy của văn phòng lại hết giấy rồi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_18_1_8', 'ten_a2_18_1', 'part-time', 'My sister has a part-time job at a bakery.', 'My sister has a part-time job at a bakery.', '/ˌpɑːrt ˈtaɪm/', 'Chị gái tôi làm việc bán thời gian tại một cửa hàng bánh mì.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_18_1_1', 'en-a2-18', 'ten_a2_18_1', 'listening', 'listening', 'After several attempts, I succeeded in fixing the lamp.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Sếp của tôi đã cho phép tôi về sớm để đi hẹn gặp.","Sau vài lần thử, tôi cuối cùng đã sửa được chiếc đèn.","Vui lòng lưu tài liệu trước khi bạn đóng máy tính xách tay.","Chúng tôi tổ chức một buổi dã ngoại cho hàng xóm vào mỗi mùa hè."]'::jsonb, 1, 'After several attempts, I succeeded in fixing the lamp. → Sau vài lần thử, tôi cuối cùng đã sửa được chiếc đèn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_18_1_2', 'en-a2-18', 'ten_a2_18_1', 'listening', 'listening', 'My boss let me leave early for my appointment.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thợ cắt tóc đã tỉa lại mái tóc cho tôi trước lễ cưới.","Chúng tôi tổ chức một buổi dã ngoại cho hàng xóm vào mỗi mùa hè.","Sếp của tôi đã cho phép tôi về sớm để đi hẹn gặp.","Máy photocopy của văn phòng lại hết giấy rồi."]'::jsonb, 2, 'My boss let me leave early for my appointment. → Sếp của tôi đã cho phép tôi về sớm để đi hẹn gặp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_18_1_3', 'en-a2-18', 'ten_a2_18_1', 'listening', 'listening', 'My first day of training involved helping customers.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Máy photocopy của văn phòng lại hết giấy rồi.","Ngày đào tạo đầu tiên của tôi bao gồm việc hỗ trợ khách hàng.","Một doanh nhân địa phương vừa mở một tiệm bánh gần trường chúng tôi.","Thợ cắt tóc đã tỉa lại mái tóc cho tôi trước lễ cưới."]'::jsonb, 1, 'My first day of training involved helping customers. → Ngày đào tạo đầu tiên của tôi bao gồm việc hỗ trợ khách hàng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_18_2', 'en-a2-18', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_18_2_1', 'ten_a2_18_2', 'succeed', 'Students are more likely to succeed when schools provide consistent feedback and practical support.', 'Students are more likely to succeed when schools provide consistent feedback and practical support.', '/səkˈsiːd/', 'Học sinh có nhiều khả năng thành công hơn khi nhà trường cung cấp phản hồi liên tục và hỗ trợ thiết thực.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_18_2_2', 'ten_a2_18_2', 'boss', 'A supportive boss can improve employee satisfaction by offering constructive feedback and recognising individual contributions.', 'A supportive boss can improve employee satisfaction by offering constructive feedback and recognising individual contributions.', '/bɔːs/', 'Một người sếp tâm lý có thể nâng cao sự hài lòng của nhân viên bằng cách đưa ra những góp ý mang tính xây dựng và ghi nhận sự đóng góp của cá nhân.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_18_2_3', 'ten_a2_18_2', 'training', 'Regular professional training helps employees adapt to technological changes and improves their long-term career prospects.', 'Regular professional training helps employees adapt to technological changes and improves their long-term career prospects.', '/ˈtreɪnɪŋ/', 'Việc đào tạo chuyên môn thường xuyên giúp nhân viên thích ứng với những thay đổi về công nghệ và cải thiện triển vọng nghề nghiệp lâu dài của họ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_18_2_4', 'ten_a2_18_2', 'organize', 'Schools should organize practical workshops that help students develop communication skills and prepare for employment.', 'Schools should organize practical workshops that help students develop communication skills and prepare for employment.', '/ˈɔːrɡənaɪz/', 'Các trường học nên tổ chức các buổi hội thảo thực tế giúp học sinh phát triển kỹ năng giao tiếp và chuẩn bị cho việc làm.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_18_2_5', 'ten_a2_18_2', 'organise', 'Local councils can organise community workshops to teach residents practical ways to reduce household waste.', 'Local councils can organise community workshops to teach residents practical ways to reduce household waste.', '/ˈɔːrɡənaɪz/', 'Hội đồng địa phương có thể tổ chức các buổi workshop cộng đồng để hướng dẫn cư dân những cách thiết thực nhằm giảm thiểu rác thải sinh hoạt.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_18_2_6', 'ten_a2_18_2', 'manager', 'An effective manager encourages open communication and ensures that employees have sufficient resources to complete their tasks.', 'An effective manager encourages open communication and ensures that employees have sufficient resources to complete their tasks.', '/ˈmænɪdʒɚ/', 'Một nhà quản lý hiệu quả sẽ khuyến khích giao tiếp cởi mở và đảm bảo nhân viên có đủ nguồn lực để hoàn thành nhiệm vụ của họ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
