INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_18_2_2', 'en-a2-18', 'ten_a2_18_2', 'listening', 'listening', 'A supportive boss can improve employee satisfaction by offering constructive feedback and recognising individual contributions.', NULL, 'Trong câu vừa nghe, từ “boss” mang nghĩa nào sau đây?', '["sếp; thủ trưởng; ông chủ","chuyến tham quan; cuộc đi vòng quanh","son môi","họa sĩ"]'::jsonb, 0, '“boss” (/bɔːs/): sếp; thủ trưởng; ông chủ. Câu đầy đủ: A supportive boss can improve employee satisfaction by offering constructive feedback and recognising individual contributions.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
