INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_18_2', 'en-a2-18', NULL, 'comprehensive_test', 'listening', 'My boss let me leave early for my appointment.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Giám đốc của chúng tôi đã chào đón các nhân viên mới trong bữa sáng.","Sau vài lần thử, tôi cuối cùng đã sửa được chiếc đèn.","Sếp của tôi đã cho phép tôi về sớm để đi hẹn gặp.","Chúng tôi tổ chức một buổi dã ngoại cho hàng xóm vào mỗi mùa hè."]'::jsonb, 2, 'My boss let me leave early for my appointment. → Sếp của tôi đã cho phép tôi về sớm để đi hẹn gặp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
