INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_18_4', 'en-a2-18', NULL, 'comprehensive_test', 'listening', 'Our neighbours organized a picnic by the river.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người lính cứu hỏa đã chỉ cho chúng tôi cách sử dụng vòi phun nước.","Giám đốc của chúng tôi đã chào đón các nhân viên mới trong bữa sáng.","Lần đầu tiên chúng tôi thử nướng bánh mì lại thành công một cách bất ngờ.","Hàng xóm của chúng tôi đã tổ chức một buổi dã ngoại bên bờ sông."]'::jsonb, 3, 'Our neighbours organized a picnic by the river. → Hàng xóm của chúng tôi đã tổ chức một buổi dã ngoại bên bờ sông.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_18_5', 'en-a2-18', NULL, 'comprehensive_test', 'listening', 'organise', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tổ chức; chuẩn bị sự kiện hoặc hoạt động","thiết kế; phác thảo","lò; bếp nấu; lò sưởi","doanh nhân; nhà kinh doanh nam"]'::jsonb, 0, 'organise (/ˈɔːrɡənaɪz/) → tổ chức; chuẩn bị sự kiện hoặc hoạt động; sắp xếp; phân loại đồ đạc ngăn nắp, khoa học', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_18_6', 'en-a2-18', NULL, 'comprehensive_test', 'listening', 'The manager helped a new employee arrange the shelves.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Vui lòng lưu tài liệu trước khi bạn đóng máy tính xách tay.","Người quản lý đã giúp một nhân viên mới sắp xếp các kệ hàng.","Máy photocopy của văn phòng lại hết giấy rồi.","Sếp của tôi đã cho phép tôi về sớm để đi hẹn gặp."]'::jsonb, 1, 'The manager helped a new employee arrange the shelves. → Người quản lý đã giúp một nhân viên mới sắp xếp các kệ hàng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
