INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_18_18', 'en-a2-18', NULL, 'comprehensive_test', 'reading', NULL, 'Students are more likely to succeed when schools provide consistent feedback and practical support.', 'Dựa vào câu trên, từ “succeed” có nghĩa phù hợp nhất là gì?', '["vật lý học","thành công; đạt được mục tiêu","viên thuốc; thuốc viên","bữa ăn nhẹ; đồ ăn vặt"]'::jsonb, 1, 'succeed: thành công; đạt được mục tiêu; kế nhiệm; thay thế vị trí của ai đó. Dịch cả câu: Học sinh có nhiều khả năng thành công hơn khi nhà trường cung cấp phản hồi liên tục và hỗ trợ thiết thực.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_18_19', 'en-a2-18', NULL, 'comprehensive_test', 'reading', NULL, 'A supportive boss can improve employee satisfaction by offering constructive feedback and recognising individual contributions.', 'Dựa vào câu trên, từ “boss” có nghĩa phù hợp nhất là gì?', '["cải thiện; nâng cao; tiến bộ","dùng với I hoặc we để đề nghị hoặc gợi ý điều gì đó","đẹp đẽ; dễ thương; xinh xắn","sếp; thủ trưởng; ông chủ"]'::jsonb, 3, 'boss: sếp; thủ trưởng; ông chủ; sai bảo; ra lệnh. Dịch cả câu: Một người sếp tâm lý có thể nâng cao sự hài lòng của nhân viên bằng cách đưa ra những góp ý mang tính xây dựng và ghi nhận sự đóng góp của cá nhân.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_18_20', 'en-a2-18', NULL, 'comprehensive_test', 'reading', NULL, 'Regular professional training helps employees adapt to technological changes and improves their long-term career prospects.', 'Dựa vào câu trên, từ “training” có nghĩa phù hợp nhất là gì?', '["ném; quăng; tung","ý kiến; quan điểm; đánh giá","bình thường; thông thường; không có gì đặc biệt","sự đào tạo; quá trình huấn luyện"]'::jsonb, 3, 'training: sự đào tạo; quá trình huấn luyện; thể lực; rèn luyện thể thao. Dịch cả câu: Việc đào tạo chuyên môn thường xuyên giúp nhân viên thích ứng với những thay đổi về công nghệ và cải thiện triển vọng nghề nghiệp lâu dài của họ.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_18_21', 'en-a2-18', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should organize practical workshops that help students develop communication skills and prepare for employment.', 'Dựa vào câu trên, từ “organize” có nghĩa phù hợp nhất là gì?', '["tổ chức; chuẩn bị","quả dưa chuột; trái dưa leo","tưởng tượng; hình dung","nhạc pop; nhạc trẻ thịnh hành"]'::jsonb, 0, 'organize: tổ chức; chuẩn bị; sắp xếp; phân loại. Dịch cả câu: Các trường học nên tổ chức các buổi hội thảo thực tế giúp học sinh phát triển kỹ năng giao tiếp và chuẩn bị cho việc làm.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_18_22', 'en-a2-18', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thợ hớt tóc nam; thợ cắt tóc”', '["square","poster","noisy","barber"]'::jsonb, 3, 'thợ hớt tóc nam; thợ cắt tóc → barber (/ˈbɑːrbɚ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_18_23', 'en-a2-18', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tiền lương; lương tháng/lương năm”', '["reply","professor","salary","peace"]'::jsonb, 2, 'tiền lương; lương tháng/lương năm → salary (/ˈsæləri/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_18_24', 'en-a2-18', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tài liệu; văn bản; hồ sơ điện tử”', '["nature","dead","document","ending"]'::jsonb, 2, 'tài liệu; văn bản; hồ sơ điện tử → document (/ˈdɑːkjumənt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-19', 'en', 'Bài 19: Công việc & Nghề nghiệp (2) - CEFR A2', 'CEFR A2', 'A2 · Công việc', '24 từ vựng Tiếng Anh CEFR A2 chủ đề công việc & nghề nghiệp kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2019, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_success', 'en-a2-19', 'success', '/səkˈses/', 'A2', 'sự thành công; thành tựu; người thành công; sự việc thành công', 'n.', 'succeed (v.), successful (adj.), successfully (adv.)', 'Đồng nghĩa: achievement · Trái nghĩa: failure', 'Khi chỉ chung chung sự thành công thì là danh từ không đếm được; cụm a success dùng để chỉ một người hoặc sự việc thành công.', 'The school concert was a success despite the rain.', NULL, 'Buổi hòa nhạc của trường đã thành công tốt đẹp mặc dù trời mưa.', '{"wordId":"success","ukIpa":"/səkˈses/","usIpa":"/səkˈses/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"the achievement of an aim or a desired result","vi":"sự thành công; thành tựu"},{"pos":"n.","en":"a person or thing that achieves a good result","vi":"người thành công; sự việc thành công"}],"examples":[{"en":"The school concert was a success despite the rain.","vi":"Buổi hòa nhạc của trường đã thành công tốt đẹp mặc dù trời mưa.","audioKind":"ex"},{"en":"Long-term success in education depends not only on funding but also on the quality of teaching.","vi":"Sự thành công lâu dài trong giáo dục không chỉ phụ thuộc vào nguồn vốn tài chính mà còn phụ thuộc vào chất lượng giảng dạy.","audioKind":"ex2"}],"collocations":[{"en":"achieve success","vi":"đạt được thành công"},{"en":"a great success","vi":"một thành công lớn"},{"en":"the key to success","vi":"chìa khóa của sự thành công"},{"en":"success rate","vi":"tỷ lệ thành công"}],"wordFamily":["succeed (v.)","successful (adj.)","successfully (adv.)"],"synonyms":["achievement"],"antonyms":["failure"],"tipVi":"Khi chỉ chung chung sự thành công thì là danh từ không đếm được; cụm a success dùng để chỉ một người hoặc sự việc thành công.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gardener', 'en-a2-19', 'gardener', '/ˈɡɑːrdənər/', 'A2', 'thợ làm vườn; người làm vườn', 'n.', 'garden (n.), garden (v.), gardening (n.)', NULL, 'Có thể chỉ thợ làm vườn chuyên nghiệp hoặc người thích làm vườn ở nhà.', 'The gardener planted bright flowers along our front path.', NULL, 'Người làm vườn đã trồng những bông hoa rực rỡ dọc theo lối đi trước nhà chúng tôi.', '{"wordId":"gardener","ukIpa":"/ˈɡɑːdənə/","usIpa":"/ˈɡɑːrdənər/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"someone who grows and cares for plants in a garden","vi":"thợ làm vườn; người làm vườn"}],"examples":[{"en":"The gardener planted bright flowers along our front path.","vi":"Người làm vườn đã trồng những bông hoa rực rỡ dọc theo lối đi trước nhà chúng tôi.","audioKind":"ex"},{"en":"Community gardeners can improve urban biodiversity by growing native plants that provide food and shelter for wildlife.","vi":"Những người làm vườn cộng đồng có thể cải thiện đa dạng sinh học đô thị bằng cách trồng các loài cây bản địa cung cấp thức ăn và nơi trú ẩn cho động vật hoang dã.","audioKind":"ex2"}],"collocations":[{"en":"a professional gardener","vi":"thợ làm vườn chuyên nghiệp"},{"en":"a keen gardener","vi":"người rất thích làm vườn"},{"en":"an experienced gardener","vi":"thợ làm vườn có kinh nghiệm"}],"wordFamily":["garden (n.)","garden (v.)","gardening (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ thợ làm vườn chuyên nghiệp hoặc người thích làm vườn ở nhà.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cleaner', 'en-a2-19', 'cleaner', '/ˈkliːnər/', 'A2', 'nhân viên dọn dẹp; người làm vệ sinh; chất tẩy rửa; thiết bị làm sạch; sạch sẽ hơn; ít gây ô nhiễm hơn', 'n.', 'clean (v.), cleaning (n.), cleanliness (n.)', NULL, 'a cleaner thường chỉ người làm vệ sinh; cleaner cũng là dạng so sánh hơn của tính từ clean.', 'The cleaner emptied the bins before the office opened.', NULL, 'Nhân viên vệ sinh đã đổ sạch các thùng rác trước khi văn phòng mở cửa.', '{"wordId":"cleaner","ukIpa":"/ˈkliːnə/","usIpa":"/ˈkliːnər/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"a person paid to clean buildings or rooms","vi":"nhân viên dọn dẹp; người làm vệ sinh"},{"pos":"n.","en":"a substance or device used to remove dirt","vi":"chất tẩy rửa; thiết bị làm sạch"},{"pos":"adj.","en":"having less dirt or causing less pollution","vi":"sạch sẽ hơn; ít gây ô nhiễm hơn"}],"examples":[{"en":"The cleaner emptied the bins before the office opened.","vi":"Nhân viên vệ sinh đã đổ sạch các thùng rác trước khi văn phòng mở cửa.","audioKind":"ex"},{"en":"Hospitals should provide every cleaner with suitable protective equipment and training to reduce infection risks.","vi":"Bệnh viện nên cung cấp cho mọi nhân viên vệ sinh thiết bị bảo hộ và đào tạo phù hợp để giảm thiểu rủi ro lây nhiễm.","audioKind":"ex2"}],"collocations":[{"en":"office cleaner","vi":"nhân viên dọn dẹp văn phòng"},{"en":"window cleaner","vi":"thợ lau cửa sổ; dung dịch lau kính"},{"en":"vacuum cleaner","vi":"máy hút bụi"},{"en":"household cleaner","vi":"chất tẩy rửa gia dụng"}],"wordFamily":["clean (v.)","cleaning (n.)","cleanliness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"a cleaner thường chỉ người làm vệ sinh; cleaner cũng là dạng so sánh hơn của tính từ clean.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_factory', 'en-a2-19', 'factory', '/ˈfæktəri/', 'A2', 'nhà máy; xưởng', 'n.', NULL, NULL, 'Số nhiều là factories; chỉ nơi sản xuất ra các sản phẩm.', 'My aunt works at a factory that makes bicycles.', NULL, 'Dì của tôi làm việc tại một nhà máy sản xuất xe đạp.', '{"wordId":"factory","ukIpa":"/ˈfæktəri/","usIpa":"/ˈfæktəri/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A building or group of buildings where goods are manufactured.","vi":"nhà máy; xưởng"}],"examples":[{"en":"My aunt works at a factory that makes bicycles.","vi":"Dì của tôi làm việc tại một nhà máy sản xuất xe đạp.","audioKind":"ex"},{"en":"Governments should require factory owners to reduce harmful emissions without compromising the safety and livelihoods of their workers.","vi":"Chính phủ nên yêu cầu các chủ nhà máy giảm thiểu lượng khí thải độc hại mà không làm tổn hại đến sự an toàn và sinh kế của công nhân.","audioKind":"ex2"}],"collocations":[{"en":"factory worker","vi":"công nhân nhà máy"},{"en":"factory owner","vi":"chủ nhà máy"},{"en":"factory production","vi":"sản xuất tại nhà máy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Số nhiều là factories; chỉ nơi sản xuất ra các sản phẩm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_postman', 'en-a2-19', 'postman', '/ˈpoʊstmən/', 'A2', 'nam nhân viên bưu điện (người làm nghề phát thư từ và bưu phẩm)', 'n.', 'post (n.), postal (adj.), postwoman (n.)', 'Đồng nghĩa: mailman, mail carrier', 'Từ thường dùng trong tiếng Anh-Anh; tiếng Anh-Mỹ dùng mail carrier và không giới hạn giới tính.', 'The postman left a parcel beside our front door.', NULL, 'Người đưa thư đã để một bưu phẩm cạnh cửa trước nhà chúng tôi.', '{"wordId":"postman","ukIpa":"/ˈpəʊstmən/","usIpa":"/ˈpoʊstmən/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"a man whose job is to deliver letters and parcels","vi":"nam nhân viên bưu điện (người làm nghề phát thư từ và bưu phẩm)"}],"examples":[{"en":"The postman left a parcel beside our front door.","vi":"Người đưa thư đã để một bưu phẩm cạnh cửa trước nhà chúng tôi.","audioKind":"ex"},{"en":"In remote villages, a postman may provide an essential link between residents and public services.","vi":"Ở các ngôi làng hẻo lánh, nhân viên bưu điện có thể đóng vai trò là cầu nối thiết yếu giữa cư dân và các dịch vụ công.","audioKind":"ex2"}],"collocations":[{"en":"the local postman","vi":"nhân viên bưu điện địa phương"},{"en":"work as a postman","vi":"làm nghề đưa thư"},{"en":"the postman''s round","vi":"tuyến đường đưa thư của nhân viên bưu điện"}],"wordFamily":["post (n.)","postal (adj.)","postwoman (n.)"],"synonyms":["mailman","mail carrier"],"antonyms":[],"tipVi":"Từ thường dùng trong tiếng Anh-Anh; tiếng Anh-Mỹ dùng mail carrier và không giới hạn giới tính.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_task', 'en-a2-19', 'task', '/tæsk/', 'A2', 'nhiệm vụ; công việc cần phải làm; giao nhiệm vụ; phân công công việc cụ thể cho ai đó', 'n.', NULL, 'Đồng nghĩa: assignment, job', 'Khi dùng làm động từ, cấu trúc task sb with doing sth dùng để chỉ việc phân công nhiệm vụ.', 'My first task today is to water the plants.', NULL, 'Nhiệm vụ đầu tiên của tôi hôm nay là tưới cây.', '{"wordId":"task","ukIpa":"/tɑːsk/","usIpa":"/tæsk/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A piece of work that needs to be done.","vi":"nhiệm vụ; công việc cần phải làm"},{"pos":"v.","en":"Give someone responsibility for a particular piece of work.","vi":"giao nhiệm vụ; phân công công việc cụ thể cho ai đó"}],"examples":[{"en":"My first task today is to water the plants.","vi":"Nhiệm vụ đầu tiên của tôi hôm nay là tưới cây.","audioKind":"ex"},{"en":"Dividing a complex task into smaller stages can help students manage their time more effectively.","vi":"Chia một nhiệm vụ phức tạp thành các giai đoạn nhỏ hơn có thể giúp học sinh quản lý thời gian hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"complete a task","vi":"hoàn thành nhiệm vụ"},{"en":"a challenging task","vi":"một nhiệm vụ đầy thử thách"},{"en":"task someone with doing something","vi":"giao cho ai đó nhiệm vụ làm gì"}],"wordFamily":[],"synonyms":["assignment","job"],"antonyms":[],"tipVi":"Khi dùng làm động từ, cấu trúc task sb with doing sth dùng để chỉ việc phân công nhiệm vụ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_uniform', 'en-a2-19', 'uniform', '/ˈjuːnɪfɔːrm/', 'A2', 'đồng phục; đồng nhất; đều đặn', 'n.', 'uniformity (n.), uniformly (adv.)', NULL, 'Vì bắt đầu bằng âm phụ âm /j/, ta dùng ''a uniform'' thay vì ''an''.', 'My school uniform is still drying by the window.', NULL, 'Bộ đồng phục học sinh của tôi vẫn đang phơi bên cửa sổ.', '{"wordId":"uniform","ukIpa":"/ˈjuːnɪfɔːm/","usIpa":"/ˈjuːnɪfɔːrm/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"Special clothing worn by members of a particular group.","vi":"đồng phục"},{"pos":"adj.","en":"Remaining the same in form, quality, or amount.","vi":"đồng nhất; đều đặn"}],"examples":[{"en":"My school uniform is still drying by the window.","vi":"Bộ đồng phục học sinh của tôi vẫn đang phơi bên cửa sổ.","audioKind":"ex"},{"en":"Uniform safety standards across all factories can help protect workers and improve overall working conditions.","vi":"Tiêu chuẩn an toàn đồng nhất ở tất cả các nhà máy có thể giúp bảo vệ người lao động và cải thiện điều kiện làm việc chung.","audioKind":"ex2"}],"collocations":[{"en":"school uniform","vi":"đồng phục học sinh"},{"en":"wear a uniform","vi":"mặc đồng phục"},{"en":"uniform standards","vi":"tiêu chuẩn thống nhất"},{"en":"uniform distribution","vi":"sự phân bố đều"}],"wordFamily":["uniformity (n.)","uniformly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Vì bắt đầu bằng âm phụ âm /j/, ta dùng ''a uniform'' thay vì ''an''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_engineer', 'en-a2-19', 'engineer', '/ˌendʒɪˈnɪr/', 'A2', 'kỹ sư; thiết kế kỹ thuật; lên kế hoạch dàn xếp', 'n.', 'engineering (n.), engineered (adj.)', NULL, 'engineer cũng có thể đóng vai trò là động từ, biểu thị thiết kế hoặc lên kế hoạch dàn xếp.', 'An engineer checked the bridge before it opened.', NULL, 'Một kỹ sư đã kiểm tra cây cầu trước khi nó được thông xe.', '{"wordId":"engineer","ukIpa":"/ˌendʒɪˈnɪə/","usIpa":"/ˌendʒɪˈnɪr/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"Someone who designs or builds machines, structures, or technical systems.","vi":"kỹ sư"},{"pos":"v.","en":"To design something technical or skilfully arrange an outcome.","vi":"thiết kế kỹ thuật; lên kế hoạch dàn xếp"}],"examples":[{"en":"An engineer checked the bridge before it opened.","vi":"Một kỹ sư đã kiểm tra cây cầu trước khi nó được thông xe.","audioKind":"ex"},{"en":"Engineers can reduce urban energy consumption by designing buildings that require less heating and cooling.","vi":"Các kỹ sư có thể giảm mức tiêu thụ năng lượng đô thị bằng cách thiết kế các tòa nhà đòi hỏi ít năng lượng sưởi ấm và làm mát hơn.","audioKind":"ex2"}],"collocations":[{"en":"civil engineer","vi":"kỹ sư xây dựng"},{"en":"software engineer","vi":"kỹ sư phần mềm"},{"en":"engineer a solution","vi":"lên kế hoạch cho một giải pháp"}],"wordFamily":["engineering (n.)","engineered (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"engineer cũng có thể đóng vai trò là động từ, biểu thị thiết kế hoặc lên kế hoạch dàn xếp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_secretary', 'en-a2-19', 'secretary', '/ˈsekrəteri/', 'A2', 'thư ký; cán sự; bộ trưởng; quốc vụ khanh', 'n.', 'secretarial (adj.), secretariat (n.)', NULL, 'Từ này có thể chỉ thư ký văn phòng, hoặc cũng dùng cho các chức vụ bộ trưởng trong chính phủ.', 'The secretary arranged a meeting for tomorrow afternoon.', NULL, 'Thư ký đã sắp xếp một cuộc họp vào chiều mai.', '{"wordId":"secretary","ukIpa":"/ˈsekrətri/","usIpa":"/ˈsekrəteri/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"Someone who arranges meetings and handles office communication.","vi":"thư ký"},{"pos":"n.","en":"An official managing an organisation''s records and routine business.","vi":"thư ký; cán sự"},{"pos":"n.","en":"A senior government official responsible for a particular department.","vi":"bộ trưởng; quốc vụ khanh"}],"examples":[{"en":"The secretary arranged a meeting for tomorrow afternoon.","vi":"Thư ký đã sắp xếp một cuộc họp vào chiều mai.","audioKind":"ex"},{"en":"A school secretary often provides essential support by coordinating appointments and communicating with parents throughout the day.","vi":"Thư ký nhà trường thường cung cấp sự hỗ trợ thiết yếu bằng cách điều phối các cuộc hẹn và liên lạc với phụ huynh suốt cả ngày.","audioKind":"ex2"}],"collocations":[{"en":"personal secretary","vi":"thư ký riêng"},{"en":"club secretary","vi":"thư ký câu lạc bộ"},{"en":"foreign secretary","vi":"bộ trưởng ngoại giao"}],"wordFamily":["secretarial (adj.)","secretariat (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ này có thể chỉ thư ký văn phòng, hoặc cũng dùng cho các chức vụ bộ trưởng trong chính phủ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_project', 'en-a2-19', 'project', '/ˈprɑːdʒekt/; /prəˈdʒekt/', 'A2', 'dự án; công trình; đề tài nghiên cứu; dự báo; ước tính; chiếu; phóng (ánh sáng, hình ảnh lên bề mặt)', 'n.', 'projection (n.), projector (n.), projected (adj.)', NULL, 'Danh từ nhấn trọng âm ở âm tiết đầu, động từ nhấn trọng âm ở âm tiết sau; phiên bản phát âm tuân theo quy tắc này.', 'Our garden project started with three pots of herbs.', NULL, 'Dự án vườn tược của chúng tôi bắt đầu từ ba chậu thảo mộc.', '{"wordId":"project","ukIpa":"/ˈprɒdʒekt/; /prəˈdʒekt/","usIpa":"/ˈprɑːdʒekt/; /prəˈdʒekt/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A planned piece of work with a particular purpose.","vi":"dự án; công trình; đề tài nghiên cứu"},{"pos":"v.","en":"To estimate a future amount or situation using current information.","vi":"dự báo; ước tính"},{"pos":"v.","en":"To send light or images onto a surface.","vi":"chiếu; phóng (ánh sáng, hình ảnh lên bề mặt)"}],"examples":[{"en":"Our garden project started with three pots of herbs.","vi":"Dự án vườn tược của chúng tôi bắt đầu từ ba chậu thảo mộc.","audioKind":"ex"},{"en":"Researchers project that demand for electricity will increase as more households switch to electric vehicles.","vi":"Các nhà nghiên cứu dự báo rằng nhu cầu điện năng sẽ tăng lên khi ngày càng có nhiều hộ gia đình chuyển sang sử dụng xe điện.","audioKind":"ex2"}],"collocations":[{"en":"a research project","vi":"một dự án nghiên cứu"},{"en":"carry out a project","vi":"thực hiện một dự án"},{"en":"be projected to rise","vi":"dự kiến tăng"},{"en":"project an image","vi":"chiếu hình ảnh"}],"wordFamily":["projection (n.)","projector (n.)","projected (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ nhấn trọng âm ở âm tiết đầu, động từ nhấn trọng âm ở âm tiết sau; phiên bản phát âm tuân theo quy tắc này.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_colleague', 'en-a2-19', 'colleague', '/ˈkɑːliːɡ/', 'A2', 'đồng nghiệp; bạn đồng sự', 'n.', NULL, 'Đồng nghĩa: coworker', 'colleague chỉ đồng nghiệp, không nhất thiết phải là bạn bè hoặc nhân viên cùng cấp.', 'My colleague brought homemade soup to the office today.', NULL, 'Đồng nghiệp của tôi đã mang súp tự nấu đến văn phòng ngày hôm nay.', '{"wordId":"colleague","ukIpa":"/ˈkɒliːɡ/","usIpa":"/ˈkɑːliːɡ/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"Someone you work with, especially in a professional job.","vi":"đồng nghiệp; bạn đồng sự"}],"examples":[{"en":"My colleague brought homemade soup to the office today.","vi":"Đồng nghiệp của tôi đã mang súp tự nấu đến văn phòng ngày hôm nay.","audioKind":"ex"},{"en":"Sharing knowledge with colleagues can improve workplace efficiency and help new employees develop essential skills.","vi":"Việc chia sẻ kiến thức với các đồng nghiệp có thể nâng cao hiệu quả nơi làm việc và giúp nhân viên mới phát triển các kỹ năng thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"work colleague","vi":"đồng nghiệp làm việc"},{"en":"former colleague","vi":"đồng nghiệp cũ"},{"en":"a close colleague","vi":"một người đồng nghiệp thân thiết"}],"wordFamily":[],"synonyms":["coworker"],"antonyms":[],"tipVi":"colleague chỉ đồng nghiệp, không nhất thiết phải là bạn bè hoặc nhân viên cùng cấp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_earn', 'en-a2-19', 'earn', '/ɜːrn/', 'A2', 'kiếm được; kiếm tiền; giành được; xứng đáng nhận được', 'v.', 'earner (n.), earnings (n.), earned (adj.)', NULL, 'earn nhấn mạnh thành quả có được nhờ công sức lao động hoặc biểu hiện xứng đáng; win thường chỉ việc chiến thắng trong một cuộc thi.', 'She earns extra money by walking dogs after school.', NULL, 'Cô ấy kiếm thêm tiền bằng cách dắt chó đi dạo sau giờ học.', '{"wordId":"earn","ukIpa":"/ɜːn/","usIpa":"/ɜːrn/","cefr":"A2","topic":"work","senses":[{"pos":"v.","en":"To receive money in return for work.","vi":"kiếm được; kiếm tiền"},{"pos":"v.","en":"To gain something deserved through your actions or qualities.","vi":"giành được; xứng đáng nhận được"}],"examples":[{"en":"She earns extra money by walking dogs after school.","vi":"Cô ấy kiếm thêm tiền bằng cách dắt chó đi dạo sau giờ học.","audioKind":"ex"},{"en":"Companies can earn public trust by reporting their environmental impact honestly and taking responsibility for their mistakes.","vi":"Các doanh nghiệp có thể giành được lòng tin của công chúng bằng cách trung thực báo cáo tác động môi trường của mình và chịu trách nhiệm về những sai sót của họ.","audioKind":"ex2"}],"collocations":[{"en":"earn a living","vi":"kiếm sống"},{"en":"earn money","vi":"kiếm tiền"},{"en":"earn respect","vi":"giành được sự tôn trọng"},{"en":"earn a reputation","vi":"tạo dựng danh tiếng"}],"wordFamily":["earner (n.)","earnings (n.)","earned (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"earn nhấn mạnh thành quả có được nhờ công sức lao động hoặc biểu hiện xứng đáng; win thường chỉ việc chiến thắng trong một cuộc thi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fireman', 'en-a2-19', 'fireman', '/ˈfaɪərmən/', 'A2', 'lính cứu hỏa nam; nam nhân viên cứu hỏa', 'n.', 'firefighter (n.), firefighting (n.)', 'Đồng nghĩa: firefighter', 'Dạng số nhiều là firemen; biểu thức chung hiện đại thường dùng từ trung tính firefighter.', 'The fireman rescued a kitten from the smoky kitchen.', NULL, 'Người lính cứu hỏa đã cứu một chú mèo con khỏi nhà bếp đầy khói.', '{"wordId":"fireman","ukIpa":"/ˈfaɪəmən/","usIpa":"/ˈfaɪərmən/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A man whose job is to put out fires.","vi":"lính cứu hỏa nam; nam nhân viên cứu hỏa"}],"examples":[{"en":"The fireman rescued a kitten from the smoky kitchen.","vi":"Người lính cứu hỏa đã cứu một chú mèo con khỏi nhà bếp đầy khói.","audioKind":"ex"},{"en":"The fireman explained that regular safety inspections could prevent many accidents in residential buildings.","vi":"Nam nhân viên cứu hỏa giải thích rằng việc kiểm tra an toàn thường xuyên có thể ngăn chặn nhiều tai nạn trong các tòa nhà dân cư.","audioKind":"ex2"}],"collocations":[{"en":"a brave fireman","vi":"một người lính cứu hỏa dũng cảm"},{"en":"a fireman''s helmet","vi":"mũ bảo hộ của lính cứu hỏa"},{"en":"a volunteer fireman","vi":"lính cứu hỏa tình nguyện"}],"wordFamily":["firefighter (n.)","firefighting (n.)"],"synonyms":["firefighter"],"antonyms":[],"tipVi":"Dạng số nhiều là firemen; biểu thức chung hiện đại thường dùng từ trung tính firefighter.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_interview', 'en-a2-19', 'interview', '/ˈɪntərvjuː/', 'A2', 'buổi phỏng vấn; cuộc phỏng vấn; buổi phỏng vấn báo chí hoặc nghiên cứu; phỏng vấn; hỏi phỏng vấn', 'n.', 'interviewer (n.), interviewee (n.)', NULL, 'interviewer là người phỏng vấn; interviewee là người được phỏng vấn hoặc trả lời phỏng vấn.', 'I practised answering questions before my first job interview.', NULL, 'Tôi đã tập trả lời các câu hỏi trước buổi phỏng vấn xin việc đầu tiên của mình.', '{"wordId":"interview","ukIpa":"/ˈɪntəvjuː/","usIpa":"/ˈɪntərvjuː/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"a meeting to assess someone''s suitability for a position","vi":"buổi phỏng vấn; cuộc phỏng vấn"},{"pos":"n.","en":"a conversation where someone answers questions for media or research","vi":"cuộc phỏng vấn; buổi phỏng vấn báo chí hoặc nghiên cứu"},{"pos":"v.","en":"to ask someone questions for selection, reporting, or research","vi":"phỏng vấn; hỏi phỏng vấn"}],"examples":[{"en":"I practised answering questions before my first job interview.","vi":"Tôi đã tập trả lời các câu hỏi trước buổi phỏng vấn xin việc đầu tiên của mình.","audioKind":"ex"},{"en":"Researchers should interview residents from diverse backgrounds to understand how housing policies affect different social groups.","vi":"Các nhà nghiên cứu nên phỏng vấn cư dân từ các hoàn cảnh khác nhau để hiểu cách chính sách nhà ở tác động đến các nhóm xã hội khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"job interview","vi":"phỏng vấn xin việc"},{"en":"conduct an interview","vi":"tiến hành một cuộc phỏng vấn"},{"en":"interview candidates","vi":"phỏng vấn các ứng viên"},{"en":"an in-depth interview","vi":"cuộc phỏng vấn sâu"}],"wordFamily":["interviewer (n.)","interviewee (n.)"],"synonyms":[],"antonyms":[],"tipVi":"interviewer là người phỏng vấn; interviewee là người được phỏng vấn hoặc trả lời phỏng vấn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_folder', 'en-a2-19', 'folder', '/ˈfoʊldər/', 'A2', 'bìa hồ sơ; cặp đựng tài liệu; thư mục giấy; thư mục (trên máy tính)', 'n.', 'fold (v.)', NULL, 'file là tệp tin; folder là thư mục chứa các tệp tin.', 'Keep your receipts in this folder beside the desk.', NULL, 'Hãy cất các biên lai của bạn vào tập tài liệu này ở bên cạnh bàn làm việc.', '{"wordId":"folder","ukIpa":"/ˈfəʊldə/","usIpa":"/ˈfoʊldər/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A folded cover used to hold loose papers.","vi":"bìa hồ sơ; cặp đựng tài liệu; thư mục giấy"},{"pos":"n.","en":"A place on a computer where files are grouped together.","vi":"thư mục (trên máy tính)"}],"examples":[{"en":"Keep your receipts in this folder beside the desk.","vi":"Hãy cất các biên lai của bạn vào tập tài liệu này ở bên cạnh bàn làm việc.","audioKind":"ex"},{"en":"Organising digital resources into clearly named folders can help students locate information efficiently during research projects.","vi":"Việc sắp xếp các tài nguyên kỹ thuật số vào các thư mục có tên rõ ràng có thể giúp học sinh tìm kiếm thông tin hiệu quả trong các dự án nghiên cứu.","audioKind":"ex2"}],"collocations":[{"en":"create a folder","vi":"tạo thư mục"},{"en":"a shared folder","vi":"thư mục chia sẻ"},{"en":"save files in a folder","vi":"lưu tệp vào thư mục"}],"wordFamily":["fold (v.)"],"synonyms":[],"antonyms":[],"tipVi":"file là tệp tin; folder là thư mục chứa các tệp tin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_leader', 'en-a2-19', 'leader', '/ˈliːdər/', 'A2', 'nhà lãnh đạo; người dẫn đầu; tổ chức dẫn đầu trong một lĩnh vực', 'n.', 'lead (v.), leadership (n.), leading (adj.)', 'Trái nghĩa: follower', 'leader chỉ người lãnh đạo; leadership chỉ năng lực lãnh đạo hoặc ban lãnh đạo.', 'Our group leader showed us the safest mountain path.', NULL, 'Trưởng nhóm của chúng tôi đã chỉ cho chúng tôi con đường mòn an toàn nhất trên núi.', '{"wordId":"leader","ukIpa":"/ˈliːdə/","usIpa":"/ˈliːdər/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"Someone who guides or directs a group of people.","vi":"nhà lãnh đạo; người dẫn đầu"},{"pos":"n.","en":"A person or organization ahead of others in a field.","vi":"người dẫn đầu; tổ chức dẫn đầu trong một lĩnh vực"}],"examples":[{"en":"Our group leader showed us the safest mountain path.","vi":"Trưởng nhóm của chúng tôi đã chỉ cho chúng tôi con đường mòn an toàn nhất trên núi.","audioKind":"ex"},{"en":"Effective leaders encourage employees to share ideas rather than simply follow instructions without question.","vi":"Những nhà lãnh đạo hiệu quả khuyến khích nhân viên chia sẻ ý tưởng thay vì chỉ tuân thủ mệnh lệnh một cách mù quáng.","audioKind":"ex2"}],"collocations":[{"en":"team leader","vi":"trưởng nhóm"},{"en":"political leader","vi":"lãnh đạo chính trị"},{"en":"market leader","vi":"doanh nghiệp dẫn đầu thị trường"},{"en":"leadership skills","vi":"kỹ năng lãnh đạo"}],"wordFamily":["lead (v.)","leadership (n.)","leading (adj.)"],"synonyms":[],"antonyms":["follower"],"tipVi":"leader chỉ người lãnh đạo; leadership chỉ năng lực lãnh đạo hoặc ban lãnh đạo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hairdresser', 'en-a2-19', 'hairdresser', '/ˈherdresər/', 'A2', 'thợ làm tóc; thợ cắt tóc', 'n.', 'hairdressing (n.)', 'Đồng nghĩa: hairstylist', 'hairdresser chỉ con người; the hairdresser''s thường chỉ tiệm làm tóc.', 'The hairdresser trimmed my hair and dried it gently.', NULL, 'Thợ làm tóc đã cắt tỉa tóc cho tôi và sấy khô nhẹ nhàng.', '{"wordId":"hairdresser","ukIpa":"/ˈheədresə/","usIpa":"/ˈherdresər/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"someone whose job is to cut and style hair","vi":"thợ làm tóc; thợ cắt tóc"}],"examples":[{"en":"The hairdresser trimmed my hair and dried it gently.","vi":"Thợ làm tóc đã cắt tỉa tóc cho tôi và sấy khô nhẹ nhàng.","audioKind":"ex"},{"en":"Training as a hairdresser combines practical skills with customer service, offering a career path outside traditional academic education.","vi":"Đào tạo nghề làm tóc kết hợp giữa kỹ năng thực hành và dịch vụ khách hàng, mở ra một con đường sự nghiệp ngoài giáo dục học thuật truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"qualified hairdresser","vi":"thợ làm tóc có tay nghề"},{"en":"go to the hairdresser''s","vi":"đến tiệm làm tóc"},{"en":"hairdresser''s salon","vi":"tiệm làm tóc"}],"wordFamily":["hairdressing (n.)"],"synonyms":["hairstylist"],"antonyms":[],"tipVi":"hairdresser chỉ con người; the hairdresser''s thường chỉ tiệm làm tóc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_photocopy', 'en-a2-19', 'photocopy', '/ˈfoʊtoʊkɑːpi/', 'A2', 'bản sao chụp; bản photo; sao chụp; photo', 'n.', 'photocopier (n.), photocopying (n.)', 'Đồng nghĩa: copy', 'Từ này vừa là danh từ (n.) vừa là động từ (v.); dạng số nhiều và ngôi thứ ba số ít đều là photocopies.', 'Please bring a photocopy of your passport tomorrow.', NULL, 'Xin vui lòng mang theo một bản sao hộ chiếu của bạn vào ngày mai.', '{"wordId":"photocopy","ukIpa":"/ˈfəʊtəʊkɒpi/","usIpa":"/ˈfoʊtoʊkɑːpi/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A paper copy of a document made using a machine.","vi":"bản sao chụp; bản photo"},{"pos":"v.","en":"To make a paper copy of a document using a machine.","vi":"sao chụp; photo"}],"examples":[{"en":"Please bring a photocopy of your passport tomorrow.","vi":"Xin vui lòng mang theo một bản sao hộ chiếu của bạn vào ngày mai.","audioKind":"ex"},{"en":"Students should keep a photocopy of important application documents in case the originals are lost.","vi":"Học sinh nên giữ lại một bản photo các tài liệu xin học quan trọng để phòng khi mất bản gốc.","audioKind":"ex2"}],"collocations":[{"en":"make a photocopy","vi":"làm bản photo"},{"en":"a photocopy of a document","vi":"bản sao của một tài liệu"},{"en":"photocopy a form","vi":"photo một mẫu đơn"}],"wordFamily":["photocopier (n.)","photocopying (n.)"],"synonyms":["copy"],"antonyms":[],"tipVi":"Từ này vừa là danh từ (n.) vừa là động từ (v.); dạng số nhiều và ngôi thứ ba số ít đều là photocopies.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_employee', 'en-a2-19', 'employee', '/ɪmˈplɔɪiː/', 'A2', 'người lao động; nhân viên; người làm thuê', 'n.', 'employ (v.), employer (n.), employment (n.), unemployed (adj.)', 'Đồng nghĩa: worker · Trái nghĩa: employer', 'employee là nhân viên, employer là người sử dụng lao động.', 'A new employee showed me around the bakery.', NULL, 'Một nhân viên mới đã dẫn tôi đi tham quan tiệm bánh.', '{"wordId":"employee","ukIpa":"/ɪmˈplɔɪiː/","usIpa":"/ɪmˈplɔɪiː/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"Someone paid to work for a person or organisation.","vi":"người lao động; nhân viên; người làm thuê"}],"examples":[{"en":"A new employee showed me around the bakery.","vi":"Một nhân viên mới đã dẫn tôi đi tham quan tiệm bánh.","audioKind":"ex"},{"en":"Employers should provide every employee with appropriate training to maintain a safe and productive workplace.","vi":"Người sử dụng lao động nên cung cấp cho mọi nhân viên sự đào tạo phù hợp để duy trì một môi trường làm việc an toàn và hiệu quả.","audioKind":"ex2"}],"collocations":[{"en":"full-time employee","vi":"nhân viên toàn thời gian"},{"en":"employee benefits","vi":"phúc lợi nhân viên"},{"en":"employee training","vi":"đào tạo nhân viên"},{"en":"employee turnover","vi":"tỷ lệ biến động nhân sự"}],"wordFamily":["employ (v.)","employer (n.)","employment (n.)","unemployed (adj.)"],"synonyms":["worker"],"antonyms":["employer"],"tipVi":"employee là nhân viên, employer là người sử dụng lao động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_milkman', 'en-a2-19', 'milkman', '/ˈmɪlkmən/', 'A2', 'người giao sữa', 'n.', 'milk (n.), milk (v.), milkwoman (n.)', NULL, 'Dạng số nhiều là "milkmen"; từ này không chỉ người vắt sữa, người vắt sữa là "milker".', 'The milkman left two glass bottles outside our door.', NULL, 'Người giao sữa đã để hai chai thủy tinh trước cửa nhà chúng tôi.', '{"wordId":"milkman","ukIpa":"/ˈmɪlkmən/","usIpa":"/ˈmɪlkmən/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A man whose job is delivering milk to homes.","vi":"người giao sữa"}],"examples":[{"en":"The milkman left two glass bottles outside our door.","vi":"Người giao sữa đã để hai chai thủy tinh trước cửa nhà chúng tôi.","audioKind":"ex"},{"en":"Regular deliveries by a local milkman can encourage households to reuse glass bottles rather than discard plastic containers.","vi":"Việc giao sữa định kỳ bởi người giao sữa địa phương có thể khuyến khích các hộ gia đình tái sử dụng chai thủy tinh thay vì vứt bỏ các hộp nhựa.","audioKind":"ex2"}],"collocations":[{"en":"local milkman","vi":"người giao sữa địa phương"},{"en":"the milkman''s round","vi":"tuyến đường giao sữa của người đưa sữa"}],"wordFamily":["milk (n.)","milk (v.)","milkwoman (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là \"milkmen\"; từ này không chỉ người vắt sữa, người vắt sữa là \"milker\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chef', 'en-a2-19', 'chef', '/ʃef/', 'A2', 'đầu bếp chuyên nghiệp; bếp trưởng', 'n.', NULL, 'Đồng nghĩa: cook', 'Chữ ch trong chef phát âm là /ʃ/; thường dùng chỉ đầu bếp chuyên nghiệp làm việc tại nhà hàng hoặc khách sạn.', 'The chef added fresh herbs to the steaming soup.', NULL, 'Đầu bếp đã cho thêm các loại thảo mộc tươi vào nồi súp đang bốc nghi ngút khói.', '{"wordId":"chef","ukIpa":"/ʃef/","usIpa":"/ʃef/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A trained cook working in a restaurant or hotel.","vi":"đầu bếp chuyên nghiệp; bếp trưởng"}],"examples":[{"en":"The chef added fresh herbs to the steaming soup.","vi":"Đầu bếp đã cho thêm các loại thảo mộc tươi vào nồi súp đang bốc nghi ngút khói.","audioKind":"ex"},{"en":"A skilled chef can design nutritious school meals that appeal to children while staying within a limited budget.","vi":"Một đầu bếp lành nghề có thể thiết kế các bữa ăn học đường đầy đủ dinh dưỡng vừa hợp khẩu vị trẻ em vừa nằm trong ngân sách hạn hẹp.","audioKind":"ex2"}],"collocations":[{"en":"head chef","vi":"bếp trưởng"},{"en":"pastry chef","vi":"thợ làm bánh ngọt"},{"en":"train as a chef","vi":"đào tạo để trở thành đầu bếp"}],"wordFamily":[],"synonyms":["cook"],"antonyms":[],"tipVi":"Chữ ch trong chef phát âm là /ʃ/; thường dùng chỉ đầu bếp chuyên nghiệp làm việc tại nhà hàng hoặc khách sạn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_department', 'en-a2-19', 'department', '/dɪˈpɑːrtmənt/', 'A2', 'bộ phận; khoa; ban; quầy hàng (trong cửa hàng lớn)', 'n.', 'departmental (adj.)', 'Đồng nghĩa: division, section', 'Khoa trong trường đại học dùng department; từ faculty hoặc school thường dùng để chỉ toàn bộ học viện hoặc khoa lớn.', 'Please ask our sales department about the delivery date.', NULL, 'Vui lòng liên hệ bộ phận kinh doanh của chúng tôi để biết ngày giao hàng.', '{"wordId":"department","ukIpa":"/dɪˈpɑːtmənt/","usIpa":"/dɪˈpɑːrtmənt/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"a division of an organisation responsible for a particular subject","vi":"bộ phận; khoa; ban"},{"pos":"n.","en":"an area of a shop selling a particular type of product","vi":"quầy hàng (trong cửa hàng lớn)"}],"examples":[{"en":"Please ask our sales department about the delivery date.","vi":"Vui lòng liên hệ bộ phận kinh doanh của chúng tôi để biết ngày giao hàng.","audioKind":"ex"},{"en":"Each university department should review its courses regularly to ensure they reflect developments in the relevant field.","vi":"Mỗi khoa trong trường đại học nên thường xuyên rà soát chương trình giảng dạy để đảm bảo chúng bắt kịp sự phát triển của lĩnh vực chuyên môn.","audioKind":"ex2"}],"collocations":[{"en":"sales department","vi":"phòng kinh doanh"},{"en":"government department","vi":"cơ quan chính phủ"},{"en":"department head","vi":"trưởng phòng"},{"en":"department store","vi":"cửa hàng bách hóa"}],"wordFamily":["departmental (adj.)"],"synonyms":["division","section"],"antonyms":[],"tipVi":"Khoa trong trường đại học dùng department; từ faculty hoặc school thường dùng để chỉ toàn bộ học viện hoặc khoa lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_builder', 'en-a2-19', 'builder', '/ˈbɪldər/', 'A2', 'thợ xây dựng; nhà thầu xây dựng', 'n.', 'build (v.), building (n.), rebuild (v.)', NULL, 'Có thể chỉ thợ xây, cũng có thể chỉ công ty nhận xây dựng nhà cửa.', 'The builder replaced the broken bricks around our doorway.', NULL, 'Thợ xây đã thay thế những viên gạch bị vỡ xung quanh cửa ra vào của chúng tôi.', '{"wordId":"builder","ukIpa":"/ˈbɪldə/","usIpa":"/ˈbɪldər/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"A person or company that constructs or repairs buildings.","vi":"thợ xây dựng; nhà thầu xây dựng"}],"examples":[{"en":"The builder replaced the broken bricks around our doorway.","vi":"Thợ xây đã thay thế những viên gạch bị vỡ xung quanh cửa ra vào của chúng tôi.","audioKind":"ex"},{"en":"Builders can reduce construction waste by choosing durable materials and planning resource use more carefully.","vi":"Các nhà thầu xây dựng có thể giảm thiểu chất thải xây dựng bằng cách chọn vật liệu bền và lên kế hoạch sử dụng tài nguyên cẩn thận hơn.","audioKind":"ex2"}],"collocations":[{"en":"local builder","vi":"thợ xây địa phương"},{"en":"house builder","vi":"nhà thầu xây dựng nhà ở"},{"en":"hire a builder","vi":"thuê thợ xây"}],"wordFamily":["build (v.)","building (n.)","rebuild (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ thợ xây, cũng có thể chỉ công ty nhận xây dựng nhà cửa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_experience', 'en-a2-19', 'experience', '/ɪkˈspɪriəns/', 'A2', 'kinh nghiệm; trải nghiệm; kinh nghiệm sống; trải qua; cảm nhận', 'n.', 'experienced (adj.), inexperienced (adj.), inexperience (n.)', NULL, 'Nghĩa "kinh nghiệm" là danh từ không đếm được; nghĩa "trải nghiệm/sự việc trải qua" là danh từ đếm được.', 'My sister has years of experience repairing old bicycles.', NULL, 'Chị tôi có nhiều năm kinh nghiệm sửa xe đạp cũ.', '{"wordId":"experience","ukIpa":"/ɪkˈspɪəriəns/","usIpa":"/ɪkˈspɪriəns/","cefr":"A2","topic":"work","senses":[{"pos":"n.","en":"knowledge or skill gained by doing things","vi":"kinh nghiệm"},{"pos":"n.","en":"something that happens to you or that you do","vi":"trải nghiệm; kinh nghiệm sống"},{"pos":"v.","en":"to have something happen to you or feel something","vi":"trải qua; cảm nhận"}],"examples":[{"en":"My sister has years of experience repairing old bicycles.","vi":"Chị tôi có nhiều năm kinh nghiệm sửa xe đạp cũ.","audioKind":"ex"},{"en":"Work experience can help graduates develop practical skills that employers value alongside academic qualifications.","vi":"Kinh nghiệm làm việc có thể giúp sinh viên mới tốt nghiệp phát triển các kỹ năng thực tế mà nhà tuyển dụng đánh giá cao bên cạnh bằng cấp học thuật.","audioKind":"ex2"}],"collocations":[{"en":"gain experience","vi":"tích 𠸣 kinh nghiệm"},{"en":"work experience","vi":"kinh nghiệm làm việc"},{"en":"a rewarding experience","vi":"trải nghiệm đáng giá"},{"en":"experience difficulties","vi":"gặp khó khăn"}],"wordFamily":["experienced (adj.)","inexperienced (adj.)","inexperience (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa \"kinh nghiệm\" là danh từ không đếm được; nghĩa \"trải nghiệm/sự việc trải qua\" là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_19_1', 'en-a2-19', 'Cách dùng “earn” (v.) — kiếm được; kiếm tiền', 'earn a living  ·  earn money  ·  earn respect', 'earn nhấn mạnh thành quả có được nhờ công sức lao động hoặc biểu hiện xứng đáng; win thường chỉ việc chiến thắng trong một cuộc thi.', 'Họ từ (Word Family): earner (n.), earnings (n.), earned (adj.)', '[{"hanzi":"She earns extra money by walking dogs after school.","pinyin":"","meaning":"Cô ấy kiếm thêm tiền bằng cách dắt chó đi dạo sau giờ học."},{"hanzi":"Companies can earn public trust by reporting their environmental impact honestly and taking responsibility for their mistakes.","pinyin":"","meaning":"Các doanh nghiệp có thể giành được lòng tin của công chúng bằng cách trung thực báo cáo tác động môi trường của mình và chịu trách nhiệm về những sai sót của họ."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_19_2', 'en-a2-19', 'Cách dùng “success” (n.) — sự thành công; thành tựu', 'achieve success  ·  a great success  ·  the key to success', 'Khi chỉ chung chung sự thành công thì là danh từ không đếm được; cụm a success dùng để chỉ một người hoặc sự việc thành công.', 'Họ từ (Word Family): succeed (v.), successful (adj.), successfully (adv.) | Đồng nghĩa: achievement · Trái nghĩa: failure', '[{"hanzi":"The school concert was a success despite the rain.","pinyin":"","meaning":"Buổi hòa nhạc của trường đã thành công tốt đẹp mặc dù trời mưa."},{"hanzi":"Long-term success in education depends not only on funding but also on the quality of teaching.","pinyin":"","meaning":"Sự thành công lâu dài trong giáo dục không chỉ phụ thuộc vào nguồn vốn tài chính mà còn phụ thuộc vào chất lượng giảng dạy."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_19_3', 'en-a2-19', 'Cách dùng “department” (n.) — bộ phận; khoa; ban', 'sales department  ·  government department  ·  department head', 'Khoa trong trường đại học dùng department; từ faculty hoặc school thường dùng để chỉ toàn bộ học viện hoặc khoa lớn.', 'Họ từ (Word Family): departmental (adj.) | Đồng nghĩa: division, section', '[{"hanzi":"Please ask our sales department about the delivery date.","pinyin":"","meaning":"Vui lòng liên hệ bộ phận kinh doanh của chúng tôi để biết ngày giao hàng."},{"hanzi":"Each university department should review its courses regularly to ensure they reflect developments in the relevant field.","pinyin":"","meaning":"Mỗi khoa trong trường đại học nên thường xuyên rà soát chương trình giảng dạy để đảm bảo chúng bắt kịp sự phát triển của lĩnh vực chuyên môn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_19_4', 'en-a2-19', 'Cách dùng “project” (n.) — dự án; công trình; đề tài nghiên cứu', 'a research project  ·  carry out a project  ·  be projected to rise', 'Danh từ nhấn trọng âm ở âm tiết đầu, động từ nhấn trọng âm ở âm tiết sau; phiên bản phát âm tuân theo quy tắc này.', 'Họ từ (Word Family): projection (n.), projector (n.), projected (adj.)', '[{"hanzi":"Our garden project started with three pots of herbs.","pinyin":"","meaning":"Dự án vườn tược của chúng tôi bắt đầu từ ba chậu thảo mộc."},{"hanzi":"Researchers project that demand for electricity will increase as more households switch to electric vehicles.","pinyin":"","meaning":"Các nhà nghiên cứu dự báo rằng nhu cầu điện năng sẽ tăng lên khi ngày càng có nhiều hộ gia đình chuyển sang sử dụng xe điện."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_19_1', 'en-a2-19', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
