INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_19_1_8', 'ten_a2_19_1', 'engineer', 'An engineer checked the bridge before it opened.', 'An engineer checked the bridge before it opened.', '/ˌendʒɪˈnɪr/', 'Một kỹ sư đã kiểm tra cây cầu trước khi nó được thông xe.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_19_1_1', 'en-a2-19', 'ten_a2_19_1', 'listening', 'listening', 'The school concert was a success despite the rain.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã tập trả lời các câu hỏi trước buổi phỏng vấn xin việc đầu tiên của mình.","Buổi hòa nhạc của trường đã thành công tốt đẹp mặc dù trời mưa.","Thư ký đã sắp xếp một cuộc họp vào chiều mai.","Người giao sữa đã để hai chai thủy tinh trước cửa nhà chúng tôi."]'::jsonb, 1, 'The school concert was a success despite the rain. → Buổi hòa nhạc của trường đã thành công tốt đẹp mặc dù trời mưa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_19_1_2', 'en-a2-19', 'ten_a2_19_1', 'listening', 'listening', 'The gardener planted bright flowers along our front path.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người làm vườn đã trồng những bông hoa rực rỡ dọc theo lối đi trước nhà chúng tôi.","Nhân viên vệ sinh đã đổ sạch các thùng rác trước khi văn phòng mở cửa.","Dì của tôi làm việc tại một nhà máy sản xuất xe đạp.","Nhiệm vụ đầu tiên của tôi hôm nay là tưới cây."]'::jsonb, 0, 'The gardener planted bright flowers along our front path. → Người làm vườn đã trồng những bông hoa rực rỡ dọc theo lối đi trước nhà chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_19_1_3', 'en-a2-19', 'ten_a2_19_1', 'listening', 'listening', 'The cleaner emptied the bins before the office opened.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đồng nghiệp của tôi đã mang súp tự nấu đến văn phòng ngày hôm nay.","Chị tôi có nhiều năm kinh nghiệm sửa xe đạp cũ.","Nhân viên vệ sinh đã đổ sạch các thùng rác trước khi văn phòng mở cửa.","Người lính cứu hỏa đã cứu một chú mèo con khỏi nhà bếp đầy khói."]'::jsonb, 2, 'The cleaner emptied the bins before the office opened. → Nhân viên vệ sinh đã đổ sạch các thùng rác trước khi văn phòng mở cửa.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_19_2', 'en-a2-19', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_19_2_1', 'ten_a2_19_2', 'success', 'Long-term success in education depends not only on funding but also on the quality of teaching.', 'Long-term success in education depends not only on funding but also on the quality of teaching.', '/səkˈses/', 'Sự thành công lâu dài trong giáo dục không chỉ phụ thuộc vào nguồn vốn tài chính mà còn phụ thuộc vào chất lượng giảng dạy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_19_2_2', 'ten_a2_19_2', 'gardener', 'Community gardeners can improve urban biodiversity by growing native plants that provide food and shelter for wildlife.', 'Community gardeners can improve urban biodiversity by growing native plants that provide food and shelter for wildlife.', '/ˈɡɑːrdənər/', 'Những người làm vườn cộng đồng có thể cải thiện đa dạng sinh học đô thị bằng cách trồng các loài cây bản địa cung cấp thức ăn và nơi trú ẩn cho động vật hoang dã.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_19_2_3', 'ten_a2_19_2', 'cleaner', 'Hospitals should provide every cleaner with suitable protective equipment and training to reduce infection risks.', 'Hospitals should provide every cleaner with suitable protective equipment and training to reduce infection risks.', '/ˈkliːnər/', 'Bệnh viện nên cung cấp cho mọi nhân viên vệ sinh thiết bị bảo hộ và đào tạo phù hợp để giảm thiểu rủi ro lây nhiễm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_19_2_4', 'ten_a2_19_2', 'factory', 'Governments should require factory owners to reduce harmful emissions without compromising the safety and livelihoods of their workers.', 'Governments should require factory owners to reduce harmful emissions without compromising the safety and livelihoods of their workers.', '/ˈfæktəri/', 'Chính phủ nên yêu cầu các chủ nhà máy giảm thiểu lượng khí thải độc hại mà không làm tổn hại đến sự an toàn và sinh kế của công nhân.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_19_2_5', 'ten_a2_19_2', 'postman', 'In remote villages, a postman may provide an essential link between residents and public services.', 'In remote villages, a postman may provide an essential link between residents and public services.', '/ˈpoʊstmən/', 'Ở các ngôi làng hẻo lánh, nhân viên bưu điện có thể đóng vai trò là cầu nối thiết yếu giữa cư dân và các dịch vụ công.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_19_2_6', 'ten_a2_19_2', 'task', 'Dividing a complex task into smaller stages can help students manage their time more effectively.', 'Dividing a complex task into smaller stages can help students manage their time more effectively.', '/tæsk/', 'Chia một nhiệm vụ phức tạp thành các giai đoạn nhỏ hơn có thể giúp học sinh quản lý thời gian hiệu quả hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_19_2_1', 'en-a2-19', 'ten_a2_19_2', 'listening', 'listening', 'Long-term success in education depends not only on funding but also on the quality of teaching.', NULL, 'Trong câu vừa nghe, từ “success” mang nghĩa nào sau đây?', '["sóng; sóng biển","sự thành công; thành tựu","thưa bà; thưa cô; phu nhân (cách xưng hô lịch sự)","tâm trí; đầu óc; trí tuệ"]'::jsonb, 1, '“success” (/səkˈses/): sự thành công; thành tựu. Câu đầy đủ: Long-term success in education depends not only on funding but also on the quality of teaching.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_19_2_2', 'en-a2-19', 'ten_a2_19_2', 'listening', 'listening', 'Community gardeners can improve urban biodiversity by growing native plants that provide food and shelter for wildlife.', NULL, 'Trong câu vừa nghe, từ “gardener” mang nghĩa nào sau đây?', '["lò nướng; lò vi sóng","mái nhà; nóc (xe)","đường mòn; lối đi nhỏ","thợ làm vườn; người làm vườn"]'::jsonb, 3, '“gardener” (/ˈɡɑːrdənər/): thợ làm vườn; người làm vườn. Câu đầy đủ: Community gardeners can improve urban biodiversity by growing native plants that provide food and shelter for wildlife.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
