INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_19_2', 'en-a2-19', NULL, 'comprehensive_test', 'listening', 'The gardener planted bright flowers along our front path.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã tập trả lời các câu hỏi trước buổi phỏng vấn xin việc đầu tiên của mình.","Đồng nghiệp của tôi đã mang súp tự nấu đến văn phòng ngày hôm nay.","Người làm vườn đã trồng những bông hoa rực rỡ dọc theo lối đi trước nhà chúng tôi.","Thợ xây đã thay thế những viên gạch bị vỡ xung quanh cửa ra vào của chúng tôi."]'::jsonb, 2, 'The gardener planted bright flowers along our front path. → Người làm vườn đã trồng những bông hoa rực rỡ dọc theo lối đi trước nhà chúng tôi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_19_3', 'en-a2-19', NULL, 'comprehensive_test', 'listening', 'cleaner', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đặc biệt; nhất là","cái kéo; cây kéo","sách bài tập","nhân viên dọn dẹp; người làm vệ sinh"]'::jsonb, 3, 'cleaner (/ˈkliːnər/) → nhân viên dọn dẹp; người làm vệ sinh; chất tẩy rửa; thiết bị làm sạch; sạch sẽ hơn; ít gây ô nhiễm hơn', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_19_4', 'en-a2-19', NULL, 'comprehensive_test', 'listening', 'My aunt works at a factory that makes bicycles.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người giao sữa đã để hai chai thủy tinh trước cửa nhà chúng tôi.","Dì của tôi làm việc tại một nhà máy sản xuất xe đạp.","Cô ấy kiếm thêm tiền bằng cách dắt chó đi dạo sau giờ học.","Thư ký đã sắp xếp một cuộc họp vào chiều mai."]'::jsonb, 1, 'My aunt works at a factory that makes bicycles. → Dì của tôi làm việc tại một nhà máy sản xuất xe đạp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_19_5', 'en-a2-19', NULL, 'comprehensive_test', 'listening', 'postman', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nhạc pop; nhạc trẻ thịnh hành","kéo, lôi, giật","nam nhân viên bưu điện (người làm nghề phát thư từ và bưu phẩm)","giao thông, xe cộ qua lại"]'::jsonb, 2, 'postman (/ˈpoʊstmən/) → nam nhân viên bưu điện (người làm nghề phát thư từ và bưu phẩm)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_19_6', 'en-a2-19', NULL, 'comprehensive_test', 'listening', 'My first task today is to water the plants.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhiệm vụ đầu tiên của tôi hôm nay là tưới cây.","Người giao sữa đã để hai chai thủy tinh trước cửa nhà chúng tôi.","Hãy cất các biên lai của bạn vào tập tài liệu này ở bên cạnh bàn làm việc.","Thư ký đã sắp xếp một cuộc họp vào chiều mai."]'::jsonb, 0, 'My first task today is to water the plants. → Nhiệm vụ đầu tiên của tôi hôm nay là tưới cây.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
