INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_19_18', 'en-a2-19', NULL, 'comprehensive_test', 'reading', NULL, 'Long-term success in education depends not only on funding but also on the quality of teaching.', 'Dựa vào câu trên, từ “success” có nghĩa phù hợp nhất là gì?', '["mật ong","một chút; một lượng nhỏ; một miếng nhỏ","sự thành công; thành tựu","tài liệu; văn bản; hồ sơ điện tử"]'::jsonb, 2, 'success: sự thành công; thành tựu; người thành công; sự việc thành công. Dịch cả câu: Sự thành công lâu dài trong giáo dục không chỉ phụ thuộc vào nguồn vốn tài chính mà còn phụ thuộc vào chất lượng giảng dạy.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_19_19', 'en-a2-19', NULL, 'comprehensive_test', 'reading', NULL, 'Community gardeners can improve urban biodiversity by growing native plants that provide food and shelter for wildlife.', 'Dựa vào câu trên, từ “gardener” có nghĩa phù hợp nhất là gì?', '["không may là; đáng tiếc là","kệ; giá; tấm ván đặt đồ","thợ làm vườn; người làm vườn","tiệc nướng ngoài trời"]'::jsonb, 2, 'gardener: thợ làm vườn; người làm vườn. Dịch cả câu: Những người làm vườn cộng đồng có thể cải thiện đa dạng sinh học đô thị bằng cách trồng các loài cây bản địa cung cấp thức ăn và nơi trú ẩn cho động vật hoang dã.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_19_20', 'en-a2-19', NULL, 'comprehensive_test', 'reading', NULL, 'Hospitals should provide every cleaner with suitable protective equipment and training to reduce infection risks.', 'Dựa vào câu trên, từ “cleaner” có nghĩa phù hợp nhất là gì?', '["lượng; số lượng","máy in","nhân viên dọn dẹp; người làm vệ sinh","phóng viên; nhà báo"]'::jsonb, 2, 'cleaner: nhân viên dọn dẹp; người làm vệ sinh; chất tẩy rửa; thiết bị làm sạch; sạch sẽ hơn; ít gây ô nhiễm hơn. Dịch cả câu: Bệnh viện nên cung cấp cho mọi nhân viên vệ sinh thiết bị bảo hộ và đào tạo phù hợp để giảm thiểu rủi ro lây nhiễm.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_19_21', 'en-a2-19', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should require factory owners to reduce harmful emissions without compromising the safety and livelihoods of their workers.', 'Dựa vào câu trên, từ “factory” có nghĩa phù hợp nhất là gì?', '["theo như; theo lời","bản báo cáo; tường thuật","nhà máy; xưởng","một chút; một lượng nhỏ; một miếng nhỏ"]'::jsonb, 2, 'factory: nhà máy; xưởng. Dịch cả câu: Chính phủ nên yêu cầu các chủ nhà máy giảm thiểu lượng khí thải độc hại mà không làm tổn hại đến sự an toàn và sinh kế của công nhân.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_19_22', 'en-a2-19', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bộ phận; khoa; ban”', '["chess","belt","mile","department"]'::jsonb, 3, 'bộ phận; khoa; ban → department (/dɪˈpɑːrtmənt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_19_23', 'en-a2-19', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thợ xây dựng; nhà thầu xây dựng”', '["worse","programme","builder","control"]'::jsonb, 2, 'thợ xây dựng; nhà thầu xây dựng → builder (/ˈbɪldər/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_19_24', 'en-a2-19', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “kinh nghiệm”', '["experience","succeed","mug","perfect"]'::jsonb, 0, 'kinh nghiệm → experience (/ɪkˈspɪriəns/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-20', 'en', 'Bài 20: Kinh tế & Tài chính - CEFR A2', 'CEFR A2', 'A2 · Kinh tế', '16 từ vựng Tiếng Anh CEFR A2 chủ đề kinh tế & tài chính kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2020, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gold', 'en-a2-20', 'gold', '/ɡoʊld/', 'A2', 'vàng; kim loại vàng; huy chương vàng; bằng vàng; có màu vàng óng', 'n.', 'golden (adj.)', NULL, 'gold khi chỉ chất liệu thường không đếm được; a gold có thể chỉ một chiếc huy chương vàng.', 'My grandmother keeps her gold ring in a wooden box.', NULL, 'Bà tôi cất chiếc nhẫn vàng trong một chiếc hộp gỗ.', '{"wordId":"gold","ukIpa":"/ɡəʊld/","usIpa":"/ɡoʊld/","cefr":"A2","topic":"economy","senses":[{"pos":"n.","en":"A valuable yellow metal used for jewellery and money","vi":"vàng; kim loại vàng"},{"pos":"n.","en":"The medal awarded for first place in a competition","vi":"huy chương vàng"},{"pos":"adj.","en":"Made of gold or having its yellow colour","vi":"bằng vàng; có màu vàng óng"}],"examples":[{"en":"My grandmother keeps her gold ring in a wooden box.","vi":"Bà tôi cất chiếc nhẫn vàng trong một chiếc hộp gỗ.","audioKind":"ex"},{"en":"Demand for gold can increase during economic uncertainty, as investors seek assets they consider relatively safe.","vi":"Nhu cầu về vàng có thể tăng lên trong thời kỳ bất ổn kinh tế khi các nhà đầu tư tìm kiếm tài sản mà họ cho là tương đối an toàn.","audioKind":"ex2"}],"collocations":[{"en":"pure gold","vi":"vàng nguyên chất"},{"en":"gold medal","vi":"huy chương vàng"},{"en":"gold jewellery","vi":"trang sức bằng vàng"},{"en":"gold reserves","vi":"dự trữ vàng"}],"wordFamily":["golden (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"gold khi chỉ chất liệu thường không đếm được; a gold có thể chỉ một chiếc huy chương vàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_euro', 'en-a2-20', 'euro', '/ˈjʊroʊ/', 'A2', 'đồng euro', 'n.', NULL, NULL, 'Trong tiếng Anh thông thường, số nhiều của euro là euros; không phải tất cả các quốc gia thuộc Liên minh Châu Âu đều dùng đồng euro.', 'I found a euro in my coat pocket today.', NULL, 'Hôm nay tôi tìm thấy một đồng euro trong túi áo khoác của mình.', '{"wordId":"euro","ukIpa":"/ˈjʊərəʊ/","usIpa":"/ˈjʊroʊ/","cefr":"A2","topic":"economy","senses":[{"pos":"n.","en":"The currency used by many countries in the European Union.","vi":"đồng euro"}],"examples":[{"en":"I found a euro in my coat pocket today.","vi":"Hôm nay tôi tìm thấy một đồng euro trong túi áo khoác của mình.","audioKind":"ex"},{"en":"Using the euro allows tourists to visit several European countries without exchanging money at each border.","vi":"Việc sử dụng đồng euro cho phép khách du lịch tham quan nhiều nước châu Âu mà không cần đổi tiền ở mỗi biên giới.","audioKind":"ex2"}],"collocations":[{"en":"the euro area","vi":"khu vực đồng euro"},{"en":"pay in euros","vi":"trả bằng tiền euro"},{"en":"adopt the euro","vi":"sử dụng đồng euro"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh thông thường, số nhiều của euro là euros; không phải tất cả các quốc gia thuộc Liên minh Châu Âu đều dùng đồng euro.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coin', 'en-a2-20', 'coin', '/kɔɪn/', 'A2', 'tiền xu; tạo ra từ mới; đặt ra thuật ngữ', 'n.', 'coinage (n.)', NULL, 'Từ coin khi đóng vai trò là động từ thường dùng để chỉ việc tạo ra từ ngữ mới, chẳng hạn như coin a term.', 'A silver coin rolled under the kitchen table.', NULL, 'Một đồng tiền xu bằng bạc lăn xuống dưới gầm bàn bếp.', '{"wordId":"coin","ukIpa":"/kɔɪn/","usIpa":"/kɔɪn/","cefr":"A2","topic":"economy","senses":[{"pos":"n.","en":"a small, flat piece of metal used as money","vi":"tiền xu"},{"pos":"v.","en":"to invent a new word or expression","vi":"tạo ra từ mới; đặt ra thuật ngữ"}],"examples":[{"en":"A silver coin rolled under the kitchen table.","vi":"Một đồng tiền xu bằng bạc lăn xuống dưới gầm bàn bếp.","audioKind":"ex"},{"en":"As digital payments become more widespread, fewer consumers carry coins for everyday purchases such as bus fares.","vi":"Khi thanh toán kỹ thuật số ngày càng trở nên phổ biến, ít người tiêu dùng mang theo tiền xu cho các giao dịch mua sắm hàng ngày như tiền vé xe buýt hơn.","audioKind":"ex2"}],"collocations":[{"en":"a gold coin","vi":"đồng vàng; tiền vàng"},{"en":"toss a coin","vi":"tung đồng xu; tung đồng ngửa"},{"en":"coin a term","vi":"đặt ra một thuật ngữ; tạo ra một thuật ngữ"}],"wordFamily":["coinage (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ coin khi đóng vai trò là động từ thường dùng để chỉ việc tạo ra từ ngữ mới, chẳng hạn như coin a term.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_product', 'en-a2-20', 'product', '/ˈprɑːdʌkt/', 'A2', 'sản phẩm; hàng hóa; hệ quả; tích (toán học)', 'n.', 'produce (v.), production (n.), producer (n.), productive (adj.)', NULL, 'product là sản phẩm hoặc kết quả, còn production là quá trình sản xuất.', 'This cleaning product removes stains from my kitchen tiles.', NULL, 'Sản phẩm làm sạch này giúp tẩy sạch các vết bẩn trên gạch ốp bếp của tôi.', '{"wordId":"product","ukIpa":"/ˈprɒdʌkt/","usIpa":"/ˈprɑːdʌkt/","cefr":"A2","topic":"economy","senses":[{"pos":"n.","en":"something made or grown to be sold or used","vi":"sản phẩm; hàng hóa"},{"pos":"n.","en":"something that results from a process or situation","vi":"sản phẩm; hệ quả"},{"pos":"n.","en":"the result of multiplying two or more quantities","vi":"tích (toán học)"}],"examples":[{"en":"This cleaning product removes stains from my kitchen tiles.","vi":"Sản phẩm làm sạch này giúp tẩy sạch các vết bẩn trên gạch ốp bếp của tôi.","audioKind":"ex"},{"en":"Consumers increasingly prefer products that use less packaging and can be repaired rather than replaced.","vi":"Người tiêu dùng ngày càng ưua chuộng các sản phẩm ít bao bì hơn và có thể sửa chữa thay vì phải vứt bỏ mua mới.","audioKind":"ex2"}],"collocations":[{"en":"launch a product","vi":"ra mắt sản phẩm"},{"en":"dairy products","vi":"sản phẩm từ sữa"},{"en":"product development","vi":"phát triển sản phẩm"},{"en":"the product of","vi":"sản phẩm của..."}],"wordFamily":["produce (v.)","production (n.)","producer (n.)","productive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"product là sản phẩm hoặc kết quả, còn production là quá trình sản xuất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_percent', 'en-a2-20', 'percent', '/pərˈsent/', 'A2', 'phần trăm', 'adv.', 'percentage (n.)', NULL, 'Tiếng Anh Anh cũng viết là per cent; dùng percent khi đi kèm tỷ lệ cụ thể.', 'I saved twenty percent on my new winter coat.', NULL, 'Tôi đã tiết kiệm được hai mươi phần trăm khi mua chiếc áo khoác mùa đông mới.', '{"wordId":"percent","ukIpa":"/pəˈsent/","usIpa":"/pərˈsent/","cefr":"A2","topic":"economy","senses":[{"pos":"adv.","en":"For every hundred, used when expressing a proportion.","vi":"phần trăm"}],"examples":[{"en":"I saved twenty percent on my new winter coat.","vi":"Tôi đã tiết kiệm được hai mươi phần trăm khi mua chiếc áo khoác mùa đông mới.","audioKind":"ex"},{"en":"Nearly forty percent of surveyed residents supported investing more public money in cycling infrastructure.","vi":"Gần bốn mươi phần trăm cư dân được khảo sát ủng hộ việc đầu tư nhiều ngân sách công hơn vào cơ sở hạ tầng dành cho xe đạp.","audioKind":"ex2"}],"collocations":[{"en":"ten percent of","vi":"mười phần trăm của"},{"en":"a five percent increase","vi":"sự tăng trưởng năm phần trăm"},{"en":"one hundred percent","vi":"một trăm phần trăm"}],"wordFamily":["percentage (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh Anh cũng viết là per cent; dùng percent khi đi kèm tỷ lệ cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_total', 'en-a2-20', 'total', '/ˈtoʊtəl/', 'A2', 'tổng cộng; toàn bộ; tổng số; tổng lượng; tổng cộng lên đến; tính tổng', 'adj.', 'totally (adv.), totality (n.)', 'Đồng nghĩa: complete, entire · Trái nghĩa: partial', 'in total có nghĩa là "tổng cộng"; totally thường diễn tả sự "hoàn toàn".', 'The total cost includes breakfast and a bus ticket.', NULL, 'Tổng chi phí đã bao gồm bữa sáng và một vé xe buýt.', '{"wordId":"total","ukIpa":"/ˈtəʊtəl/","usIpa":"/ˈtoʊtəl/","cefr":"A2","topic":"economy","senses":[{"pos":"adj.","en":"including everything, or complete in degree","vi":"tổng cộng; toàn bộ"},{"pos":"n.","en":"the amount obtained by adding everything together","vi":"tổng số; tổng lượng"},{"pos":"v.","en":"to reach a particular amount or add amounts together","vi":"tổng cộng lên đến; tính tổng"}],"examples":[{"en":"The total cost includes breakfast and a bus ticket.","vi":"Tổng chi phí đã bao gồm bữa sáng và một vé xe buýt.","audioKind":"ex"},{"en":"Improving home insulation can reduce total energy consumption while making housing more comfortable throughout the year.","vi":"Cải thiện khả năng cách nhiệt của ngôi nhà có thể làm giảm tổng năng lượng tiêu thụ đồng thời giúp không gian sống thoải mái hơn quanh năm.","audioKind":"ex2"}],"collocations":[{"en":"total cost","vi":"tổng chi phí"},{"en":"in total","vi":"tổng cộng"},{"en":"a total of","vi":"tổng số..."},{"en":"total energy consumption","vi":"tổng năng lượng tiêu thụ"}],"wordFamily":["totally (adv.)","totality (n.)"],"synonyms":["complete","entire"],"antonyms":["partial"],"tipVi":"in total có nghĩa là \"tổng cộng\"; totally thường diễn tả sự \"hoàn toàn\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sale', 'en-a2-20', 'sale', '/seɪl/', 'A2', 'việc bán hàng; sự giao dịch mua bán; đợt giảm giá; chương trình khuyến mại; doanh thu; doanh số bán hàng', 'n.', 'sell (v.), seller (n.)', NULL, 'for sale có nghĩa là được rao bán; trong khi doanh thu hoặc lượng hàng bán ra thường dùng ở dạng số nhiều là sales.', 'I bought these boots in the winter sale.', NULL, 'Tôi đã mua đôi bốt này trong đợt giảm giá mùa đông.', '{"wordId":"sale","ukIpa":"/seɪl/","usIpa":"/seɪl/","cefr":"A2","topic":"economy","senses":[{"pos":"n.","en":"the act of exchanging something for money","vi":"việc bán hàng; sự giao dịch mua bán"},{"pos":"n.","en":"a period when a shop sells goods at reduced prices","vi":"đợt giảm giá; chương trình khuyến mại"},{"pos":"n.","en":"the amount sold or money earned from selling goods","vi":"doanh thu; doanh số bán hàng"}],"examples":[{"en":"I bought these boots in the winter sale.","vi":"Tôi đã mua đôi bốt này trong đợt giảm giá mùa đông.","audioKind":"ex"},{"en":"The sale of locally produced food can support farmers while reducing emissions associated with long-distance transport.","vi":"Việc tiêu thụ các sản phẩm thực phẩm sản xuất tại địa phương có thể hỗ trợ người nông dân đồng thời giảm thiểu lượng khí thải liên quan đến vận chuyển đường dài.","audioKind":"ex2"}],"collocations":[{"en":"for sale","vi":"được bày bán; đang bán"},{"en":"on sale","vi":"đang giảm giá; đang bán hạ giá"},{"en":"sales figures","vi":"số liệu doanh thu"},{"en":"a clearance sale","vi":"đợt bán hàng thanh lý"}],"wordFamily":["sell (v.)","seller (n.)"],"synonyms":[],"antonyms":[],"tipVi":"for sale có nghĩa là được rao bán; trong khi doanh thu hoặc lượng hàng bán ra thường dùng ở dạng số nhiều là sales.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_per', 'en-a2-20', 'per', '/pər/', 'A2', 'mỗi; một', 'prep.', NULL, NULL, 'per thường đi với danh từ số ít, không thêm mạo từ, ví dụ per day.', 'The swimming pool costs five pounds per visit.', NULL, 'Hồ bơi có giá năm bảng Anh cho mỗi lượt vào cửa.', '{"wordId":"per","ukIpa":"/pə(r)/","usIpa":"/pər/","cefr":"A2","topic":"economy","senses":[{"pos":"prep.","en":"For each unit of something.","vi":"mỗi; một"}],"examples":[{"en":"The swimming pool costs five pounds per visit.","vi":"Hồ bơi có giá năm bảng Anh cho mỗi lượt vào cửa.","audioKind":"ex"},{"en":"Reducing energy consumption per household is an important step towards lowering a country''s carbon emissions.","vi":"Giảm mức tiêu thụ năng lượng trên mỗi hộ gia đình là một bước quan trọng để hạ thấp lượng khí thải carbon của một quốc gia.","audioKind":"ex2"}],"collocations":[{"en":"per person","vi":"mỗi người"},{"en":"per hour","vi":"mỗi giờ"},{"en":"per capita","vi":"tính trên đầu người"},{"en":"per year","vi":"mỗi năm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"per thường đi với danh từ số ít, không thêm mạo từ, ví dụ per day.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cost', 'en-a2-20', 'cost', '/kɔːst/', 'A2', 'chi phí; giá tiền; có giá là; tiêu tốn; sự đánh đổi; tổn thất', 'n.', 'costly (adj.), costing (n.)', NULL, 'Khi diễn tả việc tiêu tốn tiền, thì quá khứ và phân từ hai của "cost" vẫn giữ nguyên là "cost".', 'The cost of our weekly groceries keeps rising.', NULL, 'Chi phí mua sắm thực phẩm hàng tuần của chúng tôi không ngừng tăng lên.', '{"wordId":"cost","ukIpa":"/kɒst/","usIpa":"/kɔːst/","cefr":"A2","topic":"economy","senses":[{"pos":"n.","en":"the money needed to buy or do something","vi":"chi phí; giá tiền"},{"pos":"v.","en":"to require a particular amount of money","vi":"có giá là; tiêu tốn"},{"pos":"n.","en":"something valuable lost to achieve or obtain something","vi":"sự đánh đổi; tổn thất"}],"examples":[{"en":"The cost of our weekly groceries keeps rising.","vi":"Chi phí mua sắm thực phẩm hàng tuần của chúng tôi không ngừng tăng lên.","audioKind":"ex"},{"en":"Improving public transport can reduce the cost of commuting and make cities more accessible.","vi":"Việc cải thiện giao thông công cộng có thể làm giảm chi phí đi lại và giúp việc di chuyển trong thành phố trở nên thuận tiện hơn.","audioKind":"ex2"}],"collocations":[{"en":"the cost of living","vi":"chi phí sinh hoạt"},{"en":"cover the cost","vi":"chi trả chi phí"},{"en":"at all costs","vi":"bằng mọi giá"},{"en":"cost a fortune","vi":"tốn rất nhiều tiền"}],"wordFamily":["costly (adj.)","costing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi diễn tả việc tiêu tốn tiền, thì quá khứ và phân từ hai của \"cost\" vẫn giữ nguyên là \"cost\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_half-price', 'en-a2-20', 'half-price', '/ˌhæf ˈpraɪs/', 'A2', 'giá một nửa; nửa giá; với nửa giá', 'adj.', 'price (n.), priced (adj.)', 'Trái nghĩa: full-price', 'Trước danh từ thường viết là half-price; at half price không có dấu gạch nối.', 'We bought half-price tickets for the afternoon boat trip.', NULL, 'Chúng tôi đã mua vé nửa giá cho chuyến đi thuyền buổi chiều.', '{"wordId":"half-price","ukIpa":"/ˌhɑːf ˈpraɪs/","usIpa":"/ˌhæf ˈpraɪs/","cefr":"A2","topic":"economy","senses":[{"pos":"adj.","en":"costing half the usual price","vi":"giá một nửa; nửa giá"},{"pos":"adv.","en":"at half the usual price","vi":"với nửa giá"}],"examples":[{"en":"We bought half-price tickets for the afternoon boat trip.","vi":"Chúng tôi đã mua vé nửa giá cho chuyến đi thuyền buổi chiều.","audioKind":"ex"},{"en":"Offering half-price public transport to students could improve access to education and reduce car use.","vi":"Việc cung cấp phương tiện giao thông công cộng nửa giá cho sinh viên có thể cải thiện khả năng tiếp cận giáo dục và giảm việc sử dụng ô tô.","audioKind":"ex2"}],"collocations":[{"en":"half-price tickets","vi":"vé nửa giá"},{"en":"half-price sale","vi":"đợt giảm giá một nửa"},{"en":"buy something half-price","vi":"mua thứ gì đó với giá một nửa"}],"wordFamily":["price (n.)","priced (adj.)"],"synonyms":[],"antonyms":["full-price"],"tipVi":"Trước danh từ thường viết là half-price; at half price không có dấu gạch nối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cash', 'en-a2-20', 'cash', '/kæʃ/', 'A2', 'tiền mặt; đổi thành tiền mặt', 'n.', 'cashless (adj.)', NULL, 'cash với nghĩa tiền mặt là danh từ không đếm được; cụm từ thanh toán bằng tiền mặt là pay in cash.', 'I keep some cash in my wallet for emergencies.', NULL, 'Tôi giữ một ít tiền mặt trong ví để phòng khi khẩn cấp.', '{"wordId":"cash","ukIpa":"/kæʃ/","usIpa":"/kæʃ/","cefr":"A2","topic":"economy","senses":[{"pos":"n.","en":"Money in the form of coins and banknotes","vi":"tiền mặt"},{"pos":"v.","en":"Exchange a cheque for money","vi":"đổi thành tiền mặt"}],"examples":[{"en":"I keep some cash in my wallet for emergencies.","vi":"Tôi giữ một ít tiền mặt trong ví để phòng khi khẩn cấp.","audioKind":"ex"},{"en":"Although digital payments are increasingly common, many small businesses still prefer customers to pay in cash.","vi":"Mặc dù thanh toán điện tử ngày càng phổ biến, nhiều cửa hàng nhỏ vẫn thích khách hàng thanh toán bằng tiền mặt hơn.","audioKind":"ex2"}],"collocations":[{"en":"pay in cash","vi":"thanh toán bằng tiền mặt"},{"en":"withdraw cash","vi":"rút tiền mặt"},{"en":"cash a cheque","vi":"đổi séc thành tiền mặt"},{"en":"cash flow","vi":"dòng tiền"}],"wordFamily":["cashless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"cash với nghĩa tiền mặt là danh từ không đếm được; cụm từ thanh toán bằng tiền mặt là pay in cash.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_customer', 'en-a2-20', 'customer', '/ˈkʌstəmər/', 'A2', 'khách hàng; người mua', 'n.', NULL, 'Đồng nghĩa: buyer, client', 'customer chỉ khách hàng nói chung; client thường chỉ khách hàng sử dụng dịch vụ chuyên nghiệp.', 'The customer asked for a larger pair of shoes.', NULL, 'Khách hàng đã hỏi tìm một đôi giày lớn hơn.', '{"wordId":"customer","ukIpa":"/ˈkʌstəmə/","usIpa":"/ˈkʌstəmər/","cefr":"A2","topic":"economy","senses":[{"pos":"n.","en":"A person or organisation that buys goods or services.","vi":"khách hàng; người mua"}],"examples":[{"en":"The customer asked for a larger pair of shoes.","vi":"Khách hàng đã hỏi tìm một đôi giày lớn hơn.","audioKind":"ex"},{"en":"Businesses can build customer loyalty by providing reliable products and responding quickly to complaints.","vi":"Các doanh nghiệp có thể xây dựng lòng trung thành của khách hàng bằng cách cung cấp các sản phẩm đáng tin cậy và phản hồi nhanh chóng đối với các khiếu nại.","audioKind":"ex2"}],"collocations":[{"en":"customer service","vi":"dịch vụ khách hàng"},{"en":"regular customer","vi":"khách hàng quen"},{"en":"customer satisfaction","vi":"sự hài lòng của khách hàng"},{"en":"customer loyalty","vi":"lòng trung thành của khách hàng"}],"wordFamily":[],"synonyms":["buyer","client"],"antonyms":[],"tipVi":"customer chỉ khách hàng nói chung; client thường chỉ khách hàng sử dụng dịch vụ chuyên nghiệp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_penny', 'en-a2-20', 'penny', '/ˈpeni/', 'A2', 'đồng xu một xu (Anh); đồng xu một phần trăm bảng Anh; đồng xu một xu (Mỹ); đồng xu một phần trăm đô la', 'n.', 'penniless (adj.)', NULL, 'Số tiền tệ ở Anh dùng pence ở số nhiều; khi chỉ những đồng xu riêng lẻ thì dùng pennies.', 'I found a penny underneath the sofa this morning.', NULL, 'Sáng nay tôi tìm thấy một đồng xu dưới ghế sô-pha.', '{"wordId":"penny","ukIpa":"/ˈpeni/","usIpa":"/ˈpeni/","cefr":"A2","topic":"economy","senses":[{"pos":"n.","en":"A British coin or unit worth one hundredth of a pound.","vi":"đồng xu một xu (Anh); đồng xu một phần trăm bảng Anh"},{"pos":"n.","en":"An American coin worth one hundredth of a dollar.","vi":"đồng xu một xu (Mỹ); đồng xu một phần trăm đô la"}],"examples":[{"en":"I found a penny underneath the sofa this morning.","vi":"Sáng nay tôi tìm thấy một đồng xu dưới ghế sô-pha.","audioKind":"ex"},{"en":"For families on low incomes, every penny saved on energy bills can make a difference.","vi":"Đối với các gia đình thu nhập thấp, từng xu tiết kiệm được từ hóa đơn tiền điện đều có thể tạo ra sự khác biệt lớn.","audioKind":"ex2"}],"collocations":[{"en":"every penny","vi":"từng xu một"},{"en":"not a penny","vi":"không có một xu dính túi"},{"en":"worth every penny","vi":"đáng từng xu; đáng giá"}],"wordFamily":["penniless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Số tiền tệ ở Anh dùng pence ở số nhiều; khi chỉ những đồng xu riêng lẻ thì dùng pennies.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pound', 'en-a2-20', 'pound', '/paʊnd/', 'A2', 'đồng bảng Anh (đơn vị tiền tệ chính của Vương quốc Anh); ao-xơ, pa-vần, cân Anh (đơn vị khối lượng khoảng 454 gram); đập mạnh; nện liên hồi; đập thình thịch', 'n.', 'pounding (n.)', NULL, 'Cả tiền tệ (bảng Anh) và đơn vị trọng lượng (cân Anh) đều dùng từ pound; số phận thường thêm s.', 'I paid one pound for this bag of apples.', NULL, 'Tôi đã trả một bảng Anh cho túi táo này.', '{"wordId":"pound","ukIpa":"/paʊnd/","usIpa":"/paʊnd/","cefr":"A2","topic":"economy","senses":[{"pos":"n.","en":"the main unit of money used in the United Kingdom","vi":"đồng bảng Anh (đơn vị tiền tệ chính của Vương quốc Anh)"},{"pos":"n.","en":"a unit of weight equal to about 454 grams","vi":"ao-xơ, pa-vần, cân Anh (đơn vị khối lượng khoảng 454 gram)"},{"pos":"v.","en":"to hit repeatedly with force or beat strongly","vi":"đập mạnh; nện liên hồi; đập thình thịch"}],"examples":[{"en":"I paid one pound for this bag of apples.","vi":"Tôi đã trả một bảng Anh cho túi táo này.","audioKind":"ex"},{"en":"A weaker pound can attract international tourists, but it also raises the cost of imported goods.","vi":"Đồng bảng Anh giảm giá có thể thu hút khách du lịch quốc tế, nhưng nó cũng làm tăng chi phí hàng hóa nhập khẩu.","audioKind":"ex2"}],"collocations":[{"en":"the British pound","vi":"đồng bảng Anh"},{"en":"a pound of butter","vi":"một pa-vần bơ"},{"en":"pound on the door","vi":"đập cửa thình thịch"},{"en":"heart pounding","vi":"tim đập thình thịch"}],"wordFamily":["pounding (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cả tiền tệ (bảng Anh) và đơn vị trọng lượng (cân Anh) đều dùng từ pound; số phận thường thêm s.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rise', 'en-a2-20', 'rise', '/raɪz/', 'A2', 'tăng lên; dâng lên; lên cao; đứng dậy; chỗi dậy; sự tăng; mức tăng; sự dâng lên', 'v.', 'rising (adj.)', 'Đồng nghĩa: increase, climb · Trái nghĩa: fall, decrease', 'rise là nội động từ, có dạng quá khứ là rose, quá khứ phân từ là risen; trong khi raise là ngoại động từ.', 'Warm air rises above the heater beside my desk.', NULL, 'Không khí ấm áp bốc lên phía trên lò sưởi cạnh bàn làm việc của tôi.', '{"wordId":"rise","ukIpa":"/raɪz/","usIpa":"/raɪz/","cefr":"A2","topic":"economy","senses":[{"pos":"v.","en":"To move upwards or become greater in amount or level.","vi":"tăng lên; dâng lên; lên cao"},{"pos":"v.","en":"To get up from sitting or lying down.","vi":"đứng dậy; chỗi dậy"},{"pos":"n.","en":"An increase in amount, level, or value.","vi":"sự tăng; mức tăng; sự dâng lên"}],"examples":[{"en":"Warm air rises above the heater beside my desk.","vi":"Không khí ấm áp bốc lên phía trên lò sưởi cạnh bàn làm việc của tôi.","audioKind":"ex"},{"en":"A sharp rise in housing costs has forced many young adults to delay moving into their own homes.","vi":"Sự gia tăng đột biến của chi phí nhà ở đã buộc nhiều người trẻ phải trì hoãn việc chuyển đến ngôi nhà riêng của họ.","audioKind":"ex2"}],"collocations":[{"en":"a sharp rise","vi":"sự tăng mạnh"},{"en":"rise steadily","vi":"tăng đều đặn"},{"en":"rise to your feet","vi":"đứng dậy"},{"en":"a rise in prices","vi":"sự tăng giá cả"}],"wordFamily":["rising (adj.)"],"synonyms":["increase","climb"],"antonyms":["fall","decrease"],"tipVi":"rise là nội động từ, có dạng quá khứ là rose, quá khứ phân từ là risen; trong khi raise là ngoại động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_increase', 'en-a2-20', 'increase', '/ɪnˈkriːs/', 'A2', 'tăng; làm tăng; sự tăng; sự gia tăng', 'v.', 'increasing (adj.), increasingly (adv.)', 'Đồng nghĩa: rise, grow · Trái nghĩa: decrease, decline', 'Trọng âm của động từ nằm ở âm tiết sau, còn danh từ nằm ở âm tiết đầu; "by" dùng cho khoảng tăng, "to" dùng cho giá trị đạt tới.', 'The bakery increased its prices again this week.', NULL, 'Tiệm bánh đã tăng giá thêm một lần nữa trong tuần này.', '{"wordId":"increase","ukIpa":"/ɪnˈkriːs/","usIpa":"/ɪnˈkriːs/","cefr":"A2","topic":"economy","senses":[{"pos":"v.","en":"Become greater in amount or size, or make something greater","vi":"tăng; làm tăng"},{"pos":"n.","en":"A rise in the amount, size, or level of something","vi":"sự tăng; sự gia tăng"}],"examples":[{"en":"The bakery increased its prices again this week.","vi":"Tiệm bánh đã tăng giá thêm một lần nữa trong tuần này.","audioKind":"ex"},{"en":"An increase in public transport investment could reduce traffic congestion and improve air quality in cities.","vi":"Việc gia tăng đầu tư vào giao thông công cộng có thể làm giảm tình trạng tắc nghẽn giao thông và cải thiện chất lượng không khí ở các đô thị.","audioKind":"ex2"}],"collocations":[{"en":"increase by","vi":"tăng thêm (một lượng)"},{"en":"increase to","vi":"tăng lên đến"},{"en":"an increase in demand","vi":"sự gia tăng về nhu cầu"},{"en":"a significant increase","vi":"sự gia tăng đáng kể"}],"wordFamily":["increasing (adj.)","increasingly (adv.)"],"synonyms":["rise","grow"],"antonyms":["decrease","decline"],"tipVi":"Trọng âm của động từ nằm ở âm tiết sau, còn danh từ nằm ở âm tiết đầu; \"by\" dùng cho khoảng tăng, \"to\" dùng cho giá trị đạt tới.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_20_1', 'en-a2-20', 'Cách dùng “euro” (n.) — đồng euro', 'the euro area  ·  pay in euros  ·  adopt the euro', 'Trong tiếng Anh thông thường, số nhiều của euro là euros; không phải tất cả các quốc gia thuộc Liên minh Châu Âu đều dùng đồng euro.', NULL, '[{"hanzi":"I found a euro in my coat pocket today.","pinyin":"","meaning":"Hôm nay tôi tìm thấy một đồng euro trong túi áo khoác của mình."},{"hanzi":"Using the euro allows tourists to visit several European countries without exchanging money at each border.","pinyin":"","meaning":"Việc sử dụng đồng euro cho phép khách du lịch tham quan nhiều nước châu Âu mà không cần đổi tiền ở mỗi biên giới."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_20_2', 'en-a2-20', 'Cách dùng “increase” (v.) — tăng; làm tăng', 'increase by  ·  increase to  ·  an increase in demand', 'Trọng âm của động từ nằm ở âm tiết sau, còn danh từ nằm ở âm tiết đầu; "by" dùng cho khoảng tăng, "to" dùng cho giá trị đạt tới.', 'Họ từ (Word Family): increasing (adj.), increasingly (adv.) | Đồng nghĩa: rise, grow · Trái nghĩa: decrease, decline', '[{"hanzi":"The bakery increased its prices again this week.","pinyin":"","meaning":"Tiệm bánh đã tăng giá thêm một lần nữa trong tuần này."},{"hanzi":"An increase in public transport investment could reduce traffic congestion and improve air quality in cities.","pinyin":"","meaning":"Việc gia tăng đầu tư vào giao thông công cộng có thể làm giảm tình trạng tắc nghẽn giao thông và cải thiện chất lượng không khí ở các đô thị."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_20_3', 'en-a2-20', 'Cách dùng “sale” (n.) — việc bán hàng; sự giao dịch mua bán', 'for sale  ·  on sale  ·  sales figures', 'for sale có nghĩa là được rao bán; trong khi doanh thu hoặc lượng hàng bán ra thường dùng ở dạng số nhiều là sales.', 'Họ từ (Word Family): sell (v.), seller (n.)', '[{"hanzi":"I bought these boots in the winter sale.","pinyin":"","meaning":"Tôi đã mua đôi bốt này trong đợt giảm giá mùa đông."},{"hanzi":"The sale of locally produced food can support farmers while reducing emissions associated with long-distance transport.","pinyin":"","meaning":"Việc tiêu thụ các sản phẩm thực phẩm sản xuất tại địa phương có thể hỗ trợ người nông dân đồng thời giảm thiểu lượng khí thải liên quan đến vận chuyển đường dài."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_20_4', 'en-a2-20', 'Cách dùng “coin” (n.) — tiền xu', 'a gold coin  ·  toss a coin  ·  coin a term', 'Từ coin khi đóng vai trò là động từ thường dùng để chỉ việc tạo ra từ ngữ mới, chẳng hạn như coin a term.', 'Họ từ (Word Family): coinage (n.)', '[{"hanzi":"A silver coin rolled under the kitchen table.","pinyin":"","meaning":"Một đồng tiền xu bằng bạc lăn xuống dưới gầm bàn bếp."},{"hanzi":"As digital payments become more widespread, fewer consumers carry coins for everyday purchases such as bus fares.","pinyin":"","meaning":"Khi thanh toán kỹ thuật số ngày càng trở nên phổ biến, ít người tiêu dùng mang theo tiền xu cho các giao dịch mua sắm hàng ngày như tiền vé xe buýt hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_20_1', 'en-a2-20', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
