INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_20_1_4', 'ten_a2_20_1', 'product', 'This cleaning product removes stains from my kitchen tiles.', 'This cleaning product removes stains from my kitchen tiles.', '/ˈprɑːdʌkt/', 'Sản phẩm làm sạch này giúp tẩy sạch các vết bẩn trên gạch ốp bếp của tôi.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_20_1_5', 'ten_a2_20_1', 'percent', 'I saved twenty percent on my new winter coat.', 'I saved twenty percent on my new winter coat.', '/pərˈsent/', 'Tôi đã tiết kiệm được hai mươi phần trăm khi mua chiếc áo khoác mùa đông mới.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_20_1_6', 'ten_a2_20_1', 'total', 'The total cost includes breakfast and a bus ticket.', 'The total cost includes breakfast and a bus ticket.', '/ˈtoʊtəl/', 'Tổng chi phí đã bao gồm bữa sáng và một vé xe buýt.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_20_1_7', 'ten_a2_20_1', 'sale', 'I bought these boots in the winter sale.', 'I bought these boots in the winter sale.', '/seɪl/', 'Tôi đã mua đôi bốt này trong đợt giảm giá mùa đông.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_20_1_8', 'ten_a2_20_1', 'per', 'The swimming pool costs five pounds per visit.', 'The swimming pool costs five pounds per visit.', '/pər/', 'Hồ bơi có giá năm bảng Anh cho mỗi lượt vào cửa.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_20_1_1', 'en-a2-20', 'ten_a2_20_1', 'listening', 'listening', 'My grandmother keeps her gold ring in a wooden box.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một đồng tiền xu bằng bạc lăn xuống dưới gầm bàn bếp.","Tôi đã tiết kiệm được hai mươi phần trăm khi mua chiếc áo khoác mùa đông mới.","Bà tôi cất chiếc nhẫn vàng trong một chiếc hộp gỗ.","Không khí ấm áp bốc lên phía trên lò sưởi cạnh bàn làm việc của tôi."]'::jsonb, 2, 'My grandmother keeps her gold ring in a wooden box. → Bà tôi cất chiếc nhẫn vàng trong một chiếc hộp gỗ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_20_1_2', 'en-a2-20', 'ten_a2_20_1', 'listening', 'listening', 'I found a euro in my coat pocket today.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi giữ một ít tiền mặt trong ví để phòng khi khẩn cấp.","Tiệm bánh đã tăng giá thêm một lần nữa trong tuần này.","Hồ bơi có giá năm bảng Anh cho mỗi lượt vào cửa.","Hôm nay tôi tìm thấy một đồng euro trong túi áo khoác của mình."]'::jsonb, 3, 'I found a euro in my coat pocket today. → Hôm nay tôi tìm thấy một đồng euro trong túi áo khoác của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_20_1_3', 'en-a2-20', 'ten_a2_20_1', 'listening', 'listening', 'A silver coin rolled under the kitchen table.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã trả một bảng Anh cho túi táo này.","Tổng chi phí đã bao gồm bữa sáng và một vé xe buýt.","Tôi đã tiết kiệm được hai mươi phần trăm khi mua chiếc áo khoác mùa đông mới.","Một đồng tiền xu bằng bạc lăn xuống dưới gầm bàn bếp."]'::jsonb, 3, 'A silver coin rolled under the kitchen table. → Một đồng tiền xu bằng bạc lăn xuống dưới gầm bàn bếp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_20_2', 'en-a2-20', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_20_2_1', 'ten_a2_20_2', 'gold', 'Demand for gold can increase during economic uncertainty, as investors seek assets they consider relatively safe.', 'Demand for gold can increase during economic uncertainty, as investors seek assets they consider relatively safe.', '/ɡoʊld/', 'Nhu cầu về vàng có thể tăng lên trong thời kỳ bất ổn kinh tế khi các nhà đầu tư tìm kiếm tài sản mà họ cho là tương đối an toàn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_20_2_2', 'ten_a2_20_2', 'euro', 'Using the euro allows tourists to visit several European countries without exchanging money at each border.', 'Using the euro allows tourists to visit several European countries without exchanging money at each border.', '/ˈjʊroʊ/', 'Việc sử dụng đồng euro cho phép khách du lịch tham quan nhiều nước châu Âu mà không cần đổi tiền ở mỗi biên giới.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_20_2_3', 'ten_a2_20_2', 'coin', 'As digital payments become more widespread, fewer consumers carry coins for everyday purchases such as bus fares.', 'As digital payments become more widespread, fewer consumers carry coins for everyday purchases such as bus fares.', '/kɔɪn/', 'Khi thanh toán kỹ thuật số ngày càng trở nên phổ biến, ít người tiêu dùng mang theo tiền xu cho các giao dịch mua sắm hàng ngày như tiền vé xe buýt hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_20_2_4', 'ten_a2_20_2', 'product', 'Consumers increasingly prefer products that use less packaging and can be repaired rather than replaced.', 'Consumers increasingly prefer products that use less packaging and can be repaired rather than replaced.', '/ˈprɑːdʌkt/', 'Người tiêu dùng ngày càng ưua chuộng các sản phẩm ít bao bì hơn và có thể sửa chữa thay vì phải vứt bỏ mua mới.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_20_2_5', 'ten_a2_20_2', 'percent', 'Nearly forty percent of surveyed residents supported investing more public money in cycling infrastructure.', 'Nearly forty percent of surveyed residents supported investing more public money in cycling infrastructure.', '/pərˈsent/', 'Gần bốn mươi phần trăm cư dân được khảo sát ủng hộ việc đầu tư nhiều ngân sách công hơn vào cơ sở hạ tầng dành cho xe đạp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_20_2_6', 'ten_a2_20_2', 'total', 'Improving home insulation can reduce total energy consumption while making housing more comfortable throughout the year.', 'Improving home insulation can reduce total energy consumption while making housing more comfortable throughout the year.', '/ˈtoʊtəl/', 'Cải thiện khả năng cách nhiệt của ngôi nhà có thể làm giảm tổng năng lượng tiêu thụ đồng thời giúp không gian sống thoải mái hơn quanh năm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_20_2_1', 'en-a2-20', 'ten_a2_20_2', 'listening', 'listening', 'Demand for gold can increase during economic uncertainty, as investors seek assets they consider relatively safe.', NULL, 'Trong câu vừa nghe, từ “gold” mang nghĩa nào sau đây?', '["vàng; kim loại vàng","thuộc về Ấn Độ hoặc người Ấn Độ","trừ ra; ngoại trừ","ki-lô-mét, cây số"]'::jsonb, 0, '“gold” (/ɡoʊld/): vàng; kim loại vàng. Câu đầy đủ: Demand for gold can increase during economic uncertainty, as investors seek assets they consider relatively safe.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_20_2_2', 'en-a2-20', 'ten_a2_20_2', 'listening', 'listening', 'Using the euro allows tourists to visit several European countries without exchanging money at each border.', NULL, 'Trong câu vừa nghe, từ “euro” mang nghĩa nào sau đây?', '["chấp nhận; đồng ý nhận","cái lỗ; hố; kẽ hở","đồng euro","đi bộ đường dài; leo núi; đi dã ngoại (đi dạo dài ở ngoài trời, đặc biệt là vùng nông thôn)"]'::jsonb, 2, '“euro” (/ˈjʊroʊ/): đồng euro. Câu đầy đủ: Using the euro allows tourists to visit several European countries without exchanging money at each border.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
