INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_20_2', 'en-a2-20', NULL, 'comprehensive_test', 'listening', 'I found a euro in my coat pocket today.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Không khí ấm áp bốc lên phía trên lò sưởi cạnh bàn làm việc của tôi.","Hôm nay tôi tìm thấy một đồng euro trong túi áo khoác của mình.","Tôi đã tiết kiệm được hai mươi phần trăm khi mua chiếc áo khoác mùa đông mới.","Tổng chi phí đã bao gồm bữa sáng và một vé xe buýt."]'::jsonb, 1, 'I found a euro in my coat pocket today. → Hôm nay tôi tìm thấy một đồng euro trong túi áo khoác của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
