INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_20_18', 'en-a2-20', NULL, 'comprehensive_test', 'reading', NULL, 'Demand for gold can increase during economic uncertainty, as investors seek assets they consider relatively safe.', 'Dựa vào câu trên, từ “gold” có nghĩa phù hợp nhất là gì?', '["vàng; kim loại vàng","hài kịch; phim hài","cộng sự; đối tác; người cùng chơi","thứ mười"]'::jsonb, 0, 'gold: vàng; kim loại vàng; huy chương vàng; bằng vàng; có màu vàng óng. Dịch cả câu: Nhu cầu về vàng có thể tăng lên trong thời kỳ bất ổn kinh tế khi các nhà đầu tư tìm kiếm tài sản mà họ cho là tương đối an toàn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_20_19', 'en-a2-20', NULL, 'comprehensive_test', 'reading', NULL, 'Using the euro allows tourists to visit several European countries without exchanging money at each border.', 'Dựa vào câu trên, từ “euro” có nghĩa phù hợp nhất là gì?', '["đồng euro","hoàn hảo; lý tưởng","thìa; muỗng","hài kịch; phim hài"]'::jsonb, 0, 'euro: đồng euro. Dịch cả câu: Việc sử dụng đồng euro cho phép khách du lịch tham quan nhiều nước châu Âu mà không cần đổi tiền ở mỗi biên giới.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_20_20', 'en-a2-20', NULL, 'comprehensive_test', 'reading', NULL, 'As digital payments become more widespread, fewer consumers carry coins for everyday purchases such as bus fares.', 'Dựa vào câu trên, từ “coin” có nghĩa phù hợp nhất là gì?', '["quần đùi; quần sọc","chắc chắn; dứt khoát; rạch ròi","tiền xu","kiểu tóc; tạo hình tóc"]'::jsonb, 2, 'coin: tiền xu; tạo ra từ mới; đặt ra thuật ngữ. Dịch cả câu: Khi thanh toán kỹ thuật số ngày càng trở nên phổ biến, ít người tiêu dùng mang theo tiền xu cho các giao dịch mua sắm hàng ngày như tiền vé xe buýt hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_20_21', 'en-a2-20', NULL, 'comprehensive_test', 'reading', NULL, 'Consumers increasingly prefer products that use less packaging and can be repaired rather than replaced.', 'Dựa vào câu trên, từ “product” có nghĩa phù hợp nhất là gì?', '["sản phẩm; hàng hóa","tình hình; hoàn cảnh; tình thế","cuối cùng","hủy bỏ; bãi bỏ; hoãn"]'::jsonb, 0, 'product: sản phẩm; hàng hóa; hệ quả; tích (toán học). Dịch cả câu: Người tiêu dùng ngày càng ưua chuộng các sản phẩm ít bao bì hơn và có thể sửa chữa thay vì phải vứt bỏ mua mới.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_20_22', 'en-a2-20', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đồng bảng Anh (đơn vị tiền tệ chính của Vương quốc Anh)”', '["pound","nail","attend","excellent"]'::jsonb, 0, 'đồng bảng Anh (đơn vị tiền tệ chính của Vương quốc Anh) → pound (/paʊnd/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_20_23', 'en-a2-20', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “tăng lên; dâng lên; lên cao”', '["spoon","nature","rise","blog"]'::jsonb, 2, 'tăng lên; dâng lên; lên cao → rise (/raɪz/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
