INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-21', 'en', 'Bài 21: Đô thị & Kiến trúc (1) - CEFR A2', 'CEFR A2', 'A2 · Đô thị', '17 từ vựng Tiếng Anh CEFR A2 chủ đề đô thị & kiến trúc kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2021, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_space', 'en-a2-21', 'space', '/speɪs/', 'A2', 'không gian; khoảng trống; chỗ; vũ trụ; không gian bên ngoài; sắp xếp có khoảng cách', 'n.', 'spacious (adj.), spacing (n.)', 'Đồng nghĩa: room, gap', 'Từ "space" là danh từ không đếm được khi mang nghĩa không gian chung hoặc vũ trụ, nhưng đếm được khi chỉ các không gian cụ thể như chỗ đậu xe.', 'There is enough space for your bike beside mine.', NULL, 'Vẫn còn đủ chỗ cho chiếc xe đạp của bạn ở bên cạnh xe của tôi.', '{"wordId":"space","ukIpa":"/speɪs/","usIpa":"/speɪs/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"Room available for something, or a gap between things","vi":"không gian; khoảng trống; chỗ"},{"pos":"n.","en":"The vast area beyond Earth''s atmosphere","vi":"vũ trụ; không gian bên ngoài"},{"pos":"v.","en":"To arrange things with gaps between them","vi":"sắp xếp có khoảng cách"}],"examples":[{"en":"There is enough space for your bike beside mine.","vi":"Vẫn còn đủ chỗ cho chiếc xe đạp của bạn ở bên cạnh xe của tôi.","audioKind":"ex"},{"en":"Providing more green space in crowded neighbourhoods can improve residents'' wellbeing and encourage outdoor physical activity.","vi":"Việc tạo ra nhiều không gian xanh hơn ở các khu dân cư đông đúc có thể cải thiện sức khỏe của cư dân và khuyến khích các hoạt động thể chất ngoài trời.","audioKind":"ex2"}],"collocations":[{"en":"green space","vi":"không gian xanh"},{"en":"outer space","vi":"vũ trụ bao la"},{"en":"parking space","vi":"chỗ đậu xe"},{"en":"space exploration","vi":"khám phá không gian"}],"wordFamily":["spacious (adj.)","spacing (n.)"],"synonyms":["room","gap"],"antonyms":[],"tipVi":"Từ \"space\" là danh từ không đếm được khi mang nghĩa không gian chung hoặc vũ trụ, nhưng đếm được khi chỉ các không gian cụ thể như chỗ đậu xe.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_underground', 'en-a2-21', 'underground', '/ˌʌndərˈɡraʊnd/', 'A2', 'ở dưới lòng đất; ngầm; hoạt động bí mật; ở dưới mặt đất; một cách bí mật; hệ thống tàu điện ngầm', 'adj.', NULL, 'Trái nghĩa: above ground', 'Danh từ chỉ tàu điện ngầm chủ yếu dùng trong tiếng Anh-Anh, với trọng âm rơi vào âm tiết đầu tiên.', 'We left our car in an underground garage.', NULL, 'Chúng tôi đã đỗ xe ở bãi đỗ xe ngầm.', '{"wordId":"underground","ukIpa":"/ˌʌndəˈɡraʊnd/","usIpa":"/ˌʌndərˈɡraʊnd/","cefr":"A2","topic":"city","senses":[{"pos":"adj.","en":"Below the ground, or operating secretly.","vi":"ở dưới lòng đất; ngầm; hoạt động bí mật"},{"pos":"adv.","en":"Below the ground, or in a hidden, secret way.","vi":"ở dưới mặt đất; một cách bí mật"},{"pos":"n.","en":"A railway system running mainly beneath a city.","vi":"hệ thống tàu điện ngầm"}],"examples":[{"en":"We left our car in an underground garage.","vi":"Chúng tôi đã đỗ xe ở bãi đỗ xe ngầm.","audioKind":"ex"},{"en":"Underground transport systems can ease congestion, although constructing tunnels requires substantial investment and careful planning.","vi":"Hệ thống giao thông ngầm có thể làm giảm tình trạng ùn tắc, dẫu cho việc xây dựng các đường hầm đòi hỏi nguồn vốn đầu tư lớn cùng kế hoạch chu đáo.","audioKind":"ex2"}],"collocations":[{"en":"underground station","vi":"ga tàu điện ngầm"},{"en":"underground car park","vi":"bãi đỗ xe ngầm"},{"en":"travel underground","vi":"di chuyển bằng đường ngầm"},{"en":"go underground","vi":"hoạt động bí mật; chuyển vào hoạt động ngầm"}],"wordFamily":[],"synonyms":[],"antonyms":["above ground"],"tipVi":"Danh từ chỉ tàu điện ngầm chủ yếu dùng trong tiếng Anh-Anh, với trọng âm rơi vào âm tiết đầu tiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_metro', 'en-a2-21', 'metro', '/ˈmetroʊ/', 'A2', 'tàu điện ngầm; hệ thống tàu điện ngầm', 'n.', NULL, 'Đồng nghĩa: subway, underground', 'metro không giới hạn ở Pháp; đi tàu điện ngầm thường dùng take the metro.', 'We took the metro to the museum this morning.', NULL, 'Sáng nay chúng tôi đã đi tàu điện ngầm đến bảo tàng.', '{"wordId":"metro","ukIpa":"/ˈmetrəʊ/","usIpa":"/ˈmetroʊ/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"An urban railway system that often runs underground.","vi":"tàu điện ngầm; hệ thống tàu điện ngầm"}],"examples":[{"en":"We took the metro to the museum this morning.","vi":"Sáng nay chúng tôi đã đi tàu điện ngầm đến bảo tàng.","audioKind":"ex"},{"en":"Expanding the metro could reduce traffic congestion by providing residents with a reliable alternative to private cars.","vi":"Việc mở rộng hệ thống tàu điện ngầm có thể giúp giảm ùn tắc giao thông bằng cách cung cấp cho người dân một phương án thay thế đáng tin cậy cho xe cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"take the metro","vi":"đi tàu điện ngầm"},{"en":"metro station","vi":"ga tàu điện ngầm"},{"en":"metro line","vi":"tuyến tàu điện ngầm"},{"en":"metro network","vi":"mạng lưới tàu điện ngầm"}],"wordFamily":[],"synonyms":["subway","underground"],"antonyms":[],"tipVi":"metro không giới hạn ở Pháp; đi tàu điện ngầm thường dùng take the metro.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hometown', 'en-a2-21', 'hometown', '/ˈhoʊmtaʊn/', 'A2', 'quê hương, thị trấn hoặc thành phố nơi lớn lên hoặc xuất thân', 'n.', 'home (n.)', NULL, 'Có thể chỉ thị trấn nhỏ hoặc thành phố lớn, không nhất thiết phải là nơi sinh ra.', 'I return to my hometown every summer to visit relatives.', NULL, 'Tôi trở về quê hương vào mỗi mùa hè để thăm họ hàng.', '{"wordId":"hometown","ukIpa":"/ˈhəʊmtaʊn/","usIpa":"/ˈhoʊmtaʊn/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"The town or city where you grew up or come from.","vi":"quê hương, thị trấn hoặc thành phố nơi lớn lên hoặc xuất thân"}],"examples":[{"en":"I return to my hometown every summer to visit relatives.","vi":"Tôi trở về quê hương vào mỗi mùa hè để thăm họ hàng.","audioKind":"ex"},{"en":"Many graduates leave their hometown to seek better employment opportunities in larger urban centres.","vi":"Nhiều sinh viên tốt nghiệp rời bỏ quê hương để tìm kiếm cơ hội việc làm tốt hơn tại các trung tâm đô thị lớn hơn.","audioKind":"ex2"}],"collocations":[{"en":"return to your hometown","vi":"trở về quê hương"},{"en":"leave your hometown","vi":"rời xa quê hương"},{"en":"hometown residents","vi":"người dân quê nhà"}],"wordFamily":["home (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ thị trấn nhỏ hoặc thành phố lớn, không nhất thiết phải là nơi sinh ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_downtown', 'en-a2-21', 'downtown', '/ˌdaʊnˈtaʊn/', 'A2', 'ở hoặc hướng về khu trung tâm thương mại của thành phố; thuộc khu trung tâm thương mại của thành phố; khu trung tâm thương mại của thành phố', 'adv.', NULL, NULL, 'Chủ yếu được dùng trong tiếng Anh-Mỹ; khi làm trạng từ thì phía trước không đi kèm giới từ to.', 'We took the bus downtown to buy new shoes.', NULL, 'Chúng tôi đã bắt xe buýt vào trung tâm thành phố để mua giày mới.', '{"wordId":"downtown","ukIpa":"/ˌdaʊnˈtaʊn/","usIpa":"/ˌdaʊnˈtaʊn/","cefr":"A2","topic":"city","senses":[{"pos":"adv.","en":"in or towards the central business area of a city","vi":"ở hoặc hướng về khu trung tâm thương mại của thành phố"},{"pos":"adj.","en":"located in the central business area of a city","vi":"thuộc khu trung tâm thương mại của thành phố"},{"pos":"n.","en":"the central business area of a city","vi":"khu trung tâm thương mại của thành phố"}],"examples":[{"en":"We took the bus downtown to buy new shoes.","vi":"Chúng tôi đã bắt xe buýt vào trung tâm thành phố để mua giày mới.","audioKind":"ex"},{"en":"Improved public transport can encourage more residents to shop downtown rather than drive to suburban shopping centres.","vi":"Việc cải thiện giao thông công cộng có thể khuyến khích nhiều cư dân mua sắm ở trung tâm thành phố hơn là lái xe đến các trung tâm mua sắm ngoại ô.","audioKind":"ex2"}],"collocations":[{"en":"go downtown","vi":"đi vào trung tâm thành phố"},{"en":"downtown area","vi":"khu vực trung tâm"},{"en":"downtown shops","vi":"các cửa hàng ở trung tâm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chủ yếu được dùng trong tiếng Anh-Mỹ; khi làm trạng từ thì phía trước không đi kèm giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_apartment', 'en-a2-21', 'apartment', '/əˈpɑːrtmənt/', 'A2', 'căn hộ; nhà chung cư', 'n.', NULL, 'Đồng nghĩa: flat', 'Tiếng Mỹ thường dùng apartment, trong khi tiếng Anh - Anh thường dùng flat trong đời sống hàng ngày.', 'Our apartment has a small balcony overlooking the park.', NULL, 'Căn hộ của chúng tôi có một ban công nhỏ nhìn ra công việc.', '{"wordId":"apartment","ukIpa":"/əˈpɑːtmənt/","usIpa":"/əˈpɑːrtmənt/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"A set of rooms forming one home within a building.","vi":"căn hộ; nhà chung cư"}],"examples":[{"en":"Our apartment has a small balcony overlooking the park.","vi":"Căn hộ của chúng tôi có một ban công nhỏ nhìn ra công việc.","audioKind":"ex"},{"en":"Building affordable apartments near railway stations can reduce commuting costs for young workers.","vi":"Việc xây dựng các căn hộ có giá cả phải chăng gần các nhà ga xe lửa có thể giảm chi phí đi lại cho các nhân viên trẻ tuổi.","audioKind":"ex2"}],"collocations":[{"en":"rent an apartment","vi":"thuê căn hộ"},{"en":"apartment block","vi":"tòa nhà chung cư"},{"en":"studio apartment","vi":"căn hộ studio"}],"wordFamily":[],"synonyms":["flat"],"antonyms":[],"tipVi":"Tiếng Mỹ thường dùng apartment, trong khi tiếng Anh - Anh thường dùng flat trong đời sống hàng ngày.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bridge', 'en-a2-21', 'bridge', '/brɪdʒ/', 'A2', 'cây cầu; cầu đường; thu hẹp khoảng cách; khắc phục; trò chơi bài cầu phỉnh (bridge)', 'n.', 'bridging (adj.)', NULL, 'Cụm bridge the gap thường dùng để chỉ việc thu hẹp sự khác biệt giữa các nhóm người hoặc sự vật.', 'We crossed the wooden bridge and entered the village.', NULL, 'Chúng tôi đi qua chiếc cầu gỗ và bước vào làng.', '{"wordId":"bridge","ukIpa":"/brɪdʒ/","usIpa":"/brɪdʒ/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"A structure carrying people or vehicles over an obstacle.","vi":"cây cầu; cầu đường"},{"pos":"v.","en":"To connect separated things or reduce differences between them.","vi":"thu hẹp khoảng cách; khắc phục"},{"pos":"n.","en":"A card game played by four people in two partnerships.","vi":"trò chơi bài cầu phỉnh (bridge)"}],"examples":[{"en":"We crossed the wooden bridge and entered the village.","vi":"Chúng tôi đi qua chiếc cầu gỗ và bước vào làng.","audioKind":"ex"},{"en":"Community language programmes can bridge cultural differences and help newcomers participate more fully in local life.","vi":"Các chương trình ngôn ngữ cộng đồng có thể thu hẹp khoảng cách văn hóa và giúp những người mới đến hòa nhập đầy đủ hơn vào cuộc sống địa phương.","audioKind":"ex2"}],"collocations":[{"en":"cross a bridge","vi":"đi qua cầu"},{"en":"suspension bridge","vi":"cầu treo"},{"en":"bridge the gap","vi":"thu hẹp khoảng cách"},{"en":"play bridge","vi":"đánh bài cầu phỉnh"}],"wordFamily":["bridging (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm bridge the gap thường dùng để chỉ việc thu hẹp sự khác biệt giữa các nhóm người hoặc sự vật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_built', 'en-a2-21', 'built', '/bɪlt/', 'A2', 'xây dựng; kiến thiết (dạng quá khứ và quá khứ phân từ của build); có vóc dáng; có thể hình', 'v.', 'build (v.), builder (n.), building (n.), rebuild (v.)', NULL, 'Dạng quá khứ và quá khứ phân từ của build là built, không phải builded.', 'We built a small shelter for the garden tools.', NULL, 'Chúng tôi đã dựng một nhà kho nhỏ cho các dụng cụ làm vườn.', '{"wordId":"built","ukIpa":"/bɪlt/","usIpa":"/bɪlt/","cefr":"A2","topic":"city","senses":[{"pos":"v.","en":"past tense and past participle of build","vi":"xây dựng; kiến thiết (dạng quá khứ và quá khứ phân từ của build)"},{"pos":"adj.","en":"having a particular body shape or physical build","vi":"có vóc dáng; có thể hình"}],"examples":[{"en":"We built a small shelter for the garden tools.","vi":"Chúng tôi đã dựng một nhà kho nhỏ cho các dụng cụ làm vườn.","audioKind":"ex"},{"en":"New homes should be built near public transport to reduce residents'' dependence on private cars.","vi":"Các ngôi nhà mới nên được xây dựng gần các phương tiện giao thông công cộng để giảm sự phụ thuộc của cư dân vào xe cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"built to last","vi":"bền vững với thời gian"},{"en":"well built","vi":"vạm vỡ; được xây dựng chắc chắn"},{"en":"built environment","vi":"môi trường nhân tạo"},{"en":"purpose-built facilities","vi":"cơ sở vật chất được xây dựng chuyên dụng"}],"wordFamily":["build (v.)","builder (n.)","building (n.)","rebuild (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ của build là built, không phải builded.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_parking', 'en-a2-21', 'parking', '/ˈpɑːrkɪŋ/', 'A2', 'việc đỗ xe; sự đậu xe; chỗ đỗ xe; bãi đỗ xe', 'n.', 'park (v.), parked (adj.)', NULL, 'Danh từ này thường không đếm được; để chỉ một chỗ đỗ xe cụ thể, hãy dùng "a parking space".', 'Parking is difficult on this narrow street after sunset.', NULL, 'Việc đỗ xe rất khó khăn trên con đường chật hẹp này sau khi mặt trời lặn.', '{"wordId":"parking","ukIpa":"/ˈpɑːkɪŋ/","usIpa":"/ˈpɑːrkɪŋ/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"The act of leaving a vehicle in a particular place.","vi":"việc đỗ xe; sự đậu xe"},{"pos":"n.","en":"Space or facilities where vehicles can be left.","vi":"chỗ đỗ xe; bãi đỗ xe"}],"examples":[{"en":"Parking is difficult on this narrow street after sunset.","vi":"Việc đỗ xe rất khó khăn trên con đường chật hẹp này sau khi mặt trời lặn.","audioKind":"ex"},{"en":"Reducing free parking in city centres may encourage commuters to use public transport more frequently.","vi":"Việc cắt giảm chỗ đỗ xe miễn phí ở các trung tâm thành phố có thể khuyến khích những người đi làm thường xuyên sử dụng phương tiện công cộng hơn.","audioKind":"ex2"}],"collocations":[{"en":"a parking space","vi":"chỗ đỗ xe"},{"en":"parking restrictions","vi":"quy định hạn chế đỗ xe"},{"en":"free parking","vi":"đỗ xe miễn phí"},{"en":"underground parking","vi":"bãi đỗ xe ngầm"}],"wordFamily":["park (v.)","parked (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ này thường không đếm được; để chỉ một chỗ đỗ xe cụ thể, hãy dùng \"a parking space\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mall', 'en-a2-21', 'mall', '/mɔːl/', 'A2', 'trung tâm thương mại', 'n.', NULL, 'Đồng nghĩa: shopping centre', 'mall thường được dùng trong tiếng Anh-Mỹ; tiếng Anh-Anh thường dùng shopping centre.', 'We spent the rainy afternoon browsing in the mall.', NULL, 'Chúng tôi đã dành cả buổi chiều mưa để đi dạo trong trung tâm thương mại.', '{"wordId":"mall","ukIpa":"/mɔːl/","usIpa":"/mɔːl/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"a large building or complex containing many shops","vi":"trung tâm thương mại"}],"examples":[{"en":"We spent the rainy afternoon browsing in the mall.","vi":"Chúng tôi đã dành cả buổi chiều mưa để đi dạo trong trung tâm thương mại.","audioKind":"ex"},{"en":"A new shopping mall may create jobs, but it can also threaten small independent retailers.","vi":"Một trung tâm mua sắm mới có thể tạo ra việc làm, nhưng nó cũng có thể đe dọa các tiểu thương độc lập.","audioKind":"ex2"}],"collocations":[{"en":"shopping mall","vi":"trung tâm mua sắm"},{"en":"indoor mall","vi":"trung tâm thương mại trong nhà"},{"en":"mall entrance","vi":"lối vào trung tâm thương mại"}],"wordFamily":[],"synonyms":["shopping centre"],"antonyms":[],"tipVi":"mall thường được dùng trong tiếng Anh-Mỹ; tiếng Anh-Anh thường dùng shopping centre.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hall', 'en-a2-21', 'hall', '/hɔːl/', 'A2', 'tiền sảnh; hành lang; phòng lớn; hội trường; nhà lớn; ký túc xá sinh viên', 'n.', 'hallway (n.)', NULL, 'Trong tiếng Anh-Anh, ký túc xá đại học thường gọi là halls hoặc halls of residence.', 'Please leave your wet shoes in the hall.', NULL, 'Xin hãy để đôi giày ướt của bạn ở ngoài tiền sảnh.', '{"wordId":"hall","ukIpa":"/hɔːl/","usIpa":"/hɔːl/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"an entrance area or passage connecting rooms in a building","vi":"tiền sảnh; hành lang"},{"pos":"n.","en":"a large room or building used for public gatherings","vi":"phòng lớn; hội trường; nhà lớn"},{"pos":"n.","en":"a building where university students live","vi":"ký túc xá sinh viên"}],"examples":[{"en":"Please leave your wet shoes in the hall.","vi":"Xin hãy để đôi giày ướt của bạn ở ngoài tiền sảnh.","audioKind":"ex"},{"en":"The community hall provides an affordable space where residents can attend classes and organise local events.","vi":"Nhà văn hóa cộng đồng cung cấp một không gian giá cả phải chăng để cư dân có thể tham gia các lớp học và tổ chức các sự kiện địa phương.","audioKind":"ex2"}],"collocations":[{"en":"an entrance hall","vi":"tiền sảnh"},{"en":"a concert hall","vi":"phòng hòa nhạc"},{"en":"a town hall","vi":"tòa thị chính"},{"en":"halls of residence","vi":"ký túc xá trường đại học"}],"wordFamily":["hallway (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, ký túc xá đại học thường gọi là halls hoặc halls of residence.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rent', 'en-a2-21', 'rent', '/rent/', 'A2', 'tiền thuê nhà; tiền thuê; thuê; mướn; cho thuê', 'n.', 'rental (n.), renter (n.)', NULL, 'rent có thể chỉ hành động thuê vào hoặc cho thuê; dùng rent out để nhấn mạnh ý nghĩa cho thuê.', 'My monthly rent includes water but not electricity.', NULL, 'Tiền thuê nhà hàng tháng của tôi đã bao gồm tiền nước nhưng chưa gồm tiền điện.', '{"wordId":"rent","ukIpa":"/rent/","usIpa":"/rent/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"money paid regularly to use someone else''s property","vi":"tiền thuê nhà; tiền thuê"},{"pos":"v.","en":"to pay to use something owned by someone else","vi":"thuê; mướn"},{"pos":"v.","en":"to let someone use your property in exchange for payment","vi":"cho thuê"}],"examples":[{"en":"My monthly rent includes water but not electricity.","vi":"Tiền thuê nhà hàng tháng của tôi đã bao gồm tiền nước nhưng chưa gồm tiền điện.","audioKind":"ex"},{"en":"Rising rents in urban areas can force essential workers to live further from their workplaces.","vi":"Tiền thuê nhà tăng cao ở các khu đô thị có thể buộc những người lao động thiết yếu phải sống xa nơi làm việc hơn.","audioKind":"ex2"}],"collocations":[{"en":"pay rent","vi":"trả tiền thuê nhà"},{"en":"rent a flat","vi":"thuê một căn hộ"},{"en":"rent out a room","vi":"cho thuê một căn phòng"},{"en":"monthly rent","vi":"tiền thuê nhà hàng tháng"}],"wordFamily":["rental (n.)","renter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"rent có thể chỉ hành động thuê vào hoặc cho thuê; dùng rent out để nhấn mạnh ý nghĩa cho thuê.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tower', 'en-a2-21', 'tower', '/ˈtaʊər/', 'A2', 'tháp; tòa tháp; cao vút; đứng cao vượt hẳn lên so với xung quanh', 'n.', 'towering (adj.)', NULL, 'Khi đóng vai trò là động từ, từ này thường đi với over hoặc above để diễn tả ý cao vượt hẳn lên so với môi trường xung quanh.', 'We climbed the tower and watched boats cross the bay.', NULL, 'Chúng tôi trèo lên tháp và ngắm nhìn những chiếc thuyền băng qua vịnh.', '{"wordId":"tower","ukIpa":"/ˈtaʊə/","usIpa":"/ˈtaʊər/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"a tall, narrow structure, standing alone or on a building","vi":"tháp; tòa tháp"},{"pos":"v.","en":"rise much higher than nearby people or things","vi":"cao vút; đứng cao vượt hẳn lên so với xung quanh"}],"examples":[{"en":"We climbed the tower and watched boats cross the bay.","vi":"Chúng tôi trèo lên tháp và ngắm nhìn những chiếc thuyền băng qua vịnh.","audioKind":"ex"},{"en":"The historic tower attracts visitors throughout the year, providing valuable income for nearby shops and restaurants.","vi":"Ngọn tháp lịch sử thu hút du khách quanh năm, mang lại nguồn thu nhập quý giá cho các cửa hàng và nhà hàng gần đó.","audioKind":"ex2"}],"collocations":[{"en":"a clock tower","vi":"tháp đồng hồ"},{"en":"a watch tower","vi":"tháp canh"},{"en":"tower above","vi":"cao vút lên trên"},{"en":"tower over","vi":"vượt trội hẳn lên"}],"wordFamily":["towering (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi đóng vai trò là động từ, từ này thường đi với over hoặc above để diễn tả ý cao vượt hẳn lên so với môi trường xung quanh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_postbox', 'en-a2-21', 'postbox', '/ˈpoʊstbɑːks/', 'A2', 'hòm thư công cộng; thùng thư bưu điện', 'n.', 'post (n.), postal (adj.)', 'Đồng nghĩa: letterbox, mailbox', 'Trong tiếng Anh - Anh, postbox chỉ hòm thư công cộng để gửi thư; người Mỹ thường dùng từ mailbox.', 'I dropped the birthday card into the postbox outside.', NULL, 'Tôi đã thả tấm bưu thiếp chúc mừng sinh nhật vào hòm thư ở bên ngoài.', '{"wordId":"postbox","ukIpa":"/ˈpəʊstbɒks/","usIpa":"/ˈpoʊstbɑːks/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"A public box where people put mail to be collected.","vi":"hòm thư công cộng; thùng thư bưu điện"}],"examples":[{"en":"I dropped the birthday card into the postbox outside.","vi":"Tôi đã thả tấm bưu thiếp chúc mừng sinh nhật vào hòm thư ở bên ngoài.","audioKind":"ex"},{"en":"Keeping a postbox within walking distance helps residents without internet access maintain contact with essential services.","vi":"Việc đặt một hòm thư ở khoảng cách có thể đi bộ tới giúp cho những cư dân không có internet duy trì liên lạc với các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"nearest postbox","vi":"hòm thư gần nhất"},{"en":"put something in a postbox","vi":"bỏ vật gì vào hòm thư"}],"wordFamily":["post (n.)","postal (adj.)"],"synonyms":["letterbox","mailbox"],"antonyms":[],"tipVi":"Trong tiếng Anh - Anh, postbox chỉ hòm thư công cộng để gửi thư; người Mỹ thường dùng từ mailbox.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_neighbourhood', 'en-a2-21', 'neighbourhood', '/ˈneɪbɚhʊd/', 'A2', 'khu phố; vùng lân cận; xóm giềng; cộng đồng cư dân', 'n.', 'neighbour (n.), neighbourly (adj.), neighbouring (adj.)', 'Đồng nghĩa: local area', 'Cách viết Anh-Anh là neighbourhood, còn Anh-Mỹ là neighborhood.', 'A small bakery has just opened in our neighbourhood.', NULL, 'Một tiệm bánh nhỏ vừa mới mở trong khu phố nhà chúng tôi.', '{"wordId":"neighbourhood","ukIpa":"/ˈneɪbəhʊd/","usIpa":"/ˈneɪbɚhʊd/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"An area around people''s homes within a town or city.","vi":"khu phố; vùng lân cận"},{"pos":"n.","en":"The people living in a particular local area.","vi":"xóm giềng; cộng đồng cư dân"}],"examples":[{"en":"A small bakery has just opened in our neighbourhood.","vi":"Một tiệm bánh nhỏ vừa mới mở trong khu phố nhà chúng tôi.","audioKind":"ex"},{"en":"Investing in neighbourhood parks can improve residents'' health while creating opportunities for people to meet and socialise.","vi":"Đầu tư vào các công viên khu phố có thể cải thiện sức khỏe cư dân đồng thời tạo cơ hội cho mọi người gặp gỡ và giao lưu.","audioKind":"ex2"}],"collocations":[{"en":"a quiet neighbourhood","vi":"khu phố yên tĩnh"},{"en":"in the neighbourhood","vi":"ở vùng lân cận"},{"en":"a residential neighbourhood","vi":"khu dân cư"}],"wordFamily":["neighbour (n.)","neighbourly (adj.)","neighbouring (adj.)"],"synonyms":["local area"],"antonyms":[],"tipVi":"Cách viết Anh-Anh là neighbourhood, còn Anh-Mỹ là neighborhood.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nearest', 'en-a2-21', 'nearest', '/ˈnɪrɪst/', 'A2', 'gần nhất (về khoảng cách, thời gian hoặc sự tương đồng); ở khoảng cách gần nhất', 'adj.', 'near (adj.), nearly (adv.), nearness (n.)', 'Đồng nghĩa: closest · Trái nghĩa: farthest, furthest', 'Là dạng so sánh hơn nhất của near; khi làm định ngữ thường dùng the nearest.', 'Could you show me the way to the nearest pharmacy?', NULL, 'Bạn có thể chỉ cho tôi đường đến hiệu thuốc gần nhất được không?', '{"wordId":"nearest","ukIpa":"/ˈnɪərɪst/","usIpa":"/ˈnɪrɪst/","cefr":"A2","topic":"city","senses":[{"pos":"adj.","en":"Closest in distance, time, or similarity","vi":"gần nhất (về khoảng cách, thời gian hoặc sự tương đồng)"},{"pos":"adv.","en":"At the shortest distance from someone or something","vi":"ở khoảng cách gần nhất"}],"examples":[{"en":"Could you show me the way to the nearest pharmacy?","vi":"Bạn có thể chỉ cho tôi đường đến hiệu thuốc gần nhất được không?","audioKind":"ex"},{"en":"For many rural residents, the nearest hospital is several hours away, making access to emergency care difficult.","vi":"Đối với nhiều cư dân nông thôn, bệnh viện gần nhất cách đó vài giờ di chuyển, khiến việc tiếp cận dịch vụ chăm sóc cấp cứu trở nên khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"nearest hospital","vi":"bệnh viện gần nhất"},{"en":"nearest neighbour","vi":"hàng xóm gần nhất"},{"en":"nearest available","vi":"gần nhất có sẵn"},{"en":"to the nearest kilometre","vi":"làm tròn đến kilômét gần nhất"}],"wordFamily":["near (adj.)","nearly (adv.)","nearness (n.)"],"synonyms":["closest"],"antonyms":["farthest","furthest"],"tipVi":"Là dạng so sánh hơn nhất của near; khi làm định ngữ thường dùng the nearest.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nearby', 'en-a2-21', 'nearby', '/ˌnɪrˈbaɪ/', 'A2', 'ở gần; lân cận; ở gần đó; ngay bên cạnh', 'adj.', NULL, 'Đồng nghĩa: close by, adjacent · Trái nghĩa: far away', 'Không dùng "nearby" làm giới từ: phải dùng "near the school" thay vì "nearby the school".', 'We bought fresh bread from a nearby bakery.', NULL, 'Chúng tôi mua bánh mỳ tươi từ một cửa hàng bánh gần nhà.', '{"wordId":"nearby","ukIpa":"/ˌnɪəˈbaɪ/","usIpa":"/ˌnɪrˈbaɪ/","cefr":"A2","topic":"city","senses":[{"pos":"adj.","en":"located a short distance away","vi":"ở gần; lân cận"},{"pos":"adv.","en":"at or to a place a short distance away","vi":"ở gần đó; ngay bên cạnh"}],"examples":[{"en":"We bought fresh bread from a nearby bakery.","vi":"Chúng tôi mua bánh mỳ tươi từ một cửa hàng bánh gần nhà.","audioKind":"ex"},{"en":"Access to nearby parks encourages urban residents to exercise regularly and spend more time outdoors.","vi":"Việc dễ dàng tiếp cận các công viên gần nhà khuyến khích cư dân đô thị tập thể dục thường xuyên và dành nhiều thời gian hơn cho các hoạt động ngoài trời.","audioKind":"ex2"}],"collocations":[{"en":"a nearby park","vi":"một công viên gần đó"},{"en":"nearby residents","vi":"cư dân lân cận"},{"en":"live nearby","vi":"sống ở gần đây"}],"wordFamily":[],"synonyms":["close by","adjacent"],"antonyms":["far away"],"tipVi":"Không dùng \"nearby\" làm giới từ: phải dùng \"near the school\" thay vì \"nearby the school\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_21_1', 'en-a2-21', 'Cách dùng “space” (n.) — không gian; khoảng trống; chỗ', 'green space  ·  outer space  ·  parking space', 'Từ "space" là danh từ không đếm được khi mang nghĩa không gian chung hoặc vũ trụ, nhưng đếm được khi chỉ các không gian cụ thể như chỗ đậu xe.', 'Họ từ (Word Family): spacious (adj.), spacing (n.) | Đồng nghĩa: room, gap', '[{"hanzi":"There is enough space for your bike beside mine.","pinyin":"","meaning":"Vẫn còn đủ chỗ cho chiếc xe đạp của bạn ở bên cạnh xe của tôi."},{"hanzi":"Providing more green space in crowded neighbourhoods can improve residents'' wellbeing and encourage outdoor physical activity.","pinyin":"","meaning":"Việc tạo ra nhiều không gian xanh hơn ở các khu dân cư đông đúc có thể cải thiện sức khỏe của cư dân và khuyến khích các hoạt động thể chất ngoài trời."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_21_2', 'en-a2-21', 'Cách dùng “tower” (n.) — tháp; tòa tháp', 'a clock tower  ·  a watch tower  ·  tower above', 'Khi đóng vai trò là động từ, từ này thường đi với over hoặc above để diễn tả ý cao vượt hẳn lên so với môi trường xung quanh.', 'Họ từ (Word Family): towering (adj.)', '[{"hanzi":"We climbed the tower and watched boats cross the bay.","pinyin":"","meaning":"Chúng tôi trèo lên tháp và ngắm nhìn những chiếc thuyền băng qua vịnh."},{"hanzi":"The historic tower attracts visitors throughout the year, providing valuable income for nearby shops and restaurants.","pinyin":"","meaning":"Ngọn tháp lịch sử thu hút du khách quanh năm, mang lại nguồn thu nhập quý giá cho các cửa hàng và nhà hàng gần đó."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_21_3', 'en-a2-21', 'Cách dùng “apartment” (n.) — căn hộ; nhà chung cư', 'rent an apartment  ·  apartment block  ·  studio apartment', 'Tiếng Mỹ thường dùng apartment, trong khi tiếng Anh - Anh thường dùng flat trong đời sống hàng ngày.', 'Đồng nghĩa: flat', '[{"hanzi":"Our apartment has a small balcony overlooking the park.","pinyin":"","meaning":"Căn hộ của chúng tôi có một ban công nhỏ nhìn ra công việc."},{"hanzi":"Building affordable apartments near railway stations can reduce commuting costs for young workers.","pinyin":"","meaning":"Việc xây dựng các căn hộ có giá cả phải chăng gần các nhà ga xe lửa có thể giảm chi phí đi lại cho các nhân viên trẻ tuổi."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_21_4', 'en-a2-21', 'Cách dùng “underground” (adj.) — ở dưới lòng đất; ngầm; hoạt động bí mật', 'underground station  ·  underground car park  ·  travel underground', 'Danh từ chỉ tàu điện ngầm chủ yếu dùng trong tiếng Anh-Anh, với trọng âm rơi vào âm tiết đầu tiên.', 'Trái nghĩa: above ground', '[{"hanzi":"We left our car in an underground garage.","pinyin":"","meaning":"Chúng tôi đã đỗ xe ở bãi đỗ xe ngầm."},{"hanzi":"Underground transport systems can ease congestion, although constructing tunnels requires substantial investment and careful planning.","pinyin":"","meaning":"Hệ thống giao thông ngầm có thể làm giảm tình trạng ùn tắc, dẫu cho việc xây dựng các đường hầm đòi hỏi nguồn vốn đầu tư lớn cùng kế hoạch chu đáo."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_21_1', 'en-a2-21', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_21_1_1', 'ten_a2_21_1', 'space', 'There is enough space for your bike beside mine.', 'There is enough space for your bike beside mine.', '/speɪs/', 'Vẫn còn đủ chỗ cho chiếc xe đạp của bạn ở bên cạnh xe của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_21_1_2', 'ten_a2_21_1', 'underground', 'We left our car in an underground garage.', 'We left our car in an underground garage.', '/ˌʌndərˈɡraʊnd/', 'Chúng tôi đã đỗ xe ở bãi đỗ xe ngầm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_21_1_3', 'ten_a2_21_1', 'metro', 'We took the metro to the museum this morning.', 'We took the metro to the museum this morning.', '/ˈmetroʊ/', 'Sáng nay chúng tôi đã đi tàu điện ngầm đến bảo tàng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_21_1_4', 'ten_a2_21_1', 'hometown', 'I return to my hometown every summer to visit relatives.', 'I return to my hometown every summer to visit relatives.', '/ˈhoʊmtaʊn/', 'Tôi trở về quê hương vào mỗi mùa hè để thăm họ hàng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_21_1_5', 'ten_a2_21_1', 'downtown', 'We took the bus downtown to buy new shoes.', 'We took the bus downtown to buy new shoes.', '/ˌdaʊnˈtaʊn/', 'Chúng tôi đã bắt xe buýt vào trung tâm thành phố để mua giày mới.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_21_1_6', 'ten_a2_21_1', 'apartment', 'Our apartment has a small balcony overlooking the park.', 'Our apartment has a small balcony overlooking the park.', '/əˈpɑːrtmənt/', 'Căn hộ của chúng tôi có một ban công nhỏ nhìn ra công việc.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_21_1_7', 'ten_a2_21_1', 'bridge', 'We crossed the wooden bridge and entered the village.', 'We crossed the wooden bridge and entered the village.', '/brɪdʒ/', 'Chúng tôi đi qua chiếc cầu gỗ và bước vào làng.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_21_1_8', 'ten_a2_21_1', 'built', 'We built a small shelter for the garden tools.', 'We built a small shelter for the garden tools.', '/bɪlt/', 'Chúng tôi đã dựng một nhà kho nhỏ cho các dụng cụ làm vườn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_21_1_1', 'en-a2-21', 'ten_a2_21_1', 'listening', 'listening', 'There is enough space for your bike beside mine.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã thả tấm bưu thiếp chúc mừng sinh nhật vào hòm thư ở bên ngoài.","Chúng tôi đã bắt xe buýt vào trung tâm thành phố để mua giày mới.","Vẫn còn đủ chỗ cho chiếc xe đạp của bạn ở bên cạnh xe của tôi.","Chúng tôi đã dành cả buổi chiều mưa để đi dạo trong trung tâm thương mại."]'::jsonb, 2, 'There is enough space for your bike beside mine. → Vẫn còn đủ chỗ cho chiếc xe đạp của bạn ở bên cạnh xe của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_21_1_2', 'en-a2-21', 'ten_a2_21_1', 'listening', 'listening', 'We left our car in an underground garage.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã dựng một nhà kho nhỏ cho các dụng cụ làm vườn.","Tôi trở về quê hương vào mỗi mùa hè để thăm họ hàng.","Chúng tôi đã đỗ xe ở bãi đỗ xe ngầm.","Chúng tôi đã dành cả buổi chiều mưa để đi dạo trong trung tâm thương mại."]'::jsonb, 2, 'We left our car in an underground garage. → Chúng tôi đã đỗ xe ở bãi đỗ xe ngầm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_21_1_3', 'en-a2-21', 'ten_a2_21_1', 'listening', 'listening', 'We took the metro to the museum this morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một tiệm bánh nhỏ vừa mới mở trong khu phố nhà chúng tôi.","Tiền thuê nhà hàng tháng của tôi đã bao gồm tiền nước nhưng chưa gồm tiền điện.","Xin hãy để đôi giày ướt của bạn ở ngoài tiền sảnh.","Sáng nay chúng tôi đã đi tàu điện ngầm đến bảo tàng."]'::jsonb, 3, 'We took the metro to the museum this morning. → Sáng nay chúng tôi đã đi tàu điện ngầm đến bảo tàng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_21_2', 'en-a2-21', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_21_2_1', 'ten_a2_21_2', 'space', 'Providing more green space in crowded neighbourhoods can improve residents'' wellbeing and encourage outdoor physical activity.', 'Providing more green space in crowded neighbourhoods can improve residents'' wellbeing and encourage outdoor physical activity.', '/speɪs/', 'Việc tạo ra nhiều không gian xanh hơn ở các khu dân cư đông đúc có thể cải thiện sức khỏe của cư dân và khuyến khích các hoạt động thể chất ngoài trời.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_21_2_2', 'ten_a2_21_2', 'underground', 'Underground transport systems can ease congestion, although constructing tunnels requires substantial investment and careful planning.', 'Underground transport systems can ease congestion, although constructing tunnels requires substantial investment and careful planning.', '/ˌʌndərˈɡraʊnd/', 'Hệ thống giao thông ngầm có thể làm giảm tình trạng ùn tắc, dẫu cho việc xây dựng các đường hầm đòi hỏi nguồn vốn đầu tư lớn cùng kế hoạch chu đáo.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_21_2_3', 'ten_a2_21_2', 'metro', 'Expanding the metro could reduce traffic congestion by providing residents with a reliable alternative to private cars.', 'Expanding the metro could reduce traffic congestion by providing residents with a reliable alternative to private cars.', '/ˈmetroʊ/', 'Việc mở rộng hệ thống tàu điện ngầm có thể giúp giảm ùn tắc giao thông bằng cách cung cấp cho người dân một phương án thay thế đáng tin cậy cho xe cá nhân.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_21_2_4', 'ten_a2_21_2', 'hometown', 'Many graduates leave their hometown to seek better employment opportunities in larger urban centres.', 'Many graduates leave their hometown to seek better employment opportunities in larger urban centres.', '/ˈhoʊmtaʊn/', 'Nhiều sinh viên tốt nghiệp rời bỏ quê hương để tìm kiếm cơ hội việc làm tốt hơn tại các trung tâm đô thị lớn hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_21_2_5', 'ten_a2_21_2', 'downtown', 'Improved public transport can encourage more residents to shop downtown rather than drive to suburban shopping centres.', 'Improved public transport can encourage more residents to shop downtown rather than drive to suburban shopping centres.', '/ˌdaʊnˈtaʊn/', 'Việc cải thiện giao thông công cộng có thể khuyến khích nhiều cư dân mua sắm ở trung tâm thành phố hơn là lái xe đến các trung tâm mua sắm ngoại ô.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_21_2_6', 'ten_a2_21_2', 'apartment', 'Building affordable apartments near railway stations can reduce commuting costs for young workers.', 'Building affordable apartments near railway stations can reduce commuting costs for young workers.', '/əˈpɑːrtmənt/', 'Việc xây dựng các căn hộ có giá cả phải chăng gần các nhà ga xe lửa có thể giảm chi phí đi lại cho các nhân viên trẻ tuổi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_21_2_1', 'en-a2-21', 'ten_a2_21_2', 'listening', 'listening', 'Providing more green space in crowded neighbourhoods can improve residents'' wellbeing and encourage outdoor physical activity.', NULL, 'Trong câu vừa nghe, từ “space” mang nghĩa nào sau đây?', '["đơn độc; một mình; không có ai ở cùng","không gian; khoảng trống; chỗ","tốc độ; vận tốc","việc đi lại; sự du lịch"]'::jsonb, 1, '“space” (/speɪs/): không gian; khoảng trống; chỗ. Câu đầy đủ: Providing more green space in crowded neighbourhoods can improve residents'' wellbeing and encourage outdoor physical activity.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_21_2_2', 'en-a2-21', 'ten_a2_21_2', 'listening', 'listening', 'Underground transport systems can ease congestion, although constructing tunnels requires substantial investment and careful planning.', NULL, 'Trong câu vừa nghe, từ “underground” mang nghĩa nào sau đây?', '["doanh nhân; nhà kinh doanh nam","phim hoạt hình","tai nạn; sự cố","ở dưới lòng đất; ngầm; hoạt động bí mật"]'::jsonb, 3, '“underground” (/ˌʌndərˈɡraʊnd/): ở dưới lòng đất; ngầm; hoạt động bí mật. Câu đầy đủ: Underground transport systems can ease congestion, although constructing tunnels requires substantial investment and careful planning.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
