INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_1', 'en-a2-21', NULL, 'comprehensive_test', 'listening', 'space', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khoảng cách; quãng đường","trường hợp; ví dụ; căn bệnh","hoang dã; mọc tự nhiên","không gian; khoảng trống; chỗ"]'::jsonb, 3, 'space (/speɪs/) → không gian; khoảng trống; chỗ; vũ trụ; không gian bên ngoài; sắp xếp có khoảng cách', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_2', 'en-a2-21', NULL, 'comprehensive_test', 'listening', 'We left our car in an underground garage.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi mua bánh mỳ tươi từ một cửa hàng bánh gần nhà.","Việc đỗ xe rất khó khăn trên con đường chật hẹp này sau khi mặt trời lặn.","Chúng tôi đã đỗ xe ở bãi đỗ xe ngầm.","Tôi trở về quê hương vào mỗi mùa hè để thăm họ hàng."]'::jsonb, 2, 'We left our car in an underground garage. → Chúng tôi đã đỗ xe ở bãi đỗ xe ngầm.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_3', 'en-a2-21', NULL, 'comprehensive_test', 'listening', 'metro', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sự sinh đẻ; sự ra đời; ca sinh","tàu điện ngầm; hệ thống tàu điện ngầm","rác thải; phế liệu","lục quân; quân đội"]'::jsonb, 1, 'metro (/ˈmetroʊ/) → tàu điện ngầm; hệ thống tàu điện ngầm', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_4', 'en-a2-21', NULL, 'comprehensive_test', 'listening', 'I return to my hometown every summer to visit relatives.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bạn có thể chỉ cho tôi đường đến hiệu thuốc gần nhất được không?","Tôi trở về quê hương vào mỗi mùa hè để thăm họ hàng.","Sáng nay chúng tôi đã đi tàu điện ngầm đến bảo tàng.","Tôi đã thả tấm bưu thiếp chúc mừng sinh nhật vào hòm thư ở bên ngoài."]'::jsonb, 1, 'I return to my hometown every summer to visit relatives. → Tôi trở về quê hương vào mỗi mùa hè để thăm họ hàng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_5', 'en-a2-21', NULL, 'comprehensive_test', 'listening', 'downtown', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["của chính mình; riêng","đá; hòn đá","văn bản; chữ","ở hoặc hướng về khu trung tâm thương mại của thành phố"]'::jsonb, 3, 'downtown (/ˌdaʊnˈtaʊn/) → ở hoặc hướng về khu trung tâm thương mại của thành phố; thuộc khu trung tâm thương mại của thành phố; khu trung tâm thương mại của thành phố', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_6', 'en-a2-21', NULL, 'comprehensive_test', 'listening', 'Our apartment has a small balcony overlooking the park.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đi qua chiếc cầu gỗ và bước vào làng.","Một tiệm bánh nhỏ vừa mới mở trong khu phố nhà chúng tôi.","Chúng tôi đã dành cả buổi chiều mưa để đi dạo trong trung tâm thương mại.","Căn hộ của chúng tôi có một ban công nhỏ nhìn ra công việc."]'::jsonb, 3, 'Our apartment has a small balcony overlooking the park. → Căn hộ của chúng tôi có một ban công nhỏ nhìn ra công việc.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_7', 'en-a2-21', NULL, 'comprehensive_test', 'listening', 'bridge', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cây cầu; cầu đường","thêm; phụ","trật tự, thứ tự","láng giềng; người hàng xóm"]'::jsonb, 0, 'bridge (/brɪdʒ/) → cây cầu; cầu đường; thu hẹp khoảng cách; khắc phục; trò chơi bài cầu phỉnh (bridge)', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_8', 'en-a2-21', NULL, 'comprehensive_test', 'listening', 'We built a small shelter for the garden tools.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã dành cả buổi chiều mưa để đi dạo trong trung tâm thương mại.","Bạn có thể chỉ cho tôi đường đến hiệu thuốc gần nhất được không?","Chúng tôi đã dựng một nhà kho nhỏ cho các dụng cụ làm vườn.","Chúng tôi trèo lên tháp và ngắm nhìn những chiếc thuyền băng qua vịnh."]'::jsonb, 2, 'We built a small shelter for the garden tools. → Chúng tôi đã dựng một nhà kho nhỏ cho các dụng cụ làm vườn.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_9', 'en-a2-21', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “in or towards the central business area of a city”?', '["nearest","bridge","downtown","tower"]'::jsonb, 2, 'downtown (/ˌdaʊnˈtaʊn/) → ở hoặc hướng về khu trung tâm thương mại của thành phố', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_10', 'en-a2-21', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A set of rooms forming one home within a building.”?', '["nearby","nearest","hall","apartment"]'::jsonb, 3, 'apartment (/əˈpɑːrtmənt/) → căn hộ; nhà chung cư', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
