INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_18', 'en-a2-21', NULL, 'comprehensive_test', 'reading', NULL, 'Providing more green space in crowded neighbourhoods can improve residents'' wellbeing and encourage outdoor physical activity.', 'Dựa vào câu trên, từ “space” có nghĩa phù hợp nhất là gì?', '["hình tròn; vòng tròn","không gian; khoảng trống; chỗ","thuốc lá điếu","cái chuông; cái cồng"]'::jsonb, 1, 'space: không gian; khoảng trống; chỗ; vũ trụ; không gian bên ngoài; sắp xếp có khoảng cách. Dịch cả câu: Việc tạo ra nhiều không gian xanh hơn ở các khu dân cư đông đúc có thể cải thiện sức khỏe của cư dân và khuyến khích các hoạt động thể chất ngoài trời.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_19', 'en-a2-21', NULL, 'comprehensive_test', 'reading', NULL, 'Underground transport systems can ease congestion, although constructing tunnels requires substantial investment and careful planning.', 'Dựa vào câu trên, từ “underground” có nghĩa phù hợp nhất là gì?', '["ở dưới lòng đất; ngầm; hoạt động bí mật","đất liền; đất đai; vùng đất","tình hình; hoàn cảnh; tình thế","đoán; phỏng đoán"]'::jsonb, 0, 'underground: ở dưới lòng đất; ngầm; hoạt động bí mật; ở dưới mặt đất; một cách bí mật; hệ thống tàu điện ngầm. Dịch cả câu: Hệ thống giao thông ngầm có thể làm giảm tình trạng ùn tắc, dẫu cho việc xây dựng các đường hầm đòi hỏi nguồn vốn đầu tư lớn cùng kế hoạch chu đáo.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_20', 'en-a2-21', NULL, 'comprehensive_test', 'reading', NULL, 'Expanding the metro could reduce traffic congestion by providing residents with a reliable alternative to private cars.', 'Dựa vào câu trên, từ “metro” có nghĩa phù hợp nhất là gì?', '["nhấp chuột; chọn một mục trên màn hình","tàu điện ngầm; hệ thống tàu điện ngầm","mì Ý sợi nhỏ dài","cơn đau đầu"]'::jsonb, 1, 'metro: tàu điện ngầm; hệ thống tàu điện ngầm. Dịch cả câu: Việc mở rộng hệ thống tàu điện ngầm có thể giúp giảm ùn tắc giao thông bằng cách cung cấp cho người dân một phương án thay thế đáng tin cậy cho xe cá nhân.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_21', 'en-a2-21', NULL, 'comprehensive_test', 'reading', NULL, 'Many graduates leave their hometown to seek better employment opportunities in larger urban centres.', 'Dựa vào câu trên, từ “hometown” có nghĩa phù hợp nhất là gì?', '["quê hương, thị trấn hoặc thành phố nơi lớn lên hoặc xuất thân","đơn giản; dễ hiểu; dễ làm","thư từ; bưu phẩm; dịch vụ bưu chính","trưa; chính ngọ"]'::jsonb, 0, 'hometown: quê hương, thị trấn hoặc thành phố nơi lớn lên hoặc xuất thân. Dịch cả câu: Nhiều sinh viên tốt nghiệp rời bỏ quê hương để tìm kiếm cơ hội việc làm tốt hơn tại các trung tâm đô thị lớn hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_22', 'en-a2-21', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khu phố; vùng lân cận”', '["neighbourhood","musical","reply","surfing"]'::jsonb, 0, 'khu phố; vùng lân cận → neighbourhood (/ˈneɪbɚhʊd/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_23', 'en-a2-21', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “gần nhất (về khoảng cách, thời gian hoặc sự tương đồng)”', '["discussion","southwest","violin","nearest"]'::jsonb, 3, 'gần nhất (về khoảng cách, thời gian hoặc sự tương đồng) → nearest (/ˈnɪrɪst/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_21_24', 'en-a2-21', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ở gần; lân cận”', '["nearby","sausage","noticeboard","tasty"]'::jsonb, 0, 'ở gần; lân cận → nearby (/ˌnɪrˈbaɪ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-22', 'en', 'Bài 22: Đô thị & Kiến trúc (2) - CEFR A2', 'CEFR A2', 'A2 · Đô thị', '16 từ vựng Tiếng Anh CEFR A2 chủ đề đô thị & kiến trúc kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2022, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crowded', 'en-a2-22', 'crowded', '/ˈkraʊdɪd/', 'A2', 'chật chội; đông đúc', 'adj.', 'crowd (n.), crowd (v.), overcrowded (adj.), overcrowding (n.)', 'Đồng nghĩa: packed, congested · Trái nghĩa: empty, uncrowded', 'be crowded with biểu thị "đông đúc, ngập tràn...".', 'The bus was so crowded that we stood all the way.', NULL, 'Xe buýt đông nghịt người đến mức chúng tôi phải đứng suốt cả quãng đường.', '{"wordId":"crowded","ukIpa":"/ˈkraʊdɪd/","usIpa":"/ˈkraʊdɪd/","cefr":"A2","topic":"city","senses":[{"pos":"adj.","en":"Containing so many people or things that little space remains","vi":"chật chội; đông đúc"}],"examples":[{"en":"The bus was so crowded that we stood all the way.","vi":"Xe buýt đông nghịt người đến mức chúng tôi phải đứng suốt cả quãng đường.","audioKind":"ex"},{"en":"Crowded urban neighbourhoods need accessible parks where residents can exercise and enjoy some personal space.","vi":"Các khu đô thị đông đúc cần có các công viên dễ tiếp cận để cư dân có thể tập thể dục và tận hưởng không gian riêng tư.","audioKind":"ex2"}],"collocations":[{"en":"crowded bus","vi":"xe buýt đông đúc"},{"en":"crowded with people","vi":"đông đúc người"},{"en":"crowded streets","vi":"đường phố chật chội"}],"wordFamily":["crowd (n.)","crowd (v.)","overcrowded (adj.)","overcrowding (n.)"],"synonyms":["packed","congested"],"antonyms":["empty","uncrowded"],"tipVi":"be crowded with biểu thị \"đông đúc, ngập tràn...\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_local', 'en-a2-22', 'local', '/ˈloʊkəl/', 'A2', 'thuộc địa phương; ở tại địa phương; người địa phương; cục bộ; bộ phận', 'adj.', 'locally (adv.), locality (n.), localise (v.)', 'Đồng nghĩa: nearby', 'Danh từ số nhiều locals chỉ người địa phương; locally là trạng thái phó từ.', 'We buy fresh bread from our local bakery every morning.', NULL, 'Chúng tôi mua bánh mì tươi ở cửa hàng bánh địa phương mỗi sáng.', '{"wordId":"local","ukIpa":"/ˈləʊkəl/","usIpa":"/ˈloʊkəl/","cefr":"A2","topic":"city","senses":[{"pos":"adj.","en":"relating to the area where someone lives or something happens","vi":"thuộc địa phương; ở tại địa phương"},{"pos":"n.","en":"a person who lives in a particular area","vi":"người địa phương"},{"pos":"adj.","en":"affecting only a limited part of something","vi":"cục bộ; bộ phận"}],"examples":[{"en":"We buy fresh bread from our local bakery every morning.","vi":"Chúng tôi mua bánh mì tươi ở cửa hàng bánh địa phương mỗi sáng.","audioKind":"ex"},{"en":"Supporting local businesses can strengthen community ties and keep more money circulating within the regional economy.","vi":"Việc hỗ trợ các doanh nghiệp địa phương có thể thắt chặt tình làng nghĩa xóm và giữ cho dòng tiền lưu thông nhiều hơn trong nền kinh tế khu vực.","audioKind":"ex2"}],"collocations":[{"en":"local community","vi":"cộng đồng địa phương"},{"en":"local authorities","vi":"chính quyền địa phương"},{"en":"local residents","vi":"cư dân địa phương"},{"en":"local anaesthetic","vi":"thuốc tê cục bộ"}],"wordFamily":["locally (adv.)","locality (n.)","localise (v.)"],"synonyms":["nearby"],"antonyms":[],"tipVi":"Danh từ số nhiều locals chỉ người địa phương; locally là trạng thái phó từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_parking-lot', 'en-a2-22', 'parking lot', '/ˈpɑːrkɪŋ lɑːt/', 'A2', 'bãi đỗ xe ngoài trời', 'n.', 'park (v.), parking (n.)', 'Đồng nghĩa: car park', 'parking lot là từ thường dùng trong tiếng Anh-Mỹ; nhà để xe nhiều tầng thường gọi là parking garage.', 'Our car is near the parking lot entrance.', NULL, 'Xe của chúng tôi ở gần lối vào bãi đỗ xe.', '{"wordId":"parking-lot","ukIpa":"/ˈpɑːkɪŋ lɒt/","usIpa":"/ˈpɑːrkɪŋ lɑːt/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"An outdoor area where cars can be parked.","vi":"bãi đỗ xe ngoài trời"}],"examples":[{"en":"Our car is near the parking lot entrance.","vi":"Xe của chúng tôi ở gần lối vào bãi đỗ xe.","audioKind":"ex"},{"en":"Planting trees around a parking lot can provide shade and reduce surface temperatures during hot weather.","vi":"Trồng cây xanh xung quanh bãi đỗ xe có thể tạo bóng mát và làm giảm nhiệt độ bề mặt trong thời tiết oi bức.","audioKind":"ex2"}],"collocations":[{"en":"empty parking lot","vi":"bãi đỗ xe trống"},{"en":"crowded parking lot","vi":"bãi đỗ xe đông đúc"},{"en":"parking lot entrance","vi":"lối vào bãi đỗ xe"}],"wordFamily":["park (v.)","parking (n.)"],"synonyms":["car park"],"antonyms":[],"tipVi":"parking lot là từ thường dùng trong tiếng Anh-Mỹ; nhà để xe nhiều tầng thường gọi là parking garage.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_crossing', 'en-a2-22', 'crossing', '/ˈkrɔːsɪŋ/', 'A2', 'vạch sang đường; chỗ qua đường; chuyến vượt biển; hành trình vượt qua', 'n.', 'cross (v.)', NULL, 'Danh từ này có thể chỉ địa điểm qua đường hoặc hành trình vượt qua đường thủy.', 'We waited at the crossing until the cars stopped.', NULL, 'Chúng tôi đợi ở vạch sang đường cho đến khi các phương tiện dừng lại.', '{"wordId":"crossing","ukIpa":"/ˈkrɒsɪŋ/","usIpa":"/ˈkrɔːsɪŋ/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"A designated place where people or vehicles cross.","vi":"vạch sang đường; chỗ qua đường"},{"pos":"n.","en":"A journey across water or another geographical barrier.","vi":"chuyến vượt biển; hành trình vượt qua"}],"examples":[{"en":"We waited at the crossing until the cars stopped.","vi":"Chúng tôi đợi ở vạch sang đường cho đến khi các phương tiện dừng lại.","audioKind":"ex"},{"en":"Installing a pedestrian crossing near every school can help protect children and encourage more families to walk.","vi":"Việc lắp đặt vạch sang đường cho người đi bộ gần mỗi trường học có thể giúp bảo vệ trẻ em và khuyến khích nhiều gia đình đi bộ hơn.","audioKind":"ex2"}],"collocations":[{"en":"pedestrian crossing","vi":"vạch sang đường cho người đi bộ"},{"en":"level crossing","vi":"đường ray giao cắt mức"},{"en":"border crossing","vi":"cửa khẩu biên giới"},{"en":"ferry crossing","vi":"chuyến phà qua sông"}],"wordFamily":["cross (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ này có thể chỉ địa điểm qua đường hoặc hành trình vượt qua đường thủy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_subway', 'en-a2-22', 'subway', '/ˈsʌbweɪ/', 'A2', 'hệ thống tàu điện ngầm; đường hầm dành cho người đi bộ qua đường', 'n.', NULL, NULL, 'Tiếng Mỹ chỉ tàu điện ngầm; tiếng Anh-Anh thường chỉ đường hầm dành cho người đi bộ.', 'We took the subway to the museum this morning.', NULL, 'Sáng nay chúng tôi đã đi tàu điện ngầm đến bảo tàng.', '{"wordId":"subway","ukIpa":"/ˈsʌbweɪ/","usIpa":"/ˈsʌbweɪ/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"An urban railway system that runs mainly underground.","vi":"hệ thống tàu điện ngầm"},{"pos":"n.","en":"A passage allowing people to walk beneath a road.","vi":"đường hầm dành cho người đi bộ qua đường"}],"examples":[{"en":"We took the subway to the museum this morning.","vi":"Sáng nay chúng tôi đã đi tàu điện ngầm đến bảo tàng.","audioKind":"ex"},{"en":"Expanding subway networks can ease traffic congestion, provided that services remain affordable and accessible to local residents.","vi":"Việc mở rộng mạng lưới tàu điện ngầm có thể giảm bớt tình trạng ùn tắc giao thông, với điều kiện giá vé phải chăng và người dân địa phương dễ dàng tiếp cận.","audioKind":"ex2"}],"collocations":[{"en":"take the subway","vi":"đi tàu điện ngầm"},{"en":"subway station","vi":"ga tàu điện ngầm"},{"en":"subway line","vi":"tuyến tàu điện ngầm"},{"en":"pedestrian subway","vi":"đường hầm cho người đi bộ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Mỹ chỉ tàu điện ngầm; tiếng Anh-Anh thường chỉ đường hầm dành cho người đi bộ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bakery', 'en-a2-22', 'bakery', '/ˈbeɪkəri/', 'A2', 'tiệm bánh; lò bánh mì', 'n.', 'bake (v.), baker (n.), baking (n.)', NULL, 'bakery chỉ cửa hàng hoặc nơi sản xuất; bánh nướng nói chung dùng baked goods.', 'The bakery near our house sells warm bread every morning.', NULL, 'Cửa hàng bánh mì gần nhà chúng tôi bán bánh mì ấm nóng vào mỗi buổi sáng.', '{"wordId":"bakery","ukIpa":"/ˈbeɪkəri/","usIpa":"/ˈbeɪkəri/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"a place where bread and cakes are made or sold","vi":"tiệm bánh; lò bánh mì"}],"examples":[{"en":"The bakery near our house sells warm bread every morning.","vi":"Cửa hàng bánh mì gần nhà chúng tôi bán bánh mì ấm nóng vào mỗi buổi sáng.","audioKind":"ex"},{"en":"Small businesses such as bakeries provide local employment and help maintain vibrant neighbourhood shopping areas.","vi":"Các doanh nghiệp nhỏ như tiệm bánh mì tạo ra việc làm tại địa phương và góp phần duy trì sự sôi động cho các khu mua sắm trong khu phố.","audioKind":"ex2"}],"collocations":[{"en":"local bakery","vi":"tiệm bánh địa phương"},{"en":"bakery owner","vi":"chủ tiệm bánh"},{"en":"bakery products","vi":"sản phẩm làm từ bột mì; bánh nướng"}],"wordFamily":["bake (v.)","baker (n.)","baking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"bakery chỉ cửa hàng hoặc nơi sản xuất; bánh nướng nói chung dùng baked goods.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_car-park', 'en-a2-22', 'car park', '/ˈkɑːr pɑːrk/', 'A2', 'bãi đậu xe; bãi đỗ xe', 'n.', NULL, 'Đồng nghĩa: parking lot', 'Tiếng Anh-Anh thường dùng car park; trong khi bãi đậu xe ngoài trời tiếng Anh-Mỹ thường gọi là parking lot.', 'We found a space in the station car park.', NULL, 'Chúng tôi đã tìm được một chỗ trống trong bãi đậu xe của nhà ga.', '{"wordId":"car-park","ukIpa":"/ˈkɑː pɑːk/","usIpa":"/ˈkɑːr pɑːrk/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"An area or building where cars can be parked.","vi":"bãi đậu xe; bãi đỗ xe"}],"examples":[{"en":"We found a space in the station car park.","vi":"Chúng tôi đã tìm được một chỗ trống trong bãi đậu xe của nhà ga.","audioKind":"ex"},{"en":"Replacing an underused car park with green space could improve the quality of life for nearby residents.","vi":"Việc thay thế một bãi đậu xe ít người sử dụng bằng không gian xanh có thể cải thiện chất lượng cuộc sống cho cư dân gần đó.","audioKind":"ex2"}],"collocations":[{"en":"multi-storey car park","vi":"bãi đậu xe nhiều tầng"},{"en":"underground car park","vi":"bãi đậu xe ngầm"},{"en":"car park entrance","vi":"lối vào bãi đậu xe"}],"wordFamily":[],"synonyms":["parking lot"],"antonyms":[],"tipVi":"Tiếng Anh-Anh thường dùng car park; trong khi bãi đậu xe ngoài trời tiếng Anh-Mỹ thường gọi là parking lot.","noteVi":"Quy chuẩn chính tả: Danh từ này thường được viết là car park, không có dấu gạch nối.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_square', 'en-a2-22', 'square', '/skwer/', 'A2', 'hình vuông; quảng trường; tính theo đơn vị bình phương', 'n.', 'squarely (adv.), squared (adj.)', NULL, 'Diện tích dùng square metres; chiều dài dùng metres, không được nhầm lẫn.', 'Fold the paper into a square before cutting it.', NULL, 'Hãy gấp tờ giấy thành hình vuông trước khi cắt.', '{"wordId":"square","ukIpa":"/skweə/","usIpa":"/skwer/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"a shape with four equal sides and four right angles","vi":"hình vuông"},{"pos":"n.","en":"an open public area surrounded by buildings","vi":"quảng trường"},{"pos":"adj.","en":"shaped like a square, or expressing area in squared units","vi":"hình vuông; tính theo đơn vị bình phương"}],"examples":[{"en":"Fold the paper into a square before cutting it.","vi":"Hãy gấp tờ giấy thành hình vuông trước khi cắt.","audioKind":"ex"},{"en":"Creating a public square can encourage social interaction and provide space for cultural events in crowded cities.","vi":"Việc tạo ra một quảng trường công cộng có thể khuyến khích giaoLưu xã hội và cung cấp không gian cho các sự kiện văn hóa ở những thành phố đông đúc.","audioKind":"ex2"}],"collocations":[{"en":"town square","vi":"quảng trường trung tâm"},{"en":"square metre","vi":"mét vuông"},{"en":"square root","vi":"căn bậc hai"},{"en":"square table","vi":"bàn vuông"}],"wordFamily":["squarely (adv.)","squared (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Diện tích dùng square metres; chiều dài dùng metres, không được nhầm lẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_traffic', 'en-a2-22', 'traffic', '/ˈtræfɪk/', 'A2', 'giao thông, xe cộ qua lại; lưu lượng dữ liệu, lưu lượng truy cập', 'n.', NULL, NULL, 'Khi chỉ giao thông hoặc dòng xe cộ, từ này là danh từ không đếm được, không dùng a traffic.', 'Heavy traffic made us late for dinner again.', NULL, 'Giao thông đông đúc lại khiến chúng tôi đến ăn tối muộn.', '{"wordId":"traffic","ukIpa":"/ˈtræfɪk/","usIpa":"/ˈtræfɪk/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"Vehicles moving along roads in a particular area","vi":"giao thông, xe cộ qua lại"},{"pos":"n.","en":"The amount of data or messages passing through a system","vi":"lưu lượng dữ liệu, lưu lượng truy cập"}],"examples":[{"en":"Heavy traffic made us late for dinner again.","vi":"Giao thông đông đúc lại khiến chúng tôi đến ăn tối muộn.","audioKind":"ex"},{"en":"Investing in reliable public transport can reduce traffic congestion and improve urban air quality.","vi":"Đầu tư vào hệ thống giao thông công cộng đáng tin cậy có thể làm giảm tình trạng tắc nghẽn giao thông và cải thiện chất lượng không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"heavy traffic","vi":"giao thông đông đúc"},{"en":"traffic congestion","vi":"tắc nghẽn giao thông"},{"en":"traffic lights","vi":"đèn giao thông"},{"en":"internet traffic","vi":"lưu lượng internet"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ giao thông hoặc dòng xe cộ, từ này là danh từ không đếm được, không dùng a traffic.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_elevator', 'en-a2-22', 'elevator', '/ˈeləveɪtər/', 'A2', 'thang máy; máy nâng', 'n.', 'elevate (v.), elevation (n.)', 'Đồng nghĩa: lift', 'Trong tiếng Anh Mỹ dùng elevator, còn tiếng Anh - Anh dùng lift.', 'We took the elevator because our bags were heavy.', NULL, 'Chúng tôi đi thang máy vì túi đồ của chúng tôi rất nặng.', '{"wordId":"elevator","ukIpa":"/ˈelɪveɪtə/","usIpa":"/ˈeləveɪtər/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"A machine carrying people or goods between floors.","vi":"thang máy; máy nâng"}],"examples":[{"en":"We took the elevator because our bags were heavy.","vi":"Chúng tôi đi thang máy vì túi đồ của chúng tôi rất nặng.","audioKind":"ex"},{"en":"Installing elevators in older apartment buildings can significantly improve accessibility for elderly residents and people with disabilities.","vi":"Việc lắp đặt thang máy trong các tòa nhà chung cư cũ có thể cải thiện đáng kể khả năng tiếp cận cho cư dân cao tuổi và người khuyết tật.","audioKind":"ex2"}],"collocations":[{"en":"take the elevator","vi":"đi thang máy"},{"en":"elevator doors","vi":"cửa thang máy"},{"en":"a passenger elevator","vi":"thang máy chở khách"}],"wordFamily":["elevate (v.)","elevation (n.)"],"synonyms":["lift"],"antonyms":[],"tipVi":"Trong tiếng Anh Mỹ dùng elevator, còn tiếng Anh - Anh dùng lift.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exit', 'en-a2-22', 'exit', '/ˈeksɪt/', 'A2', 'lối ra; cửa thoát hiểm; rời khỏi; thoát', 'n.', NULL, 'Đồng nghĩa: way out, leave · Trái nghĩa: entrance, enter', 'Danh từ chỉ "exit", động từ chỉ "leave"; đừng nhầm lẫn với "exist".', 'We found the exit at the back of the cinema.', NULL, 'Chúng tôi tìm thấy lối ra ở phía sau rạp chiếu phim.', '{"wordId":"exit","ukIpa":"/ˈeksɪt/","usIpa":"/ˈeksɪt/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"a door or passage used to leave a place","vi":"lối ra; cửa thoát hiểm"},{"pos":"v.","en":"to leave a place or close a computer program","vi":"rời khỏi; thoát"}],"examples":[{"en":"We found the exit at the back of the cinema.","vi":"Chúng tôi tìm thấy lối ra ở phía sau rạp chiếu phim.","audioKind":"ex"},{"en":"Public buildings must have clearly visible emergency exits so that occupants can leave safely during an evacuation.","vi":"Các tòa nhà công cộng phải có lối thoát hiểm khẩn cấp được đánh dấu rõ ràng để mọi người có thể rời đi an toàn trong quá trình sơ tán.","audioKind":"ex2"}],"collocations":[{"en":"emergency exit","vi":"lối thoát hiểm khẩn cấp"},{"en":"fire exit","vi":"lối thoát hỏa hoạn"},{"en":"nearest exit","vi":"lối ra gần nhất"},{"en":"exit a program","vi":"thoát khỏi một chương trình"}],"wordFamily":[],"synonyms":["way out","leave"],"antonyms":["entrance","enter"],"tipVi":"Danh từ chỉ \"exit\", động từ chỉ \"leave\"; đừng nhầm lẫn với \"exist\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_entrance', 'en-a2-22', 'entrance', '/ˈentrəns/', 'A2', 'lối vào; cổng vào; sự đi vào; quyền vào; quyền gia nhập', 'n.', 'enter (v.), entry (n.)', 'Đồng nghĩa: entryway · Trái nghĩa: exit', 'Lối vào của một nơi nào đó dùng entrance to, không dùng entrance of.', 'I''ll meet you at the entrance after lunch.', NULL, 'Tôi sẽ gặp bạn ở lối vào sau bữa trưa.', '{"wordId":"entrance","ukIpa":"/ˈentrəns/","usIpa":"/ˈentrəns/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"An opening or place through which people enter.","vi":"lối vào; cổng vào"},{"pos":"n.","en":"The act of entering or the right to join.","vi":"sự đi vào; quyền vào; quyền gia nhập"}],"examples":[{"en":"I''ll meet you at the entrance after lunch.","vi":"Tôi sẽ gặp bạn ở lối vào sau bữa trưa.","audioKind":"ex"},{"en":"Universities should ensure that entrance requirements recognise different educational backgrounds while maintaining appropriate academic standards.","vi":"Các trường đại học nên đảm bảo rằng các yêu cầu đầu vào công nhận các nền tảng giáo dục khác nhau đồng thời duy trì các tiêu chuẩn học thuật phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"the main entrance","vi":"lối vào chính"},{"en":"an entrance exam","vi":"kỳ thi tuyển sinh"},{"en":"entrance requirements","vi":"yêu cầu đầu vào"},{"en":"an entrance fee","vi":"phí vào cửa"}],"wordFamily":["enter (v.)","entry (n.)"],"synonyms":["entryway"],"antonyms":["exit"],"tipVi":"Lối vào của một nơi nào đó dùng entrance to, không dùng entrance of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_roof', 'en-a2-22', 'roof', '/ruːf/', 'A2', 'mái nhà; nóc (xe); lợp mái; che mái', 'n.', 'roofing (n.), rooftop (n.), roofless (adj.)', NULL, 'Danh từ số nhiều là roofs; roof chỉ mái nhà ở bên ngoài, còn ceiling chỉ trần nhà ở bên trong.', 'Rain drummed on the roof throughout the night.', NULL, 'Tiếng mưa gõ lộp bộp trên mái nhà suốt cả đêm.', '{"wordId":"roof","ukIpa":"/ruːf/","usIpa":"/ruːf/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"the top covering of a building or vehicle","vi":"mái nhà; nóc (xe)"},{"pos":"v.","en":"to cover a building with a roof","vi":"lợp mái; che mái"}],"examples":[{"en":"Rain drummed on the roof throughout the night.","vi":"Tiếng mưa gõ lộp bộp trên mái nhà suốt cả đêm.","audioKind":"ex"},{"en":"Installing solar panels on the roof can help households lower electricity bills and reduce their environmental impact.","vi":"Lắp đặt các tấm pin mặt trời trên mái nhà có thể giúp các hộ gia đình giảm hóa đơn tiền điện và giảm thiểu tác động đến môi trường.","audioKind":"ex2"}],"collocations":[{"en":"flat roof","vi":"mái nhà phẳng"},{"en":"roof tiles","vi":"ngói lợp mái"},{"en":"under one roof","vi":"dưới một mái nhà"},{"en":"roof leak","vi":"mái nhà bị dột"}],"wordFamily":["roofing (n.)","rooftop (n.)","roofless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ số nhiều là roofs; roof chỉ mái nhà ở bên ngoài, còn ceiling chỉ trần nhà ở bên trong.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bristol', 'en-a2-22', 'Bristol', '/ˈbrɪstəl/', 'A2', 'Bristol (một thành phố ở phía tây nam nước Anh)', 'n.', 'Bristolian (n.), Bristolian (adj.)', NULL, 'Trọng âm rơi vào âm tiết đầu tiên; thành phố nằm ở phía tây nam nước Anh.', 'We walked around the harbour in Bristol yesterday.', NULL, 'Chúng tôi đã đi dạo quanh khu vực cảng ở Bristol ngày hôm qua.', '{"wordId":"bristol","ukIpa":"/ˈbrɪstəl/","usIpa":"/ˈbrɪstəl/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"A city in southwestern England with a historic port.","vi":"Bristol (một thành phố ở phía tây nam nước Anh)"}],"examples":[{"en":"We walked around the harbour in Bristol yesterday.","vi":"Chúng tôi đã đi dạo quanh khu vực cảng ở Bristol ngày hôm qua.","audioKind":"ex"},{"en":"Bristol provides an interesting example of how historic waterfront areas can be adapted for modern urban life.","vi":"Bristol là một ví dụ thú vị về cách các khu vực ven sông lịch sử có thể được cải tạo để phù hợp với cuộc sống đô thị hiện đại.","audioKind":"ex2"}],"collocations":[{"en":"Bristol Harbour","vi":"Cảng Bristol"},{"en":"central Bristol","vi":"trung tâm thành phố Bristol"},{"en":"the city of Bristol","vi":"thành phố Bristol"}],"wordFamily":["Bristolian (n.)","Bristolian (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Trọng âm rơi vào âm tiết đầu tiên; thành phố nằm ở phía tây nam nước Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bench', 'en-a2-22', 'bench', '/bentʃ/', 'A2', 'ghế dài; bàn làm việc; bàn thao tác; cho ngồi dự bị; không cho ra sân', 'n.', NULL, NULL, 'Ghế dài thường không có tựa lưng, nhưng không bắt buộc; bàn làm việc cũng có thể dùng từ bench.', 'We shared a park bench and watched the ducks.', NULL, 'Chúng tôi cùng ngồi trên một chiếc ghế dài trong công viên và ngắm nhìn những chú vịt.', '{"wordId":"bench","ukIpa":"/bentʃ/","usIpa":"/bentʃ/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"A long seat designed for several people.","vi":"ghế dài"},{"pos":"n.","en":"A sturdy table used for practical work.","vi":"bàn làm việc; bàn thao tác"},{"pos":"v.","en":"To keep a player out of a game.","vi":"cho ngồi dự bị; không cho ra sân"}],"examples":[{"en":"We shared a park bench and watched the ducks.","vi":"Chúng tôi cùng ngồi trên một chiếc ghế dài trong công viên và ngắm nhìn những chú vịt.","audioKind":"ex"},{"en":"Installing benches along pedestrian routes can make city centres more accessible to older residents and people with limited mobility.","vi":"Việc lắp đặt ghế dài dọc theo các lối đi bộ có thể giúp trung tâm thành phố dễ tiếp cận hơn đối với cư dân lớn tuổi và những người có khả năng di chuyển hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"a park bench","vi":"ghế dài trong công viên"},{"en":"a wooden bench","vi":"ghế băng gỗ"},{"en":"a work bench","vi":"bàn làm việc"},{"en":"the substitutes'' bench","vi":"ghế dự bị"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Ghế dài thường không có tựa lưng, nhưng không bắt buộc; bàn làm việc cũng có thể dùng từ bench.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_corner', 'en-a2-22', 'corner', '/ˈkɔːrnər/', 'A2', 'góc; góc phố; khúc cua; dồn vào chân tường; đẩy vào thế bí', 'n.', NULL, NULL, 'Góc trong phòng dùng in the corner; góc ngoài đường phố thường dùng on hoặc at.', 'We put a small lamp in the corner.', NULL, 'Chúng tôi đặt một chiếc đèn nhỏ ở góc phòng.', '{"wordId":"corner","ukIpa":"/ˈkɔːnə/","usIpa":"/ˈkɔːrnər/","cefr":"A2","topic":"city","senses":[{"pos":"n.","en":"A place where two sides, walls, or streets meet.","vi":"góc; góc phố; khúc cua"},{"pos":"v.","en":"To trap someone so they cannot escape or avoid answering.","vi":"dồn vào chân tường; đẩy vào thế bí"}],"examples":[{"en":"We put a small lamp in the corner.","vi":"Chúng tôi đặt một chiếc đèn nhỏ ở góc phòng.","audioKind":"ex"},{"en":"Shops on street corners can encourage walking by making everyday services more accessible to local residents.","vi":"Các cửa hàng ở góc phố thúc đẩy thói quen đi bộ bằng cách giúp người dân dễ dàng tiếp cận các dịch vụ thiết yếu hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"street corner","vi":"góc đường"},{"en":"around the corner","vi":"ở ngay góc phố; sắp xảy ra"},{"en":"in the corner","vi":"ở trong góc"},{"en":"corner the market","vi":"lũng đoạn thị trường"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Góc trong phòng dùng in the corner; góc ngoài đường phố thường dùng on hoặc at.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_22_1', 'en-a2-22', 'Cách dùng “car park” (n.) — bãi đậu xe; bãi đỗ xe', 'multi-storey car park  ·  underground car park  ·  car park entrance', 'Tiếng Anh-Anh thường dùng car park; trong khi bãi đậu xe ngoài trời tiếng Anh-Mỹ thường gọi là parking lot.', 'Đồng nghĩa: parking lot', '[{"hanzi":"We found a space in the station car park.","pinyin":"","meaning":"Chúng tôi đã tìm được một chỗ trống trong bãi đậu xe của nhà ga."},{"hanzi":"Replacing an underused car park with green space could improve the quality of life for nearby residents.","pinyin":"","meaning":"Việc thay thế một bãi đậu xe ít người sử dụng bằng không gian xanh có thể cải thiện chất lượng cuộc sống cho cư dân gần đó."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_22_2', 'en-a2-22', 'Cách dùng “parking lot” (n.) — bãi đỗ xe ngoài trời', 'empty parking lot  ·  crowded parking lot  ·  parking lot entrance', 'parking lot là từ thường dùng trong tiếng Anh-Mỹ; nhà để xe nhiều tầng thường gọi là parking garage.', 'Họ từ (Word Family): park (v.), parking (n.) | Đồng nghĩa: car park', '[{"hanzi":"Our car is near the parking lot entrance.","pinyin":"","meaning":"Xe của chúng tôi ở gần lối vào bãi đỗ xe."},{"hanzi":"Planting trees around a parking lot can provide shade and reduce surface temperatures during hot weather.","pinyin":"","meaning":"Trồng cây xanh xung quanh bãi đỗ xe có thể tạo bóng mát và làm giảm nhiệt độ bề mặt trong thời tiết oi bức."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_22_3', 'en-a2-22', 'Cách dùng “bench” (n.) — ghế dài', 'a park bench  ·  a wooden bench  ·  a work bench', 'Ghế dài thường không có tựa lưng, nhưng không bắt buộc; bàn làm việc cũng có thể dùng từ bench.', NULL, '[{"hanzi":"We shared a park bench and watched the ducks.","pinyin":"","meaning":"Chúng tôi cùng ngồi trên một chiếc ghế dài trong công viên và ngắm nhìn những chú vịt."},{"hanzi":"Installing benches along pedestrian routes can make city centres more accessible to older residents and people with limited mobility.","pinyin":"","meaning":"Việc lắp đặt ghế dài dọc theo các lối đi bộ có thể giúp trung tâm thành phố dễ tiếp cận hơn đối với cư dân lớn tuổi và những người có khả năng di chuyển hạn chế."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_22_4', 'en-a2-22', 'Cách dùng “roof” (n.) — mái nhà; nóc (xe)', 'flat roof  ·  roof tiles  ·  under one roof', 'Danh từ số nhiều là roofs; roof chỉ mái nhà ở bên ngoài, còn ceiling chỉ trần nhà ở bên trong.', 'Họ từ (Word Family): roofing (n.), rooftop (n.), roofless (adj.)', '[{"hanzi":"Rain drummed on the roof throughout the night.","pinyin":"","meaning":"Tiếng mưa gõ lộp bộp trên mái nhà suốt cả đêm."},{"hanzi":"Installing solar panels on the roof can help households lower electricity bills and reduce their environmental impact.","pinyin":"","meaning":"Lắp đặt các tấm pin mặt trời trên mái nhà có thể giúp các hộ gia đình giảm hóa đơn tiền điện và giảm thiểu tác động đến môi trường."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_22_1', 'en-a2-22', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_22_1_1', 'ten_a2_22_1', 'crowded', 'The bus was so crowded that we stood all the way.', 'The bus was so crowded that we stood all the way.', '/ˈkraʊdɪd/', 'Xe buýt đông nghịt người đến mức chúng tôi phải đứng suốt cả quãng đường.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_22_1_2', 'ten_a2_22_1', 'local', 'We buy fresh bread from our local bakery every morning.', 'We buy fresh bread from our local bakery every morning.', '/ˈloʊkəl/', 'Chúng tôi mua bánh mì tươi ở cửa hàng bánh địa phương mỗi sáng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_22_1_3', 'ten_a2_22_1', 'parking lot', 'Our car is near the parking lot entrance.', 'Our car is near the parking lot entrance.', '/ˈpɑːrkɪŋ lɑːt/', 'Xe của chúng tôi ở gần lối vào bãi đỗ xe.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_22_1_4', 'ten_a2_22_1', 'crossing', 'We waited at the crossing until the cars stopped.', 'We waited at the crossing until the cars stopped.', '/ˈkrɔːsɪŋ/', 'Chúng tôi đợi ở vạch sang đường cho đến khi các phương tiện dừng lại.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_22_1_5', 'ten_a2_22_1', 'subway', 'We took the subway to the museum this morning.', 'We took the subway to the museum this morning.', '/ˈsʌbweɪ/', 'Sáng nay chúng tôi đã đi tàu điện ngầm đến bảo tàng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_22_1_6', 'ten_a2_22_1', 'bakery', 'The bakery near our house sells warm bread every morning.', 'The bakery near our house sells warm bread every morning.', '/ˈbeɪkəri/', 'Cửa hàng bánh mì gần nhà chúng tôi bán bánh mì ấm nóng vào mỗi buổi sáng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_22_1_7', 'ten_a2_22_1', 'car park', 'We found a space in the station car park.', 'We found a space in the station car park.', '/ˈkɑːr pɑːrk/', 'Chúng tôi đã tìm được một chỗ trống trong bãi đậu xe của nhà ga.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_22_1_8', 'ten_a2_22_1', 'square', 'Fold the paper into a square before cutting it.', 'Fold the paper into a square before cutting it.', '/skwer/', 'Hãy gấp tờ giấy thành hình vuông trước khi cắt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_22_1_1', 'en-a2-22', 'ten_a2_22_1', 'listening', 'listening', 'The bus was so crowded that we stood all the way.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi cùng ngồi trên một chiếc ghế dài trong công viên và ngắm nhìn những chú vịt.","Xe của chúng tôi ở gần lối vào bãi đỗ xe.","Xe buýt đông nghịt người đến mức chúng tôi phải đứng suốt cả quãng đường.","Cửa hàng bánh mì gần nhà chúng tôi bán bánh mì ấm nóng vào mỗi buổi sáng."]'::jsonb, 2, 'The bus was so crowded that we stood all the way. → Xe buýt đông nghịt người đến mức chúng tôi phải đứng suốt cả quãng đường.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_22_1_2', 'en-a2-22', 'ten_a2_22_1', 'listening', 'listening', 'We buy fresh bread from our local bakery every morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã đi dạo quanh khu vực cảng ở Bristol ngày hôm qua.","Hãy gấp tờ giấy thành hình vuông trước khi cắt.","Chúng tôi đợi ở vạch sang đường cho đến khi các phương tiện dừng lại.","Chúng tôi mua bánh mì tươi ở cửa hàng bánh địa phương mỗi sáng."]'::jsonb, 3, 'We buy fresh bread from our local bakery every morning. → Chúng tôi mua bánh mì tươi ở cửa hàng bánh địa phương mỗi sáng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_22_1_3', 'en-a2-22', 'ten_a2_22_1', 'listening', 'listening', 'Our car is near the parking lot entrance.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xe của chúng tôi ở gần lối vào bãi đỗ xe.","Chúng tôi tìm thấy lối ra ở phía sau rạp chiếu phim.","Giao thông đông đúc lại khiến chúng tôi đến ăn tối muộn.","Chúng tôi mua bánh mì tươi ở cửa hàng bánh địa phương mỗi sáng."]'::jsonb, 0, 'Our car is near the parking lot entrance. → Xe của chúng tôi ở gần lối vào bãi đỗ xe.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_22_2', 'en-a2-22', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_22_2_1', 'ten_a2_22_2', 'crowded', 'Crowded urban neighbourhoods need accessible parks where residents can exercise and enjoy some personal space.', 'Crowded urban neighbourhoods need accessible parks where residents can exercise and enjoy some personal space.', '/ˈkraʊdɪd/', 'Các khu đô thị đông đúc cần có các công viên dễ tiếp cận để cư dân có thể tập thể dục và tận hưởng không gian riêng tư.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_22_2_2', 'ten_a2_22_2', 'local', 'Supporting local businesses can strengthen community ties and keep more money circulating within the regional economy.', 'Supporting local businesses can strengthen community ties and keep more money circulating within the regional economy.', '/ˈloʊkəl/', 'Việc hỗ trợ các doanh nghiệp địa phương có thể thắt chặt tình làng nghĩa xóm và giữ cho dòng tiền lưu thông nhiều hơn trong nền kinh tế khu vực.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_22_2_3', 'ten_a2_22_2', 'parking lot', 'Planting trees around a parking lot can provide shade and reduce surface temperatures during hot weather.', 'Planting trees around a parking lot can provide shade and reduce surface temperatures during hot weather.', '/ˈpɑːrkɪŋ lɑːt/', 'Trồng cây xanh xung quanh bãi đỗ xe có thể tạo bóng mát và làm giảm nhiệt độ bề mặt trong thời tiết oi bức.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_22_2_4', 'ten_a2_22_2', 'crossing', 'Installing a pedestrian crossing near every school can help protect children and encourage more families to walk.', 'Installing a pedestrian crossing near every school can help protect children and encourage more families to walk.', '/ˈkrɔːsɪŋ/', 'Việc lắp đặt vạch sang đường cho người đi bộ gần mỗi trường học có thể giúp bảo vệ trẻ em và khuyến khích nhiều gia đình đi bộ hơn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_22_2_5', 'ten_a2_22_2', 'subway', 'Expanding subway networks can ease traffic congestion, provided that services remain affordable and accessible to local residents.', 'Expanding subway networks can ease traffic congestion, provided that services remain affordable and accessible to local residents.', '/ˈsʌbweɪ/', 'Việc mở rộng mạng lưới tàu điện ngầm có thể giảm bớt tình trạng ùn tắc giao thông, với điều kiện giá vé phải chăng và người dân địa phương dễ dàng tiếp cận.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_22_2_6', 'ten_a2_22_2', 'bakery', 'Small businesses such as bakeries provide local employment and help maintain vibrant neighbourhood shopping areas.', 'Small businesses such as bakeries provide local employment and help maintain vibrant neighbourhood shopping areas.', '/ˈbeɪkəri/', 'Các doanh nghiệp nhỏ như tiệm bánh mì tạo ra việc làm tại địa phương và góp phần duy trì sự sôi động cho các khu mua sắm trong khu phố.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_22_2_1', 'en-a2-22', 'ten_a2_22_2', 'listening', 'listening', 'Crowded urban neighbourhoods need accessible parks where residents can exercise and enjoy some personal space.', NULL, 'Trong câu vừa nghe, từ “crowded” mang nghĩa nào sau đây?', '["ở phía trước; tiến về phía trước","tùy thuộc; phụ thuộc","chật chội; đông đúc","bất thường; khác lạ"]'::jsonb, 2, '“crowded” (/ˈkraʊdɪd/): chật chội; đông đúc. Câu đầy đủ: Crowded urban neighbourhoods need accessible parks where residents can exercise and enjoy some personal space.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_22_2_2', 'en-a2-22', 'ten_a2_22_2', 'listening', 'listening', 'Supporting local businesses can strengthen community ties and keep more money circulating within the regional economy.', NULL, 'Trong câu vừa nghe, từ “local” mang nghĩa nào sau đây?', '["việc đi lại; sự du lịch","bữa ăn nhẹ; đồ ăn vặt","thuộc địa phương; ở tại địa phương","hạnh phúc; niềm vui"]'::jsonb, 2, '“local” (/ˈloʊkəl/): thuộc địa phương; ở tại địa phương. Câu đầy đủ: Supporting local businesses can strengthen community ties and keep more money circulating within the regional economy.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
