INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_22_2', 'en-a2-22', NULL, 'comprehensive_test', 'listening', 'We buy fresh bread from our local bakery every morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi sẽ gặp bạn ở lối vào sau bữa trưa.","Chúng tôi mua bánh mì tươi ở cửa hàng bánh địa phương mỗi sáng.","Hãy gấp tờ giấy thành hình vuông trước khi cắt.","Chúng tôi đi thang máy vì túi đồ của chúng tôi rất nặng."]'::jsonb, 1, 'We buy fresh bread from our local bakery every morning. → Chúng tôi mua bánh mì tươi ở cửa hàng bánh địa phương mỗi sáng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_22_3', 'en-a2-22', NULL, 'comprehensive_test', 'listening', 'parking lot', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["buồn ngủ; mệt mỏi","bãi đỗ xe ngoài trời","gần như, hầu như","chính tôi; bản thân tôi (tự làm và nhận tác động)"]'::jsonb, 1, 'parking lot (/ˈpɑːrkɪŋ lɑːt/) → bãi đỗ xe ngoài trời', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_22_4', 'en-a2-22', NULL, 'comprehensive_test', 'listening', 'We waited at the crossing until the cars stopped.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đi thang máy vì túi đồ của chúng tôi rất nặng.","Hãy gấp tờ giấy thành hình vuông trước khi cắt.","Chúng tôi đợi ở vạch sang đường cho đến khi các phương tiện dừng lại.","Chúng tôi mua bánh mì tươi ở cửa hàng bánh địa phương mỗi sáng."]'::jsonb, 2, 'We waited at the crossing until the cars stopped. → Chúng tôi đợi ở vạch sang đường cho đến khi các phương tiện dừng lại.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_22_5', 'en-a2-22', NULL, 'comprehensive_test', 'listening', 'subway', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thùng rác","buổi trưa; chính ngọ","hệ thống tàu điện ngầm","phòng vệ sinh công cộng; nhà vệ sinh"]'::jsonb, 2, 'subway (/ˈsʌbweɪ/) → hệ thống tàu điện ngầm; đường hầm dành cho người đi bộ qua đường', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_22_6', 'en-a2-22', NULL, 'comprehensive_test', 'listening', 'The bakery near our house sells warm bread every morning.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xe buýt đông nghịt người đến mức chúng tôi phải đứng suốt cả quãng đường.","Chúng tôi đi thang máy vì túi đồ của chúng tôi rất nặng.","Tiếng mưa gõ lộp bộp trên mái nhà suốt cả đêm.","Cửa hàng bánh mì gần nhà chúng tôi bán bánh mì ấm nóng vào mỗi buổi sáng."]'::jsonb, 3, 'The bakery near our house sells warm bread every morning. → Cửa hàng bánh mì gần nhà chúng tôi bán bánh mì ấm nóng vào mỗi buổi sáng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_22_7', 'en-a2-22', NULL, 'comprehensive_test', 'listening', 'car park', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["món ca-ri; món rau hoặc thịt nấu với các loại gia vị","thịt bò","thứ chín","bãi đậu xe; bãi đỗ xe"]'::jsonb, 3, 'car park (/ˈkɑːr pɑːrk/) → bãi đậu xe; bãi đỗ xe', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
