INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_22_18', 'en-a2-22', NULL, 'comprehensive_test', 'reading', NULL, 'Crowded urban neighbourhoods need accessible parks where residents can exercise and enjoy some personal space.', 'Dựa vào câu trên, từ “crowded” có nghĩa phù hợp nhất là gì?', '["nhật ký; sổ nhật ký","chật chội; đông đúc","thời khóa biểu; lịch trình; bảng giờ tàu chạy","đá; tảng đá; nham thạch"]'::jsonb, 1, 'crowded: chật chội; đông đúc. Dịch cả câu: Các khu đô thị đông đúc cần có các công viên dễ tiếp cận để cư dân có thể tập thể dục và tận hưởng không gian riêng tư.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_22_19', 'en-a2-22', NULL, 'comprehensive_test', 'reading', NULL, 'Supporting local businesses can strengthen community ties and keep more money circulating within the regional economy.', 'Dựa vào câu trên, từ “local” có nghĩa phù hợp nhất là gì?', '["chọn; lựa chọn","thông minh; lanh lợi","thuộc địa phương; ở tại địa phương","bàn chải; cọ vẽ"]'::jsonb, 2, 'local: thuộc địa phương; ở tại địa phương; người địa phương; cục bộ; bộ phận. Dịch cả câu: Việc hỗ trợ các doanh nghiệp địa phương có thể thắt chặt tình làng nghĩa xóm và giữ cho dòng tiền lưu thông nhiều hơn trong nền kinh tế khu vực.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_22_20', 'en-a2-22', NULL, 'comprehensive_test', 'reading', NULL, 'Planting trees around a parking lot can provide shade and reduce surface temperatures during hot weather.', 'Dựa vào câu trên, từ “parking lot” có nghĩa phù hợp nhất là gì?', '["bãi đỗ xe ngoài trời","cổ (phần cơ thể nối đầu với vai)","thứ mười hai","robot; người máy tự động"]'::jsonb, 0, 'parking lot: bãi đỗ xe ngoài trời. Dịch cả câu: Trồng cây xanh xung quanh bãi đỗ xe có thể tạo bóng mát và làm giảm nhiệt độ bề mặt trong thời tiết oi bức.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_22_21', 'en-a2-22', NULL, 'comprehensive_test', 'reading', NULL, 'Installing a pedestrian crossing near every school can help protect children and encourage more families to walk.', 'Dựa vào câu trên, từ “crossing” có nghĩa phù hợp nhất là gì?', '["quyết định; sự lựa chọn","áo chui đầu (len); áo len (tiếng Anh - Anh)","vạch sang đường; chỗ qua đường","chủ sở hữu; người chủ"]'::jsonb, 2, 'crossing: vạch sang đường; chỗ qua đường; chuyến vượt biển; hành trình vượt qua. Dịch cả câu: Việc lắp đặt vạch sang đường cho người đi bộ gần mỗi trường học có thể giúp bảo vệ trẻ em và khuyến khích nhiều gia đình đi bộ hơn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_22_22', 'en-a2-22', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “Bristol (một thành phố ở phía tây nam nước Anh)”', '["hit","disagree","Bristol","pear"]'::jsonb, 2, 'Bristol (một thành phố ở phía tây nam nước Anh) → Bristol (/ˈbrɪstəl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_22_23', 'en-a2-22', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ghế dài”', '["bench","gardener","twin","birth"]'::jsonb, 0, 'ghế dài → bench (/bentʃ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_22_24', 'en-a2-22', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “góc; góc phố; khúc cua”', '["corner","packet","hometown","sunglasses"]'::jsonb, 0, 'góc; góc phố; khúc cua → corner (/ˈkɔːrnər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-23', 'en', 'Bài 23: Thể thao & Vận động (1) - CEFR A2', 'CEFR A2', 'A2 · Thể thao', '19 từ vựng Tiếng Anh CEFR A2 chủ đề thể thao & vận động kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2023, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ski', 'en-a2-23', 'ski', '/skiː/', 'A2', 'trượt tuyết; vát trượt tuyết; ván trượt', 'v.', 'skiing (n.), skier (n.)', NULL, 'Quá khứ là skied, hiện phân từ là skiing; số nhiều của ski là skis.', 'We learned to ski on a gentle snowy slope.', NULL, 'Chúng tôi đã học trượt tuyết trên một sườn dốc tuyết thoai thoải.', '{"wordId":"ski","ukIpa":"/skiː/","usIpa":"/skiː/","cefr":"A2","topic":"sport","senses":[{"pos":"v.","en":"to move over snow wearing long narrow boards on your feet","vi":"trượt tuyết"},{"pos":"n.","en":"a long narrow board worn on a foot for travelling over snow","vi":"vát trượt tuyết; ván trượt"}],"examples":[{"en":"We learned to ski on a gentle snowy slope.","vi":"Chúng tôi đã học trượt tuyết trên một sườn dốc tuyết thoai thoải.","audioKind":"ex"},{"en":"Tourists who ski in mountain resorts contribute to local employment but may also increase environmental pressure.","vi":"Du khách đi trượt tuyết tại các khu nghỉ dưỡng miền núi đóng góp vào việc làm cho người dân địa phương nhưng cũng có thể làm tăng áp lực môi trường.","audioKind":"ex2"}],"collocations":[{"en":"go skiing","vi":"đi trượt tuyết"},{"en":"ski resort","vi":"khu nghỉ dưỡng trượt tuyết"},{"en":"ski slope","vi":"sườn dốc trượt tuyết"},{"en":"a pair of skis","vi":"một đôi ván trượt"}],"wordFamily":["skiing (n.)","skier (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ là skied, hiện phân từ là skiing; số nhiều của ski là skis.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_surfing', 'en-a2-23', 'surfing', '/ˈsɝːfɪŋ/', 'A2', 'môn lướt sóng; lướt web; duyệt trang web', 'n.', 'surf (v.), surfer (n.)', NULL, 'Hoạt động thể thao dùng go surfing; lướt internet cũng có thể nói surf the internet.', 'We went surfing at the beach early this morning.', NULL, 'Chúng tôi đã đi lướt sóng ở bãi biển vào sáng sớm nay.', '{"wordId":"surfing","ukIpa":"/ˈsɜːfɪŋ/","usIpa":"/ˈsɝːfɪŋ/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"The sport of riding waves while standing on a board.","vi":"môn lướt sóng"},{"pos":"n.","en":"The activity of browsing websites on the internet.","vi":"lướt web; duyệt trang web"}],"examples":[{"en":"We went surfing at the beach early this morning.","vi":"Chúng tôi đã đi lướt sóng ở bãi biển vào sáng sớm nay.","audioKind":"ex"},{"en":"The growing popularity of surfing can support coastal economies while increasing pressure on fragile marine environments.","vi":"Sự phổ biến ngày càng tăng của môn lướt sóng có thể thúc đẩy kinh tế vùng ven biển đồng thời làm gia tăng áp lực lên hệ sinh thái biển mỏng manh.","audioKind":"ex2"}],"collocations":[{"en":"go surfing","vi":"đi lướt sóng"},{"en":"surfing lessons","vi":"lớp học lướt sóng"},{"en":"web surfing","vi":"lướt web"}],"wordFamily":["surf (v.)","surfer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Hoạt động thể thao dùng go surfing; lướt internet cũng có thể nói surf the internet.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stadium', 'en-a2-23', 'stadium', '/ˈsteɪdiəm/', 'A2', 'sân vận động', 'n.', NULL, NULL, 'Dạng số nhiều có thể dùng stadiums hoặc stadia, trong đó từ đầu phổ biến hơn.', 'Fans filled the stadium before the football match began.', NULL, 'Người hâm mộ đã lấp đầy sân vận động trước khi trận bóng đá bắt đầu.', '{"wordId":"stadium","ukIpa":"/ˈsteɪdiəm/","usIpa":"/ˈsteɪdiəm/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"a large sports venue with seating around a central area","vi":"sân vận động"}],"examples":[{"en":"Fans filled the stadium before the football match began.","vi":"Người hâm mộ đã lấp đầy sân vận động trước khi trận bóng đá bắt đầu.","audioKind":"ex"},{"en":"Building a new stadium may attract visitors, but its long-term maintenance costs require careful consideration.","vi":"Việc xây dựng một sân vận động mới có thể thu hút khách du lịch, nhưng chi phí bảo trì lâu dài của nó đòi hỏi phải được cân nhắc kỹ lưỡng.","audioKind":"ex2"}],"collocations":[{"en":"football stadium","vi":"sân vận động bóng đá"},{"en":"packed stadium","vi":"sân vận động chật kín chỗ"},{"en":"stadium capacity","vi":"sức chứa của sân vận động"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều có thể dùng stadiums hoặc stadia, trong đó từ đầu phổ biến hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fan', 'en-a2-23', 'fan', '/fæn/', 'A2', 'người hâm mộ; người cuồng nhiệt; tín đồ; quạt; quạt máy; quạt giấy; quạt gió; thổi gió; làm bùng lên', 'n.', NULL, 'Đồng nghĩa: enthusiast, admirer', 'Để diễn đạt ý "người hâm mộ của ai/cái gì", sử dụng cấu trúc a fan of.', 'As a football fan, I rarely miss a match.', NULL, 'Là một người hâm mộ bóng đá, tôi hiếm khi bỏ lỡ trận đấu nào.', '{"wordId":"fan","ukIpa":"/fæn/","usIpa":"/fæn/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"someone who greatly enjoys or admires a person or thing","vi":"người hâm mộ; người cuồng nhiệt; tín đồ"},{"pos":"n.","en":"a device or object moved to create a cooling airflow","vi":"quạt; quạt máy; quạt giấy"},{"pos":"v.","en":"to move air towards something, or make a feeling stronger","vi":"quạt gió; thổi gió; làm bùng lên"}],"examples":[{"en":"As a football fan, I rarely miss a match.","vi":"Là một người hâm mộ bóng đá, tôi hiếm khi bỏ lỡ trận đấu nào.","audioKind":"ex"},{"en":"Sports fans can strengthen local communities by supporting neighbourhood teams and participating in shared events.","vi":"Những người hâm mộ thể thao có thể gắn kết cộng đồng địa phương bằng cách ủng hộ các đội bóng khu vực và tham gia các sự kiện chung.","audioKind":"ex2"}],"collocations":[{"en":"a fan of","vi":"người hâm mộ của..."},{"en":"football fan","vi":"người hâm mộ bóng đá"},{"en":"electric fan","vi":"quạt điện"},{"en":"fan the flames","vi":"thêm dầu vào lửa; thổi bùng ngọn lửa"}],"wordFamily":[],"synonyms":["enthusiast","admirer"],"antonyms":[],"tipVi":"Để diễn đạt ý \"người hâm mộ của ai/cái gì\", sử dụng cấu trúc a fan of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trainer', 'en-a2-23', 'trainer', '/ˈtreɪnər/', 'A2', 'huấn luyện viên; chuyên gia đào tạo; giày thể thao; giày chạy bộ', 'n.', 'train (v.), training (n.), trainee (n.)', 'Đồng nghĩa: coach, instructor', 'Giày thể thao tiếng Anh Anh thường dùng trainers, còn tiếng Anh Mỹ dùng sneakers.', 'My trainer showed me how to lift weights safely.', NULL, 'Huấn luyện viên của tôi đã chỉ cho tôi cách nâng tạ một cách an toàn.', '{"wordId":"trainer","ukIpa":"/ˈtreɪnə/","usIpa":"/ˈtreɪnər/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"someone who teaches people or animals particular skills","vi":"huấn luyện viên; chuyên gia đào tạo"},{"pos":"n.","en":"a shoe designed for sport or casual wear","vi":"giày thể thao; giày chạy bộ"}],"examples":[{"en":"My trainer showed me how to lift weights safely.","vi":"Huấn luyện viên của tôi đã chỉ cho tôi cách nâng tạ một cách an toàn.","audioKind":"ex"},{"en":"A qualified trainer can help employees develop practical skills that improve their performance at work.","vi":"Một huấn luyện viên đủ trình độ có thể giúp nhân viên phát triển các kỹ năng thực tế nhằm nâng cao hiệu quả công việc.","audioKind":"ex2"}],"collocations":[{"en":"personal trainer","vi":"huấn luyện viên cá nhân"},{"en":"fitness trainer","vi":"huấn luyện viên thể hình"},{"en":"a pair of trainers","vi":"một đôi giày thể thao"}],"wordFamily":["train (v.)","training (n.)","trainee (n.)"],"synonyms":["coach","instructor"],"antonyms":[],"tipVi":"Giày thể thao tiếng Anh Anh thường dùng trainers, còn tiếng Anh Mỹ dùng sneakers.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_olympics', 'en-a2-23', 'Olympics', '/əˈlɪmpɪks/', 'A2', 'thế vận hội Olympic', 'n.', 'Olympic (adj.), Olympian (n.)', 'Đồng nghĩa: Olympic Games', 'Viết hoa chữ cái đầu, thường đi với mạo từ the; còn được gọi là the Olympic Games.', 'Our family watched the Olympics together after dinner.', NULL, 'Gia đình tôi cùng nhau xem Thế vận hội sau bữa tối.', '{"wordId":"olympics","ukIpa":"/əˈlɪmpɪks/","usIpa":"/əˈlɪmpɪks/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"An international sporting competition with summer and winter editions.","vi":"thế vận hội Olympic"}],"examples":[{"en":"Our family watched the Olympics together after dinner.","vi":"Gia đình tôi cùng nhau xem Thế vận hội sau bữa tối.","audioKind":"ex"},{"en":"Hosting the Olympics can improve transport infrastructure, but governments must consider the long-term costs of maintaining sports facilities.","vi":"Việc đăng cai Thế vận hội có thể cải thiện cơ sở hạ tầng giao thông, nhưng chính phủ phải cân nhắc chi phí dài hạn để bảo trì các cơ sở thể thao.","audioKind":"ex2"}],"collocations":[{"en":"host the Olympics","vi":"đăng cai Thế vận hội"},{"en":"compete in the Olympics","vi":"thi đấu tại Thế vận hội"},{"en":"the Summer Olympics","vi":"Thế vận hội Mùa hè"},{"en":"the Winter Olympics","vi":"Thế vận hội Mùa đông"}],"wordFamily":["Olympic (adj.)","Olympian (n.)"],"synonyms":["Olympic Games"],"antonyms":[],"tipVi":"Viết hoa chữ cái đầu, thường đi với mạo từ the; còn được gọi là the Olympic Games.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_climbing', 'en-a2-23', 'climbing', '/ˈklaɪmɪŋ/', 'A2', 'môn leo núi; môn thể thao leo vách đá (hoặc tường nhân tạo); có tính chất leo; bám vào để leo lên (của thực vật)', 'n.', 'climb (v.), climb (n.), climber (n.)', NULL, 'Trong từ climb, phụ âm b là âm câm không phát âm; cụm climbing plants dùng để chỉ các loài thực vật thân leo.', 'I tried indoor climbing with my sister yesterday.', NULL, 'Hôm qua tôi đã thử chơi môn leo núi trong nhà cùng chị gái.', '{"wordId":"climbing","ukIpa":"/ˈklaɪmɪŋ/","usIpa":"/ˈklaɪmɪŋ/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"The sport of going up rocks, mountains, or artificial walls.","vi":"môn leo núi; môn thể thao leo vách đá (hoặc tường nhân tạo)"},{"pos":"adj.","en":"Growing upwards by attaching to or winding around supports.","vi":"có tính chất leo; bám vào để leo lên (của thực vật)"}],"examples":[{"en":"I tried indoor climbing with my sister yesterday.","vi":"Hôm qua tôi đã thử chơi môn leo núi trong nhà cùng chị gái.","audioKind":"ex"},{"en":"Schools can use supervised climbing activities to develop students'' confidence, physical coordination, and ability to assess risks.","vi":"Các trường học có thể tổ chức các hoạt động leo núi có giám sát để phát triển sự tự tin, khả năng phối hợp thể chất và kỹ năng đánh giá rủi ro cho học sinh.","audioKind":"ex2"}],"collocations":[{"en":"rock climbing","vi":"leo núi đá"},{"en":"indoor climbing","vi":"leo núi trong nhà"},{"en":"climbing equipment","vi":"trang thiết bị leo núi"},{"en":"climbing plants","vi":"cây leo"}],"wordFamily":["climb (v.)","climb (n.)","climber (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong từ climb, phụ âm b là âm câm không phát âm; cụm climbing plants dùng để chỉ các loài thực vật thân leo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_badminton', 'en-a2-23', 'badminton', '/ˈbædmɪntən/', 'A2', 'môn cầu lông', 'n.', NULL, NULL, 'Tên môn thể thao thường không đếm được; cụm từ "chơi cầu lông" dùng play badminton.', 'We play badminton at the sports centre every Saturday.', NULL, 'Chúng tôi chơi cầu lông tại trung tâm thể thao vào mỗi thứ Bảy.', '{"wordId":"badminton","ukIpa":"/ˈbædmɪntən/","usIpa":"/ˈbædmɪntən/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"A sport involving hitting a shuttlecock over a net with rackets","vi":"môn cầu lông"}],"examples":[{"en":"We play badminton at the sports centre every Saturday.","vi":"Chúng tôi chơi cầu lông tại trung tâm thể thao vào mỗi thứ Bảy.","audioKind":"ex"},{"en":"Schools can encourage regular exercise by offering accessible activities such as badminton and swimming.","vi":"Nhà trường có thể khuyến khích việc tập thể dục thường xuyên bằng cách cung cấp các hoạt động dễ tiếp cận như cầu lông và bơi lội.","audioKind":"ex2"}],"collocations":[{"en":"play badminton","vi":"chơi cầu lông"},{"en":"badminton court","vi":"sân cầu lông"},{"en":"badminton racket","vi":"vợt cầu lông"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên môn thể thao thường không đếm được; cụm từ \"chơi cầu lông\" dùng play badminton.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_running', 'en-a2-23', 'running', '/ˈrʌnɪŋ/', 'A2', 'chạy; môn chạy; sự quản lý; sự vận hành; chảy liên tục; đang hoạt động', 'n.', 'run (v.), runner (n.)', NULL, 'Biểu thị hoạt động chạy (running) thì không đếm được; cụm "the running of" dùng để chỉ việc quản lý.', 'Running along the beach always clears my head.', NULL, 'Chạy dọc theo bờ biển luôn giúp tôi sảng khoái đầu óc.', '{"wordId":"running","ukIpa":"/ˈrʌnɪŋ/","usIpa":"/ˈrʌnɪŋ/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"the activity or sport of moving quickly on foot","vi":"chạy; môn chạy"},{"pos":"n.","en":"the work of managing or operating something","vi":"sự quản lý; sự vận hành"},{"pos":"adj.","en":"flowing continuously or operating rather than stopped","vi":"chảy liên tục; đang hoạt động"}],"examples":[{"en":"Running along the beach always clears my head.","vi":"Chạy dọc theo bờ biển luôn giúp tôi sảng khoái đầu óc.","audioKind":"ex"},{"en":"Local volunteers play a crucial role in the daily running of community sports centres.","vi":"Các tình nguyện viên địa phương đóng vai trò thiết yếu trong việc quản lý hằng ngày của các trung tâm thể thao cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"go running","vi":"đi chạy bộ"},{"en":"day-to-day running","vi":"hoạt động hằng ngày"},{"en":"running water","vi":"nước máy; nước chảy"},{"en":"running costs","vi":"chi phí vận hành"}],"wordFamily":["run (v.)","runner (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Biểu thị hoạt động chạy (running) thì không đếm được; cụm \"the running of\" dùng để chỉ việc quản lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jogging', 'en-a2-23', 'jogging', '/ˈdʒɑːɡɪŋ/', 'A2', 'chạy bộ (chạy chậm và đều như một hình thức tập thể dục)', 'n.', 'jog (v.), jogger (n.)', NULL, 'Khi chuyển động từ jog sang dạng V-ing thành jogging, phải gấp đôi phụ âm g.', 'She goes jogging around the park before breakfast.', NULL, 'Cô ấy đi chạy bộ quanh công viên trước bữa sáng.', '{"wordId":"jogging","ukIpa":"/ˈdʒɒɡɪŋ/","usIpa":"/ˈdʒɑːɡɪŋ/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"Running slowly and steadily as a form of exercise.","vi":"chạy bộ (chạy chậm và đều như một hình thức tập thể dục)"}],"examples":[{"en":"She goes jogging around the park before breakfast.","vi":"Cô ấy đi chạy bộ quanh công viên trước bữa sáng.","audioKind":"ex"},{"en":"Regular jogging can improve physical fitness, especially when combined with a balanced diet and adequate rest.","vi":"Chạy bộ thường xuyên có thể cải thiện thể lực, đặc biệt là khi kết hợp với chế độ ăn uống cân bằng và nghỉ ngơi đầy đủ.","audioKind":"ex2"}],"collocations":[{"en":"go jogging","vi":"đi chạy bộ"},{"en":"jogging shoes","vi":"giày chạy bộ"},{"en":"jogging route","vi":"tuyến đường chạy bộ"}],"wordFamily":["jog (v.)","jogger (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chuyển động từ jog sang dạng V-ing thành jogging, phải gấp đôi phụ âm g.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skateboard', 'en-a2-23', 'skateboard', '/ˈskeɪtbɔːrd/', 'A2', 'ván trượt; trượt ván; đi ván trượt', 'n.', 'skateboarding (n.), skateboarder (n.)', NULL, 'Skateboard không có tay cầm; trong khi scooter thường có tay cầm.', 'He carried his skateboard home when the rain started.', NULL, 'Cậu ấy mang ván trượt về nhà khi trời bắt đầu đổ mưa.', '{"wordId":"skateboard","ukIpa":"/ˈskeɪtbɔːd/","usIpa":"/ˈskeɪtbɔːrd/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"A narrow board with small wheels, ridden standing up.","vi":"ván trượt"},{"pos":"v.","en":"To move or perform tricks on a skateboard.","vi":"trượt ván; đi ván trượt"}],"examples":[{"en":"He carried his skateboard home when the rain started.","vi":"Cậu ấy mang ván trượt về nhà khi trời bắt đầu đổ mưa.","audioKind":"ex"},{"en":"Providing dedicated areas for skateboard users can encourage physical activity while reducing conflicts with pedestrians in public spaces.","vi":"Việc cung cấp các khu vực dành riêng cho người trượt ván có thể khuyến khích hoạt động thể chất đồng thời giảm thiểu xung đột với người đi bộ trong không gian công cộng.","audioKind":"ex2"}],"collocations":[{"en":"ride a skateboard","vi":"chơi ván trượt"},{"en":"skateboard tricks","vi":"kỹ thuật trượt ván"},{"en":"a skateboard park","vi":"công viên trượt ván"}],"wordFamily":["skateboarding (n.)","skateboarder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Skateboard không có tay cầm; trong khi scooter thường có tay cầm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beat', 'en-a2-23', 'beat', '/biːt/', 'A2', 'đánh bại; thắng; đập liên hồi; đập (nhịp tim); nhịp (âm thanh hoặc chuyển động)', 'v.', 'beaten (adj.), unbeaten (adj.), beater (n.)', 'Đồng nghĩa: defeat · Trái nghĩa: lose to', 'Quá khứ là beat, quá phân từ là beaten; thắng trong trận đấu dùng win.', 'My sister beat me at chess again yesterday.', NULL, 'Chị gái lại vừa đánh bại tôi ở ván cờ vua ngày hôm qua.', '{"wordId":"beat","ukIpa":"/biːt/","usIpa":"/biːt/","cefr":"A2","topic":"sport","senses":[{"pos":"v.","en":"To defeat someone in a game, competition, or contest.","vi":"đánh bại; thắng"},{"pos":"v.","en":"To hit repeatedly, or move with a regular rhythm.","vi":"đập liên hồi; đập (nhịp tim)"},{"pos":"n.","en":"A regular pulse of sound or movement.","vi":"nhịp (âm thanh hoặc chuyển động)"}],"examples":[{"en":"My sister beat me at chess again yesterday.","vi":"Chị gái lại vừa đánh bại tôi ở ván cờ vua ngày hôm qua.","audioKind":"ex"},{"en":"Athletes need consistent training and psychological support to beat their strongest competitors in international events.","vi":"Các vận động viên cần tập luyện kiên trì và có sự hỗ trợ tâm lý để đánh bại các đối thủ mạnh nhất trong các giải đấu quốc tế.","audioKind":"ex2"}],"collocations":[{"en":"beat an opponent","vi":"đánh bại đối thủ"},{"en":"beat a record","vi":"phá kỷ lục"},{"en":"a steady beat","vi":"nhịp đập đều đặn"},{"en":"beat an egg","vi":"đánh trứng"}],"wordFamily":["beaten (adj.)","unbeaten (adj.)","beater (n.)"],"synonyms":["defeat"],"antonyms":["lose to"],"tipVi":"Quá khứ là beat, quá phân từ là beaten; thắng trong trận đấu dùng win.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cricket', 'en-a2-23', 'cricket', '/ˈkrɪkɪt/', 'A2', 'môn bóng gậy; môn cricket; con dế', 'n.', 'cricketer (n.)', NULL, 'Chỉ môn thể thao cricket là danh từ không đếm được; chỉ con dế là danh từ đếm được.', 'We played cricket in the park after lunch.', NULL, 'Chúng tôi đã chơi cricket ở công viên sau bữa trưa.', '{"wordId":"cricket","ukIpa":"/ˈkrɪkɪt/","usIpa":"/ˈkrɪkɪt/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"A team sport using a bat, ball, and wickets.","vi":"môn bóng gậy; môn cricket"},{"pos":"n.","en":"A jumping insect that makes a chirping sound.","vi":"con dế"}],"examples":[{"en":"We played cricket in the park after lunch.","vi":"Chúng tôi đã chơi cricket ở công viên sau bữa trưa.","audioKind":"ex"},{"en":"Team sports such as cricket can help young people develop cooperation skills and build lasting friendships.","vi":"Các môn thể thao đồng đội như cricket có thể giúp giới trẻ phát triển kỹ năng hợp tác và xây dựng tình bạn lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"play cricket","vi":"chơi cricket"},{"en":"a cricket match","vi":"một trận đấu cricket"},{"en":"a cricket bat","vi":"gậy đánh cricket"},{"en":"crickets chirping","vi":"dế kêu"}],"wordFamily":["cricketer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ môn thể thao cricket là danh từ không đếm được; chỉ con dế là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ping-pong', 'en-a2-23', 'ping-pong', '/ˈpɪŋ pɑːŋ/', 'A2', 'bóng bàn; di chuyển qua lại; liên tục qua lại', 'n.', NULL, 'Đồng nghĩa: table tennis', 'Từ này mang tính khẩu ngữ; trong văn viết và thi đấu chính thức, từ table tennis được dùng phổ biến hơn.', 'We played ping-pong together while waiting for dinner.', NULL, 'Chúng tôi cùng chơi bóng bàn trong lúc chờ bữa tối.', '{"wordId":"ping-pong","ukIpa":"/ˈpɪŋ pɒŋ/","usIpa":"/ˈpɪŋ pɑːŋ/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"A game hitting a light ball across a table with bats","vi":"bóng bàn"},{"pos":"v.","en":"To move or pass repeatedly back and forth","vi":"di chuyển qua lại; liên tục qua lại"}],"examples":[{"en":"We played ping-pong together while waiting for dinner.","vi":"Chúng tôi cùng chơi bóng bàn trong lúc chờ bữa tối.","audioKind":"ex"},{"en":"Community centres can offer inexpensive activities such as ping-pong to encourage social interaction among older residents.","vi":"Các trung tâm cộng đồng có thể cung cấp các hoạt động chi phí thấp như bóng bàn nhằm khuyến khích giao lưu xã hội giữa các cư dân lớn tuổi.","audioKind":"ex2"}],"collocations":[{"en":"play ping-pong","vi":"chơi bóng bàn"},{"en":"ping-pong table","vi":"bàn bóng bàn"},{"en":"ping-pong ball","vi":"quả bóng bàn"},{"en":"ping-pong bat","vi":"vợt bóng bàn"}],"wordFamily":[],"synonyms":["table tennis"],"antonyms":[],"tipVi":"Từ này mang tính khẩu ngữ; trong văn viết và thi đấu chính thức, từ table tennis được dùng phổ biến hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skateboarding', 'en-a2-23', 'skateboarding', '/ˈskeɪtbɔːrdɪŋ/', 'A2', 'trò chơi trượt ván; bộ môn trượt ván', 'n.', 'skateboard (n.), skateboard (v.), skateboarder (n.)', NULL, 'Dùng skateboarding để chỉ môn thể thao, trong khi skateboard chỉ dụng cụ ván trượt.', 'We went skateboarding at the park after lunch.', NULL, 'Chúng tôi ra công viên trượt ván sau bữa trưa.', '{"wordId":"skateboarding","ukIpa":"/ˈskeɪtbɔːdɪŋ/","usIpa":"/ˈskeɪtbɔːrdɪŋ/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"the activity of riding and performing tricks on a skateboard","vi":"trò chơi trượt ván; bộ môn trượt ván"}],"examples":[{"en":"We went skateboarding at the park after lunch.","vi":"Chúng tôi ra công viên trượt ván sau bữa trưa.","audioKind":"ex"},{"en":"Dedicated skateboarding facilities give young people safe spaces to exercise and develop their balance and coordination.","vi":"Các cơ sở vật chất chuyên dụng cho môn trượt ván mang lại cho giới trẻ không gian an toàn để rèn luyện sức khỏe cũng như phát triển khả năng giữ thăng bằng và phối hợp vận động.","audioKind":"ex2"}],"collocations":[{"en":"go skateboarding","vi":"đi trượt ván"},{"en":"skateboarding skills","vi":"kỹ năng trượt ván"},{"en":"skateboarding facilities","vi":"cơ sở vật chất trượt ván"}],"wordFamily":["skateboard (n.)","skateboard (v.)","skateboarder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng skateboarding để chỉ môn thể thao, trong khi skateboard chỉ dụng cụ ván trượt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skiing', 'en-a2-23', 'skiing', '/ˈskiːɪŋ/', 'A2', 'môn trượt tuyết; hoạt động trượt tuyết', 'n.', 'ski (v.), skier (n.)', NULL, 'Trượt tuyết trên tuyết dùng go skiing; còn trượt nước phải nói là water skiing.', 'We went skiing together during our winter holiday.', NULL, 'Chúng tôi đã cùng nhau đi trượt tuyết trong kỳ nghỉ đông.', '{"wordId":"skiing","ukIpa":"/ˈskiːɪŋ/","usIpa":"/ˈskiːɪŋ/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"The activity of moving over snow on skis.","vi":"môn trượt tuyết; hoạt động trượt tuyết"}],"examples":[{"en":"We went skiing together during our winter holiday.","vi":"Chúng tôi đã cùng nhau đi trượt tuyết trong kỳ nghỉ đông.","audioKind":"ex"},{"en":"Skiing attracts winter tourists to mountain regions, creating seasonal jobs but increasing demand for water.","vi":"Hoạt động trượt tuyết thu hút khách du lịch mùa đông đến các vùng núi, tạo ra nhiều việc làm thời vụ nhưng đồng thời cũng làm tăng nhu cầu sử dụng nước.","audioKind":"ex2"}],"collocations":[{"en":"go skiing","vi":"đi trượt tuyết"},{"en":"cross-country skiing","vi":"trượt tuyết băng đồng"},{"en":"downhill skiing","vi":"trượt tuyết đổ dốc"},{"en":"skiing lessons","vi":"các bài học trượt tuyết"}],"wordFamily":["ski (v.)","skier (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trượt tuyết trên tuyết dùng go skiing; còn trượt nước phải nói là water skiing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_soccer', 'en-a2-23', 'soccer', '/ˈsɑːkər/', 'A2', 'môn bóng đá', 'n.', NULL, 'Đồng nghĩa: football', 'Tiếng Anh - Anh thường gọi là football, còn tiếng Anh - Mỹ gọi là soccer.', 'We play soccer in the park every Saturday morning.', NULL, 'Chúng tôi chơi đá bóng ở công viên vào mỗi sáng thứ Bảy.', '{"wordId":"soccer","ukIpa":"/ˈsɒkə/","usIpa":"/ˈsɑːkər/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"A game where two teams kick a ball into goals.","vi":"môn bóng đá"}],"examples":[{"en":"We play soccer in the park every Saturday morning.","vi":"Chúng tôi chơi đá bóng ở công viên vào mỗi sáng thứ Bảy.","audioKind":"ex"},{"en":"Community soccer clubs provide affordable exercise and help young people develop teamwork skills outside the classroom.","vi":"Các câu lạc bộ bóng đá cộng đồng cung cấp cơ hội rèn luyện sức khỏe với chi phí phải chăng, giúp giới trẻ phát triển kỹ năng làm việc nhóm ngoài giờ học trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"play soccer","vi":"chơi bóng đá"},{"en":"soccer team","vi":"đội bóng đá"},{"en":"soccer field","vi":"sân bóng đá"},{"en":"soccer match","vi":"trận đấu bóng đá"}],"wordFamily":[],"synonyms":["football"],"antonyms":[],"tipVi":"Tiếng Anh - Anh thường gọi là football, còn tiếng Anh - Mỹ gọi là soccer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_runner', 'en-a2-23', 'runner', '/ˈrʌnər/', 'A2', 'người chạy bộ; vận động viên chạy đua', 'n.', 'run (v.), running (n.)', NULL, 'Khi thêm -er vào run ta gấp đôi chữ n; runner-up có nghĩa là người về nhì (á quân).', 'A runner in bright shoes passed us by the lake.', NULL, 'Một người chạy bộ mang giày màu sáng đã chạy qua chúng tôi ở bên hồ.', '{"wordId":"runner","ukIpa":"/ˈrʌnə/","usIpa":"/ˈrʌnər/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"a person who runs, especially for exercise or in races","vi":"người chạy bộ; vận động viên chạy đua"}],"examples":[{"en":"A runner in bright shoes passed us by the lake.","vi":"Một người chạy bộ mang giày màu sáng đã chạy qua chúng tôi ở bên hồ.","audioKind":"ex"},{"en":"Urban parks provide runners with safer exercise spaces away from heavy traffic and polluted main roads.","vi":"Các công viên đô thị cung cấp cho người chạy bộ không gian tập luyện an toàn hơn, tránh xa các luồng giao thông đông đúc và những tuyến đường chính ô nhiễm.","audioKind":"ex2"}],"collocations":[{"en":"long-distance runner","vi":"vận động viên chạy cự ly dài"},{"en":"marathon runner","vi":"vận động viên chạy ma-ra-tông"},{"en":"keen runner","vi":"người rất thích chạy bộ"}],"wordFamily":["run (v.)","running (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi thêm -er vào run ta gấp đôi chữ n; runner-up có nghĩa là người về nhì (á quân).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_snowboarding', 'en-a2-23', 'snowboarding', '/ˈsnoʊbɔːrdɪŋ/', 'A2', 'môn trượt ván tuyết', 'n.', 'snowboard (n.), snowboard (v.), snowboarder (n.)', NULL, 'snowboarding là cả hai chân được gắn cố định trên một chiếc ván duy nhất, khác với môn trượt tuyết hai ván (skiing).', 'I tried snowboarding yesterday and landed in soft snow.', NULL, 'Hôm qua tôi đã thử trượt ván tuyết và ngã vào lớp tuyết mềm.', '{"wordId":"snowboarding","ukIpa":"/ˈsnəʊbɔːdɪŋ/","usIpa":"/ˈsnoʊbɔːrdɪŋ/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"The sport of travelling down snowy slopes on one board.","vi":"môn trượt ván tuyết"}],"examples":[{"en":"I tried snowboarding yesterday and landed in soft snow.","vi":"Hôm qua tôi đã thử trượt ván tuyết và ngã vào lớp tuyết mềm.","audioKind":"ex"},{"en":"Snowboarding lessons should include safety training so that beginners can share mountain slopes responsibly.","vi":"Các lớp học trượt ván tuyết nên bao gồm đào tạo an toàn để người mới bắt đầu có thể cùng chia sẻ sườn dốc một cách có trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"go snowboarding","vi":"đi trượt ván tuyết"},{"en":"snowboarding lessons","vi":"lớp học trượt ván tuyết"},{"en":"snowboarding equipment","vi":"dụng cụ trượt ván tuyết"}],"wordFamily":["snowboard (n.)","snowboard (v.)","snowboarder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"snowboarding là cả hai chân được gắn cố định trên một chiếc ván duy nhất, khác với môn trượt tuyết hai ván (skiing).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_23_1', 'en-a2-23', 'Cách dùng “snowboarding” (n.) — môn trượt ván tuyết', 'go snowboarding  ·  snowboarding lessons  ·  snowboarding equipment', 'snowboarding là cả hai chân được gắn cố định trên một chiếc ván duy nhất, khác với môn trượt tuyết hai ván (skiing).', 'Họ từ (Word Family): snowboard (n.), snowboard (v.), snowboarder (n.)', '[{"hanzi":"I tried snowboarding yesterday and landed in soft snow.","pinyin":"","meaning":"Hôm qua tôi đã thử trượt ván tuyết và ngã vào lớp tuyết mềm."},{"hanzi":"Snowboarding lessons should include safety training so that beginners can share mountain slopes responsibly.","pinyin":"","meaning":"Các lớp học trượt ván tuyết nên bao gồm đào tạo an toàn để người mới bắt đầu có thể cùng chia sẻ sườn dốc một cách có trách nhiệm."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_23_2', 'en-a2-23', 'Cách dùng “climbing” (n.) — môn leo núi; môn thể thao leo vách đá (hoặc tường nhân tạo)', 'rock climbing  ·  indoor climbing  ·  climbing equipment', 'Trong từ climb, phụ âm b là âm câm không phát âm; cụm climbing plants dùng để chỉ các loài thực vật thân leo.', 'Họ từ (Word Family): climb (v.), climb (n.), climber (n.)', '[{"hanzi":"I tried indoor climbing with my sister yesterday.","pinyin":"","meaning":"Hôm qua tôi đã thử chơi môn leo núi trong nhà cùng chị gái."},{"hanzi":"Schools can use supervised climbing activities to develop students'' confidence, physical coordination, and ability to assess risks.","pinyin":"","meaning":"Các trường học có thể tổ chức các hoạt động leo núi có giám sát để phát triển sự tự tin, khả năng phối hợp thể chất và kỹ năng đánh giá rủi ro cho học sinh."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_23_3', 'en-a2-23', 'Cách dùng “ping-pong” (n.) — bóng bàn', 'play ping-pong  ·  ping-pong table  ·  ping-pong ball', 'Từ này mang tính khẩu ngữ; trong văn viết và thi đấu chính thức, từ table tennis được dùng phổ biến hơn.', 'Đồng nghĩa: table tennis', '[{"hanzi":"We played ping-pong together while waiting for dinner.","pinyin":"","meaning":"Chúng tôi cùng chơi bóng bàn trong lúc chờ bữa tối."},{"hanzi":"Community centres can offer inexpensive activities such as ping-pong to encourage social interaction among older residents.","pinyin":"","meaning":"Các trung tâm cộng đồng có thể cung cấp các hoạt động chi phí thấp như bóng bàn nhằm khuyến khích giao lưu xã hội giữa các cư dân lớn tuổi."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_23_4', 'en-a2-23', 'Cách dùng “running” (n.) — chạy; môn chạy', 'go running  ·  day-to-day running  ·  running water', 'Biểu thị hoạt động chạy (running) thì không đếm được; cụm "the running of" dùng để chỉ việc quản lý.', 'Họ từ (Word Family): run (v.), runner (n.)', '[{"hanzi":"Running along the beach always clears my head.","pinyin":"","meaning":"Chạy dọc theo bờ biển luôn giúp tôi sảng khoái đầu óc."},{"hanzi":"Local volunteers play a crucial role in the daily running of community sports centres.","pinyin":"","meaning":"Các tình nguyện viên địa phương đóng vai trò thiết yếu trong việc quản lý hằng ngày của các trung tâm thể thao cộng đồng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_23_1', 'en-a2-23', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
