INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_23_1_2', 'ten_a2_23_1', 'surfing', 'We went surfing at the beach early this morning.', 'We went surfing at the beach early this morning.', '/ˈsɝːfɪŋ/', 'Chúng tôi đã đi lướt sóng ở bãi biển vào sáng sớm nay.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_23_1_3', 'ten_a2_23_1', 'stadium', 'Fans filled the stadium before the football match began.', 'Fans filled the stadium before the football match began.', '/ˈsteɪdiəm/', 'Người hâm mộ đã lấp đầy sân vận động trước khi trận bóng đá bắt đầu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_23_1_4', 'ten_a2_23_1', 'fan', 'As a football fan, I rarely miss a match.', 'As a football fan, I rarely miss a match.', '/fæn/', 'Là một người hâm mộ bóng đá, tôi hiếm khi bỏ lỡ trận đấu nào.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_23_1_5', 'ten_a2_23_1', 'trainer', 'My trainer showed me how to lift weights safely.', 'My trainer showed me how to lift weights safely.', '/ˈtreɪnər/', 'Huấn luyện viên của tôi đã chỉ cho tôi cách nâng tạ một cách an toàn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
