INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_23_1_8', 'ten_a2_23_1', 'badminton', 'We play badminton at the sports centre every Saturday.', 'We play badminton at the sports centre every Saturday.', '/ˈbædmɪntən/', 'Chúng tôi chơi cầu lông tại trung tâm thể thao vào mỗi thứ Bảy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_23_1_1', 'en-a2-23', 'ten_a2_23_1', 'listening', 'listening', 'We learned to ski on a gentle snowy slope.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hôm qua tôi đã thử trượt ván tuyết và ngã vào lớp tuyết mềm.","Chúng tôi đã học trượt tuyết trên một sườn dốc tuyết thoai thoải.","Huấn luyện viên của tôi đã chỉ cho tôi cách nâng tạ một cách an toàn.","Chúng tôi chơi đá bóng ở công viên vào mỗi sáng thứ Bảy."]'::jsonb, 1, 'We learned to ski on a gentle snowy slope. → Chúng tôi đã học trượt tuyết trên một sườn dốc tuyết thoai thoải.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_23_1_2', 'en-a2-23', 'ten_a2_23_1', 'listening', 'listening', 'We went surfing at the beach early this morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã đi lướt sóng ở bãi biển vào sáng sớm nay.","Chúng tôi cùng chơi bóng bàn trong lúc chờ bữa tối.","Chúng tôi ra công viên trượt ván sau bữa trưa.","Chị gái lại vừa đánh bại tôi ở ván cờ vua ngày hôm qua."]'::jsonb, 0, 'We went surfing at the beach early this morning. → Chúng tôi đã đi lướt sóng ở bãi biển vào sáng sớm nay.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_23_1_3', 'en-a2-23', 'ten_a2_23_1', 'listening', 'listening', 'Fans filled the stadium before the football match began.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Người hâm mộ đã lấp đầy sân vận động trước khi trận bóng đá bắt đầu.","Chúng tôi ra công viên trượt ván sau bữa trưa.","Hôm qua tôi đã thử chơi môn leo núi trong nhà cùng chị gái.","Chúng tôi chơi đá bóng ở công viên vào mỗi sáng thứ Bảy."]'::jsonb, 0, 'Fans filled the stadium before the football match began. → Người hâm mộ đã lấp đầy sân vận động trước khi trận bóng đá bắt đầu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_23_2', 'en-a2-23', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_23_2_1', 'ten_a2_23_2', 'ski', 'Tourists who ski in mountain resorts contribute to local employment but may also increase environmental pressure.', 'Tourists who ski in mountain resorts contribute to local employment but may also increase environmental pressure.', '/skiː/', 'Du khách đi trượt tuyết tại các khu nghỉ dưỡng miền núi đóng góp vào việc làm cho người dân địa phương nhưng cũng có thể làm tăng áp lực môi trường.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_23_2_2', 'ten_a2_23_2', 'surfing', 'The growing popularity of surfing can support coastal economies while increasing pressure on fragile marine environments.', 'The growing popularity of surfing can support coastal economies while increasing pressure on fragile marine environments.', '/ˈsɝːfɪŋ/', 'Sự phổ biến ngày càng tăng của môn lướt sóng có thể thúc đẩy kinh tế vùng ven biển đồng thời làm gia tăng áp lực lên hệ sinh thái biển mỏng manh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_23_2_3', 'ten_a2_23_2', 'stadium', 'Building a new stadium may attract visitors, but its long-term maintenance costs require careful consideration.', 'Building a new stadium may attract visitors, but its long-term maintenance costs require careful consideration.', '/ˈsteɪdiəm/', 'Việc xây dựng một sân vận động mới có thể thu hút khách du lịch, nhưng chi phí bảo trì lâu dài của nó đòi hỏi phải được cân nhắc kỹ lưỡng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_23_2_4', 'ten_a2_23_2', 'fan', 'Sports fans can strengthen local communities by supporting neighbourhood teams and participating in shared events.', 'Sports fans can strengthen local communities by supporting neighbourhood teams and participating in shared events.', '/fæn/', 'Những người hâm mộ thể thao có thể gắn kết cộng đồng địa phương bằng cách ủng hộ các đội bóng khu vực và tham gia các sự kiện chung.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_23_2_5', 'ten_a2_23_2', 'trainer', 'A qualified trainer can help employees develop practical skills that improve their performance at work.', 'A qualified trainer can help employees develop practical skills that improve their performance at work.', '/ˈtreɪnər/', 'Một huấn luyện viên đủ trình độ có thể giúp nhân viên phát triển các kỹ năng thực tế nhằm nâng cao hiệu quả công việc.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_23_2_6', 'ten_a2_23_2', 'Olympics', 'Hosting the Olympics can improve transport infrastructure, but governments must consider the long-term costs of maintaining sports facilities.', 'Hosting the Olympics can improve transport infrastructure, but governments must consider the long-term costs of maintaining sports facilities.', '/əˈlɪmpɪks/', 'Việc đăng cai Thế vận hội có thể cải thiện cơ sở hạ tầng giao thông, nhưng chính phủ phải cân nhắc chi phí dài hạn để bảo trì các cơ sở thể thao.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_23_2_1', 'en-a2-23', 'ten_a2_23_2', 'listening', 'listening', 'Tourists who ski in mountain resorts contribute to local employment but may also increase environmental pressure.', NULL, 'Trong câu vừa nghe, từ “ski” mang nghĩa nào sau đây?', '["ngón tay","ba lô đeo lưng","thất lễ; thô lỗ; bất lịch sự","trượt tuyết"]'::jsonb, 3, '“ski” (/skiː/): trượt tuyết. Câu đầy đủ: Tourists who ski in mountain resorts contribute to local employment but may also increase environmental pressure.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_23_2_2', 'en-a2-23', 'ten_a2_23_2', 'listening', 'listening', 'The growing popularity of surfing can support coastal economies while increasing pressure on fragile marine environments.', NULL, 'Trong câu vừa nghe, từ “surfing” mang nghĩa nào sau đây?', '["về phía, hướng về","dày; đậm (khoảng cách giữa hai bề mặt lớn)","môn lướt sóng","chuyến tham quan; cuộc đi vòng quanh"]'::jsonb, 2, '“surfing” (/ˈsɝːfɪŋ/): môn lướt sóng. Câu đầy đủ: The growing popularity of surfing can support coastal economies while increasing pressure on fragile marine environments.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
