INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_23_6', 'en-a2-23', NULL, 'comprehensive_test', 'listening', 'Our family watched the Olympics together after dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đã cùng nhau đi trượt tuyết trong kỳ nghỉ đông.","Chúng tôi ra công viên trượt ván sau bữa trưa.","Gia đình tôi cùng nhau xem Thế vận hội sau bữa tối.","Chúng tôi đã chơi cricket ở công viên sau bữa trưa."]'::jsonb, 2, 'Our family watched the Olympics together after dinner. → Gia đình tôi cùng nhau xem Thế vận hội sau bữa tối.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_23_7', 'en-a2-23', NULL, 'comprehensive_test', 'listening', 'climbing', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["quê hương, thị trấn hoặc thành phố nơi lớn lên hoặc xuất thân","công cộng; chung; công khai","môn leo núi; môn thể thao leo vách đá (hoặc tường nhân tạo)","ở phía trước; tiến về phía trước"]'::jsonb, 2, 'climbing (/ˈklaɪmɪŋ/) → môn leo núi; môn thể thao leo vách đá (hoặc tường nhân tạo); có tính chất leo; bám vào để leo lên (của thực vật)', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_23_8', 'en-a2-23', NULL, 'comprehensive_test', 'listening', 'We play badminton at the sports centre every Saturday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hôm qua tôi đã thử chơi môn leo núi trong nhà cùng chị gái.","Huấn luyện viên của tôi đã chỉ cho tôi cách nâng tạ một cách an toàn.","Chúng tôi chơi cầu lông tại trung tâm thể thao vào mỗi thứ Bảy.","Chạy dọc theo bờ biển luôn giúp tôi sảng khoái đầu óc."]'::jsonb, 2, 'We play badminton at the sports centre every Saturday. → Chúng tôi chơi cầu lông tại trung tâm thể thao vào mỗi thứ Bảy.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_23_9', 'en-a2-23', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “someone who teaches people or animals particular skills”?', '["runner","trainer","skateboard","skateboarding"]'::jsonb, 1, 'trainer (/ˈtreɪnər/) → huấn luyện viên; chuyên gia đào tạo', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_23_10', 'en-a2-23', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An international sporting competition with summer and winter editions.”?', '["Olympics","badminton","skiing","climbing"]'::jsonb, 0, 'Olympics (/əˈlɪmpɪks/) → thế vận hội Olympic', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_23_11', 'en-a2-23', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The sport of going up rocks, mountains, or artificial walls.”?', '["Olympics","climbing","fan","surfing"]'::jsonb, 1, 'climbing (/ˈklaɪmɪŋ/) → môn leo núi; môn thể thao leo vách đá (hoặc tường nhân tạo)', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_23_12', 'en-a2-23', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A sport involving hitting a shuttlecock over a net with rackets”?', '["ping-pong","running","badminton","cricket"]'::jsonb, 2, 'badminton (/ˈbædmɪntən/) → môn cầu lông', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
