INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_23_18', 'en-a2-23', NULL, 'comprehensive_test', 'reading', NULL, 'Tourists who ski in mountain resorts contribute to local employment but may also increase environmental pressure.', 'Dựa vào câu trên, từ “ski” có nghĩa phù hợp nhất là gì?', '["áo chui đầu (len); áo len (tiếng Anh - Anh)","bí mật; giữ kín","chất khí; thể khí","trượt tuyết"]'::jsonb, 3, 'ski: trượt tuyết; vát trượt tuyết; ván trượt. Dịch cả câu: Du khách đi trượt tuyết tại các khu nghỉ dưỡng miền núi đóng góp vào việc làm cho người dân địa phương nhưng cũng có thể làm tăng áp lực môi trường.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_23_19', 'en-a2-23', NULL, 'comprehensive_test', 'reading', NULL, 'The growing popularity of surfing can support coastal economies while increasing pressure on fragile marine environments.', 'Dựa vào câu trên, từ “surfing” có nghĩa phù hợp nhất là gì?', '["bàn chải; cọ vẽ","hẹp; chật","giáo sư","môn lướt sóng"]'::jsonb, 3, 'surfing: môn lướt sóng; lướt web; duyệt trang web. Dịch cả câu: Sự phổ biến ngày càng tăng của môn lướt sóng có thể thúc đẩy kinh tế vùng ven biển đồng thời làm gia tăng áp lực lên hệ sinh thái biển mỏng manh.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_23_20', 'en-a2-23', NULL, 'comprehensive_test', 'reading', NULL, 'Building a new stadium may attract visitors, but its long-term maintenance costs require careful consideration.', 'Dựa vào câu trên, từ “stadium” có nghĩa phù hợp nhất là gì?', '["giày xăng-đan; giày sandal","công bằng; hợp lý","sân vận động","môn bóng đá"]'::jsonb, 2, 'stadium: sân vận động. Dịch cả câu: Việc xây dựng một sân vận động mới có thể thu hút khách du lịch, nhưng chi phí bảo trì lâu dài của nó đòi hỏi phải được cân nhắc kỹ lưỡng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_23_21', 'en-a2-23', NULL, 'comprehensive_test', 'reading', NULL, 'Sports fans can strengthen local communities by supporting neighbourhood teams and participating in shared events.', 'Dựa vào câu trên, từ “fan” có nghĩa phù hợp nhất là gì?', '["người hâm mộ; người cuồng nhiệt; tín đồ","bản sao chụp; bản photo","máy tính xách tay; máy tính xách tay cá nhân","hiện đại; đương đại"]'::jsonb, 0, 'fan: người hâm mộ; người cuồng nhiệt; tín đồ; quạt; quạt máy; quạt giấy; quạt gió; thổi gió; làm bùng lên. Dịch cả câu: Những người hâm mộ thể thao có thể gắn kết cộng đồng địa phương bằng cách ủng hộ các đội bóng khu vực và tham gia các sự kiện chung.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
