INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-24', 'en', 'Bài 24: Thể thao & Vận động (2) - CEFR A2', 'CEFR A2', 'A2 · Thể thao', '18 từ vựng Tiếng Anh CEFR A2 chủ đề thể thao & vận động kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2024, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_skate', 'en-a2-24', 'skate', '/skeɪt/', 'A2', 'trượt băng; trượt patin; giày trượt băng; giày trượt patin', 'v.', 'skater (n.), skating (n.)', NULL, 'Giày trượt thường dùng số nhiều skates; go skating diễn đạt hành động đi trượt băng/patin.', 'We skate around the rink every Saturday afternoon.', NULL, 'Chúng tôi trượt patin quanh sân băng vào mỗi chiều thứ Bảy.', '{"wordId":"skate","ukIpa":"/skeɪt/","usIpa":"/skeɪt/","cefr":"A2","topic":"sport","senses":[{"pos":"v.","en":"to move over ice or ground wearing special wheeled or bladed shoes","vi":"trượt băng; trượt patin"},{"pos":"n.","en":"a boot with a blade or wheels for moving smoothly","vi":"giày trượt băng; giày trượt patin"}],"examples":[{"en":"We skate around the rink every Saturday afternoon.","vi":"Chúng tôi trượt patin quanh sân băng vào mỗi chiều thứ Bảy.","audioKind":"ex"},{"en":"Public facilities where children can skate safely encourage physical activity and provide affordable recreation for families.","vi":"Các cơ sở công cộng nơi trẻ em có thể trượt băng an toàn sẽ khuyến khích vận động thể chất và mang lại hoạt động giải trí vừa túi tiền cho các gia đình.","audioKind":"ex2"}],"collocations":[{"en":"ice skate","vi":"trượt băng"},{"en":"roller skate","vi":"trượt patin"},{"en":"a pair of skates","vi":"một đôi giày trượt"}],"wordFamily":["skater (n.)","skating (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Giày trượt thường dùng số nhiều skates; go skating diễn đạt hành động đi trượt băng/patin.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_score', 'en-a2-24', 'score', '/skɔːr/', 'A2', 'điểm số; kết quả; ghi bàn; đạt điểm; nhạc phim; bản nhạc', 'n.', 'scorer (n.), scoring (n.), scoreless (adj.)', NULL, 'score có thể làm danh từ hoặc động từ; score a goal nghĩa là ghi bàn trong thể thao.', 'My score improved after a week of practice.', NULL, 'Điểm số của tôi đã cải thiện sau một tuần luyện tập.', '{"wordId":"score","ukIpa":"/skɔː/","usIpa":"/skɔːr/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"the points gained in a game, test, or competition","vi":"điểm số; kết quả"},{"pos":"v.","en":"to gain points in a game, test, or competition","vi":"ghi bàn; đạt điểm"},{"pos":"n.","en":"music written for a film or the written music itself","vi":"nhạc phim; bản nhạc"}],"examples":[{"en":"My score improved after a week of practice.","vi":"Điểm số của tôi đã cải thiện sau một tuần luyện tập.","audioKind":"ex"},{"en":"Test scores provide useful information, but they cannot fully reflect students'' creativity or practical skills.","vi":"Điểm thi cung cấp những thông tin hữu ích, nhưng chúng không thể phản ánh đầy đủ sự sáng tạo hoặc kỹ năng thực tế của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"a high score","vi":"điểm số cao"},{"en":"score a goal","vi":"ghi bàn thắng"},{"en":"test scores","vi":"điểm thi"},{"en":"a film score","vi":"nhạc phim"}],"wordFamily":["scorer (n.)","scoring (n.)","scoreless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"score có thể làm danh từ hoặc động từ; score a goal nghĩa là ghi bàn trong thể thao.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cycling', 'en-a2-24', 'cycling', '/ˈsaɪklɪŋ/', 'A2', 'việc đi xe đạp; môn đạp xe', 'n.', 'cycle (v.), cyclist (n.)', 'Đồng nghĩa: bicycling', 'Khi chỉ hoạt động này, danh từ thường không đếm được; thường dùng cụm go cycling.', 'We go cycling beside the river every Sunday morning.', NULL, 'Chúng tôi đi đạp xe dọc bờ sông vào mỗi sáng chủ nhật.', '{"wordId":"cycling","ukIpa":"/ˈsaɪklɪŋ/","usIpa":"/ˈsaɪklɪŋ/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"The activity of riding a bicycle for transport or exercise.","vi":"việc đi xe đạp; môn đạp xe"}],"examples":[{"en":"We go cycling beside the river every Sunday morning.","vi":"Chúng tôi đi đạp xe dọc bờ sông vào mỗi sáng chủ nhật.","audioKind":"ex"},{"en":"Investing in safe cycling routes can encourage commuters to choose healthier and less polluting forms of transport.","vi":"Đầu tư vào các tuyến đường dành cho xe đạp an toàn có thể khuyến khích người đi làm chọn phương tiện di chuyển lành mạnh hơn và ít gây ô nhiễm hơn.","audioKind":"ex2"}],"collocations":[{"en":"go cycling","vi":"đi đạp xe"},{"en":"cycling route","vi":"tuyến đường đạp xe"},{"en":"cycling helmet","vi":"mũ bảo hiểm đi xe đạp"},{"en":"cycling infrastructure","vi":"cơ sở hạ tầng cho xe đạp"}],"wordFamily":["cycle (v.)","cyclist (n.)"],"synonyms":["bicycling"],"antonyms":[],"tipVi":"Khi chỉ hoạt động này, danh từ thường không đếm được; thường dùng cụm go cycling.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_winner', 'en-a2-24', 'winner', '/ˈwɪnər/', 'A2', 'người chiến thắng; đội chiến thắng; người thành công; bên được lợi', 'n.', 'win (v.), winning (adj.)', 'Đồng nghĩa: victor · Trái nghĩa: loser', 'winner chỉ người chiến thắng; winning có thể dùng làm tính từ bổ nghĩa cho đội.', 'The winner lifted her trophy as the crowd cheered.', NULL, 'Người chiến thắng giơ cao chiếc cúp trong khi đám đông hò reo.', '{"wordId":"winner","ukIpa":"/ˈwɪnə/","usIpa":"/ˈwɪnər/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"a person or team that wins a competition","vi":"người chiến thắng; đội chiến thắng"},{"pos":"n.","en":"someone or something successful or benefiting from a situation","vi":"người thành công; bên được lợi"}],"examples":[{"en":"The winner lifted her trophy as the crowd cheered.","vi":"Người chiến thắng giơ cao chiếc cúp trong khi đám đông hò reo.","audioKind":"ex"},{"en":"Consumers may be the main winners when greater competition encourages companies to lower prices and improve services.","vi":"Người tiêu dùng có thể là những người hưởng lợi chính khi sự cạnh tranh lớn hơn thúc đẩy các doanh nghiệp hạ giá và cải thiện dịch vụ.","audioKind":"ex2"}],"collocations":[{"en":"a prize winner","vi":"người nhận giải"},{"en":"the overall winner","vi":"nhà vô địch toàn đoàn"},{"en":"a clear winner","vi":"người chiến thắng rõ ràng"}],"wordFamily":["win (v.)","winning (adj.)"],"synonyms":["victor"],"antonyms":["loser"],"tipVi":"winner chỉ người chiến thắng; winning có thể dùng làm tính từ bổ nghĩa cho đội.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chess', 'en-a2-24', 'chess', '/tʃes/', 'A2', 'cờ vua; môn cờ vua', 'n.', NULL, NULL, 'Dùng play chess, không thêm mạo từ the.', 'My grandfather taught me chess during the winter holidays.', NULL, 'Ông tôi đã dạy tôi chơi cờ vua trong kỳ nghỉ đông.', '{"wordId":"chess","ukIpa":"/tʃes/","usIpa":"/tʃes/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"a two-player board game involving pieces with different permitted moves","vi":"cờ vua; môn cờ vua"}],"examples":[{"en":"My grandfather taught me chess during the winter holidays.","vi":"Ông tôi đã dạy tôi chơi cờ vua trong kỳ nghỉ đông.","audioKind":"ex"},{"en":"Playing chess regularly may help children develop concentration and practise planning several steps ahead.","vi":"Chơi cờ vua thường xuyên có thể giúp trẻ phát triển khả năng tập trung và rèn luyện kỹ năng tính toán trước nhiều nước đi.","audioKind":"ex2"}],"collocations":[{"en":"play chess","vi":"chơi cờ vua"},{"en":"chess board","vi":"bàn cờ vua"},{"en":"chess tournament","vi":"giải đấu cờ vua"},{"en":"chess piece","vi":"quân cờ vua"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dùng play chess, không thêm mạo từ the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_judo', 'en-a2-24', 'judo', '/ˈdʒuːdoʊ/', 'A2', 'môn judo; võ judo', 'n.', 'judoka (n.)', NULL, 'Tập judo dùng do judo, không dùng play judo.', 'Our judo teacher showed us how to fall safely.', NULL, 'Giáo viên võ judo của chúng tôi đã chỉ cho chúng tôi cách ngã an toàn.', '{"wordId":"judo","ukIpa":"/ˈdʒuːdəʊ/","usIpa":"/ˈdʒuːdoʊ/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"A sport using throws and holds to overcome an opponent.","vi":"môn judo; võ judo"}],"examples":[{"en":"Our judo teacher showed us how to fall safely.","vi":"Giáo viên võ judo của chúng tôi đã chỉ cho chúng tôi cách ngã an toàn.","audioKind":"ex"},{"en":"Practising judo under qualified supervision can help young people develop balance, self-discipline, and respect for others.","vi":"Tập luyện võ judo dưới sự hướng dẫn có chuyên môn có thể giúp giới trẻ phát triển khả năng giữ thăng bằng, tính kỷ luật tự giác và sự tôn trọng đối với người khác.","audioKind":"ex2"}],"collocations":[{"en":"do judo","vi":"tập judo"},{"en":"judo instructor","vi":"huấn luyện viên judo"},{"en":"judo club","vi":"câu lạc bộ judo"},{"en":"judo match","vi":"trận đấu judo"}],"wordFamily":["judoka (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tập judo dùng do judo, không dùng play judo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_volleyball', 'en-a2-24', 'volleyball', '/ˈvɑːlibɔːl/', 'A2', 'môn bóng chuyền; quả bóng chuyền', 'n.', NULL, NULL, 'Khi chỉ môn thể thao thì đây là danh từ không đếm được, trong cụm play volleyball không dùng mạo từ.', 'We played volleyball on the beach until the sun set.', NULL, 'Chúng tôi chơi bóng chuyền trên bãi biển cho đến khi mặt trời lặn.', '{"wordId":"volleyball","ukIpa":"/ˈvɒlibɔːl/","usIpa":"/ˈvɑːlibɔːl/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"A game of hitting a ball over a high net.","vi":"môn bóng chuyền; quả bóng chuyền"}],"examples":[{"en":"We played volleyball on the beach until the sun set.","vi":"Chúng tôi chơi bóng chuyền trên bãi biển cho đến khi mặt trời lặn.","audioKind":"ex"},{"en":"Team sports such as volleyball can help students develop communication skills while encouraging regular physical activity.","vi":"Các môn thể thao tập thể như bóng chuyền có thể giúp học sinh phát triển kỹ năng giao tiếp đồng thời khích lệ việc rèn luyện thể chất thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"play volleyball","vi":"chơi bóng chuyền"},{"en":"beach volleyball","vi":"bóng chuyền bãi biển"},{"en":"volleyball court","vi":"sân bóng chuyền"},{"en":"volleyball team","vi":"đội bóng chuyền"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ môn thể thao thì đây là danh từ không đếm được, trong cụm play volleyball không dùng mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_baseball', 'en-a2-24', 'baseball', '/ˈbeɪsbɔːl/', 'A2', 'môn bóng chày; quả bóng chày', 'n.', NULL, NULL, 'Tên môn thể thao không đếm được; dùng a baseball khi chỉ một quả bóng chày cụ thể.', 'We played baseball in the park after lunch.', NULL, 'Chúng tôi chơi bóng chày ở công viên sau bữa trưa.', '{"wordId":"baseball","ukIpa":"/ˈbeɪsbɔːl/","usIpa":"/ˈbeɪsbɔːl/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"A team sport involving hitting a ball and running between bases","vi":"môn bóng chày"},{"pos":"n.","en":"The small, hard ball used in this sport","vi":"quả bóng chày"}],"examples":[{"en":"We played baseball in the park after lunch.","vi":"Chúng tôi chơi bóng chày ở công viên sau bữa trưa.","audioKind":"ex"},{"en":"Team sports such as baseball can help young people develop cooperation skills and maintain physical fitness.","vi":"Các môn thể thao đồng đội như bóng chày có thể giúp người trẻ phát triển kỹ năng hợp tác và duy trì thể lực.","audioKind":"ex2"}],"collocations":[{"en":"play baseball","vi":"chơi bóng chày"},{"en":"baseball bat","vi":"gậy bóng chày"},{"en":"baseball glove","vi":"găng tay bóng chày"},{"en":"baseball field","vi":"sân bóng chày"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tên môn thể thao không đếm được; dùng a baseball khi chỉ một quả bóng chày cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sailing', 'en-a2-24', 'sailing', '/ˈseɪlɪŋ/', 'A2', 'môn thể thao lướt buồm; hoạt động đi thuyền buồm; chuyến tàu chạy theo lịch trình', 'n.', 'sail (v.), sail (n.), sailor (n.)', NULL, 'Nghĩa thể thao là danh từ không đếm được; nghĩa chuyến tàu/chuyến phà là danh từ đếm được, ví dụ daily sailings.', 'We went sailing on the lake last weekend.', NULL, 'Cuối tuần qua chúng tôi đã đi chèo thuyền trên hồ.', '{"wordId":"sailing","ukIpa":"/ˈseɪlɪŋ/","usIpa":"/ˈseɪlɪŋ/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"The activity of travelling in a boat powered by wind.","vi":"môn thể thao lướt buồm; hoạt động đi thuyền buồm"},{"pos":"n.","en":"A scheduled journey or departure by a ship or ferry.","vi":"chuyến tàu chạy theo lịch trình"}],"examples":[{"en":"We went sailing on the lake last weekend.","vi":"Cuối tuần qua chúng tôi đã đi chèo thuyền trên hồ.","audioKind":"ex"},{"en":"Sailing clubs can encourage outdoor exercise while teaching young people teamwork and respect for marine environments.","vi":"Các câu lạc bộ chèo thuyền buồm có thể khuyến khích việc tập thể dục ngoài trời đồng thời dạy cho giới trẻ tinh thần đồng đội và ý thức tôn trọng môi trường biển.","audioKind":"ex2"}],"collocations":[{"en":"go sailing","vi":"đi chèo thuyền buồm"},{"en":"a sailing club","vi":"câu lạc bộ chèo thuyền"},{"en":"a sailing boat","vi":"thuyền buồm"},{"en":"regular sailings","vi":"các chuyến tàu định kỳ"}],"wordFamily":["sail (v.)","sail (n.)","sailor (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nghĩa thể thao là danh từ không đếm được; nghĩa chuyến tàu/chuyến phà là danh từ đếm được, ví dụ daily sailings.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_windsurfing', 'en-a2-24', 'windsurfing', '/ˈwɪndsɝːfɪŋ/', 'A2', 'môn lướt ván buồm', 'n.', 'windsurf (v.), windsurfer (n.)', NULL, 'windsurfing mượn sức gió để di chuyển; surfing chủ yếu lướt trên sóng biển.', 'My sister tried windsurfing during our holiday by the lake.', NULL, 'Chị tôi đã thử môn lướt ván buồm trong kỳ nghỉ của chúng tôi ở bên hồ.', '{"wordId":"windsurfing","ukIpa":"/ˈwɪndsɜːfɪŋ/","usIpa":"/ˈwɪndsɝːfɪŋ/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"A water sport using a board with an attached sail.","vi":"môn lướt ván buồm"}],"examples":[{"en":"My sister tried windsurfing during our holiday by the lake.","vi":"Chị tôi đã thử môn lướt ván buồm trong kỳ nghỉ của chúng tôi ở bên hồ.","audioKind":"ex"},{"en":"Windsurfing schools can attract visitors to coastal towns, provided that local authorities establish clear water safety guidelines.","vi":"Các trường dạy lướt ván buồm có thể thu hút du khách đến các thị trấn ven biển, miễn là cơ quan chức năng địa phương thiết lập các hướng dẫn an toàn dưới nước rõ ràng.","audioKind":"ex2"}],"collocations":[{"en":"go windsurfing","vi":"đi lướt ván buồm"},{"en":"windsurfing equipment","vi":"trang thiết bị lướt ván buồm"},{"en":"windsurfing lessons","vi":"các bài học lướt ván buồm"}],"wordFamily":["windsurf (v.)","windsurfer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"windsurfing mượn sức gió để di chuyển; surfing chủ yếu lướt trên sóng biển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jog', 'en-a2-24', 'jog', '/dʒɑːɡ/', 'A2', 'chạy bộ chậm và đều đặn, thường là để rèn luyện sức khỏe; buổi chạy bộ chậm và đều; khều nhẹ; va chạm nhẹ vào cái gì đó, thường là vô tình', 'v.', 'jogger (n.), jogging (n.)', NULL, 'Cụm từ jog someone''s memory có nghĩa là gợi nhắc lại ký ức của ai đó.', 'We jog around the park before breakfast every morning.', NULL, 'Chúng tôi chạy bộ quanh công viên trước bữa sáng mỗi buổi sáng.', '{"wordId":"jog","ukIpa":"/dʒɒɡ/","usIpa":"/dʒɑːɡ/","cefr":"A2","topic":"sport","senses":[{"pos":"v.","en":"To run slowly and steadily, usually for exercise.","vi":"chạy bộ chậm và đều đặn, thường là để rèn luyện sức khỏe"},{"pos":"n.","en":"A period of slow, steady running.","vi":"buổi chạy bộ chậm và đều"},{"pos":"v.","en":"To knock or push something slightly, often accidentally.","vi":"khều nhẹ; va chạm nhẹ vào cái gì đó, thường là vô tình"}],"examples":[{"en":"We jog around the park before breakfast every morning.","vi":"Chúng tôi chạy bộ quanh công viên trước bữa sáng mỗi buổi sáng.","audioKind":"ex"},{"en":"People who jog regularly may improve their cardiovascular health without needing expensive equipment or gym memberships.","vi":"Những người thường xuyên chạy bộ có thể cải thiện sức khỏe tim mạch mà không cần đến dụng cụ đắt tiền hay thẻ thành viên phòng gym.","audioKind":"ex2"}],"collocations":[{"en":"go for a jog","vi":"đi chạy bộ"},{"en":"jog along","vi":"chạy bộ thong thả"},{"en":"jog someone''s memory","vi":"gợi nhắc lại ký ức của ai đó"}],"wordFamily":["jogger (n.)","jogging (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ jog someone''s memory có nghĩa là gợi nhắc lại ký ức của ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bowling', 'en-a2-24', 'bowling', '/ˈboʊlɪŋ/', 'A2', 'môn thể thao bowling; thao tác ném bóng (trong môn cricket)', 'n.', 'bowl (v.), bowler (n.)', NULL, 'Môn bowling dùng cấu trúc go bowling; từ này cũng có thể chỉ thao tác ném bóng trong môn cricket.', 'My cousins and I went bowling on Saturday.', NULL, 'Hôm thứ Bảy, tôi và các anh chị em họ đã đi chơi bowling.', '{"wordId":"bowling","ukIpa":"/ˈbəʊlɪŋ/","usIpa":"/ˈboʊlɪŋ/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"a game of rolling a heavy ball to knock down pins","vi":"môn thể thao bowling"},{"pos":"n.","en":"the action of delivering the ball towards a cricket batter","vi":"thao tác ném bóng (trong môn cricket)"}],"examples":[{"en":"My cousins and I went bowling on Saturday.","vi":"Hôm thứ Bảy, tôi và các anh chị em họ đã đi chơi bowling.","audioKind":"ex"},{"en":"Leisure centres offering activities such as bowling can encourage social interaction among people of different ages.","vi":"Các trung tâm giải trí cung cấp các hoạt động như bowling có thể thúc đẩy sự giao lưu xã hội giữa những người ở các độ tuổi khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"go bowling","vi":"đi chơi bowling"},{"en":"bowling alley","vi":"quán bowling; câu lạc bộ bowling"},{"en":"bowling ball","vi":"quả bóng bowling"},{"en":"fast bowling","vi":"cú ném bóng tốc độ"}],"wordFamily":["bowl (v.)","bowler (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Môn bowling dùng cấu trúc go bowling; từ này cũng có thể chỉ thao tác ném bóng trong môn cricket.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coach', 'en-a2-24', 'coach', '/koʊtʃ/', 'A2', 'huấn luyện viên; xe khách đường dài; huấn luyện; kèm cặp', 'n.', 'coaching (n.)', 'Đồng nghĩa: trainer', 'Trong tiếng Anh-Anh, coach còn chỉ xe khách đường dài, còn bus thường chỉ xe buýt thành phố.', 'Our coach showed us how to hold the racket.', NULL, 'Huấn luyện viên của chúng tôi đã chỉ cho chúng tôi cách cầm vợt.', '{"wordId":"coach","ukIpa":"/kəʊtʃ/","usIpa":"/koʊtʃ/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"someone who trains people to improve their sporting skills","vi":"huấn luyện viên"},{"pos":"n.","en":"a comfortable bus used for longer journeys","vi":"xe khách đường dài"},{"pos":"v.","en":"to train or teach someone to improve particular skills","vi":"huấn luyện; kèm cặp"}],"examples":[{"en":"Our coach showed us how to hold the racket.","vi":"Huấn luyện viên của chúng tôi đã chỉ cho chúng tôi cách cầm vợt.","audioKind":"ex"},{"en":"A skilled coach can help young athletes build confidence while developing healthy attitudes towards competition.","vi":"Một huấn luyện viên giỏi có thể giúp các vận động viên trẻ xây dựng sự tự tin đồng thời nuôi dưỡng thái độ lành mạnh đối với cạnh tranh.","audioKind":"ex2"}],"collocations":[{"en":"sports coach","vi":"huấn luyện viên thể thao"},{"en":"travel by coach","vi":"đi du lịch bằng xe khách"},{"en":"coach a team","vi":"hướng dẫn một đội"},{"en":"coach someone for an exam","vi":"kèm một người thi đấu"}],"wordFamily":["coaching (n.)"],"synonyms":["trainer"],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, coach còn chỉ xe khách đường dài, còn bus thường chỉ xe buýt thành phố.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_race', 'en-a2-24', 'race', '/reɪs/', 'A2', 'cuộc đua; cuộc thi chạy; chủng tộc; đua tốc độ; chạy đua; phóng nhanh', 'n.', 'racer (n.), racing (n.), racial (adj.), racially (adv.)', NULL, 'Race có thể chỉ cuộc thi tốc độ hoặc chủng tộc; không nên nhầm lẫn với dân tộc.', 'We watched the boat race from the bridge.', NULL, 'Chúng tôi đã xem cuộc đua thuyền từ trên cầu.', '{"wordId":"race","ukIpa":"/reɪs/","usIpa":"/reɪs/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"A competition to see who finishes a course fastest.","vi":"cuộc đua; cuộc thi chạy"},{"pos":"n.","en":"A social grouping based on perceived shared ancestry and physical characteristics.","vi":"chủng tộc"},{"pos":"v.","en":"To compete in speed or move very quickly.","vi":"đua tốc độ; chạy đua; phóng nhanh"}],"examples":[{"en":"We watched the boat race from the bridge.","vi":"Chúng tôi đã xem cuộc đua thuyền từ trên cầu.","audioKind":"ex"},{"en":"Schools should ensure that all children receive equal educational opportunities, regardless of their race or family income.","vi":"Các trường học nên đảm bảo rằng tất cả trẻ em đều nhận được cơ hội giáo dục công bằng, bất kể chủng tộc hay thu nhập gia đình.","audioKind":"ex2"}],"collocations":[{"en":"win a race","vi":"thắng một cuộc đua"},{"en":"a relay race","vi":"chạy đua tiếp sức"},{"en":"regardless of race","vi":"bất kể chủng tộc"},{"en":"race against time","vi":"chạy đua với thời gian"}],"wordFamily":["racer (n.)","racing (n.)","racial (adj.)","racially (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Race có thể chỉ cuộc thi tốc độ hoặc chủng tộc; không nên nhầm lẫn với dân tộc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_golf', 'en-a2-24', 'golf', '/ɡɑːlf/', 'A2', 'môn đánh gôn; môn thể thao đánh gôn', 'n.', 'golfer (n.), golfing (n.)', NULL, 'Các môn thể thao thường không đi kèm mạo từ: play golf.', 'My grandfather plays golf with his friends every Sunday.', NULL, 'Ông tôi chơi gôn cùng bạn bè vào mỗi Chủ Nhật.', '{"wordId":"golf","ukIpa":"/ɡɒlf/","usIpa":"/ɡɑːlf/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"A sport hitting a small ball into holes with clubs","vi":"môn đánh gôn; môn thể thao đánh gôn"}],"examples":[{"en":"My grandfather plays golf with his friends every Sunday.","vi":"Ông tôi chơi gôn cùng bạn bè vào mỗi Chủ Nhật.","audioKind":"ex"},{"en":"Golf courses can attract tourists, but maintaining their grass may require considerable amounts of water.","vi":"Các sân gôn có thể thu hút khách du lịch, nhưng việc duy trì thảm cỏ của chúng có thể đòi hỏi lượng nước đáng kể.","audioKind":"ex2"}],"collocations":[{"en":"play golf","vi":"chơi gôn"},{"en":"a golf course","vi":"sân gôn"},{"en":"a golf club","vi":"gậy đánh gôn; câu lạc bộ gôn"},{"en":"a round of golf","vi":"một vòng đánh gôn"}],"wordFamily":["golfer (n.)","golfing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Các môn thể thao thường không đi kèm mạo từ: play golf.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kick', 'en-a2-24', 'kick', '/kɪk/', 'A2', 'sút; đá bằng chân; cú đá; cú sút', 'v.', 'kicker (n.)', NULL, 'kick dùng chân đá; hit chỉ hành động đánh hoặc đấm nói chung, không giới hạn bộ phận cơ thể.', 'She kicked the ball gently towards her little brother.', NULL, 'Cô ấy nhẹ nhàng đá quả bóng về phía cậu em trai.', '{"wordId":"kick","ukIpa":"/kɪk/","usIpa":"/kɪk/","cefr":"A2","topic":"sport","senses":[{"pos":"v.","en":"to hit something with your foot","vi":"sút; đá bằng chân"},{"pos":"n.","en":"an act of hitting something with your foot","vi":"cú đá; cú sút"}],"examples":[{"en":"She kicked the ball gently towards her little brother.","vi":"Cô ấy nhẹ nhàng đá quả bóng về phía cậu em trai.","audioKind":"ex"},{"en":"Children learn to kick and throw balls through activities that improve coordination and encourage teamwork.","vi":"Trẻ em học cách đá và ném bóng thông qua các hoạt động giúp cải thiện khả năng phối hợp và thúc đẩy tinh thần đồng đội.","audioKind":"ex2"}],"collocations":[{"en":"kick a ball","vi":"sút bóng"},{"en":"kick a habit","vi":"từ bỏ thói quen"},{"en":"free kick","vi":"quả đá phạt trực tiếp"}],"wordFamily":["kicker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"kick dùng chân đá; hit chỉ hành động đánh hoặc đấm nói chung, không giới hạn bộ phận cơ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hockey', 'en-a2-24', 'hockey', '/ˈhɑːki/', 'A2', 'môn khúc côn cầu', 'n.', NULL, NULL, 'Ở Anh, từ này thường chỉ khúc côn cầu trên cỏ; ở Mỹ thường chỉ khúc côn cầu trên băng.', 'We practised hockey on the school field yesterday.', NULL, 'Hôm qua chúng tôi đã tập chơi khúc côn cầu trên sân vận động của trường.', '{"wordId":"hockey","ukIpa":"/ˈhɒki/","usIpa":"/ˈhɑːki/","cefr":"A2","topic":"sport","senses":[{"pos":"n.","en":"A team sport using sticks to hit a ball or puck","vi":"môn khúc côn cầu"}],"examples":[{"en":"We practised hockey on the school field yesterday.","vi":"Hôm qua chúng tôi đã tập chơi khúc côn cầu trên sân vận động của trường.","audioKind":"ex"},{"en":"Making hockey facilities more accessible could encourage greater participation in team sports among young people.","vi":"Việc cải thiện khả năng tiếp cận các cơ sở vật chất chơi khúc côn cầu có thể khuyến khích nhiều người trẻ tham gia các môn thể thao đồng đội hơn.","audioKind":"ex2"}],"collocations":[{"en":"field hockey","vi":"khúc côn cầu trên cỏ"},{"en":"ice hockey","vi":"khúc côn cầu trên băng"},{"en":"hockey stick","vi":"gậy khúc côn cầu"},{"en":"play hockey","vi":"chơi khúc côn cầu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Ở Anh, từ này thường chỉ khúc côn cầu trên cỏ; ở Mỹ thường chỉ khúc côn cầu trên băng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_throw', 'en-a2-24', 'throw', '/θroʊ/', 'A2', 'ném; quăng; tung; tổ chức tiệc; cú ném; khoảng cách ném', 'v.', 'thrower (n.)', 'Đồng nghĩa: toss, hurl · Trái nghĩa: catch', 'Động từ bất quy tắc: throw–threw–thrown; có thể dùng throw để chỉ việc tổ chức tiệc.', 'Throw me the ball before the dog grabs it.', NULL, 'Ném quả bóng cho tôi trước khi con chó chộp lấy nó.', '{"wordId":"throw","ukIpa":"/θrəʊ/","usIpa":"/θroʊ/","cefr":"A2","topic":"sport","senses":[{"pos":"v.","en":"To send something through the air using your hand","vi":"ném; quăng; tung"},{"pos":"v.","en":"To organise and host a party","vi":"tổ chức tiệc"},{"pos":"n.","en":"An act of throwing, or the distance something is thrown","vi":"cú ném; khoảng cách ném"}],"examples":[{"en":"Throw me the ball before the dog grabs it.","vi":"Ném quả bóng cho tôi trước khi con chó chộp lấy nó.","audioKind":"ex"},{"en":"Schools can teach children to throw and catch safely through games that develop coordination and teamwork.","vi":"Nhà trường có thể dạy học sinh cách ném và bắt bóng an toàn thông qua các trò chơi giúp phát triển sự phối hợp vận động và tinh thần đồng đội.","audioKind":"ex2"}],"collocations":[{"en":"throw a ball","vi":"ném bóng"},{"en":"throw a party","vi":"tổ chức tiệc"},{"en":"throw away rubbish","vi":"vứt rác"}],"wordFamily":["thrower (n.)"],"synonyms":["toss","hurl"],"antonyms":["catch"],"tipVi":"Động từ bất quy tắc: throw–threw–thrown; có thể dùng throw để chỉ việc tổ chức tiệc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_24_1', 'en-a2-24', 'Cách dùng “sailing” (n.) — môn thể thao lướt buồm; hoạt động đi thuyền buồm', 'go sailing  ·  a sailing club  ·  a sailing boat', 'Nghĩa thể thao là danh từ không đếm được; nghĩa chuyến tàu/chuyến phà là danh từ đếm được, ví dụ daily sailings.', 'Họ từ (Word Family): sail (v.), sail (n.), sailor (n.)', '[{"hanzi":"We went sailing on the lake last weekend.","pinyin":"","meaning":"Cuối tuần qua chúng tôi đã đi chèo thuyền trên hồ."},{"hanzi":"Sailing clubs can encourage outdoor exercise while teaching young people teamwork and respect for marine environments.","pinyin":"","meaning":"Các câu lạc bộ chèo thuyền buồm có thể khuyến khích việc tập thể dục ngoài trời đồng thời dạy cho giới trẻ tinh thần đồng đội và ý thức tôn trọng môi trường biển."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_24_2', 'en-a2-24', 'Cách dùng “volleyball” (n.) — môn bóng chuyền; quả bóng chuyền', 'play volleyball  ·  beach volleyball  ·  volleyball court', 'Khi chỉ môn thể thao thì đây là danh từ không đếm được, trong cụm play volleyball không dùng mạo từ.', NULL, '[{"hanzi":"We played volleyball on the beach until the sun set.","pinyin":"","meaning":"Chúng tôi chơi bóng chuyền trên bãi biển cho đến khi mặt trời lặn."},{"hanzi":"Team sports such as volleyball can help students develop communication skills while encouraging regular physical activity.","pinyin":"","meaning":"Các môn thể thao tập thể như bóng chuyền có thể giúp học sinh phát triển kỹ năng giao tiếp đồng thời khích lệ việc rèn luyện thể chất thường xuyên."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_24_3', 'en-a2-24', 'Cách dùng “bowling” (n.) — môn thể thao bowling', 'go bowling  ·  bowling alley  ·  bowling ball', 'Môn bowling dùng cấu trúc go bowling; từ này cũng có thể chỉ thao tác ném bóng trong môn cricket.', 'Họ từ (Word Family): bowl (v.), bowler (n.)', '[{"hanzi":"My cousins and I went bowling on Saturday.","pinyin":"","meaning":"Hôm thứ Bảy, tôi và các anh chị em họ đã đi chơi bowling."},{"hanzi":"Leisure centres offering activities such as bowling can encourage social interaction among people of different ages.","pinyin":"","meaning":"Các trung tâm giải trí cung cấp các hoạt động như bowling có thể thúc đẩy sự giao lưu xã hội giữa những người ở các độ tuổi khác nhau."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_24_4', 'en-a2-24', 'Cách dùng “coach” (n.) — huấn luyện viên', 'sports coach  ·  travel by coach  ·  coach a team', 'Trong tiếng Anh-Anh, coach còn chỉ xe khách đường dài, còn bus thường chỉ xe buýt thành phố.', 'Họ từ (Word Family): coaching (n.) | Đồng nghĩa: trainer', '[{"hanzi":"Our coach showed us how to hold the racket.","pinyin":"","meaning":"Huấn luyện viên của chúng tôi đã chỉ cho chúng tôi cách cầm vợt."},{"hanzi":"A skilled coach can help young athletes build confidence while developing healthy attitudes towards competition.","pinyin":"","meaning":"Một huấn luyện viên giỏi có thể giúp các vận động viên trẻ xây dựng sự tự tin đồng thời nuôi dưỡng thái độ lành mạnh đối với cạnh tranh."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_24_1', 'en-a2-24', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_24_1_1', 'ten_a2_24_1', 'skate', 'We skate around the rink every Saturday afternoon.', 'We skate around the rink every Saturday afternoon.', '/skeɪt/', 'Chúng tôi trượt patin quanh sân băng vào mỗi chiều thứ Bảy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_24_1_2', 'ten_a2_24_1', 'score', 'My score improved after a week of practice.', 'My score improved after a week of practice.', '/skɔːr/', 'Điểm số của tôi đã cải thiện sau một tuần luyện tập.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_24_1_3', 'ten_a2_24_1', 'cycling', 'We go cycling beside the river every Sunday morning.', 'We go cycling beside the river every Sunday morning.', '/ˈsaɪklɪŋ/', 'Chúng tôi đi đạp xe dọc bờ sông vào mỗi sáng chủ nhật.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_24_1_4', 'ten_a2_24_1', 'winner', 'The winner lifted her trophy as the crowd cheered.', 'The winner lifted her trophy as the crowd cheered.', '/ˈwɪnər/', 'Người chiến thắng giơ cao chiếc cúp trong khi đám đông hò reo.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_24_1_5', 'ten_a2_24_1', 'chess', 'My grandfather taught me chess during the winter holidays.', 'My grandfather taught me chess during the winter holidays.', '/tʃes/', 'Ông tôi đã dạy tôi chơi cờ vua trong kỳ nghỉ đông.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_24_1_6', 'ten_a2_24_1', 'judo', 'Our judo teacher showed us how to fall safely.', 'Our judo teacher showed us how to fall safely.', '/ˈdʒuːdoʊ/', 'Giáo viên võ judo của chúng tôi đã chỉ cho chúng tôi cách ngã an toàn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_24_1_7', 'ten_a2_24_1', 'volleyball', 'We played volleyball on the beach until the sun set.', 'We played volleyball on the beach until the sun set.', '/ˈvɑːlibɔːl/', 'Chúng tôi chơi bóng chuyền trên bãi biển cho đến khi mặt trời lặn.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_24_1_8', 'ten_a2_24_1', 'baseball', 'We played baseball in the park after lunch.', 'We played baseball in the park after lunch.', '/ˈbeɪsbɔːl/', 'Chúng tôi chơi bóng chày ở công viên sau bữa trưa.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_24_1_1', 'en-a2-24', 'ten_a2_24_1', 'listening', 'listening', 'We skate around the rink every Saturday afternoon.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cuối tuần qua chúng tôi đã đi chèo thuyền trên hồ.","Chúng tôi trượt patin quanh sân băng vào mỗi chiều thứ Bảy.","Người chiến thắng giơ cao chiếc cúp trong khi đám đông hò reo.","Chúng tôi chạy bộ quanh công viên trước bữa sáng mỗi buổi sáng."]'::jsonb, 1, 'We skate around the rink every Saturday afternoon. → Chúng tôi trượt patin quanh sân băng vào mỗi chiều thứ Bảy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_24_1_2', 'en-a2-24', 'ten_a2_24_1', 'listening', 'listening', 'My score improved after a week of practice.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Điểm số của tôi đã cải thiện sau một tuần luyện tập.","Chúng tôi đã xem cuộc đua thuyền từ trên cầu.","Người chiến thắng giơ cao chiếc cúp trong khi đám đông hò reo.","Huấn luyện viên của chúng tôi đã chỉ cho chúng tôi cách cầm vợt."]'::jsonb, 0, 'My score improved after a week of practice. → Điểm số của tôi đã cải thiện sau một tuần luyện tập.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_24_1_3', 'en-a2-24', 'ten_a2_24_1', 'listening', 'listening', 'We go cycling beside the river every Sunday morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Huấn luyện viên của chúng tôi đã chỉ cho chúng tôi cách cầm vợt.","Chúng tôi trượt patin quanh sân băng vào mỗi chiều thứ Bảy.","Chúng tôi đã xem cuộc đua thuyền từ trên cầu.","Chúng tôi đi đạp xe dọc bờ sông vào mỗi sáng chủ nhật."]'::jsonb, 3, 'We go cycling beside the river every Sunday morning. → Chúng tôi đi đạp xe dọc bờ sông vào mỗi sáng chủ nhật.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_24_2', 'en-a2-24', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_24_2_1', 'ten_a2_24_2', 'skate', 'Public facilities where children can skate safely encourage physical activity and provide affordable recreation for families.', 'Public facilities where children can skate safely encourage physical activity and provide affordable recreation for families.', '/skeɪt/', 'Các cơ sở công cộng nơi trẻ em có thể trượt băng an toàn sẽ khuyến khích vận động thể chất và mang lại hoạt động giải trí vừa túi tiền cho các gia đình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_24_2_2', 'ten_a2_24_2', 'score', 'Test scores provide useful information, but they cannot fully reflect students'' creativity or practical skills.', 'Test scores provide useful information, but they cannot fully reflect students'' creativity or practical skills.', '/skɔːr/', 'Điểm thi cung cấp những thông tin hữu ích, nhưng chúng không thể phản ánh đầy đủ sự sáng tạo hoặc kỹ năng thực tế của học sinh.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_24_2_3', 'ten_a2_24_2', 'cycling', 'Investing in safe cycling routes can encourage commuters to choose healthier and less polluting forms of transport.', 'Investing in safe cycling routes can encourage commuters to choose healthier and less polluting forms of transport.', '/ˈsaɪklɪŋ/', 'Đầu tư vào các tuyến đường dành cho xe đạp an toàn có thể khuyến khích người đi làm chọn phương tiện di chuyển lành mạnh hơn và ít gây ô nhiễm hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_24_2_4', 'ten_a2_24_2', 'winner', 'Consumers may be the main winners when greater competition encourages companies to lower prices and improve services.', 'Consumers may be the main winners when greater competition encourages companies to lower prices and improve services.', '/ˈwɪnər/', 'Người tiêu dùng có thể là những người hưởng lợi chính khi sự cạnh tranh lớn hơn thúc đẩy các doanh nghiệp hạ giá và cải thiện dịch vụ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_24_2_5', 'ten_a2_24_2', 'chess', 'Playing chess regularly may help children develop concentration and practise planning several steps ahead.', 'Playing chess regularly may help children develop concentration and practise planning several steps ahead.', '/tʃes/', 'Chơi cờ vua thường xuyên có thể giúp trẻ phát triển khả năng tập trung và rèn luyện kỹ năng tính toán trước nhiều nước đi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_24_2_6', 'ten_a2_24_2', 'judo', 'Practising judo under qualified supervision can help young people develop balance, self-discipline, and respect for others.', 'Practising judo under qualified supervision can help young people develop balance, self-discipline, and respect for others.', '/ˈdʒuːdoʊ/', 'Tập luyện võ judo dưới sự hướng dẫn có chuyên môn có thể giúp giới trẻ phát triển khả năng giữ thăng bằng, tính kỷ luật tự giác và sự tôn trọng đối với người khác.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_24_2_1', 'en-a2-24', 'ten_a2_24_2', 'listening', 'listening', 'Public facilities where children can skate safely encourage physical activity and provide affordable recreation for families.', NULL, 'Trong câu vừa nghe, từ “skate” mang nghĩa nào sau đây?', '["sau đó; về sau","dù sao đi nữa; bất chấp thế nào","mãi mãi; đời đời; vĩnh viễn","trượt băng; trượt patin"]'::jsonb, 3, '“skate” (/skeɪt/): trượt băng; trượt patin. Câu đầy đủ: Public facilities where children can skate safely encourage physical activity and provide affordable recreation for families.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_24_2_2', 'en-a2-24', 'ten_a2_24_2', 'listening', 'listening', 'Test scores provide useful information, but they cannot fully reflect students'' creativity or practical skills.', NULL, 'Trong câu vừa nghe, từ “score” mang nghĩa nào sau đây?', '["điểm số; kết quả","cát","một triệu","đẹp đẽ; dễ thương; xinh xắn"]'::jsonb, 0, '“score” (/skɔːr/): điểm số; kết quả. Câu đầy đủ: Test scores provide useful information, but they cannot fully reflect students'' creativity or practical skills.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
