INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_24_1', 'en-a2-24', NULL, 'comprehensive_test', 'listening', 'skate', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["móng tay; móng chân","trượt băng; trượt patin","một chút; một lượng nhỏ; một miếng nhỏ","sự chăm sóc; sự chiếu cố"]'::jsonb, 1, 'skate (/skeɪt/) → trượt băng; trượt patin; giày trượt băng; giày trượt patin', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_24_2', 'en-a2-24', NULL, 'comprehensive_test', 'listening', 'My score improved after a week of practice.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hôm thứ Bảy, tôi và các anh chị em họ đã đi chơi bowling.","Chúng tôi trượt patin quanh sân băng vào mỗi chiều thứ Bảy.","Ông tôi đã dạy tôi chơi cờ vua trong kỳ nghỉ đông.","Điểm số của tôi đã cải thiện sau một tuần luyện tập."]'::jsonb, 3, 'My score improved after a week of practice. → Điểm số của tôi đã cải thiện sau một tuần luyện tập.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_24_3', 'en-a2-24', NULL, 'comprehensive_test', 'listening', 'cycling', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đường cao tốc","căn bệnh; tình trạng ốm đau","cái kéo; cây kéo","việc đi xe đạp; môn đạp xe"]'::jsonb, 3, 'cycling (/ˈsaɪklɪŋ/) → việc đi xe đạp; môn đạp xe', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_24_4', 'en-a2-24', NULL, 'comprehensive_test', 'listening', 'The winner lifted her trophy as the crowd cheered.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Người chiến thắng giơ cao chiếc cúp trong khi đám đông hò reo.","Cuối tuần qua chúng tôi đã đi chèo thuyền trên hồ.","Hôm qua chúng tôi đã tập chơi khúc côn cầu trên sân vận động của trường.","Cô ấy nhẹ nhàng đá quả bóng về phía cậu em trai."]'::jsonb, 0, 'The winner lifted her trophy as the crowd cheered. → Người chiến thắng giơ cao chiếc cúp trong khi đám đông hò reo.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_24_5', 'en-a2-24', NULL, 'comprehensive_test', 'listening', 'chess', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cờ vua; môn cờ vua","hủy bỏ; bãi bỏ; hoãn","con ong","thuộc về kỹ thuật số; số hóa"]'::jsonb, 0, 'chess (/tʃes/) → cờ vua; môn cờ vua', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_24_6', 'en-a2-24', NULL, 'comprehensive_test', 'listening', 'Our judo teacher showed us how to fall safely.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy nhẹ nhàng đá quả bóng về phía cậu em trai.","Ném quả bóng cho tôi trước khi con chó chộp lấy nó.","Giáo viên võ judo của chúng tôi đã chỉ cho chúng tôi cách ngã an toàn.","Ông tôi chơi gôn cùng bạn bè vào mỗi Chủ Nhật."]'::jsonb, 2, 'Our judo teacher showed us how to fall safely. → Giáo viên võ judo của chúng tôi đã chỉ cho chúng tôi cách ngã an toàn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
