INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_24_8', 'en-a2-24', NULL, 'comprehensive_test', 'listening', 'We played baseball in the park after lunch.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi chơi bóng chày ở công viên sau bữa trưa.","Cuối tuần qua chúng tôi đã đi chèo thuyền trên hồ.","Người chiến thắng giơ cao chiếc cúp trong khi đám đông hò reo.","Ông tôi chơi gôn cùng bạn bè vào mỗi Chủ Nhật."]'::jsonb, 0, 'We played baseball in the park after lunch. → Chúng tôi chơi bóng chày ở công viên sau bữa trưa.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_24_9', 'en-a2-24', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “a two-player board game involving pieces with different permitted moves”?', '["kick","sailing","score","chess"]'::jsonb, 3, 'chess (/tʃes/) → cờ vua; môn cờ vua', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
