INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_24_18', 'en-a2-24', NULL, 'comprehensive_test', 'reading', NULL, 'Public facilities where children can skate safely encourage physical activity and provide affordable recreation for families.', 'Dựa vào câu trên, từ “skate” có nghĩa phù hợp nhất là gì?', '["nam nhân viên bưu điện (người làm nghề phát thư từ và bưu phẩm)","hạt tiêu; bột tiêu","trượt băng; trượt patin","xe máy; xe mô tô"]'::jsonb, 2, 'skate: trượt băng; trượt patin; giày trượt băng; giày trượt patin. Dịch cả câu: Các cơ sở công cộng nơi trẻ em có thể trượt băng an toàn sẽ khuyến khích vận động thể chất và mang lại hoạt động giải trí vừa túi tiền cho các gia đình.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_24_19', 'en-a2-24', NULL, 'comprehensive_test', 'reading', NULL, 'Test scores provide useful information, but they cannot fully reflect students'' creativity or practical skills.', 'Dựa vào câu trên, từ “score” có nghĩa phù hợp nhất là gì?', '["hoàn hảo; lý tưởng","điểm số; kết quả","mối quan hệ; mối quan hệ tình cảm","có sương mù, mờ mịt"]'::jsonb, 1, 'score: điểm số; kết quả; ghi bàn; đạt điểm; nhạc phim; bản nhạc. Dịch cả câu: Điểm thi cung cấp những thông tin hữu ích, nhưng chúng không thể phản ánh đầy đủ sự sáng tạo hoặc kỹ năng thực tế của học sinh.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_24_20', 'en-a2-24', NULL, 'comprehensive_test', 'reading', NULL, 'Investing in safe cycling routes can encourage commuters to choose healthier and less polluting forms of transport.', 'Dựa vào câu trên, từ “cycling” có nghĩa phù hợp nhất là gì?', '["thảo luận; bàn luận; bàn bạc","còn sống (thay vì đã chết)","cổ đại; thuộc thời cổ đại","việc đi xe đạp; môn đạp xe"]'::jsonb, 3, 'cycling: việc đi xe đạp; môn đạp xe. Dịch cả câu: Đầu tư vào các tuyến đường dành cho xe đạp an toàn có thể khuyến khích người đi làm chọn phương tiện di chuyển lành mạnh hơn và ít gây ô nhiễm hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_24_21', 'en-a2-24', NULL, 'comprehensive_test', 'reading', NULL, 'Consumers may be the main winners when greater competition encourages companies to lower prices and improve services.', 'Dựa vào câu trên, từ “winner” có nghĩa phù hợp nhất là gì?', '["sút; đá bằng chân","kiếm được; kiếm tiền","kiểu tóc; tạo hình tóc","người chiến thắng; đội chiến thắng"]'::jsonb, 3, 'winner: người chiến thắng; đội chiến thắng; người thành công; bên được lợi. Dịch cả câu: Người tiêu dùng có thể là những người hưởng lợi chính khi sự cạnh tranh lớn hơn thúc đẩy các doanh nghiệp hạ giá và cải thiện dịch vụ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_24_22', 'en-a2-24', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sút; đá bằng chân”', '["apartment","shut","kick","fight"]'::jsonb, 2, 'sút; đá bằng chân → kick (/kɪk/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_24_23', 'en-a2-24', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “môn khúc côn cầu”', '["pleased","FALSE","hockey","government"]'::jsonb, 2, 'môn khúc côn cầu → hockey (/ˈhɑːki/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_24_24', 'en-a2-24', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ném; quăng; tung”', '["throw","distance","serve","palace"]'::jsonb, 0, 'ném; quăng; tung → throw (/θroʊ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-25', 'en', 'Bài 25: Công nghệ & Kỹ thuật (1) - CEFR A2', 'CEFR A2', 'A2 · Công nghệ', '18 từ vựng Tiếng Anh CEFR A2 chủ đề công nghệ & kỹ thuật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2025, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_typing', 'en-a2-25', 'typing', '/ˈtaɪpɪŋ/', 'A2', 'việc đánh máy; thao tác gõ phím', 'n.', 'type (v.), typist (n.), typewriter (n.)', NULL, 'Khi là danh từ, từ này không đếm được; đây đồng thời là phân từ hiện tại của type.', 'My typing has become faster since I started practising.', NULL, 'Tốc độ đánh máy của tôi đã nhanh hơn kể từ khi tôi bắt đầu luyện tập.', '{"wordId":"typing","ukIpa":"/ˈtaɪpɪŋ/","usIpa":"/ˈtaɪpɪŋ/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"The activity of entering words using a keyboard.","vi":"việc đánh máy; thao tác gõ phím"}],"examples":[{"en":"My typing has become faster since I started practising.","vi":"Tốc độ đánh máy của tôi đã nhanh hơn kể từ khi tôi bắt đầu luyện tập.","audioKind":"ex"},{"en":"Although voice recognition is improving, accurate typing remains a valuable skill in many office jobs.","vi":"Mặc dù công nghệ nhận diện giọng nói đang cải thiện, kỹ năng đánh máy chính xác vẫn là một năng lực quý giá trong nhiều công việc văn phòng.","audioKind":"ex2"}],"collocations":[{"en":"typing speed","vi":"tốc độ đánh máy"},{"en":"touch typing","vi":"đánh máy bằng mười ngón"},{"en":"typing skills","vi":"kỹ năng đánh máy"},{"en":"typing error","vi":"lỗi đánh máy"}],"wordFamily":["type (v.)","typist (n.)","typewriter (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi là danh từ, từ này không đếm được; đây đồng thời là phân từ hiện tại của type.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recorder', 'en-a2-25', 'recorder', '/rɪˈkɔːrdər/', 'A2', 'máy ghi âm; thiết bị ghi hình; sáo dọc; người ghi chép', 'n.', 'record (v.), recording (n.)', NULL, 'play the recorder chỉ thổi sáo dọc, không phải là phát máy ghi âm.', 'I placed the recorder beside her before the interview.', NULL, 'Tôi đặt máy ghi âm bên cạnh cô ấy trước buổi phỏng vấn.', '{"wordId":"recorder","ukIpa":"/rɪˈkɔːdə/","usIpa":"/rɪˈkɔːrdər/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"a device that captures sound, images, or information","vi":"máy ghi âm; thiết bị ghi hình"},{"pos":"n.","en":"a wooden or plastic wind instrument with finger holes","vi":"sáo dọc"},{"pos":"n.","en":"a person who keeps an official record","vi":"người ghi chép"}],"examples":[{"en":"I placed the recorder beside her before the interview.","vi":"Tôi đặt máy ghi âm bên cạnh cô ấy trước buổi phỏng vấn.","audioKind":"ex"},{"en":"Using a digital recorder allows researchers to review interviews carefully and identify recurring themes.","vi":"Việc sử dụng máy ghi âm kỹ thuật số giúp các nhà nghiên cứu xem xét kỹ lưỡng các cuộc phỏng vấn và nhận diện các chủ đề lặp lại.","audioKind":"ex2"}],"collocations":[{"en":"digital recorder","vi":"máy ghi âm kỹ thuật số"},{"en":"voice recorder","vi":"thiết bị ghi âm giọng nói"},{"en":"play the recorder","vi":"thổi sáo dọc"}],"wordFamily":["record (v.)","recording (n.)"],"synonyms":[],"antonyms":[],"tipVi":"play the recorder chỉ thổi sáo dọc, không phải là phát máy ghi âm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_user', 'en-a2-25', 'user', '/ˈjuːzər/', 'A2', 'người dùng; người sử dụng', 'n.', 'use (v.), useful (adj.), usable (adj.), usage (n.)', NULL, 'use đóng vai trò động từ và chữ s trong user được phát âm là /z/.', 'Each user can choose a different colour for their profile.', NULL, 'Mỗi người dùng có thể chọn một màu sắc khác nhau cho hồ sơ cá nhân của họ.', '{"wordId":"user","ukIpa":"/ˈjuːzə/","usIpa":"/ˈjuːzər/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"A person who uses a product, service, or facility.","vi":"người dùng; người sử dụng"}],"examples":[{"en":"Each user can choose a different colour for their profile.","vi":"Mỗi người dùng có thể chọn một màu sắc khác nhau cho hồ sơ cá nhân của họ.","audioKind":"ex"},{"en":"Software developers should consider the needs of every user, including people with limited technical skills.","vi":"Các nhà phát triển phần mềm nên cân nhắc nhu cầu của mọi người dùng, kể cả những người có kỹ năng công nghệ hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"user account","vi":"tài khoản người dùng"},{"en":"user feedback","vi":"phản hồi từ người dùng"},{"en":"road user","vi":"người tham gia giao thông"},{"en":"regular user","vi":"người dùng thường xuyên"}],"wordFamily":["use (v.)","useful (adj.)","usable (adj.)","usage (n.)"],"synonyms":[],"antonyms":[],"tipVi":"use đóng vai trò động từ và chữ s trong user được phát âm là /z/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_digital', 'en-a2-25', 'digital', '/ˈdɪdʒɪtəl/', 'A2', 'thuộc về kỹ thuật số; số hóa', 'adj.', 'digit (n.), digitally (adv.), digitise (v.), digitisation (n.)', 'Trái nghĩa: analogue', 'Digital nhấn mạnh vào hệ thống kỹ thuật số; từ chỉ tính chất con số đơn thuần thường dùng numerical.', 'She keeps digital copies of all her family photos.', NULL, 'Cô ấy lưu giữ các bản sao kỹ thuật số của tất cả ảnh gia đình.', '{"wordId":"digital","ukIpa":"/ˈdɪdʒɪtəl/","usIpa":"/ˈdɪdʒɪtəl/","cefr":"A2","topic":"technology","senses":[{"pos":"adj.","en":"using electronic systems that store and process information as digits","vi":"thuộc về kỹ thuật số; số hóa"}],"examples":[{"en":"She keeps digital copies of all her family photos.","vi":"Cô ấy lưu giữ các bản sao kỹ thuật số của tất cả ảnh gia đình.","audioKind":"ex"},{"en":"Improving digital skills can help older adults access public services and maintain contact with distant relatives.","vi":"Nâng cao kỹ năng số có thể giúp người cao tuổi tiếp cận các dịch vụ công cộng và giữ liên lạc với họ hàng ở xa.","audioKind":"ex2"}],"collocations":[{"en":"digital technology","vi":"công nghệ số"},{"en":"digital skills","vi":"kỹ năng số"},{"en":"digital divide","vi":"khoảng cách số"},{"en":"digital camera","vi":"máy ảnh kỹ thuật số"}],"wordFamily":["digit (n.)","digitally (adv.)","digitise (v.)","digitisation (n.)"],"synonyms":[],"antonyms":["analogue"],"tipVi":"Digital nhấn mạnh vào hệ thống kỹ thuật số; từ chỉ tính chất con số đơn thuần thường dùng numerical.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tool', 'en-a2-25', 'tool', '/tuːl/', 'A2', 'công cụ; dụng cụ (dùng để xây dựng, sửa chữa); phương tiện; công cụ hỗ trợ để thực hiện công việc hoặc đạt mục đích', 'n.', 'toolbox (n.), toolkit (n.)', 'Đồng nghĩa: implement', 'tool là danh từ đếm được; equipment thường là danh từ không đếm được.', 'This small tool helps me tighten the loose screws.', NULL, 'Cây dụng cụ nhỏ này giúp tôi siết chặt những con ốc bị lỏng.', '{"wordId":"tool","ukIpa":"/tuːl/","usIpa":"/tuːl/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"An object used to build, repair, or make things.","vi":"công cụ; dụng cụ (dùng để xây dựng, sửa chữa)"},{"pos":"n.","en":"Something that helps you perform a task or achieve something.","vi":"phương tiện; công cụ hỗ trợ để thực hiện công việc hoặc đạt mục đích"}],"examples":[{"en":"This small tool helps me tighten the loose screws.","vi":"Cây dụng cụ nhỏ này giúp tôi siết chặt những con ốc bị lỏng.","audioKind":"ex"},{"en":"Digital maps are a valuable tool for urban planners seeking to design more accessible public transport networks.","vi":"Bản đồ kỹ thuật số là công cụ đắc lực cho các nhà quy hoạch đô thị khi muốn thiết kế các mạng lưới giao thông công cộng dễ tiếp cận hơn.","audioKind":"ex2"}],"collocations":[{"en":"hand tools","vi":"dụng cụ cầm tay"},{"en":"power tools","vi":"dụng cụ điện cầm tay"},{"en":"a useful tool","vi":"một công cụ hữu ích"},{"en":"a tool for learning","vi":"một công cụ học tập"}],"wordFamily":["toolbox (n.)","toolkit (n.)"],"synonyms":["implement"],"antonyms":[],"tipVi":"tool là danh từ đếm được; equipment thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_invent', 'en-a2-25', 'invent', '/ɪnˈvent/', 'A2', 'phát minh; sáng chế; bịa ra; thêu dệt', 'v.', 'invention (n.), inventor (n.), inventive (adj.)', NULL, 'Invent là sáng chế ra thứ chưa từng có; còn discover là tìm ra thứ đã tồn tại từ trước.', 'My sister invented a clever tool for picking apples.', NULL, 'Chị tôi đã phát minh ra một dụng cụ thông minh để hái táo.', '{"wordId":"invent","ukIpa":"/ɪnˈvent/","usIpa":"/ɪnˈvent/","cefr":"A2","topic":"technology","senses":[{"pos":"v.","en":"To design or make something that did not exist before.","vi":"phát minh; sáng chế"},{"pos":"v.","en":"To make up a story or excuse that is untrue.","vi":"bịa ra; thêu dệt"}],"examples":[{"en":"My sister invented a clever tool for picking apples.","vi":"Chị tôi đã phát minh ra một dụng cụ thông minh để hái táo.","audioKind":"ex"},{"en":"Engineers must invent affordable technologies that help rural communities gain access to clean drinking water.","vi":"Các kỹ sư phải phát minh ra những công nghệ có giá cả phải chăng giúp cộng đồng nông thôn tiếp cận nguồn nước uống sạch.","audioKind":"ex2"}],"collocations":[{"en":"invent a device","vi":"phát minh một thiết bị"},{"en":"invent an excuse","vi":"bịa ra cái cớ"},{"en":"invent a story","vi":"thêu dệt câu chuyện"}],"wordFamily":["invention (n.)","inventor (n.)","inventive (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Invent là sáng chế ra thứ chưa từng có; còn discover là tìm ra thứ đã tồn tại từ trước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_electric', 'en-a2-25', 'electric', '/ɪˈlektrɪk/', 'A2', 'thuộc về điện; chạy bằng điện; sôi nổi; cuồng nhiệt', 'adj.', 'electricity (n.), electrical (adj.), electrically (adv.), electrician (n.)', NULL, 'Thiết bị chạy bằng điện thường dùng electric; hệ thống điện nói chung dùng electrical.', 'Our electric kettle boils water in two minutes.', NULL, 'Ấm đun nước điện của chúng tôi đun sôi nước chỉ trong hai phút.', '{"wordId":"electric","ukIpa":"/ɪˈlektrɪk/","usIpa":"/ɪˈlektrɪk/","cefr":"A2","topic":"technology","senses":[{"pos":"adj.","en":"Using, producing, or relating to electricity.","vi":"thuộc về điện; chạy bằng điện"},{"pos":"adj.","en":"Full of excitement and energy.","vi":"sôi nổi; cuồng nhiệt"}],"examples":[{"en":"Our electric kettle boils water in two minutes.","vi":"Ấm đun nước điện của chúng tôi đun sôi nước chỉ trong hai phút.","audioKind":"ex"},{"en":"Electric buses can reduce urban air pollution, especially when their power comes from renewable sources.","vi":"Xe buýt điện có thể giúp giảm ô nhiễm không khí đô thị, đặc biệt là khi nguồn điện của chúng đến từ các nguồn năng lượng tái tạo.","audioKind":"ex2"}],"collocations":[{"en":"electric car","vi":"xe ô tô điện"},{"en":"electric current","vi":"dòng điện"},{"en":"electric shock","vi":"điện giật"},{"en":"electric atmosphere","vi":"không khí cuồng nhiệt"}],"wordFamily":["electricity (n.)","electrical (adj.)","electrically (adv.)","electrician (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thiết bị chạy bằng điện thường dùng electric; hệ thống điện nói chung dùng electrical.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_online', 'en-a2-25', 'online', '/ˌɑːnˈlaɪn/', 'A2', 'trực tuyến; ở trên mạng; kết nối mạng', 'adj.', NULL, 'Trái nghĩa: offline', 'Từ này vừa có thể đóng vai trò là tính từ (online courses) vừa là trạng từ (shop online).', 'I booked our train tickets online after dinner.', NULL, 'Tôi đã đặt vé tàu qua mạng sau bữa tối.', '{"wordId":"online","ukIpa":"/ˌɒnˈlaɪn/","usIpa":"/ˌɑːnˈlaɪn/","cefr":"A2","topic":"technology","senses":[{"pos":"adj.","en":"Available through the internet or connected to a computer network.","vi":"trực tuyến; ở trên mạng"},{"pos":"adv.","en":"Using the internet or while connected to a computer network.","vi":"trực tuyến; kết nối mạng"}],"examples":[{"en":"I booked our train tickets online after dinner.","vi":"Tôi đã đặt vé tàu qua mạng sau bữa tối.","audioKind":"ex"},{"en":"Online courses can widen access to education, especially for learners who live far from universities.","vi":"Các khóa học trực tuyến có thể mở rộng cơ hội tiếp cận giáo dục, đặc biệt là đối với những người học sống ở xa các trường đại học.","audioKind":"ex2"}],"collocations":[{"en":"online shopping","vi":"mua sắm trực tuyến"},{"en":"online learning","vi":"học tập trực tuyến"},{"en":"go online","vi":"lên mạng"},{"en":"available online","vi":"có sẵn trên mạng"}],"wordFamily":[],"synonyms":[],"antonyms":["offline"],"tipVi":"Từ này vừa có thể đóng vai trò là tính từ (online courses) vừa là trạng từ (shop online).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_technology', 'en-a2-25', 'technology', '/tekˈnɑːlədʒi/', 'A2', 'công nghệ; kỹ thuật', 'n.', 'technological (adj.), technologically (adv.), technologist (n.)', NULL, 'Khi chỉ chung chung về khoa học công nghệ thì không đếm được; dùng technologies khi chỉ nhiều loại công nghệ cụ thể.', 'New technology lets us control the lights from our phones.', NULL, 'Công nghệ mới cho phép chúng tôi điều khiển đèn từ điện thoại của mình.', '{"wordId":"technology","ukIpa":"/tekˈnɒlədʒi/","usIpa":"/tekˈnɑːlədʒi/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"Practical use of scientific knowledge, especially through tools and machines.","vi":"công nghệ; kỹ thuật"}],"examples":[{"en":"New technology lets us control the lights from our phones.","vi":"Công nghệ mới cho phép chúng tôi điều khiển đèn từ điện thoại của mình.","audioKind":"ex"},{"en":"Investment in clean technology can reduce industrial pollution while creating skilled jobs in emerging sectors.","vi":"Việc đầu tư vào công nghệ sạch có thể làm giảm ô nhiễm công nghiệp đồng thời tạo ra các việc làm đòi hỏi kỹ năng cao trong các lĩnh vực mới nổi.","audioKind":"ex2"}],"collocations":[{"en":"digital technology","vi":"công nghệ số"},{"en":"advanced technology","vi":"công nghệ tiên tiến"},{"en":"information technology","vi":"công nghệ thông tin"},{"en":"develop new technologies","vi":"phát triển các công nghệ mới"}],"wordFamily":["technological (adj.)","technologically (adv.)","technologist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ chung chung về khoa học công nghệ thì không đếm được; dùng technologies khi chỉ nhiều loại công nghệ cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_system', 'en-a2-25', 'system', '/ˈsɪstəm/', 'A2', 'hệ thống; chế độ; thể chế; phương pháp', 'n.', 'systematic (adj.), systematically (adv.), systemic (adj.)', NULL, 'Từ "systematic" có nghĩa là có hệ thống, còn "systemic" có nghĩa là toàn hệ thống.', 'The heating system stopped working during a cold night.', NULL, 'Hệ thống sưởi đã ngừng hoạt động trong một đêm lạnh giá.', '{"wordId":"system","ukIpa":"/ˈsɪstəm/","usIpa":"/ˈsɪstəm/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"A set of connected parts that work together.","vi":"hệ thống"},{"pos":"n.","en":"An organised structure through which services or institutions operate.","vi":"chế độ; thể chế"},{"pos":"n.","en":"An organised way of doing something.","vi":"hệ thống; phương pháp"}],"examples":[{"en":"The heating system stopped working during a cold night.","vi":"Hệ thống sưởi đã ngừng hoạt động trong một đêm lạnh giá.","audioKind":"ex"},{"en":"An effective education system should support students with different abilities and prepare them for future employment.","vi":"Một hệ thống giáo dục hiệu quả nên hỗ trợ học sinh có năng lực khác nhau và trang bị cho các em khả năng làm việc trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"heating system","vi":"hệ thống sưởi"},{"en":"education system","vi":"hệ thống giáo dục"},{"en":"public transport system","vi":"hệ thống giao thông công cộng"},{"en":"immune system","vi":"hệ thống miễn dịch"}],"wordFamily":["systematic (adj.)","systematically (adv.)","systemic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ \"systematic\" có nghĩa là có hệ thống, còn \"systemic\" có nghĩa là toàn hệ thống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_screen', 'en-a2-25', 'screen', '/skriːn/', 'A2', 'màn hình; màn chiếu; sàng lọc; kiểm tra; chiếu phim; phát sóng', 'n.', 'screening (n.), onscreen (adj.)', NULL, 'screen A for B có nghĩa là kiểm tra A xem có gặp vấn đề B hay không.', 'I wiped the fingerprints off my laptop screen.', NULL, 'Tôi đã lau sạch các vết dấu tay trên màn hình máy tính xách tay của mình.', '{"wordId":"screen","ukIpa":"/skriːn/","usIpa":"/skriːn/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"A surface on which electronic images or films appear.","vi":"màn hình; màn chiếu"},{"pos":"v.","en":"To check people or things for problems or suitability.","vi":"sàng lọc; kiểm tra"},{"pos":"v.","en":"To show a film or programme to an audience.","vi":"chiếu phim; phát sóng"}],"examples":[{"en":"I wiped the fingerprints off my laptop screen.","vi":"Tôi đã lau sạch các vết dấu tay trên màn hình máy tính xách tay của mình.","audioKind":"ex"},{"en":"Health services should screen vulnerable patients regularly to detect diseases before serious symptoms develop.","vi":"Các cơ quan y tế nên thường xuyên sàng lọc các bệnh nhân dễ mắc bệnh để phát hiện bệnh trước khi các triệu chứng nghiêm trọng xuất hiện.","audioKind":"ex2"}],"collocations":[{"en":"screen time","vi":"thời gian dùng màn hình"},{"en":"touch screen","vi":"màn hình cảm ứng"},{"en":"screen for disease","vi":"sàng lọc bệnh"},{"en":"screen a film","vi":"chiếu một bộ phim"}],"wordFamily":["screening (n.)","onscreen (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"screen A for B có nghĩa là kiểm tra A xem có gặp vấn đề B hay không.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_keyboard', 'en-a2-25', 'keyboard', '/ˈkiːbɔːrd/', 'A2', 'bàn phím (máy tính); bàn phím (nhạc cụ); đàn phím điện tử', 'n.', NULL, NULL, 'Máy tính bảng/bàn phím máy tính thường dùng a keyboard; chơi nhạc cụ phím dùng play the keyboard.', 'I brushed the crumbs off my keyboard before starting work.', NULL, 'Tôi phủi sạch vụn bánh mì trên bàn phím trước khi bắt đầu làm việc.', '{"wordId":"keyboard","ukIpa":"/ˈkiːbɔːd/","usIpa":"/ˈkiːbɔːrd/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"A set of keys used to enter information into a computer","vi":"bàn phím (máy tính)"},{"pos":"n.","en":"A musical instrument''s keys, or an electronic instrument with keys","vi":"bàn phím (nhạc cụ); đàn phím điện tử"}],"examples":[{"en":"I brushed the crumbs off my keyboard before starting work.","vi":"Tôi phủi sạch vụn bánh mì trên bàn phím trước khi bắt đầu làm việc.","audioKind":"ex"},{"en":"Students with limited mobility may benefit from an adapted keyboard that makes digital learning more accessible.","vi":"Học sinh có khả năng vận động hạn chế có thể hưởng lợi từ bàn phím thích ứng giúp việc học tập kỹ thuật số trở nên dễ tiếp cận hơn.","audioKind":"ex2"}],"collocations":[{"en":"wireless keyboard","vi":"bàn phím không dây"},{"en":"keyboard shortcut","vi":"phím tắt bàn phím"},{"en":"play the keyboard","vi":"chơi đàn phím điện tử"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Máy tính bảng/bàn phím máy tính thường dùng a keyboard; chơi nhạc cụ phím dùng play the keyboard.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_printer', 'en-a2-25', 'printer', '/ˈprɪntər/', 'A2', 'máy in; thợ in; nhà in', 'n.', 'print (v.), printing (n.), printable (adj.)', NULL, 'print là in; printer có thể chỉ máy móc hoặc người làm nghề in.', 'The printer ran out of paper halfway through my homework.', NULL, 'Máy in hết giấy khi tôi mới làm bài tập được nửa chừng.', '{"wordId":"printer","ukIpa":"/ˈprɪntə/","usIpa":"/ˈprɪntər/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"a machine that produces paper copies of digital documents or images","vi":"máy in"},{"pos":"n.","en":"a person or business that prints books and other materials","vi":"thợ in; nhà in"}],"examples":[{"en":"The printer ran out of paper halfway through my homework.","vi":"Máy in hết giấy khi tôi mới làm bài tập được nửa chừng.","audioKind":"ex"},{"en":"Schools can reduce paper waste by setting every printer to print on both sides automatically.","vi":"Các trường học có thể giảm lãng phí giấy bằng cách cài đặt mọi máy in tự động in hai mặt.","audioKind":"ex2"}],"collocations":[{"en":"laser printer","vi":"máy in laser"},{"en":"inkjet printer","vi":"máy in phun"},{"en":"printer cartridge","vi":"hộp mực máy in"}],"wordFamily":["print (v.)","printing (n.)","printable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"print là in; printer có thể chỉ máy móc hoặc người làm nghề in.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_homepage', 'en-a2-25', 'homepage', '/ˈhoʊmpeɪdʒ/', 'A2', 'trang chủ (của một trang web)', 'n.', NULL, NULL, 'Cũng có thể viết là home page; không có nghĩa là bất kỳ trang web nào khác trong một trang web lớn.', 'The library''s homepage has a photo of its new reading room.', NULL, 'Trang chủ của thư viện có đăng bức ảnh phòng đọc sách mới của họ.', '{"wordId":"homepage","ukIpa":"/ˈhəʊmpeɪdʒ/","usIpa":"/ˈhoʊmpeɪdʒ/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"The main page of a website, linking to other sections.","vi":"trang chủ (của một trang web)"}],"examples":[{"en":"The library''s homepage has a photo of its new reading room.","vi":"Trang chủ của thư viện có đăng bức ảnh phòng đọc sách mới của họ.","audioKind":"ex"},{"en":"A university homepage should provide clear access to course information, application guidance, and support services for international students.","vi":"Trang chủ của trường đại học nên cung cấp các đường dẫn rõ ràng để sinh viên quốc tế xem thông tin khóa học, hướng dẫn nộp đơn và dịch vụ hỗ trợ.","audioKind":"ex2"}],"collocations":[{"en":"website homepage","vi":"trang chủ của trang web"},{"en":"homepage design","vi":"thiết kế trang chủ"},{"en":"visit the homepage","vi":"truy cập trang chủ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cũng có thể viết là home page; không có nghĩa là bất kỳ trang web nào khác trong một trang web lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_password', 'en-a2-25', 'password', '/ˈpæswɜːrd/', 'A2', 'mật khẩu; mật mã', 'n.', NULL, NULL, 'password là mật khẩu thông thường; passcode cũng có thể dùng để chỉ mã PIN hoặc mật khẩu dạng số.', 'I forgot my password and couldn''t open my account.', NULL, 'Tôi quên mất mật khẩu nên không thể truy cập vào tài khoản của mình.', '{"wordId":"password","ukIpa":"/ˈpɑːswɜːd/","usIpa":"/ˈpæswɜːrd/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"A secret word or sequence used to gain access.","vi":"mật khẩu; mật mã"}],"examples":[{"en":"I forgot my password and couldn''t open my account.","vi":"Tôi quên mất mật khẩu nên không thể truy cập vào tài khoản của mình.","audioKind":"ex"},{"en":"Using a different password for each account can reduce the risk of personal information being stolen.","vi":"Việc sử dụng các mật khẩu khác nhau cho mỗi tài khoản có thể giảm thiểu nguy cơ bị đánh cắp thông tin cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"a strong password","vi":"mật khẩu mạnh"},{"en":"reset a password","vi":"đặt lại mật khẩu"},{"en":"enter a password","vi":"nhập mật khẩu"},{"en":"password protection","vi":"sự bảo vệ bằng mật khẩu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"password là mật khẩu thông thường; passcode cũng có thể dùng để chỉ mã PIN hoặc mật khẩu dạng số.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_headphone', 'en-a2-25', 'headphone', '/ˈhedfoʊn/', 'A2', 'tai nghe', 'n.', NULL, 'Đồng nghĩa: earpiece', 'Thường dùng ở dạng số nhiều headphones khi chỉ thiết bị, một chiếc dùng a pair of.', 'I wear headphones so my music won''t disturb anyone.', NULL, 'Tôi đeo tai nghe để âm nhạc của mình không làm phiền ai cả.', '{"wordId":"headphone","ukIpa":"/ˈhedfəʊn/","usIpa":"/ˈhedfoʊn/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"one of two earpieces worn over the ears for listening","vi":"tai nghe"}],"examples":[{"en":"I wear headphones so my music won''t disturb anyone.","vi":"Tôi đeo tai nghe để âm nhạc của mình không làm phiền ai cả.","audioKind":"ex"},{"en":"Students using headphones in shared study spaces should keep the volume low to protect their hearing.","vi":"Những sinh viên sử dụng tai nghe ở khu vực học tập chung nên giữ âm lượng ở mức thấp để bảo vệ thính lực của mình.","audioKind":"ex2"}],"collocations":[{"en":"a pair of headphones","vi":"một cặp tai nghe"},{"en":"wireless headphones","vi":"tai nghe không dây"},{"en":"headphone jack","vi":"giắc cắm tai nghe"}],"wordFamily":[],"synonyms":["earpiece"],"antonyms":[],"tipVi":"Thường dùng ở dạng số nhiều headphones khi chỉ thiết bị, một chiếc dùng a pair of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_print', 'en-a2-25', 'print', '/prɪnt/', 'A2', 'in; in ấn; chữ in; bản in; dấu vết; vết hằn', 'v.', 'printer (n.), printing (n.), printable (adj.), reprint (v.)', NULL, 'print out chỉ việc in ra; out of print chỉ sách đã tuyệt bản.', 'Could you print two copies of this recipe?', NULL, 'Bạn có thể in giúp tôi hai bản công thức nấu ăn này không?', '{"wordId":"print","ukIpa":"/prɪnt/","usIpa":"/prɪnt/","cefr":"A2","topic":"technology","senses":[{"pos":"v.","en":"To produce words or images on paper using a machine","vi":"in; in ấn"},{"pos":"n.","en":"Letters and words produced on paper by printing","vi":"chữ in; bản in"},{"pos":"n.","en":"A mark left by something pressed against a surface","vi":"dấu vết; vết hằn"}],"examples":[{"en":"Could you print two copies of this recipe?","vi":"Bạn có thể in giúp tôi hai bản công thức nấu ăn này không?","audioKind":"ex"},{"en":"Schools can reduce paper waste by encouraging students to print assignments only when physical copies are necessary.","vi":"Nhà trường có thể giảm thiểu lãng phí giấy bằng cách khuyến khích học sinh chỉ in bài tập khi thực sự cần bản giấy.","audioKind":"ex2"}],"collocations":[{"en":"print a document","vi":"in tài liệu"},{"en":"small print","vi":"chữ nhỏ; điều khoản chi tiết"},{"en":"in print","vi":"đã được xuất bản và còn bán"},{"en":"out of print","vi":"đã tuyệt bản"}],"wordFamily":["printer (n.)","printing (n.)","printable (adj.)","reprint (v.)"],"synonyms":[],"antonyms":[],"tipVi":"print out chỉ việc in ra; out of print chỉ sách đã tuyệt bản.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tablet', 'en-a2-25', 'tablet', '/ˈtæblət/', 'A2', 'máy tính bảng; viên thuốc; tấm bia; bản khắc', 'n.', NULL, NULL, 'tablet vừa có nghĩa là máy tính bảng, vừa chỉ viên thuốc, cần dựa vào ngữ cảnh để phân biệt.', 'I use my tablet to watch cooking videos.', NULL, 'Tôi dùng máy tính bảng để xem các video nấu ăn.', '{"wordId":"tablet","ukIpa":"/ˈtæblət/","usIpa":"/ˈtæblət/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"a portable computer with a flat touchscreen","vi":"máy tính bảng"},{"pos":"n.","en":"a small solid dose of medicine swallowed whole","vi":"viên thuốc"},{"pos":"n.","en":"a flat stone or metal slab bearing an inscription","vi":"tấm bia; bản khắc"}],"examples":[{"en":"I use my tablet to watch cooking videos.","vi":"Tôi dùng máy tính bảng để xem các video nấu ăn.","audioKind":"ex"},{"en":"Providing every student with a tablet may improve access to resources, but teachers still need suitable training.","vi":"Việc cung cấp máy tính bảng cho mọi học sinh có thể giúp tiếp cận tài nguyên tốt hơn, nhưng giáo viên vẫn cần được đào tạo phù hợp.","audioKind":"ex2"}],"collocations":[{"en":"tablet computer","vi":"máy tính bảng"},{"en":"take a tablet","vi":"uống thuốc viên"},{"en":"vitamin tablet","vi":"viên vitamin"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"tablet vừa có nghĩa là máy tính bảng, vừa chỉ viên thuốc, cần dựa vào ngữ cảnh để phân biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_25_1', 'en-a2-25', 'Cách dùng “technology” (n.) — công nghệ; kỹ thuật', 'digital technology  ·  advanced technology  ·  information technology', 'Khi chỉ chung chung về khoa học công nghệ thì không đếm được; dùng technologies khi chỉ nhiều loại công nghệ cụ thể.', 'Họ từ (Word Family): technological (adj.), technologically (adv.), technologist (n.)', '[{"hanzi":"New technology lets us control the lights from our phones.","pinyin":"","meaning":"Công nghệ mới cho phép chúng tôi điều khiển đèn từ điện thoại của mình."},{"hanzi":"Investment in clean technology can reduce industrial pollution while creating skilled jobs in emerging sectors.","pinyin":"","meaning":"Việc đầu tư vào công nghệ sạch có thể làm giảm ô nhiễm công nghiệp đồng thời tạo ra các việc làm đòi hỏi kỹ năng cao trong các lĩnh vực mới nổi."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_25_2', 'en-a2-25', 'Cách dùng “digital” (adj.) — thuộc về kỹ thuật số; số hóa', 'digital technology  ·  digital skills  ·  digital divide', 'Digital nhấn mạnh vào hệ thống kỹ thuật số; từ chỉ tính chất con số đơn thuần thường dùng numerical.', 'Họ từ (Word Family): digit (n.), digitally (adv.), digitise (v.), digitisation (n.) | Trái nghĩa: analogue', '[{"hanzi":"She keeps digital copies of all her family photos.","pinyin":"","meaning":"Cô ấy lưu giữ các bản sao kỹ thuật số của tất cả ảnh gia đình."},{"hanzi":"Improving digital skills can help older adults access public services and maintain contact with distant relatives.","pinyin":"","meaning":"Nâng cao kỹ năng số có thể giúp người cao tuổi tiếp cận các dịch vụ công cộng và giữ liên lạc với họ hàng ở xa."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_25_3', 'en-a2-25', 'Cách dùng “homepage” (n.) — trang chủ (của một trang web)', 'website homepage  ·  homepage design  ·  visit the homepage', 'Cũng có thể viết là home page; không có nghĩa là bất kỳ trang web nào khác trong một trang web lớn.', NULL, '[{"hanzi":"The library''s homepage has a photo of its new reading room.","pinyin":"","meaning":"Trang chủ của thư viện có đăng bức ảnh phòng đọc sách mới của họ."},{"hanzi":"A university homepage should provide clear access to course information, application guidance, and support services for international students.","pinyin":"","meaning":"Trang chủ của trường đại học nên cung cấp các đường dẫn rõ ràng để sinh viên quốc tế xem thông tin khóa học, hướng dẫn nộp đơn và dịch vụ hỗ trợ."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_25_4', 'en-a2-25', 'Cách dùng “keyboard” (n.) — bàn phím (máy tính)', 'wireless keyboard  ·  keyboard shortcut  ·  play the keyboard', 'Máy tính bảng/bàn phím máy tính thường dùng a keyboard; chơi nhạc cụ phím dùng play the keyboard.', NULL, '[{"hanzi":"I brushed the crumbs off my keyboard before starting work.","pinyin":"","meaning":"Tôi phủi sạch vụn bánh mì trên bàn phím trước khi bắt đầu làm việc."},{"hanzi":"Students with limited mobility may benefit from an adapted keyboard that makes digital learning more accessible.","pinyin":"","meaning":"Học sinh có khả năng vận động hạn chế có thể hưởng lợi từ bàn phím thích ứng giúp việc học tập kỹ thuật số trở nên dễ tiếp cận hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_25_1', 'en-a2-25', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
