INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_25_1_2', 'ten_a2_25_1', 'recorder', 'I placed the recorder beside her before the interview.', 'I placed the recorder beside her before the interview.', '/rɪˈkɔːrdər/', 'Tôi đặt máy ghi âm bên cạnh cô ấy trước buổi phỏng vấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_25_1_3', 'ten_a2_25_1', 'user', 'Each user can choose a different colour for their profile.', 'Each user can choose a different colour for their profile.', '/ˈjuːzər/', 'Mỗi người dùng có thể chọn một màu sắc khác nhau cho hồ sơ cá nhân của họ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
