INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_25_1_5', 'ten_a2_25_1', 'tool', 'This small tool helps me tighten the loose screws.', 'This small tool helps me tighten the loose screws.', '/tuːl/', 'Cây dụng cụ nhỏ này giúp tôi siết chặt những con ốc bị lỏng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_25_1_6', 'ten_a2_25_1', 'invent', 'My sister invented a clever tool for picking apples.', 'My sister invented a clever tool for picking apples.', '/ɪnˈvent/', 'Chị tôi đã phát minh ra một dụng cụ thông minh để hái táo.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_25_1_7', 'ten_a2_25_1', 'electric', 'Our electric kettle boils water in two minutes.', 'Our electric kettle boils water in two minutes.', '/ɪˈlektrɪk/', 'Ấm đun nước điện của chúng tôi đun sôi nước chỉ trong hai phút.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_25_1_8', 'ten_a2_25_1', 'online', 'I booked our train tickets online after dinner.', 'I booked our train tickets online after dinner.', '/ˌɑːnˈlaɪn/', 'Tôi đã đặt vé tàu qua mạng sau bữa tối.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_25_1_1', 'en-a2-25', 'ten_a2_25_1', 'listening', 'listening', 'My typing has become faster since I started practising.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Máy in hết giấy khi tôi mới làm bài tập được nửa chừng.","Tốc độ đánh máy của tôi đã nhanh hơn kể từ khi tôi bắt đầu luyện tập.","Tôi đeo tai nghe để âm nhạc của mình không làm phiền ai cả.","Tôi dùng máy tính bảng để xem các video nấu ăn."]'::jsonb, 1, 'My typing has become faster since I started practising. → Tốc độ đánh máy của tôi đã nhanh hơn kể từ khi tôi bắt đầu luyện tập.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_25_1_2', 'en-a2-25', 'ten_a2_25_1', 'listening', 'listening', 'I placed the recorder beside her before the interview.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cây dụng cụ nhỏ này giúp tôi siết chặt những con ốc bị lỏng.","Cô ấy lưu giữ các bản sao kỹ thuật số của tất cả ảnh gia đình.","Tôi đặt máy ghi âm bên cạnh cô ấy trước buổi phỏng vấn.","Máy in hết giấy khi tôi mới làm bài tập được nửa chừng."]'::jsonb, 2, 'I placed the recorder beside her before the interview. → Tôi đặt máy ghi âm bên cạnh cô ấy trước buổi phỏng vấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_25_1_3', 'en-a2-25', 'ten_a2_25_1', 'listening', 'listening', 'Each user can choose a different colour for their profile.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi quên mất mật khẩu nên không thể truy cập vào tài khoản của mình.","Mỗi người dùng có thể chọn một màu sắc khác nhau cho hồ sơ cá nhân của họ.","Ấm đun nước điện của chúng tôi đun sôi nước chỉ trong hai phút.","Tốc độ đánh máy của tôi đã nhanh hơn kể từ khi tôi bắt đầu luyện tập."]'::jsonb, 1, 'Each user can choose a different colour for their profile. → Mỗi người dùng có thể chọn một màu sắc khác nhau cho hồ sơ cá nhân của họ.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_25_2', 'en-a2-25', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_25_2_1', 'ten_a2_25_2', 'typing', 'Although voice recognition is improving, accurate typing remains a valuable skill in many office jobs.', 'Although voice recognition is improving, accurate typing remains a valuable skill in many office jobs.', '/ˈtaɪpɪŋ/', 'Mặc dù công nghệ nhận diện giọng nói đang cải thiện, kỹ năng đánh máy chính xác vẫn là một năng lực quý giá trong nhiều công việc văn phòng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_25_2_2', 'ten_a2_25_2', 'recorder', 'Using a digital recorder allows researchers to review interviews carefully and identify recurring themes.', 'Using a digital recorder allows researchers to review interviews carefully and identify recurring themes.', '/rɪˈkɔːrdər/', 'Việc sử dụng máy ghi âm kỹ thuật số giúp các nhà nghiên cứu xem xét kỹ lưỡng các cuộc phỏng vấn và nhận diện các chủ đề lặp lại.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_25_2_3', 'ten_a2_25_2', 'user', 'Software developers should consider the needs of every user, including people with limited technical skills.', 'Software developers should consider the needs of every user, including people with limited technical skills.', '/ˈjuːzər/', 'Các nhà phát triển phần mềm nên cân nhắc nhu cầu của mọi người dùng, kể cả những người có kỹ năng công nghệ hạn chế.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_25_2_4', 'ten_a2_25_2', 'digital', 'Improving digital skills can help older adults access public services and maintain contact with distant relatives.', 'Improving digital skills can help older adults access public services and maintain contact with distant relatives.', '/ˈdɪdʒɪtəl/', 'Nâng cao kỹ năng số có thể giúp người cao tuổi tiếp cận các dịch vụ công cộng và giữ liên lạc với họ hàng ở xa.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_25_2_5', 'ten_a2_25_2', 'tool', 'Digital maps are a valuable tool for urban planners seeking to design more accessible public transport networks.', 'Digital maps are a valuable tool for urban planners seeking to design more accessible public transport networks.', '/tuːl/', 'Bản đồ kỹ thuật số là công cụ đắc lực cho các nhà quy hoạch đô thị khi muốn thiết kế các mạng lưới giao thông công cộng dễ tiếp cận hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_25_2_6', 'ten_a2_25_2', 'invent', 'Engineers must invent affordable technologies that help rural communities gain access to clean drinking water.', 'Engineers must invent affordable technologies that help rural communities gain access to clean drinking water.', '/ɪnˈvent/', 'Các kỹ sư phải phát minh ra những công nghệ có giá cả phải chăng giúp cộng đồng nông thôn tiếp cận nguồn nước uống sạch.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_25_2_1', 'en-a2-25', 'ten_a2_25_2', 'listening', 'listening', 'Although voice recognition is improving, accurate typing remains a valuable skill in many office jobs.', NULL, 'Trong câu vừa nghe, từ “typing” mang nghĩa nào sau đây?', '["ghế sô-pha; ghế dài có tựa","dễ chịu; thoải mái","thuộc về Thụy Điển, người Thụy Điển hoặc tiếng Thụy Điển","việc đánh máy; thao tác gõ phím"]'::jsonb, 3, '“typing” (/ˈtaɪpɪŋ/): việc đánh máy; thao tác gõ phím. Câu đầy đủ: Although voice recognition is improving, accurate typing remains a valuable skill in many office jobs.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_25_2_2', 'en-a2-25', 'ten_a2_25_2', 'listening', 'listening', 'Using a digital recorder allows researchers to review interviews carefully and identify recurring themes.', NULL, 'Trong câu vừa nghe, từ “recorder” mang nghĩa nào sau đây?', '["y tá; điều dưỡng viên","đi qua; vượt qua","sức khỏe; thể trạng","máy ghi âm; thiết bị ghi hình"]'::jsonb, 3, '“recorder” (/rɪˈkɔːrdər/): máy ghi âm; thiết bị ghi hình. Câu đầy đủ: Using a digital recorder allows researchers to review interviews carefully and identify recurring themes.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
