INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_25_2', 'en-a2-25', NULL, 'comprehensive_test', 'listening', 'I placed the recorder beside her before the interview.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Máy in hết giấy khi tôi mới làm bài tập được nửa chừng.","Bạn có thể in giúp tôi hai bản công thức nấu ăn này không?","Tôi đặt máy ghi âm bên cạnh cô ấy trước buổi phỏng vấn.","Ấm đun nước điện của chúng tôi đun sôi nước chỉ trong hai phút."]'::jsonb, 2, 'I placed the recorder beside her before the interview. → Tôi đặt máy ghi âm bên cạnh cô ấy trước buổi phỏng vấn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
