INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_25_4', 'en-a2-25', NULL, 'comprehensive_test', 'listening', 'She keeps digital copies of all her family photos.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy lưu giữ các bản sao kỹ thuật số của tất cả ảnh gia đình.","Bạn có thể in giúp tôi hai bản công thức nấu ăn này không?","Ấm đun nước điện của chúng tôi đun sôi nước chỉ trong hai phút.","Hệ thống sưởi đã ngừng hoạt động trong một đêm lạnh giá."]'::jsonb, 0, 'She keeps digital copies of all her family photos. → Cô ấy lưu giữ các bản sao kỹ thuật số của tất cả ảnh gia đình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_25_5', 'en-a2-25', NULL, 'comprehensive_test', 'listening', 'tool', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ý kiến; quan điểm; đánh giá","rác thải; vật bỏ đi","bánh kếp; bánh xèo mỏng","công cụ; dụng cụ (dùng để xây dựng, sửa chữa)"]'::jsonb, 3, 'tool (/tuːl/) → công cụ; dụng cụ (dùng để xây dựng, sửa chữa); phương tiện; công cụ hỗ trợ để thực hiện công việc hoặc đạt mục đích', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_25_6', 'en-a2-25', NULL, 'comprehensive_test', 'listening', 'My sister invented a clever tool for picking apples.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đeo tai nghe để âm nhạc của mình không làm phiền ai cả.","Tốc độ đánh máy của tôi đã nhanh hơn kể từ khi tôi bắt đầu luyện tập.","Tôi đã lau sạch các vết dấu tay trên màn hình máy tính xách tay của mình.","Chị tôi đã phát minh ra một dụng cụ thông minh để hái táo."]'::jsonb, 3, 'My sister invented a clever tool for picking apples. → Chị tôi đã phát minh ra một dụng cụ thông minh để hái táo.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_25_7', 'en-a2-25', NULL, 'comprehensive_test', 'listening', 'electric', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khả năng chính tả; cách viết đúng chính tả","kết hôn với ai; lập gia đình","thuộc về điện; chạy bằng điện","tim; trái tim"]'::jsonb, 2, 'electric (/ɪˈlektrɪk/) → thuộc về điện; chạy bằng điện; sôi nổi; cuồng nhiệt', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_25_8', 'en-a2-25', NULL, 'comprehensive_test', 'listening', 'I booked our train tickets online after dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Công nghệ mới cho phép chúng tôi điều khiển đèn từ điện thoại của mình.","Tôi phủi sạch vụn bánh mì trên bàn phím trước khi bắt đầu làm việc.","Chị tôi đã phát minh ra một dụng cụ thông minh để hái táo.","Tôi đã đặt vé tàu qua mạng sau bữa tối."]'::jsonb, 3, 'I booked our train tickets online after dinner. → Tôi đã đặt vé tàu qua mạng sau bữa tối.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_25_9', 'en-a2-25', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An object used to build, repair, or make things.”?', '["tablet","headphone","technology","tool"]'::jsonb, 3, 'tool (/tuːl/) → công cụ; dụng cụ (dùng để xây dựng, sửa chữa)', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_25_10', 'en-a2-25', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “To design or make something that did not exist before.”?', '["invent","user","homepage","system"]'::jsonb, 0, 'invent (/ɪnˈvent/) → phát minh; sáng chế', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_25_11', 'en-a2-25', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Using, producing, or relating to electricity.”?', '["invent","recorder","electric","printer"]'::jsonb, 2, 'electric (/ɪˈlektrɪk/) → thuộc về điện; chạy bằng điện', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_25_12', 'en-a2-25', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Available through the internet or connected to a computer network.”?', '["technology","password","typing","online"]'::jsonb, 3, 'online (/ˌɑːnˈlaɪn/) → trực tuyến; ở trên mạng', 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_25_13', 'en-a2-25', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Practical use of scientific knowledge, especially through tools and machines.”?', '["online","digital","electric","technology"]'::jsonb, 3, 'technology (/tekˈnɑːlədʒi/) → công nghệ; kỹ thuật', 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
