INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_25_18', 'en-a2-25', NULL, 'comprehensive_test', 'reading', NULL, 'Although voice recognition is improving, accurate typing remains a valuable skill in many office jobs.', 'Dựa vào câu trên, từ “typing” có nghĩa phù hợp nhất là gì?', '["nút; nút bấm","từ (một thời điểm trong quá khứ) cho đến nay","việc đánh máy; thao tác gõ phím","văn bản; chữ"]'::jsonb, 2, 'typing: việc đánh máy; thao tác gõ phím. Dịch cả câu: Mặc dù công nghệ nhận diện giọng nói đang cải thiện, kỹ năng đánh máy chính xác vẫn là một năng lực quý giá trong nhiều công việc văn phòng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_25_19', 'en-a2-25', NULL, 'comprehensive_test', 'reading', NULL, 'Using a digital recorder allows researchers to review interviews carefully and identify recurring themes.', 'Dựa vào câu trên, từ “recorder” có nghĩa phù hợp nhất là gì?', '["khách; khách tham quan; du khách","điện; năng lượng điện","công việc nhà; việc nhà","máy ghi âm; thiết bị ghi hình"]'::jsonb, 3, 'recorder: máy ghi âm; thiết bị ghi hình; sáo dọc; người ghi chép. Dịch cả câu: Việc sử dụng máy ghi âm kỹ thuật số giúp các nhà nghiên cứu xem xét kỹ lưỡng các cuộc phỏng vấn và nhận diện các chủ đề lặp lại.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_25_20', 'en-a2-25', NULL, 'comprehensive_test', 'reading', NULL, 'Software developers should consider the needs of every user, including people with limited technical skills.', 'Dựa vào câu trên, từ “user” có nghĩa phù hợp nhất là gì?', '["người dùng; người sử dụng","người chiến thắng; đội chiến thắng","tưởng tượng; hình dung","khói; làn khói"]'::jsonb, 0, 'user: người dùng; người sử dụng. Dịch cả câu: Các nhà phát triển phần mềm nên cân nhắc nhu cầu của mọi người dùng, kể cả những người có kỹ năng công nghệ hạn chế.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_25_21', 'en-a2-25', NULL, 'comprehensive_test', 'reading', NULL, 'Improving digital skills can help older adults access public services and maintain contact with distant relatives.', 'Dựa vào câu trên, từ “digital” có nghĩa phù hợp nhất là gì?', '["mới nhất, gần đây nhất","về phía, hướng về","thuộc về kỹ thuật số; số hóa","mỹ phẩm; đồ trang điểm"]'::jsonb, 2, 'digital: thuộc về kỹ thuật số; số hóa. Dịch cả câu: Nâng cao kỹ năng số có thể giúp người cao tuổi tiếp cận các dịch vụ công cộng và giữ liên lạc với họ hàng ở xa.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
