INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-26', 'en', 'Bài 26: Công nghệ & Kỹ thuật (2) - CEFR A2', 'CEFR A2', 'A2 · Công nghệ', '18 từ vựng Tiếng Anh CEFR A2 chủ đề công nghệ & kỹ thuật kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2026, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pc', 'en-a2-26', 'PC', '/ˌpiː ˈsiː/', 'A2', 'máy tính cá nhân', 'n.', NULL, 'Đồng nghĩa: personal computer', 'PC là viết tắt của personal computer; dạng số nhiều là PCs.', 'My PC takes ages to start on cold mornings.', NULL, 'Máy tính cá nhân của tôi mất rất lâu để khởi động vào những buổi sáng lạnh trời.', '{"wordId":"pc","ukIpa":"/ˌpiː ˈsiː/","usIpa":"/ˌpiː ˈsiː/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"A computer designed for use by one person.","vi":"máy tính cá nhân"}],"examples":[{"en":"My PC takes ages to start on cold mornings.","vi":"Máy tính cá nhân của tôi mất rất lâu để khởi động vào những buổi sáng lạnh trời.","audioKind":"ex"},{"en":"Providing each student with a PC may improve access to digital resources, but requires substantial funding.","vi":"Việc cung cấp cho mỗi học sinh một chiếc máy tính cá nhân có thể cải thiện khả năng tiếp cận tài nguyên số, nhưng đòi hỏi nguồn kinh phí lớn.","audioKind":"ex2"}],"collocations":[{"en":"desktop PC","vi":"máy tính cá nhân để bàn"},{"en":"use a PC","vi":"sử dụng máy tính cá nhân"},{"en":"PC software","vi":"phần mềm máy tính cá nhân"}],"wordFamily":[],"synonyms":["personal computer"],"antonyms":[],"tipVi":"PC là viết tắt của personal computer; dạng số nhiều là PCs.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_app', 'en-a2-26', 'app', '/æp/', 'A2', 'ứng dụng; chương trình máy tính', 'n.', 'application (n.)', 'Đồng nghĩa: application', 'app là viết tắt của application; là danh từ đếm được, dùng với an app.', 'This app reminds me to water my plants every Sunday.', NULL, 'Ứng dụng này nhắc tôi tưới cây vào mỗi chủ nhật.', '{"wordId":"app","ukIpa":"/æp/","usIpa":"/æp/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"A computer program designed for a particular task.","vi":"ứng dụng; chương trình máy tính"}],"examples":[{"en":"This app reminds me to water my plants every Sunday.","vi":"Ứng dụng này nhắc tôi tưới cây vào mỗi chủ nhật.","audioKind":"ex"},{"en":"A language learning app can provide affordable practice, although it cannot fully replace interaction with a teacher.","vi":"Một ứng dụng học ngôn ngữ có thể cung cấp các bài tập với chi phí hợp lý, mặc dù nó không thể thay thế hoàn toàn sự tương tác với giáo viên.","audioKind":"ex2"}],"collocations":[{"en":"download an app","vi":"tải ứng dụng"},{"en":"mobile app","vi":"ứng dụng di động"},{"en":"install an app","vi":"cài đặt ứng dụng"},{"en":"language learning app","vi":"ứng dụng học ngoại ngữ"}],"wordFamily":["application (n.)"],"synonyms":["application"],"antonyms":[],"tipVi":"app là viết tắt của application; là danh từ đếm được, dùng với an app.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_download', 'en-a2-26', 'download', '/ˌdaʊnˈloʊd/', 'A2', 'tải xuống; sự tải xuống; tệp tải xuống', 'v.', 'downloadable (adj.)', 'Trái nghĩa: upload', 'Động từ nhấn trọng âm ở âm tiết sau, danh từ nhấn ở âm tiết đầu; từ trái nghĩa là ''upload''.', 'Download the map before you leave the hotel tomorrow.', NULL, 'Hãy tải bản đồ xuống trước khi bạn rời khách sạn vào ngày mai.', '{"wordId":"download","ukIpa":"/ˌdaʊnˈləʊd/","usIpa":"/ˌdaʊnˈloʊd/","cefr":"A2","topic":"technology","senses":[{"pos":"v.","en":"to copy data from the internet onto your device","vi":"tải xuống"},{"pos":"n.","en":"the act of downloading, or a file obtained this way","vi":"sự tải xuống; tệp tải xuống"}],"examples":[{"en":"Download the map before you leave the hotel tomorrow.","vi":"Hãy tải bản đồ xuống trước khi bạn rời khách sạn vào ngày mai.","audioKind":"ex"},{"en":"Students can download course materials at home, allowing them to study even when internet access is unavailable.","vi":"Học sinh có thể tải tài liệu khóa học về nhà, giúp các em học tập ngay cả khi không có kết nối internet.","audioKind":"ex2"}],"collocations":[{"en":"download a file","vi":"tải tệp xuống"},{"en":"download an app","vi":"tải ứng dụng"},{"en":"free download","vi":"tải xuống miễn phí"},{"en":"download speed","vi":"tốc độ tải xuống"}],"wordFamily":["downloadable (adj.)"],"synonyms":[],"antonyms":["upload"],"tipVi":"Động từ nhấn trọng âm ở âm tiết sau, danh từ nhấn ở âm tiết đầu; từ trái nghĩa là ''upload''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_program', 'en-a2-26', 'program', '/ˈproʊɡræm/', 'A2', 'chương trình máy tính; lập trình; cài đặt chương trình; chương trình; kế hoạch; lịch trình', 'n.', 'programmer (n.), programming (n.), programmable (adj.)', NULL, 'Tiếng Anh-Anh dùng program cho chương trình máy tính; programme cho kế hoạch, chương trình truyền hình.', 'This program helps me organise all my holiday photos.', NULL, 'Chương trình này giúp tôi sắp xếp tất cả các bức ảnh kỳ nghỉ của mình.', '{"wordId":"program","ukIpa":"/ˈprəʊɡræm/","usIpa":"/ˈproʊɡræm/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"A set of instructions that tells a computer what to do.","vi":"chương trình máy tính"},{"pos":"v.","en":"Write computer instructions or set a machine to operate automatically.","vi":"lập trình; cài đặt chương trình"},{"pos":"n.","en":"An organised plan, course of activities, or broadcast show.","vi":"chương trình; kế hoạch; lịch trình"}],"examples":[{"en":"This program helps me organise all my holiday photos.","vi":"Chương trình này giúp tôi sắp xếp tất cả các bức ảnh kỳ nghỉ của mình.","audioKind":"ex"},{"en":"Schools should teach students how to program computers rather than simply how to use existing software.","vi":"Các trường học nên dạy học sinh cách lập trình máy tính thay vì chỉ đơn thuần biết cách sử dụng phần mềm có sẵn.","audioKind":"ex2"}],"collocations":[{"en":"computer program","vi":"chương trình máy tính"},{"en":"run a program","vi":"chạy chương trình"},{"en":"program a computer","vi":"lập trình máy tính"},{"en":"training program","vi":"chương trình đào tạo"}],"wordFamily":["programmer (n.)","programming (n.)","programmable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Tiếng Anh-Anh dùng program cho chương trình máy tính; programme cho kế hoạch, chương trình truyền hình.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mobile', 'en-a2-26', 'mobile', '/ˈmoʊbəl/', 'A2', 'di động; có thể di chuyển; thuộc di động (viễn thông); điện thoại di động', 'adj.', 'mobility (n.), immobile (adj.), mobilise (v.)', 'Trái nghĩa: immobile', 'Tiếng Anh-Anh thường dùng a mobile để chỉ điện thoại di động; tiếng Anh-Mỹ hay dùng a cell phone.', 'The mobile library visits our village every Friday morning.', NULL, 'Thư viện lưu động đến thăm làng chúng tôi vào mỗi sáng thứ Sáu.', '{"wordId":"mobile","ukIpa":"/ˈməʊbaɪl/","usIpa":"/ˈmoʊbəl/","cefr":"A2","topic":"technology","senses":[{"pos":"adj.","en":"able to move or be moved easily between places","vi":"di động; có thể di chuyển"},{"pos":"adj.","en":"relating to phones or services used while away from home","vi":"thuộc di động (viễn thông)"},{"pos":"n.","en":"a telephone you can carry and use almost anywhere","vi":"điện thoại di động"}],"examples":[{"en":"The mobile library visits our village every Friday morning.","vi":"Thư viện lưu động đến thăm làng chúng tôi vào mỗi sáng thứ Sáu.","audioKind":"ex"},{"en":"Mobile clinics can improve access to basic healthcare for people living in remote rural communities.","vi":"Các phòng khám lưu động có thể giúp người dân sống ở các cộng đồng nông thôn vùng sâu vùng xa dễ dàng tiếp cận dịch vụ chăm sóc sức khỏe cơ bản hơn.","audioKind":"ex2"}],"collocations":[{"en":"mobile phone","vi":"điện thoại di động"},{"en":"mobile clinic","vi":"phòng khám lưu động"},{"en":"mobile workforce","vi":"lực lượng lao động di động"},{"en":"mobile network","vi":"mạng di động"}],"wordFamily":["mobility (n.)","immobile (adj.)","mobilise (v.)"],"synonyms":[],"antonyms":["immobile"],"tipVi":"Tiếng Anh-Anh thường dùng a mobile để chỉ điện thoại di động; tiếng Anh-Mỹ hay dùng a cell phone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wifi', 'en-a2-26', 'wifi', '/ˈwaɪ faɪ/', 'A2', 'mạng không dây; wifi', 'n.', NULL, NULL, 'Quy chuẩn viết đúng chính tả là Wi-Fi; thường là danh từ không đếm được, không thêm mạo từ a.', 'The café offers free wifi near the window seats.', NULL, 'Quán cà phê có cung cấp wifi miễn phí ở khu vực ghế ngồi gần cửa sổ.', '{"wordId":"wifi","ukIpa":"/ˈwaɪ faɪ/","usIpa":"/ˈwaɪ faɪ/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"Technology connecting devices to a network without cables.","vi":"mạng không dây; wifi"}],"examples":[{"en":"The café offers free wifi near the window seats.","vi":"Quán cà phê có cung cấp wifi miễn phí ở khu vực ghế ngồi gần cửa sổ.","audioKind":"ex"},{"en":"Providing reliable public wifi can help residents access essential services and participate in online learning.","vi":"Cung cấp mạng wifi công cộng ổn định giúp người dân tiếp cận các dịch vụ thiết yếu và tham gia học tập trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"free wifi","vi":"wifi miễn phí"},{"en":"wifi connection","vi":"kết nối wifi"},{"en":"wifi password","vi":"mật khẩu wifi"},{"en":"wifi signal","vi":"tín hiệu wifi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Quy chuẩn viết đúng chính tả là Wi-Fi; thường là danh từ không đếm được, không thêm mạo từ a.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_file', 'en-a2-26', 'file', '/faɪl/', 'A2', 'tệp tin; tài liệu lưu trữ; lưu trữ hồ sơ; nộp đơn; cái giũa', 'n.', 'filing (n.)', NULL, 'file a complaint chỉ việc chính thức khiếu nại, không phải là mang đơn khiếu nại đi cất vào hồ sơ.', 'I saved the file before switching off my laptop.', NULL, 'Tôi đã lưu tệp trước khi tắt máy tính xách tay của mình.', '{"wordId":"file","ukIpa":"/faɪl/","usIpa":"/faɪl/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"Stored information on a computer, or an organized collection of papers.","vi":"tệp tin; tài liệu lưu trữ"},{"pos":"v.","en":"To store documents systematically or submit them to an authority.","vi":"lưu trữ hồ sơ; nộp đơn"},{"pos":"n.","en":"A rough metal tool used to smooth or shape surfaces.","vi":"cái giũa"}],"examples":[{"en":"I saved the file before switching off my laptop.","vi":"Tôi đã lưu tệp trước khi tắt máy tính xách tay của mình.","audioKind":"ex"},{"en":"Public institutions should store confidential files securely to prevent unauthorized access and protect citizens'' personal information.","vi":"Các cơ quan công quyền nên lưu trữ tài liệu mật một cách an toàn để ngăn chặn việc truy cập trái phép và bảo vệ thông tin cá nhân của công dân.","audioKind":"ex2"}],"collocations":[{"en":"save a file","vi":"lưu tệp"},{"en":"attach a file","vi":"đính kèm tệp"},{"en":"file a complaint","vi":"nộp đơn khiếu nại"},{"en":"file documents","vi":"lưu trữ tài liệu"}],"wordFamily":["filing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"file a complaint chỉ việc chính thức khiếu nại, không phải là mang đơn khiếu nại đi cất vào hồ sơ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_selfie', 'en-a2-26', 'selfie', '/ˈselfi/', 'A2', 'ảnh tự chụp; ảnh selfie', 'n.', NULL, NULL, 'Chụp ảnh tự chụp dùng take a selfie, không dùng make a selfie.', 'We took a selfie beside the lake after our walk.', NULL, 'Chúng tôi đã chụp một bức ảnh tự chụp bên hồ sau buổi đi dạo.', '{"wordId":"selfie","ukIpa":"/ˈselfi/","usIpa":"/ˈselfi/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"A photograph you take of yourself, usually with a phone.","vi":"ảnh tự chụp; ảnh selfie"}],"examples":[{"en":"We took a selfie beside the lake after our walk.","vi":"Chúng tôi đã chụp một bức ảnh tự chụp bên hồ sau buổi đi dạo.","audioKind":"ex"},{"en":"Sharing a selfie online can express personal identity, but users should consider their privacy settings first.","vi":"Chia sẻ ảnh tự chụp trực tuyến có thể thể hiện bản sắc cá nhân, nhưng người dùng nên cân nhắc cài đặt quyền riêng tư trước tiên.","audioKind":"ex2"}],"collocations":[{"en":"take a selfie","vi":"chụp ảnh selfie"},{"en":"post a selfie","vi":"đăng ảnh selfie"},{"en":"selfie stick","vi":"gậy chụp ảnh selfie"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chụp ảnh tự chụp dùng take a selfie, không dùng make a selfie.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_robot', 'en-a2-26', 'robot', '/ˈroʊbɑːt/', 'A2', 'robot; người máy tự động', 'n.', 'robotic (adj.), robotics (n.), robotically (adv.)', NULL, 'robot là danh từ đếm được; robotics dùng để chỉ ngành chế tạo robot.', 'A small robot cleaned the floor while we ate breakfast.', NULL, 'Một con robot nhỏ đã lau sàn nhà trong lúc chúng tôi ăn sáng.', '{"wordId":"robot","ukIpa":"/ˈrəʊbɒt/","usIpa":"/ˈroʊbɑːt/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"a machine programmed to perform tasks automatically","vi":"robot; người máy tự động"}],"examples":[{"en":"A small robot cleaned the floor while we ate breakfast.","vi":"Một con robot nhỏ đã lau sàn nhà trong lúc chúng tôi ăn sáng.","audioKind":"ex"},{"en":"Robots can perform repetitive factory tasks, but workers may need additional training to move into new roles.","vi":"Robot có thể thực hiện các công việc lặp đi lặp lại trong nhà máy, nhưng công nhân có thể cần được đào tạo thêm để chuyển sang các vai trò mới.","audioKind":"ex2"}],"collocations":[{"en":"industrial robot","vi":"robot công nghiệp"},{"en":"robot arm","vi":"cánh tay robot"},{"en":"autonomous robot","vi":"robot tự hành"}],"wordFamily":["robotic (adj.)","robotics (n.)","robotically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"robot là danh từ đếm được; robotics dùng để chỉ ngành chế tạo robot.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_smartphone', 'en-a2-26', 'smartphone', '/ˈsmɑːrtfoʊn/', 'A2', 'điện thoại thông minh', 'n.', NULL, NULL, 'smartphone là danh từ đếm được, thường được viết liền thành một từ.', 'I used my smartphone to photograph the evening sky.', NULL, 'Tôi dùng điện thoại thông minh để chụp lại bầu trời chiều.', '{"wordId":"smartphone","ukIpa":"/ˈsmɑːtfəʊn/","usIpa":"/ˈsmɑːrtfoʊn/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"A mobile phone with internet access and computer-like functions.","vi":"điện thoại thông minh"}],"examples":[{"en":"I used my smartphone to photograph the evening sky.","vi":"Tôi dùng điện thoại thông minh để chụp lại bầu trời chiều.","audioKind":"ex"},{"en":"Although smartphones provide convenient access to information, excessive use may disrupt sleep and reduce concentration.","vi":"Mặc dù điện thoại thông minh giúp truy cập thông tin thuận tiện, việc lạm dụng có thể làm gián đoạn giấc ngủ và giảm khả năng tập trung.","audioKind":"ex2"}],"collocations":[{"en":"smartphone app","vi":"ứng dụng điện thoại thông minh"},{"en":"smartphone user","vi":"người dùng điện thoại thông minh"},{"en":"smartphone addiction","vi":"tình trạng nghiện điện thoại thông minh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"smartphone là danh từ đếm được, thường được viết liền thành một từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_click', 'en-a2-26', 'click', '/klɪk/', 'A2', 'nhấp chuột; chọn một mục trên màn hình; tiếng kêu lách cách; hành động nhấp chọn trên màn hình; chợt hiểu ra; bỗng nhiên vỡ lẽ', 'v.', 'clickable (adj.)', NULL, 'Khi nhấp vào liên kết thường dùng click on; cấu trúc it clicked có thể dùng khi chợt hiểu ra vấn đề.', 'Click on the picture to see a larger version.', NULL, 'Nhấp vào bức ảnh để xem phiên bản lớn hơn.', '{"wordId":"click","ukIpa":"/klɪk/","usIpa":"/klɪk/","cefr":"A2","topic":"technology","senses":[{"pos":"v.","en":"to press a mouse button or select something on screen","vi":"nhấp chuột; chọn một mục trên màn hình"},{"pos":"n.","en":"a short sharp sound, or an action selecting something onscreen","vi":"tiếng kêu lách cách; hành động nhấp chọn trên màn hình"},{"pos":"v.","en":"to suddenly become clear or understood","vi":"chợt hiểu ra; bỗng nhiên vỡ lẽ"}],"examples":[{"en":"Click on the picture to see a larger version.","vi":"Nhấp vào bức ảnh để xem phiên bản lớn hơn.","audioKind":"ex"},{"en":"Students should check whether a website is trustworthy before they click on links or share personal information.","vi":"Học sinh nên kiểm tra xem một trang web có đáng tin cậy hay không trước khi nhấp vào các liên kết hoặc chia sẻ thông tin cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"click on a link","vi":"nhấp vào một liên kết"},{"en":"a mouse click","vi":"một cú nhấp chuột"},{"en":"a sharp click","vi":"tiếng lách cách sắc bén"}],"wordFamily":["clickable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi nhấp vào liên kết thường dùng click on; cấu trúc it clicked có thể dùng khi chợt hiểu ra vấn đề.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_equipment', 'en-a2-26', 'equipment', '/ɪˈkwɪpmənt/', 'A2', 'thiết bị, dụng cụ, trang thiết bị', 'n.', 'equip (v.), equipped (adj.)', 'Đồng nghĩa: gear', 'Equipment là danh từ không đếm được; khi chỉ một món thiết bị cụ thể, dùng cụm a piece of equipment.', 'Please put the camping equipment back in the garage.', NULL, 'Xin hãy cất đồ dùng cắm trại trở lại nhà xe.', '{"wordId":"equipment","ukIpa":"/ɪˈkwɪpmənt/","usIpa":"/ɪˈkwɪpmənt/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"the tools and other items needed for a particular activity","vi":"thiết bị, dụng cụ, trang thiết bị"}],"examples":[{"en":"Please put the camping equipment back in the garage.","vi":"Xin hãy cất đồ dùng cắm trại trở lại nhà xe.","audioKind":"ex"},{"en":"Schools need suitable laboratory equipment to give students practical experience and encourage an interest in science.","vi":"Các trường học cần trang bị thiết bị phòng thí nghiệm phù hợp để mang lại cho học sinh kinh nghiệm thực tế và khơi dậy niềm yêu thích khoa học.","audioKind":"ex2"}],"collocations":[{"en":"sports equipment","vi":"dụng cụ thể thao"},{"en":"medical equipment","vi":"trang thiết bị y tế"},{"en":"safety equipment","vi":"thiết bị an toàn"},{"en":"a piece of equipment","vi":"một thiết bị / món đồ trang thiết bị"}],"wordFamily":["equip (v.)","equipped (adj.)"],"synonyms":["gear"],"antonyms":[],"tipVi":"Equipment là danh từ không đếm được; khi chỉ một món thiết bị cụ thể, dùng cụm a piece of equipment.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_engine', 'en-a2-26', 'engine', '/ˈendʒɪn/', 'A2', 'động cơ; máy; động lực; phần mềm cốt lõi; công cụ phần mềm', 'n.', NULL, 'Đồng nghĩa: motor', 'Engine thường chỉ động cơ chạy bằng nhiên liệu; động cơ điện thường dùng motor.', 'The engine stopped just as we reached the driveway.', NULL, 'Động cơ tắt ngúm ngay khi chúng tôi lái xe đến lối vào nhà.', '{"wordId":"engine","ukIpa":"/ˈendʒɪn/","usIpa":"/ˈendʒɪn/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"a machine that produces power to make something move","vi":"động cơ; máy"},{"pos":"n.","en":"something that strongly drives growth or change","vi":"động lực"},{"pos":"n.","en":"software that performs a particular core task within a system","vi":"phần mềm cốt lõi; công cụ phần mềm"}],"examples":[{"en":"The engine stopped just as we reached the driveway.","vi":"Động cơ tắt ngúm ngay khi chúng tôi lái xe đến lối vào nhà.","audioKind":"ex"},{"en":"Cleaner engine technology can reduce air pollution, although expanding public transport remains essential for sustainable urban travel.","vi":"Công nghệ động cơ sạch hơn có thể làm giảm ô nhiễm không khí, mặc dù việc mở rộng giao thông công cộng vẫn rất cần thiết cho việc đi lại đô thị bền vững.","audioKind":"ex2"}],"collocations":[{"en":"start the engine","vi":"khởi động động cơ"},{"en":"jet engine","vi":"động cơ phản lực"},{"en":"search engine","vi":"công cụ tìm kiếm"},{"en":"an engine of growth","vi":"động lực tăng trưởng"}],"wordFamily":[],"synonyms":["motor"],"antonyms":[],"tipVi":"Engine thường chỉ động cơ chạy bằng nhiên liệu; động cơ điện thường dùng motor.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_software', 'en-a2-26', 'software', '/ˈsɔːftwer/', 'A2', 'phần mềm', 'n.', NULL, NULL, 'Từ không đếm được: nói some software, không nói a software.', 'This software helps me edit photos on my laptop.', NULL, 'Phần mềm này giúp tôi chỉnh sửa ảnh trên máy tính xách tay.', '{"wordId":"software","ukIpa":"/ˈsɒftweə/","usIpa":"/ˈsɔːftwer/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"programs that tell a computer how to perform tasks","vi":"phần mềm"}],"examples":[{"en":"This software helps me edit photos on my laptop.","vi":"Phần mềm này giúp tôi chỉnh sửa ảnh trên máy tính xách tay.","audioKind":"ex"},{"en":"Schools need reliable software and adequate teacher training to make effective use of digital learning tools.","vi":"Các trường học cần phần mềm đáng tin cậy và chương trình đào tạo giáo viên đầy đủ để sử dụng hiệu quả các công cụ học tập kỹ thuật số.","audioKind":"ex2"}],"collocations":[{"en":"install software","vi":"cài đặt phần mềm"},{"en":"software development","vi":"phát triển phần mềm"},{"en":"software update","vi":"cập nhật phần mềm"},{"en":"open-source software","vi":"phần mềm mã nguồn mở"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ không đếm được: nói some software, không nói a software.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_web', 'en-a2-26', 'web', '/web/', 'A2', 'mạng toàn cầu; internet; mạng nhện; mạng lưới phức tạp; mối quan hệ chằng chịt', 'n.', 'website (n.), webpage (n.)', NULL, 'Lên mạng thường dùng on the web; web không hoàn toàn đồng nghĩa với internet.', 'I found a simple soup recipe on the web.', NULL, 'Tôi tìm thấy một công thức nấu món súp đơn giản trên mạng.', '{"wordId":"web","ukIpa":"/web/","usIpa":"/web/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"The system of connected pages accessed through the internet.","vi":"mạng toàn cầu; internet"},{"pos":"n.","en":"A structure of fine threads a spider makes to catch insects.","vi":"mạng nhện"},{"pos":"n.","en":"A complicated network of connected things or relationships.","vi":"mạng lưới phức tạp; mối quan hệ chằng chịt"}],"examples":[{"en":"I found a simple soup recipe on the web.","vi":"Tôi tìm thấy một công thức nấu món súp đơn giản trên mạng.","audioKind":"ex"},{"en":"Although the web provides convenient access to information, students must learn to evaluate the reliability of online sources.","vi":"Mặc dù mạng toàn cầu mang lại sự tiện lợi trong việc tiếp cận thông tin, học sinh phải học cách đánh giá độ tin cậy của các nguồn trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"browse the web","vi":"lướt web"},{"en":"a spider''s web","vi":"mạng nhện"},{"en":"a web of relationships","vi":"mạng lưới quan hệ phức tạp"}],"wordFamily":["website (n.)","webpage (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Lên mạng thường dùng on the web; web không hoàn toàn đồng nghĩa với internet.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_laptop', 'en-a2-26', 'laptop', '/ˈlæptɑːp/', 'A2', 'máy tính xách tay; máy tính xách tay cá nhân', 'n.', NULL, 'Đồng nghĩa: notebook computer', 'laptop là máy tính xách tay; desktop thường dùng để chỉ máy tính để bàn.', 'My laptop fits neatly into the front of my backpack.', NULL, 'Chiếc máy tính xách tay của tôi vừa khít vào ngăn phía trước của balo.', '{"wordId":"laptop","ukIpa":"/ˈlæptɒp/","usIpa":"/ˈlæptɑːp/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"A portable computer with a screen that folds over its keyboard.","vi":"máy tính xách tay; máy tính xách tay cá nhân"}],"examples":[{"en":"My laptop fits neatly into the front of my backpack.","vi":"Chiếc máy tính xách tay của tôi vừa khít vào ngăn phía trước của balo.","audioKind":"ex"},{"en":"Providing every student with a laptop may improve access to learning resources, but technical support remains essential.","vi":"Việc cung cấp máy tính xách tay cho mỗi học sinh có thể cải thiện khả năng tiếp cận các nguồn tài nguyên học tập, nhưng hỗ trợ kỹ thuật vẫn là điều thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"laptop computer","vi":"máy tính xách tay"},{"en":"laptop charger","vi":"sạc máy tính xách tay"},{"en":"laptop battery","vi":"pin máy tính xách tay"}],"wordFamily":[],"synonyms":["notebook computer"],"antonyms":[],"tipVi":"laptop là máy tính xách tay; desktop thường dùng để chỉ máy tính để bàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_connect', 'en-a2-26', 'connect', '/kəˈnekt/', 'A2', 'kết nối; nối liền; cắm (thiết bị điện tử); liên kết; liên hệ (nhận ra hoặc thiết lập mối quan hệ giữa các sự vật); gắn kết; tạo dựng mối quan hệ tốt đẹp với ai đó', 'v.', 'connection (n.), connected (adj.), connectivity (n.), disconnect (v.)', 'Đồng nghĩa: link, join · Trái nghĩa: disconnect', 'Kết nối thiết bị thường dùng cấu trúc connect A to B.', 'Connect your phone to the speaker using this cable.', NULL, 'Hãy kết nối điện thoại của bạn với loa bằng cáp này.', '{"wordId":"connect","ukIpa":"/kəˈnekt/","usIpa":"/kəˈnekt/","cefr":"A2","topic":"technology","senses":[{"pos":"v.","en":"to join things together or link them electronically","vi":"kết nối; nối liền; cắm (thiết bị điện tử)"},{"pos":"v.","en":"to recognize or establish a relationship between things","vi":"liên kết; liên hệ (nhận ra hoặc thiết lập mối quan hệ giữa các sự vật)"},{"pos":"v.","en":"to develop a good relationship with someone","vi":"gắn kết; tạo dựng mối quan hệ tốt đẹp với ai đó"}],"examples":[{"en":"Connect your phone to the speaker using this cable.","vi":"Hãy kết nối điện thoại của bạn với loa bằng cáp này.","audioKind":"ex"},{"en":"New rail services can connect rural communities with cities, improving access to education and employment.","vi":"Các dịch vụ đường sắt mới có thể kết nối các cộng đồng nông thôn với thành phố, giúp việc tiếp cận giáo dục và việc làm trở nên thuận lợi hơn.","audioKind":"ex2"}],"collocations":[{"en":"connect to the internet","vi":"kết nối với internet"},{"en":"connect A with B","vi":"liên kết A với B"},{"en":"connect with people","vi":"kết nối với mọi người"}],"wordFamily":["connection (n.)","connected (adj.)","connectivity (n.)","disconnect (v.)"],"synonyms":["link","join"],"antonyms":["disconnect"],"tipVi":"Kết nối thiết bị thường dùng cấu trúc connect A to B.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tape-recorder', 'en-a2-26', 'tape-recorder', '/ˈteɪp rɪˌkɔːrdər/', 'A2', 'máy ghi âm bằng băng từ', 'n.', 'tape (n.), record (v.), recorder (n.), recording (n.)', NULL, 'Hiện đại thường viết là tape recorder, không có dấu gạch nối.', 'My grandfather still uses a tape-recorder to record songs.', NULL, 'Ông tôi vẫn dùng máy ghi âm bằng băng từ để ghi lại các bài hát.', '{"wordId":"tape-recorder","ukIpa":"/ˈteɪp rɪˌkɔːdə/","usIpa":"/ˈteɪp rɪˌkɔːrdər/","cefr":"A2","topic":"technology","senses":[{"pos":"n.","en":"A device that records and plays sound using magnetic tape.","vi":"máy ghi âm bằng băng từ"}],"examples":[{"en":"My grandfather still uses a tape-recorder to record songs.","vi":"Ông tôi vẫn dùng máy ghi âm bằng băng từ để ghi lại các bài hát.","audioKind":"ex"},{"en":"Before digital devices became widespread, researchers often used a tape-recorder to preserve interviews for later analysis.","vi":"Trước khi các thiết bị kỹ thuật số trở nên phổ biến, các nhà nghiên cứu thường sử dụng máy ghi âm bằng băng từ để lưu giữ các cuộc phỏng vấn phục vụ cho việc phân tích sau này.","audioKind":"ex2"}],"collocations":[{"en":"a portable tape-recorder","vi":"máy ghi âm di động"},{"en":"a cassette tape-recorder","vi":"máy ghi âm băng cassette"}],"wordFamily":["tape (n.)","record (v.)","recorder (n.)","recording (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Hiện đại thường viết là tape recorder, không có dấu gạch nối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_26_1', 'en-a2-26', 'Cách dùng “program” (n.) — chương trình máy tính', 'computer program  ·  run a program  ·  program a computer', 'Tiếng Anh-Anh dùng program cho chương trình máy tính; programme cho kế hoạch, chương trình truyền hình.', 'Họ từ (Word Family): programmer (n.), programming (n.), programmable (adj.)', '[{"hanzi":"This program helps me organise all my holiday photos.","pinyin":"","meaning":"Chương trình này giúp tôi sắp xếp tất cả các bức ảnh kỳ nghỉ của mình."},{"hanzi":"Schools should teach students how to program computers rather than simply how to use existing software.","pinyin":"","meaning":"Các trường học nên dạy học sinh cách lập trình máy tính thay vì chỉ đơn thuần biết cách sử dụng phần mềm có sẵn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_26_2', 'en-a2-26', 'Cách dùng “click” (v.) — nhấp chuột; chọn một mục trên màn hình', 'click on a link  ·  a mouse click  ·  a sharp click', 'Khi nhấp vào liên kết thường dùng click on; cấu trúc it clicked có thể dùng khi chợt hiểu ra vấn đề.', 'Họ từ (Word Family): clickable (adj.)', '[{"hanzi":"Click on the picture to see a larger version.","pinyin":"","meaning":"Nhấp vào bức ảnh để xem phiên bản lớn hơn."},{"hanzi":"Students should check whether a website is trustworthy before they click on links or share personal information.","pinyin":"","meaning":"Học sinh nên kiểm tra xem một trang web có đáng tin cậy hay không trước khi nhấp vào các liên kết hoặc chia sẻ thông tin cá nhân."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_26_3', 'en-a2-26', 'Cách dùng “equipment” (n.) — thiết bị, dụng cụ, trang thiết bị', 'sports equipment  ·  medical equipment  ·  safety equipment', 'Equipment là danh từ không đếm được; khi chỉ một món thiết bị cụ thể, dùng cụm a piece of equipment.', 'Họ từ (Word Family): equip (v.), equipped (adj.) | Đồng nghĩa: gear', '[{"hanzi":"Please put the camping equipment back in the garage.","pinyin":"","meaning":"Xin hãy cất đồ dùng cắm trại trở lại nhà xe."},{"hanzi":"Schools need suitable laboratory equipment to give students practical experience and encourage an interest in science.","pinyin":"","meaning":"Các trường học cần trang bị thiết bị phòng thí nghiệm phù hợp để mang lại cho học sinh kinh nghiệm thực tế và khơi dậy niềm yêu thích khoa học."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_26_4', 'en-a2-26', 'Cách dùng “file” (n.) — tệp tin; tài liệu lưu trữ', 'save a file  ·  attach a file  ·  file a complaint', 'file a complaint chỉ việc chính thức khiếu nại, không phải là mang đơn khiếu nại đi cất vào hồ sơ.', 'Họ từ (Word Family): filing (n.)', '[{"hanzi":"I saved the file before switching off my laptop.","pinyin":"","meaning":"Tôi đã lưu tệp trước khi tắt máy tính xách tay của mình."},{"hanzi":"Public institutions should store confidential files securely to prevent unauthorized access and protect citizens'' personal information.","pinyin":"","meaning":"Các cơ quan công quyền nên lưu trữ tài liệu mật một cách an toàn để ngăn chặn việc truy cập trái phép và bảo vệ thông tin cá nhân của công dân."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_26_1', 'en-a2-26', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_26_1_1', 'ten_a2_26_1', 'PC', 'My PC takes ages to start on cold mornings.', 'My PC takes ages to start on cold mornings.', '/ˌpiː ˈsiː/', 'Máy tính cá nhân của tôi mất rất lâu để khởi động vào những buổi sáng lạnh trời.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_26_1_2', 'ten_a2_26_1', 'app', 'This app reminds me to water my plants every Sunday.', 'This app reminds me to water my plants every Sunday.', '/æp/', 'Ứng dụng này nhắc tôi tưới cây vào mỗi chủ nhật.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_26_1_3', 'ten_a2_26_1', 'download', 'Download the map before you leave the hotel tomorrow.', 'Download the map before you leave the hotel tomorrow.', '/ˌdaʊnˈloʊd/', 'Hãy tải bản đồ xuống trước khi bạn rời khách sạn vào ngày mai.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_26_1_4', 'ten_a2_26_1', 'program', 'This program helps me organise all my holiday photos.', 'This program helps me organise all my holiday photos.', '/ˈproʊɡræm/', 'Chương trình này giúp tôi sắp xếp tất cả các bức ảnh kỳ nghỉ của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_26_1_5', 'ten_a2_26_1', 'mobile', 'The mobile library visits our village every Friday morning.', 'The mobile library visits our village every Friday morning.', '/ˈmoʊbəl/', 'Thư viện lưu động đến thăm làng chúng tôi vào mỗi sáng thứ Sáu.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_26_1_6', 'ten_a2_26_1', 'wifi', 'The café offers free wifi near the window seats.', 'The café offers free wifi near the window seats.', '/ˈwaɪ faɪ/', 'Quán cà phê có cung cấp wifi miễn phí ở khu vực ghế ngồi gần cửa sổ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_26_1_7', 'ten_a2_26_1', 'file', 'I saved the file before switching off my laptop.', 'I saved the file before switching off my laptop.', '/faɪl/', 'Tôi đã lưu tệp trước khi tắt máy tính xách tay của mình.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_26_1_8', 'ten_a2_26_1', 'selfie', 'We took a selfie beside the lake after our walk.', 'We took a selfie beside the lake after our walk.', '/ˈselfi/', 'Chúng tôi đã chụp một bức ảnh tự chụp bên hồ sau buổi đi dạo.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_26_1_1', 'en-a2-26', 'ten_a2_26_1', 'listening', 'listening', 'My PC takes ages to start on cold mornings.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Phần mềm này giúp tôi chỉnh sửa ảnh trên máy tính xách tay.","Nhấp vào bức ảnh để xem phiên bản lớn hơn.","Chương trình này giúp tôi sắp xếp tất cả các bức ảnh kỳ nghỉ của mình.","Máy tính cá nhân của tôi mất rất lâu để khởi động vào những buổi sáng lạnh trời."]'::jsonb, 3, 'My PC takes ages to start on cold mornings. → Máy tính cá nhân của tôi mất rất lâu để khởi động vào những buổi sáng lạnh trời.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_26_1_2', 'en-a2-26', 'ten_a2_26_1', 'listening', 'listening', 'This app reminds me to water my plants every Sunday.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ứng dụng này nhắc tôi tưới cây vào mỗi chủ nhật.","Tôi dùng điện thoại thông minh để chụp lại bầu trời chiều.","Ông tôi vẫn dùng máy ghi âm bằng băng từ để ghi lại các bài hát.","Hãy tải bản đồ xuống trước khi bạn rời khách sạn vào ngày mai."]'::jsonb, 0, 'This app reminds me to water my plants every Sunday. → Ứng dụng này nhắc tôi tưới cây vào mỗi chủ nhật.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_26_1_3', 'en-a2-26', 'ten_a2_26_1', 'listening', 'listening', 'Download the map before you leave the hotel tomorrow.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã chụp một bức ảnh tự chụp bên hồ sau buổi đi dạo.","Hãy tải bản đồ xuống trước khi bạn rời khách sạn vào ngày mai.","Thư viện lưu động đến thăm làng chúng tôi vào mỗi sáng thứ Sáu.","Nhấp vào bức ảnh để xem phiên bản lớn hơn."]'::jsonb, 1, 'Download the map before you leave the hotel tomorrow. → Hãy tải bản đồ xuống trước khi bạn rời khách sạn vào ngày mai.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_26_2', 'en-a2-26', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_26_2_1', 'ten_a2_26_2', 'PC', 'Providing each student with a PC may improve access to digital resources, but requires substantial funding.', 'Providing each student with a PC may improve access to digital resources, but requires substantial funding.', '/ˌpiː ˈsiː/', 'Việc cung cấp cho mỗi học sinh một chiếc máy tính cá nhân có thể cải thiện khả năng tiếp cận tài nguyên số, nhưng đòi hỏi nguồn kinh phí lớn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_26_2_2', 'ten_a2_26_2', 'app', 'A language learning app can provide affordable practice, although it cannot fully replace interaction with a teacher.', 'A language learning app can provide affordable practice, although it cannot fully replace interaction with a teacher.', '/æp/', 'Một ứng dụng học ngôn ngữ có thể cung cấp các bài tập với chi phí hợp lý, mặc dù nó không thể thay thế hoàn toàn sự tương tác với giáo viên.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_26_2_3', 'ten_a2_26_2', 'download', 'Students can download course materials at home, allowing them to study even when internet access is unavailable.', 'Students can download course materials at home, allowing them to study even when internet access is unavailable.', '/ˌdaʊnˈloʊd/', 'Học sinh có thể tải tài liệu khóa học về nhà, giúp các em học tập ngay cả khi không có kết nối internet.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_26_2_4', 'ten_a2_26_2', 'program', 'Schools should teach students how to program computers rather than simply how to use existing software.', 'Schools should teach students how to program computers rather than simply how to use existing software.', '/ˈproʊɡræm/', 'Các trường học nên dạy học sinh cách lập trình máy tính thay vì chỉ đơn thuần biết cách sử dụng phần mềm có sẵn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_26_2_5', 'ten_a2_26_2', 'mobile', 'Mobile clinics can improve access to basic healthcare for people living in remote rural communities.', 'Mobile clinics can improve access to basic healthcare for people living in remote rural communities.', '/ˈmoʊbəl/', 'Các phòng khám lưu động có thể giúp người dân sống ở các cộng đồng nông thôn vùng sâu vùng xa dễ dàng tiếp cận dịch vụ chăm sóc sức khỏe cơ bản hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_26_2_6', 'ten_a2_26_2', 'wifi', 'Providing reliable public wifi can help residents access essential services and participate in online learning.', 'Providing reliable public wifi can help residents access essential services and participate in online learning.', '/ˈwaɪ faɪ/', 'Cung cấp mạng wifi công cộng ổn định giúp người dân tiếp cận các dịch vụ thiết yếu và tham gia học tập trực tuyến.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
