INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_26_2_2', 'en-a2-26', 'ten_a2_26_2', 'listening', 'listening', 'A language learning app can provide affordable practice, although it cannot fully replace interaction with a teacher.', NULL, 'Trong câu vừa nghe, từ “app” mang nghĩa nào sau đây?', '["chi tiết; tiểu tiết","ứng dụng; chương trình máy tính","khu phố; vùng lân cận","phim hoạt hình"]'::jsonb, 1, '“app” (/æp/): ứng dụng; chương trình máy tính. Câu đầy đủ: A language learning app can provide affordable practice, although it cannot fully replace interaction with a teacher.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
