INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_26_2', 'en-a2-26', NULL, 'comprehensive_test', 'listening', 'This app reminds me to water my plants every Sunday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chiếc máy tính xách tay của tôi vừa khít vào ngăn phía trước của balo.","Ứng dụng này nhắc tôi tưới cây vào mỗi chủ nhật.","Chương trình này giúp tôi sắp xếp tất cả các bức ảnh kỳ nghỉ của mình.","Ông tôi vẫn dùng máy ghi âm bằng băng từ để ghi lại các bài hát."]'::jsonb, 1, 'This app reminds me to water my plants every Sunday. → Ứng dụng này nhắc tôi tưới cây vào mỗi chủ nhật.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_26_3', 'en-a2-26', NULL, 'comprehensive_test', 'listening', 'download', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tải xuống","lối ra; cửa thoát hiểm","Malaysia (một quốc gia Đông Nam Á nằm ở bán đảo Mã Lai và đảo Borneo)","bài phát biểu; bài diễn thuyết"]'::jsonb, 0, 'download (/ˌdaʊnˈloʊd/) → tải xuống; sự tải xuống; tệp tải xuống', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_26_4', 'en-a2-26', NULL, 'comprehensive_test', 'listening', 'This program helps me organise all my holiday photos.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chương trình này giúp tôi sắp xếp tất cả các bức ảnh kỳ nghỉ của mình.","Chiếc máy tính xách tay của tôi vừa khít vào ngăn phía trước của balo.","Tôi tìm thấy một công thức nấu món súp đơn giản trên mạng.","Quán cà phê có cung cấp wifi miễn phí ở khu vực ghế ngồi gần cửa sổ."]'::jsonb, 0, 'This program helps me organise all my holiday photos. → Chương trình này giúp tôi sắp xếp tất cả các bức ảnh kỳ nghỉ của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_26_5', 'en-a2-26', NULL, 'comprehensive_test', 'listening', 'mobile', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["giải quyết; giải đáp","điện; năng lượng điện","dùng với I hoặc we để đề nghị hoặc gợi ý điều gì đó","di động; có thể di chuyển"]'::jsonb, 3, 'mobile (/ˈmoʊbəl/) → di động; có thể di chuyển; thuộc di động (viễn thông); điện thoại di động', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_26_6', 'en-a2-26', NULL, 'comprehensive_test', 'listening', 'The café offers free wifi near the window seats.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Hãy tải bản đồ xuống trước khi bạn rời khách sạn vào ngày mai.","Ông tôi vẫn dùng máy ghi âm bằng băng từ để ghi lại các bài hát.","Tôi tìm thấy một công thức nấu món súp đơn giản trên mạng.","Quán cà phê có cung cấp wifi miễn phí ở khu vực ghế ngồi gần cửa sổ."]'::jsonb, 3, 'The café offers free wifi near the window seats. → Quán cà phê có cung cấp wifi miễn phí ở khu vực ghế ngồi gần cửa sổ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_26_7', 'en-a2-26', NULL, 'comprehensive_test', 'listening', 'file', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thường xuyên; thông thường; trong hầu hết các trường hợp","tệp tin; tài liệu lưu trữ","bạc (kim loại quý)","bừa bộn; không ngăn nắp"]'::jsonb, 1, 'file (/faɪl/) → tệp tin; tài liệu lưu trữ; lưu trữ hồ sơ; nộp đơn; cái giũa', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_26_8', 'en-a2-26', NULL, 'comprehensive_test', 'listening', 'We took a selfie beside the lake after our walk.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Ông tôi vẫn dùng máy ghi âm bằng băng từ để ghi lại các bài hát.","Chúng tôi đã chụp một bức ảnh tự chụp bên hồ sau buổi đi dạo.","Hãy kết nối điện thoại của bạn với loa bằng cáp này.","Hãy tải bản đồ xuống trước khi bạn rời khách sạn vào ngày mai."]'::jsonb, 1, 'We took a selfie beside the lake after our walk. → Chúng tôi đã chụp một bức ảnh tự chụp bên hồ sau buổi đi dạo.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
