INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_26_18', 'en-a2-26', NULL, 'comprehensive_test', 'reading', NULL, 'Providing each student with a PC may improve access to digital resources, but requires substantial funding.', 'Dựa vào câu trên, từ “PC” có nghĩa phù hợp nhất là gì?', '["hàng tuần, diễn ra mỗi tuần","máy tính cá nhân","chi tiết; tiểu tiết","năng động; tích cực tham gia"]'::jsonb, 1, 'PC: máy tính cá nhân. Dịch cả câu: Việc cung cấp cho mỗi học sinh một chiếc máy tính cá nhân có thể cải thiện khả năng tiếp cận tài nguyên số, nhưng đòi hỏi nguồn kinh phí lớn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_26_19', 'en-a2-26', NULL, 'comprehensive_test', 'reading', NULL, 'A language learning app can provide affordable practice, although it cannot fully replace interaction with a teacher.', 'Dựa vào câu trên, từ “app” có nghĩa phù hợp nhất là gì?', '["xe tải; xe vận tải lớn","ứng dụng; chương trình máy tính","thuộc về xã hội","tiệc nướng ngoài trời"]'::jsonb, 1, 'app: ứng dụng; chương trình máy tính. Dịch cả câu: Một ứng dụng học ngôn ngữ có thể cung cấp các bài tập với chi phí hợp lý, mặc dù nó không thể thay thế hoàn toàn sự tương tác với giáo viên.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_26_20', 'en-a2-26', NULL, 'comprehensive_test', 'reading', NULL, 'Students can download course materials at home, allowing them to study even when internet access is unavailable.', 'Dựa vào câu trên, từ “download” có nghĩa phù hợp nhất là gì?', '["quê hương, thị trấn hoặc thành phố nơi lớn lên hoặc xuất thân","chủ động đề nghị; đề ra","bữa tối; bữa ăn nhẹ trước khi đi ngủ","tải xuống"]'::jsonb, 3, 'download: tải xuống; sự tải xuống; tệp tải xuống. Dịch cả câu: Học sinh có thể tải tài liệu khóa học về nhà, giúp các em học tập ngay cả khi không có kết nối internet.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_26_21', 'en-a2-26', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should teach students how to program computers rather than simply how to use existing software.', 'Dựa vào câu trên, từ “program” có nghĩa phù hợp nhất là gì?', '["có thể; có lẽ","chương trình máy tính","Thượng Đế; Chúa; vị thần tối cao","sân; khu đất quanh nhà (thường có rào chắn)"]'::jsonb, 1, 'program: chương trình máy tính; lập trình; cài đặt chương trình; chương trình; kế hoạch; lịch trình. Dịch cả câu: Các trường học nên dạy học sinh cách lập trình máy tính thay vì chỉ đơn thuần biết cách sử dụng phần mềm có sẵn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_26_22', 'en-a2-26', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “máy tính xách tay; máy tính xách tay cá nhân”', '["blood","naughty","laptop","passport"]'::jsonb, 2, 'máy tính xách tay; máy tính xách tay cá nhân → laptop (/ˈlæptɑːp/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_26_23', 'en-a2-26', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “kết nối; nối liền; cắm (thiết bị điện tử)”', '["project","connect","Korean","education"]'::jsonb, 1, 'kết nối; nối liền; cắm (thiết bị điện tử) → connect (/kəˈnekt/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_26_24', 'en-a2-26', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “máy ghi âm bằng băng từ”', '["tape-recorder","lift","knock","runner"]'::jsonb, 0, 'máy ghi âm bằng băng từ → tape-recorder (/ˈteɪp rɪˌkɔːrdər/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-27', 'en', 'Bài 27: Khoa học & Nghiên cứu - CEFR A2', 'CEFR A2', 'A2 · Khoa học', '15 từ vựng Tiếng Anh CEFR A2 chủ đề khoa học & nghiên cứu kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2027, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_model', 'en-a2-27', 'model', '/ˈmɑːdəl/', 'A2', 'mô hình; mẫu; tấm gương; khuôn mẫu; người mẫu', 'n.', 'modelling (n.), modeller (n.)', NULL, 'Từ model còn có thể dùng làm động từ, chỉ hành động làm mô hình hoặc làm người mẫu.', 'He built a model of a bridge from cardboard.', NULL, 'Cậu ấy làm một mô hình cây cầu bằng bìa cứng.', '{"wordId":"model","ukIpa":"/ˈmɒdəl/","usIpa":"/ˈmɑːdəl/","cefr":"A2","topic":"science","senses":[{"pos":"n.","en":"a representation showing how something looks, works, or is organised","vi":"mô hình; mẫu"},{"pos":"n.","en":"someone or something that provides a good example to follow","vi":"tấm gương; khuôn mẫu"},{"pos":"n.","en":"a person who displays clothes or poses for artists","vi":"người mẫu"}],"examples":[{"en":"He built a model of a bridge from cardboard.","vi":"Cậu ấy làm một mô hình cây cầu bằng bìa cứng.","audioKind":"ex"},{"en":"Researchers use a computer model to predict how rising temperatures may affect regional water supplies.","vi":"Các nhà nghiên cứu sử dụng một mô hình máy tính để dự đoán nhiệt độ tăng cao có thể ảnh hưởng như thế nào đến nguồn nước khu vực.","audioKind":"ex2"}],"collocations":[{"en":"scale model","vi":"mô hình tỉ lệ"},{"en":"computer model","vi":"mô hình máy tính"},{"en":"role model","vi":"tấm gương sáng"},{"en":"fashion model","vi":"người mẫu thời trang"}],"wordFamily":["modelling (n.)","modeller (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ model còn có thể dùng làm động từ, chỉ hành động làm mô hình hoặc làm người mẫu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_discover', 'en-a2-27', 'discover', '/dɪˈskʌvər/', 'A2', 'phát hiện; tìm ra', 'v.', 'discovery (n.), discoverer (n.)', 'Đồng nghĩa: find, uncover', 'Discover là tìm ra thứ đã có sẵn trong tự nhiên; còn invent là sáng chế ra thứ hoàn toàn mới.', 'We discovered a quiet beach behind the cliffs.', NULL, 'Chúng tôi đã phát hiện ra một bãi biển yên tĩnh nằm khuất sau những vách đá.', '{"wordId":"discover","ukIpa":"/dɪˈskʌvə/","usIpa":"/dɪˈskʌvər/","cefr":"A2","topic":"science","senses":[{"pos":"v.","en":"to find something or learn something previously unknown","vi":"phát hiện; tìm ra"}],"examples":[{"en":"We discovered a quiet beach behind the cliffs.","vi":"Chúng tôi đã phát hiện ra một bãi biển yên tĩnh nằm khuất sau những vách đá.","audioKind":"ex"},{"en":"Scientists may discover new ways to treat diseases by studying plants in tropical forests.","vi":"Các nhà khoa học có thể khám phá ra những phương pháp điều trị bệnh mới thông qua việc nghiên cứu thực vật trong các khu rừng nhiệt đới.","audioKind":"ex2"}],"collocations":[{"en":"discover a cure","vi":"tìm ra phương pháp chữa trị"},{"en":"discover a new species","vi":"phát hiện loài mới"},{"en":"discover the truth","vi":"khám phá sự thật"}],"wordFamily":["discovery (n.)","discoverer (n.)"],"synonyms":["find","uncover"],"antonyms":[],"tipVi":"Discover là tìm ra thứ đã có sẵn trong tự nhiên; còn invent là sáng chế ra thứ hoàn toàn mới.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_centimetre', 'en-a2-27', 'centimetre', '/ˈsentəmiːtər/', 'A2', 'xentimét; centimet', 'n.', NULL, NULL, 'Cách viết tiếng Anh-Anh là "centimetre", tiếng Anh-Mỹ là "centimeter"; viết tắt là "cm".', 'This little plant grew one centimetre in a week.', NULL, 'Cây nhỏ này đã cao thêm một xentimét trong vòng một tuần.', '{"wordId":"centimetre","ukIpa":"/ˈsentɪmiːtə/","usIpa":"/ˈsentəmiːtər/","cefr":"A2","topic":"science","senses":[{"pos":"n.","en":"A unit of length equal to one hundredth of a metre.","vi":"xentimét; centimet"}],"examples":[{"en":"This little plant grew one centimetre in a week.","vi":"Cây nhỏ này đã cao thêm một xentimét trong vòng một tuần.","audioKind":"ex"},{"en":"Even a small rise in sea level, measured in centimetres, can increase flooding risks in coastal communities.","vi":"Ngay cả một mực nước biển dâng lên nhỏ, tính bằng xentimét, cũng có thể làm tăng nguy cơ ngập lụt ở các cộng đồng ven biển.","audioKind":"ex2"}],"collocations":[{"en":"a centimetre long","vi":"dài một xentimét"},{"en":"square centimetre","vi":"xentimét vuông"},{"en":"cubic centimetre","vi":"xentimét khối"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cách viết tiếng Anh-Anh là \"centimetre\", tiếng Anh-Mỹ là \"centimeter\"; viết tắt là \"cm\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_biology', 'en-a2-27', 'biology', '/baɪˈɑːlədʒi/', 'A2', 'sinh học; đặc điểm sinh học; cơ chế sinh lý', 'n.', 'biological (adj.), biologically (adv.), biologist (n.)', NULL, 'Tên môn học thường không đếm được; nhà sinh học là "biologist".', 'We examined onion cells under microscopes in biology today.', NULL, 'Chúng tôi đã quan sát các tế bào hành tây dưới kính hiển vi trong giờ sinh học ngày hôm nay.', '{"wordId":"biology","ukIpa":"/baɪˈɒlədʒi/","usIpa":"/baɪˈɑːlədʒi/","cefr":"A2","topic":"science","senses":[{"pos":"n.","en":"the scientific study of living things","vi":"sinh học"},{"pos":"n.","en":"the natural processes and characteristics of a living thing","vi":"đặc điểm sinh học; cơ chế sinh lý"}],"examples":[{"en":"We examined onion cells under microscopes in biology today.","vi":"Chúng tôi đã quan sát các tế bào hành tây dưới kính hiển vi trong giờ sinh học ngày hôm nay.","audioKind":"ex"},{"en":"A basic understanding of biology helps people evaluate health information and make informed decisions about their lifestyles.","vi":"Hiểu biết cơ bản về sinh học giúp mọi người đánh giá các thông tin sức khỏe và đưa ra các quyết định sáng suốt về lối sống của mình.","audioKind":"ex2"}],"collocations":[{"en":"study biology","vi":"học sinh học"},{"en":"marine biology","vi":"sinh học biển"},{"en":"human biology","vi":"sinh học con người"},{"en":"molecular biology","vi":"sinh học phân tử"}],"wordFamily":["biological (adj.)","biologically (adv.)","biologist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên môn học thường không đếm được; nhà sinh học là \"biologist\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_electricity', 'en-a2-27', 'electricity', '/ɪˌlekˈtrɪsəti/', 'A2', 'điện; năng lượng điện', 'n.', 'electric (adj.), electrical (adj.), electrician (n.), electrify (v.)', 'Đồng nghĩa: electric power', 'electricity là danh từ không đếm được; electric thường chỉ thiết bị dùng điện, electrical chỉ các vấn đề liên quan đến điện.', 'The storm cut off electricity to our entire street.', NULL, 'Cơn bão đã làm mất điện toàn bộ con phố của chúng tôi.', '{"wordId":"electricity","ukIpa":"/ɪˌlekˈtrɪsəti/","usIpa":"/ɪˌlekˈtrɪsəti/","cefr":"A2","topic":"science","senses":[{"pos":"n.","en":"Energy carried by charged particles, used to power devices","vi":"điện; năng lượng điện"}],"examples":[{"en":"The storm cut off electricity to our entire street.","vi":"Cơn bão đã làm mất điện toàn bộ con phố của chúng tôi.","audioKind":"ex"},{"en":"Generating electricity from renewable sources can reduce dependence on fossil fuels and lower greenhouse gas emissions.","vi":"Sản xuất điện từ các nguồn năng lượng tái tạo có thể giảm sự phụ thuộc vào nhiên liệu hóa thạch và cắt giảm lượng khí thải nhà kính.","audioKind":"ex2"}],"collocations":[{"en":"generate electricity","vi":"sản xuất điện"},{"en":"electricity supply","vi":"cung cấp điện"},{"en":"an electricity bill","vi":"hóa đơn tiền điện"},{"en":"save electricity","vi":"tiết kiệm điện"}],"wordFamily":["electric (adj.)","electrical (adj.)","electrician (n.)","electrify (v.)"],"synonyms":["electric power"],"antonyms":[],"tipVi":"electricity là danh từ không đếm được; electric thường chỉ thiết bị dùng điện, electrical chỉ các vấn đề liên quan đến điện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lab', 'en-a2-27', 'lab', '/læb/', 'A2', 'phòng thí nghiệm; phòng nghiên cứu', 'n.', 'laboratory (n.)', 'Đồng nghĩa: laboratory', 'lab là từ viết tắt phổ biến của laboratory, cả hai đều là danh từ đếm được.', 'We wore safety goggles while mixing liquids in the lab.', NULL, 'Chúng tôi đeo kính bảo hộ khi pha trộn các chất lỏng trong phòng thí nghiệm.', '{"wordId":"lab","ukIpa":"/læb/","usIpa":"/læb/","cefr":"A2","topic":"science","senses":[{"pos":"n.","en":"A room or building equipped for scientific experiments and tests","vi":"phòng thí nghiệm; phòng nghiên cứu"}],"examples":[{"en":"We wore safety goggles while mixing liquids in the lab.","vi":"Chúng tôi đeo kính bảo hộ khi pha trộn các chất lỏng trong phòng thí nghiệm.","audioKind":"ex"},{"en":"A well-equipped school lab allows students to test scientific ideas through practical experiments rather than memorisation alone.","vi":"Một phòng thí nghiệm học đường được trang bị đầy đủ giúp học sinh kiểm chứng các quan điểm khoa học thông qua thực nghiệm thực tế thay vì chỉ học vẹt.","audioKind":"ex2"}],"collocations":[{"en":"research lab","vi":"phòng nghiên cứu"},{"en":"science lab","vi":"phòng thí nghiệm khoa học"},{"en":"lab equipment","vi":"thiết bị phòng thí nghiệm"},{"en":"lab technician","vi":"kỹ thuật viên phòng thí nghiệm"}],"wordFamily":["laboratory (n.)"],"synonyms":["laboratory"],"antonyms":[],"tipVi":"lab là từ viết tắt phổ biến của laboratory, cả hai đều là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_physics', 'en-a2-27', 'physics', '/ˈfɪzɪks/', 'A2', 'vật lý học', 'n.', 'physicist (n.), physical (adj.)', NULL, 'Mặc dù tận cùng bằng chữ s, từ này vẫn là danh từ không đếm được và đi với động từ số ít.', 'Our physics teacher showed us how magnets attract iron.', NULL, 'Giáo viên vật lý của chúng tôi đã cho chúng tôi thấy nam châm hút sắt như thế nào.', '{"wordId":"physics","ukIpa":"/ˈfɪzɪks/","usIpa":"/ˈfɪzɪks/","cefr":"A2","topic":"science","senses":[{"pos":"n.","en":"the science of matter, energy, forces, and their interactions","vi":"vật lý học"}],"examples":[{"en":"Our physics teacher showed us how magnets attract iron.","vi":"Giáo viên vật lý của chúng tôi đã cho chúng tôi thấy nam châm hút sắt như thế nào.","audioKind":"ex"},{"en":"A strong understanding of physics can help engineers develop safer buildings and more efficient transport systems.","vi":"Hiểu sâu sắc về vật lý học có thể giúp các kỹ sư thiết kế những tòa nhà an toàn hơn và hệ thống giao thông hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"study physics","vi":"học môn vật lý"},{"en":"the laws of physics","vi":"các định luật vật lý"},{"en":"nuclear physics","vi":"vật lý hạt nhân"}],"wordFamily":["physicist (n.)","physical (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Mặc dù tận cùng bằng chữ s, từ này vẫn là danh từ không đếm được và đi với động từ số ít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_moon', 'en-a2-27', 'moon', '/muːn/', 'A2', 'mặt trăng; vệ tinh tự nhiên', 'n.', 'moonlight (n.), moonlit (adj.)', NULL, 'Chỉ mặt trăng của Trái Đất thường dùng the moon; vệ tinh tự nhiên của các hành tinh khác là danh từ đếm được.', 'The moon rose slowly above the trees behind our house.', NULL, 'Mặt trăng từ từ nhô lên phía trên những rặng cây đằng sau ngôi nhà chúng tôi.', '{"wordId":"moon","ukIpa":"/muːn/","usIpa":"/muːn/","cefr":"A2","topic":"science","senses":[{"pos":"n.","en":"the natural object that moves around Earth","vi":"mặt trăng"},{"pos":"n.","en":"a natural object that moves around a planet","vi":"vệ tinh tự nhiên"}],"examples":[{"en":"The moon rose slowly above the trees behind our house.","vi":"Mặt trăng từ từ nhô lên phía trên những rặng cây đằng sau ngôi nhà chúng tôi.","audioKind":"ex"},{"en":"Research on the moon may help scientists understand how Earth and other rocky planets formed.","vi":"Nghiên cứu về mặt trăng có thể giúp các nhà khoa học hiểu được Trái Đất và các hành tinh đá khác được hình thành như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"full moon","vi":"trăng tròn"},{"en":"crescent moon","vi":"trăng lưỡi liềm"},{"en":"the surface of the moon","vi":"bề mặt mặt trăng"}],"wordFamily":["moonlight (n.)","moonlit (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ mặt trăng của Trái Đất thường dùng the moon; vệ tinh tự nhiên của các hành tinh khác là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_metal', 'en-a2-27', 'metal', '/ˈmetl/', 'A2', 'kim loại', 'n.', 'metallic (adj.)', NULL, 'Khi chỉ chất liệu chung chung thì "metal" không đếm được; khi chỉ các loại kim loại cụ thể thì có thể đếm được.', 'The metal handle felt cold against my fingers.', NULL, 'Tay cầm bằng kim loại chạm vào ngón tay mang cảm giác lạnh ngắt.', '{"wordId":"metal","ukIpa":"/ˈmetl/","usIpa":"/ˈmetl/","cefr":"A2","topic":"science","senses":[{"pos":"n.","en":"a usually hard, shiny material that conducts heat and electricity","vi":"kim loại"}],"examples":[{"en":"The metal handle felt cold against my fingers.","vi":"Tay cầm bằng kim loại chạm vào ngón tay mang cảm giác lạnh ngắt.","audioKind":"ex"},{"en":"Recycling metal reduces the demand for mining and can significantly lower energy consumption in manufacturing.","vi":"Việc tái chế kim loại giúp giảm thiểu nhu cầu khai thác mỏ và có thể làm giảm đáng kể mức tiêu thụ năng lượng trong quá trình sản xuất.","audioKind":"ex2"}],"collocations":[{"en":"scrap metal","vi":"phế liệu kim loại"},{"en":"precious metal","vi":"kim loại quý"},{"en":"metal frame","vi":"khung kim loại"},{"en":"heavy metal","vi":"kim loại nặng"}],"wordFamily":["metallic (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ chất liệu chung chung thì \"metal\" không đếm được; khi chỉ các loại kim loại cụ thể thì có thể đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_temperature', 'en-a2-27', 'temperature', '/ˈtemprətʃər/', 'A2', 'nhiệt độ; khí hậu; thân nhiệt; sự phát sốt; cơn sốt', 'n.', NULL, NULL, 'have a temperature thường mang nghĩa là bị sốt, chứ không chỉ đơn thuần là có thân nhiệt.', 'The temperature dropped sharply after the sun went down.', NULL, 'Nhiệt độ giảm xuống đột ngột sau khi mặt trời lặn.', '{"wordId":"temperature","ukIpa":"/ˈtemprətʃə/","usIpa":"/ˈtemprətʃər/","cefr":"A2","topic":"science","senses":[{"pos":"n.","en":"A measure of how hot or cold something is.","vi":"nhiệt độ; khí hậu; thân nhiệt"},{"pos":"n.","en":"A body temperature higher than normal because of illness.","vi":"sự phát sốt; cơn sốt"}],"examples":[{"en":"The temperature dropped sharply after the sun went down.","vi":"Nhiệt độ giảm xuống đột ngột sau khi mặt trời lặn.","audioKind":"ex"},{"en":"Rising ocean temperatures can damage coral reefs and threaten the survival of many marine species.","vi":"Nhiệt độ đại dương tăng cao có thể tàn phá các rạn san hô và đe dọa sự sống còn của nhiều loài sinh vật biển.","audioKind":"ex2"}],"collocations":[{"en":"room temperature","vi":"nhiệt độ phòng"},{"en":"body temperature","vi":"thân nhiệt"},{"en":"take someone''s temperature","vi":"đo nhiệt độ cho ai đó"},{"en":"have a temperature","vi":"bị sốt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"have a temperature thường mang nghĩa là bị sốt, chứ không chỉ đơn thuần là có thân nhiệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gramme', 'en-a2-27', 'gramme', '/ɡræm/', 'A2', 'gam', 'n.', 'gram (n.), kilogramme (n.), milligramme (n.)', 'Đồng nghĩa: gram', 'gramme là cách viết theo Anh-Anh; gram phổ biến hơn, ký hiệu đơn vị là g.', 'Add one gramme of salt to the soup.', NULL, 'Cho thêm một gam muối vào nồi súp.', '{"wordId":"gramme","ukIpa":"/ɡræm/","usIpa":"/ɡræm/","cefr":"A2","topic":"science","senses":[{"pos":"n.","en":"a unit of mass equal to one thousandth of a kilogram","vi":"gam"}],"examples":[{"en":"Add one gramme of salt to the soup.","vi":"Cho thêm một gam muối vào nồi súp.","audioKind":"ex"},{"en":"Even a single gramme of certain pollutants can harm aquatic life when released into a small pond.","vi":"Thậm chí chỉ một gam của một số chất ô nhiễm cũng có thể gây hại cho sinh vật dưới nước khi xả thải vào một cái ao nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"a gramme of salt","vi":"một gam muối"},{"en":"per gramme","vi":"mỗi gam"},{"en":"weigh in grammes","vi":"tính trọng lượng bằng gam"}],"wordFamily":["gram (n.)","kilogramme (n.)","milligramme (n.)"],"synonyms":["gram"],"antonyms":[],"tipVi":"gramme là cách viết theo Anh-Anh; gram phổ biến hơn, ký hiệu đơn vị là g.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chemistry', 'en-a2-27', 'chemistry', '/ˈkemɪstri/', 'A2', 'hóa học; thành phần hóa học; đặc tính hóa học; sự tâm đầu ý hợp; sự thu hút lẫn nhau', 'n.', 'chemical (adj.), chemist (n.), chemically (adv.)', NULL, 'Tên môn học thường không đếm được: study chemistry, không dùng a.', 'We mixed two clear liquids in chemistry class today.', NULL, 'Hôm nay chúng tôi đã trộn hai chất lỏng trong suốt trong giờ hóa học.', '{"wordId":"chemistry","ukIpa":"/ˈkemɪstri/","usIpa":"/ˈkemɪstri/","cefr":"A2","topic":"science","senses":[{"pos":"n.","en":"the science of substances and how they react","vi":"hóa học"},{"pos":"n.","en":"the chemical properties and processes of a substance","vi":"thành phần hóa học; đặc tính hóa học"},{"pos":"n.","en":"a natural connection or attraction between people","vi":"sự tâm đầu ý hợp; sự thu hút lẫn nhau"}],"examples":[{"en":"We mixed two clear liquids in chemistry class today.","vi":"Hôm nay chúng tôi đã trộn hai chất lỏng trong suốt trong giờ hóa học.","audioKind":"ex"},{"en":"Understanding the chemistry of seawater helps scientists explain how rising carbon emissions affect marine life.","vi":"Hiểu rõ hóa học của nước biển giúp các lượng gia thích cách lượng khí thải carbon tăng cao ảnh hưởng đến đời sống sinh vật biển.","audioKind":"ex2"}],"collocations":[{"en":"organic chemistry","vi":"hóa học hữu cơ"},{"en":"study chemistry","vi":"học hóa học"},{"en":"soil chemistry","vi":"hóa học đất"}],"wordFamily":["chemical (adj.)","chemist (n.)","chemically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Tên môn học thường không đếm được: study chemistry, không dùng a.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_planet', 'en-a2-27', 'planet', '/ˈplænɪt/', 'A2', 'hành tinh', 'n.', 'planetary (adj.)', NULL, 'planet chỉ hành tinh, star chỉ ngôi sao; the planet thường được dùng để chỉ Trái Đất.', 'We watched a bright planet through the telescope tonight.', NULL, 'Đêm nay chúng tôi đã ngắm nhìn một hành tinh sáng rực qua ống kính viễn vọng.', '{"wordId":"planet","ukIpa":"/ˈplænɪt/","usIpa":"/ˈplænɪt/","cefr":"A2","topic":"science","senses":[{"pos":"n.","en":"A large round object that travels around a star.","vi":"hành tinh"}],"examples":[{"en":"We watched a bright planet through the telescope tonight.","vi":"Đêm nay chúng tôi đã ngắm nhìn một hành tinh sáng rực qua ống kính viễn vọng.","audioKind":"ex"},{"en":"Scientists study distant planets to understand whether conditions suitable for life exist beyond Earth.","vi":"Các nhà khoa học nghiên cứu những hành tinh xa xôi để tìm hiểu xem liệu có điều kiện thích hợp cho sự sống tồn tại ngoài Trái Đất hay không.","audioKind":"ex2"}],"collocations":[{"en":"a distant planet","vi":"một hành tinh xa xôi"},{"en":"orbit a planet","vi":"quay quanh một hành tinh"},{"en":"protect the planet","vi":"bảo vệ hành tinh"}],"wordFamily":["planetary (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"planet chỉ hành tinh, star chỉ ngôi sao; the planet thường được dùng để chỉ Trái Đất.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scientist', 'en-a2-27', 'scientist', '/ˈsaɪəntɪst/', 'A2', 'nhà khoa học', 'n.', 'science (n.), scientific (adj.), scientifically (adv.)', NULL, 'scientist chỉ con người, science là khoa học, scientific là tính từ.', 'The scientist examined a drop of water under the microscope.', NULL, 'Nhà khoa học đã soi một giọt nước dưới kính hiển vi.', '{"wordId":"scientist","ukIpa":"/ˈsaɪəntɪst/","usIpa":"/ˈsaɪəntɪst/","cefr":"A2","topic":"science","senses":[{"pos":"n.","en":"Someone who studies the natural world through research and experiments","vi":"nhà khoa học"}],"examples":[{"en":"The scientist examined a drop of water under the microscope.","vi":"Nhà khoa học đã soi một giọt nước dưới kính hiển vi.","audioKind":"ex"},{"en":"Scientists are developing more efficient batteries to support the transition from fossil fuels to renewable energy.","vi":"Các nhà khoa học đang phát triển các loại pin hiệu quả hơn để hỗ trợ quá trình chuyển đổi từ nhiên liệu hóa thạch sang năng lượng tái tạo.","audioKind":"ex2"}],"collocations":[{"en":"research scientist","vi":"nhà nghiên cứu khoa học"},{"en":"leading scientist","vi":"nhà khoa học hàng đầu"},{"en":"environmental scientist","vi":"nhà khoa học môi trường"}],"wordFamily":["science (n.)","scientific (adj.)","scientifically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"scientist chỉ con người, science là khoa học, scientific là tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gas', 'en-a2-27', 'gas', '/ɡæs/', 'A2', 'chất khí; thể khí; khí đốt; nhiên liệu khí; xăng (tiếng Anh Mỹ)', 'n.', 'gaseous (adj.)', NULL, 'Chỉ chung các loại chất khí thường không đếm được; nhiều loại khí dùng gases.', 'We use gas to cook our meals at home.', NULL, 'Chúng tôi sử dụng khí đốt để nấu ăn ở nhà.', '{"wordId":"gas","ukIpa":"/ɡæs/","usIpa":"/ɡæs/","cefr":"A2","topic":"science","senses":[{"pos":"n.","en":"A substance that spreads freely to fill its container.","vi":"chất khí; thể khí"},{"pos":"n.","en":"Gas used as fuel for heating or cooking.","vi":"khí đốt; nhiên liệu khí"},{"pos":"n.","en":"Petrol used to power vehicles, in American English.","vi":"xăng (tiếng Anh Mỹ)"}],"examples":[{"en":"We use gas to cook our meals at home.","vi":"Chúng tôi sử dụng khí đốt để nấu ăn ở nhà.","audioKind":"ex"},{"en":"Reducing greenhouse gas emissions requires investment in cleaner energy and more efficient public transport systems.","vi":"Việc giảm lượng phát thải khí nhà kính đòi hỏi phải đầu tư vào năng lượng sạch hơn và hệ thống giao thông công cộng hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"greenhouse gas","vi":"khí nhà kính"},{"en":"natural gas","vi":"khí tự nhiên"},{"en":"a gas leak","vi":"sự rò rỉ khí đốt"},{"en":"a gas station","vi":"trạm xăng"}],"wordFamily":["gaseous (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ chung các loại chất khí thường không đếm được; nhiều loại khí dùng gases.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_27_1', 'en-a2-27', 'Cách dùng “electricity” (n.) — điện; năng lượng điện', 'generate electricity  ·  electricity supply  ·  an electricity bill', 'electricity là danh từ không đếm được; electric thường chỉ thiết bị dùng điện, electrical chỉ các vấn đề liên quan đến điện.', 'Họ từ (Word Family): electric (adj.), electrical (adj.), electrician (n.), electrify (v.) | Đồng nghĩa: electric power', '[{"hanzi":"The storm cut off electricity to our entire street.","pinyin":"","meaning":"Cơn bão đã làm mất điện toàn bộ con phố của chúng tôi."},{"hanzi":"Generating electricity from renewable sources can reduce dependence on fossil fuels and lower greenhouse gas emissions.","pinyin":"","meaning":"Sản xuất điện từ các nguồn năng lượng tái tạo có thể giảm sự phụ thuộc vào nhiên liệu hóa thạch và cắt giảm lượng khí thải nhà kính."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_27_2', 'en-a2-27', 'Cách dùng “metal” (n.) — kim loại', 'scrap metal  ·  precious metal  ·  metal frame', 'Khi chỉ chất liệu chung chung thì "metal" không đếm được; khi chỉ các loại kim loại cụ thể thì có thể đếm được.', 'Họ từ (Word Family): metallic (adj.)', '[{"hanzi":"The metal handle felt cold against my fingers.","pinyin":"","meaning":"Tay cầm bằng kim loại chạm vào ngón tay mang cảm giác lạnh ngắt."},{"hanzi":"Recycling metal reduces the demand for mining and can significantly lower energy consumption in manufacturing.","pinyin":"","meaning":"Việc tái chế kim loại giúp giảm thiểu nhu cầu khai thác mỏ và có thể làm giảm đáng kể mức tiêu thụ năng lượng trong quá trình sản xuất."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_27_3', 'en-a2-27', 'Cách dùng “moon” (n.) — mặt trăng', 'full moon  ·  crescent moon  ·  the surface of the moon', 'Chỉ mặt trăng của Trái Đất thường dùng the moon; vệ tinh tự nhiên của các hành tinh khác là danh từ đếm được.', 'Họ từ (Word Family): moonlight (n.), moonlit (adj.)', '[{"hanzi":"The moon rose slowly above the trees behind our house.","pinyin":"","meaning":"Mặt trăng từ từ nhô lên phía trên những rặng cây đằng sau ngôi nhà chúng tôi."},{"hanzi":"Research on the moon may help scientists understand how Earth and other rocky planets formed.","pinyin":"","meaning":"Nghiên cứu về mặt trăng có thể giúp các nhà khoa học hiểu được Trái Đất và các hành tinh đá khác được hình thành như thế nào."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_27_4', 'en-a2-27', 'Cách dùng “discover” (v.) — phát hiện; tìm ra', 'discover a cure  ·  discover a new species  ·  discover the truth', 'Discover là tìm ra thứ đã có sẵn trong tự nhiên; còn invent là sáng chế ra thứ hoàn toàn mới.', 'Họ từ (Word Family): discovery (n.), discoverer (n.) | Đồng nghĩa: find, uncover', '[{"hanzi":"We discovered a quiet beach behind the cliffs.","pinyin":"","meaning":"Chúng tôi đã phát hiện ra một bãi biển yên tĩnh nằm khuất sau những vách đá."},{"hanzi":"Scientists may discover new ways to treat diseases by studying plants in tropical forests.","pinyin":"","meaning":"Các nhà khoa học có thể khám phá ra những phương pháp điều trị bệnh mới thông qua việc nghiên cứu thực vật trong các khu rừng nhiệt đới."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_27_1', 'en-a2-27', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_27_1_1', 'ten_a2_27_1', 'model', 'He built a model of a bridge from cardboard.', 'He built a model of a bridge from cardboard.', '/ˈmɑːdəl/', 'Cậu ấy làm một mô hình cây cầu bằng bìa cứng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_27_1_2', 'ten_a2_27_1', 'discover', 'We discovered a quiet beach behind the cliffs.', 'We discovered a quiet beach behind the cliffs.', '/dɪˈskʌvər/', 'Chúng tôi đã phát hiện ra một bãi biển yên tĩnh nằm khuất sau những vách đá.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_27_1_3', 'ten_a2_27_1', 'centimetre', 'This little plant grew one centimetre in a week.', 'This little plant grew one centimetre in a week.', '/ˈsentəmiːtər/', 'Cây nhỏ này đã cao thêm một xentimét trong vòng một tuần.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_27_1_4', 'ten_a2_27_1', 'biology', 'We examined onion cells under microscopes in biology today.', 'We examined onion cells under microscopes in biology today.', '/baɪˈɑːlədʒi/', 'Chúng tôi đã quan sát các tế bào hành tây dưới kính hiển vi trong giờ sinh học ngày hôm nay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_27_1_5', 'ten_a2_27_1', 'electricity', 'The storm cut off electricity to our entire street.', 'The storm cut off electricity to our entire street.', '/ɪˌlekˈtrɪsəti/', 'Cơn bão đã làm mất điện toàn bộ con phố của chúng tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_27_1_6', 'ten_a2_27_1', 'lab', 'We wore safety goggles while mixing liquids in the lab.', 'We wore safety goggles while mixing liquids in the lab.', '/læb/', 'Chúng tôi đeo kính bảo hộ khi pha trộn các chất lỏng trong phòng thí nghiệm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_27_1_7', 'ten_a2_27_1', 'physics', 'Our physics teacher showed us how magnets attract iron.', 'Our physics teacher showed us how magnets attract iron.', '/ˈfɪzɪks/', 'Giáo viên vật lý của chúng tôi đã cho chúng tôi thấy nam châm hút sắt như thế nào.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_27_1_8', 'ten_a2_27_1', 'moon', 'The moon rose slowly above the trees behind our house.', 'The moon rose slowly above the trees behind our house.', '/muːn/', 'Mặt trăng từ từ nhô lên phía trên những rặng cây đằng sau ngôi nhà chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_27_1_1', 'en-a2-27', 'ten_a2_27_1', 'listening', 'listening', 'He built a model of a bridge from cardboard.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cơn bão đã làm mất điện toàn bộ con phố của chúng tôi.","Cậu ấy làm một mô hình cây cầu bằng bìa cứng.","Cho thêm một gam muối vào nồi súp.","Giáo viên vật lý của chúng tôi đã cho chúng tôi thấy nam châm hút sắt như thế nào."]'::jsonb, 1, 'He built a model of a bridge from cardboard. → Cậu ấy làm một mô hình cây cầu bằng bìa cứng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_27_1_2', 'en-a2-27', 'ten_a2_27_1', 'listening', 'listening', 'We discovered a quiet beach behind the cliffs.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cây nhỏ này đã cao thêm một xentimét trong vòng một tuần.","Cho thêm một gam muối vào nồi súp.","Đêm nay chúng tôi đã ngắm nhìn một hành tinh sáng rực qua ống kính viễn vọng.","Chúng tôi đã phát hiện ra một bãi biển yên tĩnh nằm khuất sau những vách đá."]'::jsonb, 3, 'We discovered a quiet beach behind the cliffs. → Chúng tôi đã phát hiện ra một bãi biển yên tĩnh nằm khuất sau những vách đá.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_27_1_3', 'en-a2-27', 'ten_a2_27_1', 'listening', 'listening', 'This little plant grew one centimetre in a week.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cậu ấy làm một mô hình cây cầu bằng bìa cứng.","Cây nhỏ này đã cao thêm một xentimét trong vòng một tuần.","Nhà khoa học đã soi một giọt nước dưới kính hiển vi.","Mặt trăng từ từ nhô lên phía trên những rặng cây đằng sau ngôi nhà chúng tôi."]'::jsonb, 1, 'This little plant grew one centimetre in a week. → Cây nhỏ này đã cao thêm một xentimét trong vòng một tuần.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_27_2', 'en-a2-27', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_27_2_1', 'ten_a2_27_2', 'model', 'Researchers use a computer model to predict how rising temperatures may affect regional water supplies.', 'Researchers use a computer model to predict how rising temperatures may affect regional water supplies.', '/ˈmɑːdəl/', 'Các nhà nghiên cứu sử dụng một mô hình máy tính để dự đoán nhiệt độ tăng cao có thể ảnh hưởng như thế nào đến nguồn nước khu vực.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_27_2_2', 'ten_a2_27_2', 'discover', 'Scientists may discover new ways to treat diseases by studying plants in tropical forests.', 'Scientists may discover new ways to treat diseases by studying plants in tropical forests.', '/dɪˈskʌvər/', 'Các nhà khoa học có thể khám phá ra những phương pháp điều trị bệnh mới thông qua việc nghiên cứu thực vật trong các khu rừng nhiệt đới.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_27_2_3', 'ten_a2_27_2', 'centimetre', 'Even a small rise in sea level, measured in centimetres, can increase flooding risks in coastal communities.', 'Even a small rise in sea level, measured in centimetres, can increase flooding risks in coastal communities.', '/ˈsentəmiːtər/', 'Ngay cả một mực nước biển dâng lên nhỏ, tính bằng xentimét, cũng có thể làm tăng nguy cơ ngập lụt ở các cộng đồng ven biển.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_27_2_4', 'ten_a2_27_2', 'biology', 'A basic understanding of biology helps people evaluate health information and make informed decisions about their lifestyles.', 'A basic understanding of biology helps people evaluate health information and make informed decisions about their lifestyles.', '/baɪˈɑːlədʒi/', 'Hiểu biết cơ bản về sinh học giúp mọi người đánh giá các thông tin sức khỏe và đưa ra các quyết định sáng suốt về lối sống của mình.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_27_2_5', 'ten_a2_27_2', 'electricity', 'Generating electricity from renewable sources can reduce dependence on fossil fuels and lower greenhouse gas emissions.', 'Generating electricity from renewable sources can reduce dependence on fossil fuels and lower greenhouse gas emissions.', '/ɪˌlekˈtrɪsəti/', 'Sản xuất điện từ các nguồn năng lượng tái tạo có thể giảm sự phụ thuộc vào nhiên liệu hóa thạch và cắt giảm lượng khí thải nhà kính.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_27_2_6', 'ten_a2_27_2', 'lab', 'A well-equipped school lab allows students to test scientific ideas through practical experiments rather than memorisation alone.', 'A well-equipped school lab allows students to test scientific ideas through practical experiments rather than memorisation alone.', '/læb/', 'Một phòng thí nghiệm học đường được trang bị đầy đủ giúp học sinh kiểm chứng các quan điểm khoa học thông qua thực nghiệm thực tế thay vì chỉ học vẹt.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_27_2_1', 'en-a2-27', 'ten_a2_27_2', 'listening', 'listening', 'Researchers use a computer model to predict how rising temperatures may affect regional water supplies.', NULL, 'Trong câu vừa nghe, từ “model” mang nghĩa nào sau đây?', '["đột ngột; bỗng nhiên","sân; khu đất quanh nhà (thường có rào chắn)","mô hình; mẫu","bất đồng ý kiến; không đồng tình"]'::jsonb, 2, '“model” (/ˈmɑːdəl/): mô hình; mẫu. Câu đầy đủ: Researchers use a computer model to predict how rising temperatures may affect regional water supplies.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_27_2_2', 'en-a2-27', 'ten_a2_27_2', 'listening', 'listening', 'Scientists may discover new ways to treat diseases by studying plants in tropical forests.', NULL, 'Trong câu vừa nghe, từ “discover” mang nghĩa nào sau đây?', '["tháp; tòa tháp","giai đoạn; thời kỳ","đơn độc; một mình; không có ai ở cùng","phát hiện; tìm ra"]'::jsonb, 3, '“discover” (/dɪˈskʌvər/): phát hiện; tìm ra. Câu đầy đủ: Scientists may discover new ways to treat diseases by studying plants in tropical forests.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
