INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_27_2', 'en-a2-27', NULL, 'comprehensive_test', 'listening', 'We discovered a quiet beach behind the cliffs.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi sử dụng khí đốt để nấu ăn ở nhà.","Nhiệt độ giảm xuống đột ngột sau khi mặt trời lặn.","Đêm nay chúng tôi đã ngắm nhìn một hành tinh sáng rực qua ống kính viễn vọng.","Chúng tôi đã phát hiện ra một bãi biển yên tĩnh nằm khuất sau những vách đá."]'::jsonb, 3, 'We discovered a quiet beach behind the cliffs. → Chúng tôi đã phát hiện ra một bãi biển yên tĩnh nằm khuất sau những vách đá.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_27_3', 'en-a2-27', NULL, 'comprehensive_test', 'listening', 'centimetre', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["dưa hấu","tiệc nướng ngoài trời","cải thiện; nâng cao; tiến bộ","xentimét; centimet"]'::jsonb, 3, 'centimetre (/ˈsentəmiːtər/) → xentimét; centimet', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_27_4', 'en-a2-27', NULL, 'comprehensive_test', 'listening', 'We examined onion cells under microscopes in biology today.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mặt trăng từ từ nhô lên phía trên những rặng cây đằng sau ngôi nhà chúng tôi.","Chúng tôi đã quan sát các tế bào hành tây dưới kính hiển vi trong giờ sinh học ngày hôm nay.","Giáo viên vật lý của chúng tôi đã cho chúng tôi thấy nam châm hút sắt như thế nào.","Chúng tôi đeo kính bảo hộ khi pha trộn các chất lỏng trong phòng thí nghiệm."]'::jsonb, 1, 'We examined onion cells under microscopes in biology today. → Chúng tôi đã quan sát các tế bào hành tây dưới kính hiển vi trong giờ sinh học ngày hôm nay.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_27_5', 'en-a2-27', NULL, 'comprehensive_test', 'listening', 'electricity', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đồng euro","điện; năng lượng điện","môn toán; toán học","thợ xây dựng; nhà thầu xây dựng"]'::jsonb, 1, 'electricity (/ɪˌlekˈtrɪsəti/) → điện; năng lượng điện', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_27_6', 'en-a2-27', NULL, 'comprehensive_test', 'listening', 'We wore safety goggles while mixing liquids in the lab.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhà khoa học đã soi một giọt nước dưới kính hiển vi.","Chúng tôi đeo kính bảo hộ khi pha trộn các chất lỏng trong phòng thí nghiệm.","Đêm nay chúng tôi đã ngắm nhìn một hành tinh sáng rực qua ống kính viễn vọng.","Cơn bão đã làm mất điện toàn bộ con phố của chúng tôi."]'::jsonb, 1, 'We wore safety goggles while mixing liquids in the lab. → Chúng tôi đeo kính bảo hộ khi pha trộn các chất lỏng trong phòng thí nghiệm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
