INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_27_8', 'en-a2-27', NULL, 'comprehensive_test', 'listening', 'The moon rose slowly above the trees behind our house.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tay cầm bằng kim loại chạm vào ngón tay mang cảm giác lạnh ngắt.","Giáo viên vật lý của chúng tôi đã cho chúng tôi thấy nam châm hút sắt như thế nào.","Nhà khoa học đã soi một giọt nước dưới kính hiển vi.","Mặt trăng từ từ nhô lên phía trên những rặng cây đằng sau ngôi nhà chúng tôi."]'::jsonb, 3, 'The moon rose slowly above the trees behind our house. → Mặt trăng từ từ nhô lên phía trên những rặng cây đằng sau ngôi nhà chúng tôi.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
