INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_27_18', 'en-a2-27', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers use a computer model to predict how rising temperatures may affect regional water supplies.', 'Dựa vào câu trên, từ “model” có nghĩa phù hợp nhất là gì?', '["có thể; có lẽ","mô hình; mẫu","dấu hiệu; triệu chứng","công chúa; vương phi"]'::jsonb, 1, 'model: mô hình; mẫu; tấm gương; khuôn mẫu; người mẫu. Dịch cả câu: Các nhà nghiên cứu sử dụng một mô hình máy tính để dự đoán nhiệt độ tăng cao có thể ảnh hưởng như thế nào đến nguồn nước khu vực.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_27_19', 'en-a2-27', NULL, 'comprehensive_test', 'reading', NULL, 'Scientists may discover new ways to treat diseases by studying plants in tropical forests.', 'Dựa vào câu trên, từ “discover” có nghĩa phù hợp nhất là gì?', '["món đồ; vật phẩm","tệ nhất; tồi tệ nhất","phát hiện; tìm ra","chất béo; mỡ"]'::jsonb, 2, 'discover: phát hiện; tìm ra. Dịch cả câu: Các nhà khoa học có thể khám phá ra những phương pháp điều trị bệnh mới thông qua việc nghiên cứu thực vật trong các khu rừng nhiệt đới.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_27_20', 'en-a2-27', NULL, 'comprehensive_test', 'reading', NULL, 'Even a small rise in sea level, measured in centimetres, can increase flooding risks in coastal communities.', 'Dựa vào câu trên, từ “centimetre” có nghĩa phù hợp nhất là gì?', '["chắc chắn; dứt khoát; rạch ròi","hồ","bằng cấp; văn bằng","xentimét; centimet"]'::jsonb, 3, 'centimetre: xentimét; centimet. Dịch cả câu: Ngay cả một mực nước biển dâng lên nhỏ, tính bằng xentimét, cũng có thể làm tăng nguy cơ ngập lụt ở các cộng đồng ven biển.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_27_21', 'en-a2-27', NULL, 'comprehensive_test', 'reading', NULL, 'A basic understanding of biology helps people evaluate health information and make informed decisions about their lifestyles.', 'Dựa vào câu trên, từ “biology” có nghĩa phù hợp nhất là gì?', '["có nghĩa là; ngụ ý; định","sinh học","phổ biến; thông thường; hay gặp","đồng phục"]'::jsonb, 1, 'biology: sinh học; đặc điểm sinh học; cơ chế sinh lý. Dịch cả câu: Hiểu biết cơ bản về sinh học giúp mọi người đánh giá các thông tin sức khỏe và đưa ra các quyết định sáng suốt về lối sống của mình.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_27_22', 'en-a2-27', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hành tinh”', '["extremely","square","planet","interest"]'::jsonb, 2, 'hành tinh → planet (/ˈplænɪt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_27_23', 'en-a2-27', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nhà khoa học”', '["pain","scientist","taste","pillow"]'::jsonb, 1, 'nhà khoa học → scientist (/ˈsaɪəntɪst/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_27_24', 'en-a2-27', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chất khí; thể khí”', '["roof","crossing","gas","fix"]'::jsonb, 2, 'chất khí; thể khí → gas (/ɡæs/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-28', 'en', 'Bài 28: Truyền thông & Tin tức - CEFR A2', 'CEFR A2', 'A2 · Truyền thông', '9 từ vựng Tiếng Anh CEFR A2 chủ đề truyền thông & tin tức kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2028, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blog', 'en-a2-28', 'blog', '/blɑːɡ/', 'A2', 'trang blog; nhật ký điện tử; viết blog', 'n.', 'blogger (n.), blogging (n.)', NULL, 'Một bài đăng trên blog được gọi là a blog post; blog thường chỉ toàn bộ trang web hoặc nhật ký trực tuyến.', 'She writes a blog about growing vegetables at home.', NULL, 'Cô ấy viết một trang blog về việc trồng rau tại nhà.', '{"wordId":"blog","ukIpa":"/blɒɡ/","usIpa":"/blɑːɡ/","cefr":"A2","topic":"media","senses":[{"pos":"n.","en":"A website or page with regularly added posts.","vi":"trang blog; nhật ký điện tử"},{"pos":"v.","en":"To write and publish posts on a blog.","vi":"viết blog"}],"examples":[{"en":"She writes a blog about growing vegetables at home.","vi":"Cô ấy viết một trang blog về việc trồng rau tại nhà.","audioKind":"ex"},{"en":"A well-researched blog can make scientific information more accessible to readers without specialist knowledge.","vi":"Một bài blog được nghiên cứu kỹ lưỡng có thể giúp độc giả không có chuyên môn dễ dàng tiếp cận thông tin khoa học hơn.","audioKind":"ex2"}],"collocations":[{"en":"write a blog","vi":"viết blog"},{"en":"blog post","vi":"bài viết trên blog"},{"en":"travel blog","vi":"blog du lịch"},{"en":"blog about something","vi":"viết blog về một chủ đề nào đó"}],"wordFamily":["blogger (n.)","blogging (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Một bài đăng trên blog được gọi là a blog post; blog thường chỉ toàn bộ trang web hoặc nhật ký trực tuyến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_text', 'en-a2-28', 'text', '/tekst/', 'A2', 'văn bản; chữ; tin nhắn; nhắn tin', 'n.', 'textual (adj.), texting (n.)', NULL, 'Nội dung chữ viết thường không đếm được; một tin nhắn có thể dùng a text.', 'The text on this menu is too small.', NULL, 'Phần chữ trên thực đơn này quá nhỏ.', '{"wordId":"text","ukIpa":"/tekst/","usIpa":"/tekst/","cefr":"A2","topic":"media","senses":[{"pos":"n.","en":"Written words, especially the main written content of something.","vi":"văn bản; chữ"},{"pos":"n.","en":"A short written message sent using a phone.","vi":"tin nhắn"},{"pos":"v.","en":"Send someone a short written message using a phone.","vi":"nhắn tin"}],"examples":[{"en":"The text on this menu is too small.","vi":"Phần chữ trên thực đơn này quá nhỏ.","audioKind":"ex"},{"en":"Teachers can combine text with images to help students understand complex scientific concepts more easily.","vi":"Giáo viên có thể kết hợp văn bản với hình ảnh để giúp học sinh hiểu các khái niệm khoa học phức tạp một cách dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"text message","vi":"tin nhắn văn bản"},{"en":"plain text","vi":"văn bản thuần túy"},{"en":"text someone","vi":"nhắn tin cho ai đó"}],"wordFamily":["textual (adj.)","texting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Nội dung chữ viết thường không đếm được; một tin nhắn có thể dùng a text.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reporter', 'en-a2-28', 'reporter', '/rɪˈpɔːrtər/', 'A2', 'phóng viên; nhà báo', 'n.', 'report (v.), reporting (n.)', 'Đồng nghĩa: journalist', 'reporter tập trung vào việc thu thập tin tức và đưa tin; journalist có phạm vi rộng hơn.', 'A reporter interviewed the coach after the match.', NULL, 'Một phóng viên đã phỏng vấn huấn luyện viên sau trận đấu.', '{"wordId":"reporter","ukIpa":"/rɪˈpɔːtə/","usIpa":"/rɪˈpɔːrtər/","cefr":"A2","topic":"media","senses":[{"pos":"n.","en":"Someone who gathers and presents news for the public.","vi":"phóng viên; nhà báo"}],"examples":[{"en":"A reporter interviewed the coach after the match.","vi":"Một phóng viên đã phỏng vấn huấn luyện viên sau trận đấu.","audioKind":"ex"},{"en":"A responsible reporter checks information carefully before publishing stories that could influence public opinion on important social issues.","vi":"Một phóng viên có trách nhiệm luôn kiểm tra thông tin cẩn thận trước khi đăng tải các bài viết có thể ảnh hưởng đến dư luận về các vấn đề xã hội quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"news reporter","vi":"phóng viên thời sự"},{"en":"television reporter","vi":"phóng viên truyền hình"},{"en":"sports reporter","vi":"phóng viên thể thao"}],"wordFamily":["report (v.)","reporting (n.)"],"synonyms":["journalist"],"antonyms":[],"tipVi":"reporter tập trung vào việc thu thập tin tức và đưa tin; journalist có phạm vi rộng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_article', 'en-a2-28', 'article', '/ˈɑːrtɪkəl/', 'A2', 'bài báo; bài viết; bài luận; đồ vật; vật phẩm (đặc biệt là món đồ thuộc một nhóm cụ thể); mạo từ (từ như a, an hoặc the đứng trước danh từ)', 'n.', NULL, 'Đồng nghĩa: piece, item', 'Một món quần áo có thể nói là an article of clothing.', 'I read an interesting article about growing tomatoes indoors.', NULL, 'Tôi đã đọc một bài viết thú vị về việc trồng cà chua trong nhà.', '{"wordId":"article","ukIpa":"/ˈɑːtɪkəl/","usIpa":"/ˈɑːrtɪkəl/","cefr":"A2","topic":"media","senses":[{"pos":"n.","en":"A piece of writing in a newspaper, magazine, or website.","vi":"bài báo; bài viết; bài luận"},{"pos":"n.","en":"A single item, especially one belonging to a particular group.","vi":"đồ vật; vật phẩm (đặc biệt là món đồ thuộc một nhóm cụ thể)"},{"pos":"n.","en":"A word such as a, an, or the before a noun.","vi":"mạo từ (từ như a, an hoặc the đứng trước danh từ)"}],"examples":[{"en":"I read an interesting article about growing tomatoes indoors.","vi":"Tôi đã đọc một bài viết thú vị về việc trồng cà chua trong nhà.","audioKind":"ex"},{"en":"The article examines how access to green spaces influences mental health in densely populated cities.","vi":"Bài báo nghiên cứu cách thức khả năng tiếp cận không gian xanh ảnh hưởng đến sức khỏe tinh thần ở các thành phố đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"a newspaper article","vi":"một bài báo"},{"en":"write an article","vi":"viết một bài báo"},{"en":"an article of clothing","vi":"một món đồ trang phục"},{"en":"the definite article","vi":"mạo từ xác định"}],"wordFamily":[],"synonyms":["piece","item"],"antonyms":[],"tipVi":"Một món quần áo có thể nói là an article of clothing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recording', 'en-a2-28', 'recording', '/rɪˈkɔːrdɪŋ/', 'A2', 'bản ghi âm; bản ghi hình; sự ghi âm; sự ghi hình; sự ghi chép', 'n.', 'record (v.), recorder (n.), recorded (adj.)', NULL, 'Một đoạn ghi âm (recording) là danh từ đếm được; khi chỉ quá trình ghi hình/ghi âm (recording) thì thường là danh từ không đếm được.', 'We listened to a recording of birds during breakfast.', NULL, 'Chúng tôi nghe một đoạn ghi âm tiếng chim hót trong bữa sáng.', '{"wordId":"recording","ukIpa":"/rɪˈkɔːdɪŋ/","usIpa":"/rɪˈkɔːrdɪŋ/","cefr":"A2","topic":"media","senses":[{"pos":"n.","en":"sound or moving images saved for later listening or viewing","vi":"bản ghi âm; bản ghi hình"},{"pos":"n.","en":"the process of saving sounds, images, or information","vi":"sự ghi âm; sự ghi hình; sự ghi chép"}],"examples":[{"en":"We listened to a recording of birds during breakfast.","vi":"Chúng tôi nghe một đoạn ghi âm tiếng chim hót trong bữa sáng.","audioKind":"ex"},{"en":"Access to a lecture recording allows students to review difficult concepts at their own pace.","vi":"Việc truy cập vào bản ghi hình bài giảng giúp học sinh ôn tập các khái niệm khó theo tốc độ riêng của các em.","audioKind":"ex2"}],"collocations":[{"en":"make a recording","vi":"làm bản ghi âm; tạo bản ghi hình"},{"en":"recording studio","vi":"phòng thu âm"},{"en":"audio recording","vi":"bản ghi âm thanh"},{"en":"accurate recording","vi":"sự ghi chép chính xác"}],"wordFamily":["record (v.)","recorder (n.)","recorded (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Một đoạn ghi âm (recording) là danh từ đếm được; khi chỉ quá trình ghi hình/ghi âm (recording) thì thường là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_report', 'en-a2-28', 'report', '/rɪˈpɔːrt/', 'A2', 'bản báo cáo; tường thuật; báo cáo; trình diện', 'n.', 'reporter (n.), reporting (n.)', 'Đồng nghĩa: account', 'report on dùng để chỉ chủ đề báo cáo; report for duty có nghĩa là báo cáo nhận nhiệm vụ.', 'I finished my report before lunch and emailed it.', NULL, 'Tôi đã làm xong bản báo cáo trước giờ ăn trưa và gửi email đi rồi.', '{"wordId":"report","ukIpa":"/rɪˈpɔːt/","usIpa":"/rɪˈpɔːrt/","cefr":"A2","topic":"media","senses":[{"pos":"n.","en":"A spoken or written account giving information about something","vi":"bản báo cáo; tường thuật"},{"pos":"v.","en":"To give information about an event or situation","vi":"báo cáo; tường thuật"},{"pos":"v.","en":"To arrive somewhere and tell the person in charge","vi":"trình diện; báo cáo"}],"examples":[{"en":"I finished my report before lunch and emailed it.","vi":"Tôi đã làm xong bản báo cáo trước giờ ăn trưa và gửi email đi rồi.","audioKind":"ex"},{"en":"The report suggests that improved access to green spaces can benefit residents'' physical and mental health.","vi":"Bản báo cáo chỉ ra rằng việc cải thiện khả năng tiếp cận không gian xanh có thể mang lại lợi ích cho sức khỏe thể chất và tinh thần của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"write a report","vi":"viết báo cáo"},{"en":"a news report","vi":"bản tin tức"},{"en":"report a problem","vi":"báo cáo một vấn đề"},{"en":"report for duty","vi":"trình diện nhận nhiệm vụ"}],"wordFamily":["reporter (n.)","reporting (n.)"],"synonyms":["account"],"antonyms":[],"tipVi":"report on dùng để chỉ chủ đề báo cáo; report for duty có nghĩa là báo cáo nhận nhiệm vụ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_poster', 'en-a2-28', 'poster', '/ˈpoʊstər/', 'A2', 'áp phích; tranh cổ động; hải báo', 'n.', 'post (v.)', NULL, 'poster là áp phích; postcard là bưu thiếp, cần chú ý phân biệt.', 'She hung a colourful poster above her desk.', NULL, 'Cô ấy treo một tấm áp phích đầy màu sắc phía trên bàn làm việc của mình.', '{"wordId":"poster","ukIpa":"/ˈpəʊstə/","usIpa":"/ˈpoʊstər/","cefr":"A2","topic":"media","senses":[{"pos":"n.","en":"A large printed picture or announcement displayed on a surface","vi":"áp phích; tranh cổ động; hải báo"}],"examples":[{"en":"She hung a colourful poster above her desk.","vi":"Cô ấy treo một tấm áp phích đầy màu sắc phía trên bàn làm việc của mình.","audioKind":"ex"},{"en":"A well-designed poster can encourage people to recycle by presenting environmental messages clearly and attractively.","vi":"Một tấm áp phích được thiết kế tốt có thể khuyến khích mọi người tái chế bằng cách truyền tải thông điệp về môi trường một cách rõ ràng và hấp dẫn.","audioKind":"ex2"}],"collocations":[{"en":"put up a poster","vi":"dán áp phích"},{"en":"design a poster","vi":"thiết kế áp phích"},{"en":"advertising poster","vi":"áp phích quảng cáo"},{"en":"poster campaign","vi":"chiến dịch áp phích"}],"wordFamily":["post (v.)"],"synonyms":[],"antonyms":[],"tipVi":"poster là áp phích; postcard là bưu thiếp, cần chú ý phân biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cartoon', 'en-a2-28', 'cartoon', '/kɑrˈtuːn/', 'A2', 'phim hoạt hình; tranh biếm họa; tranh châm biếm', 'n.', 'cartoonist (n.)', NULL, 'Cartoon có thể chỉ phim hoạt hình hoặc tranh đơn, còn truyện tranh thường dùng comic.', 'We watched a funny cartoon about a dancing penguin.', NULL, 'Chúng tôi đã xem một bộ phim hoạt hình hài hước về một chú chim cánh cụt biết khiêu vũ.', '{"wordId":"cartoon","ukIpa":"/kɑːˈtuːn/","usIpa":"/kɑrˈtuːn/","cefr":"A2","topic":"media","senses":[{"pos":"n.","en":"a film or programme made using animated drawings or images","vi":"phim hoạt hình"},{"pos":"n.","en":"a humorous drawing, often commenting on society or politics","vi":"tranh biếm họa; tranh châm biếm"}],"examples":[{"en":"We watched a funny cartoon about a dancing penguin.","vi":"Chúng tôi đã xem một bộ phim hoạt hình hài hước về một chú chim cánh cụt biết khiêu vũ.","audioKind":"ex"},{"en":"Political cartoons can communicate complex social criticism through simple images that appeal to a wide audience.","vi":"Tranh biếm họa chính trị có thể truyền tải những lời chỉ trích xã hội phức tạp thông qua hình ảnh đơn giản thu hút đông đảo khán giả.","audioKind":"ex2"}],"collocations":[{"en":"cartoon character","vi":"nhân vật hoạt hình"},{"en":"animated cartoon","vi":"phim hoạt hình động"},{"en":"political cartoon","vi":"tranh biếm họa chính trị"}],"wordFamily":["cartoonist (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cartoon có thể chỉ phim hoạt hình hoặc tranh đơn, còn truyện tranh thường dùng comic.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_advertisement', 'en-a2-28', 'advertisement', '/ˌædvɚˈtaɪzmənt/', 'A2', 'quảng cáo', 'n.', 'advertise (v.), advertising (n.), advertiser (n.)', 'Đồng nghĩa: advert, ad', 'Nội dung quảng cáo thường dùng for; advertising dùng để chỉ chung hoạt động quảng cáo.', 'I saw an advertisement for bicycles at the station.', NULL, 'Tôi thấy một quảng cáo xe đạp ở nhà ga.', '{"wordId":"advertisement","ukIpa":"/ədˈvɜːtɪsmənt/","usIpa":"/ˌædvɚˈtaɪzmənt/","cefr":"A2","topic":"media","senses":[{"pos":"n.","en":"A public message promoting a product, service, event, or opportunity.","vi":"quảng cáo"}],"examples":[{"en":"I saw an advertisement for bicycles at the station.","vi":"Tôi thấy một quảng cáo xe đạp ở nhà ga.","audioKind":"ex"},{"en":"Advertisements aimed at young consumers should present accurate information rather than encourage unnecessary spending.","vi":"Các quảng cáo hướng đến người tiêu dùng trẻ tuổi nên cung cấp thông tin chính xác thay vì khuyến khích chi tiêu không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"an advertisement for","vi":"quảng cáo về..."},{"en":"place an advertisement","vi":"đăng quảng cáo"},{"en":"online advertisement","vi":"quảng cáo trực tuyến"}],"wordFamily":["advertise (v.)","advertising (n.)","advertiser (n.)"],"synonyms":["advert","ad"],"antonyms":[],"tipVi":"Nội dung quảng cáo thường dùng for; advertising dùng để chỉ chung hoạt động quảng cáo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_28_1', 'en-a2-28', 'Cách dùng “recording” (n.) — bản ghi âm; bản ghi hình', 'make a recording  ·  recording studio  ·  audio recording', 'Một đoạn ghi âm (recording) là danh từ đếm được; khi chỉ quá trình ghi hình/ghi âm (recording) thì thường là danh từ không đếm được.', 'Họ từ (Word Family): record (v.), recorder (n.), recorded (adj.)', '[{"hanzi":"We listened to a recording of birds during breakfast.","pinyin":"","meaning":"Chúng tôi nghe một đoạn ghi âm tiếng chim hót trong bữa sáng."},{"hanzi":"Access to a lecture recording allows students to review difficult concepts at their own pace.","pinyin":"","meaning":"Việc truy cập vào bản ghi hình bài giảng giúp học sinh ôn tập các khái niệm khó theo tốc độ riêng của các em."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_28_2', 'en-a2-28', 'Cách dùng “blog” (n.) — trang blog; nhật ký điện tử', 'write a blog  ·  blog post  ·  travel blog', 'Một bài đăng trên blog được gọi là a blog post; blog thường chỉ toàn bộ trang web hoặc nhật ký trực tuyến.', 'Họ từ (Word Family): blogger (n.), blogging (n.)', '[{"hanzi":"She writes a blog about growing vegetables at home.","pinyin":"","meaning":"Cô ấy viết một trang blog về việc trồng rau tại nhà."},{"hanzi":"A well-researched blog can make scientific information more accessible to readers without specialist knowledge.","pinyin":"","meaning":"Một bài blog được nghiên cứu kỹ lưỡng có thể giúp độc giả không có chuyên môn dễ dàng tiếp cận thông tin khoa học hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_28_3', 'en-a2-28', 'Cách dùng “reporter” (n.) — phóng viên; nhà báo', 'news reporter  ·  television reporter  ·  sports reporter', 'reporter tập trung vào việc thu thập tin tức và đưa tin; journalist có phạm vi rộng hơn.', 'Họ từ (Word Family): report (v.), reporting (n.) | Đồng nghĩa: journalist', '[{"hanzi":"A reporter interviewed the coach after the match.","pinyin":"","meaning":"Một phóng viên đã phỏng vấn huấn luyện viên sau trận đấu."},{"hanzi":"A responsible reporter checks information carefully before publishing stories that could influence public opinion on important social issues.","pinyin":"","meaning":"Một phóng viên có trách nhiệm luôn kiểm tra thông tin cẩn thận trước khi đăng tải các bài viết có thể ảnh hưởng đến dư luận về các vấn đề xã hội quan trọng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_28_4', 'en-a2-28', 'Cách dùng “report” (n.) — bản báo cáo; tường thuật', 'write a report  ·  a news report  ·  report a problem', 'report on dùng để chỉ chủ đề báo cáo; report for duty có nghĩa là báo cáo nhận nhiệm vụ.', 'Họ từ (Word Family): reporter (n.), reporting (n.) | Đồng nghĩa: account', '[{"hanzi":"I finished my report before lunch and emailed it.","pinyin":"","meaning":"Tôi đã làm xong bản báo cáo trước giờ ăn trưa và gửi email đi rồi."},{"hanzi":"The report suggests that improved access to green spaces can benefit residents'' physical and mental health.","pinyin":"","meaning":"Bản báo cáo chỉ ra rằng việc cải thiện khả năng tiếp cận không gian xanh có thể mang lại lợi ích cho sức khỏe thể chất và tinh thần của cư dân."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_28_1', 'en-a2-28', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_28_1_1', 'ten_a2_28_1', 'blog', 'She writes a blog about growing vegetables at home.', 'She writes a blog about growing vegetables at home.', '/blɑːɡ/', 'Cô ấy viết một trang blog về việc trồng rau tại nhà.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_28_1_2', 'ten_a2_28_1', 'text', 'The text on this menu is too small.', 'The text on this menu is too small.', '/tekst/', 'Phần chữ trên thực đơn này quá nhỏ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_28_1_3', 'ten_a2_28_1', 'reporter', 'A reporter interviewed the coach after the match.', 'A reporter interviewed the coach after the match.', '/rɪˈpɔːrtər/', 'Một phóng viên đã phỏng vấn huấn luyện viên sau trận đấu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_28_1_4', 'ten_a2_28_1', 'article', 'I read an interesting article about growing tomatoes indoors.', 'I read an interesting article about growing tomatoes indoors.', '/ˈɑːrtɪkəl/', 'Tôi đã đọc một bài viết thú vị về việc trồng cà chua trong nhà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_28_1_5', 'ten_a2_28_1', 'recording', 'We listened to a recording of birds during breakfast.', 'We listened to a recording of birds during breakfast.', '/rɪˈkɔːrdɪŋ/', 'Chúng tôi nghe một đoạn ghi âm tiếng chim hót trong bữa sáng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_28_1_6', 'ten_a2_28_1', 'report', 'I finished my report before lunch and emailed it.', 'I finished my report before lunch and emailed it.', '/rɪˈpɔːrt/', 'Tôi đã làm xong bản báo cáo trước giờ ăn trưa và gửi email đi rồi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_28_1_7', 'ten_a2_28_1', 'poster', 'She hung a colourful poster above her desk.', 'She hung a colourful poster above her desk.', '/ˈpoʊstər/', 'Cô ấy treo một tấm áp phích đầy màu sắc phía trên bàn làm việc của mình.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_28_1_8', 'ten_a2_28_1', 'cartoon', 'We watched a funny cartoon about a dancing penguin.', 'We watched a funny cartoon about a dancing penguin.', '/kɑrˈtuːn/', 'Chúng tôi đã xem một bộ phim hoạt hình hài hước về một chú chim cánh cụt biết khiêu vũ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_28_1_1', 'en-a2-28', 'ten_a2_28_1', 'listening', 'listening', 'She writes a blog about growing vegetables at home.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã xem một bộ phim hoạt hình hài hước về một chú chim cánh cụt biết khiêu vũ.","Cô ấy viết một trang blog về việc trồng rau tại nhà.","Tôi đã đọc một bài viết thú vị về việc trồng cà chua trong nhà.","Chúng tôi nghe một đoạn ghi âm tiếng chim hót trong bữa sáng."]'::jsonb, 1, 'She writes a blog about growing vegetables at home. → Cô ấy viết một trang blog về việc trồng rau tại nhà.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_28_1_2', 'en-a2-28', 'ten_a2_28_1', 'listening', 'listening', 'The text on this menu is too small.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã làm xong bản báo cáo trước giờ ăn trưa và gửi email đi rồi.","Chúng tôi đã xem một bộ phim hoạt hình hài hước về một chú chim cánh cụt biết khiêu vũ.","Cô ấy viết một trang blog về việc trồng rau tại nhà.","Phần chữ trên thực đơn này quá nhỏ."]'::jsonb, 3, 'The text on this menu is too small. → Phần chữ trên thực đơn này quá nhỏ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_28_1_3', 'en-a2-28', 'ten_a2_28_1', 'listening', 'listening', 'A reporter interviewed the coach after the match.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã đọc một bài viết thú vị về việc trồng cà chua trong nhà.","Một phóng viên đã phỏng vấn huấn luyện viên sau trận đấu.","Cô ấy treo một tấm áp phích đầy màu sắc phía trên bàn làm việc của mình.","Chúng tôi đã xem một bộ phim hoạt hình hài hước về một chú chim cánh cụt biết khiêu vũ."]'::jsonb, 1, 'A reporter interviewed the coach after the match. → Một phóng viên đã phỏng vấn huấn luyện viên sau trận đấu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_28_2', 'en-a2-28', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_28_2_1', 'ten_a2_28_2', 'blog', 'A well-researched blog can make scientific information more accessible to readers without specialist knowledge.', 'A well-researched blog can make scientific information more accessible to readers without specialist knowledge.', '/blɑːɡ/', 'Một bài blog được nghiên cứu kỹ lưỡng có thể giúp độc giả không có chuyên môn dễ dàng tiếp cận thông tin khoa học hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_28_2_2', 'ten_a2_28_2', 'text', 'Teachers can combine text with images to help students understand complex scientific concepts more easily.', 'Teachers can combine text with images to help students understand complex scientific concepts more easily.', '/tekst/', 'Giáo viên có thể kết hợp văn bản với hình ảnh để giúp học sinh hiểu các khái niệm khoa học phức tạp một cách dễ dàng hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_28_2_3', 'ten_a2_28_2', 'reporter', 'A responsible reporter checks information carefully before publishing stories that could influence public opinion on important social issues.', 'A responsible reporter checks information carefully before publishing stories that could influence public opinion on important social issues.', '/rɪˈpɔːrtər/', 'Một phóng viên có trách nhiệm luôn kiểm tra thông tin cẩn thận trước khi đăng tải các bài viết có thể ảnh hưởng đến dư luận về các vấn đề xã hội quan trọng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_28_2_4', 'ten_a2_28_2', 'article', 'The article examines how access to green spaces influences mental health in densely populated cities.', 'The article examines how access to green spaces influences mental health in densely populated cities.', '/ˈɑːrtɪkəl/', 'Bài báo nghiên cứu cách thức khả năng tiếp cận không gian xanh ảnh hưởng đến sức khỏe tinh thần ở các thành phố đông dân cư.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_28_2_5', 'ten_a2_28_2', 'recording', 'Access to a lecture recording allows students to review difficult concepts at their own pace.', 'Access to a lecture recording allows students to review difficult concepts at their own pace.', '/rɪˈkɔːrdɪŋ/', 'Việc truy cập vào bản ghi hình bài giảng giúp học sinh ôn tập các khái niệm khó theo tốc độ riêng của các em.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_28_2_6', 'ten_a2_28_2', 'report', 'The report suggests that improved access to green spaces can benefit residents'' physical and mental health.', 'The report suggests that improved access to green spaces can benefit residents'' physical and mental health.', '/rɪˈpɔːrt/', 'Bản báo cáo chỉ ra rằng việc cải thiện khả năng tiếp cận không gian xanh có thể mang lại lợi ích cho sức khỏe thể chất và tinh thần của cư dân.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
