INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_28_6', 'en-a2-28', NULL, 'comprehensive_test', 'listening', 'I finished my report before lunch and emailed it.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Phần chữ trên thực đơn này quá nhỏ.","Cô ấy viết một trang blog về việc trồng rau tại nhà.","Chúng tôi đã xem một bộ phim hoạt hình hài hước về một chú chim cánh cụt biết khiêu vũ.","Tôi đã làm xong bản báo cáo trước giờ ăn trưa và gửi email đi rồi."]'::jsonb, 3, 'I finished my report before lunch and emailed it. → Tôi đã làm xong bản báo cáo trước giờ ăn trưa và gửi email đi rồi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_28_7', 'en-a2-28', NULL, 'comprehensive_test', 'listening', 'poster', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["áp phích; tranh cổ động; hải báo","tiếng ồn; tiếng động","tệ hơn; tồi tệ hơn; nghiêm trọng hơn","may mắn thay, thật may (đặc biệt khi điều tồi tệ suýt xảy ra)"]'::jsonb, 0, 'poster (/ˈpoʊstər/) → áp phích; tranh cổ động; hải báo', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_28_8', 'en-a2-28', NULL, 'comprehensive_test', 'listening', 'We watched a funny cartoon about a dancing penguin.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi thấy một quảng cáo xe đạp ở nhà ga.","Phần chữ trên thực đơn này quá nhỏ.","Chúng tôi đã xem một bộ phim hoạt hình hài hước về một chú chim cánh cụt biết khiêu vũ.","Tôi đã làm xong bản báo cáo trước giờ ăn trưa và gửi email đi rồi."]'::jsonb, 2, 'We watched a funny cartoon about a dancing penguin. → Chúng tôi đã xem một bộ phim hoạt hình hài hước về một chú chim cánh cụt biết khiêu vũ.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_28_9', 'en-a2-28', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “sound or moving images saved for later listening or viewing”?', '["advertisement","cartoon","text","recording"]'::jsonb, 3, 'recording (/rɪˈkɔːrdɪŋ/) → bản ghi âm; bản ghi hình', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
