INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_28_18', 'en-a2-28', NULL, 'comprehensive_test', 'reading', NULL, 'A well-researched blog can make scientific information more accessible to readers without specialist knowledge.', 'Dựa vào câu trên, từ “blog” có nghĩa phù hợp nhất là gì?', '["vàng; kim loại vàng","đi bộ đường dài; leo núi; đi dã ngoại (đi dạo dài ở ngoài trời, đặc biệt là vùng nông thôn)","đã ly hôn","trang blog; nhật ký điện tử"]'::jsonb, 3, 'blog: trang blog; nhật ký điện tử; viết blog. Dịch cả câu: Một bài blog được nghiên cứu kỹ lưỡng có thể giúp độc giả không có chuyên môn dễ dàng tiếp cận thông tin khoa học hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_28_19', 'en-a2-28', NULL, 'comprehensive_test', 'reading', NULL, 'Teachers can combine text with images to help students understand complex scientific concepts more easily.', 'Dựa vào câu trên, từ “text” có nghĩa phù hợp nhất là gì?', '["găng tay; bao tay","tim; trái tim","thế kỷ; một trăm năm","văn bản; chữ"]'::jsonb, 3, 'text: văn bản; chữ; tin nhắn; nhắn tin. Dịch cả câu: Giáo viên có thể kết hợp văn bản với hình ảnh để giúp học sinh hiểu các khái niệm khoa học phức tạp một cách dễ dàng hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_28_20', 'en-a2-28', NULL, 'comprehensive_test', 'reading', NULL, 'A responsible reporter checks information carefully before publishing stories that could influence public opinion on important social issues.', 'Dựa vào câu trên, từ “reporter” có nghĩa phù hợp nhất là gì?', '["phóng viên; nhà báo","con ếch","bàn chải; cọ vẽ","nên; phải"]'::jsonb, 0, 'reporter: phóng viên; nhà báo. Dịch cả câu: Một phóng viên có trách nhiệm luôn kiểm tra thông tin cẩn thận trước khi đăng tải các bài viết có thể ảnh hưởng đến dư luận về các vấn đề xã hội quan trọng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_28_21', 'en-a2-28', NULL, 'comprehensive_test', 'reading', NULL, 'The article examines how access to green spaces influences mental health in densely populated cities.', 'Dựa vào câu trên, từ “article” có nghĩa phù hợp nhất là gì?', '["cực kỳ; vô cùng","bài báo; bài viết; bài luận","giai đoạn; thời kỳ","mối quan hệ; mối quan hệ tình cảm"]'::jsonb, 1, 'article: bài báo; bài viết; bài luận; đồ vật; vật phẩm (đặc biệt là món đồ thuộc một nhóm cụ thể); mạo từ (từ như a, an hoặc the đứng trước danh từ). Dịch cả câu: Bài báo nghiên cứu cách thức khả năng tiếp cận không gian xanh ảnh hưởng đến sức khỏe tinh thần ở các thành phố đông dân cư.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
