INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-29', 'en', 'Bài 29: Đời sống hằng ngày (1) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '27 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2029, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_circle', 'en-a2-29', 'circle', '/ˈsɝːkəl/', 'A2', 'hình tròn; vòng tròn; vòng tròn (những người có cùng bạn bè hoặc sở thích); giới; tầng lớp; khoanh tròn; bay lượn vòng quanh', 'n.', 'circular (adj.)', NULL, 'circle là hình tròn hoặc vòng tròn; trong khi cycle thường chỉ chu kỳ hoặc vòng tuần hoàn.', 'The children sat in a circle on the grass.', NULL, 'Lũ trẻ ngồi thành một vòng tròn trên bãi cỏ.', '{"wordId":"circle","ukIpa":"/ˈsɜːkəl/","usIpa":"/ˈsɝːkəl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A round shape whose edge is equally distant from its centre.","vi":"hình tròn; vòng tròn"},{"pos":"n.","en":"A group of people connected by friendship or shared interests.","vi":"vòng tròn (những người có cùng bạn bè hoặc sở thích); giới; tầng lớp"},{"pos":"v.","en":"To move around something or draw a ring around it.","vi":"khoanh tròn; bay lượn vòng quanh"}],"examples":[{"en":"The children sat in a circle on the grass.","vi":"Lũ trẻ ngồi thành một vòng tròn trên bãi cỏ.","audioKind":"ex"},{"en":"Joining community activities can help older adults expand their social circle and reduce feelings of isolation.","vi":"Tham gia các hoạt động cộng đồng có thể giúp người cao tuổi mở rộng vòng tròn xã hội và giảm cảm giác cô lập.","audioKind":"ex2"}],"collocations":[{"en":"draw a circle","vi":"vẽ một hình tròn"},{"en":"in a circle","vi":"thành vòng tròn"},{"en":"social circle","vi":"vòng tròn xã hội; giao lưu"},{"en":"circle overhead","vi":"bay lượn phía trên"}],"wordFamily":["circular (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"circle là hình tròn hoặc vòng tròn; trong khi cycle thường chỉ chu kỳ hoặc vòng tuần hoàn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pardon', 'en-a2-29', 'pardon', '/ˈpɑːrdən/', 'A2', 'xin lỗi; xin nhắc lại (lời lịch sự để yêu cầu người khác lặp lại); tha thứ; ân xá; sự ân xá; sự tha thứ', 'int.', 'pardonable (adj.), unpardonable (adj.)', 'Đồng nghĩa: forgive, excuse', 'Khi không nghe rõ bạn có thể nói Pardon?, với ngữ điệu thường đi lên.', 'Pardon? I couldn''t hear you over the washing machine.', NULL, 'Xin bạn nói lại được không? Tiếng máy giặt to quá nên tôi không nghe rõ.', '{"wordId":"pardon","ukIpa":"/ˈpɑːdən/","usIpa":"/ˈpɑːrdən/","cefr":"A2","topic":"daily","senses":[{"pos":"int.","en":"Used politely to ask someone to repeat what they said.","vi":"xin lỗi; xin nhắc lại (lời lịch sự để yêu cầu người khác lặp lại)"},{"pos":"v.","en":"To forgive someone or officially release them from punishment.","vi":"tha thứ; ân xá"},{"pos":"n.","en":"Official forgiveness for a crime, or forgiveness for an offence.","vi":"sự ân xá; sự tha thứ"}],"examples":[{"en":"Pardon? I couldn''t hear you over the washing machine.","vi":"Xin bạn nói lại được không? Tiếng máy giặt to quá nên tôi không nghe rõ.","audioKind":"ex"},{"en":"A legal pardon can help someone rebuild their life, although public acceptance may take longer.","vi":"Một lệnh ân xá pháp lý có thể giúp một người làm lại cuộc đời, mặc dù sự chấp nhận từ cộng đồng có thể mất nhiều thời gian hơn.","audioKind":"ex2"}],"collocations":[{"en":"pardon me","vi":"xin lỗi bạn; phiền bạn"},{"en":"I beg your pardon","vi":"xin lỗi bạn; xin vui lòng nhắc lại"},{"en":"grant a pardon","vi":"ban ân xá"}],"wordFamily":["pardonable (adj.)","unpardonable (adj.)"],"synonyms":["forgive","excuse"],"antonyms":[],"tipVi":"Khi không nghe rõ bạn có thể nói Pardon?, với ngữ điệu thường đi lên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_easily', 'en-a2-29', 'easily', '/ˈiːzəli/', 'A2', 'dễ dàng; không mấy khó khăn; rõ rệt; cách biệt rõ ràng; rất có thể; khả năng cao', 'adv.', 'easy (adj.), ease (n.), ease (v.)', 'Đồng nghĩa: effortlessly, readily · Trái nghĩa: laboriously', 'easily có thể tu từ cho cấp so sánh nhất: easily the best có nghĩa là vượt trội hơn hẳn.', 'This small suitcase fits easily beneath the train seat.', NULL, 'Chiếc va-li nhỏ này dễ dàng nhét vừa bên dưới ghế ngồi trên tàu.', '{"wordId":"easily","ukIpa":"/ˈiːzəli/","usIpa":"/ˈiːzəli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"without difficulty or much effort","vi":"dễ dàng; không mấy khó khăn"},{"pos":"adv.","en":"by a clear margin, especially in comparisons","vi":"rõ rệt; cách biệt rõ ràng"},{"pos":"adv.","en":"with a strong possibility of something happening","vi":"rất có thể; khả năng cao"}],"examples":[{"en":"This small suitcase fits easily beneath the train seat.","vi":"Chiếc va-li nhỏ này dễ dàng nhét vừa bên dưới ghế ngồi trên tàu.","audioKind":"ex"},{"en":"Public information should be presented clearly so that people with different literacy levels can easily understand it.","vi":"Thông tin công cộng nên được trình bày rõ ràng để những người có trình độ văn hóa khác nhau đều có thể dễ dàng hiểu được.","audioKind":"ex2"}],"collocations":[{"en":"easily accessible","vi":"dễ tiếp cận"},{"en":"easily understood","vi":"dễ hiểu"},{"en":"easily the best","vi":"đảm bảo là tốt nhất"},{"en":"could easily happen","vi":"rất có thể xảy ra"}],"wordFamily":["easy (adj.)","ease (n.)","ease (v.)"],"synonyms":["effortlessly","readily"],"antonyms":["laboriously"],"tipVi":"easily có thể tu từ cho cấp so sánh nhất: easily the best có nghĩa là vượt trội hơn hẳn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bit', 'en-a2-29', 'bit', '/bɪt/', 'A2', 'một chút; một lượng nhỏ; một miếng nhỏ; bit (đơn vị thông tin nhỏ nhất trong máy tính)', 'n.', NULL, NULL, 'a bit of đi với danh từ; a bit dùng để bổ nghĩa cho tính từ; bit cũng là dạng quá khứ của bite.', 'There is a bit of cake left for you.', NULL, 'Vẫn còn một chút bánh ngọt để dành cho bạn đấy.', '{"wordId":"bit","ukIpa":"/bɪt/","usIpa":"/bɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A small amount or piece of something.","vi":"một chút; một lượng nhỏ; một miếng nhỏ"},{"pos":"n.","en":"The smallest unit of information stored by a computer.","vi":"bit (đơn vị thông tin nhỏ nhất trong máy tính)"}],"examples":[{"en":"There is a bit of cake left for you.","vi":"Vẫn còn một chút bánh ngọt để dành cho bạn đấy.","audioKind":"ex"},{"en":"Even a small bit of practical experience can help students understand difficult scientific concepts.","vi":"Ngay cả một chút kinh nghiệm thực tế nhỏ nhoi cũng có thể giúp học sinh hiểu được các khái niệm khoa học phức tạp.","audioKind":"ex2"}],"collocations":[{"en":"a bit of","vi":"một chút"},{"en":"a little bit","vi":"một chút xíu"},{"en":"bit by bit","vi":"từng chút một"},{"en":"bits and pieces","vi":"những thứ lặt vặt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"a bit of đi với danh từ; a bit dùng để bổ nghĩa cho tính từ; bit cũng là dạng quá khứ của bite.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_burn', 'en-a2-29', 'burn', '/bɝːn/', 'A2', 'cháy; đốt cháy; bỏng; làm bỏng; vết bỏng', 'v.', 'burning (adj.), burner (n.), burnt (adj.)', NULL, 'Dạng quá khứ và quá khứ phân từ có thể dùng burnt hoặc burned.', 'A small fire burned quietly in the fireplace.', NULL, 'Một đốm lửa nhỏ đang cháy êm đềm trong lò sưởi.', '{"wordId":"burn","ukIpa":"/bɜːn/","usIpa":"/bɝːn/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To produce flames, or destroy something with fire.","vi":"cháy; đốt cháy"},{"pos":"v.","en":"To damage skin or other material through heat.","vi":"bỏng; làm bỏng"},{"pos":"n.","en":"An injury caused by heat, chemicals, or electricity.","vi":"vết bỏng"}],"examples":[{"en":"A small fire burned quietly in the fireplace.","vi":"Một đốm lửa nhỏ đang cháy êm đềm trong lò sưởi.","audioKind":"ex"},{"en":"Burning fossil fuels releases greenhouse gases, making cleaner energy sources essential for environmental protection.","vi":"Việc đốt nhiên liệu hóa thạch giải phóng khí nhà kính, khiến các nguồn năng lượng sạch hơn trở nên vô cùng quan trọng đối với công tác bảo vệ môi trường.","audioKind":"ex2"}],"collocations":[{"en":"burn fossil fuels","vi":"đốt nhiên liệu hóa thạch"},{"en":"burn calories","vi":"đốt cháy calo"},{"en":"burn your hand","vi":"bỏng tay"},{"en":"a severe burn","vi":"vết bỏng nặng"}],"wordFamily":["burning (adj.)","burner (n.)","burnt (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ có thể dùng burnt hoặc burned.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_knock', 'en-a2-29', 'knock', '/nɑːk/', 'A2', 'gõ; gõ cửa; va phải; đụng ngã; tiếng gõ; cú đánh', 'v.', NULL, 'Đồng nghĩa: tap', 'Chữ k ở đầu từ không phát âm; gõ cửa dùng knock on hoặc at the door.', 'Please knock on the door before you come in.', NULL, 'Xin vui lòng gõ cửa trước khi bạn bước vào.', '{"wordId":"knock","ukIpa":"/nɒk/","usIpa":"/nɑːk/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to hit a surface, especially a door, to make a sound","vi":"gõ; gõ cửa"},{"pos":"v.","en":"to hit something accidentally, often making it move or fall","vi":"va phải; đụng ngã"},{"pos":"n.","en":"a sound or blow caused by hitting something","vi":"tiếng gõ; cú đánh"}],"examples":[{"en":"Please knock on the door before you come in.","vi":"Xin vui lòng gõ cửa trước khi bạn bước vào.","audioKind":"ex"},{"en":"Strong winds can knock down trees, causing serious disruption to transport networks in urban areas.","vi":"Gió lớn có thể quật ngã cây cối, gây gián đoạn nghiêm trọng cho các mạng lưới giao thông ở khu vực đô thị.","audioKind":"ex2"}],"collocations":[{"en":"knock on the door","vi":"gõ cửa"},{"en":"knock something over","vi":"làm rơi vỡ vật gì; đánh đổ"},{"en":"knock down","vi":"đánh gục; phá bỏ"},{"en":"a loud knock","vi":"tiếng gõ lớn"}],"wordFamily":[],"synonyms":["tap"],"antonyms":[],"tipVi":"Chữ k ở đầu từ không phát âm; gõ cửa dùng knock on hoặc at the door.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sneaker', 'en-a2-29', 'sneaker', '/ˈsniːkɚ/', 'A2', 'giày thể thao; giày vải đế cao su', 'n.', NULL, 'Đồng nghĩa: trainer', 'Tiếng Mỹ thường dùng sneakers, trong khi tiếng Anh-Anh hay gọi là trainers.', 'One sneaker was hiding under the kitchen chair.', NULL, 'Một chiếc giày thể thao đang nằm ẩn dưới cái ghế bếp.', '{"wordId":"sneaker","ukIpa":"/ˈsniːkə/","usIpa":"/ˈsniːkɚ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A comfortable shoe with a rubber sole, worn for exercise.","vi":"giày thể thao; giày vải đế cao su"}],"examples":[{"en":"One sneaker was hiding under the kitchen chair.","vi":"Một chiếc giày thể thao đang nằm ẩn dưới cái ghế bếp.","audioKind":"ex"},{"en":"A well-designed sneaker can provide support during exercise, although suitable footwear varies according to the activity.","vi":"Một đôi giày thể thao được thiết kế tốt có thể hỗ trợ trong lúc tập luyện, mặc dù các loại giày dép phù hợp sẽ thay đổi tùy theo hoạt động.","audioKind":"ex2"}],"collocations":[{"en":"a pair of sneakers","vi":"một đôi giày thể thao"},{"en":"running sneakers","vi":"giày chạy bộ"},{"en":"wear sneakers","vi":"mang giày thể thao"}],"wordFamily":[],"synonyms":["trainer"],"antonyms":[],"tipVi":"Tiếng Mỹ thường dùng sneakers, trong khi tiếng Anh-Anh hay gọi là trainers.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bell', 'en-a2-29', 'bell', '/bel/', 'A2', 'cái chuông; cái cồng; tiếng chuông', 'n.', NULL, NULL, 'Cụm ring a bell còn có nghĩa là "nghe quen quen; gợi nhớ lại điều gì đó".', 'The bicycle bell rang as a cyclist approached.', NULL, 'Tiếng chuông xe đạp vang lên khi một người đi xe đạp đến gần.', '{"wordId":"bell","ukIpa":"/bel/","usIpa":"/bel/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a hollow metal object that rings when struck","vi":"cái chuông; cái cồng"},{"pos":"n.","en":"the ringing sound made by a bell","vi":"tiếng chuông"}],"examples":[{"en":"The bicycle bell rang as a cyclist approached.","vi":"Tiếng chuông xe đạp vang lên khi một người đi xe đạp đến gần.","audioKind":"ex"},{"en":"In many schools, a bell marks the beginning and end of each lesson.","vi":"Ở nhiều trường học, tiếng chuông đánh dấu thời điểm bắt đầu và kết thúc của mỗi tiết học.","audioKind":"ex2"}],"collocations":[{"en":"ring a bell","vi":"rung chuông; đánh chuông"},{"en":"door bell","vi":"chuông cửa"},{"en":"church bell","vi":"chuông nhà thờ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm ring a bell còn có nghĩa là \"nghe quen quen; gợi nhớ lại điều gì đó\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bright', 'en-a2-29', 'bright', '/braɪt/', 'A2', 'sáng sủa; rực rỡ; thông minh; sáng dạ; tươi sáng; đầy triển vọng', 'adj.', 'brightly (adv.), brightness (n.), brighten (v.)', 'Trái nghĩa: dim, dull', 'Tính từ "bright" dùng để chỉ ánh sáng mạnh, trái ngược với "dim" (mờ ảo).', 'Bright sunlight streamed through the kitchen window this morning.', NULL, 'Ánh nắng rực rỡ chiếu qua cửa sổ nhà bếp vào sáng nay.', '{"wordId":"bright","ukIpa":"/braɪt/","usIpa":"/braɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"giving much light or having a strong, clear colour","vi":"sáng sủa; rực rỡ"},{"pos":"adj.","en":"quick to learn and understand things","vi":"thông minh; sáng dạ"},{"pos":"adj.","en":"promising success or showing happiness","vi":"tươi sáng; đầy triển vọng"}],"examples":[{"en":"Bright sunlight streamed through the kitchen window this morning.","vi":"Ánh nắng rực rỡ chiếu qua cửa sổ nhà bếp vào sáng nay.","audioKind":"ex"},{"en":"Access to quality education can give young people a bright future regardless of their family background.","vi":"Việc tiếp cận giáo dục chất lượng có thể mang lại cho giới trẻ một tương lai tươi sáng bất kể hoàn cảnh gia đình của họ.","audioKind":"ex2"}],"collocations":[{"en":"bright colours","vi":"màu sắc rực rỡ"},{"en":"bright student","vi":"học sinh thông minh"},{"en":"bright future","vi":"tương lai tươi sáng"},{"en":"bright sunlight","vi":"ánh nắng chói chang"}],"wordFamily":["brightly (adv.)","brightness (n.)","brighten (v.)"],"synonyms":[],"antonyms":["dim","dull"],"tipVi":"Tính từ \"bright\" dùng để chỉ ánh sáng mạnh, trái ngược với \"dim\" (mờ ảo).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glove', 'en-a2-29', 'glove', '/ɡlʌv/', 'A2', 'găng tay; bao tay', 'n.', 'gloved (adj.)', NULL, 'Cụm từ chỉ một đôi găng tay là "a pair of gloves", cần lưu ý từ "gloves" luôn ở dạng số nhiều.', 'I found my missing glove under the kitchen chair.', NULL, 'Tôi tìm thấy chiếc găng tay bị thất lạc của mình dưới chiếc ghế trong bếp.', '{"wordId":"glove","ukIpa":"/ɡlʌv/","usIpa":"/ɡlʌv/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A hand covering with separate sections for fingers and thumb.","vi":"găng tay; bao tay"}],"examples":[{"en":"I found my missing glove under the kitchen chair.","vi":"Tôi tìm thấy chiếc găng tay bị thất lạc của mình dưới chiếc ghế trong bếp.","audioKind":"ex"},{"en":"Healthcare workers should change disposable gloves between patients to reduce the risk of spreading infections.","vi":"Nhân viên y tế nên thay găng tay dùng một lần giữa các bệnh nhân để giảm nguy cơ lây lan mầm bệnh.","audioKind":"ex2"}],"collocations":[{"en":"a pair of gloves","vi":"một đôi găng tay"},{"en":"disposable gloves","vi":"găng tay dùng một lần"},{"en":"protective gloves","vi":"găng tay bảo hộ"},{"en":"boxing gloves","vi":"găng tay đấm bốc"}],"wordFamily":["gloved (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm từ chỉ một đôi găng tay là \"a pair of gloves\", cần lưu ý từ \"gloves\" luôn ở dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_complete', 'en-a2-29', 'complete', '/kəmˈpliːt/', 'A2', 'hoàn thành; điền xong; hoàn chỉnh; đầy đủ; hoàn toàn; trọn vẹn', 'v.', 'completion (n.), completely (adv.), incomplete (adj.)', 'Đồng nghĩa: finish, entire · Trái nghĩa: incomplete, partial', '"Complete a form" có nghĩa là điền thông tin vào mẫu đơn chứ không phải là tạo ra biểu mẫu đó.', 'I completed the puzzle just before dinner was ready.', NULL, 'Tôi vừa hoàn thành bức tranh ghép hình ngay trước khi bữa tối sẵn sàng.', '{"wordId":"complete","ukIpa":"/kəmˈpliːt/","usIpa":"/kəmˈpliːt/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to finish doing something or filling in information","vi":"hoàn thành; điền xong"},{"pos":"adj.","en":"having every necessary part, with nothing missing","vi":"hoàn chỉnh; đầy đủ"},{"pos":"adj.","en":"total, without any limit or exception","vi":"hoàn toàn; trọn vẹn"}],"examples":[{"en":"I completed the puzzle just before dinner was ready.","vi":"Tôi vừa hoàn thành bức tranh ghép hình ngay trước khi bữa tối sẵn sàng.","audioKind":"ex"},{"en":"Students who complete vocational training often gain practical skills that help them enter the workforce more confidently.","vi":"Những học sinh hoàn thành khóa đào tạo nghề thường tích lũy được các kỹ năng thực tế giúp họ tự tin gia nhập thị trường lao động hơn.","audioKind":"ex2"}],"collocations":[{"en":"complete a course","vi":"hoàn thành một khóa học"},{"en":"complete a form","vi":"điền vào một mẫu đơn"},{"en":"a complete set","vi":"một bộ hoàn chỉnh"},{"en":"a complete success","vi":"một thành công trọn vẹn"}],"wordFamily":["completion (n.)","completely (adv.)","incomplete (adj.)"],"synonyms":["finish","entire"],"antonyms":["incomplete","partial"],"tipVi":"\"Complete a form\" có nghĩa là điền thông tin vào mẫu đơn chứ không phải là tạo ra biểu mẫu đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kiss', 'en-a2-29', 'kiss', '/kɪs/', 'A2', 'hôn; chạm môi; nụ hôn', 'v.', NULL, NULL, 'Cấu trúc diễn tả hành động hôn lên má ai đó là "kiss someone on the cheek".', 'She kissed her daughter gently before leaving for work.', NULL, 'Cô ấy nhẹ nhàng hôn con gái trước khi đi làm.', '{"wordId":"kiss","ukIpa":"/kɪs/","usIpa":"/kɪs/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to touch someone or something with your lips affectionately","vi":"hôn; chạm môi"},{"pos":"n.","en":"an affectionate touch made with the lips","vi":"nụ hôn"}],"examples":[{"en":"She kissed her daughter gently before leaving for work.","vi":"Cô ấy nhẹ nhàng hôn con gái trước khi đi làm.","audioKind":"ex"},{"en":"In some cultures, a kiss on the cheek is a common greeting between close friends.","vi":"Ở một số nền văn hóa, một nụ hôn lên má là cách chào hỏi phổ biến giữa những người bạn thân thiết.","audioKind":"ex2"}],"collocations":[{"en":"kiss someone goodbye","vi":"hôn ai đó chào tạm biệt"},{"en":"give someone a kiss","vi":"tặng ai đó một nụ hôn"},{"en":"a kiss on the cheek","vi":"nụ hôn lên má"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc diễn tả hành động hôn lên má ai đó là \"kiss someone on the cheek\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_madam', 'en-a2-29', 'madam', '/ˈmædəm/', 'A2', 'thưa bà; thưa cô; phu nhân (cách xưng hô lịch sự)', 'n.', NULL, 'Đồng nghĩa: ma''am', 'Sử dụng khi gọi phụ nữ một cách trang trọng; thường không dùng trong giao tiếp đời thường giữa những người quen biết.', 'Would you like a table by the window, madam?', NULL, 'Bà có muốn ngồi bàn gần cửa sổ không ạ?', '{"wordId":"madam","ukIpa":"/ˈmædəm/","usIpa":"/ˈmædəm/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A formal, polite way of addressing a woman.","vi":"thưa bà; thưa cô; phu nhân (cách xưng hô lịch sự)"}],"examples":[{"en":"Would you like a table by the window, madam?","vi":"Bà có muốn ngồi bàn gần cửa sổ không ạ?","audioKind":"ex"},{"en":"In formal customer service settings, staff may address a female customer as madam to show respect.","vi":"Trong các tình huống dịch vụ khách hàng trang trọng, nhân viên có thể gọi khách hàng nữ là madam để thể hiện sự tôn trọng.","audioKind":"ex2"}],"collocations":[{"en":"Dear Madam","vi":"Kính gửi Quý bà"},{"en":"yes, madam","vi":"vâng, thưa bà"},{"en":"Madam Chair","vi":"Chủ tịch (nữ) tọa đàm"}],"wordFamily":[],"synonyms":["ma''am"],"antonyms":[],"tipVi":"Sử dụng khi gọi phụ nữ một cách trang trọng; thường không dùng trong giao tiếp đời thường giữa những người quen biết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_missed', 'en-a2-29', 'missed', '/mɪst/', 'A2', 'bỏ lỡ; trễ; trượt; không chú ý; nhớ nhung', 'v.', 'miss (v.), missing (adj.)', NULL, 'Là dạng quá khứ và quá phân từ của miss; đuôi -ed phát âm là /t/.', 'We missed the bus and walked home together.', NULL, 'Chúng tôi lỡ chuyến xe buýt và cùng nhau đi bộ về nhà.', '{"wordId":"missed","ukIpa":"/mɪst/","usIpa":"/mɪst/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"failed to catch, attend, or take advantage of something","vi":"bỏ lỡ; trễ"},{"pos":"v.","en":"failed to hit or notice someone or something","vi":"trượt; không chú ý"},{"pos":"v.","en":"felt sad because someone or something was absent","vi":"nhớ nhung"}],"examples":[{"en":"We missed the bus and walked home together.","vi":"Chúng tôi lỡ chuyến xe buýt và cùng nhau đi bộ về nhà.","audioKind":"ex"},{"en":"Students who missed lessons due to illness should receive additional support to catch up with their classmates.","vi":"Những học sinh bỏ lỡ bài học do ốm đau nên nhận được sự hỗ trợ bổ sung để theo kịp các bạn cùng lớp.","audioKind":"ex2"}],"collocations":[{"en":"missed opportunity","vi":"cơ hội bị bỏ lỡ"},{"en":"missed call","vi":"cuộc gọi nhỡ"},{"en":"missed deadline","vi":"hạn chót bị lỡ"}],"wordFamily":["miss (v.)","missing (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Là dạng quá khứ và quá phân từ của miss; đuôi -ed phát âm là /t/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slice', 'en-a2-29', 'slice', '/slaɪs/', 'A2', 'miếng mỏng; lát; cắt thành lát mỏng; một phần; phần chia', 'n.', 'slicer (n.), sliced (adj.)', NULL, 'slice nhấn mạnh lát được cắt ra; piece mang nghĩa chung chung là một miếng hoặc một phần.', 'She put a slice of lemon in my tea.', NULL, 'Cô ấy bỏ một lát chanh vào trà của tôi.', '{"wordId":"slice","ukIpa":"/slaɪs/","usIpa":"/slaɪs/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a thin, flat piece cut from something larger","vi":"miếng mỏng; lát"},{"pos":"v.","en":"to cut something into thin, flat pieces","vi":"cắt thành lát mỏng"},{"pos":"n.","en":"a share or portion of something","vi":"một phần; phần chia"}],"examples":[{"en":"She put a slice of lemon in my tea.","vi":"Cô ấy bỏ một lát chanh vào trà của tôi.","audioKind":"ex"},{"en":"Housing costs consume a large slice of household income, leaving many families with little money for leisure.","vi":"Chi phí nhà ở chiếm một phần lớn trong thu nhập hộ gia đình, khiến nhiều gia đình có rất ít tiền cho việc giải trí.","audioKind":"ex2"}],"collocations":[{"en":"a slice of bread","vi":"một lát bánh mì"},{"en":"slice thinly","vi":"cắt thành lát mỏng"},{"en":"a slice of the market","vi":"một phần thị phần"}],"wordFamily":["slicer (n.)","sliced (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"slice nhấn mạnh lát được cắt ra; piece mang nghĩa chung chung là một miếng hoặc một phần.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_less', 'en-a2-29', 'less', '/les/', 'A2', 'ít hơn (lượng nhỏ hơn); ít hơn; kém hơn; lượng ít hơn', 'det.', NULL, 'Trái nghĩa: more', 'Dùng less trước danh từ không đếm được; danh từ đếm được số nhiều thường dùng fewer.', 'Please put less sugar in my tea this time.', NULL, 'Lần này làm ơn cho ít đường hơn vào trà của tôi.', '{"wordId":"less","ukIpa":"/les/","usIpa":"/les/","cefr":"A2","topic":"daily","senses":[{"pos":"det.","en":"a smaller amount of something","vi":"ít hơn (lượng nhỏ hơn)"},{"pos":"adv.","en":"to a smaller degree or extent","vi":"ít hơn; kém hơn"},{"pos":"pron.","en":"a smaller amount","vi":"lượng ít hơn"}],"examples":[{"en":"Please put less sugar in my tea this time.","vi":"Lần này làm ơn cho ít đường hơn vào trà của tôi.","audioKind":"ex"},{"en":"Households can use less energy by improving insulation and choosing appliances that consume electricity more efficiently.","vi":"Các hộ gia đình có thể tiêu thụ ít năng lượng hơn bằng cách cải thiện lớp cách nhiệt và chọn các thiết bị điện tiết kiệm điện hơn.","audioKind":"ex2"}],"collocations":[{"en":"less than","vi":"ít hơn"},{"en":"less likely","vi":"ít có khả năng hơn"},{"en":"less and less","vi":"ngày càng ít đi"},{"en":"no less than","vi":"không ít hơn; tới tận"}],"wordFamily":[],"synonyms":[],"antonyms":["more"],"tipVi":"Dùng less trước danh từ không đếm được; danh từ đếm được số nhiều thường dùng fewer.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_broken', 'en-a2-29', 'broken', '/ˈbroʊkən/', 'A2', 'bị vỡ; bị gãy; bị hỏng; hỏng hóc; không trôi chảy; đứt quãng', 'adj.', 'break (v.), breakable (adj.), unbroken (adj.)', 'Đồng nghĩa: damaged · Trái nghĩa: intact', 'Cũng là phân từ II của break; dạng quá khứ là broke.', 'She carefully swept the broken glass into a dustpan.', NULL, 'Cô ấy cẩn thận quét những mảnh thủy tinh vỡ vào hót rác.', '{"wordId":"broken","ukIpa":"/ˈbrəʊkən/","usIpa":"/ˈbroʊkən/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Damaged by being split or separated into pieces.","vi":"bị vỡ; bị gãy"},{"pos":"adj.","en":"Not working properly because of damage.","vi":"bị hỏng; hỏng hóc"},{"pos":"adj.","en":"Spoken with difficulty and frequent pauses or errors.","vi":"không trôi chảy; đứt quãng"}],"examples":[{"en":"She carefully swept the broken glass into a dustpan.","vi":"Cô ấy cẩn thận quét những mảnh thủy tinh vỡ vào hót rác.","audioKind":"ex"},{"en":"Repairing broken household appliances rather than replacing them can reduce waste and conserve valuable natural resources.","vi":"Việc sửa chữa các thiết bị gia dụng bị hỏng thay vì vứt bỏ chúng có thể giúp giảm rác thải và bảo tồn các nguồn tài nguyên thiên nhiên quý giá.","audioKind":"ex2"}],"collocations":[{"en":"broken glass","vi":"mảnh thủy tinh vỡ"},{"en":"a broken bone","vi":"xương bị gãy"},{"en":"broken English","vi":"tiếng Anh bập bõm không trôi chảy"},{"en":"a broken promise","vi":"lời hứa không được thực hiện"}],"wordFamily":["break (v.)","breakable (adj.)","unbroken (adj.)"],"synonyms":["damaged"],"antonyms":["intact"],"tipVi":"Cũng là phân từ II của break; dạng quá khứ là broke.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sausage', 'en-a2-29', 'sausage', '/ˈsɑː.sɪdʒ/', 'A2', 'xúc xích', 'n.', NULL, NULL, 'Một chiếc xúc xích là danh từ đếm được; sausage meat chỉ phần thịt làm xúc xích, là danh từ không đếm được.', 'We grilled sausages and served them with fresh vegetables.', NULL, 'Chúng tôi nướng xúc xích và ăn kèm với rau tươi.', '{"wordId":"sausage","ukIpa":"/ˈsɒs.ɪdʒ/","usIpa":"/ˈsɑː.sɪdʒ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"finely chopped meat enclosed in a thin, tube-shaped skin","vi":"xúc xích"}],"examples":[{"en":"We grilled sausages and served them with fresh vegetables.","vi":"Chúng tôi nướng xúc xích và ăn kèm với rau tươi.","audioKind":"ex"},{"en":"Consumers are increasingly choosing vegetarian sausages as they seek alternatives to traditional meat products.","vi":"Người tiêu dùng ngày càng lựa chọn xúc xích chay khi họ tìm kiếm các giải pháp thay thế cho các sản phẩm thịt truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"grilled sausages","vi":"xúc xích nướng"},{"en":"vegetarian sausage","vi":"xúc xích chay"},{"en":"sausage meat","vi":"thịt làm xúc xích"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Một chiếc xúc xích là danh từ đếm được; sausage meat chỉ phần thịt làm xúc xích, là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hole', 'en-a2-29', 'hole', '/hoʊl/', 'A2', 'cái lỗ; hố; kẽ hở; lỗ hổng; khiếm khuyết', 'n.', NULL, 'Đồng nghĩa: opening, gap', 'hole chỉ cái lỗ; whole có nghĩa là toàn bộ, nguyên vẹn, hai từ này phát âm giống nhau.', 'There''s a small hole in my favourite sock.', NULL, 'Có một lỗ thủng nhỏ ở chiếc tất yêu thích của tôi.', '{"wordId":"hole","ukIpa":"/həʊl/","usIpa":"/hoʊl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"An opening through something or a hollow space in the ground.","vi":"cái lỗ; hố; kẽ hở"},{"pos":"n.","en":"A weakness or missing part in a plan or argument.","vi":"lỗ hổng; khiếm khuyết"}],"examples":[{"en":"There''s a small hole in my favourite sock.","vi":"Có một lỗ thủng nhỏ ở chiếc tất yêu thích của tôi.","audioKind":"ex"},{"en":"The discovery of a hole in the safety fence prompted residents to request urgent repairs.","vi":"Việc phát hiện ra một lỗ hổng ở hàng rào an toàn đã thúc đẩy cư dân yêu cầu sửa chữa gấp.","audioKind":"ex2"}],"collocations":[{"en":"dig a hole","vi":"đào hố"},{"en":"fill a hole","vi":"lấp lỗ hổng"},{"en":"a hole in the ground","vi":"cái hố trên mặt đất"},{"en":"pick holes in","vi":"vạch lá tìm sâu; bới lông tìm vết"}],"wordFamily":[],"synonyms":["opening","gap"],"antonyms":[],"tipVi":"hole chỉ cái lỗ; whole có nghĩa là toàn bộ, nguyên vẹn, hai từ này phát âm giống nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bookcase', 'en-a2-29', 'bookcase', '/ˈbʊkkeɪs/', 'A2', 'tủ sách; giá sách lớn', 'n.', NULL, NULL, 'bookcase chỉ toàn bộ chiếc tủ đựng sách, còn bookshelf chỉ tấm ván kệ sách hoặc một tầng để sách.', 'She keeps her favourite novels in a wooden bookcase.', NULL, 'Cô ấy giữ những cuốn tiểu thuyết yêu thích của mình trong một tủ sách bằng gỗ.', '{"wordId":"bookcase","ukIpa":"/ˈbʊkkeɪs/","usIpa":"/ˈbʊkkeɪs/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A piece of furniture with shelves for books.","vi":"tủ sách; giá sách lớn"}],"examples":[{"en":"She keeps her favourite novels in a wooden bookcase.","vi":"Cô ấy giữ những cuốn tiểu thuyết yêu thích của mình trong một tủ sách bằng gỗ.","audioKind":"ex"},{"en":"Placing accessible bookcases in classrooms can encourage children to read independently during their free time.","vi":"Việc đặt các tủ sách dễ tiếp cận trong lớp học có thể khuyến khích trẻ em đọc sách một cách độc lập trong thời gian rảnh.","audioKind":"ex2"}],"collocations":[{"en":"wooden bookcase","vi":"tủ sách bằng gỗ"},{"en":"built-in bookcase","vi":"tủ sách âm tường"},{"en":"a bookcase full of books","vi":"tủ sách đầy ắp sách"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"bookcase chỉ toàn bộ chiếc tủ đựng sách, còn bookshelf chỉ tấm ván kệ sách hoặc một tầng để sách.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_brush', 'en-a2-29', 'brush', '/brʌʃ/', 'A2', 'bàn chải; cọ vẽ; chải; quét; làm sạch bằng bàn chải; chạm nhẹ; lướt qua', 'n.', 'brushing (n.), toothbrush (n.), hairbrush (n.)', NULL, 'brush against biểu thị chạm nhẹ; brush up on biểu thị ôn tập.', 'Use a soft brush to clean your muddy shoes.', NULL, 'Hãy dùng một chiếc bàn chải mềm để làm sạch đôi giày dính bùn của bạn.', '{"wordId":"brush","ukIpa":"/brʌʃ/","usIpa":"/brʌʃ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a tool with bristles used for cleaning, painting or arranging hair","vi":"bàn chải; cọ vẽ"},{"pos":"v.","en":"to clean, paint or arrange something using a brush","vi":"chải; quét; làm sạch bằng bàn chải"},{"pos":"v.","en":"to touch something lightly while moving past it","vi":"chạm nhẹ; lướt qua"}],"examples":[{"en":"Use a soft brush to clean your muddy shoes.","vi":"Hãy dùng một chiếc bàn chải mềm để làm sạch đôi giày dính bùn của bạn.","audioKind":"ex"},{"en":"Children should learn to brush their teeth properly, as good habits can prevent many dental problems.","vi":"Trẻ em nên học cách chải răng đúng cách, bởi vì những thói quen tốt có thể ngăn ngừa nhiều vấn đề về răng miệng.","audioKind":"ex2"}],"collocations":[{"en":"brush your teeth","vi":"chải răng"},{"en":"brush your hair","vi":"chải tóc"},{"en":"a paint brush","vi":"cọ vẽ; chổi sơn"},{"en":"brush against","vi":"chạm nhẹ vào; lướt qua"}],"wordFamily":["brushing (n.)","toothbrush (n.)","hairbrush (n.)"],"synonyms":[],"antonyms":[],"tipVi":"brush against biểu thị chạm nhẹ; brush up on biểu thị ôn tập.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_simple', 'en-a2-29', 'simple', '/ˈsɪmpəl/', 'A2', 'đơn giản; dễ hiểu; dễ làm; mộc mạc; giản dị; không cầu kỳ', 'adj.', 'simply (adv.), simplicity (n.), simplify (v.), simplification (n.)', 'Đồng nghĩa: easy, straightforward, uncomplicated · Trái nghĩa: complicated, complex', 'simple có thể chỉ sự dễ dàng hoặc nét mộc mạc, không nhất thiết mang hàm ý nghèo nàn, thô sơ.', 'This simple recipe takes just ten minutes to prepare.', NULL, 'Công thức đơn giản này chỉ mất vỏn vẹn mười phút để chuẩn bị.', '{"wordId":"simple","ukIpa":"/ˈsɪmpəl/","usIpa":"/ˈsɪmpəl/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Easy to understand or do; not complicated.","vi":"đơn giản; dễ hiểu; dễ làm"},{"pos":"adj.","en":"Plain and without unnecessary decoration or extra features.","vi":"mộc mạc; giản dị; không cầu kỳ"}],"examples":[{"en":"This simple recipe takes just ten minutes to prepare.","vi":"Công thức đơn giản này chỉ mất vỏn vẹn mười phút để chuẩn bị.","audioKind":"ex"},{"en":"Schools should provide simple instructions so that all students can complete classroom tasks independently.","vi":"Nhà trường nên cung cấp các hướng dẫn dễ hiểu để mọi học sinh đều có thể tự hoàn thành nhiệm vụ trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"simple solution","vi":"giải pháp đơn giản"},{"en":"simple instructions","vi":"hướng dẫn dễ hiểu"},{"en":"keep it simple","vi":"giữ cho mọi thứ đơn giản"}],"wordFamily":["simply (adv.)","simplicity (n.)","simplify (v.)","simplification (n.)"],"synonyms":["easy","straightforward","uncomplicated"],"antonyms":["complicated","complex"],"tipVi":"simple có thể chỉ sự dễ dàng hoặc nét mộc mạc, không nhất thiết mang hàm ý nghèo nàn, thô sơ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_yet', 'en-a2-29', 'yet', '/jet/', 'A2', 'chưa; còn; đến nay (thường dùng trong câu hỏi và câu phủ định); nhưng; tuy nhiên; mặc dù vậy; thêm nữa; lại còn', 'adv.', NULL, NULL, 'Biểu thị "chưa" thường đặt ở cuối câu phủ định; trong câu hỏi có thể mang nghĩa "đã".', 'I haven''t finished dinner yet, so please wait.', NULL, 'Mình vẫn chưa ăn xong bữa tối, vì thế hãy đợi một lát nhé.', '{"wordId":"yet","ukIpa":"/jet/","usIpa":"/jet/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"Up to now, especially in questions and negative statements.","vi":"chưa; còn; đến nay (thường dùng trong câu hỏi và câu phủ định)"},{"pos":"conj.","en":"But, despite what has just been stated.","vi":"nhưng; tuy nhiên; mặc dù vậy"},{"pos":"adv.","en":"Used to emphasize a further increase or addition.","vi":"thêm nữa; lại còn"}],"examples":[{"en":"I haven''t finished dinner yet, so please wait.","vi":"Mình vẫn chưa ăn xong bữa tối, vì thế hãy đợi một lát nhé.","audioKind":"ex"},{"en":"Renewable energy is becoming cheaper, yet many countries still depend heavily on fossil fuels.","vi":"Năng lượng tái tạo đang ngày càng trở nên rẻ hơn, thế nhưng nhiều quốc gia vẫn phụ thuộc rất nhiều vào nhiên liệu hóa thạch.","audioKind":"ex2"}],"collocations":[{"en":"not yet","vi":"vẫn chưa"},{"en":"have yet to do","vi":"vẫn chưa làm gì"},{"en":"yet another","vi":"lại thêm một... nữa"},{"en":"better yet","vi":"tuyệt vời hơn nữa; tốt hơn hết là"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Biểu thị \"chưa\" thường đặt ở cuối câu phủ định; trong câu hỏi có thể mang nghĩa \"đã\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jewelry', 'en-a2-29', 'jewelry', '/ˈdʒuːəlri/', 'A2', 'trang sức; đồ trang trí quý giá', 'n.', 'jewel (n.), jeweler (n.)', NULL, 'Là cách viết theo kiểu Mỹ, kiểu Anh là jewellery; đây là danh từ không đếm được, dùng từ piece để đếm.', 'She keeps her jewelry in a small wooden box.', NULL, 'Cô ấy cất trang sức của mình trong một chiếc hộp gỗ nhỏ.', '{"wordId":"jewelry","ukIpa":"/ˈdʒuːəlri/","usIpa":"/ˈdʒuːəlri/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"decorative objects worn on the body, such as rings and necklaces","vi":"trang sức; đồ trang trí quý giá"}],"examples":[{"en":"She keeps her jewelry in a small wooden box.","vi":"Cô ấy cất trang sức của mình trong một chiếc hộp gỗ nhỏ.","audioKind":"ex"},{"en":"Consumers increasingly want assurance that the materials used in jewelry are sourced responsibly and without environmental damage.","vi":"Người tiêu dùng ngày càng muốn được đảm bảo rằng các nguyên liệu dùng làm trang sức có nguồn gốc minh bạch và không gây tổn hại đến môi trường.","audioKind":"ex2"}],"collocations":[{"en":"a piece of jewelry","vi":"một món đồ trang sức"},{"en":"handmade jewelry","vi":"đồ trang sức thủ công"},{"en":"gold jewelry","vi":"trang sức vàng"},{"en":"costume jewelry","vi":"đồ trang sức giả; trang sức xi mạ"}],"wordFamily":["jewel (n.)","jeweler (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là cách viết theo kiểu Mỹ, kiểu Anh là jewellery; đây là danh từ không đếm được, dùng từ piece để đếm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_refuse', 'en-a2-29', 'refuse', '/rɪˈfjuːz/', 'A2', 'từ chối; khước từ; rác thải; phế liệu', 'v.', 'refusal (n.)', 'Đồng nghĩa: decline, reject · Trái nghĩa: accept', 'Danh từ đọc /ˈrefjuːs/; động từ theo sau là to do, không đi với doing.', 'She refused to leave without her favourite blue umbrella.', NULL, 'Cô ấy từ chối rời đi mà không có chiếc ô màu xanh yêu thích của mình.', '{"wordId":"refuse","ukIpa":"/rɪˈfjuːz/","usIpa":"/rɪˈfjuːz/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to say that you will not do or accept something","vi":"từ chối; khước từ"},{"pos":"n.","en":"unwanted waste material that people throw away","vi":"rác thải; phế liệu"}],"examples":[{"en":"She refused to leave without her favourite blue umbrella.","vi":"Cô ấy từ chối rời đi mà không có chiếc ô màu xanh yêu thích của mình.","audioKind":"ex"},{"en":"Local authorities may refuse permission for developments that threaten wildlife habitats or increase flood risks.","vi":"Các cơ quan địa phương có thể từ chối cấp phép cho các dự án phát triển đe dọa môi trường sống của động vật hoang dã hoặc làm tăng nguy cơ ngập lụt.","audioKind":"ex2"}],"collocations":[{"en":"refuse to do something","vi":"từ chối làm điều gì đó"},{"en":"refuse an offer","vi":"từ chối một lời đề nghị"},{"en":"refuse permission","vi":"từ chối cấp phép"},{"en":"refuse collection","vi":"thu gom rác thải"}],"wordFamily":["refusal (n.)"],"synonyms":["decline","reject"],"antonyms":["accept"],"tipVi":"Danh từ đọc /ˈrefjuːs/; động từ theo sau là to do, không đi với doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lazy', 'en-a2-29', 'lazy', '/ˈleɪzi/', 'A2', 'lười biếng; biếng nhác; thư thái; nhàn nhã', 'adj.', 'laziness (n.), lazily (adv.), laze (v.)', 'Đồng nghĩa: idle · Trái nghĩa: hardworking, industrious', '"lazy afternoon" dùng để chỉ buổi chiều thư thái, không nhất thiết mang sắc thái tiêu cực.', 'I felt too lazy to cook dinner tonight.', NULL, 'Tôi thấy lười nấu bữa tối vào tối nay.', '{"wordId":"lazy","ukIpa":"/ˈleɪzi/","usIpa":"/ˈleɪzi/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"unwilling to work or make an effort","vi":"lười biếng; biếng nhác"},{"pos":"adj.","en":"relaxed and involving little activity","vi":"thư thái; nhàn nhã"}],"examples":[{"en":"I felt too lazy to cook dinner tonight.","vi":"Tôi thấy lười nấu bữa tối vào tối nay.","audioKind":"ex"},{"en":"Students who struggle with homework should not automatically be considered lazy, as learning difficulties may be involved.","vi":"Không nên vội vàng cho rằng những học sinh gặp khó khăn với bài tập về nhà là lười biếng, bởi vì có thể liên quan đến các vấn đề học tập khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"too lazy to","vi":"lười đến mức không muốn"},{"en":"a lazy afternoon","vi":"một buổi chiều thư thái"},{"en":"feel lazy","vi":"cảm thấy lười biếng"}],"wordFamily":["laziness (n.)","lazily (adv.)","laze (v.)"],"synonyms":["idle"],"antonyms":["hardworking","industrious"],"tipVi":"\"lazy afternoon\" dùng để chỉ buổi chiều thư thái, không nhất thiết mang sắc thái tiêu cực.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anywhere', 'en-a2-29', 'anywhere', '/ˈeniwer/', 'A2', 'ở bất cứ đâu; đến bất cứ nơi nào; ở bất cứ nơi nào (dùng trong câu hỏi và câu phủ định)', 'adv.', NULL, 'Trái nghĩa: nowhere', 'Là trạng từ bất định, thường không đứng độc lập làm danh từ; "anywhere else" nghĩa là nơi khác.', 'You can sit anywhere you like in this room.', NULL, 'Bạn có thể ngồi ở bất cứ chỗ nào bạn thích trong căn phòng này.', '{"wordId":"anywhere","ukIpa":"/ˈeniweə/","usIpa":"/ˈeniwer/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"in or to any place","vi":"ở bất cứ đâu; đến bất cứ nơi nào"},{"pos":"adv.","en":"in any place, used in questions and negative statements","vi":"ở bất cứ nơi nào (dùng trong câu hỏi và câu phủ định)"}],"examples":[{"en":"You can sit anywhere you like in this room.","vi":"Bạn có thể ngồi ở bất cứ chỗ nào bạn thích trong căn phòng này.","audioKind":"ex"},{"en":"Reliable internet access allows employees to work from anywhere, reducing the need for daily commuting.","vi":"Truy cập Internet ổn định cho phép nhân viên làm việc từ bất kỳ đâu, giảm bớt nhu cầu đi lại đi làm mỗi ngày.","audioKind":"ex2"}],"collocations":[{"en":"anywhere else","vi":"bất cứ nơi nào khác"},{"en":"from anywhere","vi":"từ bất cứ đâu"},{"en":"hardly anywhere","vi":"hầu như không ở đâu"}],"wordFamily":[],"synonyms":[],"antonyms":["nowhere"],"tipVi":"Là trạng từ bất định, thường không đứng độc lập làm danh từ; \"anywhere else\" nghĩa là nơi khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_29_1', 'en-a2-29', 'Cách dùng “madam” (n.) — thưa bà; thưa cô; phu nhân (cách xưng hô lịch sự)', 'Dear Madam  ·  yes, madam  ·  Madam Chair', 'Sử dụng khi gọi phụ nữ một cách trang trọng; thường không dùng trong giao tiếp đời thường giữa những người quen biết.', 'Đồng nghĩa: ma''am', '[{"hanzi":"Would you like a table by the window, madam?","pinyin":"","meaning":"Bà có muốn ngồi bàn gần cửa sổ không ạ?"},{"hanzi":"In formal customer service settings, staff may address a female customer as madam to show respect.","pinyin":"","meaning":"Trong các tình huống dịch vụ khách hàng trang trọng, nhân viên có thể gọi khách hàng nữ là madam để thể hiện sự tôn trọng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_29_2', 'en-a2-29', 'Cách dùng “sausage” (n.) — xúc xích', 'grilled sausages  ·  vegetarian sausage  ·  sausage meat', 'Một chiếc xúc xích là danh từ đếm được; sausage meat chỉ phần thịt làm xúc xích, là danh từ không đếm được.', NULL, '[{"hanzi":"We grilled sausages and served them with fresh vegetables.","pinyin":"","meaning":"Chúng tôi nướng xúc xích và ăn kèm với rau tươi."},{"hanzi":"Consumers are increasingly choosing vegetarian sausages as they seek alternatives to traditional meat products.","pinyin":"","meaning":"Người tiêu dùng ngày càng lựa chọn xúc xích chay khi họ tìm kiếm các giải pháp thay thế cho các sản phẩm thịt truyền thống."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_29_3', 'en-a2-29', 'Cách dùng “jewelry” (n.) — trang sức; đồ trang trí quý giá', 'a piece of jewelry  ·  handmade jewelry  ·  gold jewelry', 'Là cách viết theo kiểu Mỹ, kiểu Anh là jewellery; đây là danh từ không đếm được, dùng từ piece để đếm.', 'Họ từ (Word Family): jewel (n.), jeweler (n.)', '[{"hanzi":"She keeps her jewelry in a small wooden box.","pinyin":"","meaning":"Cô ấy cất trang sức của mình trong một chiếc hộp gỗ nhỏ."},{"hanzi":"Consumers increasingly want assurance that the materials used in jewelry are sourced responsibly and without environmental damage.","pinyin":"","meaning":"Người tiêu dùng ngày càng muốn được đảm bảo rằng các nguyên liệu dùng làm trang sức có nguồn gốc minh bạch và không gây tổn hại đến môi trường."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_29_4', 'en-a2-29', 'Cách dùng “bookcase” (n.) — tủ sách; giá sách lớn', 'wooden bookcase  ·  built-in bookcase  ·  a bookcase full of books', 'bookcase chỉ toàn bộ chiếc tủ đựng sách, còn bookshelf chỉ tấm ván kệ sách hoặc một tầng để sách.', NULL, '[{"hanzi":"She keeps her favourite novels in a wooden bookcase.","pinyin":"","meaning":"Cô ấy giữ những cuốn tiểu thuyết yêu thích của mình trong một tủ sách bằng gỗ."},{"hanzi":"Placing accessible bookcases in classrooms can encourage children to read independently during their free time.","pinyin":"","meaning":"Việc đặt các tủ sách dễ tiếp cận trong lớp học có thể khuyến khích trẻ em đọc sách một cách độc lập trong thời gian rảnh."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_29_1', 'en-a2-29', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
