INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_29_1_8', 'ten_a2_29_1', 'bell', 'The bicycle bell rang as a cyclist approached.', 'The bicycle bell rang as a cyclist approached.', '/bel/', 'Tiếng chuông xe đạp vang lên khi một người đi xe đạp đến gần.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_29_1_1', 'en-a2-29', 'ten_a2_29_1', 'listening', 'listening', 'The children sat in a circle on the grass.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy cẩn thận quét những mảnh thủy tinh vỡ vào hót rác.","Một đốm lửa nhỏ đang cháy êm đềm trong lò sưởi.","Tiếng chuông xe đạp vang lên khi một người đi xe đạp đến gần.","Lũ trẻ ngồi thành một vòng tròn trên bãi cỏ."]'::jsonb, 3, 'The children sat in a circle on the grass. → Lũ trẻ ngồi thành một vòng tròn trên bãi cỏ.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_29_1_2', 'en-a2-29', 'ten_a2_29_1', 'listening', 'listening', 'Pardon? I couldn''t hear you over the washing machine.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tiếng chuông xe đạp vang lên khi một người đi xe đạp đến gần.","Chiếc va-li nhỏ này dễ dàng nhét vừa bên dưới ghế ngồi trên tàu.","Ánh nắng rực rỡ chiếu qua cửa sổ nhà bếp vào sáng nay.","Xin bạn nói lại được không? Tiếng máy giặt to quá nên tôi không nghe rõ."]'::jsonb, 3, 'Pardon? I couldn''t hear you over the washing machine. → Xin bạn nói lại được không? Tiếng máy giặt to quá nên tôi không nghe rõ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_29_1_3', 'en-a2-29', 'ten_a2_29_1', 'listening', 'listening', 'This small suitcase fits easily beneath the train seat.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Vẫn còn một chút bánh ngọt để dành cho bạn đấy.","Xin bạn nói lại được không? Tiếng máy giặt to quá nên tôi không nghe rõ.","Cô ấy bỏ một lát chanh vào trà của tôi.","Chiếc va-li nhỏ này dễ dàng nhét vừa bên dưới ghế ngồi trên tàu."]'::jsonb, 3, 'This small suitcase fits easily beneath the train seat. → Chiếc va-li nhỏ này dễ dàng nhét vừa bên dưới ghế ngồi trên tàu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_29_2', 'en-a2-29', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_29_2_1', 'ten_a2_29_2', 'circle', 'Joining community activities can help older adults expand their social circle and reduce feelings of isolation.', 'Joining community activities can help older adults expand their social circle and reduce feelings of isolation.', '/ˈsɝːkəl/', 'Tham gia các hoạt động cộng đồng có thể giúp người cao tuổi mở rộng vòng tròn xã hội và giảm cảm giác cô lập.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_29_2_2', 'ten_a2_29_2', 'pardon', 'A legal pardon can help someone rebuild their life, although public acceptance may take longer.', 'A legal pardon can help someone rebuild their life, although public acceptance may take longer.', '/ˈpɑːrdən/', 'Một lệnh ân xá pháp lý có thể giúp một người làm lại cuộc đời, mặc dù sự chấp nhận từ cộng đồng có thể mất nhiều thời gian hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_29_2_3', 'ten_a2_29_2', 'easily', 'Public information should be presented clearly so that people with different literacy levels can easily understand it.', 'Public information should be presented clearly so that people with different literacy levels can easily understand it.', '/ˈiːzəli/', 'Thông tin công cộng nên được trình bày rõ ràng để những người có trình độ văn hóa khác nhau đều có thể dễ dàng hiểu được.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_29_2_4', 'ten_a2_29_2', 'bit', 'Even a small bit of practical experience can help students understand difficult scientific concepts.', 'Even a small bit of practical experience can help students understand difficult scientific concepts.', '/bɪt/', 'Ngay cả một chút kinh nghiệm thực tế nhỏ nhoi cũng có thể giúp học sinh hiểu được các khái niệm khoa học phức tạp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_29_2_5', 'ten_a2_29_2', 'burn', 'Burning fossil fuels releases greenhouse gases, making cleaner energy sources essential for environmental protection.', 'Burning fossil fuels releases greenhouse gases, making cleaner energy sources essential for environmental protection.', '/bɝːn/', 'Việc đốt nhiên liệu hóa thạch giải phóng khí nhà kính, khiến các nguồn năng lượng sạch hơn trở nên vô cùng quan trọng đối với công tác bảo vệ môi trường.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_29_2_6', 'ten_a2_29_2', 'knock', 'Strong winds can knock down trees, causing serious disruption to transport networks in urban areas.', 'Strong winds can knock down trees, causing serious disruption to transport networks in urban areas.', '/nɑːk/', 'Gió lớn có thể quật ngã cây cối, gây gián đoạn nghiêm trọng cho các mạng lưới giao thông ở khu vực đô thị.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_29_2_1', 'en-a2-29', 'ten_a2_29_2', 'listening', 'listening', 'Joining community activities can help older adults expand their social circle and reduce feelings of isolation.', NULL, 'Trong câu vừa nghe, từ “circle” mang nghĩa nào sau đây?', '["hình tròn; vòng tròn","cái chết; sự qua đời","thích hơn; ưu tiên hơn","sự lựa chọn; quyền lựa chọn"]'::jsonb, 0, '“circle” (/ˈsɝːkəl/): hình tròn; vòng tròn. Câu đầy đủ: Joining community activities can help older adults expand their social circle and reduce feelings of isolation.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_29_2_2', 'en-a2-29', 'ten_a2_29_2', 'listening', 'listening', 'A legal pardon can help someone rebuild their life, although public acceptance may take longer.', NULL, 'Trong câu vừa nghe, từ “pardon” mang nghĩa nào sau đây?', '["thuộc về Ireland; thuộc về người Ireland","xin lỗi; xin nhắc lại (lời lịch sự để yêu cầu người khác lặp lại)","hòm thư công cộng; thùng thư bưu điện","khắp mọi nơi; đâu đâu cũng có"]'::jsonb, 1, '“pardon” (/ˈpɑːrdən/): xin lỗi; xin nhắc lại (lời lịch sự để yêu cầu người khác lặp lại). Câu đầy đủ: A legal pardon can help someone rebuild their life, although public acceptance may take longer.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
