INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('eqen_a2_29_1', 'en-a2-29', NULL, 'expanded_quiz', 'vocabulary', NULL, NULL, 'Từ tiếng Anh “circle” (/ˈsɝːkəl/) có nghĩa là gì?', '["một chút; một lượng nhỏ; một miếng nhỏ","hình tròn; vòng tròn","ở bất cứ đâu; đến bất cứ nơi nào","bị vỡ; bị gãy"]'::jsonb, 1, '“circle” (n.): hình tròn; vòng tròn; vòng tròn (những người có cùng bạn bè hoặc sở thích); giới; tầng lớp; khoanh tròn; bay lượn vòng quanh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
