INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_29_2', 'en-a2-29', NULL, 'comprehensive_test', 'listening', 'Pardon? I couldn''t hear you over the washing machine.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Xin vui lòng gõ cửa trước khi bạn bước vào.","Xin bạn nói lại được không? Tiếng máy giặt to quá nên tôi không nghe rõ.","Công thức đơn giản này chỉ mất vỏn vẹn mười phút để chuẩn bị.","Có một lỗ thủng nhỏ ở chiếc tất yêu thích của tôi."]'::jsonb, 1, 'Pardon? I couldn''t hear you over the washing machine. → Xin bạn nói lại được không? Tiếng máy giặt to quá nên tôi không nghe rõ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_29_3', 'en-a2-29', NULL, 'comprehensive_test', 'listening', 'easily', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["khăn choàng cổ; khăn đội đầu","phát hiện; tìm ra","dễ dàng; không mấy khó khăn","dép đi trong nhà; giày đi trong nhà"]'::jsonb, 2, 'easily (/ˈiːzəli/) → dễ dàng; không mấy khó khăn; rõ rệt; cách biệt rõ ràng; rất có thể; khả năng cao', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_29_4', 'en-a2-29', NULL, 'comprehensive_test', 'listening', 'There is a bit of cake left for you.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Vẫn còn một chút bánh ngọt để dành cho bạn đấy.","Cô ấy từ chối rời đi mà không có chiếc ô màu xanh yêu thích của mình.","Công thức đơn giản này chỉ mất vỏn vẹn mười phút để chuẩn bị.","Tôi tìm thấy chiếc găng tay bị thất lạc của mình dưới chiếc ghế trong bếp."]'::jsonb, 0, 'There is a bit of cake left for you. → Vẫn còn một chút bánh ngọt để dành cho bạn đấy.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_29_5', 'en-a2-29', NULL, 'comprehensive_test', 'listening', 'burn', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["huấn luyện viên","cháy; đốt cháy","quốc gia Ai-len","tiền thuê nhà; tiền thuê"]'::jsonb, 1, 'burn (/bɝːn/) → cháy; đốt cháy; bỏng; làm bỏng; vết bỏng', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_29_6', 'en-a2-29', NULL, 'comprehensive_test', 'listening', 'Please knock on the door before you come in.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi vừa hoàn thành bức tranh ghép hình ngay trước khi bữa tối sẵn sàng.","Tôi tìm thấy chiếc găng tay bị thất lạc của mình dưới chiếc ghế trong bếp.","Xin vui lòng gõ cửa trước khi bạn bước vào.","Một chiếc giày thể thao đang nằm ẩn dưới cái ghế bếp."]'::jsonb, 2, 'Please knock on the door before you come in. → Xin vui lòng gõ cửa trước khi bạn bước vào.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_29_7', 'en-a2-29', NULL, 'comprehensive_test', 'listening', 'sneaker', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["mỹ phẩm; đồ trang điểm","kỳ lạ, khác thường, bất ngờ","Malaysia (một quốc gia Đông Nam Á nằm ở bán đảo Mã Lai và đảo Borneo)","giày thể thao; giày vải đế cao su"]'::jsonb, 3, 'sneaker (/ˈsniːkɚ/) → giày thể thao; giày vải đế cao su', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_29_8', 'en-a2-29', NULL, 'comprehensive_test', 'listening', 'The bicycle bell rang as a cyclist approached.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Mình vẫn chưa ăn xong bữa tối, vì thế hãy đợi một lát nhé.","Chúng tôi nướng xúc xích và ăn kèm với rau tươi.","Tiếng chuông xe đạp vang lên khi một người đi xe đạp đến gần.","Xin bạn nói lại được không? Tiếng máy giặt to quá nên tôi không nghe rõ."]'::jsonb, 2, 'The bicycle bell rang as a cyclist approached. → Tiếng chuông xe đạp vang lên khi một người đi xe đạp đến gần.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
