INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_29_18', 'en-a2-29', NULL, 'comprehensive_test', 'reading', NULL, 'Joining community activities can help older adults expand their social circle and reduce feelings of isolation.', 'Dựa vào câu trên, từ “circle” có nghĩa phù hợp nhất là gì?', '["lính; quân nhân","một nghìn; một ngàn","hình tròn; vòng tròn","ngựa vằn"]'::jsonb, 2, 'circle: hình tròn; vòng tròn; vòng tròn (những người có cùng bạn bè hoặc sở thích); giới; tầng lớp; khoanh tròn; bay lượn vòng quanh. Dịch cả câu: Tham gia các hoạt động cộng đồng có thể giúp người cao tuổi mở rộng vòng tròn xã hội và giảm cảm giác cô lập.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_29_19', 'en-a2-29', NULL, 'comprehensive_test', 'reading', NULL, 'A legal pardon can help someone rebuild their life, although public acceptance may take longer.', 'Dựa vào câu trên, từ “pardon” có nghĩa phù hợp nhất là gì?', '["tác giả; nhà văn","điểm số; kết quả","xin lỗi; xin nhắc lại (lời lịch sự để yêu cầu người khác lặp lại)","nước ngọt có gas"]'::jsonb, 2, 'pardon: xin lỗi; xin nhắc lại (lời lịch sự để yêu cầu người khác lặp lại); tha thứ; ân xá; sự ân xá; sự tha thứ. Dịch cả câu: Một lệnh ân xá pháp lý có thể giúp một người làm lại cuộc đời, mặc dù sự chấp nhận từ cộng đồng có thể mất nhiều thời gian hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_29_20', 'en-a2-29', NULL, 'comprehensive_test', 'reading', NULL, 'Public information should be presented clearly so that people with different literacy levels can easily understand it.', 'Dựa vào câu trên, từ “easily” có nghĩa phù hợp nhất là gì?', '["xuyên qua, qua lại bên trong","dễ dàng; không mấy khó khăn","dự đoán; trông đợi","con bướm"]'::jsonb, 1, 'easily: dễ dàng; không mấy khó khăn; rõ rệt; cách biệt rõ ràng; rất có thể; khả năng cao. Dịch cả câu: Thông tin công cộng nên được trình bày rõ ràng để những người có trình độ văn hóa khác nhau đều có thể dễ dàng hiểu được.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_29_21', 'en-a2-29', NULL, 'comprehensive_test', 'reading', NULL, 'Even a small bit of practical experience can help students understand difficult scientific concepts.', 'Dựa vào câu trên, từ “bit” có nghĩa phù hợp nhất là gì?', '["một chút; một lượng nhỏ; một miếng nhỏ","ghế sô-pha; ghế dài có tựa","có lẽ; chắc là","vùng biển; bờ biển"]'::jsonb, 0, 'bit: một chút; một lượng nhỏ; một miếng nhỏ; bit (đơn vị thông tin nhỏ nhất trong máy tính). Dịch cả câu: Ngay cả một chút kinh nghiệm thực tế nhỏ nhoi cũng có thể giúp học sinh hiểu được các khái niệm khoa học phức tạp.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_29_22', 'en-a2-29', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “từ chối; khước từ”', '["sort","refuse","mix","camping"]'::jsonb, 1, 'từ chối; khước từ → refuse (/rɪˈfjuːz/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_29_23', 'en-a2-29', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “lười biếng; biếng nhác”', '["main","energy","lazy","southeast"]'::jsonb, 2, 'lười biếng; biếng nhác → lazy (/ˈleɪzi/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_29_24', 'en-a2-29', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ở bất cứ đâu; đến bất cứ nơi nào”', '["anywhere","dentist","decision","hold"]'::jsonb, 0, 'ở bất cứ đâu; đến bất cứ nơi nào → anywhere (/ˈeniwer/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-30', 'en', 'Bài 30: Đời sống hằng ngày (2) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '27 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2030, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_seventh', 'en-a2-30', 'seventh', '/ˈsevənθ/', 'A2', 'thứ bảy; một phần bảy', 'num.', 'seven (num.), seventeen (num.), seventieth (num.)', NULL, 'Số thứ tự thường đi kèm với mạo từ "the"; không dùng "the" khi đã có từ hạn định chỉ sở hữu.', 'Our new flat is on the seventh floor.', NULL, 'Căn hộ mới của chúng tôi ở tầng bảy.', '{"wordId":"seventh","ukIpa":"/ˈsevənθ/","usIpa":"/ˈsevənθ/","cefr":"A2","topic":"daily","senses":[{"pos":"num.","en":"Coming after sixth and before eighth in an ordered sequence.","vi":"thứ bảy"},{"pos":"n.","en":"One of seven equal parts of something.","vi":"một phần bảy"}],"examples":[{"en":"Our new flat is on the seventh floor.","vi":"Căn hộ mới của chúng tôi ở tầng bảy.","audioKind":"ex"},{"en":"By the seventh week of the course, students were able to analyse basic scientific data independently.","vi":"Đến tuần thứ bảy của khóa học, học sinh đã có thể tự phân tích các dữ liệu khoa học cơ bản.","audioKind":"ex2"}],"collocations":[{"en":"the seventh floor","vi":"tầng bảy"},{"en":"in seventh place","vi":"đứng ở vị trí thứ bảy"},{"en":"a seventh of","vi":"một phần bảy của"}],"wordFamily":["seven (num.)","seventeen (num.)","seventieth (num.)"],"synonyms":[],"antonyms":[],"tipVi":"Số thứ tự thường đi kèm với mạo từ \"the\"; không dùng \"the\" khi đã có từ hạn định chỉ sở hữu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gardening', 'en-a2-30', 'gardening', '/ˈɡɑːrdənɪŋ/', 'A2', 'làm vườn; nghệ thuật làm vườn', 'n.', 'garden (n.), garden (v.), gardener (n.)', NULL, 'Thường là danh từ không đếm được: do some gardening.', 'My grandmother enjoys gardening on cool spring mornings.', NULL, 'Bà tôi thích làm vườn vào những buổi sáng mùa xuân mát mẻ.', '{"wordId":"gardening","ukIpa":"/ˈɡɑːdənɪŋ/","usIpa":"/ˈɡɑːrdənɪŋ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"The activity of growing and caring for plants in gardens.","vi":"làm vườn; nghệ thuật làm vườn"}],"examples":[{"en":"My grandmother enjoys gardening on cool spring mornings.","vi":"Bà tôi thích làm vườn vào những buổi sáng mùa xuân mát mẻ.","audioKind":"ex"},{"en":"Community gardening can improve urban environments while helping residents develop stronger social connections.","vi":"Hoạt động làm vườn cộng đồng có thể cải thiện môi trường đô thị đồng thời giúp cư dân phát triển các mối quan hệ xã hội khăng khít hơn.","audioKind":"ex2"}],"collocations":[{"en":"gardening tools","vi":"dụng cụ làm vườn"},{"en":"do some gardening","vi":"làm một số việc vườn tược"},{"en":"community gardening","vi":"làm vườn cộng đồng"}],"wordFamily":["garden (n.)","garden (v.)","gardener (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được: do some gardening.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_save', 'en-a2-30', 'save', '/seɪv/', 'A2', 'cứu; cứu sống; bảo vệ; tiết kiệm; dành dụm; lưu; giữ lại', 'v.', 'saving (n.), savings (n.), saver (n.)', NULL, 'save money có thể mang nghĩa là tiết kiệm tiền hoặc để dành tiền.', 'The lifeguard saved a child from the deep water.', NULL, 'Nhân viên cứu hộ đã cứu một đứa trẻ khỏi vùng nước sâu.', '{"wordId":"save","ukIpa":"/seɪv/","usIpa":"/seɪv/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To prevent someone or something from being harmed or lost.","vi":"cứu; cứu sống; bảo vệ"},{"pos":"v.","en":"To use less of something or keep money for later.","vi":"tiết kiệm; dành dụm"},{"pos":"v.","en":"To keep something for future use, especially computer data.","vi":"lưu; giữ lại"}],"examples":[{"en":"The lifeguard saved a child from the deep water.","vi":"Nhân viên cứu hộ đã cứu một đứa trẻ khỏi vùng nước sâu.","audioKind":"ex"},{"en":"Investing in reliable public transport can save commuters time and reduce household travel costs.","vi":"Đầu tư vào giao thông công cộng đáng tin cậy có thể giúp người đi làm tiết kiệm thời gian và giảm chi phí đi lại của gia đình.","audioKind":"ex2"}],"collocations":[{"en":"save a life","vi":"cứu một mạng người"},{"en":"save money","vi":"tiết kiệm tiền; để dành tiền"},{"en":"save time","vi":"tiết kiệm thời gian"},{"en":"save a file","vi":"lưu một tệp tin"}],"wordFamily":["saving (n.)","savings (n.)","saver (n.)"],"synonyms":[],"antonyms":[],"tipVi":"save money có thể mang nghĩa là tiết kiệm tiền hoặc để dành tiền.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jewellery', 'en-a2-30', 'jewellery', '/ˈdʒuːəlri/', 'A2', 'đồ trang sức; trang sức; nữ trang', 'n.', 'jewel (n.), jeweller (n.)', NULL, 'Không đếm được; một món dùng a piece of; cách viết theo kiểu Mỹ là jewelry.', 'She keeps her jewellery in a small wooden box.', NULL, 'Cô ấy cất trang sức của mình trong một chiếc hộp gỗ nhỏ.', '{"wordId":"jewellery","ukIpa":"/ˈdʒuːəlri/","usIpa":"/ˈdʒuːəlri/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Decorative objects worn on the body, such as rings and necklaces.","vi":"đồ trang sức; trang sức; nữ trang"}],"examples":[{"en":"She keeps her jewellery in a small wooden box.","vi":"Cô ấy cất trang sức của mình trong một chiếc hộp gỗ nhỏ.","audioKind":"ex"},{"en":"Traditional jewellery can reflect cultural identity while providing income for skilled craftspeople in rural communities.","vi":"Đồ trang sức truyền thống có thể phản ánh bản sắc văn hóa đồng thời tạo thu nhập cho các nghệ nhân lành nghề ở vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"a piece of jewellery","vi":"một món đồ trang sức"},{"en":"gold jewellery","vi":"trang sức bằng vàng"},{"en":"handmade jewellery","vi":"trang sức thủ công"}],"wordFamily":["jewel (n.)","jeweller (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Không đếm được; một món dùng a piece of; cách viết theo kiểu Mỹ là jewelry.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_towards', 'en-a2-30', 'towards', '/tɔːrdz/', 'A2', 'về phía, hướng về ai hoặc cái gì; đối với, về phía (thái độ đối xử); giúp đạt được mục tiêu hoặc góp phần chi trả việc gì', 'prep.', NULL, 'Đồng nghĩa: toward · Trái nghĩa: away from', 'towards và toward có nghĩa giống nhau; towards được dùng phổ biến hơn trong tiếng Anh-Anh.', 'The puppy ran towards me with its tail wagging.', NULL, 'Chú cún con vẫy đuôi chạy về phía tôi.', '{"wordId":"towards","ukIpa":"/təˈwɔːdz/","usIpa":"/tɔːrdz/","cefr":"A2","topic":"daily","senses":[{"pos":"prep.","en":"In the direction of someone or something.","vi":"về phía, hướng về ai hoặc cái gì"},{"pos":"prep.","en":"In relation to someone or something, especially in attitude.","vi":"đối với, về phía (thái độ đối xử)"},{"pos":"prep.","en":"Helping to achieve a goal or pay for something.","vi":"giúp đạt được mục tiêu hoặc góp phần chi trả việc gì"}],"examples":[{"en":"The puppy ran towards me with its tail wagging.","vi":"Chú cún con vẫy đuôi chạy về phía tôi.","audioKind":"ex"},{"en":"Investment in public transport is an important step towards reducing air pollution in cities.","vi":"Đầu tư vào giao thông công cộng là một bước quan trọng nhằm giảm thiểu ô nhiễm không khí ở các đô thị.","audioKind":"ex2"}],"collocations":[{"en":"walk towards","vi":"đi về phía"},{"en":"attitude towards","vi":"thái độ đối với"},{"en":"work towards a goal","vi":"nỗ lực vì một mục tiêu"},{"en":"go towards the cost","vi":"góp phần chi trả chi phí"}],"wordFamily":[],"synonyms":["toward"],"antonyms":["away from"],"tipVi":"towards và toward có nghĩa giống nhau; towards được dùng phổ biến hơn trong tiếng Anh-Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_strange', 'en-a2-30', 'strange', '/streɪndʒ/', 'A2', 'kỳ lạ, khác thường, bất ngờ; xa lạ, chưa từng biết hoặc chưa từng trải qua', 'adj.', 'strangely (adv.), strangeness (n.), stranger (n.)', 'Đồng nghĩa: odd, unusual, unfamiliar · Trái nghĩa: normal, familiar', 'strange có thể mang nghĩa kỳ lạ hoặc xa lạ; stranger là danh từ chỉ người lạ.', 'There was a strange noise coming from the cupboard.', NULL, 'Có một âm thanh kỳ lạ phát ra từ chiếc tủ.', '{"wordId":"strange","ukIpa":"/streɪndʒ/","usIpa":"/streɪndʒ/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Unusual or unexpected in a way that seems surprising","vi":"kỳ lạ, khác thường, bất ngờ"},{"pos":"adj.","en":"Not known or experienced before","vi":"xa lạ, chưa từng biết hoặc chưa từng trải qua"}],"examples":[{"en":"There was a strange noise coming from the cupboard.","vi":"Có một âm thanh kỳ lạ phát ra từ chiếc tủ.","audioKind":"ex"},{"en":"Customs that seem strange to visitors may reflect important social values within the local community.","vi":"Những phong tục có vẻ kỳ lạ đối với du khách có thể phản ánh những giá trị xã hội quan trọng trong cộng đồng địa phương.","audioKind":"ex2"}],"collocations":[{"en":"strange behaviour","vi":"hành vi kỳ lạ"},{"en":"feel strange","vi":"cảm thấy lạ lẫm, không thoải mái"},{"en":"a strange place","vi":"nơi xa lạ"},{"en":"a strange noise","vi":"tiếng động lạ"}],"wordFamily":["strangely (adv.)","strangeness (n.)","stranger (n.)"],"synonyms":["odd","unusual","unfamiliar"],"antonyms":["normal","familiar"],"tipVi":"strange có thể mang nghĩa kỳ lạ hoặc xa lạ; stranger là danh từ chỉ người lạ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_latest', 'en-a2-30', 'latest', '/ˈleɪtɪst/', 'A2', 'mới nhất, gần đây nhất; tin tức mới nhất, sự việc mới nhất', 'adj.', 'late (adj.), lately (adv.), lateness (n.)', 'Đồng nghĩa: newest, most recent · Trái nghĩa: earliest', 'latest chỉ sự mới nhất; last thường chỉ cái trước đó hoặc cái cuối cùng.', 'Have you heard the latest news about our neighbour?', NULL, 'Bạn đã nghe tin tức mới nhất về người hàng xóm của chúng ta chưa?', '{"wordId":"latest","ukIpa":"/ˈleɪtɪst/","usIpa":"/ˈleɪtɪst/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Most recent or newest.","vi":"mới nhất, gần đây nhất"},{"pos":"n.","en":"The most recent news, developments, or products.","vi":"tin tức mới nhất, sự việc mới nhất"}],"examples":[{"en":"Have you heard the latest news about our neighbour?","vi":"Bạn đã nghe tin tức mới nhất về người hàng xóm của chúng ta chưa?","audioKind":"ex"},{"en":"The latest research suggests that regular physical activity can improve both memory and mental health.","vi":"Nghiên cứu mới nhất cho thấy việc tập thể dục đều đặn có thể cải thiện cả trí nhớ lẫn sức khỏe tinh thần.","audioKind":"ex2"}],"collocations":[{"en":"the latest research","vi":"nghiên cứu mới nhất"},{"en":"the latest version","vi":"phiên bản mới nhất"},{"en":"at the latest","vi":"muộn nhất, chậm nhất là"}],"wordFamily":["late (adj.)","lately (adv.)","lateness (n.)"],"synonyms":["newest","most recent"],"antonyms":["earliest"],"tipVi":"latest chỉ sự mới nhất; last thường chỉ cái trước đó hoặc cái cuối cùng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wardrobe', 'en-a2-30', 'wardrobe', '/ˈwɔːrdroʊb/', 'A2', 'tủ đựng quần áo, tủ quần áo; toàn bộ trang phục, quần áo mà một người sở hữu', 'n.', NULL, NULL, 'Vừa có nghĩa là chiếc tủ đựng quần áo, vừa chỉ tổng số lượng quần áo một người có.', 'Her winter coats fill most of the wardrobe.', NULL, 'Những chiếc áo khoác mùa đông của cô ấy chiếm phần lớn không gian tủ quần áo.', '{"wordId":"wardrobe","ukIpa":"/ˈwɔːdrəʊb/","usIpa":"/ˈwɔːrdroʊb/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a tall cupboard used for storing clothes","vi":"tủ đựng quần áo, tủ quần áo"},{"pos":"n.","en":"all the clothes that a person owns","vi":"toàn bộ trang phục, quần áo mà một người sở hữu"}],"examples":[{"en":"Her winter coats fill most of the wardrobe.","vi":"Những chiếc áo khoác mùa đông của cô ấy chiếm phần lớn không gian tủ quần áo.","audioKind":"ex"},{"en":"Building a smaller wardrobe with durable clothing can reduce the environmental impact of fashion consumption.","vi":"Xây dựng một tủ quần áo tối giản với những trang phục bền bỉ có thể làm giảm tác động môi trường của ngành tiêu thụ thời trang.","audioKind":"ex2"}],"collocations":[{"en":"fitted wardrobe","vi":"tủ âm tường"},{"en":"capsule wardrobe","vi":"tủ quần áo tối giản, tinh gọn"},{"en":"update your wardrobe","vi":"làm mới tủ quần áo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Vừa có nghĩa là chiếc tủ đựng quần áo, vừa chỉ tổng số lượng quần áo một người có.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_smart', 'en-a2-30', 'smart', '/smɑːrt/', 'A2', 'thông minh; sáng suốt; gọn gàng, lịch sự; sành điệu; thông minh (dùng công nghệ)', 'adj.', 'smartly (adv.), smartness (n.), smarten (v.)', 'Đồng nghĩa: clever, intelligent · Trái nghĩa: foolish', 'Từ này có thể mang nghĩa chỉ sự chỉn chu, sành điệu hoặc sự thông minh tùy theo ngữ cảnh.', 'That was a smart way to fix the shelf.', NULL, 'Đó là một cách thông minh để sửa chiếc kệ.', '{"wordId":"smart","ukIpa":"/smɑːt/","usIpa":"/smɑːrt/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"intelligent or showing good judgment","vi":"thông minh; sáng suốt"},{"pos":"adj.","en":"neat, stylish, and suitable for a formal occasion","vi":"gọn gàng, lịch sự; sành điệu"},{"pos":"adj.","en":"using computer technology to perform tasks automatically","vi":"thông minh (dùng công nghệ)"}],"examples":[{"en":"That was a smart way to fix the shelf.","vi":"Đó là một cách thông minh để sửa chiếc kệ.","audioKind":"ex"},{"en":"Smart irrigation systems can reduce water waste by adjusting supply according to soil conditions.","vi":"Hệ thống tưới tiêu thông minh có thể làm giảm lãng phí nước bằng cách điều chỉnh lượng nước cung cấp theo tình trạng của đất.","audioKind":"ex2"}],"collocations":[{"en":"a smart choice","vi":"một lựa chọn sáng suốt"},{"en":"smart clothes","vi":"quần áo lịch sự, chỉn chu"},{"en":"smart technology","vi":"công nghệ thông minh"},{"en":"look smart","vi":"trông gọn gàng, lịch sự"}],"wordFamily":["smartly (adv.)","smartness (n.)","smarten (v.)"],"synonyms":["clever","intelligent"],"antonyms":["foolish"],"tipVi":"Từ này có thể mang nghĩa chỉ sự chỉn chu, sành điệu hoặc sự thông minh tùy theo ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clear', 'en-a2-30', 'clear', '/klɪr/', 'A2', 'rõ ràng; dễ hiểu; trong trẻo; quang đãng; dọn sạch; làm sạch', 'adj.', 'clearly (adv.), clarity (n.), clearance (n.), unclear (adj.)', 'Trái nghĩa: unclear', 'Cấu trúc make it clear that… dùng để diễn tả việc làm rõ điều gì đó.', 'The instructions were clear, so I assembled the shelf easily.', NULL, 'Các hướng dẫn rất rõ ràng nên tôi đã lắp ráp chiếc kệ một cách dễ dàng.', '{"wordId":"clear","ukIpa":"/klɪə/","usIpa":"/klɪr/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Easy to understand, see, or hear","vi":"rõ ràng; dễ hiểu"},{"pos":"adj.","en":"Free from cloud, dirt, or anything blocking light","vi":"trong trẻo; quang đãng"},{"pos":"v.","en":"To remove unwanted things from a place","vi":"dọn sạch; làm sạch"}],"examples":[{"en":"The instructions were clear, so I assembled the shelf easily.","vi":"Các hướng dẫn rất rõ ràng nên tôi đã lắp ráp chiếc kệ một cách dễ dàng.","audioKind":"ex"},{"en":"Public health campaigns should provide clear advice that people from different educational backgrounds can easily understand.","vi":"Các chiến dịch y tế công cộng nên đưa ra các khuyến nghị rõ ràng mà người dân từ các nền tảng giáo dục khác nhau đều có thể dễ dàng hiểu được.","audioKind":"ex2"}],"collocations":[{"en":"clear instructions","vi":"hướng dẫn rõ ràng"},{"en":"clear evidence","vi":"bằng chứng rõ ràng"},{"en":"crystal clear","vi":"trong suốt như pha lê; cực kỳ rõ ràng"},{"en":"clear the table","vi":"dọn bàn ăn"}],"wordFamily":["clearly (adv.)","clarity (n.)","clearance (n.)","unclear (adj.)"],"synonyms":[],"antonyms":["unclear"],"tipVi":"Cấu trúc make it clear that… dùng để diễn tả việc làm rõ điều gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cereal', 'en-a2-30', 'cereal', '/ˈsɪriəl/', 'A2', 'ngũ cốc ăn sáng; món ngũ cốc ăn kèm sữa; cây lương thực; hạt ngũ cốc', 'n.', NULL, NULL, 'Món ăn sáng thường không đếm được; chỉ các loài ngũ cốc có thể dùng cereals.', 'She poured cold milk over her bowl of cereal.', NULL, 'Cô ấy đổ sữa lạnh lên bát ngũ cốc ăn sáng của mình.', '{"wordId":"cereal","ukIpa":"/ˈsɪəriəl/","usIpa":"/ˈsɪriəl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a breakfast food made from grains, often eaten with milk","vi":"ngũ cốc ăn sáng; món ngũ cốc ăn kèm sữa"},{"pos":"n.","en":"a plant grown for grain, or the grain it produces","vi":"cây lương thực; hạt ngũ cốc"}],"examples":[{"en":"She poured cold milk over her bowl of cereal.","vi":"Cô ấy đổ sữa lạnh lên bát ngũ cốc ăn sáng của mình.","audioKind":"ex"},{"en":"Farmers may need to grow different cereal crops as changing rainfall patterns affect agricultural production.","vi":"Nông dân có thể cần trồng các loại cây lương thực khác khi các hình thức mưa thay đổi ảnh hưởng đến sản xuất nông nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"breakfast cereal","vi":"ngũ cốc ăn sáng"},{"en":"a bowl of cereal","vi":"một bát ngũ cốc"},{"en":"cereal crops","vi":"cây lương thực"},{"en":"wholegrain cereal","vi":"ngũ cốc nguyên hạt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Món ăn sáng thường không đếm được; chỉ các loài ngũ cốc có thể dùng cereals.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_alone', 'en-a2-30', 'alone', '/əˈloʊn/', 'A2', 'đơn độc; một mình; không có ai ở cùng; tự mình; không cần sự giúp đỡ của ai; chỉ; duy chỉ; loại trừ tất cả những thứ hoặc người khác', 'adj.', NULL, 'Đồng nghĩa: unaccompanied', 'alone chỉ sự cô độc về mặt thể chất, không nhất thiết là cô đơn; lonely nhấn mạnh cảm giác cô đơn.', 'I was alone in the kitchen when the kettle boiled.', NULL, 'Tôi đang ở một mình trong nhà bếp khi ấm nước sôi.', '{"wordId":"alone","ukIpa":"/əˈləʊn/","usIpa":"/əˈloʊn/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"without anyone else present","vi":"đơn độc; một mình; không có ai ở cùng"},{"pos":"adv.","en":"without other people or their help","vi":"một mình; tự mình; không cần sự giúp đỡ của ai"},{"pos":"adv.","en":"only, excluding everything or everyone else","vi":"chỉ; duy chỉ; loại trừ tất cả những thứ hoặc người khác"}],"examples":[{"en":"I was alone in the kitchen when the kettle boiled.","vi":"Tôi đang ở một mình trong nhà bếp khi ấm nước sôi.","audioKind":"ex"},{"en":"Governments cannot solve environmental problems alone, as lasting progress also requires cooperation from businesses and individual citizens.","vi":"Chính phủ không thể đơn độc giải quyết các vấn đề môi trường, vì sự tiến bộ lâu dài cũng đòi hỏi sự hợp tác từ các doanh nghiệp và công dân cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"live alone","vi":"sống một mình"},{"en":"travel alone","vi":"đi du lịch một mình"},{"en":"leave someone alone","vi":"để cho ai đó yên"},{"en":"go it alone","vi":"tự mình làm việc gì"}],"wordFamily":[],"synonyms":["unaccompanied"],"antonyms":[],"tipVi":"alone chỉ sự cô độc về mặt thể chất, không nhất thiết là cô đơn; lonely nhấn mạnh cảm giác cô đơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beef', 'en-a2-30', 'beef', '/biːf/', 'A2', 'thịt bò', 'n.', NULL, NULL, 'Chỉ thực phẩm thường không đếm được: dùng some beef, không dùng a beef.', 'We cooked the beef slowly with carrots and potatoes.', NULL, 'Chúng tôi nấu chậm thịt bò cùng với cà rốt và khoai tây.', '{"wordId":"beef","ukIpa":"/biːf/","usIpa":"/biːf/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"meat from cattle, eaten as food","vi":"thịt bò"}],"examples":[{"en":"We cooked the beef slowly with carrots and potatoes.","vi":"Chúng tôi nấu chậm thịt bò cùng với cà rốt và khoai tây.","audioKind":"ex"},{"en":"Reducing beef consumption could lower greenhouse gas emissions because raising cattle requires substantial land and resources.","vi":"Việc giảm tiêu thụ thịt bò có thể làm giảm phát thải khí nhà kính vì chăn nuôi bò đòi hỏi nhiều đất đai và tài nguyên.","audioKind":"ex2"}],"collocations":[{"en":"roast beef","vi":"thịt bò nướng"},{"en":"minced beef","vi":"thịt bò băm"},{"en":"beef stew","vi":"món thịt bò hầm"},{"en":"lean beef","vi":"thịt bò nạc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chỉ thực phẩm thường không đếm được: dùng some beef, không dùng a beef.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ketchup', 'en-a2-30', 'ketchup', '/ˈketʃəp/', 'A2', 'tương cà chua', 'n.', NULL, 'Đồng nghĩa: catsup', 'Là danh từ không đếm được; khác với loại sốt đặc dùng trong nấu ăn là tomato paste.', 'He squeezed some ketchup onto his plate of chips.', NULL, 'Anh ấy bóp một ít tương cà lên đĩa khoai tây chiên của mình.', '{"wordId":"ketchup","ukIpa":"/ˈketʃəp/","usIpa":"/ˈketʃəp/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A thick, usually tomato-based sauce served with food.","vi":"tương cà chua"}],"examples":[{"en":"He squeezed some ketchup onto his plate of chips.","vi":"Anh ấy bóp một ít tương cà lên đĩa khoai tây chiên của mình.","audioKind":"ex"},{"en":"Reducing added sugar in everyday products such as ketchup could help consumers make healthier dietary choices.","vi":"Việc giảm lượng đường bổ sung trong các sản phẩm hàng ngày như tương cà có thể giúp người tiêu dùng đưa ra lựa chọn ăn uống lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"tomato ketchup","vi":"tương cà chua"},{"en":"a bottle of ketchup","vi":"một chai tương cà"},{"en":"a squeeze of ketchup","vi":"một ít tương cà bóp ra"}],"wordFamily":[],"synonyms":["catsup"],"antonyms":[],"tipVi":"Là danh từ không đếm được; khác với loại sốt đặc dùng trong nấu ăn là tomato paste.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mail', 'en-a2-30', 'mail', '/meɪl/', 'A2', 'thư từ; bưu phẩm; dịch vụ bưu chính; gửi thư; gửi bưu phẩm', 'n.', 'mailing (n.), mailer (n.)', 'Đồng nghĩa: post', 'Khi mang nghĩa thư từ, mail thường là danh từ không đếm được; trong tiếng Anh-Anh đời thường, từ post cũng hay được dùng.', 'The mail arrived just as we finished breakfast.', NULL, 'Thư từ vừa tới lúc chúng tôi ăn sáng xong.', '{"wordId":"mail","ukIpa":"/meɪl/","usIpa":"/meɪl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"letters and parcels sent or delivered through a postal service","vi":"thư từ; bưu phẩm; dịch vụ bưu chính"},{"pos":"v.","en":"to send a letter or parcel through a postal service","vi":"gửi thư; gửi bưu phẩm"}],"examples":[{"en":"The mail arrived just as we finished breakfast.","vi":"Thư từ vừa tới lúc chúng tôi ăn sáng xong.","audioKind":"ex"},{"en":"Although digital communication is widespread, many rural residents still depend on mail for essential documents.","vi":"Mặc dù truyền thông kỹ thuật số đã phổ biến, nhiều cư dân nông thôn vẫn phụ thuộc vào dịch vụ bưu chính để nhận các tài liệu quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"send by mail","vi":"gửi qua đường bưu điện"},{"en":"check the mail","vi":"kiểm tra thư"},{"en":"mail a parcel","vi":"gửi bưu phẩm"}],"wordFamily":["mailing (n.)","mailer (n.)"],"synonyms":["post"],"antonyms":[],"tipVi":"Khi mang nghĩa thư từ, mail thường là danh từ không đếm được; trong tiếng Anh-Anh đời thường, từ post cũng hay được dùng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thousand', 'en-a2-30', 'thousand', '/ˈθaʊzənd/', 'A2', 'một nghìn; một ngàn; hàng nghìn; số lượng lớn', 'num.', 'thousandth (num.)', NULL, 'Sau số từ cụ thể không thêm s; khi chỉ số lượng chung chung thì dùng thousands of.', 'The repair cost nearly a thousand dollars in total.', NULL, 'Chi phí sửa chữa tổng cộng gần một nghìn đô la.', '{"wordId":"thousand","ukIpa":"/ˈθaʊzənd/","usIpa":"/ˈθaʊzənd/","cefr":"A2","topic":"daily","senses":[{"pos":"num.","en":"The number equal to ten hundreds.","vi":"một nghìn; một ngàn"},{"pos":"n.","en":"A very large quantity, expressed as thousands.","vi":"hàng nghìn; số lượng lớn"}],"examples":[{"en":"The repair cost nearly a thousand dollars in total.","vi":"Chi phí sửa chữa tổng cộng gần một nghìn đô la.","audioKind":"ex"},{"en":"Several thousand residents have benefited from the new cycle routes connecting suburban neighbourhoods with the city centre.","vi":"Hàng nghìn cư dân đã được hưởng lợi từ các tuyến đường dành cho xe đạp mới kết nối các khu vực ngoại ô với trung tâm thành phố.","audioKind":"ex2"}],"collocations":[{"en":"a thousand people","vi":"một nghìn người"},{"en":"two thousand years","vi":"hai nghìn năm"},{"en":"thousands of","vi":"hàng nghìn..."}],"wordFamily":["thousandth (num.)"],"synonyms":[],"antonyms":[],"tipVi":"Sau số từ cụ thể không thêm s; khi chỉ số lượng chung chung thì dùng thousands of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_certainly', 'en-a2-30', 'certainly', '/ˈsɝːtənli/', 'A2', 'chắc chắn; quả thực; tất nhiên rồi; được chứ', 'adv.', 'certain (adj.), certainty (n.), uncertain (adj.)', 'Đồng nghĩa: definitely, undoubtedly', 'Thường đứng trước động từ thường hoặc sau động từ to be; cũng có thể dùng độc lập để đáp lại yêu cầu một cách lịch sự.', 'This warm coat will certainly keep you comfortable outside.', NULL, 'Chiếc áo khoác ấm áp này chắc chắn sẽ giữ cho bạn thoải mái khi ở ngoài trời.', '{"wordId":"certainly","ukIpa":"/ˈsɜːtənli/","usIpa":"/ˈsɝːtənli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"Used to express that something is definitely true.","vi":"chắc chắn; quả thực"},{"pos":"adv.","en":"Used to agree politely to a request.","vi":"tất nhiên rồi; được chứ"}],"examples":[{"en":"This warm coat will certainly keep you comfortable outside.","vi":"Chiếc áo khoác ấm áp này chắc chắn sẽ giữ cho bạn thoải mái khi ở ngoài trời.","audioKind":"ex"},{"en":"Improved public transport would certainly benefit commuters, although its success would depend on reliable services and affordable fares.","vi":"Việc cải thiện giao thông công cộng chắc chắn sẽ mang lại lợi ích cho những người đi lại làm việc, mặc dù thành công của nó còn phụ thuộc vào dịch vụ đáng tin cậy và giá vé phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"almost certainly","vi":"gần như chắc chắn"},{"en":"certainly not","vi":"chắc chắn là không"},{"en":"will certainly help","vi":"chắc chắn sẽ giúp ích"}],"wordFamily":["certain (adj.)","certainty (n.)","uncertain (adj.)"],"synonyms":["definitely","undoubtedly"],"antonyms":[],"tipVi":"Thường đứng trước động từ thường hoặc sau động từ to be; cũng có thể dùng độc lập để đáp lại yêu cầu một cách lịch sự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_danger', 'en-a2-30', 'danger', '/ˈdeɪndʒər/', 'A2', 'sự nguy hiểm; mối nguy; nguy cơ; mối đe dọa', 'n.', 'dangerous (adj.), dangerously (adv.), endanger (v.), endangered (adj.)', 'Đồng nghĩa: peril, risk, threat · Trái nghĩa: safety', 'in danger chỉ trạng thái đang gặp nguy hiểm; dangerous dùng để chỉ tính chất gây nguy hiểm.', 'Keep away from the edge; there''s a danger of falling.', NULL, 'Hãy tránh xa mép vực; có nguy cơ bị rơi xuống đấy.', '{"wordId":"danger","ukIpa":"/ˈdeɪndʒə/","usIpa":"/ˈdeɪndʒər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"The possibility that someone or something will be harmed.","vi":"sự nguy hiểm; mối nguy"},{"pos":"n.","en":"Someone or something that may cause harm.","vi":"nguy cơ; mối đe dọa"}],"examples":[{"en":"Keep away from the edge; there''s a danger of falling.","vi":"Hãy tránh xa mép vực; có nguy cơ bị rơi xuống đấy.","audioKind":"ex"},{"en":"Poorly maintained roads pose a serious danger to cyclists, particularly in areas without dedicated cycling lanes.","vi":"Những con đường xuống cấp tạo ra mối đe dọa nghiêm trọng cho người đi xe đạp, đặc biệt là ở những khu vực không có làn đường dành riêng cho xe đạp.","audioKind":"ex2"}],"collocations":[{"en":"in danger","vi":"đang gặp nguy hiểm"},{"en":"out of danger","vi":"thoát khỏi nguy hiểm"},{"en":"pose a danger to","vi":"gây nguy hiểm cho"},{"en":"danger of extinction","vi":"nguy cơ tuyệt chủng"}],"wordFamily":["dangerous (adj.)","dangerously (adv.)","endanger (v.)","endangered (adj.)"],"synonyms":["peril","risk","threat"],"antonyms":["safety"],"tipVi":"in danger chỉ trạng thái đang gặp nguy hiểm; dangerous dùng để chỉ tính chất gây nguy hiểm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_indoor', 'en-a2-30', 'indoor', '/ˈɪndɔːr/', 'A2', 'trong nhà', 'adj.', 'indoors (adv.)', 'Trái nghĩa: outdoor', 'indoor làm định ngữ đứng trước danh từ; indoors đóng vai trò là trạng từ, chẳng hạn như stay indoors.', 'Our hotel has an indoor pool beside the gym.', NULL, 'Khách sạn của chúng tôi có một hồ bơi trong nhà nằm bên cạnh phòng tập thể dục.', '{"wordId":"indoor","ukIpa":"/ˈɪndɔː/","usIpa":"/ˈɪndɔːr/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Located, used, or happening inside a building.","vi":"trong nhà"}],"examples":[{"en":"Our hotel has an indoor pool beside the gym.","vi":"Khách sạn của chúng tôi có một hồ bơi trong nhà nằm bên cạnh phòng tập thể dục.","audioKind":"ex"},{"en":"Indoor sports facilities allow children to remain physically active regardless of weather conditions throughout the year.","vi":"Các cơ sở thể thao trong nhà giúp trẻ em duy trì vận động thể chất quanh năm mà không bị ảnh hưởng bởi điều kiện thời tiết.","audioKind":"ex2"}],"collocations":[{"en":"indoor swimming pool","vi":"hồ bơi trong nhà"},{"en":"indoor activities","vi":"hoạt động trong nhà"},{"en":"indoor air quality","vi":"chất lượng không khí trong nhà"}],"wordFamily":["indoors (adv.)"],"synonyms":[],"antonyms":["outdoor"],"tipVi":"indoor làm định ngữ đứng trước danh từ; indoors đóng vai trò là trạng từ, chẳng hạn như stay indoors.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_convenient', 'en-a2-30', 'convenient', '/kənˈviːniənt/', 'A2', 'thuận tiện; thuận lợi; gần gũi; thuận đường', 'adj.', 'convenience (n.), conveniently (adv.), inconvenient (adj.), inconvenience (n.)', 'Đồng nghĩa: handy, suitable · Trái nghĩa: inconvenient', 'Dùng cấu trúc It is convenient for me, không nói I am convenient.', 'Is Saturday morning a convenient time for your visit?', NULL, 'Sáng thứ Bảy có phải là thời gian thuận tiện để bạn ghé thăm không?', '{"wordId":"convenient","ukIpa":"/kənˈviːniənt/","usIpa":"/kənˈviːniənt/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Easy to use or suitable for your needs and plans.","vi":"thuận tiện; thuận lợi"},{"pos":"adj.","en":"Situated close to somewhere you need to reach.","vi":"gần gũi; thuận đường"}],"examples":[{"en":"Is Saturday morning a convenient time for your visit?","vi":"Sáng thứ Bảy có phải là thời gian thuận tiện để bạn ghé thăm không?","audioKind":"ex"},{"en":"Online learning offers a convenient way for working adults to develop skills without travelling to a campus.","vi":"Học trực tuyến mang đến một phương thức thuận tiện để người lớn đi làm phát triển kỹ năng mà không cần phải di chuyển đến trường.","audioKind":"ex2"}],"collocations":[{"en":"a convenient time","vi":"thời điểm thuận tiện"},{"en":"convenient for someone","vi":"thuận tiện cho ai đó"},{"en":"a convenient location","vi":"vị trí thuận lợi"},{"en":"a convenient way to","vi":"cách thức thuận tiện để"}],"wordFamily":["convenience (n.)","conveniently (adv.)","inconvenient (adj.)","inconvenience (n.)"],"synonyms":["handy","suitable"],"antonyms":["inconvenient"],"tipVi":"Dùng cấu trúc It is convenient for me, không nói I am convenient.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_taste', 'en-a2-30', 'taste', '/teɪst/', 'A2', 'vị; vị giác; nếm; có hương vị; gu thẩm mỹ; sở thích', 'n.', 'tasty (adj.), tasteless (adj.), tasteful (adj.), taster (n.)', 'Đồng nghĩa: flavour', 'Khi taste mang nghĩa là "có hương vị", nó đi kèm với tính từ chứ không dùng phó từ.', 'The soup has a rich taste of roasted tomatoes.', NULL, 'Món súp này mang hương vị đậm đà của cà chua nướng.', '{"wordId":"taste","ukIpa":"/teɪst/","usIpa":"/teɪst/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A food''s flavour, or the sense that detects it.","vi":"vị; vị giác"},{"pos":"v.","en":"To try food or drink, or have a particular flavour.","vi":"nếm; có hương vị"},{"pos":"n.","en":"Someone''s preferences or ability to judge what is attractive.","vi":"gu thẩm mỹ; sở thích"}],"examples":[{"en":"The soup has a rich taste of roasted tomatoes.","vi":"Món súp này mang hương vị đậm đà của cà chua nướng.","audioKind":"ex"},{"en":"Children may develop a taste for healthier foods when schools offer varied and appealing meals.","vi":"Trẻ em có thể dần hình thành sở thích ăn uống lành mạnh hơn khi trường học cung cấp những bữa ăn đa dạng và hấp dẫn.","audioKind":"ex2"}],"collocations":[{"en":"taste delicious","vi":"có vị ngon"},{"en":"a bitter taste","vi":"vị đắng"},{"en":"a taste for","vi":"có sở thích về..."},{"en":"good taste","vi":"gu thẩm mỹ tốt"}],"wordFamily":["tasty (adj.)","tasteless (adj.)","tasteful (adj.)","taster (n.)"],"synonyms":["flavour"],"antonyms":[],"tipVi":"Khi taste mang nghĩa là \"có hương vị\", nó đi kèm với tính từ chứ không dùng phó từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jump', 'en-a2-30', 'jump', '/dʒʌmp/', 'A2', 'nhảy; bật cao; tăng vọt; tăng đột ngột; cú nhảy; sự tăng vọt', 'v.', 'jumpy (adj.)', 'Đồng nghĩa: leap', 'jump at the chance ý chỉ chớp lấy cơ hội một cách hào hứng.', 'The dog jumped over a puddle beside the gate.', NULL, 'Con chó đã nhảy qua vũng nước bên cạnh cổng.', '{"wordId":"jump","ukIpa":"/dʒʌmp/","usIpa":"/dʒʌmp/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To push yourself off the ground into the air.","vi":"nhảy; bật cao"},{"pos":"v.","en":"To increase suddenly by a large amount.","vi":"tăng vọt; tăng đột ngột"},{"pos":"n.","en":"An act of jumping or a sudden large increase.","vi":"cú nhảy; sự tăng vọt"}],"examples":[{"en":"The dog jumped over a puddle beside the gate.","vi":"Con chó đã nhảy qua vũng nước bên cạnh cổng.","audioKind":"ex"},{"en":"Housing costs have jumped sharply in cities where demand continues to exceed the supply of affordable homes.","vi":"Chi phí nhà ở đã tăng vọt ở những thành phố nơi nhu cầu tiếp tục vượt quá nguồn cung nhà ở giá rẻ.","audioKind":"ex2"}],"collocations":[{"en":"jump over a fence","vi":"nhảy qua hàng rào"},{"en":"jump at the chance","vi":"chớp lấy cơ hội"},{"en":"a sharp jump in prices","vi":"sự tăng giá vọt"}],"wordFamily":["jumpy (adj.)"],"synonyms":["leap"],"antonyms":[],"tipVi":"jump at the chance ý chỉ chớp lấy cơ hội một cách hào hứng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_record', 'en-a2-30', 'record', '/ˈrekərd/', 'A2', 'hồ sơ; sổ sách; bản ghi chép; ghi lại; ghi âm; ghi hình; kỷ lục', 'n.', 'recording (n.), recorder (n.), recorded (adj.)', NULL, 'Danh từ nhấn trọng âm ở âm tiết đầu; động từ nhấn trọng âm ở âm tiết thứ hai.', 'I keep a record of everything I spend.', NULL, 'Tôi ghi chép lại mọi khoản chi tiêu của mình.', '{"wordId":"record","ukIpa":"/ˈrekɔːd/","usIpa":"/ˈrekərd/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Stored information about events, activities, or a person''s history.","vi":"hồ sơ; sổ sách; bản ghi chép"},{"pos":"v.","en":"To store information, sounds, or images for future use.","vi":"ghi lại; ghi âm; ghi hình"},{"pos":"n.","en":"The best result ever achieved in a particular activity.","vi":"kỷ lục"}],"examples":[{"en":"I keep a record of everything I spend.","vi":"Tôi ghi chép lại mọi khoản chi tiêu của mình.","audioKind":"ex"},{"en":"Accurate medical records allow healthcare professionals to make informed decisions and avoid unnecessary treatments.","vi":"Hồ sơ y tế chính xác giúp các chuyên gia chăm sóc sức khỏe đưa ra quyết định sáng suốt và tránh các phương pháp điều trị không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"keep a record","vi":"lưu giữ hồ sơ"},{"en":"medical records","vi":"hồ sơ y tế"},{"en":"break a record","vi":"phá kỷ lục"},{"en":"record a conversation","vi":"ghi âm cuộc trò chuyện"}],"wordFamily":["recording (n.)","recorder (n.)","recorded (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ nhấn trọng âm ở âm tiết đầu; động từ nhấn trọng âm ở âm tiết thứ hai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clearly', 'en-a2-30', 'clearly', '/ˈklɪrli/', 'A2', 'rõ ràng; rành mạch; hiển nhiên; rõ mười mươi', 'adv.', 'clear (adj.), clarity (n.), clarify (v.)', 'Đồng nghĩa: plainly, obviously · Trái nghĩa: unclearly', 'clearly ở đầu câu thường mang nghĩa là ''hiển nhiên'', không phải là ''một cách rõ ràng''.', 'Please speak clearly so everyone can hear you.', NULL, 'Làm ơn nói rõ ràng để mọi người có thể nghe thấy bạn.', '{"wordId":"clearly","ukIpa":"/ˈklɪəli/","usIpa":"/ˈklɪrli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"In a way that is easy to see, hear, or understand.","vi":"rõ ràng; rành mạch"},{"pos":"adv.","en":"In a way that shows something is obviously true.","vi":"hiển nhiên; rõ mười mươi"}],"examples":[{"en":"Please speak clearly so everyone can hear you.","vi":"Làm ơn nói rõ ràng để mọi người có thể nghe thấy bạn.","audioKind":"ex"},{"en":"Public health information should clearly explain the benefits and potential risks of any recommended treatment.","vi":"Thông tin y tế công cộng nên giải thích rõ ràng các lợi ích và rủi ro tiềm ẩn của bất kỳ phương pháp điều trị nào được khuyến nghị.","audioKind":"ex2"}],"collocations":[{"en":"speak clearly","vi":"nói rõ ràng"},{"en":"clearly explain","vi":"giải thích rõ ràng"},{"en":"clearly visible","vi":"nhìn rõ"}],"wordFamily":["clear (adj.)","clarity (n.)","clarify (v.)"],"synonyms":["plainly","obviously"],"antonyms":["unclearly"],"tipVi":"clearly ở đầu câu thường mang nghĩa là ''hiển nhiên'', không phải là ''một cách rõ ràng''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_curry', 'en-a2-30', 'curry', '/ˈkɜːri/', 'A2', 'món ca-ri; món rau hoặc thịt nấu với các loại gia vị; nấu với gia vị ca-ri', 'n.', NULL, NULL, 'curry thường chỉ món ăn; bột cà ri dùng curry powder.', 'This vegetable curry tastes wonderful with rice and warm bread.', NULL, 'Món rau ca-ri này ăn kèm cơm và bánh mì ấm thì ngon tuyệt.', '{"wordId":"curry","ukIpa":"/ˈkʌri/","usIpa":"/ˈkɜːri/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A dish of vegetables or meat cooked with spices.","vi":"món ca-ri; món rau hoặc thịt nấu với các loại gia vị"},{"pos":"v.","en":"To cook food with curry spices.","vi":"nấu với gia vị ca-ri"}],"examples":[{"en":"This vegetable curry tastes wonderful with rice and warm bread.","vi":"Món rau ca-ri này ăn kèm cơm và bánh mì ấm thì ngon tuyệt.","audioKind":"ex"},{"en":"School cafeterias can offer vegetable curry as an affordable alternative to meals containing meat.","vi":"Các bếp ăn trường học có thể cung cấp món ca-ri rau củ như một lựa chọn thay thế vừa túi tiền cho các bữa ăn có thịt.","audioKind":"ex2"}],"collocations":[{"en":"chicken curry","vi":"cà ri gà"},{"en":"vegetable curry","vi":"cà ri rau củ"},{"en":"curry powder","vi":"bột cà ri"},{"en":"curry paste","vi":"sốt cà ri"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"curry thường chỉ món ăn; bột cà ri dùng curry powder.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_vase', 'en-a2-30', 'vase', '/veɪs/', 'A2', 'bình hoa; lọ hoa', 'n.', NULL, NULL, 'Cách phát âm Anh-Anh thường là /vɑːz/; Anh-Mỹ thường là /veɪs/.', 'I put fresh flowers in the vase by the window.', NULL, 'Tôi cắm hoa tươi vào chiếc lọ bên cửa sổ.', '{"wordId":"vase","ukIpa":"/vɑːz/","usIpa":"/veɪs/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a container used to hold flowers or for decoration","vi":"bình hoa; lọ hoa"}],"examples":[{"en":"I put fresh flowers in the vase by the window.","vi":"Tôi cắm hoa tươi vào chiếc lọ bên cửa sổ.","audioKind":"ex"},{"en":"Traditional pottery, including decorative vases, can provide valuable insights into the artistic practices of past societies.","vi":"Đồ gốm truyền thống, bao gồm cả những chiếc bình hoa trang trí, có thể cung cấp những góc nhìn quý giá về thực hành nghệ thuật của các xã hội trong quá khứ.","audioKind":"ex2"}],"collocations":[{"en":"a vase of flowers","vi":"một bình hoa"},{"en":"a glass vase","vi":"lọ hoa bằng thủy tinh"},{"en":"a ceramic vase","vi":"lọ hoa bằng gốm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cách phát âm Anh-Anh thường là /vɑːz/; Anh-Mỹ thường là /veɪs/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_saw', 'en-a2-30', 'saw', '/sɔː/', 'A2', 'cái cưa; lưỡi cưa; cưa; cắt bằng cưa; đã nhìn thấy; đã trông thấy (dạng quá khứ của see)', 'n.', 'sawdust (n.), sawing (n.)', NULL, 'Dạng quá khứ của động từ "cưa" là sawed; còn saw ở đây cũng là dạng quá khứ của see (nhìn thấy).', 'He used a saw to cut the wooden shelf.', NULL, 'Anh ấy dùng cưa để cắt tấm ván gỗ.', '{"wordId":"saw","ukIpa":"/sɔː/","usIpa":"/sɔː/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a tool with a toothed blade for cutting hard materials","vi":"cái cưa; lưỡi cưa"},{"pos":"v.","en":"cut something using a saw","vi":"cưa; cắt bằng cưa"},{"pos":"v.","en":"past tense of see: noticed or looked at something","vi":"đã nhìn thấy; đã trông thấy (dạng quá khứ của see)"}],"examples":[{"en":"He used a saw to cut the wooden shelf.","vi":"Anh ấy dùng cưa để cắt tấm ván gỗ.","audioKind":"ex"},{"en":"The last decade saw significant improvements in public transport, particularly in rapidly growing urban areas.","vi":"Thập kỷ qua chứng kiến những cải thiện đáng kể về giao thông công cộng, đặc biệt là ở các khu vực đô thị đang phát triển nhanh chóng.","audioKind":"ex2"}],"collocations":[{"en":"a hand saw","vi":"cái cưa tay"},{"en":"saw through wood","vi":"cưa xuyên qua gỗ"},{"en":"saw something in half","vi":"cưa đôi một vật"}],"wordFamily":["sawdust (n.)","sawing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ của động từ \"cưa\" là sawed; còn saw ở đây cũng là dạng quá khứ của see (nhìn thấy).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_30_1', 'en-a2-30', 'Cách dùng “mail” (n.) — thư từ; bưu phẩm; dịch vụ bưu chính', 'send by mail  ·  check the mail  ·  mail a parcel', 'Khi mang nghĩa thư từ, mail thường là danh từ không đếm được; trong tiếng Anh-Anh đời thường, từ post cũng hay được dùng.', 'Họ từ (Word Family): mailing (n.), mailer (n.) | Đồng nghĩa: post', '[{"hanzi":"The mail arrived just as we finished breakfast.","pinyin":"","meaning":"Thư từ vừa tới lúc chúng tôi ăn sáng xong."},{"hanzi":"Although digital communication is widespread, many rural residents still depend on mail for essential documents.","pinyin":"","meaning":"Mặc dù truyền thông kỹ thuật số đã phổ biến, nhiều cư dân nông thôn vẫn phụ thuộc vào dịch vụ bưu chính để nhận các tài liệu quan trọng."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_30_2', 'en-a2-30', 'Cách dùng “certainly” (adv.) — chắc chắn; quả thực', 'almost certainly  ·  certainly not  ·  will certainly help', 'Thường đứng trước động từ thường hoặc sau động từ to be; cũng có thể dùng độc lập để đáp lại yêu cầu một cách lịch sự.', 'Họ từ (Word Family): certain (adj.), certainty (n.), uncertain (adj.) | Đồng nghĩa: definitely, undoubtedly', '[{"hanzi":"This warm coat will certainly keep you comfortable outside.","pinyin":"","meaning":"Chiếc áo khoác ấm áp này chắc chắn sẽ giữ cho bạn thoải mái khi ở ngoài trời."},{"hanzi":"Improved public transport would certainly benefit commuters, although its success would depend on reliable services and affordable fares.","pinyin":"","meaning":"Việc cải thiện giao thông công cộng chắc chắn sẽ mang lại lợi ích cho những người đi lại làm việc, mặc dù thành công của nó còn phụ thuộc vào dịch vụ đáng tin cậy và giá vé phải chăng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_30_3', 'en-a2-30', 'Cách dùng “indoor” (adj.) — trong nhà', 'indoor swimming pool  ·  indoor activities  ·  indoor air quality', 'indoor làm định ngữ đứng trước danh từ; indoors đóng vai trò là trạng từ, chẳng hạn như stay indoors.', 'Họ từ (Word Family): indoors (adv.) | Trái nghĩa: outdoor', '[{"hanzi":"Our hotel has an indoor pool beside the gym.","pinyin":"","meaning":"Khách sạn của chúng tôi có một hồ bơi trong nhà nằm bên cạnh phòng tập thể dục."},{"hanzi":"Indoor sports facilities allow children to remain physically active regardless of weather conditions throughout the year.","pinyin":"","meaning":"Các cơ sở thể thao trong nhà giúp trẻ em duy trì vận động thể chất quanh năm mà không bị ảnh hưởng bởi điều kiện thời tiết."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_30_4', 'en-a2-30', 'Cách dùng “alone” (adj.) — đơn độc; một mình; không có ai ở cùng', 'live alone  ·  travel alone  ·  leave someone alone', 'alone chỉ sự cô độc về mặt thể chất, không nhất thiết là cô đơn; lonely nhấn mạnh cảm giác cô đơn.', 'Đồng nghĩa: unaccompanied', '[{"hanzi":"I was alone in the kitchen when the kettle boiled.","pinyin":"","meaning":"Tôi đang ở một mình trong nhà bếp khi ấm nước sôi."},{"hanzi":"Governments cannot solve environmental problems alone, as lasting progress also requires cooperation from businesses and individual citizens.","pinyin":"","meaning":"Chính phủ không thể đơn độc giải quyết các vấn đề môi trường, vì sự tiến bộ lâu dài cũng đòi hỏi sự hợp tác từ các doanh nghiệp và công dân cá nhân."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_30_1', 'en-a2-30', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_30_1_1', 'ten_a2_30_1', 'seventh', 'Our new flat is on the seventh floor.', 'Our new flat is on the seventh floor.', '/ˈsevənθ/', 'Căn hộ mới của chúng tôi ở tầng bảy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_30_1_2', 'ten_a2_30_1', 'gardening', 'My grandmother enjoys gardening on cool spring mornings.', 'My grandmother enjoys gardening on cool spring mornings.', '/ˈɡɑːrdənɪŋ/', 'Bà tôi thích làm vườn vào những buổi sáng mùa xuân mát mẻ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_30_1_3', 'ten_a2_30_1', 'save', 'The lifeguard saved a child from the deep water.', 'The lifeguard saved a child from the deep water.', '/seɪv/', 'Nhân viên cứu hộ đã cứu một đứa trẻ khỏi vùng nước sâu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_30_1_4', 'ten_a2_30_1', 'jewellery', 'She keeps her jewellery in a small wooden box.', 'She keeps her jewellery in a small wooden box.', '/ˈdʒuːəlri/', 'Cô ấy cất trang sức của mình trong một chiếc hộp gỗ nhỏ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_30_1_5', 'ten_a2_30_1', 'towards', 'The puppy ran towards me with its tail wagging.', 'The puppy ran towards me with its tail wagging.', '/tɔːrdz/', 'Chú cún con vẫy đuôi chạy về phía tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_30_1_6', 'ten_a2_30_1', 'strange', 'There was a strange noise coming from the cupboard.', 'There was a strange noise coming from the cupboard.', '/streɪndʒ/', 'Có một âm thanh kỳ lạ phát ra từ chiếc tủ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_30_1_7', 'ten_a2_30_1', 'latest', 'Have you heard the latest news about our neighbour?', 'Have you heard the latest news about our neighbour?', '/ˈleɪtɪst/', 'Bạn đã nghe tin tức mới nhất về người hàng xóm của chúng ta chưa?', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_30_1_8', 'ten_a2_30_1', 'wardrobe', 'Her winter coats fill most of the wardrobe.', 'Her winter coats fill most of the wardrobe.', '/ˈwɔːrdroʊb/', 'Những chiếc áo khoác mùa đông của cô ấy chiếm phần lớn không gian tủ quần áo.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_30_1_1', 'en-a2-30', 'ten_a2_30_1', 'listening', 'listening', 'Our new flat is on the seventh floor.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Món súp này mang hương vị đậm đà của cà chua nướng.","Căn hộ mới của chúng tôi ở tầng bảy.","Chúng tôi nấu chậm thịt bò cùng với cà rốt và khoai tây.","Chi phí sửa chữa tổng cộng gần một nghìn đô la."]'::jsonb, 1, 'Our new flat is on the seventh floor. → Căn hộ mới của chúng tôi ở tầng bảy.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_30_1_2', 'en-a2-30', 'ten_a2_30_1', 'listening', 'listening', 'My grandmother enjoys gardening on cool spring mornings.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Căn hộ mới của chúng tôi ở tầng bảy.","Món rau ca-ri này ăn kèm cơm và bánh mì ấm thì ngon tuyệt.","Những chiếc áo khoác mùa đông của cô ấy chiếm phần lớn không gian tủ quần áo.","Bà tôi thích làm vườn vào những buổi sáng mùa xuân mát mẻ."]'::jsonb, 3, 'My grandmother enjoys gardening on cool spring mornings. → Bà tôi thích làm vườn vào những buổi sáng mùa xuân mát mẻ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_30_1_3', 'en-a2-30', 'ten_a2_30_1', 'listening', 'listening', 'The lifeguard saved a child from the deep water.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy cất trang sức của mình trong một chiếc hộp gỗ nhỏ.","Nhân viên cứu hộ đã cứu một đứa trẻ khỏi vùng nước sâu.","Chiếc áo khoác ấm áp này chắc chắn sẽ giữ cho bạn thoải mái khi ở ngoài trời.","Anh ấy dùng cưa để cắt tấm ván gỗ."]'::jsonb, 1, 'The lifeguard saved a child from the deep water. → Nhân viên cứu hộ đã cứu một đứa trẻ khỏi vùng nước sâu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_30_2', 'en-a2-30', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_30_2_1', 'ten_a2_30_2', 'seventh', 'By the seventh week of the course, students were able to analyse basic scientific data independently.', 'By the seventh week of the course, students were able to analyse basic scientific data independently.', '/ˈsevənθ/', 'Đến tuần thứ bảy của khóa học, học sinh đã có thể tự phân tích các dữ liệu khoa học cơ bản.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_30_2_2', 'ten_a2_30_2', 'gardening', 'Community gardening can improve urban environments while helping residents develop stronger social connections.', 'Community gardening can improve urban environments while helping residents develop stronger social connections.', '/ˈɡɑːrdənɪŋ/', 'Hoạt động làm vườn cộng đồng có thể cải thiện môi trường đô thị đồng thời giúp cư dân phát triển các mối quan hệ xã hội khăng khít hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_30_2_3', 'ten_a2_30_2', 'save', 'Investing in reliable public transport can save commuters time and reduce household travel costs.', 'Investing in reliable public transport can save commuters time and reduce household travel costs.', '/seɪv/', 'Đầu tư vào giao thông công cộng đáng tin cậy có thể giúp người đi làm tiết kiệm thời gian và giảm chi phí đi lại của gia đình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_30_2_4', 'ten_a2_30_2', 'jewellery', 'Traditional jewellery can reflect cultural identity while providing income for skilled craftspeople in rural communities.', 'Traditional jewellery can reflect cultural identity while providing income for skilled craftspeople in rural communities.', '/ˈdʒuːəlri/', 'Đồ trang sức truyền thống có thể phản ánh bản sắc văn hóa đồng thời tạo thu nhập cho các nghệ nhân lành nghề ở vùng nông thôn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_30_2_5', 'ten_a2_30_2', 'towards', 'Investment in public transport is an important step towards reducing air pollution in cities.', 'Investment in public transport is an important step towards reducing air pollution in cities.', '/tɔːrdz/', 'Đầu tư vào giao thông công cộng là một bước quan trọng nhằm giảm thiểu ô nhiễm không khí ở các đô thị.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_30_2_6', 'ten_a2_30_2', 'strange', 'Customs that seem strange to visitors may reflect important social values within the local community.', 'Customs that seem strange to visitors may reflect important social values within the local community.', '/streɪndʒ/', 'Những phong tục có vẻ kỳ lạ đối với du khách có thể phản ánh những giá trị xã hội quan trọng trong cộng đồng địa phương.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
