INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_30_2_2', 'en-a2-30', 'ten_a2_30_2', 'listening', 'listening', 'Community gardening can improve urban environments while helping residents develop stronger social connections.', NULL, 'Trong câu vừa nghe, từ “gardening” mang nghĩa nào sau đây?', '["riêng tư; cá nhân","làm vườn; nghệ thuật làm vườn","danh từ","thuộc về con người; loài người"]'::jsonb, 1, '“gardening” (/ˈɡɑːrdənɪŋ/): làm vườn; nghệ thuật làm vườn. Câu đầy đủ: Community gardening can improve urban environments while helping residents develop stronger social connections.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
