INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_30_1', 'en-a2-30', NULL, 'comprehensive_test', 'listening', 'seventh', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["có tuyết rơi; nhiều tuyết","của họ; cái của họ","thứ bảy","đĩa; bát đĩa"]'::jsonb, 2, 'seventh (/ˈsevənθ/) → thứ bảy; một phần bảy', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_30_2', 'en-a2-30', NULL, 'comprehensive_test', 'listening', 'My grandmother enjoys gardening on cool spring mornings.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhân viên cứu hộ đã cứu một đứa trẻ khỏi vùng nước sâu.","Cô ấy đổ sữa lạnh lên bát ngũ cốc ăn sáng của mình.","Bà tôi thích làm vườn vào những buổi sáng mùa xuân mát mẻ.","Tôi ghi chép lại mọi khoản chi tiêu của mình."]'::jsonb, 2, 'My grandmother enjoys gardening on cool spring mornings. → Bà tôi thích làm vườn vào những buổi sáng mùa xuân mát mẻ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_30_3', 'en-a2-30', NULL, 'comprehensive_test', 'listening', 'save', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cứu; cứu sống; bảo vệ","chính; chủ yếu","lo lắng; bận tâm","đầu gối; khớp gối"]'::jsonb, 0, 'save (/seɪv/) → cứu; cứu sống; bảo vệ; tiết kiệm; dành dụm; lưu; giữ lại', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_30_4', 'en-a2-30', NULL, 'comprehensive_test', 'listening', 'She keeps her jewellery in a small wooden box.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy cất trang sức của mình trong một chiếc hộp gỗ nhỏ.","Những chiếc áo khoác mùa đông của cô ấy chiếm phần lớn không gian tủ quần áo.","Tôi ghi chép lại mọi khoản chi tiêu của mình.","Chi phí sửa chữa tổng cộng gần một nghìn đô la."]'::jsonb, 0, 'She keeps her jewellery in a small wooden box. → Cô ấy cất trang sức của mình trong một chiếc hộp gỗ nhỏ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_30_5', 'en-a2-30', NULL, 'comprehensive_test', 'listening', 'towards', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bừa bộn; không ngăn nắp","lời chúc mừng; sự chúc mừng","sáng sủa; rực rỡ","về phía, hướng về ai hoặc cái gì"]'::jsonb, 3, 'towards (/tɔːrdz/) → về phía, hướng về ai hoặc cái gì; đối với, về phía (thái độ đối xử); giúp đạt được mục tiêu hoặc góp phần chi trả việc gì', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_30_6', 'en-a2-30', NULL, 'comprehensive_test', 'listening', 'There was a strange noise coming from the cupboard.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Con chó đã nhảy qua vũng nước bên cạnh cổng.","Bạn đã nghe tin tức mới nhất về người hàng xóm của chúng ta chưa?","Chúng tôi nấu chậm thịt bò cùng với cà rốt và khoai tây.","Có một âm thanh kỳ lạ phát ra từ chiếc tủ."]'::jsonb, 3, 'There was a strange noise coming from the cupboard. → Có một âm thanh kỳ lạ phát ra từ chiếc tủ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
