INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_30_8', 'en-a2-30', NULL, 'comprehensive_test', 'listening', 'Her winter coats fill most of the wardrobe.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đổ sữa lạnh lên bát ngũ cốc ăn sáng của mình.","Những chiếc áo khoác mùa đông của cô ấy chiếm phần lớn không gian tủ quần áo.","Các hướng dẫn rất rõ ràng nên tôi đã lắp ráp chiếc kệ một cách dễ dàng.","Cô ấy cất trang sức của mình trong một chiếc hộp gỗ nhỏ."]'::jsonb, 1, 'Her winter coats fill most of the wardrobe. → Những chiếc áo khoác mùa đông của cô ấy chiếm phần lớn không gian tủ quần áo.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
