INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_30_18', 'en-a2-30', NULL, 'comprehensive_test', 'reading', NULL, 'By the seventh week of the course, students were able to analyse basic scientific data independently.', 'Dựa vào câu trên, từ “seventh” có nghĩa phù hợp nhất là gì?', '["thứ bảy","xuất hiện; hiện ra","môn lướt sóng","của họ; cái của họ"]'::jsonb, 0, 'seventh: thứ bảy; một phần bảy. Dịch cả câu: Đến tuần thứ bảy của khóa học, học sinh đã có thể tự phân tích các dữ liệu khoa học cơ bản.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_30_19', 'en-a2-30', NULL, 'comprehensive_test', 'reading', NULL, 'Community gardening can improve urban environments while helping residents develop stronger social connections.', 'Dựa vào câu trên, từ “gardening” có nghĩa phù hợp nhất là gì?', '["kỳ lạ, khác thường, bất ngờ","sau đó; về sau","làm vườn; nghệ thuật làm vườn","thư ký"]'::jsonb, 2, 'gardening: làm vườn; nghệ thuật làm vườn. Dịch cả câu: Hoạt động làm vườn cộng đồng có thể cải thiện môi trường đô thị đồng thời giúp cư dân phát triển các mối quan hệ xã hội khăng khít hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_30_20', 'en-a2-30', NULL, 'comprehensive_test', 'reading', NULL, 'Investing in reliable public transport can save commuters time and reduce household travel costs.', 'Dựa vào câu trên, từ “save” có nghĩa phù hợp nhất là gì?', '["ở nước ngoài; ra nước ngoài","môi trường tự nhiên","cứu; cứu sống; bảo vệ","khách hàng; người mua"]'::jsonb, 2, 'save: cứu; cứu sống; bảo vệ; tiết kiệm; dành dụm; lưu; giữ lại. Dịch cả câu: Đầu tư vào giao thông công cộng đáng tin cậy có thể giúp người đi làm tiết kiệm thời gian và giảm chi phí đi lại của gia đình.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_30_21', 'en-a2-30', NULL, 'comprehensive_test', 'reading', NULL, 'Traditional jewellery can reflect cultural identity while providing income for skilled craftspeople in rural communities.', 'Dựa vào câu trên, từ “jewellery” có nghĩa phù hợp nhất là gì?', '["đồ trang sức; trang sức; nữ trang","chống lại; phản đối","ảnh tự chụp; ảnh selfie","nhận thấy; chú ý"]'::jsonb, 0, 'jewellery: đồ trang sức; trang sức; nữ trang. Dịch cả câu: Đồ trang sức truyền thống có thể phản ánh bản sắc văn hóa đồng thời tạo thu nhập cho các nghệ nhân lành nghề ở vùng nông thôn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_30_22', 'en-a2-30', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “món ca-ri; món rau hoặc thịt nấu với các loại gia vị”', '["curry","education","exactly","wish"]'::jsonb, 0, 'món ca-ri; món rau hoặc thịt nấu với các loại gia vị → curry (/ˈkɜːri/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_30_23', 'en-a2-30', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “bình hoa; lọ hoa”', '["barbecue","detail","photocopy","vase"]'::jsonb, 3, 'bình hoa; lọ hoa → vase (/veɪs/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_30_24', 'en-a2-30', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cái cưa; lưỡi cưa”', '["paragraph","roof","career","saw"]'::jsonb, 3, 'cái cưa; lưỡi cưa → saw (/sɔː/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-31', 'en', 'Bài 31: Đời sống hằng ngày (3) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '27 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2031, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_till', 'en-a2-31', 'till', '/tɪl/', 'A2', 'cho đến khi; đến tận; cho đến khi (sự việc xảy ra); máy tính tiền; ngăn kéo đựng tiền', 'prep.', NULL, 'Đồng nghĩa: until', 'till có nghĩa tương tự như until; khi dùng làm liên từ để nói về tương lai, nó thường đi với thì hiện tại đơn.', 'The little bakery stays open till six every evening.', NULL, 'Tiệm bánh nhỏ mở cửa đến tận sáu giờ mỗi buổi tối.', '{"wordId":"till","ukIpa":"/tɪl/","usIpa":"/tɪl/","cefr":"A2","topic":"daily","senses":[{"pos":"prep.","en":"up to a particular time","vi":"cho đến khi; đến tận"},{"pos":"conj.","en":"up to the time when something happens","vi":"cho đến khi (sự việc xảy ra)"},{"pos":"n.","en":"a machine or drawer where a shop keeps cash","vi":"máy tính tiền; ngăn kéo đựng tiền"}],"examples":[{"en":"The little bakery stays open till six every evening.","vi":"Tiệm bánh nhỏ mở cửa đến tận sáu giờ mỗi buổi tối.","audioKind":"ex"},{"en":"Some parents work till late evening, making affordable childcare essential for families in urban areas.","vi":"Một số bậc phụ huynh phải làm việc đến tận đêm muộn, điều này khiến cho dịch vụ chăm sóc trẻ với chi phí phải chăng trở nên cực kỳ quan trọng đối với các gia đình ở khu vực thành thị.","audioKind":"ex2"}],"collocations":[{"en":"till late","vi":"đến tận muộn"},{"en":"wait till","vi":"chờ cho đến khi"},{"en":"at the till","vi":"tại quầy thu ngân"}],"wordFamily":[],"synonyms":["until"],"antonyms":[],"tipVi":"till có nghĩa tương tự như until; khi dùng làm liên từ để nói về tương lai, nó thường đi với thì hiện tại đơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spaghetti', 'en-a2-31', 'spaghetti', '/spəˈɡeti/', 'A2', 'mì Ý sợi nhỏ dài', 'n.', NULL, NULL, 'Đây là danh từ không đếm được; để chỉ một phần ăn, dùng a plate of spaghetti.', 'She twirled the spaghetti around her fork before taking a bite.', NULL, 'Cô ấy cuộn mì Ý quanh chiếc nĩa trước khi ăn một miếng.', '{"wordId":"spaghetti","ukIpa":"/spəˈɡeti/","usIpa":"/spəˈɡeti/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Pasta shaped into long, thin strands.","vi":"mì Ý sợi nhỏ dài"}],"examples":[{"en":"She twirled the spaghetti around her fork before taking a bite.","vi":"Cô ấy cuộn mì Ý quanh chiếc nĩa trước khi ăn một miếng.","audioKind":"ex"},{"en":"Simple meals such as spaghetti with vegetables can help students eat affordably while maintaining a balanced diet.","vi":"Những bữa ăn đơn giản như mì Ý sốt rau củ có thể giúp học sinh ăn uống tiết kiệm mà vẫn duy trì được chế độ dinh dưỡng cân bằng.","audioKind":"ex2"}],"collocations":[{"en":"a plate of spaghetti","vi":"một đĩa mì Ý"},{"en":"spaghetti sauce","vi":"sốt mì Ý"},{"en":"cook spaghetti","vi":"nấu mì Ý"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đây là danh từ không đếm được; để chỉ một phần ăn, dùng a plate of spaghetti.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_garlic', 'en-a2-31', 'garlic', '/ˈɡɑːrlɪk/', 'A2', 'củ tỏi; tép tỏi', 'n.', NULL, NULL, 'Thường là danh từ không đếm được; một tép tỏi dùng a clove of garlic.', 'Crush the garlic before adding it to the soup.', NULL, 'Hãy đập dập tỏi trước khi cho vào món súp.', '{"wordId":"garlic","ukIpa":"/ˈɡɑːlɪk/","usIpa":"/ˈɡɑːrlɪk/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A plant whose strong-smelling bulbs are used to flavour food.","vi":"củ tỏi; tép tỏi"}],"examples":[{"en":"Crush the garlic before adding it to the soup.","vi":"Hãy đập dập tỏi trước khi cho vào món súp.","audioKind":"ex"},{"en":"Using garlic and herbs can add flavour to meals without increasing their salt content.","vi":"Sử dụng tỏi và các loại thảo mộc có thể làm tăng hương vị cho món ăn mà không làm tăng hàm lượng muối.","audioKind":"ex2"}],"collocations":[{"en":"a clove of garlic","vi":"một tép tỏi"},{"en":"crushed garlic","vi":"tỏi đập dập"},{"en":"garlic bread","vi":"bánh mì bơ tỏi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; một tép tỏi dùng a clove of garlic.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_control', 'en-a2-31', 'control', '/kənˈtroʊl/', 'A2', 'sự kiểm soát; quyền quản lý; kiểm soát; quản lý; hạn chế; bộ phận điều khiển; thiết bị vận hành', 'n.', 'controlled (adj.), uncontrolled (adj.), controller (n.), controllable (adj.)', NULL, 'Quá khứ là controlled, phân từ hiện tại là controlling đều gấp đôi chữ l.', 'Keep control of the kite by holding the string firmly.', NULL, 'Giữ chặt dây để điều khiển con diều thật tốt.', '{"wordId":"control","ukIpa":"/kənˈtrəʊl/","usIpa":"/kənˈtroʊl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"The power to direct or limit someone or something.","vi":"sự kiểm soát; quyền quản lý"},{"pos":"v.","en":"To direct, manage, or limit someone or something.","vi":"kiểm soát; quản lý; hạn chế"},{"pos":"n.","en":"A device used to operate a machine or vehicle.","vi":"bộ phận điều khiển; thiết bị vận hành"}],"examples":[{"en":"Keep control of the kite by holding the string firmly.","vi":"Giữ chặt dây để điều khiển con diều thật tốt.","audioKind":"ex"},{"en":"Stricter control of industrial emissions could improve air quality and reduce health risks in densely populated cities.","vi":"Việc kiểm soát chặt chẽ hơn đối với lượng khí thải công nghiệp có thể cải thiện chất lượng không khí và giảm thiểu rủi ro sức khỏe ở các thành phố đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"take control of","vi":"giành quyền kiểm soát"},{"en":"under control","vi":"đang nằm trong tầm kiểm soát"},{"en":"lose control","vi":"mất kiểm soát"},{"en":"control pollution","vi":"kiểm soát ô nhiễm"}],"wordFamily":["controlled (adj.)","uncontrolled (adj.)","controller (n.)","controllable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ là controlled, phân từ hiện tại là controlling đều gấp đôi chữ l.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_supper', 'en-a2-31', 'supper', '/ˈsʌpər/', 'A2', 'bữa tối; bữa ăn nhẹ trước khi đi ngủ', 'n.', NULL, 'Đồng nghĩa: evening meal', 'Thường chỉ bữa tối mang tính thân mật, gần gũi, hoặc có thể chỉ bữa ăn nhẹ trước khi đi ngủ.', 'We had soup and fresh bread for supper.', NULL, 'Chúng tôi ăn súp và bánh mì tươi cho bữa tối.', '{"wordId":"supper","ukIpa":"/ˈsʌpə/","usIpa":"/ˈsʌpər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"An evening meal, sometimes a light meal before bed.","vi":"bữa tối; bữa ăn nhẹ trước khi đi ngủ"}],"examples":[{"en":"We had soup and fresh bread for supper.","vi":"Chúng tôi ăn súp và bánh mì tươi cho bữa tối.","audioKind":"ex"},{"en":"Sharing supper regularly can help families maintain close relationships despite increasingly demanding work schedules.","vi":"Việc thường xuyên cùng nhau ăn tối có thể giúp các gia đình duy trì mối quan hệ khăng khít mặc dù lịch trình làm việc ngày càng bận rộn.","audioKind":"ex2"}],"collocations":[{"en":"have supper","vi":"ăn tối"},{"en":"a light supper","vi":"bữa tối nhẹ nhàng"},{"en":"after supper","vi":"sau bữa tối"}],"wordFamily":[],"synonyms":["evening meal"],"antonyms":[],"tipVi":"Thường chỉ bữa tối mang tính thân mật, gần gũi, hoặc có thể chỉ bữa ăn nhẹ trước khi đi ngủ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_serious', 'en-a2-31', 'serious', '/ˈsɪriəs/', 'A2', 'nghiêm trọng; trầm trọng; nghiêm túc; đàng hoàng', 'adj.', 'seriously (adv.), seriousness (n.)', 'Đồng nghĩa: severe, grave · Trái nghĩa: minor, light-hearted', 'Cụm serious about theo sau bởi danh từ hoặc danh động từ, thể hiện thái độ nghiêm túc.', 'The leaking pipe caused serious damage to our kitchen.', NULL, 'Đường ống nước bị rò rỉ đã gây ra thiệt hại nghiêm trọng cho căn bếp của chúng tôi.', '{"wordId":"serious","ukIpa":"/ˈsɪəriəs/","usIpa":"/ˈsɪriəs/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"causing harm or requiring careful attention","vi":"nghiêm trọng; trầm trọng"},{"pos":"adj.","en":"not joking, or thinking carefully about something","vi":"nghiêm túc; đàng hoàng"}],"examples":[{"en":"The leaking pipe caused serious damage to our kitchen.","vi":"Đường ống nước bị rò rỉ đã gây ra thiệt hại nghiêm trọng cho căn bếp của chúng tôi.","audioKind":"ex"},{"en":"Air pollution remains a serious threat to public health, especially in densely populated cities.","vi":"Ô nhiễm không khí vẫn là một mối đe dọa nghiêm trọng đối với sức khỏe cộng đồng, đặc biệt là ở các thành phố đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"serious damage","vi":"thiệt hại nghiêm trọng"},{"en":"serious consequences","vi":"hậu quả nghiêm trọng"},{"en":"serious about","vi":"nghiêm túc về"},{"en":"take something seriously","vi":"coi trọng việc gì"}],"wordFamily":["seriously (adv.)","seriousness (n.)"],"synonyms":["severe","grave"],"antonyms":["minor","light-hearted"],"tipVi":"Cụm serious about theo sau bởi danh từ hoặc danh động từ, thể hiện thái độ nghiêm túc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_comfortable', 'en-a2-31', 'comfortable', '/ˈkʌmftɚbl/', 'A2', 'thoải mái; dễ chịu; tự tin; sung túc; khá giả', 'adj.', 'comfort (n.), comfortably (adv.), uncomfortable (adj.), discomfort (n.)', 'Đồng nghĩa: comfy, relaxed · Trái nghĩa: uncomfortable', 'comfortable chỉ sự thoải mái; convenient chỉ sự tiện lợi.', 'This soft chair is comfortable enough for an afternoon nap.', NULL, 'Chiếc ghế êm ái này đủ thoải mái cho một giấc ngủ ngắn buổi chiều.', '{"wordId":"comfortable","ukIpa":"/ˈkʌmftəbl/","usIpa":"/ˈkʌmftɚbl/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"physically pleasant and free from discomfort","vi":"thoải mái; dễ chịu"},{"pos":"adj.","en":"feeling relaxed and confident in a situation","vi":"thoải mái; tự tin"},{"pos":"adj.","en":"having enough money to live well without financial worry","vi":"sung túc; khá giả"}],"examples":[{"en":"This soft chair is comfortable enough for an afternoon nap.","vi":"Chiếc ghế êm ái này đủ thoải mái cho một giấc ngủ ngắn buổi chiều.","audioKind":"ex"},{"en":"Comfortable classrooms with adequate lighting can help students concentrate and participate more actively in lessons.","vi":"Các phòng học thoải mái với hệ thống chiếu sáng đầy đủ có thể giúp học sinh tập trung và tham gia bài học tích cực hơn.","audioKind":"ex2"}],"collocations":[{"en":"comfortable shoes","vi":"giày thoải mái"},{"en":"feel comfortable","vi":"cảm thấy thoải mái"},{"en":"comfortable with something","vi":"thoải mái với điều gì"},{"en":"a comfortable income","vi":"thu nhập khá giả"}],"wordFamily":["comfort (n.)","comfortably (adv.)","uncomfortable (adj.)","discomfort (n.)"],"synonyms":["comfy","relaxed"],"antonyms":["uncomfortable"],"tipVi":"comfortable chỉ sự thoải mái; convenient chỉ sự tiện lợi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_among', 'en-a2-31', 'among', '/əˈmʌŋ/', 'A2', 'ở giữa; trong số; trong một nhóm; chung cho một nhóm', 'prep.', NULL, NULL, 'among nhấn mạnh nhóm đông người hoặc vật; between thường dùng cho mối quan hệ giữa hai hoặc nhiều đối tượng riêng biệt.', 'We found a small wooden house among the trees.', NULL, 'Chúng tôi tìm thấy một ngôi nhà gỗ nhỏ nằm giữa những tán cây.', '{"wordId":"among","ukIpa":"/əˈmʌŋ/","usIpa":"/əˈmʌŋ/","cefr":"A2","topic":"daily","senses":[{"pos":"prep.","en":"surrounded by people or things","vi":"ở giữa; trong số"},{"pos":"prep.","en":"within or shared by a group","vi":"trong một nhóm; chung cho một nhóm"}],"examples":[{"en":"We found a small wooden house among the trees.","vi":"Chúng tôi tìm thấy một ngôi nhà gỗ nhỏ nằm giữa những tán cây.","audioKind":"ex"},{"en":"Regular exercise is increasingly popular among office workers who spend most of their day sitting.","vi":"Việc tập thể dục thường xuyên ngày càng trở nên phổ biến đối với nhân viên văn phòng, những người phải ngồi hầu như cả ngày.","audioKind":"ex2"}],"collocations":[{"en":"among friends","vi":"giữa những người bạn"},{"en":"among other things","vi":"ngoài ra; bên cạnh những việc khác"},{"en":"divide among","vi":"chia đều cho"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"among nhấn mạnh nhóm đông người hoặc vật; between thường dùng cho mối quan hệ giữa hai hoặc nhiều đối tượng riêng biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_toast', 'en-a2-31', 'toast', '/toʊst/', 'A2', 'bánh mì nướng; nướng vàng; làm cho giòn bằng nhiệt; lời chúc rượu; sự nâng ly chúc mừng', 'n.', 'toaster (n.), toasted (adj.)', NULL, 'Danh từ chỉ món bánh mì nướng là danh từ không đếm được; chỉ lời chúc rượu là danh từ đếm được.', 'I spread butter on my toast while it was warm.', NULL, 'Tôi phết bơ lên miếng bánh mì nướng khi nó còn ấm.', '{"wordId":"toast","ukIpa":"/təʊst/","usIpa":"/toʊst/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Sliced bread browned and made crisp by heat.","vi":"bánh mì nướng"},{"pos":"v.","en":"To heat food until it becomes brown and crisp.","vi":"nướng vàng; làm cho giòn bằng nhiệt"},{"pos":"n.","en":"An occasion when people raise drinks to honour someone or something.","vi":"lời chúc rượu; sự nâng ly chúc mừng"}],"examples":[{"en":"I spread butter on my toast while it was warm.","vi":"Tôi phết bơ lên miếng bánh mì nướng khi nó còn ấm.","audioKind":"ex"},{"en":"A simple breakfast of toast and fruit can help students maintain their energy during morning lessons.","vi":"Một bữa sáng đơn giản gồm bánh mì nướng và trái cây có thể giúp học sinh duy trì năng lượng trong các tiết học buổi sáng.","audioKind":"ex2"}],"collocations":[{"en":"a slice of toast","vi":"một lát bánh mì nướng"},{"en":"toast bread","vi":"nướng bánh mì"},{"en":"propose a toast","vi":"đề nghị nâng ly"},{"en":"a toast to someone","vi":"lời chúc mừng ai đó"}],"wordFamily":["toaster (n.)","toasted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ chỉ món bánh mì nướng là danh từ không đếm được; chỉ lời chúc rượu là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_couch', 'en-a2-31', 'couch', '/kaʊtʃ/', 'A2', 'ghế sô-pha; ghế dài có tựa; diễn đạt; dùng lời lẽ để biểu đạt', 'n.', NULL, 'Đồng nghĩa: sofa', 'Động từ thường dùng ở dạng bị động be couched in, mang nghĩa được diễn đạt bằng một cách thức hoặc văn phong cụ thể.', 'We curled up on the couch after dinner.', NULL, 'Chúng tôi cuộn tròn người trên ghế sô-pha sau bữa tối.', '{"wordId":"couch","ukIpa":"/kaʊtʃ/","usIpa":"/kaʊtʃ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A comfortable seat for two or more people.","vi":"ghế sô-pha; ghế dài có tựa"},{"pos":"v.","en":"To express something in a particular way.","vi":"diễn đạt; dùng lời lẽ để biểu đạt"}],"examples":[{"en":"We curled up on the couch after dinner.","vi":"Chúng tôi cuộn tròn người trên ghế sô-pha sau bữa tối.","audioKind":"ex"},{"en":"Public health advice should be couched in clear language so that everyone can understand it.","vi":"Các khuyến nghị về y tế công cộng nên được diễn đạt bằng ngôn ngữ rõ ràng để mọi người đều có thể hiểu được.","audioKind":"ex2"}],"collocations":[{"en":"on the couch","vi":"trên ghế sô-pha"},{"en":"a leather couch","vi":"ghế sô-pha bằng da"},{"en":"couched in diplomatic terms","vi":"được diễn đạt bằng ngôn ngữ ngoại giao"}],"wordFamily":[],"synonyms":["sofa"],"antonyms":[],"tipVi":"Động từ thường dùng ở dạng bị động be couched in, mang nghĩa được diễn đạt bằng một cách thức hoặc văn phong cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_armchair', 'en-a2-31', 'armchair', '/ˈɑːrmtʃer/', 'A2', 'ghế bành; chỉ đưa ra ý kiến suông, thiếu kinh nghiệm thực tế', 'n.', NULL, NULL, 'Ngồi trong ghế bành dùng in; khi đóng vai trò là tính từ, từ này đứng trước danh từ và thường mang sắc thái châm biếm, chê bai.', 'Grandpa fell asleep in his armchair beside the window.', NULL, 'Ông đã ngủ thiếp đi trên chiếc ghế bành cạnh cửa sổ.', '{"wordId":"armchair","ukIpa":"/ˈɑːmtʃeə(r)/","usIpa":"/ˈɑːrmtʃer/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A comfortable chair with supports for your arms.","vi":"ghế bành"},{"pos":"adj.","en":"Giving opinions without direct experience or active involvement.","vi":"chỉ đưa ra ý kiến suông, thiếu kinh nghiệm thực tế"}],"examples":[{"en":"Grandpa fell asleep in his armchair beside the window.","vi":"Ông đã ngủ thiếp đi trên chiếc ghế bành cạnh cửa sổ.","audioKind":"ex"},{"en":"Armchair critics may underestimate the practical challenges that teachers face when managing large classes with limited resources.","vi":"Những nhà bình luận lý thuyết suông có thể đánh giá thấp những khó khăn thực tế mà giáo viên phải đối mặt khi quản lý các lớp học lớn với nguồn lực hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"comfortable armchair","vi":"ghế bành thoải mái"},{"en":"sit in an armchair","vi":"ngồi trên ghế bành"},{"en":"armchair critic","vi":"nhà bình luận lý thuyết suông"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Ngồi trong ghế bành dùng in; khi đóng vai trò là tính từ, từ này đứng trước danh từ và thường mang sắc thái châm biếm, chê bai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_since', 'en-a2-31', 'since', '/sɪns/', 'A2', 'từ (một thời điểm trong quá khứ) cho đến nay; từ khi; bởi vì, do; từ đó về sau, kể từ lúc đó', 'prep.', NULL, NULL, 'Khi chỉ thời gian, since đi với mốc thời gian bắt đầu, còn for đi với khoảng thời gian.', 'I have lived in this neighbourhood since childhood.', NULL, 'Tôi đã sống ở khu phố này từ khi còn nhỏ.', '{"wordId":"since","ukIpa":"/sɪns/","usIpa":"/sɪns/","cefr":"A2","topic":"daily","senses":[{"pos":"prep.","en":"from a past time until a later time, usually now","vi":"từ (một thời điểm trong quá khứ) cho đến nay"},{"pos":"conj.","en":"from when something happened; because something is true","vi":"từ khi; bởi vì, do"},{"pos":"adv.","en":"at a time or throughout the period after that","vi":"từ đó về sau, kể từ lúc đó"}],"examples":[{"en":"I have lived in this neighbourhood since childhood.","vi":"Tôi đã sống ở khu phố này từ khi còn nhỏ.","audioKind":"ex"},{"en":"Since public transport reduces traffic congestion, governments should invest in more reliable bus services.","vi":"Vì giao thông công cộng giúp giảm thiểu tình trạng tắc nghẽn giao thông, chính phủ nên đầu tư vào các dịch vụ xe buýt đáng tin cậy hơn.","audioKind":"ex2"}],"collocations":[{"en":"ever since","vi":"kể từ đó đến nay"},{"en":"since then","vi":"kể từ lúc đó"},{"en":"since childhood","vi":"từ thủa nhỏ"},{"en":"long since","vi":"từ lâu lắm rồi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ thời gian, since đi với mốc thời gian bắt đầu, còn for đi với khoảng thời gian.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tip', 'en-a2-31', 'tip', '/tɪp/', 'A2', 'mẹo hay; lời khuyên hữu ích; đầu nhọn; chóp; tiền boa', 'n.', NULL, NULL, 'Danh từ tip mang nghĩa "lời khuyên" là danh từ đếm được, khác với advice không đếm được: dùng a tip.', 'My neighbour shared a useful tip for growing tomatoes.', NULL, 'Người hàng xóm đã chia sẻ một mẹo hữu ích để trồng cà chua.', '{"wordId":"tip","ukIpa":"/tɪp/","usIpa":"/tɪp/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a useful piece of advice","vi":"mẹo hay; lời khuyên hữu ích"},{"pos":"n.","en":"the narrow or pointed end of something","vi":"đầu nhọn; chóp"},{"pos":"n.","en":"extra money given to someone for providing a service","vi":"tiền boa"}],"examples":[{"en":"My neighbour shared a useful tip for growing tomatoes.","vi":"Người hàng xóm đã chia sẻ một mẹo hữu ích để trồng cà chua.","audioKind":"ex"},{"en":"Schools can offer practical tips on managing money to help young people develop responsible spending habits.","vi":"Các trường học có thể đưa ra các mẹo thực tế về quản lý tài chính để giúp người trẻ xây dựng thói quen chi tiêu có trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"a useful tip","vi":"một mẹo hữu ích"},{"en":"the tip of the tongue","vi":"đầu lưỡi"},{"en":"leave a tip","vi":"để lại tiền boa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ tip mang nghĩa \"lời khuyên\" là danh từ đếm được, khác với advice không đếm được: dùng a tip.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_balloon', 'en-a2-31', 'balloon', '/bəˈluːn/', 'A2', 'bóng bay; khinh khí cầu', 'n.', 'ballooning (n.)', NULL, '"Blow up a balloon" có nghĩa là thổi bóng bay, không phải là làm nổ tung quả bóng.', 'A yellow balloon floated above the birthday cake.', NULL, 'Một quả bóng bay màu vàng bay lơ lửng phía trên chiếc bánh sinh nhật.', '{"wordId":"balloon","ukIpa":"/bəˈluːn/","usIpa":"/bəˈluːn/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A thin rubber bag filled with air or gas.","vi":"bóng bay"},{"pos":"n.","en":"A large gas-filled bag carrying people in a basket.","vi":"khinh khí cầu"}],"examples":[{"en":"A yellow balloon floated above the birthday cake.","vi":"Một quả bóng bay màu vàng bay lơ lửng phía trên chiếc bánh sinh nhật.","audioKind":"ex"},{"en":"Releasing balloons outdoors can harm wildlife when the rubber fragments fall into rivers and oceans.","vi":"Việc thả bóng bay ngoài trời có thể gây hại cho động vật hoang dã khi các mảnh cao su rơi xuống sông và đại dương.","audioKind":"ex2"}],"collocations":[{"en":"blow up a balloon","vi":"thổi bóng bay"},{"en":"hot-air balloon","vi":"khinh khí cầu"},{"en":"release balloons","vi":"thả bóng bay"}],"wordFamily":["ballooning (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"Blow up a balloon\" có nghĩa là thổi bóng bay, không phải là làm nổ tung quả bóng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lower', 'en-a2-31', 'lower', '/ˈloʊər/', 'A2', 'thấp hơn; ở phía dưới; hạ xuống; làm giảm', 'adj.', 'low (adj.), lowly (adj.)', 'Trái nghĩa: higher, raise', 'lower là ngoại động từ thường đi kèm tân ngữ; khi chỉ mức giá giảm, từ này cũng có thể dùng như nội động từ.', 'Keep the heavy bowls on the lower shelf.', NULL, 'Hãy để những chiếc bát nặng ở ngăn kệ dưới.', '{"wordId":"lower","ukIpa":"/ˈləʊə/","usIpa":"/ˈloʊər/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"below something else in position, level, or amount","vi":"thấp hơn; ở phía dưới"},{"pos":"v.","en":"to move something down or reduce its level","vi":"hạ xuống; làm giảm"}],"examples":[{"en":"Keep the heavy bowls on the lower shelf.","vi":"Hãy để những chiếc bát nặng ở ngăn kệ dưới.","audioKind":"ex"},{"en":"Governments can lower transport costs by investing in reliable bus services and safe cycling routes.","vi":"Chính phủ có thể giảm chi phí giao thông bằng cách đầu tư vào các dịch vụ xe buýt đáng tin cậy và làn đường dành cho xe đạp an toàn.","audioKind":"ex2"}],"collocations":[{"en":"lower income","vi":"thu nhập thấp hơn"},{"en":"lower prices","vi":"giảm giá"},{"en":"lower your voice","vi":"áp dụng giọng thấp hơn"},{"en":"lower back","vi":"vùng thắt lưng"}],"wordFamily":["low (adj.)","lowly (adj.)"],"synonyms":[],"antonyms":["higher","raise"],"tipVi":"lower là ngoại động từ thường đi kèm tân ngữ; khi chỉ mức giá giảm, từ này cũng có thể dùng như nội động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kite', 'en-a2-31', 'kite', '/kaɪt/', 'A2', 'diều; chim diều', 'n.', NULL, NULL, '“Thả diều” dùng fly a kite, không dùng play a kite.', 'We flew a bright kite on the windy beach.', NULL, 'Chúng tôi thả một con diều sặc sỡ trên bãi biển đầy gió.', '{"wordId":"kite","ukIpa":"/kaɪt/","usIpa":"/kaɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A lightweight frame flown in the wind on a string","vi":"diều"},{"pos":"n.","en":"A bird of prey with long wings and often a forked tail","vi":"chim diều"}],"examples":[{"en":"We flew a bright kite on the windy beach.","vi":"Chúng tôi thả một con diều sặc sỡ trên bãi biển đầy gió.","audioKind":"ex"},{"en":"Outdoor activities such as flying kites offer families affordable recreation and encourage children to spend time away from screens.","vi":"Các hoạt động ngoài trời như thả diều mang đến cho gia đình hình thức giải trí tiết kiệm và khuyến khích trẻ em dành thời gian rời xa màn hình thiết bị.","audioKind":"ex2"}],"collocations":[{"en":"fly a kite","vi":"thả diều"},{"en":"kite string","vi":"dây diều"},{"en":"kite flying","vi":"hoạt động thả diều"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"“Thả diều” dùng fly a kite, không dùng play a kite.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_depend', 'en-a2-31', 'depend', '/dɪˈpend/', 'A2', 'tùy thuộc; phụ thuộc; tin cậy', 'v.', 'dependence (n.), dependent (adj.), dependable (adj.), independent (adj.)', 'Đồng nghĩa: rely', 'Thường đi với on hoặc upon; It depends nghĩa là "tùy tình hình".', 'Our weekend plans depend on how the weather turns out.', NULL, 'Kế hoạch cuối tuần của chúng tôi tùy thuộc vào thời tiết thế nào.', '{"wordId":"depend","ukIpa":"/dɪˈpend/","usIpa":"/dɪˈpend/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to be determined or affected by something","vi":"tùy thuộc; phụ thuộc"},{"pos":"v.","en":"to need or trust someone or something for support","vi":"phụ thuộc; tin cậy"}],"examples":[{"en":"Our weekend plans depend on how the weather turns out.","vi":"Kế hoạch cuối tuần của chúng tôi tùy thuộc vào thời tiết thế nào.","audioKind":"ex"},{"en":"Many rural communities depend on reliable public transport to access healthcare, education, and employment opportunities.","vi":"Nhiều cộng đồng nông thôn phụ thuộc vào giao thông công cộng đáng tin cậy để tiếp cận dịch vụ y tế, giáo dục và cơ hội việc làm.","audioKind":"ex2"}],"collocations":[{"en":"depend on","vi":"tùy thuộc vào; phụ thuộc vào"},{"en":"depend heavily on","vi":"phụ thuộc nhiều vào"},{"en":"depend on someone to do something","vi":"trông chờ ai làm việc gì"}],"wordFamily":["dependence (n.)","dependent (adj.)","dependable (adj.)","independent (adj.)"],"synonyms":["rely"],"antonyms":[],"tipVi":"Thường đi với on hoặc upon; It depends nghĩa là \"tùy tình hình\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mid-day', 'en-a2-31', 'mid-day', '/ˌmɪdˈdeɪ/', 'A2', 'buổi trưa; chính ngọ', 'n.', NULL, 'Đồng nghĩa: noon · Trái nghĩa: midnight', 'Tiếng Anh hiện đại thường viết là midday; dùng at midday để chỉ thời điểm chính ngọ.', 'We stopped for lunch at mid-day beside the river.', NULL, 'Chúng tôi dừng chân ăn trưa vào lúc giữa trưa bên bờ sông.', '{"wordId":"mid-day","ukIpa":"/ˌmɪdˈdeɪ/","usIpa":"/ˌmɪdˈdeɪ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"The middle of the day, around twelve o''clock.","vi":"buổi trưa; chính ngọ"}],"examples":[{"en":"We stopped for lunch at mid-day beside the river.","vi":"Chúng tôi dừng chân ăn trưa vào lúc giữa trưa bên bờ sông.","audioKind":"ex"},{"en":"Outdoor workers should have access to shade at mid-day, when exposure to direct sunlight can be intense.","vi":"Người lao động ngoài trời nên có chỗ râm mát vào giữa trưa, khi ánh nắng chiếu trực tiếp có thể rất gay gắt.","audioKind":"ex2"}],"collocations":[{"en":"at mid-day","vi":"vào lúc giữa trưa"},{"en":"by mid-day","vi":"đến giữa trưa"},{"en":"mid-day meal","vi":"bữa trưa"}],"wordFamily":[],"synonyms":["noon"],"antonyms":["midnight"],"tipVi":"Tiếng Anh hiện đại thường viết là midday; dùng at midday để chỉ thời điểm chính ngọ.","noteVi":"Có thể viết có gân nối; ngày nay thường viết liền thành midday.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_joke', 'en-a2-31', 'joke', '/dʒoʊk/', 'A2', 'trò đùa; câu chuyện cười; nói đùa; đùa cợt', 'n.', 'joking (adj.), jokingly (adv.), joker (n.)', NULL, 'Kể chuyện cười dùng tell a joke, không dùng say a joke.', 'My brother told a joke that made everyone laugh.', NULL, 'Anh trai tôi đã kể một câu chuyện cười khiến tất cả mọi người bật cười.', '{"wordId":"joke","ukIpa":"/dʒəʊk/","usIpa":"/dʒoʊk/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Something said or done to make people laugh.","vi":"trò đùa; câu chuyện cười"},{"pos":"v.","en":"To say something funny or not seriously meant.","vi":"nói đùa; đùa cợt"}],"examples":[{"en":"My brother told a joke that made everyone laugh.","vi":"Anh trai tôi đã kể một câu chuyện cười khiến tất cả mọi người bật cười.","audioKind":"ex"},{"en":"Teachers sometimes use jokes to reduce anxiety and create a more relaxed classroom atmosphere.","vi":"Giáo viên đôi khi sử dụng những câu chuyện cười để giảm bớt sự lo lắng và tạo bầu không khí lớp học thoải mái hơn.","audioKind":"ex2"}],"collocations":[{"en":"tell a joke","vi":"kể chuyện cười"},{"en":"play a joke on someone","vi":"trọc ghẹo ai"},{"en":"joke about something","vi":"đùa giỡn về điều gì"}],"wordFamily":["joking (adj.)","jokingly (adv.)","joker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Kể chuyện cười dùng tell a joke, không dùng say a joke.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_guest', 'en-a2-31', 'guest', '/ɡest/', 'A2', 'khách; khách mời; khách lưu trú; khách trọ', 'n.', NULL, 'Đồng nghĩa: visitor · Trái nghĩa: host', 'guest có thể chỉ khách được mời hoặc khách thuê phòng trả tiền tại khách sạn.', 'Each guest brought a dish to share at dinner.', NULL, 'Mỗi vị khách mang theo một món ăn để chia sẻ trong bữa tối.', '{"wordId":"guest","ukIpa":"/ɡest/","usIpa":"/ɡest/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Someone invited to visit a home or attend an event.","vi":"khách; khách mời"},{"pos":"n.","en":"Someone staying at a hotel or similar accommodation.","vi":"khách lưu trú; khách trọ"}],"examples":[{"en":"Each guest brought a dish to share at dinner.","vi":"Mỗi vị khách mang theo một món ăn để chia sẻ trong bữa tối.","audioKind":"ex"},{"en":"Hotels can encourage guests to conserve water by offering towel replacement only when requested.","vi":"Khách sạn có thể khuyến khích khách lưu trú tiết kiệm nước bằng cách chỉ thay khăn tắm khi có yêu cầu.","audioKind":"ex2"}],"collocations":[{"en":"invite guests","vi":"mời khách"},{"en":"hotel guest","vi":"khách sạn"},{"en":"guest speaker","vi":"diễn giả khách mời"},{"en":"guest room","vi":"phòng dành cho khách"}],"wordFamily":[],"synonyms":["visitor"],"antonyms":["host"],"tipVi":"guest có thể chỉ khách được mời hoặc khách thuê phòng trả tiền tại khách sạn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dishwasher', 'en-a2-31', 'dishwasher', '/ˈdɪʃwɑːʃər/', 'A2', 'máy rửa bát; máy rửa chén; thợ rửa bát; nhân viên rửa bát', 'n.', 'dishwashing (n.)', NULL, 'Trong đời sống thường chỉ máy rửa bát; trong ngữ cảnh tuyển dụng cũng có thể chỉ thợ rửa bát.', 'Please load the dishwasher after you finish your lunch.', NULL, 'Làm ơn cho bát đĩa vào máy rửa chén sau khi ăn trưa xong nhé.', '{"wordId":"dishwasher","ukIpa":"/ˈdɪʃwɒʃə/","usIpa":"/ˈdɪʃwɑːʃər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a machine that washes dishes and kitchen utensils","vi":"máy rửa bát; máy rửa chén"},{"pos":"n.","en":"a person employed to wash dishes","vi":"thợ rửa bát; nhân viên rửa bát"}],"examples":[{"en":"Please load the dishwasher after you finish your lunch.","vi":"Làm ơn cho bát đĩa vào máy rửa chén sau khi ăn trưa xong nhé.","audioKind":"ex"},{"en":"Running a dishwasher only when it is full can help households conserve water and energy.","vi":"Chỉ chạy máy rửa bát khi đã đầy bát đĩa sẽ giúp các hộ gia đình tiết kiệm nước và năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"load the dishwasher","vi":"cho bát đĩa vào máy rửa chén"},{"en":"unload the dishwasher","vi":"lấy bát đĩa ra khỏi máy rửa chén"},{"en":"dishwasher detergent","vi":"chất tẩy rửa chuyên dụng cho máy rửa chén"}],"wordFamily":["dishwashing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong đời sống thường chỉ máy rửa bát; trong ngữ cảnh tuyển dụng cũng có thể chỉ thợ rửa bát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_completely', 'en-a2-31', 'completely', '/kəmˈpliːtli/', 'A2', 'hoàn toàn; triệt để', 'adv.', 'complete (adj.), completion (n.), incomplete (adj.)', 'Đồng nghĩa: entirely, totally, wholly · Trái nghĩa: partly', 'Biểu thị mức độ đạt đến toàn bộ, thường bổ nghĩa cho tính từ hoặc động từ.', 'My shoes were completely wet after walking through the rain.', NULL, 'Giày của tôi đã ướt sũng sau khi đi dầm mưa về.', '{"wordId":"completely","ukIpa":"/kəmˈpliːtli/","usIpa":"/kəmˈpliːtli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"In every way or to the fullest possible degree.","vi":"hoàn toàn; triệt để"}],"examples":[{"en":"My shoes were completely wet after walking through the rain.","vi":"Giày của tôi đã ướt sũng sau khi đi dầm mưa về.","audioKind":"ex"},{"en":"Although online courses offer flexibility, they cannot completely replace the social benefits of classroom learning.","vi":"Mặc dù các khóa học trực tuyến mang lại sự linh hoạt, chúng không thể hoàn toàn thay thế những lợi ích xã hội của việc học tập trên lớp.","audioKind":"ex2"}],"collocations":[{"en":"completely different","vi":"hoàn toàn khác biệt"},{"en":"completely forget","vi":"quên sạch sành sanh"},{"en":"completely agree","vi":"hoàn toàn đồng ý"}],"wordFamily":["complete (adj.)","completion (n.)","incomplete (adj.)"],"synonyms":["entirely","totally","wholly"],"antonyms":["partly"],"tipVi":"Biểu thị mức độ đạt đến toàn bộ, thường bổ nghĩa cho tính từ hoặc động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nobody', 'en-a2-31', 'nobody', '/ˈnoʊbədi/', 'A2', 'không ai; không một ai; kẻ vô danh; kẻ tầm thường', 'pron.', NULL, 'Đồng nghĩa: no one · Trái nghĩa: everybody', 'Khi làm chủ ngữ thì động từ chia ở ngôi thứ ba số ít; bản thân từ này đã mang nghĩa phủ định.', 'Nobody noticed the kitten sleeping behind the sofa.', NULL, 'Không một ai chú ý đến chú mèo con đang ngủ sau ghế sô-bìa.', '{"wordId":"nobody","ukIpa":"/ˈnəʊbədi/","usIpa":"/ˈnoʊbədi/","cefr":"A2","topic":"daily","senses":[{"pos":"pron.","en":"not a single person","vi":"không ai; không một ai"},{"pos":"n.","en":"a person considered unimportant or unknown","vi":"kẻ vô danh; kẻ tầm thường"}],"examples":[{"en":"Nobody noticed the kitten sleeping behind the sofa.","vi":"Không một ai chú ý đến chú mèo con đang ngủ sau ghế sô-bìa.","audioKind":"ex"},{"en":"Nobody should be denied access to education because their family cannot afford school fees.","vi":"Không ai nên bị tước quyền tiếp cận giáo dục chỉ vì gia đình họ không đủ khả năng đóng học phí.","audioKind":"ex2"}],"collocations":[{"en":"nobody else","vi":"không một ai khác"},{"en":"almost nobody","vi":"hầu như không có ai"},{"en":"nobody knows","vi":"không ai biết"}],"wordFamily":[],"synonyms":["no one"],"antonyms":["everybody"],"tipVi":"Khi làm chủ ngữ thì động từ chia ở ngôi thứ ba số ít; bản thân từ này đã mang nghĩa phủ định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_enter', 'en-a2-31', 'enter', '/ˈentər/', 'A2', 'đi vào; bước vào; tham gia; gia nhập; nhập dữ liệu; ghi chép', 'v.', 'entry (n.), entrance (n.), entrant (n.)', 'Trái nghĩa: exit, leave', 'Đi vào một địa điểm nào đó dùng enter a place, không đi kèm giới từ into.', 'Please wipe your shoes before you enter the kitchen.', NULL, 'Làm ơn lau giày trước khi bước vào phòng bếp.', '{"wordId":"enter","ukIpa":"/ˈentə/","usIpa":"/ˈentər/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To go or come into a place.","vi":"đi vào; bước vào"},{"pos":"v.","en":"To become involved in a competition, activity, or organisation.","vi":"tham gia; gia nhập"},{"pos":"v.","en":"To put information into a computer or official record.","vi":"nhập dữ liệu; ghi chép"}],"examples":[{"en":"Please wipe your shoes before you enter the kitchen.","vi":"Làm ơn lau giày trước khi bước vào phòng bếp.","audioKind":"ex"},{"en":"Young people often need practical training before they enter the workforce and take on professional responsibilities.","vi":"Người trẻ tuổi thường cần được đào tạo thực tế trước khi bước chân vào thị trường lao động và gánh vác các trách nhiệm chuyên môn.","audioKind":"ex2"}],"collocations":[{"en":"enter a competition","vi":"tham gia một cuộc thi"},{"en":"enter the workforce","vi":"bước chân vào thị trường lao động"},{"en":"enter data","vi":"nhập dữ liệu"},{"en":"enter a room","vi":"vào phòng"}],"wordFamily":["entry (n.)","entrance (n.)","entrant (n.)"],"synonyms":[],"antonyms":["exit","leave"],"tipVi":"Đi vào một địa điểm nào đó dùng enter a place, không đi kèm giới từ into.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_awful', 'en-a2-31', 'awful', '/ˈɔːfəl/', 'A2', 'tệ hại; khó chịu', 'adj.', 'awfully (adv.), awfulness (n.)', 'Đồng nghĩa: terrible, dreadful · Trái nghĩa: wonderful', 'feel awful có thể chỉ cơ thể khó chịu, cũng có thể chỉ cảm giác ân hận hoặc tâm trạng tồi tệ.', 'The soup tasted awful, so I made a sandwich.', NULL, 'Món súp có vị rất tệ, thế nên tôi đã làm một chiếc bánh mì kẹp.', '{"wordId":"awful","ukIpa":"/ˈɔːfəl/","usIpa":"/ˈɔːfəl/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Extremely bad or unpleasant.","vi":"tệ hại; khó chịu"}],"examples":[{"en":"The soup tasted awful, so I made a sandwich.","vi":"Món súp có vị rất tệ, thế nên tôi đã làm một chiếc bánh mì kẹp.","audioKind":"ex"},{"en":"Residents described the awful conditions in overcrowded housing and called for stricter safety standards.","vi":"Cư dân đã mô tả các điều kiện sống tồi tệ trong những khu nhà ở chật chội và kêu gọi các tiêu chuẩn an toàn nghiêm ngặt hơn.","audioKind":"ex2"}],"collocations":[{"en":"awful weather","vi":"thời tiết tồi tệ"},{"en":"feel awful","vi":"cảm thấy khó chịu"},{"en":"awful smell","vi":"mùi khó ngửi"}],"wordFamily":["awfully (adv.)","awfulness (n.)"],"synonyms":["terrible","dreadful"],"antonyms":["wonderful"],"tipVi":"feel awful có thể chỉ cơ thể khó chịu, cũng có thể chỉ cảm giác ân hận hoặc tâm trạng tồi tệ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bathtub', 'en-a2-31', 'bathtub', '/ˈbæθtʌb/', 'A2', 'bồn tắm', 'n.', NULL, 'Đồng nghĩa: bath, tub', 'bathtub thường dùng trong tiếng Anh-Mỹ; tiếng Anh-Anh hay dùng bath.', 'The kitten watched water dripping into the empty bathtub.', NULL, 'Chú mèo con nhìn nước nhỏ giọt vào chiếc bồn tắm trống không.', '{"wordId":"bathtub","ukIpa":"/ˈbɑːθtʌb/","usIpa":"/ˈbæθtʌb/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A large container that you sit in to wash your body.","vi":"bồn tắm"}],"examples":[{"en":"The kitten watched water dripping into the empty bathtub.","vi":"Chú mèo con nhìn nước nhỏ giọt vào chiếc bồn tắm trống không.","audioKind":"ex"},{"en":"Replacing a bathtub with a shower can save space in small urban apartments.","vi":"Việc thay thế bồn tắm bằng buồng tắm đứng có thể tiết kiệm không gian trong các căn hộ đô thị nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"fill the bathtub","vi":"xả nước đầy bồn tắm"},{"en":"an empty bathtub","vi":"bồn tắm trống không"},{"en":"a freestanding bathtub","vi":"bồn tắm đặt độc lập"}],"wordFamily":[],"synonyms":["bath","tub"],"antonyms":[],"tipVi":"bathtub thường dùng trong tiếng Anh-Mỹ; tiếng Anh-Anh hay dùng bath.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mailbox', 'en-a2-31', 'mailbox', '/ˈmeɪlbɑːks/', 'A2', 'hòm thư; hộp thư; hộp thư điện tử', 'n.', 'mail (n.), mail (v.)', NULL, 'Là từ phổ biến trong tiếng Mỹ; tiếng Anh-Anh thường dùng letterbox hoặc postbox.', 'A postcard from my cousin arrived in our mailbox.', NULL, 'Một tấm bưu thiếp từ người anh họ đã được gửi đến hòm thư nhà chúng tôi.', '{"wordId":"mailbox","ukIpa":"/ˈmeɪlbɒks/","usIpa":"/ˈmeɪlbɑːks/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A box where letters are delivered or collected.","vi":"hòm thư; hộp thư"},{"pos":"n.","en":"An electronic space where email messages are received and stored.","vi":"hộp thư điện tử"}],"examples":[{"en":"A postcard from my cousin arrived in our mailbox.","vi":"Một tấm bưu thiếp từ người anh họ đã được gửi đến hòm thư nhà chúng tôi.","audioKind":"ex"},{"en":"Residents in remote areas may travel considerable distances to reach the nearest public mailbox.","vi":"Cư dân ở các vùng sâu vùng xa có thể phải di chuyển một quãng đường dài để đến được hòm thư công cộng gần nhất.","audioKind":"ex2"}],"collocations":[{"en":"check your mailbox","vi":"kiểm tra hòm thư"},{"en":"an overflowing mailbox","vi":"hòm thư đầy ắp"},{"en":"an electronic mailbox","vi":"hộp thư điện tử"}],"wordFamily":["mail (n.)","mail (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Là từ phổ biến trong tiếng Mỹ; tiếng Anh-Anh thường dùng letterbox hoặc postbox.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_31_1', 'en-a2-31', 'Cách dùng “armchair” (n.) — ghế bành', 'comfortable armchair  ·  sit in an armchair  ·  armchair critic', 'Ngồi trong ghế bành dùng in; khi đóng vai trò là tính từ, từ này đứng trước danh từ và thường mang sắc thái châm biếm, chê bai.', NULL, '[{"hanzi":"Grandpa fell asleep in his armchair beside the window.","pinyin":"","meaning":"Ông đã ngủ thiếp đi trên chiếc ghế bành cạnh cửa sổ."},{"hanzi":"Armchair critics may underestimate the practical challenges that teachers face when managing large classes with limited resources.","pinyin":"","meaning":"Những nhà bình luận lý thuyết suông có thể đánh giá thấp những khó khăn thực tế mà giáo viên phải đối mặt khi quản lý các lớp học lớn với nguồn lực hạn chế."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_31_2', 'en-a2-31', 'Cách dùng “among” (prep.) — ở giữa; trong số', 'among friends  ·  among other things  ·  divide among', 'among nhấn mạnh nhóm đông người hoặc vật; between thường dùng cho mối quan hệ giữa hai hoặc nhiều đối tượng riêng biệt.', NULL, '[{"hanzi":"We found a small wooden house among the trees.","pinyin":"","meaning":"Chúng tôi tìm thấy một ngôi nhà gỗ nhỏ nằm giữa những tán cây."},{"hanzi":"Regular exercise is increasingly popular among office workers who spend most of their day sitting.","pinyin":"","meaning":"Việc tập thể dục thường xuyên ngày càng trở nên phổ biến đối với nhân viên văn phòng, những người phải ngồi hầu như cả ngày."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_31_3', 'en-a2-31', 'Cách dùng “couch” (n.) — ghế sô-pha; ghế dài có tựa', 'on the couch  ·  a leather couch  ·  couched in diplomatic terms', 'Động từ thường dùng ở dạng bị động be couched in, mang nghĩa được diễn đạt bằng một cách thức hoặc văn phong cụ thể.', 'Đồng nghĩa: sofa', '[{"hanzi":"We curled up on the couch after dinner.","pinyin":"","meaning":"Chúng tôi cuộn tròn người trên ghế sô-pha sau bữa tối."},{"hanzi":"Public health advice should be couched in clear language so that everyone can understand it.","pinyin":"","meaning":"Các khuyến nghị về y tế công cộng nên được diễn đạt bằng ngôn ngữ rõ ràng để mọi người đều có thể hiểu được."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_31_4', 'en-a2-31', 'Cách dùng “till” (prep.) — cho đến khi; đến tận', 'till late  ·  wait till  ·  at the till', 'till có nghĩa tương tự như until; khi dùng làm liên từ để nói về tương lai, nó thường đi với thì hiện tại đơn.', 'Đồng nghĩa: until', '[{"hanzi":"The little bakery stays open till six every evening.","pinyin":"","meaning":"Tiệm bánh nhỏ mở cửa đến tận sáu giờ mỗi buổi tối."},{"hanzi":"Some parents work till late evening, making affordable childcare essential for families in urban areas.","pinyin":"","meaning":"Một số bậc phụ huynh phải làm việc đến tận đêm muộn, điều này khiến cho dịch vụ chăm sóc trẻ với chi phí phải chăng trở nên cực kỳ quan trọng đối với các gia đình ở khu vực thành thị."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_31_1', 'en-a2-31', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
