INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_31_1_2', 'ten_a2_31_1', 'spaghetti', 'She twirled the spaghetti around her fork before taking a bite.', 'She twirled the spaghetti around her fork before taking a bite.', '/spəˈɡeti/', 'Cô ấy cuộn mì Ý quanh chiếc nĩa trước khi ăn một miếng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_31_1_3', 'ten_a2_31_1', 'garlic', 'Crush the garlic before adding it to the soup.', 'Crush the garlic before adding it to the soup.', '/ˈɡɑːrlɪk/', 'Hãy đập dập tỏi trước khi cho vào món súp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_31_1_4', 'ten_a2_31_1', 'control', 'Keep control of the kite by holding the string firmly.', 'Keep control of the kite by holding the string firmly.', '/kənˈtroʊl/', 'Giữ chặt dây để điều khiển con diều thật tốt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_31_1_5', 'ten_a2_31_1', 'supper', 'We had soup and fresh bread for supper.', 'We had soup and fresh bread for supper.', '/ˈsʌpər/', 'Chúng tôi ăn súp và bánh mì tươi cho bữa tối.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_31_1_6', 'ten_a2_31_1', 'serious', 'The leaking pipe caused serious damage to our kitchen.', 'The leaking pipe caused serious damage to our kitchen.', '/ˈsɪriəs/', 'Đường ống nước bị rò rỉ đã gây ra thiệt hại nghiêm trọng cho căn bếp của chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_31_1_7', 'ten_a2_31_1', 'comfortable', 'This soft chair is comfortable enough for an afternoon nap.', 'This soft chair is comfortable enough for an afternoon nap.', '/ˈkʌmftɚbl/', 'Chiếc ghế êm ái này đủ thoải mái cho một giấc ngủ ngắn buổi chiều.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_31_1_8', 'ten_a2_31_1', 'among', 'We found a small wooden house among the trees.', 'We found a small wooden house among the trees.', '/əˈmʌŋ/', 'Chúng tôi tìm thấy một ngôi nhà gỗ nhỏ nằm giữa những tán cây.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_31_1_1', 'en-a2-31', 'ten_a2_31_1', 'listening', 'listening', 'The little bakery stays open till six every evening.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi cuộn tròn người trên ghế sô-pha sau bữa tối.","Anh trai tôi đã kể một câu chuyện cười khiến tất cả mọi người bật cười.","Tiệm bánh nhỏ mở cửa đến tận sáu giờ mỗi buổi tối.","Làm ơn cho bát đĩa vào máy rửa chén sau khi ăn trưa xong nhé."]'::jsonb, 2, 'The little bakery stays open till six every evening. → Tiệm bánh nhỏ mở cửa đến tận sáu giờ mỗi buổi tối.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_31_1_2', 'en-a2-31', 'ten_a2_31_1', 'listening', 'listening', 'She twirled the spaghetti around her fork before taking a bite.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy cuộn mì Ý quanh chiếc nĩa trước khi ăn một miếng.","Chiếc ghế êm ái này đủ thoải mái cho một giấc ngủ ngắn buổi chiều.","Chúng tôi ăn súp và bánh mì tươi cho bữa tối.","Kế hoạch cuối tuần của chúng tôi tùy thuộc vào thời tiết thế nào."]'::jsonb, 0, 'She twirled the spaghetti around her fork before taking a bite. → Cô ấy cuộn mì Ý quanh chiếc nĩa trước khi ăn một miếng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_31_1_3', 'en-a2-31', 'ten_a2_31_1', 'listening', 'listening', 'Crush the garlic before adding it to the soup.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi cuộn tròn người trên ghế sô-pha sau bữa tối.","Hãy để những chiếc bát nặng ở ngăn kệ dưới.","Hãy đập dập tỏi trước khi cho vào món súp.","Cô ấy cuộn mì Ý quanh chiếc nĩa trước khi ăn một miếng."]'::jsonb, 2, 'Crush the garlic before adding it to the soup. → Hãy đập dập tỏi trước khi cho vào món súp.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_31_2', 'en-a2-31', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_31_2_1', 'ten_a2_31_2', 'till', 'Some parents work till late evening, making affordable childcare essential for families in urban areas.', 'Some parents work till late evening, making affordable childcare essential for families in urban areas.', '/tɪl/', 'Một số bậc phụ huynh phải làm việc đến tận đêm muộn, điều này khiến cho dịch vụ chăm sóc trẻ với chi phí phải chăng trở nên cực kỳ quan trọng đối với các gia đình ở khu vực thành thị.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_31_2_2', 'ten_a2_31_2', 'spaghetti', 'Simple meals such as spaghetti with vegetables can help students eat affordably while maintaining a balanced diet.', 'Simple meals such as spaghetti with vegetables can help students eat affordably while maintaining a balanced diet.', '/spəˈɡeti/', 'Những bữa ăn đơn giản như mì Ý sốt rau củ có thể giúp học sinh ăn uống tiết kiệm mà vẫn duy trì được chế độ dinh dưỡng cân bằng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_31_2_3', 'ten_a2_31_2', 'garlic', 'Using garlic and herbs can add flavour to meals without increasing their salt content.', 'Using garlic and herbs can add flavour to meals without increasing their salt content.', '/ˈɡɑːrlɪk/', 'Sử dụng tỏi và các loại thảo mộc có thể làm tăng hương vị cho món ăn mà không làm tăng hàm lượng muối.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_31_2_4', 'ten_a2_31_2', 'control', 'Stricter control of industrial emissions could improve air quality and reduce health risks in densely populated cities.', 'Stricter control of industrial emissions could improve air quality and reduce health risks in densely populated cities.', '/kənˈtroʊl/', 'Việc kiểm soát chặt chẽ hơn đối với lượng khí thải công nghiệp có thể cải thiện chất lượng không khí và giảm thiểu rủi ro sức khỏe ở các thành phố đông dân cư.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_31_2_5', 'ten_a2_31_2', 'supper', 'Sharing supper regularly can help families maintain close relationships despite increasingly demanding work schedules.', 'Sharing supper regularly can help families maintain close relationships despite increasingly demanding work schedules.', '/ˈsʌpər/', 'Việc thường xuyên cùng nhau ăn tối có thể giúp các gia đình duy trì mối quan hệ khăng khít mặc dù lịch trình làm việc ngày càng bận rộn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_31_2_6', 'ten_a2_31_2', 'serious', 'Air pollution remains a serious threat to public health, especially in densely populated cities.', 'Air pollution remains a serious threat to public health, especially in densely populated cities.', '/ˈsɪriəs/', 'Ô nhiễm không khí vẫn là một mối đe dọa nghiêm trọng đối với sức khỏe cộng đồng, đặc biệt là ở các thành phố đông dân cư.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_31_2_1', 'en-a2-31', 'ten_a2_31_2', 'listening', 'listening', 'Some parents work till late evening, making affordable childcare essential for families in urban areas.', NULL, 'Trong câu vừa nghe, từ “till” mang nghĩa nào sau đây?', '["hét; la lớn; gọi lớn","thất bại; không làm được việc gì đó","cho đến khi; đến tận","lãng phí"]'::jsonb, 2, '“till” (/tɪl/): cho đến khi; đến tận. Câu đầy đủ: Some parents work till late evening, making affordable childcare essential for families in urban areas.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_31_2_2', 'en-a2-31', 'ten_a2_31_2', 'listening', 'listening', 'Simple meals such as spaghetti with vegetables can help students eat affordably while maintaining a balanced diet.', NULL, 'Trong câu vừa nghe, từ “spaghetti” mang nghĩa nào sau đây?', '["có màu sắc; được nhuộm màu","tuyệt vời; đáng kinh ngạc","mì Ý sợi nhỏ dài","khu phố; vùng lân cận"]'::jsonb, 2, '“spaghetti” (/spəˈɡeti/): mì Ý sợi nhỏ dài. Câu đầy đủ: Simple meals such as spaghetti with vegetables can help students eat affordably while maintaining a balanced diet.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
