INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_31_2', 'en-a2-31', NULL, 'comprehensive_test', 'listening', 'She twirled the spaghetti around her fork before taking a bite.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi ăn súp và bánh mì tươi cho bữa tối.","Chúng tôi thả một con diều sặc sỡ trên bãi biển đầy gió.","Anh trai tôi đã kể một câu chuyện cười khiến tất cả mọi người bật cười.","Cô ấy cuộn mì Ý quanh chiếc nĩa trước khi ăn một miếng."]'::jsonb, 3, 'She twirled the spaghetti around her fork before taking a bite. → Cô ấy cuộn mì Ý quanh chiếc nĩa trước khi ăn một miếng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
