INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_31_6', 'en-a2-31', NULL, 'comprehensive_test', 'listening', 'The leaking pipe caused serious damage to our kitchen.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi phết bơ lên miếng bánh mì nướng khi nó còn ấm.","Hãy đập dập tỏi trước khi cho vào món súp.","Đường ống nước bị rò rỉ đã gây ra thiệt hại nghiêm trọng cho căn bếp của chúng tôi.","Làm ơn lau giày trước khi bước vào phòng bếp."]'::jsonb, 2, 'The leaking pipe caused serious damage to our kitchen. → Đường ống nước bị rò rỉ đã gây ra thiệt hại nghiêm trọng cho căn bếp của chúng tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
