INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_31_8', 'en-a2-31', NULL, 'comprehensive_test', 'listening', 'We found a small wooden house among the trees.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi tìm thấy một ngôi nhà gỗ nhỏ nằm giữa những tán cây.","Mỗi vị khách mang theo một món ăn để chia sẻ trong bữa tối.","Hãy đập dập tỏi trước khi cho vào món súp.","Hãy để những chiếc bát nặng ở ngăn kệ dưới."]'::jsonb, 0, 'We found a small wooden house among the trees. → Chúng tôi tìm thấy một ngôi nhà gỗ nhỏ nằm giữa những tán cây.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_31_9', 'en-a2-31', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “An evening meal, sometimes a light meal before bed.”?', '["supper","spaghetti","depend","armchair"]'::jsonb, 0, 'supper (/ˈsʌpər/) → bữa tối; bữa ăn nhẹ trước khi đi ngủ', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
