INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_31_18', 'en-a2-31', NULL, 'comprehensive_test', 'reading', NULL, 'Some parents work till late evening, making affordable childcare essential for families in urban areas.', 'Dựa vào câu trên, từ “till” có nghĩa phù hợp nhất là gì?', '["cho đến khi; đến tận","nhật ký; sổ nhật ký","thấp hơn; ở phía dưới","nhạc công; nghệ sĩ âm nhạc; nhạc sĩ"]'::jsonb, 0, 'till: cho đến khi; đến tận; cho đến khi (sự việc xảy ra); máy tính tiền; ngăn kéo đựng tiền. Dịch cả câu: Một số bậc phụ huynh phải làm việc đến tận đêm muộn, điều này khiến cho dịch vụ chăm sóc trẻ với chi phí phải chăng trở nên cực kỳ quan trọng đối với các gia đình ở khu vực thành thị.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_31_19', 'en-a2-31', NULL, 'comprehensive_test', 'reading', NULL, 'Simple meals such as spaghetti with vegetables can help students eat affordably while maintaining a balanced diet.', 'Dựa vào câu trên, từ “spaghetti” có nghĩa phù hợp nhất là gì?', '["tưởng tượng; hình dung","đá; hòn đá","mì Ý sợi nhỏ dài","chó con, con chó nhỏ"]'::jsonb, 2, 'spaghetti: mì Ý sợi nhỏ dài. Dịch cả câu: Những bữa ăn đơn giản như mì Ý sốt rau củ có thể giúp học sinh ăn uống tiết kiệm mà vẫn duy trì được chế độ dinh dưỡng cân bằng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_31_20', 'en-a2-31', NULL, 'comprehensive_test', 'reading', NULL, 'Using garlic and herbs can add flavour to meals without increasing their salt content.', 'Dựa vào câu trên, từ “garlic” có nghĩa phù hợp nhất là gì?', '["mỏng; mảnh","củ tỏi; tép tỏi","tạo ra; sáng tạo","chính phủ; cơ quan quản lý nhà nước"]'::jsonb, 1, 'garlic: củ tỏi; tép tỏi. Dịch cả câu: Sử dụng tỏi và các loại thảo mộc có thể làm tăng hương vị cho món ăn mà không làm tăng hàm lượng muối.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_31_21', 'en-a2-31', NULL, 'comprehensive_test', 'reading', NULL, 'Stricter control of industrial emissions could improve air quality and reduce health risks in densely populated cities.', 'Dựa vào câu trên, từ “control” có nghĩa phù hợp nhất là gì?', '["sự kiểm soát; quyền quản lý","hình vuông","tổng thống","sau đó; về sau"]'::jsonb, 0, 'control: sự kiểm soát; quyền quản lý; kiểm soát; quản lý; hạn chế; bộ phận điều khiển; thiết bị vận hành. Dịch cả câu: Việc kiểm soát chặt chẽ hơn đối với lượng khí thải công nghiệp có thể cải thiện chất lượng không khí và giảm thiểu rủi ro sức khỏe ở các thành phố đông dân cư.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
