INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-32', 'en', 'Bài 32: Đời sống hằng ngày (4) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '27 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2032, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_habit', 'en-a2-32', 'habit', '/ˈhæbɪt/', 'A2', 'thói quen; tập quán', 'n.', 'habitual (adj.), habitually (adv.)', NULL, 'Để diễn đạt thói quen làm việc gì, dùng habit of doing.', 'Checking my phone before breakfast has become a habit.', NULL, 'Thói quen kiểm tra điện thoại trước bữa sáng đã trở thành một phần trong sinh hoạt của tôi.', '{"wordId":"habit","ukIpa":"/ˈhæbɪt/","usIpa":"/ˈhæbɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"something you do regularly, often without thinking","vi":"thói quen; tập quán"}],"examples":[{"en":"Checking my phone before breakfast has become a habit.","vi":"Thói quen kiểm tra điện thoại trước bữa sáng đã trở thành một phần trong sinh hoạt của tôi.","audioKind":"ex"},{"en":"Developing the habit of regular exercise during childhood can improve health throughout adult life.","vi":"Việc hình thành thói quen tập thể dục đều đặn từ thời thơ ấu có thể cải thiện tình trạng sức khỏe trong suốt quãng đời trưởng thành.","audioKind":"ex2"}],"collocations":[{"en":"form a habit","vi":"hình thành thói quen"},{"en":"break a habit","vi":"từ bỏ thói quen"},{"en":"out of habit","vi":"vì thói quen"},{"en":"get into the habit of","vi":"tập thói quen làm gì"}],"wordFamily":["habitual (adj.)","habitually (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Để diễn đạt thói quen làm việc gì, dùng habit of doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drawer', 'en-a2-32', 'drawer', '/drɔːr/', 'A2', 'ngăn kéo; hộc tủ', 'n.', NULL, NULL, 'Ngăn kéo là drawer; tủ quần áo là wardrobe.', 'I keep spare keys in the top kitchen drawer.', NULL, 'Tôi cất chìa khóa dự phòng trong ngăn kéo tủ bếp trên cùng.', '{"wordId":"drawer","ukIpa":"/drɔː/","usIpa":"/drɔːr/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a sliding storage compartment in a desk or other furniture","vi":"ngăn kéo; hộc tủ"}],"examples":[{"en":"I keep spare keys in the top kitchen drawer.","vi":"Tôi cất chìa khóa dự phòng trong ngăn kéo tủ bếp trên cùng.","audioKind":"ex"},{"en":"Office desks with lockable drawers help employees store personal belongings securely in shared working environments.","vi":"Bàn làm việc có ngăn kéo khóa được giúp nhân viên cất giữ đồ đạc cá nhân an toàn trong môi trường làm việc chung.","audioKind":"ex2"}],"collocations":[{"en":"open a drawer","vi":"mở ngăn kéo"},{"en":"top drawer","vi":"ngăn kéo trên cùng"},{"en":"desk drawer","vi":"ngăn kéo bàn làm việc"},{"en":"chest of drawers","vi":"tủ có ngăn kéo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Ngăn kéo là drawer; tủ quần áo là wardrobe.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rubber', 'en-a2-32', 'rubber', '/ˈrʌbər/', 'A2', 'cao su; cục tẩy; gôm', 'n.', 'rubbery (adj.)', NULL, 'Cao su là danh từ không đếm được; cục tẩy đếm được, tiếng Anh-Mỹ thường dùng eraser.', 'These rubber boots keep my feet dry in puddles.', NULL, 'Đôi bốt cao su này giúp chân tôi không bị ướt khi đi vào vũng nước.', '{"wordId":"rubber","ukIpa":"/ˈrʌbə/","usIpa":"/ˈrʌbər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"an elastic material used to make tyres and other products","vi":"cao su"},{"pos":"n.","en":"a small object used to remove pencil marks","vi":"cục tẩy; gôm"}],"examples":[{"en":"These rubber boots keep my feet dry in puddles.","vi":"Đôi bốt cao su này giúp chân tôi không bị ướt khi đi vào vũng nước.","audioKind":"ex"},{"en":"Recycling rubber from used tyres can reduce waste and provide material for safer playground surfaces.","vi":"Tái chế cao su từ lốp xe cũ có thể giảm rác thải và cung cấp vật liệu cho bề mặt sân chơi an toàn hơn.","audioKind":"ex2"}],"collocations":[{"en":"natural rubber","vi":"cao su tự nhiên"},{"en":"rubber band","vi":"dây thun; dây cao su"},{"en":"rubber gloves","vi":"găng tay cao su"},{"en":"rubber boots","vi":"bốt cao su"}],"wordFamily":["rubbery (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cao su là danh từ không đếm được; cục tẩy đếm được, tiếng Anh-Mỹ thường dùng eraser.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mix', 'en-a2-32', 'mix', '/mɪks/', 'A2', 'trộn; pha trộn; hòa trộn; hỗn hợp; sự kết hợp; giao du; hòa nhập; kết bạn', 'v.', 'mixture (n.), mixed (adj.), mixer (n.)', 'Đồng nghĩa: blend, combine · Trái nghĩa: separate', 'mix A with B chỉ sự trộn lẫn; mix A up with B chỉ sự nhầm lẫn.', 'Mix the flour and eggs in a large bowl.', NULL, 'Trộn đều bột mì và trứng trong một cái tô lớn.', '{"wordId":"mix","ukIpa":"/mɪks/","usIpa":"/mɪks/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To combine different substances or things.","vi":"trộn; pha trộn; hòa trộn"},{"pos":"n.","en":"A combination of different substances, people, or things.","vi":"hỗn hợp; sự kết hợp"},{"pos":"v.","en":"To spend time socially with other people.","vi":"giao du; hòa nhập; kết bạn"}],"examples":[{"en":"Mix the flour and eggs in a large bowl.","vi":"Trộn đều bột mì và trứng trong một cái tô lớn.","audioKind":"ex"},{"en":"Successful neighbourhoods often contain a mix of housing types that serve people with different incomes.","vi":"Các khu dân cư thành công thường bao gồm sự kết hợp của nhiều loại nhà ở phục vụ cho người có mức thu nhập khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"mix ingredients","vi":"trộn các nguyên liệu"},{"en":"mix with others","vi":"giao lưu với người khác"},{"en":"a diverse mix","vi":"sự kết hợp đa dạng"},{"en":"mix things up","vi":"làm xáo trộn mọi thứ"}],"wordFamily":["mixture (n.)","mixed (adj.)","mixer (n.)"],"synonyms":["blend","combine"],"antonyms":["separate"],"tipVi":"mix A with B chỉ sự trộn lẫn; mix A up with B chỉ sự nhầm lẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shampoo', 'en-a2-32', 'shampoo', '/ʃæmˈpuː/', 'A2', 'dầu gội đầu; gội đầu bằng dầu gội', 'n.', NULL, NULL, 'Danh từ chỉ chung dầu gội thường không đếm được; một chai dùng a bottle of shampoo.', 'I packed a small bottle of shampoo for our trip.', NULL, 'Tôi đã mang theo một chai dầu gội nhỏ cho chuyến đi chơi của chúng tôi.', '{"wordId":"shampoo","ukIpa":"/ʃæmˈpuː/","usIpa":"/ʃæmˈpuː/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a liquid product used to wash hair","vi":"dầu gội đầu"},{"pos":"v.","en":"to wash hair using shampoo","vi":"gội đầu bằng dầu gội"}],"examples":[{"en":"I packed a small bottle of shampoo for our trip.","vi":"Tôi đã mang theo một chai dầu gội nhỏ cho chuyến đi chơi của chúng tôi.","audioKind":"ex"},{"en":"Using refillable shampoo containers can reduce plastic waste generated by households and the tourism industry.","vi":"Sử dụng chai dầu gội có thể đổ đầy lại giúp giảm thiểu rác thải nhựa do các hộ gia đình và ngành du lịch tạo ra.","audioKind":"ex2"}],"collocations":[{"en":"a bottle of shampoo","vi":"một chai dầu gội đầu"},{"en":"mild shampoo","vi":"dầu gội dịu nhẹ"},{"en":"shampoo your hair","vi":"gội đầu của bạn"},{"en":"dry shampoo","vi":"dầu gội khô"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ chỉ chung dầu gội thường không đếm được; một chai dùng a bottle of shampoo.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heater', 'en-a2-32', 'heater', '/ˈhiːtər/', 'A2', 'máy sưởi; thiết bị sưởi ấm', 'n.', 'heat (n.), heat (v.), heating (n.), heated (adj.)', NULL, 'heater chỉ thiết bị; heating chỉ hệ thống sưởi hoặc sự sưởi ấm.', 'We switched on the heater before the guests arrived.', NULL, 'Chúng tôi đã bật máy sưởi trước khi khách đến.', '{"wordId":"heater","ukIpa":"/ˈhiːtə/","usIpa":"/ˈhiːtər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a device that heats air, water, or another substance","vi":"máy sưởi; thiết bị sưởi ấm"}],"examples":[{"en":"We switched on the heater before the guests arrived.","vi":"Chúng tôi đã bật máy sưởi trước khi khách đến.","audioKind":"ex"},{"en":"Replacing an inefficient water heater can lower household energy bills and reduce overall electricity consumption.","vi":"Việc thay thế một bình đun nước nóng kém hiệu quả có thể làm giảm hóa đơn năng lượng của gia đình và cắt giảm tổng lượng điện tiêu thụ.","audioKind":"ex2"}],"collocations":[{"en":"electric heater","vi":"máy sưởi điện"},{"en":"water heater","vi":"bình nóng lạnh; máy nước nóng"},{"en":"portable heater","vi":"máy sưởi di động"}],"wordFamily":["heat (n.)","heat (v.)","heating (n.)","heated (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"heater chỉ thiết bị; heating chỉ hệ thống sưởi hoặc sự sưởi ấm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_store', 'en-a2-32', 'store', '/stɔːr/', 'A2', 'cửa hàng; tiệm; cất giữ; lưu trữ; tích trữ; sự dự trữ; kho dự trữ', 'n.', 'storage (n.), storekeeper (n.)', 'Đồng nghĩa: shop, keep', 'Trong tiếng Anh-Mỹ thường dùng store, trong khi tiếng Anh-Anh hàng ngày chuộng dùng shop hơn.', 'The store near our house sells fresh bread.', NULL, 'Cửa hàng gần nhà chúng tôi bán bánh mì tươi.', '{"wordId":"store","ukIpa":"/stɔː/","usIpa":"/stɔːr/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a place where people buy goods","vi":"cửa hàng; tiệm"},{"pos":"v.","en":"to keep something somewhere for future use","vi":"cất giữ; lưu trữ; tích trữ"},{"pos":"n.","en":"a supply of something kept for future use","vi":"sự dự trữ; kho dự trữ"}],"examples":[{"en":"The store near our house sells fresh bread.","vi":"Cửa hàng gần nhà chúng tôi bán bánh mì tươi.","audioKind":"ex"},{"en":"Modern batteries can store energy from solar panels for use when sunlight is no longer available.","vi":"Pin hiện đại có thể lưu trữ năng lượng từ các tấm pin mặt trời để sử dụng khi không có ánh nắng mặt trời.","audioKind":"ex2"}],"collocations":[{"en":"department store","vi":"cửa hàng bách hóa"},{"en":"store data","vi":"lưu trữ dữ liệu"},{"en":"store food","vi":"tích trữ thực phẩm"},{"en":"a store of knowledge","vi":"kho tàng kiến thức"}],"wordFamily":["storage (n.)","storekeeper (n.)"],"synonyms":["shop","keep"],"antonyms":[],"tipVi":"Trong tiếng Anh-Mỹ thường dùng store, trong khi tiếng Anh-Anh hàng ngày chuộng dùng shop hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_item', 'en-a2-32', 'item', '/ˈaɪtəm/', 'A2', 'món đồ; vật phẩm; mục; điều khoản; mẩu tin', 'n.', 'itemise (v.), itemisation (n.)', NULL, 'item là danh từ đếm được; một món trang phục có thể nói là an item of clothing.', 'Please place each item carefully in the shopping bag.', NULL, 'Xin vui lòng đặt cẩn thận từng món đồ vào trong túi mua sắm.', '{"wordId":"item","ukIpa":"/ˈaɪtəm/","usIpa":"/ˈaɪtəm/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A single object, especially one in a collection.","vi":"món đồ; vật phẩm"},{"pos":"n.","en":"One part of a list, programme, or news report.","vi":"mục; điều khoản; mẩu tin"}],"examples":[{"en":"Please place each item carefully in the shopping bag.","vi":"Xin vui lòng đặt cẩn thận từng món đồ vào trong túi mua sắm.","audioKind":"ex"},{"en":"Each item on the meeting agenda addresses a different challenge facing local public transport services.","vi":"Mỗi mục trong chương trình nghị sự của cuộc họp đều đề cập đến một thách thức khác nhau mà các dịch vụ giao thông công cộng địa phương đang phải đối mặt.","audioKind":"ex2"}],"collocations":[{"en":"household item","vi":"đồ gia dụng"},{"en":"luxury item","vi":"hàng xa xỉ"},{"en":"agenda item","vi":"mục trong chương trình nghị sự"},{"en":"news item","vi":"mẩu tin tức"}],"wordFamily":["itemise (v.)","itemisation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"item là danh từ đếm được; một món trang phục có thể nói là an item of clothing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_replace', 'en-a2-32', 'replace', '/rɪˈpleɪs/', 'A2', 'thay thế; đổi mới; lắp lại; đặt lại chỗ cũ', 'v.', 'replacement (n.), replaceable (adj.), irreplaceable (adj.)', NULL, 'replace A with B dùng B để thay thế cho A, chú ý không nhầm lẫn hướng tác động.', 'We need to replace the broken kitchen chair.', NULL, 'Chúng ta cần thay thế chiếc ghế phòng bếp đã bị hỏng.', '{"wordId":"replace","ukIpa":"/rɪˈpleɪs/","usIpa":"/rɪˈpleɪs/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To take something''s place or put something else in its place.","vi":"thay thế; đổi mới; lắp lại"},{"pos":"v.","en":"To put something back where it was before.","vi":"đặt lại chỗ cũ"}],"examples":[{"en":"We need to replace the broken kitchen chair.","vi":"Chúng ta cần thay thế chiếc ghế phòng bếp đã bị hỏng.","audioKind":"ex"},{"en":"Renewable energy could gradually replace fossil fuels if governments invest sufficiently in infrastructure and storage technology.","vi":"Năng lượng tái tạo có thể dần thay thế nhiên liệu hóa thạch nếu các chính phủ đầu tư đầy đủ vào cơ sở hạ tầng và công nghệ lưu trữ.","audioKind":"ex2"}],"collocations":[{"en":"replace A with B","vi":"thay thế A bằng B"},{"en":"replace a battery","vi":"thay pin"},{"en":"be replaced by","vi":"bị thay thế bởi"}],"wordFamily":["replacement (n.)","replaceable (adj.)","irreplaceable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"replace A with B dùng B để thay thế cho A, chú ý không nhầm lẫn hướng tác động.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_yard', 'en-a2-32', 'yard', '/jɑːrd/', 'A2', 'sân; khu đất quanh nhà (thường có rào chắn); y-đao (đơn vị đo chiều dài bằng 3 feet hoặc 0,9144 mét)', 'n.', NULL, 'Đồng nghĩa: courtyard', 'Mỹ yard có thể chỉ bãi cỏ quanh nhà; Anh thường dùng garden.', 'Our dog chased a yellow ball across the yard.', NULL, 'Con chó của chúng tôi đuổi theo một quả bóng màu vàng chạy khắp sân.', '{"wordId":"yard","ukIpa":"/jɑːd/","usIpa":"/jɑːrd/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"An outdoor area beside a building, often enclosed.","vi":"sân; khu đất quanh nhà (thường có rào chắn)"},{"pos":"n.","en":"A unit of length equal to three feet or 0.9144 metres.","vi":"y-đao (đơn vị đo chiều dài bằng 3 feet hoặc 0,9144 mét)"}],"examples":[{"en":"Our dog chased a yellow ball across the yard.","vi":"Con chó của chúng tôi đuổi theo một quả bóng màu vàng chạy khắp sân.","audioKind":"ex"},{"en":"Converting an unused school yard into a garden can provide valuable outdoor learning opportunities for urban children.","vi":"Việc biến một sân trường không dùng đến thành khu vườn có thể mang lại cơ hội học tập ngoài trời quý giá cho trẻ em thành thị.","audioKind":"ex2"}],"collocations":[{"en":"back yard","vi":"sân sau"},{"en":"school yard","vi":"sân trường"},{"en":"a yard of fabric","vi":"một y-đao vải"}],"wordFamily":[],"synonyms":["courtyard"],"antonyms":[],"tipVi":"Mỹ yard có thể chỉ bãi cỏ quanh nhà; Anh thường dùng garden.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shine', 'en-a2-32', 'shine', '/ʃaɪn/', 'A2', 'chiếu sáng; tỏa sáng; phản chiếu ánh sáng; đánh bóng; làm cho sáng bóng; độ bóng; ánh sáng phản chiếu trên bề mặt nhẵn', 'v.', 'shiny (adj.)', NULL, 'Quá khứ của nghĩa phát sáng thường là shone; đánh bóng dùng shined.', 'The sun shone through my bedroom window this morning.', NULL, 'Ánh mặt trời chiếu xuyên qua cửa sổ phòng ngủ của tôi sáng nay.', '{"wordId":"shine","ukIpa":"/ʃaɪn/","usIpa":"/ʃaɪn/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To give out or reflect light.","vi":"chiếu sáng; tỏa sáng; phản chiếu ánh sáng"},{"pos":"v.","en":"To polish something until its surface becomes bright and smooth.","vi":"đánh bóng; làm cho sáng bóng"},{"pos":"n.","en":"Brightness on a smooth surface that reflects light.","vi":"độ bóng; ánh sáng phản chiếu trên bề mặt nhẵn"}],"examples":[{"en":"The sun shone through my bedroom window this morning.","vi":"Ánh mặt trời chiếu xuyên qua cửa sổ phòng ngủ của tôi sáng nay.","audioKind":"ex"},{"en":"Streetlights that shine directly into homes can disturb sleep and reduce residents'' quality of life.","vi":"Đèn đường chiếu thẳng vào nhà có thể làm phiền giấc ngủ và giảm chất lượng sống của người dân.","audioKind":"ex2"}],"collocations":[{"en":"shine brightly","vi":"chiếu sáng rực rỡ"},{"en":"shine a light on","vi":"chiếu đèn vào"},{"en":"shine your shoes","vi":"đánh giày cho bóng"},{"en":"a healthy shine","vi":"vẻ sáng bóng khỏe mạnh"}],"wordFamily":["shiny (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Quá khứ của nghĩa phát sáng thường là shone; đánh bóng dùng shined.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pear', 'en-a2-32', 'pear', '/per/', 'A2', 'quả lê', 'n.', 'pear-shaped (adj.)', NULL, 'pear phát âm giống pair; một quả lê dùng a pear.', 'She sliced a ripe pear into her breakfast bowl.', NULL, 'Cô ấy thái một quả lê chín vào bát ngũ cốc ăn sáng của mình.', '{"wordId":"pear","ukIpa":"/peə/","usIpa":"/per/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A sweet, juicy fruit, often narrower at the top","vi":"quả lê"}],"examples":[{"en":"She sliced a ripe pear into her breakfast bowl.","vi":"Cô ấy thái một quả lê chín vào bát ngũ cốc ăn sáng của mình.","audioKind":"ex"},{"en":"Buying locally grown pears during their natural season may reduce the need for long-distance food transport.","vi":"Mua những quả lê trồng tại địa phương trong mùa tự nhiên có thể giảm nhu cầu vận chuyển thực phẩm đường dài.","audioKind":"ex2"}],"collocations":[{"en":"a ripe pear","vi":"quả lê chín"},{"en":"a pear tree","vi":"cây lê"},{"en":"pear juice","vi":"nước ép lê"}],"wordFamily":["pear-shaped (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"pear phát âm giống pair; một quả lê dùng a pear.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_immediately', 'en-a2-32', 'immediately', '/ɪˈmiːdiətli/', 'A2', 'ngay lập tức; tức khắc; ngay trước, ngay sau hoặc ngay cạnh; ngay khi', 'adv.', 'immediate (adj.), immediacy (n.)', 'Đồng nghĩa: instantly, promptly', 'Dùng làm liên từ mang nghĩa "ngay khi" chủ yếu xuất hiện trong tiếng Anh - Anh.', 'When the doorbell rang, I immediately opened the door.', NULL, 'Khi chuông cửa reo, tôi lập tức ra mở cửa.', '{"wordId":"immediately","ukIpa":"/ɪˈmiːdiətli/","usIpa":"/ɪˈmiːdiətli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"without waiting or any delay","vi":"ngay lập tức; tức khắc"},{"pos":"adv.","en":"directly before, after, or next to something","vi":"ngay trước, ngay sau hoặc ngay cạnh"},{"pos":"conj.","en":"as soon as something happens","vi":"ngay khi"}],"examples":[{"en":"When the doorbell rang, I immediately opened the door.","vi":"Khi chuông cửa reo, tôi lập tức ra mở cửa.","audioKind":"ex"},{"en":"Schools should respond immediately to safety concerns rather than waiting for a serious incident to occur.","vi":"Các trường học nên phản hồi ngay lập tức đối với các mối lo ngại về an toàn thay vì chờ đợi một sự cố nghiêm trọng xảy ra.","audioKind":"ex2"}],"collocations":[{"en":"respond immediately","vi":"phản hồi ngay lập tức"},{"en":"immediately after","vi":"ngay sau..."},{"en":"immediately available","vi":"có sẵn ngay"}],"wordFamily":["immediate (adj.)","immediacy (n.)"],"synonyms":["instantly","promptly"],"antonyms":[],"tipVi":"Dùng làm liên từ mang nghĩa \"ngay khi\" chủ yếu xuất hiện trong tiếng Anh - Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_freezer', 'en-a2-32', 'freezer', '/ˈfriːzər/', 'A2', 'tủ đông; ngăn đá', 'n.', 'freeze (v.), frozen (adj.), freezing (adj.)', NULL, 'freezer dùng để đông lạnh; fridge chủ yếu dùng để làm mát.', 'Put the ice cream back in the freezer.', NULL, 'Hãy cất kem lại vào ngăn đá đi.', '{"wordId":"freezer","ukIpa":"/ˈfriːzə/","usIpa":"/ˈfriːzər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"an appliance or compartment that keeps food frozen","vi":"tủ đông; ngăn đá"}],"examples":[{"en":"Put the ice cream back in the freezer.","vi":"Hãy cất kem lại vào ngăn đá đi.","audioKind":"ex"},{"en":"Using a freezer allows households to store seasonal produce longer and reduce food waste.","vi":"Việc sử dụng tủ đông giúp các hộ gia đình lưu trữ nông sản theo mùa lâu hơn và giảm lãng phí thực phẩm.","audioKind":"ex2"}],"collocations":[{"en":"chest freezer","vi":"tủ đông dạng nằm"},{"en":"freezer compartment","vi":"ngăn đông tủ lạnh"},{"en":"defrost the freezer","vi":"xả tuyết tủ đông"}],"wordFamily":["freeze (v.)","frozen (adj.)","freezing (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"freezer dùng để đông lạnh; fridge chủ yếu dùng để làm mát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pub', 'en-a2-32', 'pub', '/pʌb/', 'A2', 'quán rượu; quán pub', 'n.', NULL, NULL, 'pub phổ biến trong bối cảnh Anh quốc, thường phục vụ cả bữa ăn, không phải là nhà trọ.', 'We had vegetable soup at the village pub.', NULL, 'Chúng tôi đã ăn súp rau ở quán rượu của làng.', '{"wordId":"pub","ukIpa":"/pʌb/","usIpa":"/pʌb/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A place serving alcoholic drinks and often meals, especially in Britain.","vi":"quán rượu; quán pub"}],"examples":[{"en":"We had vegetable soup at the village pub.","vi":"Chúng tôi đã ăn súp rau ở quán rượu của làng.","audioKind":"ex"},{"en":"In some rural communities, the local pub provides an important meeting place for residents.","vi":"Ở một số cộng đồng nông thôn, quán rượu địa phương là nơi tụ họp quan trọng của cư dân.","audioKind":"ex2"}],"collocations":[{"en":"a local pub","vi":"một quán rượu địa phương"},{"en":"a village pub","vi":"một quán rượu trong làng"},{"en":"pub food","vi":"đồ ăn quán rượu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"pub phổ biến trong bối cảnh Anh quốc, thường phục vụ cả bữa ăn, không phải là nhà trọ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kid', 'en-a2-32', 'kid', '/kɪd/', 'A2', 'đứa trẻ; trẻ con; nói đùa; trêu chọc; dê con', 'n.', 'kidding (n.)', 'Đồng nghĩa: child, youngster, joke', 'kid mang tính khẩu ngữ; trong văn viết trang trọng, từ "trẻ em" nên dùng child.', 'The kids built a tiny bridge across the stream.', NULL, 'Mấy đứa trẻ đã dựng một cây cầu nhỏ bắc qua dòng suối.', '{"wordId":"kid","ukIpa":"/kɪd/","usIpa":"/kɪd/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A child or young person, in informal language.","vi":"đứa trẻ; trẻ con"},{"pos":"v.","en":"Say something playfully that is not meant to be believed.","vi":"nói đùa; trêu chọc"},{"pos":"n.","en":"A young goat.","vi":"dê con"}],"examples":[{"en":"The kids built a tiny bridge across the stream.","vi":"Mấy đứa trẻ đã dựng một cây cầu nhỏ bắc qua dòng suối.","audioKind":"ex"},{"en":"Outdoor activities can help kids develop social skills while improving their physical health.","vi":"Các hoạt động ngoài trời có thể giúp trẻ em phát triển kỹ năng xã hội đồng thời nâng cao sức khỏe thể chất.","audioKind":"ex2"}],"collocations":[{"en":"young kids","vi":"trẻ nhỏ"},{"en":"just kidding","vi":"chỉ đùa thôi"},{"en":"kid around","vi":"đùa nghịch"}],"wordFamily":["kidding (n.)"],"synonyms":["child","youngster","joke"],"antonyms":[],"tipVi":"kid mang tính khẩu ngữ; trong văn viết trang trọng, từ \"trẻ em\" nên dùng child.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fork', 'en-a2-32', 'fork', '/fɔːrk/', 'A2', 'cái nĩa; chiếc dĩa ăn; ngã ba đường; chỗ phân nhánh; chia nhánh; rẽ nhánh', 'n.', NULL, NULL, 'Động từ forks có nghĩa là phân nhánh; a fork in the road chỉ ngã ba đường.', 'She picked up a carrot with her fork.', NULL, 'Cô ấy dùng nĩa để gắp một miếng cà rốt.', '{"wordId":"fork","ukIpa":"/fɔːk/","usIpa":"/fɔːrk/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A tool with pointed prongs for picking up food","vi":"cái nĩa; chiếc dĩa ăn"},{"pos":"n.","en":"A place where a road or path divides","vi":"ngã ba đường; chỗ phân nhánh"},{"pos":"v.","en":"Divide into separate branches or directions","vi":"chia nhánh; rẽ nhánh"}],"examples":[{"en":"She picked up a carrot with her fork.","vi":"Cô ấy dùng nĩa để gắp một miếng cà rốt.","audioKind":"ex"},{"en":"Where a rural path forks, clear directions can prevent visitors from entering environmentally sensitive areas.","vi":"Tại đoạn đường mòn ở vùng quê phân nhánh, các biển chỉ dẫn rõ ràng có thể ngăn du khách đi vào các khu vực nhạy cảm về sinh thái.","audioKind":"ex2"}],"collocations":[{"en":"a knife and fork","vi":"một bộ dao nĩa"},{"en":"a fork in the road","vi":"ngã ba đường"},{"en":"fork left","vi":"rẽ trái ở ngã ba"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ forks có nghĩa là phân nhánh; a fork in the road chỉ ngã ba đường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_prepare', 'en-a2-32', 'prepare', '/prɪˈper/', 'A2', 'chuẩn bị; làm cho ai hoặc cái gì sẵn sàng cho một hoạt động hoặc tình huống; soạn thảo; làm cho thức ăn, tài liệu hoặc kế hoạch sẵn sàng để sử dụng', 'v.', 'preparation (n.), prepared (adj.), preparatory (adj.)', 'Đồng nghĩa: get ready', 'prepare for đi với danh từ; prepare to đi với động từ nguyên thể.', 'I prepare my lunch before leaving home each morning.', NULL, 'Tôi chuẩn bị bữa trưa trước khi rời nhà vào mỗi buổi sáng.', '{"wordId":"prepare","ukIpa":"/prɪˈpeə/","usIpa":"/prɪˈper/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"Make someone or something ready for an activity or situation","vi":"chuẩn bị; làm cho ai hoặc cái gì sẵn sàng cho một hoạt động hoặc tình huống"},{"pos":"v.","en":"Make food, a document, or a plan ready for use","vi":"chuẩn bị; soạn thảo; làm cho thức ăn, tài liệu hoặc kế hoạch sẵn sàng để sử dụng"}],"examples":[{"en":"I prepare my lunch before leaving home each morning.","vi":"Tôi chuẩn bị bữa trưa trước khi rời nhà vào mỗi buổi sáng.","audioKind":"ex"},{"en":"Schools should prepare students for employment by developing practical skills alongside their academic knowledge.","vi":"Nhà trường nên trang bị cho học sinh năng lực làm việc bằng cách phát triển các kỹ năng thực tế song song với kiến thức học thuật.","audioKind":"ex2"}],"collocations":[{"en":"prepare for an exam","vi":"chuẩn bị cho kỳ thi"},{"en":"prepare a meal","vi":"chuẩn bị bữa ăn"},{"en":"prepare a report","vi":"soạn thảo báo cáo"},{"en":"prepare to leave","vi":"chuẩn bị rời đi"}],"wordFamily":["preparation (n.)","prepared (adj.)","preparatory (adj.)"],"synonyms":["get ready"],"antonyms":[],"tipVi":"prepare for đi với danh từ; prepare to đi với động từ nguyên thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mug', 'en-a2-32', 'mug', '/mʌɡ/', 'A2', 'cốc có quai lớn; trấn lột; cướp giật (ngoài đường)', 'n.', 'mugger (n.), mugging (n.)', NULL, 'mug thường có quai, kích thước lớn; khi dùng làm động từ có thể chỉ hành vi cướp bóc ngoài đường.', 'I warmed my hands around a mug of tea.', NULL, 'Tôi xuýt xoa làm ấm đôi tay quanh một cốc trà lớn.', '{"wordId":"mug","ukIpa":"/mʌɡ/","usIpa":"/mʌɡ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a large cup with a handle, usually for hot drinks","vi":"cốc có quai lớn"},{"pos":"v.","en":"to attack someone in public and steal from them","vi":"trấn lột; cướp giật (ngoài đường)"}],"examples":[{"en":"I warmed my hands around a mug of tea.","vi":"Tôi xuýt xoa làm ấm đôi tay quanh một cốc trà lớn.","audioKind":"ex"},{"en":"Providing reusable mugs in offices can reduce the waste generated by disposable cups each day.","vi":"Việc cung cấp những chiếc cốc dùng nhiều lần tại văn phòng có thể làm giảm lượng rác thải do cốc dùng một lần tạo ra mỗi ngày.","audioKind":"ex2"}],"collocations":[{"en":"a mug of coffee","vi":"một cốc cà phê lớn"},{"en":"ceramic mug","vi":"cốc sứ có quai"},{"en":"get mugged","vi":"bị cướp giật"}],"wordFamily":["mugger (n.)","mugging (n.)"],"synonyms":[],"antonyms":[],"tipVi":"mug thường có quai, kích thước lớn; khi dùng làm động từ có thể chỉ hành vi cướp bóc ngoài đường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_raincoat', 'en-a2-32', 'raincoat', '/ˈreɪnkoʊt/', 'A2', 'áo mưa', 'n.', NULL, NULL, 'Cả tiếng Anh Anh và Anh Mỹ đều sử dụng raincoat, không bị giới hạn riêng ở Mỹ.', 'I grabbed my raincoat before stepping into the rain.', NULL, 'Tôi vội cầm lấy áo mưa trước khi bước ra ngoài trời mưa.', '{"wordId":"raincoat","ukIpa":"/ˈreɪnkəʊt/","usIpa":"/ˈreɪnkoʊt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A coat that keeps your clothes dry in the rain.","vi":"áo mưa"}],"examples":[{"en":"I grabbed my raincoat before stepping into the rain.","vi":"Tôi vội cầm lấy áo mưa trước khi bước ra ngoài trời mưa.","audioKind":"ex"},{"en":"Travellers visiting regions with unpredictable weather should carry a lightweight raincoat to stay comfortable during outdoor activities.","vi":"Những du khách đến thăm các vùng có thời tiết thất thường nên mang theo một chiếc áo mưa mỏng nhẹ để luôn thoải mái trong các hoạt động ngoài trời.","audioKind":"ex2"}],"collocations":[{"en":"waterproof raincoat","vi":"áo mưa chống nước"},{"en":"lightweight raincoat","vi":"áo mưa mỏng nhẹ"},{"en":"put on a raincoat","vi":"mặc áo mưa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cả tiếng Anh Anh và Anh Mỹ đều sử dụng raincoat, không bị giới hạn riêng ở Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_diary', 'en-a2-32', 'diary', '/ˈdaɪəri/', 'A2', 'nhật ký; sổ nhật ký; sổ tay ghi lịch trình; sổ tay công tác', 'n.', NULL, 'Đồng nghĩa: journal', 'diary là nhật ký, còn dairy là sản phẩm sữa; cần chú ý trật tự các chữ cái để tránh nhầm lẫn.', 'I write in my diary before going to bed.', NULL, 'Tôi viết nhật ký trước khi đi ngủ.', '{"wordId":"diary","ukIpa":"/ˈdaɪəri/","usIpa":"/ˈdaɪəri/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A book containing personal accounts of daily events and feelings.","vi":"nhật ký; sổ nhật ký"},{"pos":"n.","en":"A book used to record appointments and future plans.","vi":"sổ tay ghi lịch trình; sổ tay công tác"}],"examples":[{"en":"I write in my diary before going to bed.","vi":"Tôi viết nhật ký trước khi đi ngủ.","audioKind":"ex"},{"en":"Keeping a learning diary encourages students to reflect on their progress and identify difficulties.","vi":"Việc giữ thói quen viết nhật ký học tập khuyến khích học sinh tự suy ngẫm về sự tiến bộ của bản thân và nhận diện những khó khăn.","audioKind":"ex2"}],"collocations":[{"en":"keep a diary","vi":"viết nhật ký"},{"en":"diary entry","vi":"một đoạn nhật ký"},{"en":"personal diary","vi":"nhật ký cá nhân"}],"wordFamily":[],"synonyms":["journal"],"antonyms":[],"tipVi":"diary là nhật ký, còn dairy là sản phẩm sữa; cần chú ý trật tự các chữ cái để tránh nhầm lẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hold', 'en-a2-32', 'hold', '/hoʊld/', 'A2', 'cầm; nắm; giữ; tổ chức (sự kiện, cuộc họp); chứa; dung nạp', 'v.', 'holder (n.), holding (n.)', NULL, 'Dạng quá khứ và phân từ hai của hold đều là held; tổ chức cuộc họp dùng động từ hold.', 'Could you hold my bag while I tie my shoes?', NULL, 'Bạn có thể giữ hộ tôi chiếc túi trong lúc tôi buộc giày không?', '{"wordId":"hold","ukIpa":"/həʊld/","usIpa":"/hoʊld/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to keep something in your hands or arms","vi":"cầm; nắm; giữ"},{"pos":"v.","en":"to organise an event or meeting","vi":"tổ chức (sự kiện, cuộc họp)"},{"pos":"v.","en":"to have enough space for something or someone","vi":"chứa; dung nạp"}],"examples":[{"en":"Could you hold my bag while I tie my shoes?","vi":"Bạn có thể giữ hộ tôi chiếc túi trong lúc tôi buộc giày không?","audioKind":"ex"},{"en":"Local councils should hold public meetings before making major changes to transport services.","vi":"Các hội đồng địa phương nên tổ chức các cuộc họp công khai trước khi thực hiện những thay đổi lớn đối với dịch vụ giao thông.","audioKind":"ex2"}],"collocations":[{"en":"hold hands","vi":"nắm tay nhau"},{"en":"hold a meeting","vi":"tổ chức một cuộc họp"},{"en":"hold your breath","vi":"nín thở"},{"en":"hold up to","vi":"chứa tối đa"}],"wordFamily":["holder (n.)","holding (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai của hold đều là held; tổ chức cuộc họp dùng động từ hold.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_packet', 'en-a2-32', 'packet', '/ˈpækɪt/', 'A2', 'gói; túi nhỏ; hộp nhỏ; gói dữ liệu', 'n.', 'pack (v.), packaging (n.)', 'Đồng nghĩa: pack', 'Tiếng Anh-Anh thường dùng a packet of; tiếng Anh-Mỹ thường dùng pack hoặc bag tùy theo vật dụng.', 'She opened a packet of biscuits for the journey.', NULL, 'Cô ấy mở một gói bánh quy cho chuyến đi.', '{"wordId":"packet","ukIpa":"/ˈpækɪt/","usIpa":"/ˈpækɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A small container or wrapped quantity of something.","vi":"gói; túi nhỏ; hộp nhỏ"},{"pos":"n.","en":"A small unit of data transmitted across a network.","vi":"gói dữ liệu"}],"examples":[{"en":"She opened a packet of biscuits for the journey.","vi":"Cô ấy mở một gói bánh quy cho chuyến đi.","audioKind":"ex"},{"en":"Charging customers for each packet of disposable utensils could encourage more sustainable habits in the food industry.","vi":"Việc tính phí khách hàng cho mỗi gói dụng cụ ăn uống dùng một lần có thể khuyến khích các thói quen bền vững hơn trong ngành công nghiệp thực phẩm.","audioKind":"ex2"}],"collocations":[{"en":"a packet of biscuits","vi":"một gói bánh quy"},{"en":"seed packet","vi":"túi hạt giống"},{"en":"data packet","vi":"gói dữ liệu"}],"wordFamily":["pack (v.)","packaging (n.)"],"synonyms":["pack"],"antonyms":[],"tipVi":"Tiếng Anh-Anh thường dùng a packet of; tiếng Anh-Mỹ thường dùng pack hoặc bag tùy theo vật dụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_somewhere', 'en-a2-32', 'somewhere', '/ˈsʌmwer/', 'A2', 'ở đâu đó; đến đâu đó; khoảng chừng', 'adv.', NULL, 'Trái nghĩa: nowhere', 'Tính từ đặt phía sau: somewhere quiet; phía trước thường không đi kèm giới từ to.', 'I left my keys somewhere near the sofa.', NULL, 'Tôi để quên chìa khóa ở đâu đó gần chiếc ghế sô-pha rồi.', '{"wordId":"somewhere","ukIpa":"/ˈsʌmweə/","usIpa":"/ˈsʌmwer/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"in or to a place that is not specified","vi":"ở đâu đó; đến đâu đó"},{"pos":"adv.","en":"approximately, when used before an amount or range","vi":"khoảng chừng"}],"examples":[{"en":"I left my keys somewhere near the sofa.","vi":"Tôi để quên chìa khóa ở đâu đó gần chiếc ghế sô-pha rồi.","audioKind":"ex"},{"en":"Young people need somewhere affordable to live before they can fully participate in the local economy.","vi":"Giới trẻ cần có một nơi ở vừa túi tiền trước khi họ có thể tham gia đầy đủ vào nền kinh tế địa phương.","audioKind":"ex2"}],"collocations":[{"en":"somewhere else","vi":"nơi nào khác"},{"en":"somewhere quiet","vi":"nơi nào đó yên tĩnh"},{"en":"somewhere around","vi":"khoảng chừng"}],"wordFamily":[],"synonyms":[],"antonyms":["nowhere"],"tipVi":"Tính từ đặt phía sau: somewhere quiet; phía trước thường không đi kèm giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_such', 'en-a2-32', 'such', '/sʌtʃ/', 'A2', 'như thế; loại này; như vậy; quá', 'det.', NULL, NULL, 'Trước danh từ đếm được số ít dùng such a/an; so đứng trực tiếp trước tính từ.', 'It was such a lovely day that we ate outside.', NULL, 'Hôm nay thời tiết đẹp quá nên chúng tôi ăn cơm ngoài trời.', '{"wordId":"such","ukIpa":"/sʌtʃ/","usIpa":"/sʌtʃ/","cefr":"A2","topic":"daily","senses":[{"pos":"det.","en":"of the kind already mentioned or being described","vi":"như thế; loại này"},{"pos":"det.","en":"used to emphasise a quality or degree before a noun","vi":"như vậy; quá"}],"examples":[{"en":"It was such a lovely day that we ate outside.","vi":"Hôm nay thời tiết đẹp quá nên chúng tôi ăn cơm ngoài trời.","audioKind":"ex"},{"en":"Many cities face severe traffic congestion, and such problems require coordinated investment in public transport.","vi":"Nhiều thành phố đối mặt với tình trạng tắc nghẽn giao thông nghiêm trọng, và những vấn đề như vậy đòi hỏi sự đầu tư đồng bộ vào giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"such as","vi":"như là"},{"en":"such a pity","vi":"thật là đáng tiếc"},{"en":"such problems","vi":"những vấn đề như vậy"},{"en":"such ... that ...","vi":"đến mức mà..."}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trước danh từ đếm được số ít dùng such a/an; so đứng trực tiếp trước tính từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bowl', 'en-a2-32', 'bowl', '/boʊl/', 'A2', 'cái bát; cái tô; cái chén; ném bóng (trong môn cricket); lăn bóng (trong môn bowling)', 'n.', 'bowler (n.), bowling (n.)', NULL, 'Cụm "a bowl of" dùng để chỉ "một bát"; "bowling" chỉ môn thể thao chơi bóng gỗ.', 'She warmed her hands around a bowl of soup.', NULL, 'Cô ấy áp hai tay vào một bát súp ấm để sưởi ấm.', '{"wordId":"bowl","ukIpa":"/bəʊl/","usIpa":"/boʊl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a round, deep container used for food or liquids","vi":"cái bát; cái tô; cái chén"},{"pos":"v.","en":"to roll a bowling ball or deliver a cricket ball","vi":"ném bóng (trong môn cricket); lăn bóng (trong môn bowling)"}],"examples":[{"en":"She warmed her hands around a bowl of soup.","vi":"Cô ấy áp hai tay vào một bát súp ấm để sưởi ấm.","audioKind":"ex"},{"en":"Serving meals in smaller bowls may help people control portions and reduce unnecessary food waste.","vi":"Ăn bằng những chiếc bát nhỏ hơn có thể giúp mọi người kiểm soát khẩu phần ăn và giảm thiểu lãng phí thực phẩm không cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"a bowl of soup","vi":"một bát súp"},{"en":"mixing bowl","vi":"bát trộn"},{"en":"salad bowl","vi":"bát đựng salad"},{"en":"bowl a ball","vi":"ném một quả bóng"}],"wordFamily":["bowler (n.)","bowling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cụm \"a bowl of\" dùng để chỉ \"một bát\"; \"bowling\" chỉ môn thể thao chơi bóng gỗ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_weekday', 'en-a2-32', 'weekday', '/ˈwiːkdeɪ/', 'A2', 'ngày làm việc trong tuần; từ thứ Hai đến thứ Sáu', 'n.', NULL, 'Trái nghĩa: weekend', 'Chỉ từ thứ Hai đến thứ Sáu, không nhất thiết ngày hôm đó thực sự phải đi làm.', 'The swimming pool is quieter on weekday mornings.', NULL, 'Hồ bơi vắng vẻ hơn vào những buổi sáng ngày trong tuần.', '{"wordId":"weekday","ukIpa":"/ˈwiːkdeɪ/","usIpa":"/ˈwiːkdeɪ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"any day from Monday to Friday","vi":"ngày làm việc trong tuần; từ thứ Hai đến thứ Sáu"}],"examples":[{"en":"The swimming pool is quieter on weekday mornings.","vi":"Hồ bơi vắng vẻ hơn vào những buổi sáng ngày trong tuần.","audioKind":"ex"},{"en":"Extending library opening hours on weekdays would benefit students who work during the day.","vi":"Việc kéo dài giờ mở cửa thư viện vào các ngày trong tuần sẽ mang lại lợi ích cho những học sinh ban ngày phải đi làm.","audioKind":"ex2"}],"collocations":[{"en":"on weekdays","vi":"vào các ngày trong tuần"},{"en":"weekday mornings","vi":"buổi sáng ngày trong tuần"},{"en":"a weekday service","vi":"dịch vụ ngày trong tuần"}],"wordFamily":[],"synonyms":[],"antonyms":["weekend"],"tipVi":"Chỉ từ thứ Hai đến thứ Sáu, không nhất thiết ngày hôm đó thực sự phải đi làm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_32_1', 'en-a2-32', 'Cách dùng “mug” (n.) — cốc có quai lớn', 'a mug of coffee  ·  ceramic mug  ·  get mugged', 'mug thường có quai, kích thước lớn; khi dùng làm động từ có thể chỉ hành vi cướp bóc ngoài đường.', 'Họ từ (Word Family): mugger (n.), mugging (n.)', '[{"hanzi":"I warmed my hands around a mug of tea.","pinyin":"","meaning":"Tôi xuýt xoa làm ấm đôi tay quanh một cốc trà lớn."},{"hanzi":"Providing reusable mugs in offices can reduce the waste generated by disposable cups each day.","pinyin":"","meaning":"Việc cung cấp những chiếc cốc dùng nhiều lần tại văn phòng có thể làm giảm lượng rác thải do cốc dùng một lần tạo ra mỗi ngày."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_32_2', 'en-a2-32', 'Cách dùng “packet” (n.) — gói; túi nhỏ; hộp nhỏ', 'a packet of biscuits  ·  seed packet  ·  data packet', 'Tiếng Anh-Anh thường dùng a packet of; tiếng Anh-Mỹ thường dùng pack hoặc bag tùy theo vật dụng.', 'Họ từ (Word Family): pack (v.), packaging (n.) | Đồng nghĩa: pack', '[{"hanzi":"She opened a packet of biscuits for the journey.","pinyin":"","meaning":"Cô ấy mở một gói bánh quy cho chuyến đi."},{"hanzi":"Charging customers for each packet of disposable utensils could encourage more sustainable habits in the food industry.","pinyin":"","meaning":"Việc tính phí khách hàng cho mỗi gói dụng cụ ăn uống dùng một lần có thể khuyến khích các thói quen bền vững hơn trong ngành công nghiệp thực phẩm."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_32_3', 'en-a2-32', 'Cách dùng “store” (n.) — cửa hàng; tiệm', 'department store  ·  store data  ·  store food', 'Trong tiếng Anh-Mỹ thường dùng store, trong khi tiếng Anh-Anh hàng ngày chuộng dùng shop hơn.', 'Họ từ (Word Family): storage (n.), storekeeper (n.) | Đồng nghĩa: shop, keep', '[{"hanzi":"The store near our house sells fresh bread.","pinyin":"","meaning":"Cửa hàng gần nhà chúng tôi bán bánh mì tươi."},{"hanzi":"Modern batteries can store energy from solar panels for use when sunlight is no longer available.","pinyin":"","meaning":"Pin hiện đại có thể lưu trữ năng lượng từ các tấm pin mặt trời để sử dụng khi không có ánh nắng mặt trời."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_32_4', 'en-a2-32', 'Cách dùng “diary” (n.) — nhật ký; sổ nhật ký', 'keep a diary  ·  diary entry  ·  personal diary', 'diary là nhật ký, còn dairy là sản phẩm sữa; cần chú ý trật tự các chữ cái để tránh nhầm lẫn.', 'Đồng nghĩa: journal', '[{"hanzi":"I write in my diary before going to bed.","pinyin":"","meaning":"Tôi viết nhật ký trước khi đi ngủ."},{"hanzi":"Keeping a learning diary encourages students to reflect on their progress and identify difficulties.","pinyin":"","meaning":"Việc giữ thói quen viết nhật ký học tập khuyến khích học sinh tự suy ngẫm về sự tiến bộ của bản thân và nhận diện những khó khăn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_32_1', 'en-a2-32', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_32_1_1', 'ten_a2_32_1', 'habit', 'Checking my phone before breakfast has become a habit.', 'Checking my phone before breakfast has become a habit.', '/ˈhæbɪt/', 'Thói quen kiểm tra điện thoại trước bữa sáng đã trở thành một phần trong sinh hoạt của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_32_1_2', 'ten_a2_32_1', 'drawer', 'I keep spare keys in the top kitchen drawer.', 'I keep spare keys in the top kitchen drawer.', '/drɔːr/', 'Tôi cất chìa khóa dự phòng trong ngăn kéo tủ bếp trên cùng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_32_1_3', 'ten_a2_32_1', 'rubber', 'These rubber boots keep my feet dry in puddles.', 'These rubber boots keep my feet dry in puddles.', '/ˈrʌbər/', 'Đôi bốt cao su này giúp chân tôi không bị ướt khi đi vào vũng nước.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_32_1_4', 'ten_a2_32_1', 'mix', 'Mix the flour and eggs in a large bowl.', 'Mix the flour and eggs in a large bowl.', '/mɪks/', 'Trộn đều bột mì và trứng trong một cái tô lớn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_32_1_5', 'ten_a2_32_1', 'shampoo', 'I packed a small bottle of shampoo for our trip.', 'I packed a small bottle of shampoo for our trip.', '/ʃæmˈpuː/', 'Tôi đã mang theo một chai dầu gội nhỏ cho chuyến đi chơi của chúng tôi.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_32_1_6', 'ten_a2_32_1', 'heater', 'We switched on the heater before the guests arrived.', 'We switched on the heater before the guests arrived.', '/ˈhiːtər/', 'Chúng tôi đã bật máy sưởi trước khi khách đến.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_32_1_7', 'ten_a2_32_1', 'store', 'The store near our house sells fresh bread.', 'The store near our house sells fresh bread.', '/stɔːr/', 'Cửa hàng gần nhà chúng tôi bán bánh mì tươi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_32_1_8', 'ten_a2_32_1', 'item', 'Please place each item carefully in the shopping bag.', 'Please place each item carefully in the shopping bag.', '/ˈaɪtəm/', 'Xin vui lòng đặt cẩn thận từng món đồ vào trong túi mua sắm.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_32_1_1', 'en-a2-32', 'ten_a2_32_1', 'listening', 'listening', 'Checking my phone before breakfast has become a habit.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Ánh mặt trời chiếu xuyên qua cửa sổ phòng ngủ của tôi sáng nay.","Thói quen kiểm tra điện thoại trước bữa sáng đã trở thành một phần trong sinh hoạt của tôi.","Cô ấy mở một gói bánh quy cho chuyến đi.","Cô ấy dùng nĩa để gắp một miếng cà rốt."]'::jsonb, 1, 'Checking my phone before breakfast has become a habit. → Thói quen kiểm tra điện thoại trước bữa sáng đã trở thành một phần trong sinh hoạt của tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_32_1_2', 'en-a2-32', 'ten_a2_32_1', 'listening', 'listening', 'I keep spare keys in the top kitchen drawer.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi cất chìa khóa dự phòng trong ngăn kéo tủ bếp trên cùng.","Tôi chuẩn bị bữa trưa trước khi rời nhà vào mỗi buổi sáng.","Cô ấy áp hai tay vào một bát súp ấm để sưởi ấm.","Cửa hàng gần nhà chúng tôi bán bánh mì tươi."]'::jsonb, 0, 'I keep spare keys in the top kitchen drawer. → Tôi cất chìa khóa dự phòng trong ngăn kéo tủ bếp trên cùng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_32_1_3', 'en-a2-32', 'ten_a2_32_1', 'listening', 'listening', 'These rubber boots keep my feet dry in puddles.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi để quên chìa khóa ở đâu đó gần chiếc ghế sô-pha rồi.","Tôi xuýt xoa làm ấm đôi tay quanh một cốc trà lớn.","Đôi bốt cao su này giúp chân tôi không bị ướt khi đi vào vũng nước.","Con chó của chúng tôi đuổi theo một quả bóng màu vàng chạy khắp sân."]'::jsonb, 2, 'These rubber boots keep my feet dry in puddles. → Đôi bốt cao su này giúp chân tôi không bị ướt khi đi vào vũng nước.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_32_2', 'en-a2-32', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_32_2_1', 'ten_a2_32_2', 'habit', 'Developing the habit of regular exercise during childhood can improve health throughout adult life.', 'Developing the habit of regular exercise during childhood can improve health throughout adult life.', '/ˈhæbɪt/', 'Việc hình thành thói quen tập thể dục đều đặn từ thời thơ ấu có thể cải thiện tình trạng sức khỏe trong suốt quãng đời trưởng thành.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_32_2_2', 'ten_a2_32_2', 'drawer', 'Office desks with lockable drawers help employees store personal belongings securely in shared working environments.', 'Office desks with lockable drawers help employees store personal belongings securely in shared working environments.', '/drɔːr/', 'Bàn làm việc có ngăn kéo khóa được giúp nhân viên cất giữ đồ đạc cá nhân an toàn trong môi trường làm việc chung.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_32_2_3', 'ten_a2_32_2', 'rubber', 'Recycling rubber from used tyres can reduce waste and provide material for safer playground surfaces.', 'Recycling rubber from used tyres can reduce waste and provide material for safer playground surfaces.', '/ˈrʌbər/', 'Tái chế cao su từ lốp xe cũ có thể giảm rác thải và cung cấp vật liệu cho bề mặt sân chơi an toàn hơn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_32_2_4', 'ten_a2_32_2', 'mix', 'Successful neighbourhoods often contain a mix of housing types that serve people with different incomes.', 'Successful neighbourhoods often contain a mix of housing types that serve people with different incomes.', '/mɪks/', 'Các khu dân cư thành công thường bao gồm sự kết hợp của nhiều loại nhà ở phục vụ cho người có mức thu nhập khác nhau.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_32_2_5', 'ten_a2_32_2', 'shampoo', 'Using refillable shampoo containers can reduce plastic waste generated by households and the tourism industry.', 'Using refillable shampoo containers can reduce plastic waste generated by households and the tourism industry.', '/ʃæmˈpuː/', 'Sử dụng chai dầu gội có thể đổ đầy lại giúp giảm thiểu rác thải nhựa do các hộ gia đình và ngành du lịch tạo ra.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_32_2_6', 'ten_a2_32_2', 'heater', 'Replacing an inefficient water heater can lower household energy bills and reduce overall electricity consumption.', 'Replacing an inefficient water heater can lower household energy bills and reduce overall electricity consumption.', '/ˈhiːtər/', 'Việc thay thế một bình đun nước nóng kém hiệu quả có thể làm giảm hóa đơn năng lượng của gia đình và cắt giảm tổng lượng điện tiêu thụ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_32_2_1', 'en-a2-32', 'ten_a2_32_2', 'listening', 'listening', 'Developing the habit of regular exercise during childhood can improve health throughout adult life.', NULL, 'Trong câu vừa nghe, từ “habit” mang nghĩa nào sau đây?', '["thói quen; tập quán","người đọc (đặc biệt là sách, báo hoặc tạp chí)","rau xà lách; rau diếp","buồn ngủ; mệt mỏi"]'::jsonb, 0, '“habit” (/ˈhæbɪt/): thói quen; tập quán. Câu đầy đủ: Developing the habit of regular exercise during childhood can improve health throughout adult life.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_32_2_2', 'en-a2-32', 'ten_a2_32_2', 'listening', 'listening', 'Office desks with lockable drawers help employees store personal belongings securely in shared working environments.', NULL, 'Trong câu vừa nghe, từ “drawer” mang nghĩa nào sau đây?', '["một phần tư (một trong bốn phần bằng nhau)","bán thời gian; làm thêm","ngăn kéo; hộc tủ","cái bát; cái tô; cái chén"]'::jsonb, 2, '“drawer” (/drɔːr/): ngăn kéo; hộc tủ. Câu đầy đủ: Office desks with lockable drawers help employees store personal belongings securely in shared working environments.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
