INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_32_2', 'en-a2-32', NULL, 'comprehensive_test', 'listening', 'I keep spare keys in the top kitchen drawer.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi cất chìa khóa dự phòng trong ngăn kéo tủ bếp trên cùng.","Cô ấy áp hai tay vào một bát súp ấm để sưởi ấm.","Bạn có thể giữ hộ tôi chiếc túi trong lúc tôi buộc giày không?","Xin vui lòng đặt cẩn thận từng món đồ vào trong túi mua sắm."]'::jsonb, 0, 'I keep spare keys in the top kitchen drawer. → Tôi cất chìa khóa dự phòng trong ngăn kéo tủ bếp trên cùng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
