INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_32_4', 'en-a2-32', NULL, 'comprehensive_test', 'listening', 'Mix the flour and eggs in a large bowl.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng ta cần thay thế chiếc ghế phòng bếp đã bị hỏng.","Tôi để quên chìa khóa ở đâu đó gần chiếc ghế sô-pha rồi.","Trộn đều bột mì và trứng trong một cái tô lớn.","Mấy đứa trẻ đã dựng một cây cầu nhỏ bắc qua dòng suối."]'::jsonb, 2, 'Mix the flour and eggs in a large bowl. → Trộn đều bột mì và trứng trong một cái tô lớn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
