INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_32_18', 'en-a2-32', NULL, 'comprehensive_test', 'reading', NULL, 'Developing the habit of regular exercise during childhood can improve health throughout adult life.', 'Dựa vào câu trên, từ “habit” có nghĩa phù hợp nhất là gì?', '["vấn đề; việc","sự luyện tập; sự rèn luyện","thói quen; tập quán","gói; túi nhỏ; hộp nhỏ"]'::jsonb, 2, 'habit: thói quen; tập quán. Dịch cả câu: Việc hình thành thói quen tập thể dục đều đặn từ thời thơ ấu có thể cải thiện tình trạng sức khỏe trong suốt quãng đời trưởng thành.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_32_19', 'en-a2-32', NULL, 'comprehensive_test', 'reading', NULL, 'Office desks with lockable drawers help employees store personal belongings securely in shared working environments.', 'Dựa vào câu trên, từ “drawer” có nghĩa phù hợp nhất là gì?', '["sữa chua","ở phía trước; tiến về phía trước","ngăn kéo; hộc tủ","lắc; rung; run rẩy"]'::jsonb, 2, 'drawer: ngăn kéo; hộc tủ. Dịch cả câu: Bàn làm việc có ngăn kéo khóa được giúp nhân viên cất giữ đồ đạc cá nhân an toàn trong môi trường làm việc chung.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_32_20', 'en-a2-32', NULL, 'comprehensive_test', 'reading', NULL, 'Recycling rubber from used tyres can reduce waste and provide material for safer playground surfaces.', 'Dựa vào câu trên, từ “rubber” có nghĩa phù hợp nhất là gì?', '["cao su","cờ vua; môn cờ vua","biến mất; khuất tầm mắt","vàng; kim loại vàng"]'::jsonb, 0, 'rubber: cao su; cục tẩy; gôm. Dịch cả câu: Tái chế cao su từ lốp xe cũ có thể giảm rác thải và cung cấp vật liệu cho bề mặt sân chơi an toàn hơn.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_32_21', 'en-a2-32', NULL, 'comprehensive_test', 'reading', NULL, 'Successful neighbourhoods often contain a mix of housing types that serve people with different incomes.', 'Dựa vào câu trên, từ “mix” có nghĩa phù hợp nhất là gì?', '["tiền mặt","chia sẻ; dùng chung; gánh vác","trộn; pha trộn; hòa trộn","trò chơi trượt ván; bộ môn trượt ván"]'::jsonb, 2, 'mix: trộn; pha trộn; hòa trộn; hỗn hợp; sự kết hợp; giao du; hòa nhập; kết bạn. Dịch cả câu: Các khu dân cư thành công thường bao gồm sự kết hợp của nhiều loại nhà ở phục vụ cho người có mức thu nhập khác nhau.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_32_22', 'en-a2-32', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “như thế; loại này”', '["such","ship","shorts","learning"]'::jsonb, 0, 'như thế; loại này → such (/sʌtʃ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_32_23', 'en-a2-32', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cái bát; cái tô; cái chén”', '["bowl","wheel","nobody","perfect"]'::jsonb, 0, 'cái bát; cái tô; cái chén → bowl (/boʊl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_32_24', 'en-a2-32', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “ngày làm việc trong tuần; từ thứ Hai đến thứ Sáu”', '["weekday","sign","ant","ending"]'::jsonb, 0, 'ngày làm việc trong tuần; từ thứ Hai đến thứ Sáu → weekday (/ˈwiːkdeɪ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-33', 'en', 'Bài 33: Đời sống hằng ngày (5) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '27 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2033, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_helpful', 'en-a2-33', 'helpful', '/ˈhelpfəl/', 'A2', 'hữu ích; giúp ích; hay giúp đỡ; nhiệt tình', 'adj.', 'help (v.), helper (n.), helpfully (adv.), helpfulness (n.)', 'Đồng nghĩa: useful, supportive · Trái nghĩa: unhelpful', 'helpful có thể dùng để chỉ sự việc hữu ích, hoặc chỉ người hay giúp đỡ.', 'Your map was helpful when we explored the village.', NULL, 'Tấm bản đồ của bạn rất hữu ích khi chúng tôi khám phá ngôi làng.', '{"wordId":"helpful","ukIpa":"/ˈhelpfəl/","usIpa":"/ˈhelpfəl/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Making something easier to do or understand.","vi":"hữu ích; giúp ích"},{"pos":"adj.","en":"Willing to help other people.","vi":"hay giúp đỡ; nhiệt tình"}],"examples":[{"en":"Your map was helpful when we explored the village.","vi":"Tấm bản đồ của bạn rất hữu ích khi chúng tôi khám phá ngôi làng.","audioKind":"ex"},{"en":"Clear feedback is particularly helpful for students who are learning to organise their ideas in academic essays.","vi":"Phản hồi rõ ràng đặc biệt hữu ích cho học sinh đang học cách tổ chức ý tưởng trong các bài luận học thuật.","audioKind":"ex2"}],"collocations":[{"en":"helpful advice","vi":"lời khuyên hữu ích"},{"en":"helpful information","vi":"thông tin hữu ích"},{"en":"helpful staff","vi":"nhân viên nhiệt tình"},{"en":"find something helpful","vi":"thấy điều gì đó hữu ích"}],"wordFamily":["help (v.)","helper (n.)","helpfully (adv.)","helpfulness (n.)"],"synonyms":["useful","supportive"],"antonyms":["unhelpful"],"tipVi":"helpful có thể dùng để chỉ sự việc hữu ích, hoặc chỉ người hay giúp đỡ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_noticeboard', 'en-a2-33', 'noticeboard', '/ˈnoʊtɪsbɔːrd/', 'A2', 'bảng thông báo; bảng tin', 'n.', NULL, 'Đồng nghĩa: bulletin board', 'Tiếng Anh-Anh dùng noticeboard, tiếng Anh-Mỹ dùng bulletin board.', 'Someone pinned a lost cat poster to the noticeboard.', NULL, 'Ai đó đã ghim tờ rơi tìm mèo lạc lên bảng thông báo.', '{"wordId":"noticeboard","ukIpa":"/ˈnəʊtɪsbɔːd/","usIpa":"/ˈnoʊtɪsbɔːrd/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A board displaying announcements for people to read.","vi":"bảng thông báo; bảng tin"}],"examples":[{"en":"Someone pinned a lost cat poster to the noticeboard.","vi":"Ai đó đã ghim tờ rơi tìm mèo lạc lên bảng thông báo.","audioKind":"ex"},{"en":"A shared noticeboard can help residents discover local events and participate more actively in community life.","vi":"Bảng thông báo chung có thể giúp cư dân nắm bắt các sự kiện địa phương và tham gia tích cực hơn vào đời sống cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"community noticeboard","vi":"bảng thông báo cộng đồng"},{"en":"on the noticeboard","vi":"trên bảng thông báo"},{"en":"put up a noticeboard","vi":"lắp đặt bảng thông báo"}],"wordFamily":[],"synonyms":["bulletin board"],"antonyms":[],"tipVi":"Tiếng Anh-Anh dùng noticeboard, tiếng Anh-Mỹ dùng bulletin board.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pick', 'en-a2-33', 'pick', '/pɪk/', 'A2', 'chọn; lựa chọn; hái (quả, hoa); cái cuốc', 'v.', 'picker (n.), picky (adj.)', 'Đồng nghĩa: choose, select', 'pick có thể mang nghĩa là chọn hoặc hái; hành động nhặt lên thường dùng pick up.', 'You can pick any colour for your new curtains.', NULL, 'Bạn có thể chọn bất kỳ màu nào cho bộ rèm cửa mới của mình.', '{"wordId":"pick","ukIpa":"/pɪk/","usIpa":"/pɪk/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to choose someone or something from available options","vi":"chọn; lựa chọn"},{"pos":"v.","en":"to remove fruit or flowers from a plant","vi":"hái (quả, hoa)"},{"pos":"n.","en":"a tool with a pointed metal head for breaking hard ground","vi":"cái cuốc"}],"examples":[{"en":"You can pick any colour for your new curtains.","vi":"Bạn có thể chọn bất kỳ màu nào cho bộ rèm cửa mới của mình.","audioKind":"ex"},{"en":"Schools should help students pick courses that match their interests rather than focus only on future earnings.","vi":"Nhà trường nên giúp học sinh chọn các môn học phù hợp với sở thích thay vì chỉ tập trung vào thu nhập trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"pick a winner","vi":"chọn ra người chiến thắng"},{"en":"pick fruit","vi":"hái quả"},{"en":"pick carefully","vi":"lựa chọn kỹ càng"},{"en":"take your pick","vi":"tự do lựa chọn"}],"wordFamily":["picker (n.)","picky (adj.)"],"synonyms":["choose","select"],"antonyms":[],"tipVi":"pick có thể mang nghĩa là chọn hoặc hái; hành động nhặt lên thường dùng pick up.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_garage', 'en-a2-33', 'garage', '/ɡəˈrɑːʒ/', 'A2', 'thư viện; phòng đọc; tiệm sửa xe; xưởng bảo dưỡng ô tô', 'n.', NULL, NULL, 'British English cũng thường dùng garage để chỉ tiệm sửa xe.', 'We keep our car and bicycles in the garage.', NULL, 'Chúng tôi để ô tô và xe đạp trong nhà để xe.', '{"wordId":"garage","ukIpa":"/ˈɡærɑːʒ/","usIpa":"/ɡəˈrɑːʒ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A building or part of a building for keeping vehicles.","vi":"thư viện; phòng đọc"},{"pos":"n.","en":"A business where vehicles are repaired and serviced.","vi":"tiệm sửa xe; xưởng bảo dưỡng ô tô"}],"examples":[{"en":"We keep our car and bicycles in the garage.","vi":"Chúng tôi để ô tô và xe đạp trong nhà để xe.","audioKind":"ex"},{"en":"Converting an unused garage into living space can provide additional accommodation without requiring new land.","vi":"Việc chuyển đổi một nhà để xe không dùng đến thành không gian sinh hoạt có thể cung cấp thêm chỗ ở mà không cần tốn đất mới.","audioKind":"ex2"}],"collocations":[{"en":"double garage","vi":"nhà để xe hai chỗ"},{"en":"garage door","vi":"cửa nhà để xe"},{"en":"local garage","vi":"tiệm sửa xe địa phương"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"British English cũng thường dùng garage để chỉ tiệm sửa xe.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_service', 'en-a2-33', 'service', '/ˈsɝːvɪs/', 'A2', 'dịch vụ; sự phục vụ; bảo dưỡng; đại tu; lễ (tôn giáo)', 'n.', 'serve (v.), server (n.)', NULL, 'Chỉ dịch vụ nói chung thường không đếm được; các dịch vụ cụ thể dùng dạng số nhiều.', 'The friendly service made us feel welcome at the café.', NULL, 'Dịch vụ thân thiện khiến chúng tôi cảm thấy được chào đón tại quán cà phê.', '{"wordId":"service","ukIpa":"/ˈsɜːvɪs/","usIpa":"/ˈsɝːvɪs/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Help or useful work provided for people or customers.","vi":"dịch vụ; sự phục vụ"},{"pos":"v.","en":"Check and repair a vehicle or machine to keep it working.","vi":"bảo dưỡng; đại tu"},{"pos":"n.","en":"A formal religious ceremony.","vi":"lễ (tôn giáo)"}],"examples":[{"en":"The friendly service made us feel welcome at the café.","vi":"Dịch vụ thân thiện khiến chúng tôi cảm thấy được chào đón tại quán cà phê.","audioKind":"ex"},{"en":"Reliable bus services allow residents without cars to reach hospitals, schools and workplaces.","vi":"Dịch vụ xe buýt đáng tin cậy giúp những cư dân không có ô tô có thể đến bệnh viện, trường học và nơi làm việc.","audioKind":"ex2"}],"collocations":[{"en":"customer service","vi":"dịch vụ khách hàng"},{"en":"public services","vi":"dịch vụ công"},{"en":"service a car","vi":"bảo dưỡng xe ô tô"},{"en":"religious service","vi":"lễ nghi tôn giáo"}],"wordFamily":["serve (v.)","server (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ dịch vụ nói chung thường không đếm được; các dịch vụ cụ thể dùng dạng số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cupboard', 'en-a2-33', 'cupboard', '/ˈkʌbɚd/', 'A2', 'tủ chén; tủ đựng đồ; tủ bếp', 'n.', NULL, 'Đồng nghĩa: cabinet', 'Âm p trong cupboard không được phát âm; từ này thường chỉ tủ có cửa để đựng đồ.', 'The clean bowls are in the cupboard above the sink.', NULL, 'Những chiếc bát sạch nằm trong tủ chén phía trên bồn rửa.', '{"wordId":"cupboard","ukIpa":"/ˈkʌbəd/","usIpa":"/ˈkʌbɚd/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A cabinet with doors and shelves for storing things","vi":"tủ chén; tủ đựng đồ; tủ bếp"}],"examples":[{"en":"The clean bowls are in the cupboard above the sink.","vi":"Những chiếc bát sạch nằm trong tủ chén phía trên bồn rửa.","audioKind":"ex"},{"en":"Well-designed cupboards can maximise storage space in small apartments without making living areas feel crowded.","vi":"Những chiếc tủ được thiết kế tốt có thể tối đa hóa không gian lưu trữ trong các căn hộ nhỏ mà không làm cho khu vực sinh hoạt có cảm giác chật chội.","audioKind":"ex2"}],"collocations":[{"en":"kitchen cupboard","vi":"tủ bếp"},{"en":"built-in cupboard","vi":"tủ âm tường"},{"en":"cupboard door","vi":"cánh tủ chén"}],"wordFamily":[],"synonyms":["cabinet"],"antonyms":[],"tipVi":"Âm p trong cupboard không được phát âm; từ này thường chỉ tủ có cửa để đựng đồ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_worse', 'en-a2-33', 'worse', '/wɝːs/', 'A2', 'tệ hơn; tồi tệ hơn; nghiêm trọng hơn; kém hơn', 'adj.', 'bad (adj.), badly (adv.), worst (adj.), worsen (v.)', 'Trái nghĩa: better', 'bad và badly có dạng so sánh hơn là worse; dạng so sánh nhất là worst.', 'The weather grew worse as we climbed the hill.', NULL, 'Thời tiết càng trở nên tồi tệ hơn khi chúng tôi leo lên đồi.', '{"wordId":"worse","ukIpa":"/wɜːs/","usIpa":"/wɝːs/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Less good or more unpleasant, harmful, or serious.","vi":"tệ hơn; tồi tệ hơn; nghiêm trọng hơn"},{"pos":"adv.","en":"Less well or more badly.","vi":"tệ hơn; kém hơn"}],"examples":[{"en":"The weather grew worse as we climbed the hill.","vi":"Thời tiết càng trở nên tồi tệ hơn khi chúng tôi leo lên đồi.","audioKind":"ex"},{"en":"Traffic congestion may become worse unless cities invest in reliable and affordable public transport.","vi":"Tình trạng tắc nghẽn giao thông có thể trở nên tồi tệ hơn trừ khi các thành phố đầu tư vào hệ thống giao thông công cộng đáng tin cậy và có giá cả phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"get worse","vi":"trở nên tồi tệ hơn"},{"en":"even worse","vi":"tệ hơn nữa"},{"en":"make matters worse","vi":"làm cho tình hình tồi tệ hơn"}],"wordFamily":["bad (adj.)","badly (adv.)","worst (adj.)","worsen (v.)"],"synonyms":[],"antonyms":["better"],"tipVi":"bad và badly có dạng so sánh hơn là worse; dạng so sánh nhất là worst.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cancel', 'en-a2-33', 'cancel', '/ˈkænsəl/', 'A2', 'hủy bỏ; bãi bỏ; hoãn; triệt tiêu; làm mất tác dụng', 'v.', 'cancellation (n.)', NULL, 'Trong tiếng Anh-Anh, dạng quá khứ là cancelled, còn tiếng Anh-Mỹ thường dùng canceled; dùng kèm với out khi mang nghĩa triệt tiêu.', 'We had to cancel our picnic because of heavy rain.', NULL, 'Chúng tôi buộc phải hủy chuyến dã ngoại vì trời mưa to.', '{"wordId":"cancel","ukIpa":"/ˈkænsəl/","usIpa":"/ˈkænsəl/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To decide that something planned will not happen.","vi":"hủy bỏ; bãi bỏ; hoãn"},{"pos":"v.","en":"To balance an opposing effect so neither changes the result.","vi":"triệt tiêu; làm mất tác dụng"}],"examples":[{"en":"We had to cancel our picnic because of heavy rain.","vi":"Chúng tôi buộc phải hủy chuyến dã ngoại vì trời mưa to.","audioKind":"ex"},{"en":"Improved energy efficiency may cancel out some environmental benefits if it encourages people to consume more.","vi":"Hiệu quả sử dụng năng lượng được cải thiện có thể triệt tiêu một số lợi ích môi trường nếu nó khuyến khích mọi người tiêu thụ nhiều hơn.","audioKind":"ex2"}],"collocations":[{"en":"cancel a booking","vi":"hủy đặt chỗ"},{"en":"cancel a flight","vi":"hủy chuyến bay"},{"en":"cancel out","vi":"triệt tiêu lẫn nhau; bù trừ"}],"wordFamily":["cancellation (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, dạng quá khứ là cancelled, còn tiếng Anh-Mỹ thường dùng canceled; dùng kèm với out khi mang nghĩa triệt tiêu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quality', 'en-a2-33', 'quality', '/ˈkwɑːləti/', 'A2', 'chất lượng; phẩm chất; đặc tính; chất lượng cao; hảo hạng', 'n.', 'qualitative (adj.), qualitatively (adv.)', 'Đồng nghĩa: standard, characteristic', 'Khi chỉ chất lượng nói chung thì không đếm được; khi chỉ phẩm chất, đặc tính thì là danh từ đếm được.', 'The quality of these shoes surprised me for the price.', NULL, 'Chất lượng của đôi giày này làm tôi ngạc nhiên so với mức giá.', '{"wordId":"quality","ukIpa":"/ˈkwɒləti/","usIpa":"/ˈkwɑːləti/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"How good or bad something is.","vi":"chất lượng"},{"pos":"n.","en":"A characteristic of a person or thing.","vi":"phẩm chất; đặc tính"},{"pos":"adj.","en":"Of a high standard.","vi":"chất lượng cao; hảo hạng"}],"examples":[{"en":"The quality of these shoes surprised me for the price.","vi":"Chất lượng của đôi giày này làm tôi ngạc nhiên so với mức giá.","audioKind":"ex"},{"en":"Governments should improve the quality of public transport before encouraging people to give up driving.","vi":"Chính phủ nên nâng cao chất lượng giao thông công cộng trước khi khuyến khích người dân từ bỏ việc lái xe ô tô.","audioKind":"ex2"}],"collocations":[{"en":"high quality","vi":"chất lượng cao"},{"en":"quality of life","vi":"chất lượng cuộc sống"},{"en":"leadership qualities","vi":"tố chất lãnh đạo"},{"en":"quality control","vi":"kiểm soát chất lượng"}],"wordFamily":["qualitative (adj.)","qualitatively (adv.)"],"synonyms":["standard","characteristic"],"antonyms":[],"tipVi":"Khi chỉ chất lượng nói chung thì không đếm được; khi chỉ phẩm chất, đặc tính thì là danh từ đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_present', 'en-a2-33', 'present', '/ˈprezənt/; /prɪˈzent/', 'A2', 'có mặt; hiện tại; trình bày; giới thiệu; trao tặng; món quà', 'adj.', 'presentation (n.), presenter (n.), presence (n.)', 'Trái nghĩa: absent', 'Danh từ và tính từ được nhấn trọng âm ở âm tiết đầu; động từ nhấn trọng âm ở âm tiết thứ hai.', 'All the children were present for the class photo.', NULL, 'Tất cả trẻ em đều có mặt trong bức ảnh chụp chung của lớp.', '{"wordId":"present","ukIpa":"/ˈprezənt/; /prɪˈzent/","usIpa":"/ˈprezənt/; /prɪˈzent/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"being in a place; existing or happening now","vi":"có mặt; hiện tại"},{"pos":"v.","en":"to show, explain or formally give something","vi":"trình bày; giới thiệu; trao tặng"},{"pos":"n.","en":"something given to someone; the time happening now","vi":"món quà; hiện tại"}],"examples":[{"en":"All the children were present for the class photo.","vi":"Tất cả trẻ em đều có mặt trong bức ảnh chụp chung của lớp.","audioKind":"ex"},{"en":"Researchers should present their findings clearly so that policymakers can make informed decisions about public health.","vi":"Các nhà nghiên cứu nên trình bày phát hiện của mình một cách rõ ràng để các nhà hoạch định chính sách có thể đưa ra quyết định sáng suốt về y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"be present at","vi":"có mặt tại"},{"en":"at present","vi":"hiện tại"},{"en":"present evidence","vi":"cung cấp bằng chứng"},{"en":"birthday present","vi":"quà sinh nhật"}],"wordFamily":["presentation (n.)","presenter (n.)","presence (n.)"],"synonyms":[],"antonyms":["absent"],"tipVi":"Danh từ và tính từ được nhấn trọng âm ở âm tiết đầu; động từ nhấn trọng âm ở âm tiết thứ hai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shape', 'en-a2-33', 'shape', '/ʃeɪp/', 'A2', 'hình dáng; hình thù; tác động; định hình; tạo hình; làm cho có hình dạng cụ thể', 'n.', 'shaped (adj.), shapeless (adj.)', 'Đồng nghĩa: form, mould', 'Cụm ''in shape'' có thể dùng để chỉ thể trạng cơ thể tốt, không chỉ mang nghĩa về hình dáng.', 'She cut the biscuits into the shape of stars.', NULL, 'Cô ấy cắt những chiếc bánh quy thành hình các vì sao.', '{"wordId":"shape","ukIpa":"/ʃeɪp/","usIpa":"/ʃeɪp/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"the outer form of something","vi":"hình dáng; hình thù"},{"pos":"v.","en":"to influence how something develops","vi":"tác động; định hình"},{"pos":"v.","en":"to give something a particular physical form","vi":"tạo hình; làm cho có hình dạng cụ thể"}],"examples":[{"en":"She cut the biscuits into the shape of stars.","vi":"Cô ấy cắt những chiếc bánh quy thành hình các vì sao.","audioKind":"ex"},{"en":"Early childhood experiences can shape attitudes towards learning and influence future educational achievement.","vi":"Những trải nghiệm thời thơ ấu có thể định hình thái độ đối với việc học tập và ảnh hưởng đến thành tựu học tập trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"in the shape of","vi":"có hình dáng của"},{"en":"take shape","vi":"dần thành hình"},{"en":"shape attitudes","vi":"định hình thái độ"},{"en":"stay in shape","vi":"giữ dáng; duy trì thể trạng cân đối"}],"wordFamily":["shaped (adj.)","shapeless (adj.)"],"synonyms":["form","mould"],"antonyms":[],"tipVi":"Cụm ''in shape'' có thể dùng để chỉ thể trạng cơ thể tốt, không chỉ mang nghĩa về hình dáng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_washroom', 'en-a2-33', 'washroom', '/ˈwɑːʃruːm/', 'A2', 'phòng vệ sinh; nhà vệ sinh', 'n.', NULL, 'Đồng nghĩa: restroom, toilet', 'Chủ yếu được dùng ở Bắc Mỹ, đặc biệt là Canada; tiếng Anh - Anh thường dùng ''toilet''.', 'There is a washroom just beside the lifts.', NULL, 'Có một phòng vệ sinh nằm ngay cạnh dãy thang máy.', '{"wordId":"washroom","ukIpa":"/ˈwɒʃruːm/","usIpa":"/ˈwɑːʃruːm/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a room with toilets and facilities for washing hands","vi":"phòng vệ sinh; nhà vệ sinh"}],"examples":[{"en":"There is a washroom just beside the lifts.","vi":"Có một phòng vệ sinh nằm ngay cạnh dãy thang máy.","audioKind":"ex"},{"en":"Every public library should provide an accessible washroom to accommodate visitors with a range of mobility needs.","vi":"Mỗi thư viện công cộng nên trang bị phòng vệ sinh tiếp cận được cho người khuyết tật để đáp ứng nhu cầu di chuyển đa dạng của khách tham quan.","audioKind":"ex2"}],"collocations":[{"en":"public washroom","vi":"phòng vệ sinh công cộng"},{"en":"accessible washroom","vi":"phòng vệ sinh không rào cản"},{"en":"washroom facilities","vi":"thiết bị nhà vệ sinh"}],"wordFamily":[],"synonyms":["restroom","toilet"],"antonyms":[],"tipVi":"Chủ yếu được dùng ở Bắc Mỹ, đặc biệt là Canada; tiếng Anh - Anh thường dùng ''toilet''.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_soda', 'en-a2-33', 'soda', '/ˈsoʊdə/', 'A2', 'nước ngọt có gas; nước soda pha khí carbon dioxide', 'n.', NULL, NULL, 'Trong tiếng Anh Mỹ, ''soda'' thường chỉ nước ngọt có gas; ''baking soda'' mới là bột nở/muối nở.', 'I spilled orange soda all over the kitchen floor.', NULL, 'Tôi vô tình làm đổ nước ngọt vị cam lênh láng khắp sàn bếp.', '{"wordId":"soda","ukIpa":"/ˈsəʊdə/","usIpa":"/ˈsoʊdə/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a sweet fizzy drink, especially in American English","vi":"nước ngọt có gas"},{"pos":"n.","en":"water containing dissolved gas, often mixed with other drinks","vi":"nước soda pha khí carbon dioxide"}],"examples":[{"en":"I spilled orange soda all over the kitchen floor.","vi":"Tôi vô tình làm đổ nước ngọt vị cam lênh láng khắp sàn bếp.","audioKind":"ex"},{"en":"Replacing sugary soda with water can help reduce daily sugar intake and support better dental health.","vi":"Việc thay thế nước ngọt có đường bằng nước lọc có thể giúp giảm lượng đường tiêu thụ mỗi ngày và hỗ trợ sức khỏe răng miệng tốt hơn.","audioKind":"ex2"}],"collocations":[{"en":"a can of soda","vi":"một lon nước ngọt"},{"en":"soda water","vi":"nước soda"},{"en":"sugary soda","vi":"nước ngọt có đường"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh Mỹ, ''soda'' thường chỉ nước ngọt có gas; ''baking soda'' mới là bột nở/muối nở.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nephew', 'en-a2-33', 'nephew', '/ˈnefjuː/', 'A2', 'cháu trai (con của anh, chị, em ruột hoặc anh, chị, em vợ/chồng)', 'n.', NULL, NULL, 'nephew chỉ cháu trai họ hàng; từ tương ứng phái nữ là niece.', 'My nephew proudly showed me his new bicycle.', NULL, 'Cậu cháu trai hãnh diện khoe với tôi chiếc xe đạp mới của thằng bé.', '{"wordId":"nephew","ukIpa":"/ˈnefjuː/","usIpa":"/ˈnefjuː/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A son of your sibling or your spouse''s sibling.","vi":"cháu trai (con của anh, chị, em ruột hoặc anh, chị, em vợ/chồng)"}],"examples":[{"en":"My nephew proudly showed me his new bicycle.","vi":"Cậu cháu trai hãnh diện khoe với tôi chiếc xe đạp mới của thằng bé.","audioKind":"ex"},{"en":"Looking after a nephew or niece can help young adults understand the responsibilities of raising children.","vi":"Việc chăm sóc cháu trai hoặc cháu gái có thể giúp người trẻ hiểu được trách nhiệm nuôi dạy trẻ nhỏ.","audioKind":"ex2"}],"collocations":[{"en":"young nephew","vi":"cháu trai nhỏ tuổi"},{"en":"nieces and nephews","vi":"các cháu trai và cháu gái"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"nephew chỉ cháu trai họ hàng; từ tương ứng phái nữ là niece.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_extremely', 'en-a2-33', 'extremely', '/ɪkˈstriːmli/', 'A2', 'cực kỳ; vô cùng', 'adv.', 'extreme (adj.)', 'Đồng nghĩa: very, exceedingly', 'Dùng để bổ nghĩa cho tính từ hoặc phó từ có thể phân cấp độ, mang sắc thái mạnh hơn từ very.', 'The soup was extremely hot, so I waited.', NULL, 'Món súp nóng cực kỳ nên tôi phải đợi một lát.', '{"wordId":"extremely","ukIpa":"/ɪkˈstriːmli/","usIpa":"/ɪkˈstriːmli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"To a very great degree.","vi":"cực kỳ; vô cùng"}],"examples":[{"en":"The soup was extremely hot, so I waited.","vi":"Món súp nóng cực kỳ nên tôi phải đợi một lát.","audioKind":"ex"},{"en":"Access to reliable internet is extremely important for students who depend on online learning.","vi":"Khả năng tiếp cận internet ổn định là vô cùng quan trọng đối với học sinh phụ thuộc vào việc học trực tuyến.","audioKind":"ex2"}],"collocations":[{"en":"extremely important","vi":"vô cùng quan trọng"},{"en":"extremely difficult","vi":"cực kỳ khó khăn"},{"en":"extremely useful","vi":"cực kỳ hữu ích"}],"wordFamily":["extreme (adj.)"],"synonyms":["very","exceedingly"],"antonyms":[],"tipVi":"Dùng để bổ nghĩa cho tính từ hoặc phó từ có thể phân cấp độ, mang sắc thái mạnh hơn từ very.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lettuce', 'en-a2-33', 'lettuce', '/ˈletɪs/', 'A2', 'rau xà lách; rau diếp', 'n.', NULL, NULL, 'Khi chỉ nguyên liệu thực phẩm, từ này thường không đếm được; để chỉ một cây xà lách nguyên vẹn, dùng a head of lettuce.', 'Wash the lettuce before adding it to your sandwich.', NULL, 'Hãy rửa sạch rau xà lách trước khi kẹp vào bánh mì sandwich của bạn.', '{"wordId":"lettuce","ukIpa":"/ˈletɪs/","usIpa":"/ˈletɪs/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a vegetable with leaves often eaten raw in salads","vi":"rau xà lách; rau diếp"}],"examples":[{"en":"Wash the lettuce before adding it to your sandwich.","vi":"Hãy rửa sạch rau xà lách trước khi kẹp vào bánh mì sandwich của bạn.","audioKind":"ex"},{"en":"Growing lettuce in urban gardens can give residents access to fresh food near their homes.","vi":"Việc trồng rau xà lách trong các khu vườn đô thị có thể giúp cư dân tiếp cận nguồn thực phẩm tươi ngon ngay gần nhà.","audioKind":"ex2"}],"collocations":[{"en":"lettuce leaves","vi":"lá xà lách"},{"en":"a head of lettuce","vi":"một cây xà lách"},{"en":"crisp lettuce","vi":"rau xà lách tươi giòn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ nguyên liệu thực phẩm, từ này thường không đếm được; để chỉ một cây xà lách nguyên vẹn, dùng a head of lettuce.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ugly', 'en-a2-33', 'ugly', '/ˈʌɡli/', 'A2', 'xấu xí; khó coi; khó chịu; hiểm ác; căng thẳng', 'adj.', 'ugliness (n.)', 'Đồng nghĩa: unattractive, unsightly · Trái nghĩa: beautiful, attractive', 'So sánh hơn uglier, so sánh nhất ugliest; dùng để chỉ ngoại hình con người sẽ mang hàm ý bất lịch sự.', 'We hid the ugly pipes behind a wooden screen.', NULL, 'Chúng tôi đã che những đường ống xấu xí đằng sau một tấm bình phong bằng gỗ.', '{"wordId":"ugly","ukIpa":"/ˈʌɡli/","usIpa":"/ˈʌɡli/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Unpleasant to look at.","vi":"xấu xí; khó coi"},{"pos":"adj.","en":"Unpleasant or threatening, especially involving anger or conflict.","vi":"khó chịu; hiểm ác; căng thẳng"}],"examples":[{"en":"We hid the ugly pipes behind a wooden screen.","vi":"Chúng tôi đã che những đường ống xấu xí đằng sau một tấm bình phong bằng gỗ.","audioKind":"ex"},{"en":"Poorly planned developments can create ugly urban landscapes that reduce residents'' satisfaction with their neighbourhoods.","vi":"Các dự án phát triển được quy hoạch kém có thể tạo ra cảnh quan đô thị nhếch nhác, làm giảm sự hài lòng của cư dân đối với khu dân cư của họ.","audioKind":"ex2"}],"collocations":[{"en":"ugly building","vi":"tòa nhà xấu xí"},{"en":"ugly sight","vi":"cảnh tượng chướng mắt"},{"en":"turn ugly","vi":"trở nên căng thẳng, hiểm ác"},{"en":"ugly confrontation","vi":"cuộc đối đầu căng thẳng"}],"wordFamily":["ugliness (n.)"],"synonyms":["unattractive","unsightly"],"antonyms":["beautiful","attractive"],"tipVi":"So sánh hơn uglier, so sánh nhất ugliest; dùng để chỉ ngoại hình con người sẽ mang hàm ý bất lịch sự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jumper', 'en-a2-33', 'jumper', '/ˈdʒʌmpər/', 'A2', 'áo chui đầu (len); áo len (tiếng Anh - Anh); người (hoặc động vật) nhảy, đặc biệt là vận động viên nhảy cao hoặc nhảy xa; váy liền thân không tay mặc ngoài áo sơ mi hoặc áo blouse (tiếng Anh - Mỹ)', 'n.', 'jump (v.), jump (n.)', 'Đồng nghĩa: sweater', 'Tiếng Anh - Anh gọi áo len chui đầu là jumper; tiếng Anh - Mỹ thường dùng từ sweater.', 'I packed a warm jumper for the camping trip.', NULL, 'Tôi đã mang theo một chiếc áo len ấm cho chuyến đi cắm trại.', '{"wordId":"jumper","ukIpa":"/ˈdʒʌmpə/","usIpa":"/ˈdʒʌmpər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A knitted piece of clothing covering the upper body.","vi":"áo chui đầu (len); áo len (tiếng Anh - Anh)"},{"pos":"n.","en":"A person or animal that jumps, especially in sport.","vi":"người (hoặc động vật) nhảy, đặc biệt là vận động viên nhảy cao hoặc nhảy xa"},{"pos":"n.","en":"A sleeveless dress worn over a shirt or blouse.","vi":"váy liền thân không tay mặc ngoài áo sơ mi hoặc áo blouse (tiếng Anh - Mỹ)"}],"examples":[{"en":"I packed a warm jumper for the camping trip.","vi":"Tôi đã mang theo một chiếc áo len ấm cho chuyến đi cắm trại.","audioKind":"ex"},{"en":"Wearing a jumper indoors can reduce the need for heating during colder months.","vi":"Mặc áo len ở trong nhà có thể giảm bớt nhu cầu sử dụng lò sưởi trong những tháng trời lạnh.","audioKind":"ex2"}],"collocations":[{"en":"woollen jumper","vi":"áo len lông cừu"},{"en":"put on a jumper","vi":"mặc áo len vào"},{"en":"high jumper","vi":"vận động viên nhảy cao"}],"wordFamily":["jump (v.)","jump (n.)"],"synonyms":["sweater"],"antonyms":[],"tipVi":"Tiếng Anh - Anh gọi áo len chui đầu là jumper; tiếng Anh - Mỹ thường dùng từ sweater.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_period', 'en-a2-33', 'period', '/ˈpɪriəd/', 'A2', 'khoảng thời gian; thời kỳ; tiết học; giờ học; thời kỳ kinh nguyệt; kỳ kinh', 'n.', 'periodic (adj.), periodically (adv.)', NULL, 'Để diễn tả một khoảng thời gian, người ta thường dùng a period of; trong tiếng Anh - Mỹ từ này cũng có nghĩa là dấu chấm câu.', 'We stayed indoors during a short period of heavy rain.', NULL, 'Chúng tôi ở trong nhà trong suốt trận mưa lớn kéo dài trong một khoảng thời gian ngắn.', '{"wordId":"period","ukIpa":"/ˈpɪəriəd/","usIpa":"/ˈpɪriəd/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A length of time or a stage in history.","vi":"khoảng thời gian; thời kỳ"},{"pos":"n.","en":"A scheduled length of time for a school lesson.","vi":"tiết học; giờ học"},{"pos":"n.","en":"The monthly flow of blood from the uterus.","vi":"thời kỳ kinh nguyệt; kỳ kinh"}],"examples":[{"en":"We stayed indoors during a short period of heavy rain.","vi":"Chúng tôi ở trong nhà trong suốt trận mưa lớn kéo dài trong một khoảng thời gian ngắn.","audioKind":"ex"},{"en":"A prolonged period of unemployment can affect both financial security and mental health.","vi":"Một giai đoạn thất nghiệp kéo dài có thể ảnh hưởng đến cả sự an toàn về tài chính lẫn sức khỏe tinh thần.","audioKind":"ex2"}],"collocations":[{"en":"a period of time","vi":"một khoảng thời gian"},{"en":"a transition period","vi":"thời kỳ quá độ"},{"en":"a historical period","vi":"thời kỳ lịch sử"},{"en":"a heavy period","vi":"kỳ kinh nguyệt ra nhiều"}],"wordFamily":["periodic (adj.)","periodically (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Để diễn tả một khoảng thời gian, người ta thường dùng a period of; trong tiếng Anh - Mỹ từ này cũng có nghĩa là dấu chấm câu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sheet', 'en-a2-33', 'sheet', '/ʃiːt/', 'A2', 'ga giường; tấm khăn trải giường; tờ (giấy); tấm (kim loại hoặc vật liệu mỏng, phẳng)', 'n.', 'sheeting (n.)', NULL, 'Sheet là danh từ đếm được; nói một tờ giấy dùng a sheet of paper.', 'I spread a clean sheet over the mattress.', NULL, 'Tôi trải một chiếc ga trải giường sạch lên tấm nệm.', '{"wordId":"sheet","ukIpa":"/ʃiːt/","usIpa":"/ʃiːt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A large piece of cloth used to cover a bed.","vi":"ga giường; tấm khăn trải giường"},{"pos":"n.","en":"A thin, flat piece of paper, metal, or another material.","vi":"tờ (giấy); tấm (kim loại hoặc vật liệu mỏng, phẳng)"}],"examples":[{"en":"I spread a clean sheet over the mattress.","vi":"Tôi trải một chiếc ga trải giường sạch lên tấm nệm.","audioKind":"ex"},{"en":"Schools can reduce paper waste by encouraging students to use both sides of each sheet.","vi":"Các trường học có thể giảm thiểu lãng phí giấy bằng cách khuyến khích học sinh sử dụng cả hai mặt của mỗi tờ giấy.","audioKind":"ex2"}],"collocations":[{"en":"bed sheet","vi":"ga trải giường"},{"en":"a sheet of paper","vi":"một tờ giấy"},{"en":"a sheet of glass","vi":"một tấm kính"},{"en":"sheet metal","vi":"tấm kim loại mỏng"}],"wordFamily":["sheeting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Sheet là danh từ đếm được; nói một tờ giấy dùng a sheet of paper.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_liter', 'en-a2-33', 'liter', '/ˈliːtɚ/', 'A2', 'lít (đơn vị đo thể tích bằng một nghìn mi-li-lít)', 'n.', NULL, 'Đồng nghĩa: litre', 'Liter là cách viết theo tiếng Anh - Mỹ, tiếng Anh - Anh viết là litre; một lít tương đương với một nghìn mi-li-lít.', 'This bottle holds exactly one liter of fresh milk.', NULL, 'Bình này chứa đúng một lít sữa tươi.', '{"wordId":"liter","ukIpa":"/ˈliːtə/","usIpa":"/ˈliːtɚ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A unit of volume equal to one thousand milliliters.","vi":"lít (đơn vị đo thể tích bằng một nghìn mi-li-lít)"}],"examples":[{"en":"This bottle holds exactly one liter of fresh milk.","vi":"Bình này chứa đúng một lít sữa tươi.","audioKind":"ex"},{"en":"Measuring household water consumption by the liter can help residents understand how much they use each day.","vi":"Đo lường lượng nước tiêu thụ trong hộ gia đình theo đơn vị lít có thể giúp cư dân hiểu rõ họ dùng bao nhiêu nước mỗi ngày.","audioKind":"ex2"}],"collocations":[{"en":"a liter of water","vi":"một lít nước"},{"en":"per liter","vi":"mỗi lít"},{"en":"half a liter","vi":"nửa lít"}],"wordFamily":[],"synonyms":["litre"],"antonyms":[],"tipVi":"Liter là cách viết theo tiếng Anh - Mỹ, tiếng Anh - Anh viết là litre; một lít tương đương với một nghìn mi-li-lít.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lie', 'en-a2-33', 'lie', '/laɪ/', 'A2', 'nằm; nằm ngửa; đặt nằm ngang; nói dối; nói sai sự thật; lời nói dối; điều dối trá', 'v.', 'liar (n.), lying (adj.)', 'Đồng nghĩa: recline, falsehood · Trái nghĩa: truth', 'Động từ nằm: lie–lay–lain; động từ nói dối: lie–lied–lied.', 'I like to lie on the grass after lunch.', NULL, 'Tôi thích nằm trên bãi cỏ sau bữa trưa.', '{"wordId":"lie","ukIpa":"/laɪ/","usIpa":"/laɪ/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"Rest with your body or an object in a flat position","vi":"nằm; nằm ngửa; đặt nằm ngang"},{"pos":"v.","en":"Say something you know is not true","vi":"nói dối; nói sai sự thật"},{"pos":"n.","en":"Something untrue that someone says deliberately","vi":"lời nói dối; điều dối trá"}],"examples":[{"en":"I like to lie on the grass after lunch.","vi":"Tôi thích nằm trên bãi cỏ sau bữa trưa.","audioKind":"ex"},{"en":"Advertisements that lie about environmental benefits can undermine public trust and discourage genuinely sustainable purchasing decisions.","vi":"Những quảng cáo nói dối về lợi ích môi trường có thể làm xói mòn lòng tin của công chúng và làm nản lòng những quyết định mua sắm thực sự bền vững.","audioKind":"ex2"}],"collocations":[{"en":"lie down","vi":"nằm xuống"},{"en":"lie awake","vi":"nằm trằn trọc không ngủ được"},{"en":"lie to someone","vi":"nói dối ai đó"},{"en":"tell a lie","vi":"nói dối"}],"wordFamily":["liar (n.)","lying (adj.)"],"synonyms":["recline","falsehood"],"antonyms":["truth"],"tipVi":"Động từ nằm: lie–lay–lain; động từ nói dối: lie–lied–lied.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ever', 'en-a2-33', 'ever', '/ˈevər/', 'A2', 'từng; bao giờ (đặc biệt dùng trong câu hỏi và câu phủ định); luôn luôn; mãi mãi (thường mô tả sự thay đổi liên tục); rốt cuộc; bao giờ hết (dùng để nhấn mạnh sự ngạc nhiên trong câu hỏi)', 'adv.', NULL, 'Trái nghĩa: never', 'Hỏi về trải nghiệm thường dùng Have you ever…; trong câu khẳng định không tùy tiện thay thế cho always.', 'Have you ever watched the sunrise from a mountain?', NULL, 'Bạn đã từng ngắm cảnh mặt trời mọc trên núi chưa?', '{"wordId":"ever","ukIpa":"/ˈevə/","usIpa":"/ˈevər/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"At any time, especially in questions and negative statements.","vi":"từng; bao giờ (đặc biệt dùng trong câu hỏi và câu phủ định)"},{"pos":"adv.","en":"Continuously or always, often describing an ongoing change.","vi":"luôn luôn; mãi mãi (thường mô tả sự thay đổi liên tục)"},{"pos":"adv.","en":"Used to emphasize surprise in a question.","vi":"rốt cuộc; bao giờ hết (dùng để nhấn mạnh sự ngạc nhiên trong câu hỏi)"}],"examples":[{"en":"Have you ever watched the sunrise from a mountain?","vi":"Bạn đã từng ngắm cảnh mặt trời mọc trên núi chưa?","audioKind":"ex"},{"en":"Public transport is more important than ever as growing cities struggle with congestion and air pollution.","vi":"Giao thông công cộng quan trọng hơn bao giờ hết khi các thành phố đang ngày càng mở rộng phải vật lộn với tình trạng tắc nghẽn và ô nhiễm không khí.","audioKind":"ex2"}],"collocations":[{"en":"ever since","vi":"kể từ đó đến nay"},{"en":"hardly ever","vi":"hầu như chưa bao giờ"},{"en":"more than ever","vi":"hơn bao giờ hết"},{"en":"ever-growing demand","vi":"nhu cầu ngày càng tăng"}],"wordFamily":[],"synonyms":[],"antonyms":["never"],"tipVi":"Hỏi về trải nghiệm thường dùng Have you ever…; trong câu khẳng định không tùy tiện thay thế cho always.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_instead', 'en-a2-33', 'instead', '/ɪnˈsted/', 'A2', 'thay vào đó; thay thế', 'adv.', NULL, NULL, 'instead có thể đứng độc lập làm trạng từ; còn instead of phải được theo sau bởi danh từ hoặc danh động từ.', 'The café was closed, so we went home instead.', NULL, 'Quán cà phê đã đóng cửa, thế là chúng tôi quyết định đi về nhà thay thế.', '{"wordId":"instead","ukIpa":"/ɪnˈsted/","usIpa":"/ɪnˈsted/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"in place of someone or something else","vi":"thay vào đó; thay thế"}],"examples":[{"en":"The café was closed, so we went home instead.","vi":"Quán cà phê đã đóng cửa, thế là chúng tôi quyết định đi về nhà thay thế.","audioKind":"ex"},{"en":"Instead of expanding roads, cities should invest in public transport to reduce congestion and pollution.","vi":"Thay vì mở rộng đường sá, các thành phố nên đầu tư vào giao thông công cộng để giảm thiểu tình trạng tắc nghẽn và ô nhiễm.","audioKind":"ex2"}],"collocations":[{"en":"instead of","vi":"thay vì"},{"en":"go instead","vi":"thay vào đó đi"},{"en":"use something instead","vi":"dùng thứ khác thay thế"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"instead có thể đứng độc lập làm trạng từ; còn instead of phải được theo sau bởi danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_owner', 'en-a2-33', 'owner', '/ˈoʊnər/', 'A2', 'chủ sở hữu; người chủ', 'n.', 'own (v.), ownership (n.)', 'Đồng nghĩa: proprietor', 'Để diễn tả ai là chủ sở hữu của cái gì, dùng cấu trúc the owner of kèm theo danh từ.', 'The owner of the bakery greets us every morning.', NULL, 'Chủ tiệm bánh chào đón chúng tôi mỗi buổi sáng.', '{"wordId":"owner","ukIpa":"/ˈəʊnə/","usIpa":"/ˈoʊnər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A person or organisation that something belongs to.","vi":"chủ sở hữu; người chủ"}],"examples":[{"en":"The owner of the bakery greets us every morning.","vi":"Chủ tiệm bánh chào đón chúng tôi mỗi buổi sáng.","audioKind":"ex"},{"en":"Property owners should maintain their buildings to ensure the safety of tenants and nearby residents.","vi":"Các chủ sở hữu bất động sản có trách nhiệm bảo dưỡng tòa nhà để đảm bảo an toàn cho người thuê nhà và cư dân xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"business owner","vi":"chủ doanh nghiệp"},{"en":"property owner","vi":"chủ bất động sản"},{"en":"rightful owner","vi":"chủ sở hữu hợp pháp"}],"wordFamily":["own (v.)","ownership (n.)"],"synonyms":["proprietor"],"antonyms":[],"tipVi":"Để diễn tả ai là chủ sở hữu của cái gì, dùng cấu trúc the owner of kèm theo danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dish', 'en-a2-33', 'dish', '/dɪʃ/', 'A2', 'đĩa; bát đĩa; món ăn; chén dĩa (số nhiều)', 'n.', NULL, NULL, 'a dish có thể chỉ một món ăn cụ thể; cụm từ do the dishes có nghĩa là rửa chén bát.', 'Please put the strawberries in that blue dish.', NULL, 'Làm ơn đặt những quả dâu tây vào chiếc đĩa màu xanh đó.', '{"wordId":"dish","ukIpa":"/dɪʃ/","usIpa":"/dɪʃ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A container used for serving or cooking food.","vi":"đĩa; bát đĩa"},{"pos":"n.","en":"Food prepared in a particular way as part of a meal.","vi":"món ăn"},{"pos":"n.","en":"Plates, bowls, and other utensils used for meals.","vi":"chén dĩa (số nhiều)"}],"examples":[{"en":"Please put the strawberries in that blue dish.","vi":"Làm ơn đặt những quả dâu tây vào chiếc đĩa màu xanh đó.","audioKind":"ex"},{"en":"Traditional dishes can attract international tourists while helping local communities preserve their distinctive food culture.","vi":"Các món ăn truyền thống không chỉ thu hút du khách quốc tế mà còn giúp cộng đồng địa phương bảo tồn văn hóa ẩm thực độc đáo của họ.","audioKind":"ex2"}],"collocations":[{"en":"serving dish","vi":"đĩa đựng thức ăn"},{"en":"traditional dish","vi":"món ăn truyền thống"},{"en":"do the dishes","vi":"rửa bát đĩa"},{"en":"main dish","vi":"món chính"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"a dish có thể chỉ một món ăn cụ thể; cụm từ do the dishes có nghĩa là rửa chén bát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quite', 'en-a2-33', 'quite', '/kwaɪt/', 'A2', 'khá; tương đối; hoàn toàn; tuyệt đối', 'adv.', NULL, NULL, 'quite good thường mang nghĩa là khá tốt; trong khi quite impossible mang nghĩa là hoàn toàn không thể.', 'The soup is quite spicy, but I like it.', NULL, 'Món súp này khá cay, nhưng tôi lại thích thế.', '{"wordId":"quite","ukIpa":"/kwaɪt/","usIpa":"/kwaɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"To a fairly large degree, but not extremely.","vi":"khá; tương đối"},{"pos":"adv.","en":"Completely or to the greatest possible degree.","vi":"hoàn toàn; tuyệt đối"}],"examples":[{"en":"The soup is quite spicy, but I like it.","vi":"Món súp này khá cay, nhưng tôi lại thích thế.","audioKind":"ex"},{"en":"Although cycling is quite popular among students, inadequate infrastructure prevents many commuters from choosing this sustainable option.","vi":"Mặc dù việc đi xe đạp khá phổ biến trong học sinh, nhưng cơ sở hạ tầng chưa đồng bộ đã ngăn cản nhiều người đi làm lựa chọn phương thức di chuyển bền vững này.","audioKind":"ex2"}],"collocations":[{"en":"quite good","vi":"khá tốt"},{"en":"quite a few","vi":"khá nhiều"},{"en":"quite different","vi":"hoàn toàn khác biệt"},{"en":"not quite","vi":"không hẳn; chưa hoàn toàn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"quite good thường mang nghĩa là khá tốt; trong khi quite impossible mang nghĩa là hoàn toàn không thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_33_1', 'en-a2-33', 'Cách dùng “cancel” (v.) — hủy bỏ; bãi bỏ; hoãn', 'cancel a booking  ·  cancel a flight  ·  cancel out', 'Trong tiếng Anh-Anh, dạng quá khứ là cancelled, còn tiếng Anh-Mỹ thường dùng canceled; dùng kèm với out khi mang nghĩa triệt tiêu.', 'Họ từ (Word Family): cancellation (n.)', '[{"hanzi":"We had to cancel our picnic because of heavy rain.","pinyin":"","meaning":"Chúng tôi buộc phải hủy chuyến dã ngoại vì trời mưa to."},{"hanzi":"Improved energy efficiency may cancel out some environmental benefits if it encourages people to consume more.","pinyin":"","meaning":"Hiệu quả sử dụng năng lượng được cải thiện có thể triệt tiêu một số lợi ích môi trường nếu nó khuyến khích mọi người tiêu thụ nhiều hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_33_2', 'en-a2-33', 'Cách dùng “period” (n.) — khoảng thời gian; thời kỳ', 'a period of time  ·  a transition period  ·  a historical period', 'Để diễn tả một khoảng thời gian, người ta thường dùng a period of; trong tiếng Anh - Mỹ từ này cũng có nghĩa là dấu chấm câu.', 'Họ từ (Word Family): periodic (adj.), periodically (adv.)', '[{"hanzi":"We stayed indoors during a short period of heavy rain.","pinyin":"","meaning":"Chúng tôi ở trong nhà trong suốt trận mưa lớn kéo dài trong một khoảng thời gian ngắn."},{"hanzi":"A prolonged period of unemployment can affect both financial security and mental health.","pinyin":"","meaning":"Một giai đoạn thất nghiệp kéo dài có thể ảnh hưởng đến cả sự an toàn về tài chính lẫn sức khỏe tinh thần."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_33_3', 'en-a2-33', 'Cách dùng “lettuce” (n.) — rau xà lách; rau diếp', 'lettuce leaves  ·  a head of lettuce  ·  crisp lettuce', 'Khi chỉ nguyên liệu thực phẩm, từ này thường không đếm được; để chỉ một cây xà lách nguyên vẹn, dùng a head of lettuce.', NULL, '[{"hanzi":"Wash the lettuce before adding it to your sandwich.","pinyin":"","meaning":"Hãy rửa sạch rau xà lách trước khi kẹp vào bánh mì sandwich của bạn."},{"hanzi":"Growing lettuce in urban gardens can give residents access to fresh food near their homes.","pinyin":"","meaning":"Việc trồng rau xà lách trong các khu vườn đô thị có thể giúp cư dân tiếp cận nguồn thực phẩm tươi ngon ngay gần nhà."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_33_4', 'en-a2-33', 'Cách dùng “liter” (n.) — lít (đơn vị đo thể tích bằng một nghìn mi-li-lít)', 'a liter of water  ·  per liter  ·  half a liter', 'Liter là cách viết theo tiếng Anh - Mỹ, tiếng Anh - Anh viết là litre; một lít tương đương với một nghìn mi-li-lít.', 'Đồng nghĩa: litre', '[{"hanzi":"This bottle holds exactly one liter of fresh milk.","pinyin":"","meaning":"Bình này chứa đúng một lít sữa tươi."},{"hanzi":"Measuring household water consumption by the liter can help residents understand how much they use each day.","pinyin":"","meaning":"Đo lường lượng nước tiêu thụ trong hộ gia đình theo đơn vị lít có thể giúp cư dân hiểu rõ họ dùng bao nhiêu nước mỗi ngày."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_33_1', 'en-a2-33', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
