INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_33_1_3', 'ten_a2_33_1', 'pick', 'You can pick any colour for your new curtains.', 'You can pick any colour for your new curtains.', '/pɪk/', 'Bạn có thể chọn bất kỳ màu nào cho bộ rèm cửa mới của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_33_1_4', 'ten_a2_33_1', 'garage', 'We keep our car and bicycles in the garage.', 'We keep our car and bicycles in the garage.', '/ɡəˈrɑːʒ/', 'Chúng tôi để ô tô và xe đạp trong nhà để xe.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_33_1_5', 'ten_a2_33_1', 'service', 'The friendly service made us feel welcome at the café.', 'The friendly service made us feel welcome at the café.', '/ˈsɝːvɪs/', 'Dịch vụ thân thiện khiến chúng tôi cảm thấy được chào đón tại quán cà phê.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_33_1_6', 'ten_a2_33_1', 'cupboard', 'The clean bowls are in the cupboard above the sink.', 'The clean bowls are in the cupboard above the sink.', '/ˈkʌbɚd/', 'Những chiếc bát sạch nằm trong tủ chén phía trên bồn rửa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_33_1_7', 'ten_a2_33_1', 'worse', 'The weather grew worse as we climbed the hill.', 'The weather grew worse as we climbed the hill.', '/wɝːs/', 'Thời tiết càng trở nên tồi tệ hơn khi chúng tôi leo lên đồi.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_33_1_8', 'ten_a2_33_1', 'cancel', 'We had to cancel our picnic because of heavy rain.', 'We had to cancel our picnic because of heavy rain.', '/ˈkænsəl/', 'Chúng tôi buộc phải hủy chuyến dã ngoại vì trời mưa to.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_33_1_1', 'en-a2-33', 'ten_a2_33_1', 'listening', 'listening', 'Your map was helpful when we explored the village.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Thời tiết càng trở nên tồi tệ hơn khi chúng tôi leo lên đồi.","Chúng tôi ở trong nhà trong suốt trận mưa lớn kéo dài trong một khoảng thời gian ngắn.","Làm ơn đặt những quả dâu tây vào chiếc đĩa màu xanh đó.","Tấm bản đồ của bạn rất hữu ích khi chúng tôi khám phá ngôi làng."]'::jsonb, 3, 'Your map was helpful when we explored the village. → Tấm bản đồ của bạn rất hữu ích khi chúng tôi khám phá ngôi làng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_33_1_2', 'en-a2-33', 'ten_a2_33_1', 'listening', 'listening', 'Someone pinned a lost cat poster to the noticeboard.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Có một phòng vệ sinh nằm ngay cạnh dãy thang máy.","Chúng tôi buộc phải hủy chuyến dã ngoại vì trời mưa to.","Ai đó đã ghim tờ rơi tìm mèo lạc lên bảng thông báo.","Bình này chứa đúng một lít sữa tươi."]'::jsonb, 2, 'Someone pinned a lost cat poster to the noticeboard. → Ai đó đã ghim tờ rơi tìm mèo lạc lên bảng thông báo.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_33_1_3', 'en-a2-33', 'ten_a2_33_1', 'listening', 'listening', 'You can pick any colour for your new curtains.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chủ tiệm bánh chào đón chúng tôi mỗi buổi sáng.","Bạn có thể chọn bất kỳ màu nào cho bộ rèm cửa mới của mình.","Chúng tôi để ô tô và xe đạp trong nhà để xe.","Tất cả trẻ em đều có mặt trong bức ảnh chụp chung của lớp."]'::jsonb, 1, 'You can pick any colour for your new curtains. → Bạn có thể chọn bất kỳ màu nào cho bộ rèm cửa mới của mình.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_33_2', 'en-a2-33', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_33_2_1', 'ten_a2_33_2', 'helpful', 'Clear feedback is particularly helpful for students who are learning to organise their ideas in academic essays.', 'Clear feedback is particularly helpful for students who are learning to organise their ideas in academic essays.', '/ˈhelpfəl/', 'Phản hồi rõ ràng đặc biệt hữu ích cho học sinh đang học cách tổ chức ý tưởng trong các bài luận học thuật.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_33_2_2', 'ten_a2_33_2', 'noticeboard', 'A shared noticeboard can help residents discover local events and participate more actively in community life.', 'A shared noticeboard can help residents discover local events and participate more actively in community life.', '/ˈnoʊtɪsbɔːrd/', 'Bảng thông báo chung có thể giúp cư dân nắm bắt các sự kiện địa phương và tham gia tích cực hơn vào đời sống cộng đồng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_33_2_3', 'ten_a2_33_2', 'pick', 'Schools should help students pick courses that match their interests rather than focus only on future earnings.', 'Schools should help students pick courses that match their interests rather than focus only on future earnings.', '/pɪk/', 'Nhà trường nên giúp học sinh chọn các môn học phù hợp với sở thích thay vì chỉ tập trung vào thu nhập trong tương lai.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_33_2_4', 'ten_a2_33_2', 'garage', 'Converting an unused garage into living space can provide additional accommodation without requiring new land.', 'Converting an unused garage into living space can provide additional accommodation without requiring new land.', '/ɡəˈrɑːʒ/', 'Việc chuyển đổi một nhà để xe không dùng đến thành không gian sinh hoạt có thể cung cấp thêm chỗ ở mà không cần tốn đất mới.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_33_2_5', 'ten_a2_33_2', 'service', 'Reliable bus services allow residents without cars to reach hospitals, schools and workplaces.', 'Reliable bus services allow residents without cars to reach hospitals, schools and workplaces.', '/ˈsɝːvɪs/', 'Dịch vụ xe buýt đáng tin cậy giúp những cư dân không có ô tô có thể đến bệnh viện, trường học và nơi làm việc.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_33_2_6', 'ten_a2_33_2', 'cupboard', 'Well-designed cupboards can maximise storage space in small apartments without making living areas feel crowded.', 'Well-designed cupboards can maximise storage space in small apartments without making living areas feel crowded.', '/ˈkʌbɚd/', 'Những chiếc tủ được thiết kế tốt có thể tối đa hóa không gian lưu trữ trong các căn hộ nhỏ mà không làm cho khu vực sinh hoạt có cảm giác chật chội.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_33_2_1', 'en-a2-33', 'ten_a2_33_2', 'listening', 'listening', 'Clear feedback is particularly helpful for students who are learning to organise their ideas in academic essays.', NULL, 'Trong câu vừa nghe, từ “helpful” mang nghĩa nào sau đây?', '["hữu ích; giúp ích","ghế dài","tổ chức; chuẩn bị sự kiện hoặc hoạt động","găng tay; bao tay"]'::jsonb, 0, '“helpful” (/ˈhelpfəl/): hữu ích; giúp ích. Câu đầy đủ: Clear feedback is particularly helpful for students who are learning to organise their ideas in academic essays.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
