INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_33_2', 'en-a2-33', NULL, 'comprehensive_test', 'listening', 'Someone pinned a lost cat poster to the noticeboard.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tấm bản đồ của bạn rất hữu ích khi chúng tôi khám phá ngôi làng.","Món súp nóng cực kỳ nên tôi phải đợi một lát.","Ai đó đã ghim tờ rơi tìm mèo lạc lên bảng thông báo.","Tôi thích nằm trên bãi cỏ sau bữa trưa."]'::jsonb, 2, 'Someone pinned a lost cat poster to the noticeboard. → Ai đó đã ghim tờ rơi tìm mèo lạc lên bảng thông báo.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_33_3', 'en-a2-33', NULL, 'comprehensive_test', 'listening', 'pick', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["từ (một thời điểm trong quá khứ) cho đến nay","nhận được (cái gì đó do ai gửi, trao hoặc cung cấp)","chọn; lựa chọn","vỗ tay; khua tay"]'::jsonb, 2, 'pick (/pɪk/) → chọn; lựa chọn; hái (quả, hoa); cái cuốc', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_33_4', 'en-a2-33', NULL, 'comprehensive_test', 'listening', 'We keep our car and bicycles in the garage.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi để ô tô và xe đạp trong nhà để xe.","Món súp này khá cay, nhưng tôi lại thích thế.","Chất lượng của đôi giày này làm tôi ngạc nhiên so với mức giá.","Tôi trải một chiếc ga trải giường sạch lên tấm nệm."]'::jsonb, 0, 'We keep our car and bicycles in the garage. → Chúng tôi để ô tô và xe đạp trong nhà để xe.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
