INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_33_6', 'en-a2-33', NULL, 'comprehensive_test', 'listening', 'The clean bowls are in the cupboard above the sink.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã mang theo một chiếc áo len ấm cho chuyến đi cắm trại.","Cậu cháu trai hãnh diện khoe với tôi chiếc xe đạp mới của thằng bé.","Những chiếc bát sạch nằm trong tủ chén phía trên bồn rửa.","Ai đó đã ghim tờ rơi tìm mèo lạc lên bảng thông báo."]'::jsonb, 2, 'The clean bowls are in the cupboard above the sink. → Những chiếc bát sạch nằm trong tủ chén phía trên bồn rửa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_33_7', 'en-a2-33', NULL, 'comprehensive_test', 'listening', 'worse', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cháu gái (con của con trai hoặc con gái)","tệ hơn; tồi tệ hơn; nghiêm trọng hơn","ngăn nắp; gọn gàng","đau đớn; gây đau"]'::jsonb, 1, 'worse (/wɝːs/) → tệ hơn; tồi tệ hơn; nghiêm trọng hơn; kém hơn', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_33_8', 'en-a2-33', NULL, 'comprehensive_test', 'listening', 'We had to cancel our picnic because of heavy rain.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy cắt những chiếc bánh quy thành hình các vì sao.","Tôi vô tình làm đổ nước ngọt vị cam lênh láng khắp sàn bếp.","Chúng tôi buộc phải hủy chuyến dã ngoại vì trời mưa to.","Bạn có thể chọn bất kỳ màu nào cho bộ rèm cửa mới của mình."]'::jsonb, 2, 'We had to cancel our picnic because of heavy rain. → Chúng tôi buộc phải hủy chuyến dã ngoại vì trời mưa to.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
