INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_33_18', 'en-a2-33', NULL, 'comprehensive_test', 'reading', NULL, 'Clear feedback is particularly helpful for students who are learning to organise their ideas in academic essays.', 'Dựa vào câu trên, từ “helpful” có nghĩa phù hợp nhất là gì?', '["vui vẻ; hạnh phúc","đi bộ đường dài; leo núi; đi dã ngoại (đi dạo dài ở ngoài trời, đặc biệt là vùng nông thôn)","lễ Phục sinh","hữu ích; giúp ích"]'::jsonb, 3, 'helpful: hữu ích; giúp ích; hay giúp đỡ; nhiệt tình. Dịch cả câu: Phản hồi rõ ràng đặc biệt hữu ích cho học sinh đang học cách tổ chức ý tưởng trong các bài luận học thuật.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_33_19', 'en-a2-33', NULL, 'comprehensive_test', 'reading', NULL, 'A shared noticeboard can help residents discover local events and participate more actively in community life.', 'Dựa vào câu trên, từ “noticeboard” có nghĩa phù hợp nhất là gì?', '["bất kỳ ai; người nào","máy tính xách tay; máy tính xách tay cá nhân","hãng hàng không","bảng thông báo; bảng tin"]'::jsonb, 3, 'noticeboard: bảng thông báo; bảng tin. Dịch cả câu: Bảng thông báo chung có thể giúp cư dân nắm bắt các sự kiện địa phương và tham gia tích cực hơn vào đời sống cộng đồng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_33_20', 'en-a2-33', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should help students pick courses that match their interests rather than focus only on future earnings.', 'Dựa vào câu trên, từ “pick” có nghĩa phù hợp nhất là gì?', '["chọn; lựa chọn","tháp; tòa tháp","cái bát; cái tô; cái chén","so sánh; đối chiếu"]'::jsonb, 0, 'pick: chọn; lựa chọn; hái (quả, hoa); cái cuốc. Dịch cả câu: Nhà trường nên giúp học sinh chọn các môn học phù hợp với sở thích thay vì chỉ tập trung vào thu nhập trong tương lai.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_33_21', 'en-a2-33', NULL, 'comprehensive_test', 'reading', NULL, 'Converting an unused garage into living space can provide additional accommodation without requiring new land.', 'Dựa vào câu trên, từ “garage” có nghĩa phù hợp nhất là gì?', '["loại; kiểu; hạng","bất đồng ý kiến; không đồng tình","nữa; không... nữa","thư viện; phòng đọc"]'::jsonb, 3, 'garage: thư viện; phòng đọc; tiệm sửa xe; xưởng bảo dưỡng ô tô. Dịch cả câu: Việc chuyển đổi một nhà để xe không dùng đến thành không gian sinh hoạt có thể cung cấp thêm chỗ ở mà không cần tốn đất mới.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
