INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-34', 'en', 'Bài 34: Đời sống hằng ngày (6) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '27 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2034, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gram', 'en-a2-34', 'gram', '/ɡræm/', 'A2', 'gam', 'n.', NULL, NULL, 'Ký hiệu là g; số nhiều là grams.', 'Add one gram of salt and stir the soup.', NULL, 'Thêm một gam muối và khuấy đều nồi súp.', '{"wordId":"gram","ukIpa":"/ɡræm/","usIpa":"/ɡræm/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A unit of mass equal to one thousandth of a kilogram.","vi":"gam"}],"examples":[{"en":"Add one gram of salt and stir the soup.","vi":"Thêm một gam muối và khuấy đều nồi súp.","audioKind":"ex"},{"en":"Comparing the nutrients provided per gram can help consumers make more informed choices about packaged foods.","vi":"Việc so sánh các chất dinh dưỡng được cung cấp trong mỗi gam có thể giúp người tiêu dùng đưa ra lựa chọn sáng suốt hơn về các loại thực phẩm đóng gói.","audioKind":"ex2"}],"collocations":[{"en":"a gram of salt","vi":"một gam muối"},{"en":"per gram","vi":"mỗi gam"},{"en":"weigh in grams","vi":"tính trọng lượng theo gam"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Ký hiệu là g; số nhiều là grams.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cookie', 'en-a2-34', 'cookie', '/ˈkʊki/', 'A2', 'bánh quy ngọt; tệp cookie (dữ liệu nhỏ lưu trên trình duyệt)', 'n.', NULL, 'Đồng nghĩa: biscuit', 'Bánh quy nhỏ; cookie của trang web không giống với tệp bộ nhớ đệm.', 'There is one chocolate cookie left in the jar.', NULL, 'Vẫn còn một chiếc bánh quy sô-cô-la trong lọ.', '{"wordId":"cookie","ukIpa":"/ˈkʊki/","usIpa":"/ˈkʊki/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A small, flat, sweet baked food","vi":"bánh quy ngọt"},{"pos":"n.","en":"A small piece of data a website stores on your device","vi":"tệp cookie (dữ liệu nhỏ lưu trên trình duyệt)"}],"examples":[{"en":"There is one chocolate cookie left in the jar.","vi":"Vẫn còn một chiếc bánh quy sô-cô-la trong lọ.","audioKind":"ex"},{"en":"Websites often use cookies to remember user preferences, but some also track browsing behaviour.","vi":"Các trang web thường sử dụng cookie để ghi nhớ sở thích của người dùng, nhưng một số trang cũng theo dõi hành vi duyệt web.","audioKind":"ex2"}],"collocations":[{"en":"chocolate chip cookie","vi":"bánh quy sô-cô-la chip"},{"en":"cookie jar","vi":"lọ đựng bánh quy"},{"en":"accept cookies","vi":"chấp nhận cookie"},{"en":"delete cookies","vi":"xóa cookie"}],"wordFamily":[],"synonyms":["biscuit"],"antonyms":[],"tipVi":"Bánh quy nhỏ; cookie của trang web không giống với tệp bộ nhớ đệm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_missing', 'en-a2-34', 'missing', '/ˈmɪsɪŋ/', 'A2', 'thất lạc; mất tích; thiếu; vắng mặt', 'adj.', 'miss (v.)', 'Đồng nghĩa: lost, absent · Trái nghĩa: present', 'missing đóng vai trò tính từ chỉ sự thất lạc hoặc thiếu vắng; be missing from nghĩa là thiếu.', 'We found the missing kitten asleep behind the sofa.', NULL, 'Chúng tôi tìm thấy chú mèo con bị thất lạc đang ngủ sau chiếc ghế sô-cô-la.', '{"wordId":"missing","ukIpa":"/ˈmɪsɪŋ/","usIpa":"/ˈmɪsɪŋ/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"lost or absent, with whereabouts unknown","vi":"thất lạc; mất tích"},{"pos":"adj.","en":"not present where something should be","vi":"thiếu; vắng mặt"}],"examples":[{"en":"We found the missing kitten asleep behind the sofa.","vi":"Chúng tôi tìm thấy chú mèo con bị thất lạc đang ngủ sau chiếc ghế sô-cô-la.","audioKind":"ex"},{"en":"Missing data can undermine the reliability of research findings and lead policymakers to draw inaccurate conclusions.","vi":"Dữ liệu bị thiếu có thể làm suy giảm độ tin cậy của các kết quả nghiên cứu và khiến các nhà hoạch định chính sách đưa ra những kết luận thiếu chính xác.","audioKind":"ex2"}],"collocations":[{"en":"go missing","vi":"mất tích"},{"en":"a missing person","vi":"người mất tích"},{"en":"missing data","vi":"dữ liệu bị thiếu"},{"en":"a missing piece","vi":"mảnh ghép còn thiếu"}],"wordFamily":["miss (v.)"],"synonyms":["lost","absent"],"antonyms":["present"],"tipVi":"missing đóng vai trò tính từ chỉ sự thất lạc hoặc thiếu vắng; be missing from nghĩa là thiếu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_left-hand', 'en-a2-34', 'left-hand', '/ˌleft ˈhænd/', 'A2', 'thuộc bên trái; phía tay trái', 'adj.', 'left (adj.), left-handed (adj.)', 'Trái nghĩa: right-hand', 'left-hand chỉ phía bên trái; left-handed chỉ người thuận tay trái.', 'Keep your ticket in the left-hand pocket of your jacket.', NULL, 'Hãy để vé của bạn vào túi áo khoác bên trái.', '{"wordId":"left-hand","ukIpa":"/ˌleft ˈhænd/","usIpa":"/ˌleft ˈhænd/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Located on the left side.","vi":"thuộc bên trái; phía tay trái"}],"examples":[{"en":"Keep your ticket in the left-hand pocket of your jacket.","vi":"Hãy để vé của bạn vào túi áo khoác bên trái.","audioKind":"ex"},{"en":"Separating cyclists from vehicles in the left-hand lane could make this busy road safer for everyone.","vi":"Việc tách người đi xe đạp ra khỏi các phương tiện ở làn đường bên trái có thể giúp con đường đông đúc này trở nên an toàn hơn cho tất cả mọi người.","audioKind":"ex2"}],"collocations":[{"en":"the left-hand side","vi":"bên trái"},{"en":"the left-hand corner","vi":"góc bên trái"},{"en":"the left-hand lane","vi":"làn đường bên trái"}],"wordFamily":["left (adj.)","left-handed (adj.)"],"synonyms":[],"antonyms":["right-hand"],"tipVi":"left-hand chỉ phía bên trái; left-handed chỉ người thuận tay trái.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pocket', 'en-a2-34', 'pocket', '/ˈpɑːkɪt/', 'A2', 'túi áo; túi quần; bỏ vào túi; bỏ túi riêng (tiền bạc); nhỏ gọn; bỏ túi', 'n.', 'pocketful (n.)', NULL, 'pocket money chỉ tiền tiêu vặt, rất phổ biến trong tiếng Anh-Anh.', 'I found my missing key in my coat pocket.', NULL, 'Tôi tìm thấy chiếc chìa khóa bị mất của mình trong túi áo khoác.', '{"wordId":"pocket","ukIpa":"/ˈpɒkɪt/","usIpa":"/ˈpɑːkɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A small bag sewn into clothing for carrying things.","vi":"túi áo; túi quần"},{"pos":"v.","en":"To put something in your pocket, or take money dishonestly.","vi":"bỏ vào túi; bỏ túi riêng (tiền bạc)"},{"pos":"adj.","en":"Small enough to fit easily inside a pocket.","vi":"nhỏ gọn; bỏ túi"}],"examples":[{"en":"I found my missing key in my coat pocket.","vi":"Tôi tìm thấy chiếc chìa khóa bị mất của mình trong túi áo khoác.","audioKind":"ex"},{"en":"Pocket dictionaries remain useful for language learners when internet access is unavailable or unreliable.","vi":"Từ điển bỏ túi vẫn rất hữu ích cho người học ngôn ngữ khi không có kết nối internet hoặc mạng không ổn định.","audioKind":"ex2"}],"collocations":[{"en":"coat pocket","vi":"túi áo khoác"},{"en":"pocket money","vi":"tiền tiêu vặt"},{"en":"out of pocket","vi":"tự bỏ tiền túi; chịu lỗ"},{"en":"pocket dictionary","vi":"từ điển bỏ túi"}],"wordFamily":["pocketful (n.)"],"synonyms":[],"antonyms":[],"tipVi":"pocket money chỉ tiền tiêu vặt, rất phổ biến trong tiếng Anh-Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_biscuit', 'en-a2-34', 'biscuit', '/ˈbɪskɪt/', 'A2', 'bánh quy giòn (cách dùng Anh-Anh); bánh mì tròn nhỏ mềm (cách dùng Mỹ)', 'n.', NULL, NULL, 'biscuit trong tiếng Anh-Anh thường tương ứng với cookie trong tiếng Anh-Mỹ; tiếng Mỹ còn chỉ loại bánh mì nhỏ mềm.', 'She dipped a biscuit into her warm tea.', NULL, 'Cô ấy nhúng một chiếc bánh quy vào ly trà ấm.', '{"wordId":"biscuit","ukIpa":"/ˈbɪskɪt/","usIpa":"/ˈbɪskɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a small, flat, crisp baked food, often sweet","vi":"bánh quy giòn (cách dùng Anh-Anh)"},{"pos":"n.","en":"a small, soft bread roll raised without yeast","vi":"bánh mì tròn nhỏ mềm (cách dùng Mỹ)"}],"examples":[{"en":"She dipped a biscuit into her warm tea.","vi":"Cô ấy nhúng một chiếc bánh quy vào ly trà ấm.","audioKind":"ex"},{"en":"Replacing sugary biscuits with fresh fruit can help children develop healthier eating habits over time.","vi":"Việc thay thế các loại bánh quy nhiều đường bằng trái cây tươi có thể giúp trẻ em dần hình thành thói quen ăn uống lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"chocolate biscuit","vi":"bánh quy sô-cô-la"},{"en":"a packet of biscuits","vi":"một gói bánh quy"},{"en":"biscuit tin","vi":"hộp đựng bánh quy"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"biscuit trong tiếng Anh-Anh thường tương ứng với cookie trong tiếng Anh-Mỹ; tiếng Mỹ còn chỉ loại bánh mì nhỏ mềm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_untidy', 'en-a2-34', 'untidy', '/ʌnˈtaɪdi/', 'A2', 'bừa bộn; không ngăn nắp; lượm thượm; không biết giữ gìn đồ đạc gọn gàng', 'adj.', 'tidy (adj.), untidily (adv.), untidiness (n.)', 'Đồng nghĩa: messy, disorganised · Trái nghĩa: tidy, neat', 'untidy nhấn mạnh sự không ngăn nắp, không nhất thiết bẩn thỉu như dirty.', 'Her untidy desk was covered with cups and notebooks.', NULL, 'Bàn làm việc bừa bộn của cô ấy bày đầy cốc và vở ghi chép.', '{"wordId":"untidy","ukIpa":"/ʌnˈtaɪdi/","usIpa":"/ʌnˈtaɪdi/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"not neat or well arranged","vi":"bừa bộn; không ngăn nắp"},{"pos":"adj.","en":"not keeping your belongings or surroundings neat","vi":"lượm thượm; không biết giữ gìn đồ đạc gọn gàng"}],"examples":[{"en":"Her untidy desk was covered with cups and notebooks.","vi":"Bàn làm việc bừa bộn của cô ấy bày đầy cốc và vở ghi chép.","audioKind":"ex"},{"en":"Shared workspaces can quickly become untidy unless employees take responsibility for keeping communal areas clean and organised.","vi":"Các không gian làm việc chung có thể nhanh chóng trở nên bừa bộn trừ khi các nhân viên có ý thức giữ gìn khu vực sinh hoạt chung luôn sạch sẽ và ngăn nắp.","audioKind":"ex2"}],"collocations":[{"en":"an untidy room","vi":"căn phòng bừa bộn"},{"en":"an untidy desk","vi":"bàn làm việc bừa bộn"},{"en":"untidy handwriting","vi":"chữ viết cẩu thả"}],"wordFamily":["tidy (adj.)","untidily (adv.)","untidiness (n.)"],"synonyms":["messy","disorganised"],"antonyms":["tidy","neat"],"tipVi":"untidy nhấn mạnh sự không ngăn nắp, không nhất thiết bẩn thỉu như dirty.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boot', 'en-a2-34', 'boot', '/buːt/', 'A2', 'giày bốt; ủng; cốp xe; khoang hành lý phía sau ô tô; khởi động máy tính và nạp hệ điều hành', 'n.', 'reboot (v.)', NULL, 'Cốp xe ô tô tiếng Anh - Anh là boot, tiếng Anh - Mỹ là trunk.', 'My boots kept my feet dry in the rain.', NULL, 'Đôi bốt giúp chân tôi khô ráo trong trời mưa.', '{"wordId":"boot","ukIpa":"/buːt/","usIpa":"/buːt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"footwear that covers the foot and part of the leg","vi":"giày bốt; ủng"},{"pos":"n.","en":"the enclosed storage space at the back of a car","vi":"cốp xe; khoang hành lý phía sau ô tô"},{"pos":"v.","en":"to start a computer and load its operating system","vi":"khởi động máy tính và nạp hệ điều hành"}],"examples":[{"en":"My boots kept my feet dry in the rain.","vi":"Đôi bốt giúp chân tôi khô ráo trong trời mưa.","audioKind":"ex"},{"en":"Protective boots are essential for construction workers because they reduce the risk of serious foot injuries.","vi":"Giày bảo hộ là vật dụng thiết yếu đối với công nhân xây dựng vì chúng làm giảm nguy cơ chấn thương chân nghiêm trọng.","audioKind":"ex2"}],"collocations":[{"en":"a pair of boots","vi":"một đôi bốt"},{"en":"walking boots","vi":"giày đi bộ đường dài"},{"en":"car boot","vi":"cốp ô tô"},{"en":"boot up a computer","vi":"khởi động máy tính"}],"wordFamily":["reboot (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Cốp xe ô tô tiếng Anh - Anh là boot, tiếng Anh - Mỹ là trunk.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ring', 'en-a2-34', 'ring', '/rɪŋ/', 'A2', 'nhẫn; vật hình vòng tròn; reo chuông; làm chuông kêu; gọi điện thoại cho ai đó', 'n.', 'ringing (n.)', NULL, 'Dạng quá khứ của reo chuông, gọi điện là rang và quá khứ phân từ là rung.', 'She slipped the silver ring onto her finger.', NULL, 'Cô ấy xỏ chiếc nhẫn bạc vào ngón tay.', '{"wordId":"ring","ukIpa":"/rɪŋ/","usIpa":"/rɪŋ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a circular band, especially one worn on a finger","vi":"nhẫn; vật hình vòng tròn"},{"pos":"v.","en":"to make a bell sound or cause one to sound","vi":"reo chuông; làm chuông kêu"},{"pos":"v.","en":"to contact someone by telephone","vi":"gọi điện thoại cho ai đó"}],"examples":[{"en":"She slipped the silver ring onto her finger.","vi":"Cô ấy xỏ chiếc nhẫn bạc vào ngón tay.","audioKind":"ex"},{"en":"Passengers should silence their phones because devices that ring repeatedly can disturb others on public transport.","vi":"Hành khách nên để điện thoại ở chế độ im lặng vì những thiết bị reo chuông liên tục có thể làm phiền người khác trên phương tiện công cộng.","audioKind":"ex2"}],"collocations":[{"en":"a wedding ring","vi":"nhẫn cưới"},{"en":"ring the doorbell","vi":"bấm chuông cửa"},{"en":"give someone a ring","vi":"gọi cho ai đó một cuộc điện thoại"},{"en":"a ring of trees","vi":"vòng tròn cây"}],"wordFamily":["ringing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ của reo chuông, gọi điện là rang và quá khứ phân từ là rung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heating', 'en-a2-34', 'heating', '/ˈhiːtɪŋ/', 'A2', 'hệ thống sưởi; sự sưởi ấm; sự làm ấm; sự nung nóng', 'n.', 'heat (n.), heat (v.), heater (n.), heated (adj.)', 'Trái nghĩa: cooling', 'Khi chỉ hệ thống sưởi, từ này thường không đếm được: turn on the heating.', 'We turned the heating on when the evening grew chilly.', NULL, 'Chúng tôi đã bật lò sưởi lên khi trời chiều trở lạnh.', '{"wordId":"heating","ukIpa":"/ˈhiːtɪŋ/","usIpa":"/ˈhiːtɪŋ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"The system or process that keeps a building warm.","vi":"hệ thống sưởi; sự sưởi ấm"},{"pos":"n.","en":"The process of making something warmer.","vi":"sự làm ấm; sự nung nóng"}],"examples":[{"en":"We turned the heating on when the evening grew chilly.","vi":"Chúng tôi đã bật lò sưởi lên khi trời chiều trở lạnh.","audioKind":"ex"},{"en":"Improving home insulation can reduce heating costs and lower the environmental impact of household energy consumption.","vi":"Cải thiện khả năng giữ nhiệt của ngôi nhà có thể làm giảm chi phí sưởi ấm và giảm thiểu tác động môi trường từ việc tiêu thụ năng lượng gia đình.","audioKind":"ex2"}],"collocations":[{"en":"central heating","vi":"sưởi ấm trung tâm"},{"en":"underfloor heating","vi":"sưởi ấm dưới sàn"},{"en":"heating bills","vi":"hóa đơn tiền sưởi"},{"en":"heating system","vi":"hệ thống sưởi"}],"wordFamily":["heat (n.)","heat (v.)","heater (n.)","heated (adj.)"],"synonyms":[],"antonyms":["cooling"],"tipVi":"Khi chỉ hệ thống sưởi, từ này thường không đếm được: turn on the heating.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_postcode', 'en-a2-34', 'postcode', '/ˈpoʊstkoʊd/', 'A2', 'mã bưu chính', 'n.', NULL, 'Đồng nghĩa: postal code, ZIP code', 'Tiếng Anh-Anh dùng postcode; tiếng Anh-Mỹ thường dùng ZIP code.', 'Please include your postcode when you fill in the form.', NULL, 'Vui lòng điền mã bưu chính của bạn khi bạn điền vào biểu mẫu.', '{"wordId":"postcode","ukIpa":"/ˈpəʊstkəʊd/","usIpa":"/ˈpoʊstkoʊd/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a code identifying a postal delivery area","vi":"mã bưu chính"}],"examples":[{"en":"Please include your postcode when you fill in the form.","vi":"Vui lòng điền mã bưu chính của bạn khi bạn điền vào biểu mẫu.","audioKind":"ex"},{"en":"Researchers used postcode data to compare access to public transport across different residential areas.","vi":"Các nhà nghiên cứu đã sử dụng dữ liệu mã bưu chính để so sánh khả năng tiếp cận phương tiện giao thông công cộng giữa các khu dân cư khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"enter a postcode","vi":"nhập mã bưu chính"},{"en":"postcode area","vi":"vùng mã bưu chính"},{"en":"postcode search","vi":"tra cứu mã bưu chính"}],"wordFamily":[],"synonyms":["postal code","ZIP code"],"antonyms":[],"tipVi":"Tiếng Anh-Anh dùng postcode; tiếng Anh-Mỹ thường dùng ZIP code.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blonde', 'en-a2-34', 'blonde', '/blɑːnd/', 'A2', 'có tóc màu vàng hoe; màu vàng nhạt; người phụ nữ tóc vàng', 'adj.', 'blond (adj.)', 'Đồng nghĩa: fair-haired', 'Blonde thường dùng cho nữ; mô tả nam giới thường dùng blond.', 'Her blonde hair shone brightly in the afternoon sun.', NULL, 'Mái tóc vàng hoe của cô ấy tỏa sáng rực rỡ dưới ánh nắng buổi chiều.', '{"wordId":"blonde","ukIpa":"/blɒnd/","usIpa":"/blɑːnd/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Having pale yellow hair, or describing this hair colour.","vi":"có tóc màu vàng hoe; màu vàng nhạt"},{"pos":"n.","en":"A woman or girl with pale yellow hair.","vi":"người phụ nữ tóc vàng"}],"examples":[{"en":"Her blonde hair shone brightly in the afternoon sun.","vi":"Mái tóc vàng hoe của cô ấy tỏa sáng rực rỡ dưới ánh nắng buổi chiều.","audioKind":"ex"},{"en":"Films that repeatedly associate blonde hair with particular personalities can reinforce unfair stereotypes about appearance.","vi":"Những bộ phim liên tục gắn liền mái tóc vàng với những tính cách cụ thể có thể củng cố những định kiến không công bằng về ngoại hình.","audioKind":"ex2"}],"collocations":[{"en":"blonde hair","vi":"mái tóc vàng"},{"en":"naturally blonde","vi":"vàng tự nhiên"},{"en":"platinum blonde","vi":"màu vàng bạch kim"}],"wordFamily":["blond (adj.)"],"synonyms":["fair-haired"],"antonyms":[],"tipVi":"Blonde thường dùng cho nữ; mô tả nam giới thường dùng blond.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lend', 'en-a2-34', 'lend', '/lend/', 'A2', 'cho mượn; cho vay; đem lại; hỗ trợ', 'v.', 'lender (n.), lending (n.)', 'Đồng nghĩa: loan · Trái nghĩa: borrow', 'Lend là cho mượn, borrow là đi mượn; dạng quá khứ của lend là lent.', 'Could you lend me your umbrella until tomorrow?', NULL, 'Bạn có thể cho tôi mượn chiếc ô của bạn cho đến ngày mai được không?', '{"wordId":"lend","ukIpa":"/lend/","usIpa":"/lend/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"Let someone use something temporarily, expecting its return.","vi":"cho mượn; cho vay"},{"pos":"v.","en":"Give support or add a particular quality to something.","vi":"đem lại; hỗ trợ"}],"examples":[{"en":"Could you lend me your umbrella until tomorrow?","vi":"Bạn có thể cho tôi mượn chiếc ô của bạn cho đến ngày mai được không?","audioKind":"ex"},{"en":"Local banks could lend small businesses money to invest in cleaner production methods.","vi":"Các ngân hàng địa phương có thể cho các doanh nghiệp nhỏ vay tiền để đầu tư vào các phương pháp sản xuất sạch hơn.","audioKind":"ex2"}],"collocations":[{"en":"lend someone something","vi":"cho ai mượn cái gì"},{"en":"lend money to","vi":"cho vay tiền đối với"},{"en":"lend support to","vi":"hỗ trợ cho"},{"en":"lend a hand","vi":"giúp một tay"}],"wordFamily":["lender (n.)","lending (n.)"],"synonyms":["loan"],"antonyms":["borrow"],"tipVi":"Lend là cho mượn, borrow là đi mượn; dạng quá khứ của lend là lent.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sandal', 'en-a2-34', 'sandal', '/ˈsændl/', 'A2', 'giày xăng-đan; giày sandal', 'n.', NULL, NULL, 'Đơn chiếc dùng sandal, một đôi dùng a pair of sandals.', 'A small stone got stuck inside my sandal.', NULL, 'Một viên đá nhỏ kẹt vào bên trong chiếc sandal của tôi.', '{"wordId":"sandal","ukIpa":"/ˈsændl/","usIpa":"/ˈsændl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A light shoe with straps that leaves much of the foot uncovered.","vi":"giày xăng-đan; giày sandal"}],"examples":[{"en":"A small stone got stuck inside my sandal.","vi":"Một viên đá nhỏ kẹt vào bên trong chiếc sandal của tôi.","audioKind":"ex"},{"en":"In warm climates, sandals are popular because their open design allows air to circulate around the feet.","vi":"Ở những vùng có khí hậu ấm áp, giày sandal rất phổ biến vì thiết kế thoáng khí giúp không khí lưu thông quanh bàn chân.","audioKind":"ex2"}],"collocations":[{"en":"a pair of sandals","vi":"một đôi sandal"},{"en":"leather sandals","vi":"giày sandal da"},{"en":"flat sandals","vi":"giày sandal đế bệt"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đơn chiếc dùng sandal, một đôi dùng a pair of sandals.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_regular', 'en-a2-34', 'regular', '/ˈreɡjələr/', 'A2', 'đều đặn; thường xuyên; đều; cân đối; khách quen', 'adj.', 'regularly (adv.), regularity (n.), irregular (adj.)', 'Đồng nghĩa: frequent · Trái nghĩa: irregular', 'regular nhấn mạnh tính quy luật hoặc thường xuyên, không đồng nghĩa với continuous (liên tục không ngừng).', 'Our dog needs regular walks to stay happy and healthy.', NULL, 'Chú chó của chúng tôi cần được đi dạo đều đặn để luôn vui vẻ và khỏe mạnh.', '{"wordId":"regular","ukIpa":"/ˈreɡjələ/","usIpa":"/ˈreɡjələr/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Happening repeatedly, often with similar gaps between events.","vi":"đều đặn; thường xuyên"},{"pos":"adj.","en":"Having an even shape, pattern, or arrangement.","vi":"đều; cân đối"},{"pos":"n.","en":"Someone who often visits the same place.","vi":"khách quen"}],"examples":[{"en":"Our dog needs regular walks to stay happy and healthy.","vi":"Chú chó của chúng tôi cần được đi dạo đều đặn để luôn vui vẻ và khỏe mạnh.","audioKind":"ex"},{"en":"Regular exercise can reduce the risk of chronic disease and improve overall wellbeing in older adults.","vi":"Tập thể dục đều đặn có thể làm giảm nguy cơ mắc các bệnh mãn tính và cải thiện sức khỏe tổng thể ở người cao tuổi.","audioKind":"ex2"}],"collocations":[{"en":"regular exercise","vi":"tập thể dục đều đặn"},{"en":"at regular intervals","vi":"cách đều nhau"},{"en":"a regular customer","vi":"một khách quen"},{"en":"a regular pattern","vi":"một mô hình đều đặn"}],"wordFamily":["regularly (adv.)","regularity (n.)","irregular (adj.)"],"synonyms":["frequent"],"antonyms":["irregular"],"tipVi":"regular nhấn mạnh tính quy luật hoặc thường xuyên, không đồng nghĩa với continuous (liên tục không ngừng).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stairs', 'en-a2-34', 'stairs', '/sterz/', 'A2', 'cầu thang', 'n.', 'stair (n.), staircase (n.), stairway (n.)', NULL, 'stairs ở dạng số nhiều nên động từ đi kèm chia số nhiều; một đoạn cầu thang dùng a flight of stairs.', 'We carried the heavy suitcase up the narrow stairs.', NULL, 'Chúng tôi khiêng chiếc vali nặng nề đi lên cầu thang chật hẹp.', '{"wordId":"stairs","ukIpa":"/steəz/","usIpa":"/sterz/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A set of steps connecting different levels of a building.","vi":"cầu thang"}],"examples":[{"en":"We carried the heavy suitcase up the narrow stairs.","vi":"Chúng tôi khiêng chiếc vali nặng nề đi lên cầu thang chật hẹp.","audioKind":"ex"},{"en":"Public buildings should provide lifts alongside stairs to ensure equal access for people with limited mobility.","vi":"Các công trình công cộng nên lắp đặt thang máy bên cạnh cầu thang bộ để đảm bảo sự tiếp cận bình đẳng cho những người bị hạn chế khả năng di chuyển.","audioKind":"ex2"}],"collocations":[{"en":"climb the stairs","vi":"leo cầu thang"},{"en":"a flight of stairs","vi":"một đoạn cầu thang"},{"en":"take the stairs","vi":"đi cầu thang bộ"}],"wordFamily":["stair (n.)","staircase (n.)","stairway (n.)"],"synonyms":[],"antonyms":[],"tipVi":"stairs ở dạng số nhiều nên động từ đi kèm chia số nhiều; một đoạn cầu thang dùng a flight of stairs.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accept', 'en-a2-34', 'accept', '/əkˈsept/', 'A2', 'chấp nhận; đồng ý nhận; thừa nhận; công nhận; chịu đựng; chấp nhận thực tế', 'v.', 'acceptance (n.), acceptable (adj.), unacceptable (adj.)', 'Trái nghĩa: reject, refuse', 'Đồng ý nhận gợi ý dùng accept; chấp nhận một vật không đồng nghĩa với việc chỉ nhận được (receive).', 'I gladly accepted her invitation to dinner on Saturday.', NULL, 'Tôi vui vẻ nhận lời mời ăn tối vào thứ Bảy của cô ấy.', '{"wordId":"accept","ukIpa":"/əkˈsept/","usIpa":"/əkˈsept/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"Agree to receive something or say yes to an offer","vi":"chấp nhận; đồng ý nhận"},{"pos":"v.","en":"Recognize that something is true or valid","vi":"thừa nhận; công nhận"},{"pos":"v.","en":"Take responsibility or stop resisting an unpleasant situation","vi":"chịu đựng; chấp nhận thực tế"}],"examples":[{"en":"I gladly accepted her invitation to dinner on Saturday.","vi":"Tôi vui vẻ nhận lời mời ăn tối vào thứ Bảy của cô ấy.","audioKind":"ex"},{"en":"Governments must accept responsibility for ensuring that all children have access to basic education.","vi":"Chính phủ phải chịu trách nhiệm đảm bảo rằng tất cả trẻ em đều được tiếp cận giáo dục cơ bản.","audioKind":"ex2"}],"collocations":[{"en":"accept an offer","vi":"chấp nhận một lời đề nghị"},{"en":"accept responsibility","vi":"chịu trách nhiệm"},{"en":"accept an invitation","vi":"chấp nhận lời mời"},{"en":"accept that","vi":"thừa nhận rằng"}],"wordFamily":["acceptance (n.)","acceptable (adj.)","unacceptable (adj.)"],"synonyms":[],"antonyms":["reject","refuse"],"tipVi":"Đồng ý nhận gợi ý dùng accept; chấp nhận một vật không đồng nghĩa với việc chỉ nhận được (receive).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_take-away', 'en-a2-34', 'take away', '/teɪk əˈweɪ/', 'A2', 'mang đi; mua mang về; lấy đi; dọn đi; tước đoạt', 'phr.', 'takeaway (n.)', NULL, 'take away là động từ sử dụng dạng cụm từ; danh từ chỉ đồ ăn mang về viết liền là takeaway.', 'Could I have a vegetable sandwich to take away?', NULL, 'Cho tôi một bánh mì kẹp rau củ mang đi nhé?', '{"wordId":"take-away","ukIpa":"/teɪk əˈweɪ/","usIpa":"/teɪk əˈweɪ/","cefr":"A2","topic":"daily","senses":[{"pos":"phr.","en":"to buy prepared food and eat it somewhere else","vi":"mang đi; mua mang về"},{"pos":"phr.","en":"to remove something from a place or person","vi":"lấy đi; dọn đi; tước đoạt"}],"examples":[{"en":"Could I have a vegetable sandwich to take away?","vi":"Cho tôi một bánh mì kẹp rau củ mang đi nhé?","audioKind":"ex"},{"en":"Restaurants should offer reusable containers to customers who buy meals to take away, reducing packaging waste.","vi":"Các nhà hàng nên cung cấp hộp đựng tái sử dụng cho khách hàng mua đồ mang về, nhằm giảm thiểu rác thải bao bì.","audioKind":"ex2"}],"collocations":[{"en":"food to take away","vi":"đồ ăn mang về"},{"en":"take away the plates","vi":"dọn đĩa đi"},{"en":"take away someone''s rights","vi":"tước đoạt quyền lợi của ai đó"}],"wordFamily":["takeaway (n.)"],"synonyms":[],"antonyms":[],"tipVi":"take away là động từ sử dụng dạng cụm từ; danh từ chỉ đồ ăn mang về viết liền là takeaway.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_candy', 'en-a2-34', 'candy', '/ˈkændi/', 'A2', 'kẹo', 'n.', NULL, 'Đồng nghĩa: sweets', 'Người Mỹ thường dùng candy, trong khi người Anh hay dùng sweets; một viên/miếng kẹo dùng a piece of.', 'She offered each guest a small piece of candy.', NULL, 'Cô ấy mời mỗi vị khách một chiếc kẹo nhỏ.', '{"wordId":"candy","ukIpa":"/ˈkændi/","usIpa":"/ˈkændi/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a sweet food made mainly from sugar","vi":"kẹo"}],"examples":[{"en":"She offered each guest a small piece of candy.","vi":"Cô ấy mời mỗi vị khách một chiếc kẹo nhỏ.","audioKind":"ex"},{"en":"Limiting advertisements for candy aimed at children could help families develop healthier eating habits.","vi":"Việc hạn chế quảng cáo kẹo nhắm vào trẻ em có thể giúp các gia đình hình thành thói quen ăn uống lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"a piece of candy","vi":"một viên kẹo"},{"en":"hard candy","vi":"kẹo cứng"},{"en":"a candy bar","vi":"một thanh kẹo"},{"en":"a candy store","vi":"cửa hàng bán kẹo"}],"wordFamily":[],"synonyms":["sweets"],"antonyms":[],"tipVi":"Người Mỹ thường dùng candy, trong khi người Anh hay dùng sweets; một viên/miếng kẹo dùng a piece of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_midnight', 'en-a2-34', 'midnight', '/ˈmɪdnaɪt/', 'A2', 'nửa đêm; mười hai giờ đêm', 'n.', NULL, 'Trái nghĩa: noon', 'Khi nói vào lúc nửa đêm dùng cụm at midnight, không dùng in midnight.', 'We stayed awake until midnight watching the snow fall.', NULL, 'Chúng tôi thức trắng đến tận nửa đêm để ngắm tuyết rơi.', '{"wordId":"midnight","ukIpa":"/ˈmɪdnaɪt/","usIpa":"/ˈmɪdnaɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Twelve o''clock at night, when one day ends and another begins.","vi":"nửa đêm; mười hai giờ đêm"}],"examples":[{"en":"We stayed awake until midnight watching the snow fall.","vi":"Chúng tôi thức trắng đến tận nửa đêm để ngắm tuyết rơi.","audioKind":"ex"},{"en":"Extending public transport services beyond midnight would benefit shift workers who currently rely on expensive taxi journeys.","vi":"Việc kéo dài thời gian hoạt động của các phương tiện giao thông công cộng qua nửa đêm sẽ mang lại lợi ích cho những công nhân làm ca đêm vốn hiện phải phụ thuộc vào những chuyến taxi đắt đỏ.","audioKind":"ex2"}],"collocations":[{"en":"at midnight","vi":"vào lúc nửa đêm"},{"en":"until midnight","vi":"cho đến nửa đêm"},{"en":"around midnight","vi":"khoảng nửa đêm"},{"en":"a midnight snack","vi":"bữa ăn nhẹ lúc nửa đêm"}],"wordFamily":[],"synonyms":[],"antonyms":["noon"],"tipVi":"Khi nói vào lúc nửa đêm dùng cụm at midnight, không dùng in midnight.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bar', 'en-a2-34', 'bar', '/bɑr/', 'A2', 'quán bar; quầy đồ uống; thanh; thỏi (vật rắn dài và hẹp); cấm; ngăn cản chính thức', 'n.', 'barred (adj.)', NULL, 'Cấu trúc biểu thị sự cấm đoán dùng bar sb from doing; dạng quá khứ là barred.', 'We ordered fresh orange juice at the hotel bar.', NULL, 'Chúng tôi gọi nước cam vắt ở quán bar của khách sạn.', '{"wordId":"bar","ukIpa":"/bɑː/","usIpa":"/bɑr/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a place or counter where drinks, especially alcoholic drinks, are served","vi":"quán bar; quầy đồ uống"},{"pos":"n.","en":"a long narrow piece of solid material","vi":"thanh; thỏi (vật rắn dài và hẹp)"},{"pos":"v.","en":"to officially prevent someone from entering or doing something","vi":"cấm; ngăn cản chính thức"}],"examples":[{"en":"We ordered fresh orange juice at the hotel bar.","vi":"Chúng tôi gọi nước cam vắt ở quán bar của khách sạn.","audioKind":"ex"},{"en":"Sports centres should not bar residents from using essential facilities simply because they cannot afford membership fees.","vi":"Các trung tâm thể thao không nên cấm cư dân sử dụng các cơ sở vật chất thiết yếu chỉ vì họ không có khả năng chi trả phí thành viên.","audioKind":"ex2"}],"collocations":[{"en":"a hotel bar","vi":"quán bar khách sạn"},{"en":"a bar of chocolate","vi":"một thanh sô-cô-la"},{"en":"metal bars","vi":"thanh kim loại"},{"en":"bar someone from doing something","vi":"cấm ai đó làm gì"}],"wordFamily":["barred (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc biểu thị sự cấm đoán dùng bar sb from doing; dạng quá khứ là barred.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_return', 'en-a2-34', 'return', '/rɪˈtɝːn/', 'A2', 'quay trở lại; trả lại; sự trở về; sự quay lại; lợi nhuận; khoản thu về từ đầu tư hoặc hoạt động', 'v.', 'returnable (adj.), returnee (n.)', NULL, 'return đã hàm chứa ý nghĩa "quay lại", nên thông thường không dùng kèm với back.', 'Please return these library books before you go away.', NULL, 'Vui lòng trả lại những cuốn sách thư viện này trước khi bạn đi vắng.', '{"wordId":"return","ukIpa":"/rɪˈtɜːn/","usIpa":"/rɪˈtɝːn/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To go back, or give something back.","vi":"quay trở lại; trả lại"},{"pos":"n.","en":"The act of coming or going back.","vi":"sự trở về; sự quay lại"},{"pos":"n.","en":"Money or benefits gained from an investment or activity.","vi":"lợi nhuận; khoản thu về từ đầu tư hoặc hoạt động"}],"examples":[{"en":"Please return these library books before you go away.","vi":"Vui lòng trả lại những cuốn sách thư viện này trước khi bạn đi vắng.","audioKind":"ex"},{"en":"Investment in early childhood education can generate a substantial economic return by improving future employment opportunities.","vi":"Việc đầu tư vào giáo dục mầm non có thể tạo ra lợi nhuận kinh tế đáng kể bằng cách cải thiện cơ hội việc làm trong tương lai.","audioKind":"ex2"}],"collocations":[{"en":"return home","vi":"về nhà"},{"en":"return to work","vi":"quay trở lại làm việc"},{"en":"in return for","vi":"để đổi lấy"},{"en":"return on investment","vi":"lợi nhuận đầu tư"}],"wordFamily":["returnable (adj.)","returnee (n.)"],"synonyms":[],"antonyms":[],"tipVi":"return đã hàm chứa ý nghĩa \"quay lại\", nên thông thường không dùng kèm với back.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_properly', 'en-a2-34', 'properly', '/ˈprɑːpərli/', 'A2', 'một cách đúng đắn; một cách thích hợp; đầy đủ; hoàn toàn; đúng mức cần thiết', 'adv.', 'proper (adj.), improper (adj.), improperly (adv.)', 'Đồng nghĩa: correctly, appropriately · Trái nghĩa: incorrectly, improperly', 'Dùng properly để bổ nghĩa cho động từ; dùng proper để bổ nghĩa cho danh từ.', 'The kitchen door will not close properly in winter.', NULL, 'Cửa nhà bếp sẽ không thể đóng kín vào mùa đông.', '{"wordId":"properly","ukIpa":"/ˈprɒpəli/","usIpa":"/ˈprɑːpərli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"In the correct or suitable way.","vi":"một cách đúng đắn; một cách thích hợp"},{"pos":"adv.","en":"Completely or to the degree that is needed.","vi":"đầy đủ; hoàn toàn; đúng mức cần thiết"}],"examples":[{"en":"The kitchen door will not close properly in winter.","vi":"Cửa nhà bếp sẽ không thể đóng kín vào mùa đông.","audioKind":"ex"},{"en":"Public recycling schemes are more effective when residents understand how to sort household waste properly.","vi":"Các chương trình tái chế công cộng sẽ hiệu quả hơn khi cư dân hiểu cách phân loại rác thải sinh hoạt đúng cách.","audioKind":"ex2"}],"collocations":[{"en":"function properly","vi":"hoạt động bình thường"},{"en":"behave properly","vi":"cư xử đúng mực"},{"en":"properly trained","vi":"được đào tạo bài bản"},{"en":"properly equipped","vi":"được trang bị đầy đủ"}],"wordFamily":["proper (adj.)","improper (adj.)","improperly (adv.)"],"synonyms":["correctly","appropriately"],"antonyms":["incorrectly","improperly"],"tipVi":"Dùng properly để bổ nghĩa cho động từ; dùng proper để bổ nghĩa cho danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pork', 'en-a2-34', 'pork', '/pɔːrk/', 'A2', 'thịt lợn', 'n.', NULL, NULL, 'pork là danh từ không đếm được chỉ thịt; con lợn sống gọi là pig.', 'We cooked the pork slowly with apples and onions.', NULL, 'Chúng tôi nấu chậm thịt lợn cùng táo và hành tây.', '{"wordId":"pork","ukIpa":"/pɔːk/","usIpa":"/pɔːrk/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Meat from a pig, used as food.","vi":"thịt lợn"}],"examples":[{"en":"We cooked the pork slowly with apples and onions.","vi":"Chúng tôi nấu chậm thịt lợn cùng táo và hành tây.","audioKind":"ex"},{"en":"Clear food labelling helps consumers identify products containing pork and make choices that suit their dietary requirements.","vi":"Nhãn mác thực phẩm rõ ràng giúp người tiêu dùng nhận biết các sản phẩm chứa thịt lợn và đưa ra lựa chọn phù hợp với nhu cầu ăn uống của họ.","audioKind":"ex2"}],"collocations":[{"en":"roast pork","vi":"thịt lợn quay"},{"en":"pork chop","vi":"sườn lợn"},{"en":"minced pork","vi":"thịt lợn xay"},{"en":"pork belly","vi":"thịt ba chỉ lợn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"pork là danh từ không đếm được chỉ thịt; con lợn sống gọi là pig.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_case', 'en-a2-34', 'case', '/keɪs/', 'A2', 'trường hợp; ví dụ; căn bệnh; hộp; vỏ; túi đựng; vụ án; lý lẽ; luận điểm', 'n.', NULL, NULL, 'in case theo sau là mệnh đề; in case of theo sau là danh từ.', 'Take an umbrella in case it rains later.', NULL, 'Mang theo một chiếc ô phòng khi trời mưa lát nữa nhé.', '{"wordId":"case","ukIpa":"/keɪs/","usIpa":"/keɪs/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A particular situation or example, including an instance of illness.","vi":"trường hợp; ví dụ; căn bệnh"},{"pos":"n.","en":"A container that holds or protects something.","vi":"hộp; vỏ; túi đựng"},{"pos":"n.","en":"A legal matter or arguments supporting a particular position.","vi":"vụ án; lý lẽ; luận điểm"}],"examples":[{"en":"Take an umbrella in case it rains later.","vi":"Mang theo một chiếc ô phòng khi trời mưa lát nữa nhé.","audioKind":"ex"},{"en":"In many cases, investing in preventive healthcare is more cost-effective than treating diseases after they develop.","vi":"Trong nhiều trường hợp, đầu tư vào y tế dự phòng mang lại hiệu quả chi phí cao hơn so với việc điều trị bệnh sau khi chúng đã phát triển.","audioKind":"ex2"}],"collocations":[{"en":"in some cases","vi":"trong một số trường hợp"},{"en":"in case of emergency","vi":"trong trường hợp khẩn cấp"},{"en":"a strong case for","vi":"lập luận vững chắc cho"},{"en":"a phone case","vi":"ốp điện thoại"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"in case theo sau là mệnh đề; in case of theo sau là danh từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pepper', 'en-a2-34', 'pepper', '/ˈpepər/', 'A2', 'hạt tiêu; bột tiêu; ớt ngọt; ớt; làm rải rác; rải đầy', 'n.', 'peppery (adj.)', NULL, 'Hạt tiêu là danh từ không đếm được; khi chỉ một quả ớt, dùng a pepper.', 'Could you pass me the pepper for my soup?', NULL, 'Bạn có thể đưa hộ tôi lọ tiêu để tôi cho vào súp không?', '{"wordId":"pepper","ukIpa":"/ˈpepə/","usIpa":"/ˈpepər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A spice used to give food a hot flavour.","vi":"hạt tiêu; bột tiêu"},{"pos":"n.","en":"A hollow vegetable that can taste sweet or hot.","vi":"ớt ngọt; ớt"},{"pos":"v.","en":"To cover or fill something with many small things.","vi":"làm rải rác; rải đầy"}],"examples":[{"en":"Could you pass me the pepper for my soup?","vi":"Bạn có thể đưa hộ tôi lọ tiêu để tôi cho vào súp không?","audioKind":"ex"},{"en":"Farmers can grow peppers in greenhouses to maintain a reliable food supply throughout the year.","vi":"Nông dân có thể trồng ớt trong nhà kính để duy trì nguồn cung cấp thực phẩm ổn định quanh năm.","audioKind":"ex2"}],"collocations":[{"en":"black pepper","vi":"tiêu đen"},{"en":"red pepper","vi":"ớt đỏ"},{"en":"pepper something with examples","vi":"làm phong phú cái gì bằng nhiều ví dụ"}],"wordFamily":["peppery (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Hạt tiêu là danh từ không đếm được; khi chỉ một quả ớt, dùng a pepper.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_allow', 'en-a2-34', 'allow', '/əˈlaʊ/', 'A2', 'cho phép; chuẩn y; làm cho có thể; dành ra; dự trù', 'v.', 'allowance (n.), allowable (adj.), disallow (v.)', 'Đồng nghĩa: permit, let · Trái nghĩa: forbid, prohibit', 'Cấu trúc dùng allow sb to do; khi không có tân ngữ, dùng allow doing.', 'The library allows visitors to borrow five books at once.', NULL, 'Thư viện cho phép độc giả mượn năm cuốn sách cùng một lúc.', '{"wordId":"allow","ukIpa":"/əˈlaʊ/","usIpa":"/əˈlaʊ/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to let someone do something","vi":"cho phép; chuẩn y"},{"pos":"v.","en":"to make something possible","vi":"làm cho có thể; cho phép"},{"pos":"v.","en":"to provide enough time or resources for something","vi":"dành ra; dự trù"}],"examples":[{"en":"The library allows visitors to borrow five books at once.","vi":"Thư viện cho phép độc giả mượn năm cuốn sách cùng một lúc.","audioKind":"ex"},{"en":"Flexible working arrangements allow employees to balance their professional responsibilities with family commitments more effectively.","vi":"Các thỏa thuận làm việc linh hoạt giúp nhân viên cân bằng trách nhiệm công việc với các nghĩa vụ gia đình một cách hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"allow someone to do something","vi":"cho phép ai đó làm gì"},{"en":"allow enough time","vi":"dành đủ thời gian"},{"en":"allow for delays","vi":"tính đến khả năng bị chậm trễ"}],"wordFamily":["allowance (n.)","allowable (adj.)","disallow (v.)"],"synonyms":["permit","let"],"antonyms":["forbid","prohibit"],"tipVi":"Cấu trúc dùng allow sb to do; khi không có tân ngữ, dùng allow doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 27, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_34_1', 'en-a2-34', 'Cách dùng “biscuit” (n.) — bánh quy giòn (cách dùng Anh-Anh)', 'chocolate biscuit  ·  a packet of biscuits  ·  biscuit tin', 'biscuit trong tiếng Anh-Anh thường tương ứng với cookie trong tiếng Anh-Mỹ; tiếng Mỹ còn chỉ loại bánh mì nhỏ mềm.', NULL, '[{"hanzi":"She dipped a biscuit into her warm tea.","pinyin":"","meaning":"Cô ấy nhúng một chiếc bánh quy vào ly trà ấm."},{"hanzi":"Replacing sugary biscuits with fresh fruit can help children develop healthier eating habits over time.","pinyin":"","meaning":"Việc thay thế các loại bánh quy nhiều đường bằng trái cây tươi có thể giúp trẻ em dần hình thành thói quen ăn uống lành mạnh hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_34_2', 'en-a2-34', 'Cách dùng “regular” (adj.) — đều đặn; thường xuyên', 'regular exercise  ·  at regular intervals  ·  a regular customer', 'regular nhấn mạnh tính quy luật hoặc thường xuyên, không đồng nghĩa với continuous (liên tục không ngừng).', 'Họ từ (Word Family): regularly (adv.), regularity (n.), irregular (adj.) | Đồng nghĩa: frequent · Trái nghĩa: irregular', '[{"hanzi":"Our dog needs regular walks to stay happy and healthy.","pinyin":"","meaning":"Chú chó của chúng tôi cần được đi dạo đều đặn để luôn vui vẻ và khỏe mạnh."},{"hanzi":"Regular exercise can reduce the risk of chronic disease and improve overall wellbeing in older adults.","pinyin":"","meaning":"Tập thể dục đều đặn có thể làm giảm nguy cơ mắc các bệnh mãn tính và cải thiện sức khỏe tổng thể ở người cao tuổi."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_34_3', 'en-a2-34', 'Cách dùng “stairs” (n.) — cầu thang', 'climb the stairs  ·  a flight of stairs  ·  take the stairs', 'stairs ở dạng số nhiều nên động từ đi kèm chia số nhiều; một đoạn cầu thang dùng a flight of stairs.', 'Họ từ (Word Family): stair (n.), staircase (n.), stairway (n.)', '[{"hanzi":"We carried the heavy suitcase up the narrow stairs.","pinyin":"","meaning":"Chúng tôi khiêng chiếc vali nặng nề đi lên cầu thang chật hẹp."},{"hanzi":"Public buildings should provide lifts alongside stairs to ensure equal access for people with limited mobility.","pinyin":"","meaning":"Các công trình công cộng nên lắp đặt thang máy bên cạnh cầu thang bộ để đảm bảo sự tiếp cận bình đẳng cho những người bị hạn chế khả năng di chuyển."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_34_4', 'en-a2-34', 'Cách dùng “candy” (n.) — kẹo', 'a piece of candy  ·  hard candy  ·  a candy bar', 'Người Mỹ thường dùng candy, trong khi người Anh hay dùng sweets; một viên/miếng kẹo dùng a piece of.', 'Đồng nghĩa: sweets', '[{"hanzi":"She offered each guest a small piece of candy.","pinyin":"","meaning":"Cô ấy mời mỗi vị khách một chiếc kẹo nhỏ."},{"hanzi":"Limiting advertisements for candy aimed at children could help families develop healthier eating habits.","pinyin":"","meaning":"Việc hạn chế quảng cáo kẹo nhắm vào trẻ em có thể giúp các gia đình hình thành thói quen ăn uống lành mạnh hơn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_34_1', 'en-a2-34', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_34_1_1', 'ten_a2_34_1', 'gram', 'Add one gram of salt and stir the soup.', 'Add one gram of salt and stir the soup.', '/ɡræm/', 'Thêm một gam muối và khuấy đều nồi súp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
