INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_34_1_1', 'en-a2-34', 'ten_a2_34_1', 'listening', 'listening', 'Add one gram of salt and stir the soup.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy nhúng một chiếc bánh quy vào ly trà ấm.","Hãy để vé của bạn vào túi áo khoác bên trái.","Thêm một gam muối và khuấy đều nồi súp.","Cô ấy mời mỗi vị khách một chiếc kẹo nhỏ."]'::jsonb, 2, 'Add one gram of salt and stir the soup. → Thêm một gam muối và khuấy đều nồi súp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_34_1_2', 'en-a2-34', 'ten_a2_34_1', 'listening', 'listening', 'There is one chocolate cookie left in the jar.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Mang theo một chiếc ô phòng khi trời mưa lát nữa nhé.","Cô ấy xỏ chiếc nhẫn bạc vào ngón tay.","Vẫn còn một chiếc bánh quy sô-cô-la trong lọ.","Vui lòng điền mã bưu chính của bạn khi bạn điền vào biểu mẫu."]'::jsonb, 2, 'There is one chocolate cookie left in the jar. → Vẫn còn một chiếc bánh quy sô-cô-la trong lọ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_34_1_3', 'en-a2-34', 'ten_a2_34_1', 'listening', 'listening', 'We found the missing kitten asleep behind the sofa.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Vẫn còn một chiếc bánh quy sô-cô-la trong lọ.","Vui lòng điền mã bưu chính của bạn khi bạn điền vào biểu mẫu.","Chúng tôi nấu chậm thịt lợn cùng táo và hành tây.","Chúng tôi tìm thấy chú mèo con bị thất lạc đang ngủ sau chiếc ghế sô-cô-la."]'::jsonb, 3, 'We found the missing kitten asleep behind the sofa. → Chúng tôi tìm thấy chú mèo con bị thất lạc đang ngủ sau chiếc ghế sô-cô-la.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
