INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_34_2_1', 'ten_a2_34_2', 'gram', 'Comparing the nutrients provided per gram can help consumers make more informed choices about packaged foods.', 'Comparing the nutrients provided per gram can help consumers make more informed choices about packaged foods.', '/ɡræm/', 'Việc so sánh các chất dinh dưỡng được cung cấp trong mỗi gam có thể giúp người tiêu dùng đưa ra lựa chọn sáng suốt hơn về các loại thực phẩm đóng gói.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_34_2_2', 'ten_a2_34_2', 'cookie', 'Websites often use cookies to remember user preferences, but some also track browsing behaviour.', 'Websites often use cookies to remember user preferences, but some also track browsing behaviour.', '/ˈkʊki/', 'Các trang web thường sử dụng cookie để ghi nhớ sở thích của người dùng, nhưng một số trang cũng theo dõi hành vi duyệt web.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_34_2_3', 'ten_a2_34_2', 'missing', 'Missing data can undermine the reliability of research findings and lead policymakers to draw inaccurate conclusions.', 'Missing data can undermine the reliability of research findings and lead policymakers to draw inaccurate conclusions.', '/ˈmɪsɪŋ/', 'Dữ liệu bị thiếu có thể làm suy giảm độ tin cậy của các kết quả nghiên cứu và khiến các nhà hoạch định chính sách đưa ra những kết luận thiếu chính xác.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_34_2_4', 'ten_a2_34_2', 'left-hand', 'Separating cyclists from vehicles in the left-hand lane could make this busy road safer for everyone.', 'Separating cyclists from vehicles in the left-hand lane could make this busy road safer for everyone.', '/ˌleft ˈhænd/', 'Việc tách người đi xe đạp ra khỏi các phương tiện ở làn đường bên trái có thể giúp con đường đông đúc này trở nên an toàn hơn cho tất cả mọi người.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_34_2_5', 'ten_a2_34_2', 'pocket', 'Pocket dictionaries remain useful for language learners when internet access is unavailable or unreliable.', 'Pocket dictionaries remain useful for language learners when internet access is unavailable or unreliable.', '/ˈpɑːkɪt/', 'Từ điển bỏ túi vẫn rất hữu ích cho người học ngôn ngữ khi không có kết nối internet hoặc mạng không ổn định.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_34_2_6', 'ten_a2_34_2', 'biscuit', 'Replacing sugary biscuits with fresh fruit can help children develop healthier eating habits over time.', 'Replacing sugary biscuits with fresh fruit can help children develop healthier eating habits over time.', '/ˈbɪskɪt/', 'Việc thay thế các loại bánh quy nhiều đường bằng trái cây tươi có thể giúp trẻ em dần hình thành thói quen ăn uống lành mạnh hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
