INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_34_2', 'en-a2-34', NULL, 'comprehensive_test', 'listening', 'There is one chocolate cookie left in the jar.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy mời mỗi vị khách một chiếc kẹo nhỏ.","Thư viện cho phép độc giả mượn năm cuốn sách cùng một lúc.","Cửa nhà bếp sẽ không thể đóng kín vào mùa đông.","Vẫn còn một chiếc bánh quy sô-cô-la trong lọ."]'::jsonb, 3, 'There is one chocolate cookie left in the jar. → Vẫn còn một chiếc bánh quy sô-cô-la trong lọ.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
