INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_34_4', 'en-a2-34', NULL, 'comprehensive_test', 'listening', 'Keep your ticket in the left-hand pocket of your jacket.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bạn có thể đưa hộ tôi lọ tiêu để tôi cho vào súp không?","Thêm một gam muối và khuấy đều nồi súp.","Hãy để vé của bạn vào túi áo khoác bên trái.","Bạn có thể cho tôi mượn chiếc ô của bạn cho đến ngày mai được không?"]'::jsonb, 2, 'Keep your ticket in the left-hand pocket of your jacket. → Hãy để vé của bạn vào túi áo khoác bên trái.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
