INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_34_18', 'en-a2-34', NULL, 'comprehensive_test', 'reading', NULL, 'Comparing the nutrients provided per gram can help consumers make more informed choices about packaged foods.', 'Dựa vào câu trên, từ “gram” có nghĩa phù hợp nhất là gì?', '["tấm thảm (trải sàn)","gam","giám đốc; thành viên hội đồng quản trị; người quản lý","sự học; quá trình học tập"]'::jsonb, 1, 'gram: gam. Dịch cả câu: Việc so sánh các chất dinh dưỡng được cung cấp trong mỗi gam có thể giúp người tiêu dùng đưa ra lựa chọn sáng suốt hơn về các loại thực phẩm đóng gói.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_34_19', 'en-a2-34', NULL, 'comprehensive_test', 'reading', NULL, 'Websites often use cookies to remember user preferences, but some also track browsing behaviour.', 'Dựa vào câu trên, từ “cookie” có nghĩa phù hợp nhất là gì?', '["bánh quy ngọt","lo lắng; hồi hộp; bồn chồn","mã bưu chính (tại Mỹ)","ngón chân"]'::jsonb, 0, 'cookie: bánh quy ngọt; tệp cookie (dữ liệu nhỏ lưu trên trình duyệt). Dịch cả câu: Các trang web thường sử dụng cookie để ghi nhớ sở thích của người dùng, nhưng một số trang cũng theo dõi hành vi duyệt web.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_34_20', 'en-a2-34', NULL, 'comprehensive_test', 'reading', NULL, 'Missing data can undermine the reliability of research findings and lead policymakers to draw inaccurate conclusions.', 'Dựa vào câu trên, từ “missing” có nghĩa phù hợp nhất là gì?', '["thất lạc; mất tích","bít tết; thịt nướng cắt lát; cá phi-lê cắt lát dày","thưa bà; thưa cô; phu nhân (cách xưng hô lịch sự)","tiếp tục"]'::jsonb, 0, 'missing: thất lạc; mất tích; thiếu; vắng mặt. Dịch cả câu: Dữ liệu bị thiếu có thể làm suy giảm độ tin cậy của các kết quả nghiên cứu và khiến các nhà hoạch định chính sách đưa ra những kết luận thiếu chính xác.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_34_21', 'en-a2-34', NULL, 'comprehensive_test', 'reading', NULL, 'Separating cyclists from vehicles in the left-hand lane could make this busy road safer for everyone.', 'Dựa vào câu trên, từ “left-hand” có nghĩa phù hợp nhất là gì?', '["thuộc bên trái; phía tay trái","tự nhiên; thiên nhiên","cháu trai (con của con trai hoặc con gái)","đồng bảng Anh (đơn vị tiền tệ chính của Vương quốc Anh)"]'::jsonb, 0, 'left-hand: thuộc bên trái; phía tay trái. Dịch cả câu: Việc tách người đi xe đạp ra khỏi các phương tiện ở làn đường bên trái có thể giúp con đường đông đúc này trở nên an toàn hơn cho tất cả mọi người.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_34_22', 'en-a2-34', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “trường hợp; ví dụ; căn bệnh”', '["case","joining","recorder","suddenly"]'::jsonb, 0, 'trường hợp; ví dụ; căn bệnh → case (/keɪs/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_34_23', 'en-a2-34', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hạt tiêu; bột tiêu”', '["cloud","president","pepper","colleague"]'::jsonb, 2, 'hạt tiêu; bột tiêu → pepper (/ˈpepər/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_34_24', 'en-a2-34', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cho phép; chuẩn y”', '["factory","earn","wallet","allow"]'::jsonb, 3, 'cho phép; chuẩn y → allow (/əˈlaʊ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-35', 'en', 'Bài 35: Đời sống hằng ngày (7) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '26 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2035, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_raise', 'en-a2-35', 'raise', '/reɪz/', 'A2', 'nâng lên; tăng lên; đưa lên; gây quỹ; quyên góp; nuôi dưỡng; nuôi nấng', 'v.', NULL, 'Đồng nghĩa: lift, increase · Trái nghĩa: lower', 'raise là ngoại động từ có tân ngữ đi kèm; rise dùng để chỉ sự tự tăng lên.', 'Please raise your hand if you need another pencil.', NULL, 'Xin hãy giơ tay lên nếu bạn cần một chiếc bút chì khác.', '{"wordId":"raise","ukIpa":"/reɪz/","usIpa":"/reɪz/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to move something higher or increase its amount or level","vi":"nâng lên; tăng lên; đưa lên"},{"pos":"v.","en":"to collect money for a particular purpose","vi":"gây quỹ; quyên góp"},{"pos":"v.","en":"to care for children or animals as they grow","vi":"nuôi dưỡng; nuôi nấng"}],"examples":[{"en":"Please raise your hand if you need another pencil.","vi":"Xin hãy giơ tay lên nếu bạn cần một chiếc bút chì khác.","audioKind":"ex"},{"en":"Community events can raise funds for conservation projects while helping residents understand local environmental challenges.","vi":"Các sự kiện cộng đồng có thể gây quỹ cho các dự án bảo tồn đồng thời giúp cư dân hiểu rõ hơn về các thách thức môi trường địa phương.","audioKind":"ex2"}],"collocations":[{"en":"raise awareness","vi":"nâng cao nhận thức"},{"en":"raise funds","vi":"gây quỹ"},{"en":"raise a child","vi":"nuôi dạy một đứa trẻ"},{"en":"raise a question","vi":"đặt ra một câu hỏi"}],"wordFamily":[],"synonyms":["lift","increase"],"antonyms":["lower"],"tipVi":"raise là ngoại động từ có tân ngữ đi kèm; rise dùng để chỉ sự tự tăng lên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_set', 'en-a2-35', 'set', '/set/', 'A2', 'đặt; thiết lập; xác định; một bộ; một tập hợp; cố định; được định sẵn', 'v.', 'setting (n.)', NULL, 'Dạng quá khứ và phân từ hai đều là set; phân từ hiện tại là setting.', 'She set the bowl gently on the kitchen table.', NULL, 'Cô ấy nhẹ nhàng đặt chiếc bát lên bàn bếp.', '{"wordId":"set","ukIpa":"/set/","usIpa":"/set/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"Put something somewhere, or establish a condition, value, or rule.","vi":"đặt; thiết lập; xác định"},{"pos":"n.","en":"A group of related things that belong together.","vi":"một bộ; một tập hợp"},{"pos":"adj.","en":"Fixed or arranged in advance.","vi":"cố định; được định sẵn"}],"examples":[{"en":"She set the bowl gently on the kitchen table.","vi":"Cô ấy nhẹ nhàng đặt chiếc bát lên bàn bếp.","audioKind":"ex"},{"en":"Governments should set clear targets for reducing air pollution and regularly assess progress towards achieving them.","vi":"Chính phủ nên đặt ra các mục tiêu rõ ràng để giảm ô nhiễm không khí và thường xuyên đánh giá tiến độ đạt được các mục tiêu đó.","audioKind":"ex2"}],"collocations":[{"en":"set a goal","vi":"đặt mục tiêu"},{"en":"set the table","vi":"dọn bàn ăn"},{"en":"a set of tools","vi":"một bộ dụng cụ"},{"en":"a set time","vi":"một thời gian cố định"}],"wordFamily":["setting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai đều là set; phân từ hiện tại là setting.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_feed', 'en-a2-35', 'feed', '/fiːd/', 'A2', 'cho ăn; ăn; thức ăn cho gia súc; thông tin cập nhật', 'v.', 'feeding (n.), feeder (n.)', NULL, 'Dạng quá khứ và phân từ hai đều là fed; feed on diễn tả nghĩa ăn... để sống.', 'Please feed the cat before you leave for school.', NULL, 'Làm ơn cho mèo ăn trước khi con đi học nhé.', '{"wordId":"feed","ukIpa":"/fiːd/","usIpa":"/fiːd/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"Give food to someone or an animal, or eat food.","vi":"cho ăn; ăn"},{"pos":"n.","en":"Food given to farm animals.","vi":"thức ăn cho gia súc"},{"pos":"n.","en":"A regularly updated stream of online content.","vi":"thông tin cập nhật"}],"examples":[{"en":"Please feed the cat before you leave for school.","vi":"Làm ơn cho mèo ăn trước khi con đi học nhé.","audioKind":"ex"},{"en":"School meal programmes help feed children whose families cannot consistently afford nutritious food.","vi":"Chương trình bữa ăn học đường giúp cung cấp thực phẩm cho trẻ em có gia đình không đủ khả năng mua thực phẩm bổ dưỡng một cách thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"feed the animals","vi":"cho động vật ăn"},{"en":"feed on insects","vi":"ăn côn trùng"},{"en":"animal feed","vi":"thức ăn chăn nuôi"},{"en":"news feed","vi":"dòng tin tức"}],"wordFamily":["feeding (n.)","feeder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng quá khứ và phân từ hai đều là fed; feed on diễn tả nghĩa ăn... để sống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pancake', 'en-a2-35', 'pancake', '/ˈpænkeɪk/', 'A2', 'bánh kếp; bánh xèo mỏng', 'n.', NULL, NULL, 'Bánh kếp kiểu Anh thường mỏng, trong khi kiểu Mỹ thường dày và xốp hơn.', 'He flipped the pancake and reached for the honey.', NULL, 'Anh ấy lật chiếc bánh kếp và với lấy hũ mật ong.', '{"wordId":"pancake","ukIpa":"/ˈpænkeɪk/","usIpa":"/ˈpænkeɪk/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A flat, round cake made by frying a liquid mixture","vi":"bánh kếp; bánh xèo mỏng"}],"examples":[{"en":"He flipped the pancake and reached for the honey.","vi":"Anh ấy lật chiếc bánh kếp và với lấy hũ mật ong.","audioKind":"ex"},{"en":"Preparing pancakes in cooking classes allows students to practise measuring ingredients and using kitchen equipment safely.","vi":"Việc chuẩn bị bánh kếp trong các lớp học nấu ăn giúp học sinh luyện tập cách đong đếm nguyên liệu và sử dụng thiết bị nhà bếp một cách an toàn.","audioKind":"ex2"}],"collocations":[{"en":"pancake batter","vi":"bột bánh kếp"},{"en":"flip a pancake","vi":"lật bánh kếp"},{"en":"a stack of pancakes","vi":"một chồng bánh kếp"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Bánh kếp kiểu Anh thường mỏng, trong khi kiểu Mỹ thường dày và xốp hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_except', 'en-a2-35', 'except', '/ɪkˈsept/', 'A2', 'trừ ra; ngoại trừ; trừ phi; chỉ là', 'prep.', 'exception (n.), exceptional (adj.), exceptionally (adv.)', 'Đồng nghĩa: excluding, apart from · Trái nghĩa: including', 'except dùng để loại trừ hoàn toàn; besides dùng để chỉ việc ngoài ra còn có thêm.', 'Everyone except my brother wanted to walk home.', NULL, 'Mọi người đều muốn đi bộ về nhà trừ anh trai tôi.', '{"wordId":"except","ukIpa":"/ɪkˈsept/","usIpa":"/ɪkˈsept/","cefr":"A2","topic":"daily","senses":[{"pos":"prep.","en":"Not including a particular person or thing.","vi":"trừ ra; ngoại trừ"},{"pos":"conj.","en":"Used to introduce a fact limiting what was just said.","vi":"trừ phi; chỉ là"}],"examples":[{"en":"Everyone except my brother wanted to walk home.","vi":"Mọi người đều muốn đi bộ về nhà trừ anh trai tôi.","audioKind":"ex"},{"en":"The proposed transport policy benefits most residents, except those living in remote rural communities.","vi":"Chính sách giao thông được đề xuất mang lại lợi ích cho hầu hết cư dân, ngoại trừ những người sống ở các vùng nông thôn hẻo lánh.","audioKind":"ex2"}],"collocations":[{"en":"except for","vi":"ngoại trừ"},{"en":"except that","vi":"trừ phi; ngoại trừ việc"},{"en":"everyone except","vi":"mọi người trừ"}],"wordFamily":["exception (n.)","exceptional (adj.)","exceptionally (adv.)"],"synonyms":["excluding","apart from"],"antonyms":["including"],"tipVi":"except dùng để loại trừ hoàn toàn; besides dùng để chỉ việc ngoài ra còn có thêm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_still', 'en-a2-35', 'still', '/stɪl/', 'A2', 'vẫn; còn; vẫn đứng yên; bất động; tuy nhiên; dù vậy', 'adv.', 'stillness (n.)', NULL, 'Khi mang nghĩa "vẫn", từ này thường đứng trước động từ thường và sau động từ to be.', 'It is nearly midnight, but my sister is still awake.', NULL, 'Đã gần nửa đêm nhưng chị tôi vẫn thức.', '{"wordId":"still","ukIpa":"/stɪl/","usIpa":"/stɪl/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"Continuing up to a particular time without stopping or changing.","vi":"vẫn; còn"},{"pos":"adj.","en":"Not moving.","vi":"vẫn đứng yên; bất động"},{"pos":"adv.","en":"Despite what has just been said.","vi":"tuy nhiên; dù vậy"}],"examples":[{"en":"It is nearly midnight, but my sister is still awake.","vi":"Đã gần nửa đêm nhưng chị tôi vẫn thức.","audioKind":"ex"},{"en":"Despite improvements in public transport, many commuters still rely on private cars because services remain unreliable in rural areas.","vi":"Mặc dù hệ thống giao thông công cộng đã được cải thiện, nhiều người đi làm vẫn phụ thuộc vào xe cá nhân vì dịch vụ ở các vùng nông thôn vẫn chưa đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"still waiting","vi":"vẫn đang chờ"},{"en":"stand still","vi":"đứng im"},{"en":"keep still","vi":"giữ nguyên trạng thái không đổi"},{"en":"still water","vi":"nước lặng"}],"wordFamily":["stillness (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi mang nghĩa \"vẫn\", từ này thường đứng trước động từ thường và sau động từ to be.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fresh', 'en-a2-35', 'fresh', '/freʃ/', 'A2', 'tươi; mới hái; trong lành; mát mẻ; mới mẻ; khác trước', 'adj.', 'freshness (n.), freshly (adv.), freshen (v.)', 'Trái nghĩa: stale', 'fresh water có nghĩa là nước ngọt; fresh air có nghĩa là không khí trong lành.', 'I bought fresh strawberries from the market this morning.', NULL, 'Sáng nay tôi mua mấy quả dâu tây tươi ở chợ.', '{"wordId":"fresh","ukIpa":"/freʃ/","usIpa":"/freʃ/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Recently produced or picked, and not preserved or stale.","vi":"tươi; mới hái"},{"pos":"adj.","en":"Clean, cool, and pleasant, especially when describing air.","vi":"trong lành; mát mẻ"},{"pos":"adj.","en":"New or different from what existed or was used before.","vi":"mới mẻ; khác trước"}],"examples":[{"en":"I bought fresh strawberries from the market this morning.","vi":"Sáng nay tôi mua mấy quả dâu tây tươi ở chợ.","audioKind":"ex"},{"en":"Access to fresh fruit and vegetables is essential for improving diets in low-income urban communities.","vi":"Việc tiếp cận rau củ và trái cây tươi là điều cần thiết để cải thiện chế độ dinh dưỡng ở các cộng đồng đô thị có thu nhập thấp.","audioKind":"ex2"}],"collocations":[{"en":"fresh produce","vi":"nông sản tươi"},{"en":"fresh air","vi":"không khí trong lành"},{"en":"a fresh start","vi":"một khởi đầu mới"},{"en":"fresh water","vi":"nước ngọt"}],"wordFamily":["freshness (n.)","freshly (adv.)","freshen (v.)"],"synonyms":[],"antonyms":["stale"],"tipVi":"fresh water có nghĩa là nước ngọt; fresh air có nghĩa là không khí trong lành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cotton', 'en-a2-35', 'cotton', '/ˈkɑːtən/', 'A2', 'bông (thực vật); vải bông; sợi bông', 'n.', NULL, NULL, 'Thường là danh từ không đếm được; trong cotton shirt thì cotton đóng vai trò là danh từ làm định ngữ.', 'This cotton shirt feels soft even after many washes.', NULL, 'Chiếc áo sơ mi bằng vải bông này vẫn mềm mại ngay cả sau nhiều lần giặt.', '{"wordId":"cotton","ukIpa":"/ˈkɒtən/","usIpa":"/ˈkɑːtən/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Soft white plant fibres used to make thread and fabric.","vi":"bông (thực vật)"},{"pos":"n.","en":"Fabric or thread made from cotton fibres.","vi":"vải bông; sợi bông"}],"examples":[{"en":"This cotton shirt feels soft even after many washes.","vi":"Chiếc áo sơ mi bằng vải bông này vẫn mềm mại ngay cả sau nhiều lần giặt.","audioKind":"ex"},{"en":"Cotton production can place considerable pressure on water supplies, particularly in regions with limited rainfall.","vi":"Sản xuất bông có thể gây áp lực đáng kể lên nguồn cung cấp nước, đặc biệt là ở những vùng có lượng mưa hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"organic cotton","vi":"bông hữu cơ"},{"en":"cotton fabric","vi":"vải cotton"},{"en":"cotton wool","vi":"bông y tế"},{"en":"cotton industry","vi":"ngành công nghiệp dệt bông"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường là danh từ không đếm được; trong cotton shirt thì cotton đóng vai trò là danh từ làm định ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_plus', 'en-a2-35', 'plus', '/plʌs/', 'A2', 'cộng với; thêm vào; ưu điểm; điểm cộng; dương; trên không', 'prep.', NULL, 'Trái nghĩa: minus', 'Khi plus đóng vai trò là danh từ chỉ ưu điểm thì là danh từ đếm được, ví dụ như a big plus.', 'The room costs sixty pounds plus breakfast each night.', NULL, 'Căn phòng có giá sáu mươi bảng cộng với tiền bữa sáng mỗi đêm.', '{"wordId":"plus","ukIpa":"/plʌs/","usIpa":"/plʌs/","cefr":"A2","topic":"daily","senses":[{"pos":"prep.","en":"With something added to an amount or group.","vi":"cộng với; thêm vào"},{"pos":"n.","en":"An advantage or positive feature.","vi":"ưu điểm; điểm cộng"},{"pos":"adj.","en":"Greater than zero, especially when describing temperatures.","vi":"dương; trên không"}],"examples":[{"en":"The room costs sixty pounds plus breakfast each night.","vi":"Căn phòng có giá sáu mươi bảng cộng với tiền bữa sáng mỗi đêm.","audioKind":"ex"},{"en":"Affordable housing plus reliable public transport can make expanding cities more accessible to workers on modest incomes.","vi":"Nhà ở giá cả phải chăng cộng với giao thông công cộng đáng tin cậy có thể giúp các thành phố đang mở rộng trở nên dễ tiếp cận hơn đối với những người lao động có thu nhập khiêm tốn.","audioKind":"ex2"}],"collocations":[{"en":"plus tax","vi":"chưa bao gồm thuế"},{"en":"a big plus","vi":"một ưu điểm lớn"},{"en":"plus ten degrees","vi":"mười độ trên không"}],"wordFamily":[],"synonyms":[],"antonyms":["minus"],"tipVi":"Khi plus đóng vai trò là danh từ chỉ ưu điểm thì là danh từ đếm được, ví dụ như a big plus.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kilogramme', 'en-a2-35', 'kilogramme', '/ˈkɪləɡræm/', 'A2', 'ki-lô-gam; ký', 'n.', NULL, 'Đồng nghĩa: kilogram, kilo', 'Là cách viết theo kiểu Anh; dạng kilogram phổ biến hơn và ký hiệu kg không thêm s.', 'We bought a kilogramme of apples at the market.', NULL, 'Chúng tôi đã mua một ký táo ở ngoài chợ.', '{"wordId":"kilogramme","ukIpa":"/ˈkɪləɡræm/","usIpa":"/ˈkɪləɡræm/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A unit of mass equal to one thousand grams.","vi":"ki-lô-gam; ký"}],"examples":[{"en":"We bought a kilogramme of apples at the market.","vi":"Chúng tôi đã mua một ký táo ở ngoài chợ.","audioKind":"ex"},{"en":"Producing a kilogramme of beef generally requires more water than producing the same weight of vegetables.","vi":"Việc sản xuất một ký thịt bò nhìn chung đòi hỏi nhiều nước hơn so với việc sản xuất cùng một trọng lượng rau củ.","audioKind":"ex2"}],"collocations":[{"en":"a kilogramme of rice","vi":"một ký gạo"},{"en":"half a kilogramme","vi":"nửa ký"},{"en":"per kilogramme","vi":"mỗi kilôgam"}],"wordFamily":[],"synonyms":["kilogram","kilo"],"antonyms":[],"tipVi":"Là cách viết theo kiểu Anh; dạng kilogram phổ biến hơn và ký hiệu kg không thêm s.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_onion', 'en-a2-35', 'onion', '/ˈʌnjən/', 'A2', 'củ hành tây', 'n.', NULL, NULL, 'Bắt đầu bằng nguyên âm, đứng trước số ít dùng an: an onion.', 'Chopping this onion is making my eyes water again.', NULL, 'Thái củ hành tây này lại khiến mắt tôi cay xè.', '{"wordId":"onion","ukIpa":"/ˈʌnjən/","usIpa":"/ˈʌnjən/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a round vegetable with layers and a strong smell","vi":"củ hành tây"}],"examples":[{"en":"Chopping this onion is making my eyes water again.","vi":"Thái củ hành tây này lại khiến mắt tôi cay xè.","audioKind":"ex"},{"en":"Growing onions and other vegetables locally can shorten supply chains and provide communities with fresher produce.","vi":"Việc trồng hành tây và các loại rau củ tại địa phương có thể rút ngắn chuỗi cung ứng và cung cấp cho cộng đồng nông sản tươi ngon hơn.","audioKind":"ex2"}],"collocations":[{"en":"chop an onion","vi":"thái hành tây"},{"en":"peel an onion","vi":"bóc vỏ hành tây"},{"en":"onion rings","vi":"hành tây chiên vòng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Bắt đầu bằng nguyên âm, đứng trước số ít dùng an: an onion.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thin', 'en-a2-35', 'thin', '/θɪn/', 'A2', 'mỏng; mảnh; gầy; ốm; làm loãng; làm thưa; thưa dần', 'adj.', 'thinly (adv.), thinness (n.)', 'Trái nghĩa: thick, fat', 'Khi nói về vóc dáng, thin không hẳn mang nghĩa khen; slim thường mang hàm ý khen ngợi.', 'I wore a thin jacket and felt cold outside.', NULL, 'Tôi mặc chiếc áo khoác mỏng và thấy lạnh khi ra ngoài.', '{"wordId":"thin","ukIpa":"/θɪn/","usIpa":"/θɪn/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Having little distance between opposite sides or surfaces.","vi":"mỏng; mảnh"},{"pos":"adj.","en":"Having little body fat or flesh.","vi":"gầy; ốm"},{"pos":"v.","en":"To make or become less dense, thick, or numerous.","vi":"làm loãng; làm thưa; thưa dần"}],"examples":[{"en":"I wore a thin jacket and felt cold outside.","vi":"Tôi mặc chiếc áo khoác mỏng và thấy lạnh khi ra ngoài.","audioKind":"ex"},{"en":"Thin layers of insulation can improve energy efficiency without significantly reducing the usable space inside buildings.","vi":"Các lớp vật liệu cách nhiệt mỏng có thể nâng cao hiệu quả sử dụng năng lượng mà không làm giảm đáng kể không gian sử dụng bên trong các tòa nhà.","audioKind":"ex2"}],"collocations":[{"en":"a thin layer","vi":"một lớp mỏng"},{"en":"thin slices","vi":"thái lát mỏng"},{"en":"thin air","vi":"khí trời loãng"},{"en":"thin out","vi":"làm thưa ra; thưa dần"}],"wordFamily":["thinly (adv.)","thinness (n.)"],"synonyms":[],"antonyms":["thick","fat"],"tipVi":"Khi nói về vóc dáng, thin không hẳn mang nghĩa khen; slim thường mang hàm ý khen ngợi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_straight', 'en-a2-35', 'straight', '/streɪt/', 'A2', 'thẳng; không cong; trực tiếp không dừng nghỉ; thành thật; thẳng thắn', 'adj.', 'straighten (v), straightness (n)', 'Trái nghĩa: curved, bent', 'Bản thân straight đã đóng vai trò là trạng từ, không cần thêm hậu tố -ly.', 'Use a ruler to draw a straight line.', NULL, 'Hãy dùng thước kẻ để vẽ một đường thẳng.', '{"wordId":"straight","ukIpa":"/streɪt/","usIpa":"/streɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"not curved or bent","vi":"thẳng; không cong"},{"pos":"adv.","en":"directly, without turning or stopping","vi":"thẳng; trực tiếp không dừng nghỉ"},{"pos":"adj.","en":"honest and clear rather than hiding the truth","vi":"thành thật; thẳng thắn"}],"examples":[{"en":"Use a ruler to draw a straight line.","vi":"Hãy dùng thước kẻ để vẽ một đường thẳng.","audioKind":"ex"},{"en":"Building straight roads across mountainous regions can be expensive and may damage natural habitats.","vi":"Việc xây dựng những con đường thẳng băng qua các vùng núi có thể tốn kém và gây tổn hại đến môi trường sống tự nhiên.","audioKind":"ex2"}],"collocations":[{"en":"a straight line","vi":"một đường thẳng"},{"en":"go straight ahead","vi":"đi thẳng về phía trước"},{"en":"a straight answer","vi":"một câu trả lời thẳng thắn"}],"wordFamily":["straighten (v)","straightness (n)"],"synonyms":[],"antonyms":["curved","bent"],"tipVi":"Bản thân straight đã đóng vai trò là trạng từ, không cần thêm hậu tố -ly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_housework', 'en-a2-35', 'housework', '/ˈhaʊswɝːk/', 'A2', 'công việc nhà; việc nhà', 'n.', 'house (n.)', 'Đồng nghĩa: household chores', 'Là danh từ không đếm được, không nói a housework; làm việc nhà dùng động từ do.', 'We share the housework so nobody spends Sunday cleaning alone.', NULL, 'Chúng tôi cùng chia sẻ việc nhà để không ai phải một mình dọn dẹp vào ngày Chủ nhật.', '{"wordId":"housework","ukIpa":"/ˈhaʊswɜːk/","usIpa":"/ˈhaʊswɝːk/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Work done to keep a home clean and tidy.","vi":"công việc nhà; việc nhà"}],"examples":[{"en":"We share the housework so nobody spends Sunday cleaning alone.","vi":"Chúng tôi cùng chia sẻ việc nhà để không ai phải một mình dọn dẹp vào ngày Chủ nhật.","audioKind":"ex"},{"en":"Sharing housework fairly allows family members to balance paid employment with responsibilities at home more effectively.","vi":"Việc phân chia công việc nhà một cách công bằng giúp các thành viên trong gia đình cân bằng hiệu quả hơn giữa việc làm có lương và trách nhiệm tại gia đình.","audioKind":"ex2"}],"collocations":[{"en":"do the housework","vi":"làm việc nhà"},{"en":"share the housework","vi":"chia sẻ việc nhà"},{"en":"household chores","vi":"việc vặt trong nhà"}],"wordFamily":["house (n.)"],"synonyms":["household chores"],"antonyms":[],"tipVi":"Là danh từ không đếm được, không nói a housework; làm việc nhà dùng động từ do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_none', 'en-a2-35', 'none', '/nʌn/', 'A2', 'không một chút nào; không ai, không vật gì; hoàn toàn không', 'pron.', NULL, NULL, 'none có thể đứng độc lập; khi bổ nghĩa cho danh từ, hãy dùng no, ví dụ no books.', 'I checked the biscuit tin, but there were none left.', NULL, 'Tôi đã kiểm tra hộp đựng bánh quy nhưng chẳng còn cái nào.', '{"wordId":"none","ukIpa":"/nʌn/","usIpa":"/nʌn/","cefr":"A2","topic":"daily","senses":[{"pos":"pron.","en":"not any of the people or things being considered","vi":"không một chút nào; không ai, không vật gì"},{"pos":"adv.","en":"not at all, used before certain comparative expressions","vi":"hoàn toàn không"}],"examples":[{"en":"I checked the biscuit tin, but there were none left.","vi":"Tôi đã kiểm tra hộp đựng bánh quy nhưng chẳng còn cái nào.","audioKind":"ex"},{"en":"Although several solutions were proposed, none addressed the underlying causes of inequality in access to education.","vi":"Mặc dù có nhiều giải pháp được đề xuất, nhưng không giải pháp nào giải quyết được nguyên nhân gốc rễ của sự bất bình đẳng trong tiếp cận giáo dục.","audioKind":"ex2"}],"collocations":[{"en":"none of","vi":"không một ai trong số"},{"en":"none at all","vi":"hoàn toàn không có"},{"en":"none the wiser","vi":"vẫn mù tịt không biết gì"},{"en":"none other than","vi":"chính là; không ai khác ngoài"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"none có thể đứng độc lập; khi bổ nghĩa cho danh từ, hãy dùng no, ví dụ no books.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pleasant', 'en-a2-35', 'pleasant', '/ˈplezənt/', 'A2', 'dễ chịu; thoải mái; thân thiện; nhã nhặn', 'adj.', 'pleasantly (adv.), pleasantness (n.), unpleasant (adj.)', 'Đồng nghĩa: enjoyable, agreeable · Trái nghĩa: unpleasant', 'pleasant dùng để miêu tả sự vật gây cảm giác dễ chịu; pleased dùng để chỉ cảm giác vui mừng của con người.', 'We enjoyed a pleasant walk beside the river.', NULL, 'Chúng tôi đã có một buổi tản bộ thú vị dọc bờ sông.', '{"wordId":"pleasant","ukIpa":"/ˈplezənt/","usIpa":"/ˈplezənt/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Enjoyable or comfortable to experience.","vi":"dễ chịu; thoải mái"},{"pos":"adj.","en":"Friendly and polite towards other people.","vi":"thân thiện; nhã nhặn"}],"examples":[{"en":"We enjoyed a pleasant walk beside the river.","vi":"Chúng tôi đã có một buổi tản bộ thú vị dọc bờ sông.","audioKind":"ex"},{"en":"Public gardens provide pleasant spaces where residents can exercise, socialise, and escape the pressures of urban life.","vi":"Các khu vườn công cộng mang lại không gian dễ chịu để cư dân tập thể dục, giao lưu và rũ bỏ áp lực của cuộc sống đô thị.","audioKind":"ex2"}],"collocations":[{"en":"pleasant weather","vi":"thời tiết dễ chịu"},{"en":"a pleasant surprise","vi":"một bất ngờ thú vị"},{"en":"a pleasant atmosphere","vi":"bầuok không khí dễ chịu"}],"wordFamily":["pleasantly (adv.)","pleasantness (n.)","unpleasant (adj.)"],"synonyms":["enjoyable","agreeable"],"antonyms":["unpleasant"],"tipVi":"pleasant dùng để miêu tả sự vật gây cảm giác dễ chịu; pleased dùng để chỉ cảm giác vui mừng của con người.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_borrow', 'en-a2-35', 'borrow', '/ˈbɑːroʊ/', 'A2', 'mượn; vay; dùng ké; vay mượn (ý tưởng, từ ngữ)', 'v.', 'borrower (n.), borrowing (n.)', 'Trái nghĩa: lend', 'borrow là mượn vào, lend là cho mượn; mượn từ ai dùng cấu trúc borrow from.', 'Could I borrow your umbrella until tomorrow morning?', NULL, 'Tôi có thể mượn ô của bạn đến sáng mai được không?', '{"wordId":"borrow","ukIpa":"/ˈbɒrəʊ/","usIpa":"/ˈbɑːroʊ/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To take and use something with permission, then return it.","vi":"mượn; vay"},{"pos":"v.","en":"To use an idea or word from another source.","vi":"dùng ké; vay mượn (ý tưởng, từ ngữ)"}],"examples":[{"en":"Could I borrow your umbrella until tomorrow morning?","vi":"Tôi có thể mượn ô của bạn đến sáng mai được không?","audioKind":"ex"},{"en":"Many languages borrow words from others as international trade and cultural exchange bring communities closer.","vi":"Nhiều ngôn ngữ mượn từ vựng từ các ngôn ngữ khác khi thương mại quốc tế và giao lưu văn hóa kéo các cộng đồng xích lại gần nhau hơn.","audioKind":"ex2"}],"collocations":[{"en":"borrow from","vi":"mượn từ"},{"en":"borrow money","vi":"vay tiền"},{"en":"borrow a book","vi":"mượn sách"},{"en":"borrow heavily","vi":"vay nợ nhiều"}],"wordFamily":["borrower (n.)","borrowing (n.)"],"synonyms":[],"antonyms":["lend"],"tipVi":"borrow là mượn vào, lend là cho mượn; mượn từ ai dùng cấu trúc borrow from.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shelf', 'en-a2-35', 'shelf', '/ʃelf/', 'A2', 'kệ; giá; tấm ván đặt đồ; thềm lục địa; vỉa đá ngầm', 'n.', 'shelve (v.), shelving (n.)', NULL, 'Dạng số nhiều là shelves; shelf life dùng để chỉ hạn sử dụng (của sản phẩm).', 'Put the clean cups on the shelf above the sink.', NULL, 'Hãy đặt những chiếc cốc sạch lên kệ ở phía trên bồn rửa bát.', '{"wordId":"shelf","ukIpa":"/ʃelf/","usIpa":"/ʃelf/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A flat board used to support or store things.","vi":"kệ; giá; tấm ván đặt đồ"},{"pos":"n.","en":"A broad, relatively flat area of rock or seabed.","vi":"thềm lục địa; vỉa đá ngầm"}],"examples":[{"en":"Put the clean cups on the shelf above the sink.","vi":"Hãy đặt những chiếc cốc sạch lên kệ ở phía trên bồn rửa bát.","audioKind":"ex"},{"en":"Placing healthy snacks on shelves at eye level may encourage shoppers to make more nutritious food choices.","vi":"Việc đặt các món ăn vặt lành mạnh lên các kệ vừa tầm mắt có thể khuyến khích người mua sắm lựa chọn nhiều thực phẩm bổ dưỡng hơn.","audioKind":"ex2"}],"collocations":[{"en":"top shelf","vi":"kệ trên cùng"},{"en":"shelf space","vi":"không gian trưng bày"},{"en":"shelf life","vi":"hạn sử dụng"},{"en":"continental shelf","vi":"thềm lục địa"}],"wordFamily":["shelve (v.)","shelving (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là shelves; shelf life dùng để chỉ hạn sử dụng (của sản phẩm).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anyway', 'en-a2-35', 'anyway', '/ˈeniweɪ/', 'A2', 'dù sao đi nữa; bất chấp thế nào; dù sao thì; nói tóm lại', 'adv.', NULL, 'Đồng nghĩa: anyhow', 'anyway là trạng từ; any way chỉ bất kỳ cách nào.', 'It started raining, but we went for a walk anyway.', NULL, 'Trời bắt đầu mưa, nhưng chúng tôi vẫn đi dạo dù sao đi nữa.', '{"wordId":"anyway","ukIpa":"/ˈeniweɪ/","usIpa":"/ˈeniweɪ/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"Despite what has happened or what someone has said.","vi":"dù sao đi nữa; bất chấp thế nào"},{"pos":"adv.","en":"Used to add a reason or return to the main subject.","vi":"dù sao thì; nói tóm lại"}],"examples":[{"en":"It started raining, but we went for a walk anyway.","vi":"Trời bắt đầu mưa, nhưng chúng tôi vẫn đi dạo dù sao đi nữa.","audioKind":"ex"},{"en":"Some residents oppose the new railway, but the government intends to proceed anyway because of its economic benefits.","vi":"Một số cư dân phản đối tuyến đường sắt mới, nhưng chính phủ vẫn có ý định tiến hành dự án vì những lợi ích kinh tế của nó.","audioKind":"ex2"}],"collocations":[{"en":"do it anyway","vi":"dù sao vẫn làm"},{"en":"go anyway","vi":"dù sao vẫn đi"},{"en":"thanks anyway","vi":"dù sao cũng cảm ơn"}],"wordFamily":[],"synonyms":["anyhow"],"antonyms":[],"tipVi":"anyway là trạng từ; any way chỉ bất kỳ cách nào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lipstick', 'en-a2-35', 'lipstick', '/ˈlɪpstɪk/', 'A2', 'son môi', 'n.', NULL, NULL, 'Danh từ không đếm được ở nghĩa vật chất; một thỏi son dùng a tube of lipstick.', 'She put on red lipstick before leaving the house.', NULL, 'Cô ấy thoa son đỏ trước khi rời khỏi nhà.', '{"wordId":"lipstick","ukIpa":"/ˈlɪpstɪk/","usIpa":"/ˈlɪpstɪk/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A cosmetic applied to lips to give them colour.","vi":"son môi"}],"examples":[{"en":"She put on red lipstick before leaving the house.","vi":"Cô ấy thoa son đỏ trước khi rời khỏi nhà.","audioKind":"ex"},{"en":"Cosmetics companies are developing refillable lipstick containers to reduce packaging waste and respond to environmental concerns.","vi":"Các công ty mỹ phẩm đang phát triển các loại vỏ son môi có thể nạp lại lõi để giảm rác thải bao bì và đáp ứng các mối quan tâm về môi trường.","audioKind":"ex2"}],"collocations":[{"en":"wear lipstick","vi":"đánh son môi"},{"en":"apply lipstick","vi":"thoa son môi"},{"en":"a tube of lipstick","vi":"một thỏi son môi"},{"en":"lipstick stain","vi":"vết son môi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ không đếm được ở nghĩa vật chất; một thỏi son dùng a tube of lipstick.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cooker', 'en-a2-35', 'cooker', '/ˈkʊkər/', 'A2', 'lò nấu; bếp nấu', 'n.', 'cook (v.), cooking (n.)', NULL, 'Trong tiếng Anh-Anh cooker chỉ bếp/lò nấu, tiếng Anh-Mỹ thường dùng stove; đầu bếp là cook.', 'The soup is bubbling in a pot on the cooker.', NULL, 'Món súp đang sôi sùng sục trong một cái nồi trên bếp.', '{"wordId":"cooker","ukIpa":"/ˈkʊkə/","usIpa":"/ˈkʊkər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"an appliance used for cooking food","vi":"lò nấu; bếp nấu"}],"examples":[{"en":"The soup is bubbling in a pot on the cooker.","vi":"Món súp đang sôi sùng sục trong một cái nồi trên bếp.","audioKind":"ex"},{"en":"Replacing an inefficient cooker with a modern appliance can reduce household energy consumption over time.","vi":"Việc thay thế một chiếc bếp hiệu suất kém bằng thiết bị hiện đại có thể làm giảm lượng năng lượng tiêu thụ của hộ gia đình theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"gas cooker","vi":"bếp ga"},{"en":"electric cooker","vi":"bếp điện"},{"en":"pressure cooker","vi":"nồi áp suất"},{"en":"rice cooker","vi":"nồi cơm điện"}],"wordFamily":["cook (v.)","cooking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh cooker chỉ bếp/lò nấu, tiếng Anh-Mỹ thường dùng stove; đầu bếp là cook.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_clothing', 'en-a2-35', 'clothing', '/ˈkloʊðɪŋ/', 'A2', 'quần áo; trang phục', 'n.', 'clothe (v.), clothes (n.), clothed (adj.)', 'Đồng nghĩa: clothes, garments', 'clothing là danh từ không đếm được; một món đồ quần áo dùng an item of clothing.', 'Pack some warm clothing for our weekend camping trip.', NULL, 'Hãy chuẩn bị một ít quần áo ấm cho chuyến đi cắm trại cuối tuần của chúng ta.', '{"wordId":"clothing","ukIpa":"/ˈkləʊðɪŋ/","usIpa":"/ˈkloʊðɪŋ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Things people wear to cover or protect their bodies.","vi":"quần áo; trang phục"}],"examples":[{"en":"Pack some warm clothing for our weekend camping trip.","vi":"Hãy chuẩn bị một ít quần áo ấm cho chuyến đi cắm trại cuối tuần của chúng ta.","audioKind":"ex"},{"en":"The clothing industry can reduce its environmental impact by using recycled materials and designing products that last longer.","vi":"Ngành công nghiệp thời trang có thể giảm thiểu tác động đến môi trường bằng cách sử dụng vật liệu tái chế và thiết kế các sản phẩm có độ bền cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"warm clothing","vi":"quần áo ấm"},{"en":"protective clothing","vi":"quần áo bảo hộ"},{"en":"an item of clothing","vi":"một món đồ quần áo"},{"en":"clothing industry","vi":"ngành công nghiệp may mặc"}],"wordFamily":["clothe (v.)","clothes (n.)","clothed (adj.)"],"synonyms":["clothes","garments"],"antonyms":[],"tipVi":"clothing là danh từ không đếm được; một món đồ quần áo dùng an item of clothing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_height', 'en-a2-35', 'height', '/haɪt/', 'A2', 'chiều cao; chiều cao của ai/cái gì; độ cao so với mặt đất hoặc mặt biển; thời kỳ đỉnh cao; giai đoạn thịnh vượng nhất', 'n.', 'high (adj.), heighten (v.)', NULL, 'height là danh từ; tính từ chỉ người cao dùng tall, vật cao dùng high.', 'She adjusted the chair''s height so her feet reached the floor.', NULL, 'Cô ấy điều chỉnh chiều cao của chiếc ghế sao cho chân cô ấy chạm tới mặt đất.', '{"wordId":"height","ukIpa":"/haɪt/","usIpa":"/haɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"the measurement of how tall someone or something is","vi":"chiều cao; chiều cao của ai/cái gì"},{"pos":"n.","en":"the distance of something above the ground or sea","vi":"độ cao so với mặt đất hoặc mặt biển"},{"pos":"n.","en":"the time when something is strongest or most successful","vi":"thời kỳ đỉnh cao; giai đoạn thịnh vượng nhất"}],"examples":[{"en":"She adjusted the chair''s height so her feet reached the floor.","vi":"Cô ấy điều chỉnh chiều cao của chiếc ghế sao cho chân cô ấy chạm tới mặt đất.","audioKind":"ex"},{"en":"Restricting the height of new buildings can protect historic views and preserve the character of older neighbourhoods.","vi":"Việc hạn chế chiều cao của các tòa nhà mới có thể bảo vệ cảnh quan lịch sử và giữ gìn nét đặc trưng của các khu phố cũ.","audioKind":"ex2"}],"collocations":[{"en":"average height","vi":"chiều cao trung bình"},{"en":"at a height of","vi":"ở độ cao"},{"en":"a fear of heights","vi":"nỗi sợ độ cao"},{"en":"at the height of","vi":"vào thời kỳ đỉnh cao của"}],"wordFamily":["high (adj.)","heighten (v.)"],"synonyms":[],"antonyms":[],"tipVi":"height là danh từ; tính từ chỉ người cao dùng tall, vật cao dùng high.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bake', 'en-a2-35', 'bake', '/beɪk/', 'A2', 'nướng bằng lò', 'v.', 'baker (n.), bakery (n.), baking (n.)', NULL, 'bake thường dùng cho bánh mì, bánh ngọt; nướng thịt thường dùng roast.', 'I baked some bread while the children set the table.', NULL, 'Tôi đã nướng một ít bánh mì trong lúc lũ trẻ bày bàn ăn.', '{"wordId":"bake","ukIpa":"/beɪk/","usIpa":"/beɪk/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To cook food in an oven using dry heat.","vi":"nướng bằng lò"}],"examples":[{"en":"I baked some bread while the children set the table.","vi":"Tôi đã nướng một ít bánh mì trong lúc lũ trẻ bày bàn ăn.","audioKind":"ex"},{"en":"Schools can teach children to bake simple foods as part of practical lessons about nutrition and independence.","vi":"Nhà trường có thể dạy trẻ em nướng những món ăn đơn giản như một phần của các bài học thực tế về dinh dưỡng và tính tự lập.","audioKind":"ex2"}],"collocations":[{"en":"bake bread","vi":"nướng bánh mì"},{"en":"bake a cake","vi":"nướng bánh ngọt"},{"en":"freshly baked","vi":"mới nướng"}],"wordFamily":["baker (n.)","bakery (n.)","baking (n.)"],"synonyms":[],"antonyms":[],"tipVi":"bake thường dùng cho bánh mì, bánh ngọt; nướng thịt thường dùng roast.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nearly', 'en-a2-35', 'nearly', '/ˈnɪrli/', 'A2', 'hầu như; suýt; gần như', 'adv.', 'near (adj.), nearness (n.)', 'Đồng nghĩa: almost, practically', 'nearly biểu thị việc suýt đạt đến mức độ nào đó; not nearly biểu thị sự thiếu hụt xa so với mức cần thiết.', 'I nearly missed the bus because I overslept.', NULL, 'Tôi suýt lỡ chuyến xe buýt vì ngủ quên.', '{"wordId":"nearly","ukIpa":"/ˈnɪəli/","usIpa":"/ˈnɪrli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"Almost, but not completely or exactly.","vi":"hầu như; suýt; gần như"}],"examples":[{"en":"I nearly missed the bus because I overslept.","vi":"Tôi suýt lỡ chuyến xe buýt vì ngủ quên.","audioKind":"ex"},{"en":"Nearly half of the surveyed residents supported expanding public transport rather than building additional roads.","vi":"Gần một nửa số cư dân được khảo sát ủng hộ việc mở rộng giao thông công cộng thay vì xây dựng thêm đường sá.","audioKind":"ex2"}],"collocations":[{"en":"nearly half","vi":"gần một nửa"},{"en":"nearly finished","vi":"gần hoàn thành"},{"en":"nearly impossible","vi":"gần như bất khả thi"},{"en":"not nearly enough","vi":"còn lâu mới đủ"}],"wordFamily":["near (adj.)","nearness (n.)"],"synonyms":["almost","practically"],"antonyms":[],"tipVi":"nearly biểu thị việc suýt đạt đến mức độ nào đó; not nearly biểu thị sự thiếu hụt xa so với mức cần thiết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pyjamas', 'en-a2-35', 'pyjamas', '/pəˈdʒɑːməz/', 'A2', 'quần áo ngủ; đồ ngủ', 'n.', NULL, NULL, 'Từ này luôn dùng ở dạng số nhiều; một bộ dùng a pair of; tiếng Anh-Mỹ viết là pajamas.', 'I put on my pyjamas and climbed into bed.', NULL, 'Tôi mặc đồ ngủ vào và lên giường đi ngủ.', '{"wordId":"pyjamas","ukIpa":"/pəˈdʒɑːməz/","usIpa":"/pəˈdʒɑːməz/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a loose top and trousers worn for sleeping","vi":"quần áo ngủ; đồ ngủ"}],"examples":[{"en":"I put on my pyjamas and climbed into bed.","vi":"Tôi mặc đồ ngủ vào và lên giường đi ngủ.","audioKind":"ex"},{"en":"Choosing comfortable pyjamas and maintaining a regular bedtime may help children establish healthier sleep routines.","vi":"Việc lựa chọn đồ ngủ thoải mái và duy trì giờ đi ngủ điều độ có thể giúp trẻ em thiết lập thói quen ngủ lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"a pair of pyjamas","vi":"một bộ đồ ngủ"},{"en":"cotton pyjamas","vi":"đồ ngủ bằng cotton"},{"en":"put on pyjamas","vi":"mặc đồ ngủ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ này luôn dùng ở dạng số nhiều; một bộ dùng a pair of; tiếng Anh-Mỹ viết là pajamas.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_35_1', 'en-a2-35', 'Cách dùng “pleasant” (adj.) — dễ chịu; thoải mái', 'pleasant weather  ·  a pleasant surprise  ·  a pleasant atmosphere', 'pleasant dùng để miêu tả sự vật gây cảm giác dễ chịu; pleased dùng để chỉ cảm giác vui mừng của con người.', 'Họ từ (Word Family): pleasantly (adv.), pleasantness (n.), unpleasant (adj.) | Đồng nghĩa: enjoyable, agreeable · Trái nghĩa: unpleasant', '[{"hanzi":"We enjoyed a pleasant walk beside the river.","pinyin":"","meaning":"Chúng tôi đã có một buổi tản bộ thú vị dọc bờ sông."},{"hanzi":"Public gardens provide pleasant spaces where residents can exercise, socialise, and escape the pressures of urban life.","pinyin":"","meaning":"Các khu vườn công cộng mang lại không gian dễ chịu để cư dân tập thể dục, giao lưu và rũ bỏ áp lực của cuộc sống đô thị."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_35_2', 'en-a2-35', 'Cách dùng “nearly” (adv.) — hầu như; suýt; gần như', 'nearly half  ·  nearly finished  ·  nearly impossible', 'nearly biểu thị việc suýt đạt đến mức độ nào đó; not nearly biểu thị sự thiếu hụt xa so với mức cần thiết.', 'Họ từ (Word Family): near (adj.), nearness (n.) | Đồng nghĩa: almost, practically', '[{"hanzi":"I nearly missed the bus because I overslept.","pinyin":"","meaning":"Tôi suýt lỡ chuyến xe buýt vì ngủ quên."},{"hanzi":"Nearly half of the surveyed residents supported expanding public transport rather than building additional roads.","pinyin":"","meaning":"Gần một nửa số cư dân được khảo sát ủng hộ việc mở rộng giao thông công cộng thay vì xây dựng thêm đường sá."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_35_3', 'en-a2-35', 'Cách dùng “cotton” (n.) — bông (thực vật)', 'organic cotton  ·  cotton fabric  ·  cotton wool', 'Thường là danh từ không đếm được; trong cotton shirt thì cotton đóng vai trò là danh từ làm định ngữ.', NULL, '[{"hanzi":"This cotton shirt feels soft even after many washes.","pinyin":"","meaning":"Chiếc áo sơ mi bằng vải bông này vẫn mềm mại ngay cả sau nhiều lần giặt."},{"hanzi":"Cotton production can place considerable pressure on water supplies, particularly in regions with limited rainfall.","pinyin":"","meaning":"Sản xuất bông có thể gây áp lực đáng kể lên nguồn cung cấp nước, đặc biệt là ở những vùng có lượng mưa hạn chế."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_35_4', 'en-a2-35', 'Cách dùng “plus” (prep.) — cộng với; thêm vào', 'plus tax  ·  a big plus  ·  plus ten degrees', 'Khi plus đóng vai trò là danh từ chỉ ưu điểm thì là danh từ đếm được, ví dụ như a big plus.', 'Trái nghĩa: minus', '[{"hanzi":"The room costs sixty pounds plus breakfast each night.","pinyin":"","meaning":"Căn phòng có giá sáu mươi bảng cộng với tiền bữa sáng mỗi đêm."},{"hanzi":"Affordable housing plus reliable public transport can make expanding cities more accessible to workers on modest incomes.","pinyin":"","meaning":"Nhà ở giá cả phải chăng cộng với giao thông công cộng đáng tin cậy có thể giúp các thành phố đang mở rộng trở nên dễ tiếp cận hơn đối với những người lao động có thu nhập khiêm tốn."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_35_1', 'en-a2-35', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
