INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_35_1_8', 'ten_a2_35_1', 'cotton', 'This cotton shirt feels soft even after many washes.', 'This cotton shirt feels soft even after many washes.', '/ˈkɑːtən/', 'Chiếc áo sơ mi bằng vải bông này vẫn mềm mại ngay cả sau nhiều lần giặt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_35_1_1', 'en-a2-35', 'ten_a2_35_1', 'listening', 'listening', 'Please raise your hand if you need another pencil.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc áo sơ mi bằng vải bông này vẫn mềm mại ngay cả sau nhiều lần giặt.","Xin hãy giơ tay lên nếu bạn cần một chiếc bút chì khác.","Anh ấy lật chiếc bánh kếp và với lấy hũ mật ong.","Trời bắt đầu mưa, nhưng chúng tôi vẫn đi dạo dù sao đi nữa."]'::jsonb, 1, 'Please raise your hand if you need another pencil. → Xin hãy giơ tay lên nếu bạn cần một chiếc bút chì khác.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_35_1_2', 'en-a2-35', 'ten_a2_35_1', 'listening', 'listening', 'She set the bowl gently on the kitchen table.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đã gần nửa đêm nhưng chị tôi vẫn thức.","Thái củ hành tây này lại khiến mắt tôi cay xè.","Chúng tôi cùng chia sẻ việc nhà để không ai phải một mình dọn dẹp vào ngày Chủ nhật.","Cô ấy nhẹ nhàng đặt chiếc bát lên bàn bếp."]'::jsonb, 3, 'She set the bowl gently on the kitchen table. → Cô ấy nhẹ nhàng đặt chiếc bát lên bàn bếp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_35_1_3', 'en-a2-35', 'ten_a2_35_1', 'listening', 'listening', 'Please feed the cat before you leave for school.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã kiểm tra hộp đựng bánh quy nhưng chẳng còn cái nào.","Hãy đặt những chiếc cốc sạch lên kệ ở phía trên bồn rửa bát.","Làm ơn cho mèo ăn trước khi con đi học nhé.","Mọi người đều muốn đi bộ về nhà trừ anh trai tôi."]'::jsonb, 2, 'Please feed the cat before you leave for school. → Làm ơn cho mèo ăn trước khi con đi học nhé.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_35_2', 'en-a2-35', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_35_2_1', 'ten_a2_35_2', 'raise', 'Community events can raise funds for conservation projects while helping residents understand local environmental challenges.', 'Community events can raise funds for conservation projects while helping residents understand local environmental challenges.', '/reɪz/', 'Các sự kiện cộng đồng có thể gây quỹ cho các dự án bảo tồn đồng thời giúp cư dân hiểu rõ hơn về các thách thức môi trường địa phương.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_35_2_2', 'ten_a2_35_2', 'set', 'Governments should set clear targets for reducing air pollution and regularly assess progress towards achieving them.', 'Governments should set clear targets for reducing air pollution and regularly assess progress towards achieving them.', '/set/', 'Chính phủ nên đặt ra các mục tiêu rõ ràng để giảm ô nhiễm không khí và thường xuyên đánh giá tiến độ đạt được các mục tiêu đó.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_35_2_3', 'ten_a2_35_2', 'feed', 'School meal programmes help feed children whose families cannot consistently afford nutritious food.', 'School meal programmes help feed children whose families cannot consistently afford nutritious food.', '/fiːd/', 'Chương trình bữa ăn học đường giúp cung cấp thực phẩm cho trẻ em có gia đình không đủ khả năng mua thực phẩm bổ dưỡng một cách thường xuyên.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_35_2_4', 'ten_a2_35_2', 'pancake', 'Preparing pancakes in cooking classes allows students to practise measuring ingredients and using kitchen equipment safely.', 'Preparing pancakes in cooking classes allows students to practise measuring ingredients and using kitchen equipment safely.', '/ˈpænkeɪk/', 'Việc chuẩn bị bánh kếp trong các lớp học nấu ăn giúp học sinh luyện tập cách đong đếm nguyên liệu và sử dụng thiết bị nhà bếp một cách an toàn.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_35_2_5', 'ten_a2_35_2', 'except', 'The proposed transport policy benefits most residents, except those living in remote rural communities.', 'The proposed transport policy benefits most residents, except those living in remote rural communities.', '/ɪkˈsept/', 'Chính sách giao thông được đề xuất mang lại lợi ích cho hầu hết cư dân, ngoại trừ những người sống ở các vùng nông thôn hẻo lánh.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_35_2_6', 'ten_a2_35_2', 'still', 'Despite improvements in public transport, many commuters still rely on private cars because services remain unreliable in rural areas.', 'Despite improvements in public transport, many commuters still rely on private cars because services remain unreliable in rural areas.', '/stɪl/', 'Mặc dù hệ thống giao thông công cộng đã được cải thiện, nhiều người đi làm vẫn phụ thuộc vào xe cá nhân vì dịch vụ ở các vùng nông thôn vẫn chưa đáng tin cậy.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_35_2_1', 'en-a2-35', 'ten_a2_35_2', 'listening', 'listening', 'Community events can raise funds for conservation projects while helping residents understand local environmental challenges.', NULL, 'Trong câu vừa nghe, từ “raise” mang nghĩa nào sau đây?', '["dấu phẩy","lược","nâng lên; tăng lên; đưa lên","dịch vụ; sự phục vụ"]'::jsonb, 2, '“raise” (/reɪz/): nâng lên; tăng lên; đưa lên. Câu đầy đủ: Community events can raise funds for conservation projects while helping residents understand local environmental challenges.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
