INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_35_6', 'en-a2-35', NULL, 'comprehensive_test', 'listening', 'It is nearly midnight, but my sister is still awake.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi cùng chia sẻ việc nhà để không ai phải một mình dọn dẹp vào ngày Chủ nhật.","Đã gần nửa đêm nhưng chị tôi vẫn thức.","Sáng nay tôi mua mấy quả dâu tây tươi ở chợ.","Thái củ hành tây này lại khiến mắt tôi cay xè."]'::jsonb, 1, 'It is nearly midnight, but my sister is still awake. → Đã gần nửa đêm nhưng chị tôi vẫn thức.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_35_7', 'en-a2-35', NULL, 'comprehensive_test', 'listening', 'fresh', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["gối","tương cà chua","môn đánh gôn; môn thể thao đánh gôn","tươi; mới hái"]'::jsonb, 3, 'fresh (/freʃ/) → tươi; mới hái; trong lành; mát mẻ; mới mẻ; khác trước', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_35_8', 'en-a2-35', NULL, 'comprehensive_test', 'listening', 'This cotton shirt feels soft even after many washes.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã kiểm tra hộp đựng bánh quy nhưng chẳng còn cái nào.","Anh ấy lật chiếc bánh kếp và với lấy hũ mật ong.","Hãy đặt những chiếc cốc sạch lên kệ ở phía trên bồn rửa bát.","Chiếc áo sơ mi bằng vải bông này vẫn mềm mại ngay cả sau nhiều lần giặt."]'::jsonb, 3, 'This cotton shirt feels soft even after many washes. → Chiếc áo sơ mi bằng vải bông này vẫn mềm mại ngay cả sau nhiều lần giặt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
