INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_35_18', 'en-a2-35', NULL, 'comprehensive_test', 'reading', NULL, 'Community events can raise funds for conservation projects while helping residents understand local environmental challenges.', 'Dựa vào câu trên, từ “raise” có nghĩa phù hợp nhất là gì?', '["kỳ nghỉ; thời gian nghỉ ngơi, du lịch","tròn; có hình tròn (hoặc hình cầu)","nâng lên; tăng lên; đưa lên","trật tự, thứ tự"]'::jsonb, 2, 'raise: nâng lên; tăng lên; đưa lên; gây quỹ; quyên góp; nuôi dưỡng; nuôi nấng. Dịch cả câu: Các sự kiện cộng đồng có thể gây quỹ cho các dự án bảo tồn đồng thời giúp cư dân hiểu rõ hơn về các thách thức môi trường địa phương.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_35_19', 'en-a2-35', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should set clear targets for reducing air pollution and regularly assess progress towards achieving them.', 'Dựa vào câu trên, từ “set” có nghĩa phù hợp nhất là gì?', '["hộ chiếu","đặt; thiết lập; xác định","không ai; không một ai","thuộc bên trái; phía tay trái"]'::jsonb, 1, 'set: đặt; thiết lập; xác định; một bộ; một tập hợp; cố định; được định sẵn. Dịch cả câu: Chính phủ nên đặt ra các mục tiêu rõ ràng để giảm ô nhiễm không khí và thường xuyên đánh giá tiến độ đạt được các mục tiêu đó.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_35_20', 'en-a2-35', NULL, 'comprehensive_test', 'reading', NULL, 'School meal programmes help feed children whose families cannot consistently afford nutritious food.', 'Dựa vào câu trên, từ “feed” có nghĩa phù hợp nhất là gì?', '["môn lướt sóng","trò đùa; câu chuyện cười","ngày làm việc trong tuần; từ thứ Hai đến thứ Sáu","cho ăn; ăn"]'::jsonb, 3, 'feed: cho ăn; ăn; thức ăn cho gia súc; thông tin cập nhật. Dịch cả câu: Chương trình bữa ăn học đường giúp cung cấp thực phẩm cho trẻ em có gia đình không đủ khả năng mua thực phẩm bổ dưỡng một cách thường xuyên.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_35_21', 'en-a2-35', NULL, 'comprehensive_test', 'reading', NULL, 'Preparing pancakes in cooking classes allows students to practise measuring ingredients and using kitchen equipment safely.', 'Dựa vào câu trên, từ “pancake” có nghĩa phù hợp nhất là gì?', '["bánh kếp; bánh xèo mỏng","bài kiểm tra ngắn; trò chơi đố vui","doanh nhân; nhà kinh doanh nam","đơn giản; dễ hiểu; dễ làm"]'::jsonb, 0, 'pancake: bánh kếp; bánh xèo mỏng. Dịch cả câu: Việc chuẩn bị bánh kếp trong các lớp học nấu ăn giúp học sinh luyện tập cách đong đếm nguyên liệu và sử dụng thiết bị nhà bếp một cách an toàn.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
