INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-36', 'en', 'Bài 36: Đời sống hằng ngày (8) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '26 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2036, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_able', 'en-a2-36', 'able', '/ˈeɪbəl/', 'A2', 'có thể; đủ khả năng; có tài năng; giỏi giang', 'adj.', 'ability (n.), unable (adj.), ably (adv.)', 'Đồng nghĩa: capable, competent · Trái nghĩa: unable, incapable', 'Diễn đạt khả năng làm gì dùng be able to do, không dùng able doing.', 'I am finally able to swim across the pool.', NULL, 'Cuối cùng tôi đã có thể bơi qua chiều dài của bể bơi.', '{"wordId":"able","ukIpa":"/ˈeɪbəl/","usIpa":"/ˈeɪbəl/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"having the skill, opportunity, or means to do something","vi":"có thể; đủ khả năng"},{"pos":"adj.","en":"skilled and effective at doing things","vi":"có tài năng; giỏi giang"}],"examples":[{"en":"I am finally able to swim across the pool.","vi":"Cuối cùng tôi đã có thể bơi qua chiều dài của bể bơi.","audioKind":"ex"},{"en":"With reliable internet access, rural students are able to attend courses previously available only in cities.","vi":"Với kết nối internet đáng tin cậy, học sinh vùng sâu vùng xa có thể tham gia các khóa học trước đây chỉ có ở thành phố.","audioKind":"ex2"}],"collocations":[{"en":"be able to","vi":"có thể làm gì"},{"en":"an able leader","vi":"một nhà lãnh đạo tài năng"},{"en":"an able student","vi":"một học sinh có năng lực"}],"wordFamily":["ability (n.)","unable (adj.)","ably (adv.)"],"synonyms":["capable","competent"],"antonyms":["unable","incapable"],"tipVi":"Diễn đạt khả năng làm gì dùng be able to do, không dùng able doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ham', 'en-a2-36', 'ham', '/hæm/', 'A2', 'thịt dăm bông; thịt lợn xông khói', 'n.', NULL, NULL, 'Danh từ chỉ thịt dăm bông thường không đếm được; dùng a slice of ham để chỉ một lát.', 'I put some ham and cheese in my sandwich.', NULL, 'Tôi cho một ít dăm bông và phô mai vào bánh mì kẹp của mình.', '{"wordId":"ham","ukIpa":"/hæm/","usIpa":"/hæm/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Meat from a pig''s leg, preserved by salting or smoking.","vi":"thịt dăm bông; thịt lợn xông khói"}],"examples":[{"en":"I put some ham and cheese in my sandwich.","vi":"Tôi cho một ít dăm bông và phô mai vào bánh mì kẹp của mình.","audioKind":"ex"},{"en":"Processed meats such as ham often contain substantial amounts of salt, which consumers should consider when planning meals.","vi":"Các loại thịt chế biến sẵn như dăm bông thường chứa hàm lượng muối đáng kể, mà người tiêu dùng nên cân nhắc khi lên thực đơn.","audioKind":"ex2"}],"collocations":[{"en":"a slice of ham","vi":"một lát thịt dăm bông"},{"en":"smoked ham","vi":"thịt dăm bông xông khói"},{"en":"ham sandwich","vi":"bánh mì kẹp dăm bông"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ chỉ thịt dăm bông thường không đếm được; dùng a slice of ham để chỉ một lát.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_leather', 'en-a2-36', 'leather', '/ˈleðər/', 'A2', 'da (đã qua xử lý để làm quần áo, túi xách và các đồ dùng khác)', 'n.', NULL, NULL, 'Thông thường là danh từ không đếm được; leather jacket có danh từ đứng trước làm bổ ngữ.', 'Her old leather bag still feels soft and smooth.', NULL, 'Chiếc túi da cũ của cô ấy vẫn mang lại cảm giác mềm mại và mịn màng.', '{"wordId":"leather","ukIpa":"/ˈleðə/","usIpa":"/ˈleðər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"animal skin treated for making clothes, bags, and other goods","vi":"da (đã qua xử lý để làm quần áo, túi xách và các đồ dùng khác)"}],"examples":[{"en":"Her old leather bag still feels soft and smooth.","vi":"Chiếc túi da cũ của cô ấy vẫn mang lại cảm giác mềm mại và mịn màng.","audioKind":"ex"},{"en":"Some consumers avoid leather products because they are concerned about animal welfare and the environmental impact of production.","vi":"Một số người tiêu dùng tránh mua sản phẩm da vì họ quan tâm đến phúc lợi động vật và tác động môi trường của quá trình sản xuất.","audioKind":"ex2"}],"collocations":[{"en":"leather jacket","vi":"áo khoác da"},{"en":"genuine leather","vi":"da thật"},{"en":"leather goods","vi":"đồ da"},{"en":"synthetic leather","vi":"da nhân tạo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thông thường là danh từ không đếm được; leather jacket có danh từ đứng trước làm bổ ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_toaster', 'en-a2-36', 'toaster', '/ˈtoʊstər/', 'A2', 'máy nướng bánh mì', 'n.', 'toast (n.), toast (v.), toasted (adj.)', NULL, 'Toaster là thiết bị điện; còn toast chỉ bánh mì nướng thì không đếm được.', 'Two slices of bread popped out of the toaster.', NULL, 'Hai lát bánh mì đã bật ra khỏi máy nướng bánh mì.', '{"wordId":"toaster","ukIpa":"/ˈtəʊstə/","usIpa":"/ˈtoʊstər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"an electrical appliance that heats bread until crisp and brown","vi":"máy nướng bánh mì"}],"examples":[{"en":"Two slices of bread popped out of the toaster.","vi":"Hai lát bánh mì đã bật ra khỏi máy nướng bánh mì.","audioKind":"ex"},{"en":"Small appliances such as toasters should be designed for easy repair rather than frequent replacement.","vi":"Các thiết bị gia dụng nhỏ như máy nướng bánh mì nên được thiết kế để dễ sửa chữa thay vì phải thay mới thường xuyên.","audioKind":"ex2"}],"collocations":[{"en":"put bread in the toaster","vi":"cho bánh mì vào máy nướng"},{"en":"two-slice toaster","vi":"máy nướng bánh mì hai lát"},{"en":"toaster oven","vi":"lò nướng bánh mì kiêm lò sấy"}],"wordFamily":["toast (n.)","toast (v.)","toasted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Toaster là thiết bị điện; còn toast chỉ bánh mì nướng thì không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recent', 'en-a2-36', 'recent', '/ˈriːsənt/', 'A2', 'gần đây; mới đây', 'adj.', 'recently (adv.), recency (n.)', 'Trái nghĩa: old', 'recent là tính từ; nếu muốn bổ nghĩa cho động từ thì phải dùng trạng từ recently.', 'Have you seen any recent photos of our puppy?', NULL, 'Bạn đã xem bức ảnh nào gần đây của chú cún nhà chúng ta chưa?', '{"wordId":"recent","ukIpa":"/ˈriːsənt/","usIpa":"/ˈriːsənt/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"having happened or started a short time ago","vi":"gần đây; mới đây"}],"examples":[{"en":"Have you seen any recent photos of our puppy?","vi":"Bạn đã xem bức ảnh nào gần đây của chú cún nhà chúng ta chưa?","audioKind":"ex"},{"en":"Recent advances in medical technology have improved treatment options for patients living in remote communities.","vi":"Những tiến bộ gần đây trong công nghệ y tế đã cải thiện các lựa chọn điều trị cho bệnh nhân sống ở các vùng cộng đồng hẻo lánh.","audioKind":"ex2"}],"collocations":[{"en":"recent research","vi":"nghiên cứu gần đây"},{"en":"recent developments","vi":"những diễn biến gần đây"},{"en":"in recent years","vi":"trong những năm gần đây"}],"wordFamily":["recently (adv.)","recency (n.)"],"synonyms":[],"antonyms":["old"],"tipVi":"recent là tính từ; nếu muốn bổ nghĩa cho động từ thì phải dùng trạng từ recently.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_burger', 'en-a2-36', 'burger', '/ˈbɝːɡər/', 'A2', 'bánh mì kẹp thịt; chả thịt băm', 'n.', NULL, 'Đồng nghĩa: hamburger', 'burger đôi khi cũng chỉ bản thân miếng chả, và không phải lúc nào cũng làm từ thịt bò.', 'I ordered a bean burger with salad for lunch.', NULL, 'Tôi gọi một chiếc bánh burger đậu kèm salad cho bữa trưa.', '{"wordId":"burger","ukIpa":"/ˈbɜːɡə/","usIpa":"/ˈbɝːɡər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A flat food patty, often served inside a round bread roll","vi":"bánh mì kẹp thịt; chả thịt băm"}],"examples":[{"en":"I ordered a bean burger with salad for lunch.","vi":"Tôi gọi một chiếc bánh burger đậu kèm salad cho bữa trưa.","audioKind":"ex"},{"en":"Restaurants can reduce their environmental impact by offering plant-based burgers alongside traditional meat dishes.","vi":"Các nhà hàng có thể giảm thiểu tác động đến môi trường bằng cách phục vụ bánh burger làm từ thực vật bên cạnh các món thịt truyền thống.","audioKind":"ex2"}],"collocations":[{"en":"beef burger","vi":"bánh burger bò"},{"en":"veggie burger","vi":"bánh burger chay"},{"en":"burger bun","vi":"vỏ bánh burger"}],"wordFamily":[],"synonyms":["hamburger"],"antonyms":[],"tipVi":"burger đôi khi cũng chỉ bản thân miếng chả, và không phải lúc nào cũng làm từ thịt bò.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_candle', 'en-a2-36', 'candle', '/ˈkændl/', 'A2', 'cây nến; ngọn nến', 'n.', 'candlelight (n.), candlestick (n.)', NULL, 'Thắp nến dùng light; thổi tắt dùng blow out.', 'He lit a candle when the electricity went off.', NULL, 'Anh ấy đã thắp một cây nến khi cúp điện.', '{"wordId":"candle","ukIpa":"/ˈkændl/","usIpa":"/ˈkændl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a piece of wax with a central string that burns","vi":"cây nến; ngọn nến"}],"examples":[{"en":"He lit a candle when the electricity went off.","vi":"Anh ấy đã thắp một cây nến khi cúp điện.","audioKind":"ex"},{"en":"Although candles create a pleasant atmosphere, they should never be left burning unattended in homes or public spaces.","vi":"Mặc dù nến tạo ra bầu không khí dễ chịu, nhưng tuyệt đối không được để nến cháy mà không có người trông coi trong nhà hoặc nơi công cộng.","audioKind":"ex2"}],"collocations":[{"en":"light a candle","vi":"thắp nến"},{"en":"blow out a candle","vi":"thổi tắt nến"},{"en":"scented candle","vi":"nến thơm"}],"wordFamily":["candlelight (n.)","candlestick (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thắp nến dùng light; thổi tắt dùng blow out.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_available', 'en-a2-36', 'available', '/əˈveɪləbl/', 'A2', 'có sẵn; có thể mua/dùng được; rảnh rỗi; có thời gian', 'adj.', 'availability (n.), unavailable (adj.)', 'Đồng nghĩa: obtainable, accessible · Trái nghĩa: unavailable', 'available to đi với người sử dụng; available for đi với mục đích sử dụng.', 'There are still tickets available for the afternoon show.', NULL, 'Vẫn còn vé cho suất chiếu buổi chiều.', '{"wordId":"available","ukIpa":"/əˈveɪləbl/","usIpa":"/əˈveɪləbl/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Ready or possible to get, buy, or use.","vi":"có sẵn; có thể mua/dùng được"},{"pos":"adj.","en":"Not busy and able to meet or help someone.","vi":"rảnh rỗi; có thời gian"}],"examples":[{"en":"There are still tickets available for the afternoon show.","vi":"Vẫn còn vé cho suất chiếu buổi chiều.","audioKind":"ex"},{"en":"Affordable housing should be available to all residents, regardless of their income or employment status.","vi":"Nhà ở giá rẻ nên có sẵn cho tất cả cư dân, bất kể thu nhập hay tình trạng việc làm của họ.","audioKind":"ex2"}],"collocations":[{"en":"readily available","vi":"dễ dàng có sẵn"},{"en":"available to everyone","vi":"có sẵn cho tất cả mọi người"},{"en":"available for use","vi":"có sẵn để sử dụng"},{"en":"make something available","vi":"làm cho cái gì có sẵn"}],"wordFamily":["availability (n.)","unavailable (adj.)"],"synonyms":["obtainable","accessible"],"antonyms":["unavailable"],"tipVi":"available to đi với người sử dụng; available for đi với mục đích sử dụng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_furniture', 'en-a2-36', 'furniture', '/ˈfɝːnɪtʃər/', 'A2', 'đồ đạc trong nhà; đồ nội thất', 'n.', 'furnish (v.), furnished (adj.), furnishings (n.)', NULL, 'Không đếm được: một món đồ nội thất nói là a piece of furniture.', 'We moved the furniture to make room for dancing.', NULL, 'Chúng tôi đã di chuyển đồ đạc để lấy chỗ khiêu vũ.', '{"wordId":"furniture","ukIpa":"/ˈfɜːnɪtʃə/","usIpa":"/ˈfɝːnɪtʃər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Movable objects such as chairs, tables, and beds in buildings.","vi":"đồ đạc trong nhà; đồ nội thất"}],"examples":[{"en":"We moved the furniture to make room for dancing.","vi":"Chúng tôi đã di chuyển đồ đạc để lấy chỗ khiêu vũ.","audioKind":"ex"},{"en":"Buying second-hand furniture can lower household expenses while reducing demand for raw materials and limiting waste.","vi":"Mua đồ nội thất cũ có thể giúp giảm chi phí sinh hoạt trong gia đình đồng thời giảm nhu cầu về nguyên liệu thô và hạn chế rác thải.","audioKind":"ex2"}],"collocations":[{"en":"a piece of furniture","vi":"một món đồ nội thất"},{"en":"wooden furniture","vi":"đồ nội thất bằng gỗ"},{"en":"second-hand furniture","vi":"đồ nội thất cũ"},{"en":"office furniture","vi":"đồ nội thất văn phòng"}],"wordFamily":["furnish (v.)","furnished (adj.)","furnishings (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Không đếm được: một món đồ nội thất nói là a piece of furniture.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_button', 'en-a2-36', 'button', '/ˈbʌtən/', 'A2', 'nút; nút bấm; cúc áo; khuy áo; cài khuy; cài cúc', 'n.', 'unbutton (v.)', NULL, 'button up chỉ việc cài khuy áo; đối với khóa kéo, dùng zip chứ không dùng button.', 'Press the green button to start the washing machine.', NULL, 'Hãy bấm nút màu xanh lá cây để khởi động máy giặt.', '{"wordId":"button","ukIpa":"/ˈbʌtən/","usIpa":"/ˈbʌtən/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A small control you press to operate something","vi":"nút; nút bấm"},{"pos":"n.","en":"A small object that fastens clothing through a hole","vi":"cúc áo; khuy áo"},{"pos":"v.","en":"Fasten clothing using buttons","vi":"cài khuy; cài cúc"}],"examples":[{"en":"Press the green button to start the washing machine.","vi":"Hãy bấm nút màu xanh lá cây để khởi động máy giặt.","audioKind":"ex"},{"en":"Emergency buttons on public transport allow passengers to alert staff quickly when assistance is needed.","vi":"Các nút khẩn cấp trên phương tiện giao thông công cộng giúp hành khách nhanh chóng thông báo cho nhân viên khi cần trợ giúp.","audioKind":"ex2"}],"collocations":[{"en":"press a button","vi":"bấm nút"},{"en":"push a button","vi":"nhấn nút"},{"en":"button up a coat","vi":"cài khuy áo khoác"},{"en":"sew on a button","vi":"khâu cúc áo"}],"wordFamily":["unbutton (v.)"],"synonyms":[],"antonyms":[],"tipVi":"button up chỉ việc cài khuy áo; đối với khóa kéo, dùng zip chứ không dùng button.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cream', 'en-a2-36', 'cream', '/kriːm/', 'A2', 'kem; sữa đặc béo; kem bôi da; thuốc mỡ; màu kem; màu trắng ngà vàng nhạt', 'n.', 'creamy (adj.), creaminess (n.)', NULL, '"Cream" là kem hoặc sữa béo, còn "cheese" mới là phô mai.', 'She poured fresh cream over a bowl of strawberries.', NULL, 'Cô ấy rưới kem tươi lên một bát dâu tây.', '{"wordId":"cream","ukIpa":"/kriːm/","usIpa":"/kriːm/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"The thick, fatty part of milk, used in food.","vi":"kem; sữa đặc béo"},{"pos":"n.","en":"A thick substance applied to skin for protection or treatment.","vi":"kem bôi da; thuốc mỡ"},{"pos":"adj.","en":"Having a pale yellowish-white colour.","vi":"màu kem; màu trắng ngà vàng nhạt"}],"examples":[{"en":"She poured fresh cream over a bowl of strawberries.","vi":"Cô ấy rưới kem tươi lên một bát dâu tây.","audioKind":"ex"},{"en":"Replacing cream with lower-fat ingredients can reduce the energy content of meals without greatly affecting flavour.","vi":"Thay thế kem bằng các nguyên liệu ít béo hơn có thể làm giảm hàm lượng calo trong bữa ăn mà không ảnh hưởng nhiều đến hương vị.","audioKind":"ex2"}],"collocations":[{"en":"whipped cream","vi":"kem đánh bông"},{"en":"face cream","vi":"kem dưỡng da mặt"},{"en":"apply cream","vi":"bôi kem"},{"en":"cream walls","vi":"tường màu kem"}],"wordFamily":["creamy (adj.)","creaminess (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"Cream\" là kem hoặc sữa béo, còn \"cheese\" mới là phô mai.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_careful', 'en-a2-36', 'careful', '/ˈkerfəl/', 'A2', 'cẩn thận; dè dặt; tỉ mỉ; cẩn trọng', 'adj.', 'care (n.), carefully (adv.), careless (adj.), carefulness (n.)', 'Đồng nghĩa: cautious, attentive · Trái nghĩa: careless', 'be careful with sau đó đi với vật; be careful to sau đó đi với động từ.', 'Be careful with that bowl; it belonged to Grandma.', NULL, 'Hãy cẩn thận với cái tô đó; nó là đồ của bà tôi đấy.', '{"wordId":"careful","ukIpa":"/ˈkeəfəl/","usIpa":"/ˈkerfəl/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"taking care to avoid danger, damage, or mistakes","vi":"cẩn thận; dè dặt"},{"pos":"adj.","en":"giving close attention to details","vi":"tỉ mỉ; cẩn trọng"}],"examples":[{"en":"Be careful with that bowl; it belonged to Grandma.","vi":"Hãy cẩn thận với cái tô đó; nó là đồ của bà tôi đấy.","audioKind":"ex"},{"en":"Careful planning can help cities expand public transport while keeping construction costs under control.","vi":"Quy hoạch chu đáo có thể giúp các thành phố mở rộng giao thông công cộng trong khi vẫn kiểm soát được chi phí xây dựng.","audioKind":"ex2"}],"collocations":[{"en":"be careful with","vi":"cẩn thận với"},{"en":"careful planning","vi":"lập kế hoạch chu đáo"},{"en":"careful consideration","vi":"suy xét kỹ lưỡng"},{"en":"careful analysis","vi":"phân tích chi tiết"}],"wordFamily":["care (n.)","carefully (adv.)","careless (adj.)","carefulness (n.)"],"synonyms":["cautious","attentive"],"antonyms":["careless"],"tipVi":"be careful with sau đó đi với vật; be careful to sau đó đi với động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unusual', 'en-a2-36', 'unusual', '/ʌnˈjuːʒuəl/', 'A2', 'bất thường; khác lạ', 'adj.', 'usual (adj.), usually (adv.), unusually (adv.)', 'Đồng nghĩa: uncommon, unconventional · Trái nghĩa: usual, ordinary', 'Cấu trúc It is unusual for sb to do diễn tả việc ai đó hiếm khi làm điều gì.', 'This carrot has an unusual shape, like a tiny hand.', NULL, 'Củ cà rốt này có hình dáng kỳ lạ, giống như một bàn tay nhỏ.', '{"wordId":"unusual","ukIpa":"/ʌnˈjuːʒuəl/","usIpa":"/ʌnˈjuːʒuəl/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Different from what is common, normal, or expected.","vi":"bất thường; khác lạ"}],"examples":[{"en":"This carrot has an unusual shape, like a tiny hand.","vi":"Củ cà rốt này có hình dáng kỳ lạ, giống như một bàn tay nhỏ.","audioKind":"ex"},{"en":"Scientists are investigating unusual weather patterns that may be linked to rising global temperatures.","vi":"Các nhà khoa học đang nghiên cứu các hình thái thời tiết bất thường có thể có liên quan đến tình trạng nhiệt độ toàn cầu tăng lên.","audioKind":"ex2"}],"collocations":[{"en":"unusual circumstances","vi":"hoàn cảnh đặc biệt"},{"en":"an unusual feature","vi":"một đặc điểm khác thường"},{"en":"highly unusual","vi":"vô cùng bất thường"}],"wordFamily":["usual (adj.)","usually (adv.)","unusually (adv.)"],"synonyms":["uncommon","unconventional"],"antonyms":["usual","ordinary"],"tipVi":"Cấu trúc It is unusual for sb to do diễn tả việc ai đó hiếm khi làm điều gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_handbag', 'en-a2-36', 'handbag', '/ˈhændbæɡ/', 'A2', 'túi xách tay; ví nữ', 'n.', 'bag (n.)', 'Đồng nghĩa: purse', 'Tiếng Mỹ dùng purse để chỉ túi xách tay nữ; tiếng Anh-Anh purse thường chỉ ví tiền lẻ.', 'She found her keys at the bottom of her handbag.', NULL, 'Cô ấy tìm thấy chìa khóa ở đáy chiếc túi xách của mình.', '{"wordId":"handbag","ukIpa":"/ˈhændbæɡ/","usIpa":"/ˈhændbæɡ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A small bag for carrying personal items, typically used by women.","vi":"túi xách tay; ví nữ"}],"examples":[{"en":"She found her keys at the bottom of her handbag.","vi":"Cô ấy tìm thấy chìa khóa ở đáy chiếc túi xách của mình.","audioKind":"ex"},{"en":"Consumers can reduce waste by choosing a durable handbag rather than replacing inexpensive accessories every season.","vi":"Người tiêu dùng có thể giảm thiểu rác thải bằng cách chọn một chiếc túi xách bền bỉ thay vì thay thế những món phụ kiện giá rẻ sau mỗi mùa.","audioKind":"ex2"}],"collocations":[{"en":"a leather handbag","vi":"túi xách da"},{"en":"a shoulder handbag","vi":"túi đeo vai"},{"en":"carry a handbag","vi":"xách túi"}],"wordFamily":["bag (n.)"],"synonyms":["purse"],"antonyms":[],"tipVi":"Tiếng Mỹ dùng purse để chỉ túi xách tay nữ; tiếng Anh-Anh purse thường chỉ ví tiền lẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cherry', 'en-a2-36', 'cherry', '/ˈtʃeri/', 'A2', 'quả anh đào; cây anh đào; cây hoa anh đào', 'n.', NULL, NULL, 'Dạng số nhiều là cherries; hạt quả dùng stone (Anh) hoặc pit (Mỹ).', 'He placed a ripe cherry on top of the cake.', NULL, 'Anh ấy đặt một quả anh đào chín mọng lên trên chiếc bánh kem.', '{"wordId":"cherry","ukIpa":"/ˈtʃeri/","usIpa":"/ˈtʃeri/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A small round fruit with a stone and usually red skin","vi":"quả anh đào"},{"pos":"n.","en":"A tree grown for its cherries or attractive blossoms","vi":"cây anh đào; cây hoa anh đào"}],"examples":[{"en":"He placed a ripe cherry on top of the cake.","vi":"Anh ấy đặt một quả anh đào chín mọng lên trên chiếc bánh kem.","audioKind":"ex"},{"en":"Cherry trees attract visitors during spring, providing seasonal income for rural communities through tourism.","vi":"Cây anh đào thu hút du khách vào mùa xuân, mang lại nguồn thu nhập theo mùa cho các cộng đồng nông thôn thông qua du lịch.","audioKind":"ex2"}],"collocations":[{"en":"cherry blossom","vi":"hoa anh đào"},{"en":"cherry tree","vi":"cây anh đào"},{"en":"ripe cherries","vi":"quả anh đào chín"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là cherries; hạt quả dùng stone (Anh) hoặc pit (Mỹ).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heavy', 'en-a2-36', 'heavy', '/ˈhevi/', 'A2', 'nặng; nặng nề; nhiều; dữ dội; lớn; nặng nhọc; căng thẳng', 'adj.', 'heavily (adv.), heaviness (n.)', 'Đồng nghĩa: weighty · Trái nghĩa: light', 'Mưa lớn dùng heavy rain, không dùng big rain.', 'This suitcase is too heavy for me to lift.', NULL, 'Chiếc va li này quá nặng đối với tôi để nhấc lên.', '{"wordId":"heavy","ukIpa":"/ˈhevi/","usIpa":"/ˈhevi/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Weighing a lot and often difficult to lift","vi":"nặng; nặng nề"},{"pos":"adj.","en":"Greater than usual in amount, strength, or intensity","vi":"nhiều; dữ dội; lớn"},{"pos":"adj.","en":"Demanding considerable effort or causing serious difficulty","vi":"nặng nhọc; căng thẳng"}],"examples":[{"en":"This suitcase is too heavy for me to lift.","vi":"Chiếc va li này quá nặng đối với tôi để nhấc lên.","audioKind":"ex"},{"en":"Heavy traffic contributes to urban air pollution and increases the time people spend commuting.","vi":"Mật độ giao thông cao góp phần gây ô nhiễm không khí đô thị và làm tăng thời gian mọi người dành cho việc di chuyển.","audioKind":"ex2"}],"collocations":[{"en":"heavy rain","vi":"mưa lớn"},{"en":"heavy traffic","vi":"giao thông ùn tắc"},{"en":"heavy workload","vi":"khối lượng công việc lớn"},{"en":"heavy lifting","vi":"công việc nặng nhọc"}],"wordFamily":["heavily (adv.)","heaviness (n.)"],"synonyms":["weighty"],"antonyms":["light"],"tipVi":"Mưa lớn dùng heavy rain, không dùng big rain.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_chat', 'en-a2-36', 'chat', '/tʃæt/', 'A2', 'trò chuyện, tán gẫu (trực tiếp hoặc qua tin nhắn điện tử); cuộc trò chuyện thân thiện, thân mật', 'v.', 'chatty (adj.)', 'Đồng nghĩa: talk, converse', 'Cấu trúc chat with ai đó, about chủ đề gì; thì quá khứ gấp đôi chữ t thành chatted.', 'We chatted about our weekend while waiting for the bus.', NULL, 'Chúng tôi đã trò chuyện về cuối tuần của mình khi đang đợi xe buýt.', '{"wordId":"chat","ukIpa":"/tʃæt/","usIpa":"/tʃæt/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To talk informally, in person or through electronic messages.","vi":"trò chuyện, tán gẫu (trực tiếp hoặc qua tin nhắn điện tử)"},{"pos":"n.","en":"A friendly, informal conversation.","vi":"cuộc trò chuyện thân thiện, thân mật"}],"examples":[{"en":"We chatted about our weekend while waiting for the bus.","vi":"Chúng tôi đã trò chuyện về cuối tuần của mình khi đang đợi xe buýt.","audioKind":"ex"},{"en":"Community gardens allow neighbours to chat regularly, helping them build stronger relationships and reduce social isolation.","vi":"Khu vườn cộng đồng tạo điều kiện cho các hàng xóm trò chuyện thường xuyên, giúp họ xây dựng mối quan hệ bền chặt hơn và giảm bớt tình trạng cô lập xã hội.","audioKind":"ex2"}],"collocations":[{"en":"chat with friends","vi":"trò chuyện với bạn bè"},{"en":"chat about work","vi":"tán gẫu về công việc"},{"en":"have a chat","vi":"có một cuộc trò chuyện"},{"en":"online chat","vi":"trò chuyện trực tuyến"}],"wordFamily":["chatty (adj.)"],"synonyms":["talk","converse"],"antonyms":[],"tipVi":"Cấu trúc chat with ai đó, about chủ đề gì; thì quá khứ gấp đôi chữ t thành chatted.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_roll', 'en-a2-36', 'roll', '/roʊl/', 'A2', 'lăn; làm cho vật gì dịch chuyển bằng cách lật qua lật lại nhiều lần; cuộn lại; tạo hình dạng cong hoặc hình trụ; cuộn (vật liệu được quấn quanh chính nó); ổ bánh mì nhỏ', 'v.', 'roller (n.)', NULL, 'roll nhấn mạnh chuyển động lăn lộn; hành động cuộn lên dùng roll up.', 'The orange rolled off the table and under my chair.', NULL, 'Quả cam lăn khỏi mặt bàn và chui xuống dưới ghế của tôi.', '{"wordId":"roll","ukIpa":"/rəʊl/","usIpa":"/roʊl/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To move or make something move by turning over repeatedly","vi":"lăn; làm cho vật gì dịch chuyển bằng cách lật qua lật lại nhiều lần"},{"pos":"v.","en":"To form something into a curved or cylindrical shape","vi":"cuộn lại; tạo hình dạng cong hoặc hình trụ"},{"pos":"n.","en":"Material wound around itself, or a small individual bread","vi":"cuộn (vật liệu được quấn quanh chính nó); ổ bánh mì nhỏ"}],"examples":[{"en":"The orange rolled off the table and under my chair.","vi":"Quả cam lăn khỏi mặt bàn và chui xuống dưới ghế của tôi.","audioKind":"ex"},{"en":"Workers roll sheets of recycled material into compact bundles to simplify storage and transportation.","vi":"Công nhân cuộn các tấm vật liệu tái chế thành các kiện gọn gàng để đơn giản hóa việc lưu trữ và vận chuyển.","audioKind":"ex2"}],"collocations":[{"en":"roll down a hill","vi":"lăn xuống đồi"},{"en":"roll up your sleeves","vi":"xắn tay áo lên"},{"en":"a roll of paper","vi":"một cuộn giấy"},{"en":"bread roll","vi":"bánh mì ổ nhỏ"}],"wordFamily":["roller (n.)"],"synonyms":[],"antonyms":[],"tipVi":"roll nhấn mạnh chuyển động lăn lộn; hành động cuộn lên dùng roll up.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quarter', 'en-a2-36', 'quarter', '/ˈkwɔːrtər/', 'A2', 'một phần tư (một trong bốn phần bằng nhau); quý (khoảng thời gian ba tháng trong năm); khu phố, khu vực trong thị trấn có đặc điểm riêng', 'n.', 'quarterly (adj.), quarterly (adv.)', NULL, 'a quarter of an hour là một khoảng thời gian một khắc (mười lăm phút); quarter cũng dùng để chỉ quý trong năm.', 'She cut the sandwich into quarters for the children.', NULL, 'Cô ấy cắt chiếc bánh mì kẹp thành bốn phần bằng nhau cho lũ trẻ.', '{"wordId":"quarter","ukIpa":"/ˈkwɔːtə/","usIpa":"/ˈkwɔːrtər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"One of four equal parts of something.","vi":"một phần tư (một trong bốn phần bằng nhau)"},{"pos":"n.","en":"A period of three months within a year.","vi":"quý (khoảng thời gian ba tháng trong năm)"},{"pos":"n.","en":"An area of a town with a particular character.","vi":"khu phố, khu vực trong thị trấn có đặc điểm riêng"}],"examples":[{"en":"She cut the sandwich into quarters for the children.","vi":"Cô ấy cắt chiếc bánh mì kẹp thành bốn phần bằng nhau cho lũ trẻ.","audioKind":"ex"},{"en":"Almost a quarter of the city''s residents depend on public transport for their daily commute.","vi":"Gần một phần tư cư dân của thành phố phụ thuộc vào giao thông công cộng cho việc đi lại hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"a quarter of","vi":"một phần tư của"},{"en":"a quarter of an hour","vi":"một khắc (mười lăm phút)"},{"en":"the first quarter","vi":"quý đầu tiên"},{"en":"the historic quarter","vi":"khu phố cổ kính"}],"wordFamily":["quarterly (adj.)","quarterly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"a quarter of an hour là một khoảng thời gian một khắc (mười lăm phút); quarter cũng dùng để chỉ quý trong năm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_advice', 'en-a2-36', 'advice', '/ədˈvaɪs/', 'A2', 'lời khuyên; sự hướng dẫn về việc ai đó nên làm gì trong một hoàn cảnh cụ thể', 'n.', 'advise (v.), adviser (n.), advisory (adj.)', 'Đồng nghĩa: guidance', 'Đây là danh từ không đếm được, không dùng an advice; động từ advise có phần đuôi phát âm là /z/.', 'Your advice helped me choose a comfortable bicycle.', NULL, 'Lời khuyên của bạn đã giúp tôi chọn được một chiếc xe đạp thoải mái.', '{"wordId":"advice","ukIpa":"/ədˈvaɪs/","usIpa":"/ədˈvaɪs/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"suggestions about what someone should do in a particular situation","vi":"lời khuyên; sự hướng dẫn về việc ai đó nên làm gì trong một hoàn cảnh cụ thể"}],"examples":[{"en":"Your advice helped me choose a comfortable bicycle.","vi":"Lời khuyên của bạn đã giúp tôi chọn được một chiếc xe đạp thoải mái.","audioKind":"ex"},{"en":"Schools should provide practical career advice so that students can make informed decisions about their future.","vi":"Nhà trường nên cung cấp những lời khuyên hướng nghiệp thiết thực để học sinh có thể đưa ra quyết định sáng suốt về tương lai của mình.","audioKind":"ex2"}],"collocations":[{"en":"give advice","vi":"đưa ra lời khuyên"},{"en":"seek advice","vi":"tìm kiếm lời khuyên"},{"en":"follow advice","vi":"làm theo lời khuyên"},{"en":"a piece of advice","vi":"một lời khuyên"}],"wordFamily":["advise (v.)","adviser (n.)","advisory (adj.)"],"synonyms":["guidance"],"antonyms":[],"tipVi":"Đây là danh từ không đếm được, không dùng an advice; động từ advise có phần đuôi phát âm là /z/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_excellent', 'en-a2-36', 'excellent', '/ˈeksələnt/', 'A2', 'tuyệt vời; xuất sắc', 'adj.', 'excellence (n.), excellently (adv.), excel (v.)', 'Đồng nghĩa: outstanding, superb · Trái nghĩa: poor, terrible', 'Vì từ ''excellent'' đã mang sẵn nghĩa ''rất tốt'', thông thường ta không dùng ''very'' đi kèm trước nó.', 'The soup was excellent, so I ordered another bowl.', NULL, 'Món súp ngon tuyệt, nên tôi đã gọi thêm một bát nữa.', '{"wordId":"excellent","ukIpa":"/ˈeksələnt/","usIpa":"/ˈeksələnt/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Extremely good or of very high quality.","vi":"tuyệt vời; xuất sắc"}],"examples":[{"en":"The soup was excellent, so I ordered another bowl.","vi":"Món súp ngon tuyệt, nên tôi đã gọi thêm một bát nữa.","audioKind":"ex"},{"en":"Excellent public transport can reduce car dependence and make cities more accessible to all residents.","vi":"Hệ thống giao thông công cộng tuyệt vời có thể làm giảm sự phụ kiện vào ô tô và giúp mọi cư dân dễ dàng di chuyển hơn.","audioKind":"ex2"}],"collocations":[{"en":"excellent service","vi":"dịch vụ tuyệt vời"},{"en":"excellent results","vi":"thành tích xuất sắc"},{"en":"excellent opportunity","vi":"cơ hội tuyệt vời"}],"wordFamily":["excellence (n.)","excellently (adv.)","excel (v.)"],"synonyms":["outstanding","superb"],"antonyms":["poor","terrible"],"tipVi":"Vì từ ''excellent'' đã mang sẵn nghĩa ''rất tốt'', thông thường ta không dùng ''very'' đi kèm trước nó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_boil', 'en-a2-36', 'boil', '/bɔɪl/', 'A2', 'sôi; làm sôi; luộc; mụn nhọt', 'v.', 'boiling (adj.), boiled (adj.), boiler (n.)', NULL, '‘boil’ chỉ hiện tượng sôi hoặc luộc; ‘simmer’ chỉ việc nấu lửa nhỏ liu riu.', 'Boil the potatoes until you can pierce them easily.', NULL, 'Luộc khoai tây cho đến khi bạn có thể dễ dàng dùng nĩa xiên qua.', '{"wordId":"boil","ukIpa":"/bɔɪl/","usIpa":"/bɔɪl/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to reach, or heat liquid until it reaches, bubbling temperature","vi":"sôi; làm sôi"},{"pos":"v.","en":"to cook food in water that is bubbling from heat","vi":"luộc"},{"pos":"n.","en":"a painful swollen lump in the skin containing pus","vi":"mụn nhọt"}],"examples":[{"en":"Boil the potatoes until you can pierce them easily.","vi":"Luộc khoai tây cho đến khi bạn có thể dễ dàng dùng nĩa xiên qua.","audioKind":"ex"},{"en":"Residents should boil drinking water when flooding has damaged local supplies and increased the risk of infection.","vi":"Cư dân nên đun sôi nước uống khi lũ lụt đã làm ô nhiễm nguồn nước địa phương và làm gia tăng nguy cơ nhiễm trùng.","audioKind":"ex2"}],"collocations":[{"en":"boil water","vi":"đun sôi nước"},{"en":"boil an egg","vi":"luộc một quả trứng"},{"en":"bring to the boil","vi":"làm cho sôi"},{"en":"boil down to","vi":"quy về; tóm lại là"}],"wordFamily":["boiling (adj.)","boiled (adj.)","boiler (n.)"],"synonyms":[],"antonyms":[],"tipVi":"‘boil’ chỉ hiện tượng sôi hoặc luộc; ‘simmer’ chỉ việc nấu lửa nhỏ liu riu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sauce', 'en-a2-36', 'sauce', '/sɔːs/', 'A2', 'nước sốt; dầu giấm; gia vị dạng lỏng', 'n.', 'saucy (adj.)', NULL, '‘sauce’ là thuật ngữ chung cho nước sốt; riêng nước tương/xì dầu gọi là ‘soy sauce’.', 'This tomato sauce tastes lovely with fresh pasta.', NULL, 'Sốt cà chua này ăn cùng mì Ý tươi rất ngon.', '{"wordId":"sauce","ukIpa":"/sɔːs/","usIpa":"/sɔːs/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A liquid or thick mixture added to food for flavour.","vi":"nước sốt; dầu giấm; gia vị dạng lỏng"}],"examples":[{"en":"This tomato sauce tastes lovely with fresh pasta.","vi":"Sốt cà chua này ăn cùng mì Ý tươi rất ngon.","audioKind":"ex"},{"en":"Preparing sauce at home allows families to control the amount of salt and sugar in their meals.","vi":"Tự làm nước sốt tại nhà giúp các gia đình kiểm soát được lượng muối và đường trong bữa ăn.","audioKind":"ex2"}],"collocations":[{"en":"tomato sauce","vi":"sốt cà chua"},{"en":"soy sauce","vi":"nước tương; xì dầu"},{"en":"pasta sauce","vi":"sốt mì Ý"},{"en":"a rich sauce","vi":"nước sốt sánh đặc"}],"wordFamily":["saucy (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"‘sauce’ là thuật ngữ chung cho nước sốt; riêng nước tương/xì dầu gọi là ‘soy sauce’.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_moustache', 'en-a2-36', 'moustache', '/ˈmʌstæʃ/', 'A2', 'rìa mép; ria mép', 'n.', 'moustached (adj.)', NULL, '‘moustache’ là phần lông mọc ở môi trên; ‘beard’ là râu quai nón hoặc râu cằm.', 'My uncle carefully trims his moustache every Sunday.', NULL, 'Chú tôi cẩn thận tỉa ria mép vào mỗi chủ nhật.', '{"wordId":"moustache","ukIpa":"/məˈstɑːʃ/","usIpa":"/ˈmʌstæʃ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Hair growing above the upper lip.","vi":"rìa mép; ria mép"}],"examples":[{"en":"My uncle carefully trims his moustache every Sunday.","vi":"Chú tôi cẩn thận tỉa ria mép vào mỗi chủ nhật.","audioKind":"ex"},{"en":"In historical portraits, a carefully styled moustache often reflected contemporary ideas about fashion and social status.","vi":"Trong các bức chân dung lịch sử, bộ ria mép được cắt tỉa cẩn thận thường phản ánh quan điểm thời bấy giờ về thời trang và địa vị xã hội.","audioKind":"ex2"}],"collocations":[{"en":"grow a moustache","vi":"để ria mép"},{"en":"trim a moustache","vi":"tỉa ria mép"},{"en":"a thick moustache","vi":"bộ ria mép rậm"}],"wordFamily":["moustached (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"‘moustache’ là phần lông mọc ở môi trên; ‘beard’ là râu quai nón hoặc râu cằm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pillow', 'en-a2-36', 'pillow', '/ˈpɪloʊ/', 'A2', 'gối', 'n.', 'pillowcase (n.)', NULL, 'pillow chủ yếu dùng khi ngủ; cushion thường chỉ đệm tựa hoặc đệm ngồi.', 'She placed a fresh pillow on the guest bed.', NULL, 'Cô ấy đặt một chiếc gối mới lên giường khách.', '{"wordId":"pillow","ukIpa":"/ˈpɪləʊ/","usIpa":"/ˈpɪloʊ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A soft support for your head when resting or sleeping.","vi":"gối"}],"examples":[{"en":"She placed a fresh pillow on the guest bed.","vi":"Cô ấy đặt một chiếc gối mới lên giường khách.","audioKind":"ex"},{"en":"Choosing a supportive pillow may improve sleep quality by helping maintain a comfortable neck position.","vi":"Chọn một chiếc gối có độ nâng đỡ tốt có thể cải thiện chất lượng giấc ngủ bằng cách giúp duy trì tư thế cổ thoải mái.","audioKind":"ex2"}],"collocations":[{"en":"soft pillow","vi":"gối mềm"},{"en":"feather pillow","vi":"gối lông vũ"},{"en":"pillow cover","vi":"vỏ gối"}],"wordFamily":["pillowcase (n.)"],"synonyms":[],"antonyms":[],"tipVi":"pillow chủ yếu dùng khi ngủ; cushion thường chỉ đệm tựa hoặc đệm ngồi.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sign', 'en-a2-36', 'sign', '/saɪn/', 'A2', 'dấu hiệu; triệu chứng; biển báo; ký hiệu; ký; ký tên; ký kết', 'n.', 'signature (n.), signatory (n.)', 'Đồng nghĩa: indication', 'Chữ g trong sign câm; a sign of đi sau với danh từ hoặc danh động từ.', 'Those dark clouds are a sign of approaching rain.', NULL, 'Những đám mây đen kia là dấu hiệu trời sắp mưa.', '{"wordId":"sign","ukIpa":"/saɪn/","usIpa":"/saɪn/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Something indicating that a condition exists or may develop","vi":"dấu hiệu; triệu chứng"},{"pos":"n.","en":"An object, mark, or gesture that communicates information","vi":"biển báo; ký hiệu; dấu hiệu"},{"pos":"v.","en":"Write your name to identify yourself or show agreement","vi":"ký; ký tên; ký kết"}],"examples":[{"en":"Those dark clouds are a sign of approaching rain.","vi":"Những đám mây đen kia là dấu hiệu trời sắp mưa.","audioKind":"ex"},{"en":"A decline in local wildlife may be a sign of wider environmental damage caused by urban expansion.","vi":"Sự sụt giảm động vật hoang dã địa phương có thể là dấu hiệu của tình trạng tàn phá môi trường rộng lớn hơn do mở rộng đô thị gây ra.","audioKind":"ex2"}],"collocations":[{"en":"a sign of improvement","vi":"dấu hiệu cải thiện"},{"en":"warning signs","vi":"biển báo cảnh báo"},{"en":"a road sign","vi":"biển báo giao thông"},{"en":"sign a contract","vi":"ký hợp đồng"}],"wordFamily":["signature (n.)","signatory (n.)"],"synonyms":["indication"],"antonyms":[],"tipVi":"Chữ g trong sign câm; a sign of đi sau với danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_36_1', 'en-a2-36', 'Cách dùng “quarter” (n.) — một phần tư (một trong bốn phần bằng nhau)', 'a quarter of  ·  a quarter of an hour  ·  the first quarter', 'a quarter of an hour là một khoảng thời gian một khắc (mười lăm phút); quarter cũng dùng để chỉ quý trong năm.', 'Họ từ (Word Family): quarterly (adj.), quarterly (adv.)', '[{"hanzi":"She cut the sandwich into quarters for the children.","pinyin":"","meaning":"Cô ấy cắt chiếc bánh mì kẹp thành bốn phần bằng nhau cho lũ trẻ."},{"hanzi":"Almost a quarter of the city''s residents depend on public transport for their daily commute.","pinyin":"","meaning":"Gần một phần tư cư dân của thành phố phụ thuộc vào giao thông công cộng cho việc đi lại hàng ngày."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_36_2', 'en-a2-36', 'Cách dùng “excellent” (adj.) — tuyệt vời; xuất sắc', 'excellent service  ·  excellent results  ·  excellent opportunity', 'Vì từ ''excellent'' đã mang sẵn nghĩa ''rất tốt'', thông thường ta không dùng ''very'' đi kèm trước nó.', 'Họ từ (Word Family): excellence (n.), excellently (adv.), excel (v.) | Đồng nghĩa: outstanding, superb · Trái nghĩa: poor, terrible', '[{"hanzi":"The soup was excellent, so I ordered another bowl.","pinyin":"","meaning":"Món súp ngon tuyệt, nên tôi đã gọi thêm một bát nữa."},{"hanzi":"Excellent public transport can reduce car dependence and make cities more accessible to all residents.","pinyin":"","meaning":"Hệ thống giao thông công cộng tuyệt vời có thể làm giảm sự phụ kiện vào ô tô và giúp mọi cư dân dễ dàng di chuyển hơn."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_36_3', 'en-a2-36', 'Cách dùng “advice” (n.) — lời khuyên; sự hướng dẫn về việc ai đó nên làm gì trong một hoàn cảnh cụ thể', 'give advice  ·  seek advice  ·  follow advice', 'Đây là danh từ không đếm được, không dùng an advice; động từ advise có phần đuôi phát âm là /z/.', 'Họ từ (Word Family): advise (v.), adviser (n.), advisory (adj.) | Đồng nghĩa: guidance', '[{"hanzi":"Your advice helped me choose a comfortable bicycle.","pinyin":"","meaning":"Lời khuyên của bạn đã giúp tôi chọn được một chiếc xe đạp thoải mái."},{"hanzi":"Schools should provide practical career advice so that students can make informed decisions about their future.","pinyin":"","meaning":"Nhà trường nên cung cấp những lời khuyên hướng nghiệp thiết thực để học sinh có thể đưa ra quyết định sáng suốt về tương lai của mình."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_36_4', 'en-a2-36', 'Cách dùng “leather” (n.) — da (đã qua xử lý để làm quần áo, túi xách và các đồ dùng khác)', 'leather jacket  ·  genuine leather  ·  leather goods', 'Thông thường là danh từ không đếm được; leather jacket có danh từ đứng trước làm bổ ngữ.', NULL, '[{"hanzi":"Her old leather bag still feels soft and smooth.","pinyin":"","meaning":"Chiếc túi da cũ của cô ấy vẫn mang lại cảm giác mềm mại và mịn màng."},{"hanzi":"Some consumers avoid leather products because they are concerned about animal welfare and the environmental impact of production.","pinyin":"","meaning":"Một số người tiêu dùng tránh mua sản phẩm da vì họ quan tâm đến phúc lợi động vật và tác động môi trường của quá trình sản xuất."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_36_1', 'en-a2-36', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_36_1_1', 'ten_a2_36_1', 'able', 'I am finally able to swim across the pool.', 'I am finally able to swim across the pool.', '/ˈeɪbəl/', 'Cuối cùng tôi đã có thể bơi qua chiều dài của bể bơi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_36_1_2', 'ten_a2_36_1', 'ham', 'I put some ham and cheese in my sandwich.', 'I put some ham and cheese in my sandwich.', '/hæm/', 'Tôi cho một ít dăm bông và phô mai vào bánh mì kẹp của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_36_1_3', 'ten_a2_36_1', 'leather', 'Her old leather bag still feels soft and smooth.', 'Her old leather bag still feels soft and smooth.', '/ˈleðər/', 'Chiếc túi da cũ của cô ấy vẫn mang lại cảm giác mềm mại và mịn màng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_36_1_4', 'ten_a2_36_1', 'toaster', 'Two slices of bread popped out of the toaster.', 'Two slices of bread popped out of the toaster.', '/ˈtoʊstər/', 'Hai lát bánh mì đã bật ra khỏi máy nướng bánh mì.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_36_1_5', 'ten_a2_36_1', 'recent', 'Have you seen any recent photos of our puppy?', 'Have you seen any recent photos of our puppy?', '/ˈriːsənt/', 'Bạn đã xem bức ảnh nào gần đây của chú cún nhà chúng ta chưa?', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_36_1_6', 'ten_a2_36_1', 'burger', 'I ordered a bean burger with salad for lunch.', 'I ordered a bean burger with salad for lunch.', '/ˈbɝːɡər/', 'Tôi gọi một chiếc bánh burger đậu kèm salad cho bữa trưa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_36_1_7', 'ten_a2_36_1', 'candle', 'He lit a candle when the electricity went off.', 'He lit a candle when the electricity went off.', '/ˈkændl/', 'Anh ấy đã thắp một cây nến khi cúp điện.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_36_1_8', 'ten_a2_36_1', 'available', 'There are still tickets available for the afternoon show.', 'There are still tickets available for the afternoon show.', '/əˈveɪləbl/', 'Vẫn còn vé cho suất chiếu buổi chiều.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_36_1_1', 'en-a2-36', 'ten_a2_36_1', 'listening', 'listening', 'I am finally able to swim across the pool.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy rưới kem tươi lên một bát dâu tây.","Hãy bấm nút màu xanh lá cây để khởi động máy giặt.","Cuối cùng tôi đã có thể bơi qua chiều dài của bể bơi.","Chúng tôi đã trò chuyện về cuối tuần của mình khi đang đợi xe buýt."]'::jsonb, 2, 'I am finally able to swim across the pool. → Cuối cùng tôi đã có thể bơi qua chiều dài của bể bơi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_36_1_2', 'en-a2-36', 'ten_a2_36_1', 'listening', 'listening', 'I put some ham and cheese in my sandwich.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc túi da cũ của cô ấy vẫn mang lại cảm giác mềm mại và mịn màng.","Cô ấy rưới kem tươi lên một bát dâu tây.","Tôi cho một ít dăm bông và phô mai vào bánh mì kẹp của mình.","Hai lát bánh mì đã bật ra khỏi máy nướng bánh mì."]'::jsonb, 2, 'I put some ham and cheese in my sandwich. → Tôi cho một ít dăm bông và phô mai vào bánh mì kẹp của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_36_1_3', 'en-a2-36', 'ten_a2_36_1', 'listening', 'listening', 'Her old leather bag still feels soft and smooth.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Những đám mây đen kia là dấu hiệu trời sắp mưa.","Tôi gọi một chiếc bánh burger đậu kèm salad cho bữa trưa.","Hãy bấm nút màu xanh lá cây để khởi động máy giặt.","Chiếc túi da cũ của cô ấy vẫn mang lại cảm giác mềm mại và mịn màng."]'::jsonb, 3, 'Her old leather bag still feels soft and smooth. → Chiếc túi da cũ của cô ấy vẫn mang lại cảm giác mềm mại và mịn màng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_36_2', 'en-a2-36', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_36_2_1', 'ten_a2_36_2', 'able', 'With reliable internet access, rural students are able to attend courses previously available only in cities.', 'With reliable internet access, rural students are able to attend courses previously available only in cities.', '/ˈeɪbəl/', 'Với kết nối internet đáng tin cậy, học sinh vùng sâu vùng xa có thể tham gia các khóa học trước đây chỉ có ở thành phố.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_36_2_2', 'ten_a2_36_2', 'ham', 'Processed meats such as ham often contain substantial amounts of salt, which consumers should consider when planning meals.', 'Processed meats such as ham often contain substantial amounts of salt, which consumers should consider when planning meals.', '/hæm/', 'Các loại thịt chế biến sẵn như dăm bông thường chứa hàm lượng muối đáng kể, mà người tiêu dùng nên cân nhắc khi lên thực đơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_36_2_3', 'ten_a2_36_2', 'leather', 'Some consumers avoid leather products because they are concerned about animal welfare and the environmental impact of production.', 'Some consumers avoid leather products because they are concerned about animal welfare and the environmental impact of production.', '/ˈleðər/', 'Một số người tiêu dùng tránh mua sản phẩm da vì họ quan tâm đến phúc lợi động vật và tác động môi trường của quá trình sản xuất.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_36_2_4', 'ten_a2_36_2', 'toaster', 'Small appliances such as toasters should be designed for easy repair rather than frequent replacement.', 'Small appliances such as toasters should be designed for easy repair rather than frequent replacement.', '/ˈtoʊstər/', 'Các thiết bị gia dụng nhỏ như máy nướng bánh mì nên được thiết kế để dễ sửa chữa thay vì phải thay mới thường xuyên.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_36_2_5', 'ten_a2_36_2', 'recent', 'Recent advances in medical technology have improved treatment options for patients living in remote communities.', 'Recent advances in medical technology have improved treatment options for patients living in remote communities.', '/ˈriːsənt/', 'Những tiến bộ gần đây trong công nghệ y tế đã cải thiện các lựa chọn điều trị cho bệnh nhân sống ở các vùng cộng đồng hẻo lánh.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_36_2_6', 'ten_a2_36_2', 'burger', 'Restaurants can reduce their environmental impact by offering plant-based burgers alongside traditional meat dishes.', 'Restaurants can reduce their environmental impact by offering plant-based burgers alongside traditional meat dishes.', '/ˈbɝːɡər/', 'Các nhà hàng có thể giảm thiểu tác động đến môi trường bằng cách phục vụ bánh burger làm từ thực vật bên cạnh các món thịt truyền thống.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_36_2_1', 'en-a2-36', 'ten_a2_36_2', 'listening', 'listening', 'With reliable internet access, rural students are able to attend courses previously available only in cities.', NULL, 'Trong câu vừa nghe, từ “able” mang nghĩa nào sau đây?', '["có thể; đủ khả năng","nhân viên lễ tân","kéo, lôi, giật","môn khúc côn cầu"]'::jsonb, 0, '“able” (/ˈeɪbəl/): có thể; đủ khả năng. Câu đầy đủ: With reliable internet access, rural students are able to attend courses previously available only in cities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_36_2_2', 'en-a2-36', 'ten_a2_36_2', 'listening', 'listening', 'Processed meats such as ham often contain substantial amounts of salt, which consumers should consider when planning meals.', NULL, 'Trong câu vừa nghe, từ “ham” mang nghĩa nào sau đây?', '["việc gia nhập; việc tham gia","sân ga; thềm nhà ga","thẻ lên máy bay; giấy lên máy bay","thịt dăm bông; thịt lợn xông khói"]'::jsonb, 3, '“ham” (/hæm/): thịt dăm bông; thịt lợn xông khói. Câu đầy đủ: Processed meats such as ham often contain substantial amounts of salt, which consumers should consider when planning meals.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
