INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_36_1', 'en-a2-36', NULL, 'comprehensive_test', 'listening', 'able', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["ốm; không khỏe","bản báo cáo; tường thuật","tiệm bánh; lò bánh mì","có thể; đủ khả năng"]'::jsonb, 3, 'able (/ˈeɪbəl/) → có thể; đủ khả năng; có tài năng; giỏi giang', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_36_2', 'en-a2-36', NULL, 'comprehensive_test', 'listening', 'I put some ham and cheese in my sandwich.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Vẫn còn vé cho suất chiếu buổi chiều.","Cô ấy rưới kem tươi lên một bát dâu tây.","Chú tôi cẩn thận tỉa ria mép vào mỗi chủ nhật.","Tôi cho một ít dăm bông và phô mai vào bánh mì kẹp của mình."]'::jsonb, 3, 'I put some ham and cheese in my sandwich. → Tôi cho một ít dăm bông và phô mai vào bánh mì kẹp của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_36_3', 'en-a2-36', NULL, 'comprehensive_test', 'listening', 'leather', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trang chủ (của một trang web)","da (đã qua xử lý để làm quần áo, túi xách và các đồ dùng khác)","phóng viên; nhà báo","bức vẽ; bức phác họa"]'::jsonb, 1, 'leather (/ˈleðər/) → da (đã qua xử lý để làm quần áo, túi xách và các đồ dùng khác)', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_36_4', 'en-a2-36', NULL, 'comprehensive_test', 'listening', 'Two slices of bread popped out of the toaster.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đặt một chiếc gối mới lên giường khách.","Luộc khoai tây cho đến khi bạn có thể dễ dàng dùng nĩa xiên qua.","Quả cam lăn khỏi mặt bàn và chui xuống dưới ghế của tôi.","Hai lát bánh mì đã bật ra khỏi máy nướng bánh mì."]'::jsonb, 3, 'Two slices of bread popped out of the toaster. → Hai lát bánh mì đã bật ra khỏi máy nướng bánh mì.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_36_5', 'en-a2-36', NULL, 'comprehensive_test', 'listening', 'recent', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["y tá; điều dưỡng viên","gần đây; mới đây","thủ tục trả phòng; việc thanh toán và rời khách sạn","thuộc về"]'::jsonb, 1, 'recent (/ˈriːsənt/) → gần đây; mới đây', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_36_6', 'en-a2-36', NULL, 'comprehensive_test', 'listening', 'I ordered a bean burger with salad for lunch.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Củ cà rốt này có hình dáng kỳ lạ, giống như một bàn tay nhỏ.","Cô ấy cắt chiếc bánh mì kẹp thành bốn phần bằng nhau cho lũ trẻ.","Tôi gọi một chiếc bánh burger đậu kèm salad cho bữa trưa.","Vẫn còn vé cho suất chiếu buổi chiều."]'::jsonb, 2, 'I ordered a bean burger with salad for lunch. → Tôi gọi một chiếc bánh burger đậu kèm salad cho bữa trưa.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_36_7', 'en-a2-36', NULL, 'comprehensive_test', 'listening', 'candle', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["Bristol (một thành phố ở phía tây nam nước Anh)","vai; bả vai","cho ăn; ăn","cây nến; ngọn nến"]'::jsonb, 3, 'candle (/ˈkændl/) → cây nến; ngọn nến', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
