INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_36_18', 'en-a2-36', NULL, 'comprehensive_test', 'reading', NULL, 'With reliable internet access, rural students are able to attend courses previously available only in cities.', 'Dựa vào câu trên, từ “able” có nghĩa phù hợp nhất là gì?', '["tai nghe","có thể; đủ khả năng","lễ cưới; đám cưới","căn tin; nhà ăn"]'::jsonb, 1, 'able: có thể; đủ khả năng; có tài năng; giỏi giang. Dịch cả câu: Với kết nối internet đáng tin cậy, học sinh vùng sâu vùng xa có thể tham gia các khóa học trước đây chỉ có ở thành phố.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_36_19', 'en-a2-36', NULL, 'comprehensive_test', 'reading', NULL, 'Processed meats such as ham often contain substantial amounts of salt, which consumers should consider when planning meals.', 'Dựa vào câu trên, từ “ham” có nghĩa phù hợp nhất là gì?', '["cuộc hẹn; sự hẹn gặp","chúng tôi (chính mình); chúng ta (chính mình)","thịt dăm bông; thịt lợn xông khói","nửa đêm; mười hai giờ đêm"]'::jsonb, 2, 'ham: thịt dăm bông; thịt lợn xông khói. Dịch cả câu: Các loại thịt chế biến sẵn như dăm bông thường chứa hàm lượng muối đáng kể, mà người tiêu dùng nên cân nhắc khi lên thực đơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_36_20', 'en-a2-36', NULL, 'comprehensive_test', 'reading', NULL, 'Some consumers avoid leather products because they are concerned about animal welfare and the environmental impact of production.', 'Dựa vào câu trên, từ “leather” có nghĩa phù hợp nhất là gì?', '["da (đã qua xử lý để làm quần áo, túi xách và các đồ dùng khác)","sự nghiệp, quá trình làm việc của một người thường trong một ngành nghề cụ thể","từ (một thời điểm trong quá khứ) cho đến nay","sự luyện tập; sự rèn luyện"]'::jsonb, 0, 'leather: da (đã qua xử lý để làm quần áo, túi xách và các đồ dùng khác). Dịch cả câu: Một số người tiêu dùng tránh mua sản phẩm da vì họ quan tâm đến phúc lợi động vật và tác động môi trường của quá trình sản xuất.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_36_21', 'en-a2-36', NULL, 'comprehensive_test', 'reading', NULL, 'Small appliances such as toasters should be designed for easy repair rather than frequent replacement.', 'Dựa vào câu trên, từ “toaster” có nghĩa phù hợp nhất là gì?', '["căn tin; nhà ăn","đồng euro","xương","máy nướng bánh mì"]'::jsonb, 3, 'toaster: máy nướng bánh mì. Dịch cả câu: Các thiết bị gia dụng nhỏ như máy nướng bánh mì nên được thiết kế để dễ sửa chữa thay vì phải thay mới thường xuyên.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_36_22', 'en-a2-36', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “rìa mép; ria mép”', '["God","moustache","palace","grandson"]'::jsonb, 1, 'rìa mép; ria mép → moustache (/ˈmʌstæʃ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_36_23', 'en-a2-36', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “gối”', '["diary","project","reply","pillow"]'::jsonb, 3, 'gối → pillow (/ˈpɪloʊ/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_36_24', 'en-a2-36', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “dấu hiệu; triệu chứng”', '["metal","sign","happily","soldier"]'::jsonb, 1, 'dấu hiệu; triệu chứng → sign (/saɪn/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-37', 'en', 'Bài 37: Đời sống hằng ngày (9) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '26 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2037, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hang', 'en-a2-37', 'hang', '/hæŋ/', 'A2', 'treo; mắc; lơ lửng; rủ xuống; thõng xuống', 'v.', 'hanger (n.), hanging (adj.)', 'Đồng nghĩa: suspend, dangle', 'Quá khứ và phân từ hai của treo là hung; nếu nghĩa là treo cổ tử hình thì dùng hanged.', 'Please hang your wet coat beside the front door.', NULL, 'Làm ơn treo chiếc áo khoác ướt của bạn cạnh cửa trước.', '{"wordId":"hang","ukIpa":"/hæŋ/","usIpa":"/hæŋ/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"attach something above the ground, or remain suspended","vi":"treo; mắc; lơ lửng"},{"pos":"v.","en":"fall or bend downwards loosely","vi":"rủ xuống; thõng xuống"}],"examples":[{"en":"Please hang your wet coat beside the front door.","vi":"Làm ơn treo chiếc áo khoác ướt của bạn cạnh cửa trước.","audioKind":"ex"},{"en":"Museums often hang paintings at different heights to make their collections accessible to visitors of all ages.","vi":"Các bảo tàng thường treo các bức tranh ở độ cao khác nhau để khách tham quan mọi lứa tuổi đều có thể ngắm nhìn bộ sưu tập.","audioKind":"ex2"}],"collocations":[{"en":"hang a picture","vi":"treo một bức tranh"},{"en":"hang on a wall","vi":"treo lên tường"},{"en":"hang your head","vi":"cúi đầu"},{"en":"hang out the washing","vi":"phơi quần áo"}],"wordFamily":["hanger (n.)","hanging (adj.)"],"synonyms":["suspend","dangle"],"antonyms":[],"tipVi":"Quá khứ và phân từ hai của treo là hung; nếu nghĩa là treo cổ tử hình thì dùng hanged.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_especially', 'en-a2-37', 'especially', '/ɪˈspeʃəli/', 'A2', 'đặc biệt; nhất là', 'adv.', 'especial (adj.)', 'Đồng nghĩa: particularly, notably', 'especially nhấn mạnh ý nghĩa "đặc biệt"; specially thường chỉ "một cách chuyên biệt, dành riêng".', 'I enjoy cooking, especially when friends come for dinner.', NULL, 'Tôi thích nấu ăn, nhất là khi có bạn bè đến ăn tối.', '{"wordId":"especially","ukIpa":"/ɪˈspeʃəli/","usIpa":"/ɪˈspeʃəli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"more than usual, or more than other people or things","vi":"đặc biệt; nhất là"}],"examples":[{"en":"I enjoy cooking, especially when friends come for dinner.","vi":"Tôi thích nấu ăn, nhất là khi có bạn bè đến ăn tối.","audioKind":"ex"},{"en":"Reliable public transport is especially important for residents who cannot afford to own a car.","vi":"Hệ thống giao thông công cộng đáng tin cậy đặc biệt quan trọng đối với những cư dân không đủ khả năng sở hữu ô tô.","audioKind":"ex2"}],"collocations":[{"en":"especially important","vi":"đặc biệt quan trọng"},{"en":"especially useful","vi":"đặc biệt hữu ích"},{"en":"especially for","vi":"đặc biệt là dành cho"}],"wordFamily":["especial (adj.)"],"synonyms":["particularly","notably"],"antonyms":[],"tipVi":"especially nhấn mạnh ý nghĩa \"đặc biệt\"; specially thường chỉ \"một cách chuyên biệt, dành riêng\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_super', 'en-a2-37', 'super', '/ˈsuːpər/', 'A2', 'tuyệt vời; cực kỳ thú vị; rất; cực kỳ', 'adj.', NULL, 'Đồng nghĩa: great, excellent · Trái nghĩa: terrible', 'Mang sắc thái khẩu ngữ mạnh; trong văn viết trang trọng nên dùng excellent hoặc very.', 'We had a super afternoon playing games in the garden.', NULL, 'Chúng tôi đã có một buổi chiều tuyệt vời chơi đùa trong vườn.', '{"wordId":"super","ukIpa":"/ˈsuːpə/","usIpa":"/ˈsuːpər/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Extremely good or enjoyable, used informally.","vi":"tuyệt vời; cực kỳ thú vị"},{"pos":"adv.","en":"Very or extremely, used informally before adjectives or adverbs.","vi":"rất; cực kỳ"}],"examples":[{"en":"We had a super afternoon playing games in the garden.","vi":"Chúng tôi đã có một buổi chiều tuyệt vời chơi đùa trong vườn.","audioKind":"ex"},{"en":"Although users may describe an app as super helpful, researchers need objective evidence to assess its educational value.","vi":"Mặc dù người dùng có thể mô tả một ứng dụng là cực kỳ hữu ích, các nhà nghiên cứu vẫn cần những bằng chứng khách quan để đánh giá giá trị giáo dục của nó.","audioKind":"ex2"}],"collocations":[{"en":"a super idea","vi":"một ý tưởng tuyệt vời"},{"en":"super helpful","vi":"cực kỳ hữu ích"},{"en":"super easy","vi":"vô cùng dễ dàng"}],"wordFamily":[],"synonyms":["great","excellent"],"antonyms":["terrible"],"tipVi":"Mang sắc thái khẩu ngữ mạnh; trong văn viết trang trọng nên dùng excellent hoặc very.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_heat', 'en-a2-37', 'heat', '/hiːt/', 'A2', 'hơi nóng; sức nóng; làm nóng; đun nóng; vòng loại; trận sơ khảo', 'n.', 'heater (n.), heating (n.), heated (adj.)', 'Đồng nghĩa: warmth · Trái nghĩa: cold', 'heat là danh từ chỉ sức nóng, hot là tính từ chỉ trạng thái nóng.', 'We rested under a tree to escape the heat.', NULL, 'Chúng tôi nghỉ ngơi dưới gốc cây để tránh cái nắng gay gắt.', '{"wordId":"heat","ukIpa":"/hiːt/","usIpa":"/hiːt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"warmth or a high temperature","vi":"hơi nóng; sức nóng"},{"pos":"v.","en":"to make or become warmer","vi":"làm nóng; đun nóng"},{"pos":"n.","en":"a race that decides who enters the next round","vi":"vòng loại; trận sơ khảo"}],"examples":[{"en":"We rested under a tree to escape the heat.","vi":"Chúng tôi nghỉ ngơi dưới gốc cây để tránh cái nắng gay gắt.","audioKind":"ex"},{"en":"Cities can reduce extreme heat by planting trees and replacing dark surfaces with materials that reflect sunlight.","vi":"Các thành phố có thể giảm bớt tình trạng nắng nóng gay gắt bằng cách trồng cây xanh và thay thế các bề mặt tối màu bằng vật liệu phản chiếu ánh sáng mặt trời.","audioKind":"ex2"}],"collocations":[{"en":"extreme heat","vi":"nắng nóng gay gắt"},{"en":"heat loss","vi":"sự thất thoát nhiệt"},{"en":"heat up food","vi":"hâm nóng thức ăn"},{"en":"a qualifying heat","vi":"một trận đấu vòng loại"}],"wordFamily":["heater (n.)","heating (n.)","heated (adj.)"],"synonyms":["warmth"],"antonyms":["cold"],"tipVi":"heat là danh từ chỉ sức nóng, hot là tính từ chỉ trạng thái nóng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lunchtime', 'en-a2-37', 'lunchtime', '/ˈlʌntʃtaɪm/', 'A2', 'giờ ăn trưa; thời gian ăn trưa', 'n.', 'lunch (n.)', NULL, 'Biểu thị "trong giờ ăn trưa" thường dùng at lunchtime.', 'At lunchtime, we sat outside and shared some sandwiches.', NULL, 'Vào giờ ăn trưa, chúng tôi ngồi ngoài trời và chia nhau vài chiếc bánh mì kẹp.', '{"wordId":"lunchtime","ukIpa":"/ˈlʌntʃtaɪm/","usIpa":"/ˈlʌntʃtaɪm/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"The time around the middle of the day when people eat.","vi":"giờ ăn trưa; thời gian ăn trưa"}],"examples":[{"en":"At lunchtime, we sat outside and shared some sandwiches.","vi":"Vào giờ ăn trưa, chúng tôi ngồi ngoài trời và chia nhau vài chiếc bánh mì kẹp.","audioKind":"ex"},{"en":"Providing quiet spaces at lunchtime may help employees relax and return to work with greater focus.","vi":"Việc cung cấp không gian yên tĩnh vào giờ ăn trưa có thể giúp nhân viên thư giãn và quay lại làm việc với sự tập trung cao hơn.","audioKind":"ex2"}],"collocations":[{"en":"at lunchtime","vi":"vào giờ ăn trưa"},{"en":"a lunchtime walk","vi":"chuyến tản bộ giờ ăn trưa"},{"en":"a lunchtime break","vi":"giờ nghỉ trưa"}],"wordFamily":["lunch (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Biểu thị \"trong giờ ăn trưa\" thường dùng at lunchtime.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cucumber', 'en-a2-37', 'cucumber', '/ˈkjuːkʌmbər/', 'A2', 'quả dưa chuột; trái dưa leo', 'n.', NULL, NULL, 'Thông thường là danh từ đếm được: a cucumber; khi chỉ nguyên liệu nấu ăn cũng có thể dùng như danh từ không đếm được.', 'She sliced a cucumber and added it to the salad.', NULL, 'Cô ấy thái dưa chuột thành lát rồi cho vào món xà lách.', '{"wordId":"cucumber","ukIpa":"/ˈkjuːkʌmbə/","usIpa":"/ˈkjuːkʌmbər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A long vegetable with green skin and crisp, watery flesh.","vi":"quả dưa chuột; trái dưa leo"}],"examples":[{"en":"She sliced a cucumber and added it to the salad.","vi":"Cô ấy thái dưa chuột thành lát rồi cho vào món xà lách.","audioKind":"ex"},{"en":"Growing cucumbers in greenhouses can provide a reliable food supply, but heating these structures requires energy.","vi":"Việc trồng dưa chuột trong nhà kính có thể cung cấp nguồn lương thực ổn định, nhưng việc sưởi ấm các cấu trúc này tiêu tốn năng lượng.","audioKind":"ex2"}],"collocations":[{"en":"sliced cucumber","vi":"dưa chuột thái lát"},{"en":"cucumber salad","vi":"món xà lách dưa chuột"},{"en":"as cool as a cucumber","vi":"bình tĩnh; điềm tĩnh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thông thường là danh từ đếm được: a cucumber; khi chỉ nguyên liệu nấu ăn cũng có thể dùng như danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_whose', 'en-a2-37', 'whose', '/huːz/', 'A2', 'của ai; cái của ai', 'det.', 'who (pron.), whom (pron.)', NULL, '"Whose" biểu thị quyền sở hữu; trong khi "who’s" là dạng viết tắt của "who is" hoặc "who has".', 'Whose umbrella is dripping water all over the floor?', NULL, 'Cái ô của ai mà nhỏ nước ướt sũng cả sàn nhà thế này?', '{"wordId":"whose","ukIpa":"/huːz/","usIpa":"/huːz/","cefr":"A2","topic":"daily","senses":[{"pos":"det.","en":"used before a noun to ask or show who owns something","vi":"của ai"},{"pos":"pron.","en":"used to ask who something belongs to","vi":"cái của ai"}],"examples":[{"en":"Whose umbrella is dripping water all over the floor?","vi":"Cái ô của ai mà nhỏ nước ướt sũng cả sàn nhà thế này?","audioKind":"ex"},{"en":"Children whose parents read regularly at home may develop a stronger interest in books.","vi":"Những đứa trẻ có cha mẹ thường xuyên đọc sách ở nhà có thể phát triển sở thích đọc sách mạnh mẽ hơn.","audioKind":"ex2"}],"collocations":[{"en":"whose turn","vi":"đến lượt ai"},{"en":"whose idea","vi":"ý kiến của ai"},{"en":"whose responsibility","vi":"trách nhiệm của ai"}],"wordFamily":["who (pron.)","whom (pron.)"],"synonyms":[],"antonyms":[],"tipVi":"\"Whose\" biểu thị quyền sở hữu; trong khi \"who’s\" là dạng viết tắt của \"who is\" hoặc \"who has\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bacon', 'en-a2-37', 'bacon', '/ˈbeɪkən/', 'A2', 'thịt xông khói; thịt lợn muối xông khói', 'n.', NULL, NULL, 'Danh từ này thường không đếm được; khi muốn chỉ một phần, dùng "a slice of bacon".', 'He cooked bacon and eggs for breakfast on Sunday.', NULL, 'Anh ấy đã nấu thịt xông khói và trứng cho bữa sáng vào Chủ nhật.', '{"wordId":"bacon","ukIpa":"/ˈbeɪkən/","usIpa":"/ˈbeɪkən/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"salted or smoked pork, usually served in thin slices","vi":"thịt xông khói; thịt lợn muối xông khói"}],"examples":[{"en":"He cooked bacon and eggs for breakfast on Sunday.","vi":"Anh ấy đã nấu thịt xông khói và trứng cho bữa sáng vào Chủ nhật.","audioKind":"ex"},{"en":"Reducing consumption of processed meat, including bacon, is often recommended as part of a healthier diet.","vi":"Việc giảm tiêu thụ thịt chế biến sẵn, bao gồm cả thịt xông khói, thường được khuyến nghị như một phần của chế độ ăn uống lành mạnh hơn.","audioKind":"ex2"}],"collocations":[{"en":"a slice of bacon","vi":"một lát thịt xông khói"},{"en":"crispy bacon","vi":"thịt xông khói giòn"},{"en":"bacon and eggs","vi":"thịt xông khói ăn kèm trứng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Danh từ này thường không đếm được; khi muốn chỉ một phần, dùng \"a slice of bacon\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_matter', 'en-a2-37', 'matter', '/ˈmætər/', 'A2', 'vấn đề; việc; quan trọng; có ý nghĩa; chất; vật chất', 'n.', NULL, NULL, 'Khi chỉ sự việc thường đếm được; khi chỉ vật chất là không đếm được; đóng vai trò động từ biểu thị sự quan trọng.', 'We can discuss this matter after lunch today.', NULL, 'Chúng ta có thể thảo luận vấn đề này sau bữa trưa hôm nay.', '{"wordId":"matter","ukIpa":"/ˈmætə/","usIpa":"/ˈmætər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a subject, situation or problem needing thought or attention","vi":"vấn đề; việc"},{"pos":"v.","en":"to be important or make a difference","vi":"quan trọng; có ý nghĩa"},{"pos":"n.","en":"physical substance that occupies space and has mass","vi":"chất; vật chất"}],"examples":[{"en":"We can discuss this matter after lunch today.","vi":"Chúng ta có thể thảo luận vấn đề này sau bữa trưa hôm nay.","audioKind":"ex"},{"en":"The quality of teaching matters more than expensive equipment when schools aim to improve student achievement.","vi":"Chất lượng giảng dạy quan trọng hơn thiết bị đắt tiền khi các trường học hướng tới mục tiêu nâng cao thành tích của học sinh.","audioKind":"ex2"}],"collocations":[{"en":"a serious matter","vi":"một vấn đề nghiêm trọng"},{"en":"a matter of time","vi":"chỉ là vấn đề thời gian"},{"en":"organic matter","vi":"chất hữu cơ"},{"en":"it doesn''t matter","vi":"không có gì quan trọng (không sao cả)"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ sự việc thường đếm được; khi chỉ vật chất là không đếm được; đóng vai trò động từ biểu thị sự quan trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_midday', 'en-a2-37', 'midday', '/ˌmɪdˈdeɪ/', 'A2', 'trưa; chính ngọ', 'n.', NULL, 'Đồng nghĩa: noon · Trái nghĩa: midnight', 'Dùng giới từ at trước thời gian; cũng có thể đặt trước danh từ như midday sun.', 'We stopped for a picnic beside the lake at midday.', NULL, 'Chúng tôi dừng lại để dã ngoại bên hồ vào giữa trưa.', '{"wordId":"midday","ukIpa":"/ˌmɪdˈdeɪ/","usIpa":"/ˌmɪdˈdeɪ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"the middle of the day, around twelve o''clock","vi":"trưa; chính ngọ"}],"examples":[{"en":"We stopped for a picnic beside the lake at midday.","vi":"Chúng tôi dừng lại để dã ngoại bên hồ vào giữa trưa.","audioKind":"ex"},{"en":"Outdoor workers should avoid direct sunlight around midday to reduce the risk of heat exhaustion.","vi":"Những người làm việc ngoài trời nên tránh ánh nắng trực tiếp vào khoảng giữa trưa để giảm nguy cơ kiệt sức vì nóng.","audioKind":"ex2"}],"collocations":[{"en":"at midday","vi":"vào giữa trưa"},{"en":"around midday","vi":"khoảng giữa trưa"},{"en":"the midday sun","vi":"nắng giữa trưa"}],"wordFamily":[],"synonyms":["noon"],"antonyms":["midnight"],"tipVi":"Dùng giới từ at trước thời gian; cũng có thể đặt trước danh từ như midday sun.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bookshelf', 'en-a2-37', 'bookshelf', '/ˈbʊkʃelf/', 'A2', 'giá sách; kệ sách', 'n.', 'shelf (n.)', NULL, 'Dạng số nhiều là bookshelves, chú ý đổi f thành ves.', 'She placed her favourite novel on the wooden bookshelf.', NULL, 'Cô ấy đặt cuốn tiểu thuyết yêu thích của mình lên chiếc giá sách bằng gỗ.', '{"wordId":"bookshelf","ukIpa":"/ˈbʊkʃelf/","usIpa":"/ˈbʊkʃelf/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a shelf used for storing books","vi":"giá sách; kệ sách"}],"examples":[{"en":"She placed her favourite novel on the wooden bookshelf.","vi":"Cô ấy đặt cuốn tiểu thuyết yêu thích của mình lên chiếc giá sách bằng gỗ.","audioKind":"ex"},{"en":"A well-stocked bookshelf in every classroom can encourage children to explore subjects beyond the school curriculum.","vi":"Một chiếc giá sách được trang bị đầy đủ sách trong mỗi lớp học có thể khuyến khích trẻ em khám phá các chủ đề ngoài chương trình học ở trường.","audioKind":"ex2"}],"collocations":[{"en":"a wooden bookshelf","vi":"giá sách bằng gỗ"},{"en":"on the bookshelf","vi":"trên giá sách"},{"en":"a well-stocked bookshelf","vi":"giá sách phong phú đầu sách"}],"wordFamily":["shelf (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều là bookshelves, chú ý đổi f thành ves.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_attractive', 'en-a2-37', 'attractive', '/əˈtræktɪv/', 'A2', 'hấp dẫn; đẹp mắt; thu hút; có sức hút; hấp dẫn (mang lại lợi ích, hứng thú)', 'adj.', 'attract (v.), attraction (n.), attractively (adv.), attractiveness (n.)', 'Đồng nghĩa: appealing, lovely · Trái nghĩa: unattractive, unappealing', 'Có thể dùng để miêu tả ngoại hình đẹp, hoặc các phương án, mức lương hấp dẫn.', 'The garden looks especially attractive when the roses bloom.', NULL, 'Khu vườn trông đặc biệt hấp dẫn khi những bông hồng nở rộ.', '{"wordId":"attractive","ukIpa":"/əˈtræktɪv/","usIpa":"/əˈtræktɪv/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Pleasant to look at","vi":"hấp dẫn; đẹp mắt; thu hút"},{"pos":"adj.","en":"Having qualities that make people interested in choosing something","vi":"có sức hút; hấp dẫn (mang lại lợi ích, hứng thú)"}],"examples":[{"en":"The garden looks especially attractive when the roses bloom.","vi":"Khu vườn trông đặc biệt hấp dẫn khi những bông hồng nở rộ.","audioKind":"ex"},{"en":"Flexible working hours make teaching a more attractive career option for some university graduates.","vi":"Thời gian làm việc linh hoạt khiến nghề dạy học trở thành lựa chọn nghề nghiệp hấp dẫn hơn đối với một số cử nhân đại học.","audioKind":"ex2"}],"collocations":[{"en":"an attractive appearance","vi":"ngoại hình thu hút"},{"en":"an attractive salary","vi":"mức lương hấp dẫn"},{"en":"an attractive option","vi":"một lựa chọn hấp dẫn"},{"en":"attractive to visitors","vi":"hấp dẫn đối với du khách"}],"wordFamily":["attract (v.)","attraction (n.)","attractively (adv.)","attractiveness (n.)"],"synonyms":["appealing","lovely"],"antonyms":["unattractive","unappealing"],"tipVi":"Có thể dùng để miêu tả ngoại hình đẹp, hoặc các phương án, mức lương hấp dẫn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_finally', 'en-a2-37', 'finally', '/ˈfaɪnəli/', 'A2', 'cuối cùng; sau cùng (sau một thời gian dài chờ đợi hoặc nỗ lực); cuối cùng (dùng để mở đầu ý cuối hoặc bước cuối cùng)', 'adv.', 'final (adj.), finality (n.), finalise (v.)', 'Đồng nghĩa: eventually, at last, lastly', 'Biểu thị sự việc xảy ra sau cùng thường đứng trước động từ thường; dùng để dẫn dắt ý cuối thường đứng đầu câu.', 'After searching all morning, I finally found my keys.', NULL, 'Sau khi tìm kiếm suốt cả buổi sáng, cuối cùng tôi cũng tìm thấy chìa khóa của mình.', '{"wordId":"finally","ukIpa":"/ˈfaɪnəli/","usIpa":"/ˈfaɪnəli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"After a long wait, delay, or effort.","vi":"cuối cùng; sau cùng (sau một thời gian dài chờ đợi hoặc nỗ lực)"},{"pos":"adv.","en":"Used to introduce the last point or action.","vi":"cuối cùng (dùng để mở đầu ý cuối hoặc bước cuối cùng)"}],"examples":[{"en":"After searching all morning, I finally found my keys.","vi":"Sau khi tìm kiếm suốt cả buổi sáng, cuối cùng tôi cũng tìm thấy chìa khóa của mình.","audioKind":"ex"},{"en":"Finally, governments should invest in reliable public transport to reduce traffic congestion and urban air pollution.","vi":"Cuối cùng, chính phủ nên đầu tư vào hệ thống giao thông công cộng đáng tin cậy để giảm thiểu tình trạng ùn tắc giao thông và ô nhiễm không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"finally arrive","vi":"cuối cùng đến nơi"},{"en":"finally succeed","vi":"cuối cùng thành công"},{"en":"finally agree","vi":"cuối cùng đồng ý"}],"wordFamily":["final (adj.)","finality (n.)","finalise (v.)"],"synonyms":["eventually","at last","lastly"],"antonyms":[],"tipVi":"Biểu thị sự việc xảy ra sau cùng thường đứng trước động từ thường; dùng để dẫn dắt ý cuối thường đứng đầu câu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_doll', 'en-a2-37', 'doll', '/dɑːl/', 'A2', 'búp bê; con rối', 'n.', NULL, NULL, 'Thường chỉ đồ chơi hình người; dùng từ này để gọi phụ nữ có thể mang hàm ý khiếm nhã.', 'My little cousin tucked her doll into a tiny bed.', NULL, 'Cô em họ nhỏ của tôi đã ôm búp bê vào chiếc giường bé xíu.', '{"wordId":"doll","ukIpa":"/dɒl/","usIpa":"/dɑːl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A toy shaped like a person.","vi":"búp bê; con rối"}],"examples":[{"en":"My little cousin tucked her doll into a tiny bed.","vi":"Cô em họ nhỏ của tôi đã ôm búp bê vào chiếc giường bé xíu.","audioKind":"ex"},{"en":"Playing with dolls can help young children develop communication skills and explore different social roles.","vi":"Chơi búp bê có thể giúp trẻ nhỏ phát triển kỹ năng giao tiếp và khám phá các vai trò xã hội khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"a rag doll","vi":"búp bê vải"},{"en":"play with dolls","vi":"chơi búp bê"},{"en":"a doll''s house","vi":"nhà búp bê"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ đồ chơi hình người; dùng từ này để gọi phụ nữ có thể mang hàm ý khiếm nhã.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_excuse', 'en-a2-37', 'excuse', '/ɪkˈskjuːs/', 'A2', 'lý do; lời bào chữa; cái cớ; tha thứ; xá tội; miễn chấp; cho phép miễn làm (nhiệm vụ) hoặc cho phép rời đi', 'n.', 'excusable (adj.), inexcusable (adj.)', NULL, 'Danh từ phát âm tận cùng là /s/, động từ phát âm là /z/; excuse me dùng khi muốn ngắt lời lịch sự.', 'He made an excuse for arriving late to dinner.', NULL, 'Anh ấy viện lý do cho việc đến bữa tối muộn.', '{"wordId":"excuse","ukIpa":"/ɪkˈskjuːs/","usIpa":"/ɪkˈskjuːs/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a reason given to explain or defend a fault","vi":"lý do; lời bào chữa; cái cớ"},{"pos":"v.","en":"forgive someone for a mistake or impolite behaviour","vi":"tha thứ; xá tội; miễn chấp"},{"pos":"v.","en":"allow someone to avoid a duty or leave","vi":"cho phép miễn làm (nhiệm vụ) hoặc cho phép rời đi"}],"examples":[{"en":"He made an excuse for arriving late to dinner.","vi":"Anh ấy viện lý do cho việc đến bữa tối muộn.","audioKind":"ex"},{"en":"Limited funding should not become an excuse for neglecting essential maintenance in schools and public hospitals.","vi":"Nguồn kinh phí hạn hẹp không nên trở thành cái cớ để lơ là việc bảo trì thiết yếu tại các trường học và bệnh viện công.","audioKind":"ex2"}],"collocations":[{"en":"make an excuse","vi":"viện lý do; tìm cớ"},{"en":"an excuse for","vi":"lý do cho"},{"en":"excuse me","vi":"xin lỗi; làm ơn cho qua"},{"en":"excuse someone from","vi":"chuẩn y cho ai miễn việc gì"}],"wordFamily":["excusable (adj.)","inexcusable (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ phát âm tận cùng là /s/, động từ phát âm là /z/; excuse me dùng khi muốn ngắt lời lịch sự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_thick', 'en-a2-37', 'thick', '/θɪk/', 'A2', 'dày; đậm (khoảng cách giữa hai bề mặt lớn); dày đặc; mù mịt; đậm đặc; đặc sệt; sền sệt', 'adj.', 'thickness (n.), thicken (v.), thickly (adv.)', 'Trái nghĩa: thin', 'Khi dùng cho chất lỏng nghĩa là đặc sệt, không nhất thiết là đậm vị.', 'She wrapped a thick blanket around her cold shoulders.', NULL, 'Cô ấy quấn một chiếc chăn dày quanh đôi vai lạnh giá của mình.', '{"wordId":"thick","ukIpa":"/θɪk/","usIpa":"/θɪk/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"having a large distance between opposite surfaces","vi":"dày; đậm (khoảng cách giữa hai bề mặt lớn)"},{"pos":"adj.","en":"having many things close together or being difficult to see through","vi":"dày đặc; mù mịt; đậm đặc"},{"pos":"adj.","en":"flowing slowly rather than easily, like heavy cream","vi":"đặc sệt; sền sệt"}],"examples":[{"en":"She wrapped a thick blanket around her cold shoulders.","vi":"Cô ấy quấn một chiếc chăn dày quanh đôi vai lạnh giá của mình.","audioKind":"ex"},{"en":"Thick layers of insulation can reduce heat loss and lower household energy bills during winter.","vi":"Các lớp cách nhiệt dày có thể làm giảm thất thoát nhiệt và hạ thấp hóa đơn tiền điện trong gia đình vào mùa đông.","audioKind":"ex2"}],"collocations":[{"en":"thick fog","vi":"sương mù dày đặc"},{"en":"thick hair","vi":"mái tóc dày"},{"en":"thick soup","vi":"súp đặc"},{"en":"thick layer","vi":"lớp dày"}],"wordFamily":["thickness (n.)","thicken (v.)","thickly (adv.)"],"synonyms":[],"antonyms":["thin"],"tipVi":"Khi dùng cho chất lỏng nghĩa là đặc sệt, không nhất thiết là đậm vị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kilo', 'en-a2-37', 'kilo', '/ˈkiːloʊ/', 'A2', 'ki-lô-gam; ký (đơn vị đo khối lượng)', 'n.', 'kilogram (n.)', 'Đồng nghĩa: kilogram', 'Kilo thường là từ viết tắt của kilogram, không dùng để chỉ kilômét (đơn vị đo khoảng cách).', 'Could I have half a kilo of tomatoes, please?', NULL, 'Cho tôi mua nửa cân cà chua được không?', '{"wordId":"kilo","ukIpa":"/ˈkiːləʊ/","usIpa":"/ˈkiːloʊ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A kilogram, a unit used to measure mass.","vi":"ki-lô-gam; ký (đơn vị đo khối lượng)"}],"examples":[{"en":"Could I have half a kilo of tomatoes, please?","vi":"Cho tôi mua nửa cân cà chua được không?","audioKind":"ex"},{"en":"Comparing food prices per kilo can help households manage their budgets and make more economical purchasing decisions.","vi":"Việc so sánh giá thực phẩm theo ký giúp các gia đình quản lý ngân sách và đưa ra quyết định mua sắm tiết kiệm hơn.","audioKind":"ex2"}],"collocations":[{"en":"half a kilo","vi":"nửa cân; nửa ký"},{"en":"a kilo of rice","vi":"một ký gạo"},{"en":"per kilo","vi":"mỗi ký; mỗi ki-lô-gam"}],"wordFamily":["kilogram (n.)"],"synonyms":["kilogram"],"antonyms":[],"tipVi":"Kilo thường là từ viết tắt của kilogram, không dùng để chỉ kilômét (đơn vị đo khoảng cách).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dustbin', 'en-a2-37', 'dustbin', '/ˈdʌstbɪn/', 'A2', 'thùng rác', 'n.', NULL, 'Đồng nghĩa: rubbish bin, garbage can, trash can', 'Đây là từ vựng thông dụng trong tiếng Anh-Anh; tiếng Anh-Mỹ thường dùng garbage can hoặc trash can.', 'Please put that rubbish in the dustbin outside.', NULL, 'Làm ơn vứt đống rác đó vào thùng rác ở bên ngoài.', '{"wordId":"dustbin","ukIpa":"/ˈdʌstbɪn/","usIpa":"/ˈdʌstbɪn/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A large container for rubbish, usually kept outside.","vi":"thùng rác"}],"examples":[{"en":"Please put that rubbish in the dustbin outside.","vi":"Làm ơn vứt đống rác đó vào thùng rác ở bên ngoài.","audioKind":"ex"},{"en":"Providing a separate dustbin for food waste can help households reduce the amount of rubbish sent to landfill.","vi":"Việc bố trí một thùng rác riêng cho rác thải thực phẩm có thể giúp các hộ gia đình giảm bớt lượng rác đưa đến bãi chôn lấp.","audioKind":"ex2"}],"collocations":[{"en":"empty the dustbin","vi":"đổ thùng rác"},{"en":"dustbin lid","vi":"nắp thùng rác"},{"en":"put rubbish in the dustbin","vi":"bỏ rác vào thùng rác"}],"wordFamily":[],"synonyms":["rubbish bin","garbage can","trash can"],"antonyms":[],"tipVi":"Đây là từ vựng thông dụng trong tiếng Anh-Anh; tiếng Anh-Mỹ thường dùng garbage can hoặc trash can.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_appear', 'en-a2-37', 'appear', '/əˈpɪr/', 'A2', 'xuất hiện; hiện ra; có vẻ như; trông có vẻ; biểu diễn; trình diện; xuất hiện trước tòa', 'v.', 'appearance (n.), disappear (v.), reappear (v.)', 'Đồng nghĩa: emerge, seem · Trái nghĩa: disappear', 'Khi mang nghĩa "dường như", động từ appear có thể đi với tính từ hoặc cấu trúc to do, không được trực tiếp đi kèm tân ngữ.', 'Stars began to appear as the sky grew darker.', NULL, 'Những ngôi sao bắt đầu xuất hiện khi bầu trời tối dần.', '{"wordId":"appear","ukIpa":"/əˈpɪə/","usIpa":"/əˈpɪr/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To become visible or come into view.","vi":"xuất hiện; hiện ra"},{"pos":"v.","en":"To seem to be a certain way.","vi":"có vẻ như; trông có vẻ"},{"pos":"v.","en":"To take part in a performance or attend court formally.","vi":"biểu diễn; trình diện; xuất hiện trước tòa"}],"examples":[{"en":"Stars began to appear as the sky grew darker.","vi":"Những ngôi sao bắt đầu xuất hiện khi bầu trời tối dần.","audioKind":"ex"},{"en":"Online courses appear to offer greater flexibility, although some learners still prefer traditional classroom interaction.","vi":"Các khóa học trực tuyến dường như mang lại tính linh hoạt cao hơn, mặc dù một số người học vẫn thích sự tương tác trong lớp học truyền thống hơn.","audioKind":"ex2"}],"collocations":[{"en":"appear suddenly","vi":"xuất hiện đột ngột"},{"en":"appear to be","vi":"dường như là"},{"en":"appear in court","vi":"ra hầu tòa"}],"wordFamily":["appearance (n.)","disappear (v.)","reappear (v.)"],"synonyms":["emerge","seem"],"antonyms":["disappear"],"tipVi":"Khi mang nghĩa \"dường như\", động từ appear có thể đi với tính từ hoặc cấu trúc to do, không được trực tiếp đi kèm tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nowhere', 'en-a2-37', 'nowhere', '/ˈnoʊwer/', 'A2', 'không nơi nào; ở đâu cũng không', 'adv.', NULL, 'Trái nghĩa: somewhere, everywhere', 'Bản thân từ nowhere đã mang nghĩa phủ định trong câu, ví dụ: I have nowhere to go.', 'There was nowhere to sit on the crowded train.', NULL, 'Chẳng có lấy một chỗ để ngồi trên chuyến tàu đông đúc đó.', '{"wordId":"nowhere","ukIpa":"/ˈnəʊweə/","usIpa":"/ˈnoʊwer/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"not in or to any place","vi":"không nơi nào; ở đâu cũng không"}],"examples":[{"en":"There was nowhere to sit on the crowded train.","vi":"Chẳng có lấy một chỗ để ngồi trên chuyến tàu đông đúc đó.","audioKind":"ex"},{"en":"Without affordable housing, some low-income families have nowhere to live despite having regular paid employment.","vi":"Nếu không có nhà ở giá rẻ, một số gia đình thu nhập thấp sẽ không có nơi để ở dù vẫn có việc làm ổn định hàng ngày.","audioKind":"ex2"}],"collocations":[{"en":"nowhere else","vi":"không nơi nào khác"},{"en":"nowhere near","vi":"còn lâu mới; hoàn toàn không bằng"},{"en":"get nowhere","vi":"chẳng đi đến đâu; không đạt kết quả gì"},{"en":"in the middle of nowhere","vi":"nơi khỉ ho cò gáy; chốn hoang vu"}],"wordFamily":[],"synonyms":[],"antonyms":["somewhere","everywhere"],"tipVi":"Bản thân từ nowhere đã mang nghĩa phủ định trong câu, ví dụ: I have nowhere to go.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_barbecue', 'en-a2-37', 'barbecue', '/ˈbɑːrbɪkjuː/', 'A2', 'tiệc nướng ngoài trời; vỉ nướng; lò nướng BBQ; nướng thịt ngoài trời', 'n.', NULL, NULL, 'Từ này vừa có thể chỉ bữa tiệc nướng, dụng cụ nướng, vừa có thể là động từ, và thường được viết tắt là BBQ.', 'We invited our neighbours to a barbecue in the garden.', NULL, 'Chúng tôi đã mời những người hàng xóm đến tham gia bữa tiệc nướng ngoài trời ở khu vườn.', '{"wordId":"barbecue","ukIpa":"/ˈbɑːbɪkjuː/","usIpa":"/ˈbɑːrbɪkjuː/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"An outdoor meal where food is cooked over a fire.","vi":"tiệc nướng ngoài trời"},{"pos":"n.","en":"Equipment for cooking food over a fire outdoors.","vi":"vỉ nướng; lò nướng BBQ"},{"pos":"v.","en":"To cook food on a grill over a fire.","vi":"nướng thịt ngoài trời"}],"examples":[{"en":"We invited our neighbours to a barbecue in the garden.","vi":"Chúng tôi đã mời những người hàng xóm đến tham gia bữa tiệc nướng ngoài trời ở khu vườn.","audioKind":"ex"},{"en":"Designated barbecue areas allow visitors to cook outdoors while reducing the risk of fires in public parks.","vi":"Các khu vực nướng thịt được quy hoạch riêng giúp du khách có thể nấu nướng ngoài trời đồng thời giảm thiểu nguy cơ xảy ra hỏa hoạn tại các công viên công cộng.","audioKind":"ex2"}],"collocations":[{"en":"have a barbecue","vi":"tổ chức tiệc nướng ngoài trời"},{"en":"barbecue sauce","vi":"sốp-xít BBQ; nước sốt nướng"},{"en":"barbecue vegetables","vi":"rau củ nướng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ này vừa có thể chỉ bữa tiệc nướng, dụng cụ nướng, vừa có thể là động từ, và thường được viết tắt là BBQ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_onto', 'en-a2-37', 'onto', '/ˈɑːntə/', 'A2', 'lên trên', 'prep.', NULL, 'Trái nghĩa: off', 'onto nhấn mạnh hành động di chuyển lên bề mặt; trong khi on thường chỉ trạng thái đã ở sẵn trên đó.', 'The cat jumped onto the sofa beside me.', NULL, 'Con mèo nhảy lên chiếc ghế sofa bên cạnh tôi.', '{"wordId":"onto","ukIpa":"/ˈɒntə/","usIpa":"/ˈɑːntə/","cefr":"A2","topic":"daily","senses":[{"pos":"prep.","en":"Moving to a position on a surface.","vi":"lên trên"}],"examples":[{"en":"The cat jumped onto the sofa beside me.","vi":"Con mèo nhảy lên chiếc ghế sofa bên cạnh tôi.","audioKind":"ex"},{"en":"Moving freight onto trains could reduce road congestion and lower emissions from the transport sector.","vi":"Việc chuyển hàng hóa lên tàu hỏa có thể làm giảm tình trạng tắc nghẽn giao thông đường bộ và hạ thấp lượng khí thải từ ngành vận tải.","audioKind":"ex2"}],"collocations":[{"en":"climb onto","vi":"trèo lên"},{"en":"step onto","vi":"bước lên"},{"en":"load goods onto","vi":"bốc hàng lên"}],"wordFamily":[],"synonyms":[],"antonyms":["off"],"tipVi":"onto nhấn mạnh hành động di chuyển lên bề mặt; trong khi on thường chỉ trạng thái đã ở sẵn trên đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_popcorn', 'en-a2-37', 'popcorn', '/ˈpɑːpkɔːrn/', 'A2', 'bỏng ngô; bắp rang bơ', 'n.', NULL, NULL, 'Thông thường là danh từ không đếm được; một hạt bỏng ngô có thể dùng là a piece of popcorn.', 'We shared a bowl of popcorn during the film.', NULL, 'Chúng tôi cùng nhau ăn một bát bỏng ngô trong lúc xem phim.', '{"wordId":"popcorn","ukIpa":"/ˈpɒpkɔːn/","usIpa":"/ˈpɑːpkɔːrn/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"corn kernels heated until they burst into light, fluffy pieces","vi":"bỏng ngô; bắp rang bơ"}],"examples":[{"en":"We shared a bowl of popcorn during the film.","vi":"Chúng tôi cùng nhau ăn một bát bỏng ngô trong lúc xem phim.","audioKind":"ex"},{"en":"Cinemas often earn additional revenue by selling snacks such as popcorn alongside tickets for film screenings.","vi":"Các rạp chiếu phim thường kiếm thêm doanh thu bằng cách bán các món ăn vặt như bỏng ngô bên cạnh vé xem phim.","audioKind":"ex2"}],"collocations":[{"en":"a bowl of popcorn","vi":"một bát bỏng ngô"},{"en":"salted popcorn","vi":"bỏng ngô vị mặn"},{"en":"make popcorn","vi":"làm bỏng ngô"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thông thường là danh từ không đếm được; một hạt bỏng ngô có thể dùng là a piece of popcorn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stove', 'en-a2-37', 'stove', '/stoʊv/', 'A2', 'lò; bếp nấu; lò sưởi', 'n.', NULL, NULL, 'stove dùng để nấu ăn hoặc sưởi ấm; oven dùng riêng cho lò nướng.', 'A pot of soup is bubbling on the stove.', NULL, 'Một nồi súp đang sôi sùng sục trên bếp.', '{"wordId":"stove","ukIpa":"/stəʊv/","usIpa":"/stoʊv/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a device used for cooking food or heating a room","vi":"lò; bếp nấu; lò sưởi"}],"examples":[{"en":"A pot of soup is bubbling on the stove.","vi":"Một nồi súp đang sôi sùng sục trên bếp.","audioKind":"ex"},{"en":"Replacing traditional indoor stoves with cleaner models can reduce household air pollution and improve respiratory health.","vi":"Việc thay thế các bếp lò truyền thống trong nhà bằng các mẫu sạch hơn có thể làm giảm ô nhiễm không khí trong nhà và cải thiện sức khỏe đường hô hấp.","audioKind":"ex2"}],"collocations":[{"en":"gas stove","vi":"bếp ga"},{"en":"electric stove","vi":"bếp điện"},{"en":"wood-burning stove","vi":"lò sưởi củi"},{"en":"on the stove","vi":"đang nấu trên bếp"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"stove dùng để nấu ăn hoặc sưởi ấm; oven dùng riêng cho lò nướng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mango', 'en-a2-37', 'mango', '/ˈmæŋɡoʊ/', 'A2', 'quả xoài; trái xoài', 'n.', NULL, NULL, 'Cả hai dạng số nhiều mangoes và mangos đều đúng.', 'This mango is sweet enough to eat without sugar.', NULL, 'Quả xoài này đủ ngọt để ăn mà không cần thêm đường.', '{"wordId":"mango","ukIpa":"/ˈmæŋɡəʊ/","usIpa":"/ˈmæŋɡoʊ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A tropical fruit with sweet orange flesh and a large stone","vi":"quả xoài; trái xoài"}],"examples":[{"en":"This mango is sweet enough to eat without sugar.","vi":"Quả xoài này đủ ngọt để ăn mà không cần thêm đường.","audioKind":"ex"},{"en":"Improved storage facilities can help mango farmers reduce food waste and earn more reliable incomes.","vi":"Cải thiện cơ sở vật chất bảo quản có thể giúp nông dân trồng xoài giảm lãng phí thực phẩm và có được thu nhập ổn định hơn.","audioKind":"ex2"}],"collocations":[{"en":"a ripe mango","vi":"quả xoài chín"},{"en":"mango juice","vi":"nước ép xoài"},{"en":"mango flesh","vi":"thịt xoài"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cả hai dạng số nhiều mangoes và mangos đều đúng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hide', 'en-a2-37', 'hide', '/haɪd/', 'A2', 'giấu; trốn; ẩn nấp; che giấu; giấu giếm; che đậy; da thú', 'v.', 'hidden (adj.), hiding (n.)', 'Đồng nghĩa: conceal · Trái nghĩa: reveal, expose', 'Quá khứ hid, phân từ quá khứ hidden; hide from nghĩa là trốn tránh.', 'We hid the birthday present under the bed.', NULL, 'Chúng tôi đã giấu món quà sinh nhật dưới gầm giường.', '{"wordId":"hide","ukIpa":"/haɪd/","usIpa":"/haɪd/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To put or stay somewhere out of sight.","vi":"giấu; trốn; ẩn nấp"},{"pos":"v.","en":"To prevent others from knowing or noticing something.","vi":"che giấu; giấu giếm; che đậy"},{"pos":"n.","en":"The skin of a large animal, often used for leather.","vi":"da thú"}],"examples":[{"en":"We hid the birthday present under the bed.","vi":"Chúng tôi đã giấu món quà sinh nhật dưới gầm giường.","audioKind":"ex"},{"en":"Companies should not hide information about environmental risks associated with their products or manufacturing processes.","vi":"Các công ty không nên che giấu thông tin về rủi ro môi trường liên quan đến sản phẩm hoặc quy trình sản xuất của họ.","audioKind":"ex2"}],"collocations":[{"en":"hide from view","vi":"ẩn khuất khỏi tầm nhìn"},{"en":"hide the truth","vi":"giấu giếm sự thật"},{"en":"hide your feelings","vi":"che giấu cảm xúc"},{"en":"animal hide","vi":"da động vật"}],"wordFamily":["hidden (adj.)","hiding (n.)"],"synonyms":["conceal"],"antonyms":["reveal","expose"],"tipVi":"Quá khứ hid, phân từ quá khứ hidden; hide from nghĩa là trốn tránh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_37_1', 'en-a2-37', 'Cách dùng “appear” (v.) — xuất hiện; hiện ra', 'appear suddenly  ·  appear to be  ·  appear in court', 'Khi mang nghĩa "dường như", động từ appear có thể đi với tính từ hoặc cấu trúc to do, không được trực tiếp đi kèm tân ngữ.', 'Họ từ (Word Family): appearance (n.), disappear (v.), reappear (v.) | Đồng nghĩa: emerge, seem · Trái nghĩa: disappear', '[{"hanzi":"Stars began to appear as the sky grew darker.","pinyin":"","meaning":"Những ngôi sao bắt đầu xuất hiện khi bầu trời tối dần."},{"hanzi":"Online courses appear to offer greater flexibility, although some learners still prefer traditional classroom interaction.","pinyin":"","meaning":"Các khóa học trực tuyến dường như mang lại tính linh hoạt cao hơn, mặc dù một số người học vẫn thích sự tương tác trong lớp học truyền thống hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_37_2', 'en-a2-37', 'Cách dùng “cucumber” (n.) — quả dưa chuột; trái dưa leo', 'sliced cucumber  ·  cucumber salad  ·  as cool as a cucumber', 'Thông thường là danh từ đếm được: a cucumber; khi chỉ nguyên liệu nấu ăn cũng có thể dùng như danh từ không đếm được.', NULL, '[{"hanzi":"She sliced a cucumber and added it to the salad.","pinyin":"","meaning":"Cô ấy thái dưa chuột thành lát rồi cho vào món xà lách."},{"hanzi":"Growing cucumbers in greenhouses can provide a reliable food supply, but heating these structures requires energy.","pinyin":"","meaning":"Việc trồng dưa chuột trong nhà kính có thể cung cấp nguồn lương thực ổn định, nhưng việc sưởi ấm các cấu trúc này tiêu tốn năng lượng."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_37_3', 'en-a2-37', 'Cách dùng “matter” (n.) — vấn đề; việc', 'a serious matter  ·  a matter of time  ·  organic matter', 'Khi chỉ sự việc thường đếm được; khi chỉ vật chất là không đếm được; đóng vai trò động từ biểu thị sự quan trọng.', NULL, '[{"hanzi":"We can discuss this matter after lunch today.","pinyin":"","meaning":"Chúng ta có thể thảo luận vấn đề này sau bữa trưa hôm nay."},{"hanzi":"The quality of teaching matters more than expensive equipment when schools aim to improve student achievement.","pinyin":"","meaning":"Chất lượng giảng dạy quan trọng hơn thiết bị đắt tiền khi các trường học hướng tới mục tiêu nâng cao thành tích của học sinh."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_37_4', 'en-a2-37', 'Cách dùng “finally” (adv.) — cuối cùng; sau cùng (sau một thời gian dài chờ đợi hoặc nỗ lực)', 'finally arrive  ·  finally succeed  ·  finally agree', 'Biểu thị sự việc xảy ra sau cùng thường đứng trước động từ thường; dùng để dẫn dắt ý cuối thường đứng đầu câu.', 'Họ từ (Word Family): final (adj.), finality (n.), finalise (v.) | Đồng nghĩa: eventually, at last, lastly', '[{"hanzi":"After searching all morning, I finally found my keys.","pinyin":"","meaning":"Sau khi tìm kiếm suốt cả buổi sáng, cuối cùng tôi cũng tìm thấy chìa khóa của mình."},{"hanzi":"Finally, governments should invest in reliable public transport to reduce traffic congestion and urban air pollution.","pinyin":"","meaning":"Cuối cùng, chính phủ nên đầu tư vào hệ thống giao thông công cộng đáng tin cậy để giảm thiểu tình trạng ùn tắc giao thông và ô nhiễm không khí đô thị."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_37_1', 'en-a2-37', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
