INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_37_1_2', 'ten_a2_37_1', 'especially', 'I enjoy cooking, especially when friends come for dinner.', 'I enjoy cooking, especially when friends come for dinner.', '/ɪˈspeʃəli/', 'Tôi thích nấu ăn, nhất là khi có bạn bè đến ăn tối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_37_1_3', 'ten_a2_37_1', 'super', 'We had a super afternoon playing games in the garden.', 'We had a super afternoon playing games in the garden.', '/ˈsuːpər/', 'Chúng tôi đã có một buổi chiều tuyệt vời chơi đùa trong vườn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_37_1_4', 'ten_a2_37_1', 'heat', 'We rested under a tree to escape the heat.', 'We rested under a tree to escape the heat.', '/hiːt/', 'Chúng tôi nghỉ ngơi dưới gốc cây để tránh cái nắng gay gắt.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_37_1_5', 'ten_a2_37_1', 'lunchtime', 'At lunchtime, we sat outside and shared some sandwiches.', 'At lunchtime, we sat outside and shared some sandwiches.', '/ˈlʌntʃtaɪm/', 'Vào giờ ăn trưa, chúng tôi ngồi ngoài trời và chia nhau vài chiếc bánh mì kẹp.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_37_1_6', 'ten_a2_37_1', 'cucumber', 'She sliced a cucumber and added it to the salad.', 'She sliced a cucumber and added it to the salad.', '/ˈkjuːkʌmbər/', 'Cô ấy thái dưa chuột thành lát rồi cho vào món xà lách.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_37_1_7', 'ten_a2_37_1', 'whose', 'Whose umbrella is dripping water all over the floor?', 'Whose umbrella is dripping water all over the floor?', '/huːz/', 'Cái ô của ai mà nhỏ nước ướt sũng cả sàn nhà thế này?', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_37_1_8', 'ten_a2_37_1', 'bacon', 'He cooked bacon and eggs for breakfast on Sunday.', 'He cooked bacon and eggs for breakfast on Sunday.', '/ˈbeɪkən/', 'Anh ấy đã nấu thịt xông khói và trứng cho bữa sáng vào Chủ nhật.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_37_1_1', 'en-a2-37', 'ten_a2_37_1', 'listening', 'listening', 'Please hang your wet coat beside the front door.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã giấu món quà sinh nhật dưới gầm giường.","Những ngôi sao bắt đầu xuất hiện khi bầu trời tối dần.","Làm ơn treo chiếc áo khoác ướt của bạn cạnh cửa trước.","Làm ơn vứt đống rác đó vào thùng rác ở bên ngoài."]'::jsonb, 2, 'Please hang your wet coat beside the front door. → Làm ơn treo chiếc áo khoác ướt của bạn cạnh cửa trước.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_37_1_2', 'en-a2-37', 'ten_a2_37_1', 'listening', 'listening', 'I enjoy cooking, especially when friends come for dinner.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi thích nấu ăn, nhất là khi có bạn bè đến ăn tối.","Sau khi tìm kiếm suốt cả buổi sáng, cuối cùng tôi cũng tìm thấy chìa khóa của mình.","Làm ơn treo chiếc áo khoác ướt của bạn cạnh cửa trước.","Anh ấy viện lý do cho việc đến bữa tối muộn."]'::jsonb, 0, 'I enjoy cooking, especially when friends come for dinner. → Tôi thích nấu ăn, nhất là khi có bạn bè đến ăn tối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_37_1_3', 'en-a2-37', 'ten_a2_37_1', 'listening', 'listening', 'We had a super afternoon playing games in the garden.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đã có một buổi chiều tuyệt vời chơi đùa trong vườn.","Cô ấy thái dưa chuột thành lát rồi cho vào món xà lách.","Cô em họ nhỏ của tôi đã ôm búp bê vào chiếc giường bé xíu.","Tôi thích nấu ăn, nhất là khi có bạn bè đến ăn tối."]'::jsonb, 0, 'We had a super afternoon playing games in the garden. → Chúng tôi đã có một buổi chiều tuyệt vời chơi đùa trong vườn.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_37_2', 'en-a2-37', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_37_2_1', 'ten_a2_37_2', 'hang', 'Museums often hang paintings at different heights to make their collections accessible to visitors of all ages.', 'Museums often hang paintings at different heights to make their collections accessible to visitors of all ages.', '/hæŋ/', 'Các bảo tàng thường treo các bức tranh ở độ cao khác nhau để khách tham quan mọi lứa tuổi đều có thể ngắm nhìn bộ sưu tập.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_37_2_2', 'ten_a2_37_2', 'especially', 'Reliable public transport is especially important for residents who cannot afford to own a car.', 'Reliable public transport is especially important for residents who cannot afford to own a car.', '/ɪˈspeʃəli/', 'Hệ thống giao thông công cộng đáng tin cậy đặc biệt quan trọng đối với những cư dân không đủ khả năng sở hữu ô tô.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_37_2_3', 'ten_a2_37_2', 'super', 'Although users may describe an app as super helpful, researchers need objective evidence to assess its educational value.', 'Although users may describe an app as super helpful, researchers need objective evidence to assess its educational value.', '/ˈsuːpər/', 'Mặc dù người dùng có thể mô tả một ứng dụng là cực kỳ hữu ích, các nhà nghiên cứu vẫn cần những bằng chứng khách quan để đánh giá giá trị giáo dục của nó.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_37_2_4', 'ten_a2_37_2', 'heat', 'Cities can reduce extreme heat by planting trees and replacing dark surfaces with materials that reflect sunlight.', 'Cities can reduce extreme heat by planting trees and replacing dark surfaces with materials that reflect sunlight.', '/hiːt/', 'Các thành phố có thể giảm bớt tình trạng nắng nóng gay gắt bằng cách trồng cây xanh và thay thế các bề mặt tối màu bằng vật liệu phản chiếu ánh sáng mặt trời.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_37_2_5', 'ten_a2_37_2', 'lunchtime', 'Providing quiet spaces at lunchtime may help employees relax and return to work with greater focus.', 'Providing quiet spaces at lunchtime may help employees relax and return to work with greater focus.', '/ˈlʌntʃtaɪm/', 'Việc cung cấp không gian yên tĩnh vào giờ ăn trưa có thể giúp nhân viên thư giãn và quay lại làm việc với sự tập trung cao hơn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_37_2_6', 'ten_a2_37_2', 'cucumber', 'Growing cucumbers in greenhouses can provide a reliable food supply, but heating these structures requires energy.', 'Growing cucumbers in greenhouses can provide a reliable food supply, but heating these structures requires energy.', '/ˈkjuːkʌmbər/', 'Việc trồng dưa chuột trong nhà kính có thể cung cấp nguồn lương thực ổn định, nhưng việc sưởi ấm các cấu trúc này tiêu tốn năng lượng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_37_2_1', 'en-a2-37', 'ten_a2_37_2', 'listening', 'listening', 'Museums often hang paintings at different heights to make their collections accessible to visitors of all ages.', NULL, 'Trong câu vừa nghe, từ “hang” mang nghĩa nào sau đây?', '["đặc biệt; nhất là","treo; mắc; lơ lửng","đơn giản; dễ hiểu; dễ làm","trừ ra; ngoại trừ"]'::jsonb, 1, '“hang” (/hæŋ/): treo; mắc; lơ lửng. Câu đầy đủ: Museums often hang paintings at different heights to make their collections accessible to visitors of all ages.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_37_2_2', 'en-a2-37', 'ten_a2_37_2', 'listening', 'listening', 'Reliable public transport is especially important for residents who cannot afford to own a car.', NULL, 'Trong câu vừa nghe, từ “especially” mang nghĩa nào sau đây?', '["dọc theo; theo","như thế; loại này","tính từ","đặc biệt; nhất là"]'::jsonb, 3, '“especially” (/ɪˈspeʃəli/): đặc biệt; nhất là. Câu đầy đủ: Reliable public transport is especially important for residents who cannot afford to own a car.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
