INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_37_2', 'en-a2-37', NULL, 'comprehensive_test', 'listening', 'I enjoy cooking, especially when friends come for dinner.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cái ô của ai mà nhỏ nước ướt sũng cả sàn nhà thế này?","Làm ơn vứt đống rác đó vào thùng rác ở bên ngoài.","Anh ấy viện lý do cho việc đến bữa tối muộn.","Tôi thích nấu ăn, nhất là khi có bạn bè đến ăn tối."]'::jsonb, 3, 'I enjoy cooking, especially when friends come for dinner. → Tôi thích nấu ăn, nhất là khi có bạn bè đến ăn tối.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
