INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_37_6', 'en-a2-37', NULL, 'comprehensive_test', 'listening', 'She sliced a cucumber and added it to the salad.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy thái dưa chuột thành lát rồi cho vào món xà lách.","Cô ấy quấn một chiếc chăn dày quanh đôi vai lạnh giá của mình.","Chúng tôi đã mời những người hàng xóm đến tham gia bữa tiệc nướng ngoài trời ở khu vườn.","Làm ơn treo chiếc áo khoác ướt của bạn cạnh cửa trước."]'::jsonb, 0, 'She sliced a cucumber and added it to the salad. → Cô ấy thái dưa chuột thành lát rồi cho vào món xà lách.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_37_7', 'en-a2-37', NULL, 'comprehensive_test', 'listening', 'whose', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["sửa chữa; tân trang","gần như, hầu như","thuộc về hoặc liên quan đến đất nước, người dân hoặc văn hóa Canada","của ai"]'::jsonb, 3, 'whose (/huːz/) → của ai; cái của ai', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_37_8', 'en-a2-37', NULL, 'comprehensive_test', 'listening', 'He cooked bacon and eggs for breakfast on Sunday.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi nghỉ ngơi dưới gốc cây để tránh cái nắng gay gắt.","Anh ấy đã nấu thịt xông khói và trứng cho bữa sáng vào Chủ nhật.","Làm ơn vứt đống rác đó vào thùng rác ở bên ngoài.","Những ngôi sao bắt đầu xuất hiện khi bầu trời tối dần."]'::jsonb, 1, 'He cooked bacon and eggs for breakfast on Sunday. → Anh ấy đã nấu thịt xông khói và trứng cho bữa sáng vào Chủ nhật.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_37_9', 'en-a2-37', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “The time around the middle of the day when people eat.”?', '["kilo","mango","heat","lunchtime"]'::jsonb, 3, 'lunchtime (/ˈlʌntʃtaɪm/) → giờ ăn trưa; thời gian ăn trưa', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
