INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_37_18', 'en-a2-37', NULL, 'comprehensive_test', 'reading', NULL, 'Museums often hang paintings at different heights to make their collections accessible to visitors of all ages.', 'Dựa vào câu trên, từ “hang” có nghĩa phù hợp nhất là gì?', '["môn bóng chuyền; quả bóng chuyền","hoàn hảo; lý tưởng","thuộc về Ấn Độ hoặc người Ấn Độ","treo; mắc; lơ lửng"]'::jsonb, 3, 'hang: treo; mắc; lơ lửng; rủ xuống; thõng xuống. Dịch cả câu: Các bảo tàng thường treo các bức tranh ở độ cao khác nhau để khách tham quan mọi lứa tuổi đều có thể ngắm nhìn bộ sưu tập.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_37_19', 'en-a2-37', NULL, 'comprehensive_test', 'reading', NULL, 'Reliable public transport is especially important for residents who cannot afford to own a car.', 'Dựa vào câu trên, từ “especially” có nghĩa phù hợp nhất là gì?', '["vùng quê; miền quê","hồ sơ; sổ sách; bản ghi chép","cuộc thảo luận; sự bàn bạc","đặc biệt; nhất là"]'::jsonb, 3, 'especially: đặc biệt; nhất là. Dịch cả câu: Hệ thống giao thông công cộng đáng tin cậy đặc biệt quan trọng đối với những cư dân không đủ khả năng sở hữu ô tô.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_37_20', 'en-a2-37', NULL, 'comprehensive_test', 'reading', NULL, 'Although users may describe an app as super helpful, researchers need objective evidence to assess its educational value.', 'Dựa vào câu trên, từ “super” có nghĩa phù hợp nhất là gì?', '["hạnh phúc; niềm vui","tuyệt vời; cực kỳ thú vị","đuôi (động vật hoặc máy bay)","hạt tiêu; bột tiêu"]'::jsonb, 1, 'super: tuyệt vời; cực kỳ thú vị; rất; cực kỳ. Dịch cả câu: Mặc dù người dùng có thể mô tả một ứng dụng là cực kỳ hữu ích, các nhà nghiên cứu vẫn cần những bằng chứng khách quan để đánh giá giá trị giáo dục của nó.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_37_21', 'en-a2-37', NULL, 'comprehensive_test', 'reading', NULL, 'Cities can reduce extreme heat by planting trees and replacing dark surfaces with materials that reflect sunlight.', 'Dựa vào câu trên, từ “heat” có nghĩa phù hợp nhất là gì?', '["thức; tỉnh táo","ngăn kéo; hộc tủ","kiến thức, sự hiểu biết","hơi nóng; sức nóng"]'::jsonb, 3, 'heat: hơi nóng; sức nóng; làm nóng; đun nóng; vòng loại; trận sơ khảo. Dịch cả câu: Các thành phố có thể giảm bớt tình trạng nắng nóng gay gắt bằng cách trồng cây xanh và thay thế các bề mặt tối màu bằng vật liệu phản chiếu ánh sáng mặt trời.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
