INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-38', 'en', 'Bài 38: Đời sống hằng ngày (10) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '26 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2038, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stick', 'en-a2-38', 'stick', '/stɪk/', 'A2', 'gậy; cành cây; thanh gỗ; dán; đính; dính vào; cắm; đâm; thọc', 'n.', 'sticky (adj.), sticker (n.)', NULL, 'Động từ dạng quá khứ và quá khứ phân từ đều là stuck; stick to diễn tả sự kiên trì, tuân thủ.', 'The dog brought a stick back to me.', NULL, 'Con chó đã ngậm một cành cây mang lại cho tôi.', '{"wordId":"stick","ukIpa":"/stɪk/","usIpa":"/stɪk/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A long, thin piece of wood used for various purposes.","vi":"gậy; cành cây; thanh gỗ"},{"pos":"v.","en":"To attach something, or become attached, using a sticky substance.","vi":"dán; đính; dính vào"},{"pos":"v.","en":"To push a pointed object into something.","vi":"cắm; đâm; thọc"}],"examples":[{"en":"The dog brought a stick back to me.","vi":"Con chó đã ngậm một cành cây mang lại cho tôi.","audioKind":"ex"},{"en":"Students can stick pictures onto a shared poster to present their research on local wildlife.","vi":"Học sinh có thể dán hình ảnh lên một tấm áp phích chung để trình bày nghiên cứu của các em về động vật hoang dã bản địa.","audioKind":"ex2"}],"collocations":[{"en":"walking stick","vi":"gậy đi bộ"},{"en":"stick to a plan","vi":"kiên định với kế hoạch; tuân thủ kế hoạch"},{"en":"stick a picture on","vi":"dán một bức ảnh lên"},{"en":"stick together","vi":"đoàn kết lại; gắn bó với nhau"}],"wordFamily":["sticky (adj.)","sticker (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Động từ dạng quá khứ và quá khứ phân từ đều là stuck; stick to diễn tả sự kiên trì, tuân thủ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_common', 'en-a2-38', 'common', '/ˈkɑːmən/', 'A2', 'phổ biến; thông thường; hay gặp; chung; chung cho nhiều người', 'adj.', 'commonly (adv.), uncommon (adj.)', 'Đồng nghĩa: frequent, widespread, shared · Trái nghĩa: rare, uncommon', 'common chỉ sự phổ biến hoặc thuộc về chung; ordinary nhấn mạnh tính bình thường, không có gì đặc biệt.', 'Heavy rain is common here during the summer.', NULL, 'Mưa lớn là chuyện thường thấy ở đây vào mùa hè.', '{"wordId":"common","ukIpa":"/ˈkɒmən/","usIpa":"/ˈkɑːmən/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"happening often or found in many places","vi":"phổ biến; thông thường; hay gặp"},{"pos":"adj.","en":"shared by two or more people or groups","vi":"chung; chung cho nhiều người"}],"examples":[{"en":"Heavy rain is common here during the summer.","vi":"Mưa lớn là chuyện thường thấy ở đây vào mùa hè.","audioKind":"ex"},{"en":"Governments should address the common challenges that prevent rural communities from accessing affordable healthcare.","vi":"Chính phủ nên giải quyết những thách thức chung vốn đang cản trở các cộng đồng nông thôn tiếp cận dịch vụ y tế phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"a common problem","vi":"vấn đề phổ biến"},{"en":"a common goal","vi":"mục tiêu chung"},{"en":"have something in common","vi":"có điểm chung"},{"en":"common practice","vi":"thói quen thông thường; tập quán chung"}],"wordFamily":["commonly (adv.)","uncommon (adj.)"],"synonyms":["frequent","widespread","shared"],"antonyms":["rare","uncommon"],"tipVi":"common chỉ sự phổ biến hoặc thuộc về chung; ordinary nhấn mạnh tính bình thường, không có gì đặc biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_kettle', 'en-a2-38', 'kettle', '/ˈketəl/', 'A2', 'ấm đun nước', 'n.', NULL, NULL, 'kettle dùng để đun nước sôi, còn teapot dùng để pha trà.', 'Put the kettle on while I find the cups.', NULL, 'Bạn đi đun nước đi trong lúc tôi tìm cốc nhé.', '{"wordId":"kettle","ukIpa":"/ˈketəl/","usIpa":"/ˈketəl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A container with a handle and spout for boiling water.","vi":"ấm đun nước"}],"examples":[{"en":"Put the kettle on while I find the cups.","vi":"Bạn đi đun nước đi trong lúc tôi tìm cốc nhé.","audioKind":"ex"},{"en":"Boiling only the water needed in a kettle can reduce household electricity consumption over time.","vi":"Việc chỉ đun lượng nước cần dùng trong ấm đun có thể giúp giảm lượng điện năng tiêu thụ của hộ gia đình theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"electric kettle","vi":"ấm đun nước điện"},{"en":"put the kettle on","vi":"bật ấm đun nước"},{"en":"boil the kettle","vi":"đun một ấm nước"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"kettle dùng để đun nước sôi, còn teapot dùng để pha trà.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_opposite', 'en-a2-38', 'opposite', '/ˈɑːpəzɪt/', 'A2', 'khác hoàn toàn; ở phía đối diện; ở phía đối diện của; trái ngược; điều ngược lại', 'adj.', 'opposition (n.), oppose (v.), opposing (adj.)', 'Đồng nghĩa: contrary · Trái nghĩa: same', 'Giới từ opposite đi thẳng ngay sau địa điểm; danh từ thường dùng the opposite of.', 'We left the station and walked in opposite directions.', NULL, 'Chúng tôi rời nhà ga và đi theo hai hướng ngược nhau.', '{"wordId":"opposite","ukIpa":"/ˈɒpəzɪt/","usIpa":"/ˈɑːpəzɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"completely different, or on the other side","vi":"khác hoàn toàn; ở phía đối diện"},{"pos":"prep.","en":"facing someone or something from the other side","vi":"ở phía đối diện của"},{"pos":"n.","en":"someone or something completely different from another","vi":"trái ngược; điều ngược lại"}],"examples":[{"en":"We left the station and walked in opposite directions.","vi":"Chúng tôi rời nhà ga và đi theo hai hướng ngược nhau.","audioKind":"ex"},{"en":"Although the policy aimed to reduce traffic, it had the opposite effect in several residential areas.","vi":"Mặc dù chính sách nhằm mục đích giảm thiểu lưu lượng giao thông, nhưng nó lại mang lại hiệu quả ngược lại ở một số khu dân cư.","audioKind":"ex2"}],"collocations":[{"en":"opposite directions","vi":"hướng ngược lại"},{"en":"the opposite effect","vi":"hiệu quả ngược lại"},{"en":"the exact opposite","vi":"điều hoàn toàn trái ngược"}],"wordFamily":["opposition (n.)","oppose (v.)","opposing (adj.)"],"synonyms":["contrary"],"antonyms":["same"],"tipVi":"Giới từ opposite đi thẳng ngay sau địa điểm; danh từ thường dùng the opposite of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ourselves', 'en-a2-38', 'ourselves', '/aʊrˈselvz/', 'A2', 'chúng tôi (chính mình); chúng ta (chính mình); tự chúng tôi; chính chúng tôi', 'pron.', 'we (pron.), us (pron.), our (det.), ours (pron.)', NULL, 'by ourselves có thể mang nghĩa là một mình, hoặc tự làm mà không cần nhờ đến sự trợ giúp của người khác.', 'We saw ourselves reflected in the clear lake.', NULL, 'Chúng tôi thấy bóng mình phản chiếu trên mặt hồ trong vắt.', '{"wordId":"ourselves","ukIpa":"/aʊəˈselvz/","usIpa":"/aʊrˈselvz/","cefr":"A2","topic":"daily","senses":[{"pos":"pron.","en":"used when we are both doing and receiving an action","vi":"chúng tôi (chính mình); chúng ta (chính mình)"},{"pos":"pron.","en":"used to emphasize that we do something, not others","vi":"tự chúng tôi; chính chúng tôi"}],"examples":[{"en":"We saw ourselves reflected in the clear lake.","vi":"Chúng tôi thấy bóng mình phản chiếu trên mặt hồ trong vắt.","audioKind":"ex"},{"en":"By involving ourselves in community projects, we can develop practical skills and strengthen local relationships.","vi":"Bằng cách tự mình tham gia vào các dự án cộng đồng, chúng tôi có thể phát triển các kỹ năng thực tế và củng cố mối quan hệ địa phương.","audioKind":"ex2"}],"collocations":[{"en":"by ourselves","vi":"tự mình; một mình"},{"en":"enjoy ourselves","vi":"chơi vui vẻ; tận hưởng niềm vui"},{"en":"pride ourselves on","vi":"tự hào về"},{"en":"for ourselves","vi":"cho chính chúng ta"}],"wordFamily":["we (pron.)","us (pron.)","our (det.)","ours (pron.)"],"synonyms":[],"antonyms":[],"tipVi":"by ourselves có thể mang nghĩa là một mình, hoặc tự làm mà không cần nhờ đến sự trợ giúp của người khác.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fried', 'en-a2-38', 'fried', '/fraɪd/', 'A2', 'được chiên; được rán bằng dầu mỡ', 'adj.', 'fry (v.), frying (n.), fryer (n.)', NULL, 'fried là quá khứ và phân từ hai của động từ fry, đồng thời cũng đóng vai trò là tính từ; không giới hạn chỉ ở đồ chiên.', 'We had fried eggs and toast for breakfast.', NULL, 'Bữa sáng hôm nay chúng tôi ăn trứng ơ-lết chiên và bánh mì nướng.', '{"wordId":"fried","ukIpa":"/fraɪd/","usIpa":"/fraɪd/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"cooked in hot oil or fat","vi":"được chiên; được rán bằng dầu mỡ"}],"examples":[{"en":"We had fried eggs and toast for breakfast.","vi":"Bữa sáng hôm nay chúng tôi ăn trứng ơ-lết chiên và bánh mì nướng.","audioKind":"ex"},{"en":"Eating fried foods too frequently can increase calorie intake and make maintaining a healthy weight more difficult.","vi":"Việc ăn đồ chiên rán quá thường xuyên có thể làm tăng lượng calo nạp vào và khiến việc duy trì cân nặng lành mạnh trở nên khó khăn hơn.","audioKind":"ex2"}],"collocations":[{"en":"fried rice","vi":"cơm chiên"},{"en":"fried eggs","vi":"trứng chiên"},{"en":"deep-fried food","vi":"thức ăn chiên ngập dầu"}],"wordFamily":["fry (v.)","frying (n.)","fryer (n.)"],"synonyms":[],"antonyms":[],"tipVi":"fried là quá khứ và phân từ hai của động từ fry, đồng thời cũng đóng vai trò là tính từ; không giới hạn chỉ ở đồ chiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_offer', 'en-a2-38', 'offer', '/ˈɔːfər/', 'A2', 'chủ động đề nghị; đề ra; sự đề nghị; lời đề nghị; cơ hội; giấy báo trúng tuyển; ra giá; trả giá', 'v.', 'offering (n.)', NULL, 'Cấu trúc chủ động làm việc gì dùng offer to do, không dùng offer doing.', 'Our neighbour offered to carry the heavy bags upstairs.', NULL, 'Hàng xóm của chúng tôi đã chủ động đề nghị giúp chúng tôi mang những chiếc túi nặng lên lầu.', '{"wordId":"offer","ukIpa":"/ˈɒfə/","usIpa":"/ˈɔːfər/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"Say you are willing to give something or do something.","vi":"chủ động đề nghị; đề ra"},{"pos":"n.","en":"A proposal of help, an opportunity, or a place.","vi":"sự đề nghị; lời đề nghị; cơ hội; giấy báo trúng tuyển"},{"pos":"v.","en":"Say how much you are willing to pay.","vi":"ra giá; trả giá"}],"examples":[{"en":"Our neighbour offered to carry the heavy bags upstairs.","vi":"Hàng xóm của chúng tôi đã chủ động đề nghị giúp chúng tôi mang những chiếc túi nặng lên lầu.","audioKind":"ex"},{"en":"Universities should offer practical training that helps students develop skills relevant to the workplace.","vi":"Các trường đại học nên cung cấp chương trình đào tạo thực tế giúp sinh viên phát triển các kỹ năng phù hợp với môi trường công sở.","audioKind":"ex2"}],"collocations":[{"en":"offer help","vi":"chủ động giúp đỡ"},{"en":"offer someone a job","vi":"cung cấp cho ai một công việc"},{"en":"accept an offer","vi":"chấp nhận một lời đề nghị"},{"en":"make an offer","vi":"đưa ra lời đề nghị; ra giá"}],"wordFamily":["offering (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc chủ động làm việc gì dùng offer to do, không dùng offer doing.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sort', 'en-a2-38', 'sort', '/sɔːrt/', 'A2', 'loại; kiểu; hạng; phân loại; sắp xếp; giải quyết ổn thỏa; xử lý xong', 'n.', 'sorting (n.), sorter (n.)', 'Đồng nghĩa: type, kind, classify', 'a sort of dùng để chỉ "một loại"; cụm sort of trong văn nói còn mang nghĩa là "có chút, phần nào".', 'What sort of music do you listen to at home?', NULL, 'Bạn thường nghe loại nhạc gì ở nhà?', '{"wordId":"sort","ukIpa":"/sɔːt/","usIpa":"/sɔːrt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a group of things sharing similar characteristics","vi":"loại; kiểu; hạng"},{"pos":"v.","en":"to arrange things in groups or a particular order","vi":"phân loại; sắp xếp"},{"pos":"v.","en":"to deal successfully with a problem or practical matter","vi":"giải quyết ổn thỏa; xử lý xong"}],"examples":[{"en":"What sort of music do you listen to at home?","vi":"Bạn thường nghe loại nhạc gì ở nhà?","audioKind":"ex"},{"en":"Households should sort their waste carefully so that recyclable materials can be processed more efficiently.","vi":"Các hộ gia đình nên phân loại rác cẩn thận để các vật liệu có thể tái chế được xử lý hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"all sorts of","vi":"đủ mọi loại"},{"en":"sort by size","vi":"phân loại theo kích thước"},{"en":"sort out a problem","vi":"giải quyết một vấn đề"},{"en":"sort of","vi":"có chút; phần nào"}],"wordFamily":["sorting (n.)","sorter (n.)"],"synonyms":["type","kind","classify"],"antonyms":[],"tipVi":"a sort of dùng để chỉ \"một loại\"; cụm sort of trong văn nói còn mang nghĩa là \"có chút, phần nào\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_arrange', 'en-a2-38', 'arrange', '/əˈreɪndʒ/', 'A2', 'sắp xếp; chuẩn bị; bố trí; xếp đặt; sắp xếp theo thứ tự', 'v.', 'arrangement (n.), rearrange (v.)', 'Đồng nghĩa: organise, plan', 'Cấu trúc sắp xếp cho ai làm việc gì dùng arrange for sb to do.', 'I arranged to meet my cousin outside the cinema.', NULL, 'Tôi đã hẹn gặp người em họ của mình bên ngoài rạp chiếu phim.', '{"wordId":"arrange","ukIpa":"/əˈreɪndʒ/","usIpa":"/əˈreɪndʒ/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"Make plans or preparations for something to happen.","vi":"sắp xếp; chuẩn bị; bố trí"},{"pos":"v.","en":"Put things in a particular order or position.","vi":"xếp đặt; sắp xếp theo thứ tự"}],"examples":[{"en":"I arranged to meet my cousin outside the cinema.","vi":"Tôi đã hẹn gặp người em họ của mình bên ngoài rạp chiếu phim.","audioKind":"ex"},{"en":"Schools can arrange visits to local businesses to help students understand the practical demands of different careers.","vi":"Nhà trường có thể tổ chức cho học sinh đi tham quan các doanh nghiệp địa phương để giúp các em hiểu rõ hơn về yêu cầu thực tế của các ngành nghề khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"arrange a meeting","vi":"sắp xếp một cuộc họp"},{"en":"arrange to meet","vi":"hẹn gặp"},{"en":"arrange for someone to do something","vi":"lo liệu cho ai làm việc gì"},{"en":"arrange flowers","vi":"cắm hoa"}],"wordFamily":["arrangement (n.)","rearrange (v.)"],"synonyms":["organise","plan"],"antonyms":[],"tipVi":"Cấu trúc sắp xếp cho ai làm việc gì dùng arrange for sb to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fix', 'en-a2-38', 'fix', '/fɪks/', 'A2', 'sửa chữa; giải quyết; cố định; lắp đặt; xác định; sắp xếp', 'v.', 'fixed (adj.), fixing (n.)', NULL, 'fix vừa có thể dùng để sửa chữa đồ vật, vừa có thể giải quyết vấn đề hoặc xác định ngày giờ.', 'My neighbour helped me fix the broken kitchen tap.', NULL, 'Hàng xóm đã giúp tôi sửa vòi nước bếp bị hỏng.', '{"wordId":"fix","ukIpa":"/fɪks/","usIpa":"/fɪks/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"Make something work properly or solve a problem.","vi":"sửa chữa; giải quyết"},{"pos":"v.","en":"Attach something firmly in a particular place.","vi":"cố định; lắp đặt"},{"pos":"v.","en":"Decide an exact time, price, or arrangement.","vi":"xác định; sắp xếp"}],"examples":[{"en":"My neighbour helped me fix the broken kitchen tap.","vi":"Hàng xóm đã giúp tôi sửa vòi nước bếp bị hỏng.","audioKind":"ex"},{"en":"Governments should fix weaknesses in existing transport networks before investing in expensive new infrastructure.","vi":"Chính phủ nên khắc phục những điểm yếu trong mạng lưới giao thông hiện tại trước khi đầu tư vào cơ sở hạ tầng mới đắt đỏ.","audioKind":"ex2"}],"collocations":[{"en":"fix a problem","vi":"giải quyết vấn đề"},{"en":"fix a date","vi":"ấn định ngày"},{"en":"fix something to a wall","vi":"cố định vật gì vào tường"},{"en":"fix a leak","vi":"sửa chỗ rò rỉ"}],"wordFamily":["fixed (adj.)","fixing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"fix vừa có thể dùng để sửa chữa đồ vật, vừa có thể giải quyết vấn đề hoặc xác định ngày giờ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bin', 'en-a2-38', 'bin', '/bɪn/', 'A2', 'thùng rác; thùng đựng đồ; vứt bỏ; bỏ vào thùng rác', 'n.', NULL, NULL, '"Thùng rác" tiếng Anh-Anh thường dùng bin, còn tiếng Anh-Mỹ thường dùng trash can.', 'Please put the banana skin in the kitchen bin.', NULL, 'Xin hãy vứt vỏ chuối vào thùng rác trong bếp.', '{"wordId":"bin","ukIpa":"/bɪn/","usIpa":"/bɪn/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A container used for rubbish or for storing things.","vi":"thùng rác; thùng đựng đồ"},{"pos":"v.","en":"To throw something away, especially into a rubbish container.","vi":"vứt bỏ; bỏ vào thùng rác"}],"examples":[{"en":"Please put the banana skin in the kitchen bin.","vi":"Xin hãy vứt vỏ chuối vào thùng rác trong bếp.","audioKind":"ex"},{"en":"Providing a separate bin for food waste can help households recycle more effectively and reduce landfill use.","vi":"Việc cung cấp một thùng đựng rác thực phẩm riêng biệt có thể giúp các hộ gia đình tái chế hiệu quả hơn và giảm lượng rác thải chôn lấp.","audioKind":"ex2"}],"collocations":[{"en":"rubbish bin","vi":"thùng rác"},{"en":"recycling bin","vi":"thùng tái chế"},{"en":"storage bin","vi":"thùng đựng đồ"},{"en":"empty the bin","vi":"đổ rác"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"\"Thùng rác\" tiếng Anh-Anh thường dùng bin, còn tiếng Anh-Mỹ thường dùng trash can.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grilled', 'en-a2-38', 'grilled', '/ɡrɪld/', 'A2', 'được nướng; được quay (bằng nhiệt trực tiếp mạnh)', 'adj.', 'grill (v.), grilling (n.)', NULL, 'grilled nhấn mạnh phương pháp nướng trực tiếp bằng nhiệt độ cao; không mang nghĩa "có kẻ ô".', 'We shared grilled vegetables and warm bread for lunch.', NULL, 'Chúng tôi ăn chung rau củ nướng và bánh mì ấm cho bữa trưa.', '{"wordId":"grilled","ukIpa":"/ɡrɪld/","usIpa":"/ɡrɪld/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Cooked using strong direct heat, often on a metal rack.","vi":"được nướng; được quay (bằng nhiệt trực tiếp mạnh)"}],"examples":[{"en":"We shared grilled vegetables and warm bread for lunch.","vi":"Chúng tôi ăn chung rau củ nướng và bánh mì ấm cho bữa trưa.","audioKind":"ex"},{"en":"Offering grilled fish alongside plant-based dishes can help school cafeterias provide a wider range of nutritious meals.","vi":"Việc cung cấp cá nướng bên cạnh các món ăn từ thực vật có thể giúp các nhà ăn trường học cung cấp nhiều bữa ăn bổ dưỡng đa dạng hơn.","audioKind":"ex2"}],"collocations":[{"en":"grilled chicken","vi":"gà nướng"},{"en":"grilled fish","vi":"cá nướng"},{"en":"grilled vegetables","vi":"rau củ nướng"}],"wordFamily":["grill (v.)","grilling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"grilled nhấn mạnh phương pháp nướng trực tiếp bằng nhiệt độ cao; không mang nghĩa \"có kẻ ô\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_post', 'en-a2-38', 'post', '/poʊst/', 'A2', 'thư tín; bưu kiện; hệ thống bưu chính; gửi qua đường bưu điện; đăng tải công khai; chức vụ; vị trí công tác', 'n.', 'postal (adj.), postage (n.), posting (n.)', 'Đồng nghĩa: mail', 'Với nghĩa gửi bưu phẩm, tiếng Anh-Anh thường dùng post, trong khi tiếng Anh-Mỹ thường dùng mail.', 'A parcel arrived in the post this morning.', NULL, 'Một bưu kiện đã được gửi đến qua đường bưu điện sáng nay.', '{"wordId":"post","ukIpa":"/pəʊst/","usIpa":"/poʊst/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Letters and parcels, or the system used to deliver them.","vi":"thư tín; bưu kiện; hệ thống bưu chính"},{"pos":"v.","en":"To send something by mail or share it publicly.","vi":"gửi qua đường bưu điện; đăng tải công khai"},{"pos":"n.","en":"A job or position in an organisation.","vi":"chức vụ; vị trí công tác"}],"examples":[{"en":"A parcel arrived in the post this morning.","vi":"Một bưu kiện đã được gửi đến qua đường bưu điện sáng nay.","audioKind":"ex"},{"en":"Local authorities should post regular updates online to keep residents informed about changes to public services.","vi":"Chính quyền địa phương nên thường xuyên đăng tải các cập nhật trực tuyến để thông báo cho người dân về những thay đổi trong dịch vụ công.","audioKind":"ex2"}],"collocations":[{"en":"by post","vi":"qua đường bưu điện"},{"en":"post a letter","vi":"gửi thư"},{"en":"post online","vi":"đăng lên mạng"},{"en":"apply for a post","vi":"nộp đơn ứng tuyển vị trí"}],"wordFamily":["postal (adj.)","postage (n.)","posting (n.)"],"synonyms":["mail"],"antonyms":[],"tipVi":"Với nghĩa gửi bưu phẩm, tiếng Anh-Anh thường dùng post, trong khi tiếng Anh-Mỹ thường dùng mail.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fit', 'en-a2-38', 'fit', '/fɪt/', 'A2', 'vừa vặn; thích hợp; vừa; khỏe mạnh; cường tráng; đủ tiêu chuẩn', 'v.', 'fitness (n.), fitted (adj.), fitting (n.), unfit (adj.)', 'Đồng nghĩa: suit, healthy · Trái nghĩa: unfit', 'fit đối với quần áo chỉ kích cỡ vừa vặn; suit thường chỉ kiểu dáng hoặc màu sắc phù hợp.', 'These boots fit perfectly, even with my thick socks.', NULL, 'Đôi bốt này vừa vặn hoàn hảo, ngay cả khi tôi đi tất dày.', '{"wordId":"fit","ukIpa":"/fɪt/","usIpa":"/fɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To be the right size, shape, or type for something.","vi":"vừa vặn; thích hợp; vừa"},{"pos":"adj.","en":"Physically healthy and strong, especially through exercise.","vi":"khỏe mạnh; cường tráng"},{"pos":"adj.","en":"Suitable or good enough for a particular purpose.","vi":"thích hợp; đủ tiêu chuẩn"}],"examples":[{"en":"These boots fit perfectly, even with my thick socks.","vi":"Đôi bốt này vừa vặn hoàn hảo, ngay cả khi tôi đi tất dày.","audioKind":"ex"},{"en":"Public exercise facilities can help older adults stay fit while strengthening social connections within their communities.","vi":"Các cơ sở tập thể dục công cộng có thể giúp người cao tuổi duy trì sức khỏe đồng thời tăng cường sự kết nối xã hội trong cộng đồng của họ.","audioKind":"ex2"}],"collocations":[{"en":"keep fit","vi":"giữ gìn vóc dáng"},{"en":"fit perfectly","vi":"vừa vặn hoàn hảo"},{"en":"fit for purpose","vi":"phù hợp với mục đích"},{"en":"fit in with","vi":"hòa nhập với; thích nghi với"}],"wordFamily":["fitness (n.)","fitted (adj.)","fitting (n.)","unfit (adj.)"],"synonyms":["suit","healthy"],"antonyms":["unfit"],"tipVi":"fit đối với quần áo chỉ kích cỡ vừa vặn; suit thường chỉ kiểu dáng hoặc màu sắc phù hợp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_normal', 'en-a2-38', 'normal', '/ˈnɔːrməl/', 'A2', 'bình thường; theo quy luật; trạng thái bình thường; mức bình thường', 'adj.', 'normally (adv.), normality (n.), abnormal (adj.)', 'Đồng nghĩa: usual, typical · Trái nghĩa: abnormal, unusual', 'normal nhấn mạnh sự phù hợp với quy luật chung; ordinary nhấn mạnh tính thông thường, không có gì đặc biệt.', 'It is normal to feel nervous before an interview.', NULL, 'Cảm thấy hồi hộp trước một buổi phỏng vấn là điều bình thường.', '{"wordId":"normal","ukIpa":"/ˈnɔːməl/","usIpa":"/ˈnɔːrməl/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"usual, expected, or typical in a particular situation","vi":"bình thường; theo quy luật"},{"pos":"n.","en":"the usual state or level of something","vi":"trạng thái bình thường; mức bình thường"}],"examples":[{"en":"It is normal to feel nervous before an interview.","vi":"Cảm thấy hồi hộp trước một buổi phỏng vấn là điều bình thường.","audioKind":"ex"},{"en":"Flexible working hours are becoming a normal feature of employment in many sectors of the economy.","vi":"Giờ làm việc linh hoạt đang dần trở thành một nét bình thường trong việc làm ở nhiều lĩnh vực kinh tế.","audioKind":"ex2"}],"collocations":[{"en":"normal life","vi":"cuộc sống bình thường"},{"en":"return to normal","vi":"trở lại bình thường"},{"en":"perfectly normal","vi":"hoàn toàn bình thường"},{"en":"normal working hours","vi":"giờ làm việc bình thường"}],"wordFamily":["normally (adv.)","normality (n.)","abnormal (adj.)"],"synonyms":["usual","typical"],"antonyms":["abnormal","unusual"],"tipVi":"normal nhấn mạnh sự phù hợp với quy luật chung; ordinary nhấn mạnh tính thông thường, không có gì đặc biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_amount', 'en-a2-38', 'amount', '/əˈmaʊnt/', 'A2', 'lượng; số lượng; lên tới; tương đương với', 'n.', NULL, 'Đồng nghĩa: quantity', 'amount of đi với danh từ không đếm được; đối với động từ, thường dùng cụm amount to.', 'Add a small amount of milk to the bowl.', NULL, 'Cho một lượng nhỏ sữa vào tô.', '{"wordId":"amount","ukIpa":"/əˈmaʊnt/","usIpa":"/əˈmaʊnt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"How much of something there is.","vi":"lượng; số lượng"},{"pos":"v.","en":"To total something or be equivalent to it.","vi":"lên tới; tương đương với"}],"examples":[{"en":"Add a small amount of milk to the bowl.","vi":"Cho một lượng nhỏ sữa vào tô.","audioKind":"ex"},{"en":"Reducing the amount of food wasted by households could significantly lower the environmental impact of food production.","vi":"Việc giảm lượng thực phẩm bị lãng phí bởi các hộ gia đình có thể làm giảm đáng kể tác động môi trường từ việc sản xuất lương thực.","audioKind":"ex2"}],"collocations":[{"en":"a large amount of","vi":"một lượng lớn"},{"en":"total amount","vi":"tổng số lượng"},{"en":"amount to","vi":"lên tới; tương đương với"}],"wordFamily":[],"synonyms":["quantity"],"antonyms":[],"tipVi":"amount of đi với danh từ không đếm được; đối với động từ, thường dùng cụm amount to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pass', 'en-a2-38', 'pass', '/pæs/', 'A2', 'đi qua; vượt qua; chuyển; trao; đỗ; đạt (kỳ thi)', 'v.', 'passing (adj.), passer-by (n.)', NULL, 'pass là động từ; past có thể làm giới từ: walk past.', 'We pass a small bakery on our way home.', NULL, 'Chúng tôi đi qua một tiệm bánh nhỏ trên đường về nhà.', '{"wordId":"pass","ukIpa":"/pɑːs/","usIpa":"/pæs/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To move past something or through a place.","vi":"đi qua; vượt qua"},{"pos":"v.","en":"To give something to another person.","vi":"chuyển; trao"},{"pos":"v.","en":"To achieve the required standard in an examination or test.","vi":"đỗ; đạt (kỳ thi)"}],"examples":[{"en":"We pass a small bakery on our way home.","vi":"Chúng tôi đi qua một tiệm bánh nhỏ trên đường về nhà.","audioKind":"ex"},{"en":"Students must pass a practical assessment before they can begin working independently in the laboratory.","vi":"Học sinh phải vượt qua kỳ kiểm tra thực hành trước khi có thể bắt đầu làm việc độc lập trong phòng thí nghiệm.","audioKind":"ex2"}],"collocations":[{"en":"pass an exam","vi":"thi đỗ; vượt qua kỳ thi"},{"en":"pass the ball","vi":"chuyền bóng"},{"en":"pass through","vi":"đi xuyên qua; ghé qua"}],"wordFamily":["passing (adj.)","passer-by (n.)"],"synonyms":[],"antonyms":[],"tipVi":"pass là động từ; past có thể làm giới từ: walk past.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_honey', 'en-a2-38', 'honey', '/ˈhʌn.i/', 'A2', 'mật ong', 'n.', NULL, NULL, 'Khi chỉ mật ong thì đây là danh từ không đếm được; một hũ mật ong nói là a jar of honey.', 'She stirred a spoonful of honey into her tea.', NULL, 'Cô ấy khuấy một thìa mật ong vào tách trà của mình.', '{"wordId":"honey","ukIpa":"/ˈhʌn.i/","usIpa":"/ˈhʌn.i/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a sweet, sticky food made by bees","vi":"mật ong"}],"examples":[{"en":"She stirred a spoonful of honey into her tea.","vi":"Cô ấy khuấy một thìa mật ong vào tách trà của mình.","audioKind":"ex"},{"en":"Local honey production can provide rural income while encouraging farmers to protect habitats for bees.","vi":"Việc sản xuất mật ong địa phương có thể mang lại thu nhập cho nông thôn đồng thời khuyến khích nông dân bảo vệ môi trường sống cho loài ong.","audioKind":"ex2"}],"collocations":[{"en":"a spoonful of honey","vi":"một thìa mật ong"},{"en":"a jar of honey","vi":"một hũ mật ong"},{"en":"honey production","vi":"sản xuất mật ong"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ mật ong thì đây là danh từ không đếm được; một hũ mật ong nói là a jar of honey.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shorts', 'en-a2-38', 'shorts', '/ʃɔːrts/', 'A2', 'quần đùi; quần sọc', 'n.', 'short (adj.)', NULL, 'shorts luôn ở dạng số nhiều; một chiếc quần đùi nói là a pair of shorts.', 'I packed shorts and sandals for our beach holiday.', NULL, 'Tôi đã chuẩn bị quần đùi và dép sandal cho kỳ nghỉ ở bãi biển của chúng tôi.', '{"wordId":"shorts","ukIpa":"/ʃɔːts/","usIpa":"/ʃɔːrts/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"trousers with legs ending above or near the knees","vi":"quần đùi; quần sọc"}],"examples":[{"en":"I packed shorts and sandals for our beach holiday.","vi":"Tôi đã chuẩn bị quần đùi và dép sandal cho kỳ nghỉ ở bãi biển của chúng tôi.","audioKind":"ex"},{"en":"In hot weather, lightweight shorts can help people stay comfortable while taking part in outdoor exercise.","vi":"Trong thời tiết nóng bức, quần đùi mỏng nhẹ có thể giúp mọi người cảm thấy thoải mái khi tham gia tập thể dục ngoài trời.","audioKind":"ex2"}],"collocations":[{"en":"a pair of shorts","vi":"một chiếc quần đùi"},{"en":"wear shorts","vi":"mặc quần đùi"},{"en":"denim shorts","vi":"quần đùi jean"},{"en":"running shorts","vi":"quần đùi chạy bộ"}],"wordFamily":["short (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"shorts luôn ở dạng số nhiều; một chiếc quần đùi nói là a pair of shorts.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bracelet', 'en-a2-38', 'bracelet', '/ˈbreɪslət/', 'A2', 'vòng đeo tay; lắc tay', 'n.', NULL, NULL, 'bracelet đeo ở cổ tay; anklet đeo ở cổ chân.', 'She wears a silver bracelet that her grandmother gave her.', NULL, 'Cô ấy đeo một chiếc vòng tay bằng bạc do bà của cô tặng.', '{"wordId":"bracelet","ukIpa":"/ˈbreɪslət/","usIpa":"/ˈbreɪslət/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A piece of jewellery worn around the wrist.","vi":"vòng đeo tay; lắc tay"}],"examples":[{"en":"She wears a silver bracelet that her grandmother gave her.","vi":"Cô ấy đeo một chiếc vòng tay bằng bạc do bà của cô tặng.","audioKind":"ex"},{"en":"A handmade bracelet can reflect local artistic traditions while providing income for craftspeople in rural communities.","vi":"Một chiếc vòng tay thủ công có thể phản ánh truyền thống nghệ thuật địa phương đồng thời tạo thu nhập cho các nghệ nhân ở các cộng đồng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"silver bracelet","vi":"vòng tay bạc; lắc tay bạc"},{"en":"charm bracelet","vi":"vòng tay đính hạt charm"},{"en":"wear a bracelet","vi":"đeo vòng tay"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"bracelet đeo ở cổ tay; anklet đeo ở cổ chân.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_board', 'en-a2-38', 'board', '/bɔːrd/', 'A2', 'tấm ván; bảng; ban quản trị; hội đồng quản trị; lên (tàu, máy bay, tàu hỏa hoặc xe buýt)', 'n.', 'boarding (n.)', NULL, 'board khi là động từ có thể kết hợp trực tiếp với phương tiện giao thông: board a train.', 'She placed a wooden board across the muddy path.', NULL, 'Cô ấy đặt một tấm ván gỗ bắc qua con đường lầy lội.', '{"wordId":"board","ukIpa":"/bɔːd/","usIpa":"/bɔːrd/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A flat piece of wood or other firm material.","vi":"tấm ván; bảng"},{"pos":"n.","en":"A group responsible for managing an organisation or making decisions.","vi":"ban quản trị; hội đồng quản trị"},{"pos":"v.","en":"Get onto a ship, aircraft, train, or bus.","vi":"lên (tàu, máy bay, tàu hỏa hoặc xe buýt)"}],"examples":[{"en":"She placed a wooden board across the muddy path.","vi":"Cô ấy đặt một tấm ván gỗ bắc qua con đường lầy lội.","audioKind":"ex"},{"en":"The board approved a plan to reduce factory emissions without cutting jobs or lowering wages.","vi":"Hội đồng quản trị đã thông qua kế hoạch giảm lượng khí thải của nhà máy mà không cần cắt giảm việc làm hay hạ mức lương.","audioKind":"ex2"}],"collocations":[{"en":"a wooden board","vi":"một tấm ván gỗ"},{"en":"board of directors","vi":"hội đồng quản trị"},{"en":"board a plane","vi":"lên máy bay"},{"en":"on board","vi":"ở trên tàu/máy bay"}],"wordFamily":["boarding (n.)"],"synonyms":[],"antonyms":[],"tipVi":"board khi là động từ có thể kết hợp trực tiếp với phương tiện giao thông: board a train.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sunglasses', 'en-a2-38', 'sunglasses', '/ˈsʌnɡlæsɪz/', 'A2', 'kính râm; kính mát', 'n.', 'sunglass (adj.)', 'Đồng nghĩa: shades', 'Thường dùng ở dạng số nhiều; một cặp kính nói là a pair of sunglasses.', 'I put on my sunglasses before leaving the house.', NULL, 'Tôi đeo kính râm trước khi rời khỏi nhà.', '{"wordId":"sunglasses","ukIpa":"/ˈsʌnɡlɑːsɪz/","usIpa":"/ˈsʌnɡlæsɪz/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"glasses with dark lenses that protect eyes from bright sunlight","vi":"kính râm; kính mát"}],"examples":[{"en":"I put on my sunglasses before leaving the house.","vi":"Tôi đeo kính râm trước khi rời khỏi nhà.","audioKind":"ex"},{"en":"Wearing sunglasses with adequate ultraviolet protection can reduce the risk of eye damage during outdoor activities.","vi":"Việc đeo kính râm có khả năng chống tia cực tím đầy đủ có thể làm giảm nguy cơ tổn thương mắt trong các hoạt động ngoài trời.","audioKind":"ex2"}],"collocations":[{"en":"a pair of sunglasses","vi":"một cặp kính râm"},{"en":"wear sunglasses","vi":"đeo kính râm"},{"en":"put on sunglasses","vi":"đeo kính râm vào"}],"wordFamily":["sunglass (adj.)"],"synonyms":["shades"],"antonyms":[],"tipVi":"Thường dùng ở dạng số nhiều; một cặp kính nói là a pair of sunglasses.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_make-up', 'en-a2-38', 'make-up', '/ˈmeɪk ʌp/', 'A2', 'mỹ phẩm; đồ trang điểm; sự cấu thành; thành phần cấu tạo', 'n.', NULL, 'Đồng nghĩa: cosmetics, composition', 'Danh từ cũng được viết là makeup; cụm động từ make up không có dấu gạch nối.', 'She keeps her make-up in a small blue bag.', NULL, 'Cô ấy giữ đồ trang điểm của mình trong một chiếc túi nhỏ màu xanh lam.', '{"wordId":"make-up","ukIpa":"/ˈmeɪk ʌp/","usIpa":"/ˈmeɪk ʌp/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Products applied to the face to change or enhance appearance.","vi":"mỹ phẩm; đồ trang điểm"},{"pos":"n.","en":"The parts or qualities that together form something.","vi":"sự cấu thành; thành phần cấu tạo"}],"examples":[{"en":"She keeps her make-up in a small blue bag.","vi":"Cô ấy giữ đồ trang điểm của mình trong một chiếc túi nhỏ màu xanh lam.","audioKind":"ex"},{"en":"The social make-up of a neighbourhood can change significantly as new housing attracts different residents.","vi":"Cấu trúc xã hội của một khu1 dân cư có thể thay đổi đáng kể khi nhà ở mới thu hút các cư dân khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"wear make-up","vi":"trang điểm"},{"en":"apply make-up","vi":"thoa lớp trang điểm"},{"en":"remove make-up","vi":"tẩy trang"},{"en":"genetic make-up","vi":"cấu trúc di truyền"}],"wordFamily":[],"synonyms":["cosmetics","composition"],"antonyms":[],"tipVi":"Danh từ cũng được viết là makeup; cụm động từ make up không có dấu gạch nối.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cover', 'en-a2-38', 'cover', '/ˈkʌvər/', 'A2', 'phủ; che đậy; bao gồm; đề cập đến; chi trả; vật che phủ; bìa sách; vỏ bọc', 'v.', 'coverage (n.), covering (n.), uncover (v.), uncovered (adj.)', NULL, 'cover A with B có nghĩa là dùng B để phủ lên A; cover một khoản chi phí nghĩa là đủ tiền chi trả.', 'Cover the bread with a cloth while it cools.', NULL, 'Dùng một chiếc khăn phủ bánh mì lại trong lúc để nguội.', '{"wordId":"cover","ukIpa":"/ˈkʌvə/","usIpa":"/ˈkʌvər/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To put something over a surface or object.","vi":"phủ; che đậy"},{"pos":"v.","en":"To include something, deal with it, or pay its cost.","vi":"bao gồm; đề cập đến; chi trả"},{"pos":"n.","en":"An outer layer that protects or encloses something.","vi":"vật che phủ; bìa sách; vỏ bọc"}],"examples":[{"en":"Cover the bread with a cloth while it cools.","vi":"Dùng một chiếc khăn phủ bánh mì lại trong lúc để nguội.","audioKind":"ex"},{"en":"University scholarships should cover living expenses as well as tuition fees for students from low-income families.","vi":"Học bổng đại học nên chi trả cả chi phí sinh hoạt lẫn học phí cho sinh viên đến từ các gia đình thu nhập thấp.","audioKind":"ex2"}],"collocations":[{"en":"cover something with","vi":"che phủ cái gì bằng"},{"en":"cover the cost","vi":"chi trả chi phí"},{"en":"cover a topic","vi":"đề cập đến một chủ đề"},{"en":"a book cover","vi":"bìa sách"}],"wordFamily":["coverage (n.)","covering (n.)","uncover (v.)","uncovered (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"cover A with B có nghĩa là dùng B để phủ lên A; cover một khoản chi phí nghĩa là đủ tiền chi trả.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_everywhere', 'en-a2-38', 'everywhere', '/ˈevriwer/', 'A2', 'khắp mọi nơi; đâu đâu cũng có', 'adv.', NULL, 'Trái nghĩa: nowhere', 'everywhere là trạng từ nên thường không đi kèm giới từ như in hoặc at ở phía trước.', 'We looked everywhere, but the kitten was under the sofa.', NULL, 'Chúng tôi tìm kiếm khắp mọi nơi, hóa ra chú mèo con ở dưới gầm ghế sofa.', '{"wordId":"everywhere","ukIpa":"/ˈevriweə/","usIpa":"/ˈevriwer/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"in, at, or to all places","vi":"khắp mọi nơi; đâu đâu cũng có"}],"examples":[{"en":"We looked everywhere, but the kitten was under the sofa.","vi":"Chúng tôi tìm kiếm khắp mọi nơi, hóa ra chú mèo con ở dưới gầm ghế sofa.","audioKind":"ex"},{"en":"Although digital services are expanding rapidly, reliable internet access is not yet available everywhere.","vi":"Mặc dù các dịch vụ số đang phát triển nhanh chóng, quyền truy cập internet ổn định vẫn chưa có sẵn ở mọi nơi.","audioKind":"ex2"}],"collocations":[{"en":"look everywhere","vi":"tìm kiếm khắp nơi"},{"en":"almost everywhere","vi":"gần như mọi nơi"},{"en":"everywhere else","vi":"mọi nơi khác"}],"wordFamily":[],"synonyms":[],"antonyms":["nowhere"],"tipVi":"everywhere là trạng từ nên thường không đi kèm giới từ như in hoặc at ở phía trước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scarf', 'en-a2-38', 'scarf', '/skɑːrf/', 'A2', 'khăn choàng cổ; khăn đội đầu', 'n.', NULL, NULL, 'Dạng số nhiều có thể là scarves hoặc scarfs, trong đó scarves phổ biến hơn.', 'She wrapped a wool scarf around her neck.', NULL, 'Cô ấy quấn một chiếc khăn len quanh cổ.', '{"wordId":"scarf","ukIpa":"/skɑːf/","usIpa":"/skɑːrf/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Cloth worn around the neck or head.","vi":"khăn choàng cổ; khăn đội đầu"}],"examples":[{"en":"She wrapped a wool scarf around her neck.","vi":"Cô ấy quấn một chiếc khăn len quanh cổ.","audioKind":"ex"},{"en":"In colder regions, a locally woven scarf can reflect traditional craftsmanship while providing essential warmth.","vi":"Ở những vùng lạnh hơn, chiếc khăn dệt thủ công có thể phản ánh nghề thủ công truyền thống đồng thời mang lại sự ấm áp cần thiết.","audioKind":"ex2"}],"collocations":[{"en":"wear a scarf","vi":"đeo khăn choàng"},{"en":"a wool scarf","vi":"khăn len"},{"en":"wrap a scarf around your neck","vi":"quấn khăn quanh cổ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Dạng số nhiều có thể là scarves hoặc scarfs, trong đó scarves phổ biến hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_38_1', 'en-a2-38', 'Cách dùng “fried” (adj.) — được chiên; được rán bằng dầu mỡ', 'fried rice  ·  fried eggs  ·  deep-fried food', 'fried là quá khứ và phân từ hai của động từ fry, đồng thời cũng đóng vai trò là tính từ; không giới hạn chỉ ở đồ chiên.', 'Họ từ (Word Family): fry (v.), frying (n.), fryer (n.)', '[{"hanzi":"We had fried eggs and toast for breakfast.","pinyin":"","meaning":"Bữa sáng hôm nay chúng tôi ăn trứng ơ-lết chiên và bánh mì nướng."},{"hanzi":"Eating fried foods too frequently can increase calorie intake and make maintaining a healthy weight more difficult.","pinyin":"","meaning":"Việc ăn đồ chiên rán quá thường xuyên có thể làm tăng lượng calo nạp vào và khiến việc duy trì cân nặng lành mạnh trở nên khó khăn hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_38_2', 'en-a2-38', 'Cách dùng “normal” (adj.) — bình thường; theo quy luật', 'normal life  ·  return to normal  ·  perfectly normal', 'normal nhấn mạnh sự phù hợp với quy luật chung; ordinary nhấn mạnh tính thông thường, không có gì đặc biệt.', 'Họ từ (Word Family): normally (adv.), normality (n.), abnormal (adj.) | Đồng nghĩa: usual, typical · Trái nghĩa: abnormal, unusual', '[{"hanzi":"It is normal to feel nervous before an interview.","pinyin":"","meaning":"Cảm thấy hồi hộp trước một buổi phỏng vấn là điều bình thường."},{"hanzi":"Flexible working hours are becoming a normal feature of employment in many sectors of the economy.","pinyin":"","meaning":"Giờ làm việc linh hoạt đang dần trở thành một nét bình thường trong việc làm ở nhiều lĩnh vực kinh tế."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_38_3', 'en-a2-38', 'Cách dùng “ourselves” (pron.) — chúng tôi (chính mình); chúng ta (chính mình)', 'by ourselves  ·  enjoy ourselves  ·  pride ourselves on', 'by ourselves có thể mang nghĩa là một mình, hoặc tự làm mà không cần nhờ đến sự trợ giúp của người khác.', 'Họ từ (Word Family): we (pron.), us (pron.), our (det.), ours (pron.)', '[{"hanzi":"We saw ourselves reflected in the clear lake.","pinyin":"","meaning":"Chúng tôi thấy bóng mình phản chiếu trên mặt hồ trong vắt."},{"hanzi":"By involving ourselves in community projects, we can develop practical skills and strengthen local relationships.","pinyin":"","meaning":"Bằng cách tự mình tham gia vào các dự án cộng đồng, chúng tôi có thể phát triển các kỹ năng thực tế và củng cố mối quan hệ địa phương."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_38_4', 'en-a2-38', 'Cách dùng “common” (adj.) — phổ biến; thông thường; hay gặp', 'a common problem  ·  a common goal  ·  have something in common', 'common chỉ sự phổ biến hoặc thuộc về chung; ordinary nhấn mạnh tính bình thường, không có gì đặc biệt.', 'Họ từ (Word Family): commonly (adv.), uncommon (adj.) | Đồng nghĩa: frequent, widespread, shared · Trái nghĩa: rare, uncommon', '[{"hanzi":"Heavy rain is common here during the summer.","pinyin":"","meaning":"Mưa lớn là chuyện thường thấy ở đây vào mùa hè."},{"hanzi":"Governments should address the common challenges that prevent rural communities from accessing affordable healthcare.","pinyin":"","meaning":"Chính phủ nên giải quyết những thách thức chung vốn đang cản trở các cộng đồng nông thôn tiếp cận dịch vụ y tế phải chăng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_38_1', 'en-a2-38', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_38_1_1', 'ten_a2_38_1', 'stick', 'The dog brought a stick back to me.', 'The dog brought a stick back to me.', '/stɪk/', 'Con chó đã ngậm một cành cây mang lại cho tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_38_1_2', 'ten_a2_38_1', 'common', 'Heavy rain is common here during the summer.', 'Heavy rain is common here during the summer.', '/ˈkɑːmən/', 'Mưa lớn là chuyện thường thấy ở đây vào mùa hè.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_38_1_3', 'ten_a2_38_1', 'kettle', 'Put the kettle on while I find the cups.', 'Put the kettle on while I find the cups.', '/ˈketəl/', 'Bạn đi đun nước đi trong lúc tôi tìm cốc nhé.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_38_1_4', 'ten_a2_38_1', 'opposite', 'We left the station and walked in opposite directions.', 'We left the station and walked in opposite directions.', '/ˈɑːpəzɪt/', 'Chúng tôi rời nhà ga và đi theo hai hướng ngược nhau.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_38_1_5', 'ten_a2_38_1', 'ourselves', 'We saw ourselves reflected in the clear lake.', 'We saw ourselves reflected in the clear lake.', '/aʊrˈselvz/', 'Chúng tôi thấy bóng mình phản chiếu trên mặt hồ trong vắt.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_38_1_6', 'ten_a2_38_1', 'fried', 'We had fried eggs and toast for breakfast.', 'We had fried eggs and toast for breakfast.', '/fraɪd/', 'Bữa sáng hôm nay chúng tôi ăn trứng ơ-lết chiên và bánh mì nướng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_38_1_7', 'ten_a2_38_1', 'offer', 'Our neighbour offered to carry the heavy bags upstairs.', 'Our neighbour offered to carry the heavy bags upstairs.', '/ˈɔːfər/', 'Hàng xóm của chúng tôi đã chủ động đề nghị giúp chúng tôi mang những chiếc túi nặng lên lầu.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_38_1_8', 'ten_a2_38_1', 'sort', 'What sort of music do you listen to at home?', 'What sort of music do you listen to at home?', '/sɔːrt/', 'Bạn thường nghe loại nhạc gì ở nhà?', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_38_1_1', 'en-a2-38', 'ten_a2_38_1', 'listening', 'listening', 'The dog brought a stick back to me.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cho một lượng nhỏ sữa vào tô.","Hàng xóm đã giúp tôi sửa vòi nước bếp bị hỏng.","Con chó đã ngậm một cành cây mang lại cho tôi.","Bạn thường nghe loại nhạc gì ở nhà?"]'::jsonb, 2, 'The dog brought a stick back to me. → Con chó đã ngậm một cành cây mang lại cho tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_38_1_2', 'en-a2-38', 'ten_a2_38_1', 'listening', 'listening', 'Heavy rain is common here during the summer.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy khuấy một thìa mật ong vào tách trà của mình.","Mưa lớn là chuyện thường thấy ở đây vào mùa hè.","Cô ấy đeo một chiếc vòng tay bằng bạc do bà của cô tặng.","Cảm thấy hồi hộp trước một buổi phỏng vấn là điều bình thường."]'::jsonb, 1, 'Heavy rain is common here during the summer. → Mưa lớn là chuyện thường thấy ở đây vào mùa hè.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_38_1_3', 'en-a2-38', 'ten_a2_38_1', 'listening', 'listening', 'Put the kettle on while I find the cups.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hàng xóm đã giúp tôi sửa vòi nước bếp bị hỏng.","Dùng một chiếc khăn phủ bánh mì lại trong lúc để nguội.","Cho một lượng nhỏ sữa vào tô.","Bạn đi đun nước đi trong lúc tôi tìm cốc nhé."]'::jsonb, 3, 'Put the kettle on while I find the cups. → Bạn đi đun nước đi trong lúc tôi tìm cốc nhé.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_38_2', 'en-a2-38', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_38_2_1', 'ten_a2_38_2', 'stick', 'Students can stick pictures onto a shared poster to present their research on local wildlife.', 'Students can stick pictures onto a shared poster to present their research on local wildlife.', '/stɪk/', 'Học sinh có thể dán hình ảnh lên một tấm áp phích chung để trình bày nghiên cứu của các em về động vật hoang dã bản địa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_38_2_2', 'ten_a2_38_2', 'common', 'Governments should address the common challenges that prevent rural communities from accessing affordable healthcare.', 'Governments should address the common challenges that prevent rural communities from accessing affordable healthcare.', '/ˈkɑːmən/', 'Chính phủ nên giải quyết những thách thức chung vốn đang cản trở các cộng đồng nông thôn tiếp cận dịch vụ y tế phải chăng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_38_2_3', 'ten_a2_38_2', 'kettle', 'Boiling only the water needed in a kettle can reduce household electricity consumption over time.', 'Boiling only the water needed in a kettle can reduce household electricity consumption over time.', '/ˈketəl/', 'Việc chỉ đun lượng nước cần dùng trong ấm đun có thể giúp giảm lượng điện năng tiêu thụ của hộ gia đình theo thời gian.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_38_2_4', 'ten_a2_38_2', 'opposite', 'Although the policy aimed to reduce traffic, it had the opposite effect in several residential areas.', 'Although the policy aimed to reduce traffic, it had the opposite effect in several residential areas.', '/ˈɑːpəzɪt/', 'Mặc dù chính sách nhằm mục đích giảm thiểu lưu lượng giao thông, nhưng nó lại mang lại hiệu quả ngược lại ở một số khu dân cư.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_38_2_5', 'ten_a2_38_2', 'ourselves', 'By involving ourselves in community projects, we can develop practical skills and strengthen local relationships.', 'By involving ourselves in community projects, we can develop practical skills and strengthen local relationships.', '/aʊrˈselvz/', 'Bằng cách tự mình tham gia vào các dự án cộng đồng, chúng tôi có thể phát triển các kỹ năng thực tế và củng cố mối quan hệ địa phương.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_38_2_6', 'ten_a2_38_2', 'fried', 'Eating fried foods too frequently can increase calorie intake and make maintaining a healthy weight more difficult.', 'Eating fried foods too frequently can increase calorie intake and make maintaining a healthy weight more difficult.', '/fraɪd/', 'Việc ăn đồ chiên rán quá thường xuyên có thể làm tăng lượng calo nạp vào và khiến việc duy trì cân nặng lành mạnh trở nên khó khăn hơn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
