INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_38_2_2', 'en-a2-38', 'ten_a2_38_2', 'listening', 'listening', 'Governments should address the common challenges that prevent rural communities from accessing affordable healthcare.', NULL, 'Trong câu vừa nghe, từ “common” mang nghĩa nào sau đây?', '["giọng nói; tiếng nói","đuôi (động vật hoặc máy bay)","hữu ích; giúp ích","phổ biến; thông thường; hay gặp"]'::jsonb, 3, '“common” (/ˈkɑːmən/): phổ biến; thông thường; hay gặp. Câu đầy đủ: Governments should address the common challenges that prevent rural communities from accessing affordable healthcare.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
