INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_38_2', 'en-a2-38', NULL, 'comprehensive_test', 'listening', 'Heavy rain is common here during the summer.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy giữ đồ trang điểm của mình trong một chiếc túi nhỏ màu xanh lam.","Mưa lớn là chuyện thường thấy ở đây vào mùa hè.","Hàng xóm đã giúp tôi sửa vòi nước bếp bị hỏng.","Cô ấy đeo một chiếc vòng tay bằng bạc do bà của cô tặng."]'::jsonb, 1, 'Heavy rain is common here during the summer. → Mưa lớn là chuyện thường thấy ở đây vào mùa hè.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_38_3', 'en-a2-38', NULL, 'comprehensive_test', 'listening', 'kettle', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cái giỏ; cái sọt","ấm đun nước","giao thông vận tải; phương tiện giao thông","thuộc giới nữ; cái; mái"]'::jsonb, 1, 'kettle (/ˈketəl/) → ấm đun nước', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_38_4', 'en-a2-38', NULL, 'comprehensive_test', 'listening', 'We left the station and walked in opposite directions.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bữa sáng hôm nay chúng tôi ăn trứng ơ-lết chiên và bánh mì nướng.","Bạn thường nghe loại nhạc gì ở nhà?","Chúng tôi rời nhà ga và đi theo hai hướng ngược nhau.","Cảm thấy hồi hộp trước một buổi phỏng vấn là điều bình thường."]'::jsonb, 2, 'We left the station and walked in opposite directions. → Chúng tôi rời nhà ga và đi theo hai hướng ngược nhau.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_38_5', 'en-a2-38', NULL, 'comprehensive_test', 'listening', 'ourselves', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đẹp đẽ; dễ thương; xinh xắn","lên trên","xe máy; xe mô tô","chúng tôi (chính mình); chúng ta (chính mình)"]'::jsonb, 3, 'ourselves (/aʊrˈselvz/) → chúng tôi (chính mình); chúng ta (chính mình); tự chúng tôi; chính chúng tôi', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_38_6', 'en-a2-38', NULL, 'comprehensive_test', 'listening', 'We had fried eggs and toast for breakfast.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã hẹn gặp người em họ của mình bên ngoài rạp chiếu phim.","Tôi đeo kính râm trước khi rời khỏi nhà.","Bữa sáng hôm nay chúng tôi ăn trứng ơ-lết chiên và bánh mì nướng.","Mưa lớn là chuyện thường thấy ở đây vào mùa hè."]'::jsonb, 2, 'We had fried eggs and toast for breakfast. → Bữa sáng hôm nay chúng tôi ăn trứng ơ-lết chiên và bánh mì nướng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_38_7', 'en-a2-38', NULL, 'comprehensive_test', 'listening', 'offer', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["chương trình; kế hoạch; đề án","sinh học","ví tiền nhỏ; túi xách tay nữ","chủ động đề nghị; đề ra"]'::jsonb, 3, 'offer (/ˈɔːfər/) → chủ động đề nghị; đề ra; sự đề nghị; lời đề nghị; cơ hội; giấy báo trúng tuyển; ra giá; trả giá', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_38_8', 'en-a2-38', NULL, 'comprehensive_test', 'listening', 'What sort of music do you listen to at home?', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Dùng một chiếc khăn phủ bánh mì lại trong lúc để nguội.","Bạn thường nghe loại nhạc gì ở nhà?","Chúng tôi tìm kiếm khắp mọi nơi, hóa ra chú mèo con ở dưới gầm ghế sofa.","Tôi đã chuẩn bị quần đùi và dép sandal cho kỳ nghỉ ở bãi biển của chúng tôi."]'::jsonb, 1, 'What sort of music do you listen to at home? → Bạn thường nghe loại nhạc gì ở nhà?', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
