INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_38_18', 'en-a2-38', NULL, 'comprehensive_test', 'reading', NULL, 'Students can stick pictures onto a shared poster to present their research on local wildlife.', 'Dựa vào câu trên, từ “stick” có nghĩa phù hợp nhất là gì?', '["sân; khu đất quanh nhà (thường có rào chắn)","gậy; cành cây; thanh gỗ","người lao động; nhân viên; người làm thuê","môn khúc côn cầu"]'::jsonb, 1, 'stick: gậy; cành cây; thanh gỗ; dán; đính; dính vào; cắm; đâm; thọc. Dịch cả câu: Học sinh có thể dán hình ảnh lên một tấm áp phích chung để trình bày nghiên cứu của các em về động vật hoang dã bản địa.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_38_19', 'en-a2-38', NULL, 'comprehensive_test', 'reading', NULL, 'Governments should address the common challenges that prevent rural communities from accessing affordable healthcare.', 'Dựa vào câu trên, từ “common” có nghĩa phù hợp nhất là gì?', '["phổ biến; thông thường; hay gặp","xentimét; centimet","con bướm","có nghĩa là; ngụ ý; định"]'::jsonb, 0, 'common: phổ biến; thông thường; hay gặp; chung; chung cho nhiều người. Dịch cả câu: Chính phủ nên giải quyết những thách thức chung vốn đang cản trở các cộng đồng nông thôn tiếp cận dịch vụ y tế phải chăng.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_38_20', 'en-a2-38', NULL, 'comprehensive_test', 'reading', NULL, 'Boiling only the water needed in a kettle can reduce household electricity consumption over time.', 'Dựa vào câu trên, từ “kettle” có nghĩa phù hợp nhất là gì?', '["trang sức; đồ trang trí quý giá","đồ trang sức; trang sức; nữ trang","ấm đun nước","sôi; làm sôi"]'::jsonb, 2, 'kettle: ấm đun nước. Dịch cả câu: Việc chỉ đun lượng nước cần dùng trong ấm đun có thể giúp giảm lượng điện năng tiêu thụ của hộ gia đình theo thời gian.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_38_21', 'en-a2-38', NULL, 'comprehensive_test', 'reading', NULL, 'Although the policy aimed to reduce traffic, it had the opposite effect in several residential areas.', 'Dựa vào câu trên, từ “opposite” có nghĩa phù hợp nhất là gì?', '["thưa ông; thưa ngài; thầy (cách gọi lịch sự đối với nam giới hoặc thầy giáo)","khác hoàn toàn; ở phía đối diện","ngón chân","biến mất; khuất tầm mắt"]'::jsonb, 1, 'opposite: khác hoàn toàn; ở phía đối diện; ở phía đối diện của; trái ngược; điều ngược lại. Dịch cả câu: Mặc dù chính sách nhằm mục đích giảm thiểu lưu lượng giao thông, nhưng nó lại mang lại hiệu quả ngược lại ở một số khu dân cư.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_38_22', 'en-a2-38', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “phủ; che đậy”', '["adventure","shut","cover","speech"]'::jsonb, 2, 'phủ; che đậy → cover (/ˈkʌvər/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_38_23', 'en-a2-38', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khắp mọi nơi; đâu đâu cũng có”', '["coach","Swedish","motorway","everywhere"]'::jsonb, 3, 'khắp mọi nơi; đâu đâu cũng có → everywhere (/ˈevriwer/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_38_24', 'en-a2-38', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khăn choàng cổ; khăn đội đầu”', '["slipper","scarf","heater","clever"]'::jsonb, 1, 'khăn choàng cổ; khăn đội đầu → scarf (/skɑːrf/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-39', 'en', 'Bài 39: Đời sống hằng ngày (11) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '26 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2039, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_refrigerator', 'en-a2-39', 'refrigerator', '/rɪˈfrɪdʒəreɪtər/', 'A2', 'tủ lạnh; tủ cấp đông', 'n.', 'refrigerate (v.), refrigeration (n.), refrigerated (adj.)', 'Đồng nghĩa: fridge', 'Trong văn nói hàng ngày thường dùng từ fridge; còn freezer dùng riêng cho ngăn đá hoặc tủ đông.', 'Put the milk in the refrigerator before it spoils.', NULL, 'Cho sữa vào tủ lạnh trước khi nó bị hỏng.', '{"wordId":"refrigerator","ukIpa":"/rɪˈfrɪdʒəreɪtə/","usIpa":"/rɪˈfrɪdʒəreɪtər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"an appliance that keeps food and drinks cold","vi":"tủ lạnh; tủ cấp đông"}],"examples":[{"en":"Put the milk in the refrigerator before it spoils.","vi":"Cho sữa vào tủ lạnh trước khi nó bị hỏng.","audioKind":"ex"},{"en":"Replacing an old refrigerator with an efficient model can reduce household electricity consumption significantly.","vi":"Việc thay thế một chiếc tủ lạnh cũ bằng mẫu tiết kiệm điện có thể làm giảm đáng kể lượng điện tiêu thụ trong gia đình.","audioKind":"ex2"}],"collocations":[{"en":"open the refrigerator","vi":"mở tủ lạnh"},{"en":"store food in the refrigerator","vi":"bảo quản thực phẩm trong tủ lạnh"},{"en":"refrigerator door","vi":"cửa tủ lạnh"}],"wordFamily":["refrigerate (v.)","refrigeration (n.)","refrigerated (adj.)"],"synonyms":["fridge"],"antonyms":[],"tipVi":"Trong văn nói hàng ngày thường dùng từ fridge; còn freezer dùng riêng cho ngăn đá hoặc tủ đông.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ninth', 'en-a2-39', 'ninth', '/naɪnθ/', 'A2', 'thứ chín; một phần chín', 'num.', 'nine (num.), nineteen (num.), ninety (num.)', NULL, 'Khi chuyển từ nine thành ninth thì bỏ chữ e; trước số thứ tự thường có mạo từ the.', 'Our new apartment is on the ninth floor.', NULL, 'Căn hộ mới của chúng tôi ở tầng chín.', '{"wordId":"ninth","ukIpa":"/naɪnθ/","usIpa":"/naɪnθ/","cefr":"A2","topic":"daily","senses":[{"pos":"num.","en":"Coming after the eighth and before the tenth.","vi":"thứ chín"},{"pos":"n.","en":"One of nine equal parts of something.","vi":"một phần chín"}],"examples":[{"en":"Our new apartment is on the ninth floor.","vi":"Căn hộ mới của chúng tôi ở tầng chín.","audioKind":"ex"},{"en":"By the ninth year of the conservation programme, several endangered species had begun to recover.","vi":"Đến năm thứ chín của chương trình bảo tồn, một số loài có nguy cơ tuyệt chủng đã bắt đầu phục hồi.","audioKind":"ex2"}],"collocations":[{"en":"the ninth floor","vi":"tầng chín"},{"en":"the ninth century","vi":"thế kỷ thứ chín"},{"en":"in ninth place","vi":"đứng ở vị trí thứ chín"},{"en":"one ninth of","vi":"một phần chín của"}],"wordFamily":["nine (num.)","nineteen (num.)","ninety (num.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chuyển từ nine thành ninth thì bỏ chữ e; trước số thứ tự thường có mạo từ the.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_reply', 'en-a2-39', 'reply', '/rɪˈplaɪ/', 'A2', 'trả lời; hồi âm; câu trả lời; sự hồi âm', 'v.', NULL, 'Đồng nghĩa: answer, respond', 'Sau reply to phải có tân ngữ chỉ người hoặc sự việc, không được dùng trực tiếp mà thiếu giới từ to.', 'Please reply before Friday so I can book dinner.', NULL, 'Xin hãy phản hồi trước thứ Sáu để tôi có thể đặt bàn ăn tối.', '{"wordId":"reply","ukIpa":"/rɪˈplaɪ/","usIpa":"/rɪˈplaɪ/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to answer someone or respond to a message","vi":"trả lời; hồi âm"},{"pos":"n.","en":"an answer given in speech or writing","vi":"câu trả lời; sự hồi âm"}],"examples":[{"en":"Please reply before Friday so I can book dinner.","vi":"Xin hãy phản hồi trước thứ Sáu để tôi có thể đặt bàn ăn tối.","audioKind":"ex"},{"en":"Local officials should reply promptly to residents who raise concerns about public transport services.","vi":"Các quan chức địa phương nên phản hồi kịp thời những cư dân bày tỏ lo ngại về dịch vụ giao thông công cộng.","audioKind":"ex2"}],"collocations":[{"en":"reply to a message","vi":"trả lời tin nhắn"},{"en":"a prompt reply","vi":"câu trả lời kịp thời"},{"en":"in reply to","vi":"đáp lại..."}],"wordFamily":[],"synonyms":["answer","respond"],"antonyms":[],"tipVi":"Sau reply to phải có tân ngữ chỉ người hoặc sự việc, không được dùng trực tiếp mà thiếu giới từ to.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bean', 'en-a2-39', 'bean', '/biːn/', 'A2', 'hạt đậu; cây đậu', 'n.', NULL, NULL, 'Là danh từ đếm được; thường dùng beans khi nhắc đến các loại hạt đậu nói chung.', 'I added some beans to the vegetable soup.', NULL, 'Tôi đã cho thêm vài hạt đậu vào món súp rau củ.', '{"wordId":"bean","ukIpa":"/biːn/","usIpa":"/biːn/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"An edible seed, or the plant that produces it.","vi":"hạt đậu; cây đậu"}],"examples":[{"en":"I added some beans to the vegetable soup.","vi":"Tôi đã cho thêm vài hạt đậu vào món súp rau củ.","audioKind":"ex"},{"en":"Beans provide an affordable source of protein and can support a balanced plant-based diet.","vi":"Các loại đậu là nguồn cung cấp protein giá cả phải chăng và giúp duy trì chế độ ăn chay cân bằng.","audioKind":"ex2"}],"collocations":[{"en":"green beans","vi":"đậu cô ve; đậu đũa"},{"en":"kidney beans","vi":"đậu thận; đậu tây"},{"en":"coffee beans","vi":"hạt cà phê"},{"en":"baked beans","vi":"đậu sốt cà chua đóng hộp"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được; thường dùng beans khi nhắc đến các loại hạt đậu nói chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_fail', 'en-a2-39', 'fail', '/feɪl/', 'A2', 'thất bại; không làm được việc gì đó; trượt (kì thi); cho điểm trượt; hỏng hóc; suy yếu; ngưng hoạt động tốt', 'v.', 'failure (n.), failed (adj.), failing (adj.)', 'Trái nghĩa: succeed, pass', 'fail to do diễn tả việc không làm được việc gì; fail an exam diễn tả việc thi trượt.', 'The cake failed to rise despite an extra egg.', NULL, 'Chiếc bánh vẫn không nở phồng lên dù đã cho thêm một quả trứng.', '{"wordId":"fail","ukIpa":"/feɪl/","usIpa":"/feɪl/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to be unsuccessful or not do something required","vi":"thất bại; không làm được việc gì đó"},{"pos":"v.","en":"to not pass a test, or give an unsuccessful grade","vi":"trượt (kì thi); cho điểm trượt"},{"pos":"v.","en":"to stop working properly or become weaker","vi":"hỏng hóc; suy yếu; ngưng hoạt động tốt"}],"examples":[{"en":"The cake failed to rise despite an extra egg.","vi":"Chiếc bánh vẫn không nở phồng lên dù đã cho thêm một quả trứng.","audioKind":"ex"},{"en":"Recycling programmes often fail when local authorities do not provide clear guidance or convenient collection services.","vi":"Các chương trình tái chế thường thất bại khi chính quyền địa phương không cung cấp hướng dẫn rõ ràng hoặc dịch vụ thu gom thuận tiện.","audioKind":"ex2"}],"collocations":[{"en":"fail to do something","vi":"không làm điều gì đó"},{"en":"fail an exam","vi":"trượt một kỳ thi"},{"en":"fail to meet expectations","vi":"không đạt kỳ vọng"}],"wordFamily":["failure (n.)","failed (adj.)","failing (adj.)"],"synonyms":[],"antonyms":["succeed","pass"],"tipVi":"fail to do diễn tả việc không làm được việc gì; fail an exam diễn tả việc thi trượt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unlucky', 'en-a2-39', 'unlucky', '/ʌnˈlʌki/', 'A2', 'gặp vận đen; kém may mắn; xui xẻo; mang lại điềm gở', 'adj.', 'lucky (adj.), luck (n.), unluckily (adv.)', 'Đồng nghĩa: unfortunate · Trái nghĩa: lucky, fortunate', 'unlucky nhấn mạnh vào sự kém may mắn, không đồng nghĩa với unhappy (buồn bã).', 'We were unlucky to miss the bus by seconds.', NULL, 'Chúng tôi thật xui xẻo khi lỡ chuyến xe buýt chỉ trong tích tắc.', '{"wordId":"unlucky","ukIpa":"/ʌnˈlʌki/","usIpa":"/ʌnˈlʌki/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Experiencing bad things because of chance","vi":"gặp vận đen; kém may mắn"},{"pos":"adj.","en":"Believed to bring bad luck","vi":"xui xẻo; mang lại điềm gở"}],"examples":[{"en":"We were unlucky to miss the bus by seconds.","vi":"Chúng tôi thật xui xẻo khi lỡ chuyến xe buýt chỉ trong tích tắc.","audioKind":"ex"},{"en":"Students who are unlucky enough to fall ill during examinations should be offered alternative assessment arrangements.","vi":"Những học sinh không may bị ốm trong thời gian thi cử nên được tạo điều kiện sắp xếp hình thức đánh giá thay thế.","audioKind":"ex2"}],"collocations":[{"en":"unlucky in love","vi":"lận đận trong chuyện tình cảm"},{"en":"unlucky enough to","vi":"không may đến mức..."},{"en":"an unlucky day","vi":"một ngày xui xẻo"}],"wordFamily":["lucky (adj.)","luck (n.)","unluckily (adv.)"],"synonyms":["unfortunate"],"antonyms":["lucky","fortunate"],"tipVi":"unlucky nhấn mạnh vào sự kém may mắn, không đồng nghĩa với unhappy (buồn bã).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ahead', 'en-a2-39', 'ahead', '/əˈhed/', 'A2', 'ở phía trước; tiến về phía trước; vượt lên trước; sớm hơn dự kiến; trong tương lai; chuẩn bị trước', 'adv.', NULL, 'Trái nghĩa: behind', 'ahead là phó từ; khi muốn nói ở phía trước ai hoặc cái gì, dùng cụm ahead of.', 'Walk straight ahead until you reach the little bridge.', NULL, 'Cứ đi thẳng phía trước cho đến khi bạn đến cây cầu nhỏ.', '{"wordId":"ahead","ukIpa":"/əˈhed/","usIpa":"/əˈhed/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"In front of someone or something, or moving forward.","vi":"ở phía trước; tiến về phía trước"},{"pos":"adv.","en":"Further advanced than others or earlier than expected.","vi":"vượt lên trước; sớm hơn dự kiến"},{"pos":"adv.","en":"In the future, or in preparation for it.","vi":"trong tương lai; chuẩn bị trước"}],"examples":[{"en":"Walk straight ahead until you reach the little bridge.","vi":"Cứ đi thẳng phía trước cho đến khi bạn đến cây cầu nhỏ.","audioKind":"ex"},{"en":"Cities need to plan ahead to ensure that transport networks can meet the demands of growing populations.","vi":"Các thành phố cần phải lên kế hoạch trước để đảm bảo mạng lưới giao thông có thể đáp ứng nhu cầu của số lượng dân cư đang gia tăng.","audioKind":"ex2"}],"collocations":[{"en":"straight ahead","vi":"thẳng tiến về phía trước; chính diện"},{"en":"ahead of schedule","vi":"trước thời hạn dự kiến"},{"en":"plan ahead","vi":"lên kế hoạch trước"},{"en":"ahead of the competition","vi":"dẫn đầu đối thủ cạnh tranh"}],"wordFamily":[],"synonyms":[],"antonyms":["behind"],"tipVi":"ahead là phó từ; khi muốn nói ở phía trước ai hoặc cái gì, dùng cụm ahead of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_steak', 'en-a2-39', 'steak', '/steɪk/', 'A2', 'bít tết; thịt nướng cắt lát; cá phi-lê cắt lát dày', 'n.', NULL, NULL, 'steak và stake đồng âm; nói steak thường chỉ bít tết.', 'She served the steak with potatoes and green beans.', NULL, 'Cô ấy phục vụ món bít tết kèm khoai tây và đậu cô ve.', '{"wordId":"steak","ukIpa":"/steɪk/","usIpa":"/steɪk/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A thick slice of meat, especially beef, or fish.","vi":"bít tết; thịt nướng cắt lát; cá phi-lê cắt lát dày"}],"examples":[{"en":"She served the steak with potatoes and green beans.","vi":"Cô ấy phục vụ món bít tết kèm khoai tây và đậu cô ve.","audioKind":"ex"},{"en":"Replacing beef steak with plant proteins occasionally can reduce the environmental impact of a person''s diet.","vi":"Việc thỉnh thoảng thay thế bít tết bò bằng protein thực vật có thể làm giảm tác động môi trường từ chế độ ăn uống của một người.","audioKind":"ex2"}],"collocations":[{"en":"grilled steak","vi":"bít tết nướng"},{"en":"sirloin steak","vi":"bít tết thăn ngoại"},{"en":"tuna steak","vi":"bít tết cá ngừ"},{"en":"well-done steak","vi":"bít tết chín kỹ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"steak và stake đồng âm; nói steak thường chỉ bít tết.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tidy', 'en-a2-39', 'tidy', '/ˈtaɪdi/', 'A2', 'ngăn nắp; gọn gàng; dọn dẹp; thu dọn', 'adj.', 'tidiness (n.), tidily (adv.), untidy (adj.)', 'Đồng nghĩa: neat, orderly · Trái nghĩa: untidy, messy', 'tidy nhấn mạnh bày trí gọn gàng; clean nhấn mạnh không có vết bẩn.', 'Her desk stays tidy, even during the busiest weeks.', NULL, 'Bàn làm việc của cô ấy luôn ngăn nắp ngay cả trong những tuần bận rộn nhất.', '{"wordId":"tidy","ukIpa":"/ˈtaɪdi/","usIpa":"/ˈtaɪdi/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Neatly arranged, with everything in its proper place.","vi":"ngăn nắp; gọn gàng"},{"pos":"v.","en":"To put things in order and make a place neat.","vi":"dọn dẹp; thu dọn"}],"examples":[{"en":"Her desk stays tidy, even during the busiest weeks.","vi":"Bàn làm việc của cô ấy luôn ngăn nắp ngay cả trong những tuần bận rộn nhất.","audioKind":"ex"},{"en":"Keeping shared workplaces tidy can help employees find equipment quickly and create a more pleasant environment.","vi":"Giữ gìn nơi làm việc chung ngăn nắp có thể giúp nhân viên tìm kiếm thiết bị nhanh chóng và tạo ra môi trường dễ chịu hơn.","audioKind":"ex2"}],"collocations":[{"en":"keep tidy","vi":"giữ gìn ngăn nắp"},{"en":"tidy up","vi":"dọn dẹp sạch sẽ"},{"en":"neat and tidy","vi":"gọn gàng ngăn nắp"}],"wordFamily":["tidiness (n.)","tidily (adv.)","untidy (adj.)"],"synonyms":["neat","orderly"],"antonyms":["untidy","messy"],"tipVi":"tidy nhấn mạnh bày trí gọn gàng; clean nhấn mạnh không có vết bẩn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wool', 'en-a2-39', 'wool', '/wʊl/', 'A2', 'len; lông cừu', 'n.', 'woollen (adj.), woolly (adj.)', NULL, 'Thường không đếm được; một cuộn len nói a ball of wool.', 'This wool scarf keeps my neck warm on windy mornings.', NULL, 'Chiếc khăn len này giữ ấm cổ tôi vào những buổi sáng lộng gió.', '{"wordId":"wool","ukIpa":"/wʊl/","usIpa":"/wʊl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Sheep''s soft hair, or yarn and cloth made from it.","vi":"len; lông cừu"}],"examples":[{"en":"This wool scarf keeps my neck warm on windy mornings.","vi":"Chiếc khăn len này giữ ấm cổ tôi vào những buổi sáng lộng gió.","audioKind":"ex"},{"en":"Wool provides natural insulation, making it a useful material for clothing designed for cold climates.","vi":"Len có khả năng cách nhiệt tự nhiên, khiến nó trở thành chất liệu hữu ích cho trang phục thiết kế trong khí hậu lạnh.","audioKind":"ex2"}],"collocations":[{"en":"pure wool","vi":"len nguyên chất"},{"en":"a ball of wool","vi":"một cuộn len"},{"en":"wool blanket","vi":"chăn len"},{"en":"wool production","vi":"sản xuất len"}],"wordFamily":["woollen (adj.)","woolly (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường không đếm được; một cuộn len nói a ball of wool.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_purse', 'en-a2-39', 'purse', '/pɝːs/', 'A2', 'ví tiền nhỏ; túi xách tay nữ; ngân quỹ; tài chính; mím chặt môi; chúm môi', 'n.', NULL, NULL, 'purse tiếng Anh-Anh thường chỉ ví tiền nhỏ, tiếng Anh-Mỹ thường chỉ túi xách tay nữ.', 'She opened her purse and took out a coin.', NULL, 'Cô ấy mở ví tiền và lấy ra một đồng xu.', '{"wordId":"purse","ukIpa":"/pɜːs/","usIpa":"/pɝːs/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a small money holder; in American English, a handbag","vi":"ví tiền nhỏ; túi xách tay nữ"},{"pos":"n.","en":"money available to a person, organisation, or government","vi":"ngân quỹ; tài chính"},{"pos":"v.","en":"to press your lips together into a small rounded shape","vi":"mím chặt môi; chúm môi"}],"examples":[{"en":"She opened her purse and took out a coin.","vi":"Cô ấy mở ví tiền và lấy ra một đồng xu.","audioKind":"ex"},{"en":"Investment in preventive healthcare could reduce the long-term burden on the public purse.","vi":"Đầu tư vào chăm sóc sức khỏe dự phòng có thể làm giảm gánh nặng dài hạn cho ngân quỹ công.","audioKind":"ex2"}],"collocations":[{"en":"a leather purse","vi":"ví da nhỏ"},{"en":"the public purse","vi":"ngân quỹ nhà nước"},{"en":"purse your lips","vi":"mím môi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"purse tiếng Anh-Anh thường chỉ ví tiền nhỏ, tiếng Anh-Mỹ thường chỉ túi xách tay nữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_notice', 'en-a2-39', 'notice', '/ˈnoʊ.t̬ɪs/', 'A2', 'nhận thấy; chú ý; thông báo; bảng thông báo; sự thông báo trước', 'v.', 'noticeable (adj.), noticeably (adv.), unnoticed (adj.)', NULL, 'notice sb do nhấn mạnh toàn bộ quá trình; notice sb doing nhấn mạnh sự việc đang diễn ra.', 'Did you notice the tiny bird outside our window?', NULL, 'Bạn có chú ý thấy con chim nhỏ ở ngoài cửa sổ nhà chúng ta không?', '{"wordId":"notice","ukIpa":"/ˈnəʊ.tɪs/","usIpa":"/ˈnoʊ.t̬ɪs/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to become aware of something through your senses","vi":"nhận thấy; chú ý"},{"pos":"n.","en":"a written statement giving information or instructions","vi":"thông báo; bảng thông báo"},{"pos":"n.","en":"information given before something happens or ends","vi":"sự thông báo trước"}],"examples":[{"en":"Did you notice the tiny bird outside our window?","vi":"Bạn có chú ý thấy con chim nhỏ ở ngoài cửa sổ nhà chúng ta không?","audioKind":"ex"},{"en":"Residents often notice improvements in air quality when cities restrict traffic in central areas.","vi":"Cư dân thường nhận thấy chất lượng không khí được cải thiện khi các thành phố hạn chế phương tiện giao thông ở các khu vực trung tâm.","audioKind":"ex2"}],"collocations":[{"en":"notice a difference","vi":"nhận ra sự khác biệt"},{"en":"take notice of","vi":"lưu ý đến"},{"en":"give notice","vi":"báo trước; đưa ra thông báo"},{"en":"at short notice","vi":"trong thời gian ngắn; báo trước gấp"}],"wordFamily":["noticeable (adj.)","noticeably (adv.)","unnoticed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"notice sb do nhấn mạnh toàn bộ quá trình; notice sb doing nhấn mạnh sự việc đang diễn ra.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cloth', 'en-a2-39', 'cloth', '/klɔːθ/', 'A2', 'vải; chất liệu vải; giẻ lau; tấm vải', 'n.', NULL, 'Đồng nghĩa: fabric, material', 'Nghĩa vải vóc là danh từ không đếm được; nghĩa giẻ lau đếm được, số nhiều là cloths; tránh nhầm lẫn với clothes.', 'She chose soft cotton cloth for the baby''s blanket.', NULL, 'Cô ấy đã chọn vải cotton mềm mại để làm chăn cho em bé.', '{"wordId":"cloth","ukIpa":"/klɒθ/","usIpa":"/klɔːθ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Material made by weaving or knitting fibres.","vi":"vải; chất liệu vải"},{"pos":"n.","en":"A piece of fabric used for cleaning or covering things.","vi":"giẻ lau; tấm vải"}],"examples":[{"en":"She chose soft cotton cloth for the baby''s blanket.","vi":"Cô ấy đã chọn vải cotton mềm mại để làm chăn cho em bé.","audioKind":"ex"},{"en":"Replacing disposable wipes with reusable cloth can reduce household waste and lower long-term cleaning costs.","vi":"Việc thay thế khăn giấy dùng một lần bằng giẻ lau có thể tái sử dụng có thể giúp giảm rác thải sinh hoạt và hạ thấp chi phí vệ sinh lâu dài.","audioKind":"ex2"}],"collocations":[{"en":"cotton cloth","vi":"vải cotton"},{"en":"a damp cloth","vi":"giẻ lau ẩm"},{"en":"a piece of cloth","vi":"một mảnh vải"}],"wordFamily":[],"synonyms":["fabric","material"],"antonyms":[],"tipVi":"Nghĩa vải vóc là danh từ không đếm được; nghĩa giẻ lau đếm được, số nhiều là cloths; tránh nhầm lẫn với clothes.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_drop', 'en-a2-39', 'drop', '/drɑːp/', 'A2', 'rơi; làm rơi; giảm xuống; giọt (chất lỏng); bỏ; từ bỏ', 'v.', NULL, NULL, 'drop by diễn tả mức độ giảm đi bao nhiêu; drop to diễn tả giảm xuống đến mức nào.', 'I dropped my keys while reaching for my phone.', NULL, 'Tôi đã làm rơi chìa khóa khi với lấy điện thoại.', '{"wordId":"drop","ukIpa":"/drɒp/","usIpa":"/drɑːp/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to fall, let something fall, or become lower","vi":"rơi; làm rơi; giảm xuống"},{"pos":"n.","en":"a very small, rounded amount of liquid","vi":"giọt (chất lỏng)"},{"pos":"v.","en":"to stop doing or considering something","vi":"bỏ; từ bỏ"}],"examples":[{"en":"I dropped my keys while reaching for my phone.","vi":"Tôi đã làm rơi chìa khóa khi với lấy điện thoại.","audioKind":"ex"},{"en":"If public transport becomes more reliable, the number of people driving to work may drop significantly.","vi":"Nếu giao thông công cộng trở nên đáng tin cậy hơn, số lượng người lái xe đi làm có thể giảm đáng kể.","audioKind":"ex2"}],"collocations":[{"en":"a drop in prices","vi":"sự giảm giá"},{"en":"a drop of water","vi":"một giọt nước"},{"en":"drop a course","vi":"bỏ một môn học"},{"en":"drop sharply","vi":"giảm mạnh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"drop by diễn tả mức độ giảm đi bao nhiêu; drop to diễn tả giảm xuống đến mức nào.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_envelope', 'en-a2-39', 'envelope', '/ˈenvəloʊp/', 'A2', 'cái phong bì; phong thư', 'n.', NULL, NULL, 'envelope là danh từ "phong bì"; envelop là động từ "bao bọc".', 'She slipped the birthday card into a blue envelope.', NULL, 'Cô ấy đã lọt tấm thiệp sinh nhật vào một chiếc phong bì màu xanh.', '{"wordId":"envelope","ukIpa":"/ˈenvələʊp/","usIpa":"/ˈenvəloʊp/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A flat paper container used for sending a letter.","vi":"cái phong bì; phong thư"}],"examples":[{"en":"She slipped the birthday card into a blue envelope.","vi":"Cô ấy đã lọt tấm thiệp sinh nhật vào một chiếc phong bì màu xanh.","audioKind":"ex"},{"en":"Although digital communication is widespread, official documents are still sometimes delivered in a sealed envelope for privacy.","vi":"Mặc dù truyền thông kỹ thuật số rất phổ biến, các tài liệu chính thức đôi khi vẫn được gửi trong một phong bì niêm phong để đảm bảo tính riêng tư.","audioKind":"ex2"}],"collocations":[{"en":"a sealed envelope","vi":"phong bì được niêm phong"},{"en":"open an envelope","vi":"mở phong bì"},{"en":"a padded envelope","vi":"phong bì có lớp đệm lót"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"envelope là danh từ \"phong bì\"; envelop là động từ \"bao bọc\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stage', 'en-a2-39', 'stage', '/steɪdʒ/', 'A2', 'giai đoạn; thời kỳ; sân khấu; tổ chức; dàn dựng; trình diễn', 'n.', 'staging (n.), staged (adj.)', NULL, 'Chỉ giai đoạn thường dùng at a stage; chỉ trên sân khấu dùng on stage.', 'The cake is cooling at this stage of preparation.', NULL, 'Bánh đang được để nguội ở giai đoạn chuẩn bị này.', '{"wordId":"stage","ukIpa":"/steɪdʒ/","usIpa":"/steɪdʒ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A particular period or step in a process.","vi":"giai đoạn; thời kỳ"},{"pos":"n.","en":"A raised area where performers appear before an audience.","vi":"sân khấu"},{"pos":"v.","en":"To organise and present a performance or public event.","vi":"tổ chức; dàn dựng; trình diễn"}],"examples":[{"en":"The cake is cooling at this stage of preparation.","vi":"Bánh đang được để nguội ở giai đoạn chuẩn bị này.","audioKind":"ex"},{"en":"Early intervention at a critical stage of childhood can significantly improve educational outcomes later in life.","vi":"Sự can thiệp sớm vào một giai đoạn quan trọng của thời thơ ấu có thể cải thiện đáng kể kết quả giáo dục về sau trong cuộc đời.","audioKind":"ex2"}],"collocations":[{"en":"at an early stage","vi":"ở giai đoạn đầu"},{"en":"a stage of development","vi":"một giai đoạn phát triển"},{"en":"on stage","vi":"trên sân khấu"},{"en":"stage a play","vi":"dàn dựng một vở kịch"}],"wordFamily":["staging (n.)","staged (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Chỉ giai đoạn thường dùng at a stage; chỉ trên sân khấu dùng on stage.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forward', 'en-a2-39', 'forward', '/ˈfɔːrwɚd/', 'A2', 'về phía trước; hướng về tương lai; chuyển tiếp; chuyển gửi; tiền đạo', 'adv.', 'forwards (adv.)', 'Đồng nghĩa: ahead · Trái nghĩa: backward', 'Từ to trong look forward to là giới từ, theo sau là danh từ hoặc danh động từ.', 'Please step forward when there is space ahead.', NULL, 'Xin hãy bước lên phía trước khi phía trước có chỗ trống.', '{"wordId":"forward","ukIpa":"/ˈfɔːwəd/","usIpa":"/ˈfɔːrwɚd/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"towards the front or a later time","vi":"về phía trước; hướng về tương lai"},{"pos":"v.","en":"to send something received to another person or place","vi":"chuyển tiếp; chuyển gửi"},{"pos":"n.","en":"an attacking player in sports such as football","vi":"tiền đạo"}],"examples":[{"en":"Please step forward when there is space ahead.","vi":"Xin hãy bước lên phía trước khi phía trước có chỗ trống.","audioKind":"ex"},{"en":"Investment in renewable energy can help countries move forward towards a more sustainable economic future.","vi":"Đầu tư vào năng lượng tái tạo có thể giúp các quốc gia tiến về phía trước hướng tới một tương lai kinh tế bền vững hơn.","audioKind":"ex2"}],"collocations":[{"en":"move forward","vi":"di chuyển về phía trước; tiến lên"},{"en":"look forward to","vi":"trông đợi; mong chờ"},{"en":"forward an email","vi":"chuyển tiếp email"},{"en":"put forward a proposal","vi":"đưa ra một đề xuất"}],"wordFamily":["forwards (adv.)"],"synonyms":["ahead"],"antonyms":["backward"],"tipVi":"Từ to trong look forward to là giới từ, theo sau là danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mess', 'en-a2-39', 'mess', '/mes/', 'A2', 'sự bừa bộn; cảnh lộn xộn; tình trạng rối rắm; tình thế khó khăn; làm bừa bộn; làm hỏng việc', 'n.', 'messy (adj.), messily (adv.)', 'Đồng nghĩa: disorder · Trái nghĩa: order', 'Thường dùng cấu trúc make a mess; mess up có thể chỉ việc làm rối tung hoặc phá hỏng.', 'The kitchen was a mess after we baked biscuits.', NULL, 'Phòng bếp trở nên bừa bộn sau khi chúng tôi nướng bánh quy.', '{"wordId":"mess","ukIpa":"/mes/","usIpa":"/mes/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A dirty or untidy state or collection of things.","vi":"sự bừa bộn; cảnh lộn xộn"},{"pos":"n.","en":"A situation full of problems or confusion.","vi":"tình trạng rối rắm; tình thế khó khăn"},{"pos":"v.","en":"To make something untidy or spoil it, usually with up.","vi":"làm bừa bộn; làm hỏng việc"}],"examples":[{"en":"The kitchen was a mess after we baked biscuits.","vi":"Phòng bếp trở nên bừa bộn sau khi chúng tôi nướng bánh quy.","audioKind":"ex"},{"en":"Without clear responsibilities, a community project can quickly become a mess, wasting both time and resources.","vi":"Nếu thiếu trách nhiệm rõ ràng, một dự án cộng đồng có thể nhanh chóng rơi vào cảnh hỗn loạn, lãng phí cả thời gian lẫn tài nguyên.","audioKind":"ex2"}],"collocations":[{"en":"make a mess","vi":"làm bừa bộn; gây ra sự hỗn độn"},{"en":"in a mess","vi":"trong tình trạng lộn xộn"},{"en":"mess up","vi":"làm hỏng; gây rối"}],"wordFamily":["messy (adj.)","messily (adv.)"],"synonyms":["disorder"],"antonyms":["order"],"tipVi":"Thường dùng cấu trúc make a mess; mess up có thể chỉ việc làm rối tung hoặc phá hỏng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_level', 'en-a2-39', 'level', '/ˈlevəl/', 'A2', 'mức độ; trình độ; cấp độ; bằng phẳng; ngang bằng; làm phẳng; san bằng', 'n.', 'levelly (adv.), levelling (n.)', NULL, 'Dùng at để chỉ mức độ đạt được; on the same level có thể chỉ cùng một tầng nhà.', 'The water level rose after last night''s heavy rain.', NULL, 'Mực nước đã dâng lên sau trận mưa lớn đêm qua.', '{"wordId":"level","ukIpa":"/ˈlevəl/","usIpa":"/ˈlevəl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A particular standard, amount, or height of something.","vi":"mức độ; trình độ; cấp độ"},{"pos":"adj.","en":"Flat and even, or at the same height.","vi":"bằng phẳng; ngang bằng"},{"pos":"v.","en":"To make a surface flat or things equal.","vi":"làm phẳng; san bằng"}],"examples":[{"en":"The water level rose after last night''s heavy rain.","vi":"Mực nước đã dâng lên sau trận mưa lớn đêm qua.","audioKind":"ex"},{"en":"Improving the level of public transport can encourage more residents to leave their cars at home.","vi":"Nâng cao chất lượng dịch vụ giao thông công cộng có thể khuyến khích nhiều cư dân để xe ở nhà hơn.","audioKind":"ex2"}],"collocations":[{"en":"sea level","vi":"mực nước biển"},{"en":"a high level of","vi":"mức độ cao của"},{"en":"level ground","vi":"mặt đất bằng phẳng"},{"en":"level the playing field","vi":"tạo ra môi trường cạnh tranh công bằng"}],"wordFamily":["levelly (adv.)","levelling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng at để chỉ mức độ đạt được; on the same level có thể chỉ cùng một tầng nhà.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_afterwards', 'en-a2-39', 'afterwards', '/ˈæftərwərdz/', 'A2', 'sau đó; về sau', 'adv.', NULL, 'Đồng nghĩa: later, afterward · Trái nghĩa: beforehand', 'Là trạng từ nên không trực tiếp đi kèm tân ngữ ở phía sau; từ after có thể đi với tân ngữ.', 'We watched a film and had dinner afterwards.', NULL, 'Chúng tôi xem một bộ phim và ăn tối sau đó.', '{"wordId":"afterwards","ukIpa":"/ˈɑːftəwədz/","usIpa":"/ˈæftərwərdz/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"At a later time, following an event.","vi":"sau đó; về sau"}],"examples":[{"en":"We watched a film and had dinner afterwards.","vi":"Chúng tôi xem một bộ phim và ăn tối sau đó.","audioKind":"ex"},{"en":"Students who discuss a lecture afterwards may remember its key ideas more clearly than those who do not.","vi":"Những học sinh thảo luận về bài giảng ngay sau đó có thể ghi nhớ các ý chính rõ ràng hơn những em không làm vậy.","audioKind":"ex2"}],"collocations":[{"en":"shortly afterwards","vi":"ngay sau đó"},{"en":"soon afterwards","vi":"không lâu sau đó"},{"en":"immediately afterwards","vi":"tiếp ngay sau đó"}],"wordFamily":[],"synonyms":["later","afterward"],"antonyms":["beforehand"],"tipVi":"Là trạng từ nên không trực tiếp đi kèm tân ngữ ở phía sau; từ after có thể đi với tân ngữ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_empty', 'en-a2-39', 'empty', '/ˈempti/', 'A2', 'trống rỗng; không có người; làm rỗng; đổ sạch; sáo rỗng; vô nghĩa; không thành thật', 'adj.', 'emptiness (n.)', 'Đồng nghĩa: vacant, unoccupied · Trái nghĩa: full', 'empty nhấn mạnh việc không có gì bên trong; vacant thường dùng để chỉ nhà cửa hoặc vị trí công việc còn trống.', 'The biscuit tin was empty when I opened it.', NULL, 'Hộp đựng bánh quy đã trống không khi tôi mở nó ra.', '{"wordId":"empty","ukIpa":"/ˈempti/","usIpa":"/ˈempti/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Containing nothing or having no people inside.","vi":"trống rỗng; không có người"},{"pos":"v.","en":"To remove everything from a container or place.","vi":"làm rỗng; đổ sạch"},{"pos":"adj.","en":"Lacking real meaning, value, or sincere intention.","vi":"sáo rỗng; vô nghĩa; không thành thật"}],"examples":[{"en":"The biscuit tin was empty when I opened it.","vi":"Hộp đựng bánh quy đã trống không khi tôi mở nó ra.","audioKind":"ex"},{"en":"Converting empty office buildings into affordable housing could help cities address shortages without expanding into surrounding countryside.","vi":"Việc chuyển đổi các tòa nhà văn phòng bỏ trống thành nhà ở giá rẻ có thể giúp các thành phố giải quyết tình trạng thiếu hụt nhà ở mà không cần mở rộng sang vùng nông thôn xung quanh.","audioKind":"ex2"}],"collocations":[{"en":"empty room","vi":"phòng trống"},{"en":"empty promises","vi":"lời hứa suông"},{"en":"empty the bin","vi":"đổ rác; làm rỗng thùng rác"},{"en":"on an empty stomach","vi":"khi bụng đói"}],"wordFamily":["emptiness (n.)"],"synonyms":["vacant","unoccupied"],"antonyms":["full"],"tipVi":"empty nhấn mạnh việc không có gì bên trong; vacant thường dùng để chỉ nhà cửa hoặc vị trí công việc còn trống.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_twelfth', 'en-a2-39', 'twelfth', '/twelfθ/', 'A2', 'thứ mười hai; một phần mười hai', 'num.', 'twelve (num)', NULL, 'twelve biến thành số thứ tự là twelfth, chú ý ve đổi thành f.', 'We celebrated her twelfth birthday with a homemade cake.', NULL, 'Chúng tôi tổ chức sinh nhật lần thứ mười hai cho con bé bằng một chiếc bánh tự làm.', '{"wordId":"twelfth","ukIpa":"/twelfθ/","usIpa":"/twelfθ/","cefr":"A2","topic":"daily","senses":[{"pos":"num.","en":"Coming after the eleventh in a sequence.","vi":"thứ mười hai"},{"pos":"n.","en":"One of twelve equal parts of something.","vi":"một phần mười hai"}],"examples":[{"en":"We celebrated her twelfth birthday with a homemade cake.","vi":"Chúng tôi tổ chức sinh nhật lần thứ mười hai cho con bé bằng một chiếc bánh tự làm.","audioKind":"ex"},{"en":"By the twelfth month of the programme, most participants had developed more effective study habits.","vi":"Đến tháng thứ mười hai của chương trình, phần lớn người tham gia đã xây dựng được thói quen học tập hiệu quả hơn.","audioKind":"ex2"}],"collocations":[{"en":"twelfth birthday","vi":"sinh nhật lần thứ mười hai"},{"en":"the twelfth century","vi":"thế kỷ thứ mười hai"},{"en":"one twelfth of","vi":"một phần mười hai của"}],"wordFamily":["twelve (num)"],"synonyms":[],"antonyms":[],"tipVi":"twelve biến thành số thứ tự là twelfth, chú ý ve đổi thành f.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_belt', 'en-a2-39', 'belt', '/belt/', 'A2', 'thắt lưng; dây nịt; vùng; dải đất; băng chuyền; băng tải', 'n.', 'belted (adj.)', NULL, 'belt ngoài thắt lưng còn chỉ vùng dạng dải, như green belt.', 'This belt keeps my trousers from slipping down.', NULL, 'Chiếc thắt lưng này giúp quần của tôi không bị tuột xuống.', '{"wordId":"belt","ukIpa":"/belt/","usIpa":"/belt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a strip worn around the waist to hold clothes","vi":"thắt lưng; dây nịt"},{"pos":"n.","en":"a long area with a particular feature","vi":"vùng; dải đất"},{"pos":"n.","en":"a continuous strip that moves machinery or carries objects","vi":"băng chuyền; băng tải"}],"examples":[{"en":"This belt keeps my trousers from slipping down.","vi":"Chiếc thắt lưng này giúp quần của tôi không bị tuột xuống.","audioKind":"ex"},{"en":"A green belt around a city can limit urban expansion and protect nearby farmland from development.","vi":"Vành đai xanh quanh một thành phố có thể hạn chế sự mở rộng đô thị và bảo vệ đất nông nghiệp lân cận khỏi bị phát triển xây dựng.","audioKind":"ex2"}],"collocations":[{"en":"leather belt","vi":"thắt lưng da"},{"en":"fasten a belt","vi":"thắt dây an toàn"},{"en":"green belt","vi":"vành đai xanh"},{"en":"conveyor belt","vi":"băng tải"}],"wordFamily":["belted (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"belt ngoài thắt lưng còn chỉ vùng dạng dải, như green belt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_whole', 'en-a2-39', 'whole', '/hoʊl/', 'A2', 'toàn bộ; trọn vẹn; không thiếu phần nào; thể thống nhất; toàn thể', 'adj.', 'wholly (adv.), wholeness (n.)', 'Đồng nghĩa: entire, complete · Trái nghĩa: partial, incomplete', 'Chú ý trật tự từ: the whole day tương đương với all the day.', 'We spent the whole afternoon baking bread together.', NULL, 'Chúng tôi dành toàn bộ buổi chiều để cùng nhau nướng bánh mì.', '{"wordId":"whole","ukIpa":"/həʊl/","usIpa":"/hoʊl/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Complete, with no part missing or left out.","vi":"toàn bộ; trọn vẹn; không thiếu phần nào"},{"pos":"n.","en":"A complete thing made up of connected parts.","vi":"thể thống nhất; toàn thể"}],"examples":[{"en":"We spent the whole afternoon baking bread together.","vi":"Chúng tôi dành toàn bộ buổi chiều để cùng nhau nướng bánh mì.","audioKind":"ex"},{"en":"Transport policies should consider the needs of the whole community rather than focusing only on car owners.","vi":"Các chính sách giao thông nên cân nhắc nhu cầu của toàn bộ cộng đồng thay vì chỉ tập trung vào những người sở hữu ô tô.","audioKind":"ex2"}],"collocations":[{"en":"the whole day","vi":"cả ngày; suốt cả ngày"},{"en":"as a whole","vi":"nói chung; nhìn chung"},{"en":"on the whole","vi":"nhìn chung; toàn cục"},{"en":"a whole range of","vi":"đủ loại; hàng loạt"}],"wordFamily":["wholly (adv.)","wholeness (n.)"],"synonyms":["entire","complete"],"antonyms":["partial","incomplete"],"tipVi":"Chú ý trật tự từ: the whole day tương đương với all the day.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_loudly', 'en-a2-39', 'loudly', '/ˈlaʊdli/', 'A2', 'to; lớn tiếng; ồn ào', 'adv.', 'loud (adj.), loudness (n.)', 'Đồng nghĩa: noisily · Trái nghĩa: quietly, softly', 'loudly nhấn mạnh âm lượng lớn; aloud nhấn mạnh việc phát ra tiếng thay vì đọc thầm.', 'Everyone cheered loudly when our team won the match.', NULL, 'Mọi người đều đồng thanh hò reo lớn khi đội chúng ta giành chiến thắng trong trận đấu.', '{"wordId":"loudly","ukIpa":"/ˈlaʊdli/","usIpa":"/ˈlaʊdli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"With a sound that has high volume.","vi":"to; lớn tiếng; ồn ào"}],"examples":[{"en":"Everyone cheered loudly when our team won the match.","vi":"Mọi người đều đồng thanh hò reo lớn khi đội chúng ta giành chiến thắng trong trận đấu.","audioKind":"ex"},{"en":"Passengers who speak loudly on public transport can disturb others, particularly during early morning or late evening journeys.","vi":"Những hành khách nói chuyện lớn tiếng trên phương tiện giao thông công cộng có thể làm phiền người khác, đặc biệt là trong những chuyến đi sáng sớm hoặc tối muộn.","audioKind":"ex2"}],"collocations":[{"en":"speak loudly","vi":"nói lớn tiếng; nói to"},{"en":"laugh loudly","vi":"cười lớn; cười vang"},{"en":"cheer loudly","vi":"hò reo lớn; cổ vũ lớn"}],"wordFamily":["loud (adj.)","loudness (n.)"],"synonyms":["noisily"],"antonyms":["quietly","softly"],"tipVi":"loudly nhấn mạnh âm lượng lớn; aloud nhấn mạnh việc phát ra tiếng thay vì đọc thầm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_main', 'en-a2-39', 'main', '/meɪn/', 'A2', 'chính; chủ yếu; đường ống chính; đường dây chính', 'adj.', 'mainly (adv.)', 'Đồng nghĩa: principal, chief, primary · Trái nghĩa: secondary, minor', 'Tính từ thường đứng trước danh từ; trạng từ là mainly.', 'The main entrance is beside the little coffee shop.', NULL, 'Lối đi chính nằm ngay bên cạnh quán cà phê nhỏ.', '{"wordId":"main","ukIpa":"/meɪn/","usIpa":"/meɪn/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Most important or largest among others.","vi":"chính; chủ yếu"},{"pos":"n.","en":"A large pipe or cable supplying water, gas, or electricity.","vi":"đường ống chính; đường dây chính"}],"examples":[{"en":"The main entrance is beside the little coffee shop.","vi":"Lối đi chính nằm ngay bên cạnh quán cà phê nhỏ.","audioKind":"ex"},{"en":"One main reason for urban migration is the wider range of employment opportunities available in cities.","vi":"Một lý do chính khiến người dân di cư ra thành phố là vì có nhiều cơ hội việc làm hơn ở các đô thị.","audioKind":"ex2"}],"collocations":[{"en":"main reason","vi":"lý do chính"},{"en":"main entrance","vi":"lối vào chính"},{"en":"main concern","vi":"mối quan tâm chính"},{"en":"water main","vi":"đường ống cấp nước chính"}],"wordFamily":["mainly (adv.)"],"synonyms":["principal","chief","primary"],"antonyms":["secondary","minor"],"tipVi":"Tính từ thường đứng trước danh từ; trạng từ là mainly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_39_1', 'en-a2-39', 'Cách dùng “cloth” (n.) — vải; chất liệu vải', 'cotton cloth  ·  a damp cloth  ·  a piece of cloth', 'Nghĩa vải vóc là danh từ không đếm được; nghĩa giẻ lau đếm được, số nhiều là cloths; tránh nhầm lẫn với clothes.', 'Đồng nghĩa: fabric, material', '[{"hanzi":"She chose soft cotton cloth for the baby''s blanket.","pinyin":"","meaning":"Cô ấy đã chọn vải cotton mềm mại để làm chăn cho em bé."},{"hanzi":"Replacing disposable wipes with reusable cloth can reduce household waste and lower long-term cleaning costs.","pinyin":"","meaning":"Việc thay thế khăn giấy dùng một lần bằng giẻ lau có thể tái sử dụng có thể giúp giảm rác thải sinh hoạt và hạ thấp chi phí vệ sinh lâu dài."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_39_2', 'en-a2-39', 'Cách dùng “empty” (adj.) — trống rỗng; không có người', 'empty room  ·  empty promises  ·  empty the bin', 'empty nhấn mạnh việc không có gì bên trong; vacant thường dùng để chỉ nhà cửa hoặc vị trí công việc còn trống.', 'Họ từ (Word Family): emptiness (n.) | Đồng nghĩa: vacant, unoccupied · Trái nghĩa: full', '[{"hanzi":"The biscuit tin was empty when I opened it.","pinyin":"","meaning":"Hộp đựng bánh quy đã trống không khi tôi mở nó ra."},{"hanzi":"Converting empty office buildings into affordable housing could help cities address shortages without expanding into surrounding countryside.","pinyin":"","meaning":"Việc chuyển đổi các tòa nhà văn phòng bỏ trống thành nhà ở giá rẻ có thể giúp các thành phố giải quyết tình trạng thiếu hụt nhà ở mà không cần mở rộng sang vùng nông thôn xung quanh."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_39_3', 'en-a2-39', 'Cách dùng “reply” (v.) — trả lời; hồi âm', 'reply to a message  ·  a prompt reply  ·  in reply to', 'Sau reply to phải có tân ngữ chỉ người hoặc sự việc, không được dùng trực tiếp mà thiếu giới từ to.', 'Đồng nghĩa: answer, respond', '[{"hanzi":"Please reply before Friday so I can book dinner.","pinyin":"","meaning":"Xin hãy phản hồi trước thứ Sáu để tôi có thể đặt bàn ăn tối."},{"hanzi":"Local officials should reply promptly to residents who raise concerns about public transport services.","pinyin":"","meaning":"Các quan chức địa phương nên phản hồi kịp thời những cư dân bày tỏ lo ngại về dịch vụ giao thông công cộng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_39_4', 'en-a2-39', 'Cách dùng “refrigerator” (n.) — tủ lạnh; tủ cấp đông', 'open the refrigerator  ·  store food in the refrigerator  ·  refrigerator door', 'Trong văn nói hàng ngày thường dùng từ fridge; còn freezer dùng riêng cho ngăn đá hoặc tủ đông.', 'Họ từ (Word Family): refrigerate (v.), refrigeration (n.), refrigerated (adj.) | Đồng nghĩa: fridge', '[{"hanzi":"Put the milk in the refrigerator before it spoils.","pinyin":"","meaning":"Cho sữa vào tủ lạnh trước khi nó bị hỏng."},{"hanzi":"Replacing an old refrigerator with an efficient model can reduce household electricity consumption significantly.","pinyin":"","meaning":"Việc thay thế một chiếc tủ lạnh cũ bằng mẫu tiết kiệm điện có thể làm giảm đáng kể lượng điện tiêu thụ trong gia đình."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_39_1', 'en-a2-39', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
