INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_39_1_3', 'ten_a2_39_1', 'reply', 'Please reply before Friday so I can book dinner.', 'Please reply before Friday so I can book dinner.', '/rɪˈplaɪ/', 'Xin hãy phản hồi trước thứ Sáu để tôi có thể đặt bàn ăn tối.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_39_1_4', 'ten_a2_39_1', 'bean', 'I added some beans to the vegetable soup.', 'I added some beans to the vegetable soup.', '/biːn/', 'Tôi đã cho thêm vài hạt đậu vào món súp rau củ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_39_1_5', 'ten_a2_39_1', 'fail', 'The cake failed to rise despite an extra egg.', 'The cake failed to rise despite an extra egg.', '/feɪl/', 'Chiếc bánh vẫn không nở phồng lên dù đã cho thêm một quả trứng.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_39_1_6', 'ten_a2_39_1', 'unlucky', 'We were unlucky to miss the bus by seconds.', 'We were unlucky to miss the bus by seconds.', '/ʌnˈlʌki/', 'Chúng tôi thật xui xẻo khi lỡ chuyến xe buýt chỉ trong tích tắc.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_39_1_7', 'ten_a2_39_1', 'ahead', 'Walk straight ahead until you reach the little bridge.', 'Walk straight ahead until you reach the little bridge.', '/əˈhed/', 'Cứ đi thẳng phía trước cho đến khi bạn đến cây cầu nhỏ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_39_1_8', 'ten_a2_39_1', 'steak', 'She served the steak with potatoes and green beans.', 'She served the steak with potatoes and green beans.', '/steɪk/', 'Cô ấy phục vụ món bít tết kèm khoai tây và đậu cô ve.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_39_1_1', 'en-a2-39', 'ten_a2_39_1', 'listening', 'listening', 'Put the milk in the refrigerator before it spoils.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cho sữa vào tủ lạnh trước khi nó bị hỏng.","Mọi người đều đồng thanh hò reo lớn khi đội chúng ta giành chiến thắng trong trận đấu.","Cứ đi thẳng phía trước cho đến khi bạn đến cây cầu nhỏ.","Phòng bếp trở nên bừa bộn sau khi chúng tôi nướng bánh quy."]'::jsonb, 0, 'Put the milk in the refrigerator before it spoils. → Cho sữa vào tủ lạnh trước khi nó bị hỏng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_39_1_2', 'en-a2-39', 'ten_a2_39_1', 'listening', 'listening', 'Our new apartment is on the ninth floor.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc thắt lưng này giúp quần của tôi không bị tuột xuống.","Cứ đi thẳng phía trước cho đến khi bạn đến cây cầu nhỏ.","Căn hộ mới của chúng tôi ở tầng chín.","Bạn có chú ý thấy con chim nhỏ ở ngoài cửa sổ nhà chúng ta không?"]'::jsonb, 2, 'Our new apartment is on the ninth floor. → Căn hộ mới của chúng tôi ở tầng chín.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_39_1_3', 'en-a2-39', 'ten_a2_39_1', 'listening', 'listening', 'Please reply before Friday so I can book dinner.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Xin hãy phản hồi trước thứ Sáu để tôi có thể đặt bàn ăn tối.","Căn hộ mới của chúng tôi ở tầng chín.","Cô ấy phục vụ món bít tết kèm khoai tây và đậu cô ve.","Cứ đi thẳng phía trước cho đến khi bạn đến cây cầu nhỏ."]'::jsonb, 0, 'Please reply before Friday so I can book dinner. → Xin hãy phản hồi trước thứ Sáu để tôi có thể đặt bàn ăn tối.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_39_2', 'en-a2-39', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_39_2_1', 'ten_a2_39_2', 'refrigerator', 'Replacing an old refrigerator with an efficient model can reduce household electricity consumption significantly.', 'Replacing an old refrigerator with an efficient model can reduce household electricity consumption significantly.', '/rɪˈfrɪdʒəreɪtər/', 'Việc thay thế một chiếc tủ lạnh cũ bằng mẫu tiết kiệm điện có thể làm giảm đáng kể lượng điện tiêu thụ trong gia đình.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_39_2_2', 'ten_a2_39_2', 'ninth', 'By the ninth year of the conservation programme, several endangered species had begun to recover.', 'By the ninth year of the conservation programme, several endangered species had begun to recover.', '/naɪnθ/', 'Đến năm thứ chín của chương trình bảo tồn, một số loài có nguy cơ tuyệt chủng đã bắt đầu phục hồi.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_39_2_3', 'ten_a2_39_2', 'reply', 'Local officials should reply promptly to residents who raise concerns about public transport services.', 'Local officials should reply promptly to residents who raise concerns about public transport services.', '/rɪˈplaɪ/', 'Các quan chức địa phương nên phản hồi kịp thời những cư dân bày tỏ lo ngại về dịch vụ giao thông công cộng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_39_2_4', 'ten_a2_39_2', 'bean', 'Beans provide an affordable source of protein and can support a balanced plant-based diet.', 'Beans provide an affordable source of protein and can support a balanced plant-based diet.', '/biːn/', 'Các loại đậu là nguồn cung cấp protein giá cả phải chăng và giúp duy trì chế độ ăn chay cân bằng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_39_2_5', 'ten_a2_39_2', 'fail', 'Recycling programmes often fail when local authorities do not provide clear guidance or convenient collection services.', 'Recycling programmes often fail when local authorities do not provide clear guidance or convenient collection services.', '/feɪl/', 'Các chương trình tái chế thường thất bại khi chính quyền địa phương không cung cấp hướng dẫn rõ ràng hoặc dịch vụ thu gom thuận tiện.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_39_2_6', 'ten_a2_39_2', 'unlucky', 'Students who are unlucky enough to fall ill during examinations should be offered alternative assessment arrangements.', 'Students who are unlucky enough to fall ill during examinations should be offered alternative assessment arrangements.', '/ʌnˈlʌki/', 'Những học sinh không may bị ốm trong thời gian thi cử nên được tạo điều kiện sắp xếp hình thức đánh giá thay thế.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_39_2_1', 'en-a2-39', 'ten_a2_39_2', 'listening', 'listening', 'Replacing an old refrigerator with an efficient model can reduce household electricity consumption significantly.', NULL, 'Trong câu vừa nghe, từ “refrigerator” mang nghĩa nào sau đây?', '["người đọc (đặc biệt là sách, báo hoặc tạp chí)","trường hợp; ví dụ; căn bệnh","tủ lạnh; tủ cấp đông","con vịt; thịt vịt"]'::jsonb, 2, '“refrigerator” (/rɪˈfrɪdʒəreɪtər/): tủ lạnh; tủ cấp đông. Câu đầy đủ: Replacing an old refrigerator with an efficient model can reduce household electricity consumption significantly.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
