INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_39_5', 'en-a2-39', NULL, 'comprehensive_test', 'listening', 'fail', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["bình hoa; lọ hoa","thất bại; không làm được việc gì đó","cung cấp; đáp ứng","hét; la lớn; gọi lớn"]'::jsonb, 1, 'fail (/feɪl/) → thất bại; không làm được việc gì đó; trượt (kì thi); cho điểm trượt; hỏng hóc; suy yếu; ngưng hoạt động tốt', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_39_6', 'en-a2-39', NULL, 'comprehensive_test', 'listening', 'We were unlucky to miss the bus by seconds.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi xem một bộ phim và ăn tối sau đó.","Mọi người đều đồng thanh hò reo lớn khi đội chúng ta giành chiến thắng trong trận đấu.","Chúng tôi thật xui xẻo khi lỡ chuyến xe buýt chỉ trong tích tắc.","Lối đi chính nằm ngay bên cạnh quán cà phê nhỏ."]'::jsonb, 2, 'We were unlucky to miss the bus by seconds. → Chúng tôi thật xui xẻo khi lỡ chuyến xe buýt chỉ trong tích tắc.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_39_7', 'en-a2-39', NULL, 'comprehensive_test', 'listening', 'ahead', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đặc biệt; nhất là","cãi nhau; tranh cãi","trật tự, thứ tự","ở phía trước; tiến về phía trước"]'::jsonb, 3, 'ahead (/əˈhed/) → ở phía trước; tiến về phía trước; vượt lên trước; sớm hơn dự kiến; trong tương lai; chuẩn bị trước', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_39_8', 'en-a2-39', NULL, 'comprehensive_test', 'listening', 'She served the steak with potatoes and green beans.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cứ đi thẳng phía trước cho đến khi bạn đến cây cầu nhỏ.","Chúng tôi thật xui xẻo khi lỡ chuyến xe buýt chỉ trong tích tắc.","Cô ấy phục vụ món bít tết kèm khoai tây và đậu cô ve.","Cô ấy đã chọn vải cotton mềm mại để làm chăn cho em bé."]'::jsonb, 2, 'She served the steak with potatoes and green beans. → Cô ấy phục vụ món bít tết kèm khoai tây và đậu cô ve.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_39_9', 'en-a2-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “to be unsuccessful or not do something required”?', '["fail","bean","level","main"]'::jsonb, 0, 'fail (/feɪl/) → thất bại; không làm được việc gì đó', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_39_10', 'en-a2-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “Experiencing bad things because of chance”?', '["refrigerator","notice","unlucky","level"]'::jsonb, 2, 'unlucky (/ʌnˈlʌki/) → gặp vận đen; kém may mắn', 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_39_11', 'en-a2-39', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “In front of someone or something, or moving forward.”?', '["afterwards","twelfth","ahead","mess"]'::jsonb, 2, 'ahead (/əˈhed/) → ở phía trước; tiến về phía trước', 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
