INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_39_18', 'en-a2-39', NULL, 'comprehensive_test', 'reading', NULL, 'Replacing an old refrigerator with an efficient model can reduce household electricity consumption significantly.', 'Dựa vào câu trên, từ “refrigerator” có nghĩa phù hợp nhất là gì?', '["tủ lạnh; tủ cấp đông","dầu gội đầu","thuộc Thụy Sĩ; thuộc người hoặc văn hóa Thụy Sĩ","củ tỏi; tép tỏi"]'::jsonb, 0, 'refrigerator: tủ lạnh; tủ cấp đông. Dịch cả câu: Việc thay thế một chiếc tủ lạnh cũ bằng mẫu tiết kiệm điện có thể làm giảm đáng kể lượng điện tiêu thụ trong gia đình.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_39_19', 'en-a2-39', NULL, 'comprehensive_test', 'reading', NULL, 'By the ninth year of the conservation programme, several endangered species had begun to recover.', 'Dựa vào câu trên, từ “ninth” có nghĩa phù hợp nhất là gì?', '["có sẵn; có thể mua/dùng được","quê hương, thị trấn hoặc thành phố nơi lớn lên hoặc xuất thân","thứ chín","nhà thờ"]'::jsonb, 2, 'ninth: thứ chín; một phần chín. Dịch cả câu: Đến năm thứ chín của chương trình bảo tồn, một số loài có nguy cơ tuyệt chủng đã bắt đầu phục hồi.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_39_20', 'en-a2-39', NULL, 'comprehensive_test', 'reading', NULL, 'Local officials should reply promptly to residents who raise concerns about public transport services.', 'Dựa vào câu trên, từ “reply” có nghĩa phù hợp nhất là gì?', '["cung cấp; đáp ứng","hài kịch; phim hài","hạt tiêu; bột tiêu","trả lời; hồi âm"]'::jsonb, 3, 'reply: trả lời; hồi âm; câu trả lời; sự hồi âm. Dịch cả câu: Các quan chức địa phương nên phản hồi kịp thời những cư dân bày tỏ lo ngại về dịch vụ giao thông công cộng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_39_21', 'en-a2-39', NULL, 'comprehensive_test', 'reading', NULL, 'Beans provide an affordable source of protein and can support a balanced plant-based diet.', 'Dựa vào câu trên, từ “bean” có nghĩa phù hợp nhất là gì?', '["hạt đậu; cây đậu","thuộc nam giới; thuộc giống đực","dê","hầu như; suýt; gần như"]'::jsonb, 0, 'bean: hạt đậu; cây đậu. Dịch cả câu: Các loại đậu là nguồn cung cấp protein giá cả phải chăng và giúp duy trì chế độ ăn chay cân bằng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_39_22', 'en-a2-39', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “toàn bộ; trọn vẹn; không thiếu phần nào”', '["file","traffic","broken","whole"]'::jsonb, 3, 'toàn bộ; trọn vẹn; không thiếu phần nào → whole (/hoʊl/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_39_23', 'en-a2-39', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “to; lớn tiếng; ồn ào”', '["loudly","classmate","entrance","type"]'::jsonb, 0, 'to; lớn tiếng; ồn ào → loudly (/ˈlaʊdli/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_39_24', 'en-a2-39', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “chính; chủ yếu”', '["congratulations","main","shout","smoking"]'::jsonb, 1, 'chính; chủ yếu → main (/meɪn/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-40', 'en', 'Bài 40: Đời sống hằng ngày (12) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '26 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2040, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_several', 'en-a2-40', 'several', '/ˈsevrəl/', 'A2', 'vài; một vài (hơn hai nhưng không nhiều); vài người; một số vật (đã được đề cập hoặc ngầm hiểu)', 'det.', NULL, 'Đồng nghĩa: a few', 'Theo sau là danh từ đếm được số nhiều; several of đi sau với từ hạn định hoặc đại từ.', 'I tried several jackets before choosing the blue one.', NULL, 'Tôi đã thử vài chiếc áo khoác trước khi chọn chiếc màu xanh.', '{"wordId":"several","ukIpa":"/ˈsevrəl/","usIpa":"/ˈsevrəl/","cefr":"A2","topic":"daily","senses":[{"pos":"det.","en":"More than two but not many","vi":"vài; một vài (hơn hai nhưng không nhiều)"},{"pos":"pron.","en":"A few people or things already mentioned or understood","vi":"vài người; một số vật (đã được đề cập hoặc ngầm hiểu)"}],"examples":[{"en":"I tried several jackets before choosing the blue one.","vi":"Tôi đã thử vài chiếc áo khoác trước khi chọn chiếc màu xanh.","audioKind":"ex"},{"en":"Several studies suggest that access to green spaces can improve mental health among people living in cities.","vi":"Một số nghiên cứu cho thấy việc tiếp cận không gian xanh có thể cải thiện sức khỏe tinh thần của những người sống ở các thành phố.","audioKind":"ex2"}],"collocations":[{"en":"several times","vi":"vài lần"},{"en":"several years","vi":"nhiều năm"},{"en":"several of them","vi":"một vài người trong số họ"},{"en":"for several reasons","vi":"vì một số lý do"}],"wordFamily":[],"synonyms":["a few"],"antonyms":[],"tipVi":"Theo sau là danh từ đếm được số nhiều; several of đi sau với từ hạn định hoặc đại từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_collect', 'en-a2-40', 'collect', '/kəˈlekt/', 'A2', 'thu thập; sưu tầm; đến đón; nhận; quyên góp; thu tiền', 'v.', 'collection (n.), collector (n.), collectable (adj.)', 'Đồng nghĩa: gather', 'Trong tiếng Anh-Anh, collect someone có thể mang nghĩa đi đón ai đó.', 'I collect smooth stones whenever we visit the beach.', NULL, 'Tôi nhặt sưu tầm những viên đá nhẵn mỗi khi chúng tôi đến bãi biển.', '{"wordId":"collect","ukIpa":"/kəˈlekt/","usIpa":"/kəˈlekt/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To gather things together or keep objects as a hobby","vi":"thu thập; sưu tầm"},{"pos":"v.","en":"To go somewhere and bring someone or something away","vi":"đến đón; nhận"},{"pos":"v.","en":"To receive or gather money from people","vi":"quyên góp; thu tiền"}],"examples":[{"en":"I collect smooth stones whenever we visit the beach.","vi":"Tôi nhặt sưu tầm những viên đá nhẵn mỗi khi chúng tôi đến bãi biển.","audioKind":"ex"},{"en":"Researchers collect data from local households to assess how transport policies affect daily travel habits.","vi":"Các nhà nghiên cứu thu thập dữ liệu từ các hộ gia đình địa phương để đánh giá chính sách giao thông tác động thế nào đến thói quen đi lại hằng ngày.","audioKind":"ex2"}],"collocations":[{"en":"collect data","vi":"thu thập dữ liệu"},{"en":"collect a parcel","vi":"nhận bưu kiện"},{"en":"collect donations","vi":"quyên góp từ thiện"},{"en":"collect stamps","vi":"sưu tầm tem"}],"wordFamily":["collection (n.)","collector (n.)","collectable (adj.)"],"synonyms":["gather"],"antonyms":[],"tipVi":"Trong tiếng Anh-Anh, collect someone có thể mang nghĩa đi đón ai đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_extra', 'en-a2-40', 'extra', '/ˈekstrə/', 'A2', 'thêm; phụ; hơn bình thường; phần thêm; diễn viên quần chúng', 'adj.', NULL, 'Đồng nghĩa: additional, supplementary', 'Tính từ (adj.) chỉ mức độ phụ thêm; trong cụm pay extra, từ này đóng vai trò trạng từ (adv.).', 'I packed an extra sweater because the evenings get cold.', NULL, 'Tôi gói thêm một chiếc áo len vì trời tối sẽ lạnh.', '{"wordId":"extra","ukIpa":"/ˈekstrə/","usIpa":"/ˈekstrə/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"added to the usual or necessary amount","vi":"thêm; phụ"},{"pos":"adv.","en":"more than usual, or in addition to the normal amount","vi":"hơn bình thường; phụ"},{"pos":"n.","en":"an additional item, or a background actor in a film","vi":"phần thêm; diễn viên quần chúng"}],"examples":[{"en":"I packed an extra sweater because the evenings get cold.","vi":"Tôi gói thêm một chiếc áo len vì trời tối sẽ lạnh.","audioKind":"ex"},{"en":"Schools should provide extra support for students who struggle to access learning materials at home.","vi":"Nhà trường nên hỗ trợ thêm cho những học sinh gặp khó khăn trong việc tiếp cận tài liệu học tập tại nhà.","audioKind":"ex2"}],"collocations":[{"en":"extra time","vi":"thời gian bù giờ"},{"en":"extra charge","vi":"phí phụ thu"},{"en":"extra care","vi":"sự chăm sóc đặc biệt"},{"en":"pay extra","vi":"trả thêm tiền"}],"wordFamily":[],"synonyms":["additional","supplementary"],"antonyms":[],"tipVi":"Tính từ (adj.) chỉ mức độ phụ thêm; trong cụm pay extra, từ này đóng vai trò trạng từ (adv.).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_guy', 'en-a2-40', 'guy', '/ɡaɪ/', 'A2', 'chàng trai; anh chàng', 'n.', NULL, 'Đồng nghĩa: man, fellow', 'guy thuộc văn phong khẩu ngữ; văn viết trang trọng thường dùng man hoặc person.', 'The guy next door helped carry my groceries.', NULL, 'Anh chàng ở nhà bên cạnh đã giúp tôi xách đồ tạp hóa về.', '{"wordId":"guy","ukIpa":"/ɡaɪ/","usIpa":"/ɡaɪ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"An informal word for a man.","vi":"chàng trai; anh chàng"}],"examples":[{"en":"The guy next door helped carry my groceries.","vi":"Anh chàng ở nhà bên cạnh đã giúp tôi xách đồ tạp hóa về.","audioKind":"ex"},{"en":"Calling a colleague a guy may sound friendly, but informal vocabulary is usually inappropriate in academic writing.","vi":"Gọi đồng nghiệp là guy có thể nghe có vẻ thân thiện, nhưng từ vựng mang tính suồng sã thường không phù hợp trong văn viết học thuật.","audioKind":"ex2"}],"collocations":[{"en":"a nice guy","vi":"một anh chàng tốt bụng"},{"en":"a young guy","vi":"một chàng trai trẻ"},{"en":"a regular guy","vi":"một người bình thường"}],"wordFamily":[],"synonyms":["man","fellow"],"antonyms":[],"tipVi":"guy thuộc văn phong khẩu ngữ; văn viết trang trọng thường dùng man hoặc person.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_coloured', 'en-a2-40', 'coloured', '/ˈkʌlərd/', 'A2', 'có màu sắc; được nhuộm màu', 'adj.', 'colour (n.), colour (v.), colourful (adj.), colourless (adj.)', 'Trái nghĩa: colourless', 'Anh-Anh viết là coloured, Anh-Mỹ viết là colored; tránh dùng để chỉ chung chung các nhóm sắc tộc.', 'Sunlight streamed through the coloured glass onto the floor.', NULL, 'Ánh nắng xuyên qua lớp kính có màu chiếu xuống sàn nhà.', '{"wordId":"coloured","ukIpa":"/ˈkʌləd/","usIpa":"/ˈkʌlərd/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Having a particular colour or colours rather than being plain.","vi":"có màu sắc; được nhuộm màu"}],"examples":[{"en":"Sunlight streamed through the coloured glass onto the floor.","vi":"Ánh nắng xuyên qua lớp kính có màu chiếu xuống sàn nhà.","audioKind":"ex"},{"en":"Teachers can use coloured blocks to help young children recognise patterns and develop basic mathematical skills.","vi":"Giáo viên có thể sử dụng các khối hình nhiều màu sắc để giúp trẻ nhỏ nhận biết các quy luật và phát triển các kỹ năng toán học cơ bản.","audioKind":"ex2"}],"collocations":[{"en":"coloured glass","vi":"kính có màu"},{"en":"coloured pencils","vi":"bút chì màu"},{"en":"brightly coloured","vi":"sặc sỡ"}],"wordFamily":["colour (n.)","colour (v.)","colourful (adj.)","colourless (adj.)"],"synonyms":[],"antonyms":["colourless"],"tipVi":"Anh-Anh viết là coloured, Anh-Mỹ viết là colored; tránh dùng để chỉ chung chung các nhóm sắc tộc.","noteVi":"Dùng để chỉ người da màu thường bị coi là lỗi thời và xúc phạm; ở một số khu vực có cách dùng chỉ danh tính đặc thù.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_gift', 'en-a2-40', 'gift', '/ɡɪft/', 'A2', 'quà; quà tặng; năng khiếu; tài năng; tặng; biếu', 'n.', 'gifted (adj.)', 'Đồng nghĩa: present, talent', 'Khi chỉ năng khiếu, thường dùng cấu trúc a gift for, theo sau là danh từ hoặc danh động từ.', 'My sister wrapped the gift in bright yellow paper.', NULL, 'Em gái tôi gói món quà bằng lớp giấy màu vàng tươi.', '{"wordId":"gift","ukIpa":"/ɡɪft/","usIpa":"/ɡɪft/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Something given freely to another person","vi":"quà; quà tặng"},{"pos":"n.","en":"A natural ability to do something well","vi":"năng khiếu; tài năng"},{"pos":"v.","en":"To give something to someone as a present","vi":"tặng; biếu"}],"examples":[{"en":"My sister wrapped the gift in bright yellow paper.","vi":"Em gái tôi gói món quà bằng lớp giấy màu vàng tươi.","audioKind":"ex"},{"en":"Schools should nurture each child''s gift rather than judge everyone by the same narrow standards.","vi":"Nhà trường nên bồi dưỡng năng khiếu của mỗi đứa trẻ thay vì đánh giá tất cả mọi người bằng cùng một tiêu chuẩn rập khuôn.","audioKind":"ex2"}],"collocations":[{"en":"birthday gift","vi":"quà sinh nhật"},{"en":"a gift for languages","vi":"năng khiếu ngoại ngữ"},{"en":"gift shop","vi":"cửa hàng quà lưu niệm"}],"wordFamily":["gifted (adj.)"],"synonyms":["present","talent"],"antonyms":[],"tipVi":"Khi chỉ năng khiếu, thường dùng cấu trúc a gift for, theo sau là danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blouse', 'en-a2-40', 'blouse', '/blaʊs/', 'A2', 'áo sơ-mi nữ; áo cánh nữ', 'n.', NULL, NULL, 'Thường chỉ áo sơ-mi dành cho phụ nữ; từ shirt có phạm vi sử dụng rộng hơn.', 'She wore a blue blouse with her favourite grey trousers.', NULL, 'Cô ấy mặc một chiếc áo sơ-mi nữ màu xanh lam với chiếc quần dài màu xám yêu thích.', '{"wordId":"blouse","ukIpa":"/blaʊz/","usIpa":"/blaʊs/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A shirt traditionally worn by women, often made from light fabric","vi":"áo sơ-mi nữ; áo cánh nữ"}],"examples":[{"en":"She wore a blue blouse with her favourite grey trousers.","vi":"Cô ấy mặc một chiếc áo sơ-mi nữ màu xanh lam với chiếc quần dài màu xám yêu thích.","audioKind":"ex"},{"en":"Choosing a durable blouse rather than a cheaply made alternative may reduce clothing waste over time.","vi":"Việc lựa chọn một chiếc áo sơ-mi nữ bền thay vì sản phẩm giá rẻ kém chất lượng có thể giúp giảm thiểu lượng rác thải thời trang theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"silk blouse","vi":"áo sơ-mi lụa"},{"en":"long-sleeved blouse","vi":"áo sơ-mi nữ dài tay"},{"en":"loose-fitting blouse","vi":"áo sơ-mi nữ rộng rãi"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường chỉ áo sơ-mi dành cho phụ nữ; từ shirt có phạm vi sử dụng rộng hơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_detail', 'en-a2-40', 'detail', '/ˈdiːteɪl/', 'A2', 'chi tiết; tiểu tiết; mức độ chi tiết; trình bày chi tiết; kể tỉ mỉ', 'n.', 'detailed (adj.)', 'Đồng nghĩa: particular', 'Cụm in detail không dùng số nhiều; thông tin liên hệ dùng contact details.', 'Please check every detail before you send the invitation.', NULL, 'Vui lòng kiểm tra từng chi tiết trước khi bạn gửi lời mời.', '{"wordId":"detail","ukIpa":"/ˈdiːteɪl/","usIpa":"/ˈdiːteɪl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a small fact or feature of something","vi":"chi tiết; tiểu tiết"},{"pos":"n.","en":"the amount of specific information provided","vi":"mức độ chi tiết"},{"pos":"v.","en":"to describe something fully, including specific facts","vi":"trình bày chi tiết; kể tỉ mỉ"}],"examples":[{"en":"Please check every detail before you send the invitation.","vi":"Vui lòng kiểm tra từng chi tiết trước khi bạn gửi lời mời.","audioKind":"ex"},{"en":"The report details how improved housing conditions can reduce health inequalities among families in urban areas.","vi":"Báo cáo này trình bày chi tiết về việc cải thiện điều kiện nhà ở có thể làm giảm sự bất bình đẳng về sức khỏe giữa các gia đình ở khu vực thành thị như thế nào.","audioKind":"ex2"}],"collocations":[{"en":"in detail","vi":"chi tiết; một cách chi tiết"},{"en":"pay attention to detail","vi":"chú ý đến chi tiết"},{"en":"contact details","vi":"thông tin liên hệ"},{"en":"further details","vi":"thông tin chi tiết thêm"}],"wordFamily":["detailed (adj.)"],"synonyms":["particular"],"antonyms":[],"tipVi":"Cụm in detail không dùng số nhiều; thông tin liên hệ dùng contact details.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_serve', 'en-a2-40', 'serve', '/sɝːv/', 'A2', 'phục vụ đồ ăn thức uống; tiếp đón khách hàng; phục vụ cho ai, tổ chức nào hoặc đất nước; dùng làm; đóng vai trò là', 'v.', 'service (n.), server (n.), serving (n.)', NULL, 'serve as sau đó đi kèm với vai trò hoặc mục đích; serve for không dùng như vậy.', 'This little café serves fresh soup with warm bread.', NULL, 'Quán cà phê nhỏ này phục vụ súp tươi kèm bánh mì ấm.', '{"wordId":"serve","ukIpa":"/sɜːv/","usIpa":"/sɝːv/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To give food or drink, or assist customers.","vi":"phục vụ đồ ăn thức uống; tiếp đón khách hàng"},{"pos":"v.","en":"To work for people, an organisation, or your country.","vi":"phục vụ cho ai, tổ chức nào hoặc đất nước"},{"pos":"v.","en":"To be used for a particular purpose.","vi":"dùng làm; đóng vai trò là"}],"examples":[{"en":"This little café serves fresh soup with warm bread.","vi":"Quán cà phê nhỏ này phục vụ súp tươi kèm bánh mì ấm.","audioKind":"ex"},{"en":"Public libraries serve as community spaces where residents can access information, attend workshops, and meet other learners.","vi":"Các thư viện công cộng đóng vai trò là không gian cộng đồng, nơi cư dân có thể tiếp cận thông tin, thamam gia các buổi hội thảo và gặp gỡ những người học khác.","audioKind":"ex2"}],"collocations":[{"en":"serve a meal","vi":"dọn một bữa ăn"},{"en":"serve customers","vi":"phục vụ khách hàng"},{"en":"serve the community","vi":"phục vụ cộng đồng"},{"en":"serve as","vi":"đóng vai trò là"}],"wordFamily":["service (n.)","server (n.)","serving (n.)"],"synonyms":[],"antonyms":[],"tipVi":"serve as sau đó đi kèm với vai trò hoặc mục đích; serve for không dùng như vậy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_least', 'en-a2-40', 'least', '/liːst/', 'A2', 'ít nhất; số lượng nhỏ nhất; ở mức độ hoặc phạm vi thấp nhất; lượng nhỏ nhất; mức độ thấp nhất', 'det.', 'little (det.), less (det.)', 'Trái nghĩa: most', 'least là dạng so sánh nhất của little; khi bổ nghĩa cho danh từ đếm được thì dùng fewest.', 'This soup needs the least salt of all.', NULL, 'Món súp này cần ít muối nhất trong tất cả.', '{"wordId":"least","ukIpa":"/liːst/","usIpa":"/liːst/","cefr":"A2","topic":"daily","senses":[{"pos":"det.","en":"the smallest amount of something","vi":"ít nhất; số lượng nhỏ nhất"},{"pos":"adv.","en":"to the smallest degree or extent","vi":"ít nhất; ở mức độ hoặc phạm vi thấp nhất"},{"pos":"pron.","en":"the smallest amount or degree","vi":"lượng nhỏ nhất; mức độ thấp nhất"}],"examples":[{"en":"This soup needs the least salt of all.","vi":"Món súp này cần ít muối nhất trong tất cả.","audioKind":"ex"},{"en":"Public transport often causes the least pollution per passenger when compared with private car travel.","vi":"Phương tiện giao thông công cộng thường gây ra lượng ô nhiễm ít nhất tính trên mỗi hành khách khi so sánh với việc đi lại bằng xe hơi cá nhân.","audioKind":"ex2"}],"collocations":[{"en":"at least","vi":"ít nhất"},{"en":"the least expensive","vi":"ít tốn kém nhất"},{"en":"least of all","vi":"ít nhất là; đặc biệt là"}],"wordFamily":["little (det.)","less (det.)"],"synonyms":[],"antonyms":["most"],"tipVi":"least là dạng so sánh nhất của little; khi bổ nghĩa cho danh từ đếm được thì dùng fewest.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_microwave', 'en-a2-40', 'microwave', '/ˈmaɪkroʊweɪv/', 'A2', 'lò vi sóng; nấu hoặc hâm nóng thức ăn bằng lò vi sóng; vi sóng', 'n.', NULL, NULL, 'Khi đóng vai trò là động từ, có thể đi trực tiếp với tân ngữ chỉ đồ ăn: microwave the soup.', 'I heated yesterday''s soup in the microwave for lunch.', NULL, 'Tôi đã hâm nóng phần súp hôm qua bằng lò vi sóng để ăn trưa.', '{"wordId":"microwave","ukIpa":"/ˈmaɪkrəweɪv/","usIpa":"/ˈmaɪkroʊweɪv/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"An electric oven that heats food using electromagnetic waves","vi":"lò vi sóng"},{"pos":"v.","en":"To cook or heat food in a microwave oven","vi":"nấu hoặc hâm nóng thức ăn bằng lò vi sóng"},{"pos":"n.","en":"A short electromagnetic wave used for heating and communication","vi":"vi sóng"}],"examples":[{"en":"I heated yesterday''s soup in the microwave for lunch.","vi":"Tôi đã hâm nóng phần súp hôm qua bằng lò vi sóng để ăn trưa.","audioKind":"ex"},{"en":"Using a microwave to reheat small portions can consume less energy than using a conventional oven.","vi":"Sử dụng lò vi sóng để hâm nóng khẩu phần nhỏ có thể tiêu tốn ít năng lượng hơn so với dùng lò nướng thông thường.","audioKind":"ex2"}],"collocations":[{"en":"microwave oven","vi":"lò vi sóng"},{"en":"microwave food","vi":"hâm nóng thức ăn bằng lò vi sóng"},{"en":"microwave radiation","vi":"bức xạ vi sóng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi đóng vai trò là động từ, có thể đi trực tiếp với tân ngữ chỉ đồ ăn: microwave the soup.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lamp', 'en-a2-40', 'lamp', '/læmp/', 'A2', 'đèn bàn; đèn', 'n.', NULL, NULL, 'lamp chỉ thiết bị đèn chiếu sáng; light cũng có thể chỉ ánh sáng hoặc ngọn đèn nói chung.', 'She switched on the lamp beside her bed.', NULL, 'Cô ấy bật chiếc đèn đặt cạnh giường của mình.', '{"wordId":"lamp","ukIpa":"/læmp/","usIpa":"/læmp/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A device that produces light, often on a table.","vi":"đèn bàn; đèn"}],"examples":[{"en":"She switched on the lamp beside her bed.","vi":"Cô ấy bật chiếc đèn đặt cạnh giường của mình.","audioKind":"ex"},{"en":"Using an adjustable desk lamp can improve comfort for students who study in poorly lit rooms.","vi":"Sử dụng đèn bàn có thể điều chỉnh độ sáng có thể giúp học sinh học tập thoải mái hơn trong những căn phòng thiếu sáng.","audioKind":"ex2"}],"collocations":[{"en":"desk lamp","vi":"đèn bàn làm việc"},{"en":"bedside lamp","vi":"đèn ngủ đầu giường"},{"en":"floor lamp","vi":"đèn cây"},{"en":"switch on a lamp","vi":"bật đèn"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"lamp chỉ thiết bị đèn chiếu sáng; light cũng có thể chỉ ánh sáng hoặc ngọn đèn nói chung.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_grape', 'en-a2-40', 'grape', '/ɡreɪp/', 'A2', 'quả nho; chùm nho', 'n.', NULL, NULL, 'Quả nho đơn lẻ dùng a grape, còn một chùm nho dùng a bunch of grapes.', 'She packed some grapes in my lunch box.', NULL, 'Cô ấy đã bỏ vài quả nho vào hộp cơm trưa của tôi.', '{"wordId":"grape","ukIpa":"/ɡreɪp/","usIpa":"/ɡreɪp/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A small round fruit growing in bunches on vines.","vi":"quả nho; chùm nho"}],"examples":[{"en":"She packed some grapes in my lunch box.","vi":"Cô ấy đã bỏ vài quả nho vào hộp cơm trưa của tôi.","audioKind":"ex"},{"en":"Farmers growing grapes may need more efficient irrigation systems as summers become hotter and drier.","vi":"Những người nông dân trồng nho có thể cần các hệ thống tưới tiêu hiệu quả hơn khi mùa hè trở nên nóng và khô hơn.","audioKind":"ex2"}],"collocations":[{"en":"a bunch of grapes","vi":"một chùm nho"},{"en":"seedless grapes","vi":"nho không hạt"},{"en":"grape juice","vi":"nước ép nho"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Quả nho đơn lẻ dùng a grape, còn một chùm nho dùng a bunch of grapes.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pan', 'en-a2-40', 'pan', '/pæn/', 'A2', 'cái chảo; nồi nông lòng; khay nướng; chê bai, chỉ trích gay gắt (vở kịch, sách, phim); quay quét máy quay (để ghi hình toàn cảnh)', 'n.', NULL, NULL, 'Khi là động từ, dạng quá khứ của pan là panned và phân từ hiện đại là panning.', 'Heat the oil in a pan before adding onions.', NULL, 'Đun nóng dầu trong chảo trước khi cho hành tây vào.', '{"wordId":"pan","ukIpa":"/pæn/","usIpa":"/pæn/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a metal container used for cooking or baking food","vi":"cái chảo; nồi nông lòng; khay nướng"},{"pos":"v.","en":"to criticize a performance, book, or film very harshly","vi":"chê bai, chỉ trích gay gắt (vở kịch, sách, phim)"},{"pos":"v.","en":"to turn a camera slowly across a scene","vi":"quay quét máy quay (để ghi hình toàn cảnh)"}],"examples":[{"en":"Heat the oil in a pan before adding onions.","vi":"Đun nóng dầu trong chảo trước khi cho hành tây vào.","audioKind":"ex"},{"en":"Television chefs can encourage healthier eating by demonstrating how to prepare nutritious meals using a single pan.","vi":"Các đầu bếp truyền hình có thể khuyến khích lối sống lành mạnh hơn bằng cách hướng dẫn cách chế biến các món ăn bổ dưỡng chỉ bằng một chiếc chảo duy nhất.","audioKind":"ex2"}],"collocations":[{"en":"frying pan","vi":"chảo rán"},{"en":"baking pan","vi":"khay nướng bánh"},{"en":"be panned by critics","vi":"bị các nhà phê bình chỉ trích gay gắt"},{"en":"pan across a scene","vi":"quay quét toàn cảnh"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Khi là động từ, dạng quá khứ của pan là panned và phân từ hiện đại là panning.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_step', 'en-a2-40', 'step', '/step/', 'A2', 'bước chân; bậc thang; bước tiến, bước đi trong một quá trình hoặc nhằm đạt được mục tiêu; bước đi; dẫm, bước lên', 'n.', NULL, NULL, 'Cấu trúc take steps to do sth có nghĩa là "thích nghi hoặc thực hiện các biện pháp để làm gì đó".', 'Take one step forward and close the door.', NULL, 'Hãy bước lên một bước và đóng cửa lại.', '{"wordId":"step","ukIpa":"/step/","usIpa":"/step/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a foot movement when walking, or a stair surface","vi":"bước chân; bậc thang"},{"pos":"n.","en":"one action in a process or towards a goal","vi":"bước tiến, bước đi trong một quá trình hoặc nhằm đạt được mục tiêu"},{"pos":"v.","en":"to move by lifting and placing your foot","vi":"bước đi; dẫm, bước lên"}],"examples":[{"en":"Take one step forward and close the door.","vi":"Hãy bước lên một bước và đóng cửa lại.","audioKind":"ex"},{"en":"Improving public transport is an important step towards reducing traffic congestion and air pollution in cities.","vi":"Cải thiện giao thông công cộng là một bước quan trọng để giảm ùn tắc giao thông và ô nhiễm không khí ở các đô thị.","audioKind":"ex2"}],"collocations":[{"en":"take a step","vi":"bước một bước; thực hiện một bước"},{"en":"step by step","vi":"từng bước một"},{"en":"take steps to","vi":"tiến hành các biện pháp để"},{"en":"step on","vi":"dẫm lên, bước lên"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cấu trúc take steps to do sth có nghĩa là \"thích nghi hoặc thực hiện các biện pháp để làm gì đó\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_double', 'en-a2-40', 'double', '/ˈdʌbəl/', 'A2', 'gấp đôi, gấp rưỡi; tăng lên gấp đôi, làm cho gấp đôi; lượng gấp đôi, con số gấp đôi', 'adj.', 'doubly (adv.)', 'Đồng nghĩa: twofold · Trái nghĩa: single, halve', 'Double dùng để diễn tả việc tăng giá trị lên gấp đôi so với ban đầu.', 'I ordered a double portion of rice for lunch.', NULL, 'Tôi đã gọi một phần cơm gấp đôi cho bữa trưa.', '{"wordId":"double","ukIpa":"/ˈdʌbəl/","usIpa":"/ˈdʌbəl/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"twice the usual amount, size, or quantity","vi":"gấp đôi, gấp rưỡi"},{"pos":"v.","en":"become twice as much, or make something twice as much","vi":"tăng lên gấp đôi, làm cho gấp đôi"},{"pos":"n.","en":"an amount that is twice as large as another","vi":"lượng gấp đôi, con số gấp đôi"}],"examples":[{"en":"I ordered a double portion of rice for lunch.","vi":"Tôi đã gọi một phần cơm gấp đôi cho bữa trưa.","audioKind":"ex"},{"en":"The city plans to double its investment in cycling infrastructure to reduce traffic congestion.","vi":"Thành phố có kế hoạch tăng gấp đôi vốn đầu tư vào cơ sở hạ tầng xe đạp nhằm giảm thiểu tình trạng ùn tắc giao thông.","audioKind":"ex2"}],"collocations":[{"en":"double the amount","vi":"số lượng gấp đôi"},{"en":"double in size","vi":"quy mô tăng gấp đôi"},{"en":"double check","vi":"kiểm tra kỹ lưỡng"},{"en":"double room","vi":"phòng đôi"}],"wordFamily":["doubly (adv.)"],"synonyms":["twofold"],"antonyms":["single","halve"],"tipVi":"Double dùng để diễn tả việc tăng giá trị lên gấp đôi so với ban đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_carpet', 'en-a2-40', 'carpet', '/ˈkɑːrpɪt/', 'A2', 'tấm thảm (trải sàn)', 'n.', 'carpeted (adj.), carpeting (n.)', NULL, 'Carpet thường chỉ thảm lớn trải cố định; rug thường chỉ thảm nhỏ có thể di chuyển.', 'We sat on the carpet and played cards.', NULL, 'Chúng tôi ngồi trên thảm và chơi bài.', '{"wordId":"carpet","ukIpa":"/ˈkɑːpɪt/","usIpa":"/ˈkɑːrpɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A thick woven covering for a floor.","vi":"tấm thảm (trải sàn)"}],"examples":[{"en":"We sat on the carpet and played cards.","vi":"Chúng tôi ngồi trên thảm và chơi bài.","audioKind":"ex"},{"en":"Installing carpet in classrooms can reduce noise, although regular cleaning is necessary to maintain good hygiene.","vi":"Việc lắp đặt thảm trải sàn trong lớp học có thể giúp giảm tiếng ồn, mặc dù việc vệ sinh thường xuyên là rất cần thiết để duy trì vệ sinh tốt.","audioKind":"ex2"}],"collocations":[{"en":"lay a carpet","vi":"trải thảm"},{"en":"fitted carpet","vi":"thảm trải kín sàn"},{"en":"carpet cleaning","vi":"vệ sinh thảm"}],"wordFamily":["carpeted (adj.)","carpeting (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Carpet thường chỉ thảm lớn trải cố định; rug thường chỉ thảm nhỏ có thể di chuyển.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_through', 'en-a2-40', 'through', '/θruː/', 'A2', 'xuyên qua, qua lại bên trong; bằng cách, thông qua (phương pháp, quá trình); từ đầu đến cuối, xuyên suốt', 'prep.', NULL, NULL, 'Through nhấn mạnh việc chuyển động từ bên trong đi ra; across nhấn mạnh việc di chuyển ngang qua bề mặt.', 'Sunlight streamed through the curtains and warmed the room.', NULL, 'Ánh nắng chiếu qua lớp rèm cửa và làm ấm căn phòng.', '{"wordId":"through","ukIpa":"/θruː/","usIpa":"/θruː/","cefr":"A2","topic":"daily","senses":[{"pos":"prep.","en":"From one side or end to the other, within something.","vi":"xuyên qua, qua lại bên trong"},{"pos":"prep.","en":"By using a particular method, person, or process.","vi":"bằng cách, thông qua (phương pháp, quá trình)"},{"pos":"adv.","en":"From beginning to end, or from one side to another.","vi":"từ đầu đến cuối, xuyên suốt"}],"examples":[{"en":"Sunlight streamed through the curtains and warmed the room.","vi":"Ánh nắng chiếu qua lớp rèm cửa và làm ấm căn phòng.","audioKind":"ex"},{"en":"Students can develop practical skills through projects that require cooperation and creative problem solving.","vi":"Học sinh có thể phát triển các kỹ năng thực tế thông qua các dự án đòi hỏi tính hợp tác và khả năng giải quyết vấn đề sáng tạo.","audioKind":"ex2"}],"collocations":[{"en":"walk through","vi":"đi xuyên qua"},{"en":"through experience","vi":"thông qua kinh nghiệm"},{"en":"read through","vi":"đọc từ đầu đến cuối"},{"en":"all through the night","vi":"suốt cả đêm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Through nhấn mạnh việc chuyển động từ bên trong đi ra; across nhấn mạnh việc di chuyển ngang qua bề mặt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_trouble', 'en-a2-40', 'trouble', '/ˈtrʌbəl/', 'A2', 'rắc rối, khó khăn, phiền toái; làm phiền, gây khó dễ, quấy rầy', 'n.', 'troubled (adj.), troubling (adj.), troublesome (adj.)', 'Đồng nghĩa: difficulty, problem', 'Cấu trúc have trouble doing something diễn tả việc gặp khó khăn khi làm gì.', 'We had trouble opening the stiff kitchen window.', NULL, 'Chúng tôi đã gặp khó khăn khi mở cánh cửa sổ nhà bếp bị kẹt cứng.', '{"wordId":"trouble","ukIpa":"/ˈtrʌbəl/","usIpa":"/ˈtrʌbəl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"problems or difficulties that cause worry or inconvenience","vi":"rắc rối, khó khăn, phiền toái"},{"pos":"v.","en":"to cause someone worry or ask them for help","vi":"làm phiền, gây khó dễ, quấy rầy"}],"examples":[{"en":"We had trouble opening the stiff kitchen window.","vi":"Chúng tôi đã gặp khó khăn khi mở cánh cửa sổ nhà bếp bị kẹt cứng.","audioKind":"ex"},{"en":"Many older adults have trouble accessing public services that are available only through digital platforms.","vi":"Nhiều người lớn tuổi gặp khó khăn trong việc tiếp cận các dịch vụ công vốn chỉ có sẵn trên các nền tảng kỹ thuật số.","audioKind":"ex2"}],"collocations":[{"en":"have trouble doing something","vi":"gặp khó khăn khi làm việc gì"},{"en":"get into trouble","vi":"vướng vào rắc rối"},{"en":"engine trouble","vi":"hỏng hóc động cơ"},{"en":"take the trouble to do something","vi":"cất công làm việc gì"}],"wordFamily":["troubled (adj.)","troubling (adj.)","troublesome (adj.)"],"synonyms":["difficulty","problem"],"antonyms":[],"tipVi":"Cấu trúc have trouble doing something diễn tả việc gặp khó khăn khi làm gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_glue', 'en-a2-40', 'glue', '/ɡluː/', 'A2', 'keo, hồ dán; dán bằng keo', 'n.', NULL, 'Đồng nghĩa: adhesive', 'Glue đóng vai trò danh từ thường không đếm được; cụm be glued to có thể dùng để diễn tả việc chăm chú nhìn cái gì.', 'Use a little glue to fix the paper wing.', NULL, 'Hãy dùng một chút keo để gắn cánh bằng giấy lại.', '{"wordId":"glue","ukIpa":"/ɡluː/","usIpa":"/ɡluː/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a sticky substance used to join things together","vi":"keo, hồ dán"},{"pos":"v.","en":"to join things together using glue","vi":"dán bằng keo"}],"examples":[{"en":"Use a little glue to fix the paper wing.","vi":"Hãy dùng một chút keo để gắn cánh bằng giấy lại.","audioKind":"ex"},{"en":"Some packaging contains layers joined with glue, which can make the materials more difficult to recycle.","vi":"Một số loại bao bì có các lớp được dán lại với nhau bằng keo, điều này có thể làm cho vật liệu khó tái chế hơn.","audioKind":"ex2"}],"collocations":[{"en":"glue stick","vi":"thỏi keo khô"},{"en":"wood glue","vi":"keo dán gỗ"},{"en":"glue together","vi":"dán dính vào nhau"},{"en":"be glued to a screen","vi":"dán mắt vào màn hình"}],"wordFamily":[],"synonyms":["adhesive"],"antonyms":[],"tipVi":"Glue đóng vai trò danh từ thường không đếm được; cụm be glued to có thể dùng để diễn tả việc chăm chú nhìn cái gì.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_safe', 'en-a2-40', 'safe', '/seɪf/', 'A2', 'an toàn; chắc chắn; ít rủi ro; két sắt', 'adj.', 'safety (n.), safely (adv.), unsafe (adj.)', 'Đồng nghĩa: secure · Trái nghĩa: dangerous, unsafe', 'safe là tính từ, safety là danh từ; chú ý sự khác biệt về từ loại.', 'Your bike is safe inside our locked garage.', NULL, 'Chiếc xe đạp của bạn nằm an toàn bên trong nhà xe đã khóa.', '{"wordId":"safe","ukIpa":"/seɪf/","usIpa":"/seɪf/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Protected from danger or unlikely to cause harm.","vi":"an toàn"},{"pos":"adj.","en":"Unlikely to fail or lead to loss.","vi":"an toàn; chắc chắn; ít rủi ro"},{"pos":"n.","en":"A strong locked container for money and valuable objects.","vi":"két sắt"}],"examples":[{"en":"Your bike is safe inside our locked garage.","vi":"Chiếc xe đạp của bạn nằm an toàn bên trong nhà xe đã khóa.","audioKind":"ex"},{"en":"Governments should ensure that all communities have access to safe drinking water and reliable sanitation.","vi":"Chính phủ nên đảm bảo rằng mọi cộng đồng đều có thể tiếp cận nước uống an toàn và các dịch vụ vệ sinh đáng tin cậy.","audioKind":"ex2"}],"collocations":[{"en":"safe and sound","vi":"bình an vô sự"},{"en":"safe drinking water","vi":"nước uống an toàn"},{"en":"a safe investment","vi":"khoản đầu tư an toàn"},{"en":"keep someone safe","vi":"bảo vệ ai đó an toàn"}],"wordFamily":["safety (n.)","safely (adv.)","unsafe (adj.)"],"synonyms":["secure"],"antonyms":["dangerous","unsafe"],"tipVi":"safe là tính từ, safety là danh từ; chú ý sự khác biệt về từ loại.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tasty', 'en-a2-40', 'tasty', '/ˈteɪsti/', 'A2', 'ngon; hợp khẩu vị', 'adj.', 'taste (n.), taste (v.), tasteless (adj.)', 'Đồng nghĩa: delicious, flavoursome · Trái nghĩa: tasteless, unpalatable', 'tasty chỉ thức ăn ngon; tasteful chỉ có gu thẩm mỹ, có tinh tế.', 'This tasty soup is perfect for a cold evening.', NULL, 'Món súp ngon lành này rất hoàn hảo cho một buổi tối lạnh giá.', '{"wordId":"tasty","ukIpa":"/ˈteɪsti/","usIpa":"/ˈteɪsti/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"having a pleasant flavour","vi":"ngon; hợp khẩu vị"}],"examples":[{"en":"This tasty soup is perfect for a cold evening.","vi":"Món súp ngon lành này rất hoàn hảo cho một buổi tối lạnh giá.","audioKind":"ex"},{"en":"School canteens can encourage healthier eating by offering tasty meals made with fresh vegetables and whole grains.","vi":"Canteen trường học có thể khuyến khích lối sống ăn uống lành mạnh hơn bằng cách cung cấp các bữa ăn ngon miệng chế biến từ rau củ tươi và ngũ cốc nguyên hạt.","audioKind":"ex2"}],"collocations":[{"en":"tasty meal","vi":"bữa ăn ngon"},{"en":"tasty snack","vi":"món ăn vặt ngon miệng"},{"en":"tasty dish","vi":"món ăn ngon"}],"wordFamily":["taste (n.)","taste (v.)","tasteless (adj.)"],"synonyms":["delicious","flavoursome"],"antonyms":["tasteless","unpalatable"],"tipVi":"tasty chỉ thức ăn ngon; tasteful chỉ có gu thẩm mỹ, có tinh tế.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_stamp', 'en-a2-40', 'stamp', '/stæmp/', 'A2', 'tem bưu chính; con dấu; dấu hiệu; đóng dấu; dậm chân; bước mạnh', 'n.', NULL, NULL, 'Tem thư dùng a stamp; “dán tem lên phong bì” dùng put a stamp on.', 'She put a stamp on the envelope before leaving.', NULL, 'Cô ấy dán một con tem lên phong bì trước khi rời đi.', '{"wordId":"stamp","ukIpa":"/stæmp/","usIpa":"/stæmp/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A small official sticker showing that postage has been paid.","vi":"tem bưu chính"},{"pos":"n.","en":"A tool that presses a mark, or the mark it leaves.","vi":"con dấu; dấu hiệu"},{"pos":"v.","en":"Press a mark onto something, or bring a foot down hard.","vi":"đóng dấu; dậm chân; bước mạnh"}],"examples":[{"en":"She put a stamp on the envelope before leaving.","vi":"Cô ấy dán một con tem lên phong bì trước khi rời đi.","audioKind":"ex"},{"en":"Although digital communication has reduced letter writing, collecting stamps remains a way to explore history and culture.","vi":"Mặc dù giao tiếp kỹ thuật số đã làm giảm việc viết thư, việc sưu tầm tem vẫn là một cách để khám phá lịch sử và văn hóa.","audioKind":"ex2"}],"collocations":[{"en":"postage stamp","vi":"tem bưu chính"},{"en":"collect stamps","vi":"sưu tầm tem"},{"en":"stamp a passport","vi":"đóng dấu hộ chiếu"},{"en":"stamp your feet","vi":"giậm chân"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tem thư dùng a stamp; “dán tem lên phong bì” dùng put a stamp on.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_unfortunately', 'en-a2-40', 'unfortunately', '/ʌnˈfɔːrtʃənətli/', 'A2', 'không may là; đáng tiếc là', 'adv.', 'fortunate (adj.), unfortunate (adj.), fortunately (adv.), fortune (n.)', 'Đồng nghĩa: regrettably, sadly · Trái nghĩa: fortunately', 'Thường đứng đầu câu kèm dấu phẩy, dùng để bày tỏ sự tiếc nuối cho toàn bộ sự việc.', 'Unfortunately, the bakery had sold out of fresh bread.', NULL, 'Đáng tiếc là tiệm bánh đã bán hết sạch bánh mì tươi.', '{"wordId":"unfortunately","ukIpa":"/ʌnˈfɔːtʃənətli/","usIpa":"/ʌnˈfɔːrtʃənətli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"used to say that something is disappointing or unlucky","vi":"không may là; đáng tiếc là"}],"examples":[{"en":"Unfortunately, the bakery had sold out of fresh bread.","vi":"Đáng tiếc là tiệm bánh đã bán hết sạch bánh mì tươi.","audioKind":"ex"},{"en":"Unfortunately, many rural schools lack the resources needed to provide students with reliable internet access.","vi":"Thật đáng tiếc, nhiều trường học vùng nông thôn vẫn thiếu nguồn lực cần thiết để cung cấp cho học sinh kết nối internet ổn định.","audioKind":"ex2"}],"collocations":[{"en":"unfortunately for someone","vi":"đối với ai đó thì thật không may"},{"en":"unfortunately not","vi":"rất tiếc là không"}],"wordFamily":["fortunate (adj.)","unfortunate (adj.)","fortunately (adv.)","fortune (n.)"],"synonyms":["regrettably","sadly"],"antonyms":["fortunately"],"tipVi":"Thường đứng đầu câu kèm dấu phẩy, dùng để bày tỏ sự tiếc nuối cho toàn bộ sự việc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_usual', 'en-a2-40', 'usual', '/ˈjuːʒuəl/', 'A2', 'thường lệ; thông thường; quen thuộc', 'adj.', 'usually (adv.), unusual (adj.), unusually (adv.)', 'Đồng nghĩa: normal, customary · Trái nghĩa: unusual', 'as usual nghĩa là "như thường lệ"; than usual nghĩa là "hơn mọi khi".', 'Our usual table by the window was already taken.', NULL, 'Cái bàn quen thuộc cạnh cửa sổ của chúng tôi đã có người ngồi.', '{"wordId":"usual","ukIpa":"/ˈjuːʒuəl/","usIpa":"/ˈjuːʒuəl/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"happening or done most often in a particular situation","vi":"thường lệ; thông thường; quen thuộc"}],"examples":[{"en":"Our usual table by the window was already taken.","vi":"Cái bàn quen thuộc cạnh cửa sổ của chúng tôi đã có người ngồi.","audioKind":"ex"},{"en":"Working from home has become the usual arrangement for some employees in the technology sector.","vi":"Làm việc tại nhà đã trở thành một thỏa thuận thông thường đối với một số nhân viên trong ngành công nghệ.","audioKind":"ex2"}],"collocations":[{"en":"as usual","vi":"như mọi khi"},{"en":"the usual routine","vi":"thói quen thường nhật"},{"en":"than usual","vi":"hơn bình thường"}],"wordFamily":["usually (adv.)","unusual (adj.)","unusually (adv.)"],"synonyms":["normal","customary"],"antonyms":["unusual"],"tipVi":"as usual nghĩa là \"như thường lệ\"; than usual nghĩa là \"hơn mọi khi\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bottom', 'en-a2-40', 'bottom', '/ˈbɑːtəm/', 'A2', 'đáy; phần thấp nhất; mông; phần cơ thể dùng để ngồi; thấp nhất; ở vị trí dưới cùng', 'n.', 'bottomless (adj.)', 'Trái nghĩa: top', 'Ở vị trí đáy của vật gì dùng at the bottom of.', 'My keys were at the bottom of my bag.', NULL, 'Chìa khóa của tôi nằm ở tận đáy túi.', '{"wordId":"bottom","ukIpa":"/ˈbɒtəm/","usIpa":"/ˈbɑːtəm/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"The lowest part of something.","vi":"đáy; phần thấp nhất"},{"pos":"n.","en":"The part of your body that you sit on.","vi":"mông; phần cơ thể dùng để ngồi"},{"pos":"adj.","en":"In the lowest position.","vi":"thấp nhất; ở vị trí dưới cùng"}],"examples":[{"en":"My keys were at the bottom of my bag.","vi":"Chìa khóa của tôi nằm ở tận đáy túi.","audioKind":"ex"},{"en":"Waste often collects at the bottom of rivers, damaging habitats and threatening aquatic life.","vi":"Rác thải thường tích tụ ở đáy sông, làm tổn hại đến môi trường sống và đe dọa các loài sinh vật dưới nước.","audioKind":"ex2"}],"collocations":[{"en":"at the bottom of","vi":"ở đáy của"},{"en":"bottom shelf","vi":"kệ dưới cùng"},{"en":"from top to bottom","vi":"từ trên xuống dưới"}],"wordFamily":["bottomless (adj.)"],"synonyms":[],"antonyms":["top"],"tipVi":"Ở vị trí đáy của vật gì dùng at the bottom of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_40_1', 'en-a2-40', 'Cách dùng “glue” (n.) — keo, hồ dán', 'glue stick  ·  wood glue  ·  glue together', 'Glue đóng vai trò danh từ thường không đếm được; cụm be glued to có thể dùng để diễn tả việc chăm chú nhìn cái gì.', 'Đồng nghĩa: adhesive', '[{"hanzi":"Use a little glue to fix the paper wing.","pinyin":"","meaning":"Hãy dùng một chút keo để gắn cánh bằng giấy lại."},{"hanzi":"Some packaging contains layers joined with glue, which can make the materials more difficult to recycle.","pinyin":"","meaning":"Một số loại bao bì có các lớp được dán lại với nhau bằng keo, điều này có thể làm cho vật liệu khó tái chế hơn."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_40_2', 'en-a2-40', 'Cách dùng “through” (prep.) — xuyên qua, qua lại bên trong', 'walk through  ·  through experience  ·  read through', 'Through nhấn mạnh việc chuyển động từ bên trong đi ra; across nhấn mạnh việc di chuyển ngang qua bề mặt.', NULL, '[{"hanzi":"Sunlight streamed through the curtains and warmed the room.","pinyin":"","meaning":"Ánh nắng chiếu qua lớp rèm cửa và làm ấm căn phòng."},{"hanzi":"Students can develop practical skills through projects that require cooperation and creative problem solving.","pinyin":"","meaning":"Học sinh có thể phát triển các kỹ năng thực tế thông qua các dự án đòi hỏi tính hợp tác và khả năng giải quyết vấn đề sáng tạo."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_40_3', 'en-a2-40', 'Cách dùng “coloured” (adj.) — có màu sắc; được nhuộm màu', 'coloured glass  ·  coloured pencils  ·  brightly coloured', 'Anh-Anh viết là coloured, Anh-Mỹ viết là colored; tránh dùng để chỉ chung chung các nhóm sắc tộc.', 'Họ từ (Word Family): colour (n.), colour (v.), colourful (adj.), colourless (adj.) | Trái nghĩa: colourless', '[{"hanzi":"Sunlight streamed through the coloured glass onto the floor.","pinyin":"","meaning":"Ánh nắng xuyên qua lớp kính có màu chiếu xuống sàn nhà."},{"hanzi":"Teachers can use coloured blocks to help young children recognise patterns and develop basic mathematical skills.","pinyin":"","meaning":"Giáo viên có thể sử dụng các khối hình nhiều màu sắc để giúp trẻ nhỏ nhận biết các quy luật và phát triển các kỹ năng toán học cơ bản."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_40_4', 'en-a2-40', 'Cách dùng “step” (n.) — bước chân; bậc thang', 'take a step  ·  step by step  ·  take steps to', 'Cấu trúc take steps to do sth có nghĩa là "thích nghi hoặc thực hiện các biện pháp để làm gì đó".', NULL, '[{"hanzi":"Take one step forward and close the door.","pinyin":"","meaning":"Hãy bước lên một bước và đóng cửa lại."},{"hanzi":"Improving public transport is an important step towards reducing traffic congestion and air pollution in cities.","pinyin":"","meaning":"Cải thiện giao thông công cộng là một bước quan trọng để giảm ùn tắc giao thông và ô nhiễm không khí ở các đô thị."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_40_1', 'en-a2-40', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_40_1_1', 'ten_a2_40_1', 'several', 'I tried several jackets before choosing the blue one.', 'I tried several jackets before choosing the blue one.', '/ˈsevrəl/', 'Tôi đã thử vài chiếc áo khoác trước khi chọn chiếc màu xanh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_40_1_2', 'ten_a2_40_1', 'collect', 'I collect smooth stones whenever we visit the beach.', 'I collect smooth stones whenever we visit the beach.', '/kəˈlekt/', 'Tôi nhặt sưu tầm những viên đá nhẵn mỗi khi chúng tôi đến bãi biển.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_40_1_3', 'ten_a2_40_1', 'extra', 'I packed an extra sweater because the evenings get cold.', 'I packed an extra sweater because the evenings get cold.', '/ˈekstrə/', 'Tôi gói thêm một chiếc áo len vì trời tối sẽ lạnh.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_40_1_4', 'ten_a2_40_1', 'guy', 'The guy next door helped carry my groceries.', 'The guy next door helped carry my groceries.', '/ɡaɪ/', 'Anh chàng ở nhà bên cạnh đã giúp tôi xách đồ tạp hóa về.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_40_1_5', 'ten_a2_40_1', 'coloured', 'Sunlight streamed through the coloured glass onto the floor.', 'Sunlight streamed through the coloured glass onto the floor.', '/ˈkʌlərd/', 'Ánh nắng xuyên qua lớp kính có màu chiếu xuống sàn nhà.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_40_1_6', 'ten_a2_40_1', 'gift', 'My sister wrapped the gift in bright yellow paper.', 'My sister wrapped the gift in bright yellow paper.', '/ɡɪft/', 'Em gái tôi gói món quà bằng lớp giấy màu vàng tươi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_40_1_7', 'ten_a2_40_1', 'blouse', 'She wore a blue blouse with her favourite grey trousers.', 'She wore a blue blouse with her favourite grey trousers.', '/blaʊs/', 'Cô ấy mặc một chiếc áo sơ-mi nữ màu xanh lam với chiếc quần dài màu xám yêu thích.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_40_1_8', 'ten_a2_40_1', 'detail', 'Please check every detail before you send the invitation.', 'Please check every detail before you send the invitation.', '/ˈdiːteɪl/', 'Vui lòng kiểm tra từng chi tiết trước khi bạn gửi lời mời.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_40_1_1', 'en-a2-40', 'ten_a2_40_1', 'listening', 'listening', 'I tried several jackets before choosing the blue one.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi đã thử vài chiếc áo khoác trước khi chọn chiếc màu xanh.","Hãy dùng một chút keo để gắn cánh bằng giấy lại.","Quán cà phê nhỏ này phục vụ súp tươi kèm bánh mì ấm.","Tôi đã hâm nóng phần súp hôm qua bằng lò vi sóng để ăn trưa."]'::jsonb, 0, 'I tried several jackets before choosing the blue one. → Tôi đã thử vài chiếc áo khoác trước khi chọn chiếc màu xanh.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_40_1_2', 'en-a2-40', 'ten_a2_40_1', 'listening', 'listening', 'I collect smooth stones whenever we visit the beach.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi nhặt sưu tầm những viên đá nhẵn mỗi khi chúng tôi đến bãi biển.","Cái bàn quen thuộc cạnh cửa sổ của chúng tôi đã có người ngồi.","Tôi đã gọi một phần cơm gấp đôi cho bữa trưa.","Vui lòng kiểm tra từng chi tiết trước khi bạn gửi lời mời."]'::jsonb, 0, 'I collect smooth stones whenever we visit the beach. → Tôi nhặt sưu tầm những viên đá nhẵn mỗi khi chúng tôi đến bãi biển.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_40_1_3', 'en-a2-40', 'ten_a2_40_1', 'listening', 'listening', 'I packed an extra sweater because the evenings get cold.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Em gái tôi gói món quà bằng lớp giấy màu vàng tươi.","Tôi gói thêm một chiếc áo len vì trời tối sẽ lạnh.","Vui lòng kiểm tra từng chi tiết trước khi bạn gửi lời mời.","Quán cà phê nhỏ này phục vụ súp tươi kèm bánh mì ấm."]'::jsonb, 1, 'I packed an extra sweater because the evenings get cold. → Tôi gói thêm một chiếc áo len vì trời tối sẽ lạnh.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_40_2', 'en-a2-40', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_40_2_1', 'ten_a2_40_2', 'several', 'Several studies suggest that access to green spaces can improve mental health among people living in cities.', 'Several studies suggest that access to green spaces can improve mental health among people living in cities.', '/ˈsevrəl/', 'Một số nghiên cứu cho thấy việc tiếp cận không gian xanh có thể cải thiện sức khỏe tinh thần của những người sống ở các thành phố.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_40_2_2', 'ten_a2_40_2', 'collect', 'Researchers collect data from local households to assess how transport policies affect daily travel habits.', 'Researchers collect data from local households to assess how transport policies affect daily travel habits.', '/kəˈlekt/', 'Các nhà nghiên cứu thu thập dữ liệu từ các hộ gia đình địa phương để đánh giá chính sách giao thông tác động thế nào đến thói quen đi lại hằng ngày.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_40_2_3', 'ten_a2_40_2', 'extra', 'Schools should provide extra support for students who struggle to access learning materials at home.', 'Schools should provide extra support for students who struggle to access learning materials at home.', '/ˈekstrə/', 'Nhà trường nên hỗ trợ thêm cho những học sinh gặp khó khăn trong việc tiếp cận tài liệu học tập tại nhà.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_40_2_4', 'ten_a2_40_2', 'guy', 'Calling a colleague a guy may sound friendly, but informal vocabulary is usually inappropriate in academic writing.', 'Calling a colleague a guy may sound friendly, but informal vocabulary is usually inappropriate in academic writing.', '/ɡaɪ/', 'Gọi đồng nghiệp là guy có thể nghe có vẻ thân thiện, nhưng từ vựng mang tính suồng sã thường không phù hợp trong văn viết học thuật.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_40_2_5', 'ten_a2_40_2', 'coloured', 'Teachers can use coloured blocks to help young children recognise patterns and develop basic mathematical skills.', 'Teachers can use coloured blocks to help young children recognise patterns and develop basic mathematical skills.', '/ˈkʌlərd/', 'Giáo viên có thể sử dụng các khối hình nhiều màu sắc để giúp trẻ nhỏ nhận biết các quy luật và phát triển các kỹ năng toán học cơ bản.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_40_2_6', 'ten_a2_40_2', 'gift', 'Schools should nurture each child''s gift rather than judge everyone by the same narrow standards.', 'Schools should nurture each child''s gift rather than judge everyone by the same narrow standards.', '/ɡɪft/', 'Nhà trường nên bồi dưỡng năng khiếu của mỗi đứa trẻ thay vì đánh giá tất cả mọi người bằng cùng một tiêu chuẩn rập khuôn.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_40_2_1', 'en-a2-40', 'ten_a2_40_2', 'listening', 'listening', 'Several studies suggest that access to green spaces can improve mental health among people living in cities.', NULL, 'Trong câu vừa nghe, từ “several” mang nghĩa nào sau đây?', '["hình tròn; vòng tròn","bước chân; bậc thang","chủ động đề nghị; đề ra","vài; một vài (hơn hai nhưng không nhiều)"]'::jsonb, 3, '“several” (/ˈsevrəl/): vài; một vài (hơn hai nhưng không nhiều). Câu đầy đủ: Several studies suggest that access to green spaces can improve mental health among people living in cities.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_40_2_2', 'en-a2-40', 'ten_a2_40_2', 'listening', 'listening', 'Researchers collect data from local households to assess how transport policies affect daily travel habits.', NULL, 'Trong câu vừa nghe, từ “collect” mang nghĩa nào sau đây?', '["cho mượn; cho vay","nghịch ngợm; hư đốn; không vâng lời","thu thập; sưu tầm","theo như; dựa theo"]'::jsonb, 2, '“collect” (/kəˈlekt/): thu thập; sưu tầm. Câu đầy đủ: Researchers collect data from local households to assess how transport policies affect daily travel habits.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
