INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_40_1', 'en-a2-40', NULL, 'comprehensive_test', 'listening', 'several', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["tổ chức; cơ quan; đoàn thể","hướng đông nam; miền đông nam","Xốt-lân; Xéc-lân (Xơ-cốt-len)","vài; một vài (hơn hai nhưng không nhiều)"]'::jsonb, 3, 'several (/ˈsevrəl/) → vài; một vài (hơn hai nhưng không nhiều); vài người; một số vật (đã được đề cập hoặc ngầm hiểu)', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_40_2', 'en-a2-40', NULL, 'comprehensive_test', 'listening', 'I collect smooth stones whenever we visit the beach.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi nhặt sưu tầm những viên đá nhẵn mỗi khi chúng tôi đến bãi biển.","Em gái tôi gói món quà bằng lớp giấy màu vàng tươi.","Chúng tôi đã gặp khó khăn khi mở cánh cửa sổ nhà bếp bị kẹt cứng.","Cô ấy đã bỏ vài quả nho vào hộp cơm trưa của tôi."]'::jsonb, 0, 'I collect smooth stones whenever we visit the beach. → Tôi nhặt sưu tầm những viên đá nhẵn mỗi khi chúng tôi đến bãi biển.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_40_3', 'en-a2-40', NULL, 'comprehensive_test', 'listening', 'extra', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cửa hàng; tiệm","thêm; phụ","hóa đơn","những chiếc lá (dạng số nhiều của leaf)"]'::jsonb, 1, 'extra (/ˈekstrə/) → thêm; phụ; hơn bình thường; phần thêm; diễn viên quần chúng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_40_4', 'en-a2-40', NULL, 'comprehensive_test', 'listening', 'The guy next door helped carry my groceries.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Anh chàng ở nhà bên cạnh đã giúp tôi xách đồ tạp hóa về.","Chúng tôi ngồi trên thảm và chơi bài.","Tôi gói thêm một chiếc áo len vì trời tối sẽ lạnh.","Cô ấy đã bỏ vài quả nho vào hộp cơm trưa của tôi."]'::jsonb, 0, 'The guy next door helped carry my groceries. → Anh chàng ở nhà bên cạnh đã giúp tôi xách đồ tạp hóa về.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_40_5', 'en-a2-40', NULL, 'comprehensive_test', 'listening', 'coloured', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["trang chủ (của một trang web)","có màu sắc; được nhuộm màu","thuộc về điện; chạy bằng điện","nhà hát; rạp hát"]'::jsonb, 1, 'coloured (/ˈkʌlərd/) → có màu sắc; được nhuộm màu', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_40_6', 'en-a2-40', NULL, 'comprehensive_test', 'listening', 'My sister wrapped the gift in bright yellow paper.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đáng tiếc là tiệm bánh đã bán hết sạch bánh mì tươi.","Món súp ngon lành này rất hoàn hảo cho một buổi tối lạnh giá.","Món súp này cần ít muối nhất trong tất cả.","Em gái tôi gói món quà bằng lớp giấy màu vàng tươi."]'::jsonb, 3, 'My sister wrapped the gift in bright yellow paper. → Em gái tôi gói món quà bằng lớp giấy màu vàng tươi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
