INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_40_18', 'en-a2-40', NULL, 'comprehensive_test', 'reading', NULL, 'Several studies suggest that access to green spaces can improve mental health among people living in cities.', 'Dựa vào câu trên, từ “several” có nghĩa phù hợp nhất là gì?', '["sân chơi; sân trường","vài; một vài (hơn hai nhưng không nhiều)","sân; khu đất quanh nhà (thường có rào chắn)","quả lê"]'::jsonb, 1, 'several: vài; một vài (hơn hai nhưng không nhiều); vài người; một số vật (đã được đề cập hoặc ngầm hiểu). Dịch cả câu: Một số nghiên cứu cho thấy việc tiếp cận không gian xanh có thể cải thiện sức khỏe tinh thần của những người sống ở các thành phố.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_40_19', 'en-a2-40', NULL, 'comprehensive_test', 'reading', NULL, 'Researchers collect data from local households to assess how transport policies affect daily travel habits.', 'Dựa vào câu trên, từ “collect” có nghĩa phù hợp nhất là gì?', '["thu thập; sưu tầm","chuẩn bị; làm cho ai hoặc cái gì sẵn sàng cho một hoạt động hoặc tình huống","phần kết; đoạn kết; cái kết","mái nhà; nóc (xe)"]'::jsonb, 0, 'collect: thu thập; sưu tầm; đến đón; nhận; quyên góp; thu tiền. Dịch cả câu: Các nhà nghiên cứu thu thập dữ liệu từ các hộ gia đình địa phương để đánh giá chính sách giao thông tác động thế nào đến thói quen đi lại hằng ngày.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_40_20', 'en-a2-40', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should provide extra support for students who struggle to access learning materials at home.', 'Dựa vào câu trên, từ “extra” có nghĩa phù hợp nhất là gì?', '["cao su","chương trình máy tính","thêm; phụ","tăng lên; dâng lên; lên cao"]'::jsonb, 2, 'extra: thêm; phụ; hơn bình thường; phần thêm; diễn viên quần chúng. Dịch cả câu: Nhà trường nên hỗ trợ thêm cho những học sinh gặp khó khăn trong việc tiếp cận tài liệu học tập tại nhà.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_40_21', 'en-a2-40', NULL, 'comprehensive_test', 'reading', NULL, 'Calling a colleague a guy may sound friendly, but informal vocabulary is usually inappropriate in academic writing.', 'Dựa vào câu trên, từ “guy” có nghĩa phù hợp nhất là gì?', '["sự đào tạo; quá trình huấn luyện","con ong","chàng trai; anh chàng","một chút; một lượng nhỏ; một miếng nhỏ"]'::jsonb, 2, 'guy: chàng trai; anh chàng. Dịch cả câu: Gọi đồng nghiệp là guy có thể nghe có vẻ thân thiện, nhưng từ vựng mang tính suồng sã thường không phù hợp trong văn viết học thuật.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_40_22', 'en-a2-40', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “không may là; đáng tiếc là”', '["unfortunately","properly","sir","armchair"]'::jsonb, 0, 'không may là; đáng tiếc là → unfortunately (/ʌnˈfɔːrtʃənətli/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_40_23', 'en-a2-40', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thường lệ; thông thường; quen thuộc”', '["journey","lamp","usual","slice"]'::jsonb, 2, 'thường lệ; thông thường; quen thuộc → usual (/ˈjuːʒuəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_40_24', 'en-a2-40', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “đáy; phần thấp nhất”', '["impossible","pronunciation","bottom","clothing"]'::jsonb, 2, 'đáy; phần thấp nhất → bottom (/ˈbɑːtəm/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-41', 'en', 'Bài 41: Đời sống hằng ngày (13) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '26 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2041, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_noon', 'en-a2-41', 'noon', '/nuːn/', 'A2', 'trưa; chính ngọ', 'n.', NULL, 'Đồng nghĩa: midday · Trái nghĩa: midnight', 'Dùng at noon, không dùng in noon; chính ngọ là 12 giờ trưa (12 p.m.).', 'Let''s meet outside the library at noon tomorrow.', NULL, 'Hãy gặp nhau ở bên ngoài thư viện vào trưa mai nhé.', '{"wordId":"noon","ukIpa":"/nuːn/","usIpa":"/nuːn/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Twelve o''clock in the middle of the day.","vi":"trưa; chính ngọ"}],"examples":[{"en":"Let''s meet outside the library at noon tomorrow.","vi":"Hãy gặp nhau ở bên ngoài thư viện vào trưa mai nhé.","audioKind":"ex"},{"en":"Outdoor workers should avoid intense physical activity around noon, when temperatures and sunlight can be particularly strong.","vi":"Những người làm việc ngoài trời nên tránh các hoạt động thể chất nặng vào khoảng giữa trưa, khi nhiệt độ và ánh nắng có thể cực kỳ gay gắt.","audioKind":"ex2"}],"collocations":[{"en":"at noon","vi":"vào lúc trưa"},{"en":"around noon","vi":"vào khoảng trưa"},{"en":"by noon","vi":"trước buổi trưa"}],"wordFamily":[],"synonyms":["midday"],"antonyms":["midnight"],"tipVi":"Dùng at noon, không dùng in noon; chính ngọ là 12 giờ trưa (12 p.m.).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wallet', 'en-a2-41', 'wallet', '/ˈwɑːlɪt/', 'A2', 'ví tiền; bóp tiền', 'n.', NULL, NULL, 'wallet thường dùng để chỉ ví gập đựng tiền giấy và các loại thẻ.', 'I left my wallet beside the kitchen sink.', NULL, 'Tôi để quên ví ở ngay cạnh bồn rửa trong bếp.', '{"wordId":"wallet","ukIpa":"/ˈwɒlɪt/","usIpa":"/ˈwɑːlɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A small folding case for carrying money and cards.","vi":"ví tiền; bóp tiền"}],"examples":[{"en":"I left my wallet beside the kitchen sink.","vi":"Tôi để quên ví ở ngay cạnh bồn rửa trong bếp.","audioKind":"ex"},{"en":"As digital payments become more common, fewer consumers need to carry cash in a wallet.","vi":"Khi thanh toán kỹ thuật số ngày càng trở nên phổ biến, ít người tiêu dùng cần mang theo tiền mặt trong ví hơn.","audioKind":"ex2"}],"collocations":[{"en":"leather wallet","vi":"ví da"},{"en":"digital wallet","vi":"ví điện tử"},{"en":"lost wallet","vi":"ví bị mất"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"wallet thường dùng để chỉ ví gập đựng tiền giấy và các loại thẻ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_oven', 'en-a2-41', 'oven', '/ˈʌvən/', 'A2', 'lò nướng; lò vi sóng', 'n.', NULL, NULL, 'oven chỉ lò nướng dạng khoang kín; thiết bị bếp nấu bên trên thường gọi là hob hoặc stove.', 'The bread is still warm from the oven.', NULL, 'Ổ bánh mì vừa mới ra lò nên vẫn còn rất ấm.', '{"wordId":"oven","ukIpa":"/ˈʌvən/","usIpa":"/ˈʌvən/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"an enclosed appliance used to bake or roast food","vi":"lò nướng; lò vi sóng"}],"examples":[{"en":"The bread is still warm from the oven.","vi":"Ổ bánh mì vừa mới ra lò nên vẫn còn rất ấm.","audioKind":"ex"},{"en":"Using an energy-efficient oven can reduce household electricity consumption without changing cooking habits significantly.","vi":"Sử dụng lò nướng tiết kiệm năng lượng có thể làm giảm lượng điện tiêu thụ trong gia đình mà không cần thay đổi đáng kể thói quen nấu nướng.","audioKind":"ex2"}],"collocations":[{"en":"preheat the oven","vi":"làm nóng lò trước"},{"en":"bake in the oven","vi":"nướng trong lò"},{"en":"oven temperature","vi":"nhiệt độ lò nướng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"oven chỉ lò nướng dạng khoang kín; thiết bị bếp nấu bên trên thường gọi là hob hoặc stove.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_worst', 'en-a2-41', 'worst', '/wɝːst/', 'A2', 'tệ nhất; tồi tệ nhất; một cách tệ hại nhất; nghiêm trọng nhất; tình huống xấu nhất; điều tồi tệ nhất', 'adj.', 'bad (adj.), badly (adv.), worse (adj.)', 'Trái nghĩa: best', 'worst là dạng so sánh bậc nhất của bad và badly; dạng so sánh hơn là worse.', 'That was the worst meal I have ever cooked.', NULL, 'Đó là bữa ăn tồi tệ nhất mà tôi từng nấu.', '{"wordId":"worst","ukIpa":"/wɜːst/","usIpa":"/wɝːst/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Worse than all others in quality, condition, or effect.","vi":"tệ nhất; tồi tệ nhất"},{"pos":"adv.","en":"More badly or severely than anyone or anything else.","vi":"một cách tệ hại nhất; nghiêm trọng nhất"},{"pos":"n.","en":"The most unpleasant situation, outcome, or part.","vi":"tình huống xấu nhất; điều tồi tệ nhất"}],"examples":[{"en":"That was the worst meal I have ever cooked.","vi":"Đó là bữa ăn tồi tệ nhất mà tôi từng nấu.","audioKind":"ex"},{"en":"The worst effects of air pollution are often experienced by children and older people in densely populated cities.","vi":"Tác động tồi tệ nhất của ô nhiễm không khí thường đổ lên đầu trẻ em và người cao tuổi ở những thành phố đông dân cư.","audioKind":"ex2"}],"collocations":[{"en":"the worst possible outcome","vi":"kết quả tồi tệ nhất có thể"},{"en":"at worst","vi":"tệ nhất là; ở mức kém nhất"},{"en":"prepare for the worst","vi":"chuẩn bị cho tình huống xấu nhất"},{"en":"worst affected","vi":"chịu ảnh hưởng nặng nề nhất"}],"wordFamily":["bad (adj.)","badly (adv.)","worse (adj.)"],"synonyms":[],"antonyms":["best"],"tipVi":"worst là dạng so sánh bậc nhất của bad và badly; dạng so sánh hơn là worse.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_quietly', 'en-a2-41', 'quietly', '/ˈkwaɪətli/', 'A2', 'một cách yên tĩnh; khẽ khàng; lặng lẽ; không phô trương', 'adv.', 'quiet (adj.), quietness (n.), quieten (v.)', 'Đồng nghĩa: softly · Trái nghĩa: loudly, noisily', 'quietly là phó từ; hãy chú ý tránh nhầm lẫn với từ quite (khá).', 'Please close the door quietly; the baby is sleeping.', NULL, 'Làm ơn khép cửa nhẹ nhàng thôi, em bé đang ngủ đấy.', '{"wordId":"quietly","ukIpa":"/ˈkwaɪətli/","usIpa":"/ˈkwaɪətli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"with little or no noise","vi":"một cách yên tĩnh; khẽ khàng"},{"pos":"adv.","en":"without attracting attention or making something widely known","vi":"lặng lẽ; không phô trương"}],"examples":[{"en":"Please close the door quietly; the baby is sleeping.","vi":"Làm ơn khép cửa nhẹ nhàng thôi, em bé đang ngủ đấy.","audioKind":"ex"},{"en":"Students who work quietly in shared study areas help create an environment that supports concentration.","vi":"Những học sinh chăm chỉ học tập một cách lặng lẽ ở các khu vực học tập chung góp phần tạo nên một môi trường đề cao sự tập trung.","audioKind":"ex2"}],"collocations":[{"en":"speak quietly","vi":"nói khẽ"},{"en":"sit quietly","vi":"ngồi yên lặng"},{"en":"quietly confident","vi":"tự tin một cách lặng lẽ"}],"wordFamily":["quiet (adj.)","quietness (n.)","quieten (v.)"],"synonyms":["softly"],"antonyms":["loudly","noisily"],"tipVi":"quietly là phó từ; hãy chú ý tránh nhầm lẫn với từ quite (khá).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_cute', 'en-a2-41', 'cute', '/kjuːt/', 'A2', 'dễ thương; đáng yêu', 'adj.', 'cuteness (n.), cutely (adv.)', 'Đồng nghĩa: adorable, sweet', 'Mang sắc thái thân mật, thường dùng trong văn phong hàng ngày để tả trẻ em, động vật hoặc vẻ bề ngoài đáng yêu.', 'That cute kitten is sleeping inside my slipper.', NULL, 'Chú mèo con dễ thương ấy đang ngủ cuộn tròn bên trong chiếc dép của tôi.', '{"wordId":"cute","ukIpa":"/kjuːt/","usIpa":"/kjuːt/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Attractive in a sweet or charming way.","vi":"dễ thương; đáng yêu"}],"examples":[{"en":"That cute kitten is sleeping inside my slipper.","vi":"Chú mèo con dễ thương ấy đang ngủ cuộn tròn bên trong chiếc dép của tôi.","audioKind":"ex"},{"en":"Advertisements often feature cute animals to attract attention and create positive feelings towards a product.","vi":"Các quảng cáo thường sử dụng hình ảnh động vật dễ thương để thu hút sự chú ý và tạo cảm tình tốt đẹp đối với sản phẩm.","audioKind":"ex2"}],"collocations":[{"en":"a cute baby","vi":"một em bé dễ thương"},{"en":"a cute smile","vi":"nụ cười dễ thương"},{"en":"look cute","vi":"trông đáng yêu"}],"wordFamily":["cuteness (n.)","cutely (adv.)"],"synonyms":["adorable","sweet"],"antonyms":[],"tipVi":"Mang sắc thái thân mật, thường dùng trong văn phong hàng ngày để tả trẻ em, động vật hoặc vẻ bề ngoài đáng yêu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_bill', 'en-a2-41', 'bill', '/bɪl/', 'A2', 'hóa đơn; dự luật; tiền giấy', 'n.', 'billing (n.)', NULL, 'Bill là dự luật đang được xem xét; sau khi thông qua và có hiệu lực thì trở thành luật.', 'We asked for the bill after finishing our lunch.', NULL, 'Chúng tôi đã gọi thanh toán hóa đơn sau khi ăn trưa xong.', '{"wordId":"bill","ukIpa":"/bɪl/","usIpa":"/bɪl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a written statement of money owed for goods or services","vi":"hóa đơn"},{"pos":"n.","en":"a proposed law being considered by a lawmaking body","vi":"dự luật"},{"pos":"n.","en":"a piece of paper money, especially in American English","vi":"tiền giấy"}],"examples":[{"en":"We asked for the bill after finishing our lunch.","vi":"Chúng tôi đã gọi thanh toán hóa đơn sau khi ăn trưa xong.","audioKind":"ex"},{"en":"The proposed bill would require companies to disclose more information about their impact on the environment.","vi":"Dự luật được đề xuất sẽ yêu cầu các công ty công bố nhiều thông tin hơn về tác động của họ đối với môi trường.","audioKind":"ex2"}],"collocations":[{"en":"pay a bill","vi":"thanh toán hóa đơn"},{"en":"electricity bill","vi":"hóa đơn tiền điện"},{"en":"pass a bill","vi":"thông qua dự luật"},{"en":"a dollar bill","vi":"một tờ đô-la"}],"wordFamily":["billing (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Bill là dự luật đang được xem xét; sau khi thông qua và có hiệu lực thì trở thành luật.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_should', 'en-a2-41', 'should', '/ʃʊd/', 'A2', 'nên; phải; lẽ ra; có lẽ; lẽ ra nên', 'v.', NULL, NULL, 'Động từ khuyết thiếu, theo sau là động từ nguyên thể; should have done thường chỉ việc lẽ ra nên làm nhưng đã không làm.', 'You should take an umbrella because it looks cloudy.', NULL, 'Bạn nên mang theo ô vì trời có vẻ âm u.', '{"wordId":"should","ukIpa":"/ʃʊd/","usIpa":"/ʃʊd/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"used to give advice or say what is right","vi":"nên; phải"},{"pos":"v.","en":"used to say something is expected or likely","vi":"lẽ ra; có lẽ"},{"pos":"v.","en":"used with have to describe an unfulfilled duty or expectation","vi":"lẽ ra nên"}],"examples":[{"en":"You should take an umbrella because it looks cloudy.","vi":"Bạn nên mang theo ô vì trời có vẻ âm u.","audioKind":"ex"},{"en":"Governments should invest in affordable public transport to reduce congestion and improve urban air quality.","vi":"Chính phủ nên đầu tư vào hệ thống giao thông công cộng giá cả phải chăng để giảm tình trạng tắc nghẽn và cải thiện chất lượng không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"should do something","vi":"nên làm điều gì đó"},{"en":"should have done","vi":"lẽ ra nên làm"},{"en":"should be able to","vi":"nên có khả năng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Động từ khuyết thiếu, theo sau là động từ nguyên thể; should have done thường chỉ việc lẽ ra nên làm nhưng đã không làm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_perfect', 'en-a2-41', 'perfect', '/ˈpɝːfɪkt/', 'A2', 'hoàn hảo; lý tưởng; làm cho hoàn thiện; trau dồi; thì hoàn thành', 'adj.', 'perfection (n.), perfectly (adv.), imperfect (adj.), perfectionist (n.)', 'Đồng nghĩa: flawless, ideal · Trái nghĩa: imperfect, flawed', 'Tính từ nhấn trọng âm ở âm tiết đầu; động từ đọc là /pəˈfekt/ (tiếng Anh-Anh).', 'This quiet corner is perfect for reading after lunch.', NULL, 'Góc nhỏ yên tĩnh này cực kỳ thích hợp để đọc sách sau bữa trưa.', '{"wordId":"perfect","ukIpa":"/ˈpɜːfɪkt/","usIpa":"/ˈpɝːfɪkt/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"without faults, or exactly right for a particular purpose","vi":"hoàn hảo; lý tưởng"},{"pos":"v.","en":"to improve something until it is as good as possible","vi":"làm cho hoàn thiện; trau dồi"},{"pos":"adj.","en":"describing verb forms using have with a past participle","vi":"thì hoàn thành"}],"examples":[{"en":"This quiet corner is perfect for reading after lunch.","vi":"Góc nhỏ yên tĩnh này cực kỳ thích hợp để đọc sách sau bữa trưa.","audioKind":"ex"},{"en":"Although no transport system is perfect, reliable public services can significantly reduce a city''s dependence on cars.","vi":"Mặc dù không có hệ thống giao thông nào hoàn hảo, các dịch vụ công cộng đáng tin cậy vẫn có thể làm giảm đáng kể sự phụ thuộc của thành phố vào ô tô.","audioKind":"ex2"}],"collocations":[{"en":"perfect timing","vi":"thời điểm hoàn hảo"},{"en":"perfect for","vi":"hoàn hảo cho"},{"en":"perfect a technique","vi":"hoàn thiện một kỹ thuật"},{"en":"present perfect","vi":"thì hiện tại hoàn thành"}],"wordFamily":["perfection (n.)","perfectly (adv.)","imperfect (adj.)","perfectionist (n.)"],"synonyms":["flawless","ideal"],"antonyms":["imperfect","flawed"],"tipVi":"Tính từ nhấn trọng âm ở âm tiết đầu; động từ đọc là /pəˈfekt/ (tiếng Anh-Anh).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_weekly', 'en-a2-41', 'weekly', '/ˈwiːkli/', 'A2', 'hàng tuần, diễn ra mỗi tuần; mỗi tuần một lần; tạp chí hàng tuần, báo ra hàng tuần', 'adj.', 'week (n.)', NULL, 'Từ này có thể dùng làm cả tính từ lẫn trạng từ: a weekly meeting; meet weekly.', 'Our weekly shopping trip usually ends at the bakery.', NULL, 'Chuyến đi mua sắm hàng tuần của chúng tôi thường kết thúc ở tiệm bánh.', '{"wordId":"weekly","ukIpa":"/ˈwiːkli/","usIpa":"/ˈwiːkli/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Happening once a week or relating to one week","vi":"hàng tuần, diễn ra mỗi tuần"},{"pos":"adv.","en":"Once every week","vi":"mỗi tuần một lần"},{"pos":"n.","en":"A newspaper or magazine published once a week","vi":"tạp chí hàng tuần, báo ra hàng tuần"}],"examples":[{"en":"Our weekly shopping trip usually ends at the bakery.","vi":"Chuyến đi mua sắm hàng tuần của chúng tôi thường kết thúc ở tiệm bánh.","audioKind":"ex"},{"en":"Weekly exercise classes at community centres can help older residents stay active and build social connections.","vi":"Các lớp tập thể dục hàng tuần tại các trung tâm cộng đồng có thể giúp cư dân cao tuổi duy trì sự năng động và xây dựng các mối quan hệ xã hội.","audioKind":"ex2"}],"collocations":[{"en":"a weekly meeting","vi":"cuộc họp hàng tuần"},{"en":"weekly earnings","vi":"thu nhập hàng tuần"},{"en":"published weekly","vi":"xuất bản hàng tuần"}],"wordFamily":["week (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ này có thể dùng làm cả tính từ lẫn trạng từ: a weekly meeting; meet weekly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_curtain', 'en-a2-41', 'curtain', '/ˈkɜːrtən/', 'A2', 'rèm cửa, màn che; tấm màn sân khấu', 'n.', NULL, NULL, 'Cụm draw the curtains có thể mang nghĩa kéo ra hoặc kéo vào tùy thuộc vào ngữ cảnh cụ thể.', 'She pulled the curtain aside to watch the rain.', NULL, 'Cô ấy kéo rèm sang một bên để ngắm trời mưa.', '{"wordId":"curtain","ukIpa":"/ˈkɜːtən/","usIpa":"/ˈkɜːrtən/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"hanging fabric used to cover a window or divide space","vi":"rèm cửa, màn che"},{"pos":"n.","en":"a large hanging cloth that hides or reveals a stage","vi":"tấm màn sân khấu"}],"examples":[{"en":"She pulled the curtain aside to watch the rain.","vi":"Cô ấy kéo rèm sang một bên để ngắm trời mưa.","audioKind":"ex"},{"en":"Installing a thick curtain over each window can reduce heat loss and improve comfort in older homes.","vi":"Việc lắp đặt một lớp rèm dày ở mỗi ô cửa sổ có thể làm giảm thất thoát nhiệt và cải thiện sự thoải mái ở các ngôi nhà cũ.","audioKind":"ex2"}],"collocations":[{"en":"draw the curtains","vi":"kéo rèm (đóng hoặc mở)"},{"en":"shower curtain","vi":"rèm phòng tắm"},{"en":"stage curtain","vi":"màn sân khấu"},{"en":"curtain rail","vi":"thanh treo rèm"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cụm draw the curtains có thể mang nghĩa kéo ra hoặc kéo vào tùy thuộc vào ngữ cảnh cụ thể.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pull', 'en-a2-41', 'pull', '/pʊl/', 'A2', 'kéo, lôi, giật; sự kéo, lực kéo; làm căng cơ, kéo căng cơ', 'v.', 'puller (n.)', 'Đồng nghĩa: tug, drag · Trái nghĩa: push', 'pull là hướng về phía bản thân; push là đẩy ra xa.', 'Please pull the door gently instead of pushing it.', NULL, 'Xin hãy nhẹ nhàng kéo cửa thay vì đẩy.', '{"wordId":"pull","ukIpa":"/pʊl/","usIpa":"/pʊl/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to move something towards you or along by holding it","vi":"kéo, lôi, giật"},{"pos":"n.","en":"an act of pulling or a force drawing something closer","vi":"sự kéo, lực kéo"},{"pos":"v.","en":"to injure a muscle by stretching it too much","vi":"làm căng cơ, kéo căng cơ"}],"examples":[{"en":"Please pull the door gently instead of pushing it.","vi":"Xin hãy nhẹ nhàng kéo cửa thay vì đẩy.","audioKind":"ex"},{"en":"Horses once pulled heavy loads through cities, but motor vehicles eventually replaced them in most transport roles.","vi":"Ngựa từng kéo các vật nặng qua các thành phố, nhưng xe cơ giới cuối cùng đã thay thế chúng trong hầu hết các vai trò vận tải.","audioKind":"ex2"}],"collocations":[{"en":"pull a muscle","vi":"kéo căng cơ"},{"en":"pull a door open","vi":"kéo mở cửa"},{"en":"pull out a tooth","vi":"nhổ một chiếc răng"},{"en":"gravitational pull","vi":"lực hút hấp dẫn"}],"wordFamily":["puller (n.)"],"synonyms":["tug","drag"],"antonyms":["push"],"tipVi":"pull là hướng về phía bản thân; push là đẩy ra xa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_toward', 'en-a2-41', 'toward', '/tɔːrd/', 'A2', 'về phía, hướng về; đối với, về thái độ hoặc hành vi; để đóng góp, nhằm đạt được', 'prep.', NULL, 'Đồng nghĩa: towards · Trái nghĩa: away from', 'toward và towards là từ đồng nghĩa; toward được dùng phổ biến hơn trong tiếng Anh-Mỹ.', 'The puppy ran toward me with a muddy ball.', NULL, 'Chú chó con ngậm một quả bóng dính bùn chạy về phía tôi.', '{"wordId":"toward","ukIpa":"/təˈwɔːd/","usIpa":"/tɔːrd/","cefr":"A2","topic":"daily","senses":[{"pos":"prep.","en":"In the direction of someone or something","vi":"về phía, hướng về"},{"pos":"prep.","en":"In relation to someone or something, especially attitudes or behaviour","vi":"đối với, về thái độ hoặc hành vi"},{"pos":"prep.","en":"Helping to achieve or pay for something","vi":"để đóng góp, nhằm đạt được"}],"examples":[{"en":"The puppy ran toward me with a muddy ball.","vi":"Chú chó con ngậm một quả bóng dính bùn chạy về phía tôi.","audioKind":"ex"},{"en":"Investment in public transport is an important step toward reducing traffic congestion and improving urban air quality.","vi":"Đầu tư vào giao thông công cộng là một bước tiến quan trọng trong việc giảm thiểu ùn tắc giao thông và cải thiện chất lượng không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"move toward","vi":"di chuyển về phía"},{"en":"attitudes toward","vi":"thái độ đối với"},{"en":"a step toward","vi":"một bước tiến tới"},{"en":"go toward the cost","vi":"dùng vào chi phí"}],"wordFamily":[],"synonyms":["towards"],"antonyms":["away from"],"tipVi":"toward và towards là từ đồng nghĩa; toward được dùng phổ biến hơn trong tiếng Anh-Mỹ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shall', 'en-a2-41', 'shall', '/ʃæl/', 'A2', 'dùng với I hoặc we để đề nghị hoặc gợi ý điều gì đó; dùng với I hoặc we để diễn đạt dự định trong tương lai một cách trang trọng; dùng trong các quy định trang trọng để nêu rõ yêu cầu bắt buộc', 'v.', NULL, NULL, 'Là động từ khuyết thiếu, theo sau là động từ nguyên mẫu; Shall we thường dùng để đưa ra lời đề nghị.', 'Shall we take a short walk after dinner?', NULL, 'Chúng ta đi dạo một lát sau bữa tối nhé?', '{"wordId":"shall","ukIpa":"/ʃæl/","usIpa":"/ʃæl/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"Used with I or we to offer or suggest something.","vi":"dùng với I hoặc we để đề nghị hoặc gợi ý điều gì đó"},{"pos":"v.","en":"Used with I or we to express future intentions formally.","vi":"dùng với I hoặc we để diễn đạt dự định trong tương lai một cách trang trọng"},{"pos":"v.","en":"Used in formal rules to state a requirement.","vi":"dùng trong các quy định trang trọng để nêu rõ yêu cầu bắt buộc"}],"examples":[{"en":"Shall we take a short walk after dinner?","vi":"Chúng ta đi dạo một lát sau bữa tối nhé?","audioKind":"ex"},{"en":"Under the proposed regulations, employers shall provide appropriate safety equipment for all workers handling hazardous materials.","vi":"Theo các quy định đề xuất, người sử dụng lao động phải cung cấp thiết bị an toàn phù hợp cho tất cả công nhân tiếp xúc với vật liệu nguy hiểm.","audioKind":"ex2"}],"collocations":[{"en":"shall we","vi":"chúng ta có nên"},{"en":"shall I","vi":"tôi có nên..."},{"en":"shall not","vi":"không được; không được phép"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là động từ khuyết thiếu, theo sau là động từ nguyên mẫu; Shall we thường dùng để đưa ra lời đề nghị.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_basket', 'en-a2-41', 'basket', '/ˈbæskɪt/', 'A2', 'cái giỏ; cái sọt; rổ bóng rổ; điểm ghi được từ cú ném bóng vào rổ', 'n.', NULL, NULL, 'a basket of apples chỉ một giỏ táo; số lượng giỏ dùng từ baskets.', 'I carried a basket of fresh apples into the kitchen.', NULL, 'Tôi xách một giỏ táo tươi bước vào nhà bếp.', '{"wordId":"basket","ukIpa":"/ˈbɑːskɪt/","usIpa":"/ˈbæskɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A container made from woven strips, wire, or similar materials","vi":"cái giỏ; cái sọt"},{"pos":"n.","en":"The hoop and net in basketball, or a score through it","vi":"rổ bóng rổ; điểm ghi được từ cú ném bóng vào rổ"}],"examples":[{"en":"I carried a basket of fresh apples into the kitchen.","vi":"Tôi xách một giỏ táo tươi bước vào nhà bếp.","audioKind":"ex"},{"en":"Providing reusable shopping baskets can encourage customers to reduce their reliance on disposable plastic bags.","vi":"Việc cung cấp các giỏ mua sắm có thể tái sử dụng có thể khuyến khích khách hàng giảm sự phụ thuộc vào túi nhựa dùng một lần.","audioKind":"ex2"}],"collocations":[{"en":"shopping basket","vi":"giỏ mua sắm"},{"en":"laundry basket","vi":"giỏ đựng đồ giặt"},{"en":"a basket of fruit","vi":"một giỏ trái cây"},{"en":"score a basket","vi":"ghi điểm bóng rổ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"a basket of apples chỉ một giỏ táo; số lượng giỏ dùng từ baskets.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pot', 'en-a2-41', 'pot', '/pɑːt/', 'A2', 'cái nồi; chậu; bình; hũ; ấm; trồng vào chậu', 'n.', NULL, NULL, 'Từ pot dùng chung cho nồi, chậu, bình; còn chảo rán phẳng thường dùng pan.', 'The soup is bubbling gently in a large pot.', NULL, 'Món súp đang sôi lăn tăn trong một cái nồi lớn.', '{"wordId":"pot","ukIpa":"/pɒt/","usIpa":"/pɑːt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A deep container used for cooking food.","vi":"cái nồi; chậu"},{"pos":"n.","en":"A container used for plants, storage, or serving drinks.","vi":"bình; hũ; ấm"},{"pos":"v.","en":"To put a plant into a container with soil.","vi":"trồng vào chậu"}],"examples":[{"en":"The soup is bubbling gently in a large pot.","vi":"Món súp đang sôi lăn tăn trong một cái nồi lớn.","audioKind":"ex"},{"en":"Growing vegetables in pots allows residents with limited outdoor space to produce some of their own food.","vi":"Trồng rau trong chậu giúp cho những cư dân có không gian ngoài trời hạn chế có thể tự sản xuất một phần thực phẩm cho riêng mình.","audioKind":"ex2"}],"collocations":[{"en":"a pot of soup","vi":"một nồi súp"},{"en":"a plant pot","vi":"chậu cây"},{"en":"a pot of tea","vi":"một ấm trà"},{"en":"pot plants","vi":"trồng cây vào chậu"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Từ pot dùng chung cho nồi, chậu, bình; còn chảo rán phẳng thường dùng pan.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_order', 'en-a2-41', 'order', '/ˈɔːrdər/', 'A2', 'trật tự, thứ tự; đặt hàng, gọi món, ra lệnh; đơn hàng, mệnh lệnh', 'n.', 'orderly (adj.), disorder (n.)', NULL, '"In order" có nghĩa là theo thứ tự; cụm "in order to" theo sau bởi động từ dùng để chỉ mục đích.', 'Please put these photos in the correct order.', NULL, 'Xin vui lòng sắp xếp các bức ảnh này theo đúng thứ tự.', '{"wordId":"order","ukIpa":"/ˈɔːdə/","usIpa":"/ˈɔːrdər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"the arrangement of things or a controlled, peaceful situation","vi":"trật tự, thứ tự"},{"pos":"v.","en":"to request goods or food, or tell someone what to do","vi":"đặt hàng, gọi món, ra lệnh"},{"pos":"n.","en":"a request for goods or an instruction that must be obeyed","vi":"đơn hàng, mệnh lệnh"}],"examples":[{"en":"Please put these photos in the correct order.","vi":"Xin vui lòng sắp xếp các bức ảnh này theo đúng thứ tự.","audioKind":"ex"},{"en":"Online shoppers can now order fresh produce directly from local farms, supporting regional economies.","vi":"Người mua sắm trực tuyến giờ đây có thể đặt mua trực tiếp nông sản tươi sống từ các trang trại địa phương, qua đó hỗ trợ nền kinh tế khu vực.","audioKind":"ex2"}],"collocations":[{"en":"in alphabetical order","vi":"theo thứ tự bảng chữ cái"},{"en":"place an order","vi":"đặt hàng"},{"en":"order a meal","vi":"gọi món ăn"},{"en":"order someone to do something","vi":"ra lệnh cho ai đó làm gì"}],"wordFamily":["orderly (adj.)","disorder (n.)"],"synonyms":[],"antonyms":[],"tipVi":"\"In order\" có nghĩa là theo thứ tự; cụm \"in order to\" theo sau bởi động từ dùng để chỉ mục đích.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hurry', 'en-a2-41', 'hurry', '/ˈhɜːri/', 'A2', 'vội vã; thúc giục; sự vội vã; sự gấp gáp', 'v.', 'hurried (adj.), hurriedly (adv.)', 'Đồng nghĩa: rush, hasten · Trái nghĩa: dawdle', 'hurry up dùng để giục giã; in a hurry diễn tả sự vội vã.', 'We hurried home before the rain began to fall.', NULL, 'Chúng tôi vội vã về nhà trước khi trời bắt đầu đổ mưa.', '{"wordId":"hurry","ukIpa":"/ˈhʌri/","usIpa":"/ˈhɜːri/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To move or act quickly, or make someone do so.","vi":"vội vã; thúc giục"},{"pos":"n.","en":"A need to act quickly because time is limited.","vi":"sự vội vã; sự gấp gáp"}],"examples":[{"en":"We hurried home before the rain began to fall.","vi":"Chúng tôi vội vã về nhà trước khi trời bắt đầu đổ mưa.","audioKind":"ex"},{"en":"When teachers hurry through difficult material, students may struggle to develop a clear understanding of key concepts.","vi":"Khi giáo viên vội vã lướt qua các tài liệu khó, học sinh có thể gặp khó khăn trong việc hiểu rõ các khái niệm cốt lõi.","audioKind":"ex2"}],"collocations":[{"en":"hurry up","vi":"nhanh lên"},{"en":"in a hurry","vi":"vội vã"},{"en":"hurry home","vi":"vội vã về nhà"},{"en":"hurry through something","vi":"vội vã làm xong việc gì đó"}],"wordFamily":["hurried (adj.)","hurriedly (adv.)"],"synonyms":["rush","hasten"],"antonyms":["dawdle"],"tipVi":"hurry up dùng để giục giã; in a hurry diễn tả sự vội vã.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nail', 'en-a2-41', 'nail', '/neɪl/', 'A2', 'móng tay; móng chân; cái đinh; đóng đinh; cố định bằng đinh', 'n.', 'fingernail (n.), toenail (n.)', NULL, 'Vừa có nghĩa là móng (tay/chân) vừa là cái đinh; khi làm động từ có nghĩa là dùng đinh cố định.', 'I cut my nails before my piano lesson.', NULL, 'Tôi đã cắt móng tay trước giờ học piano.', '{"wordId":"nail","ukIpa":"/neɪl/","usIpa":"/neɪl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"The hard covering at the end of a finger or toe.","vi":"móng tay; móng chân"},{"pos":"n.","en":"A thin pointed metal piece used to fasten materials together.","vi":"cái đinh"},{"pos":"v.","en":"To attach something using nails.","vi":"đóng đinh; cố định bằng đinh"}],"examples":[{"en":"I cut my nails before my piano lesson.","vi":"Tôi đã cắt móng tay trước giờ học piano.","audioKind":"ex"},{"en":"Teaching children to keep their nails clean can help establish healthy personal hygiene habits early.","vi":"Dạy trẻ giữ sạch móng tay có thể giúp hình thành thói quen vệ sinh cá nhân tốt từ sớm.","audioKind":"ex2"}],"collocations":[{"en":"cut your nails","vi":"cắt móng tay"},{"en":"nail polish","vi":"sơn móng tay"},{"en":"hammer a nail","vi":"đóng đinh bằng búa"},{"en":"nail down","vi":"đóng chặt bằng đinh"}],"wordFamily":["fingernail (n.)","toenail (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Vừa có nghĩa là móng (tay/chân) vừa là cái đinh; khi làm động từ có nghĩa là dùng đinh cố định.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pie', 'en-a2-41', 'pie', '/paɪ/', 'A2', 'bánh nướng; bánh pa-tê-sô', 'n.', NULL, NULL, 'pie chỉ bánh nướng có nhân; còn "biểu đồ tròn" phải dùng từ pie chart.', 'We shared a warm apple pie after dinner.', NULL, 'Chúng tôi cùng nhau ăn một chiếc bánh táo nướng ấm nóng sau bữa tối.', '{"wordId":"pie","ukIpa":"/paɪ/","usIpa":"/paɪ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Food with a pastry base or covering and a filling.","vi":"bánh nướng; bánh pa-tê-sô"}],"examples":[{"en":"We shared a warm apple pie after dinner.","vi":"Chúng tôi cùng nhau ăn một chiếc bánh táo nướng ấm nóng sau bữa tối.","audioKind":"ex"},{"en":"Traditional dishes, such as fruit pie, can help preserve regional food culture across generations.","vi":"Các món ăn truyền thống, chẳng hạn như bánh nướng hoa quả, có thể giúp bảo tồn văn hóa ẩm thực vùng miền qua các thế hệ.","audioKind":"ex2"}],"collocations":[{"en":"apple pie","vi":"bánh táo nướng"},{"en":"meat pie","vi":"bánh nướng nhân thịt"},{"en":"a slice of pie","vi":"một miếng bánh nướng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"pie chỉ bánh nướng có nhân; còn \"biểu đồ tròn\" phải dùng từ pie chart.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_form', 'en-a2-41', 'form', '/fɔːrm/', 'A2', 'hình thức; dạng; hình dáng; tờ khai; mẫu đơn; hình thành; tạo thành; thành lập', 'n.', 'formation (n.), formless (adj.)', NULL, 'fill in a form là cách dùng trong tiếng Anh-Anh; người Mỹ thường dùng fill out a form.', 'The clouds took the form of a giant rabbit.', NULL, 'Những đám mây có hình dạng của một chú thỏ khổng lồ.', '{"wordId":"form","ukIpa":"/fɔːm/","usIpa":"/fɔːrm/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a type, arrangement, or shape of something","vi":"hình thức; dạng; hình dáng"},{"pos":"n.","en":"a document with spaces for providing requested information","vi":"tờ khai; mẫu đơn"},{"pos":"v.","en":"to develop, create, or combine into something","vi":"hình thành; tạo thành; thành lập"}],"examples":[{"en":"The clouds took the form of a giant rabbit.","vi":"Những đám mây có hình dạng của một chú thỏ khổng lồ.","audioKind":"ex"},{"en":"Online learning has become a popular form of education because it offers flexibility for working adults.","vi":"Học trực tuyến đã trở thành một hình thức giáo dục phổ biến vì nó mang lại sự linh hoạt cho người lớn đi làm.","audioKind":"ex2"}],"collocations":[{"en":"a form of","vi":"một dạng của..."},{"en":"in the form of","vi":"dưới hình thức..."},{"en":"fill in a form","vi":"điền vào tờ đơn"},{"en":"form a habit","vi":"hình thành thói quen"}],"wordFamily":["formation (n.)","formless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"fill in a form là cách dùng trong tiếng Anh-Anh; người Mỹ thường dùng fill out a form.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hairstyle', 'en-a2-41', 'hairstyle', '/ˈherstaɪl/', 'A2', 'kiểu tóc; tạo hình tóc', 'n.', 'hairstylist (n.), hair (n.)', NULL, 'Là danh từ đếm được, dùng để chỉ kiểu tóc chung khi cắt hoặc tạo mẫu.', 'Your new hairstyle really suits your round glasses.', NULL, 'Kiểu tóc mới của bạn trông rất hợp với chiếc kính gọng tròn đấy.', '{"wordId":"hairstyle","ukIpa":"/ˈheəstaɪl/","usIpa":"/ˈherstaɪl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"the way someone''s hair is cut or arranged","vi":"kiểu tóc; tạo hình tóc"}],"examples":[{"en":"Your new hairstyle really suits your round glasses.","vi":"Kiểu tóc mới của bạn trông rất hợp với chiếc kính gọng tròn đấy.","audioKind":"ex"},{"en":"In some workplaces, strict rules about hairstyles can limit employees'' freedom to express their identity.","vi":"Ở một số môi trường làm việc, các quy định nghiêm ngặt về kiểu tóc có thể hạn chế quyền tự do thể hiện bản sắc cá nhân của nhân viên.","audioKind":"ex2"}],"collocations":[{"en":"change your hairstyle","vi":"thay đổi kiểu tóc"},{"en":"a short hairstyle","vi":"kiểu tóc ngắn"},{"en":"a fashionable hairstyle","vi":"kiểu tóc thời thượng"}],"wordFamily":["hairstylist (n.)","hair (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được, dùng để chỉ kiểu tóc chung khi cắt hoặc tạo mẫu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_type', 'en-a2-41', 'type', '/taɪp/', 'A2', 'loại; kiểu; gõ bàn phím', 'n.', 'typist (n.), typing (n.)', 'Đồng nghĩa: kind, sort', 'Sau cụm type of phải dùng danh từ; nếu chỉ nhiều loại khác nhau thì dùng types of.', 'What type of bread would you like today?', NULL, 'Hôm nay bạn muốn mua loại bánh mì nào?', '{"wordId":"type","ukIpa":"/taɪp/","usIpa":"/taɪp/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a group of things sharing particular features","vi":"loại; kiểu"},{"pos":"v.","en":"to enter words using a keyboard","vi":"gõ bàn phím"}],"examples":[{"en":"What type of bread would you like today?","vi":"Hôm nay bạn muốn mua loại bánh mì nào?","audioKind":"ex"},{"en":"Different types of public transport are needed to serve both urban and rural communities.","vi":"Cần có các loại phương tiện giao thông công cộng khác nhau để phục vụ cho cả cộng đồng đô thị và nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"a type of","vi":"một loại..."},{"en":"blood type","vi":"nhóm máu"},{"en":"type a message","vi":"gõ tin nhắn"}],"wordFamily":["typist (n.)","typing (n.)"],"synonyms":["kind","sort"],"antonyms":[],"tipVi":"Sau cụm type of phải dùng danh từ; nếu chỉ nhiều loại khác nhau thì dùng types of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_theirs', 'en-a2-41', 'theirs', '/ðerz/', 'A2', 'của họ; cái của họ', 'pron.', 'they (pron.), them (pron.), their (det.), themselves (pron.)', NULL, 'theirs được dùng độc lập, tuyệt đối không đi kèm danh từ phía sau và không thêm dấu nháy đơn.', 'Our garden is small, but theirs has several trees.', NULL, 'Khu vườn của chúng tôi nhỏ, nhưng khu vườn của họ lại có vài cây lớn.', '{"wordId":"theirs","ukIpa":"/ðeəz/","usIpa":"/ðerz/","cefr":"A2","topic":"daily","senses":[{"pos":"pron.","en":"The one or ones belonging to them","vi":"của họ; cái của họ"}],"examples":[{"en":"Our garden is small, but theirs has several trees.","vi":"Khu vườn của chúng tôi nhỏ, nhưng khu vườn của họ lại có vài cây lớn.","audioKind":"ex"},{"en":"Some families own their homes, while others rent theirs because property prices remain beyond their reach.","vi":"Một số gia đình sở hữu nhà riêng, trong khi những gia đình khác phải thuê nhà vì giá bất động sản vẫn vượt quá tầm với của họ.","audioKind":"ex2"}],"collocations":[{"en":"a friend of theirs","vi":"một người bạn của họ"},{"en":"theirs to keep","vi":"của họ để giữ"},{"en":"ours and theirs","vi":"của chúng tôi và của họ"}],"wordFamily":["they (pron.)","them (pron.)","their (det.)","themselves (pron.)"],"synonyms":[],"antonyms":[],"tipVi":"theirs được dùng độc lập, tuyệt đối không đi kèm danh từ phía sau và không thêm dấu nháy đơn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_loud', 'en-a2-41', 'loud', '/laʊd/', 'A2', 'to; lớn tiếng; inh ỏi', 'adj.', 'loudly (adv.), loudness (n.)', 'Trái nghĩa: quiet, soft', 'read out loud có nghĩa là đọc thành tiếng; loudly cũng có thể dùng để chỉ việc phát ra âm thanh lớn.', 'A loud crash woke everyone in the house.', NULL, 'Một tiếng động lớn đã đánh thức mọi người trong nhà.', '{"wordId":"loud","ukIpa":"/laʊd/","usIpa":"/laʊd/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Making or having a strong sound that is easily heard.","vi":"to; lớn tiếng; inh ỏi"},{"pos":"adv.","en":"With a strong sound that is easily heard.","vi":"to; lớn tiếng"}],"examples":[{"en":"A loud crash woke everyone in the house.","vi":"Một tiếng động lớn đã đánh thức mọi người trong nhà.","audioKind":"ex"},{"en":"Frequent exposure to loud music can damage hearing, particularly among young people who use headphones.","vi":"Việc thường xuyên nghe nhạc với âm lượng lớn có thể làm tổn thương thính giác, đặc biệt là ở những người trẻ tuổi thường xuyên dùng tai nghe.","audioKind":"ex2"}],"collocations":[{"en":"loud noise","vi":"tiếng ồn lớn"},{"en":"loud music","vi":"nhạc mở âm lượng lớn"},{"en":"out loud","vi":"phát ra thành tiếng"},{"en":"loud and clear","vi":"rõ mồn một; rành mạch"}],"wordFamily":["loudly (adv.)","loudness (n.)"],"synonyms":[],"antonyms":["quiet","soft"],"tipVi":"read out loud có nghĩa là đọc thành tiếng; loudly cũng có thể dùng để chỉ việc phát ra âm thanh lớn.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shout', 'en-a2-41', 'shout', '/ʃaʊt/', 'A2', 'hét; la lớn; gọi lớn; tiếng hét; tiếng hò reo', 'v.', NULL, 'Đồng nghĩa: yell · Trái nghĩa: whisper', 'shout at thường mang hàm ý tức giận; shout to chú trọng vào việc làm cho người ở xa nghe thấy.', 'We shouted across the river, but nobody heard us.', NULL, 'Chúng tôi hét qua bờ sông, nhưng không ai nghe thấy.', '{"wordId":"shout","ukIpa":"/ʃaʊt/","usIpa":"/ʃaʊt/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To speak or call out in a very loud voice.","vi":"hét; la lớn; gọi lớn"},{"pos":"n.","en":"A loud call or cry made with the voice.","vi":"tiếng hét; tiếng hò reo"}],"examples":[{"en":"We shouted across the river, but nobody heard us.","vi":"Chúng tôi hét qua bờ sông, nhưng không ai nghe thấy.","audioKind":"ex"},{"en":"In noisy classrooms, teachers may need to shout, which can strain their voices over time.","vi":"Trong những lớp học ồn ào, giáo viên có thể phải la lớn, điều này về lâu dài có thể làm tổn hại đến giọng nói của họ.","audioKind":"ex2"}],"collocations":[{"en":"shout for help","vi":"hét lớn cầu cứu"},{"en":"shout at someone","vi":"quát mắng ai đó"},{"en":"shout to someone","vi":"gọi lớn với ai đó"},{"en":"a shout of joy","vi":"tiếng hò reo vui sướng"}],"wordFamily":[],"synonyms":["yell"],"antonyms":["whisper"],"tipVi":"shout at thường mang hàm ý tức giận; shout to chú trọng vào việc làm cho người ở xa nghe thấy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_41_1', 'en-a2-41', 'Cách dùng “should” (v.) — nên; phải', 'should do something  ·  should have done  ·  should be able to', 'Động từ khuyết thiếu, theo sau là động từ nguyên thể; should have done thường chỉ việc lẽ ra nên làm nhưng đã không làm.', NULL, '[{"hanzi":"You should take an umbrella because it looks cloudy.","pinyin":"","meaning":"Bạn nên mang theo ô vì trời có vẻ âm u."},{"hanzi":"Governments should invest in affordable public transport to reduce congestion and improve urban air quality.","pinyin":"","meaning":"Chính phủ nên đầu tư vào hệ thống giao thông công cộng giá cả phải chăng để giảm tình trạng tắc nghẽn và cải thiện chất lượng không khí đô thị."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_41_2', 'en-a2-41', 'Cách dùng “cute” (adj.) — dễ thương; đáng yêu', 'a cute baby  ·  a cute smile  ·  look cute', 'Mang sắc thái thân mật, thường dùng trong văn phong hàng ngày để tả trẻ em, động vật hoặc vẻ bề ngoài đáng yêu.', 'Họ từ (Word Family): cuteness (n.), cutely (adv.) | Đồng nghĩa: adorable, sweet', '[{"hanzi":"That cute kitten is sleeping inside my slipper.","pinyin":"","meaning":"Chú mèo con dễ thương ấy đang ngủ cuộn tròn bên trong chiếc dép của tôi."},{"hanzi":"Advertisements often feature cute animals to attract attention and create positive feelings towards a product.","pinyin":"","meaning":"Các quảng cáo thường sử dụng hình ảnh động vật dễ thương để thu hút sự chú ý và tạo cảm tình tốt đẹp đối với sản phẩm."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_41_3', 'en-a2-41', 'Cách dùng “shall” (v.) — dùng với I hoặc we để đề nghị hoặc gợi ý điều gì đó', 'shall we  ·  shall I  ·  shall not', 'Là động từ khuyết thiếu, theo sau là động từ nguyên mẫu; Shall we thường dùng để đưa ra lời đề nghị.', NULL, '[{"hanzi":"Shall we take a short walk after dinner?","pinyin":"","meaning":"Chúng ta đi dạo một lát sau bữa tối nhé?"},{"hanzi":"Under the proposed regulations, employers shall provide appropriate safety equipment for all workers handling hazardous materials.","pinyin":"","meaning":"Theo các quy định đề xuất, người sử dụng lao động phải cung cấp thiết bị an toàn phù hợp cho tất cả công nhân tiếp xúc với vật liệu nguy hiểm."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_41_4', 'en-a2-41', 'Cách dùng “loud” (adj.) — to; lớn tiếng; inh ỏi', 'loud noise  ·  loud music  ·  out loud', 'read out loud có nghĩa là đọc thành tiếng; loudly cũng có thể dùng để chỉ việc phát ra âm thanh lớn.', 'Họ từ (Word Family): loudly (adv.), loudness (n.) | Trái nghĩa: quiet, soft', '[{"hanzi":"A loud crash woke everyone in the house.","pinyin":"","meaning":"Một tiếng động lớn đã đánh thức mọi người trong nhà."},{"hanzi":"Frequent exposure to loud music can damage hearing, particularly among young people who use headphones.","pinyin":"","meaning":"Việc thường xuyên nghe nhạc với âm lượng lớn có thể làm tổn thương thính giác, đặc biệt là ở những người trẻ tuổi thường xuyên dùng tai nghe."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_41_1', 'en-a2-41', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
