INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_41_1_5', 'ten_a2_41_1', 'quietly', 'Please close the door quietly; the baby is sleeping.', 'Please close the door quietly; the baby is sleeping.', '/ˈkwaɪətli/', 'Làm ơn khép cửa nhẹ nhàng thôi, em bé đang ngủ đấy.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
