INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_41_1_7', 'ten_a2_41_1', 'bill', 'We asked for the bill after finishing our lunch.', 'We asked for the bill after finishing our lunch.', '/bɪl/', 'Chúng tôi đã gọi thanh toán hóa đơn sau khi ăn trưa xong.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_41_1_8', 'ten_a2_41_1', 'should', 'You should take an umbrella because it looks cloudy.', 'You should take an umbrella because it looks cloudy.', '/ʃʊd/', 'Bạn nên mang theo ô vì trời có vẻ âm u.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_41_1_1', 'en-a2-41', 'ten_a2_41_1', 'listening', 'listening', 'Let''s meet outside the library at noon tomorrow.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng ta đi dạo một lát sau bữa tối nhé?","Món súp đang sôi lăn tăn trong một cái nồi lớn.","Hãy gặp nhau ở bên ngoài thư viện vào trưa mai nhé.","Một tiếng động lớn đã đánh thức mọi người trong nhà."]'::jsonb, 2, 'Let''s meet outside the library at noon tomorrow. → Hãy gặp nhau ở bên ngoài thư viện vào trưa mai nhé.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_41_1_2', 'en-a2-41', 'ten_a2_41_1', 'listening', 'listening', 'I left my wallet beside the kitchen sink.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Đó là bữa ăn tồi tệ nhất mà tôi từng nấu.","Chúng tôi vội vã về nhà trước khi trời bắt đầu đổ mưa.","Chúng tôi hét qua bờ sông, nhưng không ai nghe thấy.","Tôi để quên ví ở ngay cạnh bồn rửa trong bếp."]'::jsonb, 3, 'I left my wallet beside the kitchen sink. → Tôi để quên ví ở ngay cạnh bồn rửa trong bếp.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_41_1_3', 'en-a2-41', 'ten_a2_41_1', 'listening', 'listening', 'The bread is still warm from the oven.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi để quên ví ở ngay cạnh bồn rửa trong bếp.","Ổ bánh mì vừa mới ra lò nên vẫn còn rất ấm.","Đó là bữa ăn tồi tệ nhất mà tôi từng nấu.","Tôi xách một giỏ táo tươi bước vào nhà bếp."]'::jsonb, 1, 'The bread is still warm from the oven. → Ổ bánh mì vừa mới ra lò nên vẫn còn rất ấm.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_41_2', 'en-a2-41', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_41_2_1', 'ten_a2_41_2', 'noon', 'Outdoor workers should avoid intense physical activity around noon, when temperatures and sunlight can be particularly strong.', 'Outdoor workers should avoid intense physical activity around noon, when temperatures and sunlight can be particularly strong.', '/nuːn/', 'Những người làm việc ngoài trời nên tránh các hoạt động thể chất nặng vào khoảng giữa trưa, khi nhiệt độ và ánh nắng có thể cực kỳ gay gắt.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_41_2_2', 'ten_a2_41_2', 'wallet', 'As digital payments become more common, fewer consumers need to carry cash in a wallet.', 'As digital payments become more common, fewer consumers need to carry cash in a wallet.', '/ˈwɑːlɪt/', 'Khi thanh toán kỹ thuật số ngày càng trở nên phổ biến, ít người tiêu dùng cần mang theo tiền mặt trong ví hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_41_2_3', 'ten_a2_41_2', 'oven', 'Using an energy-efficient oven can reduce household electricity consumption without changing cooking habits significantly.', 'Using an energy-efficient oven can reduce household electricity consumption without changing cooking habits significantly.', '/ˈʌvən/', 'Sử dụng lò nướng tiết kiệm năng lượng có thể làm giảm lượng điện tiêu thụ trong gia đình mà không cần thay đổi đáng kể thói quen nấu nướng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_41_2_4', 'ten_a2_41_2', 'worst', 'The worst effects of air pollution are often experienced by children and older people in densely populated cities.', 'The worst effects of air pollution are often experienced by children and older people in densely populated cities.', '/wɝːst/', 'Tác động tồi tệ nhất của ô nhiễm không khí thường đổ lên đầu trẻ em và người cao tuổi ở những thành phố đông dân cư.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_41_2_5', 'ten_a2_41_2', 'quietly', 'Students who work quietly in shared study areas help create an environment that supports concentration.', 'Students who work quietly in shared study areas help create an environment that supports concentration.', '/ˈkwaɪətli/', 'Những học sinh chăm chỉ học tập một cách lặng lẽ ở các khu vực học tập chung góp phần tạo nên một môi trường đề cao sự tập trung.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_41_2_6', 'ten_a2_41_2', 'cute', 'Advertisements often feature cute animals to attract attention and create positive feelings towards a product.', 'Advertisements often feature cute animals to attract attention and create positive feelings towards a product.', '/kjuːt/', 'Các quảng cáo thường sử dụng hình ảnh động vật dễ thương để thu hút sự chú ý và tạo cảm tình tốt đẹp đối với sản phẩm.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_41_2_1', 'en-a2-41', 'ten_a2_41_2', 'listening', 'listening', 'Outdoor workers should avoid intense physical activity around noon, when temperatures and sunlight can be particularly strong.', NULL, 'Trong câu vừa nghe, từ “noon” mang nghĩa nào sau đây?', '["vài; một vài (hơn hai nhưng không nhiều)","giải thưởng; phần thưởng","trưa; chính ngọ","tương tự; giống nhau"]'::jsonb, 2, '“noon” (/nuːn/): trưa; chính ngọ. Câu đầy đủ: Outdoor workers should avoid intense physical activity around noon, when temperatures and sunlight can be particularly strong.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
