INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_41_5', 'en-a2-41', NULL, 'comprehensive_test', 'listening', 'quietly', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["cơ hội","hành động; cư xử; đóng vai","một cách yên tĩnh; khẽ khàng","chuột túi; con kangaroo"]'::jsonb, 2, 'quietly (/ˈkwaɪətli/) → một cách yên tĩnh; khẽ khàng; lặng lẽ; không phô trương', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_41_6', 'en-a2-41', NULL, 'comprehensive_test', 'listening', 'That cute kitten is sleeping inside my slipper.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi xách một giỏ táo tươi bước vào nhà bếp.","Khu vườn của chúng tôi nhỏ, nhưng khu vườn của họ lại có vài cây lớn.","Chú mèo con dễ thương ấy đang ngủ cuộn tròn bên trong chiếc dép của tôi.","Hôm nay bạn muốn mua loại bánh mì nào?"]'::jsonb, 2, 'That cute kitten is sleeping inside my slipper. → Chú mèo con dễ thương ấy đang ngủ cuộn tròn bên trong chiếc dép của tôi.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_41_7', 'en-a2-41', NULL, 'comprehensive_test', 'listening', 'bill', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["từ (một thời điểm trong quá khứ) cho đến nay","đẩy; ấn","hầu như; suýt; gần như","hóa đơn"]'::jsonb, 3, 'bill (/bɪl/) → hóa đơn; dự luật; tiền giấy', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_41_8', 'en-a2-41', NULL, 'comprehensive_test', 'listening', 'You should take an umbrella because it looks cloudy.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bạn nên mang theo ô vì trời có vẻ âm u.","Chuyến đi mua sắm hàng tuần của chúng tôi thường kết thúc ở tiệm bánh.","Chú chó con ngậm một quả bóng dính bùn chạy về phía tôi.","Xin hãy nhẹ nhàng kéo cửa thay vì đẩy."]'::jsonb, 0, 'You should take an umbrella because it looks cloudy. → Bạn nên mang theo ô vì trời có vẻ âm u.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
