INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_41_18', 'en-a2-41', NULL, 'comprehensive_test', 'reading', NULL, 'Outdoor workers should avoid intense physical activity around noon, when temperatures and sunlight can be particularly strong.', 'Dựa vào câu trên, từ “noon” có nghĩa phù hợp nhất là gì?', '["cải thiện; nâng cao; tiến bộ","trưa; chính ngọ","lười biếng; biếng nhác","chật chội; đông đúc"]'::jsonb, 1, 'noon: trưa; chính ngọ. Dịch cả câu: Những người làm việc ngoài trời nên tránh các hoạt động thể chất nặng vào khoảng giữa trưa, khi nhiệt độ và ánh nắng có thể cực kỳ gay gắt.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_41_19', 'en-a2-41', NULL, 'comprehensive_test', 'reading', NULL, 'As digital payments become more common, fewer consumers need to carry cash in a wallet.', 'Dựa vào câu trên, từ “wallet” có nghĩa phù hợp nhất là gì?', '["ví tiền; bóp tiền","nghĩa; ý nghĩa; hàm ý","găng tay; bao tay","thích hơn; ưu tiên hơn"]'::jsonb, 0, 'wallet: ví tiền; bóp tiền. Dịch cả câu: Khi thanh toán kỹ thuật số ngày càng trở nên phổ biến, ít người tiêu dùng cần mang theo tiền mặt trong ví hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_41_20', 'en-a2-41', NULL, 'comprehensive_test', 'reading', NULL, 'Using an energy-efficient oven can reduce household electricity consumption without changing cooking habits significantly.', 'Dựa vào câu trên, từ “oven” có nghĩa phù hợp nhất là gì?', '["lo lắng; bận tâm","lò nướng; lò vi sóng","lười biếng; biếng nhác","người hâm mộ; người cuồng nhiệt; tín đồ"]'::jsonb, 1, 'oven: lò nướng; lò vi sóng. Dịch cả câu: Sử dụng lò nướng tiết kiệm năng lượng có thể làm giảm lượng điện tiêu thụ trong gia đình mà không cần thay đổi đáng kể thói quen nấu nướng.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_41_21', 'en-a2-41', NULL, 'comprehensive_test', 'reading', NULL, 'The worst effects of air pollution are often experienced by children and older people in densely populated cities.', 'Dựa vào câu trên, từ “worst” có nghĩa phù hợp nhất là gì?', '["hủy bỏ; bãi bỏ; hoãn","giới thiệu; ra mắt (tên tuổi của mọi người)","phá hủy; tàn phá","tệ nhất; tồi tệ nhất"]'::jsonb, 3, 'worst: tệ nhất; tồi tệ nhất; một cách tệ hại nhất; nghiêm trọng nhất; tình huống xấu nhất; điều tồi tệ nhất. Dịch cả câu: Tác động tồi tệ nhất của ô nhiễm không khí thường đổ lên đầu trẻ em và người cao tuổi ở những thành phố đông dân cư.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_41_22', 'en-a2-41', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “của họ; cái của họ”', '["certain","armchair","drop","theirs"]'::jsonb, 3, 'của họ; cái của họ → theirs (/ðerz/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
