INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-42', 'en', 'Bài 42: Đời sống hằng ngày (14) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '26 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2042, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_beside', 'en-a2-42', 'beside', '/bɪˈsaɪd/', 'A2', 'ở bên cạnh; sát bên', 'prep.', NULL, 'Đồng nghĩa: next to, alongside', 'beside có nghĩa là "ở bên cạnh"; còn besides có nghĩa là "ngoài ra; bên cạnh đó".', 'Please leave your wet boots beside the door.', NULL, 'Làm ơn để đôi ủng ướt của bạn ở bên cạnh cửa.', '{"wordId":"beside","ukIpa":"/bɪˈsaɪd/","usIpa":"/bɪˈsaɪd/","cefr":"A2","topic":"daily","senses":[{"pos":"prep.","en":"At the side of someone or something.","vi":"ở bên cạnh; sát bên"}],"examples":[{"en":"Please leave your wet boots beside the door.","vi":"Làm ơn để đôi ủng ướt của bạn ở bên cạnh cửa.","audioKind":"ex"},{"en":"Creating walking paths beside urban rivers can encourage physical activity and improve residents'' access to nature.","vi":"Việc xây dựng các lối đi bộ bên cạnh các con sông trong thành phố có thể khuyến khích hoạt động thể chất và giúp người dân tiếp cận thiên nhiên dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"sit beside someone","vi":"ngồi bên cạnh ai đó"},{"en":"beside the river","vi":"bên bờ sông"},{"en":"beside the point","vi":"lạc đề; không liên quan"}],"wordFamily":[],"synonyms":["next to","alongside"],"antonyms":[],"tipVi":"beside có nghĩa là \"ở bên cạnh\"; còn besides có nghĩa là \"ngoài ra; bên cạnh đó\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tie', 'en-a2-42', 'tie', '/taɪ/', 'A2', 'buộc; cột; thắt; cà vạt; mối liên hệ; mối quan hệ', 'v.', 'untie (v.)', 'Đồng nghĩa: fasten, bind · Trái nghĩa: untie', 'Dạng phân từ hiện tại của tie là tying; khi chỉ mối quan hệ, từ này thường dùng ở số nhiều là ties.', 'Please tie your shoelaces before you run outside.', NULL, 'Hãy thắt dây giày của bạn trước khi chạy ra ngoài.', '{"wordId":"tie","ukIpa":"/taɪ/","usIpa":"/taɪ/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to fasten something using string, rope, or a knot","vi":"buộc; cột; thắt"},{"pos":"n.","en":"a long narrow piece of cloth worn around the collar","vi":"cà vạt"},{"pos":"n.","en":"a connection between people, groups, or places","vi":"mối liên hệ; mối quan hệ"}],"examples":[{"en":"Please tie your shoelaces before you run outside.","vi":"Hãy thắt dây giày của bạn trước khi chạy ra ngoài.","audioKind":"ex"},{"en":"Strong ties between schools and local employers can help young people make a smoother transition into work.","vi":"Mối quan hệ gắn bó giữa các trường học và nhà tuyển dụng địa phương có thể giúp người trẻ bước chân vào môi trường làm việc một cách suôn sẻ hơn.","audioKind":"ex2"}],"collocations":[{"en":"tie a knot","vi":"thắt nút"},{"en":"wear a tie","vi":"đeo cà vạt"},{"en":"family ties","vi":"tình cảm gia đình"},{"en":"strengthen ties","vi":"tăng cường mối quan hệ"}],"wordFamily":["untie (v.)"],"synonyms":["fasten","bind"],"antonyms":["untie"],"tipVi":"Dạng phân từ hiện tại của tie là tying; khi chỉ mối quan hệ, từ này thường dùng ở số nhiều là ties.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_including', 'en-a2-42', 'including', '/ɪnˈkluːdɪŋ/', 'A2', 'bao gồm; kể cả', 'prep.', 'include (v.), inclusion (n.), inclusive (adj.)', 'Trái nghĩa: excluding', 'including đứng trước danh từ hoặc đại từ; trong khi included thường đứng ngay sau đó.', 'Everyone came to the picnic, including our new neighbours.', NULL, 'Mọi người đều đến buổi dã ngoại, kể cả những người hàng xóm mới của chúng ta.', '{"wordId":"including","ukIpa":"/ɪnˈkluːdɪŋ/","usIpa":"/ɪnˈkluːdɪŋ/","cefr":"A2","topic":"daily","senses":[{"pos":"prep.","en":"With someone or something as part of a larger group.","vi":"bao gồm; kể cả"}],"examples":[{"en":"Everyone came to the picnic, including our new neighbours.","vi":"Mọi người đều đến buổi dã ngoại, kể cả những người hàng xóm mới của chúng ta.","audioKind":"ex"},{"en":"Cities should provide accessible public spaces for all residents, including older people and those with limited mobility.","vi":"Các thành phố nên cung cấp không gian công cộng dễ tiếp cận cho tất cả cư dân, bao gồm cả người cao tuổi và những người có khả năng vận động hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"including tax","vi":"đã bao gồm thuế"},{"en":"including delivery","vi":"bao gồm phí vận chuyển"},{"en":"including children","vi":"bao gồm cả trẻ em"}],"wordFamily":["include (v.)","inclusion (n.)","inclusive (adj.)"],"synonyms":[],"antonyms":["excluding"],"tipVi":"including đứng trước danh từ hoặc đại từ; trong khi included thường đứng ngay sau đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tiny', 'en-a2-42', 'tiny', '/ˈtaɪni/', 'A2', 'nhỏ xíu; tí hon; cực nhỏ', 'adj.', 'tinier (adj.), tiniest (adj.)', 'Đồng nghĩa: minute, minuscule · Trái nghĩa: huge, enormous', 'Mang sắc thái mạnh hơn small, nhấn mạnh mức độ nhỏ đến ngạc nhiên.', 'A tiny frog jumped out of the flower pot.', NULL, 'Một chú ếch tí hon từ trong chậu hoa nhảy ra.', '{"wordId":"tiny","ukIpa":"/ˈtaɪni/","usIpa":"/ˈtaɪni/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Extremely small in size or amount.","vi":"nhỏ xíu; tí hon; cực nhỏ"}],"examples":[{"en":"A tiny frog jumped out of the flower pot.","vi":"Một chú ếch tí hon từ trong chậu hoa nhảy ra.","audioKind":"ex"},{"en":"Even tiny changes in daily habits can reduce household energy consumption over time.","vi":"Ngay cả những thay đổi nhỏ bé trong thói quen sinh hoạt hàng ngày cũng có thể làm giảm lượng tiêu thụ năng lượng của hộ gia đình theo thời gian.","audioKind":"ex2"}],"collocations":[{"en":"a tiny amount","vi":"một lượng cực nhỏ"},{"en":"a tiny fraction","vi":"một phần rất nhỏ"},{"en":"a tiny village","vi":"một ngôi làng nhỏ"}],"wordFamily":["tinier (adj.)","tiniest (adj.)"],"synonyms":["minute","minuscule"],"antonyms":["huge","enormous"],"tipVi":"Mang sắc thái mạnh hơn small, nhấn mạnh mức độ nhỏ đến ngạc nhiên.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_naughty', 'en-a2-42', 'naughty', '/ˈnɔːti/', 'A2', 'nghịch ngợm; hư đốn; không vâng lời', 'adj.', 'naughtiness (n.), naughtily (adv.)', 'Đồng nghĩa: mischievous, disobedient · Trái nghĩa: well-behaved', 'Thường dùng cho trẻ em hoặc vật nuôi, thông thường không ám chỉ hành vi sai trái nghiêm trọng.', 'The naughty puppy dragged my slippers into the garden.', NULL, 'Chú chó con nghịch ngợm đã lôi đôi dép của tôi vào khu vườn.', '{"wordId":"naughty","ukIpa":"/ˈnɔːti/","usIpa":"/ˈnɔːti/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Behaving badly, especially by disobeying adults","vi":"nghịch ngợm; hư đốn; không vâng lời"}],"examples":[{"en":"The naughty puppy dragged my slippers into the garden.","vi":"Chú chó con nghịch ngợm đã lôi đôi dép của tôi vào khu vườn.","audioKind":"ex"},{"en":"Children described as naughty may benefit more from patient guidance than from repeated punishment.","vi":"Những đứa trẻ được mô tả là nghịch ngợm có thể nhận được nhiều lợi ích hơn từ sự hướng dẫn kiên nhẫn thay vì bị phạt lặp đi lặp lại.","audioKind":"ex2"}],"collocations":[{"en":"naughty child","vi":"đứa trẻ nghịch ngợm"},{"en":"naughty behaviour","vi":"hành vi nghịch ngợm"},{"en":"be naughty","vi":"cư xử hư đốn"}],"wordFamily":["naughtiness (n.)","naughtily (adv.)"],"synonyms":["mischievous","disobedient"],"antonyms":["well-behaved"],"tipVi":"Thường dùng cho trẻ em hoặc vật nuôi, thông thường không ám chỉ hành vi sai trái nghiêm trọng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_final', 'en-a2-42', 'final', '/ˈfaɪnəl/', 'A2', 'cuối cùng; không thể thay đổi; quyết định cuối cùng; trận chung kết; kỳ thi cuối kỳ', 'adj.', 'finally (adv.), finalise (v.), finality (n.)', 'Đồng nghĩa: last · Trái nghĩa: initial', 'finally là trạng từ; final khi làm danh từ có thể chỉ trận chung kết hoặc kỳ thi cuối kỳ.', 'We packed the final box and locked the door.', NULL, 'Chúng tôi đóng gói thùng hàng cuối cùng và khóa cửa lại.', '{"wordId":"final","ukIpa":"/ˈfaɪnəl/","usIpa":"/ˈfaɪnəl/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"coming last in a series or process","vi":"cuối cùng"},{"pos":"adj.","en":"settled and not open to further change or discussion","vi":"không thể thay đổi; quyết định cuối cùng"},{"pos":"n.","en":"a competition''s last match, or an examination ending a course","vi":"trận chung kết; kỳ thi cuối kỳ"}],"examples":[{"en":"We packed the final box and locked the door.","vi":"Chúng tôi đóng gói thùng hàng cuối cùng và khóa cửa lại.","audioKind":"ex"},{"en":"The final stage of the research involved comparing energy consumption across several types of housing.","vi":"Giai đoạn cuối cùng của nghiên cứu liên quan đến việc so sánh mức tiêu thụ năng lượng giữa một số loại nhà ở.","audioKind":"ex2"}],"collocations":[{"en":"final decision","vi":"quyết định cuối cùng"},{"en":"final stage","vi":"giai đoạn cuối"},{"en":"reach the final","vi":"lọt vào trận chung kết"},{"en":"final exams","vi":"kỳ thi cuối kỳ"}],"wordFamily":["finally (adv.)","finalise (v.)","finality (n.)"],"synonyms":["last"],"antonyms":["initial"],"tipVi":"finally là trạng từ; final khi làm danh từ có thể chỉ trận chung kết hoặc kỳ thi cuối kỳ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_melon', 'en-a2-42', 'melon', '/ˈmelən/', 'A2', 'quả dưa (dưa gang, dưa lưới...)', 'n.', NULL, NULL, 'melon dùng chung cho các loại dưa; watermelon chỉ riêng dưa hấu.', 'She sliced a ripe melon for our picnic.', NULL, 'Cô ấy cắt một quả dưa chín để chúng tôi ăn trong buổi dã ngoại.', '{"wordId":"melon","ukIpa":"/ˈmelən/","usIpa":"/ˈmelən/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A large round fruit with thick skin and sweet, juicy flesh.","vi":"quả dưa (dưa gang, dưa lưới...)"}],"examples":[{"en":"She sliced a ripe melon for our picnic.","vi":"Cô ấy cắt một quả dưa chín để chúng tôi ăn trong buổi dã ngoại.","audioKind":"ex"},{"en":"Farmers growing melons in dry regions often use efficient irrigation systems to reduce water consumption.","vi":"Những người nông dân trồng dưa ở các vùng khô hạn thường sử dụng hệ thống tưới tiêu hiệu quả để giảm lượng nước tiêu thụ.","audioKind":"ex2"}],"collocations":[{"en":"ripe melon","vi":"dưa chín"},{"en":"a slice of melon","vi":"một miếng dưa"},{"en":"melon seeds","vi":"hạt dưa"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"melon dùng chung cho các loại dưa; watermelon chỉ riêng dưa hấu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_actually', 'en-a2-42', 'actually', '/ˈæktʃuəli/', 'A2', 'thực ra; thực sự; quả thực', 'adv.', 'actual (adj.), actuality (n.)', 'Đồng nghĩa: in fact, in reality', 'actually mang nghĩa là "thực ra / thực tế", không dùng để chỉ "hiện tại / bây giờ".', 'I thought this soup was spicy, but it is actually sweet.', NULL, 'Tôi cứ nghĩ món súp này cay, nhưng thực ra nó có vị ngọt.', '{"wordId":"actually","ukIpa":"/ˈæktʃuəli/","usIpa":"/ˈæktʃuəli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"in fact, often surprisingly or contrary to what was expected","vi":"thực ra; thực sự; quả thực"}],"examples":[{"en":"I thought this soup was spicy, but it is actually sweet.","vi":"Tôi cứ nghĩ món súp này cay, nhưng thực ra nó có vị ngọt.","audioKind":"ex"},{"en":"Although online courses seem convenient, some students actually learn more effectively through face-to-face interaction.","vi":"Mặc dù các khóa học trực tuyến có vẻ thuận tiện, nhưng một số học sinh thực sự học tập hiệu quả hơn thông qua tương tác trực tiếp.","audioKind":"ex2"}],"collocations":[{"en":"actually happen","vi":"thực sự xảy ra"},{"en":"actually mean","vi":"ý thực sự là"},{"en":"actually work","vi":"thực sự có hiệu quả"}],"wordFamily":["actual (adj.)","actuality (n.)"],"synonyms":["in fact","in reality"],"antonyms":[],"tipVi":"actually mang nghĩa là \"thực ra / thực tế\", không dùng để chỉ \"hiện tại / bây giờ\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_towel', 'en-a2-42', 'towel', '/ˈtaʊəl/', 'A2', 'khăn tắm; khăn lau; dùng khăn lau khô', 'n.', 'towelling (n.)', NULL, 'Là danh từ đếm được; paper towel chỉ khăn giấy thấm nước, không phải khăn vải.', 'He wrapped a warm towel around his wet shoulders.', NULL, 'Anh ấy quấn một chiếc khăn ấm quanh đôi vai đang ướt của mình.', '{"wordId":"towel","ukIpa":"/ˈtaʊəl/","usIpa":"/ˈtaʊəl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a piece of absorbent cloth used for drying things","vi":"khăn tắm; khăn lau"},{"pos":"v.","en":"to dry someone or something with a towel","vi":"dùng khăn lau khô"}],"examples":[{"en":"He wrapped a warm towel around his wet shoulders.","vi":"Anh ấy quấn một chiếc khăn ấm quanh đôi vai đang ướt của mình.","audioKind":"ex"},{"en":"Hotels can reduce water consumption by encouraging guests to reuse their towels during their stay.","vi":"Các khách sạn có thể giảm lượng nước tiêu thụ bằng cách khuyến khích khách lưu trú tái sử dụng khăn tắm của họ.","audioKind":"ex2"}],"collocations":[{"en":"bath towel","vi":"khăn tắm"},{"en":"hand towel","vi":"khăn lau tay"},{"en":"paper towel","vi":"khăn giấy"},{"en":"towel dry","vi":"lau khô bằng khăn"}],"wordFamily":["towelling (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được; paper towel chỉ khăn giấy thấm nước, không phải khăn vải.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_hit', 'en-a2-42', 'hit', '/hɪt/', 'A2', 'đánh; va đập; tác động xấu; giáng đòn mạnh; sự thành công lớn; người/vật rất được yêu thích', 'v.', 'hitter (n.)', 'Đồng nghĩa: strike', 'Dạng quá khứ và quá khứ phân từ vẫn là hit; phân từ hiện đại là hitting.', 'The ball hit the fence and bounced towards me.', NULL, 'Quả bóng đập vào hàng rào và nảy về phía tôi.', '{"wordId":"hit","ukIpa":"/hɪt/","usIpa":"/hɪt/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"Strike someone or something with force.","vi":"đánh; va đập"},{"pos":"v.","en":"Affect someone or something badly, often suddenly.","vi":"tác động xấu; giáng đòn mạnh"},{"pos":"n.","en":"Someone or something that becomes very popular or successful.","vi":"sự thành công lớn; người/vật rất được yêu thích"}],"examples":[{"en":"The ball hit the fence and bounced towards me.","vi":"Quả bóng đập vào hàng rào và nảy về phía tôi.","audioKind":"ex"},{"en":"Rising energy prices have hit small businesses particularly hard, forcing many owners to reduce their operating hours.","vi":"Giá năng lượng leo thang đã tác động cực kỳ nặng nề đến các doanh nghiệp nhỏ, buộc nhiều chủ cơ sở phải cắt giảm thời gian hoạt động.","audioKind":"ex2"}],"collocations":[{"en":"hit the ball","vi":"đánh bóng"},{"en":"be hit hard","vi":"chịu đòn nặng nề; chịu tổn thất lớn"},{"en":"a big hit","vi":"một thành công lớn"},{"en":"hit a target","vi":"đánh trúng mục tiêu"}],"wordFamily":["hitter (n.)"],"synonyms":["strike"],"antonyms":[],"tipVi":"Dạng quá khứ và quá khứ phân từ vẫn là hit; phân từ hiện đại là hitting.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lift', 'en-a2-42', 'lift', '/lɪft/', 'A2', 'nâng lên; nhấc lên; thang máy; quá giang; đi nhờ xe', 'v.', 'lifting (n.)', 'Đồng nghĩa: raise, elevator · Trái nghĩa: lower', 'Thang máy tiếng Anh-Anh là lift, tiếng Anh-Mỹ là elevator.', 'Can you help me lift this box onto the shelf?', NULL, 'Bạn có thể giúp tôi nhấc chiếc hộp này lên kệ không?', '{"wordId":"lift","ukIpa":"/lɪft/","usIpa":"/lɪft/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To move someone or something to a higher position.","vi":"nâng lên; nhấc lên"},{"pos":"n.","en":"A machine carrying people or goods between floors.","vi":"thang máy"},{"pos":"n.","en":"A ride in someone else''s vehicle.","vi":"quá giang; đi nhờ xe"}],"examples":[{"en":"Can you help me lift this box onto the shelf?","vi":"Bạn có thể giúp tôi nhấc chiếc hộp này lên kệ không?","audioKind":"ex"},{"en":"Installing lifts in older public buildings can improve access for wheelchair users and people with limited mobility.","vi":"Việc lắp đặt thang máy ở các tòa nhà công cộng cũ có thể giúp người đi xe lăn và người hạn chế khả năng di chuyển tiếp cận dễ dàng hơn.","audioKind":"ex2"}],"collocations":[{"en":"lift weights","vi":"cử tạ"},{"en":"take the lift","vi":"đi thang máy"},{"en":"give someone a lift","vi":"cho ai đó đi nhờ xe"},{"en":"lift a ban","vi":"dỡ bỏ lệnh cấm"}],"wordFamily":["lifting (n.)"],"synonyms":["raise","elevator"],"antonyms":["lower"],"tipVi":"Thang máy tiếng Anh-Anh là lift, tiếng Anh-Mỹ là elevator.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_jam', 'en-a2-42', 'jam', '/dʒæm/', 'A2', 'mứt quả; mứt trái cây; tình trạng kẹt xe; sự tắc nghẽn; làm kẹt; nhồi nhét', 'n.', 'jammed (adj.)', NULL, 'Mứt quả thường là danh từ không đếm được; một vụ kẹt xe dùng a traffic jam.', 'I spread strawberry jam on my toast this morning.', NULL, 'Sáng nay tôi phết mứt dâu tây lên bánh mì nướng.', '{"wordId":"jam","ukIpa":"/dʒæm/","usIpa":"/dʒæm/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A sweet spread made by cooking fruit with sugar.","vi":"mứt quả; mứt trái cây"},{"pos":"n.","en":"A situation where movement stops because things are packed together.","vi":"tình trạng kẹt xe; sự tắc nghẽn"},{"pos":"v.","en":"To become stuck, or force something into a tight space.","vi":"làm kẹt; nhồi nhét"}],"examples":[{"en":"I spread strawberry jam on my toast this morning.","vi":"Sáng nay tôi phết mứt dâu tây lên bánh mì nướng.","audioKind":"ex"},{"en":"Frequent traffic jams increase air pollution and make daily journeys more stressful for urban residents.","vi":"Tình trạng ùn tắc giao thông thường xuyên làm gia tăng ô nhiễm không khí và khiến việc di chuyển hằng ngày trở nên căng thẳng hơn đối với cư dân thành thị.","audioKind":"ex2"}],"collocations":[{"en":"strawberry jam","vi":"mứt dâu tây"},{"en":"traffic jam","vi":"kẹt xe; tắc đường"},{"en":"get jammed","vi":"bị kẹt cứng"},{"en":"jam something into","vi":"nhồi nhét cái gì vào"}],"wordFamily":["jammed (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Mứt quả thường là danh từ không đếm được; một vụ kẹt xe dùng a traffic jam.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_normally', 'en-a2-42', 'normally', '/ˈnɔːrməli/', 'A2', 'thường xuyên; thông thường; trong hầu hết các trường hợp; bình thường; theo cách thông thường', 'adv.', 'normal (adj.), normality (n.), abnormal (adj.), abnormally (adv.)', 'Đồng nghĩa: usually, ordinarily · Trái nghĩa: abnormally', 'Có thể dùng để chỉ tần suất "thường xuyên" hoặc trạng thái "bình thường".', 'I normally walk to work unless it rains heavily.', NULL, 'Tôi thường đi bộ đi làm trừ khi trời mưa to.', '{"wordId":"normally","ukIpa":"/ˈnɔːməli/","usIpa":"/ˈnɔːrməli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"usually, or in most situations","vi":"thường xuyên; thông thường; trong hầu hết các trường hợp"},{"pos":"adv.","en":"in the usual, expected, or healthy way","vi":"bình thường; theo cách thông thường"}],"examples":[{"en":"I normally walk to work unless it rains heavily.","vi":"Tôi thường đi bộ đi làm trừ khi trời mưa to.","audioKind":"ex"},{"en":"Students normally benefit from regular feedback, especially when teachers provide clear guidance on improving their work.","vi":"Học sinh thường nhận được lợi ích từ các phản hồi định kỳ, đặc biệt là khi giáo viên cung cấp hướng dẫn rõ ràng để cải thiện bài làm.","audioKind":"ex2"}],"collocations":[{"en":"normally expect","vi":"thường mong đợi"},{"en":"function normally","vi":"hoạt động bình thường"},{"en":"breathe normally","vi":"thở bình thường"}],"wordFamily":["normal (adj.)","normality (n.)","abnormal (adj.)","abnormally (adv.)"],"synonyms":["usually","ordinarily"],"antonyms":["abnormally"],"tipVi":"Có thể dùng để chỉ tần suất \"thường xuyên\" hoặc trạng thái \"bình thường\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_disappear', 'en-a2-42', 'disappear', '/ˌdɪsəˈpɪr/', 'A2', 'biến mất; khuất tầm mắt; không còn tồn tại; tiêu vong', 'v.', 'disappearance (n.), appear (v.), appearance (n.)', 'Đồng nghĩa: vanish · Trái nghĩa: appear', 'Thường là nội động từ, không dùng cấu trúc bị động như be disappeared.', 'We watched the boat disappear into the thick fog.', NULL, 'Chúng tôi đứng nhìn con thuyền khuất dạng trong làn sương mù dày đặc.', '{"wordId":"disappear","ukIpa":"/ˌdɪsəˈpɪə/","usIpa":"/ˌdɪsəˈpɪr/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To become impossible to see or find.","vi":"biến mất; khuất tầm mắt"},{"pos":"v.","en":"To stop existing.","vi":"không còn tồn tại; tiêu vong"}],"examples":[{"en":"We watched the boat disappear into the thick fog.","vi":"Chúng tôi đứng nhìn con thuyền khuất dạng trong làn sương mù dày đặc.","audioKind":"ex"},{"en":"Many traditional crafts may disappear unless governments support skilled workers and encourage younger generations to learn them.","vi":"Nhiều nghề thủ công truyền thống có thể biến mất trừ khi chính phủ hỗ trợ những người thợ lành nghề và khuyến khích thế hệ trẻ học hỏi.","audioKind":"ex2"}],"collocations":[{"en":"disappear from view","vi":"biến mất khỏi tầm mắt"},{"en":"disappear without a trace","vi":"biến mất không một dấu vết"},{"en":"disappear completely","vi":"biến mất hoàn toàn"}],"wordFamily":["disappearance (n.)","appear (v.)","appearance (n.)"],"synonyms":["vanish"],"antonyms":["appear"],"tipVi":"Thường là nội động từ, không dùng cấu trúc bị động như be disappeared.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_push', 'en-a2-42', 'push', '/pʊʃ/', 'A2', 'đẩy; ấn; thúc đẩy; ép buộc; giục giã; sự thúc đẩy; nỗ lực quyết tâm', 'v.', 'pushy (adj.)', 'Trái nghĩa: pull', 'push là đẩy, pull là kéo; push for mang nghĩa đấu tranh lực lượng.', 'Could you push the trolley while I carry these bags?', NULL, 'Bạn có thể đẩy chiếc xe đẩy này trong lúc tôi xách những chiếc túi này không?', '{"wordId":"push","ukIpa":"/pʊʃ/","usIpa":"/pʊʃ/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to press something or move it away by applying force","vi":"đẩy; ấn"},{"pos":"v.","en":"to strongly encourage or force someone to act","vi":"thúc đẩy; ép buộc; giục giã"},{"pos":"n.","en":"an act of pushing or a determined effort","vi":"sự thúc đẩy; nỗ lực quyết tâm"}],"examples":[{"en":"Could you push the trolley while I carry these bags?","vi":"Bạn có thể đẩy chiếc xe đẩy này trong lúc tôi xách những chiếc túi này không?","audioKind":"ex"},{"en":"Schools should encourage academic progress without pushing students to compete constantly with their classmates.","vi":"Nhà trường nên khuyến khích sự tiến bộ trong học tập thay vì ép buộc học sinh phải liên tục cạnh tranh với bạn cùng lớp.","audioKind":"ex2"}],"collocations":[{"en":"push a button","vi":"bấm nút"},{"en":"push someone to do something","vi":"thúc giục ai đó làm gì"},{"en":"push for reform","vi":"đấu tranh cho cải cách"},{"en":"push up prices","vi":"đẩy giá lên cao"}],"wordFamily":["pushy (adj.)"],"synonyms":[],"antonyms":["pull"],"tipVi":"push là đẩy, pull là kéo; push for mang nghĩa đấu tranh lực lượng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_eighth', 'en-a2-42', 'eighth', '/eɪtθ/', 'A2', 'thứ tám; một phần tám', 'num.', 'eight (num.)', NULL, 'Trước số thứ tự thường có mạo từ the; âm cuối th trong eighth phát âm là /θ/.', 'Our apartment is on the eighth floor of this building.', NULL, 'Căn hộ của chúng tôi ở tầng tám của tòa nhà này.', '{"wordId":"eighth","ukIpa":"/eɪtθ/","usIpa":"/eɪtθ/","cefr":"A2","topic":"daily","senses":[{"pos":"num.","en":"Coming immediately after seventh in order","vi":"thứ tám"},{"pos":"n.","en":"One of eight equal parts of something","vi":"một phần tám"}],"examples":[{"en":"Our apartment is on the eighth floor of this building.","vi":"Căn hộ của chúng tôi ở tầng tám của tòa nhà này.","audioKind":"ex"},{"en":"The survey ranked public transport eighth among the factors influencing where young professionals choose to live.","vi":"Cuộc khảo sát xếp hạng giao thông công cộng ở vị trí thứ tám trong số các yếu tố ảnh hưởng đến việc lựa chọn nơi sinh sống của giới chuyên gia trẻ tuổi.","audioKind":"ex2"}],"collocations":[{"en":"the eighth floor","vi":"tầng tám"},{"en":"eighth place","vi":"vị trí thứ tám"},{"en":"one eighth of","vi":"một phần tám của"}],"wordFamily":["eight (num.)"],"synonyms":[],"antonyms":[],"tipVi":"Trước số thứ tự thường có mạo từ the; âm cuối th trong eighth phát âm là /θ/.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_luckily', 'en-a2-42', 'luckily', '/ˈlʌkɪli/', 'A2', 'may mắn thay; ơn giời; thật may là', 'adv.', 'luck (n.), lucky (adj.), unlucky (adj.), unluckily (adv.)', 'Đồng nghĩa: fortunately · Trái nghĩa: unfortunately, unluckily', 'Thường dùng để bổ nghĩa cho cả câu, khi đứng đầu câu thường đi kèm dấu phẩy.', 'My bag fell open, but luckily nothing dropped out.', NULL, 'Túi của tôi bị bục ra nhưng may mắn là không có gì rơi ra ngoài.', '{"wordId":"luckily","ukIpa":"/ˈlʌkɪli/","usIpa":"/ˈlʌkɪli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"By good fortune, often avoiding an unpleasant result.","vi":"may mắn thay; ơn giời; thật may là"}],"examples":[{"en":"My bag fell open, but luckily nothing dropped out.","vi":"Túi của tôi bị bục ra nhưng may mắn là không có gì rơi ra ngoài.","audioKind":"ex"},{"en":"The storm damaged several classrooms, but luckily the school had already moved its students to a safer building.","vi":"Cơn bão đã làm hư hại một số phòng học, nhưng may mắn là nhà trường đã chuyển học sinh đến một tòa nhà an toàn hơn từ trước.","audioKind":"ex2"}],"collocations":[{"en":"luckily for us","vi":"thật may mắn cho chúng tôi"},{"en":"luckily enough","vi":"rất may là"},{"en":"luckily no one was hurt","vi":"may mắn là không ai bị thương"}],"wordFamily":["luck (n.)","lucky (adj.)","unlucky (adj.)","unluckily (adv.)"],"synonyms":["fortunately"],"antonyms":["unfortunately","unluckily"],"tipVi":"Thường dùng để bổ nghĩa cho cả câu, khi đứng đầu câu thường đi kèm dấu phẩy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lovely', 'en-a2-42', 'lovely', '/ˈlʌvli/', 'A2', 'đẹp đẽ; dễ thương; xinh xắn; đáng yêu; tuyệt vời; dễ chịu', 'adj.', 'loveliness (n.)', 'Đồng nghĩa: beautiful, delightful, pleasant · Trái nghĩa: unpleasant', 'Mặc dù tận cùng bằng -ly nhưng đây là tính từ; loại từ này rất phổ biến trong văn nói tiếng Anh-Anh.', 'There are lovely yellow flowers beside the kitchen window.', NULL, 'Có những bông hoa vàng xinh xắn ở bên cửa sổ nhà bếp.', '{"wordId":"lovely","ukIpa":"/ˈlʌvli/","usIpa":"/ˈlʌvli/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"beautiful or attractive in a pleasing way","vi":"đẹp đẽ; dễ thương; xinh xắn"},{"pos":"adj.","en":"very pleasant, enjoyable, or kind","vi":"đáng yêu; tuyệt vời; dễ chịu"}],"examples":[{"en":"There are lovely yellow flowers beside the kitchen window.","vi":"Có những bông hoa vàng xinh xắn ở bên cửa sổ nhà bếp.","audioKind":"ex"},{"en":"Preserving lovely coastal landscapes can attract visitors while giving local residents valuable spaces for outdoor recreation.","vi":"Việc bảo tồn cảnh quan bờ biển tuyệt đẹp có thể thu hút du khách đồng thời mang lại cho người dân địa phương không gian quý giá để giải trí ngoài trời.","audioKind":"ex2"}],"collocations":[{"en":"a lovely view","vi":"cảnh đẹp"},{"en":"have a lovely time","vi":"có khoảng thời gian tuyệt vời"},{"en":"a lovely person","vi":"một người tốt bụng và dễ mến"}],"wordFamily":["loveliness (n.)"],"synonyms":["beautiful","delightful","pleasant"],"antonyms":["unpleasant"],"tipVi":"Mặc dù tận cùng bằng -ly nhưng đây là tính từ; loại từ này rất phổ biến trong văn nói tiếng Anh-Anh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_avoid', 'en-a2-42', 'avoid', '/əˈvɔɪd/', 'A2', 'tránh; ngăn chặn; tránh xa; né tránh', 'v.', 'avoidable (adj.), unavoidable (adj.), avoidance (n.)', 'Đồng nghĩa: evade, steer clear of · Trái nghĩa: confront', 'Theo sau là danh từ hoặc danh động từ: avoid doing, không dùng to do.', 'We left early to avoid the morning traffic.', NULL, 'Chúng tôi đi sớm để tránh tình trạng ùn tắc giao thông buổi sáng.', '{"wordId":"avoid","ukIpa":"/əˈvɔɪd/","usIpa":"/əˈvɔɪd/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to prevent something from happening or refrain from doing something","vi":"tránh; ngăn chặn"},{"pos":"v.","en":"to stay away from someone or something","vi":"tránh xa; né tránh"}],"examples":[{"en":"We left early to avoid the morning traffic.","vi":"Chúng tôi đi sớm để tránh tình trạng ùn tắc giao thông buổi sáng.","audioKind":"ex"},{"en":"Cities should improve public transport to avoid further increases in traffic congestion and air pollution.","vi":"Các thành phố nên cải thiện giao thông công cộng để tránh tình trạng ùn tắc giao thông và ô nhiễm không khí gia tăng hơn nữa.","audioKind":"ex2"}],"collocations":[{"en":"avoid doing something","vi":"tránh làm điều gì đó"},{"en":"avoid mistakes","vi":"tránh mắc lỗi"},{"en":"avoid contact","vi":"tránh tiếp xúc"}],"wordFamily":["avoidable (adj.)","unavoidable (adj.)","avoidance (n.)"],"synonyms":["evade","steer clear of"],"antonyms":["confront"],"tipVi":"Theo sau là danh từ hoặc danh động từ: avoid doing, không dùng to do.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lemon', 'en-a2-42', 'lemon', '/ˈlemən/', 'A2', 'quả chanh; màu vàng chanh; màu vàng nhạt', 'n.', NULL, NULL, 'Toàn bộ quả chanh là danh từ đếm được; nước cốt chanh trong lemon juice là danh từ không đếm được.', 'I squeezed half a lemon over the grilled fish.', NULL, 'Tôi vắt nửa quả chanh lên món cá nướng.', '{"wordId":"lemon","ukIpa":"/ˈlemən/","usIpa":"/ˈlemən/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a yellow citrus fruit with sour juice","vi":"quả chanh"},{"pos":"adj.","en":"having a pale yellow colour","vi":"màu vàng chanh; màu vàng nhạt"}],"examples":[{"en":"I squeezed half a lemon over the grilled fish.","vi":"Tôi vắt nửa quả chanh lên món cá nướng.","audioKind":"ex"},{"en":"Adding lemon juice to meals can improve flavour without increasing the amount of salt consumed.","vi":"Việc thêm nước cốt chanh vào món ăn có thể cải thiện hương vị mà không làm tăng lượng muối tiêu thụ.","audioKind":"ex2"}],"collocations":[{"en":"lemon juice","vi":"nước cốt chanh"},{"en":"a slice of lemon","vi":"một lát chanh"},{"en":"lemon zest","vi":"vỏ chanh bào"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Toàn bộ quả chanh là danh từ đếm được; nước cốt chanh trong lemon juice là danh từ không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_forever', 'en-a2-42', 'forever', '/fərˈevər/', 'A2', 'mãi mãi; đời đời; vĩnh viễn; luôn luôn; suốt ngày (thường mang ý phàn nàn)', 'adv.', NULL, 'Đồng nghĩa: everlastingly, permanently · Trái nghĩa: temporarily', 'Cấu trúc be forever doing thường diễn tả sự bất mãn: cứ mãi làm việc gì đó.', 'I wish these sunny afternoons could last forever.', NULL, 'Tôi ước gì những buổi chiều đầy nắng này có thể kéo dài mãi mãi.', '{"wordId":"forever","ukIpa":"/fəˈrevə/","usIpa":"/fərˈevər/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"for all future time","vi":"mãi mãi; đời đời; vĩnh viễn"},{"pos":"adv.","en":"very often, especially in an annoying way","vi":"luôn luôn; suốt ngày (thường mang ý phàn nàn)"}],"examples":[{"en":"I wish these sunny afternoons could last forever.","vi":"Tôi ước gì những buổi chiều đầy nắng này có thể kéo dài mãi mãi.","audioKind":"ex"},{"en":"Without effective conservation measures, some rare animal species could disappear forever within the next few decades.","vi":"Nếu không có các biện pháp bảo tồn hiệu quả, một số loài động vật quý hiếm có thể biến mất vĩnh viễn trong vài thập kỷ tới.","audioKind":"ex2"}],"collocations":[{"en":"last forever","vi":"kéo dài mãi mãi"},{"en":"gone forever","vi":"mất đi vĩnh viễn"},{"en":"forever changing","vi":"thay đổi không ngừng"}],"wordFamily":[],"synonyms":["everlastingly","permanently"],"antonyms":["temporarily"],"tipVi":"Cấu trúc be forever doing thường diễn tả sự bất mãn: cứ mãi làm việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_lock', 'en-a2-42', 'lock', '/lɑːk/', 'A2', 'khóa; khóa chặt; ổ khóa; một lọn tóc; một túm tóc', 'v.', 'unlock (v.), locked (adj.), lockable (adj.)', 'Trái nghĩa: unlock', 'lock là khóa lại, unlock là mở khóa; cả hai không thể dùng thay thế cho nhau.', 'Please lock the back door before you go upstairs.', NULL, 'Xin hãy khóa cửa sau lại trước khi bạn lên lầu.', '{"wordId":"lock","ukIpa":"/lɒk/","usIpa":"/lɑːk/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to secure something so it cannot open, move, or be accessed","vi":"khóa; khóa chặt"},{"pos":"n.","en":"a device that keeps something shut until opened correctly","vi":"ổ khóa"},{"pos":"n.","en":"a small section of someone''s hair","vi":"một lọn tóc; một túm tóc"}],"examples":[{"en":"Please lock the back door before you go upstairs.","vi":"Xin hãy khóa cửa sau lại trước khi bạn lên lầu.","audioKind":"ex"},{"en":"Employees should lock their computers whenever they leave their desks to prevent unauthorised access to confidential information.","vi":"Nhân viên nên khóa máy tính của họ bất cứ khi nào họ rời khỏi bàn làm việc để ngăn chặn việc truy cập trái phép vào thông tin bảo mật.","audioKind":"ex2"}],"collocations":[{"en":"lock the door","vi":"khóa cửa"},{"en":"lock the screen","vi":"khóa màn hình"},{"en":"a door lock","vi":"ổ khóa cửa"},{"en":"a lock of hair","vi":"một lọn tóc"}],"wordFamily":["unlock (v.)","locked (adj.)","lockable (adj.)"],"synonyms":[],"antonyms":["unlock"],"tipVi":"lock là khóa lại, unlock là mở khóa; cả hai không thể dùng thay thế cho nhau.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_curly', 'en-a2-42', 'curly', '/ˈkɜːrli/', 'A2', 'quăn; xoăn; uốn lượn', 'adj.', 'curl (n.), curl (v.)', 'Đồng nghĩa: curled · Trái nghĩa: straight', 'curly chỉ độ xoăn rõ rệt; wavy thường chỉ dạng gợn sóng nhẹ nhàng.', 'Her curly hair bounced as she ran upstairs.', NULL, 'Mái tóc xoăn của cô ấy nảy lên theo từng bước chân khi cô chạy lên lầu.', '{"wordId":"curly","ukIpa":"/ˈkɜːli/","usIpa":"/ˈkɜːrli/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"forming curls or curved shapes, especially when describing hair","vi":"quăn; xoăn; uốn lượn"}],"examples":[{"en":"Her curly hair bounced as she ran upstairs.","vi":"Mái tóc xoăn của cô ấy nảy lên theo từng bước chân khi cô chạy lên lầu.","audioKind":"ex"},{"en":"Advertising should represent people with diverse appearances, including those with curly hair and different skin tones.","vi":"Quảng cáo nên thể hiện những người có ngoại hình đa dạng, bao gồm cả những người tóc xoăn và có màu da khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"curly hair","vi":"tóc xoăn"},{"en":"naturally curly","vi":"xoăn tự nhiên"},{"en":"a curly tail","vi":"chiếc đuôi cuộn tròn"}],"wordFamily":["curl (n.)","curl (v.)"],"synonyms":["curled"],"antonyms":["straight"],"tipVi":"curly chỉ độ xoăn rõ rệt; wavy thường chỉ dạng gợn sóng nhẹ nhàng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_narrow', 'en-a2-42', 'narrow', '/ˈnæroʊ/', 'A2', 'hẹp; chật; hạn chế; sát nút; sít sao; thu hẹp; làm hẹp lại', 'adj.', 'narrowly (adv.), narrowness (n.)', 'Trái nghĩa: wide, widen', 'narrow down có nghĩa là thu hẹp phạm vi lựa chọn, không dùng để chỉ đường xá bị thu hẹp.', 'The narrow path only allows us to walk single file.', NULL, 'Con đường hẹp chỉ cho phép chúng tôi đi thành một hàng dọc.', '{"wordId":"narrow","ukIpa":"/ˈnærəʊ/","usIpa":"/ˈnæroʊ/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"having little distance from one side to the other","vi":"hẹp; chật"},{"pos":"adj.","en":"limited in range or achieved by only a small margin","vi":"hạn chế; sát nút; sít sao"},{"pos":"v.","en":"to become or make something less wide or extensive","vi":"thu hẹp; làm hẹp lại"}],"examples":[{"en":"The narrow path only allows us to walk single file.","vi":"Con đường hẹp chỉ cho phép chúng tôi đi thành một hàng dọc.","audioKind":"ex"},{"en":"Governments should invest in rural schools to narrow the educational gap between urban and remote communities.","vi":"Chính phủ nên đầu tư vào các trường học ở nông thôn để thu hẹp khoảng cách giáo dục giữa các cộng đồng đô thị và vùng sâu vùng xa.","audioKind":"ex2"}],"collocations":[{"en":"a narrow street","vi":"một con đường hẹp"},{"en":"a narrow victory","vi":"một chiến thắng sít sao"},{"en":"narrow the gap","vi":"thu hẹp khoảng cách"},{"en":"narrow down the options","vi":"thu hẹp các lựa chọn"}],"wordFamily":["narrowly (adv.)","narrowness (n.)"],"synonyms":[],"antonyms":["wide","widen"],"tipVi":"narrow down có nghĩa là thu hẹp phạm vi lựa chọn, không dùng để chỉ đường xá bị thu hẹp.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_anymore', 'en-a2-42', 'anymore', '/ˌeniˈmɔːr/', 'A2', 'nữa; không... nữa', 'adv.', NULL, 'Đồng nghĩa: any longer', 'Dùng để chỉ việc không còn tiếp tục; trong tiếng Anh-Anh thường viết là any more, khi chỉ số lượng "nhiều hơn" thì phải viết thành hai từ riêng biệt.', 'I don''t take the bus to school anymore.', NULL, 'Tôi không đi xe buýt đến trường nữa.', '{"wordId":"anymore","ukIpa":"/ˌeniˈmɔː/","usIpa":"/ˌeniˈmɔːr/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"Any longer, usually in negative statements.","vi":"nữa; không... nữa"}],"examples":[{"en":"I don''t take the bus to school anymore.","vi":"Tôi không đi xe buýt đến trường nữa.","audioKind":"ex"},{"en":"Many employees do not commute every day anymore because their employers now offer flexible working arrangements.","vi":"Nhiều nhân viên không còn phải đi lại làm việc mỗi ngày nữa vì người sử dụng lao động hiện nay cung cấp các hình thức làm việc linh hoạt.","audioKind":"ex2"}],"collocations":[{"en":"not live here anymore","vi":"không còn sống ở đây nữa"},{"en":"not need it anymore","vi":"không còn cần nó nữa"}],"wordFamily":[],"synonyms":["any longer"],"antonyms":[],"tipVi":"Dùng để chỉ việc không còn tiếp tục; trong tiếng Anh-Anh thường viết là any more, khi chỉ số lượng \"nhiều hơn\" thì phải viết thành hai từ riêng biệt.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_tenth', 'en-a2-42', 'tenth', '/tenθ/', 'A2', 'thứ mười; một phần mười', 'num.', 'ten (num.), tenthly (adv.)', NULL, 'Thứ mười thường dùng the tenth; một phần mười dùng a tenth.', 'Our apartment is on the tenth floor of this building.', NULL, 'Căn hộ của chúng tôi nằm ở tầng mười của tòa nhà này.', '{"wordId":"tenth","ukIpa":"/tenθ/","usIpa":"/tenθ/","cefr":"A2","topic":"daily","senses":[{"pos":"num.","en":"in the position after ninth and before eleventh","vi":"thứ mười"},{"pos":"n.","en":"one of ten equal parts of something","vi":"một phần mười"}],"examples":[{"en":"Our apartment is on the tenth floor of this building.","vi":"Căn hộ của chúng tôi nằm ở tầng mười của tòa nhà này.","audioKind":"ex"},{"en":"Only a tenth of the survey participants regularly cycled to work, suggesting considerable scope for improving cycling infrastructure.","vi":"Chỉ có một phần mười số người tham gia khảo sát thường xuyên đi xe đạp đi làm, cho thấy vẫn còn nhiều dư địa để cải thiện cơ sở hạ tầng dành cho xe đạp.","audioKind":"ex2"}],"collocations":[{"en":"the tenth floor","vi":"tầng thứ mười"},{"en":"a tenth of","vi":"một phần mười của"},{"en":"tenth place","vi":"vị trí thứ mười"}],"wordFamily":["ten (num.)","tenthly (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"Thứ mười thường dùng the tenth; một phần mười dùng a tenth.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_42_1', 'en-a2-42', 'Cách dùng “anymore” (adv.) — nữa; không... nữa', 'not live here anymore  ·  not need it anymore', 'Dùng để chỉ việc không còn tiếp tục; trong tiếng Anh-Anh thường viết là any more, khi chỉ số lượng "nhiều hơn" thì phải viết thành hai từ riêng biệt.', 'Đồng nghĩa: any longer', '[{"hanzi":"I don''t take the bus to school anymore.","pinyin":"","meaning":"Tôi không đi xe buýt đến trường nữa."},{"hanzi":"Many employees do not commute every day anymore because their employers now offer flexible working arrangements.","pinyin":"","meaning":"Nhiều nhân viên không còn phải đi lại làm việc mỗi ngày nữa vì người sử dụng lao động hiện nay cung cấp các hình thức làm việc linh hoạt."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_42_2', 'en-a2-42', 'Cách dùng “lovely” (adj.) — đẹp đẽ; dễ thương; xinh xắn', 'a lovely view  ·  have a lovely time  ·  a lovely person', 'Mặc dù tận cùng bằng -ly nhưng đây là tính từ; loại từ này rất phổ biến trong văn nói tiếng Anh-Anh.', 'Họ từ (Word Family): loveliness (n.) | Đồng nghĩa: beautiful, delightful, pleasant · Trái nghĩa: unpleasant', '[{"hanzi":"There are lovely yellow flowers beside the kitchen window.","pinyin":"","meaning":"Có những bông hoa vàng xinh xắn ở bên cửa sổ nhà bếp."},{"hanzi":"Preserving lovely coastal landscapes can attract visitors while giving local residents valuable spaces for outdoor recreation.","pinyin":"","meaning":"Việc bảo tồn cảnh quan bờ biển tuyệt đẹp có thể thu hút du khách đồng thời mang lại cho người dân địa phương không gian quý giá để giải trí ngoài trời."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_42_3', 'en-a2-42', 'Cách dùng “tie” (v.) — buộc; cột; thắt', 'tie a knot  ·  wear a tie  ·  family ties', 'Dạng phân từ hiện tại của tie là tying; khi chỉ mối quan hệ, từ này thường dùng ở số nhiều là ties.', 'Họ từ (Word Family): untie (v.) | Đồng nghĩa: fasten, bind · Trái nghĩa: untie', '[{"hanzi":"Please tie your shoelaces before you run outside.","pinyin":"","meaning":"Hãy thắt dây giày của bạn trước khi chạy ra ngoài."},{"hanzi":"Strong ties between schools and local employers can help young people make a smoother transition into work.","pinyin":"","meaning":"Mối quan hệ gắn bó giữa các trường học và nhà tuyển dụng địa phương có thể giúp người trẻ bước chân vào môi trường làm việc một cách suôn sẻ hơn."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_42_4', 'en-a2-42', 'Cách dùng “lemon” (n.) — quả chanh', 'lemon juice  ·  a slice of lemon  ·  lemon zest', 'Toàn bộ quả chanh là danh từ đếm được; nước cốt chanh trong lemon juice là danh từ không đếm được.', NULL, '[{"hanzi":"I squeezed half a lemon over the grilled fish.","pinyin":"","meaning":"Tôi vắt nửa quả chanh lên món cá nướng."},{"hanzi":"Adding lemon juice to meals can improve flavour without increasing the amount of salt consumed.","pinyin":"","meaning":"Việc thêm nước cốt chanh vào món ăn có thể cải thiện hương vị mà không làm tăng lượng muối tiêu thụ."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_42_1', 'en-a2-42', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_42_1_1', 'ten_a2_42_1', 'beside', 'Please leave your wet boots beside the door.', 'Please leave your wet boots beside the door.', '/bɪˈsaɪd/', 'Làm ơn để đôi ủng ướt của bạn ở bên cạnh cửa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_42_1_2', 'ten_a2_42_1', 'tie', 'Please tie your shoelaces before you run outside.', 'Please tie your shoelaces before you run outside.', '/taɪ/', 'Hãy thắt dây giày của bạn trước khi chạy ra ngoài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_42_1_3', 'ten_a2_42_1', 'including', 'Everyone came to the picnic, including our new neighbours.', 'Everyone came to the picnic, including our new neighbours.', '/ɪnˈkluːdɪŋ/', 'Mọi người đều đến buổi dã ngoại, kể cả những người hàng xóm mới của chúng ta.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_42_1_4', 'ten_a2_42_1', 'tiny', 'A tiny frog jumped out of the flower pot.', 'A tiny frog jumped out of the flower pot.', '/ˈtaɪni/', 'Một chú ếch tí hon từ trong chậu hoa nhảy ra.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_42_1_5', 'ten_a2_42_1', 'naughty', 'The naughty puppy dragged my slippers into the garden.', 'The naughty puppy dragged my slippers into the garden.', '/ˈnɔːti/', 'Chú chó con nghịch ngợm đã lôi đôi dép của tôi vào khu vườn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
