INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_42_1_8', 'ten_a2_42_1', 'actually', 'I thought this soup was spicy, but it is actually sweet.', 'I thought this soup was spicy, but it is actually sweet.', '/ˈæktʃuəli/', 'Tôi cứ nghĩ món súp này cay, nhưng thực ra nó có vị ngọt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_42_1_1', 'en-a2-42', 'ten_a2_42_1', 'listening', 'listening', 'Please leave your wet boots beside the door.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi không đi xe buýt đến trường nữa.","Con đường hẹp chỉ cho phép chúng tôi đi thành một hàng dọc.","Làm ơn để đôi ủng ướt của bạn ở bên cạnh cửa.","Bạn có thể đẩy chiếc xe đẩy này trong lúc tôi xách những chiếc túi này không?"]'::jsonb, 2, 'Please leave your wet boots beside the door. → Làm ơn để đôi ủng ướt của bạn ở bên cạnh cửa.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_42_1_2', 'en-a2-42', 'ten_a2_42_1', 'listening', 'listening', 'Please tie your shoelaces before you run outside.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Hãy thắt dây giày của bạn trước khi chạy ra ngoài.","Mọi người đều đến buổi dã ngoại, kể cả những người hàng xóm mới của chúng ta.","Cô ấy cắt một quả dưa chín để chúng tôi ăn trong buổi dã ngoại.","Anh ấy quấn một chiếc khăn ấm quanh đôi vai đang ướt của mình."]'::jsonb, 0, 'Please tie your shoelaces before you run outside. → Hãy thắt dây giày của bạn trước khi chạy ra ngoài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_42_1_3', 'en-a2-42', 'ten_a2_42_1', 'listening', 'listening', 'Everyone came to the picnic, including our new neighbours.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Quả bóng đập vào hàng rào và nảy về phía tôi.","Mọi người đều đến buổi dã ngoại, kể cả những người hàng xóm mới của chúng ta.","Hãy thắt dây giày của bạn trước khi chạy ra ngoài.","Chúng tôi đóng gói thùng hàng cuối cùng và khóa cửa lại."]'::jsonb, 1, 'Everyone came to the picnic, including our new neighbours. → Mọi người đều đến buổi dã ngoại, kể cả những người hàng xóm mới của chúng ta.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_42_2', 'en-a2-42', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_42_2_1', 'ten_a2_42_2', 'beside', 'Creating walking paths beside urban rivers can encourage physical activity and improve residents'' access to nature.', 'Creating walking paths beside urban rivers can encourage physical activity and improve residents'' access to nature.', '/bɪˈsaɪd/', 'Việc xây dựng các lối đi bộ bên cạnh các con sông trong thành phố có thể khuyến khích hoạt động thể chất và giúp người dân tiếp cận thiên nhiên dễ dàng hơn.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_42_2_2', 'ten_a2_42_2', 'tie', 'Strong ties between schools and local employers can help young people make a smoother transition into work.', 'Strong ties between schools and local employers can help young people make a smoother transition into work.', '/taɪ/', 'Mối quan hệ gắn bó giữa các trường học và nhà tuyển dụng địa phương có thể giúp người trẻ bước chân vào môi trường làm việc một cách suôn sẻ hơn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_42_2_3', 'ten_a2_42_2', 'including', 'Cities should provide accessible public spaces for all residents, including older people and those with limited mobility.', 'Cities should provide accessible public spaces for all residents, including older people and those with limited mobility.', '/ɪnˈkluːdɪŋ/', 'Các thành phố nên cung cấp không gian công cộng dễ tiếp cận cho tất cả cư dân, bao gồm cả người cao tuổi và những người có khả năng vận động hạn chế.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_42_2_4', 'ten_a2_42_2', 'tiny', 'Even tiny changes in daily habits can reduce household energy consumption over time.', 'Even tiny changes in daily habits can reduce household energy consumption over time.', '/ˈtaɪni/', 'Ngay cả những thay đổi nhỏ bé trong thói quen sinh hoạt hàng ngày cũng có thể làm giảm lượng tiêu thụ năng lượng của hộ gia đình theo thời gian.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_42_2_5', 'ten_a2_42_2', 'naughty', 'Children described as naughty may benefit more from patient guidance than from repeated punishment.', 'Children described as naughty may benefit more from patient guidance than from repeated punishment.', '/ˈnɔːti/', 'Những đứa trẻ được mô tả là nghịch ngợm có thể nhận được nhiều lợi ích hơn từ sự hướng dẫn kiên nhẫn thay vì bị phạt lặp đi lặp lại.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_42_2_6', 'ten_a2_42_2', 'final', 'The final stage of the research involved comparing energy consumption across several types of housing.', 'The final stage of the research involved comparing energy consumption across several types of housing.', '/ˈfaɪnəl/', 'Giai đoạn cuối cùng của nghiên cứu liên quan đến việc so sánh mức tiêu thụ năng lượng giữa một số loại nhà ở.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_42_2_1', 'en-a2-42', 'ten_a2_42_2', 'listening', 'listening', 'Creating walking paths beside urban rivers can encourage physical activity and improve residents'' access to nature.', NULL, 'Trong câu vừa nghe, từ “beside” mang nghĩa nào sau đây?', '["thuộc về Thái Lan, người Thái hoặc tiếng Thái","tủ lạnh; tủ cấp đông","ở bên cạnh; sát bên","xúc xích"]'::jsonb, 2, '“beside” (/bɪˈsaɪd/): ở bên cạnh; sát bên. Câu đầy đủ: Creating walking paths beside urban rivers can encourage physical activity and improve residents'' access to nature.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_42_2_2', 'en-a2-42', 'ten_a2_42_2', 'listening', 'listening', 'Strong ties between schools and local employers can help young people make a smoother transition into work.', NULL, 'Trong câu vừa nghe, từ “tie” mang nghĩa nào sau đây?', '["khô; ráo","thợ xây dựng; nhà thầu xây dựng","buộc; cột; thắt","dầu gội đầu"]'::jsonb, 2, '“tie” (/taɪ/): buộc; cột; thắt. Câu đầy đủ: Strong ties between schools and local employers can help young people make a smoother transition into work.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
