INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_42_2', 'en-a2-42', NULL, 'comprehensive_test', 'listening', 'Please tie your shoelaces before you run outside.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi không đi xe buýt đến trường nữa.","Hãy thắt dây giày của bạn trước khi chạy ra ngoài.","Tôi vắt nửa quả chanh lên món cá nướng.","Túi của tôi bị bục ra nhưng may mắn là không có gì rơi ra ngoài."]'::jsonb, 1, 'Please tie your shoelaces before you run outside. → Hãy thắt dây giày của bạn trước khi chạy ra ngoài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_42_3', 'en-a2-42', NULL, 'comprehensive_test', 'listening', 'including', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["kỹ năng; kỹ xảo; sự khéo léo","bao gồm; kể cả","người đọc (đặc biệt là sách, báo hoặc tạp chí)","thang máy; máy nâng"]'::jsonb, 1, 'including (/ɪnˈkluːdɪŋ/) → bao gồm; kể cả', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_42_4', 'en-a2-42', NULL, 'comprehensive_test', 'listening', 'A tiny frog jumped out of the flower pot.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Túi của tôi bị bục ra nhưng may mắn là không có gì rơi ra ngoài.","Một chú ếch tí hon từ trong chậu hoa nhảy ra.","Chúng tôi đứng nhìn con thuyền khuất dạng trong làn sương mù dày đặc.","Chúng tôi đi sớm để tránh tình trạng ùn tắc giao thông buổi sáng."]'::jsonb, 1, 'A tiny frog jumped out of the flower pot. → Một chú ếch tí hon từ trong chậu hoa nhảy ra.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_42_5', 'en-a2-42', NULL, 'comprehensive_test', 'listening', 'naughty', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["đồng nghiệp; bạn đồng sự","rõ ràng; dễ hiểu","thùng rác; thùng đựng đồ","nghịch ngợm; hư đốn; không vâng lời"]'::jsonb, 3, 'naughty (/ˈnɔːti/) → nghịch ngợm; hư đốn; không vâng lời', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_42_6', 'en-a2-42', NULL, 'comprehensive_test', 'listening', 'We packed the final box and locked the door.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chúng tôi đứng nhìn con thuyền khuất dạng trong làn sương mù dày đặc.","Anh ấy quấn một chiếc khăn ấm quanh đôi vai đang ướt của mình.","Cô ấy cắt một quả dưa chín để chúng tôi ăn trong buổi dã ngoại.","Chúng tôi đóng gói thùng hàng cuối cùng và khóa cửa lại."]'::jsonb, 3, 'We packed the final box and locked the door. → Chúng tôi đóng gói thùng hàng cuối cùng và khóa cửa lại.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
