INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_42_8', 'en-a2-42', NULL, 'comprehensive_test', 'listening', 'I thought this soup was spicy, but it is actually sweet.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi cứ nghĩ món súp này cay, nhưng thực ra nó có vị ngọt.","Làm ơn để đôi ủng ướt của bạn ở bên cạnh cửa.","Xin hãy khóa cửa sau lại trước khi bạn lên lầu.","Tôi vắt nửa quả chanh lên món cá nướng."]'::jsonb, 0, 'I thought this soup was spicy, but it is actually sweet. → Tôi cứ nghĩ món súp này cay, nhưng thực ra nó có vị ngọt.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
