INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_42_18', 'en-a2-42', NULL, 'comprehensive_test', 'reading', NULL, 'Creating walking paths beside urban rivers can encourage physical activity and improve residents'' access to nature.', 'Dựa vào câu trên, từ “beside” có nghĩa phù hợp nhất là gì?', '["sút; đá bằng chân","việc bán hàng; sự giao dịch mua bán","ở bên cạnh; sát bên","nướng bằng lò"]'::jsonb, 2, 'beside: ở bên cạnh; sát bên. Dịch cả câu: Việc xây dựng các lối đi bộ bên cạnh các con sông trong thành phố có thể khuyến khích hoạt động thể chất và giúp người dân tiếp cận thiên nhiên dễ dàng hơn.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_42_19', 'en-a2-42', NULL, 'comprehensive_test', 'reading', NULL, 'Strong ties between schools and local employers can help young people make a smoother transition into work.', 'Dựa vào câu trên, từ “tie” có nghĩa phù hợp nhất là gì?', '["quản lý; giám đốc; người điều hành","buộc; cột; thắt","áp phích; tranh cổ động; hải báo","đánh bại; thắng"]'::jsonb, 1, 'tie: buộc; cột; thắt; cà vạt; mối liên hệ; mối quan hệ. Dịch cả câu: Mối quan hệ gắn bó giữa các trường học và nhà tuyển dụng địa phương có thể giúp người trẻ bước chân vào môi trường làm việc một cách suôn sẻ hơn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_42_20', 'en-a2-42', NULL, 'comprehensive_test', 'reading', NULL, 'Cities should provide accessible public spaces for all residents, including older people and those with limited mobility.', 'Dựa vào câu trên, từ “including” có nghĩa phù hợp nhất là gì?', '["bao gồm; kể cả","buổi hòa nhạc; buổi biểu diễn âm nhạc","môn toán; toán học","môn bóng đá"]'::jsonb, 0, 'including: bao gồm; kể cả. Dịch cả câu: Các thành phố nên cung cấp không gian công cộng dễ tiếp cận cho tất cả cư dân, bao gồm cả người cao tuổi và những người có khả năng vận động hạn chế.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_42_21', 'en-a2-42', NULL, 'comprehensive_test', 'reading', NULL, 'Even tiny changes in daily habits can reduce household energy consumption over time.', 'Dựa vào câu trên, từ “tiny” có nghĩa phù hợp nhất là gì?', '["nửa đêm; mười hai giờ đêm","thành công; có kết quả tốt","sắp xếp; chuẩn bị; bố trí","nhỏ xíu; tí hon; cực nhỏ"]'::jsonb, 3, 'tiny: nhỏ xíu; tí hon; cực nhỏ. Dịch cả câu: Ngay cả những thay đổi nhỏ bé trong thói quen sinh hoạt hàng ngày cũng có thể làm giảm lượng tiêu thụ năng lượng của hộ gia đình theo thời gian.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_42_22', 'en-a2-42', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “hẹp; chật”', '["allow","narrow","island","pot"]'::jsonb, 1, 'hẹp; chật → narrow (/ˈnæroʊ/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_42_23', 'en-a2-42', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “nữa; không... nữa”', '["playground","honey","anymore","balloon"]'::jsonb, 2, 'nữa; không... nữa → anymore (/ˌeniˈmɔːr/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_42_24', 'en-a2-42', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thứ mười”', '["nearly","tenth","pain","enemy"]'::jsonb, 1, 'thứ mười → tenth (/tenθ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-43', 'en', 'Bài 43: Đời sống hằng ngày (15) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '26 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2043, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_calendar', 'en-a2-43', 'calendar', '/ˈkæləndər/', 'A2', 'lịch; bảng lịch; lịch trình; hệ thống lịch; phép tính lịch', 'n.', NULL, NULL, 'calendar year chỉ một tháng một đến tháng mười hai, không đồng nghĩa với năm học.', 'I marked our camping weekend on the kitchen calendar.', NULL, 'Tôi đã đánh dấu cuối tuần đi cắm trại của chúng tôi lên cuốn lịch ở nhà bếp.', '{"wordId":"calendar","ukIpa":"/ˈkælɪndə/","usIpa":"/ˈkæləndər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A chart of dates or a schedule of events.","vi":"lịch; bảng lịch; lịch trình"},{"pos":"n.","en":"A system for dividing time into years, months, and days.","vi":"hệ thống lịch; phép tính lịch"}],"examples":[{"en":"I marked our camping weekend on the kitchen calendar.","vi":"Tôi đã đánh dấu cuối tuần đi cắm trại của chúng tôi lên cuốn lịch ở nhà bếp.","audioKind":"ex"},{"en":"Schools should publish an annual calendar so families can plan holidays around important educational events.","vi":"Các trường học nên công bố lịch trình hàng năm để các gia đình có thể sắp xếp kỳ nghỉ xung quanh các hoạt động giáo dục quan trọng.","audioKind":"ex2"}],"collocations":[{"en":"academic calendar","vi":"lịch học"},{"en":"calendar year","vi":"năm dương lịch"},{"en":"lunar calendar","vi":"âm lịch"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"calendar year chỉ một tháng một đến tháng mười hai, không đồng nghĩa với năm học.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_comb', 'en-a2-43', 'comb', '/koʊm/', 'A2', 'lược; chải tóc; lục soát kỹ lưỡng', 'n.', NULL, NULL, 'Chữ cái b cuối từ không phát âm; comb through diễn tả hành động tìm kiếm kỹ lưỡng.', 'She pulled a comb from her bag and tidied her hair.', NULL, 'Cô ấy lấy một chiếc lược trong túi ra và chải lại mái tóc của mình.', '{"wordId":"comb","ukIpa":"/kəʊm/","usIpa":"/koʊm/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A toothed tool used to arrange or tidy hair.","vi":"lược"},{"pos":"v.","en":"To tidy hair with a comb, or search an area thoroughly.","vi":"chải tóc; lục soát kỹ lưỡng"}],"examples":[{"en":"She pulled a comb from her bag and tidied her hair.","vi":"Cô ấy lấy một chiếc lược trong túi ra và chải lại mái tóc của mình.","audioKind":"ex"},{"en":"Volunteers combed the beach for plastic waste before the start of the summer tourist season.","vi":"Các tình nguyện viên đã lục soát kỹ lưỡng bãi biển để thu gom rác nhựa trước khi mùa du lịch hè bắt đầu.","audioKind":"ex2"}],"collocations":[{"en":"comb your hair","vi":"chải tóc của bạn"},{"en":"a fine-toothed comb","vi":"lược dày răng"},{"en":"comb through","vi":"lục soát kỹ lưỡng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái b cuối từ không phát âm; comb through diễn tả hành động tìm kiếm kỹ lưỡng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_noisy', 'en-a2-43', 'noisy', '/ˈnɔɪzi/', 'A2', 'ồn ào; náo nhiệt; ồn', 'adj.', 'noise (n.), noisily (adv.), noisiness (n.)', 'Đồng nghĩa: loud · Trái nghĩa: quiet, silent', 'noisy là tính từ, noise là danh từ; cần lưu ý không nhầm với nosy.', 'Our noisy washing machine woke everyone up this morning.', NULL, 'Chiếc máy giặt ồn ào của chúng tôi đã đánh thức mọi người vào sáng nay.', '{"wordId":"noisy","ukIpa":"/ˈnɔɪzi/","usIpa":"/ˈnɔɪzi/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"making a lot of loud or unpleasant sounds","vi":"ồn ào; náo nhiệt; ồn"}],"examples":[{"en":"Our noisy washing machine woke everyone up this morning.","vi":"Chiếc máy giặt ồn ào của chúng tôi đã đánh thức mọi người vào sáng nay.","audioKind":"ex"},{"en":"Living near noisy roads can affect sleep quality and increase stress among urban residents.","vi":"Sống gần những con đường ồn ào có thể ảnh hưởng đến chất lượng giấc ngủ và làm gia tăng mức độ căng thẳng ở cư dân thành thị.","audioKind":"ex2"}],"collocations":[{"en":"a noisy neighbour","vi":"hàng xóm ồn ào"},{"en":"a noisy environment","vi":"môi trường ồn ào"},{"en":"a noisy crowd","vi":"đám đông náo nhiệt"}],"wordFamily":["noise (n.)","noisily (adv.)","noisiness (n.)"],"synonyms":["loud"],"antonyms":["quiet","silent"],"tipVi":"noisy là tính từ, noise là danh từ; cần lưu ý không nhầm với nosy.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_secret', 'en-a2-43', 'secret', '/ˈsiːkrət/', 'A2', 'bí mật; giữ kín; điều bí mật; bí quyết; phương sách', 'adj.', 'secrecy (n.), secretly (adv.), secretive (adj.)', 'Đồng nghĩa: confidential, hidden · Trái nghĩa: public', 'Bí quyết thường dùng cấu trúc the secret to, theo sau to là danh từ hoặc danh động từ.', 'We planned a secret picnic for our grandparents.', NULL, 'Chúng tôi đã lên kế hoạch cho một buổi dã ngoại bí mật dành tặng ông bà.', '{"wordId":"secret","ukIpa":"/ˈsiːkrət/","usIpa":"/ˈsiːkrət/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Kept hidden from people who should not know.","vi":"bí mật; giữ kín"},{"pos":"n.","en":"Information known only to a limited group of people.","vi":"điều bí mật; bí mật"},{"pos":"n.","en":"An important way of achieving a particular result.","vi":"bí quyết; phương sách"}],"examples":[{"en":"We planned a secret picnic for our grandparents.","vi":"Chúng tôi đã lên kế hoạch cho một buổi dã ngoại bí mật dành tặng ông bà.","audioKind":"ex"},{"en":"Governments must balance the need to keep information secret with the public''s right to know.","vi":"Chính phủ phải cân bằng giữa nhu cầu giữ kín thông tin và quyền được biết của công chúng.","audioKind":"ex2"}],"collocations":[{"en":"keep a secret","vi":"giữ bí mật"},{"en":"in secret","vi":"một cách bí mật"},{"en":"secret information","vi":"thông tin mật"},{"en":"the secret to success","vi":"bí quyết thành công"}],"wordFamily":["secrecy (n.)","secretly (adv.)","secretive (adj.)"],"synonyms":["confidential","hidden"],"antonyms":["public"],"tipVi":"Bí quyết thường dùng cấu trúc the secret to, theo sau to là danh từ hoặc danh động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_sir', 'en-a2-43', 'sir', '/sɝː/', 'A2', 'thưa ông; thưa ngài; thầy (cách gọi lịch sự đối với nam giới hoặc thầy giáo); ngài (tước hiệu đặt trước tên của một hiệp sĩ hoặc nam tước)', 'n.', NULL, NULL, 'Tước hiệu hiệp sĩ dùng Sir kết hợp với tên hoặc họ tên đầy đủ, không dùng đơn độc với họ.', 'Excuse me, sir, you left your umbrella behind.', NULL, 'Xin lỗi ông, ông để quên ô kìa.', '{"wordId":"sir","ukIpa":"/sɜː/","usIpa":"/sɝː/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A polite way to address a man or male teacher.","vi":"thưa ông; thưa ngài; thầy (cách gọi lịch sự đối với nam giới hoặc thầy giáo)"},{"pos":"n.","en":"A title used before a knight''s or baronet''s name.","vi":"ngài (tước hiệu đặt trước tên của một hiệp sĩ hoặc nam tước)"}],"examples":[{"en":"Excuse me, sir, you left your umbrella behind.","vi":"Xin lỗi ông, ông để quên ô kìa.","audioKind":"ex"},{"en":"In some schools, students address male teachers as sir to show respect during lessons.","vi":"Ở một số trường học, học sinh gọi các thầy giáo là sir để bày tỏ sự tôn trọng trong giờ học.","audioKind":"ex2"}],"collocations":[{"en":"yes, sir","vi":"vâng, thưa ông"},{"en":"excuse me, sir","vi":"xin lỗi ông"},{"en":"Dear Sir","vi":"Kính gửi ông (lời xưng hô trong thư tín)"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Tước hiệu hiệp sĩ dùng Sir kết hợp với tên hoặc họ tên đầy đủ, không dùng đơn độc với họ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_silly', 'en-a2-43', 'silly', '/ˈsɪli/', 'A2', 'ngốc nghếch; ngây ngô; trò cười; ngớ ngẩn', 'adj.', 'silliness (n.)', 'Đồng nghĩa: foolish · Trái nghĩa: sensible', 'Sắc thái nhẹ hơn từ stupid, đôi khi chỉ sự vui đùa, không nghiêm túc.', 'It was silly to leave my umbrella at home.', NULL, 'Thật ngốc nghếch khi để quên ô ở nhà.', '{"wordId":"silly","ukIpa":"/ˈsɪli/","usIpa":"/ˈsɪli/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Showing poor judgment or a lack of sensible thought","vi":"ngốc nghếch; ngây ngô"},{"pos":"adj.","en":"Playfully funny in a way that is not serious","vi":"trò cười; ngớ ngẩn"}],"examples":[{"en":"It was silly to leave my umbrella at home.","vi":"Thật ngốc nghếch khi để quên ô ở nhà.","audioKind":"ex"},{"en":"Teachers should avoid calling any question silly, as this may discourage students from participating in class.","vi":"Giáo viên nên tránh gọi bất kỳ câu hỏi nào là ngớ ngẩn, vì điều này có thể làm học sinh nhụt chí tham gia lớp học.","audioKind":"ex2"}],"collocations":[{"en":"silly mistake","vi":"lỗi ngớ ngẩn"},{"en":"silly question","vi":"câu hỏi ngốc nghếch"},{"en":"silly joke","vi":"trò đùa nhảm nhí"},{"en":"feel silly","vi":"cảm thấy mình thật ngốc"}],"wordFamily":["silliness (n.)"],"synonyms":["foolish"],"antonyms":["sensible"],"tipVi":"Sắc thái nhẹ hơn từ stupid, đôi khi chỉ sự vui đùa, không nghiêm túc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_repair', 'en-a2-43', 'repair', '/rɪˈper/', 'A2', 'sửa chữa; tân trang; công việc sửa chữa; sự bảo dưỡng; cải thiện mối quan hệ; khắc phục tình huống', 'v.', 'repairable (adj.), irreparable (adj.), repairer (n.)', 'Đồng nghĩa: fix, mend · Trái nghĩa: damage', 'Cụ thể việc sửa chữa thường dùng dạng số nhiều repairs; beyond repair có nghĩa là không thể sửa chữa được nữa.', 'Can you repair the broken zip on my jacket?', NULL, 'Bạn có thể sửa giúp tôi chiếc khóa kéo bị hỏng trên áo khoác được không?', '{"wordId":"repair","ukIpa":"/rɪˈpeə/","usIpa":"/rɪˈper/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To make something damaged or broken work properly again","vi":"sửa chữa; tân trang"},{"pos":"n.","en":"Work done to restore something damaged or broken","vi":"công việc sửa chữa; sự bảo dưỡng"},{"pos":"v.","en":"To improve a damaged relationship or put a situation right","vi":"cải thiện mối quan hệ; khắc phục tình huống"}],"examples":[{"en":"Can you repair the broken zip on my jacket?","vi":"Bạn có thể sửa giúp tôi chiếc khóa kéo bị hỏng trên áo khoác được không?","audioKind":"ex"},{"en":"Encouraging consumers to repair household appliances rather than replace them could significantly reduce electronic waste.","vi":"Việc khuyến khích người tiêu dùng sửa chữa các thiết bị gia dụng thay vì mua mới có thể làm giảm đáng kể lượng rác thải điện tử.","audioKind":"ex2"}],"collocations":[{"en":"repair damage","vi":"sửa chữa hư hỏng"},{"en":"carry out repairs","vi":"tiến hành sửa chữa"},{"en":"beyond repair","vi":"hỏng hoàn toàn không thể sửa"},{"en":"in good repair","vi":"được bảo dưỡng tốt"}],"wordFamily":["repairable (adj.)","irreparable (adj.)","repairer (n.)"],"synonyms":["fix","mend"],"antonyms":["damage"],"tipVi":"Cụ thể việc sửa chữa thường dùng dạng số nhiều repairs; beyond repair có nghĩa là không thể sửa chữa được nữa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shut', 'en-a2-43', 'shut', '/ʃʌt/', 'A2', 'đóng; khép; ngừng hoạt động; đóng cửa; không mở cửa', 'v.', 'shutdown (n.)', 'Đồng nghĩa: close · Trái nghĩa: open', 'Dạng quá khứ và quá khứ phân từ đều là shut; phân từ hiện tại là shutting.', 'Please shut the window before the rain gets in.', NULL, 'Làm ơn đóng cửa sổ lại trước khi trời mưa hắt vào.', '{"wordId":"shut","ukIpa":"/ʃʌt/","usIpa":"/ʃʌt/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to close something or stop being open for business","vi":"đóng; khép; ngừng hoạt động"},{"pos":"adj.","en":"closed or not open for business","vi":"đóng cửa; không mở cửa"}],"examples":[{"en":"Please shut the window before the rain gets in.","vi":"Làm ơn đóng cửa sổ lại trước khi trời mưa hắt vào.","audioKind":"ex"},{"en":"When local libraries shut, residents lose valuable access to free learning resources and shared community spaces.","vi":"Khi các thư viện địa phương đóng cửa, người dân sẽ mất đi quyền tiếp cận quý giá với các nguồn tài nguyên học tập miễn phí và không gian sinh hoạt chung.","audioKind":"ex2"}],"collocations":[{"en":"shut the door","vi":"đóng cửa"},{"en":"shut your eyes","vi":"nhắm mắt"},{"en":"shut down a factory","vi":"đóng cửa một nhà máy"},{"en":"keep something shut","vi":"giữ cho vật gì đó đóng"}],"wordFamily":["shutdown (n.)"],"synonyms":["close"],"antonyms":["open"],"tipVi":"Dạng quá khứ và quá khứ phân từ đều là shut; phân từ hiện tại là shutting.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_myself', 'en-a2-43', 'myself', '/maɪˈself/', 'A2', 'chính tôi; bản thân tôi (tự làm và nhận tác động); tự mình; cá nhân tôi (nhấn mạnh hành động)', 'pron.', NULL, NULL, 'by myself có nghĩa là một mình hoặc độc lập; không được dùng myself để thay thế cho chủ ngữ I.', 'I made myself a sandwich before the walk.', NULL, 'Tôi đã tự làm cho mình một cái bánh mì kẹp trước khi đi dạo.', '{"wordId":"myself","ukIpa":"/maɪˈself/","usIpa":"/maɪˈself/","cefr":"A2","topic":"daily","senses":[{"pos":"pron.","en":"Used when I am both the person acting and receiving.","vi":"chính tôi; bản thân tôi (tự làm và nhận tác động)"},{"pos":"pron.","en":"Used to emphasize that I personally do something.","vi":"tự mình; cá nhân tôi (nhấn mạnh hành động)"}],"examples":[{"en":"I made myself a sandwich before the walk.","vi":"Tôi đã tự làm cho mình một cái bánh mì kẹp trước khi đi dạo.","audioKind":"ex"},{"en":"By volunteering at a community garden, I taught myself practical skills that formal education rarely provides.","vi":"Bằng cách làm tình nguyện viên tại khu vườn cộng đồng, tôi đã tự trau dồi cho mình những kỹ năng thực tế mà giáo dục chính quy hiếm khi cung cấp.","audioKind":"ex2"}],"collocations":[{"en":"by myself","vi":"tự mình; một mình"},{"en":"teach myself","vi":"tự học"},{"en":"enjoy myself","vi":"chơi vui vẻ; tự thưởng thức"},{"en":"not feel myself","vi":"cảm thấy không được khỏe; cảm thấy khác thường"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"by myself có nghĩa là một mình hoặc độc lập; không được dùng myself để thay thế cho chủ ngữ I.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_already', 'en-a2-43', 'already', '/ɔːlˈredi/', 'A2', 'đã; từ trước; đã từ lâu', 'adv.', NULL, NULL, 'Thường đứng sau trợ động từ và trước động từ chính; thể hiện sự việc đã xảy ra hoặc sớm hơn dự kiến.', 'I have already packed my bag for tomorrow.', NULL, 'Tôi đã sắp xếp xong hành lý cho ngày mai rồi.', '{"wordId":"already","ukIpa":"/ɔːlˈredi/","usIpa":"/ɔːlˈredi/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"before now or earlier than expected","vi":"đã; từ trước; đã từ lâu"}],"examples":[{"en":"I have already packed my bag for tomorrow.","vi":"Tôi đã sắp xếp xong hành lý cho ngày mai rồi.","audioKind":"ex"},{"en":"Many cities have already introduced cycling schemes to reduce traffic congestion and improve public health.","vi":"Nhiều thành phố đã triển khai các chương trình đi xe đạp nhằm giảm thiểu tình trạng ùn tắc giao thông và nâng cao sức khỏe cộng đồng.","audioKind":"ex2"}],"collocations":[{"en":"have already done","vi":"đã làm"},{"en":"already available","vi":"đã có sẵn"},{"en":"already in place","vi":"đã được thiết lập; đã đi vào hoạt động"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường đứng sau trợ động từ và trước động từ chính; thể hiện sự việc đã xảy ra hoặc sớm hơn dự kiến.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_closed', 'en-a2-43', 'closed', '/kloʊzd/', 'A2', 'đóng; khép; đóng cửa; ngừng hoạt động kinh doanh; bảo thủ; không chịu tiếp thu ý kiến mới', 'adj.', 'close (v.), closure (n.)', 'Đồng nghĩa: shut · Trái nghĩa: open', 'Là tính từ có nghĩa là "đóng"; đây đồng thời là dạng quá khứ và quá khứ phân từ của động từ close.', 'Keep the window closed while the heating is on.', NULL, 'Hãy giữ cho cửa sổ đóng khi đang bật máy sưởi.', '{"wordId":"closed","ukIpa":"/kləʊzd/","usIpa":"/kloʊzd/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"not open","vi":"đóng; khép"},{"pos":"adj.","en":"not available for business or public use","vi":"đóng cửa; ngừng hoạt động kinh doanh"},{"pos":"adj.","en":"unwilling to consider different ideas","vi":"bảo thủ; không chịu tiếp thu ý kiến mới"}],"examples":[{"en":"Keep the window closed while the heating is on.","vi":"Hãy giữ cho cửa sổ đóng khi đang bật máy sưởi.","audioKind":"ex"},{"en":"When local libraries remain closed at weekends, working families have fewer opportunities to access educational resources.","vi":"Khi các thư viện địa phương tiếp tục đóng cửa vào cuối tuần, các gia đình bận rộn sẽ có ít cơ hội tiếp cận với các nguồn tài nguyên giáo dục hơn.","audioKind":"ex2"}],"collocations":[{"en":"keep something closed","vi":"giữ cho vật gì đó đóng"},{"en":"closed for repairs","vi":"đóng cửa để sửa chữa"},{"en":"a closed mind","vi":"tư duy bảo thủ; sự khép kín trong suy nghĩ"}],"wordFamily":["close (v.)","closure (n.)"],"synonyms":["shut"],"antonyms":["open"],"tipVi":"Là tính từ có nghĩa là \"đóng\"; đây đồng thời là dạng quá khứ và quá khứ phân từ của động từ close.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_necklace', 'en-a2-43', 'necklace', '/ˈnekləs/', 'A2', 'dây chuyền; vòng cổ', 'n.', NULL, NULL, 'Đuôi -lace phát âm là /ləs/, khác với cách phát âm của từ đơn lace.', 'She wore a silver necklace with a tiny bird.', NULL, 'Cô ấy đeo một chiếc vòng cổ bằng bạc có đính hình chú chim nhỏ.', '{"wordId":"necklace","ukIpa":"/ˈnekləs/","usIpa":"/ˈnekləs/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a piece of jewellery worn around the neck","vi":"dây chuyền; vòng cổ"}],"examples":[{"en":"She wore a silver necklace with a tiny bird.","vi":"Cô ấy đeo một chiếc vòng cổ bằng bạc có đính hình chú chim nhỏ.","audioKind":"ex"},{"en":"A handmade necklace can reflect local traditions while providing income for craftspeople in rural communities.","vi":"Một chiếc vòng cổ thủ công vừa thể hiện nét văn hóa truyền thống vừa mang lại thu nhập cho thợ thủ công ở các vùng nông thôn.","audioKind":"ex2"}],"collocations":[{"en":"wear a necklace","vi":"đeo vòng cổ"},{"en":"a pearl necklace","vi":"vòng ngọc trai"},{"en":"a silver necklace","vi":"vòng cổ bằng bạc"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Đuôi -lace phát âm là /ləs/, khác với cách phát âm của từ đơn lace.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_soft', 'en-a2-43', 'soft', '/sɔːft/', 'A2', 'mềm; dễ uốn; êm dịu; nhẹ nhàng; không chói gắt; mềm mỏng; thiếu kiên quyết', 'adj.', 'soften (v.), softness (n.), softly (adv.)', 'Trái nghĩa: hard, harsh', 'soft là tính từ; khi bổ nghĩa cho hành động nói năng hoặc cử chỉ thường dùng phó từ softly.', 'This soft blanket keeps me warm on chilly evenings.', NULL, 'Chiếc chăn mềm mại này sưởi ấm tôi trong những đêm lạnh giá.', '{"wordId":"soft","ukIpa":"/sɒft/","usIpa":"/sɔːft/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"easy to press, bend, or change in shape","vi":"mềm; dễ uốn"},{"pos":"adj.","en":"gentle and not loud, bright, or harsh","vi":"êm dịu; nhẹ nhàng; không chói gắt"},{"pos":"adj.","en":"not strict or severe enough","vi":"mềm mỏng; thiếu kiên quyết"}],"examples":[{"en":"This soft blanket keeps me warm on chilly evenings.","vi":"Chiếc chăn mềm mại này sưởi ấm tôi trong những đêm lạnh giá.","audioKind":"ex"},{"en":"Soft lighting and comfortable furniture can make hospital waiting areas feel less stressful for patients.","vi":"Ánh sáng dịu nhẹ và nội thất thoải mái có thể giúp bệnh nhân giảm bớt căng thẳng khi chờ khám ở bệnh viện.","audioKind":"ex2"}],"collocations":[{"en":"soft skin","vi":"làn da mềm mại"},{"en":"a soft voice","vi":"giọng nói dịu dàng"},{"en":"soft lighting","vi":"ánh sáng dịu nhẹ"},{"en":"be soft on","vi":"quá dễ dãi với ai"}],"wordFamily":["soften (v.)","softness (n.)","softly (adv.)"],"synonyms":[],"antonyms":["hard","harsh"],"tipVi":"soft là tính từ; khi bổ nghĩa cho hành động nói năng hoặc cử chỉ thường dùng phó từ softly.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ordinary', 'en-a2-43', 'ordinary', '/ˈɔːrdəneri/', 'A2', 'bình thường; thông thường; không có gì đặc biệt', 'adj.', 'ordinarily (adv.), extraordinary (adj.)', 'Đồng nghĩa: normal, usual, unremarkable · Trái nghĩa: extraordinary, unusual', 'ordinary nhấn mạnh tính chất thông thường, không nổi bật; không đồng nghĩa với average (tính theo mức trung bình).', 'It looked like an ordinary box until we opened it.', NULL, 'Trông nó giống như một chiếc hộp bình thường cho đến khi chúng tôi mở ra.', '{"wordId":"ordinary","ukIpa":"/ˈɔːdənəri/","usIpa":"/ˈɔːrdəneri/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Normal or usual, without special or unusual features.","vi":"bình thường; thông thường; không có gì đặc biệt"}],"examples":[{"en":"It looked like an ordinary box until we opened it.","vi":"Trông nó giống như một chiếc hộp bình thường cho đến khi chúng tôi mở ra.","audioKind":"ex"},{"en":"Urban planning should reflect the needs of ordinary residents rather than focus exclusively on attracting wealthy investors.","vi":"Quy hoạch đô thị nên phản ánh nhu cầu của người dân bình thường thay vì chỉ tập trung thu hút giới đầu tư giàu có.","audioKind":"ex2"}],"collocations":[{"en":"ordinary people","vi":"người bình thường"},{"en":"ordinary life","vi":"cuộc sống bình thường"},{"en":"an ordinary day","vi":"một ngày bình thường"},{"en":"out of the ordinary","vi":"khác thường; lạ thường"}],"wordFamily":["ordinarily (adv.)","extraordinary (adj.)"],"synonyms":["normal","usual","unremarkable"],"antonyms":["extraordinary","unusual"],"tipVi":"ordinary nhấn mạnh tính chất thông thường, không nổi bật; không đồng nghĩa với average (tính theo mức trung bình).","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_finger', 'en-a2-43', 'finger', '/ˈfɪŋɡɚ/', 'A2', 'ngón tay; dùng ngón tay chạm; sờ', 'n.', 'fingertip (n.), fingernail (n.)', NULL, 'Thường không bao gồm ngón cái; ngón cái được gọi riêng là thumb.', 'She wore a silver ring on her middle finger.', NULL, 'Cô ấy đeo một chiếc nhẫn bạc ở ngón giữa.', '{"wordId":"finger","ukIpa":"/ˈfɪŋɡə/","usIpa":"/ˈfɪŋɡɚ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"one of the long movable parts of a hand","vi":"ngón tay"},{"pos":"v.","en":"to touch or handle something with your fingers","vi":"dùng ngón tay chạm; sờ"}],"examples":[{"en":"She wore a silver ring on her middle finger.","vi":"Cô ấy đeo một chiếc nhẫn bạc ở ngón giữa.","audioKind":"ex"},{"en":"Tasks requiring precise finger movements can help young children develop coordination before they learn to write.","vi":"Các bài tập đòi hỏi chuyển động ngón tay chính xác có thể giúp trẻ nhỏ phát triển khả năng phối hợp trước khi chúng học viết.","audioKind":"ex2"}],"collocations":[{"en":"index finger","vi":"ngón trỏ"},{"en":"middle finger","vi":"ngón giữa"},{"en":"point a finger at","vi":"chỉ trích ai đó; đổ lỗi"}],"wordFamily":["fingertip (n.)","fingernail (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Thường không bao gồm ngón cái; ngón cái được gọi riêng là thumb.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_slipper', 'en-a2-43', 'slipper', '/ˈslɪpɚ/', 'A2', 'dép đi trong nhà; giày đi trong nhà', 'n.', NULL, NULL, 'Thường dùng ở dạng số nhiều slippers; dép xỏ ngón thường được gọi là flip-flops.', 'I found my missing slipper underneath the sofa.', NULL, 'Tôi tìm thấy chiếc dép bị thất lạc của mình ở dưới gầm sofa.', '{"wordId":"slipper","ukIpa":"/ˈslɪpə/","usIpa":"/ˈslɪpɚ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A soft, comfortable shoe worn inside the home.","vi":"dép đi trong nhà; giày đi trong nhà"}],"examples":[{"en":"I found my missing slipper underneath the sofa.","vi":"Tôi tìm thấy chiếc dép bị thất lạc của mình ở dưới gầm sofa.","audioKind":"ex"},{"en":"Providing slippers in shared accommodation can improve comfort, although regular cleaning remains essential for good hygiene.","vi":"Việc cung cấp dép đi trong nhà ở các khu vực sinh hoạt chung có thể nâng cao sự thoải mái, mặc dù việc vệ sinh định kỳ vẫn là yếu tố thiết yếu để đảm bảo vệ sinh.","audioKind":"ex2"}],"collocations":[{"en":"a pair of slippers","vi":"một đôi dép đi trong nhà"},{"en":"put on your slippers","vi":"xỏ dép vào"},{"en":"bedroom slippers","vi":"dép đi phòng ngủ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường dùng ở dạng số nhiều slippers; dép xỏ ngón thường được gọi là flip-flops.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_badly', 'en-a2-43', 'badly', '/ˈbædli/', 'A2', 'kém; tồi; tồi tệ; trầm trọng; nghiêm trọng; rất nhiều; khẩn cấp', 'adv.', 'bad (adj.)', 'Đồng nghĩa: poorly, severely · Trái nghĩa: well', 'Dạng so sánh hơn là worse, so sánh nhất là worst; không phải là cách dùng tính từ của bad.', 'I slept badly because the room was too hot.', NULL, 'Tôi ngủ rất kém vì phòng quá nóng.', '{"wordId":"badly","ukIpa":"/ˈbædli/","usIpa":"/ˈbædli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"In a way that is poor, unsuccessful, or unacceptable","vi":"kém; tồi; tồi tệ"},{"pos":"adv.","en":"To a serious or harmful degree","vi":"trầm trọng; nghiêm trọng"},{"pos":"adv.","en":"Very much, especially when wanting or needing something","vi":"rất nhiều; khẩn cấp"}],"examples":[{"en":"I slept badly because the room was too hot.","vi":"Tôi ngủ rất kém vì phòng quá nóng.","audioKind":"ex"},{"en":"Poorly maintained roads can badly affect rural communities by limiting access to schools, hospitals, and markets.","vi":"Những con đường xuống cấp có thể ảnh hưởng nghiêm trọng đến các cộng đồng nông thôn bằng cách hạn chế việc tiếp cận trường học, bệnh viện và chợ.","audioKind":"ex2"}],"collocations":[{"en":"perform badly","vi":"thể hiện kém"},{"en":"badly damaged","vi":"hư hỏng nặng"},{"en":"badly needed","vi":"rất cần thiết"}],"wordFamily":["bad (adj.)"],"synonyms":["poorly","severely"],"antonyms":["well"],"tipVi":"Dạng so sánh hơn là worse, so sánh nhất là worst; không phải là cách dùng tính từ của bad.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_count', 'en-a2-43', 'count', '/kaʊnt/', 'A2', 'đếm; tính số lượng; có giá trị; có trọng lượng; quan trọng; sự đếm; tổng số', 'v.', 'countable (adj.), countless (adj.), uncountable (adj.)', 'Đồng nghĩa: tally', 'count on mang nghĩa dựa dẫm, tin cậy; count khi mang nghĩa "quan trọng" là nội động từ.', 'Please count the plates before our guests arrive.', NULL, 'Xin hãy đếm lại số đĩa trước khi khách của chúng ta đến.', '{"wordId":"count","ukIpa":"/kaʊnt/","usIpa":"/kaʊnt/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to find how many things there are","vi":"đếm; tính số lượng"},{"pos":"v.","en":"to matter or have an important effect","vi":"có giá trị; có trọng lượng; quan trọng"},{"pos":"n.","en":"the act of counting, or the total found","vi":"sự đếm; tổng số"}],"examples":[{"en":"Please count the plates before our guests arrive.","vi":"Xin hãy đếm lại số đĩa trước khi khách của chúng ta đến.","audioKind":"ex"},{"en":"When evaluating educational success, students'' confidence and creativity should count as much as examination results.","vi":"Khi đánh giá thành công trong giáo dục, sự tự tin và tính sáng tạo của học sinh cũng cần được coi trọng ngang ngửa với kết quả thi cử.","audioKind":"ex2"}],"collocations":[{"en":"count up","vi":"tính tổng"},{"en":"lose count","vi":"quên mất đã đếm đến đâu; không nhớ nổi"},{"en":"count on someone","vi":"tin tưởng vào ai đó"},{"en":"every minute counts","vi":"mỗi phút đều quý giá"}],"wordFamily":["countable (adj.)","countless (adj.)","uncountable (adj.)"],"synonyms":["tally"],"antonyms":[],"tipVi":"count on mang nghĩa dựa dẫm, tin cậy; count khi mang nghĩa \"quan trọng\" là nội động từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_situation', 'en-a2-43', 'situation', '/ˌsɪtʃuˈeɪʃən/', 'A2', 'tình hình; hoàn cảnh; tình thế', 'n.', 'situational (adj.)', 'Đồng nghĩa: circumstances', 'Biểu thị trạng thái đang ở trong một hoàn cảnh nào đó, hãy dùng "in a situation".', 'We faced a difficult situation when our car broke down.', NULL, 'Chúng tôi đã phải đối mặt với một tình huống khó khăn khi chiếc xe ô tô bị hỏng.', '{"wordId":"situation","ukIpa":"/ˌsɪtʃuˈeɪʃən/","usIpa":"/ˌsɪtʃuˈeɪʃən/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"The conditions and events affecting someone or something at a time.","vi":"tình hình; hoàn cảnh; tình thế"}],"examples":[{"en":"We faced a difficult situation when our car broke down.","vi":"Chúng tôi đã phải đối mặt với một tình huống khó khăn khi chiếc xe ô tô bị hỏng.","audioKind":"ex"},{"en":"The housing situation has become increasingly difficult for young people living in major cities.","vi":"Tình trạng nhà ở ngày càng trở nên khó khăn hơn đối với các bạn trẻ sinh sống tại những thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"a difficult situation","vi":"một tình huống khó khăn"},{"en":"the current situation","vi":"tình hình hiện tại"},{"en":"deal with a situation","vi":"giải quyết một tình huống"}],"wordFamily":["situational (adj.)"],"synonyms":["circumstances"],"antonyms":[],"tipVi":"Biểu thị trạng thái đang ở trong một hoàn cảnh nào đó, hãy dùng \"in a situation\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_continue', 'en-a2-43', 'continue', '/kənˈtɪnjuː/', 'A2', 'tiếp tục; tiếp tục lại; bắt đầu lại', 'v.', 'continuation (n.), continuous (adj.), continual (adj.), continuously (adv.)', 'Đồng nghĩa: carry on, proceed · Trái nghĩa: stop, cease', 'Có thể đi kèm với "to do" hoặc "doing", nhìn chung đều diễn tả hành động tiếp tục làm việc gì đó.', 'We continued walking along the beach despite the rain.', NULL, 'Chúng tôi vẫn tiếp tục đi dạo dọc bờ biển mặc cho trời đang mưa.', '{"wordId":"continue","ukIpa":"/kənˈtɪnjuː/","usIpa":"/kənˈtɪnjuː/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To keep doing something or keep happening.","vi":"tiếp tục"},{"pos":"v.","en":"To start again after a pause or interruption.","vi":"tiếp tục lại; bắt đầu lại"}],"examples":[{"en":"We continued walking along the beach despite the rain.","vi":"Chúng tôi vẫn tiếp tục đi dạo dọc bờ biển mặc cho trời đang mưa.","audioKind":"ex"},{"en":"If housing costs continue to rise, more young adults may struggle to live independently in major cities.","vi":"Nếu chi phí nhà ở tiếp tục tăng cao, nhiều người trẻ tuổi hơn có thể sẽ gặp khó khăn trong việc tự lập cuộc sống tại các thành phố lớn.","audioKind":"ex2"}],"collocations":[{"en":"continue to grow","vi":"tiếp tục tăng trưởng"},{"en":"continue working","vi":"tiếp tục làm việc"},{"en":"continue a discussion","vi":"tiếp tục cuộc thảo luận"},{"en":"continue as planned","vi":"tiếp tục theo kế hoạch"}],"wordFamily":["continuation (n.)","continuous (adj.)","continual (adj.)","continuously (adv.)"],"synonyms":["carry on","proceed"],"antonyms":["stop","cease"],"tipVi":"Có thể đi kèm với \"to do\" hoặc \"doing\", nhìn chung đều diễn tả hành động tiếp tục làm việc gì đó.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_watermelon', 'en-a2-43', 'watermelon', '/ˈwɔːtɚmelən/', 'A2', 'dưa hấu', 'n.', NULL, NULL, 'Quả dưa hấu nguyên vẹn là danh từ đếm được; khi chỉ phần ruột dưa đã cắt ra thì thường không đếm được.', 'We shared a cold watermelon after playing outside.', NULL, 'Chúng tôi đã cùng nhau ăn một quả dưa hấu mát lạnh sau khi chơi đùa ngoài trời.', '{"wordId":"watermelon","ukIpa":"/ˈwɔːtəmelən/","usIpa":"/ˈwɔːtɚmelən/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a large green-skinned fruit with juicy, usually red flesh","vi":"dưa hấu"}],"examples":[{"en":"We shared a cold watermelon after playing outside.","vi":"Chúng tôi đã cùng nhau ăn một quả dưa hấu mát lạnh sau khi chơi đùa ngoài trời.","audioKind":"ex"},{"en":"Growing watermelons in dry regions requires careful irrigation management to protect limited local water supplies.","vi":"Việc trồng dưa hấu ở các vùng khô hạn đòi hỏi phải quản lý tưới tiêu thật cẩn thận nhằm bảo vệ nguồn nước hạn hẹp tại địa phương.","audioKind":"ex2"}],"collocations":[{"en":"a slice of watermelon","vi":"một miếng dưa hấu"},{"en":"watermelon seeds","vi":"hạt dưa hấu"},{"en":"ripe watermelon","vi":"dưa hấu chín"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Quả dưa hấu nguyên vẹn là danh từ đếm được; khi chỉ phần ruột dưa đã cắt ra thì thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dry', 'en-a2-43', 'dry', '/draɪ/', 'A2', 'khô; ráo; làm khô; phơi khô; trở nên khô; khô khan; nhàm chán', 'adj.', 'dryness (n.), dryer (n.)', 'Trái nghĩa: wet, damp', 'Dạng so sánh hơn của tính từ là "drier"; danh từ "dryer" chỉ thiết bị sấy khô.', 'The towels are dry after hanging in the sunshine.', NULL, 'Những chiếc khăn đã khô sau khi được phơi ngoài ánh nắng mặt trời.', '{"wordId":"dry","ukIpa":"/draɪ/","usIpa":"/draɪ/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"not wet or containing very little moisture","vi":"khô; ráo"},{"pos":"v.","en":"to remove moisture or become free from moisture","vi":"làm khô; phơi khô; trở nên khô"},{"pos":"adj.","en":"not interesting or entertaining","vi":"khô khan; nhàm chán"}],"examples":[{"en":"The towels are dry after hanging in the sunshine.","vi":"Những chiếc khăn đã khô sau khi được phơi ngoài ánh nắng mặt trời.","audioKind":"ex"},{"en":"Long periods of dry weather can damage crops and threaten food security in agricultural communities.","vi":"Thời tiết khô hạn kéo dài có thể gây tổn hại cho mùa màng và đe dọa đến an ninh lương thực ở các cộng đồng làm nông nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"dry weather","vi":"thời tiết khô hạn"},{"en":"dry skin","vi":"da khô"},{"en":"dry your hands","vi":"lau khô tay"},{"en":"dry up","vi":"cạn kiệt; khô cạn"}],"wordFamily":["dryness (n.)","dryer (n.)"],"synonyms":[],"antonyms":["wet","damp"],"tipVi":"Dạng so sánh hơn của tính từ là \"drier\"; danh từ \"dryer\" chỉ thiết bị sấy khô.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_round', 'en-a2-43', 'round', '/raʊnd/', 'A2', 'tròn; có hình tròn (hoặc hình cầu); vòng; hiệp (trong một chuỗi hoạt động lặp lại); quanh; xung quanh', 'adj.', 'roundness (n.), rounded (adj.)', NULL, 'round làm giới từ phổ biến trong tiếng Anh-Anh, trong khi tiếng Anh-Mỹ thường dùng around.', 'We placed a round table beside the kitchen window.', NULL, 'Chúng tôi đặt một chiếc bàn tròn bên cạnh cửa sổ nhà bếp.', '{"wordId":"round","ukIpa":"/raʊnd/","usIpa":"/raʊnd/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"shaped like a circle or ball","vi":"tròn; có hình tròn (hoặc hình cầu)"},{"pos":"n.","en":"one stage in a repeated series of activities","vi":"vòng; hiệp (trong một chuỗi hoạt động lặp lại)"},{"pos":"prep.","en":"around something or on all sides of it","vi":"quanh; xung quanh"}],"examples":[{"en":"We placed a round table beside the kitchen window.","vi":"Chúng tôi đặt một chiếc bàn tròn bên cạnh cửa sổ nhà bếp.","audioKind":"ex"},{"en":"A further round of negotiations may help governments reach an agreement on reducing industrial emissions.","vi":"Một vòng đàm phán tiếp theo có thể giúp các chính phủ đạt được thỏa thuận về việc giảm phát thải công nghiệp.","audioKind":"ex2"}],"collocations":[{"en":"round table","vi":"bàn tròn"},{"en":"a round of talks","vi":"một vòng đàm phán"},{"en":"walk round the lake","vi":"đi bộ vòng quanh hồ"}],"wordFamily":["roundness (n.)","rounded (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"round làm giới từ phổ biến trong tiếng Anh-Anh, trong khi tiếng Anh-Mỹ thường dùng around.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_receive', 'en-a2-43', 'receive', '/rɪˈsiːv/', 'A2', 'nhận được (cái gì đó do ai gửi, trao hoặc cung cấp); tiếp đón; đón tiếp (ai đó đến một nơi)', 'v.', 'receiver (n.), reception (n.), recipient (n.)', 'Đồng nghĩa: get, obtain · Trái nghĩa: send', 'receive thiên về việc nhận được; accept thiên về việc sẵn lòng chấp nhận.', 'Did you receive the photos I sent yesterday?', NULL, 'Bạn đã nhận được những bức ảnh tôi gửi hôm qua chưa?', '{"wordId":"receive","ukIpa":"/rɪˈsiːv/","usIpa":"/rɪˈsiːv/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"To get something that someone sends, gives, or provides.","vi":"nhận được (cái gì đó do ai gửi, trao hoặc cung cấp)"},{"pos":"v.","en":"To welcome someone arriving at a place.","vi":"tiếp đón; đón tiếp (ai đó đến một nơi)"}],"examples":[{"en":"Did you receive the photos I sent yesterday?","vi":"Bạn đã nhận được những bức ảnh tôi gửi hôm qua chưa?","audioKind":"ex"},{"en":"All residents should receive clear information about changes to public transport before new routes are introduced.","vi":"Tất cả cư dân nên nhận được thông tin rõ ràng về các thay đổi đối với phương tiện giao thông công cộng trước khi các tuyến đường mới đi vào hoạt động.","audioKind":"ex2"}],"collocations":[{"en":"receive an email","vi":"nhận email"},{"en":"receive treatment","vi":"nhận điều trị"},{"en":"receive a warm welcome","vi":"nhận được sự chào đón nồng nhiệt"}],"wordFamily":["receiver (n.)","reception (n.)","recipient (n.)"],"synonyms":["get","obtain"],"antonyms":["send"],"tipVi":"receive thiên về việc nhận được; accept thiên về việc sẵn lòng chấp nhận.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_blond', 'en-a2-43', 'blond', '/blɑːnd/', 'A2', 'có màu vàng nhạt; tóc vàng; người tóc vàng', 'adj.', 'blonde (adj.), blondness (n.)', 'Đồng nghĩa: fair-haired, golden-haired · Trái nghĩa: dark-haired', 'blonde thường được dùng cho nữ giới; từ này không giới hạn về màu da.', 'His blond hair looked almost white in the sunshine.', NULL, 'Mái tóc vàng của anh ấy trông gần như trắng dưới ánh nắng mặt trời.', '{"wordId":"blond","ukIpa":"/blɒnd/","usIpa":"/blɑːnd/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Having hair that is pale yellow or golden.","vi":"có màu vàng nhạt; tóc vàng"},{"pos":"n.","en":"A person with pale yellow or golden hair.","vi":"người tóc vàng"}],"examples":[{"en":"His blond hair looked almost white in the sunshine.","vi":"Mái tóc vàng của anh ấy trông gần như trắng dưới ánh nắng mặt trời.","audioKind":"ex"},{"en":"In discussions of inherited traits, blond hair is often used as an example of human physical variation.","vi":"Trong các cuộc thảo luận về đặc điểm di truyền, tóc vàng thường được dùng làm ví dụ về sự biến đổi thể chất của con người.","audioKind":"ex2"}],"collocations":[{"en":"blond hair","vi":"tóc vàng"},{"en":"a blond child","vi":"một đứa trẻ tóc vàng"},{"en":"naturally blond","vi":"tóc vàng tự nhiên"}],"wordFamily":["blonde (adj.)","blondness (n.)"],"synonyms":["fair-haired","golden-haired"],"antonyms":["dark-haired"],"tipVi":"blonde thường được dùng cho nữ giới; từ này không giới hạn về màu da.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_huge', 'en-a2-43', 'huge', '/hjuːdʒ/', 'A2', 'khổng lồ; to lớn; rất nhiều (về kích thước, số lượng hoặc mức độ)', 'adj.', 'hugely (adv.)', 'Đồng nghĩa: enormous, immense, massive · Trái nghĩa: tiny, small', 'Bản thân từ này đã mang nghĩa cực kỳ lớn, thường dùng absolutely huge để nhấn mạnh thêm.', 'A huge dog was sleeping beside the tiny kitten.', NULL, 'Một chú chó khổng lồ đang ngủ cạnh chú mèo con bé xíu.', '{"wordId":"huge","ukIpa":"/hjuːdʒ/","usIpa":"/hjuːdʒ/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"extremely large in size, amount, or degree","vi":"khổng lồ; to lớn; rất nhiều (về kích thước, số lượng hoặc mức độ)"}],"examples":[{"en":"A huge dog was sleeping beside the tiny kitten.","vi":"Một chú chó khổng lồ đang ngủ cạnh chú mèo con bé xíu.","audioKind":"ex"},{"en":"Investing in public transport could bring huge benefits to cities struggling with congestion and air pollution.","vi":"Đầu tư vào giao thông công cộng có thể mang lại những lợi ích to lớn cho các thành phố đang vật lộn với tình trạng tắc nghẽn giao thông và ô nhiễm không khí.","audioKind":"ex2"}],"collocations":[{"en":"huge amount","vi":"số lượng lớn"},{"en":"huge difference","vi":"sự khác biệt lớn"},{"en":"huge impact","vi":"tác động to lớn"},{"en":"huge success","vi":"thành công vang dội"}],"wordFamily":["hugely (adv.)"],"synonyms":["enormous","immense","massive"],"antonyms":["tiny","small"],"tipVi":"Bản thân từ này đã mang nghĩa cực kỳ lớn, thường dùng absolutely huge để nhấn mạnh thêm.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_43_1', 'en-a2-43', 'Cách dùng “ordinary” (adj.) — bình thường; thông thường; không có gì đặc biệt', 'ordinary people  ·  ordinary life  ·  an ordinary day', 'ordinary nhấn mạnh tính chất thông thường, không nổi bật; không đồng nghĩa với average (tính theo mức trung bình).', 'Họ từ (Word Family): ordinarily (adv.), extraordinary (adj.) | Đồng nghĩa: normal, usual, unremarkable · Trái nghĩa: extraordinary, unusual', '[{"hanzi":"It looked like an ordinary box until we opened it.","pinyin":"","meaning":"Trông nó giống như một chiếc hộp bình thường cho đến khi chúng tôi mở ra."},{"hanzi":"Urban planning should reflect the needs of ordinary residents rather than focus exclusively on attracting wealthy investors.","pinyin":"","meaning":"Quy hoạch đô thị nên phản ánh nhu cầu của người dân bình thường thay vì chỉ tập trung thu hút giới đầu tư giàu có."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_43_2', 'en-a2-43', 'Cách dùng “repair” (v.) — sửa chữa; tân trang', 'repair damage  ·  carry out repairs  ·  beyond repair', 'Cụ thể việc sửa chữa thường dùng dạng số nhiều repairs; beyond repair có nghĩa là không thể sửa chữa được nữa.', 'Họ từ (Word Family): repairable (adj.), irreparable (adj.), repairer (n.) | Đồng nghĩa: fix, mend · Trái nghĩa: damage', '[{"hanzi":"Can you repair the broken zip on my jacket?","pinyin":"","meaning":"Bạn có thể sửa giúp tôi chiếc khóa kéo bị hỏng trên áo khoác được không?"},{"hanzi":"Encouraging consumers to repair household appliances rather than replace them could significantly reduce electronic waste.","pinyin":"","meaning":"Việc khuyến khích người tiêu dùng sửa chữa các thiết bị gia dụng thay vì mua mới có thể làm giảm đáng kể lượng rác thải điện tử."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_43_3', 'en-a2-43', 'Cách dùng “watermelon” (n.) — dưa hấu', 'a slice of watermelon  ·  watermelon seeds  ·  ripe watermelon', 'Quả dưa hấu nguyên vẹn là danh từ đếm được; khi chỉ phần ruột dưa đã cắt ra thì thường không đếm được.', NULL, '[{"hanzi":"We shared a cold watermelon after playing outside.","pinyin":"","meaning":"Chúng tôi đã cùng nhau ăn một quả dưa hấu mát lạnh sau khi chơi đùa ngoài trời."},{"hanzi":"Growing watermelons in dry regions requires careful irrigation management to protect limited local water supplies.","pinyin":"","meaning":"Việc trồng dưa hấu ở các vùng khô hạn đòi hỏi phải quản lý tưới tiêu thật cẩn thận nhằm bảo vệ nguồn nước hạn hẹp tại địa phương."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_43_4', 'en-a2-43', 'Cách dùng “already” (adv.) — đã; từ trước; đã từ lâu', 'have already done  ·  already available  ·  already in place', 'Thường đứng sau trợ động từ và trước động từ chính; thể hiện sự việc đã xảy ra hoặc sớm hơn dự kiến.', NULL, '[{"hanzi":"I have already packed my bag for tomorrow.","pinyin":"","meaning":"Tôi đã sắp xếp xong hành lý cho ngày mai rồi."},{"hanzi":"Many cities have already introduced cycling schemes to reduce traffic congestion and improve public health.","pinyin":"","meaning":"Nhiều thành phố đã triển khai các chương trình đi xe đạp nhằm giảm thiểu tình trạng ùn tắc giao thông và nâng cao sức khỏe cộng đồng."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_43_1', 'en-a2-43', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
