INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_43_1_2', 'ten_a2_43_1', 'comb', 'She pulled a comb from her bag and tidied her hair.', 'She pulled a comb from her bag and tidied her hair.', '/koʊm/', 'Cô ấy lấy một chiếc lược trong túi ra và chải lại mái tóc của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_43_1_3', 'ten_a2_43_1', 'noisy', 'Our noisy washing machine woke everyone up this morning.', 'Our noisy washing machine woke everyone up this morning.', '/ˈnɔɪzi/', 'Chiếc máy giặt ồn ào của chúng tôi đã đánh thức mọi người vào sáng nay.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_43_1_4', 'ten_a2_43_1', 'secret', 'We planned a secret picnic for our grandparents.', 'We planned a secret picnic for our grandparents.', '/ˈsiːkrət/', 'Chúng tôi đã lên kế hoạch cho một buổi dã ngoại bí mật dành tặng ông bà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_43_1_5', 'ten_a2_43_1', 'sir', 'Excuse me, sir, you left your umbrella behind.', 'Excuse me, sir, you left your umbrella behind.', '/sɝː/', 'Xin lỗi ông, ông để quên ô kìa.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
