INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_43_1_7', 'ten_a2_43_1', 'repair', 'Can you repair the broken zip on my jacket?', 'Can you repair the broken zip on my jacket?', '/rɪˈper/', 'Bạn có thể sửa giúp tôi chiếc khóa kéo bị hỏng trên áo khoác được không?', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_43_1_8', 'ten_a2_43_1', 'shut', 'Please shut the window before the rain gets in.', 'Please shut the window before the rain gets in.', '/ʃʌt/', 'Làm ơn đóng cửa sổ lại trước khi trời mưa hắt vào.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_43_1_1', 'en-a2-43', 'ten_a2_43_1', 'listening', 'listening', 'I marked our camping weekend on the kitchen calendar.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Một chú chó khổng lồ đang ngủ cạnh chú mèo con bé xíu.","Cô ấy đeo một chiếc vòng cổ bằng bạc có đính hình chú chim nhỏ.","Tôi đã đánh dấu cuối tuần đi cắm trại của chúng tôi lên cuốn lịch ở nhà bếp.","Chúng tôi đã lên kế hoạch cho một buổi dã ngoại bí mật dành tặng ông bà."]'::jsonb, 2, 'I marked our camping weekend on the kitchen calendar. → Tôi đã đánh dấu cuối tuần đi cắm trại của chúng tôi lên cuốn lịch ở nhà bếp.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_43_1_2', 'en-a2-43', 'ten_a2_43_1', 'listening', 'listening', 'She pulled a comb from her bag and tidied her hair.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc chăn mềm mại này sưởi ấm tôi trong những đêm lạnh giá.","Chúng tôi đã lên kế hoạch cho một buổi dã ngoại bí mật dành tặng ông bà.","Cô ấy lấy một chiếc lược trong túi ra và chải lại mái tóc của mình.","Tôi đã đánh dấu cuối tuần đi cắm trại của chúng tôi lên cuốn lịch ở nhà bếp."]'::jsonb, 2, 'She pulled a comb from her bag and tidied her hair. → Cô ấy lấy một chiếc lược trong túi ra và chải lại mái tóc của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_43_1_3', 'en-a2-43', 'ten_a2_43_1', 'listening', 'listening', 'Our noisy washing machine woke everyone up this morning.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chiếc máy giặt ồn ào của chúng tôi đã đánh thức mọi người vào sáng nay.","Cô ấy lấy một chiếc lược trong túi ra và chải lại mái tóc của mình.","Chúng tôi đã phải đối mặt với một tình huống khó khăn khi chiếc xe ô tô bị hỏng.","Tôi đã đánh dấu cuối tuần đi cắm trại của chúng tôi lên cuốn lịch ở nhà bếp."]'::jsonb, 0, 'Our noisy washing machine woke everyone up this morning. → Chiếc máy giặt ồn ào của chúng tôi đã đánh thức mọi người vào sáng nay.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_43_2', 'en-a2-43', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_43_2_1', 'ten_a2_43_2', 'calendar', 'Schools should publish an annual calendar so families can plan holidays around important educational events.', 'Schools should publish an annual calendar so families can plan holidays around important educational events.', '/ˈkæləndər/', 'Các trường học nên công bố lịch trình hàng năm để các gia đình có thể sắp xếp kỳ nghỉ xung quanh các hoạt động giáo dục quan trọng.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_43_2_2', 'ten_a2_43_2', 'comb', 'Volunteers combed the beach for plastic waste before the start of the summer tourist season.', 'Volunteers combed the beach for plastic waste before the start of the summer tourist season.', '/koʊm/', 'Các tình nguyện viên đã lục soát kỹ lưỡng bãi biển để thu gom rác nhựa trước khi mùa du lịch hè bắt đầu.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_43_2_3', 'ten_a2_43_2', 'noisy', 'Living near noisy roads can affect sleep quality and increase stress among urban residents.', 'Living near noisy roads can affect sleep quality and increase stress among urban residents.', '/ˈnɔɪzi/', 'Sống gần những con đường ồn ào có thể ảnh hưởng đến chất lượng giấc ngủ và làm gia tăng mức độ căng thẳng ở cư dân thành thị.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_43_2_4', 'ten_a2_43_2', 'secret', 'Governments must balance the need to keep information secret with the public''s right to know.', 'Governments must balance the need to keep information secret with the public''s right to know.', '/ˈsiːkrət/', 'Chính phủ phải cân bằng giữa nhu cầu giữ kín thông tin và quyền được biết của công chúng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_43_2_5', 'ten_a2_43_2', 'sir', 'In some schools, students address male teachers as sir to show respect during lessons.', 'In some schools, students address male teachers as sir to show respect during lessons.', '/sɝː/', 'Ở một số trường học, học sinh gọi các thầy giáo là sir để bày tỏ sự tôn trọng trong giờ học.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_43_2_6', 'ten_a2_43_2', 'silly', 'Teachers should avoid calling any question silly, as this may discourage students from participating in class.', 'Teachers should avoid calling any question silly, as this may discourage students from participating in class.', '/ˈsɪli/', 'Giáo viên nên tránh gọi bất kỳ câu hỏi nào là ngớ ngẩn, vì điều này có thể làm học sinh nhụt chí tham gia lớp học.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_43_2_1', 'en-a2-43', 'ten_a2_43_2', 'listening', 'listening', 'Schools should publish an annual calendar so families can plan holidays around important educational events.', NULL, 'Trong câu vừa nghe, từ “calendar” mang nghĩa nào sau đây?', '["theo như; dựa theo","lịch; bảng lịch; lịch trình","ồn ào; náo nhiệt; ồn","thịt xông khói; thịt lợn muối xông khói"]'::jsonb, 1, '“calendar” (/ˈkæləndər/): lịch; bảng lịch; lịch trình. Câu đầy đủ: Schools should publish an annual calendar so families can plan holidays around important educational events.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_43_2_2', 'en-a2-43', 'ten_a2_43_2', 'listening', 'listening', 'Volunteers combed the beach for plastic waste before the start of the summer tourist season.', NULL, 'Trong câu vừa nghe, từ “comb” mang nghĩa nào sau đây?', '["dặm (đơn vị đo khoảng cách)","ga giường; tấm khăn trải giường","lò; bếp nấu; lò sưởi","lược"]'::jsonb, 3, '“comb” (/koʊm/): lược. Câu đầy đủ: Volunteers combed the beach for plastic waste before the start of the summer tourist season.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
