INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_43_2', 'en-a2-43', NULL, 'comprehensive_test', 'listening', 'She pulled a comb from her bag and tidied her hair.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bạn đã nhận được những bức ảnh tôi gửi hôm qua chưa?","Cô ấy lấy một chiếc lược trong túi ra và chải lại mái tóc của mình.","Xin hãy đếm lại số đĩa trước khi khách của chúng ta đến.","Tôi đã đánh dấu cuối tuần đi cắm trại của chúng tôi lên cuốn lịch ở nhà bếp."]'::jsonb, 1, 'She pulled a comb from her bag and tidied her hair. → Cô ấy lấy một chiếc lược trong túi ra và chải lại mái tóc của mình.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
