INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_43_4', 'en-a2-43', NULL, 'comprehensive_test', 'listening', 'We planned a secret picnic for our grandparents.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Những chiếc khăn đã khô sau khi được phơi ngoài ánh nắng mặt trời.","Thật ngốc nghếch khi để quên ô ở nhà.","Một chú chó khổng lồ đang ngủ cạnh chú mèo con bé xíu.","Chúng tôi đã lên kế hoạch cho một buổi dã ngoại bí mật dành tặng ông bà."]'::jsonb, 3, 'We planned a secret picnic for our grandparents. → Chúng tôi đã lên kế hoạch cho một buổi dã ngoại bí mật dành tặng ông bà.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_43_5', 'en-a2-43', NULL, 'comprehensive_test', 'listening', 'sir', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["thưa ông; thưa ngài; thầy (cách gọi lịch sự đối với nam giới hoặc thầy giáo)","nhà khoa học","phục vụ đồ ăn thức uống; tiếp đón khách hàng","miếng mỏng; lát"]'::jsonb, 0, 'sir (/sɝː/) → thưa ông; thưa ngài; thầy (cách gọi lịch sự đối với nam giới hoặc thầy giáo); ngài (tước hiệu đặt trước tên của một hiệp sĩ hoặc nam tước)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_43_6', 'en-a2-43', NULL, 'comprehensive_test', 'listening', 'It was silly to leave my umbrella at home.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Tôi đã tự làm cho mình một cái bánh mì kẹp trước khi đi dạo.","Thật ngốc nghếch khi để quên ô ở nhà.","Chúng tôi đã cùng nhau ăn một quả dưa hấu mát lạnh sau khi chơi đùa ngoài trời.","Một chú chó khổng lồ đang ngủ cạnh chú mèo con bé xíu."]'::jsonb, 1, 'It was silly to leave my umbrella at home. → Thật ngốc nghếch khi để quên ô ở nhà.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_43_7', 'en-a2-43', NULL, 'comprehensive_test', 'listening', 'repair', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nghĩa; ý nghĩa; hàm ý","danh từ","máy rửa bát; máy rửa chén","sửa chữa; tân trang"]'::jsonb, 3, 'repair (/rɪˈper/) → sửa chữa; tân trang; công việc sửa chữa; sự bảo dưỡng; cải thiện mối quan hệ; khắc phục tình huống', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_43_8', 'en-a2-43', NULL, 'comprehensive_test', 'listening', 'Please shut the window before the rain gets in.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy đeo một chiếc vòng cổ bằng bạc có đính hình chú chim nhỏ.","Xin lỗi ông, ông để quên ô kìa.","Chúng tôi vẫn tiếp tục đi dạo dọc bờ biển mặc cho trời đang mưa.","Làm ơn đóng cửa sổ lại trước khi trời mưa hắt vào."]'::jsonb, 3, 'Please shut the window before the rain gets in. → Làm ơn đóng cửa sổ lại trước khi trời mưa hắt vào.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
