INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_43_18', 'en-a2-43', NULL, 'comprehensive_test', 'reading', NULL, 'Schools should publish an annual calendar so families can plan holidays around important educational events.', 'Dựa vào câu trên, từ “calendar” có nghĩa phù hợp nhất là gì?', '["đầu gối; khớp gối","tủ lạnh; tủ cấp đông","lịch; bảng lịch; lịch trình","y tá; điều dưỡng viên"]'::jsonb, 2, 'calendar: lịch; bảng lịch; lịch trình; hệ thống lịch; phép tính lịch. Dịch cả câu: Các trường học nên công bố lịch trình hàng năm để các gia đình có thể sắp xếp kỳ nghỉ xung quanh các hoạt động giáo dục quan trọng.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_43_19', 'en-a2-43', NULL, 'comprehensive_test', 'reading', NULL, 'Volunteers combed the beach for plastic waste before the start of the summer tourist season.', 'Dựa vào câu trên, từ “comb” có nghĩa phù hợp nhất là gì?', '["lược","phần trăm","ngũ cốc ăn sáng; món ngũ cốc ăn kèm sữa","lắc; rung; run rẩy"]'::jsonb, 0, 'comb: lược; chải tóc; lục soát kỹ lưỡng. Dịch cả câu: Các tình nguyện viên đã lục soát kỹ lưỡng bãi biển để thu gom rác nhựa trước khi mùa du lịch hè bắt đầu.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_43_20', 'en-a2-43', NULL, 'comprehensive_test', 'reading', NULL, 'Living near noisy roads can affect sleep quality and increase stress among urban residents.', 'Dựa vào câu trên, từ “noisy” có nghĩa phù hợp nhất là gì?', '["môn trượt tuyết; hoạt động trượt tuyết","ấm đun nước","chất khí; thể khí","ồn ào; náo nhiệt; ồn"]'::jsonb, 3, 'noisy: ồn ào; náo nhiệt; ồn. Dịch cả câu: Sống gần những con đường ồn ào có thể ảnh hưởng đến chất lượng giấc ngủ và làm gia tăng mức độ căng thẳng ở cư dân thành thị.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_43_21', 'en-a2-43', NULL, 'comprehensive_test', 'reading', NULL, 'Governments must balance the need to keep information secret with the public''s right to know.', 'Dựa vào câu trên, từ “secret” có nghĩa phù hợp nhất là gì?', '["thư tín; bưu kiện; hệ thống bưu chính","bí mật; giữ kín","hệ thống tàu điện ngầm","giải thích; làm rõ"]'::jsonb, 1, 'secret: bí mật; giữ kín; điều bí mật; bí quyết; phương sách. Dịch cả câu: Chính phủ phải cân bằng giữa nhu cầu giữ kín thông tin và quyền được biết của công chúng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
