INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_43_24', 'en-a2-43', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “khổng lồ; to lớn; rất nhiều (về kích thước, số lượng hoặc mức độ)”', '["countryside","instruction","ancient","huge"]'::jsonb, 3, 'khổng lồ; to lớn; rất nhiều (về kích thước, số lượng hoặc mức độ) → huge (/hjuːdʒ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-44', 'en', 'Bài 44: Đời sống hằng ngày (16) - CEFR A2', 'CEFR A2', 'A2 · Đời sống', '26 từ vựng Tiếng Anh CEFR A2 chủ đề đời sống hằng ngày kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2044, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_accident', 'en-a2-44', 'accident', '/ˈæksɪdənt/', 'A2', 'tai nạn; sự cố; rủi ro bất ngờ', 'n.', 'accidental (adj.), accidentally (adv.)', NULL, 'by accident có nghĩa là vô tình, trái nghĩa với cụm từ on purpose.', 'Luckily, nobody was hurt in the accident outside our house.', NULL, 'May mắn là không ai bị thương trong vụ tai nạn xảy ra ngay trước nhà chúng tôi.', '{"wordId":"accident","ukIpa":"/ˈæksɪdənt/","usIpa":"/ˈæksɪdənt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"An unexpected event that causes injury or damage.","vi":"tai nạn; sự cố"},{"pos":"n.","en":"Something that happens without being planned or intended.","vi":"tai nạn; rủi ro bất ngờ"}],"examples":[{"en":"Luckily, nobody was hurt in the accident outside our house.","vi":"May mắn là không ai bị thương trong vụ tai nạn xảy ra ngay trước nhà chúng tôi.","audioKind":"ex"},{"en":"Better street lighting can reduce the risk of accidents involving cyclists and pedestrians at night.","vi":"Hệ thống chiếu sáng đường phố tốt hơn có thể làm giảm nguy cơ xảy ra tai nạn liên quan đến người đi xe đạp và người đi bộ vào ban đêm.","audioKind":"ex2"}],"collocations":[{"en":"a road accident","vi":"tai nạn giao thông đường bộ"},{"en":"by accident","vi":"tình cờ; vô tình"},{"en":"prevent accidents","vi":"phòng ngừa tai nạn"}],"wordFamily":["accidental (adj.)","accidentally (adv.)"],"synonyms":[],"antonyms":[],"tipVi":"by accident có nghĩa là vô tình, trái nghĩa với cụm từ on purpose.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_touch', 'en-a2-44', 'touch', '/tʌtʃ/', 'A2', 'chạm; sờ; xúc giác; sự chạm; làm cảm động; làm rung động', 'v.', 'touching (adj.), touched (adj.), untouched (adj.)', NULL, 'Giữ liên lạc dùng keep in touch with someone.', 'Please don''t touch the pan; it is still hot.', NULL, 'Xin đừng chạm vào cái chảo; nó vẫn còn rất nóng.', '{"wordId":"touch","ukIpa":"/tʌtʃ/","usIpa":"/tʌtʃ/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to put your hand or another body part against something","vi":"chạm; sờ"},{"pos":"n.","en":"the sense of feeling things through skin, or physical contact","vi":"xúc giác; sự chạm"},{"pos":"v.","en":"to make someone feel a strong, often tender emotion","vi":"làm cảm động; làm rung động"}],"examples":[{"en":"Please don''t touch the pan; it is still hot.","vi":"Xin đừng chạm vào cái chảo; nó vẫn còn rất nóng.","audioKind":"ex"},{"en":"Digital communication helps families stay in touch, even when work or study separates them across countries.","vi":"Giao tiếp kỹ thuật số giúp các gia đình giữ liên lạc, ngay cả khi công việc hoặc học tập chia cách họ ở các quốc gia khác nhau.","audioKind":"ex2"}],"collocations":[{"en":"keep in touch","vi":"giữ liên lạc"},{"en":"lose touch","vi":"mất liên lạc"},{"en":"sense of touch","vi":"xúc giác"},{"en":"deeply touched","vi":"vô cùng cảm động"}],"wordFamily":["touching (adj.)","touched (adj.)","untouched (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Giữ liên lạc dùng keep in touch with someone.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_dessert', 'en-a2-44', 'dessert', '/dɪˈzɝːt/', 'A2', 'món tráng miệng', 'n.', NULL, 'Đồng nghĩa: sweet', 'dessert có hai chữ s, trọng âm rơi vào âm tiết sau; desert mang nghĩa sa mạc có trọng âm ở âm tiết đầu.', 'We shared a bowl of ice cream for dessert.', NULL, 'Chúng tôi chia nhau một bát kem làm món tráng miệng.', '{"wordId":"dessert","ukIpa":"/dɪˈzɜːt/","usIpa":"/dɪˈzɝːt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"Sweet food eaten at the end of a meal.","vi":"món tráng miệng"}],"examples":[{"en":"We shared a bowl of ice cream for dessert.","vi":"Chúng tôi chia nhau một bát kem làm món tráng miệng.","audioKind":"ex"},{"en":"Offering fresh fruit for dessert can help school cafeterias encourage healthier eating habits among children.","vi":"Cung cấp trái cây tươi làm món tráng miệng có thể giúp các căn tin trường học khuyến khích thói quen ăn uống lành mạnh hơn ở trẻ em.","audioKind":"ex2"}],"collocations":[{"en":"for dessert","vi":"làm món tráng miệng"},{"en":"dessert menu","vi":"thực đơn tráng miệng"},{"en":"fruit dessert","vi":"món tráng miệng từ trái cây"}],"wordFamily":[],"synonyms":["sweet"],"antonyms":[],"tipVi":"dessert có hai chữ s, trọng âm rơi vào âm tiết sau; desert mang nghĩa sa mạc có trọng âm ở âm tiết đầu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_spoon', 'en-a2-44', 'spoon', '/spuːn/', 'A2', 'thìa; muỗng; dùng thìa múc', 'n.', 'spoonful (n.)', NULL, 'Lượng chứa trong một thìa thường được diễn đạt bằng a spoonful of.', 'She stirred her soup with a wooden spoon.', NULL, 'Cô ấy dùng một chiếc muỗng gỗ để khuấy súp.', '{"wordId":"spoon","ukIpa":"/spuːn/","usIpa":"/spuːn/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A utensil with a small bowl for eating or serving.","vi":"thìa; muỗng"},{"pos":"v.","en":"To move or serve food using a spoon.","vi":"dùng thìa múc"}],"examples":[{"en":"She stirred her soup with a wooden spoon.","vi":"Cô ấy dùng một chiếc muỗng gỗ để khuấy súp.","audioKind":"ex"},{"en":"Teaching children to use a spoon independently can help develop their coordination and confidence.","vi":"Dạy trẻ tự múc ăn bằng thìa có thể giúp phát triển sự phối hợp vận động và sự tự tin của trẻ.","audioKind":"ex2"}],"collocations":[{"en":"wooden spoon","vi":"muỗng gỗ"},{"en":"soup spoon","vi":"thìa ăn súp"},{"en":"spoon into a bowl","vi":"múc vào bát bằng thìa"}],"wordFamily":["spoonful (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Lượng chứa trong một thìa thường được diễn đạt bằng a spoonful of.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_zipcode', 'en-a2-44', 'ZIP code', '/ˈzɪp koʊd/', 'A2', 'mã bưu chính (tại Mỹ)', 'n.', NULL, NULL, 'Thuật ngữ dùng ở Mỹ; ở Anh thường dùng postcode và từ chung là postal code.', 'Please include your ZIP code when entering your address.', NULL, 'Vui lòng ghi kèm mã bưu chính khi điền địa chỉ của bạn.', '{"wordId":"zipcode","ukIpa":"/ˈzɪp kəʊd/","usIpa":"/ˈzɪp koʊd/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A code identifying a postal delivery area in the United States.","vi":"mã bưu chính (tại Mỹ)"}],"examples":[{"en":"Please include your ZIP code when entering your address.","vi":"Vui lòng ghi kèm mã bưu chính khi điền địa chỉ của bạn.","audioKind":"ex"},{"en":"Researchers grouped households by ZIP code to examine geographical differences in access to healthcare services.","vi":"Các nhà nghiên cứu đã phân nhóm các hộ gia đình theo mã bưu chính để khảo sát sự khác biệt về khả năng tiếp cận dịch vụ y tế giữa các khu vực địa lý.","audioKind":"ex2"}],"collocations":[{"en":"enter a ZIP code","vi":"nhập mã bưu chính"},{"en":"ZIP code lookup","vi":"tra cứu mã bưu chính"},{"en":"ZIP code area","vi":"vùng mã bưu chính"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thuật ngữ dùng ở Mỹ; ở Anh thường dùng postcode và từ chung là postal code.","noteVi":"Đã chuẩn hóa cách viết liền không chuẩn thành ZIP code.","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pea', 'en-a2-44', 'pea', '/piː/', 'A2', 'quả đậu Hà Lan; hạt đậu Hà Lan', 'n.', NULL, NULL, 'Là danh từ đếm được; khi chỉ chung đậu Hà Lan để ăn thường dùng dạng số nhiều peas.', 'She added frozen peas to the vegetable soup.', NULL, 'Cô ấy đã cho thêm đậu Hà Lan đông lạnh vào món súp rau củ.', '{"wordId":"pea","ukIpa":"/piː/","usIpa":"/piː/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A small, round, green seed eaten as a vegetable","vi":"quả đậu Hà Lan; hạt đậu Hà Lan"}],"examples":[{"en":"She added frozen peas to the vegetable soup.","vi":"Cô ấy đã cho thêm đậu Hà Lan đông lạnh vào món súp rau củ.","audioKind":"ex"},{"en":"Growing peas and other vegetables at school can help children understand where their food comes from.","vi":"Việc trồng đậu Hà Lan và các loại rau củ khác tại trường học có thể giúp trẻ em hiểu rõ nguồn gốc thực phẩm của chúng.","audioKind":"ex2"}],"collocations":[{"en":"frozen peas","vi":"đậu Hà Lan đông lạnh"},{"en":"pea soup","vi":"súp đậu Hà Lan"},{"en":"a pea pod","vi":"vỏ đậu Hà Lan"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Là danh từ đếm được; khi chỉ chung đậu Hà Lan để ăn thường dùng dạng số nhiều peas.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_nasty', 'en-a2-44', 'nasty', '/ˈnæsti/', 'A2', 'khó chịu; khó ngửi; tồi tệ; ác ý; bất thiện; cay nghiệt; nghiêm trọng; đau đớn', 'adj.', 'nastily (adv.), nastiness (n.)', 'Đồng nghĩa: unpleasant, mean · Trái nghĩa: pleasant, kind', 'Từ nasty mang sắc thái ghê tởm hơn bad; khi dùng cho người thường có nghĩa là cay nghiệt, bất thiện.', 'A nasty smell came from the kitchen bin.', NULL, 'Có một mùi khó chịu bốc ra từ thùng rác trong bếp.', '{"wordId":"nasty","ukIpa":"/ˈnɑːsti/","usIpa":"/ˈnæsti/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Very unpleasant to experience, taste, smell, or see.","vi":"khó chịu; khó ngửi; tồi tệ"},{"pos":"adj.","en":"Deliberately unkind or hurtful towards another person.","vi":"ác ý; bất thiện; cay nghiệt"},{"pos":"adj.","en":"Severe or painful, especially describing an illness or injury.","vi":"nghiêm trọng; đau đớn"}],"examples":[{"en":"A nasty smell came from the kitchen bin.","vi":"Có một mùi khó chịu bốc ra từ thùng rác trong bếp.","audioKind":"ex"},{"en":"Nasty comments on social media can discourage young people from participating in otherwise valuable online discussions.","vi":"Những bình luận ác ý trên mạng xã hội có thể làm nhụt chí những người trẻ muốn tham gia vào các cuộc thảo luận trực tuyến vốn dĩ rất giá trị.","audioKind":"ex2"}],"collocations":[{"en":"nasty smell","vi":"mùi khó chịu"},{"en":"nasty comment","vi":"bình luận ác ý"},{"en":"nasty injury","vi":"chấn thương nặng"},{"en":"nasty shock","vi":"cú sốc bất ngờ"}],"wordFamily":["nastily (adv.)","nastiness (n.)"],"synonyms":["unpleasant","mean"],"antonyms":["pleasant","kind"],"tipVi":"Từ nasty mang sắc thái ghê tởm hơn bad; khi dùng cho người thường có nghĩa là cay nghiệt, bất thiện.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_silver', 'en-a2-44', 'silver', '/ˈsɪlvər/', 'A2', 'bạc (kim loại quý); có màu xám bạc; làm bằng bạc; huy chương bạc', 'n.', 'silvery (adj.)', NULL, 'Khi chỉ kim loại bạc thì từ này không đếm được; a silver có thể dùng để chỉ một huy chương bạc.', 'This little spoon is made of pure silver.', NULL, 'Chiếc thìa nhỏ này được làm bằng bạc nguyên chất.', '{"wordId":"silver","ukIpa":"/ˈsɪlvə/","usIpa":"/ˈsɪlvər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A shiny greyish-white precious metal used for jewellery and coins.","vi":"bạc (kim loại quý)"},{"pos":"adj.","en":"Having a shiny greyish-white colour, or made of silver.","vi":"có màu xám bạc; làm bằng bạc"},{"pos":"n.","en":"A medal awarded for second place in a competition.","vi":"huy chương bạc"}],"examples":[{"en":"This little spoon is made of pure silver.","vi":"Chiếc thìa nhỏ này được làm bằng bạc nguyên chất.","audioKind":"ex"},{"en":"Silver is widely used in electronic devices because it conducts electricity exceptionally well.","vi":"Bạc được sử dụng rộng rãi trong các thiết bị điện tử vì nó dẫn điện cực kỳ tốt.","audioKind":"ex2"}],"collocations":[{"en":"pure silver","vi":"bạc nguyên chất"},{"en":"a silver medal","vi":"huy chương bạc"},{"en":"silver jewellery","vi":"trang sức bạc"}],"wordFamily":["silvery (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Khi chỉ kim loại bạc thì từ này không đếm được; a silver có thể dùng để chỉ một huy chương bạc.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_differently', 'en-a2-44', 'differently', '/ˈdɪfrəntli/', 'A2', 'khác biệt; theo cách khác', 'adv.', 'different (adj.), difference (n.), differ (v.)', 'Trái nghĩa: similarly', 'Phó từ dùng để bổ nghĩa cho động từ; nếu muốn nói người hoặc vật khác nhau thì dùng tính từ different.', 'My sister and I arrange our desks differently.', NULL, 'Tôi và chị gái sắp xếp bàn làm việc theo những cách khác nhau.', '{"wordId":"differently","ukIpa":"/ˈdɪfrəntli/","usIpa":"/ˈdɪfrəntli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"in a way that is not the same","vi":"khác biệt; theo cách khác"}],"examples":[{"en":"My sister and I arrange our desks differently.","vi":"Tôi và chị gái sắp xếp bàn làm việc theo những cách khác nhau.","audioKind":"ex"},{"en":"Students learn differently, so teachers should offer varied activities rather than rely on a single method.","vi":"Học sinh tiếp thu kiến thức theo những cách khác nhau, vì vậy giáo viên nên cung cấp các hoạt động đa dạng thay vì chỉ dựa vào một phương pháp duy nhất.","audioKind":"ex2"}],"collocations":[{"en":"think differently","vi":"tư duy theo cách khác"},{"en":"treat someone differently","vi":"đối xử khác biệt với ai"},{"en":"react differently","vi":"phản ứng khác nhau"},{"en":"do things differently","vi":"làm mọi việc theo cách khác"}],"wordFamily":["different (adj.)","difference (n.)","differ (v.)"],"synonyms":[],"antonyms":["similarly"],"tipVi":"Phó từ dùng để bổ nghĩa cho động từ; nếu muốn nói người hoặc vật khác nhau thì dùng tính từ different.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_almost', 'en-a2-44', 'almost', '/ˈɔːlmoʊst/', 'A2', 'gần như, hầu như', 'adv.', NULL, 'Đồng nghĩa: nearly, practically', 'almost có thể kết hợp với all, every và no; không được kết hợp trực tiếp với most.', 'I almost missed the bus while tying my shoes.', NULL, 'Tôi suýt lỡ chuyến xe buýt vì mải buộc dây giày.', '{"wordId":"almost","ukIpa":"/ˈɔːlməʊst/","usIpa":"/ˈɔːlmoʊst/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"Nearly, but not completely or not quite.","vi":"gần như, hầu như"}],"examples":[{"en":"I almost missed the bus while tying my shoes.","vi":"Tôi suýt lỡ chuyến xe buýt vì mải buộc dây giày.","audioKind":"ex"},{"en":"Almost all participants agreed that affordable public transport would improve their access to employment opportunities.","vi":"Hầu như tất cả người tham gia đều đồng ý rằng phương tiện giao thông công cộng giá rẻ sẽ giúp họ tiếp cận tốt hơn với các cơ hội việc làm.","audioKind":"ex2"}],"collocations":[{"en":"almost all","vi":"hầu như tất cả"},{"en":"almost certainly","vi":"hầu như chắc chắn"},{"en":"almost impossible","vi":"gần như không thể"},{"en":"almost every day","vi":"hầu như mỗi ngày"}],"wordFamily":[],"synonyms":["nearly","practically"],"antonyms":[],"tipVi":"almost có thể kết hợp với all, every và no; không được kết hợp trực tiếp với most.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_exactly', 'en-a2-44', 'exactly', '/ɪɡˈzæktli/', 'A2', 'chính xác; hoàn toàn; chính xác thế; đúng vậy', 'adv.', 'exact (adj.), exactness (n.)', 'Đồng nghĩa: precisely · Trái nghĩa: approximately, roughly', 'not exactly thường mang ý nghĩa không hẳn là như vậy, hoặc dùng để phủ định một cách nhẹ nhàng, lịch sự.', 'This jacket is exactly the colour I wanted.', NULL, 'Chiếc áo khoác này có màu chính xác như tôi muốn.', '{"wordId":"exactly","ukIpa":"/ɪɡˈzæktli/","usIpa":"/ɪɡˈzæktli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"Precisely, with no difference or error.","vi":"chính xác; hoàn toàn"},{"pos":"adv.","en":"Used to confirm that something is completely correct.","vi":"chính xác thế; đúng vậy"}],"examples":[{"en":"This jacket is exactly the colour I wanted.","vi":"Chiếc áo khoác này có màu chính xác như tôi muốn.","audioKind":"ex"},{"en":"Researchers must record exactly how much energy each household uses to ensure reliable comparisons between regions.","vi":"Các nhà nghiên cứu phải ghi chép chính xác lượng năng lượng mà mỗi hộ gia đình tiêu thụ để đảm bảo tính đáng tin cậy khi so sánh giữa các khu vực.","audioKind":"ex2"}],"collocations":[{"en":"exactly the same","vi":"hoàn toàn giống nhau"},{"en":"exactly right","vi":"hoàn toàn chính xác"},{"en":"know exactly","vi":"biết chính xác"}],"wordFamily":["exact (adj.)","exactness (n.)"],"synonyms":["precisely"],"antonyms":["approximately","roughly"],"tipVi":"not exactly thường mang ý nghĩa không hẳn là như vậy, hoặc dùng để phủ định một cách nhẹ nhàng, lịch sự.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_either', 'en-a2-44', 'either', '/ˈiːðər/', 'A2', 'mỗi (trong hai); bất kỳ (trong hai); một trong hai người hoặc vật; cũng không', 'det.', NULL, NULL, 'either…or… diễn tả sự lựa chọn giữa hai khả năng; ở cuối câu phủ định, either mang nghĩa "cũng không".', 'You can borrow either umbrella; both are dry.', NULL, 'Bạn có thể mượn bất kỳ cây dù nào trong hai cây; cả hai đều khô ráo.', '{"wordId":"either","ukIpa":"/ˈaɪðə/","usIpa":"/ˈiːðər/","cefr":"A2","topic":"daily","senses":[{"pos":"det.","en":"One or the other of two; each of two sides.","vi":"mỗi (trong hai); bất kỳ (trong hai)"},{"pos":"pron.","en":"One or the other of two people or things.","vi":"một trong hai người hoặc vật"},{"pos":"adv.","en":"Also not, used after a negative statement.","vi":"cũng không"}],"examples":[{"en":"You can borrow either umbrella; both are dry.","vi":"Bạn có thể mượn bất kỳ cây dù nào trong hai cây; cả hai đều khô ráo.","audioKind":"ex"},{"en":"Students can choose either vocational training or university education, depending on their interests and career goals.","vi":"Học sinh có thể chọn học nghề hoặc giáo dục đại học, tùy thuộc vào sở thích và mục tiêu nghề nghiệp của các em.","audioKind":"ex2"}],"collocations":[{"en":"either way","vi":"dù theo cách nào đi nữa"},{"en":"either side","vi":"cả hai bên; mỗi bên"},{"en":"not either","vi":"cũng không"},{"en":"either of them","vi":"bất kỳ ai trong số họ"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"either…or… diễn tả sự lựa chọn giữa hai khả năng; ở cuối câu phủ định, either mang nghĩa \"cũng không\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_suddenly', 'en-a2-44', 'suddenly', '/ˈsʌdənli/', 'A2', 'đột ngột; bỗng nhiên', 'adv.', 'sudden (adj.), suddenness (n.)', 'Đồng nghĩa: abruptly · Trái nghĩa: gradually', 'Có thể đứng ở đầu câu hoặc trước động từ; nhấn mạnh sự thay đổi diễn ra bất ngờ, không báo trước.', 'The lights suddenly went out while we were cooking.', NULL, 'Đèn bỗng nhiên vụt tắt khi chúng tôi đang nấu ăn.', '{"wordId":"suddenly","ukIpa":"/ˈsʌdənli/","usIpa":"/ˈsʌdənli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"Quickly and unexpectedly, with little or no warning.","vi":"đột ngột; bỗng nhiên"}],"examples":[{"en":"The lights suddenly went out while we were cooking.","vi":"Đèn bỗng nhiên vụt tắt khi chúng tôi đang nấu ăn.","audioKind":"ex"},{"en":"When demand suddenly increases, public transport systems may struggle to provide enough services for passengers.","vi":"Khi nhu cầu đột ngột tăng lên, hệ thống giao thông công cộng có thể gặp khó khăn trong việc cung cấp đủ chuyến cho hành khách.","audioKind":"ex2"}],"collocations":[{"en":"suddenly appear","vi":"đột ngột xuất hiện"},{"en":"suddenly realise","vi":"bỗng nhận ra"},{"en":"stop suddenly","vi":"dừng lại đột ngột"}],"wordFamily":["sudden (adj.)","suddenness (n.)"],"synonyms":["abruptly"],"antonyms":["gradually"],"tipVi":"Có thể đứng ở đầu câu hoặc trước động từ; nhấn mạnh sự thay đổi diễn ra bất ngờ, không báo trước.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_scissors', 'en-a2-44', 'scissors', '/ˈsɪzərz/', 'A2', 'cái kéo; cây kéo', 'n.', NULL, NULL, 'Thường ở dạng số nhiều; một cái kéo nói là a pair of scissors.', 'Please use these scissors to cut the wrapping paper.', NULL, 'Xin vui lòng dùng cái kéo này để cắt giấy gói quà.', '{"wordId":"scissors","ukIpa":"/ˈsɪzəz/","usIpa":"/ˈsɪzərz/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A tool with two blades for cutting things.","vi":"cái kéo; cây kéo"}],"examples":[{"en":"Please use these scissors to cut the wrapping paper.","vi":"Xin vui lòng dùng cái kéo này để cắt giấy gói quà.","audioKind":"ex"},{"en":"Teachers should supervise young children when they use scissors during classroom craft activities.","vi":"Giáo viên nên giám sát trẻ nhỏ khi các em sử dụng kéo trong các hoạt động thủ công ở lớp.","audioKind":"ex2"}],"collocations":[{"en":"a pair of scissors","vi":"một cái kéo"},{"en":"sharp scissors","vi":"cái kéo bén"},{"en":"cut with scissors","vi":"cắt bằng kéo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Thường ở dạng số nhiều; một cái kéo nói là a pair of scissors.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 14, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_own', 'en-a2-44', 'own', '/oʊn/', 'A2', 'của chính mình; riêng; sở hữu; có', 'adj.', 'owner (n.), ownership (n.)', 'Đồng nghĩa: possess', 'own mang nghĩa "của chính mình" thường đứng sau từ chỉ sở hữu, chẳng hạn như my own.', 'I finally have my own room in our new flat.', NULL, 'Cuối cùng tôi đã có căn phòng riêng trong căn hộ mới của chúng tôi.', '{"wordId":"own","ukIpa":"/əʊn/","usIpa":"/oʊn/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Belonging to a particular person, rather than someone else.","vi":"của chính mình; riêng"},{"pos":"v.","en":"To have something that legally belongs to you.","vi":"sở hữu; có"}],"examples":[{"en":"I finally have my own room in our new flat.","vi":"Cuối cùng tôi đã có căn phòng riêng trong căn hộ mới của chúng tôi.","audioKind":"ex"},{"en":"People who own their homes may feel more financially secure, although maintenance costs can be substantial.","vi":"Những người sở hữu nhà riêng có thể cảm thấy an toàn hơn về mặt tài chính, mặc dù chi phí bảo trì nhà cửa có thể khá lớn.","audioKind":"ex2"}],"collocations":[{"en":"my own room","vi":"căn phòng riêng của tôi"},{"en":"own a home","vi":"sở hữu một ngôi nhà"},{"en":"on your own","vi":"tự lập; một mình"},{"en":"of your own","vi":"của riêng bạn"}],"wordFamily":["owner (n.)","ownership (n.)"],"synonyms":["possess"],"antonyms":[],"tipVi":"own mang nghĩa \"của chính mình\" thường đứng sau từ chỉ sở hữu, chẳng hạn như my own.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 15, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_wooden', 'en-a2-44', 'wooden', '/ˈwʊdən/', 'A2', 'làm bằng gỗ; cứng nhắc; gượng gạo', 'adj.', 'wood (n.), wooded (adj.), woody (adj.)', NULL, 'wooden chỉ đồ vật làm bằng gỗ; woody thường chỉ chất gỗ hoặc có tính chất như gỗ.', 'She stirred the soup slowly with a wooden spoon.', NULL, 'Cô ấy dùng một chiếc thìa gỗ để khuấy súp từ từ.', '{"wordId":"wooden","ukIpa":"/ˈwʊdən/","usIpa":"/ˈwʊdən/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"made of wood","vi":"làm bằng gỗ"},{"pos":"adj.","en":"showing little natural feeling or movement","vi":"cứng nhắc; gượng gạo"}],"examples":[{"en":"She stirred the soup slowly with a wooden spoon.","vi":"Cô ấy dùng một chiếc thìa gỗ để khuấy súp từ từ.","audioKind":"ex"},{"en":"Wooden buildings can offer environmental benefits when their materials come from responsibly managed forests.","vi":"Các công trình bằng gỗ có thể mang lại lợi ích môi trường khi vật liệu của chúng đến từ các khu rừng được quản lý có trách nhiệm.","audioKind":"ex2"}],"collocations":[{"en":"wooden floor","vi":"sàn gỗ"},{"en":"wooden furniture","vi":"đồ nội thất bằng gỗ"},{"en":"wooden spoon","vi":"thìa gỗ"},{"en":"wooden performance","vi":"buổi biểu diễn gượng gạo"}],"wordFamily":["wood (n.)","wooded (adj.)","woody (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"wooden chỉ đồ vật làm bằng gỗ; woody thường chỉ chất gỗ hoặc có tính chất như gỗ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 16, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_necessary', 'en-a2-44', 'necessary', '/ˈnesəseri/', 'A2', 'cần thiết; thiết yếu', 'adj.', 'necessity (n.), necessarily (adv.), unnecessary (adj.), necessitate (v.)', 'Đồng nghĩa: essential, required · Trái nghĩa: unnecessary', 'Cấu trúc phổ biến là it is necessary to do; necessarily có nghĩa là "tất yếu/được một cách tất yếu".', 'Take a warm coat if you think it''s necessary.', NULL, 'Hãy mang theo một chiếc áo khoác ấm nếu bạn thấy cần thiết.', '{"wordId":"necessary","ukIpa":"/ˈnesəsəri/","usIpa":"/ˈnesəseri/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"needed for a particular purpose or situation","vi":"cần thiết; thiết yếu"}],"examples":[{"en":"Take a warm coat if you think it''s necessary.","vi":"Hãy mang theo một chiếc áo khoác ấm nếu bạn thấy cần thiết.","audioKind":"ex"},{"en":"Investment in public transport is necessary to reduce traffic congestion and improve urban air quality.","vi":"Việc đầu tư vào giao thông công cộng là cần thiết để giảm thiểu tình trạng ùn tắc giao thông và cải thiện chất lượng không khí đô thị.","audioKind":"ex2"}],"collocations":[{"en":"if necessary","vi":"nếu cần thiết"},{"en":"necessary precautions","vi":"các biện pháp phòng ngừa cần thiết"},{"en":"necessary for","vi":"cần thiết cho"},{"en":"absolutely necessary","vi":"hoàn toàn cần thiết"}],"wordFamily":["necessity (n.)","necessarily (adv.)","unnecessary (adj.)","necessitate (v.)"],"synonyms":["essential","required"],"antonyms":["unnecessary"],"tipVi":"Cấu trúc phổ biến là it is necessary to do; necessarily có nghĩa là \"tất yếu/được một cách tất yếu\".","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 17, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_air-conditioning', 'en-a2-44', 'air-conditioning', '/ˈer kəndɪʃənɪŋ/', 'A2', 'hệ thống điều hòa không khí; máy lạnh', 'n.', 'air conditioner (n.), air-conditioned (adj.)', NULL, 'Danh từ không đếm được; một chiếc máy điều hòa dùng là an air conditioner.', 'Please turn on the air-conditioning before the guests arrive.', NULL, 'Xin hãy bật điều hòa trước khi khách đến nhé.', '{"wordId":"air-conditioning","ukIpa":"/ˈeə kəndɪʃənɪŋ/","usIpa":"/ˈer kəndɪʃənɪŋ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A system that cools indoor air and controls humidity.","vi":"hệ thống điều hòa không khí; máy lạnh"}],"examples":[{"en":"Please turn on the air-conditioning before the guests arrive.","vi":"Xin hãy bật điều hòa trước khi khách đến nhé.","audioKind":"ex"},{"en":"Greater reliance on air-conditioning during heatwaves can place considerable pressure on urban electricity supplies.","vi":"Việc phụ thuộc nhiều hơn vào điều hòa không khí trong các đợt nắng nóng có thể gây áp lực đáng kể lên nguồn cung cấp điện đô thị.","audioKind":"ex2"}],"collocations":[{"en":"air-conditioning system","vi":"hệ thống điều hòa không khí"},{"en":"central air-conditioning","vi":"hệ thống điều hòa trung tâm"},{"en":"turn on the air-conditioning","vi":"bật điều hòa"}],"wordFamily":["air conditioner (n.)","air-conditioned (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Danh từ không đếm được; một chiếc máy điều hòa dùng là an air conditioner.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_messy', 'en-a2-44', 'messy', '/ˈmesi/', 'A2', 'lộn xộn; bừa bãi; bẩn thỉu; rắc rối; phức tạp; khó giải quyết', 'adj.', 'mess (n.), messily (adv.), messiness (n.)', 'Đồng nghĩa: untidy, disorderly · Trái nghĩa: tidy, neat', 'messy có thể chỉ đồ đạc bừa bộn, hoặc chỉ tình huống phức tạp khó xử lý.', 'His desk was messy after an afternoon of painting.', NULL, 'Bàn làm việc của cậu ấy bừa bộn sau cả buổi chiều tô vẽ.', '{"wordId":"messy","ukIpa":"/ˈmesi/","usIpa":"/ˈmesi/","cefr":"A2","topic":"daily","senses":[{"pos":"adj.","en":"Untidy or dirty, with things scattered or out of place.","vi":"lộn xộn; bừa bãi; bẩn thỉu"},{"pos":"adj.","en":"Complicated and difficult to deal with.","vi":"rắc rối; phức tạp; khó giải quyết"}],"examples":[{"en":"His desk was messy after an afternoon of painting.","vi":"Bàn làm việc của cậu ấy bừa bộn sau cả buổi chiều tô vẽ.","audioKind":"ex"},{"en":"Without clear responsibilities, cooperation between public agencies can become messy and delay the delivery of essential services.","vi":"Nếu không có trách nhiệm rõ ràng, sự hợp tác giữa các cơ quan công quyền có thể trở nên rối rắm và làm chậm trễ việc cung cấp các dịch vụ thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"messy room","vi":"phòng ốc bừa bộn"},{"en":"messy handwriting","vi":"chữ viết nguệch ngoạc"},{"en":"messy situation","vi":"tình thế rắc rối"}],"wordFamily":["mess (n.)","messily (adv.)","messiness (n.)"],"synonyms":["untidy","disorderly"],"antonyms":["tidy","neat"],"tipVi":"messy có thể chỉ đồ đạc bừa bộn, hoặc chỉ tình huống phức tạp khó xử lý.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_recently', 'en-a2-44', 'recently', '/ˈriːsəntli/', 'A2', 'gần đây; mới đây', 'adv.', 'recent (adj.)', 'Đồng nghĩa: lately', 'Có thể dùng với thì quá khứ đơn hoặc hiện đại hoàn thành, không giới hạn chỉ ở thì hoàn thành.', 'We recently moved into a flat near the river.', NULL, 'Chúng tôi mới chuyển đến một căn hộ gần bờ sông.', '{"wordId":"recently","ukIpa":"/ˈriːsəntli/","usIpa":"/ˈriːsəntli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"Not long ago, or during the period just before now.","vi":"gần đây; mới đây"}],"examples":[{"en":"We recently moved into a flat near the river.","vi":"Chúng tôi mới chuyển đến một căn hộ gần bờ sông.","audioKind":"ex"},{"en":"Researchers have recently explored how access to green spaces influences the mental health of urban residents.","vi":"Các nhà nghiên cứu gần đây đã khám phá ra việc tiếp cận không gian xanh ảnh hưởng như thế nào đến sức khỏe tâm thần của cư dân thành thị.","audioKind":"ex2"}],"collocations":[{"en":"until recently","vi":"cho đến tận gần đây"},{"en":"only recently","vi":"mới đây thôi"},{"en":"recently published","vi":"mới được xuất bản gần đây"}],"wordFamily":["recent (adj.)"],"synonyms":["lately"],"antonyms":[],"tipVi":"Có thể dùng với thì quá khứ đơn hoặc hiện đại hoàn thành, không giới hạn chỉ ở thì hoàn thành.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mostly', 'en-a2-44', 'mostly', '/ˈmoʊstli/', 'A2', 'chủ yếu là; phần lớn là', 'adv.', 'most (adv.)', 'Đồng nghĩa: mainly, largely, chiefly', 'mostly chỉ phần lớn hoặc đa số trường hợp; almost chỉ sự suýt soát hoặc hầu như.', 'My weekend was mostly spent cooking and reading.', NULL, 'Cuối tuần của tôi phần lớn dành cho việc nấu ăn và đọc sách.', '{"wordId":"mostly","ukIpa":"/ˈməʊstli/","usIpa":"/ˈmoʊstli/","cefr":"A2","topic":"daily","senses":[{"pos":"adv.","en":"mainly, or for the largest part","vi":"chủ yếu là; phần lớn là"}],"examples":[{"en":"My weekend was mostly spent cooking and reading.","vi":"Cuối tuần của tôi phần lớn dành cho việc nấu ăn và đọc sách.","audioKind":"ex"},{"en":"In many rural areas, residents rely mostly on private vehicles because public transport services are limited.","vi":"Ở nhiều vùng nông thôn, cư dân chủ yếu phụ thuộc vào xe cá nhân vì các dịch vụ giao thông công cộng còn hạn chế.","audioKind":"ex2"}],"collocations":[{"en":"mostly sunny","vi":"hầu hết thời gian trời nắng"},{"en":"mostly made of","vi":"chủ yếu làm từ"},{"en":"mostly because","vi":"chủ yếu là vì"}],"wordFamily":["most (adv.)"],"synonyms":["mainly","largely","chiefly"],"antonyms":[],"tipVi":"mostly chỉ phần lớn hoặc đa số trường hợp; almost chỉ sự suýt soát hoặc hầu như.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_shake', 'en-a2-44', 'shake', '/ʃeɪk/', 'A2', 'lắc; rung; run rẩy; làm chấn động; làm lung lay; cái lắc; cái rung', 'v.', 'shaky (adj.), shakily (adv.)', 'Đồng nghĩa: tremble, quiver', 'Biến đổi bất quy tắc: shake—shook—shaken.', 'Shake the bottle well before pouring juice into your glass.', NULL, 'Lắc đều chai trước khi rót nước ép ra cốc.', '{"wordId":"shake","ukIpa":"/ʃeɪk/","usIpa":"/ʃeɪk/","cefr":"A2","topic":"daily","senses":[{"pos":"v.","en":"to move quickly back and forth, or cause this movement","vi":"lắc; rung; run rẩy"},{"pos":"v.","en":"to upset someone deeply or weaken their confidence","vi":"làm chấn động; làm lung lay"},{"pos":"n.","en":"a quick movement back and forth","vi":"cái lắc; cái rung"}],"examples":[{"en":"Shake the bottle well before pouring juice into your glass.","vi":"Lắc đều chai trước khi rót nước ép ra cốc.","audioKind":"ex"},{"en":"Repeated failures in public transport can shake commuters'' confidence in the reliability of urban services.","vi":"Việc phương tiện giao thông công cộng liên tục gặp sự cố có thể làm lung lay niềm tin của người đi làm vào độ tin cậy của các dịch vụ đô thị.","audioKind":"ex2"}],"collocations":[{"en":"shake hands","vi":"bắt tay"},{"en":"shake your head","vi":"lắc đầu"},{"en":"shake with fear","vi":"run lên vì sợ"},{"en":"shake confidence","vi":"làm lung lay niềm tin"}],"wordFamily":["shaky (adj.)","shakily (adv.)"],"synonyms":["tremble","quiver"],"antonyms":[],"tipVi":"Biến đổi bất quy tắc: shake—shook—shaken.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_litre', 'en-a2-44', 'litre', '/ˈliːtər/', 'A2', 'lít (đơn vị thể tích)', 'n.', NULL, NULL, 'Cách viết Anh-Anh là litre, Anh-Mỹ là liter; số ít và số nhiều thêm s.', 'We need a litre of milk for this pudding.', NULL, 'Chúng ta cần một lít sữa cho món bánh pudding này.', '{"wordId":"litre","ukIpa":"/ˈliːtə/","usIpa":"/ˈliːtər/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a unit of volume equal to one thousand millilitres","vi":"lít (đơn vị thể tích)"}],"examples":[{"en":"We need a litre of milk for this pudding.","vi":"Chúng ta cần một lít sữa cho món bánh pudding này.","audioKind":"ex"},{"en":"Measuring household water use in litres can help residents understand consumption and identify opportunities to reduce waste.","vi":"Việc đo lường lượng nước sử dụng trong hộ gia đình bằng đơn vị lít có thể giúp cư dân hiểu rõ mức tiêu thụ và tìm ra cơ hội giảm thiểu lãng phí.","audioKind":"ex2"}],"collocations":[{"en":"a litre of milk","vi":"một lít sữa"},{"en":"half a litre","vi":"nửa lít"},{"en":"litres per minute","vi":"số lít mỗi phút"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Cách viết Anh-Anh là litre, Anh-Mỹ là liter; số ít và số nhiều thêm s.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_haircut', 'en-a2-44', 'haircut', '/ˈherkʌt/', 'A2', 'sự cắt tóc; kiểu tóc', 'n.', 'hair (n.), hairdresser (n.)', NULL, 'Dùng get hoặc have a haircut, không dùng cut a haircut.', 'I need a haircut before my cousin''s wedding.', NULL, 'Tôi cần đi cắt tóc trước đám cưới của anh họ tôi.', '{"wordId":"haircut","ukIpa":"/ˈheəkʌt/","usIpa":"/ˈherkʌt/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"An act of cutting hair, or the resulting hairstyle.","vi":"sự cắt tóc; kiểu tóc"}],"examples":[{"en":"I need a haircut before my cousin''s wedding.","vi":"Tôi cần đi cắt tóc trước đám cưới của anh họ tôi.","audioKind":"ex"},{"en":"Offering affordable haircuts at community centres can help trainee hairdressers gain practical experience while serving local residents.","vi":"Cung cấp dịch vụ cắt tóc giá cả phải chăng tại các trung tâm cộng đồng có thể giúp thợ cắt tóc thực tập tích lũy kinh nghiệm thực tế đồng thời phục vụ người dân địa phương.","audioKind":"ex2"}],"collocations":[{"en":"get a haircut","vi":"đi cắt tóc"},{"en":"a short haircut","vi":"kiểu tóc ngắn"},{"en":"need a haircut","vi":"cần cắt tóc"}],"wordFamily":["hair (n.)","hairdresser (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Dùng get hoặc have a haircut, không dùng cut a haircut.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_pineapple', 'en-a2-44', 'pineapple', '/ˈpaɪnæpəl/', 'A2', 'quả dứa; quả thơm', 'n.', NULL, NULL, 'Quả dứa nguyên vẹn đếm được, phần thịt dứa dùng làm thức ăn thường không đếm được.', 'She sliced a fresh pineapple for our picnic.', NULL, 'Cô ấy đã thái một quả dứa tươi cho buổi dã ngoại của chúng tôi.', '{"wordId":"pineapple","ukIpa":"/ˈpaɪnæpəl/","usIpa":"/ˈpaɪnæpəl/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"a tropical fruit with rough skin and sweet yellow flesh","vi":"quả dứa; quả thơm"}],"examples":[{"en":"She sliced a fresh pineapple for our picnic.","vi":"Cô ấy đã thái một quả dứa tươi cho buổi dã ngoại của chúng tôi.","audioKind":"ex"},{"en":"Growing pineapple for export can support rural incomes, but intensive farming may damage local soils.","vi":"Trồng dứa để xuất khẩu có thể hỗ trợ thu nhập nông thôn, nhưng canh tác thâm canh có thể làm hại đất đai địa phương.","audioKind":"ex2"}],"collocations":[{"en":"fresh pineapple","vi":"dứa tươi"},{"en":"pineapple juice","vi":"nước ép dứa"},{"en":"pineapple chunks","vi":"dứa cắt miếng"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Quả dứa nguyên vẹn đếm được, phần thịt dứa dùng làm thức ăn thường không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 25, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_mirror', 'en-a2-44', 'mirror', '/ˈmɪrɚ/', 'A2', 'cái gương; phản chiếu; phản ánh', 'n.', NULL, 'Đồng nghĩa: reflect', 'Soi gương dùng look in the mirror, không dùng look the mirror.', 'He checked his hair in the mirror before leaving.', NULL, 'Anh ấy soi gương chỉnh lại mái tóc trước khi rời đi.', '{"wordId":"mirror","ukIpa":"/ˈmɪrə/","usIpa":"/ˈmɪrɚ/","cefr":"A2","topic":"daily","senses":[{"pos":"n.","en":"A smooth surface, usually glass, that shows a reflected image.","vi":"cái gương"},{"pos":"v.","en":"Show the same qualities, changes, or features as something else.","vi":"phản chiếu; phản ánh"}],"examples":[{"en":"He checked his hair in the mirror before leaving.","vi":"Anh ấy soi gương chỉnh lại mái tóc trước khi rời đi.","audioKind":"ex"},{"en":"Changes in consumer spending often mirror broader economic trends, particularly during periods of financial uncertainty.","vi":"Sự thay đổi trong chi tiêu của người tiêu dùng thường phản ánh các xu hướng kinh tế rộng lớn hơn, đặc biệt trong những giai đoạn bất ổn tài chính.","audioKind":"ex2"}],"collocations":[{"en":"look in the mirror","vi":"soi gương"},{"en":"a full-length mirror","vi":"gương toàn thân"},{"en":"mirror changes","vi":"phản ánh sự thay đổi"},{"en":"mirror reality","vi":"phản ánh thực tế"}],"wordFamily":[],"synonyms":["reflect"],"antonyms":[],"tipVi":"Soi gương dùng look in the mirror, không dùng look the mirror.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 26, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_44_1', 'en-a2-44', 'Cách dùng “exactly” (adv.) — chính xác; hoàn toàn', 'exactly the same  ·  exactly right  ·  know exactly', 'not exactly thường mang ý nghĩa không hẳn là như vậy, hoặc dùng để phủ định một cách nhẹ nhàng, lịch sự.', 'Họ từ (Word Family): exact (adj.), exactness (n.) | Đồng nghĩa: precisely · Trái nghĩa: approximately, roughly', '[{"hanzi":"This jacket is exactly the colour I wanted.","pinyin":"","meaning":"Chiếc áo khoác này có màu chính xác như tôi muốn."},{"hanzi":"Researchers must record exactly how much energy each household uses to ensure reliable comparisons between regions.","pinyin":"","meaning":"Các nhà nghiên cứu phải ghi chép chính xác lượng năng lượng mà mỗi hộ gia đình tiêu thụ để đảm bảo tính đáng tin cậy khi so sánh giữa các khu vực."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_44_2', 'en-a2-44', 'Cách dùng “dessert” (n.) — món tráng miệng', 'for dessert  ·  dessert menu  ·  fruit dessert', 'dessert có hai chữ s, trọng âm rơi vào âm tiết sau; desert mang nghĩa sa mạc có trọng âm ở âm tiết đầu.', 'Đồng nghĩa: sweet', '[{"hanzi":"We shared a bowl of ice cream for dessert.","pinyin":"","meaning":"Chúng tôi chia nhau một bát kem làm món tráng miệng."},{"hanzi":"Offering fresh fruit for dessert can help school cafeterias encourage healthier eating habits among children.","pinyin":"","meaning":"Cung cấp trái cây tươi làm món tráng miệng có thể giúp các căn tin trường học khuyến khích thói quen ăn uống lành mạnh hơn ở trẻ em."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_44_3', 'en-a2-44', 'Cách dùng “differently” (adv.) — khác biệt; theo cách khác', 'think differently  ·  treat someone differently  ·  react differently', 'Phó từ dùng để bổ nghĩa cho động từ; nếu muốn nói người hoặc vật khác nhau thì dùng tính từ different.', 'Họ từ (Word Family): different (adj.), difference (n.), differ (v.) | Trái nghĩa: similarly', '[{"hanzi":"My sister and I arrange our desks differently.","pinyin":"","meaning":"Tôi và chị gái sắp xếp bàn làm việc theo những cách khác nhau."},{"hanzi":"Students learn differently, so teachers should offer varied activities rather than rely on a single method.","pinyin":"","meaning":"Học sinh tiếp thu kiến thức theo những cách khác nhau, vì vậy giáo viên nên cung cấp các hoạt động đa dạng thay vì chỉ dựa vào một phương pháp duy nhất."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_44_4', 'en-a2-44', 'Cách dùng “either” (det.) — mỗi (trong hai); bất kỳ (trong hai)', 'either way  ·  either side  ·  not either', 'either…or… diễn tả sự lựa chọn giữa hai khả năng; ở cuối câu phủ định, either mang nghĩa "cũng không".', NULL, '[{"hanzi":"You can borrow either umbrella; both are dry.","pinyin":"","meaning":"Bạn có thể mượn bất kỳ cây dù nào trong hai cây; cả hai đều khô ráo."},{"hanzi":"Students can choose either vocational training or university education, depending on their interests and career goals.","pinyin":"","meaning":"Học sinh có thể chọn học nghề hoặc giáo dục đại học, tùy thuộc vào sở thích và mục tiêu nghề nghiệp của các em."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_44_1', 'en-a2-44', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_44_1_1', 'ten_a2_44_1', 'accident', 'Luckily, nobody was hurt in the accident outside our house.', 'Luckily, nobody was hurt in the accident outside our house.', '/ˈæksɪdənt/', 'May mắn là không ai bị thương trong vụ tai nạn xảy ra ngay trước nhà chúng tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_44_1_2', 'ten_a2_44_1', 'touch', 'Please don''t touch the pan; it is still hot.', 'Please don''t touch the pan; it is still hot.', '/tʌtʃ/', 'Xin đừng chạm vào cái chảo; nó vẫn còn rất nóng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_44_1_3', 'ten_a2_44_1', 'dessert', 'We shared a bowl of ice cream for dessert.', 'We shared a bowl of ice cream for dessert.', '/dɪˈzɝːt/', 'Chúng tôi chia nhau một bát kem làm món tráng miệng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_44_1_4', 'ten_a2_44_1', 'spoon', 'She stirred her soup with a wooden spoon.', 'She stirred her soup with a wooden spoon.', '/spuːn/', 'Cô ấy dùng một chiếc muỗng gỗ để khuấy súp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_44_1_5', 'ten_a2_44_1', 'ZIP code', 'Please include your ZIP code when entering your address.', 'Please include your ZIP code when entering your address.', '/ˈzɪp koʊd/', 'Vui lòng ghi kèm mã bưu chính khi điền địa chỉ của bạn.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_44_1_6', 'ten_a2_44_1', 'pea', 'She added frozen peas to the vegetable soup.', 'She added frozen peas to the vegetable soup.', '/piː/', 'Cô ấy đã cho thêm đậu Hà Lan đông lạnh vào món súp rau củ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_44_1_7', 'ten_a2_44_1', 'nasty', 'A nasty smell came from the kitchen bin.', 'A nasty smell came from the kitchen bin.', '/ˈnæsti/', 'Có một mùi khó chịu bốc ra từ thùng rác trong bếp.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_44_1_8', 'ten_a2_44_1', 'silver', 'This little spoon is made of pure silver.', 'This little spoon is made of pure silver.', '/ˈsɪlvər/', 'Chiếc thìa nhỏ này được làm bằng bạc nguyên chất.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_44_1_1', 'en-a2-44', 'ten_a2_44_1', 'listening', 'listening', 'Luckily, nobody was hurt in the accident outside our house.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng ta cần một lít sữa cho món bánh pudding này.","May mắn là không ai bị thương trong vụ tai nạn xảy ra ngay trước nhà chúng tôi.","Tôi cần đi cắt tóc trước đám cưới của anh họ tôi.","Xin vui lòng dùng cái kéo này để cắt giấy gói quà."]'::jsonb, 1, 'Luckily, nobody was hurt in the accident outside our house. → May mắn là không ai bị thương trong vụ tai nạn xảy ra ngay trước nhà chúng tôi.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_44_1_2', 'en-a2-44', 'ten_a2_44_1', 'listening', 'listening', 'Please don''t touch the pan; it is still hot.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Tôi cần đi cắt tóc trước đám cưới của anh họ tôi.","Vui lòng ghi kèm mã bưu chính khi điền địa chỉ của bạn.","Cuối cùng tôi đã có căn phòng riêng trong căn hộ mới của chúng tôi.","Xin đừng chạm vào cái chảo; nó vẫn còn rất nóng."]'::jsonb, 3, 'Please don''t touch the pan; it is still hot. → Xin đừng chạm vào cái chảo; nó vẫn còn rất nóng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_44_1_3', 'en-a2-44', 'ten_a2_44_1', 'listening', 'listening', 'We shared a bowl of ice cream for dessert.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Cô ấy dùng một chiếc thìa gỗ để khuấy súp từ từ.","Tôi và chị gái sắp xếp bàn làm việc theo những cách khác nhau.","Cô ấy đã cho thêm đậu Hà Lan đông lạnh vào món súp rau củ.","Chúng tôi chia nhau một bát kem làm món tráng miệng."]'::jsonb, 3, 'We shared a bowl of ice cream for dessert. → Chúng tôi chia nhau một bát kem làm món tráng miệng.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_44_2', 'en-a2-44', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_44_2_1', 'ten_a2_44_2', 'accident', 'Better street lighting can reduce the risk of accidents involving cyclists and pedestrians at night.', 'Better street lighting can reduce the risk of accidents involving cyclists and pedestrians at night.', '/ˈæksɪdənt/', 'Hệ thống chiếu sáng đường phố tốt hơn có thể làm giảm nguy cơ xảy ra tai nạn liên quan đến người đi xe đạp và người đi bộ vào ban đêm.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_44_2_2', 'ten_a2_44_2', 'touch', 'Digital communication helps families stay in touch, even when work or study separates them across countries.', 'Digital communication helps families stay in touch, even when work or study separates them across countries.', '/tʌtʃ/', 'Giao tiếp kỹ thuật số giúp các gia đình giữ liên lạc, ngay cả khi công việc hoặc học tập chia cách họ ở các quốc gia khác nhau.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_44_2_3', 'ten_a2_44_2', 'dessert', 'Offering fresh fruit for dessert can help school cafeterias encourage healthier eating habits among children.', 'Offering fresh fruit for dessert can help school cafeterias encourage healthier eating habits among children.', '/dɪˈzɝːt/', 'Cung cấp trái cây tươi làm món tráng miệng có thể giúp các căn tin trường học khuyến khích thói quen ăn uống lành mạnh hơn ở trẻ em.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_44_2_4', 'ten_a2_44_2', 'spoon', 'Teaching children to use a spoon independently can help develop their coordination and confidence.', 'Teaching children to use a spoon independently can help develop their coordination and confidence.', '/spuːn/', 'Dạy trẻ tự múc ăn bằng thìa có thể giúp phát triển sự phối hợp vận động và sự tự tin của trẻ.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_44_2_5', 'ten_a2_44_2', 'ZIP code', 'Researchers grouped households by ZIP code to examine geographical differences in access to healthcare services.', 'Researchers grouped households by ZIP code to examine geographical differences in access to healthcare services.', '/ˈzɪp koʊd/', 'Các nhà nghiên cứu đã phân nhóm các hộ gia đình theo mã bưu chính để khảo sát sự khác biệt về khả năng tiếp cận dịch vụ y tế giữa các khu vực địa lý.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_44_2_6', 'ten_a2_44_2', 'pea', 'Growing peas and other vegetables at school can help children understand where their food comes from.', 'Growing peas and other vegetables at school can help children understand where their food comes from.', '/piː/', 'Việc trồng đậu Hà Lan và các loại rau củ khác tại trường học có thể giúp trẻ em hiểu rõ nguồn gốc thực phẩm của chúng.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
