INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_44_2', 'en-a2-44', NULL, 'comprehensive_test', 'listening', 'Please don''t touch the pan; it is still hot.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["May mắn là không ai bị thương trong vụ tai nạn xảy ra ngay trước nhà chúng tôi.","Xin đừng chạm vào cái chảo; nó vẫn còn rất nóng.","Anh ấy soi gương chỉnh lại mái tóc trước khi rời đi.","Chiếc áo khoác này có màu chính xác như tôi muốn."]'::jsonb, 1, 'Please don''t touch the pan; it is still hot. → Xin đừng chạm vào cái chảo; nó vẫn còn rất nóng.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_44_3', 'en-a2-44', NULL, 'comprehensive_test', 'listening', 'dessert', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["món tráng miệng","thức; tỉnh táo","chất dẻo; nhựa","vừa vặn; thích hợp; vừa"]'::jsonb, 0, 'dessert (/dɪˈzɝːt/) → món tráng miệng', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_44_4', 'en-a2-44', NULL, 'comprehensive_test', 'listening', 'She stirred her soup with a wooden spoon.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Cô ấy dùng một chiếc muỗng gỗ để khuấy súp.","Lắc đều chai trước khi rót nước ép ra cốc.","Cô ấy đã thái một quả dứa tươi cho buổi dã ngoại của chúng tôi.","Tôi cần đi cắt tóc trước đám cưới của anh họ tôi."]'::jsonb, 0, 'She stirred her soup with a wooden spoon. → Cô ấy dùng một chiếc muỗng gỗ để khuấy súp.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
