INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_44_6', 'en-a2-44', NULL, 'comprehensive_test', 'listening', 'She added frozen peas to the vegetable soup.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Đèn bỗng nhiên vụt tắt khi chúng tôi đang nấu ăn.","Cô ấy đã cho thêm đậu Hà Lan đông lạnh vào món súp rau củ.","Bàn làm việc của cậu ấy bừa bộn sau cả buổi chiều tô vẽ.","Xin hãy bật điều hòa trước khi khách đến nhé."]'::jsonb, 1, 'She added frozen peas to the vegetable soup. → Cô ấy đã cho thêm đậu Hà Lan đông lạnh vào món súp rau củ.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
