INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_44_18', 'en-a2-44', NULL, 'comprehensive_test', 'reading', NULL, 'Better street lighting can reduce the risk of accidents involving cyclists and pedestrians at night.', 'Dựa vào câu trên, từ “accident” có nghĩa phù hợp nhất là gì?', '["tai nạn; sự cố","điên rồ; ngớ ngẩn; bất hợp lý; kỳ quặc","người chiến thắng; đội chiến thắng","trừ ra; ngoại trừ"]'::jsonb, 0, 'accident: tai nạn; sự cố; rủi ro bất ngờ. Dịch cả câu: Hệ thống chiếu sáng đường phố tốt hơn có thể làm giảm nguy cơ xảy ra tai nạn liên quan đến người đi xe đạp và người đi bộ vào ban đêm.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_44_19', 'en-a2-44', NULL, 'comprehensive_test', 'reading', NULL, 'Digital communication helps families stay in touch, even when work or study separates them across countries.', 'Dựa vào câu trên, từ “touch” có nghĩa phù hợp nhất là gì?', '["thông minh; sáng suốt","máy phô tô; máy photocopy","dự đoán; trông đợi","chạm; sờ"]'::jsonb, 3, 'touch: chạm; sờ; xúc giác; sự chạm; làm cảm động; làm rung động. Dịch cả câu: Giao tiếp kỹ thuật số giúp các gia đình giữ liên lạc, ngay cả khi công việc hoặc học tập chia cách họ ở các quốc gia khác nhau.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_44_20', 'en-a2-44', NULL, 'comprehensive_test', 'reading', NULL, 'Offering fresh fruit for dessert can help school cafeterias encourage healthier eating habits among children.', 'Dựa vào câu trên, từ “dessert” có nghĩa phù hợp nhất là gì?', '["món tráng miệng","cái nồi; chậu","hòn đảo","chính phủ; cơ quan quản lý nhà nước"]'::jsonb, 0, 'dessert: món tráng miệng. Dịch cả câu: Cung cấp trái cây tươi làm món tráng miệng có thể giúp các căn tin trường học khuyến khích thói quen ăn uống lành mạnh hơn ở trẻ em.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_44_21', 'en-a2-44', NULL, 'comprehensive_test', 'reading', NULL, 'Teaching children to use a spoon independently can help develop their coordination and confidence.', 'Dựa vào câu trên, từ “spoon” có nghĩa phù hợp nhất là gì?', '["trưa; chính ngọ","thìa; muỗng","chạy; môn chạy","góc; góc phố; khúc cua"]'::jsonb, 1, 'spoon: thìa; muỗng; dùng thìa múc. Dịch cả câu: Dạy trẻ tự múc ăn bằng thìa có thể giúp phát triển sự phối hợp vận động và sự tự tin của trẻ.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_44_22', 'en-a2-44', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “sự cắt tóc; kiểu tóc”', '["reply","action","haircut","boss"]'::jsonb, 2, 'sự cắt tóc; kiểu tóc → haircut (/ˈherkʌt/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_44_23', 'en-a2-44', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “quả dứa; quả thơm”', '["cause","day off","wardrobe","pineapple"]'::jsonb, 3, 'quả dứa; quả thơm → pineapple (/ˈpaɪnæpəl/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_44_24', 'en-a2-44', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cái gương”', '["mirror","discussion","loud","truck"]'::jsonb, 0, 'cái gương → mirror (/ˈmɪrɚ/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO lessons (id, language_code, title, hsk_level, unit, description, date_added, sort_order, is_system, owner_id, is_deleted, deleted_at) VALUES ('en-a2-45', 'en', 'Bài 45: Từ vựng Tổng hợp - CEFR A2', 'CEFR A2', 'A2 · Tổng hợp', '13 từ vựng Tiếng Anh CEFR A2 chủ đề tổng hợp đa chủ đề kèm ảnh minh họa, phát âm UK/US, collocations và câu ví dụ song ngữ.', '2026-11-26', 2045, TRUE, NULL, 0, NULL) ON CONFLICT (id) DO UPDATE SET language_code = 'en', title = EXCLUDED.title, hsk_level = EXCLUDED.hsk_level, unit = EXCLUDED.unit, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_system = TRUE, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_army', 'en-a2-45', 'army', '/ˈɑːrmi/', 'A2', 'lục quân; quân đội; đội quân lớn; lực lượng đông đảo', 'n.', NULL, NULL, 'army chủ yếu chỉ lục quân; armed forces dùng chung cho mọi quân chủng.', 'My cousin joined the army after leaving school.', NULL, 'Anh họ tôi đã gia nhập quân đội sau khi tốt nghiệp ra trường.', '{"wordId":"army","ukIpa":"/ˈɑːmi/","usIpa":"/ˈɑːrmi/","cefr":"A2","topic":"government","senses":[{"pos":"n.","en":"A country''s military force trained mainly to fight on land.","vi":"lục quân; quân đội"},{"pos":"n.","en":"A large group of people working toward a shared purpose.","vi":"đội quân lớn; lực lượng đông đảo"}],"examples":[{"en":"My cousin joined the army after leaving school.","vi":"Anh họ tôi đã gia nhập quân đội sau khi tốt nghiệp ra trường.","audioKind":"ex"},{"en":"During major floods, the army can provide essential transport and supplies when civilian services are overwhelmed.","vi":"Trong những trận lũ lụt lớn, quân đội có thể cung cấp các phương tiện vận chuyển và vật tư thiết yếu khi các dịch vụ dân sự bị quá tải.","audioKind":"ex2"}],"collocations":[{"en":"join the army","vi":"gia nhập quân đội"},{"en":"serve in the army","vi":"phục vụ trong quân đội"},{"en":"an army of volunteers","vi":"một lực lượng tình nguyện viên đông đảo"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"army chủ yếu chỉ lục quân; armed forces dùng chung cho mọi quân chủng.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_rule', 'en-a2-45', 'rule', '/ruːl/', 'A2', 'quy định; điều lệ; nguyên tắc; sự thống trị; quyền cai trị; cai trị; cai quản; phán quyết; ra quyết định pháp lý', 'n.', 'ruler (n.), ruling (n.)', 'Đồng nghĩa: regulation, govern', 'as a rule ý chỉ “thông thường”; rule out ý chỉ “loại trừ”.', 'Our main rule is to leave muddy shoes outside.', NULL, 'Quy định chính của chúng tôi là phải để giày dính bùn ở bên ngoài.', '{"wordId":"rule","ukIpa":"/ruːl/","usIpa":"/ruːl/","cefr":"A2","topic":"government","senses":[{"pos":"n.","en":"an instruction stating what is allowed or required","vi":"quy định; điều lệ; nguyên tắc"},{"pos":"n.","en":"control of a country or people by a leader or group","vi":"sự thống trị; quyền cai trị"},{"pos":"v.","en":"to govern a country or make an official legal decision","vi":"cai trị; cai quản; phán quyết; ra quyết định pháp lý"}],"examples":[{"en":"Our main rule is to leave muddy shoes outside.","vi":"Quy định chính của chúng tôi là phải để giày dính bùn ở bên ngoài.","audioKind":"ex"},{"en":"Clear rules on industrial waste disposal are essential for protecting rivers and ensuring safe drinking water.","vi":"Các quy định rõ ràng về xử lý chất thải công nghiệp là cốt lõi để bảo vệ các dòng sông và đảm bảo nguồn nước uống an toàn.","audioKind":"ex2"}],"collocations":[{"en":"follow the rules","vi":"tuân theo quy định"},{"en":"break a rule","vi":"phạm quy; phá vỡ quy tắc"},{"en":"as a rule","vi":"thông thường; như một quy luật"},{"en":"rule out","vi":"loại trừ; bác bỏ"}],"wordFamily":["ruler (n.)","ruling (n.)"],"synonyms":["regulation","govern"],"antonyms":[],"tipVi":"as a rule ý chỉ “thông thường”; rule out ý chỉ “loại trừ”.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_government', 'en-a2-45', 'government', '/ˈɡʌvərnmənt/', 'A2', 'chính phủ; cơ quan quản lý nhà nước; sự cai trị; hệ thống chính quyền', 'n.', 'govern (v.), governmental (adj.), governance (n.), governor (n.)', 'Đồng nghĩa: administration', 'Trong tiếng Anh Anh, khi chỉ tập thể chính phủ, có thể dùng động từ ở số ít hoặc số nhiều.', 'The government plans to build a new hospital nearby.', NULL, 'Chính phủ có kế hoạch xây dựng một bệnh viện mới gần đây.', '{"wordId":"government","ukIpa":"/ˈɡʌvənmənt/","usIpa":"/ˈɡʌvərnmənt/","cefr":"A2","topic":"government","senses":[{"pos":"n.","en":"the group of people officially controlling a country or region","vi":"chính phủ; cơ quan quản lý nhà nước"},{"pos":"n.","en":"the activity or system of controlling a country","vi":"sự cai trị; hệ thống chính quyền"}],"examples":[{"en":"The government plans to build a new hospital nearby.","vi":"Chính phủ có kế hoạch xây dựng một bệnh viện mới gần đây.","audioKind":"ex"},{"en":"Local government plays a crucial role in providing affordable housing and maintaining essential public services.","vi":"Chính phủ địa phương đóng vai trò quan trọng trong việc cung cấp nhà ở giá rẻ và duy trì các dịch vụ công thiết yếu.","audioKind":"ex2"}],"collocations":[{"en":"local government","vi":"chính quyền địa phương"},{"en":"central government","vi":"chính phủ trung ương"},{"en":"government policy","vi":"chính sách của chính phủ"},{"en":"a system of government","vi":"một hệ thống chính trị"}],"wordFamily":["govern (v.)","governmental (adj.)","governance (n.)","governor (n.)"],"synonyms":["administration"],"antonyms":[],"tipVi":"Trong tiếng Anh Anh, khi chỉ tập thể chính phủ, có thể dùng động từ ở số ít hoặc số nhiều.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_president', 'en-a2-45', 'president', '/ˈprezɪdənt/', 'A2', 'tổng thống; chủ tịch; tổng giám đốc; hiệu trưởng trường đại học', 'n.', 'presidential (adj.), presidency (n.), preside (v.)', NULL, 'Có thể chỉ tổng thống hoặc người đứng đầu tổ chức; dịch tùy theo ngữ cảnh.', 'The president waved to the crowd outside the palace.', NULL, 'Vị tổng thống vẫy tay chào đám đông ở bên ngoài cung điện.', '{"wordId":"president","ukIpa":"/ˈprezɪdənt/","usIpa":"/ˈprezɪdənt/","cefr":"A2","topic":"government","senses":[{"pos":"n.","en":"the head of state in a country without a monarch","vi":"tổng thống"},{"pos":"n.","en":"the person leading an organisation, company, club, or university","vi":"chủ tịch; tổng giám đốc; hiệu trưởng trường đại học"}],"examples":[{"en":"The president waved to the crowd outside the palace.","vi":"Vị tổng thống vẫy tay chào đám đông ở bên ngoài cung điện.","audioKind":"ex"},{"en":"The newly elected president promised to improve public healthcare and expand access to affordable education.","vi":"Vị tổng thống mới đắc cử đã cam kết cải thiện y tế công cộng và mở rộng khả năng tiếp cận giáo dục với chi phí phải chăng.","audioKind":"ex2"}],"collocations":[{"en":"elect a president","vi":"bầu tổng thống"},{"en":"presidential election","vi":"cuộc bầu cử tổng thống"},{"en":"university president","vi":"hiệu trưởng trường đại học"},{"en":"vice president","vi":"phó tổng thống; phó chủ tịch"}],"wordFamily":["presidential (adj.)","presidency (n.)","preside (v.)"],"synonyms":[],"antonyms":[],"tipVi":"Có thể chỉ tổng thống hoặc người đứng đầu tổ chức; dịch tùy theo ngữ cảnh.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_queen', 'en-a2-45', 'queen', '/kwiːn/', 'A2', 'nữ vương; vương hậu; ong chúa; kiến chúa; quân hậu (trong cờ vua)', 'n.', 'queenship (n.)', NULL, 'queen có thể chỉ nữ vương trị vì đất nước hoặc vợ của nhà vua.', 'The queen waved to the crowd from her carriage.', NULL, 'Nữ vương vẫy tay chào đám đông từ trên xe ngựa của mình.', '{"wordId":"queen","ukIpa":"/kwiːn/","usIpa":"/kwiːn/","cefr":"A2","topic":"government","senses":[{"pos":"n.","en":"A female monarch, or the wife of a king.","vi":"nữ vương; vương hậu"},{"pos":"n.","en":"The main egg-laying female in a social insect colony.","vi":"ong chúa; kiến chúa"},{"pos":"n.","en":"The chess piece that moves any distance in any direction.","vi":"quân hậu (trong cờ vua)"}],"examples":[{"en":"The queen waved to the crowd from her carriage.","vi":"Nữ vương vẫy tay chào đám đông từ trên xe ngựa của mình.","audioKind":"ex"},{"en":"In some constitutional monarchies, the queen performs ceremonial duties while elected representatives make political decisions.","vi":"Ở một số quốc gia quân chủ lập hiến, nữ vương thực hiện các nghĩa vụ nghi lễ trong khi các đại biểu do dân bầu đưa ra các quyết định chính trị.","audioKind":"ex2"}],"collocations":[{"en":"queen bee","vi":"ong chúa"},{"en":"the reigning queen","vi":"nữ vương đương triều"},{"en":"king and queen","vi":"vua và hoàng hậu"}],"wordFamily":["queenship (n.)"],"synonyms":[],"antonyms":[],"tipVi":"queen có thể chỉ nữ vương trị vì đất nước hoặc vợ của nhà vua.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_king', 'en-a2-45', 'king', '/kɪŋ/', 'A2', 'vua; quốc vương', 'n.', 'kingdom (n.), kingship (n.)', 'Đồng nghĩa: monarch', 'king chỉ nam vương; queen có thể chỉ nữ hoàng hoặc hoàng hậu.', 'The king waved to the crowd from his carriage.', NULL, 'Nhà vua vẫy tay chào đám đông từ trên cỗ xe ngựa của mình.', '{"wordId":"king","ukIpa":"/kɪŋ/","usIpa":"/kɪŋ/","cefr":"A2","topic":"government","senses":[{"pos":"n.","en":"a male ruler who usually inherits his position","vi":"vua; quốc vương"}],"examples":[{"en":"The king waved to the crowd from his carriage.","vi":"Nhà vua vẫy tay chào đám đông từ trên cỗ xe ngựa của mình.","audioKind":"ex"},{"en":"In some countries, the king performs ceremonial duties while elected representatives make political decisions.","vi":"Ở một số quốc gia, nhà vua thực hiện các nhiệm vụ nghi lễ trong khi các đại biểu được bầu cử đưa ra các quyết định chính trị.","audioKind":"ex2"}],"collocations":[{"en":"become king","vi":"lên làm vua"},{"en":"crown a king","vi":"làm lễ đăng quang cho vua"},{"en":"the king''s reign","vi":"triều đại của nhà vua"}],"wordFamily":["kingdom (n.)","kingship (n.)"],"synonyms":["monarch"],"antonyms":[],"tipVi":"king chỉ nam vương; queen có thể chỉ nữ hoàng hoặc hoàng hậu.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_law', 'en-a2-45', 'law', '/lɔː/', 'A2', 'luật; pháp luật; ngành luật; luật học; quy luật; định luật', 'n.', 'lawyer (n.), lawful (adj.), unlawful (adj.), lawless (adj.)', NULL, 'Một điều luật cụ thể là danh từ đếm được; ngành luật dùng law không đếm được.', 'The law requires drivers to stop at red lights.', NULL, 'Luật pháp yêu cầu các tài xế phải dừng lại khi có đèn đỏ.', '{"wordId":"law","ukIpa":"/lɔː/","usIpa":"/lɔː/","cefr":"A2","topic":"government","senses":[{"pos":"n.","en":"an official rule, or the system of such rules","vi":"luật; pháp luật"},{"pos":"n.","en":"the study or profession concerned with legal rules","vi":"ngành luật; luật học"},{"pos":"n.","en":"a general scientific rule describing how something always behaves","vi":"quy luật; định luật"}],"examples":[{"en":"The law requires drivers to stop at red lights.","vi":"Luật pháp yêu cầu các tài xế phải dừng lại khi có đèn đỏ.","audioKind":"ex"},{"en":"Governments should enforce environmental laws consistently to prevent businesses from gaining advantages through harmful practices.","vi":"Các chính phủ nên thực thi luật môi trường một cách nhất quán để ngăn chặn các doanh nghiệp trục lợi từ các hành vi gây hại.","audioKind":"ex2"}],"collocations":[{"en":"break the law","vi":"phạm luật"},{"en":"enforce the law","vi":"thi hành pháp luật"},{"en":"study law","vi":"học luật"},{"en":"the laws of physics","vi":"các định luật vật lý"}],"wordFamily":["lawyer (n.)","lawful (adj.)","unlawful (adj.)","lawless (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Một điều luật cụ thể là danh từ đếm được; ngành luật dùng law không đếm được.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_war', 'en-a2-45', 'war', '/wɔːr/', 'A2', 'chiến tranh, cuộc giao tranh vũ trang giữa các quốc gia hoặc các nhóm; cuộc đấu tranh kiên quyết nhằm đánh bại một điều gì đó có hại', 'n.', 'warfare (n.), wartime (n.)', 'Đồng nghĩa: armed conflict · Trái nghĩa: peace', 'Diễn tả trạng thái đang có chiến tranh thì dùng at war, không thêm mạo từ.', 'The museum displays uniforms worn during the war.', NULL, 'Bảo tàng trưng bày các bộ quân phục được mặc trong thời kỳ chiến tranh.', '{"wordId":"war","ukIpa":"/wɔː/","usIpa":"/wɔːr/","cefr":"A2","topic":"history","senses":[{"pos":"n.","en":"armed fighting between countries or groups","vi":"chiến tranh, cuộc giao tranh vũ trang giữa các quốc gia hoặc các nhóm"},{"pos":"n.","en":"a determined effort to defeat something harmful","vi":"cuộc đấu tranh kiên quyết nhằm đánh bại một điều gì đó có hại"}],"examples":[{"en":"The museum displays uniforms worn during the war.","vi":"Bảo tàng trưng bày các bộ quân phục được mặc trong thời kỳ chiến tranh.","audioKind":"ex"},{"en":"War can disrupt children''s education and force families to leave their homes in search of safety.","vi":"Chiến tranh có thể làm gián đoạn việc học tập của trẻ em và buộc các gia đình phải rời bỏ nhà cửa để tìm kiếm sự an toàn.","audioKind":"ex2"}],"collocations":[{"en":"civil war","vi":"nội chiến"},{"en":"at war","vi":"đang có chiến tranh, đang giao tranh"},{"en":"declare war","vi":"tuyên chiến"},{"en":"war on poverty","vi":"cuộc chiến chống nghèo đói"}],"wordFamily":["warfare (n.)","wartime (n.)"],"synonyms":["armed conflict"],"antonyms":["peace"],"tipVi":"Diễn tả trạng thái đang có chiến tranh thì dùng at war, không thêm mạo từ.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_palace', 'en-a2-45', 'palace', '/ˈpæləs/', 'A2', 'cung điện; dinh thự lớn', 'n.', 'palatial (adj.)', NULL, 'Từ này chủ yếu được dùng làm danh từ; trong cụm palace gardens, từ này đóng vai trò là danh từ bổ nghĩa.', 'We walked through the palace gardens before lunch.', NULL, 'Chúng tôi đi dạo qua những khu vườn của cung điện trước bữa trưa.', '{"wordId":"palace","ukIpa":"/ˈpæləs/","usIpa":"/ˈpæləs/","cefr":"A2","topic":"history","senses":[{"pos":"n.","en":"A grand official home for a royal or important leader.","vi":"cung điện; dinh thự lớn"}],"examples":[{"en":"We walked through the palace gardens before lunch.","vi":"Chúng tôi đi dạo qua những khu vườn của cung điện trước bữa trưa.","audioKind":"ex"},{"en":"Opening a historic palace to visitors can generate income for conservation and support local tourism.","vi":"Việc mở cửa một cung điện lịch sử cho du khách tham quan có thể tạo ra nguồn thu cho công tác bảo tồn và hỗ trợ ngành du lịch địa phương.","audioKind":"ex2"}],"collocations":[{"en":"royal palace","vi":"cung điện hoàng gia"},{"en":"presidential palace","vi":"dinh tổng thống"},{"en":"palace grounds","vi":"khuôn viên cung điện"}],"wordFamily":["palatial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Từ này chủ yếu được dùng làm danh từ; trong cụm palace gardens, từ này đóng vai trò là danh từ bổ nghĩa.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_castle', 'en-a2-45', 'castle', '/ˈkæsəl/', 'A2', 'lâu đài', 'n.', NULL, NULL, 'Âm t trong từ castle là âm câm; palace dùng để chỉ cung điện hoàng gia.', 'We climbed the hill to explore the old castle.', NULL, 'Chúng tôi trèo lên ngọn đồi để khám phá lâu đài cổ.', '{"wordId":"castle","ukIpa":"/ˈkɑːsəl/","usIpa":"/ˈkæsəl/","cefr":"A2","topic":"history","senses":[{"pos":"n.","en":"A large fortified building with thick walls and towers.","vi":"lâu đài"}],"examples":[{"en":"We climbed the hill to explore the old castle.","vi":"Chúng tôi trèo lên ngọn đồi để khám phá lâu đài cổ.","audioKind":"ex"},{"en":"Restoring a historic castle can attract tourists while preserving valuable evidence of a region''s architectural heritage.","vi":"Việc trùng tu một lâu đài lịch sử có thể thu hút khách du lịch đồng thời bảo tồn được những bằng chứng quý giá về di sản kiến trúc của một vùng.","audioKind":"ex2"}],"collocations":[{"en":"medieval castle","vi":"lâu đài thời trung cổ"},{"en":"castle walls","vi":"tường thành lâu đài"},{"en":"ruined castle","vi":"lâu đài hoang phế"}],"wordFamily":[],"synonyms":[],"antonyms":[],"tipVi":"Âm t trong từ castle là âm câm; palace dùng để chỉ cung điện hoàng gia.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":true}}'::jsonb, 10, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_century', 'en-a2-45', 'century', '/ˈsentʃəri/', 'A2', 'thế kỷ; một trăm năm', 'n.', 'centennial (adj.)', NULL, 'Số thứ tự của thế kỷ thường lớn hơn hai chữ số đầu của năm một đơn vị: ví dụ từ năm 1901 đến 2000 thuộc thế kỷ 20.', 'This bridge was built more than a century ago.', NULL, 'Cây cầu này được xây dựng từ hơn một thế kỷ trước.', '{"wordId":"century","ukIpa":"/ˈsentʃəri/","usIpa":"/ˈsentʃəri/","cefr":"A2","topic":"history","senses":[{"pos":"n.","en":"A period of one hundred years.","vi":"thế kỷ; một trăm năm"}],"examples":[{"en":"This bridge was built more than a century ago.","vi":"Cây cầu này được xây dựng từ hơn một thế kỷ trước.","audioKind":"ex"},{"en":"Over the past century, improvements in sanitation have contributed significantly to longer life expectancy worldwide.","vi":"Trong thế kỷ qua, những cải thiện về điều kiện vệ sinh đã đóng góp đáng kể vào việc kéo dài tuổi thọ trung bình trên toàn thế giới.","audioKind":"ex2"}],"collocations":[{"en":"the twentieth century","vi":"thế kỷ hai mươi"},{"en":"over a century ago","vi":"hơn một thế kỷ trước"},{"en":"the turn of the century","vi":"thời kỳ giao giữa hai thế kỷ"}],"wordFamily":["centennial (adj.)"],"synonyms":[],"antonyms":[],"tipVi":"Số thứ tự của thế kỷ thường lớn hơn hai chữ số đầu của năm một đơn vị: ví dụ từ năm 1901 đến 2000 thuộc thế kỷ 20.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 11, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_egyptian', 'en-a2-45', 'Egyptian', '/iˈdʒɪpʃən/', 'A2', 'thuộc về Ai Cập; của người Ai Cập; người Ai Cập', 'adj.', 'Egypt (n.)', NULL, 'Chữ cái đầu phải viết hoa; khi chỉ nhiều người Ai Cập dùng Egyptians.', 'We admired Egyptian pottery at the museum yesterday.', NULL, 'Chúng tôi đã chiêm ngưỡng đồ gốm Ai Cập tại bảo tàng ngày hôm qua.', '{"wordId":"egyptian","ukIpa":"/iˈdʒɪpʃən/","usIpa":"/iˈdʒɪpʃən/","cefr":"A2","topic":"history","senses":[{"pos":"adj.","en":"relating to Egypt, its people, or its culture","vi":"thuộc về Ai Cập; của người Ai Cập"},{"pos":"n.","en":"a person from Egypt","vi":"người Ai Cập"}],"examples":[{"en":"We admired Egyptian pottery at the museum yesterday.","vi":"Chúng tôi đã chiêm ngưỡng đồ gốm Ai Cập tại bảo tàng ngày hôm qua.","audioKind":"ex"},{"en":"Ancient Egyptian irrigation systems demonstrate how communities adapted farming practices to seasonal changes in river levels.","vi":"Hệ thống thủy lợi Ai Cập cổ đại cho thấy cộng đồng xưa đã điều chỉnh phương thức canh tác như thế nào để thích ứng với biến động theo mùa của mực nước sông.","audioKind":"ex2"}],"collocations":[{"en":"ancient Egyptian civilisation","vi":"văn minh Ai Cập cổ đại"},{"en":"Egyptian art","vi":"nghệ thuật Ai Cập"},{"en":"Egyptian cotton","vi":"bông Ai Cập"}],"wordFamily":["Egypt (n.)"],"synonyms":[],"antonyms":[],"tipVi":"Chữ cái đầu phải viết hoa; khi chỉ nhiều người Ai Cập dùng Egyptians.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 12, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO vocabularies (id, lesson_id, hanzi, pinyin, sino_vietnamese, meaning, word_type, radical, breakdown, mnemonic, example_hanzi, example_pinyin, example_meaning, meta, sort_order, is_deleted, deleted_at) VALUES ('ven_ancient', 'en-a2-45', 'ancient', '/ˈeɪnʃənt/', 'A2', 'cổ đại; thuộc thời cổ đại; cổ xưa; lâu đời', 'adj.', NULL, 'Đồng nghĩa: age-old · Trái nghĩa: modern', 'ancient nhấn mạnh khoảng thời gian cách đây rất lâu, không nên dùng thay cho tính từ old thông thường.', 'We explored an ancient temple during our holiday.', NULL, 'Chúng tôi đã khám phá một ngôi đền cổ trong chuyến nghỉ dưỡng của mình.', '{"wordId":"ancient","ukIpa":"/ˈeɪnʃənt/","usIpa":"/ˈeɪnʃənt/","cefr":"A2","topic":"history","senses":[{"pos":"adj.","en":"belonging to a period thousands of years in the past","vi":"cổ đại; thuộc thời cổ đại"},{"pos":"adj.","en":"having existed for a very long time","vi":"cổ xưa; lâu đời"}],"examples":[{"en":"We explored an ancient temple during our holiday.","vi":"Chúng tôi đã khám phá một ngôi đền cổ trong chuyến nghỉ dưỡng của mình.","audioKind":"ex"},{"en":"Studying ancient civilisations helps researchers understand how early societies managed water, trade, and public health.","vi":"Việc nghiên cứu các nền văn minh cổ đại giúp các nhà nghiên cứu hiểu được cách các xã hội thời kỳ đầu quản lý nguồn nước, thương mại và y tế công cộng.","audioKind":"ex2"}],"collocations":[{"en":"ancient history","vi":"lịch sử cổ đại"},{"en":"ancient civilisation","vi":"nền văn minh cổ đại"},{"en":"ancient ruins","vi":"tàn tích cổ đại"},{"en":"ancient monument","vi":"di tích lịch sử cổ đại"}],"wordFamily":[],"synonyms":["age-old"],"antonyms":["modern"],"tipVi":"ancient nhấn mạnh khoảng thời gian cách đây rất lâu, không nên dùng thay cho tính từ old thông thường.","noteVi":"","media":{"img":true,"uk":true,"us":true,"ex":true,"ex2":false}}'::jsonb, 13, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, hanzi = EXCLUDED.hanzi, pinyin = EXCLUDED.pinyin, sino_vietnamese = EXCLUDED.sino_vietnamese, meaning = EXCLUDED.meaning, word_type = EXCLUDED.word_type, radical = EXCLUDED.radical, breakdown = EXCLUDED.breakdown, mnemonic = EXCLUDED.mnemonic, example_hanzi = EXCLUDED.example_hanzi, example_pinyin = EXCLUDED.example_pinyin, example_meaning = EXCLUDED.example_meaning, meta = EXCLUDED.meta, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_45_1', 'en-a2-45', 'Cách dùng “century” (n.) — thế kỷ; một trăm năm', 'the twentieth century  ·  over a century ago  ·  the turn of the century', 'Số thứ tự của thế kỷ thường lớn hơn hai chữ số đầu của năm một đơn vị: ví dụ từ năm 1901 đến 2000 thuộc thế kỷ 20.', 'Họ từ (Word Family): centennial (adj.)', '[{"hanzi":"This bridge was built more than a century ago.","pinyin":"","meaning":"Cây cầu này được xây dựng từ hơn một thế kỷ trước."},{"hanzi":"Over the past century, improvements in sanitation have contributed significantly to longer life expectancy worldwide.","pinyin":"","meaning":"Trong thế kỷ qua, những cải thiện về điều kiện vệ sinh đã đóng góp đáng kể vào việc kéo dài tuổi thọ trung bình trên toàn thế giới."}]'::jsonb, 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_45_2', 'en-a2-45', 'Cách dùng “palace” (n.) — cung điện; dinh thự lớn', 'royal palace  ·  presidential palace  ·  palace grounds', 'Từ này chủ yếu được dùng làm danh từ; trong cụm palace gardens, từ này đóng vai trò là danh từ bổ nghĩa.', 'Họ từ (Word Family): palatial (adj.)', '[{"hanzi":"We walked through the palace gardens before lunch.","pinyin":"","meaning":"Chúng tôi đi dạo qua những khu vườn của cung điện trước bữa trưa."},{"hanzi":"Opening a historic palace to visitors can generate income for conservation and support local tourism.","pinyin":"","meaning":"Việc mở cửa một cung điện lịch sử cho du khách tham quan có thể tạo ra nguồn thu cho công tác bảo tồn và hỗ trợ ngành du lịch địa phương."}]'::jsonb, 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_45_3', 'en-a2-45', 'Cách dùng “ancient” (adj.) — cổ đại; thuộc thời cổ đại', 'ancient history  ·  ancient civilisation  ·  ancient ruins', 'ancient nhấn mạnh khoảng thời gian cách đây rất lâu, không nên dùng thay cho tính từ old thông thường.', 'Đồng nghĩa: age-old · Trái nghĩa: modern', '[{"hanzi":"We explored an ancient temple during our holiday.","pinyin":"","meaning":"Chúng tôi đã khám phá một ngôi đền cổ trong chuyến nghỉ dưỡng của mình."},{"hanzi":"Studying ancient civilisations helps researchers understand how early societies managed water, trade, and public health.","pinyin":"","meaning":"Việc nghiên cứu các nền văn minh cổ đại giúp các nhà nghiên cứu hiểu được cách các xã hội thời kỳ đầu quản lý nguồn nước, thương mại và y tế công cộng."}]'::jsonb, 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO grammars (id, lesson_id, title, formula, explanation, notes, examples, sort_order, is_deleted, deleted_at) VALUES ('gen_a2_45_4', 'en-a2-45', 'Cách dùng “government” (n.) — chính phủ; cơ quan quản lý nhà nước', 'local government  ·  central government  ·  government policy', 'Trong tiếng Anh Anh, khi chỉ tập thể chính phủ, có thể dùng động từ ở số ít hoặc số nhiều.', 'Họ từ (Word Family): govern (v.), governmental (adj.), governance (n.), governor (n.) | Đồng nghĩa: administration', '[{"hanzi":"The government plans to build a new hospital nearby.","pinyin":"","meaning":"Chính phủ có kế hoạch xây dựng một bệnh viện mới gần đây."},{"hanzi":"Local government plays a crucial role in providing affordable housing and maintaining essential public services.","pinyin":"","meaning":"Chính phủ địa phương đóng vai trò quan trọng trong việc cung cấp nhà ở giá rẻ và duy trì các dịch vụ công thiết yếu."}]'::jsonb, 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, formula = EXCLUDED.formula, explanation = EXCLUDED.explanation, notes = EXCLUDED.notes, examples = EXCLUDED.examples, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_45_1', 'en-a2-45', 'Bài đọc 1: Câu giao tiếp hằng ngày', 'Luyện nghe và đọc các câu giao tiếp ngắn sử dụng từ vựng trọng tâm trong bài.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_45_1_1', 'ten_a2_45_1', 'army', 'My cousin joined the army after leaving school.', 'My cousin joined the army after leaving school.', '/ˈɑːrmi/', 'Anh họ tôi đã gia nhập quân đội sau khi tốt nghiệp ra trường.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_45_1_2', 'ten_a2_45_1', 'rule', 'Our main rule is to leave muddy shoes outside.', 'Our main rule is to leave muddy shoes outside.', '/ruːl/', 'Quy định chính của chúng tôi là phải để giày dính bùn ở bên ngoài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_45_1_3', 'ten_a2_45_1', 'government', 'The government plans to build a new hospital nearby.', 'The government plans to build a new hospital nearby.', '/ˈɡʌvərnmənt/', 'Chính phủ có kế hoạch xây dựng một bệnh viện mới gần đây.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_45_1_4', 'ten_a2_45_1', 'president', 'The president waved to the crowd outside the palace.', 'The president waved to the crowd outside the palace.', '/ˈprezɪdənt/', 'Vị tổng thống vẫy tay chào đám đông ở bên ngoài cung điện.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_45_1_5', 'ten_a2_45_1', 'queen', 'The queen waved to the crowd from her carriage.', 'The queen waved to the crowd from her carriage.', '/kwiːn/', 'Nữ vương vẫy tay chào đám đông từ trên xe ngựa của mình.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_45_1_6', 'ten_a2_45_1', 'king', 'The king waved to the crowd from his carriage.', 'The king waved to the crowd from his carriage.', '/kɪŋ/', 'Nhà vua vẫy tay chào đám đông từ trên cỗ xe ngựa của mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_45_1_7', 'ten_a2_45_1', 'law', 'The law requires drivers to stop at red lights.', 'The law requires drivers to stop at red lights.', '/lɔː/', 'Luật pháp yêu cầu các tài xế phải dừng lại khi có đèn đỏ.', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_45_1_8', 'ten_a2_45_1', 'war', 'The museum displays uniforms worn during the war.', 'The museum displays uniforms worn during the war.', '/wɔːr/', 'Bảo tàng trưng bày các bộ quân phục được mặc trong thời kỳ chiến tranh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_45_1_1', 'en-a2-45', 'ten_a2_45_1', 'listening', 'listening', 'My cousin joined the army after leaving school.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Luật pháp yêu cầu các tài xế phải dừng lại khi có đèn đỏ.","Bảo tàng trưng bày các bộ quân phục được mặc trong thời kỳ chiến tranh.","Nữ vương vẫy tay chào đám đông từ trên xe ngựa của mình.","Anh họ tôi đã gia nhập quân đội sau khi tốt nghiệp ra trường."]'::jsonb, 3, 'My cousin joined the army after leaving school. → Anh họ tôi đã gia nhập quân đội sau khi tốt nghiệp ra trường.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_45_1_2', 'en-a2-45', 'ten_a2_45_1', 'listening', 'listening', 'Our main rule is to leave muddy shoes outside.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Bảo tàng trưng bày các bộ quân phục được mặc trong thời kỳ chiến tranh.","Quy định chính của chúng tôi là phải để giày dính bùn ở bên ngoài.","Chúng tôi đã chiêm ngưỡng đồ gốm Ai Cập tại bảo tàng ngày hôm qua.","Chúng tôi trèo lên ngọn đồi để khám phá lâu đài cổ."]'::jsonb, 1, 'Our main rule is to leave muddy shoes outside. → Quy định chính của chúng tôi là phải để giày dính bùn ở bên ngoài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_45_1_3', 'en-a2-45', 'ten_a2_45_1', 'listening', 'listening', 'The government plans to build a new hospital nearby.', NULL, 'Nghe câu tiếng Anh và chọn bản dịch tiếng Việt đúng nhất:', '["Chúng tôi đi dạo qua những khu vườn của cung điện trước bữa trưa.","Chính phủ có kế hoạch xây dựng một bệnh viện mới gần đây.","Chúng tôi đã khám phá một ngôi đền cổ trong chuyến nghỉ dưỡng của mình.","Nữ vương vẫy tay chào đám đông từ trên xe ngựa của mình."]'::jsonb, 1, 'The government plans to build a new hospital nearby. → Chính phủ có kế hoạch xây dựng một bệnh viện mới gần đây.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO texts (id, lesson_id, title, description, sort_order, is_deleted, deleted_at) VALUES ('ten_a2_45_2', 'en-a2-45', 'Bài đọc 2: Ngữ cảnh học thuật (IELTS)', 'Làm quen với cách dùng từ vựng A2 trong các câu văn phong học thuật chuẩn IELTS.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, title = EXCLUDED.title, description = EXCLUDED.description, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_45_2_1', 'ten_a2_45_2', 'army', 'During major floods, the army can provide essential transport and supplies when civilian services are overwhelmed.', 'During major floods, the army can provide essential transport and supplies when civilian services are overwhelmed.', '/ˈɑːrmi/', 'Trong những trận lũ lụt lớn, quân đội có thể cung cấp các phương tiện vận chuyển và vật tư thiết yếu khi các dịch vụ dân sự bị quá tải.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_45_2_2', 'ten_a2_45_2', 'rule', 'Clear rules on industrial waste disposal are essential for protecting rivers and ensuring safe drinking water.', 'Clear rules on industrial waste disposal are essential for protecting rivers and ensuring safe drinking water.', '/ruːl/', 'Các quy định rõ ràng về xử lý chất thải công nghiệp là cốt lõi để bảo vệ các dòng sông và đảm bảo nguồn nước uống an toàn.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_45_2_3', 'ten_a2_45_2', 'government', 'Local government plays a crucial role in providing affordable housing and maintaining essential public services.', 'Local government plays a crucial role in providing affordable housing and maintaining essential public services.', '/ˈɡʌvərnmənt/', 'Chính phủ địa phương đóng vai trò quan trọng trong việc cung cấp nhà ở giá rẻ và duy trì các dịch vụ công thiết yếu.', 3, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_45_2_4', 'ten_a2_45_2', 'president', 'The newly elected president promised to improve public healthcare and expand access to affordable education.', 'The newly elected president promised to improve public healthcare and expand access to affordable education.', '/ˈprezɪdənt/', 'Vị tổng thống mới đắc cử đã cam kết cải thiện y tế công cộng và mở rộng khả năng tiếp cận giáo dục với chi phí phải chăng.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_45_2_5', 'ten_a2_45_2', 'queen', 'In some constitutional monarchies, the queen performs ceremonial duties while elected representatives make political decisions.', 'In some constitutional monarchies, the queen performs ceremonial duties while elected representatives make political decisions.', '/kwiːn/', 'Ở một số quốc gia quân chủ lập hiến, nữ vương thực hiện các nghĩa vụ nghi lễ trong khi các đại biểu do dân bầu đưa ra các quyết định chính trị.', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO text_sentences (id, text_id, speaker, hanzi, display_hanzi, pinyin, meaning, sort_order, is_deleted, deleted_at) VALUES ('tsen_a2_45_2_6', 'ten_a2_45_2', 'king', 'In some countries, the king performs ceremonial duties while elected representatives make political decisions.', 'In some countries, the king performs ceremonial duties while elected representatives make political decisions.', '/kɪŋ/', 'Ở một số quốc gia, nhà vua thực hiện các nhiệm vụ nghi lễ trong khi các đại biểu được bầu cử đưa ra các quyết định chính trị.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET text_id = EXCLUDED.text_id, speaker = EXCLUDED.speaker, hanzi = EXCLUDED.hanzi, display_hanzi = EXCLUDED.display_hanzi, pinyin = EXCLUDED.pinyin, meaning = EXCLUDED.meaning, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_45_2_1', 'en-a2-45', 'ten_a2_45_2', 'listening', 'listening', 'During major floods, the army can provide essential transport and supplies when civilian services are overwhelmed.', NULL, 'Trong câu vừa nghe, từ “army” mang nghĩa nào sau đây?', '["bồn tắm","lục quân; quân đội","trả lời; hồi âm","dự án; công trình; đề tài nghiên cứu"]'::jsonb, 1, '“army” (/ˈɑːrmi/): lục quân; quân đội. Câu đầy đủ: During major floods, the army can provide essential transport and supplies when civilian services are overwhelmed.', 1, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('lqen_a2_45_2_2', 'en-a2-45', 'ten_a2_45_2', 'listening', 'listening', 'Clear rules on industrial waste disposal are essential for protecting rivers and ensuring safe drinking water.', NULL, 'Trong câu vừa nghe, từ “rule” mang nghĩa nào sau đây?', '["quy định; điều lệ; nguyên tắc","luật; pháp luật","tâm trí; đầu óc; trí tuệ","hài kịch; phim hài"]'::jsonb, 0, '“rule” (/ruːl/): quy định; điều lệ; nguyên tắc. Câu đầy đủ: Clear rules on industrial waste disposal are essential for protecting rivers and ensuring safe drinking water.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, text_id = EXCLUDED.text_id, audio_text = EXCLUDED.audio_text, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
