INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_45_2', 'en-a2-45', NULL, 'comprehensive_test', 'listening', 'Our main rule is to leave muddy shoes outside.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Bảo tàng trưng bày các bộ quân phục được mặc trong thời kỳ chiến tranh.","Quy định chính của chúng tôi là phải để giày dính bùn ở bên ngoài.","Nhà vua vẫy tay chào đám đông từ trên cỗ xe ngựa của mình.","Chúng tôi đã khám phá một ngôi đền cổ trong chuyến nghỉ dưỡng của mình."]'::jsonb, 1, 'Our main rule is to leave muddy shoes outside. → Quy định chính của chúng tôi là phải để giày dính bùn ở bên ngoài.', 2, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
