INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_45_4', 'en-a2-45', NULL, 'comprehensive_test', 'listening', 'The president waved to the crowd outside the palace.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Chính phủ có kế hoạch xây dựng một bệnh viện mới gần đây.","Chúng tôi trèo lên ngọn đồi để khám phá lâu đài cổ.","Vị tổng thống vẫy tay chào đám đông ở bên ngoài cung điện.","Chúng tôi đã khám phá một ngôi đền cổ trong chuyến nghỉ dưỡng của mình."]'::jsonb, 2, 'The president waved to the crowd outside the palace. → Vị tổng thống vẫy tay chào đám đông ở bên ngoài cung điện.', 4, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_45_5', 'en-a2-45', NULL, 'comprehensive_test', 'listening', 'queen', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["nữ vương; vương hậu","vùng quê; miền quê","cuối cùng; sau cùng (sau một thời gian dài chờ đợi hoặc nỗ lực)","buổi trưa; chính ngọ"]'::jsonb, 0, 'queen (/kwiːn/) → nữ vương; vương hậu; ong chúa; kiến chúa; quân hậu (trong cờ vua)', 5, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_45_6', 'en-a2-45', NULL, 'comprehensive_test', 'listening', 'The king waved to the crowd from his carriage.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhà vua vẫy tay chào đám đông từ trên cỗ xe ngựa của mình.","Anh họ tôi đã gia nhập quân đội sau khi tốt nghiệp ra trường.","Nữ vương vẫy tay chào đám đông từ trên xe ngựa của mình.","Cây cầu này được xây dựng từ hơn một thế kỷ trước."]'::jsonb, 0, 'The king waved to the crowd from his carriage. → Nhà vua vẫy tay chào đám đông từ trên cỗ xe ngựa của mình.', 6, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_45_7', 'en-a2-45', NULL, 'comprehensive_test', 'listening', 'law', NULL, 'Nghe phát âm tiếng Anh và chọn nghĩa tiếng Việt đúng:', '["vội vã; thúc giục","máy ghi âm; thiết bị ghi hình","luật; pháp luật","nhà khoa học"]'::jsonb, 2, 'law (/lɔː/) → luật; pháp luật; ngành luật; luật học; quy luật; định luật', 7, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_45_8', 'en-a2-45', NULL, 'comprehensive_test', 'listening', 'The museum displays uniforms worn during the war.', NULL, 'Nghe câu tiếng Anh sau và chọn bản dịch tiếng Việt đúng:', '["Nhà vua vẫy tay chào đám đông từ trên cỗ xe ngựa của mình.","Bảo tàng trưng bày các bộ quân phục được mặc trong thời kỳ chiến tranh.","Quy định chính của chúng tôi là phải để giày dính bùn ở bên ngoài.","Chúng tôi trèo lên ngọn đồi để khám phá lâu đài cổ."]'::jsonb, 1, 'The museum displays uniforms worn during the war. → Bảo tàng trưng bày các bộ quân phục được mặc trong thời kỳ chiến tranh.', 8, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_45_9', 'en-a2-45', NULL, 'comprehensive_test', 'vocab', NULL, NULL, 'Từ nào có nghĩa là: “A female monarch, or the wife of a king.”?', '["ancient","queen","president","century"]'::jsonb, 1, 'queen (/kwiːn/) → nữ vương; vương hậu', 9, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
