INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_45_18', 'en-a2-45', NULL, 'comprehensive_test', 'reading', NULL, 'During major floods, the army can provide essential transport and supplies when civilian services are overwhelmed.', 'Dựa vào câu trên, từ “army” có nghĩa phù hợp nhất là gì?', '["lời chúc mừng; sự chúc mừng","hành động; cư xử; đóng vai","lục quân; quân đội","cộng sự; đối tác; người cùng chơi"]'::jsonb, 2, 'army: lục quân; quân đội; đội quân lớn; lực lượng đông đảo. Dịch cả câu: Trong những trận lũ lụt lớn, quân đội có thể cung cấp các phương tiện vận chuyển và vật tư thiết yếu khi các dịch vụ dân sự bị quá tải.', 18, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_45_19', 'en-a2-45', NULL, 'comprehensive_test', 'reading', NULL, 'Clear rules on industrial waste disposal are essential for protecting rivers and ensuring safe drinking water.', 'Dựa vào câu trên, từ “rule” có nghĩa phù hợp nhất là gì?', '["phía tây bắc; vùng tây bắc","sắp xếp; chuẩn bị; bố trí","thêm; phụ","quy định; điều lệ; nguyên tắc"]'::jsonb, 3, 'rule: quy định; điều lệ; nguyên tắc; sự thống trị; quyền cai trị; cai trị; cai quản; phán quyết; ra quyết định pháp lý. Dịch cả câu: Các quy định rõ ràng về xử lý chất thải công nghiệp là cốt lõi để bảo vệ các dòng sông và đảm bảo nguồn nước uống an toàn.', 19, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_45_20', 'en-a2-45', NULL, 'comprehensive_test', 'reading', NULL, 'Local government plays a crucial role in providing affordable housing and maintaining essential public services.', 'Dựa vào câu trên, từ “government” có nghĩa phù hợp nhất là gì?', '["buổi phỏng vấn; cuộc phỏng vấn","máy tính bảng","chính phủ; cơ quan quản lý nhà nước","chất dẻo; nhựa"]'::jsonb, 2, 'government: chính phủ; cơ quan quản lý nhà nước; sự cai trị; hệ thống chính quyền. Dịch cả câu: Chính phủ địa phương đóng vai trò quan trọng trong việc cung cấp nhà ở giá rẻ và duy trì các dịch vụ công thiết yếu.', 20, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_45_21', 'en-a2-45', NULL, 'comprehensive_test', 'reading', NULL, 'The newly elected president promised to improve public healthcare and expand access to affordable education.', 'Dựa vào câu trên, từ “president” có nghĩa phù hợp nhất là gì?', '["bông (thực vật)","tổng thống","thợ làm tóc; thợ cắt tóc","tưởng tượng; hình dung"]'::jsonb, 1, 'president: tổng thống; chủ tịch; tổng giám đốc; hiệu trưởng trường đại học. Dịch cả câu: Vị tổng thống mới đắc cử đã cam kết cải thiện y tế công cộng và mở rộng khả năng tiếp cận giáo dục với chi phí phải chăng.', 21, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_45_22', 'en-a2-45', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thế kỷ; một trăm năm”', '["quarter","offer","closed","century"]'::jsonb, 3, 'thế kỷ; một trăm năm → century (/ˈsentʃəri/)', 22, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_45_23', 'en-a2-45', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “thuộc về Ai Cập; của người Ai Cập”', '["rose","Egyptian","energy","luggage"]'::jsonb, 1, 'thuộc về Ai Cập; của người Ai Cập → Egyptian (/iˈdʒɪpʃən/)', 23, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
INSERT INTO quiz_questions (id, lesson_id, text_id, scope, category, audio_text, passage, question, options, correct_index, explanation, sort_order, is_deleted, deleted_at) VALUES ('cten_a2_45_24', 'en-a2-45', NULL, 'comprehensive_test', 'translate_vi_zh', NULL, NULL, 'Chọn từ tiếng Anh đúng cho nghĩa: “cổ đại; thuộc thời cổ đại”', '["jewelry","ancient","tourism","bin"]'::jsonb, 1, 'cổ đại; thuộc thời cổ đại → ancient (/ˈeɪnʃənt/)', 24, 0, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, category = EXCLUDED.category, audio_text = EXCLUDED.audio_text, passage = EXCLUDED.passage, question = EXCLUDED.question, options = EXCLUDED.options, correct_index = EXCLUDED.correct_index, explanation = EXCLUDED.explanation, sort_order = EXCLUDED.sort_order, is_deleted = 0, deleted_at = NULL;
